MultiLanguageQuestData['en'] = {}
MultiLanguageQuestData['en'][1] = {title = "Alexander's Quest", objective = "Find the forgotten location and cast the magical spell.", description = "Welcome to the world of Alexander craft. Please try to not break the windows.  \n\nSeek out the fallen crest in the land of icy wastes. There incant the spell of a forgotten age, wallowing in the teeming mists of life. \n <<Do Not Localize>>You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nShabby Arakkoa Disguise\n\nThe following spell will be cast on you:\n\nChicken Other\n\nYou will also receive:\n\n17 Pound Catfish"}
MultiLanguageQuestData['en'][2] = {title = "Sharptalon's Claw", objective = "Bring Sharptalon's Claw to Senani Thunderheart at Splintertree Post, Ashenvale.", description = "The mighty hippogryph Sharptalon has been slain, with the claw of the felled beast serving as a testament to your victory.  Senani Thunderheart at the Splintertree Post will no doubt be interested in seeing this trophy as proof of your deeds.", progress = "Yes, mighty <class>, I sensed your arrival.  I trust you have more news to report to me about your hunt?", completion = "Most impressive, &lt;name&gt;... the claw of Sharptalon could not have been easy to get!  The Ashenvale Hunt goes well for you!\n\nSharptalon had long terrorized the peons from the lumber camps near its path as they tried to travel here to Splintertree Post.  No doubt once the word gets out that it was you who put down the beast, many rousing songs of your bravery will be heard at campfires and lumber mills across Ashenvale!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5] = {title = "Jitters' Growling Gut", objective = "Speak with Chef Grual.", description = "I've been stuck hiding in this ghost town for weeks, and I haven't eaten anything but grubs and weeds!  I need some decent food, and I'm willing to trade well for it.\n\nBring me a feast and I'll pay you handsomely.\n\nI heard Chef Grual at the Scarlet Raven Tavern in Darkshire makes very good Dusky Crab Cakes...", progress = nil, completion = "You need some Crab Cakes, do you?  Well I might be able to cook some up for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6] = {title = "Bounty on Garrick Padfoot", objective = "Kill Garrick Padfoot and bring his head to Deputy Willem at Northshire Abbey.", description = "Garrick Padfoot - a cutthroat who's plagued our farmers and merchants for weeks - was seen at a shack near the vineyards, which lies east of the Abbey and across the bridge.  Bring me the villain's head, and earn his bounty!\n\nBut be wary, <name>.  Garrick has gathered a gang of thugs around him.  He will not be an easy man to reach.", progress = "Did you find Garrick's shack?  Are we finally free of that villain?", completion = "Hah - you caught him!  You've done Elwynn a great service, and earned a nice bounty!", rewards = "You will be able to choose one of these rewards:\n\nTapered PantsLayered TunicEnsign Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7] = {title = "Kobold Camp Cleanup", objective = "Kill 10 Kobold Vermin, then return to Marshal McBride.", description = "Your first task is one of cleansing, <name>.  A clan of kobolds have infested the woods to the north.  Go there and fight the kobold vermin you find.  Reduce their numbers so that we may one day drive them from Northshire.", progress = "How goes the hunting, <name>?  Have you found and defeated those vermin?", completion = "Well done, citizen.  Those kobolds are thieves and cowards, but in large numbers they pose a threat to us.  And the humans of Stormwind do not need another threat.\n\nFor defeating them, you have my gratitude.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8] = {title = "A Rogue's Deal", objective = "Deliver the Nondescript Letter to Innkeeper Renee in Tirisfal Glades.", description = "Hey, mate! Do a favor for a young man who's been fighting more than his fair share of mindless zombies and spiders?\n\nI got this here letter that needs to go to Brill... to an innkeeper named Renee something-or-other. Don't really matter none what her last name is.\n\nAnyway, it's a nice cozy little place full of victims of the plague trying to make their way in the world. And it be a great spot for you to rest too if the need arises. You should check it out... you do and I'll pay you well.", progress = "Yes? Yes? What is it?\n\nThe forsaken; they certainly do have huge appetites. Make yourself at home... yes, rest those weary bones. My name's Renee if you need anything at all.", completion = "Oh? A letter? Wonderful news! I've been waiting on word from my dear old mother in Deathknell. Such a saint, she is. I wonder how she's holding up.\n\nWhat? Too cheery? Not buying it, are you?\n\nWell, get lost then... it's really no business who the letter's from anyway. Go on! Get lost!\n\nCome back when you've got some coin to spend... loafer.\n\nNext thing you know, you'll be coming back to rest after a long days adventure or some stupid thing like that.", rewards = "You will be able to choose one of these rewards:\n\nForest Mushroom CapRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][9] = {title = "The Killing Fields", objective = "Farmer Saldean wants you to kill 20 Harvest Watchers.", description = "Look at what has happened to this place!  These lands were once occupied by good farm folk.  But the damned thieves have driven them all off.  Not me, though!  But it seems some Harvest Watchers have taken over the fields.\n\nIf you're up for the work, I'd like you to go out and kill twenty of them.  Come back when you're done for your pay.  If you finish up with the ones in my field, clear them from the neighboring fields as well.", progress = "Ah, I see you're back!  I hope you've been hard at work clearing those fields of those Harvest Watchers.  Have you killed twenty yet?", completion = "Good work, friend.  You have earned your pay well.  Who knows, perhaps Westfall will prosper once again.", rewards = "You will be able to choose one of these rewards:\n\nHarvester's PantsHarvester's Robe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10] = {title = "The Scrimshank Redemption", objective = "Discover the fate of Junior Surveyor Scrimshank, and bring either him or his surveying equipment to Senior Surveyor Fizzledowser in Gadgetzan.", description = "Oh, this is just terrible!  I sent out my top assistant, Junior Surveyor Scrimshank, into the desert southeast of here.  That's an area we call the Gaping Chasm.  Well, he's gone missing, and his last report had more of those weird bugs where he was.  Could it be that they've infested two major regions of the desert now?\n\nI need you to head into the Gaping Chasm and look for Scrimshank, please!  That... or at least find his surveying equipment.  I fear that may be all that is left of the poor sod.", progress = "Well, what news do you have?  You look like you've been in quite the fight... is Scrimshank alive?", completion = "He was a good goblin, young Scrimshank.  Let's hope that his demise was not in vain by what he was able to record with his surveying equipment.\n\nIt seems as though we have quite the situation on our hands here with these bugs.  They're way too cunning for their own good, and the research we've done so far is shaping up to indicate that they might even be under the controlling influence of a third party!  If this is the case, then it bodes ill for not only Gadgetzan, but the whole desert!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11] = {title = "Riverpaw Gnoll Bounty", objective = "Bring 8 Painted Gnoll Armbands to Deputy Rainer at the Barracks.", description = "Gnolls, brutish creatures with no decent business in these lands, have been seen along the borders of Elwynn Forest.  A large pack of them, many more than we can handle alone, have infested the woods south of the guard tower yonder.  Another group has infested the areas near Stone Cairn Lake to the east.\n\nThe Stormwind Army will commend whomever helps kill them.  Bring me their painted gnoll armbands as proof of your deed.", progress = "Hail, <name>.  Have you been killing Gnolls...?", completion = "I see you've been busy!  You have our thanks, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nMilitia BucklerUrchin's Pants\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][12] = {title = "The People's Militia", objective = "Gryan Stoutmantle wants you to kill 15 Defias Trappers and 15 Defias Smugglers then return to him on Sentinel Hill.", description = "The People's Militia has but one goal:  To defend the lands of Westfall and return peace to our surroundings.  Unfortunately, the price of peace is often blood. \n\nOne of my scouts has brought word of a band of Defias Trappers wreaking havoc nearby.  I have reports of Defias Trapper sightings near the Jangolode Mine to the Northwest as well as at the Molsen Farm and Furlbrow's Pumpkin Farm. If you seek to join our ranks, slay 15 Defias Trappers and 15 Defias Smugglers then return to me.", progress = "Perhaps I did not make myself clear, pledge.  In order to prove your worth as a servant to The People's Militia and to the Light you need to slay 15 Defias Trappers and 15 Defias Smugglers then return to me when the deed is done.", completion = "Well done, &lt;name&gt;.  My scout witnessed your valiant acts.  You are proving yourself quite well so far.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][13] = {title = "The People's Militia", objective = "Gryan Stoutmantle wants you to kill 15 Defias Pillagers and 15 Defias Looters and return to him on Sentinel Hill.", description = "A band of vicious Defias Pillagers has been seen plundering the Gold Coast Quarry, Moonbrook and the Alexston Farmstead.  The People's Militia will not stand for such behavior.  Dispatch immediately, <name>, and make the Light's presence known in Westfall.\n\nThe Gold Coast Quarry is near the shore, to the West of the tower.  As the next step of your training, I want you to kill 15 of those foul Defias Pillagers and 15 Defias Looters.", progress = "We have not time to talk, <name>.  The Defias Pillagers are denying the people of Westfall the peace and prosperity they deserve.  Make sure at least 15 Defias Pillagers and 15 Defias Looters have been killed.  That will send a clear message that corruption is not welcome here.", completion = "Your worth to The People's Militia has been validated by your brave acts thus far.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][14] = {title = "The People's Militia", objective = "Gryan Stoutmantle wants you to kill 15 Defias Highwaymen, 5 Defias Pathstalkers and 5 Defias Knuckledusters then return to him on Sentinel Hill.", description = "Some Defias have eluded us.  My most trusted scout reports that these Defias have been looting and pillaging the countryside, all the way into Southern Westfall.  We believe they are hiding out in the Dagger Hills, plotting their next move.   Slay the wretches in the name of The People's Militia.", progress = "<name>, now is no time for idle chatter.  If you still wish to prove yourself to The People's Militia you need to slay the Defias I notified you about earlier.  Return to me when you have completed your duty.", completion = "When I left the tainted lands of Lordaeron I returned to a grim state of affairs here in my homeland.  But there is hope for Westfall yet.  As proven by your valor in battle, it is obvious to me that you serve our cause with honor.  It is with great pride that I induct thee into The People's Militia.  May the Light shine upon you.", rewards = "You will be able to choose one of these rewards:\n\nEdge of the People's MilitiaFist of the People's MilitiaSpark of the People's Militia\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][15] = {title = "Investigate Echo Ridge", objective = "Kill 10 Kobold Workers, then report back to Marshal McBride.", description = "<name>, my scouts tell me that the kobold infestation is larger than we had thought.  A group of kobold workers has camped near the Echo Ridge Mine to the north.\n\nGo to the mine and remove them.  We know there are at least 10.  Kill them, see if there are more, then report back to me.", progress = "Have you been to the mines?  Are you ready to report?", completion = "I don't like hearing of all these kobolds in our mine.  No good can come of this.  Here, take this as payment, and when you're ready, speak to me again.  I would like you to go back to the mines one more time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][16] = {title = "Give Gerard a Drink", objective = "Farming is thirsty work, and I'm always looking for refreshing spring water.\n\nIf you have any, then I'm willing to make a trade.", description = nil, progress = "Farming is thirsty work, and I'm always looking for refreshing spring water.\n\nIf you have any, then I'm willing to make a trade.", completion = "Thanks, &lt;name&gt;!  And come back if you want to trade again.", rewards = "You will receive:\n\nShiny Red Apple"}
MultiLanguageQuestData['en'][17] = {title = "Uldaman Reagent Run", objective = "Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar.", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done &lt;name&gt;, you've proven your worth once again!  The caps will be an interesting study, yon verily!\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!", rewards = "You will receive:\n\nRestorative Potion"}
MultiLanguageQuestData['en'][18] = {title = "Brotherhood of Thieves", objective = "Bring 12 Red Burlap Bandanas to Deputy Willem outside the Northshire Abbey.", description = "Recently, a new group of thieves has been hanging around Northshire.  They call themselves the Defias Brotherhood, and have been seen across the river to the east.\n\nI don't know what they're up to, but I'm sure it's not good!  Bring me the bandanas they wear, and I'll reward you with a weapon.", progress = "Have you gathered those bandanas for me yet?", completion = "Back with some bandanas, I see.  The Stormwind Army appreciates your help.", rewards = "You will be able to choose one of these rewards:\n\nMilitia DaggerMilitia HammerMilitia ShortswordMilitia WarhammerMilitia Quarterstaff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][19] = {title = "Tharil'zun", objective = "Bring Tharil'zun's Head to Marshal Marris in Redridge.", description = "Blackrock Outrunners and Renegades are running ambushes between here and Stonewatch Keep.  The leader of the Outrunners is an orc named Tharil'zun--we want this orc.  Bring me the head of Tharil'zun!", progress = "Orc pressure from Blackrock is still tense.  But have you at least rid us of Tharil'zun?", completion = "Tharil'zun was a vicious, crafty orc.  Well done--I'm sure he didn't go down easy.  Here is your reward, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nFire Hardened BucklerOrc Crusher\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][20] = {title = "Blackrock Menace", objective = "Bring 10 Battleworn Axes to Marshal Marris in Lakeshire.", description = "The Blackrock orcs have travelled from the Burning Steppes and claimed Stonewatch Keep to the north.  From there they maraud the areas north of Lakeshire and keep its citizens in town, penned like cattle.\n\nHelp rid Lakeshire of this menace.  Kill these Blackrock orcs and bring me ten of their Battleworn Axes as proof.\n\nAnd although Blackrocks threaten us from the north, we've received reports of more in the southeastern pocket of Redridge.  If you find any there, then they too should be hunted.", progress = "Have you been slaying orcs, <name>?  If so, then show me...", completion = "That makes for a lot fewer orcs to worry about, thanks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][21] = {title = "Skirmish at Echo Ridge", objective = "Kill 12 Kobold Laborers, then return to Marshal McBride at Northshire Abbey.", description = "Your previous investigations are proof that the Echo Ridge Mine needs purging.  Return to the mine and help clear it of kobolds.\n\nWaste no time, <name>.  The longer the kobolds are left unmolested in the mine, the deeper a foothold they gain in Northshire.", progress = "I know it's bloody work, <name>, but it's vital to the safety of Northshire.  Are you ready to report?", completion = "Once again, you have earned my respect, and the gratitude of the Stormwind Army.  There may yet be kobolds in the mine, but I will marshal others against them.  We have further tasks for you.", rewards = "You will be able to choose one of these rewards:\n\nOutfitter BeltOutfitter BootsOutfitter Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][22] = {title = "Goretusk Liver Pie", objective = "Salma Saldean needs 8 Goretusk livers to make a Goretusk Liver Pie.", description = "The onions are peeled.  The garlic is minced.  The rosemary is crushed.  The crust has been baked.  The dill weed is chopped.  The gravy is simmering.  Now all I need for my famous meat pie are 8 Goretusk Livers!", progress = "All I need for my famous meat pie are 8 Goretusk Livers!", completion = "These are just perfect, &lt;name&gt;!  Thank you so much.  Farmer Saldean and I are going to feast tonight.  And here is a little something for you, for the hard work.  You didn't think I was going to let a &lt;class&gt; like you go hungry, did you?", rewards = "You will receive:\n\nGoretusk Liver PieRecipe: Goretusk Liver Pie"}
MultiLanguageQuestData['en'][23] = {title = "Ursangous's Paw", objective = "Bring Ursangous's Paw to Senani Thunderheart at Splintertree Post, Ashenvale.", description = "The paw of the mighty bear Ursangous is your trophy for this part of the Ashenvale Hunt.  On the paw is a small quarter-crescent emblem; the significance of the emblem remains a mystery.\n\nThe paw should be brought to Senani Thunderheart in Splintertree Post to prove that you have bested the mighty creature and completed this portion of the hunt.", progress = "Ah - <name> - I was just thinking about you!  How goes your hunting?", completion = "Ah, the paw of Ursangous!  Your skill is impressive, &lt;class&gt;; he is credited with numerous kills.  The crescent on his paw is no doubt a sign that he was trained by the night elves that skulk about Ashenvale.  Ursangous is... was one of the mightiest bears you'd find in these parts.  To have bested such a creature is a testament to your will and resolve.\n\nYour ancestors would be proud!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][24] = {title = "Shadumbra's Head", objective = "Bring Shadumbra's Head to Senani Thunderheart at Splintertree Post, Ashenvale.", description = "The once swift Shadumbra now lies still as you claim victory over it.  The head of the slain nightsaber is a fitting trophy for this fight of the Ashenvale Hunt.  Senani Thunderheart at Splintertree Post will want to see such a trophy to award you credit for this part of the Ashenvale Hunt.", progress = "Greetings once again, <name>!  Have you come to show me proof of your hunt?", completion = "A victory for &lt;name&gt; in the Ashenvale Hunt!  Well done - the head of Shadumbra is a fitting trophy to claim for such an impressive fight, no doubt.\n\nShadumbra's savagery was well known throughout the post here.  Any trip to the west, especially on foot trying to get out to the Zoram Strand, was wrought with danger because of this tiger.  Thanks to you, this danger has abated.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][25] = {title = "Stonetalon Standstill", objective = "Dispatch 12 Befouled Water Elementals at Mystral Lake, due east of the Talondeep Path and southwest of Splintertree Post.\n\nScout the gazebo on Mystral Lake that overlooks the nearby Alliance outpost.\n\nReturn to Mastok Wrilehiss at Splintertree Post, Ashenvale.", description = "If you want to be useful, then why don't you do something about the situation near Talondeep Path?\n\nThe transports between Ashenvale and Stonetalon are at a standstill because of the lake coming alive and attacking anything that gets close... which means anyone on the path.  What'd be even more useful than just putting the hammer down on the water elementals there is someone scouting the gazebo on Mystral Lake - the one that has a solid view of the Alliance outpost there.\n\nYou up for being useful?", progress = "You back already?  What's the situation out there - all cleared up now, thanks to you?", completion = "Yeah, I heard that someone tore up the lake out there like a dust devil through the Barrens.  From the sound of it too, we might be able to set up a possible observation area out there to keep an eye on our Alliance friends.  Well, that is if we can keep it on the down low...\n\nLooks like you ended up being quite useful after all; the transports between here and Stonetalon should have an easier time of it.  Take this - you've earned it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][26] = {title = "A Lesson to Learn", objective = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", description = "<name>, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", progress = nil, completion = "Salutations, young &lt;class&gt;; the time has come for you to know our aquatic form.  It is one that lets you move freely and indefinitely through water.  You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome.  The first will test your ability to work in water under pressure.  The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][27] = {title = "A Lesson to Learn", objective = "Speak with Dendrite Starblaze in the village of Nighthaven, Moonglade.", description = "<name>, I have been following your progress with much delight.  You are most assuredly developing yourself into a valued protector of nature.\n\nThe time has come for you to learn more about one of the various animal aspects that Cenarius has blessed us with the ability to change into - one that affords you command and mastery of the water.  For this, you must travel to the village of Nighthaven in Moonglade and speak with Dendrite Starblaze of the Cenarion Circle there.  He will guide you further.", progress = nil, completion = "Salutations, young &lt;class&gt;; the time has come for you to know our aquatic form.  It is one that lets you move freely and indefinitely through water.  You will find this aspect a useful tool and a blessing... but it is one that must be earned before it is mastered.\n\nYou will face two trials to overcome.  The first will test your ability to work in water under pressure.  The second will test your resolve to understand the aspects of the form itself.\n\nStand ready, as the time of testing is now upon us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][28] = {title = "Trial of the Lake", objective = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, <name>.", progress = "To complete the Trial of the Lake, you must use the Shrine Bauble within the boundaries of this shrine.  Until you do so, your trial remains unfinished and it is at risk of failure.", completion = "Well now, it looks like yet another &lt;class&gt; has successfully completed the Trial of the Lake!  Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri.  It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine.  Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such.  By using the bauble here, it serves as a nod to the importance of this place within the Circle.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][29] = {title = "Trial of the Lake", objective = "Find a Shrine Bauble in Lake Elune'ara, and take it to the Shrine of Remulos in northwestern Moonglade. Once there, use the Shrine Bauble.\n\nYou must speak with Tajarri at the shrine afterwards in order to complete the trial.", description = "For your first trial, search the depths of Lake Elune'ara to locate a Shrine Bauble.  It decays rapidly, so proceed with it to the Shrine of Remulos post haste.  Use the bauble at the shrine, and then speak with Tajarri there; she is one of Moonglade's most trusted wardens.\n\nYou only have a set amount of time to complete the task, and you may be competing against other druids searching for baubles themselves.  Mental and physical dexterity will be critical to your success.\n\nGood luck, <name>.", progress = "To complete the Trial of the Lake, you must use the Shrine Bauble within the boundaries of this shrine.  Until you do so, your trial remains unfinished and it is at risk of failure.", completion = "Well now, it looks like yet another &lt;class&gt; has successfully completed the Trial of the Lake!  Well done, my young friend - well done.\n\nAs I've said, my name is Tajarri.  It is my duty and my privilege to serve as a warden for Moonglade, and specifically this shrine.  Keeper Remulos guides the Cenarion Circle in preservation of nature and balance, and his shrine serves as a lasting tribute to such.  By using the bauble here, it serves as a nod to the importance of this place within the Circle.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][30] = {title = "Trial of the Sea Lion", objective = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", progress = "Have you formed your pendant for me to inspect, <name>?  If you need help in locating the parts, try asking the local populace for information.  Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, &lt;name&gt; - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][31] = {title = "Aquatic Form", objective = "Return to Thunder Bluff and show Turak Runetotem the Pendant of the Sea Lion.", description = "You have completed the necessary lessons all young druids are taught before they can adopt an aquatic aspect.  Go now back to your trainer, Turak Runetotem, in Thunder Bluff.  Show him your pendant and prove to him you are ready to learn what he has to teach you.  He will complete your training, allowing you to become one with the water.\n\nGoodbye, young druid.  We shall speak again.", progress = "Your return to Thunder Bluff is not without heralding, though I will need proof of your lessons learned in Moonglade before I will teach you your aquatic form.\n\nDo you have the Pendant of the Sea Lion?", completion = "Very impressive, &lt;name&gt;.  Your ancestors would be pleased with your progress!  You're ready to learn your aquatic form, and it is my pleasure to teach it to you.\n\nAlso, in recognition of your achievement during the two trials, I give you this item.  I hope you'll find it to be a welcome addition to your gear as a protector of nature and a keeper of the balance.", rewards = "The following spell will be cast on you:\n\nAquatic Form\n\nYou will receive:\n\nAquarius Belt"}
MultiLanguageQuestData['en'][32] = {title = "Rise of the Silithid", objective = "Take the report to Zilzibin Drumlore in Orgrimmar.", description = "Here's your report.  I urge you to take it to someone who might have working knowledge in this kind of thing.\n\nI know this troll scholar named Zilzibin Drumlore.  He's spent a lot of time studying life forms that are unique to the ecology of Azeroth; he's a historian to boot!  If you want someone to help figure out what exactly this threat is and how to stop it, give this report to him.  We're going to need all the help we can get.\n\nZil lives in a house on the second tier of the Drag in Orgrimmar.", progress = "I'm sorry, I don't know you... but from the look of things you have at least heard something of me.  Now, what can I help you with?  Do you have something for me?", completion = "This report... I've dealt with these beasts before.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, &lt;name&gt;: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][33] = {title = "Wolves Across the Border", objective = "Bring 8 pieces of Tough Wolf Meat to Eagan Peltskinner outside Northshire Abbey.", description = "I hate those nasty timber wolves!  But I sure like eating wolf steaks...  Bring me tough wolf meat and I will exchange it for something you'll find useful.\n\ntough wolf meat is gathered from hunting the timber wolves and young wolves wandering the Northshire countryside.", progress = "Hey <name>.  I'm getting hungry...did you get that tough wolf meat?", completion = "You've been busy!  I can't wait to cook up that wolf meat...\n\nI have some things here you might want - take your pick!", rewards = "You will be able to choose one of these rewards:\n\nSoft Fur-lined ShoesWolfskin Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][34] = {title = "An Unwelcome Guest", objective = "Martie Jainrose of Lakeshire wants you to kill Bellygrub. Bring her his tusk as proof.", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", progress = "Is Bellygrub still at it or were you able to rid Lakeshire of the pest once and for all?", completion = "Finally the menace is laid to rest!  Thank you, &lt;name&gt;, you have done me a great service.  The garden shall be in full bloom this season!", rewards = "You will receive:\n\nBouquet of Scarlet Begonias"}
MultiLanguageQuestData['en'][35] = {title = "Further Concerns", objective = "Marshal Dughan wants you to speak with Guard Thomas.", description = "If you are concerned that the rumors of murlocs are true, then do this -- travel to the eastern Elwynn bridge and speak with Guard Thomas.  He has been stationed at the bridge for the past week and will know the state of the area.\n\nBring me his report.", progress = nil, completion = "Yes, murlocs have settled in and around the streams of eastern Elwynn.  We don't know why they are here, but they are aggressive and at least semi-intelligent.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][36] = {title = "Westfall Stew", objective = "Verna Furlbrow wants you to deliver her recipe for Westfall Stew to Salma Saldean.", description = "I never thought the day would come when I'd leave the farm.  But the fields are overrun with thieves and it's far too dangerous for us here now.  As soon as Farmer Furlbrow gets the wagon fixed, we'll be on our way.  \n\nMaybe you could do me a favor?  Let me scribble down my recipe for Westfall stew.  Please take it to Salma Saldean over on the farm yonder.  The Saldean's farm is just beyond the fork in the road.", progress = "I'm going to miss that Verna Furlbrow so much.  I don't suppose you happened to see her on your way here?", completion = "That Verna was always such a sweet lass.  We'll miss her here in Westfall but between you and me, she's a city girl at heart and Stormwind will suit her just fine.  But enough gossip!  Now we can make Westfall Stew!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][37] = {title = "Find the Lost Guards", objective = "Guard Thomas wants you to travel north up the river and search for the two lost guards, Rolf and Malakai.", description = "A few days ago we sent two Guards, Rolf and Malakai, to investigate along the river, and they have not yet returned.  To complete my report, I must know what happened to those men.\n\nTravel north along the river and find the guards... or their remains.", progress = nil, completion = "Although much has been stripped from the corpse, strewn nearby is a medallion with the words: \"Footman Malakai Stone\" etched upon it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][38] = {title = "Westfall Stew", objective = "Salma Saldean wants 3 Stringy Vulture Meat, 3 Goretusk Snouts, 3 Murloc Eyes, 3 Okra.", description = "Help me make some Westfall Stew!  Come back with the following ingredients: \n\n 3 Stringy Vulture Meat\n 3 Goretusk Snouts\n 3 Murloc Eyes\n 3 Okra", progress = "Come back with the following ingredients: \n\n 3 Stringy Vulture Meat\n 3 Goretusk Snouts\n 3 Murloc Eyes\n 3 Okra", completion = "That Okra will thicken up this broth nicely!  Now we just add the Stringy Vulture Meat, a few Murloc Eyes and those delicious Goretusk Snouts.  And we're done!  For all your help, &lt;name&gt;, I want you to take today's first batch of Westfall Stew!", rewards = "You will receive:\n\nWestfall StewRecipe: Westfall StewSalma's Oven MittsSharp Kitchen Knife"}
MultiLanguageQuestData['en'][39] = {title = "Deliver Thomas' Report", objective = "Report to Marshal Dughan in Goldshire.", description = "Tell Marshal Dughan of Malakai and Rolf's deaths, and report to him that the Murlocs in eastern Elwynn cannot be contained by our current troop presence.\n\nI know we don't have many troops to spare, but hopefully Dughan can find someone.", progress = nil, completion = "Hmm, this news is troubling.  Already our defenses are stretched thin, and losing Rolf and Malakai to those murlocs put us in an even worse position.\n\nIf things don't improve, there will be fighting in Goldshire by the week's end!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][40] = {title = "A Fishy Peril", objective = "Remy \"Two Times\" wants you to speak with Marshal Dughan in Goldshire.", description = "<name>, there's a new threat in Elwynn Forest!  Murlocs are swimming up the streams of eastern Elwynn, scaring away fish and attacking gentle folk!\n\nI warned Marshal Dughan, but he's more worried about the gnolls and the bandits.  He's not convinced that the murlocs are a danger.\n\nPlease, <name>, speak to Dughan and persuade him to send more troops to the east!", progress = nil, completion = "Yes, I spoke with Remy.  I respect him as a merchant, though all reports of Murlocs to the east have been sketchy at best.\n\nYour concerns are noted, but unless I receive a military report of a murloc threat, we can't afford to send more troops east.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][45] = {title = "Discover Rolf's Fate", objective = "Search the murloc village for Rolf, or signs of his death.", description = "Upon further searching the area, you find webbed footprints leading east along the shore of Stone Cairn Lake.  In the distance to the east, you can just barely see a Murloc village.\n\nPerhaps Rolf's fate ended there...", progress = nil, completion = "You find around the neck of the corpse a metal medallion inscribed with the words \"Footman Rolf Hartford.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][46] = {title = "Bounty on Murlocs", objective = "Bring 8 Torn Murloc Fins to Guard Thomas at the east Elwynn bridge.", description = "The Stormwind Army has placed a bounty on murloc lurkers and foragers in Elwynn.  Slaughter them and bring me their torn murloc fins, and the Stormwind Army will reward you well.\n\nThe murlocs have built a village at Stone Cairn Lake north of here, and another to the south where the stream forks.", progress = "How goes the hunting, <name>?", completion = "You have the fins?  Great!  Marshal Dughan is anxious about the Murloc situation in eastern Elwynn, and I'd like to tell him that it's becoming under control.\n\nYour actions have helped realize that.", rewards = "You will be able to choose one of these rewards:\n\nLong BayonetSolid Metal ClubWell-used Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][47] = {title = "Gold Dust Exchange", objective = "Bring 10 Gold Dust to Remy \"Two Times\" in Goldshire. Gold Dust is gathered from Kobolds in Elwynn Forest.", description = "The Kobolds in these parts sometimes carry Gold Dust on them.  I could really use the stuff - bring me a load of it and I'll give you the best price in town...best price in town!\n\nYou can find kobolds in the Fargodeep Mine to the south, and around the Jasperlode Mine to the northeast.", progress = "Psst!  You have that Gold Dust for me...for me?", completion = "Thanks for the dust, &lt;name&gt;.  Here's your cash, and...here is a token from associates of mine.  You might find it useful...useful.", rewards = "You will receive:\n\nBag of Marbles"}
MultiLanguageQuestData['en'][48] = {title = "Sweet Amber", objective = "Bring Holy Spring Water to Grimbooze Thunderbrew.", description = "In the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", progress = "Hiccup! Ho ho!  You want an encore?\n\nIn the land to the south where vines twist and creep\nLies a hidden well where the water runs deep\nPure as the Light's sacred Daughter\nBring to me now some Holy Spring Water.", completion = "Hiccup! Ho Ho!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][49] = {title = "Sweet Amber", objective = "Grimbooze Thunderbrew wants a Sack of Barley, a Sack of Rye and a Sack of Corn.", description = "Amber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", progress = "Encore? Well, sure!\n\nAmber is the hue of my life's longest love\nLike the last embers of dusk in the sky above\nRetrieve for me so that my love shall be born\nOne sack of each: barley, rye and corn.", completion = "Hiccup! Ho ho!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][50] = {title = "Sweet Amber", objective = "Grimbooze Thunderbrew wants Truesilver.", description = "I'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", progress = "An encore for you?  Well sure friend!\n\nI'll mix and mix till we have a mash\nFor this will be our own private stash\nA still must be fashioned of metal strong\nBring me some Truesilver so I can finish this song.", completion = "Hiccup! Ho ho!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][51] = {title = "Sweet Amber", objective = "Bring a Sycamore Branch to Grimbooze Thunderbrew.", description = "Not yet filtered but freshly distilled\nLike unseeded land waiting there tilled.\nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", progress = "An encore?  Why for you, anything!\n\nNot yet filtered but freshly distilled\nLike unseeded land waiting there tilled. \nNext I will fashion our pile of charcoal\nDeliver a sycamore branch, that is your next goal.", completion = "Hiccup! Ho ho!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][52] = {title = "Protect the Frontier", objective = "Kill 8 Prowlers and 5 Young Forest Bears, and then return to Guard Thomas at the east Elwynn bridge.", description = "Hail, <name>.  Wild animals are growing more and more aggressive the farther we get from Goldshire, and the Eastvale Logging Camp suffers nearly constant attacks from wolves and bears!\n\nWe could use your help out here.", progress = "Have you killed those wolves and bears?", completion = "Thanks a lot for the help, &lt;name&gt;.  Something in the forest must be making these animals so bold.\n\nWhatever it is, I hope it stays there.", rewards = "You will receive:\n\nLesser Healing Potion"}
MultiLanguageQuestData['en'][53] = {title = "Sweet Amber", objective = "Bring Grimbooze Thunderbrew a bundle of Charred Oak.", description = "Mellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", progress = "Sure, I'll sing it again for you, friend!\n\nMellifluous liquid clear as a baby's tears\nTurns a lovely deep amber over the years\nBut before we proceed to get lit to the hilt\nA barrel of charred oak must be built.", completion = "Aged in the barrel, filtered through coal\nIt passes your lips and right through your soul.\nSo lets us drink now, a toast to you\nAnd me while we're at it, Grimbooze Thunderbrew!", rewards = "You will receive:\n\nThunderbrew's Boot Flask"}
MultiLanguageQuestData['en'][54] = {title = "Report to Goldshire", objective = "Take Marshal McBride's Documents to Marshal Dughan in Goldshire.", description = "<name>, you are a <class> with proven interest in the security of Northshire.  You are now tasked with the protection of the surrounding Elwynn Forest.\n\nIf you accept this duty, then I have prepared papers that must be delivered to Marshal Dughan in Goldshire.  Goldshire lies along the southern road, past the border gates.", progress = "You have word from McBride?  Northshire is a garden compared to Elwynn Forest, but I wonder what Marshal McBride has to report.\n\nHere, let me have his papers...", completion = "Well, it says here that you've been awarded Acting Deputy Status with the Stormwind Marshals.  Congratulations.\n\nAnd good luck - keeping Elwynn safe is no picnic... what with most the army busy doing who knows what for who knows which noble!\n\nIt's hard to keep track of politics in these dark days...", rewards = "You will receive:\n\nPikeman Shield"}
MultiLanguageQuestData['en'][55] = {title = "Morbent Fel", objective = "Use Morbent's Bane on Morbent Fel, kill Morbent Fel, then return Morbent's Bane to Sven at his camp.", description = "Morbent Fel hides in his lair, the house perched atop the hill to the east overlooking the Raven Hill cemetery.  His time in this land is drawing to an end...\n\nUse Morbent's Bane against him.  It will render his protective magics powerless.\n\nSlay him.  Slay him, and save us from his wickedness.  Be the instrument of my revenge, and a hero of Duskwood!", progress = "Is Morbent Fel defeated?!", completion = "Morbent Fel has been defeated.  The dark riders are still at large, but a small piece of that which I had hoped beyond hope has come to pass.\n\nYou have done the impossible, and your deeds will forever live in the legends of Duskwood.\n\nGo, &lt;name&gt;.  And perhaps, one day, fate may bring you back to me...", rewards = "You will be able to choose one of these rewards:\n\nNight Watch PantaloonsWatch Master's CloakSparkmetal Coif\n\nYou will also receive:\n\nTorch of Holy Flame"}
MultiLanguageQuestData['en'][56] = {title = "The Night Watch", objective = "Commander Althea Ebonlocke of Darkshire wants you to kill 8 Skeletal Warriors and 6 Skeletal Mages.", description = "As Commander of The Night Watch it is my sworn duty to protect the citizens of Darkshire.  Stormwind has retracted their commissioned guards from their posts here, leaving us to our own devices.\n\nIf you feel worthy of the task, we need your help! Assist The Night Watch by venturing forth into Tranquil Gardens, just south of Darkshire, and slaying 8 Skeletal Warriors and 6 Skeletal Mages.  The undead threat must be thwarted!", progress = "I see you are back, <name>.  If you wish to prove yourself to be of service to The Night Watch, return to me once you have slain 8 Skeletal Warriors and 6 Skeletal Mages.", completion = "Splendid, &lt;name&gt;.  For your service to the people of Darkshire you shall be rewarded.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][57] = {title = "The Night Watch", objective = "Commander Althea Ebonlocke of Darkshire wants you to kill 15 Skeletal Fiends and 15 Skeletal Horrors.", description = "<name>, I'm getting reports of an undead infestation in the forest!  If you're up to the job, journey to the Raven Hill graveyard and slay 15 of those vile Skeletal Fiends and 15 Skeletal Horrors.  There are also reports of skeletons just south of Darkshire, in and around Tranquil Gardens Cemetery.  The undead must be driven from Duskwood!", progress = nil, completion = "The people of Darkshire thank you, &lt;name&gt;.  You have proven yourself to be a great ally of The Night Watch.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][58] = {title = "The Night Watch", objective = "Commander Althea Ebonlocke of Darkshire wants you to kill 20 Plague Spreaders in the eastern Raven Hill mausoleum.", description = "The situation in Raven Hill is still grim.  The safety of Darkshire is in your hands, <name>.  I don't have enough Watchers to keep the town safe.  We need you to dispatch for Raven Hill yet again and rid the eastern mausoleum of 20 Plague Spreaders!", progress = "I need your assistance, <name>.  Travel to the cemetery to the northwest and rid the eastern mausoleum of 20 Plague Spreaders.\n\nReturn to me when your task is complete.", completion = "On behalf of the people of Darkshire and as the Leader of the Night Watch, I thank you, &lt;name&gt;, for your bravery and dedication.  May the Light shine upon your ways.", rewards = "You will be able to choose one of these rewards:\n\nBandolier of the Night WatchQuiver of the Night WatchGunnysack of the Night Watch\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][59] = {title = "Cloth and Leather Armor", objective = "Give Sara Timberlain the Stormwind Armor Marker.", description = "For your shrewdness and valor, I have a marker here that is good for one piece of armor.  I want you to take it to Sara Timberlain at the Eastvale Logging Camp.  Give her the marker, and she will fashion the armor for you.  And after you receive it, <name>, use it in the defense of Elwynn.\n\nThe Eastvale Logging Camp is beyond Guard Thomas' post to the east.", progress = "I have been commissioned by the Stormwind Army to supply their people with cloth and leather armor.\n\nIf you have a marker for me, then I'd be happy to make you something.", completion = "Ah, thank you for the marker.  Please feel free to pick your choice of armor.\n\nLuck to you, brave &lt;class&gt;.  And may this armor serve you well.", rewards = "You will be able to choose one of these rewards:\n\nWell-stitched RobePatched Pants\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][60] = {title = "Kobold Candles", objective = "Bring 8 Large Candles to William Pestle in Goldshire.", description = "Hello, <good sir/my lady>!  Do you have a moment?\n\nMy brother and I run an apothecary in Stormwind, and I'm here to gather large candles for their wax.  Can you help me?\n\nYou can get large candles from kobolds, and I hear rumors that kobolds are infesting the Elwynn mines ... the Fargodeep mine to the south and Jasperlode Mine to the east.  I suggest looking for candles in one of those places.", progress = "Did you gather those candles yet?", completion = "You were busy hunting kobolds, were you?  Thanks for the candles, &lt;name&gt;, and here's your reward...", rewards = "You will receive:\n\nGlowing Wax Stick"}
MultiLanguageQuestData['en'][61] = {title = "Shipment to Stormwind", objective = "Bring William's Shipment to Morgan Pestle in the Stormwind Trade District.", description = "My brother Morgan is waiting in Stormwind for my shipment of candles.  I don't have enough time to make the trip myself, but if you'd like to take him the shipment, he'll pay you well.\n\nI've packed up the candles, and you can find Morgan in our shop, Pestle's Apothecary, in the Stormwind Trade District.", progress = "Oh, a shipment from my brother?  Splendid!  Fortune truly shines on me today!", completion = "Here is your payment ... and while you're here, take a look around!  I'm sure we have a potion or other trinket you'd find useful.", rewards = "You will be able to choose one of these rewards:\n\nExplosive RocketOil of OlafElixir of Lion's Strength\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][62] = {title = "The Fargodeep Mine", objective = "Explore the Fargodeep Mine, then return to Marshal Dughan in Goldshire.", description = "The mine in Northshire isn't the only one with problems!  I have reports that the Fargodeep Mine in Elwynn has also become a haven for Kobolds.\n\nExplore the mine and confirm these reports, then return to me.  The mine is almost due south of Goldshire, between the Stonefield and Maclure homesteads.", progress = "What do you have to report, <name>?  Have you been to the Fargodeep Mine?", completion = "This is bad news.  What's next, dragons?!?  We'll have to increase our patrols near that mine.  Thanks for your efforts, &lt;name&gt;.  And hold a moment... I might have another task for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][63] = {title = "Call of Water", objective = "Defeat the Corrupt Manifestation of Water and place the Corrupted Manifestation's Bracers along with the Remaining Drops of Purest Water on the Brazier of Everfount in Silverpine Forest.", description = "Along the coast of Silverpine, west of the Sepulcher, you will find a shrine that has become tainted by the plague. The spirits there no longer speak to our people and it will be up to you to defeat the manifestation and cleanse the pool.\n\nTake the elemental's bracers, along with the remaining drops of Brine's potion, and place them on the brazier. The ritual should be enough to summon a pure spirit for you to communicate with.\n\nBring me proof the task is done, and I will reward you with your totem.", progress = "The brazier still reflects the ambient light from the area, and the flame shifts slightly as you move closer.\n\nThe corruption along the hills seems to have kept its distance, and besides the missing components, the brazier looks prepared for the ritual to summon a cleansed manifestation of water.", completion = "You place the bracers atop the brazier and then pour the remaining drops of Brine's potion into the flame. The drops crackle as they hit the flame and you begin to incant the simple words Islen taught you....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64] = {title = "The Forgotten Heirloom", objective = "Farmer Furlbrow wants you to retrieve his pocket watch from the wardrobe in his farmhouse at the pumpkin farm to the West.", description = "It was horrible!  Verna woke me when she heard a ruckus in the fields.  The fields were full of hooligans.  We left in a rush and I forgot to pack my pocket watch.  Verna's pa gave me that watch on our wedding day and I feel just sick knowing those thieves have it.  I left the pocket watch in the wardrobe at the farmhouse.  Look for the field of pumpkins to the West -- you can't miss it.  If you bring it back to me, I'd sure be grateful!", progress = "Don't suppose you were able to get my watch?", completion = "My watch!  Thank you so much, kind sir! \n\nWe are but poor farmers and we have lost our land but please accept this reward as a token of our appreciation.", rewards = "You will receive:\n\nFreshly Baked BreadIce Cold Milk"}
MultiLanguageQuestData['en'][65] = {title = "The Defias Brotherhood", objective = "Gryan Stoutmantle wants you to talk to Wiley in Lakeshire.", description = "The band of wretches responsible for driving the good people of Westfall from the land call themselves The Defias Brotherhood.  I need you to infiltrate this clan of thugs.  We need to know who heads up the cartel and where they are hiding out.  In Lakeshire, in the inn, there is a rogue by the name of Wiley who owes me a favor.\n\nTravel to Lakeshire in the Redridge Mountains, east of Elwynn, and find out what you can.", progress = nil, completion = "So, Stoutmantle sent you?  Well, I owe him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][66] = {title = "The Legend of Stalvan", objective = "Seek out the Clerk Daltry in the Darkshire Town Hall.", description = "Last night a horrible disturbance rippled through my veins.  I sensed that my granddaughter, Alyssa, was in great danger.  I consulted the cards and Death stared up at me from the table.\n\nAfter taking a long journey through a dark trance I was able to uncover a clue to this terrifying mystery.  A name came to me, the name of Stalvan.\n\nSeek out the Clerk in the Town Hall and see if you can find out more about this character.  I fear for us all.", progress = nil, completion = "Ah so Madame Eva sent you. . . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][67] = {title = "The Legend of Stalvan", objective = "Travel to the Moonbrook Schoolhouse and bring back any updated information about Stalvan to Clerk Daltry.", description = "Stalvan, eh?  Let me check the town registry.\n\nStalvan. . .Stalvan. . .let's see.  Ah, here we go!  I have a record of a Mr. Stalvan Mistmantle.  The last recorded address is the Moonbrook Schoolhouse.  My, talk about outdated!\n\nDo me a favor will you, friend?  If you happen to go out to Moonbrook, let me know if you get any update on this fellow.  I like to keep the records clean.", progress = nil, completion = "The old footlocker creaks open. . . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][68] = {title = "The Legend of Stalvan", objective = "Take the Dusty Unsent Letter to Clerk Daltry.", description = "You find a Dusty Unsent Letter in the old footlocker.", progress = "Ah, I remember you.  You're the one who was asking about that Stalvan fellow.  Did you ever find what you were looking for?", completion = "Interesting.  So the chap did spend some time in Moonbrook after all.  It is rather odd the letter never got delivered.  Nonetheless, I shall update the registry.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][69] = {title = "The Legend of Stalvan", objective = "Go to The Lion's Pride Inn to see if anyone there has heard of the name Stalvan.", description = "Oh my!  Must have missed this the first time.  In the registry, right beneath the first address for Stalvan there's another one listed, only partially scratched out.  Looks like he was headed to The Lion's Pride Inn over in Goldshire.  Might want to check there, <name>.", progress = nil, completion = "Stalvan?  Sure sounds familiar.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][70] = {title = "The Legend of Stalvan", objective = "Retrieve Stalvan's Undelivered Letter from the chest and deliver it to the Canal District in Stormwind.", description = "The name Stalvan rings a bell.  I remember now.\n\nMany years back, on a stormy night, a messenger came in, seeking refuge for the night.  Near the stroke of midnight, the man ran down the stairs screaming, his face pale with fear.  Still wearing his bedclothes, he disappeared into the downpour.\n\nIn his haste he forgot his letters in the chest upstairs.  He never returned for them. One remains from that Stalvan fellow, intended for the Canal District in Stormwind.  Help yourself to it.", progress = "What have ya got there?  Let me take a look at that. . .", completion = "You've got some nerve bringing this here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][71] = {title = "Report to Thomas", objective = "Deliver Rolf and Malakai's Medallions to Guard Thomas at the eastern Elwynn bridge.", description = "Now that you have both medallions, deliver them to Guard Thomas at the bridge so that he might know the fate of his murdered guards.", progress = "Hello, <name>.  Have you discovered the fates of Rolf and Malakai?", completion = "You have confirmed my fears, &lt;name&gt;.  The murlocs are a threat we cannot ignore.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][72] = {title = "The Legend of Stalvan", objective = "Search through the packed up possessions for a clue.", description = "My father was the caretaker of the estate long before I was.  He had to mop the blood up after the massacre.  But that's neither here nor there.\n\nThe last funds of the Flintridge trust have dried up.  Now the last of the family possessions are headed for auction.  Blame the tax vultures.  I guess if you're really itching to learn more you're free to look through this junk.  Who knows what you might find.", progress = nil, completion = "You slowly slide the lid of the crate off. . . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][74] = {title = "The Legend of Stalvan", objective = "The Torn Journal page you discovered provides your next clue.", description = "Inside the crate you find various objects: musty heirlooms, a family portrait, a few hunting trophies and some old books.  Near the bottom, underneath a ceramic vase, you uncover A Torn Journal Page.", progress = "What have you got there?  I cannot see.  My eyesight is very bad.  Put it in my hands.", completion = "I can barely make out those letters.  But that writing style reminds me of something I once saw before my vision became so poor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][75] = {title = "The Legend of Stalvan", objective = "Marshal Haggard wants you to check the chest upstairs for the Faded Journal Page.", description = "There was a bundle of parchments in the chest upstairs when I moved into this place.  I looked at them once when I first arrived but I gave up once the fog hazed over my peepers. \n\nDo an old, nearly-blind man a favor and check the chest upstairs for anything that might help you in your quest to discover more about this Stalvan character.  I'm pretty sure there's a faded journal page that might be of interest to you.  Bring it to me and I'll help in anyway I can.", progress = "Did you find that page I mentioned, <name>?", completion = "You found it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][76] = {title = "The Jasperlode Mine", objective = "Explore the Jasperlode Mine, then report back to Marshal Dughan in Goldshire.", description = "Thanks to you we know the Fargodeep Mine is infested with kobolds.  Now we need a scout to investigate the more distant Jasperlode Mine.\n\nExplore Jasperlode and confirm any kobold presence.  To reach the mine, travel east along the road until you reach the Tower of Azora.  From the tower, head north and you'll find the mine in the foothills.", progress = "Hail, <name>.  What do you have to report? Have you scouted the Jasperlode Mine?", completion = "Kobolds at the Jasperlode Mine, you say?  Curses!  The situation is worsening by the minute!\n\nThank you for the report, &lt;name&gt;.  But I wish that the news you brought was good news.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][77] = {title = "A Sticky Situation", objective = "Recover 10 bottles of Hinterlands Honey Ripple from the crates located around the abandoned Horde base in Skulk Rock.", description = "I possess original packaging materials for the ripple Dran Droffers seeks.  I will assist you in packaging the ripple for Malton's abrasive father... for a fee of two additional bottles of said ripple.  They are located in crates found in the abandoned Horde base near Skulk Rock.\n\nIt will be an arduous task, to wit; foul slimes and oozes will be found sticking to the ruins; rumor has it they are led by some sort of master ooze.  Regardless, procure the ripple and return to me here for packaging.", progress = "I trust that your arrival here at our camp is to deliver the bottles of ripple that are integral to the task at hand, yes?", completion = "Finely executed, &lt;name&gt;.  I am glad you had enough foresight not to bruise the delicacy of the ripple.  There is nothing worse than the bouquet of ripple that has been jostled about needlessly.\n\nIt will take a moment for the magic to be wrought over this precious cargo.  Actually, no magic is involved; I merely have some empty packaging for Hinterlands Honey Ripple.  Our chicanery shall turn these bottles into an alcoholic treasure of the ages.\n\nOnward - for great booze!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][78] = {title = "The Legend of Stalvan", objective = "Take the Faded Journal Page to Tavernkeep Smitts.", description = "I know of someone who might be able to assist you.  Back when I was leading the Stormwind Guard, we used to get drinks at the Scarlet Raven Tavern in Darkshire.  The Innkeeper there, Smitts, was quite an expert on the local lore.  Show him this page and see what he has to say about it.", progress = "Marshal Haggard sent you?  Why didn't you say so? \n\nAh, good ol' Haggard.  Poor chap is going to be completely blind before long.  Anyway, let me see what you've got there.", completion = "By the Light!  You bet I recognize that handwriting.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][79] = {title = "The Legend of Stalvan", objective = "Take the muddy page to Commander Ebonlocke.", description = "I followed the legend of that Stalvan character for years.  When those visiting nobles were slaughtered a few years back I went with Haggard to investigate.  I found these muddy pages but we were never able to link the handwriting to that crazy man in the woods.  Your trail of evidence proves his guilt.  Take this to Commander Ebonlocke immediately and fill her in on what you've discovered!", progress = "This better be good, <class>.  Let me see what you have and tell me your tale.  But by the Light, be quick about it.  Darkshire's defense is my number one priority.  I have not the time to squander on dead-end leads.", completion = "My, you have proved yourself to be quite a detective, &lt;class&gt;.", rewards = "You will receive:\n\nA Bloodstained Journal Page"}
MultiLanguageQuestData['en'][80] = {title = "The Legend of Stalvan", objective = "Show Clerk Daltry the Bloodstained Journal Page.", description = "I have had my eye on that creep, Stalvan, for quite sometime.  But if this page was written by the same hand it proves his guilt beyond a shadow of a doubt.\n\nIn all his days keeping the Town Registry, Clerk Daltry has become an expert at identifying handwriting.  Show him this page and see if the writing matches that of the registry signature.", progress = "Back again, <name>?  What do you have this time?", completion = "Why yes!  The writing on this page does in fact match that of the registry signatures.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][81] = {title = "Ripple Delivery", objective = "Deliver the barrel to Dran Droffers in Orgrimmar.", description = "I have taken the extra step of securing not only Dran's packaged ripple in the barrel, but also the extra bottles of ripple he is purloining.  While I may not hold Dran very highly, there is nothing worse than jostled ripple.  You're welcome.\n\nNow, deliver yon barrel to Dran Droffers in his salvage emporium in Orgrimmar.  Pray tell, please extend my warmest greetings to Malton; let him know that should he ever thirst for fine drink and finer drinking companions, we would be honored with his visit.", progress = "If you're not here to buy anything, and you're not here to deliver anything, then you're wasting my time!  You better have that ripple!", completion = "Well, let's see what's in this barrel!\n\nYes, yes, it looks as though it is all here.  Here's your fee for the package, good job on that.  I stand to make five times that fee when I sell it to the tavern!  Har har!\n\nThese extra bottles of Hinterlands Honey Ripple are going to be set for a special occasion.  I think I'll drink some with champagne.  I'll call it... champipple.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][82] = {title = "Noxious Lair Investigation", objective = "Bring five Centipaar insect parts from the Noxious Lair to Alchemist Pestlezugg in Gadgetzan.", description = "All right now, these reports about the bugs... what we know is that they are draining the water pools that used to be where the Noxious Lair is. What we DON'T know is, well, everything else.\n\nLet's figure out who our enemy is first! I want you to head into the Noxious Lair and get some parts off of those critters. Get five from the Centipaar there and bring them to Alchemist Pestlezugg for him to dink with. With him on the case, we'll figure out what they are!", progress = "You're Junior Surveyor <name>, yes?  Quickly now, there is a dire situation at hand!  Do you have the insect parts that Fizzledowser said you would?!", completion = "Good work - I'll start my analysis on these now!  I can tell you right from the start though... these are nothing like any insect form I have ever seen.  It's almost as if these bugs are being controlled by an outside force or something.\n\nYou need to go talk to Fizzledowser right away; apparently there is an emergency that he needs your help with on the double!  I'm not sure, but I think it involves more of the bugs in the Tanaris desert!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][83] = {title = "Red Linen Goods", objective = "Bring 6 Red Linen Bandanas to Sara Timberlain at the Eastvale Logging Camp.", description = "The Defias gang in Northshire wears burlap masks, but the Defias in Elwynn wear linen which I can use to make fine linen goods.\n\nBring me red linen bandanas and I'll use them to fashion something for you.\n\nDefias gang members have camps pocketed throughout Elwynn.", progress = "I'm running low on linen, <name>.  Do you have any for me?", completion = "Ah, these are nice bandanas, if a little rough...\n\nHere you are!", rewards = "You will receive:\n\nRed Linen ShirtRed Linen Sash"}
MultiLanguageQuestData['en'][84] = {title = "Back to Billy", objective = "Bring the Pork Belly Pie to Billy Maclure at the Maclure Vineyards.", description = "Here you go.  And when you give this pie to that Billy, you tell him I hope he chokes on it!", progress = "Ugh... I'm starving!  Do you have that pie for me, <name>?", completion = "Mm, yum!  This pie is the best!\n\nI think my memory is coming back to me...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][85] = {title = "Lost Necklace", objective = "Speak with Billy Maclure.", description = "I lost my necklace, and think that guttersnipe Billy Maclure took it!  He's usually scuttling like a rat around the Maclure vineyards east of here. \n\nGet my necklace back for me, and you'll warm an old widow's heart.", progress = nil, completion = "You lost a what?  Well I didn't take no necklace, because I ain't no thief!\n\nI might know who did but...&lt;grin&gt;...I'm too hungry to remember.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][86] = {title = "Pie for Billy", objective = "Bring 4 Chunks of Boar Meat to Auntie Bernice Stonefield at the Stonefield's Farm.", description = "Maybe if I got a pie, I could tell you who has that necklace.  And you know, I think that old Bernice lady at that other farm makes great Pork Belly Pies... \n\nMaybe if you gave her some chunks of boar meat from the boars that hang around our farms, and told her what it was for, she'd bake up a pie for you.", progress = "I don't think it's right feeding the boy who stole my necklace in the first place, but if that's what it takes to get back what's mine, then so be it!\n\nDo you have that boar meat?", completion = "Though this wild boar meat is tough, simmer it enough and it sure does make for some tasty pie!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][87] = {title = "Goldtooth", objective = "Bring Bernice's Necklace to \"Auntie\" Bernice Stonefield at the Stonefield Farm.", description = "I was playing near the Fargodeep Mine, and I think I dropped, er...I mean I saw, the old lady's necklace.  Don't ask me how it got there...it wasn't me!\n\nWell anyway, I saw this big, gold-toothed kobold pick up the necklace and run into the mine.  Go find that kobold and you'll find the necklace, I swear!", progress = "Hello, <name>.  Have you found my necklace?", completion = "Oh, you found it!  Thank you, thank you dear!\n\nHere, take this.  It was my husband's and he always said it was lucky.  If only he didn't forget it on his last campaign! *sniff*", rewards = "You will receive:\n\nLion-stamped Gloves"}
MultiLanguageQuestData['en'][88] = {title = "Princess Must Die!", objective = "Kill Princess, grab her collar, then bring it back to Ma Stonefield at the Stonefield Farm.", description = "The Brackwells have a prize-winning pig, Princess.  The sow is HUGE, and she got that way from sneaking over here and eating my veggies!\n\nSo before she comes to our fields...Princess must die!  Bring me her collar as proof of the deed and I'll give you something for your time!\n\nPrincess is usually over at the Brackwell Pumpkin Patch, to the east and beyond the Maclure farm.  Get her before she gets hungry and comes back here!", progress = "Did you see her yet?  Did you get her?", completion = "Thank goodness!  That pig was getting so big she'd have eaten our whole crop!  Thank you, &lt;name&gt;.\n\nNow, do either of these suit you?", rewards = "You will be able to choose one of these rewards:\n\nWeather-worn BootsBrass-studded BracersFarmer's Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][89] = {title = "The Everstill Bridge", objective = "Bring 5 Iron Pikes and 5 Iron Rivets to Foreman Oslow in Lakeshire.", description = "During the last orc invasion we were forced to smelt our iron down to make bullets, swords and armor.  We sent word to Stormwind for a new shipment of materials but a band of Redridge gnolls hijacked the caravan and ran off into the hills behind Lakeshire.\n\nNow we're coming up short on supplies to get this bridge rebuilt.  If you can bring me 5 iron pikes and 5 iron rivets, <name>, I'll make sure you're rewarded. \n\nNow let's get to work!", progress = "This bridge isn't going to build itself!  Now where are those iron pikes and iron rivets?", completion = "Great work, &lt;name&gt;.  These supplies will help the bridge effort immensely.  We'll get this beauty shored up in no time.", rewards = "You will be able to choose one of these rewards:\n\nSmith's TrousersBridgeworker's GlovesRiding Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][90] = {title = "Seasoned Wolf Kabobs", objective = "Gather 10 Lean Wolf Flanks and Stormwind Seasoning Herbs and return to Chef Grual in Darkshire.", description = "Seasoned Wolf Kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.  Bring me 10 Lean Wolf Flanks as well as some Stormwind Seasoning Herbs.  There are so many wolves here in the forest, I am sure finding the Flanks will be no problem.  For the herbs, seek out Felicia Gump in her canal district flower shop in Stormwind.", progress = "Were you able to find 10 Lean Wolf Flanks yet?  How about the herbs from Felicia in Stormwind?", completion = "Very nice work, &lt;name&gt;!  Enjoy the delicacy known as Seasoned Wolf Kabob!", rewards = "You will receive:\n\nSeasoned Wolf KabobRecipe: Seasoned Wolf Kabob"}
MultiLanguageQuestData['en'][91] = {title = "Solomon's Law", objective = "Bring 10 Shadowhide Pendants to Bailiff Conacher in the Lakeshire Town Hall.", description = "An enemy of Stormwind has taken up residence in the eastern foothills of Redridge. This wicked villain uses the Arcane to spread terror and misery upon our town and our people. Under the name, Morganth, he conducts his evil business.\n\nMorganth now controls the Shadowhide Gnoll Clan to perform his biddings. As stated by the Law of Lakeshire, aiding a criminal of the Kingdom is punishable by death.\n\nThese vile gnolls must be killed!\n\nTurn in 10 Shadowhide Pendants to me, and you shall be rewarded.", progress = "Turn in 10 Shadowhide Pendants to me, and you shall be rewarded.", completion = "The Court of Lakeshire recognizes your commitment to justice, &lt;name&gt;.  By enforcing the laws of the Kingdom you have helped uphold the justice of the land.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][92] = {title = "Redridge Goulash", objective = "Chef Breanna of Lakeshire wants five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", description = "Nothing would please me more than to make you some Redridge Goulash. But there's a slight problem. During the recent orc uprising I fed the entire brigade of Stormwind troops. My cupboard is now bare. But if you can provide me with the ingredients, I'd be happy to oblige.\n\nJust bring me five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", progress = "I still need five pieces of Tough Condor Meat, five Great Goretusk Snouts and five helpings of Crisp Spider Meat.", completion = "Well done, &lt;name&gt;. Such fine specimens too! And here is your delicious delicacy known as Redridge Goulash!", rewards = "You will receive:\n\nRedridge GoulashRecipe: Redridge Goulash"}
MultiLanguageQuestData['en'][93] = {title = "Dusky Crab Cakes", objective = "Gather 6 Gooey Spider Legs and bring them to Chef Grual in Darkshire.", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider legs!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!  Bring me Gooey Spider Legs and I'll whip you up a few of them.\n\nI hear Venom Web Spiders are a good source - they nest to the north, between the foothills and the river.", progress = "Hail, <name>.  Did you get those Gooey Spider Legs yet?", completion = "Ah yes, a nice clutch of legs you have there!  Let me just get these seasoned with my secret spices (no looking!) and get them to skittering on a skillet for a while...\n\nAnd, although Dusky Crab Cakes are my specialty and I won't give out the recipe, here's the recipe for a dish that's almost as good.", rewards = "You will receive:\n\nRecipe: Gooey Spider Cake"}
MultiLanguageQuestData['en'][94] = {title = "A Watchful Eye", objective = "Take the Glyph of Azora to the Lion Statue near the Tower of Ilgalar in Redridge.", description = "My rival, Morganth, is a vicious mage of great power who lives in the Tower of Ilgalar in Redridge.  I have developed a means of spying on him, the Eye of Azora, and can now view him from afar.\n\nBut to study his thoughts ... I require further aid.\n\nIf you are willing, then take my Glyph of Azora to the Tower of Ilgalar.  Place it upon the Lion Statue near the Tower.\n\nWhen this is done, the power of Azora will grant visions of Morganth's future plans.", progress = "This Lion Statue has sat here for decades, and keeps a lonely watch over the infamous Tower of Ilgalar.\n\nThere is a depression at the base of the statue, where a gem or glyph might be set...", completion = "You place the Glyph of Azora on the stone.  It adheres itself ... and you hear from it Theocritus' disembodied voice:\n\nYou have my gratitude, young &lt;name&gt;.  You may now speak with me through this Glyph, and I might have future tasks for you ... after I have probed the thoughts of my rival.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][95] = {title = "Sven's Revenge", objective = "Go to Sven's Farm and find what was buried behind the old stump.", description = "I used to work one of the farms to the southeast...until Dark Riders from Deadwind Pass descended upon my farm and slaughtered my family when I was away!\n\nWhen I returned I saw a shadowy figure skulking near my barn, burying something.  He fled before I could catch him, and I couldn't linger for I was hot on the heels of the Dark Riders.  So I never discovered what was hidden.\n\nIf you can find what that shadowy figure buried, I would be grateful.  The hiding spot is behind the old stump near my barn.", progress = nil, completion = "A mound of dirt is here, hastily piled up as if someone had need of hiding something...without much time to do it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][96] = {title = "Call of Water", objective = "Bring the Shard of Water to Islen Waterseer in the Barrens.", description = "Take shard. Take shard and give life.\n\nGive life and understand. Understand water is life... corruption stops life.\n\nYou protect and give life with water's power.", progress = "You've returned. Splendid!\n\nHow went your journey to Silverpine? Did it take you long?\n\nIt is hard for me to tell if you were successful there because so much of the land has become corrupt. Its stench overwhelms any good that you might have done. But small successes are sometimes as important as large ones. Purifying the water there was instrumental for you, and for all shamans.", completion = "This is the proof I asked for. You've done well, &lt;name&gt;.\n\nI am pleased to be the first to congratulate you and give you this... your water totem.\n\nUse it well, and good luck.\n\nYour next test will not be for some time, so learn your lessons well. Pure water will not only give life back to those who are injured, but can have many other effects. I suggest you seek out a &lt;class&gt; trainer when you have the time. They might have other spells for you to learn.", rewards = "You will learn:\n\nHealing Stream Totem\n\nThe following spell will be cast on you:\n\nHealing Stream Totem\n\nYou will also receive:\n\nWater Totem"}
MultiLanguageQuestData['en'][97] = {title = "The Legend of Stalvan", objective = "Report the news to Commander Ebonlocke.", description = "Let Commander Ebonlocke know immediately that the handwriting matched, <name>!  Her suspicions were correct!", progress = nil, completion = "I knew it!  Fine work, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][98] = {title = "The Legend of Stalvan", objective = "Kill Stalvan Mistmantle and show Madame Eva his family ring.", description = "Stalvan Mistmantle led a life of depravity.  Innocent victims died by his hand.  Undoubtedly he is guilty of countless crimes.  Now the lunatic threatens Darkshire.  The Light only knows what sordid acts he is plotting.  Travel to his cottage just north of town, <class>, and execute Stalvan, once and for all.\n\nWhen the deed is done, travel to Madame Eva's and show her his family ring.  After all, it was her premonition that led to this gruesome discovery.  But Darkshire is safer because of her.", progress = "Yes, <name>?", completion = "I know, &lt;name&gt;: Stalvan is dead.  I sensed a wave of hope ripple through the tainted forest.  Once and for all, Duskwood is free from his blood thirst.  My joy is hampered by thoughts of those who fell prey to the horrible beast.  Nonetheless, you are a brave and cunning &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nCrescent of Forlorn SpiritsRing of Forlorn Spirits\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][99] = {title = "Arugal's Folly", objective = "Bring 6 Pyrewood Shackles to Dalar Dawnweaver at the Sepulcher.", description = "As my understanding of Arugal's magic grows so does my disdain for the hapless fool.  I am close to completing my research on his so called remedy.\n\nMy knowledge will be complete when I learn what enchantment is causing the strange behavior going on in Pyrewood Village.  By day, the peasants appear to be Human.  But when the sun goes down the townsfolk turn into Moonrage Worgen.\n\nI need to draw energy from the enchanted shackles Arugal cast on them.  Bring to me six enchanted Pyrewood Shackles, <name>.", progress = "Have you secured the Pyrewood Shackles yet, <name>?", completion = "Your persistence is commendable.  With the knowledge you helped me gather, Arugal will fall and his reckless magic shall be undone.  Cheers to you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nLogsplitterBonegrinding PestleCinder Wand\n\nThe following spell will be cast on you:\n\nArcane Intellect\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][100] = {title = "Call of Water", objective = "Speak to the Minor Manifestation of Water in Silverpine Forest.", description = "Light explodes as you finish the incantation. The sounds of the water drops hitting the flame have died down and your senses are overcome as the corrupt spirits around you are destroyed.", progress = nil, completion = "Thanks to you. Thanks to the shamans.\n\nCorruption ebbs but life continues to wane. Up to shamans to protect life.", rewards = nil}
MultiLanguageQuestData['en'][101] = {title = "The Totem of Infliction", objective = "Bring 10 Ghoul Fangs, 10 Skeleton Fingers and 5 Vials of Spider Venom to Madame Eva in Darkshire.", description = "As the mystical taint creeps through the forest, the need for self-protection is undeniable, <name>.  The winds whisper to me and they speak of a great danger which waits patiently for you in the near future.\n\nIf you wish to protect yourself, noble <class>, bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", progress = "Bring to me 10 ghoul fangs, 10 skeleton fingers and 5 vials of spider venom.  For you I shall enchant a Totem of Infliction which will harm those who attempt violent acts against you.", completion = "Very wise of you, &lt;name&gt;.  This Totem of Infliction will help to protect you against the evil which lurks throughout Azeroth and beyond.  When you feel threatened, hold this totem and take comfort in its magical aura.  Be brave, fair &lt;class&gt;.  You will need all the courage you can muster for I see much bloodshed in your future.", rewards = "You will receive:\n\nTotem of Infliction"}
MultiLanguageQuestData['en'][102] = {title = "Patrolling Westfall", objective = "Bring 8 Gnoll Paws to Captain Danuvin on Sentinel Hill.", description = "Stormwind has abandoned us.  A foul wind of depravity rustles through the plains of Westfall.  This was my homeland and I will not turn my back on the citizens who choose to remain here.  We, the former farmers, shall make our stand.\n\nYour task, should you choose to accept, is to patrol the grasslands of Westfall.  Track down and slay the vile Gnolls that seem to be working in conjunction with the Deadmines thieves. Bring me eight Gnoll Paws and I will reward your bravery.", progress = "Have you collected 8 paws from those treacherous Gnolls yet?", completion = "Well done, &lt;name&gt;.  With valiant adventurers such as yourself fighting alongside The People's Militia, Westfall just might return to the prosperous breadbasket it once was.  Please accept this in recognition of your tireless efforts.", rewards = "You will be able to choose one of these rewards:\n\nBelt of the People's MilitiaBracers of the People's Militia\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][103] = {title = "Keeper of the Flame", objective = "Bring 5 Flasks of Oil to Captain Grayson at the Westfall Lighthouse.", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me 5 flasks of oil from the Harvest Monsters.", progress = "The flame will not burn for long without oil, <name>.", completion = "Praise you, brave &lt;class&gt;.  The rocks of the Westfall Coast shall be lit thanks to your hard work.  Many lives will be spared so long as the torch is kept lit.\n\nI died needlessly on this very shore.  My afterlife plight is to see that no others follow my destiny.", rewards = "You will be able to choose one of these rewards:\n\nMinor Mana PotionMinor Healing Potion\n\nYou will also receive:\n\nScroll of IntellectScroll of Stamina"}
MultiLanguageQuestData['en'][104] = {title = "The Coastal Menace", objective = "Bring a scale of Old Murk-Eye to Captain Grayson at the Westfall Lighthouse.", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", progress = "Have you laid waste to the menace known as Old Murk-Eye yet?  He has been spotted roaming the coastline of Westfall.\n\nReturn to me when the foul beast is dead.", completion = "So the foul heathen, Murk-Eye is dead.  Well done, &lt;name&gt;.  By your hands one life was laid to rest but perhaps many more were saved.  The Great Sea, wrought with danger as it is, shall be a wee bit safer this night thanks to your heroics.", rewards = "You will be able to choose one of these rewards:\n\nGrayson's TorchBuckler of the SeasTorchlight Wand\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][105] = {title = "Alas, Andorhal", objective = "Bring Araj's Phylactery Shard to High Executor Derrington at the Bulwark, Western Plaguelands.", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, <name>, and bring me a shard from his phylactery as proof!", progress = "Your task has been given to you, <name>.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Horde on this day, &lt;name&gt;.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Horde a victory for the ages!", rewards = "You will receive:\n\nMark of Resolution"}
MultiLanguageQuestData['en'][106] = {title = "Young Lovers", objective = "Give Maybell's Love Letter to Tommy Joe Stonefield.", description = "Oh, I'm cursed!  My heart belongs to Tommy Joe Stonefield, but our families are bitter enemies.  So I can't see him, even though my eyes ache to gaze upon that handsome face!\n\nPlease, take this letter and give it to Tommy Joe.  He's usually at the river to the west of the Stonefield Farm, which is due west of here.", progress = "You have what??  Maybell is the light of my dull life.  Hurry, let me see her letter!", completion = "Ah!  I can't stand us being apart.  I have to see her!!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][107] = {title = "Note to William", objective = "Take Gramma Stonefield's Note to William Pestle.", description = "I bet William Pestle has a potion to unite our two young lovers!\n\nHere, take this note to William.  He's staying at the Lion's Pride Inn in Goldshire.", progress = "You have a note from \"Gramma\" Stonefield, eh?  I haven't seen Mildred in years!  I wonder what she has to say...", completion = "My heart goes out to those two poor souls, Maybell and Tommy Joe.  I remember being young and in love, once.\n\nThere must be something I can do to help them!  Let me think...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][109] = {title = "Report to Gryan Stoutmantle", objective = "Talk to Gryan Stoutmantle. He usually can be found in the stone tower on Sentinel Hill, just off the road, in the middle of Westfall.", description = "Looks to me you've seen quite a bit of combat in your time, <class>.  If you haven't already, you should report to Gryan Stoutmantle.  He heads up the People's Militia, aimed at protecting the farmlands of Westfall.  I bet he could use your help.  You can usually find him in the stone tower on Sentinel Hill, just off the road in the middle of Westfall.", progress = nil, completion = "Ah, so my friend sent you here?  How kind.  \n\nWell the Stormwind Monarchy has abandoned our cause.  Now it is up to the People's Militia to keep the land free from corruption.  If our cause interests you, I can put your combat skills to use in the name of freedom.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][110] = {title = "Insect Part Analysis", objective = "Check in Gadgetzan for Alchemist Pestlezugg and his analysis of the insect parts.", description = "I'm going to spend some time taking a look at Scrimshank's surveying gear... as well as putting his personal effects in order.  I get the sneaking feeling behind my ears that this isn't the last loss we'll be facing against these bugs.\n\nI'd like for you to check in with Alchemist Pestlezugg to see if he has had a chance to process the insect parts we sent him.  If they're ready, bring them to me.", progress = nil, completion = "Yes, I have the results right here.  They are... unsettling, to say the least\n\nOur initial suspicion that the bugs are being controlled by an outside force, we believe, is correct.  If this is the case, then we are dealing with not only a very powerful unknown force, but also a malignant one.  These bugs have been changed to be pure ravagers.  I've never seen anything quite like it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][111] = {title = "Speak with Gramma", objective = "Speak with Gramma Stonefield.", description = "Please, <name>, talk with my Gramma.  If anyone can find a way to bring me together with Maybell, she can.\n\nShe's inside our house east of here.", progress = nil, completion = "While our families are feuding, Tommy Joe and Maybell don't have much of a future, but... maybe we can get them together for just a little while.\n\nHm, what can we do...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][112] = {title = "Collecting Kelp", objective = "Bring 4 Crystal Kelp Fronds to William Pestle in Goldshire.", description = "I can make an invisibility liquor for Maybell, so she can slip away from the Maclure Vineyards and go to Tommy Joe.  But to make the Liquor, I need some crystal kelp.\n\nAlthough the kelp usually grows in the ocean... sometimes murlocs collect it.  See if the murlocs near Crystal Lake have any.  Crystal Lake is just east of Goldshire.", progress = "Do you have that crystal kelp?  I'm sure Maybell is anxious to see her beau...", completion = "You got them.  Good show!  Now, just one moment while I concoct the potion...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][113] = {title = "Insect Part Analysis", objective = "Deliver the report to Senior Surveyor Fizzledowser in Gadgetzan. Be sure he gives you a copy of the report, as Alchemist Pestlezugg has requested.", description = "Senior Surveyor Fizzledowser needs to see this report immediately.  Actually... everyone who can read needs to see this report.  We are facing a grave and serious threat to not only Tanaris and Gadgetzan, but if left unchecked, the entirety of southern Kalimdor.  Heck, even quite possible the whole of Azeroth; this thing has given no indication it will subside.\n\nHave Fizzledowser make a duplicate of the report for you to distribute freely to your allegiance. Everyone must know about this threat!", progress = "Well Junior Surveyor <name>, has ol' Pestlezugg got that report ready yet?", completion = "Thank you for delivering the report, Junior Surveyor &lt;name&gt;; here is your pay for your diligent service to the Gadgetzan Water Company.\n\nWhile I am usually not thrilled about handing out our valuable information carte blanche to those who would otherwise pay good coin for it, I've known Pestlezugg for a number of years now.  If he recommends letting everyone know about it, then so be it.  Give me a moment and I'll make you a copy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][114] = {title = "The Escape", objective = "Take the Invisibility Liquor to Maybell Maclure.", description = "Take this invisibility liquor to young Maybell.  It should last long enough for her to visit Tommy Joe.", progress = "Did you deliver my letter to Tommy Joe?  What did he say??", completion = "Oh...my!  I feel guilty deceiving my family, but my feelings for Tommy Joe are too strong to ignore.\n\nThank you, &lt;name&gt;.  I'll drink this liquor as soon as I have the chance and sneak away to my love.\n\nAnd for you... please take this.", rewards = "You will receive:\n\nMinor Healing Potion"}
MultiLanguageQuestData['en'][115] = {title = "Shadow Magic", objective = "Bring 3 Midnight Orbs to Marshal Marris in Lakeshire.", description = "The Blackrock orcs enlisted shadowcasters to aid their attacks in Redridge, and they have brought with them devices of dark power--midnight orbs.  These orbs have struck telling blows against Redridge's defenders, and it's imperative we remove the demon-tainted items from the conflict.\n\nFind and deliver to me midnight orbs from slain Blackrock shadowcasters.  I will then have them disposed of, for this world would be a better place without them!", progress = "How goes your conflict with the shadowcasters?  Did you find the midnight orbs?", completion = "Thank you, &lt;name&gt;.  I'll send these to be destroyed immediately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][116] = {title = "Dry Times", objective = "Barkeep Daniels of Lakeshire needs a keg of Thunderbrew Lager, a cask of Merlot, a bottle of Moonshine and a skin of Sweet Rum.", description = "I find myself in quite a pinch here, <name>.  The bottles are close to running dry.  The latest booze shipment is long overdue.  The orc invasion has been hell.\n\nPerhaps you can go to work for me?\n\nI need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", progress = "I need you to pick up a keg of Thunderbrew Lager from Grimbooze Thunderbrew in the Westfall hills, a cask of Merlot from Stormwind, a bottle of Moonshine from Darkshire and a skin of Sweet Rum from Goldshire.  Bring those back to me and I will see to it you are rewarded.", completion = "A job well done, &lt;name&gt;!  I know well the roads you had to journey to procure this fine array of liquor.  But my patrons will be happy once again! \n\nMy wife is quite a seamstress.  Please accept this cloak she made in return for your services.", rewards = "You will receive:\n\nFinely Woven CloakA Bulging Coin Purse"}
MultiLanguageQuestData['en'][117] = {title = "Thunderbrew", objective = "Bring Grimbooze Thunderbrew 5 hops to complete his special brew.", description = "Hurry, my friend, move with haste \nIn order for our rich lager to taste \nMore like beer and less like stew, \nHops are needed to make the brew.", progress = "Hurry, my friend, move with haste \nIn order for our rich lager to taste\nMore like beer and less like stew,\nHops are needed to make the brew.", completion = "Hops and Barley, yeast and malt \nThe taste-buds feel a virtual assault, \nNo need to plead, no need to beg \nFor Thunderbrew Lager comes in a keg!", rewards = "You will receive:\n\nKeg of Thunderbrew"}
MultiLanguageQuestData['en'][118] = {title = "The Price of Shoes", objective = "Take Verner's Note to Smith Argus in Goldshire.", description = "I've been using so much iron keeping the Stormwind Guards outfitted, I don't have enough to supply the stable's horses with shoes!\n\nTake this note to Blacksmith Argus in Goldshire.  It explains to him my problem and requests a shipment of horseshoes.", progress = "What's that?  Verner sent you, you say?  Well give me his note.  And SPEAK UP!", completion = "Heh, so old Verner needs some shoes, does he!?!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][119] = {title = "Return to Verner", objective = "Return to Verner Osgood in Redridge. Give him the Crate of Horseshoes.", description = "Ok, I'll give him his 50 horseshoes...\n\nHere they are, all boxed up and ready to go!  Tell Verner it was a pleasure doing business, and be sure he reads the note attached to this crate!", progress = "Great, you're back!  Did you get the shoes?", completion = "Thank you, this really helps me out.\n\nBut what's this?  Argus sent a note with the crate...What??  Argus wants me to PAY him?  Bah!\n\nWell, &lt;name&gt;, thank you for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][120] = {title = "Messenger to Stormwind", objective = "Magistrate Solomon has given you a report which must be delivered to General Marcus Jonathan in Stormwind. The judge wants you to return to him as soon as the delivery has been made.", description = "These are trying times, <class>.  The township is under constant siege.  Without reinforcements, we will certainly face defeat.  The message I now entrust to you is of utmost importance.  Get this report to General Marcus Jonathan of Stormwind immediately.  Once your delivery is made, return to me at once with any news, be it good or bad. \n\nNow make haste!", progress = "What have you there?", completion = "At ease, &lt;class&gt;.\n\nMagistrate Solomon is a noble leader.  His words carry great weight with me.  I shall seek the counsel of the King and make the situation clear to him.  Assure the good judge that he has the Stormwind Army's support.  Reinforcements will be sent as soon as word is given from His Majesty.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][121] = {title = "Messenger to Stormwind", objective = "Take General Marcus Jonathan's letter of response to Magistrate Solomon in Lakeshire.", description = "While I wait for a response from the King I want you to carry this letter to Magistrate Solomon. \n\nDismissed, <class>!", progress = "Did the General send news?  Are reinforcements on the way?", completion = "Thank you for your time, &lt;class&gt;.  For your service to Lakeshire and Stormwind I reward you with these coins.\n\nNow if you'll excuse me, I find this correspondence somewhat of a mystery.  Something is amiss in our Kingdom.  I fear this is the beginning of conflict, not the end.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][122] = {title = "Underbelly Scales", objective = "Gather 6 Underbelly Whelp Scales from Black Dragon Whelps, and bring them to Verner Osgood in Redridge.", description = "I need some underbelly scales from black dragon whelps to pay for the shoes Argus sent me from Goldshire.  If you can get 6 of them for me, then I can pay Argus with some... and have enough left to fashion something for you.\n\nBlack dragon whelps are often flying around south of Lakeshire, but they like to wander.  You might have to just keep an eye out and hunt them when you see them.", progress = "I know that greedy Argus will send someone to collect his scales if I don't give them to him soon.  Have you found those scales yet?", completion = "Thanks!  These will get me out of debt to Argus...", rewards = "You will be able to choose one of these rewards:\n\nBlack Whelp BootsBlack Whelp Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][123] = {title = "The Collector", objective = "Go to Marshal Dughan in Goldshire and give him The Collector's Schedule.", description = "This note is a schedule with a list of days and times when a person -- described only as \"The Collector\" -- will receive a shipment of gold from the mines in Elwynn Forest.\n\nFrom the schedule, it looks as if the Collector resides near the Brackwell Pumpkin Patch in eastern Elwynn.\n\nThis sounds important.  You should report it to Marshal Dughan in Goldshire.", progress = "What?!?  We haven't had our people working the Elwynn mines for months!\n\nLet me see that note you have...", completion = "Hm... I have heard of this \"Collector\" but I don't know whom he's working for.  Thank you for the schedule.  It will help us solve this mystery.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][124] = {title = "A Baying of Gnolls", objective = "Kill 10 Redridge Brutes and 8 Redridge Mystics, then return to Verner Osgood.", description = "As if the attacking orcs weren't enough!  Now I have gnoll brutes and mystics prowling along the ridge north of my stable, taking my horses when they stray...\n\nIf you can get rid of those gnolls, my horses and I would be very grateful.", progress = "My horses still seem skittish, and I still hear that cursed wolf cry at night.  Please, <name>, do something about those Gnolls!", completion = "Thank you for all your help, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][125] = {title = "The Lost Tools", objective = "Foreman Oslow of Lakeshire wants you to retrieve his toolbox from the bottom of Lake Everstill.", description = "I could really use a hand here, <name>.  With the town under siege, it's been hard to get supplies.  My tools were being delivered from Goldshire by wagon but the bridge was blown out.  We put the tools in a boat but the orcs hit it with a catapult.  Just my luck, my toolbox sank right to the bottom of the lake.\n\nRetrieve my toolbox, <name>, and I'll make it worth your while.", progress = "Were you able to find my tools?", completion = "Excellent recovery, &lt;name&gt;!  I never thought I'd see these tools again.", rewards = "You will receive:\n\nMedium Armor Kit"}
MultiLanguageQuestData['en'][126] = {title = "Howling in the Hills", objective = "Bring Yowler's Paw to Verner Osgood in Lakeshire.", description = "<name>, the gnolls are still out there.  I can hear their baying as they hunt in the hills above Lakeshire.  And one cry is louder than the rest - Yowler,  their leader.\n\nKill Yowler and send his pack scattering!  Bring me his paw as proof.\n\nAnd be careful, this gnoll is their leader for a reason.  He is no Mongrel...", progress = "Yowler is a dangerous creature, <name>.  If you're not ready for him, I understand.", completion = "Again, thank you for your help.  The Stormwind army is so busy dealing with the orcs, they don't have the troops to protect Redridge from local threats like the gnolls.", rewards = "You will be able to choose one of these rewards:\n\nRing of Iron WillGold Militia Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][127] = {title = "Selling Fish", objective = "Bring 10 Spotted Sunfish to Dockmaster Baren in Lakeshire.", description = "Lake Everstill is famous for its spotted sunfish.  There's always demand for them...and I'm running low!\n\nBring me a batch of 10 and I'll barter well for them.  If you can't fish yourself, then...maybe you can get them off the murlocs!", progress = "You have some sunfish for me, eh?", completion = "Pleasure doin' business with you, matey!", rewards = "You will receive:\n\nMurloc Fin SoupRecipe: Murloc Fin SoupFishliver Oil"}
MultiLanguageQuestData['en'][128] = {title = "Blackrock Bounty", objective = "Kill 15 Blackrock Champions and Guard Howe in Lakeshire will reward you.", description = "The Blackrock Clan must be destroyed. The Enemy has invaded our lands. These mountains fall under the sovereign right of the King of Stormwind. Our sources tell us that the leaders of each unit within the Clan are known as Champions. You'll find them in their encampment to the north, just west of the road to the Burning Steppes.\n\nMagistrate Solomon wants these foul brutes dead. Slay 15 Blackrock Champions and return to me.", progress = nil, completion = "I see you have fought valiantly against the Blackrock Clan, &lt;class&gt;.  Your service to our township is great indeed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][129] = {title = "A Free Lunch", objective = "Bring Parker's lunch to Guard Parker. He patrols the road leading to Darkshire.", description = "Can you do me a favor?  I've prepared a lunch for Guard Parker, but he's out on patrol...he's a big, strong Stormwind guard who can defend himself, but it's much too dangerous out there for a townsperson like me.\n\nSo if you deliver his lunch for me, then come back here and I'll give you a free lunch!  Parker patrols the stretch of road leading to Duskwood.", progress = "Darcy sent me a lunch, did she?  Such a kind heart she has.  Well...let's have it!", completion = "Thanks, I could really use the meal.  Guarding Lakeshire from the orcs and gnolls is tough work!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][130] = {title = "Visit the Herbalist", objective = "Speak with the Redridge Herbalist, Martie Jainrose.", description = "Before you go back to Darcy, can you bring her some flowers for me?  You can get them at the herbalist shop back in Lakeshire, at the west end of town.\n\nBut when you get the flowers...don't tell the herbalist, Martie, whom they're from, or whom they're for...", progress = nil, completion = "You need a bouquet of flowers?  You haven't been in town very long...have you already found for yourself a sweetheart here?\n\nI know I shouldn't pry, but it's nice to see that love is in the air... especially in dangerous times like these.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][131] = {title = "Delivering Daffodils", objective = "Give Darcy the Daffodil Bouquet.", description = "Here is your bouquet.  I chose Daffodils for you.  They're my favorite!", progress = "Hello again, <name>.  Did Parker like the lunch I sent him?", completion = "Oh, those are lovely!  I can't wait to put them in some water!\n\nBut...these are Martie's favorite flowers.  Parker didn't have you go to that jealous vixen for this bouquet, did he?  You didn't tell her who they were for, did you?  If you did, then it wouldn't surprise me if she poisoned them.\n\nOh, but it's not your fault.  Thank you, and here's your meal.", rewards = "You will receive:\n\nSauteed Sunfish"}
MultiLanguageQuestData['en'][132] = {title = "The Defias Brotherhood", objective = "Take Wiley's Note to Gryan Stoutmantle in Westfall.", description = "What I am about to tell you could cost me my life.  The Defias gang is up to something big.  Last I heard they were working in conjunction with various gnolls, kobolds and even goblins.\n\nTake this note to Stoutmantle.  It explains as much as I know on the subject.", progress = "Good to see you back, <name>.  What did Wiley have to say for himself?", completion = "Bah!  I should have let that scoundrel rot when I had the chance.  But this information is crucial.  Good work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][133] = {title = "Ghoulish Effigy", objective = "Gather 7 Ghoul Ribs and bring them to Abercrombie at his shack.", description = "I live so far from the protection of town, it's a wonder the ghouls and the walking dead haven't eaten me!  In fact, just yesterday a pack of Bone Chewers was pounding on the walls of my house!\n\nI want to make an effigy - a kind of \"scarecrow\" for Ghouls.  To do that I need some Ghoul Ribs.  You can get them from Flesh Eaters, Bone Chewers, Brain Eaters, Rotted Ones and Plague Spreaders.\n\nGet the ribs for me, and I will repay you with some coin.", progress = "I think I hear a pack of Ghouls scurrying around the back of the house - I better put that effigy up quick!  Did you get those Ghoul Ribs for me?", completion = "Ah, thanks.  These will do just the trick!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][134] = {title = "Ogre Thieves", objective = "Return Abercrombie's Crate to Abercrombie.", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, <name>, retrieve this crate for me for I miss it sorely.", progress = "Do you have my crate?  If so, then please...give it to me quickly!", completion = "Thank the Nec-...well, thank YOU, &lt;name&gt;!  You have more than earned your reward.\n\nAha!  Happy!  Happy nights ahead!!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][135] = {title = "The Defias Brotherhood", objective = "Take Wiley's Note to Mathias Shaw in Stormwind.", description = "I wonder what Wiley meant when he mentioned the Stonemasons.  Perhaps that was a slip of tongue.  Could the Defias gang be related to the Stonemasons?  Only one man would know for sure:  Mathias Shaw, head of SI:7. Show him Wiley's Note and see if he has anything to add to this growing mystery. If you have trouble finding Shaw, check the Barracks in Old Town.", progress = "What business do you have with me?  I am a very busy man. . .", completion = "This matter might be more complex than Stoutmantle realizes.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][136] = {title = "Captain Sander's Hidden Treasure", objective = "Find Captain Sanders' footlocker and search it for the next clue.", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", progress = nil, completion = "The footlocker slowly creaks open.  Sand and water seem to be its only contents. But wait!  A small crab scurries out with a clue to the treasure in his claws!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][138] = {title = "Captain Sander's Hidden Treasure", objective = "Find the old barrel near the ruined chimney and search it for your next clue.\n\nProvided item: \n", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", progress = nil, completion = "Good work, treasure hunter!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][139] = {title = "Captain Sander's Hidden Treasure", objective = "Search the empty jug next to the windmill for the next clue.\n\nProvided item: \n", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", progress = nil, completion = "You're on your way to the jackpot, treasure seeker!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][140] = {title = "Captain Sander's Hidden Treasure", objective = "Locate Captain Sanders' chest and open it for your reward.\n\nProvided item: \n", description = "Sure enough, deep within the Old Jug there is another clue to Sander's treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", progress = nil, completion = "The hinges on the old chest are rusty but they still work.  You force the chest open and take the booty.\n\nCongratulations!", rewards = "You will receive:\n\nSilver BarCaptain Sander's ShirtCaptain Sander's SashCaptain Sander's Booty Bag"}
MultiLanguageQuestData['en'][141] = {title = "The Defias Brotherhood", objective = "Take Shaw's report to Gryan Stoutmantle in Westfall.", description = "The Stonemasons' Guild was run by a man named Edwin VanCleef.  VanCleef was responsible for rebuilding Stormwind after the orcs razed it in the First War.  Apparently, VanCleef and his men were unhappy with their treatment by the King after the reconstruction was complete.  That just might explain a thing or two.\n\nI have written a more detailed account for your Master in Westfall.  Take this to him at once!", progress = "Did Master Shaw shed any light on things?", completion = "Edwin VanCleef. . .I know the name well.  To think that a man so industrious and talented could turn into such a scoundrel unnerves me.  I'll need further proof before I believe this.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][142] = {title = "The Defias Brotherhood", objective = "Track down the Defias Messenger in Westfall and bring his message to Stoutmantle.", description = "We need to discover the location of the Defias hideout.  <name>, my scout reports that a Defias Messenger has been seen on the roads between Moonbrook, the Gold Coast Quarry and the Jangolode Mine.  I want you to capture him.  If he resists, kill him and bring me whatever he is carrying.", progress = "<name>, were you able to gather any information?  Did you locate the messenger?", completion = "This is indeed firm proof that VanCleef is in charge.  Now all we need to know is where the Defias gang is hiding out.\n\nWe've had a stroke of luck while you were gone.  We captured a thief trying to steal Saldean's wagon.  He has promised to lead us to the hideout in exchange for his life.  I want you to defend the traitor so he can reveal the hideout.  Return to me once you have uncovered the location.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][143] = {title = "Messenger to Westfall", objective = "Magistrate Solomon wants you to take his written plea to Gryan Stoutmantle in Westfall.", description = "Something odd is afoot with the Stormwind Army.  They should have been here in force by now.  Time is a luxury we don't have, however.  I will not stand by and watch the people of Lakeshire give their lives without trying to enlist more help.  I've heard word of a people's militia forming in Westfall.\n\nTake this plea to their leader, Gryan Stoutmantle.  Perhaps Stoutmantle's men can lend some support here until the King sends reserves.", progress = "Hail, <class>.  What business do you have with The People's Militia?", completion = "Good Messenger, you have served your master well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][144] = {title = "Messenger to Westfall", objective = "Return to Magistrate Solomon with Gryan Stoutmantle's response.", description = "Magistrate Solomon's note pains me to read.  But it is obvious he knows not the war which is waged in Westfall or else he would know better than to expect aid from the Militia.  If Stormwind had not deserted us as well, we would not have the need for the Militia.\n\nTake this response to your master in Redridge, <class>.  And let him know that my heart is heavy with the loss of good men.", progress = "Shall we expect the People's Militia soon?  Does Lord Stoutmantle's news bode well?", completion = "I do say, this is not good at all.  I did not realize that Stoutmantle's situation was not unlike ours here in Lakeshire.  What action is so important that it calls the Stormwind Army away from its people?  Bah, I should not ponder aloud.\n\nHere, messenger.  Accept these coins in exchange for your service to the Township.  I might call upon you again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][145] = {title = "Messenger to Darkshire", objective = "Magistrate Solomon wants you to take a letter to Lord Ebonlocke in Darkshire.", description = "I require your assistance once again.  I have written to Lord Ebonlocke, requesting that he sends his trained guards, the Night Watch, to help with Lakeshire's defense.  It is imperative this message makes it to him swiftly.  You must exercise extreme caution.  Ebonlocke is the mayor of Darkshire, in the heart of Duskwood.  Do not stray from the roads.", progress = "You appear to have traveled from afar, <class>.  What business do you have here in Darkshire?", completion = "Thank you for making the long journey here.  This is indeed important information.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][146] = {title = "Messenger to Darkshire", objective = "Return to Magistrate Solomon with Lord Ebonlocke's letter of response.", description = "If I did not know Magistrate Solomon personally, I would say the man has gone mad.  Send the Night Watch to Lakeshire because Stormwind refuses aid?  The Night Watch was formed because Stormwind left us when this foul magic seeped into the land.  If I sent my Night Watch, this town would be overrun by evil before the guards even reached the forest's edge.\n\nTake this letter of response to your Master in Lakeshire.", progress = "Ah, good to see you back, messenger.  Shall I inform the Marshal that the Night Watch is on its way from Darkshire?", completion = "By the Light!  The Stormwind Army retreated from Westfall.  And the Guard no longer protects Darkshire?  There is some treachery abound.  How could this be so? \n\nOh I forgot to reward your service, &lt;class&gt;.  Here are some coins.  Now excuse me.  Something is amiss in Stormwind and I must get to the bottom of it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][147] = {title = "Manhunt", objective = "Find and kill \"the Collector\"  then return to Marshal Dughan with The Collector's Ring.", description = "If the \"Collector\" is taking gold from our mines then he's stealing from the kingdom!  Bring the Collector to justice, and bring me the ring mentioned in the pickup schedule you gave me.  It may tell us whom the Collector is working for...\n\nThat Pickup Schedule says the Collector is hiding out at the Brackwell Pumpkin Patch.  You should search for him there.", progress = "Did you find the Collector?  Did you discover whom he's working for?", completion = "You found him?  Well done, &lt;name&gt;.  He won't be \"collecting\" from the Elwynn Mines again!\n\nAnd this ring you found is interesting... it's a membership ring for the old Stonemason's Guild in Stormwind.  Why would a lowly thief have an artisan guild ring, and why are the Defias Thieves collecting money from our mines?\n\nDifficult questions.  I hope one day we'll have answers.", rewards = "You will be able to choose one of these rewards:\n\nStormwind Chain GlovesElastic Wristguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][148] = {title = "Supplies from Darkshire", objective = "Speak with Madame Eva.", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some Ghost Hair Thread?  You can get it from Madame Eva at her home on the Darkshire square.", progress = nil, completion = "Ah, Ghost Hair Thread is what you need, is it?  I'm afraid I have none in stock, but I can make some for you...if you can supply the ghost hair.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][149] = {title = "Ghost Hair Thread", objective = "Bring the Spectral Comb to Blind Mary.", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", progress = "<Sob> Oh please, don't look at me!  I tore out these eyes with my own hands, but I can still feel your gaze!\n\nI'm hideous!  Hideous!  Please, look away!!", completion = "What is this?  A comb?  It's lovely!  And it glides through my hair as if it weren't the stiff, stringy horror that it is.\n\nOh, if only I had a mirror...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][150] = {title = "Murloc Poachers", objective = "Bring 8 Murloc Fins to Dockmaster Baren in Lakeshire.", description = "Murlocs are becoming a problem.  Larger groups of the fishmen are dropping anchor along the shores of Lake Everstill and fishing up a storm!  We need them gone before they eat all the fish in the lake!\n\nHunt murlocs!  Bring me eight of their fins and I might have something for you...", progress = "Do you have those fins?  Hurry, we need those murlocs driven from the lake!", completion = "Well done, &lt;name&gt;.  I hope you didn't have too much trouble with those murlocs.\n\nIt's strange seeing them so far from the sea.  I wonder if they're here because they're running from something...", rewards = "You will receive:\n\nDwarven Fishing Pole"}
MultiLanguageQuestData['en'][151] = {title = "Poor Old Blanchy", objective = "Verna Furlbrow in Westfall wants you to bring her 8 Handfuls of Oats.", description = "Poor Old Blanchy!  Such a tired beast after all the work we put her through. I fed her before we left the farm, but we weren't expecting the wagon to break on us. If you could bring her a few handfuls of oats from the fields, I'd be grateful.\n\nI bet you could find some around all of the farms in Westfall, if you can steer clear of those horrific machines that have taken over. There are several farms southwest of here.", progress = "Old Blanchy is on her last leg.  Did you happen to find any oats for her?", completion = "Thank you so much, &lt;name&gt;!  Poor Old Blanchy will be so happy!", rewards = "You will receive:\n\nOld Blanchy's BlanketOld Blanchy's Feed Pouch"}
MultiLanguageQuestData['en'][152] = {title = "The Coast Isn't Clear", objective = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and return to Captain Grayson at the Westfall Lighthouse.", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", progress = "Kill 7 Tidehunters, 7 Warriors, 7 Oracles and 7 Coastrunners and I will see to it that you are rewarded.", completion = "Well done, &lt;name&gt;.  You have quite a knack for combat.  Thanks to you the Coast of Westfall is a safer place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][153] = {title = "Red Leather Bandanas", objective = "Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill.", description = "The Defias Front is constantly shifting.  I've been following their movements for quite some time now.  On a side note, I've ascertained that many members of the gang can be tracked by the Red Leather Bandanas they wear.\n\nBring me 15 of these Bandanas and I'll see to it you are rewarded.", progress = "Bring me 15 red leather bandanas and I'll pay you well.", completion = "Nice work, &lt;race&gt;.  Please accept one of these items as payment for all your hard work.", rewards = "You will be able to choose one of these rewards:\n\nCloak of the People's MilitiaGreaves of the People's MilitiaLeggings of the People's Militia\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][154] = {title = "Return the Comb", objective = "Return the Ghost Hair Comb to Madame Eva in Darkshire.", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", progress = "I sense that you have seen Blind Mary.  You have my Comb...?", completion = "I can make a spool of Ghost Hair Thread with this, and have a few strands to spare.  Here are some coins for those extra strands.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][155] = {title = "The Defias Brotherhood", objective = "Escort the Defias Traitor to the secret hideout of the Defias Brotherhood. Once the Defias Traitor shows you where VanCleef and his men are hiding out, return to Gryan Stoutmantle with the information.", description = "So Stoutmantle sends a scrawny <race> like you to protect me?  Guess you'll have to do.  Better bring some friends too. \n\nYou know the deal, right?  You watch my back and I'll take you to the Defias hideout.  But you better be close by my side.  The Defias gang wants my head now.  If they see me with you, they'll try to kill me.\n\nLet me know when you and any friends you can round up are ready to go.", progress = nil, completion = "Most excellent, &lt;name&gt;!  VanCleef is as good as ours now that we know where he is hiding.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][156] = {title = "Gather Rot Blossoms", objective = "Gather 8 Rot Blossoms and bring them to Tavernkeep Smitts in Darkshire.", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nrot blossoms grow in strange places.  In particular, I hear you can find them inside the skulls of Skeletal Horrors and Skeletal Fiends... not that I've gotten close enough to look!\n\nThe Raven Hill Cemetery is lousy with those skeletons.  You may as well get rid of them while you're looking for rot blossoms.  The town of Darkshire would be grateful.", progress = "Hi, <name>.  Do you have those rot blossoms for me yet?", completion = "Good,  you got the rot blossoms.  And I'll tell Althea Ebonlocke of the Night Watch that you were killing skeletons.\n\nKeeping the people of Darkshire safe is a grim burden for the Night Watch, and news that others are helping stem the tide of fiends in Duskwood is welcome news indeed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][157] = {title = "Deliver the Thread", objective = "Bring the Ghost Hair Thread to Abercrombie, in his shack north of the Raven Hill Cemetery.", description = "Here is your thread, <name>.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", progress = "I need to string the Ghost Hair Thread along my door and my windows to keep out unwanted spirits.  Did you get it for me?", completion = "Delightful!  This will do splendidly...\n\nHere, good &lt;name&gt;, take this as payment for your honorable deed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][158] = {title = "Zombie Juice", objective = "Speak with Tavernkeep Smitts.", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, <name>.  These nights get cold, and I need that drink to put fire in my veins again!", progress = nil, completion = "You need some Zombie Juice, do you?  Hmm...that's some strong stuff - I don't usually get requests for it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][159] = {title = "Juice Delivery", objective = "Bring the Zombie Juice to Abercrombie at his shack.", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", progress = "I need that Zombie Juice to keep me warm on these cold, dark nights.  Did you get it for me?", completion = "A thousand thanks, &lt;name&gt;.  You warm an old man's heart with your foolish-...I mean...with your kindness!\n\nHere you are, friend.  Take this as a token of my gratitude.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][160] = {title = "Note to the Mayor", objective = "Bring Abercrombie's Letter to Ello Ebonlocke, Mayor of Darkshire.", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", progress = "Abercrombie...?  I don't know a person of that name.  You say you have a letter for me from this Abercrombie fellow?\n\nWell let's have it then...", completion = "&lt;Ello looks at the letter...&gt;\n\nWhat language is this?  It looks ancient...I can't read it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][161] = {title = "A Dark Threat Looms", objective = "Chief Engineer Hinderweir wants you to take the strange smelling powder to Ashlan Stonesmirk, the explosives expert in Dun Modr.", description = "If my suspicions are correct, this is some type of explosive powder.  This must be analyzed by an explosives expert so we know just what we're dealing with here.  Ashlan Stonesmirk was assigned to the regiment guarding Dun Modr and the Thandol Span.  I need you to make a grave and perilous journey, <name>.\n\nTravel through the Algaz Gate, follow the road through the Wetlands and seek out Stonesmirk in Dun Modr.  Heed my advice: stick to the roads and stop for nothing!", progress = "You say somethin', sonny?  Can't hear a bloody thing besides the ringin' in me ears.  Say, what's that you got there?", completion = "Ah, well Ol' Hinderweir is wise to be worried.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][162] = {title = "Rise of the Silithid", objective = "Take the Insect Analysis Report to Gracina Spiritmight in Darnassus.", description = "I urge you to take this report to someone who has working knowledge in this kind of thing.\n\nI know this night elf scholar named Gracina Spiritmight.  She's spent a lot of time studying life forms that are unique to the ecology of Azeroth; she's a historian to boot!  If you want someone to help figure out what exactly this threat is, and more importantly how to stop it, give her the report.  We'll need the help.\n\nLast I heard, she was residing in the Temple of the Moon, located in Darnassus.", progress = "Peace and tranquility be on to you, stranger.  Why have you sought me out this day?", completion = "This report... we night elves know of the terror mentioned here.  Fizzledowser was wise to send this, and you, to me.\n\nThese creatures will consume the Tanaris desert rapidly; they are nothing short of one of the greatest menaces we all will ever face.  Familiarize yourself with this name, &lt;name&gt;: silithid.  The insects mentioned here are the silithid, and they are the tools of one of the greatest threats that both the Horde and Alliance face.\n\nIf only we were smart enough to see that before.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][163] = {title = "Raven Hill", objective = "Find out what is haunting Raven Hill.", description = "Something's amiss at Raven Hill, <name>. Calor swears that someone--or something--is haunting the buildings there. Two nights running he's noticed the shadows moving, and the third before that he says he saw light in one of the windows.\n\nIf, as you say, you care about the safety of Duskwood, find out what monster haunts in Raven Hill.", progress = nil, completion = "No! Please don't kill me! It's just me... Jitters!! They're everywhere... I can't escape them! Monsters in Raven Hill? N-n-n-o... couldn't be. Only harmless Jitters.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][164] = {title = "Deliveries to Sven", objective = "Deliver the supplies to Sven.", description = "Do you know Sven? Now, there is a man who does the work of the Light! He and his followers keep a camp at the northwestern edge of Duskwood.\n\nUnfortunately, because they are so few, they cannot even spare a man to fetch supplies from town. Will you deliver these supplies to him?", progress = "You look a sturdy type, <class>. Have you come to join our fight?", completion = "These supplies will be most useful. The aid of the Carevin family is always appreciated. Here is a little something for your trouble.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][165] = {title = "The Hermit", objective = "Check on the old man in the shack near Raven Hill cemetery.", description = "There was an old man who used to come into town to buy supplies rather frequently, but I haven't seen him for quite some time now. He lives out in a shack overlooking Raven Hill cemetery, if I remember correctly. Perhaps you should go see if something is amiss.", progress = nil, completion = "Elaine Carevin? Hehe, oh yes... of course, the Carevins.\n\nNo, nothing's wrong but it is hard for me to go into town now. The roads are dangerous and I'm not getting any younger. Maybe you can do an old man some favors?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][166] = {title = "The Defias Brotherhood", objective = "Kill Edwin VanCleef and bring his head to Gryan Stoutmantle.", description = "There is but one task left for you to complete.  Edwin VanCleef must be assassinated.  While it saddens me to condemn any man to a death sentence, it is for the greater good of the people of Westfall that VanCleef is laid to rest once and for all.  Bring me the villain's head once the deed is done.", progress = "How goes the hunt for Edwin VanCleef?", completion = "&lt;name&gt;, your bravery is remarkable.  The People's Militia thanks you for your service to the people of Westfall.  With VanCleef dead, this marks the beginning of the end for the Defias Brotherhood.  Hopefully some day soon peace will once again grace the plains of this fair land.\n\nI salute you, Sir!", rewards = "You will be able to choose one of these rewards:\n\nChausses of WestfallTunic of WestfallStaff of Westfall\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][167] = {title = "Oh Brother. . .", objective = "Bring Foreman Thistlenettle's Explorers' League Badge to Wilder Thistlenettle in Stormwind.", description = "We were deep in a vast mine in Westfall, hidden beneath a barn in Moonbrook. No clue where these stinkin' thieving types came from. Anyway, the mine tunnel collapsed on us. I got out but the others... well... the others haven't been heard from.\n\nYou look like you might have better luck in there. If you could look for my brother, I'd be thankful.  He always carried his Explorers' League Badge. If you can't find him, that badge would at least give me some peace of mind.", progress = "Did you find any sign of my brother?  Is there any hope after all this time?", completion = "My suspicions were correct.  My poor brother.... Well, thank you for bringing some conclusion to this mystery, even if the conclusion was grim.", rewards = "You will receive:\n\nMiner's Revenge"}
MultiLanguageQuestData['en'][168] = {title = "Collecting Memories", objective = "Retrieve 4 Miners' Union Cards and return them to Wilder Thistlenettle in Stormwind.", description = "Many of my friends perished that horrible day when the mine tunnel caved in.  If your adventures happen to bring you into that wing of the mine in Moonbrook, please keep an eye out for any sign which might identify them.  If you come across any of their Miners' Union Cards, bring them back to me and I'll make sure their families get some resolution from this horrible accident.", progress = "Were you able to retrieve any of my old co-worker's Miners' Union Cards?", completion = "Thank you for collecting these, &lt;name&gt;.  Your efforts will help bring peace to the dead in the wake of this tragedy.  I will see to it that the families are notified.", rewards = "You will be able to choose one of these rewards:\n\nTunneler's BootsDusty Mining Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][169] = {title = "Wanted: Gath'Ilzogg", objective = "Kill Gath'Ilzogg and bring his head to Magistrate Solomon in Lakeshire for the reward.", description = "Wanted! Gath'Ilzogg, Leader of the Blackrock attacks on Stonewatch Keep and raids against the township of Lakeshire. \n\nGath'Ilzogg is extremely dangerous.  He is reportedly holed up in the recently conquered keep plotting the Blackrock clan's further crimes against humanity.  The orc infestation must be quelled at all costs.  A gracious reward will be given to whatever brave soul can deliver the head of Gath'Ilzogg to Magistrate Solomon.", progress = "What do you have there, <race>?", completion = "Fantastic work, &lt;name&gt;!  Gath'Ilzogg led those brutes into battle, killing many innocent humans.  Vindication is ours.  This is the first step in reclaiming the keep for the kingdom of Stormwind!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][170] = {title = "A New Threat", objective = "Balir Frosthammer wants you to kill 6 Rockjaw Troggs and 6 Burly Rockjaw Troggs.", description = "I hope you're here to lend us a hand, <class>. After the last trogg attack, we could use all the help we can get.\n\nI hear the buggers have been popping up all across the lands, and it seems Coldridge Valley is no exception. They've been spotted all over the hills to the southeast and near the frozen lake.\n\nAnd that's not all, just a few nights ago, they attacked and overran our camp to the west! \n\nWe're a bit shorthanded here, <lad/lass>, and we need strong arms to help drive the troggs back.", progress = "Tenacious little buggers, aren't they?", completion = "If the problems we've had here are indicative of what is happening elsewhere in our lands, by Magni's beard, we have some troubles ahead of us! I can only hope that the king and Senate are taking steps to deal with the threat the troggs pose.", rewards = "You will be able to choose one of these rewards:\n\nBear ShawlRustic BeltSnow Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][171] = {title = "A Warden of the Alliance", objective = "Return your ward to the Stormwind orphanage by handing in the Human Orphan Whistle to Orphan Matron Nightingale in the Cathedral District.", description = "You have been so very kind to me, <name>.  I never dreamed that I'd have so much fun during Children's Week.  Thank you.  I don't wanna be sad about what's happened to me and all - my folks always told me to rise above anything bad that happens.  You know, when I grow up I wanna be a hero... just like you.\n\nI'm sad to say this, but it's time for me to go home.  Let's go back and I'll tell the matron what an awesome person you are!", progress = "It is a pleasure to see you again, <name>.  Have you attended to the duties you've volunteered for during Children's Week?", completion = "May the heavens bless you, &lt;name&gt;.  You've done more for Randis than most would ever think of doing for him.  Thank you - you're a shining star in the skies of the Alliance.\n\nPlease - if you can spare the time, come back and visit us.  I know that Randis would like that, as would I.\n\nRandis had so much fun with you, &lt;name&gt;.  He wanted to give you one of his favorite pets to remember him by.", rewards = "You will be able to choose one of these rewards:\n\nPiglet's CollarRat CageTurtle BoxCurmudgeon's Payoff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][172] = {title = "Children's Week", objective = "Use the Orcish Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item: \n", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means <name> - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", progress = nil, completion = "Zug zug!  My name is Grunth, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  My matron says that they died with honor in battle.  I'm happy to meet you.\n\nI hope we'll do plenty of things together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch.", rewards = nil}
MultiLanguageQuestData['en'][173] = {title = "Worgen in the Woods", objective = "Kill 6 Nightbane Shadow Weaver worgen for Calor in Darkshire.", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane Shadow Weaver worgen in Brightwood Grove--bright, hah!--and the Rotting Orchard.", progress = "<name>, how fares the hunt?", completion = "Impressive, &lt;name&gt;. It would seem that you are capable enough to handle yourself. Perhaps a more suitable challenge could be found for one of your abilities.\n\nIt is curious though... The worgen seemed to just appear out of thin air. But then, with all the other strange creatures that have moved across our borders, I suppose it's only one of many concerns.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][174] = {title = "Look To The Stars", objective = "Viktori Prism'Antras of Darkshire wants you to bring him a bronze tube.", description = "My Gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars.  A truth exists, beyond magic, that can explain the strange transformation in the forest.\n\nBring to me a bronze tube made by a skilled engineer.  That is the first step, according to Cog's blueprint.", progress = "Have you found a skilled engineer to create a bronze tube yet?", completion = "This is perfect, &lt;name&gt;.  The first step is complete!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][175] = {title = "Look To The Stars", objective = "Locate Mary and persuade her to give up a reflective surface for Viktori's project.", description = "According to Cog's blueprint, what I need now is a way to reflect light.  I remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", progress = nil, completion = "Why yes, I used to own a looking glass.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][176] = {title = "Wanted: \"Hogger\"", objective = "Slay the gnoll Hogger and bring his Huge Gnoll Claw to Marshal Dughan.", description = "Wanted: Hogger\n\nA huge gnoll, Hogger, is prowling the woods in southwestern Elwynn.  He has overpowered all attempts at his capture.\n\nThe Stormwind Army has placed a generous bounty on the Gnoll.  To earn the reward, bounty hunters should bring proof of Hogger's demise to Marshal Dughan in Goldshire.", progress = "Yes, Hogger has been a real pain for me and my men.  You have something to report about the beast?", completion = "Hah!  Well done!  I was starting to think no one would take down that monster!\n\nHere you are, &lt;name&gt;.  And thanks - that Gnoll was giving me a headache the size of Blackrock Spire!", rewards = "You will be able to choose one of these rewards:\n\nFootman TunicStormwind Guard LeggingsBalanced Fighting Stick\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][177] = {title = "Look To The Stars", objective = "Retrieve Blind Mary's Looking Glass from the Insane Ghoul and give it to Viktori in Darkshire.", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an Insane Ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", progress = "I showed Cog the beginnings of our star-viewing machine.  He was impressed.  Did you happen to find a reflective device?", completion = "Most superb!  This will work perfectly.  Many thanks!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][178] = {title = "Theocritus' Retrieval", objective = "Bring the Faded Shadowhide Pendant to Theocritus the Mage.", description = "<You hear a disembodied voice...>\n\nDo not be alarmed.  I am Theocritus, High Mage of Tower Azora in Elwynn Forest.  The pendant you are holding is a method of communication between the Shadowhide Gnolls and their master, Morganth.\n\nThrough months of research, I believe I too can communicate through these pendants.  If you can hear this message, then my spell was a success.\n\nBring me this pendant and I will reward you for the service.", progress = "I spoke to you through a pendant, you say?  Hmm...give it to me, so that I might study it.", completion = "You have my gratitude, &lt;name&gt;.  I sent that message to the Shadowhide Pendants weeks ago and had believed it a failure.  But it seems the spell did reach at least some pendants, after a significant delay.\n\nIn time I hope to learn how to send an attack through the pendants, to immobilize any Shadowhide Gnolls who wear them.\n\nBut before that is possible, I'm afraid that much more research is required.", rewards = "You will receive:\n\nRestoring Balm"}
MultiLanguageQuestData['en'][179] = {title = "Dwarven Outfitters", objective = "Sten Stoutarm would like 8 pieces of Tough Wolf Meat.", description = "What do we have here? You look as though you might need something to keep your hands warm, hm?\n\nI'll tell you what would help: a pair of nice, warm gloves. And, being the kind soul that I am, I'd be more than happy to provide you with a suitable pair. I've one condition, however.\n\nI need you to go get me some wolf meat. Nice arrangement, hm? You bring me some wolf meat, and I'll make sure you don't lose any digits to frostbite. Well, what do you say?", progress = "Wolves giving you a bit of trouble? You'd do well to avoid the fangs and claws and other sharp bits, yes?", completion = "Ah! Wonderful. The wolf meat should do nicely. Oh, don't worry, &lt;name&gt;, I wouldn't forget my part of the bargain. Here, one of these should fit you.", rewards = "You will be able to choose one of these rewards:\n\nRabbit Handler GlovesWolf Handler GlovesBoar Handler Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][180] = {title = "Wanted: Lieutenant Fangore", objective = "Kill Lieutenant Fangore and return to Magistrate Solomon in Lakeshire with his paw.", description = "Wanted: Lieutenant Fangore\n\nKnown leader of the Shadowhide Gnoll Clan, working under the enemy of the Township and Kingdom, Morganth.  By mandate of Magistrate Solomon, this vile betrayer of Stormwind is wanted dead.  Show his paw to the Magistrate as proof of his death.", progress = "What news do you bring before the Court?", completion = "So the evil Lieutenant Fangore is dead?  Good riddance to that foul creature.  You are very brave, &lt;class&gt;.  The Township of Lakeshire thanks you for your aid.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][181] = {title = "Look To The Stars", objective = "Locate Zzarc'Vul in the southern ogre mound in Duskwood and return his monocle to Viktori in Darkshire.", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", progress = "Were you able to convince Zzarc'Vul to lend us his monocle for our experiment?", completion = "At last!  The stargazing device is complete!  Thank you, &lt;name&gt;.  Now I can continue my research. . .", rewards = "You will be able to choose one of these rewards:\n\nZodiac GlovesBelt of the Stars\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][182] = {title = "The Troll Cave", objective = "Grelin Whitebeard would like you to kill 14 Frostmane Troll Whelps.", description = "My brother Senir and I were sent to different parts of Dun Morogh to investigate the threat posed by the trolls. The Senate has its hands full with the troggs, so they've no need for further annoyances.\n\nFrom what I've seen, the trolls aren't well situated here in Coldridge Valley--mostly the southern cave. I'd say that the army will not be necessary. A few strong arms should be more than enough.\n\nPerhaps you'd like to assist in this endeavor? I have the authority to offer compensation for your help.", progress = "From what I've learned, these trolls hail from the Frostmane clan. I'm afraid I don't know much else about them that would be of any use to you, <name>.", completion = "Argh! Those Light-blasted trolls!\n\n&lt;He takes a few breaths and seems to settle down... a bit.&gt;\n\nA group of them came in the night and stole my journal! I knew better than to trust that good-for-nothing appr...", rewards = "You will be able to choose one of these rewards:\n\nAnvilmar Hand AxeAnvilmar HammerAnvilmar KnifeAnvilmar Sledge\n\nYou will also receive:\n\nHealing Herb"}
MultiLanguageQuestData['en'][183] = {title = "The Boar Hunter", objective = "Talin Keeneye would like you to kill 12 Small Crag Boars.", description = "Nothing like a day of boar hunting, eh?\n\nThough, here in Coldridge Valley, there are so many boars it almost takes the fun out of it. No need to get them charging. They're all angry and ready without any help. In fact, recently, there've been so many boars in the area, it's become dangerous for me to do my daily hunting.\n\nLong story short, if you could help me kill some of the boars, I would appreciate it.", progress = "How goes the hunt?", completion = "Excellent! I can go back to my... leisurely... hunting now. Thank you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nDwarven Cloth BritchesDwarven Leather Pants\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][184] = {title = "Furlbrow's Deed", objective = "Bring Furlbrow's Deed to Farmer Furlbrow.", description = "This is the deed to an expanse of farmlands within Westfall.  It is signed by a Theodore Furlbrow and cosigned by his wife, Verna.  And on the back of the deed are hastily scrawled words:\n\n\"We leaned on Furlbrow and got his deed.  Thought it might be handy if you wanted to forge one of these for your own place.\n\nThe Furlbrows won't give us trouble.  Last I saw them they were on their way out of Westfall, stuck with a broken wagon.\"\n\nYou think the Furlbrows might want their deed back...", progress = "You have the deed to my farm??  That's good news!  Some ruffians stole it days ago... I thought it was gone for good!\n\nPlease, let me have it.  We're on our way out of Westfall and ain't coming back any time soon, but if we do then we'll need those papers...", completion = "Loads of thanks, &lt;name&gt;!  As I was saying, these parts aren't fit for honest folk anymore, but if things get better, then this deed will let us reclaim our land.\n\nI don't have much to offer you, but here -- take this.", rewards = "You will receive:\n\nRipe WatermelonSmall Pumpkin"}
MultiLanguageQuestData['en'][185] = {title = "Tiger Mastery", objective = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Young Stranglethorn Tigers.", description = "When I was but a young girl, my father trained me in the art of tiger hunting.\n\nYou'll find the young felines much easier to track and slay.  For this reason, we'll start you out easy.  One can often find young tigers near the expedition camp.\n\nTest your tracking skills and see if you can hunt some of the beasts down.", progress = "I don't feel confident in training you further, <name>, until you have proven yourself skilled in slaying the youngest of the tigers first.", completion = "Nicely done, &lt;name&gt;.  You are ready to move on.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][186] = {title = "Tiger Mastery", objective = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Stranglethorn Tigers.", description = "You are learning, <class>.  Let us test your skills with the mature cats now. Kill 10 Stranglethorn Tigers this time out.", progress = "If you strive for greater challenges you must first prove yourself with the task at hand.  Return to me after you've killed 10 Stranglethorn Tigers.", completion = "I am impressed, &lt;class&gt;.  You are progressing quite well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][187] = {title = "Tiger Mastery", objective = "Ajeck Rouack of Nesingwary's Expedition wants you to kill 10 Elder Stranglethorn Tigers.", description = "Now I'm going to up the stakes on you and truly test your skill.  Prove to me you can kill 10 Elder Stranglethorn Tigers.  If you can do that, you will be ready for your final challenge before I declare you a master tiger hunter in Master Nesingwary's presence.\n\nElder Stranglethorn Tigers are not only the most difficult to find, they are also the fiercest to defeat.", progress = "You must kill 10 Elder Stranglethorn Tigers before I give you the final challenge that will determine if you are a true tiger hunting master.", completion = "Most impressive.  I believe you are almost ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][188] = {title = "Tiger Mastery", objective = "Ajeck Rouack of Nesingwary's Expedition wants you to kill Sin'Dall and return with her paw.", description = "Here is the final challenge that I will put forth.  We've been tracking an elusive tiger for weeks.  We call the beast Sin'Dall.  See if you can do what no <race> has done before: hunt down and kill Sin'Dall.  Bring me her paw as proof of your accomplishment.\n\nTracking her down will be no easy task.", progress = "How goes the hunt for Sin'Dall?", completion = "Most impressive, I do say!  You are a true Master Tiger Hunter, &lt;name&gt;!", rewards = "You will receive:\n\nTiger Hunter Gloves"}
MultiLanguageQuestData['en'][189] = {title = "Bloodscalp Ears", objective = "Acquire 15 Bloodscalp Ears and return them to Kebok in Booty Bay.", description = "Damn trolls! They've been killing off our agents in the jungle! I've already lost a good number of my best guards to skirmishes with them. The costs are piling up! How will I explain this to Baron Revilgaz?\n\nDecisive action... Think, Kebok... you weren't assigned to the post you have today for sitting around... I've got it! You... <name>, is it? You'll help me, won't you? There's money to be had!\n\nHere's the deal... you bring me the ears of fifteen Bloodscalp Trolls, and I'll compensate you well.", progress = "You've had success I hope? All over the place, those trolls. Filthy devils.\n\nOh yes, that reminds me! Be sure to tell your friends, yes? We could use much assistance!", completion = "Oh excellent, excellent. That'll help a little, for the present...\n\n&lt;He trails off, grumbling about profit margins and costs...&gt;\n\nWhat? You're still here? Reward? Oh, right... of course, here, take this... it should be more than enough.", rewards = "You will receive:\n\nGoblin Fishing Pole"}
MultiLanguageQuestData['en'][190] = {title = "Panther Mastery", objective = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Young Panthers.", description = "If you want to be a part of the hunt with this crack group under Hemet Jr.'s leadership, you're going to need to prove yourself an able panther hunter.  We'll start you out easy -- don't you worry.  Let's see you kill 10 young panthers to start.\n\nTracking them down is only half the challenge...", progress = "A true panther hunter would be out in the fields, trying to stalk his prey. Show some commitment to your goal, <class>, and get back out there.", completion = "Off to a good start, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][191] = {title = "Panther Mastery", objective = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Panthers.", description = "Now you're ready to turn it up a notch.  If you want to prove yourself worthy of socializing with the likes of these big game hunters, you'll need to prove that you can kill 10 panthers.\n\nThose big boys are tougher.  They're not as easy as the young ones you were killing earlier.", progress = "Go kill 10 panthers!  Show us what you've got!", completion = "Perfectly executed, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][192] = {title = "Panther Mastery", objective = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to kill 10 Shadowmaw Panthers.", description = "Now the hard part.  A true panther hunter can show skill by dropping Shadowmaw Panthers, the deadliest in Stranglethorn.  Prove to us that you can slay 10 of these beasts.\n\nIf you think they are hard to track, wait until you attempt to slay one....", progress = "What are you doing here, <name>!  You should be crawling through the brush, trying to kill 10 Shadowmaw Panthers.  I thought you fancied yourself a big game <class>?", completion = "You've done well, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][193] = {title = "Panther Mastery", objective = "Sir S. J. Erlgadin of Nesingwary's Expedition wants you to bring him the Fang of Bhag'thera.", description = "You've almost proven yourself to be a master hunter of panthers.  A panther by the name of Bhag'thera has been prowling the jungle.  So far he's eluded our party.  See if you can use your skills to kill the great Bhag'thera.\n\nBring me the Fang of Bhag'thera and you'll have earned my respect!", progress = "Bhag'thera can prove to be an elusive beast.  How fares the hunt?", completion = "So the great Bhag'thera is dead!  Cheers to you, &lt;name&gt;.  You are a mighty &lt;class&gt; indeed!", rewards = "You will receive:\n\nPanther Hunter Leggings"}
MultiLanguageQuestData['en'][194] = {title = "Raptor Mastery", objective = "Hemet Nesingwary Jr. wants you to kill 10 Stranglethorn Raptors.", description = "So you think your hunting skills are in tip-top shape?  I can put them to the test in a jiffy.  Head out into that jungle and kill 10 Stranglethorn Raptors.  We'll see just how much of a big game hunter you are.\n\nAnd no, I won't tell you where you can find them!  Locating the beasts is half the challenge.", progress = "I never met a hunter who got any kills by standing around the campfire.  Were you planning on killing those Stranglethorn Raptors or were you hoping they would die of old age?", completion = "Nicely done, old chap!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][195] = {title = "Raptor Mastery", objective = "Hemet Nesingwary Jr. wants you to kill 10 Lashtail Raptors.", description = "Now let's step up the challenge and see if you're up to it.  Venture into the jungle and bag yourself 10 of those bloody Lashtail Raptors.  Let's see what you've got!", progress = "A true hunter sets his focus on his prey.  You, my friend, seem more concerned with chit-chatting around the campfire.  Now get out there and kill 10 Lashtails before I go and rid the entire bloody jungle of them in one hunt.", completion = "Now that's how you get a trophy or two over the ol' hearth!  Nice killing, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][196] = {title = "Raptor Mastery", objective = "Hemet Nesingwary Jr. wants you to kill 10 Jungle Stalkers.", description = "Let's see how you handle this next challenge.  There is a cagey breed of raptor out there.  We call them Jungle Stalkers.  They are far more difficult to track down and kill than the other breeds you've been trying your luck at.  Kill 10 Jungle Stalkers and I'll tip you off to the best hunting yet.", progress = "Bah!  What are you doing standing around, <name>!  A true big game hunter never gives up once his prey is in his sights.  Those Jungle Stalkers aren't going to come running up to this campfire and throw themselves in it.  Silly bloke.", completion = "Ho ho!! We have ourselves a true raptor slayer!  Nicely done, old chap!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][197] = {title = "Raptor Mastery", objective = "Hemet Nesingwary Jr. wants you to kill Tethis, an elusive, dangerous raptor in Stranglethorn.", description = "Because you proved yourself to be such a go-getter in the jungle, let me tell you about a ferocious raptor that even I have failed to kill.  Ajeck here calls this wily raptor Tethis.\n\nIf you want to prove yourself a true master, kill Tethis and bring me his talon.  It would be a feat that no other big game hunter has accomplished.", progress = "How goes the hunt for Tethis?  Tracked her all the way back to camp, did you?", completion = "Master &lt;name&gt;, the raptor slayer!\n\nHas a nice ring to it, eh?", rewards = "You will receive:\n\nRaptor Hunter Tunic"}
MultiLanguageQuestData['en'][198] = {title = "Supplies to Private Thorsen", objective = "Deliver the Miscellaneous Goblin Supplies to Private Thorsen.", description = "Hmm. Yes, I do have something you could do, actually. Lieutenant Doren and his followers up in the north need their regular supplies from us.\n\nThey haven't been delivered, and with the trolls attacking, I'll need someone to do it. Doren's camp lies northwest of the road at the entrance to Stranglethorn from Duskwood. Give the supplies to Private Thorsen, if he's not in the camp, then he'll be patrolling south of it. He'll take care of them.\n\nMind you, if you fail, you'll owe me restitution.", progress = "Yes? What do you want? Oh, supplies from the goblins. Strange seeing a <race> delivering them, usually they send their own. No matter... you didn't touch them did you? Good good... we wouldn't want anything to happen to our mines, oh no.", completion = "These land mines will help us defend ourselves from that animal Kurzen and his men. Thank you for bringing them. If you need further work, I can probably find something for you to do. And you won't have to deal with those goblins, hm?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][199] = {title = "A Dark Threat Looms", objective = "Return to Chief Engineer Hinderweir and show him the clue that you discovered.", description = "You take a sample of the strange smelling powder.", progress = "Did you happen to discover any clues, <name>?", completion = "This is an alarming discovery, to say the least!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][200] = {title = "Bookie Herod", objective = "Find Bookie Herod's Records.", description = "If Kurzen knows Thorsen's secret, then we have a spy in our midst.  We must determine how the secret was leaked!\n\nThorsen's contact within Kurzen's camp was Bookie Herod.  Herod is Kurzen's logistics officer and knows everything about the running of Kurzen's Compound.  If you can get Herod's notes or records, maybe we can find out how Thorsen was discovered.\n\nWhen we were still with Kurzen, Bookie's office was on the top floor of the camp's only two-story house.  His records are probably still there.", progress = nil, completion = "These are Bookie Herod's notes and records.\n\nAmong them are: a list of supplies within the camp, material requests from Colonel Kurzen, and various letters and correspondences.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][201] = {title = "Investigate the Camp", objective = "Find the hunters' camp and report its location to Krazek in Booty Bay.", description = "I've gotten reports of a group of hunters that have set up camp upriver of the Venture Company mining camp on Lake Nazferiti.  Now, normally I wouldn't care, but improbably, I heard that Hemet Nesingwary Jr. was one of the hunters there.  He's certainly well-connected, if you catch my meaning, and you never can be too safe.\n\nWhy don't you go check out the camp, <name>, see what they're about?", progress = nil, completion = "Hmmm, so my information was correct, as usual. Interesting. Well, I don't suppose they pose any sort of threat of interference with our operation, but perhaps they have a need for some of our excellent manufactured products. Hmmm...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][202] = {title = "Colonel Kurzen", objective = "Kill 6 Kurzen Elite, 4 Kurzen Subchiefs, and bring Kurzen's Head to Lieutenant Doren at the Rebel Camp.", description = "You have proven yourself time and again, and your resourcefulness seems to rival even that of Kurzen himself.  You may be the salvation of our band of rebels...if you can pit yourself against Kurzen and prevail!\n\nHe commands his men from deep within the Stockpile.  You must enter that cave, brave through his defenders, and face Kurzen and his leaders.\n\nFarewell, <name>.  My hope, and the fate of my men, go with you.", progress = "Dare I hope that Kurzen and his defenders are dead, <name>?", completion = "I dared not believe the reports, but you bring us proof that...Kurzen and his leaders are defeated.  You have saved us!\n\nThese jungles are filled with menaces of all types, but none had the cruel intellect of Kurzen.  We may all breathe easier now that he is gone.", rewards = "You will receive:\n\nShrapnel Blaster"}
MultiLanguageQuestData['en'][203] = {title = "The Second Rebellion", objective = "Kill 15 Kurzen Jungle Fighters.\n\nReturn to Sergeant Yohwa at the Rebel Camp.", description = "We're fighting a losing battle with Colonel Kurzen.  Not only is he a brilliant tactician, he outnumbers us at least 10 to 1!  To survive, we need to use his own, covert tactics against him.\n\nEnter his camp to the east and kill his men.  Lots of them.  And get out before reinforcements can close on you.", progress = "I hope you've been successful in your hunting, <name>.  We won't last long against him without your help.", completion = "Well done.  The loss of those Jungle Fighters will relieve some of the pressure on our camp.\n\nBut now that you've had a taste of the forces we're up against, do you still want to throw your lot in with us??", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][204] = {title = "Bad Medicine", objective = "Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa at the Rebel Camp.", description = "To have a chance against Kurzen, we need his healing support neutralized.  He has gathered a large number of Medicine Men who heal his forces with Jungle Remedies and poison our fighters with Venom Fern Extracts.\n\nWe need those remedies and extracts for our own.  Search the Kurzen Compound - his Medicine Men and Jungle fighers will have the remedies, and the extracts are probably stowed in some of the camp's supply boxes.", progress = "I'm waiting on those remedies and that extract, <name>.", completion = "Well done, &lt;name&gt;.  These remedies will keep more of us alive and in fighting shape.  And the extracts will help us create our own remedies.", rewards = "You will be able to choose one of these rewards:\n\nPalm Frond MantleGuerrilla Cleaver\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][205] = {title = "Troll Witchery", objective = "Bring 4 Skullsplitter Fetishes to Brother Nimetz at the Rebel Camp.", description = "While I study those legends you acquired, gather for me implements of evil troll magic.  Enter the territory of the Skullsplitter trolls, a second tribe to the distant south, and acquire Skullsplitter Fetishes from their Witchdoctors and Mystics.", progress = "Do you have those fetishes, <name>?  They might hold the secret to Kurzen's degradation...I must know!", completion = "Thank you.  I will study these fetishes and see if they hold the secret of Kurzen's fall into evil.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][206] = {title = "Mai'Zoth", objective = "Bring the Mind's Eye to Brother Nimetz at the Rebel Camp.", description = "Kurzen may be dead, but...that which drove him to evil still lives!  Through my studies I have discovered this: An Ogre Mage - Mai'Zoth - dwells in an Ogre Mound within the eastern mountains of Stranglethorn.  He is rumored to employ mind-controlling magic, and I am positive that he corrupted Kurzen.\n\nIf Mai'Zoth is allowed to live, then his evil may influence others, and may even cause another Kurzen to surface.\n\nKill him, and bring me his Mind's Eye, the artifact he uses to corrupt others.", progress = "I give you my blessing.  Mai'Zoth's strength is matched only by his evil.", completion = "Aha!  You've done it!  You are a great force for good, &lt;name&gt;, and may your strength never fade!\n\nI will study this Mind's Eye and determine if it may be used for good.  If not...then it must be destroyed.", rewards = "You will receive:\n\nTranquil Orb"}
MultiLanguageQuestData['en'][207] = {title = "Kurzen's Mystery", objective = "Find the 4 tablets and bring their legends back to Brother Nimetz.", description = "Colonel Kurzen was once a great, noble man - I must find what caused his fall into depravity!  He may be under the sway of troll magic.  To confirm this, I must study some of their legends.\n\nThere are 4 tablets hidden within the troll ruins of Stranglethorn.  I must see what is written on these tablets!  Transcribe their markings and bring the transcriptions back to me.\n\nThe first tablet is in the Bal'lal Ruins, the second is in the Vile Reef, and the third and fourth are in the Ruins of Zul'Kunda.", progress = "<name>!  Do you have the troll legends?  I must know their secrets!", completion = "Thank you, &lt;name&gt;.  I will study these legends to see if there is some link between the trolls and the evil that has possessed Colonel Kurzen.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][208] = {title = "Big Game Hunter", objective = "Hemet Nesingwary Jr. wants you to bring him the head of King Bangalash, the great white tiger.", description = "<name>, you are a hunter worthy of our company.  From the battlefields of Lordaeron to the deepest jungle, I have rarely witnessed such prowess with weaponry as you have demonstrated.\n\nYou have killed the ferocious Sin'Dall, the elusive Bag'thera and the treacherous Tethis.  But the true prize is the head of King Bangalash.  That white tiger is the reason I am here.  I've had my sights on him for quite some time now.  Kill King Bangalash and your hunting prowess is proven to be second to none.", progress = "I see you're back, old bloke.  King Bangalash has caused me to come crawling back to camp many times.  Hang in there.", completion = "Bloody well done!  Right-o!  Congratulations, &lt;name&gt;, for succeeding where others have failed.\n\nI am honored to count you as a comrade of our great hunting party here.  No one will ever doubt your expertise in hunting and tracking!\n\nCheers to you, I say!  Cheers!", rewards = "You will be able to choose one of these rewards:\n\nMaster Hunter's BowMaster Hunter's Rifle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][209] = {title = "Skullsplitter Tusks", objective = "Acquire 18 Skullsplitter Tusks and return them to Kebok.", description = "It's expensive and hard to kill enough tigers to support the export of tiger fangs to the islands in the South Seas. Luckily, we've developed a technique that allows us to take mundane horn-like objects and turn them into undetectable forgeries.\n\nThe closest match we've found, amazingly, are the tusks of the Skullsplitter trolls.\n\nHey, before you say anything, what the buyer doesn't know doesn't hurt them, am I right? Bring me a large number of them so we can get to work on the monthly shipment!", progress = "Tough buggers, aren't they? Well, have you had any luck? Sorry to seem impatient, but this has been a huge thorn in my side! Well?", completion = "Ah, good work, good work! Ugh, though you could have done a better job cleaning off the-- Well, no matter, no matter! My thanks to you, &lt;name&gt;, our operation will no doubt see increased output and productivity thanks to your help! Good good, now, onto other matters...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][210] = {title = "Krazek's Cookery", objective = "Bring Krazek's Crock Pot to Krazek the goblin.", description = "I do most of the cooking at the camp.  And it used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant in Booty Bay.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.", progress = "Hello!  You brought me something?", completion = "Oh I see, it's a Krazek's Crock Pot!  An ingenious piece of work, but it can break a spring or throw a gear now and then.  Let me see what's wrong with this one...\n\nAha!  Its steam charger is rusted out, it has a cracked knuckle-gasket and its fobulator is missing teeth.  I'm surprised the pot could even boil a turnip in this state!\n\nCan I fix it?  Of course I can fix it!\n\nBut there's a price.  Oh yes, there is always a price...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][211] = {title = "Alas, Andorhal", objective = "Bring Araj's Phylactery Shard to Commander Ashlam Valorfist at Chillwind Camp, Western Plaguelands.", description = "Alas, the time to attack Andorhal and drive out the lich that controls it is upon us!\n\nInside the ruins of the city is where the lich - Araj the Summoner - holds dominion.  He is guarded by numerous Scourge surrounding the remains of city's center, and his personal retinue of guardians attached to him directly is formidable.  You will need numerous allies to even stand a chance of facing him successfully.\n\nDestroy Araj, <name>, and bring me a shard from his phylactery as proof!", progress = "Your task has been given to you, <name>.  Do you have a shard from the lich's phylactery as proof of the task being accomplished?", completion = "You've done it!  Araj... the lich is finally defeated!\n\nYou've done a tremendous service to the Alliance on this day, &lt;name&gt;.  Your bravery and perseverance are a testament to what it means to be a true hero.  Please - accept this as a token for all to see and know that you have delivered the Alliance a victory for the ages!", rewards = "You will receive:\n\nMark of Resolution"}
MultiLanguageQuestData['en'][212] = {title = "A Meal Served Cold", objective = "Kill a Cold Eye Basilisk, get a Chilled Basilisk Haunch, and return it to Angus Stern in the Blue Recluse.", description = "One of my most famous dishes is Chilled Basilisk in Lime Vinaigrette.  But the problem is... the meat is impossible to keep fresh, and I must serve the dish tonight for a noble's birthday!\n\nSo if you can bring me a Chilled Basilisk Haunch from a freshly-killed Cold Eye Basilisk, quickly, then I will owe you a king's feast!\n\nCold Eye Basilisks are known to roam along the beach dunes of northwestern Stranglethorn, so you have much traveling to do.  And be swift!", progress = "<name>!  Do you have that haunch?  I must begin preparing it soon, or the banquet will be ruined!", completion = "Ah, this will do nicely!  Many, many thanks!\n\nNow if you'll excuse me, I must get the haunch chopped, marinated and garnished for the banquet.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][213] = {title = "Hostile Takeover", objective = "Retrieve 8 Tumbled Crystals and return them to Kebok in Booty Bay.", description = "He's done it this time! Bad enough that Gelriz's muscling out the moguls who were appointed by the trade princes, now he tries to cut in on the most notorious pirate!\n\nRevilgaz won't have it, and he's told me to take care of the problem in my own way.\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti are deeply interested in those strange blue crystals they have been finding in the mines. Bring me samples of the stone from their geologists, I don't care what you have to do to get them.", progress = "I need those stones, <name>. By whatever means necessary! Just do it, don't give me the details!\n\nIt's about results, <name>, nothing more, nothing less.", completion = "Fascinating. That the crystals have been tumbled using this process can only indicate that they are planning to use them as some sort of fuel or other catalyst. I don't know much more than that. Samples will have to be dispatched to Head Chemist Gigglefont.", rewards = "You will receive:\n\nGemmed Gloves"}
MultiLanguageQuestData['en'][214] = {title = "Red Silk Bandanas", objective = "Scout Riell at the Sentinel Hill Tower wants you to bring her 10 Red Silk Bandanas.", description = "It's no secret that the trademark of the Defias Gang is their Red Bandanas.  But we've learned that the material from which these bandanas are made signifies the member's rank.\n\nThat being said, I want you to eliminate as many high ranking Defias members as you can.  The highest ranking members will undoubtedly be found in VanCleef's secret hideout.  When you're done bring me 10 Red Silk Bandanas as proof of their deaths and I will reward you.  Good luck, <name>.", progress = "Have you been reclaiming our land from the Defias gang?  If so show me 10 Red Silk Bandanas as proof.", completion = "Well done, &lt;name&gt;!  On behalf of The People's Militia I salute you for your efforts.  Soon we will return this land to the people with help from brave souls like you.", rewards = "You will be able to choose one of these rewards:\n\nSolid ShortbladeScrimshaw DaggerPiercing Axe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][215] = {title = "Jungle Secrets", objective = "Speak with Lieutenant Doren at the Rebel Camp.", description = "Thank you for saving me, <name>.  I know how this looks, but...allow me to explain.\n\nI was charged by Lieutenant Doren to re-enlist with Kurzen's men, so that I might spy on them and bring sorely needed intelligence to the rebels.  You saw here what I had thought would be my chance to infiltrate Kurzen's Compound.  I was wrong, and again, thanks for saving me.\n\nThis was a top secret mission, so you must tell no one.  But if you speak with Doren he will explain.", progress = nil, completion = "Yes, what Thorsen told you is true.  You must be discrete with this.  At one time, we rebels were fiercely loyal to Colonel Kurzen.  But such was Kurzen's corruption, our passion twisted into rage.   If it was made known that Private Thorsen has had recent dealings with Kurzen's men, then one night he would find himself with a slit throat.\n\nTo my knowledge, only Sergeant Yohwa, Thorsen and I were privy to Thorsen's mission.  But there must be another.  A traitor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][216] = {title = "Between a Rock and a Thistlefur", objective = "Take down 8 Thistlefur Avengers and 8 Thistlefur Shaman; most are located east of Zoram Strand in Thistlefur Village. Once completed, return to Karang Amakkar at Zoram'gar Outpost, Ashenvale.", description = "The Thistlefur furbolgs are threatening our expansion!  Thistlefur Village to our east blocks the way between us here and the Splintertree Post.  It's a path that would circumvent the village of Astranaar; without it, we give the Alliance an extra expansion path.\n\n<name>, we must not allow... an expansion path gap!\n\nProceed to Thistlefur Village and thin out the furbolgs.  You will be given compensation for this task, but more importantly you will be doing your duty for the Horde!", progress = "Have you taken the fight to the Thistlefur?  With a clear path between our bases, our chances of claiming the whole of Ashenvale increase dramatically.", completion = "Well done &lt;class&gt;, well done!  I will continue to send forces to thin out the furbolg, but I can at least count on a different path that will be free of Alliance entanglements.  The Horde conquest of Ashenvale is now in full swing!\n\nYou've earned your pay this day, hero.  I salute you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][217] = {title = "In Defense of the King's Lands", objective = "Kill the Trogg leader, Grawmug, and his two guards, Gnasher and Brawler then report back to Captain Rugelfuss in the southern guard tower.", description = "<name>, our scouts have identified the leader of this recent Trogg incursion.  It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug.  Grawmug is heavily guarded, however.  Two of his most elite guards, Gnasher and Brawler, never leave his side.\n\nIf you feel yourself worthy, <name>, I want you to lead the assassination mission on Grawmug and his two thugs.  With the Trogg leadership dead, we just might stand a chance at pushing these beasts back into the ground.", progress = "Grawmug and his two guards, Gnasher and Brawler, are still alive.  Your mission is not complete until all 3 have been brought to death.  The Dwarven empire is counting on you, <name>.", completion = "Most excellent, &lt;name&gt;!  You have brought hope to Loch Modan.  With Grawmug dead, we stand a better chance of seeing the Troggs eliminated from the land.", rewards = "You will be able to choose one of these rewards:\n\nFrontier BritchesDwarven DefenderLucky Trousers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][218] = {title = "The Stolen Journal", objective = "Grelin Whitebeard wants you to kill Grik'nir the Cold, and retrieve his journal.", description = "My journal! They took it away to the cave. The one that had it... It was a big brute with some odd markings on his skin and face. I didn't get a much better look than that.\n\nYou've had some luck with the trolls, maybe you could go get it back for me?", progress = "<name>! Any luck?", completion = "Wonderful, &lt;name&gt;! Many thanks for retrieving my notebook. Well, it would seem that the troll situation here in Coldridge Valley is under control and not much cause for worry.\n\nAfter I put the finishing touches on my report, I'll need someone to courier it to my brother Senir.", rewards = "You will be able to choose one of these rewards:\n\nDwarven Kite ShieldSmooth Walking Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][219] = {title = "Missing In Action", objective = "Protect Corporal Keeshan on the journey back to Redridge.", description = "At last, friends of the Alliance!\n\nHelp... please... \n\nThe last thing I remember these foul Orcs overpowered our regiment.  Most the men were killed. I took a strong blow to the head and everything went black. Now I am held captive in this cave.  Help me, I am hurt badly.\n\nI'll need help getting back to town... please... you're my last hope...", progress = "Yes?", completion = "You have served the Kingdom well, &lt;class&gt;.  Thank you for assisting Corporal Keeshan with his escape from those dreaded Blackrock Orcs.  You shall be rewarded for your brave acts this day.", rewards = "You will be able to choose one of these rewards:\n\nRobe of SolomonDeputy Chain CoatBone-studded Leather\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][220] = {title = "Call of Water", objective = "Bring the Vial of Purest Water to Islen Waterseer in the Barrens.", description = "Islen will have one more task for you before rewarding you with your next totem. The vial of water I've given you is necessary for whatever that task is.\n\nGo now and find her. We shall meet again some day.", progress = "Hello again, <name>. You're looking well.\n\nWhat brings you back to me so soon?", completion = "Ah, a vial of water created and blessed by Brine, and gathered by you, no less.\n\nThe liquid in this vial will be key in creating a sapta for you, but also used in one other task.\n\nThe sapta I create for you should be used to see the water spirits at the shrine in Silverpine Forest, south of the Undercity. The remaining drops, well, the remaining drops I will tell you about if you feel you are ready.\n\nAre you prepared for one more journey, &lt;name&gt;?", rewards = "You will receive:\n\nWater Sapta"}
MultiLanguageQuestData['en'][221] = {title = "Worgen in the Woods", objective = "Kill 12 Nightbane Dark Runner worgen for Calor in Darkshire.", description = "You might have noticed some larger worgen wandering around with the Shadow Weavers in the woods? From what we can tell, these Dark Runners make up the bulk of the worgen numbers.\n\nOn my rangings, I've also noticed that they have overrun the Rotting Orchard southwest of town. These worgen are a bit tougher than the last you faced.\n\nBe on your guard.", progress = "Back so soon, <name>? I hope you haven't come to tell me you've given up.", completion = "You performed well against the Dark Runners, &lt;name&gt;. But it seems as though their numbers are inexhaustible. Every time we make progress, more spring up to refill their ranks.\n\nWhat is the evil power that draws them here? Why have they come to disturb our unhappy realm...\n\nI will put my faith in Master Carevin. No doubt he will get to the bottom of the problem.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][222] = {title = "Worgen in the Woods", objective = "Kill 8 Nightbane Vile Fang and 8 Nightbane Tainted One worgen for Calor in Darkshire.", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", progress = "Intimidating beasts aren't they? But have no fear, <name>, those who stand for the Light will never fall!", completion = "&lt;name&gt;, to be honest with you, I did not believe that you would get this far, but you are clearly a &lt;class&gt; to be reckoned with. In fact, if you wish to formally join Master Carevin's struggle, I will gladly write for you a letter of recommendation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][223] = {title = "Worgen in the Woods", objective = "Bring Calor's note to Jonathan Carevin.", description = "Here you go, <name>. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", progress = "Yes, what is it? Make it quick, I've pressing matters to attend to.", completion = "Excuse me for my cold reception, &lt;name&gt;, but as I'm sure you can tell, I am an extremely busy man. I see that you have impressed Calor--and I assure you, that is no small feat--and that he has given his recommendation.\n\nThere are unsavory types afoot, &lt;name&gt;, and we can use the help of all who have proven themselves. We battle against demons, the undead, and those who would provide them aid. Be vigilant, be wary, and trust none who would not give aid to our cause.\n\nGlory under the Light.", rewards = "You will be able to choose one of these rewards:\n\nCloak of the FaithShield of the Faith\n\nYou will also receive:\n\nConsecrated Wand"}
MultiLanguageQuestData['en'][224] = {title = "In Defense of the King's Lands", objective = "Mountaineer Cobbleflint of the southern guard tower wants you to kill 10 Stonesplinter Troggs and 10 Stonesplinter Scouts.", description = "We need to protect the Loch, <name>!  With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front.  Troggs are tunneling up from every crevice!  The Trogg infestation poses the largest threat to Ironforge.  These disgusting mutants must be destroyed.\n\nWe need you, brave adventurer, to venture forth and lay waste to the Trogg threat.  Slay 10 Stonesplinter Troggs and 10 Stonesplinter Scouts and report back.", progress = "Loch Modan is under siege, <name>!  We need every able-bodied member of the Alliance to aid our cause.  Have you killed 10 Stonesplinter Troggs and 10 Stonesplinter Scouts yet?", completion = "Well done, &lt;name&gt;!  You demonstrated uncanny courage on the battlefield.  Our war against the Troggs will be won with efforts such as yours.  You have served King Magni well.\n\nIf you fancy yourself well-suited for this kind of adventuring, I suggest you speak with Mountaineer Gravelgaw.  The Captain has him assigned to a rough patrol that I am sure he can use some help with.  Check with Gravelgaw just inside the tower.", rewards = "You will receive:\n\nDalaran Sharp"}
MultiLanguageQuestData['en'][225] = {title = "The Weathered Grave", objective = "Speak with Sirra Von'Indi in Darkshire.", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", progress = nil, completion = "Morgan Ladimore?\n\nAhh, yes, of course. His was a long and sorrowful tale. I knew him, well, before he left for the war, but that was the last time I saw him. A noble and good man, he was, but he suffered a bad end.\n\nHere, I should have something here that can tell the tale better than my own recollections...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][226] = {title = "Wolves at Our Heels", objective = "Kill 12 Starving Dire Wolves and 8 Rabid Dire Wolves, then return to Lars at Sven's Camp on the western border of Duskwood.", description = "Sven and I have dangerous days ahead of us, what with the Necromancer to the east and all.  And out here alone as we are, we have to hunt for our own food.  It seems every time I'm heading back to camp with some meat on me, starving or rabid dire wolves come out of the forest wanting a bite.  It goes without saying, living out here is dangerous work!\n\nBut if you can rid us of some of those wolves, we'd have an easier time of it.  They mostly prowl north and east of here, near the river.", progress = "You still hunting wolves...?", completion = "Oh good.  You thinned out that pack quite a bit, and without those wolves nipping out our heels, we can bind our minds to dealing with Morbent Fel.\n\nHere, take some of these Flash Bundles.  They make them in town, and a lot have been donated to Sven to help with his cause.", rewards = "You will receive:\n\nFlash Bundle"}
MultiLanguageQuestData['en'][227] = {title = "Morgan Ladimore", objective = "Speak with Commander Althea Ebonlocke in Darkshire.", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", progress = nil, completion = "Morgan Ladimore? Never heard of...\n\nOh, you mean Mor'Ladim! I guess you haven't heard the story?\n\nWell, I'll give you the short version. A wandering undead calling itself Mor'Ladim has been wandering Duskwood. From what we've gathered, it appears to be the undead body of Morgan Ladimore, of whom you apparently know. He's been causing us all sorts of problems, attacking Watchmen on patrol and killing people.\n\n&lt;She sizes you up.&gt;\n\nYou seem to be capable enough, maybe you could lay him to rest.", rewards = "You will receive:\n\nThe Story of Morgan Ladimore"}
MultiLanguageQuestData['en'][228] = {title = "Mor'Ladim", objective = "Kill Mor'Ladim, then return his skull to Commander Althea Ebonlocke in Darkshire.", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", progress = "I don't blame you if you're having trouble with him, <name>. Some of our strongest Watchers have been lost to Mor'Ladim.", completion = "You killed him? That's no small accomplishment, &lt;name&gt;! On behalf of the people of Darkshire and the Night Watch, I thank you.\n\nAh... there is one small matter, however...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][229] = {title = "The Daughter Who Lived", objective = "Speak with Watcher Sarah Ladimore in Darkshire.", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", progress = nil, completion = "Yes? My father...\n\n&lt;Her eyes become downcast.&gt;\n\nI wish... there was something I could have done for him... If only I had talked to him before he...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][230] = {title = "Sven's Camp", objective = "Bring the Book from Sven's Farm to Sven.", description = "Digging through the mound, you find a small, dirt-stained book.\n\nThe book has no title, but...it has information Sven would like to know.", progress = "You found what??  Please, let me see it...", completion = "&lt;Sven reads the book's pages, then slams it shut.&gt;\n\nThat shadowy figure I saw was a witness to my family's death!  There are questions I'd like to ask that man...if only I knew who he was!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][231] = {title = "A Daughter's Love", objective = "Take Sarah Ladimore's ring to Morgan Ladimore's grave.", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, <name>.", progress = "Leave me be...", completion = "&lt;A ghostly voice sounds on the wind...&gt;\n\nThis is...? Sarah? Could it be she's still alive? The weight is removed from my shoulders...\n\n&lt;name&gt;. Take my sword, Archeus. As my soul is put to rest, I have no more need for it. It was forged to do good, and though I have proved myself unworthy to hold it, perhaps you will carry on the Light through it.\n\nLys, my love...", rewards = "You will receive:\n\nArcheus"}
MultiLanguageQuestData['en'][232] = {title = "Errand for Apothecary Zinge", objective = "Take the purchase order to Alessandro Luca in the Undercity.", description = "The Royal Apothecary Society needs your assistance.  Listen closely, and both of us may profit from my plan.\n\nApothecary Keever in the next room may be... touched... but his research does potentially bear fruit if it were pursued by a clever researcher.  Fortunately, I am such a researcher.  I want you to take this purchase order to Alessandro Luca, the proprietor of Blue Moon Odds and Ends; he'll give you a testing kit.  When you have it, bring it back to me and I'll outline your task in detail.", progress = "Yes, and what may I assist you with?  Are you here on business for the Royal Apothecary Society, or have you arrived here merely to brighten my day?", completion = "Ah, Zinge needs a kit, does she?  It saddens me that Zinge does not choose to grace myself with her sweet presence.\n\nVery well, let me procure a kit for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][233] = {title = "Coldridge Valley Mail Delivery", objective = "Deliver the stack of letters to Talin Keeneye.", description = "Hm, I don't suppose you'd be willing to do a favor for me, <lad/lass>? A stack of letters came through the pass today, but I don't have the time to send them along.\n\nThey're all addressed to Talin Keeneye. You can find him to the west down the road. He's set up camp next to the frozen lake.\n\nWhat do you say?", progress = "Yes? Do you have something for me?", completion = "Thank you, I've been waiting for these letters for quite some time...\n\nUnfortunately, these letters aren't all for me. This one is addressed to Grelin Whitebeard. He's not too far away if you'd like to deliver it to him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][234] = {title = "Coldridge Valley Mail Delivery", objective = "Deliver the letter to Grelin Whitebeard.", description = "If I remember correctly, Grelin's camp is down the road to the southeast. No doubt he'll be eager to get his mail.", progress = "Is there something I can help you with?", completion = "Ahh, excellent. It's been a while since I received word from Ironforge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][235] = {title = "The Ashenvale Hunt", objective = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", progress = nil, completion = "Welcome to the new frontier, &lt;name&gt;.  Ashenvale is a land of opportunity, one where a young &lt;class&gt; like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][237] = {title = "In Defense of the King's Lands", objective = "Mountaineer Gravelgaw in the southern guard tower wants you to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers and report back to him.", description = "Mountaineer Cobbleflint had nothing but good things to say about you, <race>.  For that reason I am going to entrust upon you a mission of utmost importance.  We need to keep pressure on the invading Trogg forces until our Dwarven brethren return from the Alliance front.\n\nSet forth into the southern hills and kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Your attacks will buy us some time.  Report back when your mission is complete.", progress = "We need more time, <race>.  Your orders are to kill 10 Stonesplinter Skullthumpers and 10 Stonesplinter Seers.  Keep the enemy under pressure until we are granted reinforcements.  This is no time for idle behavior.", completion = "You accomplished your mission well, &lt;race&gt;.  The King himself would be proud.\n\nThe reinforcements promised to us never showed, however.  Apparently the Alliance front is a sea of crimson from the blood of our fallen brethren.  The news of the losses leaves a bitter taste in one's mouth.  But we must not let their deaths go for naught.  We must rally in these grim times and bring glory back to the Alliance.\n\nSpeak with Mountaineer Wallbang for reassignment.  You're needed now more than ever.", rewards = "You will receive:\n\nLesser Healing Potion"}
MultiLanguageQuestData['en'][238] = {title = "Errand for Apothecary Zinge", objective = "Bring the Field Sampling Kit to Apothecary Zinge in the Undercity.", description = "The kit is ready, <name>.  No doubt that Apothecary Zinge will want this as soon as possible.  Take it to her without delay, and let her know that I will add the cost of the kit to the Society's tab.  Also, please extend to her my warmest salutations.\n\nWell, don't just stand there.  Such is the life of a simple courier, yes?", progress = "Yes, I think Luca is as disturbing as you do.  It matters not - hand me the field sampling kit.  I will need to make some adjustments to it in order to survey for the proper base materials.\n\nYou have the kit, don't you?", completion = "Good - it pleases me to be working with someone who takes pride in not wasting my time.\n\nAfter I make some adjustments to this kit, you'll be ready to head out into the field.  You'll be using it to collect some vital data to the task at hand.\n\nIt will take just a moment for me to finish the modifications.  While you are waiting, you should probably start thinking about what you'd like to bring to the desert with you.\n\nYes, I said the desert.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][239] = {title = "Westbrook Garrison Needs Help!", objective = "Go to the Westbrook Garrison and speak with Deputy Rainer.", description = "The Garrison on our western border sends word of increasing gnoll and thief activity.  They're requesting we send more Stormwind soldiers... but we just don't have any to spare!\n\nIf you can help, we could use it.  Go and speak with Deputy Rainer at the Westbrook Garrison and see what he needs done.\n\nThe Garrison is down the road to the west.  After you cross the bridge over the small brook it will be to the right.", progress = nil, completion = "Marshall Dughan sent you, eh?  Well you're not from the army, but if Dughan sent you then that's good enough for me!\n\nOur situation is, to say the least, a stressed one.  I hope you can give us a hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][240] = {title = "Return to Jitters", objective = "Return to Jitters with the Dusky Crab Cakes.", description = "And here we are - \"Crab\" Cakes ala Grual!", progress = "<name>, you're here!  Do you have my food?!?", completion = "Aha!  Thank you, &lt;name&gt;.  Those really hit the spot!\n\nAnd here, please let me pay you for these!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][243] = {title = "Into the Field", objective = "Speak to Chief Engineer Bilgewhizzle in Gadgetzan about getting a power source for the testing kit.\n\nProvided item: \n", description = "You will be headed to the Tanaris desert, testing the tissue consistency of the basilisks, scorpids, and hyena native there.  Obtain tissue samples and use them with the testing kit in tow; expect a chunk of the samples to fail.  I need eight acceptable samples of each creature type.\n\nIn addition, the goblins of Gadgetzan have a power source that must be used with this kind of modified kit.  Speak to Chief Engineer Bilgewhizzle and acquire one for the kit.\n\nReturn to me only when you are successful.", progress = nil, completion = "Ah, our model 4711-FTZ power sources!  We normally use them to power the water wells, but THANKS TO THE VILE NOMADS, we have an over abundance of power sources right now.\n\nSure, I can get you a power source for whatever nefarious science experiment you think you're trying to hide from me.  It ain't gonna be free though, &lt;race&gt;.  Nothing's free in Gadgetzan.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][244] = {title = "Encroaching Gnolls", objective = "Report to Deputy Feldon.", description = "Hail, <class>.  I am charged to patrol this stretch of road.  Although the road is safe for now, I've seen gnoll encampments to the north and east of here.\n\nLakeshire must know of the gathering gnoll force!  Report to Deputy Feldon in Lakeshire and tell him of the gnolls.  Do this, and I'm sure Feldon will offer you a scout's wage.\n\nFeldon's usually inspecting the area south of the bridge to Lakeshire.", progress = nil, completion = "There are Redridge gnolls that close to Elwynn??  They may be poised to advance into our homeland.  Soon the people of Lakeshire may not be the only humans under siege!\n\nHere is your pay, though you bring us dire news.  And it comes at a bad time, for we are ill equipped to deal with it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][245] = {title = "Eight-Legged Menaces", objective = "Kill 15 Pygmy Venom Web Spiders, and then report back to Watcher Dodds in Duskwood.", description = "Hail, <class>. Perhaps you've seen those spiders that have taken over the western border? The eight-legged menaces are too much for us to handle, and the Commander hasn't enough manpower to spare so far from Darkshire.\n\nI hate to ask this of you, but you seem like you might be able to handle them. I can't promise you anything of great value, but I can reward you if you can help root out the filthy bugs.\n\nOh, and a word of advice, you'll want to avoid their venom if you can.", progress = nil, completion = "Ah! You're back. And not too much worse for wear, it'd seem. Of course, &lt;name&gt;, the Night Watch is grateful for your work, and I did promise you a reward, so here.", rewards = "You will receive:\n\nNight Watch Gauntlets"}
MultiLanguageQuestData['en'][246] = {title = "Assessing the Threat", objective = "Kill 10 Redridge Mongrels and 6 Redridge Poachers, then report back to Deputy Feldon in Lakeshire.", description = "We don't have men to spare, but something must be done about those gnolls you reported to me.\n\nScout southern Redridge for gnolls.  Harry them, kill those you can and report back to me with a count of their numbers and an assessment of the threat they present.  You may find those gnolls camped all along the southern road of Redridge.\n\nDo this for the Stormwind Army, <name>, and you will be rewarded.", progress = "Excuse me, <name>, but we have a lot to keep our hands tied here.  If you have nothing to report, then I must put my mind to other matters.", completion = "&lt;Deputy Feldon listens to your report...&gt;\n\nThere's a sizable force of gnolls encamped there, and from what you tell me they are tough ones.  It must not have been easy for you to gather this intelligence.\n\nHere you are, &lt;name&gt;.  We are grateful for your aid.\n\nAnd if you haven't already done so, speak with Marshal Marris and Magistrate Solomon within Lakeshire.  Our situation grows ever more desperate - those two will have need of you I'm sure.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][247] = {title = "The Hunt Completed", objective = "<name>, you have slain all three beasts that comprise the Ashenvale Hunt.  You have brought me adequate proof of their demise; there is no question of your strength and tenacity.  The blood of a hunter streaks through your veins, and you should be commended!\n\nPlease, accept this bauble as a sign of congratulations on your mighty deeds done in Ashenvale for the Horde today.  May your ancestors watch over you!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWildhunter Cloak"}
MultiLanguageQuestData['en'][248] = {title = "Looking Further", objective = "Climb the intact watch tower beside Stonewatch Keep.\n\nFind a suitable container to place the Glyph of Azora.", description = "I have been watching the Tower of Ilgalar, and can detect that Morganth is in conflict with the Orcs in Stonewatch Keep.  I do not know the reason behind their contention, but you may aid me in unraveling this mystery.\n\nTake another Glyph of Azora, then go to the top of the intact watch tower beside Stonewatch Keep.\n\nFind a suitable object on which to place the Glyph.  A chest or a jar -- some place where the glyph will not be noticed -- will suit my purpose.", progress = "This jar once held a foul-smelling liquor, but now lies empty and forgotten on a pair of barrels.", completion = "It is a suitable vessel for the Glyph of Azora, allowing Theocritus to delve into the minds within Stonewatch Keep.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][249] = {title = "Morganth", objective = "Defeat Morganth.\n\nBring his Pendant of Shadow to Theocritus at the Tower of Azora in Elwynn Forest.", description = "After much observation, I have discovered Morganth's plans.\n\nHe searches for the Scythe of Elune...and he may have found it!  If he has, then the Redridge Mountains, and the kingdom of Stormwind, will soon feel his dark might.\n\nI am not prepared to pit myself against Morganth, but I fear he must be dealt with now.  So you must enter the Tower of Ilgalar and face Morganth.\n\nDefeat him, and bring me his Pendant of Shadow.  Do this, and the kingdom will owe you much.", progress = "Hurry, <name>, before my fears of Morganth spreading his power are made real!", completion = "You have done well, &lt;name&gt;.  In defeating the warlock Morganth, Stormwind is saved from a grave peril.\n\nI offer you this reward most humbly.  And I would bid you peace, if these were peaceful times.\n\nBut instead, I will bid you luck with your trials, and victory in the conflicts ahead.", rewards = "You will receive:\n\nRose Mantle"}
MultiLanguageQuestData['en'][250] = {title = "A Dark Threat Looms", objective = "Investigate the area near the eastern ramp of the Dam and bring Chief Engineer Hinderweir a clue that might reveal what the Dark Iron Dwarves are up to.", description = "Thank the stars someone is concerned about the well-being of the Dam.  First the destruction of the Thandol Span and then the pillaging of Dun Modr!  I have no doubt that the Dam will be the target of the next Dark Iron threat.  Most of the security detail here was reassigned to the Alliance Front, including my top inspector.\n\nThat's why I need you, <name>.  I spotted some Dark Iron Sappers milling about the eastern ramp of the Dam.   Investigate the area and bring back a clue.", progress = nil, completion = "The suspicious looking barrel contains a strange smelling powder.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][251] = {title = "Translate Abercrombie's Note", objective = "Bring the Letter to Ello to Sirra Von'Indi.", description = "Take the note you gave me to Sirra Von'Indi.  He's very learned in languages and ancient arts - if anyone here can translate this message, it's he.", progress = "A note from Abercrombie the hermit, eh?  I don't know him, though if he lives out at the graveyard then I do know his brains have rotted out!", completion = "&lt;Sirra begins translating the note...&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][252] = {title = "Translation to Ello", objective = "Bring the Translated Letter to Lord Ello Ebonlocke", description = "Oh my!  If what is written on this note is true, then Abercrombie's done something...unspeakable.\n\nYou better bring the translated note back to Ello.\n\nAnd do so quickly, for I fear a doom already lumbers toward our town...", progress = "Ah, is the note translated?  Please, let me see it...", completion = "&lt;Ello reads the letter...and his face goes white.  He then looks at you...&gt;\n\nAlthough the aid you gave Abercrombie may have been motivated from kindness, your actions have doomed our town.\n\n&lt;Ello becomes lost in his thoughts...&gt;", rewards = "You will receive:\n\nTranslated Letter from The Embalmer"}
MultiLanguageQuestData['en'][253] = {title = "Bride of the Embalmer", objective = "Find Eliza's grave. Retrieve the Embalmer's Heart from her, then return to Ello Ebonlocke.", description = "The Embalmer is a name told in one of our children's stories.  He was a kindly alchemist, driven mad by the death of his wife, Eliza.  To restore her, he used dark magic to place his own heart within the bosom of his dead spouse.\n\nThis revived Eliza...but it cursed her with a hunger for human flesh, forcing the Embalmer to keep her buried.\n\nHis heart is his power.  Find his wife's grave, retrieve his heart, and bring it to me while it still beats.  Do this and his power will be broken.", progress = "Have you yet found Eliza's grave?  Do you have the Embalmer's heart?", completion = "You've done it!  The magic within his heart will be proof against the Embalmer's evil, and a powerful aegis over the town of Darkshire.\n\nYou have done a great thing for our people, &lt;name&gt;.  Your name will remain in our annals forever.", rewards = "You will receive:\n\nMantle of HonorCrest of Darkshire"}
MultiLanguageQuestData['en'][254] = {title = "Digging Through the Dirt", objective = "You dig through the semi-loose dirt over the grave...and find the remains of a coffin.\n\nWithin the coffin you can feel the vibrating scrapes of clawed fingers and the gnashing of rotted teeth...\n\nWill you open the coffin and retrieve the Embalmer's heart?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][255] = {title = "Mercenaries", objective = "Magistrate Bluntnose of Thelsamar has hired you to kill 4 Mo'grosh Ogres, 4 Mo'grosh Brutes and 4 Mo'grosh Enforcers.", description = "Two months just to hear from Ironforge that we'll be spared a handful of soldiers for our own defense, and another two months until they arrive! Bad enough that our town goes unprotected, but the excavation and the dam--the dam!--are open to attacks as well.\n\nI've no choice then, it seems. I'll need hired arms.\n\nHow about you? You seem a likely sort, <class>. A group of ogres has set up camp on the northeast of the lake. Perhaps you will be the one to remove the threat to our town?", progress = "Have you had any luck?", completion = "Ah, this is excellent news! Your efforts are greatly appreciated by myself and the people of Thelsamar. Better yet, if we can solve the ogre problem, we'll be able to shift our focus to those Light-burning troggs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][256] = {title = "WANTED: Chok'sul", objective = "Kill Chok'sul and bring his head to Magistrate Bluntnose of Thelsamar.", description = "By order of the Magistrate of Thelsamar:\n\nChok'sul, the ogre presumed to be the leader and coordinator of attacks against the town of Thelsamar, Stonewrought Dam, and the excavation site, is wanted dead through any means necessary.\n\nMonetary compensation will be provided when proof is brought to the Magistrate of Chok'sul's death.\n\nChok'sul was last seen at the ogre encampment in the northeastern part of Loch Modan.", progress = "Yes? Is there something I can do for you?", completion = "Yech! What is that thing? And why would you bring it...\n\nBloody--! Is it? Well, Light burn me, is that the head of that bloody ogre? This certainly is a catch then! Here, your reward and the thanks of myself and the people of Thelsamar.", rewards = "You will be able to choose one of these rewards:\n\nDurable Chain ShouldersKimbra Boots\n\nYou will also receive:\n\nMinor Channeling Ring"}
MultiLanguageQuestData['en'][257] = {title = "A Hunter's Boast", objective = "Kill 6 Mountain Buzzards and return to Daryl the Youngling in the Farstrider Lodge within 15 minutes.", description = "Think you can match wits with Daryl the Bold, huh? I should think not! Of course, you're more than welcome to try. Here's a challenge that should prove to be above your abilities, so don't feel too bad if you can't face up to it.\n\nA flock of buzzards has nested here in Loch Modan. Why don't you try to take down some of the beasts? Tell you what, if you meet my challenge in fifteen minutes, I'll give you my bow or gun.\n\n<He looks you over dismissively.>\n\nIt seems you haven't much to lose, anyways.", progress = "No luck? Don't feel too bad, Bolerroer...\n\nNot everyone can be me.", completion = "What? Success?\n\nTake it from me, Airtzama, you don't let it get to your head. I mean, any unshaven boy with a bow could have killed such... small specimens. And I hope you don't enjoy killing the buzzards so much, yes? We wouldn't want them to become extinct. \n\nWell, err... Never let it be said that Daryl the Bold would not hold to his word.", rewards = "You will be able to choose one of these rewards:\n\nDaryl's Hunting BowDaryl's Hunting Rifle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][258] = {title = "A Hunter's Challenge", objective = "Kill 5 Elder Mountain Boars and return to Daryl the Youngling in the Farstrider Lodge within 12 minutes.", description = "<name>ath, is it? I can tell you're bursting with pride over completing the first test, hm? As I told you before, it's no large feat.\n\nYou should try your hand at boar hunting. Trust me, this is no Coldridge Valley boar hunt, so you'd best have a care with them. I'll give you just twelve minutes this time.\n\nDon't feel bad if you fail. I'd give you the shirt off my back if you succeeded!\n\nHave I ever related to you the story of how I received my famous scar? No? It was two years ago...", progress = "It's only natural to feel sorry for yourself when shown up by someone so new to this world. You shouldn't feel bad, Airtzah.\n\nHm? Did I get your name wrong?", completion = "You seem a bit worse for wear. No doubt the boars gave you some trouble, hm? No worries, I will be discreet about your struggle, I can imagine how hard it must be for you without the accusations of wagging tongues.\n\nOh! You managed to kill the boars? I... well, that is... that is to say, I'm not surprised! Any child could have--bet?\n\nWhat bet?", rewards = "You will receive:\n\nFine Cloth ShirtDaryl's Shortsword"}
MultiLanguageQuestData['en'][261] = {title = "Down the Scarlet Path", objective = "Destroy 30 Undead Ravagers, then return to Brother Anton at Nijel's Point.", description = "I will be frank.  We are at war with the Scourge.  It is an evil that corrupts our people and infects our land.  It must be stopped before it overwhelms us and drags our world into shadow.  We of the Scarlet Crusade have sworn to fight the Scourge with body and soul.\n\nIf you are with us, then gather your courage and prove your allegiance--destroy the undead ravagers of Desolace, in the Valley of Bones to the south.\n\nDo this, and the Crusade will embrace you.", progress = "The Scourge grows in power with the passing of each day.  If you truly wish to halt its advances, then show me.", completion = "You have proven your resolve, and the Scarlet Crusade commends you.\n\nIf you do not shy from righteous slaughter, then perhaps your path lies with us...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][262] = {title = "The Shadowy Figure", objective = "Take the book you found at Sven's farm and show it to townsfolk in Darkshire.", description = "I must know who was that skulker in the shadows I saw the night my family was killed!\n\nPlease, <name>, you have shown your resourcefulness.  Please find that shadowy figure.  I must learn what secrets he holds!\n\nI do not have clues that you do not already know, but here - take the book you found at my farm.  Perhaps some of the townsfolk can link this book with its owner.", progress = "If you have something that belongs to the shadowy figure for whom you seek, then let me see it.  I may be able to divine something of its owner.", completion = "Hmm... Someone handled this book recently, someone who is driven by revenge.  But the impressions left on it, at least the impressions from the original owner, are faint.\n\nI can tell, however, that the original owner of this book is not a native of Darkshire.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][263] = {title = "In Defense of the King's Lands", objective = "Mountaineer Wallbang in the southern guard tower wants you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.", description = "The Mountaineers tell me you are quite brave and capable, <name>.  We need a <race> like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned <class> here, let's see what you can do.\n\nGo out and kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers.  Let's see if you live up to your reputation, Trogg-Slayer.", progress = "Back so soon?  In case I didn't make myself clear we need you to kill 10 Stonesplinter Shaman and 10 Stonesplinter Bonesnappers, <name>.  Now go get 'em, Trogg-Slayer!", completion = "I knew the second I laid eyes on you, &lt;name&gt;, that you would make Ironforge proud.  You have served King Magni well.  Now that you've proven yourself to be such a loyal aid to the Kingdom, perhaps you should talk with the Captain to see if he'll entrust you with a higher detail.\n\nI salute you, &lt;name&gt;.", rewards = "You will receive:\n\nCoarse Sharpening Stone"}
MultiLanguageQuestData['en'][264] = {title = "Until Death Do Us Part", objective = "Place Clarice's Pendant on Yuriv's Tomb in Silverpine.", description = "Filthy scum! Leaves me for his damn crusade. Because \"the Light is the most important thing we have against the threats the undead pose.\"\n\nWell, what about his children?! What about ME?! Night after night I sat patiently waiting for him... always second to his blasted duty!\n\nWell, witness what \"justice\" brings you, <name>! He's dead and I'm bearing the very thing he was trying to stop!\n\nTake this piece of junk and put it on his tomb at the Sepulcher. I want nothing to do with it anymore... or him!", progress = "The stone is cold to the touch,  but has obviously been abused. Trash litters the area; nicks and gashes decorate the relief atop the coffin; and the foliage around the grave has started to grow over the site.\n\nNo one cares for whoever is buried here, especially not any victims of the plague.", completion = "You place the worthless pendant on the grave, and the gemstone within the setting seems to dull noticeably.\n\nAs you stand to leave, you look down at the pendant; it lies lifelessly over the hands of the relief sculpted into the top of the coffin. Your thoughts are interrupted by a stiff, cool breeze passing over the Sepulcher. For a moment everything around you is silent.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][265] = {title = "The Shadowy Search Continues", objective = "See if other townsfolk have clues about the shadowy figure.", description = "Here is your book back, <name>, and I bid you fortune with your search.  If you ask others in town, perhaps they can offer you more clues.\n\nAnd here is one more for you - although the author of this book is a stranger to Darkshire, the book itself was purchased here.", progress = "Sometimes I'll sell blank books to scholars and mages, or to anyone who wants to keep a journal.\n\nI remember well everyone to whom I sold a book within the last few months...", completion = "Ah, yes.  I sold this book a month ago to a shady person.  He didn't tell me his name, but he was a nervous, jittery chap, always looking over his shoulder.\n\nI hope that helps you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][266] = {title = "Inquire at the Inn", objective = "Search the inn for clues about the shadowy figure.", description = "Here is your book, and good luck with your inquiries.\n\nYou might want to expand your search to the inn.  If the person whom you seek spent time in town, then chances are someone saw him there.", progress = "The Scarlet Raven doesn't see the business it used to, but we still do get travelers passing through.\n\nIf you can describe the person you're looking for, maybe I'll remember him.", completion = "Oh yeah, I remember this book.  Its owner rented a room for a few days, and spent his nights at the bar, writing.\n\nHe left town in a hurry, muttering about being hunted by...something.  Last I saw him he was heading west out of town, looking for a new spot to hide.\n\nThe first place he'd find to the west is Raven Hill...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][267] = {title = "The Trogg Threat", objective = "Bring 8 Trogg Stone Teeth to Captain Rugelfuss in the southern guard tower.", description = "<class>, you may or may not be aware of the Trogg threat looming over Dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we are left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the Gate here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned Troggs lurking in the hills.  If you're up to the task, wage an assault on the Troggs.  Bring me back 8 Trogg Stone Teeth as proof.", progress = "Do you have 8 Trogg Stone Teeth to show me?  If not, there is still work to be done, <name>.", completion = "I am quite impressed, &lt;name&gt;.  You have done the Dwarven race a great favor by defending our lands.  King Magni Bronzebeard himself would be proud!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][268] = {title = "Return to Sven", objective = "Return to Sven with Jitters' completed journal.", description = "The book you found was only half finished.  I had to leave it at Sven's farm when I fled there...\n\nHere.  Take my completed journal to Sven.  It describes more fully what happened at his farm.\n\nAlthough this journal has been my only company these past weeks, if giving it up keeps me from having to face Sven and his wrath, then I do it willingly!", progress = "Did you find who the Shadowy Figure was?", completion = "This journal explains much to me, and sets me on the path against the dark riders!  I have seen these riders in Duskwood, and have seen them speak with the wizard Morbent Fel, at the Forlorn Rowe.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][269] = {title = "Seeking Wisdom", objective = "Give Jitters' Completed Journal to Bishop Farthing in Stormwind.", description = "Go to the city of Stormwind and speak with Bishop Farthing in the Cathedral of Light.  Give him Jitters' journal and tell him you mean to face Morbent Fel.\n\nAlthough Stormwind has forsaken Darkshire, Farthing is a kind soul and very wise.  He may help you on your quest to save us.\n\nYour mission is perilous, but hurry, <name>.  With each passing hour, the shadows of Duskwood grow ever darker.", progress = "Rest, brother.  I can tell you have traveled far, and you bear a heavy burden.  Can you tell me what casts that dark shadow over you?", completion = "&lt;After reading the journal and hearing your intent...&gt;\n\nAn evil taint has gained a foothold within the already beleaguered Duskwood.  I thank the Light we have a hero such as you to face it.\n\nBut you must first prepare yourself for the coming trial...for the Necromancer Morbent Fel is immensely powerful, and has cast dark enchantments about himself to protect him from physical assaults.  If you are to defeat him, you will need a weapon that is proof against these protections.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][270] = {title = "The Doomed Fleet", objective = "Go to Menethil Harbor in the Wetlands, and speak with Glorin Steelbrow.", description = "Years ago, the Third Fleet of Kul'Tiras sunk along the coasts of The Wetlands, an expanse of marsh north of the Dwarven kingdom of Ironforge.  Aboard one ship was a load of Lightforge Iron.\n\nThis metal is precious to us, for items crafted from it strike with holy truth.  If you are to face Morbent Fel, then you will need such a weapon.\n\nGo to Menethil Harbor and speak with my dwarven colleague Glorin Steelbrow.  If that lost metal can be found, he'll know where to look.", progress = nil, completion = "Lightforge Iron is a precious metal, but it sounds like your quest is a dire one.  You've come a long way, Brother.  With luck, you might just find what you seek!\n\nAnd if you do get the iron, I know who can fashion it into a weapon against this Necromancer you speak of in Duskwood.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][271] = {title = "Vyrin's Revenge", objective = "Kill Ol' Sooty then show your handiwork to Daryl the Youngling at the Farstrider Lodge.", description = "I don't suppose you'd be interested in a little payback for His Boldness? Daryl does have some skill, it pains me to say.\n\nA year ago, a large bear had been the target of the Farstrider Lodge, but none of the hunters had any luck with him. So, Daryl thought he'd try his hand against him. All he had to show for his effort was that ugly scar over his eye.\n\nKill the bear, and I'm sure even Daryl would be speechless for once.\n\nThe bear, Ol' Sooty, can be found around his lair in the hills over Thelsamar.", progress = "Ah, <name>! Back so soon? No doubt you've been at the hunt again? Don't worry if you've had some setbacks, in the long run it will make you better!\n\n...You couldn't get much worse, anyway...", completion = "Er... what's this? A bear's head, by the looks at it.\n\n&lt;He runs a finger along his scar unconsciously.&gt;\n\nWell, that's quite an interesting kill you have yourself there. Couldn't be that bear from back then...\n\n&lt;He trails off then starts to visibly shake.&gt;\n\nOh, take that away take it away! Get that grisly thing out of here!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][272] = {title = "Trial of the Sea Lion", objective = "Find the Half Pendant of Aquatic Agility and the Half Pendant of Aquatic Endurance. Speak with the residents of Moonglade to learn clues as to where these items may be located.\n\nForm the Pendant of the Sea Lion from the two pendant halves. You need to be in proximity of the Shrine of Remulos to do this.\n\nBring the joined pendant to Dendrite Starblaze in the village of Nighthaven, Moonglade.", description = "For the second trial, you'll need the two halves that make the Pendant of the Sea Lion.  One half draws power from the agility of the sea lion aspect, gliding through water; the other draws power from the incredible endurance of the sea lion aspect.  Druids draw on both these traits equally to embody the aspect of their aquatic form.\n\nSpeak with the locals of Moonglade to learn where the parts may lie, and bring both here to join them together.  Once formed, take the pendant to Dendrite Starblaze.", progress = "Have you formed your pendant for me to inspect, <name>?  If you need help in locating the parts, try asking the local populace for information.  Not only will you find what you seek, but it will give you a reason to explore this wondrous and sacred glade.", completion = "You've completed the Trial of the Sea Lion, &lt;name&gt; - congratulations.\n\nEach task in acquiring the pendant shows that both agility and endurance are necessary to act in harmony with what you desire to do underwater.  Neither can exist without the other, and both cannot be done without your willingness to embrace the aspect of the sea lion.\n\nRemember these lessons well, and count on them once you have gained your aquatic form.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][273] = {title = "Resupplying the Excavation", objective = "Speak with Huldar.", description = "It's not too late though, you're welcome to go look for Huldar. He can't have made it very far, strong as they are, Miran and Saean can only move so fast laden down with those barrels.\n\nThey're taking the normal route to the site, leaving south out of town and following the curve of the Loch.\n\nShouldn't have a problem finding them unless they've already gotten there.", progress = nil, completion = "Hmph, it'll take more than a Dark Iron ambush to stop the deliveries!\n\nBut Saean... I would never have suspected him to be one of their sympathizers. We've been working with him for almost a year now... maybe I missed the signs.\n\nWell, I'll consider that later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][274] = {title = "A Dark Threat Looms", objective = "Ashlan Stonesmirk wants you to return to Chief Engineer Hinderweir and inform him of the new discovery.", description = "This ain't no ordinary blast powder.  Look at the tiny silver crystals.  And the distinct smell!  Why it's clear as daylight that this is Seaforium Powder.  Seaforium is harmless enough.  But once it's wet it could blow Ironforge out of the mountain.\n\nThe chemical reaction can be defused by mixing four components:  lurker venom, crushed Mo'Grosh crystal, a crocolisk tear and this disarming colloid.  Now tell Hinderweir before it's too late!", progress = "What is that you bring from Ashlan?", completion = "A disarming colloid? For Seaforium?  Oh heavens!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][275] = {title = "Blisters on The Land", objective = "Kill 8 Fen Creepers, then return to Rethiel the Greenwarden in the Wetlands.", description = "I do not know why, but a festering grows within the Wetlands.  Fen Creepers have risen.  They are diseased, fevered blisters on the land, and for the fever to break they must be dispatched and allowed to settle back into the marshes.\n\nThe Fen Creepers shamble amidst the waterways of the Wetlands.", progress = "The Wetlands still weep, and the Fen Creepers still rage.  Return to me when your task is done.", completion = "This land is soothed by your efforts, and for this I will grant you a boon.", rewards = "You will be able to choose one of these rewards:\n\nFen Keeper RobeForest ChainPhytoblade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][276] = {title = "Tramping Paws", objective = "Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden in the Wetlands.", description = "The Mosshide Gnolls have lived in the Wetlands peacefully for many years, but now grow in numbers.  Their feet stamp flat the fen's bushes and flowers, and their foul axes cut too much wood to fuel their fires.\n\nThey are no longer in balance with the land.  For the Wetlands to survive, the Gnolls must be reduced.\n\nKill 15 Mosshide Gnolls and 10 Mosshide Mongrels.  Hunt them to the south, near the Dwarven gate of Algaz.  After you do this, return to me.", progress = "Your task is still at hand, young <class>.", completion = "By reducing the Gnolls' number, you have tended to the health of the Wetlands.  Although my faith in your people has been taxed in the past, &lt;race&gt;, it may yet be restored.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][277] = {title = "Fire Taboo", objective = "Bring Rethiel the Greenwarden 9 Crude Flints.", description = "The Mosshides are cutting the trees of the Wetlands, using the trees' flesh to warm themselves with fire.  I will suffer this pain no longer!\n\nRid the Mosshides of their crude flints, the tools they use to make fire.  The flints are borne by all Mosshides except the smaller Mosshide gnolls and Mosshide mongrels.", progress = "Do you have the Gnolls' tools for fire?", completion = "... thank you.  I will smash these flints and cast them into the sea, so that they may never again be used to burn living wood.", rewards = "You will receive:\n\nSpongy Morel"}
MultiLanguageQuestData['en'][278] = {title = "A Dark Threat Looms", objective = "Chief Engineer Hinderweir wants you to gather Lurker Venom, a Mo'grosh Crystal, and a Crocolisk Tear.", description = "Begin collecting the disarming materials immediately, <name>.  Lurker Venom can be found on the indigenous spiders in Loch Modan.  Crocolisk tears are found here in the Loch as well.  But a Mo'Grosh crystal will be very difficult to procure.  The ogres to the northeast mine them but the crystals are a very rare commodity.\n\nWe need to be prepared to defuse a Dark Iron attack!  Return to me once you've collected the needed items and I will prepare the mixture.", progress = "Do you have the needed items?  Time is of the essence!!", completion = "Just in time, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][279] = {title = "Claws from the Deep", objective = "Kill 12 Bluegill Murlocs.\n\nSlay Gobbler and take his head.\n\nBring Gobbler's Head to Karl Boran in Menethil Harbor.", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", progress = "Our merchants will not be safe until we are rid of Gobbler and those Murlocs.", completion = "Ah, well done &lt;name&gt;.\n\nAccept this as payment for fulfillment of your contract with the Merchant Marines.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][280] = {title = "A Dark Threat Looms", objective = "Chief Engineer Hinderweir wants you to swim down to the base of the dam, locate the powder keg and stir in the Disarming Mixture to prevent an explosion.", description = "Earlier today I spotted some Dark Iron Insurgents swimming toward the Dam with a large keg.  No Mountaineers were on hand to stop them!  I'm afraid they've planted the Seaforium at the base of the Dam and it could blow at any minute!  Let me combine all these ingredients into the Disarming Mixture.  There we go.\n\nNow I need you to take this mixture and stir it into the keg before it's too late!  Hurry!", progress = "The top of the keg slowly twists off.", completion = "The keg fizzles slightly as the Disarming Mixture settles in.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][281] = {title = "Reclaiming Goods", objective = "Search the crates and barrels at the coastal Murloc camps.", description = "Not long ago a merchant vessel, the Blind Princess, was raided by Murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal Murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil Statuette and return it to me.", progress = nil, completion = "This crate is covered with clawed scratches, and the marks of water damage.  Prying it open reveals soggy and rotted straw, as if something of value was stored in the crate.  You search through the straw...\n\n...and find an armload of red-colored bottles.", rewards = "You will receive:\n\nHealing Potion"}
MultiLanguageQuestData['en'][282] = {title = "Senir's Observations", objective = "Speak with Mountaineer Thalos.", description = "I was planning on sending my apprentice to my brother Senir with my report, but I would feel much better were it placed in more... reliable hands. That is, of course, if you wouldn't mind?\n\nHmm... you'll have to take the tunnel to get to Kharanos.\n\nSpeak with Mountaineer Thalos before going through the tunnel. It's completely infested with troggs now.\n\nFollow the road back to Anvilmar, then keep heading east to the tunnel, Thalos is stationed nearby.", progress = "Hail! Have a care, <name>, the tunnel to Dun Morogh is infested with troggs and is not safe for travel.\n\nIf you haven't any pressing business in Dun Morogh, I'll have to ask you to remain in Anvilmar until the tunnel is safer.", completion = "Hm, well, if Whitebeard is sending you to Dun Morogh on important business, I can't very well stop you, can I?\n\nAt least let me provide you with some advice and directions.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][283] = {title = "A Dark Threat Looms", objective = "The Disarming Mixture seemed to take effect. Return to Chief Engineer Hinderweir to report the good news.", description = "The keg fizzles slightly.", progress = nil, completion = "Thank you so much, &lt;name&gt;!! You have saved the Stonewrought Dam!  Without your help, the Dark Iron terrorists would have surely seen to this mighty landmark's demise.  You have made the Kingdom and the Alliance proud, brave &lt;class&gt;.\n\nThe Dam is once again safe. . . for the time being at least. . . .", rewards = "You will be able to choose one of these rewards:\n\nDwarven Tree ChopperThornblade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][284] = {title = "The Search Continues", objective = "Search for the Menethil Statuette.", description = "You thoroughly search this cluster of Murloc hovels, and find no trace of the Menethil Statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", progress = nil, completion = "This barrel is largely untouched.  Prying it open...\n\n...you are assaulted by the pungent odor of cheese.  It's a little wet, but still tasty!", rewards = "You will receive:\n\nDwarven Mild"}
MultiLanguageQuestData['en'][285] = {title = "Search More Hovels", objective = "Continue searching the Murloc hovels for the Menethil Statuette.", description = "This grouping of Murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil Statuette!", progress = nil, completion = "This barrel is halfway buried amidst the mud and grass ...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][286] = {title = "Return the Statuette", objective = "Bring Karl Boran the Menethil Statuette.", description = "After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw.  It depicts a young, long-haired Paladin with hammer upraised.\n\nThis must be the Menethil Statuette!  You must now return it to Karl Boran in Menethil Harbor.", progress = "Do you have the statuette?", completion = "The captain of the Blind Princess will be relieved to hear this precious cargo has been recovered.  You have well earned this payment for services rendered.\n\nIt is good to see dependable folk like you, especially in trying times such as these.", rewards = "You will be able to choose one of these rewards:\n\nIcicle RodMariner Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][287] = {title = "Frostmane Hold", objective = "Explore Frostmane Hold, and kill 5 Frostmane Headhunters for Senir Whitebeard in Kharanos.", description = "I'm behind on my report, and could use your help, <name>. I just managed to find where the trolls are holed up, but I saw so many trolls, I was afraid to go in.\n\nHere's what I need... Go down to the cave, poke around inside, kill a few of the trolls, then come back here.\n\nTake the road north out of Kharanos, when you get to the bridge, follow the frozen river west until you reach Iceflow Lake. You'll find Brewnall Village on the west bank. The Hold is southwest of the village.", progress = "You can't find it? My directions were very clear! We don't have much time, you've got to hurry! Don't come back until you've found the cave.", completion = "Ah, &lt;name&gt;! I didn't think you'd have much trouble finding the place, my directions are excellent, you know...\n\nLet me just finish up my report then.\n\n\n\nThere! Well, haha, now this certainly is funny... I don't suppose, &lt;name&gt;, that you would mind doing one last favor for me?", rewards = "You will be able to choose one of these rewards:\n\nWarm Winter RobeStone Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][288] = {title = "The Third Fleet", objective = "Buy First Mate Fitzsimmons a Flagon of Mead.", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked  by Red Dragons.  Dragons controlled by Orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Oh, my head hammers and pounds!  I'll need a fresh drink if I'm to get a handle on this hangover and continue my tale.", progress = "Oh, I'm so very thirsty!  Won't you buy a drink for this poor, pathetic fool?", completion = "Ah!  That hits the spot, and loosens the tongue.  Thanks, mate!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][289] = {title = "The Cursed Crew", objective = "Kill 13 Cursed Sailors, 5 Cursed Marines and First Mate Snellig. Bring Snellig's Snuffbox to First Mate Fitzsimmons in Menethil Harbor.", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north.  But although I'm the only member of the fleet still breathing, I'm not the only one still walking about!  For on one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nBut if you can free some of my brothers, then perhaps you can break their curse.", progress = "In my dreams, I can sometimes hear the doomed moans of my brethren!  Please, good sir, free them from the bonds and quiet their cries.", completion = "My thanks to you, &lt;name&gt;.  And the gratitude of my cursed brethren goes to you as well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][290] = {title = "Lifting the Curse", objective = "Get the Intrepid Strongbox Key from Captain Halyndor.\n\nUse the key to open the Intrepid's Locked Strongbox.", description = "To break the curse and free all of my brethren, the...thing...stowed on my ship must be retrieved and cleansed!  I don't know what it was, but I do know that it was stored securely in the ship's strongbox, which Captain Halyndor lorded over.\n\nMy old captain is still in my dreams.  I know he walks my doomed ship, the Intrepid.  Get the key from him, and use it to open the Intrepid's strongbox.\n\nThen, after you have the cursed thing, bring it to the priest Glorin Steelbrow in town.", progress = "This chest is securely locked.", completion = "The key is rusted but it fits the lock neatly.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][291] = {title = "The Reports", objective = "Deliver Senir's report to Senator Barin Redstone in Ironforge.", description = "Excellent! Take my report to Senator Barin Redstone. He's a sour type, so don't let his less-than-sunny disposition get to you. He's in Ironforge, in the chamber where King Magni holds court.\n\nDon't know the way to Ironforge? Take the road out of Kharanos north, cross the bridge, then follow the road east--there are large banners flanking the road--up the mountainside.\n\nBy the way, if you might avoid mentioning how you assisted me? Can't let them think I'm not working hard out here, you know?", progress = "Hmm... it would seem that my guards are becoming less discriminatory with petitioners. Well, what do you want? Make it quick.", completion = "&lt;He quickly peruses the report.&gt;\n\nAuthority of the KING!? Has Magni taken complete leave of his senses! And that damnable Whitebeard... Taken matters into his own hands, has he? The Senate will not be pleased to hear about this, not one bit.\n\nWhat, are you still here? Go, before I call the guards!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][292] = {title = "The Eye of Paleth", objective = "Bring the Cursed Eye of Paleth to Glorin Steelbrow.", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light.  It is the treasure of which Fitzsimmons spoke: a Cursed Eye of Paleth.\n\nTake the Cursed Eye of Paleth to the dwarven priest Glorin Steelbrow, in Menethil Harbor.  Ask him how to remove the Eye's curse.", progress = "That drunk Fitzsimmons sent you to me?  Well, you can tell him I don't have any extra ale.  He's going to have to panhandle someone else!", completion = "An Eye of Paleth?  Amazing!  Hmm...there's something wrong with this one.  You found it on one of those shipwrecks?  Well that explains it!  But...I didn't know they had such an Eye on the Third Fleet...\n\nIt's no wonder Fitzsimmons was so spooked.  A Cursed Eye of Paleth is no cause for mirth.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][293] = {title = "Cleansing the Eye", objective = "Bring Archbishop Benedictus the Cursed Eye of Paleth. Benedictus is in the Cathedral of Light, in the city of Stormwind.", description = "I can't lift the curse from the Eye of Paleth.  The Eyes were crafted by Human Priests, so you'll have to go to Stormwind to find someone who can help you.  Speak with Archbishop Benedictus.  He is head of the Cathedral of Light in Stormwind.  He can help.\n\nI hope, for your sake.", progress = "What is that orb you have?  It looks...soiled.", completion = "An Eye of Paleth.  But this one has seen much sorrow...it must have been witness to a terrible, terrible tragedy.\n\nLet me cleanse it, for the Eyes were created to shine bright, and their powers can be quite dangerous if tainted like this one.", rewards = "You will receive:\n\nEye of Paleth"}
MultiLanguageQuestData['en'][294] = {title = "Ormer's Revenge", objective = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill 10 Mottled Screechers and 10 Mottled Raptors.", description = "The situation is severe, that much is for sure.  When we uncovered these bones it attracted the Raptors.  These filthy beasts killed my brethren and trapped me, Merrin and the poor Prospector up here.\n\nHelp clear the Wetlands of these Raptors, <name>.  Mottled Raptors and Mottled Screechers are just West of the bluff there.  Kill 10 of each, if you can.\n\nThat will be a good start to the vengeance I have planned for them.", progress = "Kill 10 Mottled Raptors and 10 Mottled Screechers, <name>.  My co-workers did not deserve the fate that was brought upon them.  It's time to even the score.", completion = "Killing is a dirty business, but you did your job well, &lt;name&gt;.  If I weren't obligated to stay with the Prospector and Merrin, I'd be down there shedding blood right along side you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][295] = {title = "Ormer's Revenge", objective = "Ormer Ironbraid wants you to kill 10 Mottled Scytheclaw raptors and 10 Mottled Razormaw raptors then return to him at the Whelgar Excavation Site.", description = "Now it's time to really make those dreaded Raptors regret their blood-thirst.  Just down below there are scores of Mottled Scytheclaws and Mottled Razormaws.  Make those rotten creatures pay by slaying 10 of each!", progress = "I want to make those Mottled Scytheclaws and Mottled Razormaws pay for what they did.  Have you killed 10 of each yet?", completion = "You did a bang-up job of clearing out those Raptors, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][296] = {title = "Ormer's Revenge", objective = "Ormer Ironbraid at the Whelgar Excavation Site wants you to kill Sarltooth and return to him with one of his talons once the task is fulfilled.", description = "While you were down there I happened to notice that one of those beasts stood out from the rest.  He was bigger and more menacing.  I bet he's the one who led the others here to cause the disruption to the dig site.\n\nI ask of you now one final task, <name>.  See to it that Sarltooth is brought to justice.  And considering the gravity of his crimes, justice in this case means death!  Bring me one of his talons as proof of his death.", progress = "Is Sarltooth dead? Have you redeemed the memory of the fallen?", completion = "Thank you, &lt;name&gt;.  Your efforts here will not be forgotten.  Many innocent Dwarves died at this site, simply doing their jobs.  The vengeance you delivered to those evil creatures should make them think twice before attacking King Magni's subjects ever again.", rewards = "You will be able to choose one of these rewards:\n\nRaptor's EndRaptorbane ArmorExcavation Rod\n\nYou will also receive:\n\nRecipe: Curiously Tasty Omelet"}
MultiLanguageQuestData['en'][297] = {title = "Gathering Idols", objective = "Bring Magmar Fellhew 8 Carved Stone Idols.", description = "Recently, just before the Troggs surfaced within the site, we had uncovered a large number of strange, carved idols.  But we didn't have the chance to study them, for soon after their discovery the Troggs chased us away from the ruins!  And those idols have a strange effect on the Troggs.  It makes them go berserk!\n\nBring me 8 idols - I want to study them, and I want them out of Trogg hands!  You can find the idols on the Troggs infesting the site.", progress = "Do you have those Idols?  We must study them and report our findings to Ironforge!", completion = "You got them!  Nicely done, &lt;name&gt;!\n\nAnd you don't look too worse for wear, even with those berserk Troggs about.  I'm going to keep my eye on you...you show some promise.", rewards = "You will be able to choose one of these rewards:\n\nDwarven FlamestickTrogg SlicerThelsamar Axe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][298] = {title = "Excavation Progress Report", objective = "Bring Ironband's Progress Report to Jern Hornhelm in Thelsamar.", description = "I need a progress report sent to Thelsamar - a progress report, and a restatement of my request for more blastpowder!  Here's the report.  Take it to Jern Hornhelm.  He's our local contact in Thelsamar.\n\nIt's not a difficult task, but it must be done.", progress = "Oh, a progress report from the site?  Very good!", completion = "Bah!  Ironband's having trouble with the Troggs.  I wonder if he wants that blastpowder to aid his digging, or to aid his efforts against the Trogg beasts...\n\nWell, either way it's powder well spent!\n\nBut what's strange is, I sent him plenty of blastpowder weeks ago.  I wonder where it went...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][299] = {title = "Uncovering the Past", objective = "Prospector Whelgar wants you to scour the excavation site in search of the 4 missing tablet fragments: Ados, Modr, Golm and Neru.", description = "Just before the invasion I uncovered a large tablet called the Goaz Stone.  The translated text breaks off in 4 places.  The text speaks of a \"divine plan\" and a \"doomed prophecy.\"\n\nI fear we are running out of time.  I am too old to go down and brave those beasts.  But you are strong.\n\nScour the excavation site and uncover the 4 missing tablet fragments: Ados, Modr, Golm and Neru.  Search for them in ancient artifacts or where the soil is loose.  Bring them to me so I can begin unlocking the mystery!", progress = "Have you uncovered the four fragments yet, <name>?   Ados, Modr, Golm and Neru...", completion = "Ah the Goaz Stone is complete!  Fine work, &lt;name&gt;.  Fine work indeed.  Now I can continue with the delicate translation of this Titan script.  I can make out new words already!  Hmm. . .it says here, \"Old Gods. . .Chained Beneath the Land.\"  This is the beginning of something epic.", rewards = "You will receive:\n\nSilk Mantle of Gamn"}
MultiLanguageQuestData['en'][301] = {title = "Report to Ironforge", objective = "Take Ironband's Progress Report to Prospector Stormpike.", description = "We'll need approval to get Ironband more blastpowder. You'll have to take his report to the Explorers' League headquarters in Ironforge.\n\nHere's the report. Give it to Prospector Stormpike, and don't forget to duck after you deliver it. Stormpike is hotheaded, and he won't be happy to hear of Ironband's slow progress at the site.\n\nYou'll find Stormpike in the Assembly of Explorers.", progress = "We Stormpikes don't like being bothered with trivial matters, <class>.  I hope you brought news worthy of my valuable attention.", completion = "Curse that Ironband!  I sent him a load of blastpowder weeks ago, but he's made no mention of it in this report.\n\nSo...where did the blastpowder go?!?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][302] = {title = "Powder to Ironband", objective = "Speak with Jern Hornhelm in Thelsamar.", description = "If Ironband still needs blastpowder, then by Magni he'll have it!  I sent the approval on ahead with a messenger to Jern Hornhelm in Thelsamar.  He'll prepare the powder and other supplies to take to Ironband.\n\nAnd one more thing: I want you to personally see that the shipment of powder reaches its destination.  The last one didn't, so keep your mind sharp and your eyes open.", progress = nil, completion = "What? Stormpike wants you to personally see the shipment to Ironband?\n\nI... suppose that's fine, the only problem is, I've already sent Huldar with the porters, Miran and Saean. You just missed them, they left just a short while ago.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][303] = {title = "The Dark Iron War", objective = "Motley Garmason at Dun Modr wants you to kill 10 Dark Iron Dwarves,  5 Dark Iron Tunnelers, 5 Dark Iron Saboteurs and 5 Dark Iron Demolitionists.", description = "War rages both home and abroad.  While mighty Dwarven soldiers give their lives in far off territories in the name of the Alliance, our own lands fall prey to the evil deeds of the Dark Iron Dwarves.  They laid waste to the Thandol Span.  Dun Modr fell soon after.\n\nWe need you to gather force and push the front back.  If you can kill 10 Dark Iron Dwarves, 5 Tunnelers, 5 Saboteurs and 5 Demolitionists, the reserve might arrive in time to finish the drive.\n\nNow make haste!", progress = "Roggo has been unable to contact the reserve forces.  We need offensive pressure on that Dark Iron encampment, <class>.  Now get back out there and serve your duty to King Magni!", completion = "You upheld your orders well, &lt;class&gt;.  You have proven yourself to be a valiant soldier and loyal servant to King Magni and for that I salute you!  With the pressure you applied to the Dark Iron encampment, we now stand a chance of driving them off our lands for good. . .if only the damned reserve would show. . . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][304] = {title = "A Grim Task", objective = "Kill Balgaras the Foul and bring his ear to Longbraid the Grim outside of Dun Modr.", description = "Many of my soldiers died in the battle of Dun Modr. My own brother perished when the West Bridge over the Thandol Span was destroyed.  Aye, the Dark Iron dwarves are a devilish breed.  From what Roggo was able to gather, the leader of the thugs in the Wetlands is a warlock named Balgaras the Foul. He is quite a coward, sending his soldiers to do his bidding but hides in his camp on Direforge Hill, to the southeast.\n\nIf you can find the spineless scum, slay him and bring me his ear. I will reward you, <class>.", progress = "Were you able to locate Balgaras the Foul yet, <class>?  He has been evading us for quite some time.", completion = "Balgaras the Foul is finally dead.  While his death will not bring back the many innocent dwarves who died needlessly by his hand, it will help to restore peace of mind to those who survived.  With Balgaras dead, the remaining Dark Iron scum should be easy enough to manage.  Now, we must wipe them out before a new leader is sent to these parts.\n\nYou have done well, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nGold Lion ShieldTranquil Ring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][305] = {title = "In Search of The Excavation Team", objective = "Tarrel Rockweaver wants you to travel to the Excavation Site and contact Merrin Rockweaver.", description = "Oh my, you must be the scout Longbraid said he would send!  You cannot imagine how worried I have been.\n\nMy wife, Merrin, has been sending me letters each week for the past month.  She is part of the Whelgar Excavation team.  But it has been nearly two weeks since her last correspondence.  Surely something is wrong!\n\nLongbraid said that he would send a scout to check up on things if we did not hear from the team soon.  I assume that scout is you, <name>.  Find Merrin at the excavation site to the east!", progress = nil, completion = "Oh, thank the heavens you are here!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][306] = {title = "In Search of The Excavation Team", objective = "Return to Tarrel Rockweaver with Merrin's note.", description = "It was horrible!  We were uncovering some rare artifacts and we began to discover these large bones.\n\nBefore we knew what was happening, these Mottled Raptors overwhelmed the dig site.  Many lives were lost.\n\nOrmer here -- so brave -- saved the Prospector and me.  He defended us as we ran for shelter.  Now we are trapped.  And our hard work lies in ruin.\n\nHere, take this note back to my sweet Tarrel.  It will explain the situation to him.", progress = "Were you able to find Merrin?  Did she send word?", completion = "Such horrible news!  At least 3 of them survived.  But when will the killing end?  I long for the day when King Magni's subjects can live without fear.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][307] = {title = "Filthy Paws", objective = "Go to the Silver Stream Mine and collect 4 loads of Miners' Gear.\n\nReturn to Mountaineer Stormpike.", description = "The Silver Stream Mine to the east ran dry long ago.  It was converted by the Miners' League into a storage depot, but now Kobolds have moved in, putting their filthy paws on good, Dwarven tools!\n\nWe'll root out those vermin soon enough, but the League wants someone to get their gear out of the mine before we warriors tromp in there and break things.  It'll be a tough delve - you might want cohorts at your side.\n\nThe gear is stored in Miners' League Crates throughout the mine.  Good luck.", progress = "Do you have that Miners' Gear, <name>?", completion = "Did you see a lot of Kobolds in there?  I can't wait for the order to clear them out of the mine.  The thought of their grimy hands clawing around our mine makes my stomach rumble!", rewards = "You will be able to choose one of these rewards:\n\nIronheart ChainRobe of the KeeperIronplate Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][308] = {title = "Distracting Jarven", objective = "Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!", description = nil, progress = "Hmph!  There  is all this booze down here, but I have strict orders not to touch it.  If only I could get a taste of some of our Thunder Ale...that would sharpen my wits, no lying!", completion = "For me?  You're a true hero, &lt;name&gt;!", rewards = nil}
MultiLanguageQuestData['en'][309] = {title = "Protecting the Shipment", objective = "Ensure Miran and the shipment arrive at the excavation site, then inform Prospector Ironband.", description = "Ready to go, <name>?\n\nFirst, we need to get this powder to Ironband. It'll be a lot for me to carry, and these parts can get dangerous -- and who knows what else the Dark Irons might have in store for me.\n\nI'll feel a lot better with you coming along.", progress = "Where is my powder, <name>? My need grows more desperate every day.", completion = "Oh, thank the Light the powder is here. But it is troubling news that you bring as well. To think that the Dark Irons have sympathizers able to procure this sort of material for their dastardly plans.\n\nThat's a matter for someone else to consider, some other time. I must put this powder to good use.", rewards = "You will be able to choose one of these rewards:\n\nForeman BeltMud Stompers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][310] = {title = "Bitter Rivals", objective = "In the basement of the Thunderbrew Distillery in Kharanos, replace a barrel of Thunder Ale with a Barrel of Barleybrew Scalder.", description = "I have to admit, those Thunderbrews make some good drinks.  But they need to learn that theirs isn't the only decent brew!  Maybe you can help me teach them that lesson...\n\nHere, take this barrel of Barleybrew Scalder.  Sneak into the basement of the Thunderbrew Distillery in Kharanos and switch it with one of their barrels of Thunder Ale.  Then we'll see how their patrons like my brew over theirs!\n\nAnd if the barrels are guarded, then you might have to distract the guard ...", progress = "The date on this barrel shows that it'll soon be tapped.", completion = "You quickly place Marleth's barrel of Barleybrew Scalder among the Thunderbrew barrels.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][311] = {title = "Return to Marleth", objective = "Bring the barrel of Thunder Ale to Marleth Barleybrew at the Brewnall Village.", description = "Having inserted a barrel of Marleth's Scalder in the Kharanos Distillery's cellar, you grab a barrel of Thunder Ale as proof of the deed...", progress = "Did you make the switch?", completion = "Not bad, &lt;name&gt;!  Did you have a hard time getting past their guard?\n\nNo matter - many thanks, and if you're ever in need of stout with a kick, don't forget the Barleybrews!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][312] = {title = "Tundra MacGrann's Stolen Stash", objective = "Retrieve Tundra MacGrann's dried meats from the stolen meat locker in Old Icebeard's cave.", description = "I had a month's worth of dried meats salted and locked away for the cold season.  Kept it locked so the bears wouldn't get it!  But while I was off hunting deer, that beast, Old Icebeard, made off with the meat locker.  He won't be able to smash through that Thorium though.  But I'll starve if I can't get my meats back.\n\nYou seem a bit more stealthy than me.  Perhaps you can retrieve my stash?  I'll never make it in and out of that cave fast enough with this bum leg of mine.", progress = "Were you able to get into my meat locker, <name>?", completion = "What a kind soul you are, &lt;name&gt;!  Thanks to your bravery I won't find myself starving when the cold season flurries blow in.", rewards = "You will be able to choose one of these rewards:\n\nIronwrought BracersWooly Mittens\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][313] = {title = "The Grizzled Den", objective = "Gather 8 Wendigo Manes and bring them to Pilot Stonegear.", description = "Driving a Siege Engine isn't for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How's your mettle?  Want to prove it to me?\n\nWell...I'm looking to make my engine, Trollplow, a little more cozy.  How about you get me a heap of Wendigo Manes from the Grizzled Den, west of Kharanos.  Those manes would make a great rug for Trollplow's inside deck!", progress = "Hey, <name>.  Been to the Grizzled Den yet?  Those Wendigos can be fierce.", completion = "Ah yes, these manes will work great!  You show a lot of grit, &lt;class&gt; - I wager we'll see great things from you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][314] = {title = "Protecting the Herd", objective = "Rudra Amberstill wants you to slay Vagash and bring his fang to her at the Ram ranch.", description = "We heard the cries in the middle of the night.  Then this morning, sure enough, the herd was missing two rams.  That dastardly beast known as Vagash has been preying on our livelihood.  With most of King Magni's army off in distant lands fighting with the Alliance, there is no one to keep Vagash at bay.\n\nPerhaps you are brave enough to seek out the beast and slay him.  Bring me one of his fangs and I will reward you.  Vagash lurks just above the ranch here, but be warned, he is deadly.", progress = "Vagash still terrorizes the herd!  Please help us by killing the wretched beast.", completion = "Very well done!  Veron will be so happy when he hears the good news.  To kill Vagash is no easy task.  I imagine one day you'll be fighting alongside King Magni's men on the Alliance Front.", rewards = "You will be able to choose one of these rewards:\n\nRancher's TrousersSoft Leather TunicColdridge Hammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][315] = {title = "The Perfect Stout", objective = "Bring 6 Shimmerweeds to Rejold Barleybrew in the Brewnall Village.", description = "I'm on a quest, a quest to make the perfect stout.  I know I can do it -- brewing's in my blood.  I just need to find the right recipe...\n\nThe Frostmane trolls grow a plant, shimmerweed, high up in the hills to the east.  They use it in their strange, tribal rituals.  We dwarves haven't found much use for it, but it has a unique taste...and I want to experiment with it in my brews!\n\nGet me some shimmerweed from Frostmane seers, or swipe it from the trolls' shimmerweed baskets.", progress = "Do you have that shimmerweed?  I almost have a batch of stout ready to brew, and I want to try throwing the weed in with this mixture.", completion = "Great!  I can't wait to use these in some of my recipes.  There's one in particular I think it'll work great in...", rewards = "You will be able to choose one of these rewards:\n\nGoat Fur CloakIvy-weave Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][316] = {title = "<UNUSED 1>", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nBlue Murloc EggOrange Murloc EggPink Murloc EggWhite Murloc EggMurloc Costume\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][317] = {title = "Stocking Jetsteam", objective = "Gather 4 Chunks of Boar Meat and 2 Thick Bear Furs, and deliver them to Pilot Bellowfiz at Steelgrill's Depot.", description = "I'm preparing to start a mission for the Siege Brigade.  It's a long one, and I need to stock Jetsteam with a month's worth of supplies.  So while Steelgrill is working on my tank, can you do some hunting for me?\n\nI'll need some fur for bedding, and boar meat for food.  You can get meat from boars and fur from the bears... you can find them both in the snow fields south of the Grizzled Den.", progress = "Preparations are going well.  How goes your hunting?", completion = "By Magni's beard, you sure did a lot of hunting!!  Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][318] = {title = "Evershine", objective = "Get a cask of Evershine from Rejold Barleybrew in Brewnall Village.", description = "Rejold Barleybrew experiments with his brews.  Some of them taste good, some bad, and some...well, some will lay all but the stoutest dwarf flat.\n\nHe lives at Brewnall Village, west of Kharanos, and one of his drinks, Evershine, is what I want.  It'll help keep me warm while I'm on the cold road.\n\nAnd...the blessed stuff burns so hot I can throw it in Jetsteam's furnace for a burst of power!  That little tactic has gotten me out of more than one tight spot.", progress = nil, completion = "Bellowfiz needs some of my Evershine?  Hm...all right.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][319] = {title = "A Favor for Evershine", objective = "Kill 6 Ice Claw Bears, 8 Elder Crag Boars, and 8 Snow Leopards, and then return to Rejold Barleybrew in Brewnall Village.", description = "I have a cask of Evershine handy, but...can you do me a favor?  Brewnall village could use a hand against the wild animals that wander the nearby snows.  Sometimes they wander close.\n\nWe're not afraid of these bears and cats and boars - no self respecting dwarf would be - but if you can take care of those animals for us, then we'd have more time for our crafting and brewing.", progress = "Have you taken care of those wild animals?", completion = "Thank you, &lt;name&gt;.  It'll be nice to work our crafts without hearing so many growls and snorts outside the village.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][320] = {title = "Return to Bellowfiz", objective = "Give the cask of Evershine to Pilot Bellowfiz at Steelgrill's Depot.", description = "Here's your cask of Evershine, <name>.  And again, thank you for the hunting earlier.", progress = "Did you get that Evershine?", completion = "Yes, this will do just fine.  I think I'll open a bottle right now and have a taste...", rewards = "You will be able to choose one of these rewards:\n\nSharp AxeGnarled Short StaffCamping Knife\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][321] = {title = "Lightforge Iron", objective = "Search the wreckage of The Flying Osprey in the Wetlands.", description = "The shipwrecks off the shore here are the doomed Third Fleet of Kul'Tiras, burned and sunk by Red Dragons during the last Great War.\n\nThe Fleet hailed from Lordaeron, but one ship, an Elvish Destroyer: Flying Osprey, was with it.  It was shipping a load of Lightforge Iron and joined the Third Fleet for protection.  Ironic that it sunk to the same dragons...\n\nEnough history.  The Flying Osprey is wrecked to the south of Menethil Harbor.  If you find the Lightforge Iron there, bring it to me.", progress = nil, completion = "This chest is waterlogged, and its siding broken.  Many claw marks mar both the inside and outside of the chest...as if Murlocs have searched through it and stolen its treasure.\n\nBut tucked deep within the chest is a single Lightforge Ingot.  Unfortunately, many more will be needed if enough metal to fashion a weapon is to be gained.", rewards = "You will receive:\n\nLightforge Ingot"}
MultiLanguageQuestData['en'][322] = {title = "Blessed Arm", objective = "Take the Crate of Lightforge Ingots to Grimand Elmore in Stormwind.", description = "There is a dwarven weaponsmith in the Dwarven District of Stormwind who can craft with lightforge iron.  His name is Grimand Elmore.\n\nI've packed the iron you found into a crate.  Take it to Grimand and tell him your tale.  I'm sure he'll oblige someone on a quest such as yours, and craft for you a weapon - a weapon to give even Morbent Fel worry!", progress = "How might I ply my craft for you, <class>?", completion = "That is quite a tale you have.  And lightforge iron!  Not for years have I worked with such a metal.  It will be an honor to craft with it again.  And you must return to me later with the story of your battle against the Necromancer.\n\nBut we get ahead of ourselves.  First, your weapon against Morbent Fel...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][323] = {title = "Proving Your Worth", objective = "Kill 15 Skeletal Raiders, 3 Skeletal Healers and 3 Skeletal Warders, and then return to Sven.", description = "Morbent Fel is a necromancer, and an ally to the dark riders.  I would pit you against the power of Morbent Fel, but I will not send you against that vile fiend without first knowing your strength.\n\nYou have already proven your bravery to me, but if you truly wish to face the necromancer, then you must now prove your skill against his minions.", progress = "Battle hard, <name>.  And do not despair, for despair is evil's greatest weapon.", completion = "Your skill in combat, &lt;name&gt;, can not be doubted.  Your resolve may yet see us through to the end of Morbent Fel!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][324] = {title = "The Lost Ingots", objective = "Gather 5 Lightforge Ingots, then return to Glorin Steelbrow in the Wetlands.", description = "Having grabbed the single lightforge ingot from the waterlogged chest, it is clear that murlocs have stolen the rest.  Hunt the murloc raiders near the Flying Osprey wreckage for the lost lightforge iron.", progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][325] = {title = "Armed and Ready", objective = "Bring Morbent's Bane to Sven in Duskwood.", description = "Here is the weapon against the fiend of which you spoke.  You're all ready, <name>.  Best of luck to you, and I look forward to your tale of glory!", progress = "Hello, <name>.  You haven't been gone that long, but I see a fire in your eyes I did not see before.", completion = "Ah, this will be proof against the fiend Morbent Fel!  Well done!\n\nYou are ready.  Morbent Fel will fall.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][328] = {title = "The Hidden Key", objective = "Use the Small Brass Key to open Bookie Herod's Strongbox.", description = "Although no mention of Private Thorsen is found in these records, hidden within the binding of one of Herod's ledger books is a small, brass key.\n\nAnd after further study of his notes, a few references to a \"secure strongbox\" are contained among various papers.  The box is somewhere within the Stockpile - the cavern complex at the back of Kurzen's Compound.\n\nIf this secure strongbox is found, and the small brass key can open it, then perhaps the mystery behind Thorsen's detection will be revealed.", progress = "The strongbox is bound in bronze, very sturdy, and very heavy.", completion = "Opening the strongbox, it's clear that this is where Herod keeps his more valuable coins and items.", rewards = "You will receive:\n\nBookmaker's Scepter"}
MultiLanguageQuestData['en'][329] = {title = "The Spy Revealed!", objective = "Take the Muddy Note to Lieutenant Doren at the Rebel Camp.", description = "Among the valuables of the strongbox is a muddy, scribbled note.  Although barely legible, it looks to be an itinerary for Private Thorsen.  It details his patrol routes, who he speaks with and how he spends his time with the rebels.  It's signed with only one letter: -M.\n\nBut whoever wrote this note must have stayed very close to Thorsen.  Whoever wrote this note is the traitor within the rebel camp.", progress = "Did you discover who knew Thorsen's secret?  Is there a traitor among us?", completion = "Thank you, &lt;name&gt;.  This note is the clue we need to root out the traitor!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][330] = {title = "Patrol Schedules", objective = "Speak with Corporal Sethman.", description = "The note you gave me is signed with an \"-M\"...I don't know what that could mean.\n\nBut...the note also says this person shared patrol routes with Thorsen last week.  So whoever shared patrol with Thorsen last week must be the traitor!\n\nGo to Corporal Sethman.  He handles the patrol schedules and can tell you who was with Thorsen.", progress = nil, completion = "Oh, yes I can check that for you.  Let's see...last week it was...\n\n...why, it was Private Merle scheduled with Thorsen.  They had the same patrol times all of last week.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][331] = {title = "Report to Doren", objective = "Speak with Lieutenant Doren.", description = "Did Lieutenant Doren want you to report back to him with that patrol information?", progress = nil, completion = "It pains me to find out it was Merle who betrayed us.  He has always been a brave soldier, and I had thought his heart was true.  But it is a great relief to have found him out - with a spy like him among us...we would not last long against Colonel Kurzen.", rewards = "You will be able to choose one of these rewards:\n\nJunglewalker SandalsFrost Metal Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][332] = {title = "Wine Shop Advert", objective = "Go to the Gallina Winery, and bring Suzetta Gallina the Wine Ticket for a free bottle of wine.", description = "If you talk to anyone about wine, then you know we Gallinas sell the best wine in Stormwind.  And we're not far, still in the Trade District along the city's lovely canals.\n\nHere, take this pamphlet.  Bring it to my sister Suzetta at our shop for a complimentary bottle of our famous pinot noir.  You won't regret it!", progress = "Greetings and welcome, master.  Have you yet tried one of our fine wines?", completion = "Ah, so you've seen Renato?  Well here you are, sir.  A bottle of our special pinot noir.  You'll not find its equal in all of Azeroth!", rewards = "You will receive:\n\nBottle of Dalaran Noir"}
MultiLanguageQuestData['en'][333] = {title = "Harlan Needs a Resupply", objective = "Go to the Canal Tailor Shop and bring Rema Schneider the Cloth Request from Harlan Bagley.", description = "We've been doing a lot of business lately.  It seems like everyone is buying armor and sturdy clothes.  Almost like they expect a cold, harsh season ahead...\n\nBut those are future worries.  My worry today is that I'm running out of knitted clothing to sell.  I need another load from our supplier.\n\nIf you can take this request to Rema Schneider at the Canal Tailor and Fit Shop, I'd be most grateful.", progress = "You bring word from Mr. Bagley?", completion = "It says here that Harlan's business is booming.  That's good news, but I wonder why people have need of all that armor.  I've heard nothing of open war...is there something the nobles aren't telling us?\n\nWell, thank you for bringing the request.  Here's your payment, and I'll see to it that Harlan gets his supplies.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][334] = {title = "Package for Thurman", objective = "Go to the Larson Clothiers in the Stormwind Mage Quarter, and give Thurman Schneider his Sewing Kit.", description = "My son Thurman is an apprentice at the Larson Clothiers, in the Mage's Quarter.  He was in a hurry today and forgot his shears and needles.  I know a great <class> like you must have important tasks at hand, but without his tools Thurman can't do his apprentice work!\n\nPlease, <name>.  Can you take my son's sewing kit to him?  Larson Clothiers is one of two clothing shops in the Mage's Quarter - it's the one deeper in, near the Mage's Tower.", progress = "Are you here to buy clothes?", completion = "Oh, blast!  I thought forgetting my kit would free me from work.  Now I guess I'll have to help the Larsons with their sewing...\n\nOh, well.  Fun will come later I guess.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][335] = {title = "A Noble Brew", objective = "Zardeth the Black Claw wants you to bring him a Tear of Tilloa from Darkshire and a Musquash Root from the Wetlands.", description = "Lord Wishock is causing quite a stir amongst the House of Nobles.  He was made aware of our little \"establishment\" down here and is lobbying for a full investigation.  I have a plan to keep Wishock \"preoccupied,\" but I'll need your help. \n\nThere is a flower growing in the Garden of Stalvan on the outskirts of Darkshire.  This small white flower is known as the Tear of Tilloa.  I will also need a Musquash Root, found only at the very base of the falls far beneath the Stonewrought Dam in the Wetlands.", progress = "Wishock will soon garner enough support to cause us much grief.  Were you able to obtain the Tear of Tilloa or Musquash Root yet?", completion = "Most excellent! These are fine samples indeed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][336] = {title = "A Noble Brew", objective = "Take the Black Claw Stout to Lord Wishock in the Hall of Petitioners.", description = "Lord Wishock, like all men, has his weaknesses.  His happens to be a fondness for liquor.  The hypocrisy is astounding.  The trite fool spends his days trying to shut down our little \"tavern\" while his nights are spent upstairs, running up a bill he never pays.  Well, let's see how Wishock likes this special brew I have prepared for him:  Black Claw stout.  It's got quite a kick, <name>.\n\nTake it to him and see how he likes it.  Most likely the old fool is milling about the Hall of Petitioners.", progress = "Can you not see that I am busy?  My words must be heard!  I am very important to the future of this Kingdom!\n\nOh... what have you there?  Why it looks like a refreshing drink...", completion = "Ah, thank you for bringing me this fine looking stout, servant.  Here's a copper for you.  Now, out of sight with you and let me enjoy my drink!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][337] = {title = "An Old History Book", objective = "Return the book: The History of Stormwind, to the Stormwind Library.", description = "Although the cover of this book is marred by scratches and caked with mud, the words \"The History of Stormwind\" can still be read along its spine.  Upon opening the book, the seal of the Stormwind Library is clearly stamped on the book's first page.\n\nIt looks like someone checked out this book, and never returned it...", progress = "Ooh!  What's that old book you have there?  Can I see it??", completion = "Oh my!  This book hasn't rested on these shelves since before the rebuilding of Stormwind, years ago.  It will have to be restored of course, it's in bad shape, but I would be honored to place it within our rare books collection.\n\nThank you, sir.  Please accept this as payment for returning the book!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][338] = {title = "The Green Hills of Stranglethorn", objective = "Collect the missing pages from The Green Hills of Stranglethorn manuscript. Once all four chapters are complete, return them to Barnil.", description = "Master Nesingwary will be so upset if he finds out!\n\nHe trusted me to proofread the manuscript of his novel, The Green Hills of Stranglethorn.  Everything was going well, but a large gust of wind blew through the camp and scattered the pages everywhere!\n\nI was able to gather most of the pages but many are still strewn about the jungle.  Collect the pages to complete each of the four chapters.\n\nI will help you organize them.  Return the chapters to me once you have all four.", progress = "Have you assembled the chapters yet, <name>?", completion = "You've certainly saved me a heap of trouble, &lt;name&gt;!  I can't thank you enough.  It shouldn't be long now until we see Master Nesingwary's book in libraries throughout the world!", rewards = "You will receive:\n\nJungle BootsThick Armor KitSuperior Healing Potion"}
MultiLanguageQuestData['en'][339] = {title = "Chapter I", objective = "Bring pages 1, 4, 6, and 8 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter I.", description = "Chapter I was quite riveting!  Master Nesingwary sets the backdrop for the story and makes mention of his hunting companions, including me! \n\nBut that's besides the point.  Let me see which pages are still missing.  It seems pages 1, 4, 6 and 8 are still out there somewhere in the jungle!", progress = "I don't suppose you were able to track down pages 1, 4, 6 and 8?  Those four are all we need to piece Chapter I back together.", completion = "At last!  Chapter I is complete!", rewards = "You will receive:\n\nGreen Hills of Stranglethorn - Chapter I"}
MultiLanguageQuestData['en'][340] = {title = "Chapter II", objective = "Bring pages 10, 11, 14 and 16 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter II.", description = "Chapter II was chock full of exciting tales of panther and tiger hunting.  I could just kick myself for letting the pages blow away! \n\n It seems I was able to recover all of the pages with the exception of pages 10, 11, 14, and 16.", progress = "We still need pages 10, 11, 14 and 16 to complete Chapter II, <name>.", completion = "Chapter II is finally complete!  Well done!", rewards = "You will receive:\n\nGreen Hills of Stranglethorn - Chapter II"}
MultiLanguageQuestData['en'][341] = {title = "Chapter III", objective = "Bring pages 18, 20, 21and 24 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter III.", description = "Chapter III was my favorite.  It tells of Sir Erlgadin and Lady Rouack's first kill with a dwarven rifle.  And the end of Chapter III, why, such a cliffhanger!  \n\nLooks to me as though we still need pages 18, 20, 21 and 24 to finish the chapter.  Those pages are out there somewhere. . .", progress = "Any luck with pages 18, 20, 21 or 24?  Those are the only ones we need to piece together Chapter III.", completion = "Phew!  Good work, &lt;name&gt;.  Chapter III is now back together in one piece!", rewards = "You will receive:\n\nGreen Hills of Stranglethorn - Chapter III"}
MultiLanguageQuestData['en'][342] = {title = "Chapter IV", objective = "Bring pages 25, 26, and 27 of Nesingwary's The Green Hills of Stranglethorn to Barnil Stonepot in order to complete Chapter IV.", description = "Ah Chapter IV; the big finale!  And what an ending it was! \n\nWe are only missing three pages for this chapter.  We need pages 25, 26 and 27 to put Chapter IV back together.", progress = "We just need three pages to finish off Chapter IV, <name>.  Do you have pages 25, 26 or 27 yet?", completion = "Superb!  We now have Chapter IV ready to go!", rewards = "You will receive:\n\nGreen Hills of Stranglethorn - Chapter IV"}
MultiLanguageQuestData['en'][343] = {title = "Speaking of Fortitude", objective = "Go to the Royal Library in Stormwind Keep and speak with Milton Sheaf. He can find for you the book on metallurgy that Brother Kristoff needs for his speech.", description = "I'm giving a speech on the Fortitude of the Spirit, and I'd like to recite passages from a particular book on metallurgy - \"The Stresses of Iron.\"  A copy of this book should be in the Royal Library, within Stormwind Keep.  Can you retrieve it for me?  If so, then may the blessings of the Light be with you!\n\nThe Royal Library is very large, but the head librarian, Milton Sheaf, knows each shelf like it was his own son.  Speak to him, he'll retrieve the book for you.", progress = nil, completion = "Metallurgy?  Ah yes, we have many books on the subject, and are happy to aid Brother Kristoff with his speech!  Now...which particular book was it the good brother needed?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][344] = {title = "Brother Paxton", objective = "Speak with Brother Paxton in the Northshire Abbey.", description = "The Stresses of Iron?  Yes, I know the book.  Quite a good one, written by the Dwarven miner Margulf Blaggon a few decades ago.  He spent most his time deep in the mountains of Khaz Modan, digging ore.  Smart fellow!\n\nBut where was I?  Oh yes, the Stresses of Iron!  I'm afraid the book was moved to the Northshire Abbey.  The caretaker of the Abbey's library, Brother Paxton, wanted to make a copy of the book for his own shelves.\n\nBut that was months ago.  I wonder why it's taking him so long...", progress = nil, completion = "Mr. Sheaf is wondering where his book is?  Well this is a tad embarrassing.  I have the book, but I'm still making my copy and I'm not quite ready to give the original up!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][345] = {title = "Ink Supplies", objective = "Speak with Foreman Oslow in Lakeshire and ask him for Rethban Iron Ore.", description = "I've been meaning to finish my copy of The Stresses of Iron, but...\n\nWell you see, I make my own ink for books I copy.  It's my own recipe; it doesn't run or smear, and it dries very quickly.  Unfortunately, it dries too quickly!  My last batch dried up before I could finish the copying job, and I haven't had the chance to make more ink!\n\nTo make more I need Rethban Iron Ore from the Redridge Mountains.  Foreman Oslow in Lakeshire is my usual supplier.", progress = nil, completion = "You need what??  Maybe you haven't noticed, but we're busy fortifying Lakeshire's defenses and repairing damage from recent orc attacks.  If you need Rethban Iron Ore, you'll have to get it yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][346] = {title = "Return to Kristoff", objective = "Return to Brother Kristoff in the Cathedral Square. Give him the book The Stresses of Iron.", description = "Now that I've finished copying the book, here's the original Stresses of Iron.  Thank you for your patience, and if you see Milton please tell him I'm sorry for the long delay.", progress = "Were you able to find the book?", completion = "That's the one!  Thank you, &lt;name&gt;.  May the Light shine brightly upon both your body and spirit!", rewards = "You will receive:\n\nWandering Boots"}
MultiLanguageQuestData['en'][347] = {title = "Rethban Ore", objective = "Gather 5 loads of Rethban Ore and bring it to Brother Paxton in the Northshire Library.", description = "Rethban Ore is named after the man who first found it, Bart Rethban.  When smelted it's not as strong as iron, but its ore has a dark, flat color that some scribes use in their dyes.  It can be found in the Rethban Caverns, north of here.\n\nWe usually have some in stock, but we're too busy preparing for Orc attacks to gather any.  And besides...Redridge Gnolls are now living in the Rethban Caverns and their Drudgers are gathering the ore themselves.\n\nSo if you need some, you'll have to get it yourself.", progress = "Do you have the Rethban Ore?", completion = "Oh, splendid!  I can use this ore to make my dye, and then can finish copying The Stresses of Iron.\n\nThank you, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][348] = {title = "Stranglethorn Fever", objective = "Seek out Witch Doctor Unbagwa and have him summon Mokk the Savage. Bring the Heart of Mokk to Fin Fizracket.", description = "Sick...so...very s-s-sick....\n\n...have contracted Stranglethorn Fever...deadly v-v-virus...\n\n...only cure...is...is...to eat the heart of M-m-m-m-mokk the Savage...elusive white beast...\n\n...Witch doctor Unbagwa...only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape...\n\n...hurry...dying...dying....", progress = "....mother?\n\n...so cold...\n\n...heading into the Twisting Nether...h-h-h-hold me mother....", completion = "...feel strength returning....\n\nWhere might be?  Booty Bay?  Oh my!  I had the strangest dream...\n\n...the weakness has not completely left me....", rewards = "You will receive:\n\nMedicine Blanket"}
MultiLanguageQuestData['en'][349] = {title = "Stranglethorn Fever", objective = "temp text 02 - log", description = "temp text 02 - description", progress = "Witch Doctor Unbagwa know what Mokk the Savage like.  Yes, yes!\n\nMe speak with spirits and make he come, I do.\n\nBut other Gorilla-beast like spirit talkin' too.  You protect Witch Doctor Unbagwa and I make he come to you.\n\nWitch Doctor Unbagwa want something first.  You bring 10 Gorilla Fangs and me start spirit talking!", completion = "Witch Doctor Unbagwa like Gorilla Fangs!  For you I talk to spirits.  Make Mokk the Savage come.\n\nYou protect Witch Doctor Unbagwa from other Gorilla-beast though or no Mokk for you!", rewards = nil}
MultiLanguageQuestData['en'][350] = {title = "Look to an Old Friend", objective = "Speak to Elling Trias in Stormwind.", description = "That Marzon would be contacting a member of the Defias and have ties to Lescovar...\n\nHaving killed VanCleef and Thredd, it would be hard to see Lescovar brought to proper justice, as your evidence is nothing without their testimonies. That is not even considering the fact that Lescovar is a noble and well connected. It effectively makes him above the law.\n\nYou'll need other help. I loathe to do so, but there is someone I know that will aid us. You'll find Trias in the Trade District of the city.", progress = nil, completion = "You're kidding? Shaw wants my help again? Of all the nerve...\n\nThe Defias Brotherhood, you say? Well, you're certainly the bearer of wonderful news, aren't you? Next you're going to tell me that Deathwing is still alive and attacking the city.\n\nAll right, tell me everything from the beginning. And don't leave out something you think might not be important. I need to know it all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][351] = {title = "Find OOX-17/TN!", objective = "Bring the distress beacon to Oglethorpe's homing robot.", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"The name's Oglethorpe, and my homing robot has gone missing!  I will reward you for its recovery!  Please take this beacon to the robot.  Excellent, I now have computed the coordinates for you!  It crashed near the Gaping Chasm in Tanaris!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover.  The beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-17/TN is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][353] = {title = "Stormpike's Delivery", objective = "Deliver the Package for Stormpike to Mountaineer Stormpike in Loch Modan.", description = "The Stormpikes are a respected dwarven clan, and are well known for their fine and discerning tastes.  So it's no wonder that Gringer Stormpike, a Mountaineer of Ironforge, commissioned me to craft him a weapon.\n\nThe weapon is finished, but... Mountaineer Stormpike is far away, in distant Loch Modan.  If you plan on traveling to the north, can you deliver this package to him?\n\nMy last message from Mountaineer Stormpike said he's stationed at the northern guard tower in Loch Modan.", progress = "You come all the way from Stormwind?  I hear it's getting dicey down there in the <race> lands, with brigands and orcs running about.  A perfect place for a <class> to prove his worth!", completion = "Aha!  So Grimand finally finished my axe!  I can't wait to try it against some troggs and kobolds!\n\nMany thanks, &lt;name&gt;.  It was a long distance to travel for this delivery.   Here are some coins for your efforts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][354] = {title = "Deaths in the Family", objective = "Bring Gregor's Remains, Nissa's Remains and Thurman's Remains to Coleman Farthing in Brill.", description = "The Agamand family was the most prosperous family in Tirisfal Glades.  I used to work their mills...before the Plague.\n\nWhen the Scourge first came, the Agamands fortified their home and convinced those in their employ to remain and help them defend.  We were fools, but at least we were loyal fools.\n\nThe Agamands, in their pride, doomed us to undeath.  And now they are minions of the Scourge!\n\nServe the Forsaken by defeating the Agamands who fell to the Plague.  Serve me by bringing me their remains.", progress = "Do you have the remains of the Agamands?  Are those cursed beasts finally destroyed?", completion = "Revenge has a sweet taste, don't you think?  When you destroyed the Agamands, did you catch any hint of free will within them?  I hope so.  I hope they knew fear before they were smashed into oblivion.\n\nIt is a foolish hope, I know.  But it is a hope I foster nonetheless.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][355] = {title = "Speak with Sevren", objective = "Speak with Magistrate Sevren in Brill.", description = "You have given me the remains of the Agamands, and satisfied my desire for revenge.  But the Agamand Mills hold a threat to all the Forsaken, not just to me.\n\nI have spoken to Magistrate Sevren of your exploits against the Agamands, and he wishes to speak with you.", progress = nil, completion = "Coleman speaks well of you, &lt;name&gt;, telling of your successful forays into the Agamand Mills.\n\nThe Forsaken have need of your talents once again...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][356] = {title = "Rear Guard Patrol", objective = "Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp.", description = "The defenders on The Bulwark protecting Tirisfal from the Plaguelands are on constant alert.  But sometimes Scourge will slip past them.\n\nOur success at the Bulwark depends on a one-front battle - we cannot allow an attack from the rear, nor can we allow our defenders' supply line to be cut.\n\nAssist the Bulwark.  Patrol east and slay any Scourge you find.  Spend particular effort at the Balnir Farmstead to the east.  It has become a haven for interloping Scourge.", progress = "Do you have a report of your patrol?", completion = "Very good.  Your efforts do much to keep the Scourge at bay.  A commendation will be sent to my superior, Executor Zygand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][357] = {title = "The Lich's Identity", objective = "Bring the Lich's Spellbook to Bethor Iceshard in the Undercity.", description = "There is a lich who dwells on the island in Brightwater Lake to the north.  Although he is a free-willed Forsaken, he believes all other Undead are Scourge slaves and has his minions attack anyone who approaches him.\n\nBut because he is Forsaken, the Queen will want him.  And if he is skilled in Necromancy, then his knowledge would be...quite useful to us.\n\nTo discover his identity and his talents, I must see his spellbook.  Steal into his camp and acquire it, then return to me.", progress = "<name>, have you acquired the book?", completion = "Very good, &lt;name&gt;.  I will study this book and determine the identity of that lich.  You have served your Queen well.\n\n\n\nAstonishing!  The book you retrieved belongs to no one other than Gunther Arcanus!\n\nGunther was a skilled Necromancer in life; he and I were friends and comrades-in-arms, before the Plague.  And judging from his book he has grown even more powerful in death.\n\nHis skills would be a great boon to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][358] = {title = "Graverobbers", objective = "Kill Rot Hide Graverobbers and Rot Hide Mongrels. \n\nBring 8 Embalming Ichors to Magistrate Sevren in Brill.", description = "The Mass Graves, southwest of Garren's Haunt to the north, were made to accommodate the...impressive...number of deaths Tirisfal suffered when the Plague first came.  \n\nThe bodies in these graves have so far been spared an undeath, but the Scourge now send Rot Hide Gnolls to gather the corpses and use them to bolster their armies.  This cannot be allowed!\n\nYour task is twofold: slay the Rot Hides at the Mass Grave and Garren's Haunt, and gather from them the Embalming Ichor that gives them life.", progress = "Is your task complete?  Have you destroyed those dog-things and drained them of their ichor?", completion = "Expertly done, &lt;name&gt;.  The Scourge are mistaken if they think they can use those corpses against us, and the fluid you gathered from the Rot Hide slaves will be studied by our Apothecaries.  It may have secrets we can use against them.\n\nAs I said, well done.  But our struggle continues, and the conflict will surely offer you more chances to prove your worth to the Forsaken.", rewards = "You will be able to choose one of these rewards:\n\nCold Steel GauntletsZombie Skin Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][359] = {title = "Forsaken Duties", objective = "Speak with Deathguard Linnea.", description = "I need a fresh report from our Deathguard waystation to the east.\n\nI must know if more Scourge forces have slipped past The Bulwark and into Tirisfal.  Our vigilance on the border to the Plaguelands must be maintained - we can't let the Scourge get a stronger foothold here!\n\nTravel south along the road, then east at the fork to the waystation.  Speak with Deathguard Linnea.  She has the information I need.", progress = nil, completion = "Magistrate Sevren wants a report?  Very well: the defenders at The Bulwark are holding the majority of the Scourge at bay, but some do slip through on occasion.\n\nWe have seen sporadic Scourge activity east of this station, with a concentration around the Balnir Farmstead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][360] = {title = "Return to the Magistrate", objective = "Return to Magistrate Sevren in Brill.", description = "Now return to Magistrate Sevren with the information I gave you.  He'll want it as soon as possible, so be swift.\n\nAnd if you see any Scourge on your way back, take them down - we can't let them wander our lands unchallenged.", progress = nil, completion = "It is troubling to hear of the Scourge slipping past the Bulwark.  The Lich King and his minions are ceaseless in their assaults.\n\nBut we will not give in.  He will not take us again!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][361] = {title = "A Letter Undelivered", objective = "Find Yvette Farthing, and deliver to her the letter from Thurman Agamand.", description = "This is a letter written by Thurman, the eldest son of Gregor Agamand.  It is addressed to an Yvette Farthing, though it does not appear to have reached her...", progress = "Yes?", completion = "Oh...my poor Thurman!  I begged him to leave Agamand Mills with me and my father, but his family loyalty was too strong!  And I knew it!  I just knew it that Brand meant him harm!!  Oh, curse this Plague, and the Scourge!\n\n&lt;Yvette's face then smoothes and grows cold.&gt;\n\nBut regrets are for the weak.  As a Forsaken, I have new goals and love is not one of them.  I would thank you for delivering this letter, for I had wondered what happened to my past love.\n\nBut that life is over.  Forever.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][362] = {title = "The Haunted Mills", objective = "Slay Devlin Agamand, and bring Devlin's Remains to Coleman Farthing in Brill.", description = "Devlin Agamand was the younger of two sons in the Agamand family, and in life the two could not be more different.  Thurman was tall and gentle while his younger brother was weak and sharp tongued.\n\nWhen Agamand Mills fell to the Plague, I was not surprised to hear that Devlin was quick to succumb.  His mad chattering can still be heard near the road leading to the Agamand Mills.\n\nI'm collecting the remains of the Agamands, and I want poor Devlin.  Find him, destroy him, and bring me his bones.", progress = "Did you find Devlin?", completion = "Thank you.  Devlin's bones will rest nicely on my mantle.\n\nIf my cold heart can find warmth, it is in knowing that the Agamands are destroyed.  They failed me and my family when the Plague came - now I swear I will smash their remains under my heel!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][363] = {title = "Rude Awakening", objective = "Speak with Shadow Priest Sarvis.", description = "About time you woke up. We were ready to toss you into the fire with the others, but it looks like you made it.\n\nI am Mordo, the caretaker of the crypt of Deathknell. And you are the Lich King's slave no more.\n\nSpeak with Shadow Priest Sarvis in the chapel at the base of the hill, he will tell you more of what you must know.", progress = nil, completion = "Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...\n\nI see the confusion on your face. Let me try to explain our... situation... to you.\n\nWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][364] = {title = "The Mindless Ones", objective = "Shadow Priest Sarvis wants you to kill 8 Mindless Zombies and 8 Wretched Zombies.", description = "We Forsaken are at war with the Lich King's army of the Scourge: necromantically raised armies of the undead, foul beasts of the north, and tormented spectres.\n\nThe northern part of the village has become overrun with the Mindless Ones, and they must be destroyed. Destroy them, show them no mercy, our former brothers and sisters as they might be. The Fallen are nothing but The Lich King's slaves.", progress = "You will not go far in this new life if you are unable to kill even the weakest of zombies, <name>. Do not return until you have success to report.", completion = "It is unfortunate that the Scourge cannot be brought into the fold, their large numbers would be useful in the battles ahead.\n\nBut they will not join us, so we have no choice but to destroy them.", rewards = "You will be able to choose one of these rewards:\n\nFlax GlovesBattered Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][365] = {title = "Fields of Grief", objective = "Steal 10 pumpkins from the farm to the west, just north of Deathknell and take them to Apothecary Johaan in Brill.", description = "What have we here?  You look like a fledgling <class>.  If you hope to prove yourself to The Dark Lady, you need to learn the ways of The Forsaken.\n\nTo the west you'll find a farm.  Humans infest the land like mold on a rotting corpse.  And worse yet, the Scarlet Crusade patrols nearby from their tower.  Teach those scum a lesson and steal 10 of their precious pumpkins.\n\nOnce you have 10, take them to Apothecary Johaan in Brill.", progress = "Deathguard Simmer sent word that you were going to provide me with some much needed reagents.  Were you able to gather 10 pumpkins yet, <name>?", completion = "You have performed your bidding well, young &lt;class&gt;.  You are proving yourself to be quite an asset to The Dark Lady's army.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][366] = {title = "Return the Book", objective = "Return Gunther's Spellbook to him, on the island of Gunther's Retreat.", description = "Long ago Gunther and I, along with the now Scourge Necromancer Thule Ravenclaw, were friends and students within the Kirin Tor - a society of mages in Dalaran.\n\nGunther and I both fell to the Plague, but I thought he either remained dead, or was raised into the ranks of the Lich King.  It is good to know he is free.\n\nWe must have him.  I have placed a spell on his book that, when he sees it, will show him that I too am free of the Lich King.  After knowing this, it is my hope that he will join us.", progress = "Your masters are fools to send you here, for I will never again be a Scourge slave!", completion = "My book?!?  So you were the thief who stole it!\n\nBut...what is this new enchantment upon it...Bethor?  He is in  Lordaeron?\n\nIf he still exists, then perhaps he too escaped from the Lich King's grasp...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][367] = {title = "A New Plague", objective = "Apothecary Johaan in the town of Brill wants you to collect 5 Vials of Darkhound Blood.", description = "Lady Sylvanas has called upon the Royal Apothecary Society. The Dark Lady believes our knowledge coupled with the newfound magic will provide the key to Arthas's demise.  She has challenged us to concoct a new plague, a plague deadlier than any ailment on Azeroth. This new disease will bring Arthas's Scourge Army to ruin.\n\nMy studies show that the blood of beasts might prove to be the key. Bring to me 5 vials of darkhound blood so I can test my theory.", progress = "Have you collected 5 vials of darkhound blood yet, <name>? Time is fleeting!", completion = "You have done well, &lt;name&gt; and I thank you for your efforts.", rewards = "You will receive:\n\nWeak Troll's Blood Potion"}
MultiLanguageQuestData['en'][368] = {title = "A New Plague", objective = "Apothecary Johaan of the town of Brill needs 5 Vile Fin Scales from Murlocs in Tirisfal Glades.", description = "While you were collecting samples for me, my experiments led me to realize that more reagents will be required for this new disease to spread properly. Poisoning some hapless victim is child's play. Plaguing an entire world proves to be a bit more complicated.\n\nI will need 5 Vile Fin Scales from Murlocs in the vicinity.  You will find the creatures along the coast to the north or to the west.", progress = "<name>, were you able to obtain 5 Vile Fin Scales from the Murlocs?", completion = "The scales are perfect, &lt;name&gt;. Exactly what I needed for this concoction.", rewards = "You will receive:\n\nSlumber Sand"}
MultiLanguageQuestData['en'][369] = {title = "A New Plague", objective = "Apothecary Johaan in the town of Brill wants you to bring him 4 samples of venom from a Vicious Night Web Spider.", description = "While you were out gathering, I uncovered some old text in one of my tomes that indicates that an ancient plague wiped out thousands of innocent victims.  Later it was discovered that the deadly agent in the plague was preserved through the venom of Night Web Spiders.\n\nBring me some venom from a Vicious Night Web Spider to complete this experiment.  I want to see if the contagious element from the venom will work with my new concoction.  Rumor has it the spiders can be found in Eastern Tirisfal Glades.", progress = "Do you have some venom from a Vicious Night Web Spider yet, <name>?  It's the final component I need in order to test my experiment.", completion = "Ah, this venom will do perfectly, &lt;name&gt;.  Everything else has been added to my concoction and boiled down.  Finally, I am ready to try this new deadly agent!", rewards = "You will receive:\n\nApprentice Sash"}
MultiLanguageQuestData['en'][370] = {title = "At War With The Scarlet Crusade", objective = "Executor Zygand in Brill wants you to kill Captain Perrine, 3 Scarlet Zealots and 3 Scarlet Missionaries.", description = "The strategic documents from Executor Arren contain all the details we need to wipe the human infestation from the lands.  According to the information, The Scarlet Crusade has assigned Captain Perrine and a brigade to the ruined tower southwest of Brill.\n\nKill Perrine along with 3 Zealots and 3 Missionaries and report back to me.", progress = "Young <class>, you shouldn't be wasting your time here in Brill when your people need you fighting for their cause.  Now, take up arms and travel to the southwest, to the ruined tower, and slay Captain Perrine along with 3 Scarlet Zealots and 3 Scarlet Missionaries.  We shall herd the Scarlet Crusade like cattle to their demise.", completion = "Captain Perrine's death will undoubtedly please The Dark Lady.  You have performed your duty well, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][371] = {title = "At War With The Scarlet Crusade", objective = "Executor Zygand in Brill has commissioned you to slay Captain Vachon and 5 Scarlet Friars.", description = "We are still at war and the Scarlet Crusade grows in strength.  The report Executor Arren sent me indicates Scarlet Crusaders have been raiding from the ruined tower in southeastern Tirisfal near the Balnir Farmstead under the command of Captain Vachon.\n\nKill Vachon along with 5 Scarlet Friars. It should prove to be a devastating blow to the Crusade!", progress = "I see you have returned but your task is not complete.  Perhaps you are at ease with the mere humans interfering with The Dark Lady's plan?  Or perhaps you can heed the call of duty and slay Captain Vachon and his band of Scarlet Friars!", completion = "Captain Vachon's death will slow down the Scarlet Crusade's advancement in Tirisfal quite a bit.  But other threats loom.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][372] = {title = "At War With The Scarlet Crusade", objective = "Executor Zygand in the town of Brill wants you to assassinate Captain Melrache and his two bodyguards.", description = "Scarlet Crusaders have been raiding from the ruined tower in northern Tirisfal, past Faol's Rest.  According to the information we have, a ruthless commander named Captain Melrache is in charge of this evil crew.\n\nI am entrusting you now with a special and dangerous mission.  Slay Melrache and his two bodyguards, in the name of The Dark Lady.", progress = "You have not yet performed your duty, <class>.  We cannot expect to carry out The Dark Lady's plan with the Scarlet Crusade pestering our soldiers.  Bring about their deaths and perform your duty to Sylvanas!", completion = "You have done extremely well, &lt;class&gt;.  With ruthless fighters like you conquering in the name of The Forsaken our race is one step closer to defeating Arthas once and for all.  I have a good feeling about you, comrade.", rewards = "You will be able to choose one of these rewards:\n\nCeremonial KnifeStriking Hatchet\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][373] = {title = "The Unsent Letter", objective = "Deliver the Letter to the City Architect to Baros Alexston in Stormwind.", description = "Searching Edwin VanCleef's person, you discover, among other things, an unsent letter. It is addressed to Baros Alexston, the City Architect of Stormwind, City Hall, Cathedral Square.\n\nIt appears to be recently written and sealed.", progress = "Yes? Is there something I can help you with?", completion = "Edwin VanCleef, you say? I would as much expect a letter from my dead grandmother... So you've killed him then? Pardon me in saying, but I'm somewhat surprised. He was a peerless fighter in his younger years. Let's see what he finds the need to write to me about after so many years.\n\n&lt;Baros peruses the letter.&gt;\n\nEdwin... I see the years haven't changed you a bit, an idealist as ever, and a romantic. He doesn't care who he hurts, &lt;name&gt;. Revenge has consumed him. But then, I'm not sure I can blame him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][374] = {title = "Proof of Demise", objective = "Bring 10 Scarlet Insignia Rings to Deathguard Burgess in Brill.", description = "Executor Zygand tells me you've been out killing Scarlet Crusaders. Tirisfal Glades is crawling with them.\n\nVarimathras, lieutenant to The Dark Lady, is seeing to it personally that the scum of Azeroth, the Human race, gets wiped into oblivion. Here in Tirisfal Glades we face a particularly annoying breed of humans: The Scarlet Crusade.\n\nVenture forth and wage an offensive on the Scarlet Crusade, <class>. Bring me back 10 Scarlet Insignia Rings as proof of your loyalty to Varimathras and The Dark Lady.", progress = "Have you collected 10 Scarlet Insignia Rings yet, <class>?", completion = "Varimathras would be proud.  You serve your leaders well, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nZombie Skin BracersClasped BeltNetted Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][375] = {title = "The Chill of Death", objective = "Bring five Duskbat Pelts and some Coarse Thread to Gretchen Dedmar in Brill.", description = "It's so cold, now.  The Plague of Undeath crawls through my veins like an icy serpent.  The Mindless State will be upon me soon.  But no doomed destiny will prevent me from serving our Dark Lady.  When the call arose I sewed body bags for the fallen soldiers of Sylvanas's mighty army.\n\nNow my hands shake from the chill.  If you would bring me five Duskbat Pelts and some Coarse Thread I could sew myself a blanket.  Help me, <name>, so that I can continue to serve the cause.", progress = "Do you have five Duskbat Pelts and some Coarse Thread yet, <name>?", completion = "I appreciate your efforts, &lt;name&gt;.  May Sylvanas recognize your bravery one day. . . .", rewards = "You will be able to choose one of these rewards:\n\nAdept's CloakSewing Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][376] = {title = "The Damned", objective = "Novice Elreth requires 6 Scavenger Paws and 6 Duskbat Wings.", description = "My duties include tending to our wounded warriors, tailoring armor and clothes, and assisting Shadow Priest Sarvis with whatever else he might need.\n\nFrom the look of it, you'll be enlisted in his service also... hunting the Mindless Ones, if I know his mind. Well, if you'd like to stay in one piece--and I've no doubt you do--perhaps I can help. I'm running out of paws and wings, and if you bring me some, I'll find some armor for you. You'll find a good number of wolves and bats to the south.", progress = "Do try your best to keep yourself unharmed until I get you some armor.", completion = "Thank you, &lt;name&gt;. This armor should help you out.\n\nHopefully, it should do you more good than the last one to wear it...", rewards = "You will be able to choose one of these rewards:\n\nFlax BracersOld Leather Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][377] = {title = "Crime and Punishment", objective = "Councilman Millstipe of Darkshire wants you to bring him the hand of Dextren Ward.", description = "As if the neglect for the residents of Duskwood was not bad enough, now the House of Nobles spits in the eye of the Darkshire Council with their decision to imprison Dextren Ward in Stormwind rather than behead the villain as per Lord Ebonlocke's sentence.\n\nWard was caught selling bodies from the cemetery to Morbent Fel, a crime punishable by death.  Yet Stormwind claims Ward as their prisoner.\n\nAssassinate Ward in The Stormwind Stockade - bring me his hand - and I shall reward you.", progress = "So long as a molester of the dead like Dextren Ward is permitted to live, justice stands betrayed.  Return to me once Lord Ebonlocke's sentence of death is carried out on that defiler, Ward.  We shall give the families of the dead the closure they deserve and better yet, we will send a clear message to the House of Nobles in Stormwind.", completion = "So Dextren Ward finally paid for his crimes against humanity?  Good riddance to the scum I say.  And cheers to you, my friend!  Not only have you given the families of the dead the peace of mind they deserve, you sent a poignant message to those corrupt bureaucrats in the House of Nobles.  Stormwind must rise to the needs of the people of Duskwood or we will break free from their tyranny.", rewards = "You will be able to choose one of these rewards:\n\nAmbassador's BootsDarkshire Mail Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][378] = {title = "The Fury Runs Deep", objective = "Motley Garmason wants Kam Deepfury's head brought to him at Dun Modr.", description = "You have proven your loyalty to King Magni, <class>.  And your hatred for the Dark Iron scum is as great as my own.\n\nThere is a task I wish to complete myself but I am bound by honor to stay with Longbraid.  But Roggo has gathered intelligence that proves Kam Deepfury was a conspirator in the attack on the Thandol Span.  It was by Deepfury's planning that Longbraid lost his kin.\n\nDeepfury is being held for political reasons in the Stormwind Stockade.  I want him dead, <name>.  For Longbraid!  Bring me his head!", progress = "I won't let foolish Human bureaucracy interfere with Dwarven matters, <name>.  Kam Deepfury is a proven conspirator in the Thandol Span attack.  King Magni's good people lost their lives because of Deepfury's deceit.  The Humans might be content to let Deepfury rot in The Stockade but I will not sleep soundly at night until Deepfury is slain.", completion = "So Kam Deepfury finally got to feel what it is like to be on the receiving end of Death?  Good.  Serves the cowardly Dark Iron scum right.  You have done well, &lt;class&gt;.  The victims of the Thandol Span attack were but mere victims in a world torn with war and unrest.  Their families will have the peace of knowing Deepfury got the punishment he deserved.  Longbraid's brother's death has been avenged.", rewards = "You will be able to choose one of these rewards:\n\nBelt of VindicationHeadbasher\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][379] = {title = "Slake That Thirst", objective = "Bring 5 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan.", description = "You want a power source.  I can help you with that.  Know what I want?  I want something to drink!  Bring me five Wastewander Water Pouches, and I'll give you the 4711-FTZ.\n\nNow... guess where you can find Wastewander Water Pouches!  Why don't you walk up to one of the Wastewander nomads to the east of here and ask them for one.  Let me know how that works out for you.", progress = "Well, did the nomads \"volunteer\" up those water pouches for you?", completion = "Excellent, the power source is yours.  Now, it isn't completely designed for use in a science kit like that, so you'll only have a limited amount of time before all the data you collect will go kablooey!\n\nWhen you collect everything you need for whatever it is you are doing, bring it to me and I'll shut it down properly.  You'll have at most two hours to get what you need to get done, done.\n\nIf you don't get it done in time, I can always sell you another power source to try again.  You heard me - sell!", rewards = "You will receive:\n\nModel 4711-FTZ Power Source"}
MultiLanguageQuestData['en'][380] = {title = "Night Web's Hollow", objective = "Executor Arren wants you to kill 10 Young Night Web Spiders and 8 Night Web Spiders.", description = "One of our greatest struggles is obtaining the natural resources we need to survive. Gold was scarce even in the height of the Alliance's power.\n\nThere is a gold mine to the northwest that has been overrun with spiders. We need gold from the mine, but we can't very well get it while the spiders are crawling around in there. I've not much manpower to commit to the task, so we'll just have to do it little by little.\n\nGet up there and see what you can do for us, <name>.", progress = "Be wary of the spiders' venom, <name>. If you feel a sharp burning, you may want to have it looked at.", completion = "Hmm, well, it's a start. It'll take a few weeks or months to fully clean out the infestation. After that, we'll have to get down there with some torches to burn away the webbing.\n\nYou've done your duty well, &lt;name&gt;, I'm sure I can find something else for you to do.", rewards = "You will be able to choose one of these rewards:\n\nFlax VestRugged Mail VestZombie Skin Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][381] = {title = "The Scarlet Crusade", objective = "Bring Executor Arren 12 Scarlet Armbands from Scarlet Converts and Scarlet Initiates.", description = "You'll be happy to know we appear to be making progress in the mine, thanks in no small part to your efforts.  We can now turn our eyes to other concerns.\n\nMy scouts have reported that a detachment of the Scarlet Crusade is setting up a camp southeast of here. The Scarlet Crusade is a despicable organization that hunts us, and they will not rest until every undead--Lich King's Scourge or no--is destroyed. We must strike first!\n\nBe careful, their unholy zeal makes them dangerous adversaries.", progress = "Those fools... They happily send themselves to their own graves.", completion = "If only they listened to reason, eh, &lt;name&gt;? Perhaps we could sit them down for reasonable discourse... ha!\n\nLight-blinded fools.", rewards = "You will be able to choose one of these rewards:\n\nForsaken DaggerForsaken MaulForsaken ShortswordForsaken Bastard Sword\n\nYou will also receive:\n\nRefreshing Spring Water"}
MultiLanguageQuestData['en'][382] = {title = "The Red Messenger", objective = "Kill Meven Korgal, the messenger, at the Crusader camp, then return any information you find to Executor Arren.", description = "Reports from my superiors in Brill indicate that an agent of the Scarlet Crusade was dispatched from the Scarlet Monastery and sent here to Deathknell. According to the reports, the messenger possesses important information on his person. I do not have further details, but whatever it is, we must have it!\n\nYou're the most qualified person I have to send, <name>. Find that messenger and bring me whatever information you can find.", progress = "How goes your mission, <name>?", completion = "Hmm... Let's see what you've got...\n\n&lt;He begins to rifle through the documents you recovered.&gt;\n\nSome news of their exploits against us... Worthless. Scouting reports... New orders, \"Continue to build up a camp near the ruined city...\" Nothing we didn't know already... Ah, what's this? A map of the dispositions of some of their field commanders and agents! We can use this.", rewards = "You will be able to choose one of these rewards:\n\nExecutor StaffDeathguard Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][383] = {title = "Vital Intelligence", objective = "Deliver the Scarlet Crusade Documents to Executor Zygand in Brill.", description = "These will need to be taken to my superior, Executor Zygand, in Brill. With this information, we'll be able to deal a decisive blow to the Scarlet Crusade. Your services have been useful here in Deathknell, but I need someone to deliver this to Zygand, and I believe he'll be able to find you more appropriate work.\n\nTake the road north out of Deathknell. Soon after entering Tirisfal proper, you'll hit a crossroads. Take the eastern fork, and keep going east. You'll pass Cold Hearth Manor along the way.", progress = "Yes, what do you want?", completion = "Yes, this is very good. You've done well in obtaining this information, &lt;name&gt;. Hmm... names of the officers in the Tirisfal Glades...\n\nImagine the blow we could deal to the morale of those bloody zealots if we were to kill their leaders in one swift strike.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][384] = {title = "Beer Basted Boar Ribs", objective = "Ragnar Thunderbrew in Kharanos wants 6 Crag Boar Ribs and a mug of Rhapsody Malt.", description = "Nothing my tavern patrons enjoy more than some Beer Basted Boar Ribs!  Only problem is, the local trapper who used to bring me supplies enlisted in the King's Army to help with the war on the Alliance front. \n\nMaybe you can help me out?  If you bring me six crag boar ribs and a Rhapsody Malt from the tavern here, I'll give you the family recipe for my famous Beer Basted Boar Ribs, not to mention a free sample!  The secret's in the Malt!", progress = "I'm going to need six crag boar ribs and a mug of Rhapsody Malt, <name>.", completion = "The Malt is brewed, the Boars are dead\nAnd before all is done and anything said\nWe will have to fight for first dibs\nOn these savory Beer Basted Boar Ribs!", rewards = "You will receive:\n\nBeer Basted Boar RibsRecipe: Beer Basted Boar Ribs"}
MultiLanguageQuestData['en'][385] = {title = "Crocolisk Hunting", objective = "Get 5 pieces of Crocolisk Meat and 6 Crocolisk Skins for Marek Ironheart at the Farstrider Lodge.", description = "Many a hunter is attracted to Loch Modan to hunt our famous crocs. There are always merchants who seek out crocolisk skins for clothing items or armor, and there are also some who enjoy the taste of their meat.\n\nWe do some trade in this, but not a huge amount, as the crocolisks are ferocious and have entrenched themselves on the islands in the Loch. But don't let me dissuade you, it's quite an experience, wrestling with the jaws of the beasts.\n\nWhy, this one time...", progress = "Did I tell you about the time I almost lost my hand to one of the crocs? Nasty bugger it was, teeth like knives. But I was lucky... Jammed the brute's jaw shut with my knife. Still have the knife around here somewhere...", completion = "Well now, these are excellent specimens you collected, &lt;name&gt;. Good money for high quality materials, that's for sure.", rewards = "You will receive:\n\nRecipe: Crocolisk SteakRugged Cape"}
MultiLanguageQuestData['en'][386] = {title = "What Comes Around...", objective = "Bring the head of Targorr the Dread to Guard Berton in Lakeshire.", description = "Targorr the Dread served under Gath'Ilzogg as supreme Executioner.  His methods were ruthless, even by filthy orc standards.  Men who fought bravely to defend the Kingdom were tortured on his whim.  Now he is being held in the Stormwind Stockade, sentenced to die.  Yet something is amiss.  One of the bureaucratic nobles put a hold on his execution.  I am sure foul play is in the works.\n\nPut an end to Targorr the Dread, <name>.  Travel to The Stockade and behead him before trickery is upon us.", progress = "Have you been to Stormwind yet, to The Stockade?  I fear whatever trickery that has kept Targorr the Dread alive for this long will eventually bring about his freedom.  He was sentenced to die, <name>, not act as some political pawn on a noble's whim.", completion = "Targorr the Dread has finally met his fate.  I for one am glad to hear the beast now knows what it is like to be on the receiving end of Death's ruthless grip.  You have done well, &lt;name&gt;.  Sometimes the truest justice can only be found outside the courtroom and beyond the clouded vision of politics.", rewards = "You will be able to choose one of these rewards:\n\nLucine LongswordHardened Root Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][387] = {title = "Quell The Uprising", objective = "Warden Thelwater of Stormwind wants you to kill 10 Defias Prisoners, 8 Defias Convicts, and 8 Defias Insurgents in The Stockade.", description = "The uprising must be quelled!  I need your assistance.  If word gets out that the prison is overrun I will lose my job!  This is a case of foul play if I've ever seen one.  But what's important now is forcing these prisoners into submission for the safety of Stormwind.\n\nThe punishment for insurgency is death.  Kill some of these deviants!  That ought to get things under control.", progress = "The Stockade is still overrun!  These Defias Rats must be shown that their actions will not be tolerated.  Now get back down there and show some force!", completion = "Your efforts in The Stockade were valiant, &lt;name&gt;.  It's obvious this problem is bigger than the both of us.  But you have performed well and for that I am thankful.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][388] = {title = "The Color of Blood", objective = "Nikova Raskol of Stormwind wants you to collect 10 Red Wool Bandanas.", description = "Bitterness flows through my veins like a cold river.  My grandson, Mac, was such a good boy.  A mere 14 years old.  When the army was sent off to the front, Mac took up arms to defend the city.  He was a guard in The Stockade, where the Defias gang is locked up.  Mac reprimanded some of the prisoners for tearing their wool blankets to make scarves, a symbol of their gang.  For that Mac was stabbed in the back.\n\nI want revenge.  Bring me 10 of their precious Wool Bandanas.  They are the color of blood.", progress = "I see you are back, <class>.  Have you collected 10 Red Wool Bandanas from those Defias Scum in The Stockade yet?", completion = "So these bandanas -- filthy tokens of corruption -- are what my Mac had to die for?  Such a waste.  Such a tragic sacrifice. \n\nBut alas, I cannot return to the past.  Just know, &lt;name&gt;, that you have brought my family justice through your deeds.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][389] = {title = "Bazil Thredd", objective = "Speak with Warden Thelwater in the Stockade.", description = "VanCleef and I were members of the Stonemasons Guild. Our main project was to rebuild Stormwind after the War.\n\nWhen we had finished our duties, we were cheated. The nobles refused to pay us for our work. Some of the more senior of the Stonemasons were offered governmental jobs, but VanCleef refused it out of loyalty to all the Stonemasons. He led a riot and left the city, swearing revenge.\n\nHis lieutenant, Bazil Thredd, might know more about VanCleef's plans. He's being held prisoner in the Stockade.", progress = nil, completion = "What in the Light do you want? Can't you see we have a crisis here?\n\nBazil Thredd?! Why would you want to speak with that bastard? How am I supposed to know you're not one of his cronies, come down to help with his bloody riot? If all the blasted cells weren't open, I might throw you in one for a while!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][391] = {title = "The Stockade Riots", objective = "Kill Bazil Thredd and bring his head back to Warden Thelwater at the Stockade.", description = "Let's get one thing straight, <name>: I don't trust you. But, with the situation as it is, you probably won't make a difference.\n\nSo here's how it's going to be: go down there and have your talk with Thredd. If you're really on our side, then kill him and bring me his head when the job's done. And if it turns out you're on his side, and don't come out... when we find you, you'll die along with the rest of the maggots.", progress = "Either you bring me Thredd's head, or I'll take yours, understand, <name>?", completion = "Without Thredd to lead them, hopefully the riots will be more controllable. We shall see.\n\nI must say, after a half hour, I hardly expected you to come out, but it seems I misjudged you.\n\nI'd guess, then, that you didn't get much useful information out of him? But I know a thing or two that might be of interest to you about Thredd's activities.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][392] = {title = "The Curious Visitor", objective = "Bring the Sealed Description of Thredd's Visitor to Baros Alexston in Stormwind.", description = "During the first years of Thredd's imprisonment, he never had any visitors. I figured that he was no longer of use to the Brotherhood, so they abandoned him.\n\nAnyway, a few months ago, that all changed; he started to get regular visits... once, maybe twice a week. It was a strange man--the quiet type. I had my suspicions, but all his papers checked out.\n\nHis documents claimed his name was Maelik; here's his description. I don't think he'll be coming to visit Thredd anymore.", progress = "Yes, <name>? What have you found?", completion = "Hmm. Maelik? No, the name doesn't sound familiar and neither does this description. But it could be anybody! A former Stonemason, one of the Defias Brotherhood... Though if he is as well connected as Thelwater suggests, perhaps someone else might recognize him. Let me think.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][393] = {title = "Shadow of the Past", objective = "Bring the Sealed Description of Thredd's Visitor to Master Mathias Shaw in Stormwind.", description = "I really haven't a clue, <name>. There is someone else who might be able to help you, and it so happens that he owes me a favor for--well, let's not get into that. Master Mathias Shaw of SI:7 can be found in the barracks in Old Town. Shaw has his thumb on most of the shady, or underhanded dealings of the city.\n\nIf anyone knows, it'd be him.", progress = "Greetings. Of what service can I be to you, <class>?", completion = "What? What's this? Yes, I think I do know who this man is, but his name is not Maelik. Assassins wear many names and many masks, discarding them as they lose their usefulness. Another alias known to be used by this man is Marzon; though even that is surely not his true name.\n\nRegardless, he is an assassin and I know a good deal about him.\n\nMarzon is currently under the employ of Lord Gregor Lescovar, a lord of shady reputation, even given the corruption of the nobility of Stormwind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][394] = {title = "The Head of the Beast", objective = "Speak to Mathias Shaw in Stormwind.", description = "Find Shaw in Old Town. Let him know that the Lescovar threat has been dealt with and about your involvement in the Lord's plots against the city. I'm sure he'll be proud to have another hero among Stormwind's citizens.\n\nHe'll more than likely send you off to meet with the Prince or some other noble. Don't let it get to your head, <name>. The nobles can think they rule the city all they want, but some things remain out of their hands.", progress = nil, completion = "He is dead, then? Your justice was swift, &lt;name&gt;. I pray to the Light that I never become your quarry!\n\n\n\nI mean no criticism, &lt;name&gt;. How could I, being the master of all assassins? But in truth, you have done the people of Stormwind a great service, and for that, I thank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][395] = {title = "Brotherhood's End", objective = "Speak with Baros Alexston in Stormwind.", description = "Ah, I almost forgot. Alexston came while you were away, he wished to speak with you. No doubt he wishes to report the goings-on of the Defias Brotherhood to the nobles.\n\nA bit of advice, <name>: if anyone should ask, I would provide all details but that it was your hand that slew Lescovar. Trust me. I am... acquainted... with the ways of such things.\n\nAnd as far as Trias goes, well, speak to no one of him... ever... if you can help it.", progress = nil, completion = "It's good to see you, &lt;name&gt;. I have heard that Lord Gregor Lescovar was found dead not long ago.\n\nIt would seem that you were successful in your mission. You have my gratitude that you have saved me, and many others, from VanCleef's revenge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][396] = {title = "An Audience with the King", objective = "Deliver Baros Alexston's report on the Defias Brotherhood to King Varian Wrynn in Stormwind Keep.", description = "I have prepared a report for the King. I believe you should be the one to deliver it to him, along with an account of your findings. Do not worry, there is no doubt that he will commend you for doing your duty to the people of Stormwind.\n\nYour audience is scheduled soon, so you'd best hurry, it's a bit of a ways to Stormwind Keep.", progress = "<name>, yes? I was informed by Baros Alexston that you would be coming. I must say, I am most interested in what you have to say.", completion = "You are to be commended for the service you have done for Stormwind, &lt;name&gt;. If VanCleef had been successful in his machinations, he would no doubt have done considerable harm to the kingdom--something we must obviously avoid.\n\nTake this, &lt;class&gt;, as a token of the King's appreciation. I am only sorry he cannot present it to you himself, but he is away on a diplomatic mission and shall not return for some time.", rewards = "You will receive:\n\nSeal of Wrynn"}
MultiLanguageQuestData['en'][397] = {title = "You Have Served Us Well", objective = "Speak with Zggi, the servant of Zardeth the Blackclaw, to claim your reward.", description = "I hear Lord Wishock enjoyed his beverage.  \n\nYou have served us well, <name>.  The Warlocks of Stormwind will be able to practice our ways without disturbance, thanks to you.  For your efforts, I have prepared a special gift for you.  Speak with my servant, Zggi, and claim your reward.", progress = nil, completion = "Master says give gift to &lt;name&gt;.  Zggi wants to keep nice gift but Zggi knows better than to betray Master.", rewards = "You will receive:\n\nDread Mage Hat"}
MultiLanguageQuestData['en'][398] = {title = "Wanted: Maggot Eye", objective = "Kill Maggot Eye and return to Executor Zygand in Brill with his paw for a reward.", description = "Wanted: Maggot Eye!\n\nA foul beast, even by Gnoll standards, Maggot Eye has been sentenced to death for his crimes against The Forsaken.  This despicable villain has been stealing corpses for use by the Lich King's army.  Maggot Eye was last seen pillaging the lands near Garren's Haunt to the north of Brill.\n\nThe town of Brill hereby offers a reward to the capable soul who can carry out the execution.  Show Executor Zygand the villain's paw once the deed is done.\n\nMercy is for the weak.", progress = "Yes?", completion = "Maggot Eye's dastardly acts have finally been avenged.  Maybe your acts of valor will send a clear message to those who wish to bring harm to our people.  On behalf of the town of Brill I thank you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nBrass Scale PantsTiller's Vest\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][399] = {title = "Humble Beginnings", objective = "Go to Baros Alexston's house in Westfall and search for his compass, then return it to him in Cathedral Square of Stormwind.", description = "It seems an eternity since I was a boy working the farm in Westfall. They say you can never go back, and it's true. Doubly true in my case, my family's home has been burned down and taken over by thieves.\n\nI have spoken with my father about the fate of some of my possessions, including my first compass. He was unable to save them. However, he also says that they should be hidden away on the farm.\n\nYou'll find the Alexston Farmstead west of Sentinel Hill. Perhaps you could go and retrieve it for me?", progress = "<name>! Did you have any luck?", completion = "Oh, thank you, &lt;name&gt;! It's of no practical use to me, but the sentimental value... Needless to say, thank you for bringing this to me... at some cost to your own well-being, not to mention the time it took to go all the way down to Westfall. You have my gratitude, and have this as a token of my thanks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][400] = {title = "Tools for Steelgrill", objective = "Deliver Steelgrill's Tools to Beldin Steelgrill.", description = "Beldin Steelgrill owns the local mechanic shop, and he's the best siege engine tech there is!  But he's not forgiving to his tools.  I swear he almost breaks more arclight spanners than we can supply him with!\n\nWe just filled his last order for tools.  If you deliver it to him I'm sure he'll make it worth the effort.\n\nHis shop, Steelgrill's Depot, is just northeast of Kharanos.  And it's a local haunt for veteran siege engine pilots, so keep your ears open for opportunities while you're there.", progress = "Hm?  You look a little young to be a siege engine pilot.  But no matter...do you need something fixed?\n\nWell take a number and get comfortable.  I'm working on a couple engines right now and won't have time for another job for at least a few days.\n\nOr, were you here for something else...?", completion = "You have my tools?  Well done, lad, well done!  I just broke my last fang-ratchet an hour ago and I need one of those to finish repairs on Pilot Stonegear's siege engine.  You did a good thing by lugging those tools here, &lt;name&gt;.\n\nHere, take these coins for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][401] = {title = "Wait for Sirra to Finish", objective = "Wait a moment, then speak with Sirra Von'Indi again.", description = "I'm almost finished translating that note.  If you come back in a few moments I should be done.", progress = nil, completion = "There we are.  It's translated...\n\n&lt;The air grows heavy, as if a thick, black curtain is drawn over the land...&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][402] = {title = "Sirra is Busy", objective = "Check back with Sirra later to see if he's still busy.I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to. Perhaps later, if we survive, I can finish this translation.", description = "I'm sorry, but with the town in the state it's in I'm afraid have other duties to attend to.  Perhaps later, if we survive, I can finish this translation.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][403] = {title = "Guarded Thunderbrew Barrel", objective = "This barrel of ale is guarded by Jarven Thunderbrew.  As long as he's in the basement, no barrels may be disturbed.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][404] = {title = "A Putrid Task", objective = "Bring 7 Putrid Claws to Deathguard Dillinger in Brill.", description = "Scourge have trickled into Tirisfal Glades and have infested the area west of Brill, near the old bridge.\n\nGo there and beat back the rotting dead and ravaged corpses you find.  Scatter their bones and bring back their putrid claws, and the Deathguards will reward you.", progress = "Have you completed the task with which I have charged you?  Do you have those putrid claws?", completion = "Well done.  I regret not being there to see you smash those &lt;race&gt; into rotting pulp!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][405] = {title = "The Prodigal Lich", objective = "Present Sevren's Orders to Bethor Iceshard in the Undercity.", description = "Bethor Iceshard, a high-ranking and powerful mage in the Undercity to the south, commands me to send him an agent with proven worth against the Scourge.  You, <name>, will be that agent.\n\nPresent these orders to Bethor.  He will then instruct you on your mission.  I don't know its details, but it deals with recruiting a wayward Lich.  And it will be dangerous.\n\nSo ready yourself, <class>.  You must not fail.\n\nYou may find Bethor in the Magic Quarter of the Undercity.", progress = "Greetings.  Either you do not know who I am, or your business with me is urgent.\n\nBecause if neither of these were true, then you would not be foolish enough to disturb me...", completion = "Ah, you are the agent sent by Magistrate Sevren.  Then yes, your business with me is crucial.\n\nI trust Sevren has mustered someone suitable for my task...but we shall see.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][407] = {title = "Fields of Grief", objective = "Take the Laced Pumpkin to the Captured Scarlet Zealot who is being held in the cellar of the Gallow's End Tavern.", description = "Harmless pumpkins, right?  Or so it would seem.  If we are to defeat Arthas's advances from the North and the Human infestation from the South we need to start realizing the full potential of our gift of undeath.\n\nWith a little ingenuity a simple pumpkin becomes an agent for our Dark Lady.  This pumpkin, laced with my latest formula, will prove to be quite a treat.\n\nYet another Scarlet Zealot has been captured and is being kept in the cellar of the Gallow's End Tavern.  Take this pumpkin to the fool.", progress = "Stay away, foul and unholy creature!  May the Light protect me!  The Scarlet Crusade shall rid Azeroth of your. . .\n\n. . .oh wait.  Is that food for me?  I am so hungry. . .", completion = "By the Light!  Finally some food!  Sweet, sweet pumpkin. . . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][408] = {title = "The Family Crypt", objective = "Kill 8 Wailing Ancestors and 8 Rotting Ancestors.\n\nKill Captain Dargol, and bring his skull to Magistrate Sevren in Brill.", description = "The Agamand Mills area has become a foothold for the Scourge.  Their strongest point is the Agamand Family Crypt where their local military leader, a skeleton named Captain Dargol, has headquartered.  With Necromancy he has raised the ancestors of the Agamands and plans to use them against us.\n\nThis cannot pass, and you must stop it.  Travel to the Agamand Family Crypt and defeat the raised Agamand ancestors.\n\nAnd, bring me the skull of Captain Dargol.", progress = "Time is not a luxury we have, <name>.  With each passing hour, the Scourge's hold on Tirisfal Glades grows more firm.", completion = "Your actions struck a telling blow against the Scourge.  And your victory will not go unnoticed - not by the Forsaken, nor by our enemies.\n\nContinue the struggle as we all do, &lt;name&gt;, and one day we will drive the Lich King himself from Azeroth!", rewards = "You will be able to choose one of these rewards:\n\nDarkwood StaffBonecracker\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][409] = {title = "Proving Allegiance", objective = "Obtain a Candle of Beckoning.\n\nSummon Lillith Nefara and kill her.\n\nReturn to Gunther on his island.", description = "You say you are not bound by the will of the Lich King, and the enchantment Bethor placed upon my book corroborates this.  But before I believe you I must have proof that you are enemy to the Scourge.\n\nThere is an old, bloody altar just off the southern coast of this island.  it is used by a powerful Scourge agent, Lillith Nefara.\n\nTake a Candle of Beckoning from this crate here.  Light it on the altar and Lillith will awake.  Destroy Lillith, and I will believe you are the Lich King's foe.", progress = "I await proof of your allegiance, <class>.", completion = "You have defeated Lillith Nefara, proving you are an enemy of the Scourge.  Incredible.\n\nI had believed I was the only &lt;race&gt; with free will, but you have shown me there are others who have broken the Lich King's domination.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][410] = {title = "The Dormant Shade", objective = "This is an old, beaten, bloody table.", description = nil, progress = "This is an old, beaten, bloody table.", completion = "You place the Candle of Beckoning upon the table and light it...", rewards = nil}
MultiLanguageQuestData['en'][411] = {title = "The Prodigal Lich Returns", objective = "Bring the Nether Gem to Bethor Iceshard in the Undercity.", description = "Take this Nether Gem to my old comrade Bethor.  It will let us communicate ... and I have much to tell him.", progress = "Have you returned Gunther's book?  Has he responded?", completion = "You convinced him to join us!  You have done a great deed for the Forsaken, &lt;name&gt;.  The Dark Lady will be informed.", rewards = "You will receive:\n\nBone Buckler"}
MultiLanguageQuestData['en'][412] = {title = "Operation Recombobulation", objective = "Bring Razzle Sprysprocket in Kharanos 8 Restabilization Cogs and 8 Gyromechanic Gears.", description = "Upon further analysis of the Gnomeregan situation, it would appear as though we not only failed to eradicate the troggs but we also happened to turn most of the gnomish race into horrific, mindless, evil-doing leper gnomes.\n\nOzzie and I plan to reverse the horrible leper effect with our latest invention: The Recombobulator.  The machine is almost complete but we are in dire need of some Restabilization Cogs and Gyromechanic Gears.  Retrieve some from the leper gnomes out front of Gnomeregan for us.", progress = "The Recombobulator will be up and running as soon as we have sufficient Restabilization Cogs and Gyromechanic Gears.", completion = "These Gyromechanic Gears and Restabilization Cogs are in perfect accordance with Ozzie's schematics for the Recombobulation Device.  Once I add some hydrolubricant to the inner combustion pistons, adjust the crank-o-ratchet and increase of the viscosity of the electrogum gel, the gnomish race will be as good as new.", rewards = "You will be able to choose one of these rewards:\n\nDriving GlovesOil-stained Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][413] = {title = "Shimmer Stout", objective = "Take the Barrel of Shimmer Stout to Mountaineer Barleybrew.", description = "I'd like my brother Wellart to try my new Shimmer Stout.  He's a Mountaineer stationed in the southern guard tower, one of two towers on the border to Loch Modan.\n\nHe may not be a brewer like the rest of us Barleybrews, but he loves his drinks and I know he'll like this one.\n\nCan you bring him this Barrel of Shimmer Stout for me?", progress = "Hello, <class>!  And what business takes you all the way out here?\n\nSomething exciting, I hope.  I haven't been in a good fight in days, and this barrel of ale is almost dry...", completion = "&lt;Mountaineer Barleybrew tastes the Shimmer Stout...&gt;\n\nOh.  Whoa!  This stuff really puts a shine in your eyes.  I feel like I can see in the dark!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][414] = {title = "Stout to Kadrell", objective = "Take the Cask of Shimmer Stout to Mountaineer Kadrell.", description = "I've been drinking more of that Shimmer Stout my brother made - it's great stuff!  I want a fellow Mountaineer to try it.  His name's Kadrell, and he's usually patrolling the road through Thelsamar in Loch Modan.\n\nTo get to Thelsamar, go southeast through the tunnel, then turn northeast when the path forks into a road.  Follow that road straight into Thelsamar.\n\nGive Mountaineer Kadrell this cask of Shimmer Stout and see what he thinks!", progress = "Greetings, <class>, and welcome to Thelsamar!", completion = "Now, let me have a taste...\n\nMagni's Beard!  This stuff gets your head turning!  And it lightens the limbs, too.\n\nI feel like I can fly!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][415] = {title = "Rejold's New Brew", objective = "Speak with Rejold Barleybrew.", description = "Rejold Barleybrew at Brewnall Village has been asking for you.\n\nHe wants to talk to you about a new drink he's been brewing...said something about you helping him with it.  You might want to head back to Brewnall Village and see what he has to say.\n\nThere could be some free booze in it for you...", progress = nil, completion = "&lt;name&gt;!  You know that Shimmerweed you brought me?  Well I used it in a few recipes I've been working on, and one of them turned out great!\n\nHere, try it out and tell me what you think...", rewards = "You will receive:\n\nMug of Shimmer Stout"}
MultiLanguageQuestData['en'][416] = {title = "Rat Catching", objective = "Bring 12 Tunnel Rat Ears to Mountaineer Kadrell in Thelsamar.", description = "We have a real infestation problem to the west.  Tunnel rat kobolds have moved into the foothills, setting up dens and fouling our land with their filth!\n\nWe want them eliminated.  Hunt them, bring me their ears and earn their bounty.\n\nYou can find tunnel rat kobolds and their dens west of Thelsamar, littered along the mountainside.", progress = "Hail, <name>.  How goes the rat catching?", completion = "Ugh!  When I asked for those ears I didn't realize they'd smell so bad!\n\nHere's your reward, &lt;name&gt;.  Well done.", rewards = "You will be able to choose one of these rewards:\n\nBurnt Hide BracersCavalier's Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][417] = {title = "A Pilot's Revenge", objective = "Kill Mangeclaw.\n\nBring his Mangy Claw and Hildelve's Journal to Pilot Hammerfoot.", description = "Hildelve wrote in his journal that he was attacked by Mangeclaw, a \"huge Ice Claw Bear.\"  He drove off the beast, but not before it mauled him savagely.\n\nJudging from the state of Hildelve's body, Mangeclaw must have later returned and killed him.\n\nHowever, Hildelve wrote in his journal his one, final wish:\n\nRevenge against Mangeclaw.", progress = "Hello, <name>.  Do you have word of my friend Hildelve?", completion = "This is grim news, for Hildelve was a good friend.  And I wish I could have been there with you when you found the beast, Mangeclaw!\n\nThank you, &lt;name&gt;.  Your deed will be remembered by the pilots of the Ironforge Siege Brigade.", rewards = "You will be able to choose one of these rewards:\n\nCraftsman's DaggerCompact Hammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][418] = {title = "Thelsamar Blood Sausages", objective = "Bring 3 pieces of Bear Meat, 3 Boar Intestines, and 3 Spider Ichor to Vidra Hearthstove in Thelsamar.", description = "There's never a shortage of empty bellies here in Thelsamar, kids running in and out, workers from the excavation coming in after  a hard day's work. We're famous for our blood sausages, I don't suppose you've ever tried them?\n\nNo? Well, around here you've got to work for your meals, and don't think just because you're a fancy <class>, you'll be any exception.\n\nI'll need bear meat, boar intestines for the casings, and spider ichor for spice. You get me some of those, and leave the cooking to Vidra!", progress = "I'm all ready to start cooking, do you have the ingredients for me?", completion = "Trust me, it seems a lot harder than it looks, but...\n\nOh, I've never known someone to take much interest in the making of sausages, but I'll give you the recipe just in case. Here you go, mind you eat them fresh!", rewards = "You will receive:\n\nBlood SausageRecipe: Blood Sausage"}
MultiLanguageQuestData['en'][419] = {title = "The Lost Pilot", objective = "Find Pilot Hildelve.", description = "My friend and fellow Siege Engine pilot, Mori Hildelve, is lost in the hills.  We were looking for a rare ore that's needed for a high-grade blastpowder, and during our search he drove his engine up a steep hill and busted it!\n\nStill convinced that ore was in these mountains, Hildelve charged me to guard our engines while he continued on foot, searching.\n\nIt's been days, and I've heard some beastly growls in the hills at night.  Mori's tough as nails, but I'm worried.\n\nPlease, <name>.  Find him.", progress = nil, completion = "Here is the corpse of a dwarf -- mauled, frozen, and picked clean by mountain scavengers.  Clutched in its hand is a book containing the roughly scribbled notes of Mori Hildelve.  And around its frame, still in superior condition, is a Brigadier's Vest.\n\nThis grisly scene must have been where the Siege Engine pilot met his end.", rewards = "You will receive:\n\nSiege Brigade Vest"}
MultiLanguageQuestData['en'][420] = {title = "Senir's Observations", objective = "Deliver Grelin's report to Senir Whitebeard in Kharanos.", description = "The troggs in the tunnel are extremely hostile, and haven't shown any hesitation in attacking travelers through the tunnel. You seem tough enough, though, so you should probably be safe.\n\nDirections? If you're going to speak with Senir, you'll find him in Kharanos.\n\nMake your way through the tunnel, and after you come out on the other side, just keep following the road, it'll run right into Kharanos.", progress = "How are you? Like to share a drink with me, perhaps? Not much else to do in the cold.", completion = "What's this? Ah, my brother's report. Hmm...\n\nI told him to be sparing with the use of the King's name, but he didn't listen. No harm, I suppose, though it's sure to ruffle some feathers in the Senate. Not that those weren't some feathers that needed ruffling! Hah!\n\nNonetheless, I guess that means that I should send my report on to Ironforge as well, but I must admit I'm a bit behind. Bloody cold.\n\nI should have some work for you later, if you're interested.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][421] = {title = "Prove Your Worth", objective = "Dalar Dawnweaver at the Sepulcher wants you to kill 5 Moonrage Whitescalps.", description = "Lady Sylvanas has charged Varimathras with the conquering of the human and dwarven lands to the south.\n\nBut that fool, Arugal -- charlatan of Dalaran and now cursed beast of Shadowfang Keep -- let his reckless magic wreak havoc with the strategic stronghold of Silverpine Forest.\n\nI need someone skilled in the ways of combat to help clean up Arugal's mess.  Prove yourself to me by killing 5 Moonrage Whitescalps.  The wretched beasts can often be found just off the road, down the hill below.", progress = "If you wish to prove yourself to me, you must kill 5 Moonrage Whitescalps.  Accomplish that task, and I will see to it your skill is put to more worthy assignments.", completion = "You have served me well, &lt;class&gt;.  It is obvious to me that you will be a worthy aide to me as I prepare to rid Silverpine Forest of Arugal's curse.", rewards = "The following spell will be cast on you:\n\nArcane Intellect\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][422] = {title = "Arugal's Folly", objective = "Retrieve the Remedy of Arugal for Dalar Dawnweaver at the Sepulcher.", description = "How Arugal gained acceptance within the Kirin Tor is beyond me.  His spell-casting knowledge seemed as transparent as a blown glass bauble.\n\nWhat's important now is learning exactly what magic Arugal used so that I can turn it against him and secure Silverpine Forest for the Dark Lady.\n\nArugal first stayed at the wheat farm just north of the bridge.  One of the Deathstalkers reported seeing some spellbooks but could not secure them.  Retrieve for me the spell labeled Remedy of Arugal from those books.", progress = "Before I know what we are dealing with here, <class>, I need to study the spell known as Remedy of Arugal.  Bring it to me now or I shall be forced to find myself a worthy servant.", completion = "This is precisely the spell I was in search of, &lt;class&gt;.  If your dedication to The Dark Lady's cause remains infallible you will find you have quite a future amongst The Forsaken.", rewards = "The following spell will be cast on you:\n\nArcane Intellect\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][423] = {title = "Arugal's Folly", objective = "Bring 6 Glutton Shackles and 3 Darksoul Shackles to Dalar Dawnweaver at the Sepulcher.", description = "After examining Arugal's work my worst suspicions were confirmed.  The old hack was not qualified to clean chamber pots in Dalaran let alone represent the Kirin Tor in its most dire hour.  Fools!\n\nArugal used enchanted items to reinforce his weak magic.  I need to examine these items first hand.  Travel forth and slay Moonrage Gluttons and Moonrage Darksouls until you have collected enough of their enchanted shackles for my research.  The foul creatures have been seen to the north and east.", progress = "I will need 6 Glutton Shackles and 3 Darksoul Shackles before I can assess the situation and devise a final solution for Arugal.  Now heed your bidding and slay Moonrage Gluttons and Moonrage Darksouls until you have what I need.", completion = "I hope I can acquire enough energy from such a limited sample.  Perhaps I should have had you get more shackles.\n\nNonetheless, you showed great skill in collecting these, &lt;class&gt;.", rewards = "The following spell will be cast on you:\n\nArcane Intellect\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][424] = {title = "Arugal's Folly", objective = "Kill Grimson the Pale and bring his head to Dalar Dawnweaver at the Sepulcher.", description = "It will indeed take me longer than I had thought to uncover the dark secrets behind the enchantments Arugal was using.\n\nBut in the meantime I need you to take care of a slight problem our Darkstalkers have discovered.  It seems that Arugal let his magic spread to the Deep Elem Mine in the hills to the southeast.\n\nThe mine would prove to be quite a resource for Varimathras's advance.\n\nI want you to behead the tainted foreman of the mine, Grimson the Pale.  With his death, the mine shall be ours.", progress = "Has Grimson the Pale been slain?  Varimathras will not be pleased if we ignore his bidding.", completion = "Most excellent.  The mine will provide superb resources for our forces as we spread throughout Silverpine and into Azeroth.", rewards = "The following spell will be cast on you:\n\nArcane Intellect\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][425] = {title = "Ivar the Foul", objective = "Kill Ivar the Foul, and bring Ivar's Head to Rane Yorick at the Ivar Patch.", description = "My brother Quinn and I were tasked to recon Silverpine Forest and report to High Executor Hadrec.  But we didn't get far -- when moving through this farm we were attacked by the ghoul Ivar the Foul.\n\nWe escaped from Ivar, but he seriously mauled Quinn.  He's healing from the potion you gave him, but Ivar may return before Quinn recovers.\n\nKill Ivar so Quinn will have time to heal.  Ivar is usually in the barn yonder, waiting for my guard to drop.", progress = "Have you killed Ivar the Foul?  If you won't do it for me and my brother, then do it for the Forsaken.", completion = "Ah, thank you.  You have my gratitude, &lt;name&gt;.\n\nAnd I will include you in the report I make to my superiors.", rewards = "You will be able to choose one of these rewards:\n\nQuilted BracersWeathered Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][426] = {title = "The Mills Overrun", objective = "Gather 5 Notched Ribs and 3 Blackened Skulls, then return to Deathguard Dillinger in Brill.", description = "The Scourge are trying to form a base at the Agamand Mills.  If they do, then they can stage further attacks within Tirisfal.\n\nThe orders have been given.  The Scourge in the Mills must be destroyed.\n\nGo to the Mills.  Collect Notched Ribs from Rattlecage and Cracked Skull Soldiers, and Blackened Skulls from Darkeye Bonecasters.\n\nTo get to the Mills, follow the road west.  After crossing the bridge, take the next fork north then keep going north.  When you see windmills, the battle will begin.", progress = "Our battles with the Scourge wage on, <name>.  Do your part and throw those cursed, mindless <race> back into the Plaguelands!", completion = "Your efforts in the war are felt among us, &lt;name&gt;.  I will not thank you for doing what is necessary, but the Deathguards of Tirisfal will remember your name.", rewards = "You will be able to choose one of these rewards:\n\nCryptwalker BootsSturdy Cloth Trousers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][427] = {title = "At War With The Scarlet Crusade", objective = "Executor Zygand of Brill wants you to kill 10 Scarlet Warriors.", description = "The documents Executor Arren provided are just the break we needed in our battle with the wretched Scarlet Crusade.  We now know their exact locations throughout Tirisfal Glades.\n\nBut the Deathguard has larger concerns.  The Lich King's army grows in number each night.  We need someone with \"initiative\" like yourself to drive the Scarlet Crusade to the grave.\n\nProve to me you are capable of serving The Dark Lady by travelling west to the tower past the Solliden Farmstead and slay 10 Scarlet Warriors.", progress = "If you wish to prove your worth to The Dark Lady, slay 10 Scarlet Warriors, <class>.", completion = "Most excellent, &lt;class&gt;.  Your skill in the art of combat is undeniable.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][428] = {title = "Lost Deathstalkers", objective = "Find the Deathstalkers Quinn and Rane Yorick.", description = "A couple weeks ago two of our Deathstalkers, Rane and Quinn Yorick, were sent on a reconnaissance mission through northern Silverpine.  We have not heard from them.\n\nThey may have become victim to the Scourge, though if that is true then I want it confirmed.  Find these Deathstalkers.\n\nTheir first objective was to scout the farms in northern Silverpine.  You should begin your search there.", progress = nil, completion = "You found us!  And not a moment too soon...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][429] = {title = "Wild Hearts", objective = "Gather 6 discolored worg hearts and bring them to Apothecary Renferrel at the Sepulcher.", description = "My brother Quinn was badly hurt by the ghoul, Ivar the Foul, and I don't know if he will heal properly without magical aid.  Although I am not an apothecary, I do know that our apothecaries can make healing potions from the discolored hearts of worgs.\n\nGather such hearts and take them to Apothecary Renferrel at the Sepulcher to the south.  Then return here with the potion.\n\nYou can find plenty of worgs between here and Malden's Orchard to the east.", progress = "My time is short, <class>, for the Dark Lady has charged me with a grave task.", completion = "&lt;Renferrel takes the hearts.&gt;\n\nIt is troubling to hear our Deathstalkers have failed their mission.\n\nLet us hope that these failures are rare.\n\nI'll give you the potion in a moment, but here is its recipe - if those Deathstalkers find themselves in need of future aid, then perhaps you can give it yourself.", rewards = "You will receive:\n\nRecipe: Discolored Healing PotionDiscolored Healing Potion"}
MultiLanguageQuestData['en'][430] = {title = "Return to Quinn", objective = "Bring Quinn's potion to Quinn Yorick at the Ivar Patch, north of the Sepulcher.", description = "Here is the potion to aid in Quinn Yorick's recovery.\n\nNow if you will excuse me, I have very important work to continue...", progress = "My sister told me you were here to aid us.  Is that true?", completion = "&lt;Quinn takes the potion and drinks it.&gt;\n\nYes, I can feel it working.  I will soon be able to travel.\n\nYou have done me a great favor, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][431] = {title = "Candles of Beckoning", objective = "You grab one of the candles and place it in your pack.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nCandle of Beckoning"}
MultiLanguageQuestData['en'][432] = {title = "Those Blasted Troggs!", objective = "Kill 6 Rockjaw Skullthumpers for Foreman Stonebrow at the Gol'Bolar quarry.", description = "Those Light-blasted troggs, turning my work site into a wreck! Look at that, there goes another barrel of powder!\n\nOhhh, I wish I could go down there and wring every one of their scrawny little necks! I want to kill them all!\n\nThis can't be good for my health, all this stress and anger... What have they left me with? Nothing!\n\nI'd kill them myself, but my aim's no good anymore! You go into the quarry and kill some of the filthy buggers! I'll pay you! Just hurt them, kill them!", progress = "It makes me so mad! Grrr...", completion = "Well, that makes me feel a little better...\n\nBut I won't be happy until they're all dead! All of them!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][433] = {title = "The Public Servant", objective = "Kill 10 Rockjaw Bonesnappers for Senator Mehr Stonehallow at the Gol'Bolar quarry.", description = "As a member of the Senate and the Explorers' League, I've taken it upon myself to take care of this part of the trogg infestation that has gripped our lands.\n\nThey've certainly made a mess of Gol'Bolar quarry, and for no reason. As we dug deep into the earth, they poured out, destroying our equipment and driving the miners out. There's not much for us to do but to exterminate the lot of them, rebuild, then get back to work.\n\nIf you help me with the troggs, I'll gladly recompense you for your time.", progress = "If we can remove the troggs from Gol'Bolar quarry, it will be the first step of many that we will have to undertake to rid ourselves of this menace.", completion = "It is a start. Hopefully we can take advantage of it, and move some Mountaineers in to secure the area. Then we can begin to restore our infrastructure and get the miners back to work.\n\nThank you for your assistance, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][434] = {title = "The Attack!", objective = "Remain in the garden until Lord Gregor Lescovar and Marzon the Silent Blade have had their conversation. Afterwards, kill them both before returning to Elling Trias in Stormwind.", description = "After I put on Spybot's disguise, he'll head in to talk to Lescovar. The guards should let him pass no problem.\n\nWhile you were getting materials for me, I took care of informing Marzon that it was time for him and Lescovar to meet again. I even dropped some false information.\n\nLescovar will dismiss his guards and wait for Marzon out here in the garden. After you catch wind of talk about the Defias, make your move. You need to kill them both before the guards return! When you're done, speak to Trias.", progress = nil, completion = "So it is done? Good. Thank you greatly for your discretion, &lt;name&gt;. You've proven worthy on more than one count. I'll be sure to keep my eyes on you and your progress within the Alliance.\n\nBe sure to keep your nose clean.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][435] = {title = "Escorting Erland", objective = "Escort Erland through the wolves, to Rane Yorick.", description = "The wolves outside won't leave, and they eye me evilly every time I step foot out that door.  They must be incredibly hungry to think I'm worth eating.\n\nI have to report to my teammate, the Deathstalker Rane Yorick.  And to get to Rane, I'll need help against those wolves.\n\nPlease escort me!  And there are a lot of wolves out there, so we'll have a better chance if you have friends who can help...", progress = "Please be brief.  There is much danger about and we cannot stand idle in conversation.", completion = "Thank you for the aid, &lt;name&gt;.  I had feared Erland was overcome by the dangers of Silverpine.  With your help, I see that he has not.", rewards = "You will receive:\n\nDeathstalker Shortsword"}
MultiLanguageQuestData['en'][436] = {title = "Ironband's Excavation", objective = "Speak with Explorer Fellhew.", description = "Prospector Ironband is heading an excavation of ancient ruins east of the lake.  His progress has been slow lately, especially considering all the supplies we've sent him.\n\nIronband's a stout, honest dwarf who values results, which has me worried that forces are at work against him.\n\nGo to Ironband's Excavation and speak with Magmar Fellhew.  He manages the details of the site and will know why there's a slowdown.\n\nTo get to the excavation site, go around the southern tip of the lake, then head east.", progress = nil, completion = "Jern wants to know what the slowdown is, eh?\n\nIronband is putting together his latest progress report with details, but I can tell you this:\n\nIt's the Troggs!!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][437] = {title = "The Dead Fields", objective = "Kill rot hide gnolls at the Dead Fields.\n\nWhen Nightlash appears, kill her.\n\nBring the Essence of Nightlash to High Executor Hadrec at the Sepulcher.", description = "Our initial scouting reports of Silverpine show the rot hides have a base at an old farm to the north, the Dead Fields.  We have sent small assaults against them, but each time they are reinforced by the banshee Nightlash, who uses her magic to rout our forces.\n\nWe want Nightlash destroyed.\n\nGo to the Dead Fields and assault the rot hides.  If you don't see Nightlash then kill the rot hides until she appears, then defeat her.\n\nHer essence will turn to dust.  Bring me that dust as proof.", progress = "Have you defeated Nightlash, <name>?  Our success against the rot hides depends on her destruction!", completion = "I heard of your successful raid against the rot hides, &lt;name&gt;, and this essence is proof of Nightlash's death.\n\nThe Scourge have lost ground this day.  Your value to the Forsaken grows.", rewards = "You will receive:\n\nReconnaissance Boots"}
MultiLanguageQuestData['en'][438] = {title = "The Decrepit Ferry", objective = "Go to the Decrepit Ferry.\n\nSearch for the reason the Scourge are there.", description = "<name>, we've discovered a new hive for the Scourge: the Decrepit Ferry.  The ferry lies east of the Sepulcher, and is heavily patrolled by rot hides and other undead.\n\nThere must be a reason for the Scourge's occupation of the area.  Go to the Decrepit Ferry and find out why the Scourge are there.", progress = nil, completion = "Heaped within this boat is a pile of wrapped corpses.  And looking east across Lordamere Lake, an opposing dock on Fenris Isle can be seen.\n\nThe fate of the corpses must lie on Fenris Isle.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][439] = {title = "Rot Hide Clues", objective = "Bring Deliah's Ring to High Executor Hadrec at the Sepulcher.", description = "Among the corpses a hand protrudes, unwrapped.  It is the hand of a woman, pockmarked from the plague but relatively fresh.  \n\nOn the hand is a ring.  Removing the ring and inspecting it reveals an engraving:\n\n\"For Deliah\"", progress = "<name>.  You return, so I assume your investigations bore fruit?", completion = "You say that this ring was worn by a woman, recently killed?\n\nThe only nearby source of such a body would be the mass graves in Tirisfal.  The Rot Hide Gnolls must be taking those corpses to Fenris Isle!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][440] = {title = "The Engraved Ring", objective = "Bring Deliah's Ring to Magistrate Sevren in Brill.", description = "If you want to find the husband or beloved who gave Deliah her ring... then speak with Magistrate Sevren in Brill.  He should have records of recent deaths and, with luck, can discover who Deliah is.\n\nBut I wouldn't hope.  Whoever gave her the ring is probably dead.  Or if he's undead he probably no longer cares about Deliah.", progress = "Hello, <name>.  What brings you back to Brill?", completion = "A Deliah did live in Brill not long ago.  She was buried in the mass grave but if what you say is true, then the Rot Hide Gnolls must have stolen her body and taken it to Silverpine.\n\nThe Rot Hides, like all the Scourge, must be destroyed.  I trust you are taking steps to make that happen.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][441] = {title = "Raleigh and the Undercity", objective = "Bring Deliah's Ring to Raleigh.", description = "Deliah had a husband, Raleigh, who now dwells in the Undercity.  If the Deliah who lived in Brill is the one who owned this ring, then Raleigh will know.\n\nRaleigh is in the Trade Quarter of the Undercity.", progress = "Do I know you?", completion = "Yes, this ring was my wife's.  Her fate was the fate of all who fail to endure these harsh times.  I feel nothing for her death, nor for the story you tell of her body's abduction.\n\nSuch feelings have long since grown cold within me.  But desire does still burn in my dead heart, &lt;name&gt;.\n\nDesire for revenge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][442] = {title = "Assault on Fenris Isle", objective = "Bring Thule's Head to High Executor Hadrec at the Sepulcher.", description = "Now is the time to assault the Scourge's place of strength in Silverpine: Fenris Isle.\n\nYou must again go to the Isle and destroy Thule Ravenclaw.  I want his head!\n\nThis mission is as dangerous as it is vital, <name>.  You must not fail.", progress = "The Scourge cannot be allowed to remain in Silverpine, <name>.  Come back to me when you have proof of Thule's death.", completion = "The death of Thule Ravenclaw was no small event, &lt;name&gt;.  Renferrel tells me that the energies released when you destroyed Thule were felt even as far as the Sepulcher.\n\nYour actions ring through the ranks of the Forsaken.  Your value to us grows.", rewards = "You will be able to choose one of these rewards:\n\nHigh Robe of the AdjudicatorTalonstrike\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][443] = {title = "Rot Hide Ichor", objective = "Bring 8 bottles of rot hide ichor to Apothecary Renferrel at the Sepulcher.", description = "Before we launch an assault on Fenris Isle, we must determine who is behind the rot hide gnolls.  Our apothecaries believe their origin lies within the strange fluid that flows through their bodies.\n\nGo to Fenris Isle, east of the Decrepit Ferry, and collect rot hide ichor from the gnolls you find there.  Bring it to Apothecary Renferrel, stationed outside the Sepulcher.", progress = "Do you have the rot hide ichor, <name>?", completion = "Very good.  This ichor will help us understand the nature of the rot hides, and may show us their weakness...\n\n...if they have one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][444] = {title = "Rot Hide Origins", objective = "Bring the Sample Ichor to Bethor Iceshard in the Undercity.", description = "I have reduced the ichor you brought me and separated it into its base components.  My findings are not conclusive, but I have determined that warlock and necromantic magics were used in the ichor's creation.\n\nWhile I continue to study the ichor, I want you to take a sample to Bethor Iceshard in the Undercity.  Bethor is not an apothecary, but his knowledge of magic may help to unravel the mystery of the rot hides.\n\nGo.  You will find Bethor in the Magic Quarter of the Undercity.", progress = "My studies require great concentration.  So I hope your visit is not a frivolous one.", completion = "This substance is laced with powerful spells, some of which I have not seen for a long, long time...\n\nOne moment -- I must invoke a spell of divination...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][445] = {title = "Delivery to Silverpine Forest", objective = "Take Apothecary Johaan's findings to Apothecary Renferrel in Silverpine Forest.", description = "Time is a luxury that is not afforded to those of us under the employ of Lady Sylvanas.  Surely you know this by now.\n\nAs a member of the Royal Apothecary Society it is my duty to share my knowledge with my colleagues so that our collective efforts might one day provide The Dark Lady with the New Plague she so badly desires.\n\nTake these findings to Apothecary Renferrel who is stationed at The Sepulcher in Silverpine Forest.  Follow the roads to the south from Brill.  From the Undercity go southwest.", progress = "What business do you have with me, <class>?", completion = "Ah, how good of Apothecary Johaan to send his research.  With so many new developments here in Silverpine, I nearly forgot about the findings coming out of Lordaeron and Tirisfal Glades.  Which reminds me, I need to get those samples off to the Necropolis soon.\n\nBut you must excuse my rambling.  Extend your stay in Silverpine, &lt;name&gt;.  We could use an able bodied &lt;class&gt; like you around here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][446] = {title = "Thule Ravenclaw", objective = "Bring Bethor's Scroll to Apothecary Renferrel at the Silverpine Sepulcher.", description = "This Ichor was crafted by an old colleague of mine: Thule Ravenclaw.  He was a young, promising mage before the great war, but when the Lich King rose to power, he betrayed his brethren and allied with the Scourge.\n\nI did not realize he still lives, nor that he leads the Rot Hides in their forays against us!\n\nI know many of his spells, and can help concoct a potion to counter them.  Take this scroll back to Apothecary Renferrel.  It has the incantations needed for the potion.", progress = "Greetings, <name>.  What did Bethor have to say?", completion = "This scroll is laced with powerful magic.  I've never used such forces in a potion ... it will be a powerful mixture, and should serve you well should you attack Thule in his stronghold on Fenris Isle.", rewards = "You will receive:\n\nBethor's Potion"}
MultiLanguageQuestData['en'][447] = {title = "A Recipe For Death", objective = "Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity.", description = "Arthas's numbers are overwhelming. But with a New Plague we could eradicate both the Scourge Army and the Human infestation once and for all.\n\nMy studies have proven that spider blood combined with a toxin derived from a grizzled bear heart results in a deadly elixir. Collect samples from the spiders in the Skittering Dark to the northwest and from the bears wandering throughout Silverpine Forest. Deliver the reagents to Master Apothecary Faranell of the Royal Apothecary Society in the Undercity.", progress = "Hail, <class>.  What business do you have with the Royal Apothecary Society?", completion = "How good of Apothecary Renferrel to send you to me, &lt;name&gt;.  These samples will indeed prove useful to the cause.  I will begin studying their toxic and contaminable properties at once.", rewards = "You will receive:\n\nSenggin Root"}
MultiLanguageQuestData['en'][448] = {title = "Report to Hadrec", objective = "Report to High Executor Hadrec at the Sepulcher.", description = "Before you launch an assault on Fenris Isle, report to High Executor Hadrec.  He may have additional information or equipment you'll need.", progress = nil, completion = "If what Bethor says is true then Thule Ravenclaw is a force that must be dealt with, and dealt with soon.\n\nTo aid in this task, you may take something from our arsenal here...", rewards = "You will be able to choose one of these rewards:\n\nCoarse WeightstoneCoarse Sharpening Stone\n\nYou will also receive:\n\nMedium Armor Kit"}
MultiLanguageQuestData['en'][449] = {title = "The Deathstalkers' Report", objective = "Bring the Deathstalker Report to High Executor Hadrec at the Sepulcher.", description = "Although Quinn's wounds are mending, I want to get our report to High Executor Hadrec as quickly as possible.  It has information that is vital to the Forsaken's occupation of Silverpine.", progress = "Did you discover the fate of the Deathstalkers?", completion = "I hadn't accounted for the level of Scourge presence we've seen in Silverpine Forest, nor for the troubles our Deathstalkers have had in their scouting efforts.\n\nYour aid to our Deathstalkers was invaluable, &lt;name&gt;.  And you will be commended.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][450] = {title = "A Recipe For Death", objective = "Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher.", description = "You can be of further service to the Royal Apothecary Society, <name>.\n\nWhen Arugal cast his wretched magic on the forest, he cursed one of our most promising members, Apothecary Berard.  Now a mindless servant of Arugal, Berard is useless to us.  But his findings might prove to be of worth.  He was studying an ancient plague that killed off all the aquatic life in Lake Lordamere ages ago.\n\nRetrieve Berard's Journal from his study in the Pyrewood Village Inn and take it to Apothecary Renferrel.", progress = "I see you are back, <name>.", completion = "Apothecary Berard's journal!  Why you are quite brave, &lt;name&gt;.  Now let's see what Berard was up to before he went mad. . .", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][451] = {title = "A Recipe For Death", objective = "Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity.", description = "According to Berard's Journal the moss from Lake Skulkers and Creepers might prove useful for our quest to brew a new plague.  Those beasts dwell on the islands in Lake Lordamere to the east.\n\nHe also mentions a very rare Hardened Tumor that he discovered on a Vile Fin murloc.  Apparently the tumor is so rare Berard was only able to obtain one.\n\nCollect samples of the moss as well as the rare Hardened Tumor and take them to Master Apothecary Faranell in the Undercity.", progress = "What brings you back to the Undercity, <name>?", completion = "Such a blow to the Royal Apothecary Society to lose Berard.  But through your hard work and Apothecary Renferrel's diligent research Berard's studies will still be useful to The Dark Lady's plight.\n\nWe are on the cusp of something great here, &lt;name&gt;.  If you were not so skilled in the ways of combat I would try to recruit you for membership in the Society.", rewards = "You will be able to choose one of these rewards:\n\nNightglow ConcoctionAcidproof Cloak\n\nYou will also receive:\n\nElixir of Minor FortitudeSwiftness Potion"}
MultiLanguageQuestData['en'][452] = {title = "Pyrewood Ambush", objective = "Help Deathstalker Faerleia kill the Pyrewood Council.", description = "You got here just in the nick of time, <name>!\n\nThe Pyrewood Council will be returning any moment.  Arugal has other matters to tend to in the keep.  He uses the Council as mere puppets to keep the mindless minions of Pyrewood under his control.  But I believe that without the guidance of the Pyrewood Council, the sons of Arugal will turn against their master.\n\nI cannot handle them all by myself.  I need you to help me.  Together we can lay waste to the Council for Lady Sylvanas.", progress = nil, completion = "You fought like a true disciple of the Dark Lady, &lt;name&gt;.  With the council dead, perhaps we can gain control of this town once and for all and drive Arugal from Shadowfang Keep.  I salute you!", rewards = "You will be able to choose one of these rewards:\n\nFaerleia's ShieldStretched Leather TrousersMystic Shawl\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][453] = {title = "Finding the Shadowy Figure", objective = "Find the Shadowy Figure. Your clues:\n\nHe is not native to Darkshire.\n\nHe is a nervous, jittery person.\n\nHe left Darkshire and headed west.", description = "Good luck, <name>.  I hope you find the chap, and I hope you find him alive.\n\nIf he's left the safety of Darkshire then he could be prey to the beasts of the wilds.", progress = "Who are you??  Leave me be!", completion = "&lt;Jitters sighs...&gt;\n\nYes, I'm the author of that book.  You finally found me, eh?\n\nWell if you read that journal...then you only know the half of it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][454] = {title = "After the Ambush", objective = "Speak with Miran.", description = "We'd been hauling the barrels of powder back and forth in trips before this... business. Now we have to split up the work, Miran's taking the barrels and I'm watching over the other ones.\n\nI don't feel safe letting Miran haul the rest of the shipment by himself. When he's ready to go, maybe you could escort him on his next trip?", progress = nil, completion = "Hello, &lt;class&gt;.\n\nYou'll be escorting me to the excavation site? That's good to hear... After Saean and his cronies, who knows what else the Dark Irons might have up their sleeves?\n\nAnyways, let me just make some final checks. Talk to me again when you're ready to go.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][455] = {title = "The Algaz Gauntlet", objective = "Traverse Dun Algaz.\n\nKill 8 Dragonmaw Scouts and 6 Dragonmaw Grunts.\n\nReport to Valstag Ironjaw in Menethil Harbor.", description = "Orcs of the Dragonmaw clan have a haven in the Wetlands.  And now they have expanded into Dun Algaz!  We can't let them keep their foothold here or Loch Modan will be cut off from Menethil Harbor, our port and stronghold in the Wetlands.\n\nBreak through Dun Algaz to the Wetlands beyond, and kill some orcs for good measure!  Report to Valstag Ironjaw in Menethil Harbor.\n\nMenethil is through Dun Algaz, then north along the road, then west at the fork.\n\nWe're counting on you, <name>.  Do not fail.", progress = nil, completion = "Your report is full of bad news!\n\nI see the Dragonmaws are making a strong move into Algaz.  Normally the Dragonmaws just hide up in the hills.  What made them surge into Algaz is still a mystery...\n\nThank you, &lt;name&gt;.  And we'll probably want your help dealing with these orcs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][456] = {title = "The Balance of Nature", objective = "Kill 7 Young Nightsabers and 4 Young Thistle Boars and return to Conservator Ilthalaine.", description = "Greetings, <name>.  I am Conservator Ilthalaine.  My purpose in Shadowglen is to ensure that the balance of nature is maintained.\n\nThe spring rains were particularly heavy this year, causing some of the forest's beasts to flourish while others suffered.\n\nUnfortunately, the nightsaber and thistle boar populations grew too large.  Shadowglen can only produce so much food for the beasts.  Journey forth, young <class>, and thin the boar and saber populations so that nature's harmony will be preserved.", progress = "There is still work to be done, <name>.  Return to me once you have thinned the nightsaber and thistle boar populations.", completion = "You performed your duties well, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nArchery Training GlovesStemleaf Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][457] = {title = "The Balance of Nature", objective = "Conservator Ilthalaine needs you to kill 7 Mangy Nightsabers and 7 Thistle Boars.", description = "Thinning the younger population of creatures here in Shadowglen was a good start, <name>, but there is still work to be done.\n\nThe resources of the forest will be depleted too quickly if the problem is not addressed.  Killing nature's beasts is a necessary evil for the good of all who share the land.  Venture into the forest and slay mangy nightsabers and thistle boars in the name of balance.", progress = "Your task is not yet complete, <name>.  Return to me once 8 mangy nightsabers and 8 thistle boars have been killed.", completion = "You have proven your dedication to nature well, &lt;name&gt;.  A young &lt;class&gt; like yourself has a promising future.", rewards = "You will be able to choose one of these rewards:\n\nDraped CloakBlackened Leather Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][458] = {title = "The Woodland Protector", objective = "Seek out the dryad known as Tarindrella.", description = "Thank goodness you are here, <class>. Strange news has traveled to me through the whisperings of the forest spirits.\n\nThe mysterious woodland protector, Tarindrella, has returned to Shadowglen. The dryad's presence has not been felt in the forests of Kalimdor in years. Something is surely amiss if she has journeyed back to this land.\n\nSeek out Tarindrella and see what business she tends to in our grove. One of the Sentinels reported seeing her to the southwest of Aldrassil.", progress = nil, completion = "I see you found me, young &lt;race&gt;.  Melithar is a wise druid to have sent you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][459] = {title = "The Woodland Protector", objective = "Collect 8 Fel Moss and bring them to Tarindrella.", description = "Something evil is brewing in the forests of Teldrassil.  Look long the hills to where the peaceful furbolgs used to dwell.  They have deserted their homes and are amassing under the name of the Gnarlpine tribe.\n\nOnly the corruption of wicked Fel Moss could cause such a transformation.  The grells and grellkin have infested the area and are threatening the residents of Shadowglen.  \n\nEngage these grells and grellkin, <name>, and see if they are indeed caught under the enchantment of the wicked Fel Moss.", progress = "Satisfy my suspicions, <name>.  Bring to me 8 Fel Moss.", completion = "Your service to the creatures of Shadowglen is worthy of reward, &lt;name&gt;.\n\nYou confirmed my fears, however.  If the grells have become tainted by the Fel Moss, one can only imagine what has become of the Gnarlpine tribe of furbolgs who once lived here.\n\nShould you find yourself in Dolanaar, able &lt;class&gt;, seek out the knowledgeable druid, Athridas Bearmantle.  He shares our concern for the well being of the forest.", rewards = "You will be able to choose one of these rewards:\n\nCanopy LeggingsTracking BootsViny Gloves\n\nYou will also receive:\n\nHealing Herb"}
MultiLanguageQuestData['en'][460] = {title = "Resting in Pieces", objective = "Bring Alaric's Head to his grave.", description = "You don't look like a rot hide.  Good.  I had lost hope...\n\nMy name is Alaric, and I was once Thule's head servant and bodyguard.  He used his magic to \"protect\" me from the Plague of Undeath, but instead his spell gave me an unlife from which I cannot escape.  And after creating the cursed rot hide gnolls, Thule beheaded me... and gave my head to the gnolls as a plaything!\n\nPlease, take me to my body.  I believe the gnolls buried it here in Fenris Keep, near the stable, in an unmarked grave.", progress = "This grave was hastily dug.", completion = "Thank you, &lt;name&gt;.  I had feared the Gnolls destroyed my body.  It is good to know they did not.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][461] = {title = "The Hidden Niche", objective = "Take Alaric to the hidden alcove.", description = "I know of a hidden niche within the keep that holds an item dear to Thule, and his old colleagues.  It also holds something you might find useful.  Take me there!\n\nThe alcove is in the southwestern tower of the keep, behind a dusty shelf.\n\nTake my body, but leave my boots.  They never fit me anyway...", progress = "This is the spot!  Bring me closer...", completion = "There we are, it's open.  Leave me here.  I spent the best days of my life in this keep, and the thought of resting within its walls gives me comfort.\n\nBe sure to close the alcove tight - I don't want those Rot Hides to find me.\n\nOh, and take this.  You've earned it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][463] = {title = "The Greenwarden", objective = "Find the Greenwarden.", description = "You've heard of the Greenwarden?  You're not looking for him, are you?  Well I say you're crazy if you are, but who am I to keep a fool from <his/her> death?\n\nIf you are seeking that beast, then I hear he is in the marsh, east of the road where it forks to Dun Modr.  He's lurking there among the crocs...and worse!\n\nAnd leave your money here.  You won't need it where you're going...and you don't want to chip ol' Greenie's tooth on your gold when he bites you in half, do you?", progress = nil, completion = "The roots and ferns speak well of you, small one.  Although I have many names, I answer to only a few.  But you may call me Rethiel.\n\nAnd you must harken...for these lands weep from festered wounds, and I would charge you to heal them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][464] = {title = "War Banners", objective = "Bring 8 Dragonmaw War Banners to Captain Stoutfist.", description = "The Dragonmaw orc clan was all but destroyed by the end of the Second War, after they lost control of their red dragon pets.  The dragons were not very happy with their old masters, and fiercely hunted the Dragonmaws.  What few remained fled from Grim Batol and into the Mountains east of Whelgar's Excavation.\n\nNow they've gained strength, and have an encampment northeast of Menethil.\n\nWe want you to attack that encampment.  Gather and bring me their war banners as proof.", progress = "Have you attacked the Dragonmaw encampment?", completion = "Well fought, &lt;name&gt;.  The Dragonmaws are not the same threat they were when they had dragons, but they're still fierce opponents.\n\nThe Dragonmaws are led by Nek'rosh, son of Nekros, who was the former head of the Dragonmaws years ago.  Nekros used powerful magic to tame the Red Dragons, but when that magic failed him...the dragons were not happy.\n\nNekros was killed, and his son has vowed revenge against the dragons who slew his father.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][465] = {title = "Nek'rosh's Gambit", objective = "Destroy the Dragonmaw catapults.", description = "While you were fighting the Dragonmaws, we discovered more of their plans.\n\nNek'rosh has built catapults and aims to lay siege to Menethil!  And with the fighting in Dun Algaz, we're effectively blocked from reinforcements!\n\nYou need to take out those catapults.  They're in the Dragonmaw encampment.\n\nHere, take this tinder.  Fight your way to the catapults and light them with the tinder.\n\nAnd after you've done that, find and kill Nek'rosh.  We need to cut this Dragonmaw beast down...at its neck.", progress = "The first catapult is before you.  Will you set it aflame?", completion = "You place some of the tinder on the catapult then strike a spark onto it.\n\nFlame erupts and quickly spreads!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][466] = {title = "Search for Incendicite", objective = "Bring 6 loads of Incendicite Ore to Pilot Stonegear in Dun Morogh.", description = "I heard that a rare ore, incendicite, was found in the Wetlands, in a cave northwest of Algaz Gate.  Incendicite is volatile stuff and hard to use without blowing yourself up, but I'm sure if it's smelted the right way it could make cannon shells that pack a mighty punch!\n\nGet me incendicite ore and I'll find someone brave enough to experiment with it.\n\nOh, and to extract that ore from a vein you'll need skill in mining.  If you don't have it, then ... bring a friend who does to that cave!", progress = "Where is that ore, <name>?!", completion = "You got the ore!  Well done, &lt;name&gt;!  I'll get someone to work with this right away.  Let's hope he doesn't blow himself up!", rewards = "You will receive:\n\nBeerstained Gloves"}
MultiLanguageQuestData['en'][467] = {title = "Stonegear's Search", objective = "Speak with Pilot Stonegear.", description = "Pilot Stonegear loves his siege engine, as every pilot should!  And he's always eager to find new ways to improve his tank's firepower!\n\nHe heard rumors of a rare ore and is looking for someone to hunt it down for him.  If your boots are starting to itch, then find Stonegear at Steelgrill's Depot in Dun Morogh and see what he wants.", progress = nil, completion = "Hello &lt;name&gt;.  You're here about the task I have, eh?  It's good to see a young &lt;race&gt; like yourself whose blood burns at the prospect of adventure!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][468] = {title = "Report to Mountaineer Rockgar", objective = "Speak with Mountaineer Rockgar.", description = "Mountaineer Rockgar is looking for volunteers for a mission through Dun Algaz and into the Wetlands.  \n\nIf you want to get your boots wet in that soggy county to the north, then speak with Rockgar at Dun Algaz.  Dun Algaz is north up the road, beyond the guard tower.", progress = nil, completion = "Hello, &lt;class&gt;!  You're here for the scouting mission, are you?  Very good!\n\nI hope your gear is in good condition, because this \"scouting\" mission has changed into something more messy...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][469] = {title = "Daily Delivery", objective = "Deliver the Bundle of Crocolisk Skins to James Halloran, the tanner, in Menethil Harbor.", description = "Greetings, traveler!\n\nDon't suppose you might be heading in the direction of Menethil, would you? If you're not, I'd suggest you stop there, it's a good place to purchase goods and even have a pint and relax.\n\nNow, if it just so happens that you're heading in that direction, I don't suppose you'd mind taking this bundle of crocolisk skins to James Halloran, the tanner?\n\nI'd do it myself, but my wife's been in quite a mood lately, and I'd like to put off facing her as long as possible.", progress = "Hello there, <class>. Could I interest you in a pair of boots?  Perhaps some newly cured skins?", completion = "Hmm, this is from Einar, right? Hasn't delivered his skins to me in person for almost a week now. No doubt it's some differences with the wife!\n\nMaybe I'll have my wife go speak with Sida sometime...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][470] = {title = "Digging Through the Ooze", objective = "One of the oozes at Ironbeard's Tomb has Sida's bag, retrieve it and bring it back to her in Menethil Harbor.", description = "On my weekly visit to Ironbeard's Tomb I was attacked by dreadful, dripping oozes! Naturally, I panicked.\n\nI threw my bag at one, but it didn't do anything! The ooze just sucked it right up... Luckily, it did give me enough time to get away.\n\nThe bad news is that I really need to get the contents of my bag!\n\nI don't know which ooze I threw my bag at; they all looked the same! Ironbeard's Tomb is northeast of here, near Dun Modr. Thank you so much!", progress = "Did you find my bag?", completion = "Oh, thank you, &lt;name&gt;! I was afraid that it was lost for good!\n\n\n\nHm, I don't have much use for this anymore, but wash it off and I'm sure you could make use of it.", rewards = "You will receive:\n\nOoze-covered Bag"}
MultiLanguageQuestData['en'][471] = {title = "Apprentice's Duties", objective = "Collect 6 Giant Crocolisk Skins and bring them to James Halloran in Menethil Harbor.", description = "I sent my apprentice out into the marshes to skin some of our famous giant Wetlands crocolisks. When he didn't return, I went out to look for him... Let's just say it wasn't a pretty sight.\n\nMidwife says he might pull through, but in the meantime I still need my skins!\n\n...If you'd like to kill a few more of the brutes, I wouldn't be opposed, after what they did. You'll find the crocs north up the coast, beyond the murloc hovels.", progress = "My apprentice is like a son to me.  It's going to be hard for him to live his life with only one leg.\n\nAh, <name>, how goes it?  Do you have my skins?", completion = "Hmm... Don't suppose you'd be interested in becoming my apprentice, would you?\n\nHah! No, I'm just kidding. You're much too old, for one thing.  Besides - from the looks of you, it would seem that you have other ambitions in life.  Nonetheless, these are some fine skins you've procured, and I'll be able to put them to good use.", rewards = "You will be able to choose one of these rewards:\n\nMalleable Chain LeggingsResilient Poncho\n\nYou will also receive:\n\nRecipe: Crocolisk Gumbo"}
MultiLanguageQuestData['en'][472] = {title = "Fall of Dun Modr", objective = "Search for Longbraid near the town of Dun Modr.", description = "Dun Modr has fallen to the Dark Iron Dwarves!\n\nMy wounds are grave, <class>.  Most of the regiment was killed!  The Dark Iron thugs attacked us before we could regroup from the Thandol Span ambush.\n\nOur leader, Longbraid, sounded the retreat horn.  As we left the town I was hit by a stray axe in the back.  All went black.\n\nI awoke here in Menethil but I fear for my fellow soldiers.  Hope still burns within me.  Perhaps Longbraid is still alive!  See if you can find him near Dun Modr, <race>!", progress = nil, completion = "What brave &lt;class&gt; sends word from Menethil?  Ah &lt;name&gt;, they call you.\n\nYou bring hope to a hopeless situation.  'Tis good news indeed that young Harlo survived.  While fleeing he received a grievous wound.  We had but little time to send him on his way on the back of the only surviving steed with the regiment.\n\nBut now we face a perilous situation.  Dun Modr has fallen and we are but a shadow of the great regiment we once were.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][473] = {title = "Report to Captain Stoutfist", objective = "Speak with Captain Stoutfist.", description = "<name>.  The Dragonmaw orc clan is showing its strength in more than just Algaz.  Captain Stoutfist has asked to speak with those willing to offer aid against these orcs.  He is inside the keep, in the war room.", progress = nil, completion = "&lt;name&gt;.  Valstag briefed me on your past success with the Dragonmaw Orcs at Dun Algaz.  You're a &lt;race&gt; of worth.\n\nAnd I have a task for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][474] = {title = "Defeat Nek'rosh", objective = "Kill Chieftain Nek'rosh\n\nBring Nek'rosh's Head to Captain Stoutfist.", description = "Now that the catapults have been burned, find and kill Chieftain Nek'rosh.", progress = "Have you killed Nek'rosh?", completion = "Stoutly done, &lt;name&gt;.  You have dealt a telling blow to the Dragonmaw orc clan.  They may never recover.  And the destruction of those catapults has made Menethil Harbor safe.\n\nYou are a &lt;race&gt; of merit, and the kingdom of Ironforge rewards those who serve it well.", rewards = "You will be able to choose one of these rewards:\n\nAncient War SwordBarreling Reaper\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][475] = {title = "A Troubling Breeze", objective = "Seek out Gaerolas Talvethren in Starbreeze Village.", description = "A troubling breeze blows through the forest.\n\nGaerolas Talvethren serves as Great Warden to the hibernating Druids of the Talon in the Ban'ethil Barrow Den.  His duty as the chosen protector of the Sleeping is to ensure their safety so that their pact with Ysera remains fulfilled.\n\nBut word from Gaerolas is now delayed and I grow nervous.  Travel east to Starbreeze Village and bring back a report from Gaerolas so that I can put my worries to rest, knowing my dreaming brethren slumber safely.", progress = nil, completion = "Thank the forest spirits you are here!  I knew Athridas would sense trouble and send help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][476] = {title = "Gnarlpine Corruption", objective = "Return to Athridas Bearmantle in Dolanaar.", description = "The Gnarlpine tribe has been corrupted!\n\nThe once peaceful furbolgs have turned against the protectors of the forest.  They ambushed me as I left for the Ban'ethil Barrow Den and proceeded to pillage Starbreeze Village.  Ursal the Mauler, their chieftain, is using the evil powers of the Fel Moss to drive them mad.\n\nI am too wounded to return to Athridas to bring him this grave news.  The task is left to you, young <class>.  We can only hope that the deranged Gnarlpines have not made it to Ban'ethil yet!", progress = nil, completion = "By the stars!  This is quite disturbing indeed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][477] = {title = "Border Crossings", objective = "Retrieve the contents of one of the Dalaran wizards' crates. You will find Pyrewood Village to the south.", description = "As you may know, the town of Ambermill remains a source of human opposition, mainly through the support they receive from the wizards of Dalaran.\n\nI don't know what their plan is, but for them to show interest in a backwater village like Ambermill indicates that it must have some greater importance.\n\nThey've been shipping crates by the wagon from Hillsbrad. Many of those supplies end up at a small camp north of Pyrewood Village. Retrieve the contents of a crate and return them to me.", progress = nil, completion = "&lt;Prying open the lid of the crate, you find an assortment of carefully-packed objects. On the top of the crate lies a bundle of maps, yellowing with age, that appear to depict Silverpine Forest and other parts of western Lordaeron.\n\nUnderneath the maps is a mysterious-looking magical pendant.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][478] = {title = "Maps and Runes", objective = "Bring the strange pendant to Shadow Priest Allister at the Sepulcher.", description = "<You quickly remove the pendant from the crate and replace the lid.>", progress = "Have you learned anything useful, <name>?", completion = "Maps and this... pendant, hm? Interesting.\n\nIt is obvious that the Dalaran wizards are interested in Ambermill for some purpose, but still, their aim is hidden to me.\n\nPerhaps Dalar will know something of their use.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][479] = {title = "Ambermill Investigations", objective = "Obtain 8 Dalaran Pendants for Shadow Priest Allister at the Sepulcher.", description = "Dalar is attempting to locate the source of the wizards' spellcasting. For now, we'll have to slow their progress in any way we can...\n\nThe conjurers, mages and protectors are no doubt carrying the pendants. Remove and retrieve them.\n\nTake the main road south and the eastern fork into Ambermill.", progress = "We must hurry, their plans must not come to fruition, or we may lose our hold on Silverpine Forest.", completion = "Dalar has found that the weaving is quite far along, despite the setback.\n\nA wizard of great power is guiding the magic energy. He must be stopped quickly.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][480] = {title = "The Weaver", objective = "Kill the Dalaran archmage, then retrieve his staff for Shadow Priest Allister at the Sepulcher.", description = "An archmage of great power is overseeing the reactivation of the ley energy node. With the progress they have made, our only hope of stopping them is by killing him. It will be difficult, he is no doubt protected by many other mages and warders.\n\nYou must go, and you must dispatch him quickly. When he is dead, retrieve his staff for me. Go now.", progress = "Quickly, time runs short, <name>!", completion = "The magic of the wizards dissipates, and the ley energies fade into dormancy. Your efforts have been fruitful, &lt;name&gt;, and we have dealt a major blow to our enemies, and to the overbearing wizards of Dalaran.\n\nWe must be vigilant, however, knowing that source of energy lies so close at hand... Plans must be made for the future.", rewards = "You will be able to choose one of these rewards:\n\nCeranium RodCamouflaged Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][481] = {title = "Dalar's Analysis", objective = "Take the rune-inscribed pendant to Dalar Dawnweaver at the Sepulcher.", description = "Take the pendant to Dalar Dawnweaver, perhaps he can shed some light on the wizards' plans.", progress = "Yes, <class>? What is it?", completion = "Interesting, more machinations of the Kirin Tor, it would seem. This is a powerful artifact. It was used frequently by powerful wizards of the Kirin Tor to channel magical energies.\n\nThat they are delivering so many to Ambermill indicates that they must be undergoing a project of some magnitude.\n\nI will see if I can pierce their shields and ascertain their intent.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][482] = {title = "Dalaran's Intentions", objective = "Speak with Shadow Priest Allister at the Sepulcher.", description = "Of course! How could I have forgotten?\n\nAmbermill was one of the sites earmarked by the Kirin Tor, noted because it houses a dormant ley energy node. The wizards must be planning to reactivate the node and use its energies for some greater purpose.\n\nWe cannot allow this to happen...\n\nIt will take a great amount of power to activate the area's ley energies, we can stall them by taking the pendants away from the wizards.\n\nRelay this information to Allister, he will decide a course of action.", progress = nil, completion = "Ill news you bring, &lt;name&gt;. If Dalar is correct--and I've no reason to believe he isn't--we must move quickly.\n\nI must confer with him on our plan of attack. But in the meanwhile we will have to delay their progress.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][483] = {title = "The Relics of Wakening", objective = "Retrieve the Relics of Wakening and bring them to Athridas Bearmantle in Dolanaar.", description = "Gnarlpine invaders were seen ravaging the Ban'ethil Barrow Den to the west.\n\nThe slumbering druids will be trapped in the Emerald Dream for eternity, unaware of their fate, unless we help. The delicate hibernation ritual cannot be broken without the Relics of Wakening.\n\nJourney to the Den and retrieve the Raven Claw Talisman, Black Feather Quill, Sapphire of Sky, and Rune of Nesting. The druids store them in sacred chests.  Return them to me and I will prepare the awakening ritual.", progress = "<name>, the kidnapped Druids of the Talon will be forever trapped in the Emerald Dream if we cannot retrieve the Relics of Wakening from the Ban'ethil Barrow Den to the west.\n\nFor every minute we delay their fate comes one step closer to eternal doom.", completion = "You have succeeded, young &lt;class&gt;!  Well done.  And just in time I might add.", rewards = "You will be able to choose one of these rewards:\n\nBarkmail LeggingsGritroot Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][484] = {title = "Young Crocolisk Skins", objective = "Obtain 4 Young Crocolisk Skins for James Halloran in Menethil Harbor.", description = "I'm James Halloran, the tanner. My cured crocolisk skins are sought after all over, shipments leaving by boat to ports around the world.\n\nMet Einar? He's one of the hunters that brings crocolisk skins in for me.\n\nI'm a bit short on the softer skins that come off crocolisk young.\n\nBeing that I'm running low, I'll pay you top coin for a stack of the skins. You can find the young crocs in the marshes right outside of town.", progress = "<name>, right? Do you have my skins?", completion = "Nice work you've done here, &lt;name&gt;. The quality of these skins is superb. I'll have to get them into the curing process as soon as possible. Oh, but before I get to that, there's some other work I need done that I think you might be able to take care of.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][485] = {title = "Find OOX-09/HL!", objective = "Take the distress beacon to Oglethorpe's homing robot at the head of the river in the Hinterlands, near Skulk Rock.", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it crashed at the head of the river near Skulk Rock!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-09/HL is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][486] = {title = "Ursal the Mauler", objective = "Kill Ursal the Mauler and return to Athridas Bearmantle in Dolanaar.", description = "Now the time has come to save the Druids of the Talon. If we fail now, <name>, they will be forever lost in sleep.\n\nI shall prepare the Relics of Wakening and perform the ritual. For my work to take effect, the cursed beast responsible for this horrible situation must be slain.  Only then will the ritual be complete.\n\nIt was Ursal the Mauler who meddled with our brethren's calling and it is Ursal the Mauler who must now pay so they can be freed.  Travel to Gnarlpine Hold in the southwest and slay him.", progress = "Our brethren cannot be awakened until Ursal the Mauler has been slain, <name>.", completion = "&lt;name&gt; you have proven yourself a most worthy and able &lt;class&gt;.  A &lt;race&gt; who follows the path of honor as sure as you do is certain to find great glory in this world.\n\nMay the forest spirits protect you wherever your travels may take you.", rewards = "You will be able to choose one of these rewards:\n\nDefender AxeThornroot Club\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][487] = {title = "The Road to Darnassus", objective = "Slay 6 Gnarlpine Ambushers and return to Sentinel Amara Nightwalker outside of Dolanaar.", description = "The road to Darnassus must be kept safe.  Travelers heading from Dolanaar to Darnassus have been reporting ruthless attacks by corrupted furbolgs from the Gnarlpine tribe.\n\nImportant news and commerce travels to and from Darnassus by way of this road daily.  We cannot afford to have a rogue band of heathens terrorizing people.\n\nTake up arms in the name of the sacred forest, <class>.  Their den lies somewhere below this vantage point.  Slay 6 of these Gnarlpine ambushers and report back to me.", progress = "The road is still not safe, <class>. Travel forth and slay 6 Gnarlpine Ambushers and return to me.", completion = "You have served the good people of Dolanaar and Darnassus well, brave &lt;class&gt;.  As a member of the Sentinel force of Teldrassil I salute your efforts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][488] = {title = "Zenn's Bidding", objective = "Bring Zenn Foulhoof outside of Dolanaar 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.", description = "Eager for work, I see.  Lucky for you a day never goes by that I don't wish I had a fledgling <class> to perform my bidding.\n\nYou see, <name>, I can make you very happy and provide you with things you never dreamed of having.  But in order for that to happen you must bring me certain items.\n\nMy business in the forest often requires certain. . .reagents.  Fetch for me 3 Nightsaber Fangs, 3 Strigid Owl Feathers and 3 swatches of Webwood Spider Silk.\n\nLet's keep this our little secret, <race>.", progress = "Have you been a busy little bee, <name>?  I've been waiting for you to bring me what I need.", completion = "Ha ha!  Well, done indeed.\n\nWho would have ever guessed that I, Zenn Foulhoof, would have a &lt;race&gt; to do my bidding?  Certainly not me!  But so it goes... this beloved world of ours is full of surprises.\n\nThree cheers for the naive and gullible!", rewards = "You will receive:\n\nSevered Voodoo Claw"}
MultiLanguageQuestData['en'][489] = {title = "Seek Redemption!", objective = "Collect 3 Fel Cones and give them to Zenn Foulhoof outside of Dolanaar.", description = "The Council of the Forest has news that you aided Zenn Foulhoof. The satyr is an enemy of the forest. As a <race>, you should know better than to defile the forest by killing Nature's creatures.\n\nYou must redeem yourself in the eyes of the Council if you wish to remain a friend of Teldrassil.\n\nTeach Foulhoof a lesson and you shall be redeemed. Fel Cones are corrupted seeds that fall from the trees. They billow with green smoke.\n\nGive some to Foulhoof. He'll think you have brought him a harmless snack.", progress = "What do you have for me, <name>?  A lovely snack I presume?", completion = "Ah, what a sweet &lt;race&gt;!  I knew you would come in handy!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][491] = {title = "Wand to Bethor", objective = "Take the Woven Wand to Bethor Iceshard in the Magic Quarter of the Undercity.", description = "Thule once told me that, long ago, he and two colleagues created a magic wand, woven together from the apprentice wands each mage possessed.  This wand was a symbol of their friendship, and although Thule came to despise it he could not part with it, nor could he let the others have it.  So he stole the wand, and hid it in Fenris Keep.\n\nHere.  Take the wand to Bethor Iceshard, one of Thule's friends from years past.  I'm sure he will want it.", progress = "<name>.  Have you defeated Thule Ravenclaw?", completion = "...what is this?  Thule had our Woven Wand?  I thought it was lost when our friendship sundered and he sided with the Lich King!\n\nHe must not have invoked its power, for if he had I would have sensed it.  And it is good that he did not use it...\n\nThis is a marvelous find.  You have my gratitude, &lt;name&gt;, and will be rewarded.", rewards = "You will be able to choose one of these rewards:\n\nStamped TrousersRugged Mail GlovesSerrated Knife\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][492] = {title = "A New Plague", objective = "Bring Johaan's Special Drink to the Captured Mountaineer.", description = "According to the Deathguard, another one of those foolish Dwarven Mountaineers has just been captured.  The Deathguard likes to use the cellar of the Gallows End Tavern as a holding cell until prisoners can be \"properly\" dealt with.\n\nWhy don't you go see how the Captured Mountaineer enjoys this special drink I made for him?  It contains a subtle hint of what The Dark Lady has planned for the rest of Azeroth.", progress = "Why if I had my trusted rifle you'd be as good as dead, <class>.  Just wait until the Steam Tank Brigade arrives to rescue me!", completion = "Ah, a drink at last.  I'm sure it's no Rhapsody Malt but I'll take anything to whet the old whistle at this point.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][493] = {title = "Journey to Hillsbrad Foothills", objective = "Deliver Apothecary Renferrel's findings to Apothecary Lydon in the town of Tarren Mill in the Hillsbrad Foothills.", description = "The Royal Apothecary Society is under extreme pressure from the Dark Lady to develop a New Plague.  We are working diligently and have made much progress.  It is our belief that the success will be achieved much faster if we share information amongst the Society.\n\nFor that reason I want you to deliver my latest findings to Apothecary Lydon in Tarren Mill, a small town nestled in the Hillsbrad Foothills.  The journey will be a long one.\n\nHead south and stick to the roads.  Follow the signs closely!", progress = "You have something for me?", completion = "Ah, most excellent.  Apothecary Renferrel has my utmost respect.  I am anxious to study his work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][494] = {title = "Time To Strike", objective = "Travel to Tarren Mill to deliver Deathstalker Lesh's message to High Executor Darthalia.", description = "Be silent and pay attention, <class>.\n\nI was sent to this position in order to survey the town of Hillsbrad.  My mission is one of reconnaissance.  It is imperative that you send word to High Executor Darthalia in Tarren Mill at once.  Let her know that I, Deathstalker Lesh, send the following message:\n\n\"The raven's cry from the west doth beckon.\"\n\nFollow the road to the east and pay close attention to the signs.  Now, hurry!  Off you go to Tarren Mill, and with urgency I might add!", progress = nil, completion = "The raven's cry from the west doth beckon?\n\nSuperb news!  Hillsbrad is ripe for attack.  We can carry out our plan of destruction now.  Varimathras will be pleased.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][495] = {title = "The Crown of Will", objective = "Report to Melisara at Tarren Mill in the Hillsbrad Foothills.", description = "Mug'Thol and his ogre warband was sent to Alterac to retrieve the Crown of Will for Lady Sylvanas. Unfortunately, instead of returning it, the idiot decided to try it on... I suppose ogres can't resist anything bright and shiny.\n\nHis bumbling actions have become something of a problem, however. The Crown of Will enabled him to resist the possession placed upon him to serve Lady Sylvanas.\n\nThe Dark Lady wants an example made, travel to Tarren Mill in Hillsbrad and report to Melisara, my lieutenant.", progress = nil, completion = "You were sent by Shalindra? Very well then, you'll find I don't waste much time with idle chatter.\n\nMug'Thol is an irritant, and we will deal with him quickly, thoroughly, and without incident.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][496] = {title = "Elixir of Suffering", objective = "Apothecary Lydon of Tarren Mill wants 10 Gray Bear Tongues and some Creeper Ichor.", description = "Ah, another wretched day in Tarren Mill.  All of this clean air puts me in such a foul mood, <name>.\n\nThe sooner we can plague the humans here, the better.  I've been conducting intense studies on possible killing agents to use in my concoctions but I haven't the time to collect them all.\n\nIf you want to make yourself of use, procure the following items for me:  10 Gray Bear Tongues and the very rare and hard to find, Creeper Ichor.  You'll find both bears and creepers just outside of Tarren Mill.", progress = "I see you are back.  I hope you were able to gather the agents I need.  Another deathless day will put me in such a gloomy mood.", completion = "These specimens are perfect.  Well, &lt;name&gt;, you have managed to bring me the slightest hint of joy on yet another miserable day.  Your efforts are appreciated.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][498] = {title = "The Rescue", objective = "Krusk in Tarren Mill needs you to free Drull and Tog'thar from Durnholde Keep.", description = "Me and some other warriors were sent by the Warchief to retrieve an object from Durnholde and to investigate this so-called Syndicate.\n\nWe went to Durnholde to take a look around, but we were taken by surprise by a large number of the humans. We fought bravely, but their sheer numbers were enough to defeat us. They took a few of us captive, but I was able to escape.\n\nDurnholde is just southeast of here, across the river. Drull and Tog'thar are being held there, you must go and rescue them.", progress = "You must make haste, <class>. I shudder to think what the humans might be doing to Drull and Tog'thar.", completion = "So the humans thought to turn our warriors into slaves, did they? We'll show them!\n\nIt would seem that they have taken Gol'dir, our leader, to another location. We must find him and rescue him. But we currently have no clue where he is...\n\nWhen we have a lead, I will be sure to tell you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nGrunt VestOrcish War Chain\n\nYou will also receive:\n\nRecipe: Big Bear Steak"}
MultiLanguageQuestData['en'][499] = {title = "Elixir of Suffering", objective = "Give Umpi the Elixir of Suffering.", description = "It will take but a moment for me to mix these components into what I have deemed an Elixir of Suffering.\n\nThere we go!  Ah, nothing brightens a gloomy day in these miserable foothills like bringing a little suffering into the world.\n\nLet us see if our little potion has achieved its desired effect.\n\nGive my assistant Umpi a taste of what the Dark Lady has planned for both humans and Scourge alike.", progress = "Ribbit!", completion = "Croak!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][500] = {title = "Crushridge Bounty", objective = "Gather 9 Dirty Knucklebones from Crushridge ogres in the Alterac Mountains. Bring them to Marshal Redpath in Southshore.", description = "Crushridge ogres have dug an ogre mound up in the Alterac Mountains near the ruined city of Alterac.  And my scouts tell me they've taken over those ruins as well.\n\nWe can't let them get cozy up there; if they think they're safe where they are, then their next step will be to move down into the foothills, which will put them right at our front door!\n\nGo north to the Alterac Mountains and hunt ogres.  Bring me the Dirty Knucklebones they carry and you will earn a nice bounty.", progress = "<name>, are you still hunting ogres?  Do you have the knucklebones I had you gather?", completion = "Very good, &lt;name&gt;.  You must have hacked through a whole mess of ogres to get all these knucklebones.\n\nThat should keep them out of our hair.  At least, for a while.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][501] = {title = "Elixir of Pain", objective = "Bring 10 vials of Mountain Lion Blood to Apothecary Lydon in Tarren Mill.", description = "Oh, <name>. . .the flowers are blooming in Hillsbrad and the air is so fresh and brisk.  I can't help but to wallow in the misery of it all.  I look out my grimy window and long for the day when our New Plague brings this world the death it deserves.\n\nAs much as I would love to sit and brood all day, my duty to the Dark Lady calls.  Help me, would you?  My research leads me to believe I can make the most splendid death-brew with the blood of a Mountain Lion.  Bring some to me and we'll have a little fun.", progress = "I remember you, <name>.  You were going to help me out in concocting my latest elixir.  I'll need that blood before I can bring my own special brand of misery to the inhabitants of Hillsbrad.", completion = "Superb collecting, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nGloves of BrawnStomping BootsFirewalker Boots\n\nYou will also receive:\n\nRecipe: Hot Lion Chops"}
MultiLanguageQuestData['en'][502] = {title = "Elixir of Pain", objective = "Feed the Elixir of Pain to Stanley.", description = "Ah, nothing like the smell of fresh blood in the foothills!\n\nNow we'll mix in a touch of this and a little of that and let the real fun begin!  What I have created with this blood, I like to call an Elixir of Pain.  If my calculations are correct this concoction could be the start of something very beautiful for Lady Sylvanas.  But what we need is a test.\n\nTake this elixir out to the northern farm in Hillsbrad Fields to the southwest.  Let's see how Farmer Ray's little dog Stanley likes this \"treat.\"", progress = "Woof?", completion = "You pour some of the elixir into your hand and hold it before Stanley's mouth.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][503] = {title = "Gol'dir", objective = "Free Gol'dir then return to Krusk in Tarren Mill.", description = "From what I can tell of the documents you procured, Gol'dir is being held in a large Syndicate base to the north, most likely in the Alterac Mountains. He has been held captive far too long and must be freed.", progress = "Give me the key, <class>, I will undo the lock myself.", completion = "Thank you, &lt;name&gt;. I led the expedition from Durotar under the Warchief's orders, but as you can see, our plans went somewhat awry. They have held me captive here in this town, forcing me to work, hauling burdens, digging...\n\nWhat I have suffered is unimportant, however. There is important information you must deliver to whomever is leading our group now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][504] = {title = "Crushridge Warmongers", objective = "Slay 10 Crushridge Warmongers, then return to Marshal Redpath in Southshore.", description = "Now that you've had a taste of the Crushridge ogres, I want you to really bloody their noses...\n\nGo into the Ruins of Alterac and seek out the Crushridge Warmongers.  I want you to cut down a good number of them - that's the only way those brutes will learn to keep their distance from Alliance territory.", progress = "You have more Warmongers to slay, <name>.  You should be up on the mountains on your task, not down here with your weapon stowed.", completion = "Very good.  Here is your reward.\n\nAnd when you were hunting those Warmongers, how did Alterac city look?  It's in bad shape I would guess.  Ogres are not known for their cleanliness.\n\nThankfully, your efforts will help keep them away from Southshore.", rewards = "You will be able to choose one of these rewards:\n\nBurning SliverLunar Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][505] = {title = "Syndicate Assassins", objective = "Kill 12 Syndicate Footpads and 8 Syndicate Thieves, then return to Magistrate Henry Maleb in Southshore.", description = "I am the new magistrate of Southshore, recently assigned after the assassination of the previous magistrate.  The assassins were never found, but through our investigations we're almost certain they were hired by the Syndicate - a group of thieves led by villainous nobles of the now fallen kingdom of Alterac.\n\nThe Syndicate has a camps in Sofera's Naze and Corahn's Dagger, north and west of the Horde-occupied Tarren Mill.  Slay the Syndicate members you find in these camps.", progress = nil, completion = "Thank you, &lt;name&gt;.  Although they may still be lurking about, we hope that some of the thieves and footpads you slew were responsible for the last magistrate's death.  But even if they weren't, the Syndicate is a taint on this land and a stain on the human race.  \n\nTheir deaths are welcome to Southshore.", rewards = "You will be able to choose one of these rewards:\n\nCrusader BeltInsulated Sage Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][506] = {title = "Blackmoore's Legacy", objective = "Return the information gathered by Gol'dir to Krusk in Tarren Mill.", description = "A day or two ago, I was visited by the leader of this Syndicate. His name was Aliden Perenolde, and styled himself lord of this land. He confided in me his plans to take the orcs that stood against him as slaves, just as his father and his mentor, the despised Blackmoore, had planned.\n\nMore important was that he brought his mistress, a wisp of a girl named Elysa. Around her neck was the pendant the Warchief desires.\n\nNow go, I will make my own way, after I have settled my business here.", progress = nil, completion = "The nerve of those overbearing humans! We'll show them that the orcs shall never submit to their will!\n\nThis will now be our mission, in addition to recovering the trinket the Warchief desires. It would seem that by accomplishing one, we will also accomplish the other.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][507] = {title = "Lord Aliden Perenolde", objective = "Kill Lord Aliden Perenolde and ask his mistress, Elysa, about Taretha's pendant.", description = "It is clear that Perenolde must be killed, his foulness removed from the world. His manor lies a ways to the north of here, on the shores of Lordamere Lake. Do your duty, <name>, then retrieve the pendant that the Warchief desires, and return here.", progress = "W-what do you want?", completion = "No, no please don't hurt me! I never meant your people any harm, he's had me against my will! Please... spare me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][508] = {title = "Taretha's Gift", objective = "Return Taretha's pendant to Krusk in Tarren Mill.", description = "The pendant? Of course you can have it... Take it! I want no memory of him... just please, please leave in peace...", progress = "You've returned, <name>. Success to report?", completion = "It is strange that the Warchief would expend so much over such a small thing. I do not claim to understand him, but I will follow him, whatever his commands. You did well, &lt;name&gt;, no doubt the Warchief will be glad to hear of your success.", rewards = "You will be able to choose one of these rewards:\n\nMantis BootsBrigand's Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][509] = {title = "Elixir of Agony", objective = "Bring 6 Mudsnout Blossoms to Apothecary Lydon in Tarren Mill.", description = "Another day, another elixir to be made. If it were up to me, I'd just let the pathetic humans and Scourge fight it out.  They seem bent on killing each other as is.\n\nAlas, our Dark Lady wants to help speed up the process a tad so why not pass these morbid days by spreading a little death and disease across the land?\n\nHere's the plan, <name>: you go out to Nethander Stead, south of Tarren Mill and east of the river and Southshore. Collect for me 6 Mudsnout Blossoms from the field for my next elixir.", progress = "Any luck at Nethander Stead?", completion = "Ah, the horrible reek of Mudsnout Blossoms.  At least those filthy Gnolls are good for something.", rewards = "You will receive:\n\nSwiftness PotionHealing Potion"}
MultiLanguageQuestData['en'][510] = {title = "Foreboding Plans", objective = "Bring the Foreboding Plans to Magistrate Maleb in Southshore.", description = "Among these documents is a list of requested supplies.  These include mundane items (food, weapons, clothing) as well as more exotic gear (masks, oil, poison).\n\nBut what is most notable is the urgency of the request - these supplies were needed soon in order to undertake what is described in the document as an \"important mission against Southshore.\"", progress = "<name>, you look anxious.  Is there something you wish to tell me?", completion = "&lt;Maleb reads the documents.&gt;\n\nThese are very troubling, &lt;name&gt;.  From the information in these documents, and from the Syndicate's actions in the past, we must assume that band of cutthroats has waged war on Southshore.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][511] = {title = "Encrypted Letter", objective = "Bring the Encrypted Letter to Loremaster Dibbs in Southshore.", description = "One of the letters on this table is encrypted and inscrutable.", progress = "Yes, sir?  Do you have some business with me?", completion = "What is this?  Hold a moment...let me take a closer look.\n\n...\n\nHm, I have never before seen this form of encryption, but I must admit that my knowledge in that area is by no means complete.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][512] = {title = "Noble Deaths", objective = "Bring 7 Alterac Signet Rings to Magistrate Maleb in Southshore.", description = "I fear the leadership behind the Syndicate is bent on Southshore's ruin.  We must strike hard at these leaders before their plans are realized.\n\nEnter the ruins of Strahnbrad, in the Alterac Mountains to the north.  We think the Syndicate is using the area as a headquarters.\n\nWe know this gang of cutthroats is run by former Alterac nobles.  They may be hiding as normal Syndicate agents, but you'll know you've killed a noble by the signet ring he wears.\n\nBring me those signet rings.", progress = "Have you been hunting the Syndicate?  Do you have those rings?", completion = "Stripping the Syndicate of its nobility will remove its ability to act decisively, and reduce it to nothing more than a gang of thugs.\n\nYou serve your Alliance well, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][513] = {title = "Elixir of Agony", objective = "Take the Mudsnout Composite to Master Apothecary Faranell in the Undercity.", description = "Just when I thought another day was going to pass devoid of any joy, you brought me those marvelous Mudsnout Blossoms.\n\nFirst I will mix them down into a fine composite.  We'll then need Master Apothecary Faranell in the Undercity to apply his colloid of decay to it and then we'll be ready for some good fun indeed!\n\nHere, take this Mudsnout Composite and run it off to Master Faranell at once, <name>.", progress = "Can you not see I am busy, <class>?  The Dark Lady insists on a new plague before the Scourge advance from Northrend overwhelms us.  And with the human threat pressing from the south, time becomes my most precious commodity.  This better be important!", completion = "Apothecary Lydon sent you?  Ah, why didn't you say so!\n\nDespite his gloomy disposition, Apothecary Lydon is one of our most dedicated and skilled members.\n\nThe good chap sends Mudsnout Composite!  I know what our friend in Hillsbrad is up to now.  And I like the way he thinks.  The Dark Lady would be most impressed with the progress he is making toward the new plague.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][514] = {title = "Letter to Stormpike", objective = "Take the Cleverly Encrypted Letter to Prospector Stormpike in Ironforge.", description = "I have a colleague in Ironforge who may be able to help decrypt this letter.  Go to the Library in the Hall of Explorers in Ironforge and speak with Prospector Stormpike.  Tell him I sent you and show him the letter.  If there's anyone north of Blackrock Spire who can read this, it is he.", progress = "Dibbs from Southshore sent you, did he?  How is the old bookworm doing?", completion = "Ah, encryption!  A specialty of mine.  Let me see here...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][515] = {title = "Elixir of Agony", objective = "Bring the Mudsnout Mixture, a Strong Troll's Blood Potion, 5 Daggerspine Scales and 5 Torn Fin Eyes to Apothecary Lydon in Tarren Mill.", description = "A mudsnout composite?  Absolutely brilliant!  Why didn't I think of that?\n\nLet me contribute my colloid of decay to this devilish brew.\n\nIn order to activate the contaminating agents in this mudsnout mixture, Lydon is going to need a strong troll's blood potion, as well as some daggerspine scales and torn fin eyes from the southern coast of Hillsbrad.  He'll know what to do once you've gathered him all the reagents.  And my, how anxious I am to hear how his experiment goes!", progress = "So glad to see you back, <name>.  I was growing so terribly bored here.  Not a single entertaining thing to do besides poison and disease Umpi and reanimate her. . .over and over and over again.\n\nHow went the trip to the Undercity?  Were you fortunate enough to slaughter any humans along the way?", completion = "The excitement of this experiment has me feeling giddy!  You have been such a great help, &lt;name&gt;.  Together we will spread death and disease to this land!", rewards = "You will be able to choose one of these rewards:\n\nHigh Apothecary CloakMeditative Sash\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][516] = {title = "Beren's Peril", objective = "Locate Beren's Peril, then kill 6 Ravenclaw Drudgers and 6 Ravenclaw Guardians, then return to Shadow Priest Allister at the Sepulcher.", description = "I have received reports that a group of undead are holing up to prepare for an attack against us. Armed with this information, we can turn the tables and attack them first, nipping their little plan in the bud.\n\nUnfortunately, my information is spotty, at best. They are reported to be hiding in a location known as Beren's Peril. The exact location is unknown, but it appears to be a cave in the hills, near a pocket of Dalaran wizards.\n\nI trust your resourcefulness. Find them, and put them down.", progress = nil, completion = "If our scouts and agents continue to procure valuable information such as this, we shall have the Lich King's Scourge removed from our lands in no time.", rewards = "You will receive:\n\nWand of Decay"}
MultiLanguageQuestData['en'][517] = {title = "Elixir of Agony", objective = "Bring a keg of Shindigger Stout to Apothecary Lydon in Tarren Mill.", description = "This new elixir is finally ready to be tested.  But why let a perfectly good, highly contagious plague go to waste on a mere frog or dog?  Let's have us some true fun in the name of Lady Sylvanas.\n\nHead down to Dun Garok.  You know the barracks where those filthy little dwarves skitter about.  Steal me a keg of their Shindigger Stout.  Once I have that keg, you and I will have quite the party, <name>.", progress = "Sometimes I get so bored out here in Tarren Mill I like to open up the formaldehyde jar and let the lovely aroma waft through the air.  Makes Umpi a little nervous though.\n\nSo were you able to get a keg from the Dwarves?  I swear if I have to stare at this deadly elixir without using it on someone for another day I am going to scream.", completion = "Finally!  Now we are ready for action!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][518] = {title = "The Crown of Will", objective = "Kill 10 Crushridge Maulers for Melisara in Tarren Mill.", description = "Mug'Thol and his Crushridge ogres have overrun the ruins of Alterac. It will be hard to inflict any serious punishment upon him without thinning out the ogres' numbers.\n\nAfter softening them up, we'll proceed.\n\nUnderstood? Good. Now go.", progress = "I note that your task is unfinished, <name>. Shall I inform Sharlindra of your ineptitude?", completion = "The snow blooms red with the blood of the ogres, but we cannot cease our efforts until the spirit and numbers of the Crushridge have been crushed and ground into the dirt and snow.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][519] = {title = "The Crown of Will", objective = "Kill Targ, Muckrake, and Glommus and bring their heads to Melisara in Tarren Mill.", description = "Targ, Muckrake, and Glommus are Mug'Thol's lieutenants. They are loyal to him, though who can say what drives an ogre to loyalty.\n\nBring me their heads, <name>, and then all that will remain is to remove Mug'Thol's head, crown and all.", progress = "I want their heads, <name>, not excuses.", completion = "...and I thought ogres smelled foul enough to begin with.\n\nWhen you bring me Mug'Thol's head, I will have the four of them mounted on pikes above Alterac. A fitting monument to those who go against the Dark Lady's wishes.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][520] = {title = "The Crown of Will", objective = "Kill Mug'Thol, and return his head with the Crown of Will to Melisara in Tarren Mill.", description = "With Mug'Thol's lieutenants dead, all that remains is to kill Mug'Thol and retrieve the Crown of Will. I have no doubt he'll be reluctant to part with it. Most likely expecting you, too, given the... departure... of his fellows.\n\nFind Mug'Thol, and deliver his head and the Crown to me. The Crushridge resistance will be at an end.", progress = "Three heads I have, a fourth I need. It will be Mug'Thol's, or it will be yours, <name>. That I promise.", completion = "You have done your duty well, &lt;name&gt;. Mug'Thol's head shall adorn the highest peak of the ruins of Alterac, and the Deathguard will sweep the remnants of the Crushridge into the ground.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][521] = {title = "The Crown of Will", objective = "Deliver the Crown of Will to Sharlindra in the Undercity.", description = "All that remains is to deliver the Crown of Will to Sharlindra in the Undercity. She will see that it is delivered to Lady Sylvanas. I would warn you against thinking to use it for your own purposes, <name>, Mug'Thol's fate should be illustration enough.", progress = "Yes? Do you have something to report?", completion = "So this is the relic the ogre used to duck the will of the Dark Lady...\n\nStrange that something so simple could wield so great a power. And to fall into as clumsy hands as those. Well done, &lt;name&gt;, I will deliver the crown to Lady Sylvanas, and see that she hears of your accomplishment.", rewards = "You will receive:\n\nEthereal Talisman"}
MultiLanguageQuestData['en'][522] = {title = "Assassin's Contract", objective = "Bring the Assassin's Contract to Magistrate Maleb in Southshore.", description = "This is a contract for the assassination of Magistrate Henry Maleb.  It was sealed and stamped in red wax, using a distinctive signet ring.", progress = "You look out of breath!  Do you have something to report?", completion = "&lt;Maleb inspects the contract.&gt;\n\nThat explains the latest attack on Southshore.  The Syndicate must be after me, just as they were the last magistrate!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][523] = {title = "Baron's Demise", objective = "Bring the Head of Baron Vardus to Magistrate Maleb in Southshore.", description = "The contract you recovered was signed by Baron Vardus, a noble of the former kingdom of Alterac, and one known for a cold heart and brutal practices.  I'm not surprised someone like the Baron was behind this.\n\nFind this man.  Find him, and bring him to justice.  He must be among the Syndicate haunts - perhaps at the ruins of Strahnbrad, or perhaps within the valley north of them.", progress = "Baron Vardus cannot think Southshore will allow him to send his thugs against us with impunity.  I want his head!", completion = "Thank you, &lt;name&gt;.  My head rests a little easier, knowing that villain lost his.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][524] = {title = "Elixir of Agony", objective = "Place the Tainted Keg on the rug for the captured farmers.", description = "Next door the Deathguards are holding a few captured farmers hostage.  High Executor Darthalia suspected one of the military strategists from Stormwind to be hiding out amongst them.  Apparently the military chap was found dead in the Plaguelands last night.  Darthalia, always looking out for me, decided the prisoners would be left to my disposal.\n\nI think it's time we threw those farmers a party.  Sounds like a grand ol' time!\n\nPlace this tainted keg on the rug in their room.  Plagued brew for all!", progress = "A musty smell emanates from the rug.", completion = "You rest the tainted keg on the dusty rug.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][525] = {title = "Further Mysteries", objective = "Bring the Decrypted Letter to Magistrate Maleb in Southshore.", description = "I decrypted the letter, but I don't know what to make of it.  You found this among thieves in the Alterac foothills?  Very strange...\n\nYou should take this to the magistrate of Southshore.  Although this letter is cryptic, his is the closest town to Alterac; if a threat is brewing, then he should know.", progress = "<name>.  Have you been traveling through the foothills and mountains again?  What news do you bring?", completion = "&lt;Maleb reads the letter.&gt;\n\nThis is translated from a letter you found in a Syndicate encampment?  This was not written by a thief, or even a noble of Alterac.\n\nIt appears The Syndicate has ties to another power, and I shudder to think what that might be.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][526] = {title = "Lightforge Ingots", objective = "Gather 5 lightforge ingots, then return to Glorin Steelbrow in the Wetlands.", description = "You might have found one lightforge ingot in that chest, but that's not enough to craft anything decent!\n\nYou should go back there and look for more.  Maybe the murlocs around that wrecked ship have lightforge ingots on them.", progress = "Did you find the lightforge iron you need?", completion = "Ah, you found them!  Now let's get this lightforge iron hammered into something useful, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][527] = {title = "Battle of Hillsbrad", objective = "Kill 6 Hillsbrad Farmhands, 6 Hillsbrad Farmers, Farmer Ray and Farmer Getz and report back to Darthalia in Tarren Mill.", description = "Stand at attention while addressing me, <class>.\n\nI am under direct command of Varimathras.  We are to quell the human infestation until our apothecaries can develop the new plague.\n\nOur information leads us to believe that the town of Hillsbrad is vulnerable to attack.  Your first assignment is aimed at disrupting their food supply and infrastructure.\n\nTravel west.  Raid the northernmost farms of Hillsbrad Fields.  Make sure that the landowners, Farmer Ray and Farmer Getz, are executed as well.", progress = "As High Executor of Tarren Mill, under the direct command of Varimathras and the Dark Lady, you are subject to follow my command.\n\nPerhaps you take this war with the Alliance lightly?  If such is the case I should behead you right here and now.  Otherwise, travel west to the town of Hillsbrad and wage battle against the humans, as ordered.\n\nDismissed.", completion = "At ease, &lt;class&gt;.  I see you have returned from battle.  My sources tell me you performed well on the Hillsbrad front.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][528] = {title = "Battle of Hillsbrad", objective = "Kill 15 Hillsbrad Peasants and report back to Darthalia in Tarren Mill.", description = "Word of the attack on the northern farms has the townsfolk panicked.  Most excellent.\n\nOur Deathstalkers report peasants fleeing to the fields in southern Hillsbrad.  The fools think they can hide in the orchards and escape their doom.\n\nProve them wrong, <name>.  Return to Hillsbrad Fields and seek out the cowering peasants.  Lay waste to them in the name of our Dark Lady.\n\nDismissed!", progress = "You have your orders, <class>.  Quit dawdling here in Tarren Mill when there is work to be done elsewhere.", completion = "The grip of death is tightening around the town of Hillsbrad.  The battle goes well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][529] = {title = "Battle of Hillsbrad", objective = "Kill Blacksmith Verringtan and 4 Hillsbrad Apprentice Blacksmiths.\n\nRetrieve a shipment of iron and report back to Darthalia in Tarren Mill.", description = "The humans of Hillsbrad have been putting up unexpected resistance.  The problem appears to be that the townsfolk are being armed by the local blacksmith.  We need to shut down all supply lines.\n\nYour mission will be to execute Blacksmith Verringtan.  Slay his apprentices as well.  While there, bring back a shipment of iron from their stockpile.  The supplies will come in handy when we are done with the conquering of Hillsbrad and begin razing Southshore.", progress = "Were you able to carry out your orders, <class>?  Did you dispose of Verringtan and his assistants?  And where is that iron shipment?", completion = "Mission accomplished, &lt;class&gt;.  And carried out quite skillfully, I might add.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][530] = {title = "A Husband's Revenge", objective = "Kill Valdred Moray.\n\nBring his hands to Raleigh Andrean in the Undercity.", description = "Valdred, once my good friend, was my wife's murderer.  Although I am incapable of grieving, I do yearn for revenge.  If you kill Valdred and bring me his cursed hands, then I will reward you.\n\nI last heard he was at the Greymane Wall in southern Silverpine, trying to flee into the kingdom of Gilneas.", progress = "Do you have those hands, <name>?", completion = "Ah, good.  These hands killed my wife, Deliah.  Revenge for her murder was my only care, and you were the instrument of that revenge.\n\nHere, take the ring you returned earlier.  Deliah has been dead to me for so long, her ring is a bauble I no longer care to keep.  Instead, I will keep these hands as a remembrance of my friend's betrayal.", rewards = "You will receive:\n\nRing of Scorn"}
MultiLanguageQuestData['en'][531] = {title = "Vyrin's Revenge", objective = "Bring Ol' Sooty's head to Vyrin Swiftwind at the Farstrider Lodge.", description = "Light! Don't bring things like that into the Lodge... it's unsanitary, unspeakable, un... un... unsanitary!\n\nJust get it out of here, will you? No one wants to see your bloody little trophy, really!", progress = "Great job, <name>! We really showed him! Here, give me the head and I'll take care of it.", completion = "Thanks for helping me out with my little plan, &lt;name&gt;. I've been itching for months to get back at that snooty, stuck-up boy, and I'd say we did a pretty good job! Here, have this, you've earned it.", rewards = "You will be able to choose one of these rewards:\n\nHunting Ammo SackHunting Quiver\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][532] = {title = "Battle of Hillsbrad", objective = "Kill Magistrate Burnside and 4 Hillsbrad Councilmen. Destroy the Hillsbrad Proclamation. Steal the Hillsbrad Town Registry. Report back to Darthalia in Tarren Mill afterwards.", description = "The town of Hillsbrad is in disarray and we believe it will soon fall.  We must, however, persist in our ruthlessness until the human scum are wiped from the foothills for eternity.\n\nDespite their overwhelming losses, the humans rally around their leadership and keep fighting.  We must eliminate their leader, Magistrate Burnside, as well as the town council.  Destroy their revered political document as well, the Hillsbrad Proclamation.  And while you're at it, steal the town registry.", progress = "What news have you?", completion = "News of your glories in Hillsbrad traveled fast.  You have done well, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][533] = {title = "Infiltration", objective = "Retrieve information about Gol'dir's whereabouts for Krusk in Tarren Mill.", description = "At last we begin to hear word and rumor, find evidence of Gol'dir's whereabouts. The humans have been moving him around, but we are narrowing down our search and focusing on the large Syndicate camp just north of here.\n\nGo there, <name>, and bring back whatever information you can get your hands on.", progress = "Have you found anything? I fear Gol'dir's prospects grow worse by the day...", completion = "Finally, we know where Gol'dir is being held. The camp in question is not too far from here, and hopefully they will not be as well prepared as they were when they captured us the first time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][535] = {title = "Valik", objective = "Bring a mug of Southshore Stout to Valik in the Syndicate camp.", description = "Urrgh... Injured and dying and confronted with the enemy.\n\nNo doubt you'll kill me anyway, but if you bring me some Southshore stout--your kind does drink, don't they?--I'll tell you what you want to know.", progress = "Did you bring me something to drink or did you just come back to finish the job?", completion = "Given my impending death, I think I can safely say that this is the sweetest tasting thing ever... Here, take this, won't do me any good when I'm dead.\n\nWell, get on with it!", rewards = "You will receive:\n\nSyndicate Missive"}
MultiLanguageQuestData['en'][536] = {title = "Down the Coast", objective = "Kill 10 Torn Fin Tidehunters and 10 Torn Fin Oracles for Lieutenant Farren Orinelle in Southshore.", description = "Transferred from the Stormwind city guard to Southshore, a town that should be abandoned by the looks of it... Smell of the harbor day and night.\n\nNot to mention ol' Redpath... Wants me to take care of the murlocs. Ha! \n\nI can barely rouse myself to go out to some of the pockets of the overgrown fish down the Western Strand. If you would go in my place and take care of them, I'd appreciate it.", progress = "Another ale, please, the last one just seemed to have disappeared!\n\nLight, how much longer am I going to be stuck out here?\n\nOh, it's you, <name>. Have you killed those murlocs yet?", completion = "I hope this will be enough to convince Redpath that I've--ha!--been carrying out his orders and ridding Southshore of the terrible and horrible menace of the dreaded murlocs! For there could be no greater evil than the ravages of overgrown fish!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][537] = {title = "Dark Council", objective = "Kill 4 Argus Shadow Mages.\n\nBring the Head of Nagaz to Magistrate Maleb in Southshore.", description = "The letter you brought me was written by a being who calls himself Nagaz, a member of the Argus Wake.  I don't know what this Argus Wake is, but if they're in alliance with the Syndicate then they must be a threat.\n\nI want you to find Nagaz and the Argus Shadow Mages mentioned in that letter.  I want you to find them, and kill them.\n\nSearch in the Uplands, where the Syndicate is strongest.  It is north of Strahnbrad.\n\nWith luck, you'll find these envoys of the Argus Wake there.", progress = "Did you find the envoys of The Argus Wake?", completion = "Well done, &lt;name&gt;.  The Argus Wake does not sound like a group we want running the Syndicate.\n\nAnd although you may have destroyed their leader here, Nagaz was merely the servant of another.  The Argus Wake might run deep through the continent of Azeroth.\n\nOr even the world.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][538] = {title = "Southshore", objective = "Speak with Loremaster Dibbs in Southshore.", description = "<name>.  If you don't mind a long journey then I have a task for you, to again help Stormwind fill its library.\n\nThe old kingdom of Alterac fell after the great war, and it had a large collection of books.  It's a tragedy that the city is ruined, but even more tragic is all of their knowledge lost!  We must recover what we can.\n\nSouthshore is the closest town to the Ruins of Alterac.  Go there and speak with Loremaster Dibbs.  He can direct you to the ruins, and to what books may be found there.", progress = nil, completion = "Ah yes, I remember Milton.  A bookworm, no doubt.  Bless him.\n\nAnd he's right.  The Ruins of Alterac still hold stores of knowledge in danger of being lost!\n\nOgres now dwell in Alterac, and they don't care much for higher learning.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][539] = {title = "Battle of Hillsbrad", objective = "Kill Foreman Bonds and 10 Hillsbrad Miners and report back to Darthalia in Tarren Mill.", description = "The Hillsbrad Town Registry indicates that the Azureload Mine is under Alliance control.  Furthermore, the mine is a prime source of iron ore for the Alliance armories.\n\nEven though we've struck a decisive blow to the town of Hillsbrad, the Alliance still supports and protects the Azureload Mine fervently.\n\nThe mine lies due south of Hillsbrad.  Go there and slay the foreman, a human by the name of Bonds.  Kill his miners as well.  That should send a clear message to the Alliance.", progress = "You were given direct orders to attack the Azureload Mine.  Your reasons for loafing about Tarren Mill better be good or I will behead you for treason.", completion = "The Dark Lady will be pleased when she learns that she has a new mine from which she can arm her soldiers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][540] = {title = "Preserving Knowledge", objective = "Bring 5 Recovered Tomes and the Worn Leather Book containing The Arm of Gri'lek to Loremaster Dibbs in Southshore.", description = "Those beastly ogres now reside within Alterac's ruins, and I shudder to think what they're doing with the precious books still there.  You must recover what you can!\n\nEnter the Ruins of Alterac and search for tomes looted by the ogres.  Get whatever you can find and bring them to me, but also seek out one book in particular: The Arm of Gri'lek.  It contains ancient troll lore that I must learn, and the Ruins of Alterac was the last known location of an intact copy of this book.", progress = "I wish I could search the ruins too, but I fear these bones wouldn't hold me during my climb up the mountains.  However, how does your hunt for knowledge progress, <name>?", completion = "Oh, you got them!  Splendid!  I must begin studying the Arm of Gri'lek immediately!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][541] = {title = "Battle of Hillsbrad", objective = "Travel to Dun Garok and kill 8 Mountaineers, 4 Riflemen, 2 Priests and Captain Ironhill and report back to Darthalia in Tarren Mill.", description = "Dwarves aiding the humans?  Damn those filthy little beasts.\n\nWe shall test the strength of the so-called Alliance.  We'll see how anxious those little ankle-bashers are to help the humans once they feel our wrath.  We know exactly where their stronghold is in this territory.\n\nThey have established a barracks in southeastern Hillsbrad along Thoradin's Wall called Dun Garok.  The final mission of this battle is to lay siege on Dun Garok, <class>.  Captain Ironhill, their leader, must die.", progress = "Dun Garok proves to be too much of an obstacle for you, <class>?  And here I thought you had established yourself valiantly in Hillsbrad.\n\nIf you're not up to handle the mission assigned to you, I will find another who can produce better results.  As for you, well, I am sure the Dark Lady could always use more grave diggers back in Tirisfal Glades.", completion = "Your actions on the battlefield are worthy of the highest praise.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][542] = {title = "Return to Milton", objective = "Bring the Tomes of Alterac to Milton Sheaf in Stormwind.", description = "I need to spend some time studying the Arm of Gri'lek book you brought me, though I'm sure Milton is eager to get the other recovered books into Stormwind's collection.\n\nHere are the books you gathered from the Ruins of Alterac, packed and catalogued.  Take them back to Milton Sheaf in Stormwind and I'm sure he'll be grateful.", progress = "<name>, you've returned!  How did your foray into Alterac go?  Did you bring anything back with you?", completion = "My oh my!  Look at these!  I can't believe they survived the ruination of Alterac.  And all those ogres too!\n\nThank you, &lt;name&gt;.  Thank you so much!  You have helped preserve human knowledge, and you add to the grandeur of the Royal Library of Stormwind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][543] = {title = "The Perenolde Tiara", objective = "Bring the Perenolde Tiara to Remington Ridgewell in Stormwind.", description = "The Perenolde Tiara is an old heirloom of the Perenolde \"nobles\" - the ruling family of Alterac before that kingdom fell to ruin.  It is said to have been crafted by master jewelers in Ironforge, and fitted with the finest of emeralds.\n\nWhen Alterac was destroyed the Tiara was lost, but there are rumors that an Ogre Mage, Grel'borg the Miser, found the tiara and now wanders the Ruins of Alterac searching for more treasures.\n\nWe would have you acquire the tiara for us.", progress = "Salutations, <name>.  Do try to avoid stepping on my pant cuffs.  This outfit is newly tailored.", completion = "Ah, this is splendid.  This will have to be cleaned of course, but you really outdid yourself, &lt;name&gt;.  I will have someone prepare the tiara and place it within our collection posthaste.\n\nAs I'm sure you will agree, our gratitude is as grand as our collection.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][544] = {title = "Prison Break In", objective = "Find the traitors and recover their artifacts, then return to Magus Voidglare in Tarren Mill.", description = "I came to Tarren Mill to research, but now must resolve a crisis.  You see, four Forsaken fled the Undercity a few months ago.  They turned their backs on their brethren, but what's worse...they stole from the Dark Lady.\n\nThese thieves broke into a secure vault and stole four artifacts, items our apothecaries required in certain studies.  Sylvanas would have these artifacts returned.\n\nThe thieves fled the Undercity to Dalaran, and those wizards quarantined them in the Lordamere Internment Camp.", progress = "Did you find the thieves?  And more importantly, did you find what they stole?", completion = "You have done a great service for the Forsaken, &lt;name&gt;.  These artifacts have been sorely missed.\n\nAnd it is good to hear that Kegan and the other betrayers have found justice.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][545] = {title = "Dalaran Patrols", objective = "Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Voidglare in Tarren Mill.", description = "The wizards of Dalaran constructed a vast, magical dome around the heart of their city.  Some believe it was for protection from the violence of these times, while others say they merely wanted solitude, to study and plot.\n\nI don't care what the reason was.  I do care that the ruined outskirts of their city, outside the dome, may hide valuable magical treasures.\n\nBut the area is patrolled by the wizards and their elemental slaves.\n\nSo hunt them, and return when their numbers are sufficiently reduced.", progress = "Have you yet thinned the Dalaran patrols around their ruins?", completion = "Very good.  Those ruins should now be safe enough to search, if one is careful.\n\nThank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][546] = {title = "Souvenirs of Death", objective = "Deathguard Samsa of Tarren Mill wants 30 Hillsbrad Human Skulls.", description = "I hear you were enlisted by Darthalia to wage war on the humans of Hillsbrad.  So jealous I am. . .\n\nWhile you're off having all the fun -- slaying humans, pillaging the town, terrorizing innocent people -- I am stuck standing guard here in Tarren Mill.\n\nPerhaps you'll take pity on an old Deathguard like myself?  You see I am collecting human skulls.  And you will be fighting humans for quite some time.  Over the course of your long battle, bring me 30 skulls and I will make it worth your while.", progress = "So the lucky <name> returns?  How many humans have you slaughtered today?  Hundreds I do hope!\n\nHave you any skulls for me?", completion = "Precious skulls!  So beautiful!  I owe you as promised, &lt;name&gt;!", rewards = "You will receive:\n\nSkull Ring"}
MultiLanguageQuestData['en'][547] = {title = "Humbert's Sword", objective = "Retrieve Deathguard Humbert's sword from Dun Garok and return it to him in Tarren Mill.", description = "High Executor Darthalia sent me to keep watch of Dun Garok from a distance.  I had set up camp just out of sight.  But when morning came and I had to boil water, I left to gather firewood.\n\nWhen I returned to camp, I discovered my gear was missing.\n\nApparently some dwarven scouts from Dun Garok had passed by and made off with it.  I need my sword!  If you can get it back for me I would be so grateful.  So many dwarves there...it will be quite difficult to find the dirty little thief who stole it.", progress = "Were you able to retrieve my sword, <name>?  High Executor Darthalia will hang me from the rafters if she discovers my folly.", completion = "You found it!\n\nAh, I feel so complete with my precious sword back in my hand.  Many thanks to you!", rewards = "You will be able to choose one of these rewards:\n\nRibbed BreastplateMercenary Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][549] = {title = "WANTED: Syndicate Personnel", objective = "Kill 10 Syndicate Rogues and 10 Syndicate Watchmen. Return to High Executor Darthalia in Tarren Mill for your reward.", description = "By the authority of Lady Sylvanas, all members of the organization known as the Syndicate are wanted dead. Those brought into custody or taken prisoner will be summarily executed. They are currently known to be amassing in the ruins of Durnholde Keep, to the southeast of Tarren Mill.\n\nA handsome reward is offered to all who bring proof of their deeds to High Executor Darthalia.", progress = "Do you have nothing better to do than stand here before me, <class>? As High Executor, I have more pressing matters than to stare at your rotting visage.", completion = "Excellent, &lt;class&gt;. At this rate, the Syndicate pest will be rid from the land in no time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][550] = {title = "Battle of Hillsbrad", objective = "Take Darthalia's Sealed Commendation to Varimathras in the Undercity.", description = "Because you fought with such valor and perseverance in the Battle of Hillsbrad, I have written this commendation, extolling your heroics in combat for the high command to recognize.\n\nTake this sealed commendation to Varimathras in the Undercity.  Go with pride, <class>.", progress = "What brings a <class> all the way to the Undercity from the battlefield?", completion = "So you are the infamous &lt;class&gt; who struck such a decisive blow against the Alliance forces in the Hillsbrad Foothills?  Word of your glorious exploits traveled quickly to the Undercity.\n\nYou have quite a future in the Dark Lady's ranks if you continue to show such leadership and expertise in battle.\n\nWhile our primary threat is the Lich King's Scourge army descending from the north, the human \"problem\" continues to impede our battle plans.  You, however, have shown that the humans can and will fall.", rewards = "You will be able to choose one of these rewards:\n\nSacred Burial TrousersDeadskull ShieldRunic Darkblade\n\nYou will also receive:\n\nBand of the Undercity"}
MultiLanguageQuestData['en'][551] = {title = "The Ensorcelled Parchment", objective = "Take the Ensorcelled Parchment to Loremaster Dibbs in Southshore.", description = "This parchment is enchanted with a spell, rendering it indecipherable.  But one word at the top of the paper can be read:\n\n\n      Nagaz\n\n", progress = "Oh.  You have something you'd like me to look at?  Some scrap of lore gathered from up in the mountains, I hope...", completion = "More encrypted notes?\n\nI wish I had the talents to decrypt all the strange bits of writing that trickle down from Alterac.  But I'm afraid I lack the knowledge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][552] = {title = "Helcular's Revenge", objective = "Retrieve Helcular's Rod from the Yeti and bring it back to Novice Thaivand in Tarren Mill.", description = "Master Helcular was almost complete with his transformation into a Lich when a human lynch mob discovered his ritual lair in the hills and brutally killed him.  To make matters worse they buried his corpse in the Southshore cemetery.\n\nSuch disregard for the great wizard is unacceptable.  As his apprentice I shall see to it that the rains of vengeance fall upon the town of Southshore.\n\nWe will need Helcular's Rod first.  Yeti overtook his ritual lair.  Undoubtedly one of the beasts has it.", progress = "Have you recovered Helcular's Rod yet?  There are so many Yeti in this region, it will be very difficult to locate.  But we must have it in order to proceed.", completion = "You found it!  Most excellent, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][553] = {title = "Helcular's Revenge", objective = "Charge the Rod of Helcular with the powers of the Flame of Azel, Flame of Veraz and the Flame of Uzel.\n\nDrive the charged rod into Helcular's grave in Southshore.", description = "Here, take the Rod of Helcular. You will need it.\n\nHelcular fashioned 3 ceremonial pyres as part of his most powerful spell.  The Flame of Azel and the Flame of Veraz lie within the Foothill Caverns. The Flame of Uzel lies in a cave above the caverns, further north in the mountains.\n\nThe Rod of Helcular must be charged from each of the three flames. Once the ritual is complete, drive the rod into Helcular's grave in Southshore, the heavily guarded human town to the south.  Vengeance shall be ours!", progress = "Helcular's grave teems with a mystical energy.", completion = "A great rumbling emanates from the ground.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][554] = {title = "Stormpike's Deciphering", objective = "Take the Ensorcelled Parchment to Prospector Stormpike in Ironforge.", description = "Prospector Stormpike is a master of decryption and deciphering.  If you take the parchment you found to him, then with luck he can make sense of it.  Stormpike is currently studying in the Prospector headquarters in Ironforge.\n\nAnd when you see him tell him you spoke with me - I've been sending him quite a lot of business lately.", progress = "More interruptions?\n\nAh, this parchment is covered with a very intricate, finely woven spell.  I can untangle it, of course, but it's going to take time.  And time is very valuable to me...\n\nPerhaps I will just purchase it from you?", completion = "A wise decision.  I don't believe there is a scholar other than myself with the skills to translate this scroll.  And if its contents prove interesting, fear not.  I will send for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][555] = {title = "Soothing Turtle Bisque", objective = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Chef Jessen in Southshore.", description = "If there's one thing you'll learn about Southshore it's that we have some of the best cuisine north of Stormwind!\n\nTake my secret recipe for Turtle Bisque, for example. I've known folks to travel from as far as Darkshire just to enjoy a bowl.  Speaking of which, I haven't been able to make any lately.  I used to head up past Dalaran to Lake Lordamere myself to hunt Snapjaws but it's just too dangerous now. If you bring me some Turtle Meat from the Snapjaws up north and Soothing Spices, I'll whip some up!", progress = "Any luck finding the ingredients?  I'll tell you, this territory isn't the peaceful place it once was.  Ah, if only this unrest never occurred. . .", completion = "Everyone will be so pleased: Chef Jessen's Soothing Turtle Bisque is served once again!", rewards = "You will receive:\n\nRecipe: Soothing Turtle BisqueSoothing Turtle Bisque"}
MultiLanguageQuestData['en'][556] = {title = "Stone Tokens", objective = "Bring 10 Worn Stone Tokens to Keeper Bel'varil in Tarren Mill.", description = "A notable talent of the wizards of Dalaran is their familiarity with elementals: powerful creatures from other dimensions.  The wizards use magical tokens as a means to control these elementals.  Magus Voidglare would like some of these tokens to study.\n\nEnter the territories of the Dalaran wizards, west of Hillsbrad, and gather the tokens.\n\nYou might find the tokens on any citizen of Dalaran, but I suggest hunting at the internment camp.  It's safer than Dalaran itself.", progress = "Do you have the Worn Stone Tokens, <name>?  The Magus is eager to unlock their secrets.", completion = "These will do nicely.  Although it looks like their magic is faded, it would be best if the Magus' initial experiments were on inert specimens such as these.\n\nThank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][557] = {title = "Bracers of Binding", objective = "Bring 4 Bracers of Earth Binding to Keeper Bel'varil in Tarren Mill.", description = "The Magus will be busy studying those stone tokens you gathered, but I know he'll eventually want examples of their counterpart: bracers of binding.  These are set around the wrists of actual elementals, and bind them into the mage's service.\n\nHunt elementals in the ruins of Dalaran and gather their Bracers of Earth Binding, and the Magus will be pleased.", progress = "Hello, <name>.  Elementals are tough quarry, but I know you're up to the task.  Do you have those bracers of binding?", completion = "You found them.  I trust the elementals from which you removed these bracers were amenable?\n\nHm...death has not only stopped my heart, but robbed me of my comedic timing, it seems.\n\nWell thank you, &lt;name&gt;.  You serve the Magus, and hence the Dark Lady, well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][558] = {title = "Jaina's Autograph", objective = "Travel to Theramore to see about getting Lady Jaina Proudmoore's autograph for your ward.", description = "They say that Lady Jaina Proudmoore in Theramore is one of the greatest heroes the Alliance has ever had.  When I grow up, I wanna be a hero of the Alliance too!\n\nDo you know Jaina, <name>?  Could you do me a favor, please?  Could you get her autograph for me?  I dunno how to ask her, and she'd probably be too busy for someone like me... but you!  You're an adventurer just like she is!  I bet she'd give you her autograph easy!\n\nPlease?", progress = "Someday, I wanna be a hero just like Jaina... well, a boy hero that is.", completion = "WOW!  You got Lady Jaina's autograph for me!  Thank you very much!  And wow... she wrote a personal message on here - to me!  I knew she'd be totally cool, and maybe someday I'll thank her myself... when I become a hero of the Alliance!\n\nYou're the best, &lt;name&gt;.  Thank you for being so nice to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][559] = {title = "Farren's Proof", objective = "Collect 10 Murloc Heads from the murlocs on the Western Strand for Lieutenant Farren Orinelle in Southshore.", description = "Would you believe it, <name>? Redpath wasn't satisfied with all the murlocs we killed--oh now, don't be modest, you had some hand in it. Now he wants me to bring proof of the dead, hacking off cold, slimy murloc heads to submit for his approval.", progress = "Did you get those heads for me, <name>?", completion = "Oh for the Love of the Light... they're dripping on the ground.\n\nCan't stand touching those things, myself. Fish are all well and good, but when they grow legs and start walking around... Haven't eaten a fish in weeks, let me tell you, and in Southshore, that means you aren't eating much.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][560] = {title = "Farren's Proof", objective = "Deliver the sack of murloc heads to Marshall Redpath in Southshore.", description = "You know, <name>, I'd really rather not take these heads... Since you've already got a handle on them, would you mind delivering them to Redpath for me?", progress = "Greetings, citizen. Have you come to lend your arm to upholding the safety of Southshore?", completion = "Farren's errand boy, are you?\n\nIf you assisted Farren in procuring these heads, then thank you. Southshore needs hard workers and effort to maintain its protection.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][561] = {title = "Farren's Proof", objective = "Speak with Lieutenant Farren Orinelle in Southshore.", description = "Please inform Lieutenant Orinelle that I would like him to refocus his efforts on the naga infesting the Eastern Strand. When he has results, tell him to report to me in person.", progress = nil, completion = "The naga, eh? Redpath must have just received the same information as me... Ha! He'll not receive a promotion from my toil. Let me explain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][562] = {title = "Stormwind Ho!", objective = "Kill 10 Daggerspine Shorehunters and 10 Daggerspine Sirens for Lieutenant Farren Orinelle in Southshore.", description = "My former mentor in the Stormwind city guard sent a message to me that Alliance High Command is becoming concerned with the threat posed by the naga. From what he's heard, there's good chances for promotion--or at least reassignment--for anyone who proves valuable in this regard.\n\nThere's just one small problem... I can't handle the naga, <name>. Oh sure, I could break up a drunken barroom brawl, or haul off a belligerent beggar, but the naga are too much for me. You've got to help me, <name>!", progress = "I've a letter ready to go to Major Samuelson in Stormwind. All I need are the results.", completion = "With the naga put down in Southshore, I'll be a shoe-in to be reassigned. I'll get to see Stormwind again... get away from this Light-forsaken port.", rewards = "You will receive:\n\nFish Gutter"}
MultiLanguageQuestData['en'][563] = {title = "Reassignment", objective = "Deliver Farren's report to Major Samuelson in Stormwind Keep.", description = "It shouldn't be a problem getting my report seen. The new captain of the guard, Major Samuelson, was my mentor while I was stationed in Stormwind. It should give him more than enough excuse to have me transferred back to the city. I'll need you to carry my report to him, though... wouldn't want ol' Redpath to catch on.", progress = "Greetings, citizen. May the Stormwind city guard be of assistance?", completion = "What's this? Ah... so my attentive pupil has applied himself to the problem of the naga in Southshore. Thank you for bringing this to me, I will certainly take it into account when I review personnel assignments in the next month.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][564] = {title = "Costly Menace", objective = "Darren Malvew of Southshore wants you to kill 8 Mountain Lions and 10 Hulking Mountain Lions.", description = "Ain't nothin' that irks me more than losin' these here beautiful horses.  And believe me, we've lost quite a few between them pesky undead creeps, the dang Syndicate gang and all the other good-for-nothin' scoundrels pokin' about these parts.\n\nBut I swear on my ol' grand-daddy's grave there ain't no bigger menace to our horses here than them Mountain Lions up in Alterac.  Always comin' down from the hills and makin' my life difficult!\n\nYou fancy yourself a hero?  Go and do somethin' about it then!", progress = nil, completion = "Ain't that great news!  Should-a gone and found me a regular ol' war hero from day one to take care of them beasts.  You'd-a made your pappy proud, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nShepherd's GirdleShepherd's Gloves\n\nYou will also receive:\n\nRecipe: Tasty Lion SteakTasty Lion Steak"}
MultiLanguageQuestData['en'][565] = {title = "Bartolo's Yeti Fur Cloak", objective = "Bring Bartolo Ginsetti of Southshore a Bolt of Wool, a Hillman's Cloak, Fine Thread and 10 clumps of Yeti Fur.", description = "I, the great Bartolo, shall make for you the world famous, Alliance renowned, Yeti Fur Cloak!\n\nTravel the planet and find yourself a better cloak, I dare you.  Oh wait, what is that, little <race>?  \"Bartolo, there is no finer cloak!\"  Yes, yes!  That, I have heard before.\n\nBartolo requires a Bolt of Wool, a Hillman's Cloak made by a skilled leatherworker, Fine Thread and Yeti Fur, of course!  Bring to me these items and you shall be a happy customer!", progress = "So you have returned to the great Bartolo.  Perhaps you have finished gathering the materials needed for your Yeti Fur Cloak?  Or maybe you just enjoy basking in the greatness of me, Bartolo!", completion = "Now it is time for the great Bartolo to work his magic!  I require no wizard's staff, no mage's rod.  For I, the great Bartolo, work magic with a mere needle and thread!", rewards = "You will receive:\n\nYeti Fur Cloak"}
MultiLanguageQuestData['en'][566] = {title = "WANTED: Baron Vardus", objective = "Kill Baron Vardus and deliver his head to High Executor Darthalia in Tarren Mill.", description = "By order of High Executor Darthalia, the human known as Baron Vardus is wanted for crimes against the Forsaken. Vardus is known to be a high-ranking member of the organization known as the Syndicate.\n\nHe was last spotted in the Uplands in the Alterac Mountains, north of Tarren Mill.\n\nHe is wanted dead. Bring evidence of his demise to High Executor Darthalia to claim the reward.", progress = "Ah, <name>. Perhaps you've come to collect the bounty on the head of Baron Vardus?", completion = "Productive work you do, &lt;name&gt;. With Baron Vardus dead, the number of Syndicate leaders grows smaller. Their resistance and irritation will be short-lived.", rewards = "You will receive:\n\nInferno Robe"}
MultiLanguageQuestData['en'][567] = {title = "Dangerous!", objective = "High Executor Darthalia of Tarren Mill is offering a bounty on Clerk Horrace Whitesteed, Citizen Wilkes, Miner Hackett and Farmer Kalaba.", description = "Dangerous!\n\nThe following humans of Hillsbrad have been deemed dangerous and are marked for bounty by High Executor Darthalia:\n\nClerk Horrace Whitesteed.  Wanted for the murder of Deathguard Toma.\n\nCitizen Wilkes.  Wanted for the murder of Apothecary Eli.\n\nMiner Hackett.  Wanted for the murder of Deathstalker Fry.\n\nFarmer Kalaba.  Wanted for the ambush of supplies from the Undercity.\n\nAll of these enemies are hiding and will be hard to find.  A reward will be granted upon notice of their death.", progress = "Yes?", completion = "You are quite the bounty hunter, &lt;class&gt;.  Well done.", rewards = "You will be able to choose one of these rewards:\n\nBow of PlunderSentry BucklerCharred Wand\n\nYou will also receive:\n\nHooded Cowl"}
MultiLanguageQuestData['en'][568] = {title = "The Defense of Grom'gol", objective = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 15 Lashtail Raptors.", description = "Throm'ka, <class>!\n\nYour arrival at Grom'gol is timely, indeed.  As commander of the Warchief's base camp here in the jungle I am bound by honor to ensure the safety of all members of the Horde.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of thinning out the raptor population outside of Grom'gol.  Once you have made significant progress, report back to me for reassignment.", progress = "Our supply efforts are still being hampered by the indigenous raptor population, <class>.", completion = "Your duty was performed with honor, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][569] = {title = "The Defense of Grom'gol", objective = "Commander Aggro'gosh of the Grom'gol base camp wants you to kill 10 Ogre Brutes and 5 Ogre Witch Doctors.", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", progress = "Have you made any progress with the ogres of the Mizjah Ruins yet, <class>?", completion = "Well done.  You have served the Warchief with honor.", rewards = "You will receive:\n\nGrom'gol Buckler"}
MultiLanguageQuestData['en'][570] = {title = "Mok'thardin's Enchantment", objective = "Far Seer Mok'thardin at the Grom'gol base camp wants 8 Shadowmaw Claws and a Pristine Tigress Fang.", description = "The power of the jungle's magic must be realized and then harnessed by the Horde.  My rituals have proven successful so far.  I can cast very powerful enchantments.  For you, brave <class>, I shall make a special item indeed.\n\nBring to me some Shadowmaw Panther claws along with a Tigress fang.  Not just any fang will do.  It must be in pristine condition.\n\nThe beasts lurk throughout the jungle but you will find some close by, just across the river from Mizjah Ruins to the southeast.", progress = "What news do you bring?", completion = "Your knowledge of the jungle is strong, &lt;name&gt;.  These specimens will be perfect.  I will thank the spirits for sacrificing such fine beasts for the cause of the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][571] = {title = "Mok'thardin's Enchantment", objective = "Bring an Aged Gorilla Sinew to Far Seer Mok'thardin in Grom'gol.", description = "What I need from you now will be very difficult to obtain.\n\nTo hold all these feathers, claws and the pristine fang in place I require a magical tether.  Only an aged gorilla sinew will work.\n\nYou will only be able to find one on an Elder Mistvale Gorilla.  They are known to forage to the east of Booty Bay.\n\nThe sinew must be perfect.  It might take quite a few kills for you to find exactly what I need but it will be well worth the hunt.", progress = "Has fortune been on your side, <name>?  Were you able to obtain an aged gorilla sinew?", completion = "A most ideal sinew, &lt;name&gt;.  Your efforts will pay off soon.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][572] = {title = "Mok'thardin's Enchantment", objective = "Bring 10 Jungle Stalker Feathers to Far Seer Mok'thardin at the Grom'gol base camp.", description = "The items you gathered from the feline beasts of the Vale are only the first requirement for a powerful enchanted item.  These jungle trinkets combined with my shamanistic ritual will provide you with a very useful tool in assisting the Horde and the Warchief.\n\nBut now you must gather for me some Jungle Stalker Feathers.  The feathers are traditionally worn by the beasts on their armbands.  You will find a tribe of the raptors directly south of Grom'gol, not far from the great arena.", progress = "Did your gathering efforts prove fruitful?", completion = "Most excellent.  I will prepare these at once.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][573] = {title = "Mok'thardin's Enchantment", objective = "Far Seer Mok'thardin of Grom'gol needs Holy Spring Water. He also wants you to kill 10 Naga Explorers.", description = "There is but one final reagent needed to complete the enchantment.\n\nIn the south, towards the western coast, high above the bluffs, lies a Holy Spring.  This spring is the subject of great conflict amongst religious and mystical scholars.  Every race in Azeroth claims that the spring waters were made divine for their people.\n\nMy final request of you: bring to me Holy Spring Water.  Be warned.  An expedition of naga explorers have advanced upon the spring.  They will need to be dealt with as well.", progress = "I am almost ready to complete the enchantment.  Have you performed my bidding?", completion = "With this Holy Spring Water the ceremonial choker is ready for enchantment.\n\nWear this with pride, &lt;name&gt;, in the name of the Warchief and in defense of the mighty Horde.", rewards = "You will receive:\n\nChoker of the High Shaman"}
MultiLanguageQuestData['en'][574] = {title = "Special Forces", objective = "Kill 10 Kurzen Commandoes and 6 Kurzen Headshrinkers.\n\nReport to Lieutenant Doren at the Rebel Camp.", description = "Now that many of his regular troops are reduced, you must face his highly trained forces.  When they're not in the wilderness slaughtering our rebel soldiers, they are found deep in the back of the Kurzen Compound, in a cave they call the Stockpile.\n\nI know many of Kurzen's troops personally, and I know they are skilled, loyal, and cruel.  This is no easy task I set before you, <name>.\n\nAfter you defeat them, report to Lieutenant Doren, my commanding officer.  He will want your report firsthand.", progress = "Sergeant Yohwa tells me you are skilled and brave, <class>.  Do you have something to report?", completion = "&lt;name&gt;.  Sergeant Yohwa trusted your abilities, and I trust her.  The defeat you brought to Kurzen's forces is almost too much to hope for.  I had feared we rebels were alone, and alone we could never stand up against the Colonel's brilliance.\n\nPerhaps hope of our survival yet remains.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][575] = {title = "Supply and Demand", objective = "Bring 2 Large River Crocolisk Skins to Drizzlik in Booty Bay.", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in northern Stranglethorn.", progress = "My equipment is all ready to go, <name>, I just need those skins. We don't want to keep Riddlevox waiting, that's for sure.\n\nIt's not a good idea for anyone to keep the chief inventor of the Tinkers' Union unsatisfied.", completion = "These skins should do. Their quality isn't too important, given that they'll make up the inside layer of the boots, but it's still important that they're comfortable.\n\nIf they're a bit too rigid, I'll use some tiger blood to soften it up. Tricks o' the trade, you know?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][576] = {title = "Keep An Eye Out", objective = "Dizzy One-Eye in Booty Bay wants you to retrieve his eye from the Bloodsail Buccaneers.", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", progress = "Ahoy, me bucko!  Might not be able to see but I can smell ye from halfway across port.\n\nCould really use me eye back.  Captain's going to keelhaul me when he finds out me peeper is in the hands of them dirty Bloodsail Buccaneers.\n\nWhat good is a lookout who can't see?  The crow's nest used to be me home...without me deadlights I'd be lucky to scrub the bilge.", completion = "Shiver me timbers and timber me shivers!  Ye found me beautiful eye!  Let's see if she still fits.\n\n&lt;name&gt; ho!  Blimey, I can see!!", rewards = "You will receive:\n\nDarktide Cape"}
MultiLanguageQuestData['en'][577] = {title = "Some Assembly Required", objective = "Bring 5 Snapjaw Crocolisks Skins to Drizzlik in Booty Bay.", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", progress = "Drizzlik's Excelsior leather boots, finest workmanship, one-hundred percent high quality saltwater crocolisk skin boots. None finer!\n\nCan't beat a glowing description like that, can you?\n\nExcept, maybe, if you have those skins for me?", completion = "My boots... they're like sausages, &lt;name&gt;. Look great, taste great. I tell you they're filled with nothing but the finest ingredients and meats, and you eat it, and you love it.\n\nIt's safer--and more enjoyable--if you just trust me, and don't ask too carefully what's really inside.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][578] = {title = "The Stone of the Tides", objective = "Find the haunted island for Baron Revilgaz in Booty Bay.", description = "If there is indeed a goblin mage and water elementals haunting the island, it could mean the Stone of the Tides can be mine!\n\nI want you to locate this haunted island... find out what's going on. Oh, and if you perhaps want to find out more about the Stone of the Tides, take this scrip to the Stormwind Library, they should be able to find you a copy of the book I first came across the legend in.\n\nCould it be that Gazban actually discovered the Stone...?", progress = nil, completion = "So the stories were true! Incredible!\n\nHowever, we will need to figure out a way to defeat the curse of the Stone of the Tides, if we are to retrieve it. The curse is magical business, we'll need one of those wizards to help us out.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][579] = {title = "Stormwind Library", objective = "King Anduin has placed great importance on learning, and thus has provided funds for making copies of various tomes and writings available to the public. It's very simple. You bring me a library scrip, and I can give you a copy of one of the available books.", description = nil, progress = "King Anduin has placed great importance on learning, and thus has provided funds for making copies of various tomes and writings available to the public. It's very simple. You bring me a library scrip, and I can give you a copy of one of the available books.", completion = "Do any of these titles interest you, &lt;name&gt;?", rewards = "You will be able to choose one of these rewards:\n\nThe Story of Morgan LadimoreLegends of the Gurubashi, Volume 3"}
MultiLanguageQuestData['en'][580] = {title = "Whiskey Slim's Lost Grog", objective = "Whiskey Slim in Booty Bay wants you to bring him the bottles of Pupellyverbos Port he lost.", description = "We was splicin' the mainbrace somethin' fierce off of the Overlook Cliffs, ol' Hinterlands just in the distance.  Thought the seas was goin' to swallow us whole.\n\nOl' Slim knows all about liquid courage!  Cap'n had a crate of Pupellyverbos Port we commandeered from a privateer en route to Stormwind.\n\nSo when that storm off of Hinterlands hit, I busted into the grog.  Big wave hit and tossed them bottles overboard.  Cap'n is goin' to give me a taste o' the cat if ye don't help me get 'em back though!", progress = "Sink me!  I'm almost outta booze here!  Cap'n is goin' to weigh anchor and Ol' Slim will be caught dry as the Tanaris Desert.  And once he discovers his port is missing. . . blimey!", completion = "Shiver me timbers!  Ye found the Cap'n's grog!\n\nI owe ye big time, friend.\n\nSeems like a storm is a brewin' outside.  Maybe I'll just keep warm with one o' these here bottles while we wait for it to pass....", rewards = "You will receive:\n\nRumsey Rum"}
MultiLanguageQuestData['en'][581] = {title = "Hunt for Yenniku", objective = "Bring 9 Bloodscalp Tusks to Nimboya at the Grom'gol Base Camp.", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", progress = "<class>.  Show me you have made prey of the Bloodscalp tribe.\n\nShow me your trophies.", completion = "These are good tusks, &lt;name&gt;.  You prove that you have the strength to hunt the Bloodscalps.\n\nAnd that is good, because you are not done hunting them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][582] = {title = "Headhunting", objective = "Bring 20 Shrunken Heads to Nimboya at the Grom'gol Base Camp.", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalp Headhunters and take from them their Shrunken Heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, <name>.  You may find many Headhunters at the ruins of Zuuldaia and Zul'Kunda, along the coast to the north.", progress = "<name>.  I fear for our chief's son.  Do you have the shrunken heads so I may inspect them?", completion = "Thank you, &lt;name&gt;.  I will inspect these heads to ensure poor Yenniku was spared the headhunter's axe.", rewards = "You will be able to choose one of these rewards:\n\nDarkspear CuffsDarkspear Armsplints\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][583] = {title = "Welcome to the Jungle", objective = "Speak with Hemet Nesingwary Jr.", description = "Welcome to Stranglethorn!\n\nPerhaps you're not aware of this, but that dwarf over there is the son of the one and only Hemet Nesingwary, renowned war hero of the Alliance and master big game hunter.  Like his father, he's not one for welcoming strangers into his camp, but you look like you've seen quite a bit of action in your day, <class>.\n\nGo and speak with him.  He's a chip off the old block, so perhaps he can give you some hunting pointers.", progress = nil, completion = "Jolly nice to make your acquaintance, &lt;name&gt;. Haven't seen a &lt;class&gt; around these parts for some time.\n\nI situated myself with this expedition for one purpose: to hunt a great and elusive beast. Seeing that you're a hero of sorts I am willing to let you take part in the hunt, but you must first prove yourself.\n\nI shall teach the ways of raptor killing to you. Ajeck will train you with tiger hunting. And Sir Erlgadin is a master of panther tracking.\n\nProve your skill and I'll let you in on the big hunt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][584] = {title = "Bloodscalp Clan Heads", objective = "Bring Gan'zulah's Head and Nezzliok's Head to the bubbling cauldron at the Grom'gol Base Camp.", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp chief and his witchdoctor know it.  They are the enemies of the Darkspear tribe and will not speak freely, so we must force the truth from their dead lips!\n\nBring me the heads of Gan'zulah and Nezzliok the Dire and place them within this cauldron.\n\nThey are deep within Zul'Kunda.  Bring their heads...we will then make them talk.", progress = "The greenish broth within the cauldron bubbles.", completion = "You place the heads of Gan'zulah and Nezzliok within the cauldron...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][585] = {title = "Speaking with Nezzliok", objective = "Bring a Balia'mah Trophy, a Ziata'jai Trophy and a Zul'Mamwe Trophy to the Bubbling Cauldron at the Grom'gol Base Camp.", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal from the Skullsplitters 3 of their trophy skulls and place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, another from Ziata'jai, and the last from Zul'Mamwe.", progress = "I await the skulls...", completion = "Yes.  These will serve me well.  When my spirit is freed, I will enter the Nether with three fine servants!\n\nYou are a credit to your &lt;race&gt; clan, and you have appeased me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][586] = {title = "Speaking with Gan'zulah", objective = "Kill 8 Skullsplitter Hunters, 6 Skullsplitter Headhunters, and 4 Skullsplitter Berserkers.\n\nBring the Broken Armor of Ana'thek to the Bubbling Cauldron at the Grom'gol Base Camp.", description = "<The head of Gan'zulah speaks.>\n\nCurse you!  And curse your ancestors!!\n\nOnly blood and revenge can cool my rage, so if that is your wish, then... do this:\n\nThrow yourself into the heart of the Skullsplitters to the east.  Slay the fiercest among them, and if you survive...then break yourself against their chief, Ana'thek the Cruel.  Hah!  Bring me his shattered armor if you can!\n\nMay he tear off your limbs and leave you to rot and be eaten by carrion.", progress = "Although my own flesh boils off my skull, I can still smell your fear.\n\nHah!  You will never complete my task...", completion = "I do not want to believe it, but I cannot deny what you have done.  And my rage eases, now that Ana'thek is defeated.  \n\nYour might will drive you to great deeds, &lt;name&gt;.  But one day...I will see you in the Nether and we will again match strength.\n\nI will be waiting.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][587] = {title = "Up to Snuff", objective = "Deeg in Booty Bay wants you to bring him 15 shares of Snuff.", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless <class> like you could convince 'em to share the goods, eh?", progress = "Any luck finding the goods, matey?", completion = "Good show, &lt;name&gt;!  And just before I need to ship out too!  Can't thank you enough, old friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][588] = {title = "The Fate of Yenniku", objective = "Speak with Kin'weelay.", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, <class>.\n\nPerhaps your Darkspear allies can offer a hope of Yenniku's salvation.  But that, I doubt.", progress = nil, completion = "Zanzil the Outcast??\n\nIf Yenniku is held by that troll, a vile and powerful witchdoctor, then I fear that only a faint hope remains.  Faint.  And tiny as the smallest insect.\n\nBut still, it is hope.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][589] = {title = "The Singing Crystals", objective = "Bring 3 Pulsing Blue Shards to Kin'weelay at the Grom'gol Base Camp.", description = "Legends tell of a jewel, hidden deep in the heart of Stranglethorn.  We call it the Mind's Eye, and it has great powers.  If you gain this Eye then, perhaps, we can use it to bring lost Yenniku back from the darkness.\n\nI will consult with the spirits of the jungle to find the Mind's Eye.  While I do this, you enter the Crystalvein Mine, southeast of here, and gather Pulsing Blue Shards from Ironjaw Basilisks.  The shards are rare, but we will need their magic to bend the Mind's Eye to our will.", progress = "Do you have the shards, <name>?  They are needed for my final ritual, after we have the Mind's Eye.", completion = "You have done well, &lt;name&gt;.  These shards are well formed.  Already I hear them sing to me.\n\nAnd while you were gone, I spoke with the spirits of the jungle.  I know where the Mind's Eye rests...\n\n...And who guards it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][590] = {title = "A Rogue's Deal", objective = "Defeat Calvin Montague in Deathknell.", description = "What?\n\nWhat?!\n\nYou want money? I don't owe you any money.\n\nLetter? What letter? Oh, you wanna fight then? All right, mate... let's do this! Owe you any money...", progress = "Not bad, mate... not bad at all.", completion = "Incredible! What skill!\n\nThought you'd be easy prey, &lt;name&gt;. Got me good, you did.\n\nHere's the coin I promised... not as much as I said it'd be, but that's on a count o' me lying to ya in the first place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][591] = {title = "The Mind's Eye", objective = "Bring the Mind's Eye to Kin'weelay at the Grom'gol Base Camp.", description = "The Mind's Eye is held by an ogre mage, east of here and deep within the Mosh'Ogg ogre mound.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", progress = "Greetings, <name>.  The spirits sing praise of your bravery, yet they tell me no tales of your quest against Mai'Zoth.\n\nDo you have the Eye?", completion = "You retrieved the eye!  Your might is the stuff of legends, &lt;name&gt;!\n\nAnd in getting the Eye, you must have defeated Mai'Zoth and sent him to the Nether.  That is why the spirits would not mention him before.\n\nIt is good that he is gone from the world of flesh and bone, but now that he is in the realm of spirits...I fear he will begin a new reign.\n\nBut that is a worry for another time.  Now, I must perform a ritual to bend the Mind's Eye to our needs...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][592] = {title = "Saving Yenniku", objective = "Bring the Filled Soul Gem to Nimboya.", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nThen, bring the gem to Nimboya.\n\nYenniku dwells with Zanzil the Outcast, at the Ruins of Aboraz, along the Crystal Shore on the distant Cape of Stranglethorn.", progress = "<name>.  Kin'weelay told me you set out to capture Yenniku.\n\nIs it true?  Do you have him?", completion = "You've done it!  You freed Yenniku from the will of Zanzil, and completed the mission I had thought was so desperate.\n\nOur tribe will remember your name in songs, &lt;name&gt;, and we will etch your tale in stone so that it will live forever.", rewards = "You will be able to choose one of these rewards:\n\nNimboya's Mystical StaffMedal of Courage\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][593] = {title = "Filling the Soul Gem", objective = "Yenniku stands stunned before you, his mind in another place...", description = nil, progress = "Yenniku stands stunned before you, his mind in another place...", completion = "You place the Soul Gem upon his forehead.  He shudders as his soul is sucked in, leaving his body, a mindless husk, behind.", rewards = "You will receive:\n\nFilled Soul Gem"}
MultiLanguageQuestData['en'][594] = {title = "Message in a Bottle", objective = "Find the author of the message in a bottle.", description = "The note reads, in fairly good handwriting:\n\nTo any that can aid me-\n\nPlease, my need for help is dire. A great Skymane holds me captive on an island in the South Seas.\n\nThe stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see Wild Shore to the northwest, and what seem to be large sailing ships to the southwest.\n\nI beg of you, my would-be savior, please help me.", progress = nil, completion = "Have you come to free me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][595] = {title = "The Bloodsail Buccaneers", objective = "First Mate Crazz wants you to check the cove north of Booty Bay.", description = "You sure seem eager to work, matey.  Not sure why some land-loving <race> <class> is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nOur ship just docked here in Booty Bay and word has it that our rivals--those damned, dirty Bloodsail Buccaneers--have been spotted all over southern Stranglethorn.\n\nAll the boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", progress = nil, completion = "On top of the barrel, you discover a map with some hastily written text on it along with some coins.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][596] = {title = "Bloody Bone Necklaces", objective = "Bring 25 Bloody Bone Necklaces to Kin'weelay at the Grom'gol Base Camp.", description = "I was sent to Grom'gol  to aid Nimboya on his quest, but... I too have reasons for being here.\n\nThe Bloodscalp tribe is enemy to our tribe.  Collecting trophies of our enemies gives us power over them.  You may aid our tribe by hunting our enemies.\n\nThey dwell to the north.  Slay Bloodscalp trolls and take from them their bloody bone necklaces.  Collect many, and your reward will be great.", progress = "The Bloodscalps will one day be crushed by the Darkspears!  Do you have the necklaces of our doomed foe?", completion = "Ah, very good.  I will boil these, and leech them, and the spirits of their owners will weaken as I render their necklaces to paste!\n\nHere, &lt;name&gt;.  This will repay my debt to you.", rewards = "You will receive:\n\nBloodbone Band"}
MultiLanguageQuestData['en'][597] = {title = "The Bloodsail Buccaneers", objective = "Report your findings to First Mate Crazz in Booty Bay.", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"You men are to secure a camp at this location and keep quiet.  Wait for the signal from the southern command post before attacking.  If anyone approaches you, kill them.\"", progress = nil, completion = "Sure, I remember you, &lt;class&gt;.  Back from scouting I see....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][598] = {title = "Split Bone Necklace", objective = "Bring 25 Split Bone Necklaces to Kin'weelay at the Grom'gol Base camp.", description = "Now that you have gathered Bloodscalp trophies, I have another task for you.  The Skullsplitter tribe of trolls live to the southeast, and for years we have warred with them.  Although the Darkspears no longer dwell in Stranglethorn, we are bound to our conflict with the Skullsplitters.\n\nSo, hunt them.  Gather their Split Bone Necklaces and return to me.  Aid us in our war, and you will earn the friendship of the Darkspears.", progress = "The Skullsplitters will curse the day they brought us to war!  Is your task complete?", completion = "Your strength is great to have gained these necklaces, &lt;name&gt;.  The Skullsplitters fall to you like young saplings stomped to earth by a Basilisk!\n\nYour deeds are a boon to us.", rewards = "You will be able to choose one of these rewards:\n\nDarkspear ShoesDarkspear Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][599] = {title = "The Bloodsail Buccaneers", objective = "Report the planned Bloodsail attack to Fleet Master Seahorn.", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Fleet Master Seahorn at once!  The ol' sea dog is around town somewhere....", progress = nil, completion = "Bloodsail Buccaneers attacking Booty Bay?  They might as well throw themselves off the Overlook Cliffs.  Nonetheless, by bringing me this information you have done my fleet of swashbucklers a great service.  The Blackwater Raiders thank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][600] = {title = "Venture Company Mining", objective = "Bring 10 Singing Blue Crystals to Crank Fizzlebub in Booty Bay.", description = "The Venture Company has a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!  Please, you must help me!\n\nThe Venture Company is mining near the Crystalvein Mine to the north.  They can't get into the mine because of all the basilisks, but they're still able to dig up Singing Crystals from the surrounding hills.\n\nTake their crystals from them, and show them they don't have the run of the jungle.\n\nAnd... um... bring me those crystals as proof!", progress = "Do you have those crystals??  I need them!!\n\nI mean...I need to know the evil Venture Company is losing ground in Stranglethorn.  Because, you know, we honest folk have to make a living!", completion = "Great!  Wonderful!  I can get a bundle for these!!\n\nThat Venture Company sure picked the wrong jungle to mine in, didn't they?  We'd all be in better shape if they moved out of here.\n\nThank you, &lt;name&gt;.  You've done a good deed this day.", rewards = "You will be able to choose one of these rewards:\n\nGoblin IgniterSilver Spade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][601] = {title = "Water Elementals", objective = "Acquire 6 Water Elemental Bracers for Baron Revilgaz in Booty Bay.", description = "The water elementals were no doubt summoned by Gazban, the goblin wizard rumored to have discovered the Stone of the Tides. As you may know, the Stone of the Tides curses its bearer, causing him to fade in and out of existence...\n\nPerhaps we can find a way to counteract the curse. We can have a mage of Dalaran analyze the magical residue of one of the water elemental's bracers. I need you to go back to the island and retrieve a few specimens.", progress = "Have you had any luck, <name>?", completion = "Hm, I haven't the eye to examine these bracers to see if any of them will be of any use, but I'm sure at least one of them will be able to help. Take them to Dalaran and have a mage look at them.\n\nAfter all, I can't very well leave Booty Bay just to chat with those tiresome old mages.\n\nNot that I'm worried anyone would try to elbow their way into being the new baron. No one crosses Revilgaz and lives to tell of it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][602] = {title = "Magical Analysis", objective = "Bring the water elemental bracers to Archmage Ansirem Runeweaver in Dalaran.", description = "From what I've heard, the mages of Dalaran are busy with the reconstruction of their destroyed city, I'm sure you can find one of them who will spare some time to look at the bracers. If there's anything I know about mages, they can't resist a magical puzzle.\n\nTake the bag of water elemental bracers and see if they can shed any light on the Stone's curse.  Look for the Archmage Ansirem Runeweaver in particular.  I've dealt with him before, and his knowledge is vast.", progress = "If you wouldn't mind, I am rather busy right now.", completion = "The Stone of the Tides? Most interesting. It might surprise you to know that I wrote a tome--several years ago--pertaining to the legends of the Gurubashi Empire. I do know quite a bit about the Stone.\n\nAt least one of these bracers appears to have some magical residue I can analyze.\n\nLet's see what I can see...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][603] = {title = "Ansirem's Key", objective = "Talk to Catelyn in Booty Bay.", description = "The mage that is in possession of the Stone is amplifying its power through some focal point... an altar of some sort. You should be able to disrupt it by overpowering it.\n\nAs it happens, I know just the thing: an ancient dagger, another troll relic. There's just one... little problem.\n\nYou see, I found the dagger while researching in Stranglethorn, but I gave it to my willful daughter, Catelyn, who ran off to Booty Bay to become a pirate.", progress = nil, completion = "My dagger? What are you, some sort of comedian?\n\nWhat? Do you just want me to repeat the story of how I've gone from the best knife fighter in Booty Bay to the laughing stock of piratedom!\n\nI lost a knife fight to one of the Bloodsail Buccaneers--bunch of right bastards they are!--and he took my blade as spoils.\n\nIt's not as though I can get by as a knife fighter with insults and a sharp tongue alone...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][604] = {title = "The Bloodsail Buccaneers", objective = "Fleet Master Seahorn in Booty Bay wants you to kill 10 Bloodsail Swashbucklers and bring back the Bloodsail Charts and the Bloodsail Orders.", description = "Crazz speaks highly of your dedication to the Blackwater Raiders.  I am going to trust you with a mission of extreme importance to the fleet.\n\nInfiltrate the so-called southern command post the Bloodsail Buccaneers have established on the Wild Shore.  Raid the encampment.  Bring me their charts along with their written orders.  We shall see exactly what those scum are up to.", progress = "Ahoy, <name>.  What word do you bring of the Bloodsail encampment to the south?", completion = "Perfect, &lt;name&gt;.  Now that we know their plan, it's just a matter of time.\n\nAnd to think the fools have dropped anchor just off the cape....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][605] = {title = "Singing Blue Shards", objective = "Bring 10 Singing Crystal Shards to Crank Fizzlebub.", description = "The Singing Crystals are unique to Stranglethorn, and are very valuable to certain parties.  I can move those crystals, but the cursed Venture Company makes it hard for an honest entrepreneur like myself to gather any!\n\nI'd like to hire you.\n\nThe basilisks in Stranglethorn eat the crystal.  This gives them their hardened skin, and sometimes decent quality crystal can be harvested from it.\n\nYou can get it from any basilisk, but the less nasty ones are along the shores south of Zul'Kunda, to the north.", progress = "Do you have those shards yet?  I'll give you a decent cut from the profits!", completion = "Aha!  These will do nicely, &lt;name&gt;.  Yes, quite nicely!\n\nHere is your cut, and...it was a pleasure doing business with you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][606] = {title = "Scaring Shaky", objective = "Bring 5 Mistvale Giblets to \"Shaky\" Phillipe in Booty Bay.", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me. Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt Elder Mistvale Gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", progress = "Hey!  I don't like the look you're giving me, mister.", completion = "Ack!  Where'd you get these?  No, don't tell me. I don't want to know!\n\nWho sent you?  Sea Wolf?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][607] = {title = "Return to MacKinley", objective = "Bring Shaky's Payment to \"Sea Wolf\" MacKinley.", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", progress = "Here here, <name>.  Did you get Shaky's payment?", completion = "Heh heh, well done!  And when you showed Shaky those giblets, how hard did he shake?\n\nHah!  He's so easy to read, when I play cards with him I can't help but win!\n\nThanks for your help, &lt;name&gt;.  Now it's your turn to get paid...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][608] = {title = "The Bloodsail Buccaneers", objective = "Fleet-Master Seahorn in Booty Bay wants you to kill Captain Stillwater, Captain Keelhaul and Fleet Master Firallon.", description = "Blast the nerve of Firallon!  He couldn't sail a skiff through Crystal Lake let alone lead an entire fleet against us.\n\nThe Bloodsail Buccaneers will pay for their carelessness.  Now that we know their plan of attack, we can counter before they know what hit them.\n\nBut why send the entire fleet to do the work of one brave adventuring party?  <name>, take some of your most skilled comrades out to Firallon's landing spot and assassinate the Bloodsail leadership.  Their fleet will sink soon after....", progress = "What's the problem, <name>?  We need to attack before the Bloodsail Buccaneers do!", completion = "Ah, what a great day for the Blackwater Raiders!  Three cheers to you, &lt;name&gt;!", rewards = "You will receive:\n\nBlackwater Tunic"}
MultiLanguageQuestData['en'][609] = {title = "Voodoo Dues", objective = "Bring Maury's Clubbed Foot, Jon-Jon's Golden Spyglass, and Chucky's Huge Ring to \"Sea Wolf\" MacKinley in Booty Bay.", description = "My list is shortening, but there are still people who owe me.\n\nNext, we have Maury \"Club Foot\" Wilkins, Jon-Jon the Crow, and Chucky \"Ten Thumbs.\"\n\nThese scurvy dogs' debts are months outstanding and I thought they skipped town to avoid paying up!  Later, I heard they're cursed and bewitched and now wander the jungle ruins.  But I don't care what their fate is - I want what's mine!\n\nThey're at the Ruins of Aboraz and the Ruins of Jubuwal, northeast of here.  Find them, and collect.", progress = "<name>, did you find those three dogs?  Did you collect their valuables?", completion = "Great!  I can get a good price for these, especially for what's inside Maury's foot!  Thanks much, &lt;name&gt;!\n\nI hope those three learned their lesson: don't bet something you can't afford to lose.\n\nAnd maybe it's too late for them, but...they should be careful of who they gamble with.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][610] = {title = "\"Pretty Boy\" Duncan", objective = "Get Catelyn's dagger from \"Pretty Boy\" Duncan.", description = "My FATHER sent you? I'd have thought that old codger would have given up on me by now.\n\nIt wasn't really his fault I ran off, he just shouldn't have expected I'd be willing to live a boring life, reading over musty books and associating with grey-haired, stiff-backed, stuffy mages!\n\nIf you need my dagger, you'll have to get it back from \"Pretty Boy\" Duncan, one of the Bloodsail Buccaneers. Put something 'tween his shoulders and I'm sure he'll give it up.", progress = "I'd never been beat before, you know, <name>? Sure I'd been cut, can't get in a knife fight without that, but he just smacked me on the side of the head, blacked me out. When I came to my blade was gone.\n\nAs much as my nickname might indicate, I still need a knife to fight, and for me, it has to be that one.", completion = "You beat Duncan? I guess you aren't as wet behind the ears as you looked at first glance.\n\nI suppose that also means I shouldn't challenge you to a fight any time soon!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][611] = {title = "The Curse of the Tides", objective = "Destroy the Altar of the Tides with Catelyn's Blade, kill Gazban and bring the Stone of the Tides and Catelyn's Blade back to Baron Revilgaz.", description = "So you're looking for an altar of some sort? Well, I'm no expert on troll ruins like my father, but I have heard about a sunken troll city out near that island you're looking for. Maybe you should try there.\n\nYou got my knife back for me, so I guess you can borrow it... but I want it back when you're done!", progress = "Have you retrieved the Stone of the Tides for me, <name>? I've already cleared out a space and purchased a fine stand for it.", completion = "Amazing! The Stone of Tides! It shall have a place of prominence in my collection of ancient troll artifacts. Did you see how it almost seems as though a tide is trapped within its surface? Magnificent!", rewards = "You will receive:\n\nRobe of Crystal Waters"}
MultiLanguageQuestData['en'][613] = {title = "Cracking Maury's Foot", objective = "Bring Maury's Key to \"Sea Wolf\" Mackinley in Booty Bay.", description = "Curses!  That swab Maury put a lock on his foot, and I can't open it!  His loot's inside the foot, and that's what he owes me!\n\nWe need to find the key to open the lock.  Maury was known to gamble with the Mosh'Ogg ogres, at their mound to the northeast.  And he told me, when he was still alive, that the last time he went to the mound he was chased off after winning too much.  Maybe the Ogres there have his key.\n\nBut if they do, you might have to kill a load of them to find the right one...", progress = "Ahoy, <name>!  Have you yet found Maury's Key?", completion = "You found it!  Thanks a million, &lt;name&gt;.  You've been a big help to me!\n\nHere you go - you earned this!", rewards = "You will receive:\n\nCollection Plate"}
MultiLanguageQuestData['en'][614] = {title = "The Captain's Chest", objective = "Bring Smotts' Chest to Hecklebury Smotts in Booty Bay.", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  And one of the giants, Gorlash, stole my Captain's Chest.  He said he wanted it for a snuffbox.  The nerve!\n\nI hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBloodband Bracers"}
MultiLanguageQuestData['en'][615] = {title = "The Captain's Cutlass", objective = "Speak with Sprogger.After I lost my first ship to those giants, I bought another. Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains. I found them, but...they beat me. They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger. He was my cook on the Smotts' Revenge, and survived the last attack. He can help you find the giant.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "After I lost my first ship to those giants, I bought another.  Named Smotts' Revenge, I filled it with supplies and crew, and set out to find the villains.  I found them, but...they beat me.  They smashed Smotts' Revenge, killed my second crew and set me on another lifeboat.\n\nThis time another of the giants, Negolash, stole my cutlass.\n\nFace Negolash and bring me my cutlass!\n\nSpeak with Sprogger.  He was my cook on the Smotts' Revenge, and survived the last attack.  He can help you find the giant.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][616] = {title = "The Haunted Isle", objective = "Speak with Baron Revilgaz in Booty Bay.", description = "Baron Revilgaz has had me keep an ear out for rumors of the strange and out-of-place in Booty Bay and Stranglethorn. I don't usually put much stock in ghost stories, but I heard some sailors in the tavern talking about a haunted island off the coast. Water elementals and a raving goblin ghost, they say.\n\nIf you're going to go talk to Revilgaz, could you relay that story to him?", progress = nil, completion = "Interesting. Some time ago, I seem to remember reading a book once that suggested...\n\nAh, of course, a troll legend it was. If what Krazek reports is true, perhaps I will soon be able to add the Stone of the Tides to my collection of ancient artifacts and relics.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][617] = {title = "Akiris by the Bundle", objective = "Bring 10 Bundles of Akiris Reed to Privateer Bloads in Booty Bay.", description = "You looking fer work, <name>? I might have some if you're up for a little challenge.\n\nI got a friend named Groy who makes a killing selling what the naga call akiris reed: it's some kind of valuable ocean reed. Not too sure what it's for, but he pays well for bundles of the stuff.\n\nYa bring me ten stalks of the stuff, and we'll have business to do. The naga were last seen along the beach to the north of here.", progress = "If ya got no business with me, then move along, <name>.", completion = "Well done, &lt;name&gt;. 10 stalks of akiris reed wasn't too much a challenge after all, huh? No offense to the naga, but hey, everybody's gotta make a living.", rewards = "You will receive:\n\nScorching Sash"}
MultiLanguageQuestData['en'][618] = {title = "Facing Negolash", objective = "Bring 10 Barbecued Buzzard Wings and 5 bottles of Junglevine Wine to Captain Smotts' Lifeboat.\n\nKill Negolash, and bring Smotts' Cutlass to Captain Smotts in Stranglethorn.", description = "Negolash is a hungry giant.\n\nWhen the giants destroyed our ship, Negolash went straight for my kitchen.  He wasn't hungry for crew like the other giants.  Negolash wanted wine...and my Barbecued Buzzard Wings.  They're my specialty, and I had to go all the way to the Badlands for the recipe!\n\nIf you want to lure the giant, then get some wine and a heap of buzzard wings.  Put them in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come for sure!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nSmotts' Compass"}
MultiLanguageQuestData['en'][619] = {title = "Enticing Negolash", objective = "This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:\n\n\"Smotts' Revenge\"", description = nil, progress = "This is an abandoned lifeboat.  Printed along its side in scratched, faded paint are the words:\n\n\"Smotts' Revenge\"", completion = "You pile food and drink upon the raft...", rewards = nil}
MultiLanguageQuestData['en'][620] = {title = "The Monogrammed Sash", objective = "Return the Monogrammed Sash to its owner.", description = "This fine sash has the letters \"HS\" embroidered along its hem.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][621] = {title = "Zanzil's Secret", objective = "Bring 12 samples of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", description = "Zanzil the Outcast dwells with his followers in the Jubuwal and Aboraz Ruins, northeast of Booty Bay.  He is exiled from his tribe.  Why? Well...\n\nZanzil has methods of bending the minds of others, and his leaders fear him.  He uses a mixture of jungle plants on his followers to suppress their will and strengthen their bodies.\n\nHis mixture would be worth much to those who wish to control others.\n\nBring me samples of his mixture, and I will find a use for them.", progress = "Do you have the samples of Zanzil's Mixture??", completion = "Ah, very good!  Here is your pay.\n\nAnd here is a little something extra... for your discretion.", rewards = "You will receive:\n\nBelt of Corruption"}
MultiLanguageQuestData['en'][622] = {title = "Return to Corporal Kaleb", objective = "Bring Krazek's Fixed Pot to Corporal Kaleb at the Rebel Camp.", description = "While you were gone I fixed the pot you brought me.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", progress = "Hello, <name>.  Did you make it to Booty Bay?  Did the goblin Krazek fix my pot??", completion = "It's fixed!  This is great, now I can get dinner started!  Thanks so much, &lt;name&gt;.\n\nI hope you were okay in Booty Bay.  That place can get pretty rough, and... I heard rumors that the goblins will sometimes drag drunk sailors to their slave boats and take them to who-knows-where... to do who-knows-what...", rewards = "You will receive:\n\nCap of Harmony"}
MultiLanguageQuestData['en'][623] = {title = "Akiris by the Bundle", objective = "Bring a Bundle of Akiris Reeds to Privateer Groy in Theramore.", description = "<name>, since I have you here, I got a message from Groy while you were gone. He mentioned bein' satisfied with the last shipment that arrived and has a client that wants some more of the stuff right away.\n\nI won't be headin' to Theramore for a week, but if you're willin' to make the journey, there's no reason you can't take the stuff for me.\n\nFeeling adventurous? You do know where Dustwallow Marsh is, doncha? I'd be careful though, Theramore can be dangerous if you're the wrong kind of crowd.", progress = "Yeah?", completion = "What?! I got a lot better things to do then talk to the likes of you, &lt;class&gt;. Make it worth my while or get outta my face.\n\nHuh? Bloads sent ya, huh? Well, whaddaya got for me?\n\n\n\nNot bad, not bad at all. Another bundle will make my client quite happy.\n\nI suppose yer next question's gonna be about money, huh, &lt;class&gt;? Of course it is!\n\nHere, take this coin and some advice: get off my docks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][624] = {title = "Cortello's Riddle", objective = "Solve the riddle!", description = "There is an ornate, well-traveled bridge\nEast of Deadwind and south of Redridge\nUnderneath there waits something for you\nSome call it a hint, others a clue\nThere it will lie for endless tomorrows\nBiding its time in the Swamp of Sorrows", progress = nil, completion = "The soggy parchment contains the next clue....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][625] = {title = "Cortello's Riddle", objective = "Solve the riddle!", description = "A far off land in Kalimdor awaits\nWhere peril has dashed hopes and fates\nEast of Barrens the weather is harsh\nGloom and danger pock Dustwallow Marsh\nBut there lies a clue for those up to the test\nWaiting to be found in a cave in the southwest", progress = nil, completion = "You find a musty scroll.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][626] = {title = "Cortello's Riddle", objective = "Solve the riddle!", description = "To Lordaeron! The great land of turmoil\nWhere brave soldiers with death do toil\nFind your way through the great unrest\nThere you will find the end to this quest\nAlong the coast of the Hinterlands, at the base of the great falls\nUnderneath the water there does your treasure call!", progress = nil, completion = "You open the chest to discover....", rewards = "You will receive:\n\nExplorer's Knapsack"}
MultiLanguageQuestData['en'][627] = {title = "Favor for Krazek", objective = "Bring 4 loads of Lesser Bloodstone Ore to Krazek in Booty Bay.", description = "There is a mountain cave in Drywhisker Gorge, far to the north in the Arathi Highlands.  In that cave is rare ore: bloodstone.  The bloodstone in this cave is not of the highest grade, but even low-quality bloodstone is valuable... to those with the knowledge to use it.\n\nI would like some.\n\nI will fix your crock pot, but while I work on it... bring me samples of bloodstone.  Bring me enough, and I'll even give you a bonus.\n\nOh, and if you don't have the skill to mine it... find someone who does!", progress = "Hello, <name>.  Did you have luck getting the bloodstone?", completion = "Ah, splendid!  That was a big favor you did for me.\n\nHere is your payment...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][628] = {title = "Excelsior", objective = "Bring an Elder Crocolisk Skin to Drizzlik in Booty Bay.", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder saltwater crocolisk. The elders only come out to defend the other saltwater crocs, so you might need to kill a few to draw one out.", progress = "I read somewhere that the saltwater crocolisks are slowly dying out... bad news for my business, isn't it?\n\nAnyways, I hope you have that elder saltwater crocolisk skin for me!", completion = "Great! Thanks to your help I'll have this order filled and sent off to Director Riddlevox on the next boat to Undermine. Ahead of schedule, even!\n\nFor all your hard work, here, I made some extras, so take a pair. It's on Drizzlik.\n\nAnd remember, there's no boot so fine as one of Drizzlik's Excelsior line!", rewards = "You will receive:\n\nExcelsior Boots"}
MultiLanguageQuestData['en'][629] = {title = "The Vile Reef", objective = "Bring a Tablet Shard to Kin'weelay at the Grom'gol Base Camp.", description = "Long ago, a great shudder of the earth sunk an old troll city beneath the waters of the Savage Coast to the northwest.  We call that place the Vile Reef, for murlocs now reside in the ruins of the city, attacking any who draw close.\n\nThere is an old tablet among those ruins that tells the ancient tale of Gri'lek, a hero of troll legends.  The tale is sacred to the Darkspear tribe, and although the tablet is too large to move, I want a shard of it to enshrine in our new home in Orgrimmar.", progress = "I await the Tablet Shard, <name>.", completion = "This is good.  When I return to Orgrimmar I will place this shard in a sacred place.  It will remind us of the might and honor of Gri'lek.\n\nThank you, &lt;name&gt;.  Your deeds mark a growing friendship with the Darkspear tribe.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][630] = {title = "Message in a Bottle", objective = "Slay King Mukla and return to Princess Poobah with the Key to free her.", description = "<name>, I put my faith in you and anyone you can muster to help free me. The great Skymane King Mukla is my captor. He commands the beasts of this island, and they keep me here against my will with the aid of this chain. If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", progress = "I thank my ancestors someone has come to aid me. Do you have the key that will free me?", completion = "&lt;name&gt;, you have saved me from a great dishonor. If it was within my power, I would offer you a place among my tribe. But for now, all I can only offer you is this token for the courage and nobility you have shown.", rewards = "You will receive:\n\nPoobah's Nose Ring"}
MultiLanguageQuestData['en'][631] = {title = "The Thandol Span", objective = "Rhag Garmason wants you to locate Ol' Rustlocke.", description = "A tremendous explosion roared through the hills.  'Twas horrible, I tell you!\n\nGood soldiers died defending the Thandol Span.  Longbraid says we'll take revenge on the Dark Irons before all is said and done.\n\nWe're in a world of hurt though and I don't see any reinforcements in sight.  Longbraid sent Ol' Rustlocke to scout the eastern bridge to see if we could secure it.\n\nThat was days ago.  We haven't the manpower to search for him with Dun Modr under siege.\n\nPerhaps you can find him...", progress = nil, completion = "You search the tiny, dwarven corpse.  Engraved into the helmet you can clearly read: Ebenezer Rustlocke.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][632] = {title = "The Thandol Span", objective = "Report back to Rhag Garmason and show him the parchment you found on Rustlocke's corpse.", description = "It seems as though poor Ol' Rustlocke ran into a Dark Iron ambush.  You notice a parchment next to his clenched fist.\n\nReport the grim news to Rhag Garmason and show him what you found.", progress = "Any sign of Ol' Rustlocke, <name>?", completion = "Oh my, the news is grave....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][633] = {title = "The Thandol Span", objective = "Destroy the cache of explosives.", description = "Heavens no!  Poor Rustlocke.  'Tis quite a tragedy indeed.\n\nWe must not let his death pass in vain.  This parchment you discovered indicates that Kam Deepfury, the mastermind behind the original attack, arranged for a cache of explosives to be stashed just across the Thandol Span, in Arathi Highlands.\n\nIf those explosives make it to the bridge, our major supply line to the north will be severed!  The cache must be destroyed, <name>!  Return to me when your mission is complete.\n\nYou're our only hope.", progress = "The cache of explosives must be destroyed!", completion = "The remaining bridge is saved!  You have done a great service to King Magni and the people of Khaz Modan.\n\nNow if we can only hold out long enough for reinforcements to show...", rewards = "You will be able to choose one of these rewards:\n\nDwarven Guard CloakSwampland Trousers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][634] = {title = "Plea To The Alliance", objective = "Seek out Captain Nials at Refuge Pointe.", description = "I ask of you one more small favor, <class>.  We await the reserves of Ironforge.  However, Roggo has knowledge of an Alliance camp to the north in Arathi Highlands at Refuge Pointe.\n\nTravel there and seek out Captain Nials.  Ask the good Captain if the Alliance can spare some soldiers to help us reclaim Dun Modr and the Thandol Span.", progress = nil, completion = "My condolences go out to Longbraid and his brave soldiers.  The news of the Thandol Span tragedy and the fall of Dun Modr hangs heavy in my heart.\n\nBut Stromgarde has fallen!  Hence our presence here at Refuge Pointe.  We are faced with retaking our own great city.\n\nHonor and duty require that we do not leave the Highlands until Stromgarde raises the mighty banner of the King once again. I will send word to Longbraid that he is on his own...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][635] = {title = "Crystal in the Mountains", objective = "Find the crystal from your vision.\n\nProvided item: \n", description = "This shard pulses as you hold it...\n\nYou feel a sense of pleading coming from the shard, as if someone is trying to communicate, someone who desperately needs your help.\n\nA vision appears in your mind - of the northern mountains of Arathi, and of a brilliant crystal jutting from the earth there.\n\nYou feel drawn to that place.", progress = nil, completion = "This crystal pulses, as if a living force is trapped within it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][637] = {title = "Sully Balloo's Letter", objective = "Deliver Sully Balloo's Letter to Sara Balloo.", description = "The waterlogged and war-torn envelope dissolves in your hands, leaving you with a few pages of a letter in your grasp, written with painstaking care.\n\nThe letter is addressed to a Mrs. Sara Balloo of Ironforge and begins, \"My dear Sara....\"", progress = "You look as though you have traveled a great distance and seen much turmoil in your time, <class>.  These times we live in are trying on the soul.  What news do you bring to me now?", completion = "You say you saw my Sully pinned beneath the icy waters?  Say it isn't so!\n\nLet me read what he wrote....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][638] = {title = "Trollbane", objective = "Travel to Hammerfall in the Arathi Highlands and speak with Zengu.", description = "With Thoras Trollbane dead and Stromgarde in ruins, Vol'jin has instructed that we make every effort to spirit the legendary sword Trol'kalar from the humans' hands, so that we might use it in our coming battles against the trolls of Zul'Gurub.\n\nZengu, one of our seasoned hunters, was dispatched to Hammerfall in northeastern Arathi Highlands to oversee its procurement.", progress = nil, completion = "How you doing, &lt;class&gt;? The task set before us by Vol'jin will be a difficult one, and any assistance you might provide will be appreciated and necessary.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][639] = {title = "Sigil of Strom", objective = "Get the Sigil of Strom for Zengu in Hammerfall.", description = "In ancient times, trolls fought against the Arathorian Empire and our most capable adversary, Lord Ignaeus of Strom, named Trollbane. He rode into battle wielding Trol'kalar--troll slayer, in their ancient tongue.\n\nBut now the sons of Trollbane are weakened, their stronghold brought to ruin.\n\nThe sword is protected by several sigils that were divided among the survivors of Stromgarde, and we must retrieve them.\n\nThe first was taken by the Syndicate, one of their men in Stromgarde should have it.", progress = "Have you located the first sigil yet? It is most likely carried on the person of one of the Syndicate agents in Stromgarde.", completion = "Excellent, mon. That's a good start to collecting the sigils we'll need to remove Trol'kalar from Trollbane's tomb.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][640] = {title = "The Broken Sigil", objective = "Retrieve the 5 Sigil Fragments from the defenders in Stromgarde, and bring them to Tor'gan in Hammerfall.", description = "Thoras Trollbane's tomb is protected by three sigils--the first of which you retrieved from the Syndicate. The other two will be harder to get, as they're held by the firmly entrenched Stromgarde militia.\n\nThe sigil of Thoradin was divided into five pieces by Thoras' son, Galen, and dispersed among the Stromgarde defenders. Retrieve the pieces and bring them to Tor'gan, the troll shaman, he will be able to bind them into the complete sigil.", progress = "Throm'ka, <class>. Zengu informed me that you required my assistance?", completion = "Ah, you need me to reconstruct this sigil? It shouldn't be too difficult... all the pieces seem to be here and the magical structure will be easy to reform.\n\nYou might want to close your eyes.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][641] = {title = "Sigil of Thoradin", objective = "Bring the restored Sigil of Thoradin to Zengu in Hammerfall.", description = "The reconstruction worked flawlessly. The sigil can now be used to unlock the seal on Trollbane's tomb. Return it to Zengu, no doubt he has additional tasks for you to complete.", progress = "<name>! Do you have the second sigil?", completion = "We're halfway to being able to remove Trol'kalar from Trollbane's tomb. We are not exactly sure where the third sigil is, as its holders seem to move around Arathi quite a bit, but I have faith that you'll be able to find it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][642] = {title = "The Princess Trapped", objective = "Gather 12 Motes of Myzrael, then bring them to the Iridescent Shards in Drywhisker Gorge.", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker Kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather Motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, <name>, aid me!", progress = "This cluster of shards looks much like the Shards of Myzrael.  But the same feeling of security does not pulse through them.", completion = "Ah!  You activated these shards.  Already I feel more myself!\n\nBut alas, I am still far from free...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][643] = {title = "Sigil of Arathor", objective = "Retrieve the Sigil of Arathor and return it to Zengu in Hammerfall.", description = "Though they can barely be said to control Stromgarde, let alone the whole of Arathi Highlands, the human prince trots the remnants of his cavalry over the countryside. I can't understand why he does it, but who understands the way the humans think, hm?\n\nWhatever his reasoning, more importantly, he has given one of the sigils to Lieutenant Valorcall, their cavalry leader. Locate him and bring his sigil back to me.", progress = "Valorcall will not be easy to track down, <name>. Mounted on horseback, he can cover ground quickly. Nonetheless, we must have his sigil.", completion = "Losing their cavalry leader will prove a large blow to the Stromgarde defenders. Better yet, it means that we are only one sigil from being able to have Trol'kalar for ourselves.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][644] = {title = "Sigil of Trollbane", objective = "Kill Prince Galen Trollbane and bring the Sigil of Trollbane to Zengu in Hammerfall.", description = "The final of the sigils needed to unlock the tomb of Thoras Trollbane is held by his son personally. He resides deep within Stromgarde, in a chapel in the militia-held districts. Prince Galen is well protected and no slouch of a warrior himself, so this task could prove most difficult.", progress = "You've returned, <name>. Is the line of Ignaeus Trollbane broken?", completion = "Quite a day this is, &lt;class&gt;. The blood of Trollbane will no longer haunt my people, and the sigils needed to take Trol'kalar are in our possession. Soon, very soon, we will strike against the hated trolls of Zul'Gurub.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][645] = {title = "Trol'kalar", objective = "Retrieve Trol'kalar from Trollbane's tomb in Stromgarde.", description = "What's this? With the four sigils brought together, they have formed together to create one sigil. There can be no doubt that this will be able to break the wardings placed upon Trollbane's tomb.\n\nTrollbane's remains are entombed in the Sanctum behind the chapel in Stromgarde. Retrieve Trol'kalar.", progress = "Etchings in the stone upon the face of the tomb of Trollbane match the glowing lines of the Sigil of Ignaeus...", completion = "Matching the lines on the face of Trollbane's tomb with the glowing lines of the Sigil of Ignaeus, a flash of light consumes the Sigil, and the legendary sword Trol'kalar is released from the stone hands' grip.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][646] = {title = "Trol'kalar", objective = "Deliver Trol'kalar to Zengu in Hammerfall.", description = "The light slowly fades, the sword Trol'kalar, held within a stone sheath has been released.", progress = "<name>! Have you taken the sword?", completion = "For generations, the forces of Strom and Arathor ravaged the trolls. Now their greatest weapon is in our hands. Our inching progress in the steamy forests of Zul'Gurub will be no more.\n\nYour assistance has been great, &lt;name&gt;, and the Darkspear trolls are indebted to you.\n\nI will be sure that the sword is delivered to Nimboya at Grom'gol.", rewards = "You will be able to choose one of these rewards:\n\nBlood-tinged ArmorPit Fighter's Shield\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][647] = {title = "MacKreel's Moonshine", objective = "Take MacKreel's Moonshine to Brewmeister Bilger in Southshore.", description = "Had quite a bit of the ol' Moonshine last night!  Longbraid would have my head if he knew that I passed out during my watch.\n\nThe noggin hurts something fierce.  Felt as though a whole brigade of siege engines passed overhead, all that rumbling.\n\nOh my, look at the time! I promised Brewmeister Bilger in Southshore that I'd repay my debt to him by sending some Moonshine.\n\nBut there are just 15 minutes left before I'm overdue!  Take him this batch, would you please?  And hurry!", progress = "What's the good word, <race>?", completion = "Ah, nothing like Foggy MacKreel's Moonshine to warm you up on a brisk day!  And here I was thinking the little bugger was going to be overdue on his bills again. Thank you, friend!  Many thanks indeed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][648] = {title = "Rescue OOX-17/TN!", objective = "Escort OOX-17/TN to Steamwheedle Port, then report to Oglethorpe Obnoticus in Booty Bay.", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-17/TN to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  I need you to escort the robot from its current location to, let's say, Steamwheedle Port!  That should be a perfect place, and long enough, to get things on line!\"\n\n\"Escort it safely to the port, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", progress = nil, completion = "Oh, YOU'RE the great savior of OOX-17/TN!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more developing, but your recovery has saved me countless hours of rebuilding time, as well as many gold pieces in rebinding costs!\n\nPlease, take your choice of any of these items I have.  Hopefully, you will make good use of one of them.  Thank you again for your generous assistance, my robots and I are in your debt!", rewards = "You will be able to choose one of these rewards:\n\nOptomatic DeflectorThermotastic Egg Timer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][649] = {title = "Ripple Recovery", objective = "Talk to Malton Droffers in Orgrimmar.", description = "I've got some salvage work for you, and if you're an aficionado of fine ripple like I am, then you'll love this task.  Ripple!\n\nIt's a drink, you dummy.\n\nAn abandoned Horde outpost has a stash of Hinterlands Honey Ripple from when they were in business.  You can't get fine ripple like that anymore!  One of Malton's dummy associates knows the shot, so you'll go out there and bring me a case of packaged ripple, and two for my own collection!  Talk to Malton, he'll fill you in on the details.", progress = nil, completion = "Oh yeah, about the ripple dad wants!  He wants to sell the ripple to a tavern here in Orgrimmar, but we'll get more money if it is in its original packaging.  I know someone who can do that, and he's in the Hinterlands where the ripple is.  But he's, um, a high elf.\n\nWell, he's a good high elf, as he's not a part of the Alliance.  Well, he's not so much a good high elf as he is a drunken high elf.  He loves, and I mean LOVES the hooch.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][650] = {title = "Ripple Recovery", objective = "Talk to Gilveradin Sunchaser; his camp is located in the Hinterlands.", description = "The elf you will need to talk to is Gilveradin Sunchaser.  He can name any wine, vintage and all, just by smell alone!  He can package up the ripple we need, so you'll need to talk with him.  We need six bottles for packaging, two for dad, and how ever many he'll want... and believe me, he'll want some.  When you've packaged the ripple and got dad's two bottles, come back here!\n\nGilveradin's camp is near some high elf lodge in the Hinterlands, and those high elves are not good.  Trust me.", progress = nil, completion = "Ah, so you know Malton?  He is an old drinking companion of mine.  You see, I have found something that transcends the boundaries of artificial treaties and alliances - alcohol.  Were we all to slake our thirsts on its blissful qualities, we all would be in a much better place spiritually.\n\nAlas, something tells me that your visit here is not to learn of alcohol's redeeming values, now is it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][651] = {title = "Stones of Binding", objective = "Gather the Burning Key, the Cresting Key and the Thundering Key from the Stone of West Binding, the Stone of East Binding and the Stone of Outer Binding.\n\nBring them to the Stone of Inner Binding.", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", progress = "This is the Stone of Inner Binding.  It is the strongest of the binding stones and must be unlocked for the others to open.", completion = "&lt;Myzrael speaks through the stone.&gt;\n\nYou have done it!  You opened the Stones of Binding!  I can feel the shackles about me loosen, and freedom draws ever closer.\n\nYou are a noble &lt;class&gt;, &lt;name&gt;.  My rescuer!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][652] = {title = "Breaking the Keystone", objective = "Find and kill Fozruk. Bring the Rod of Order to the Keystone in the Arathi Highlands.", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n<name>, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", progress = "The Keystone is charged with tremendous geomantic energy.", completion = "You place the rod in the keystone.  And a shudder is felt beneath you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][653] = {title = "Myzrael's Allies", objective = "Speak with Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, <name>.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface.\n\nSpeak with Gerrig Bonegrip.  He is in Ironforge, in a shop of the Forlorn Cavern.  He knows how I can be summoned.", progress = nil, completion = "The Lady told me of your coming, &lt;class&gt;.  You are welcome in my abode for you, like I, serve a higher cause.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][654] = {title = "Tanaris Field Sampling", objective = "Acquire acceptable samples for 8 basilisks, 8 hyenas, and 8 scorpions. Bring the testing kit back to Chief Engineer Bilgewhizzle in Gadgetzan before the power source runs out.", description = "Activating the power source makes the field testing kit start to glow and vibrate.  It would seem to be working as planned.\n\nAccording to Chief Engineer Bilgewhizzle, you now have two hours to collect the data you need in the Tanaris desert.  If you do not collect it within two hours, all the data will be lost and you will need to buy another power source from him.\n\nReturn to him when you have completed the task.", progress = "Well, did you get everything you needed?  If you didn't and the power runs out, everything inside will be ruined and you'll have to start over.\n\nHey, don't look to me for sympathy; I'm all about the Gadgetzan Water Company making a profit, and if that means selling you power sources until we can afford to import water in from the icy springs of Dun Morogh, so be it!", completion = "All right then, it will take me just a second to remove the power source.  After that, you can do with it whatever you like now without having to worry about losing the data inside.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][655] = {title = "Hammerfall", objective = "Speak with Tor'gan in Hammerfall.", description = "It is still clear to me, like yesterday... So many years without hope, with wood and steel to bind me to this terrible place. Then finally, finally! There was the Warchief. Doomhammer in his midnight plate, his warhammer held high.\n\nIt was... too terrible... That the blow of a coward would strike down our greatest hero. From behind he charged on his horse, and then his lance ran him through... I fell to my knees. What hope was there? What hope is there...", progress = nil, completion = "Ah, Gor'mul you speak of. Yes, from what he says, it seems he has never recovered from the death of Doomhammer.\n\nGor'mul was a captive here when Thrall and Orgrim fought to free the camp, but as the earth shook and our brethren escaped, he was left behind. He wandered alone and lost for years without direction or hope, until we returned to establish ourselves here in Hammerfall.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][656] = {title = "Summoning the Princess", objective = "Go to the Shards of Myzrael, summon her and defeat her.\n\nGather her Eldritch Shackles and bind them to the Shards of Myzrael.", description = "You must defeat Myzrael before she grows in strength.  If you do not, then once she has gathered enough power she will challenge her captors!  There are some who think they can control her, but if she can be controlled then why did the giants chain her in the first place??\n\nCrazy logic, eh?\n\nTo defeat her, summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards of Myzrael.\n\nDo that, and she will again be trapped.", progress = "The Shards of Myzrael are now strangely quiet.", completion = "As the eldritch shackles are placed around the Shards, an unhuman wail is heard from far below.  The scream is followed by a roar.\n\nThe Shards of Myzrael no longer invoke feelings of warmth and security as they once did.  Now they pulse with an open menace... as if the thing beneath them holds ill will toward the surface.", rewards = "You will receive:\n\nPulsating Crystalline Shard"}
MultiLanguageQuestData['en'][657] = {title = "Hints of a New Plague?", objective = "Speak to Kinelory.", description = "<Quae begins to go through the folder.>\n\nThis IS interesting. Seems Apothecary Jorell has been working on some deadly experiments here at Go'Shek. Not sure what that has to do with Hillsbrad, but Phin wouldn't like it if we let it continue.\n\nWe had a run-in with some orcs while you were gone, and I'm not in good enough shape to help Kinelory. If you're up for it, she's going to need some protection when she goes down to the farm to steal whatever research Jorell still hasn't sent to Tarren Mill.", progress = nil, completion = "If it brings Phin peace, I'll destroy every single one of the Forsaken personally. He's done so much for us since the plague. We never thought we'd find friends or family again.\n\nWhen you're prepared, come let me know. We'll get started right away.", rewards = nil}
MultiLanguageQuestData['en'][658] = {title = "Hints of a New Plague?", objective = "Find the Forsaken Courier and bring back her Sealed Folder to Quae near the Go'Shek Farm.", description = "So, Phin sent you to check on us? Not surprised--he worries too much.\n\nWe've been watching the farm for days, and Kin claims she saw a courier come out of that small house to the south not long ago.\n\nShe talks a lot, but I can always trust her senses when we're in dangerous areas.\n\nYou wouldn't happen to be a skilled tracker, would you? We think the courier might be carrying notes to Tarren Mill. If we could get our hands on those documents, it might shed some light on what's happening in Hillsbrad.", progress = "We appreciate your help in looking for that courier, <name>.\n\nWhile you were gone, Kin saw an apothecary come out of that same house to the south of here. I'm confident that they're up to no good--I just need proof of it before we go off and do something rash.\n\nHave you had any luck yet?", completion = "Excellent! \n\nLet's see what this is about...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][659] = {title = "Hints of a New Plague?", objective = "Find Quae and Kinelory near the Go'Shek Farm in the Arathi Highlands.", description = "Hail, and well met, <name>. I lead a group of adventurers investigating odd happenings in this area.\n\nMy cousin in Hillsbrad recently put down his dog Stanley because the animal mystically grew to an immense size and savagely attacked anyone who came near him.\n\nI believe the undead are involved, and we're looking for signs to prove as much.\n\nTwo of my companions, Quae and Kinelory, headed to the Go'Shek Farm in the Arathi Highlands, and haven't checked in for days. Find them for me? I grow concerned.", progress = nil, completion = "Try and stay as quiet as possible, traveler.\n\nOrcs don't take too well to being spied on, and there is more to this farm than meets the eye.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][660] = {title = "Hints of a New Plague?", objective = "Protect Kinelory until she returns to Quae.", description = "All right, <name>. I'm ready if you are.\n\nShall we?", progress = "The time for talk is done. Protect Kinelory if you care about the people of Hillsbrad at all.", completion = "You've done a great service for us, &lt;name&gt;. Thank you.\n\nI hope Kin wasn't too much of a handful down there. She's very friendly, but can be just as deadly when you're her enemy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][661] = {title = "Hints of a New Plague?", objective = "Find Phin Odelic in Southshore.", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nThese items she brought back from the farm should at least let Phin get an idea of what's going on out here in Arathi. Just to make sure there's no retaliation after your attack, we're going to stay here for a bit longer. Would you be willing to head back to Southshore and talk to Phin?", progress = nil, completion = "So, the two troublemakers are all right after all? Haha, I'm glad to hear it. I thank you for bringing me news of their whereabouts and status--it pleases me greatly that they are still alive; the two of them are irreplaceable as friends and traveling companions.\n\nBut... it's more important I thank you properly for your help. Here. Take this along with my group's thanks.\n\nWith any luck, we'll figure out what the Forsaken are up to, and put an end to it.", rewards = "You will be able to choose one of these rewards:\n\nDustfall RobesLightstep Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][662] = {title = "Deep Sea Salvage", objective = "First Mate Nilzlix wants you to retrieve the Charts and Logs from the Maiden's Folly and the Spirit of Silverpine.", description = "O'Breen led the ships into the cove.  We were certain this is where the treasure could be found.  The Harbinger docked safely but as the Maiden's Folly and Spirit of Silverpine approached the tides began to lower.  Strangest thing I've ever seen!\n\nThose two ships ran aground into something... some sort of temple in the reef.  They sank so quickly, was quite a tragedy.\n\nWe need to retrieve their Logs as well as their Charts before we leave.  We can't leave that information behind for prying eyes!", progress = "How goes the search and recovery mission, <name>?  We really need to get those Logs and Charts back from the Maiden's Folly and Spirit of Silverpine.\n\nIf the information from those sources were to fall into enemy hands, Fleet Master Seahorn would force us down the plank.\n\nThat is if we ever get out of this mess...", completion = "Knowing this information is secure will bring some ease to the command in Booty Bay.  Well done, &lt;name&gt;.", rewards = "You will receive:\n\nBlack Water Hammer"}
MultiLanguageQuestData['en'][663] = {title = "Land Ho!", objective = "Talk to Captain O'Breen in Faldir's Cove.", description = "Lolo sees a tiny <race>! Always on the lookout, Lolo is!\n\nWelcome to Faldir's Cove.  Captain O'Breen said we'd only be here for a few hours.  Just long enough to gather the treasure and get back to Booty Bay.\n\nBut Lolo thinks we're going to be here a lot longer than that.  We lost the other two ships from our formation.  Poor Spirit of Silverpine and Maiden's Folly.  On the bottom of the sea they rest now!\n\nLolo suggests you talk to Captain O'Breen if you plan on sticking around here.", progress = nil, completion = "Ahoy, matey.\n\n'Twas a horrible mess. Seahorn will have my ship if he finds out what went down.\n\nOne of the Professor's contraptions indicated the lost treasure was near this cove. I brought the Harbinger in to dock and signaled for the Spirit of Silverpine and Maiden's Folly to follow suit.\n\nThen the sea rumbled. The tides lowered and the two ships crashed into the reef.\n\nIt's not just a reef. Something's down there....\n\nHelp my crew out and you'll be rewarded handsomely.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][664] = {title = "Drowned Sorrows", objective = "Captain Steelgut in Faldir's Cove wants you to kill 10 Daggerspine Raiders and 3 Daggerspine Sorceresses.", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", progress = "Bah, maybe I should go kill those naga scum myself.  It's obvious you're not goin' to do it.\n\nMaybe I can find some knitting needles so you can keep yourself busy.", completion = "Nice work out there, &lt;name&gt;.\n\nThose scum deserved what they got. While nothin' will ever bring me ship or me crew back, the death of those naga gives me some solace.", rewards = "You will receive:\n\nSeawolf Gloves"}
MultiLanguageQuestData['en'][665] = {title = "Sunken Treasure", objective = "Escort Professor Phizzlethorpe to the cave and back.", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", progress = "This is no time to talk! The goggles need to be charged with the power of the stone!", completion = "The goggles work perfectly now! Well done, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][666] = {title = "Sunken Treasure", objective = "Doctor Draxlegauge in Faldir's Cove wants you to collect 10 Elven Gems and return the Goggles of Gem Hunting once you are done.", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, <name>, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", progress = "How did the goggles work? Did everything function properly? Adjustments can be made if necessary.\n\nOh, and I'll need those goggles back when you're done. I am sure Captain O'Breen will have many uses for them later on.", completion = "Most superb, &lt;name&gt;! The Captain will be very pleased! And just wait until word gets back to Fleetmaster Seahorn!", rewards = "You will be able to choose one of these rewards:\n\nGnomish ZapperServomechanic Sledgehammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][667] = {title = "Death From Below", objective = "Protect Shakes O'Breen during the attack.", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, <name>?", progress = "To arms!", completion = "We survived the attack!\n\nWe could not have done it without you, &lt;name&gt;.\n\nWe'll be heading out as soon as the tide rises. If you weren't such a promising hero I'd offer you a place on my crew. But I can tell you have bigger fish to fry.\n\nEven if you are a puny &lt;race&gt;....", rewards = "You will be able to choose one of these rewards:\n\nColdwater RingSeafire Band\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][668] = {title = "Sunken Treasure", objective = "Take the Elven Gems to Captain O'Breen.", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, <name>, take these to O'Breen.", progress = "Ahoy, <class>.  What brings you to the bridge?", completion = "So the little gnomes proved their worth after all? I knew we kept those ankle biters around for a reason!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][669] = {title = "Sunken Treasure", objective = "Take the Sample Elven Gem to Fleet Master Seahorn in Booty Bay.", description = "Fleet Master Seahorn will want to hear about our find at once.\n\nBut as you can see, we're not in much of a position to get out of here. Not only is the tide too low, but those damned creatures we disrupted are keeping a close eye on our movements.\n\nYou can be of great service to the Blackwater Raiders if you can get word to Fleet Master Seahorn in Booty Bay that we discovered the treasure and are working on extracting more.  Take him this sample as proof.", progress = "What brings you to Booty Bay, <class>?", completion = "Ah, leave it to good old Shakes O'Breen! I knew that he was the right Captain for the mission!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][670] = {title = "Sunken Treasure", objective = "Deliver Seahorn's Letter to Shakes O'Breen in Arathi Highlands.", description = "Say, <name>, you seem to be an adventurous type. My fleet is stuck in Booty Bay until we can restock.\n\nThere are some heavy things brewing here and abroad and I need to get some top secret correspondence to Shakes O'Breen who is tied up off the Arathi coast.\n\nCan I trust you to deliver this message safely and in confidence?", progress = "So was Seahorn impressed? I bet you his smile reached from Booty Bay to Ratchet.", completion = "Thank you for making such a long and perilous journey. You have the gratitude of the Blackwater Raiders.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][671] = {title = "Foul Magics", objective = "Get 10 Bloodstone Amulets for Tor'gan in Hammerfall.", description = "I have felt a strangeness in the air... a feeling that simmers in my blood. I had my suspicions. I set off to find the source of my unease and discovered to the west, at Northfold Manor, the residual traces of demonic summoning. As I got close, my blood began to boil and the rage within me grew.\n\nOn the ground I spied an amulet of bloodstone, used to assist in demonic summoning. The one I found was depleted, however. I'll need another to examine, but I dare not return to the manor. Can you bring me some?", progress = "Once-cursed blood still runs through my veins, <name>. If someone... something is summoning demons, it must be stopped.", completion = "It will take some time for me to ascertain the true intentions of the Syndicate, but their obvious association with dark, demonic magic troubles me. I will tell you when I know more.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][672] = {title = "Raising Spirits", objective = "Acquire 10 Highland Raptor Eyes from Highland Striders and Highland Thrashers for Tor'gan in Hammerfall.", description = "We tried to settle him in, cheer him up, telling him stories of our mighty city at Orgrimmar in Kalimdor, but nothing would move him.\n\nTales of our young Warchief, Thrall, who bears the armor and hammer of Orgrim... but, perhaps... Perhaps! A demonstration of our newly found shamanistic magic would give him new hope. It is worth a try!\n\nA small object we could make for him, yes... Bring me some raptor eyes, and I will see what I can do.", progress = "I will create an amulet that will give Gor'mul some of the strength of the raptors. Perhaps that will awaken some flame within him...", completion = "Excellent. The spirits of the raptors that gave these eyes will lend strength to the bearer of this amulet.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][673] = {title = "Foul Magics", objective = "Retrieve Marez Cowl's Bloodstone Orb and bring it to Tor'gan in Hammerfall.", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of his energy.\n\nFind the warlock and kill him. Bring me whatever magical object you find on his person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", progress = "The burning in my blood... it grows by the day. The warlock must be stopped.", completion = "My restless nights will turn to peaceful slumber when I have destroyed this orb. Thank you, &lt;name&gt;. It is a chilling reminder of the terrible power the demons held over the orcs before Hellscream released them from their curse.", rewards = "You will be able to choose one of these rewards:\n\nWhite Drakeskin CapRadiant Silver Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][674] = {title = "Raising Spirits", objective = "Give the Raptor Talon Amulet to Gor'mul.", description = "Here, take this amulet to Gor'mul, and see if the raptors' strength can awaken the flame of the warrior that once burned through his veins.", progress = "What hope is there when the hand of a coward can slay the mightiest of the mightiest? What hope, I ask you!", completion = "What is this? Polished bone. What use have I for polished bone? Will a trinket restore the Horde to its glory?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][675] = {title = "Raising Spirits", objective = "Speak with Tor'gan.", description = "<Gor'mul tosses the amulet into the ground.>\n\nTor'gan sent you, didn't he? Pah! Why he feels some mercy towards me I would not understand. Mercy was denied me when I was not allowed to die with my Warchief in battle. A cruel blow fate has dealt me...", progress = nil, completion = "It did not work, I see. Nonetheless, I feel that showing him the power of the shamans will eventually return Gor'mul to his once proud self. The amulet's power was not great enough to show him our newfound power.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][676] = {title = "The Hammer May Fall", objective = "Kill 8 Boulderfist Ogres and 10 Boulderfist Enforcers, then find Drum Fel in the Hammerfall outpost in Arathi Highlands.", description = "Weaklings... all of them. You, <class>, what are you looking at? Think you're something special, huh? Why not prove it?\n\nThe Hammerfall outpost in Arathi's under attack. Unless we send them help soon, their demise is imminent.\n\nBut before you go rushing off, you may want to test your skills first. Northeast of Stromgarde in Arathi is an ogre mound inhabited by the Boulderfist tribe. When you can handle the ogres and enforcers there, then report to Drum Fel in Hammerfall.", progress = "I have not the time to sharpen my axe, let alone leave the outpost to slay those beasts that would try and slay my kin.\n\nYou do not seem to have the experience of a grunt let alone a full-fledged <class>, what do you want, <name>?", completion = "So, you think you're strong enough to help Hammerfall? So be it.\n\nTallow either sent you to that ogre mound in the hopes that you would kill yourself or he thinks you're strong enough to aid us. Either way, you're here now and I am in need of more soldiers in our fight against the constant attacks.\n\nIf you plan on staying in Hammerfall then get some rest, and come speak to me again when you're ready. There's no shortage of fighting to be had.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][677] = {title = "Call to Arms", objective = "Slay 10 Witherbark Axe Throwers, 10 Headhunters and 8 Witch Doctors, and return to Drum Fel in the Hammerfall outpost.", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", progress = "If you have not yet completed my task, then perhaps you are a coward in heart as well as a tyro in war.", completion = "The signs of war are upon your garments, and sweat drips from your brow. Good, very good indeed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][678] = {title = "Call to Arms", objective = "Kill 10 Boulderfist Brutes and 4 Boulderfist Magi, and return to Drum Fel in the Hammerfall outpost.", description = "Your strength is evident, <name>. Now to see how you fare against a real enemy.\n\nThe Boulderfists have a lair to the southwest of here towards the dwarven bridge, and, if I'm not mistaken, the maulers and magi there shall present to you a greater challenge--they have done so to us thus far.\n\nSlay as many as you can and come to me in body when you are successful, or come to me in spirit when you fail. I shall give praise to your tenacity in battle either way.", progress = "You hesitate. Why? You have shown great strength thus far, <name>. Do not fail me now.", completion = "You are as strong as a kodo, and your lust for battle does your people proud.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][679] = {title = "Call to Arms", objective = "Kill 7 Boulderfist Shaman and 3 Boulderfist Lords and return to Drum Fel in the Hammerfall outpost.", description = "The head of the beast is ready to be taken off... with great force, <name>. You have shown every sign that you are able to help us with this final mighty blow. The leaders of these attacks have made their lair within the ruins of Stromgarde, a glaring symbol of human frailty.\n\nFind and slay those Boulderfist lords and their lackey shaman who would try and drive us from these lands.", progress = nil, completion = "You do your people proud, &lt;name&gt;. The threat has been greatly lessened, and I am sure we will begin to thrive here in the Highlands.", rewards = "You will be able to choose one of these rewards:\n\nSilent HunterSkullsplitter\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][680] = {title = "The Real Threat", objective = "Slay Or'Kalar and bring his Head to Korin Fel in the Hammerfall outpost.", description = "You serve my husband well, <class>, but he does not know why Hammerfall is under attack.\n\nOr'Kalar, Mug'thol's pawn in Stromgarde, has an intense hatred for my husband, and wishes nothing more than my husband's death for defeating him years ago.\n\nMy auguries tell me that Or'Kalar has laid a trap for my husband, so I have hidden signs of the ogre's presence from him.\n\nMy husband will rush off foolishly if he learns of the ogre's whereabouts and I would ask for your help in slaying the creature.", progress = "Near the Tower of Arathor--that is where you will find Or'Kalar. His death will stop the attacks on Hammerfall and protect my husband's life.\n\nI see in your eyes that you think me weak--even dishonorable--for my silence. Some day you will learn what it is to love as I do. Perhaps then you will understand a different kind of strength and honor.\n\nIn the meantime, do as I ask, and slay Or'Kalar.", completion = "You have done me a great service, &lt;name&gt;. Know that my husband's life and the safety of Hammerfall has been protected for another day because of your deeds. Please take this as a reward for your courage.", rewards = "You will be able to choose one of these rewards:\n\nMistspray KiltSword of Hammerfall\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][681] = {title = "Northfold Manor", objective = "Kill 10 Syndicate Highwaymen and 6 Syndicate Mercenaries.\n\nReturn to Captain Nials at Refuge Pointe.", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nWe need help from the town of Southshore, but supplies are difficult to receive while the Syndicate holds territory between us.\n\nGo to the Syndicate base in Northfold Manor and slay them.  Then, perhaps, pressure on our supply trains will lessen and more will get through.", progress = "<name>, with each passing hour our hold on Stromgarde grows more tenuous.  You must make haste or our city will surely fall.", completion = "Very good, &lt;name&gt;.  With the deaths of those Syndicate members we should have an easier time receiving supplies from Southshore.\n\nPerhaps our cause yet has hope.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][682] = {title = "Stromgarde Badges", objective = "Bring 7 Stromgarde Badges to Captain Nials at Refuge Pointe.", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", progress = "Have you retrieved any Stromgarde Badges, <name>?  The Syndicate must learn they cannot profit from our dead.", completion = "Thank you, &lt;name&gt;.  We will inform the families of these fallen soldiers that they were killed in battle.\n\nIt will be grim news to bear, but it is better than the uncertainty of a missing loved one.", rewards = "You will receive:\n\nStromgarde Cavalry Leggings"}
MultiLanguageQuestData['en'][683] = {title = "Sara Balloo's Plea", objective = "Take Sara Balloo's note to King Magni Bronzebeard of Ironforge.", description = "<name>, I have but a small request to ask of you.\n\nTake this note I have prepared to our great monarch of Ironforge, King Magni Bronzebeard. 'Tis a small task to ask of one such as yourself, someone who has shown great valor to the cause of the Alliance thus far.\n\nFor me to go before the King in my grief-ridden state would not serve the purpose of my cause.  Surely you understand.", progress = "So you are <name> the <class>? News of your contributions to the Alliance has traveled quite far, you know?\n\nOn what business do you come before me today?", completion = "It will take but a moment for me to peruse this letter...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][684] = {title = "Wanted! Marez Cowl", objective = "Bring Marez's head to Captain Nials at Refuge Pointe.", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning Warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", progress = "Greetings, <class>.  You have a report to make?", completion = "You took down Marez Cowl?  Well done, &lt;name&gt;.  Well done indeed!\n\nMarez menaced our Stromgarde defenders, and it is rumored she was an emissary between the Syndicate and some other, darker power.  We are glad to see that she'll no longer ply her powers against us.", rewards = "You will receive:\n\nArcane Runed Bracers"}
MultiLanguageQuestData['en'][685] = {title = "Wanted! Otto and Falconcrest", objective = "Bring Otto's Head and Falconcrest's Head to Captain Nials at Refuge Pointe.", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", progress = "Hello.  Do you have a report to submit?", completion = "Falconcrest and Otto?  Wonderful!\n\nHere is your reward, &lt;name&gt;.  I am happy to pay it.", rewards = "You will be able to choose one of these rewards:\n\nRod of SorrowWar Rider Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][686] = {title = "A King's Tribute", objective = "King Magni Bronzebeard wants you to speak with Grand Mason Marblesten.", description = "I do not expect good dwarves like Mrs. Balloo to understand why the travesties of war must be endured for the greater good of our people. The loss of her husband, and the loss of every dwarf that fights in the name of the Alliance, weighs heavy on my soul.\n\nWhile I cannot bring her husband back from the Twisting Nether, I can pay tribute to him.\n\nI am going to commission a memorial to Sully Balloo to be built by Grand Mason Marblesten.\n\nSend word to him now, <class>. You shall be custodian of my bidding.", progress = nil, completion = "So King Magni Bronzebeard himself sent ye?\n\nMy, my! This must be important!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][687] = {title = "Theldurin the Lost", objective = "Find Theldurin the Lost.", description = "Theldurin the Lost was once a member of our order, the Twilight's Hammer.  But he lost his mind and scorned our teachings.  And before he fled from us, he stole the scroll of Myzrael!  We could not catch him, but rumors say he hides in the Badlands, gibbering and mad.\n\nTo bring the Lady back to us, you must find the scroll.  And to do that, you must find Theldurin.", progress = nil, completion = "Hello.  Hello, hello hello hello hello HELLO!\n\nI'm sorry - wait, no I'm not!  Don't be rude!\n\nOh no...that was crazy talk.\n\nBut...sometimes being crazy is my only solace.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][688] = {title = "Myzrael's Allies", objective = "Speak with Zaruk in Hammerfall.", description = "<Myzrael speaks.>\n\nFree!  I AM FREE!  I am free to gather strength, hidden from my captors.  For if they faced me now they would surely overpower and again imprison me.\n\nBut in time I will confront the giants, and they will regret their wardship of me!\n\nYou are a noble ally, <name>.  I will need your help again in time.  When I am ready, I will need you to summon me to the surface\n\nSpeak with Zaruk in Hammerfall.  He knows how I can be summoned.", progress = nil, completion = "Welcome, &lt;class&gt;.  The Lady has informed me of your coming, and if we are to bring her back to the surface then we have much to discuss...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][689] = {title = "A King's Tribute", objective = "Grand Mason Marblesten of Ironforge wants 5 pieces of Alterac Granite.", description = "So our good King would like a memorial built in honor of a soldier named Sully Balloo?  And you say the poor chap died during the Thandol Span tragedy?\n\nBah, will there ever be peace on Azeroth?\n\nNonetheless, any commission from the King is of utmost importance. To build a truly epic and lasting piece I want to work with one of the finest stones available. Travel to Darrow Hill in Hillsbrad and gather for me some Alterac Granite.", progress = "<name>, <name>, <name>! Tell me you have enough Alterac Granite for me to begin my masterpiece in honor of Sully Balloo.", completion = "Perfect! Better than I could have imagined!\n\nAnd I have quite an imagination you know...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][690] = {title = "Malin's Request", objective = "Find Skuerto at Refuge Pointe in the Arathi Highlands.", description = "Greetings, <name>. You have the look of an adventurer about you, and I have a task that needs some tending to.\n\nArchmage Trelane, my original master, fled Stromgarde in the Arathi Highlands not too long ago, and he's asked me to help him in recovering some of the items he left behind.\n\nThe city fell under siege, and he attempted to defend the Tower of Arathor, but to no avail. I have agents in the Highlands already, but they've requested I send more aid. Are you interested?", progress = nil, completion = "So, Malin sent ye? I don't care if Muradin rose up from the dead and whisked ye here on a dragon. I'm busy! Talk to Kryten if you need somethin'.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][691] = {title = "Worth Its Weight in Gold", objective = "Find 10 Witherbark Tusks, 4 Witherbark Medicine Pouches and a Shadow Hunter Knife for Apprentice Kryten at Refuge Pointe.", description = "Archmage Malin sent Skuerto and I here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need the following: Witherbark tusks, Witherbark medicine pouches and a shadow hunter knife.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", progress = "Have you had any luck so far, <name>?\n\n\n\nIf my research is correct, the tusks should come from any Witherbark troll. The medicine pouches come from the Witherbark witch doctors, and the strongest of the Witherbark shadow hunters should carry the special knife given to them after they've completed their rites of passage. There's no way to tell which shadow hunters will have the knife until you do battle.", completion = "Incredible! I can see why Malin asked you to come join us--very well done indeed!\n\nAt this rate, Skuerto and I will be headed back to Stormwind in no time at all.\n\nI believe my dwarven companion is back from scouting Boulderfist Hall; go speak to him when you're ready.\n\nIt looked as though he might have had a bit of a scuffle with the ogres. Don't mention that to him, though; he's very sensitive about criticisms to his skills at scouting.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][692] = {title = "The Lost Fragments", objective = "Bring the Torn Scroll Fragment, the Crumpled Scroll Fragment and the Singed Scroll Fragment to Theldurin the Lost.", description = "The Scroll of Myzrael...the Scroll of Myzrael?!  You don't want that!  Its magic can pull Myzrael to the surface world and if you do that, we are in trouble!\n\nOr...maybe it's too late.  Maybe she already is free.  Maybe she's just gathering strength before unleashing herself upon us.  If so, then you'll NEED the scroll!\n\n...too bad it's destroyed.  Enraged elementals stole it and tore it up and now fight over the fragments.\n\nBut if you can gather those fragments, maybe we can fix it...", progress = "Did you find those fragments?!?!  You'll need the Scroll of Myzrael if you want to trap her again, before it's too late!", completion = "Ah, you found them!  Good work, &lt;name&gt;! These might be the only chance we have against the evil of Myzrael!\n\nJust let me find my scrap-ratchet and see if I can re-attach these fragments...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][693] = {title = "Wand over Fist", objective = "Find Trelane's Wand of Invocation and return it to Skuerto at Refuge Pointe.", description = "Hey, <name>. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", progress = "Our goal is the wand, <name>. Focus on that for now.", completion = "Brilliant, &lt;name&gt;. One item down an' three more to go, based on my list. The other three items are all in Stromgarde.\n\nTake a rest an' get your strength back--the next phase of my plan'll require a little more time an' effort. Come back to me after you've gotten a warm meal an' some rest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][694] = {title = "Trelane's Defenses", objective = "Find an Azure Agate and bring it to Apprentice Kryten at Refuge Pointe.", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to activate the tower's defenses if you're gonna stand a chance against 'em an' still make it to the items alive. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant 'em so they'll work as a key.", progress = "<name>, hello again. Have you found an azure agate yet?", completion = "You amaze me, &lt;name&gt;. Well done again.\n\nGive me a moment to cast the proper spell to enchant the gem, an' you'll be ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][695] = {title = "An Apprentice's Enchantment", objective = "Speak to Skuerto.\n\nProvided item: \n", description = "Here you are, <name>. The gem only needs to be pressed against one of the pedestals near the base of the tower to activate its defenses. Use it when you're ready to enter the tower and find Trelane's remaining items. \n\nGood luck to you. I'll be awaiting your return here at the camp. Oh, and speak to Skuerto before you leave. He'll give you the rest of the details you'll need.", progress = nil, completion = "Good, good.\n\nIf there are no other delays, how about we get started?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][696] = {title = "Attack on the Tower", objective = "Find Trelane's Phylactery, Trelane's Orb, and Trelane's Ember Agate, and return them to Skuerto at Refuge Pointe.", description = "Here's what your lookin' for: Trelane's phylactery, Trelane's orb, an' Trelane's ember agate.\n\nAll three should be in chests within the tower an' you shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nThe tower's defenses won't take care of 'em on their own; you'll need to have your weapons at the ready. Those ogres find out you're there and stealing from 'em, an' they'll be sure to put the hurt on you.\n\nBe careful, an' good luck.", progress = "You do this, an' I'm sure Malin'll be more than pleased with you.", completion = "Malin couldn't've asked a worthier person to come here an' aid us, &lt;name&gt;. You've done a grand job!\n\nHe'll be pleased to see what an overwhelming success our mission's been.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][697] = {title = "Malin's Request", objective = "Take the Sealed Letter to Archmage Malin in the Mage Quarter of Stormwind.", description = "Take this letter back to Stormwind and let Malin know that Kryten an' I'll be home soon. He'll reward you well for helping us here, <name>, of that I've no doubt.\n\nTravel safely.", progress = "Yes? You look vaguely familiar. I do apologize, but have we met? I get so busy I lose track.", completion = "&lt;Archmage Malin opens the letter, and his eyes grow wide.&gt;\n\nBy the Light, you've done it. How wonderful. Trelane will be so pleased. I'm sure Kryten and Skuerto are just as excited as I am to have them on their way back to Stormwind.\n\nThank you, &lt;name&gt;. Please, take this to help you in your journeys.", rewards = "You will be able to choose one of these rewards:\n\nVigilant BucklerWingborne Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][698] = {title = "Lack of Surplus", objective = "Bring 8 Unprepared Sawtooth Flanks to Tok'Kar in Swamp of Sorrows.", description = "I'm working on getting some supplies together for our outpost near the beach to the east--Tok'kar does what he can, but between shifts of guard duty and cooking for his soldiers there's not much time left in the day.\n\nThey do enjoy cooking up some sawtooth meat when they can, but I haven't had time to get them another shipment. Would you mind helping them out?\n\nThe young sawtooths aren't as tasty as the older ones, so stay clear of those; give them a year or two to get to full size.", progress = "Lok'tar, <class>. Traveling through the swamps isn't a risk taken lightly. You're brave to test your mettle here.", completion = "Ah! Wonderful. Fresh meat for the fire tonight. Thank you, &lt;name&gt;.\n\nYou've helped make the coming nights more tolerable. The fire burns bright, and our stomachs will be full.\n\nIt's a pleasant surprise to have you bring us a shipment; Dar's not the most attractive orc anyone's laid eyes upon, but at least his attitude reeks far less than his smell.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][699] = {title = "Lack of Surplus", objective = "Bring 6 Sawtooth Snapper Claws to Tok'Kar in the Swamp of Sorrows.", description = "With the threat of murlocs along the coast, we're stationed out here to protect--or warn if the force is too large--of any coming threats to Stonard. It doesn't give us much time for relaxation, and we could use some more help if you're able.\n\nThe sawtooth snappers' claws make for fine weapons when properly prepared. Bring me some of their claws and I'll see you're rewarded with one of our weapons in thanks for the fresh meat and the good company.", progress = "Good mead, a warm fire, an army of orcs and an arsenal of weapons... that's all we really need out here along the coast. I don't regret my position out here safeguarding Stonard, but it would be nice if we could one day get a burrow, or at least a tower.", completion = "Glad to see you're alive and well, &lt;name&gt;.\n\nThese claws should make do nicely. The more weapons we have at the ready for attacks against us, the better off we'll be.\n\nI'll get started on your weapon as soon as possible. It will only take a short time. I've become quite adept and quick at their production.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][700] = {title = "A King's Tribute", objective = "Report to King Magni Bronzebeard.", description = "Ah, such fine stone comes from Lordaeron.  Such a shame the land is in such shambles.\n\nBut the Memorial came out quite well! I should think the King will be most pleased with it.\n\nNow if you will, please send word to His Majesty that the Memorial is complete as requested.", progress = nil, completion = "The granite seems but a small token compared to a great dwarf's life. But no dwarf shall last on this planet for eternity.\n\nLet us just hope that the memorial stands as a reminder to those who will trod the great Azeroth of the future.  Lest we not forget it is for them that brave soldiers such as Sully Balloo so valiantly gave their lives.", rewards = "You will receive:\n\nIronforge Memorial Ring"}
MultiLanguageQuestData['en'][701] = {title = "Guile of the Raptor", objective = "Acquire 12 Raptor Hearts from Highland Fleshstalkers for Tor'gan.", description = "With some additional objects, I will be able to create an item that will imbue Gor'mul with the guile of the raptor! With the power of the raptor flowing through him, Gor'mul will know our new power and rediscover the warrior that lies dormant!\n\nI will require raptor hearts to fashion the item and spell.", progress = "My preparations are made, all I require are the raptor hearts.", completion = "Yes, these will work perfectly. I will transfer their power and the spirit of the raptors into this orb. This orb will imbue Gor'mul with the fiery strength and intelligence of the raptor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][702] = {title = "Guile of the Raptor", objective = "Give Tor'gan's Orb to Gor'mul.", description = "Take this orb and use its energy to give Gor'mul the essence of the raptor. Surely this will invigorate his spirit and give him new purpose in life. With him returned to normal, we can explain to him the current state of the Horde, and we will have a great warrior's assistance in our unceasing battles.", progress = "Returned again have you? Indeed there is nothing more I could wish for now than more of Tor'gan's pity.\n\nWhat have you for me this time? Perhaps a piece of brightly colored string? Or a length of rope to end this misery of mine...", completion = "At least it is something interesting you bring to me this time. A strange power it emits...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][703] = {title = "Barbecued Buzzard Wings", objective = "Bring 4 Buzzard Wings to Rigglefuzz.", description = "Oh yes, my barbecued buzzard wings are a favorite!  The sauce is rich and the meat is tangy.  And the smell will bring the hungry running from miles away!\n\nI have everything I need to cook up a batch.  Everything...except the buzzard wings!\n\nIf you want some then get me the buzzard wings.  Bring me enough, and I might even share the recipe with you!", progress = "Hello, <name>.  Did you bring me my wings?", completion = "Ah, I'll get started on those wings right away.  I can almost taste them already!\n\nAnd here's the recipe in case you want to make them yourself!", rewards = "You will receive:\n\nBarbecued Buzzard WingRecipe: Barbecued Buzzard Wing"}
MultiLanguageQuestData['en'][704] = {title = "Agmond's Fate", objective = "Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan.", description = "The last report I received from Agmond is troubling, more so now that he's dead!  He mentioned that his diggers uncovered \"ancient urns\" at the dig site outside Uldaman.  I fear that the urns he found at that site incited the troggs, just as did the idols I found here.\n\nI need you to get those urns for our studies.  Go to the Uldaman site, gather the urns, then return to me.", progress = "Did you find those urns, <name>?  We must find the link between them and the troggs!", completion = "Well done!  With luck and diligence, we will find whatever link exists between the troggs and these ancient artifacts.  \n\nYou have done a great deed for the Prospectors, &lt;name&gt;.  Your efforts will not be forgotten.  And neither will Agmond.", rewards = "You will receive:\n\nProspector Gloves"}
MultiLanguageQuestData['en'][705] = {title = "Pearl Diving", objective = "Bring 9 Blue Pearls to Rigglefuzz in the Badlands.", description = "The Badlands is a harsh place, filled with vicious predators and bold scavengers.  Scary, especially for a short little goblin.  To survive, I have to be tricky!\n\nI know the recipe for flash bombs.  I use those to scare away wildlife.  But I'm running low on one of the ingredients: crushed blue pearl powder.  Get me some and I'll make it worth your efforts.\n\nHeh, and I hope you have good boots on.  The Blue Pearls I need are found from clams at the Vile Reef.\n\nYep, the Vile Reef in Stranglethorn!", progress = "Did you get my pearls?  I'm almost out of flash bombs!", completion = "These will work great!  I just need to smash them into powder...then mix them with a little of this and a little of that.\n\nWatch out, scavengers!  Prepare to be flashed!", rewards = "You will be able to choose one of these rewards:\n\nFlash RifleFlash Wand\n\nYou will also receive:\n\nFlash Bomb"}
MultiLanguageQuestData['en'][706] = {title = "Fiery Blaze Enchantments", objective = "Acquire a Black Drake's Heart for Sigrun Ironhew.", description = "As an apprentice to Feranor Steeltoe, I learned his special technique for imbuing weapons with fiery enchantments. Last I heard of him, he was working at a smithy with a hunting party up in Lordaeron.\n\nI can't tell you too many of the details about the process, but I can tell you it requires blood from a rare, still-beating black drake whelp's heart. I don't have much to do waiting for word from Ironforge. If you bring me a heart from the whelps in Lethlor Ravine, I'll show you my skill!", progress = "How goes the hunt, <class>?", completion = "Ah yes, this will do excellently. This will enable your weapons to strike with searing heat!", rewards = "You will receive:\n\nFiery Blaze Enchantment"}
MultiLanguageQuestData['en'][707] = {title = "Ironband Wants You!", objective = "Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan.", description = "<name>.  I received reports from Prospector Ironband at his excavation site in Loch Modan--he needs some legwork done concerning another of our excavations.\n\nI don't have more details than that, but if you want to stretch your legs then go speak with Ironband.", progress = nil, completion = "So Stormpike sent you, did he?  Good.\n\nI have a big task for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][708] = {title = "The Black Box", objective = "Take the Corroded Black Box to the Hall of Arms in Ironforge.", description = "The surface of this metallic black box is heavily pitted, as if it had been immersed in acid - it must have been sitting in the giant condor's stomach for a long time.\n\nTurning the box over, a symbol is found stamped on its bottom.  Below the symbol are the words:\n\n\"Engine #19 - Ironforge Siege Brigade\"You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][709] = {title = "Solution to Doom", objective = "Bring the Tablet of Ryun'eh to Theldurin the Lost.", description = "Oh my!  Oh my!  There is a doom approaching.  Mark me!  A doom!\n\nNo, I cannot speak of it...cannot utter their names or they may hear me!  But if we learn, yes, if we learn more of them...then maybe we can learn how to foil them!\n\nMaybe.\n\nGo into Uldaman.  No!  I said it!  You must find...find the tablet of...Ryun'eh.  Yes, find it!  And don't make me speak that name again!\n\nIt is deep in that place, in an ancient chest.  That's where it hides...in a chest crafted before the works of any dwarf.", progress = "Did you find the tablet?  It must hold secrets!  Secrets to save us!", completion = "Oh, fortune is with us!  Thank you!  We may yet be saved!", rewards = "You will receive:\n\nDoomsayer's Robe"}
MultiLanguageQuestData['en'][710] = {title = "Study of the Elements: Rock", objective = "Find 10 Small Stone Shards and bring them to Lotwil Veriatus in the Badlands.", description = "Here in the Badlands I've stopped to work on my latest project: my shackles of elemental binding.\n\nWhen complete, they will allow mages to summon even more powerful elementals for use in even greater capacities. To start things off, I need small stone shards to test some of my newest offensive spells along with a few gizmos I've pieced together.\n\nThe shards are easily collected from the lesser rock elementals to the west of here. Could you bring me some?", progress = "This area's perfect for-- Could you hold these in place for a moment? Yes, just like that, along the vector normal. Now, what was I... Right. Perfect for testing my latest project. The raw materials, the open space... what more could an intelligent and enlightened practitioner of the arts ask for?", completion = "These shall do nicely, &lt;name&gt;. Thank you. Hmm, a bit more sand than I'd anticipated. Have to adjust the coefficient of friction. No, wait; it should still be negligible with the frost oil.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][711] = {title = "Study of the Elements: Rock", objective = "Bring 3 Large Stone Slabs to Lotwil Veriatus in the Badlands.", description = "<name>, you've already proven more able than all my apprentices combined.\n\nThe next parts I need require a little more strength. Large stone slabs can be found on rock elementals if you're careful enough. Their bodies are stronger and larger, and therefore more prone to having pieces large enough for my tests. You can find them further west of here or southeast along the mountains' edges.\n\nTake your time; I'll need a while to test these smaller pieces you brought me.", progress = "I'm most pleased, <name>. My spells affected the smaller pieces just as I predicted. If this experiment is as successful as I foresee, then the elementals I'll be able to control will put anything summoned prior to this to shame.", completion = "&lt;name&gt;, simply amazing! I would have thought it'd take half a dozen tauren to bring all these to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][712] = {title = "Study of the Elements: Rock", objective = "Bring 5 Bracers of Rock Binding to Lotwil Veriatus in the Badlands.", description = "<name>, there's one more part I need from the elementals here in the Badlands: the bracers of rock binding from the greater rock elementals. By my calculations, those bracers should be enough to gauge the strength of my own shackles.\n\nMy attempts at scrying the greater rock elementals showed a group of them southwest of here, near some ogres if I recall.\n\nBring me 5 of their bracers just so I have extras. Servo's notorious for misplacing my reagents and research.", progress = "The stone slabs you found were ideal, <name>. Lucien will be taking the extra ones back to Kharanos when we're done here. After all, they could prove useful again.\n\nFor instance, they'd be a nice basis for a handy little shelter once I start looking into a multidisciplinary approach to high-yield explosives...", completion = "&lt;name&gt;, have you ever considered becoming a research assistant? No? I'm not sure what I'll do without your abilities here. Intelligence, curiosity, and strength--all combined into one package.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][713] = {title = "Coolant Heads Prevail", objective = "Find Frost Oil and bring it to Lotwil Veriatus in Badlands.", description = "Let me tell you something about Frost Oil: nothing can keep an engine or gears from overheating quite like it.\n\nIts cooling properties are extraordinary, and its longevity as a lubricant without equal. That's not all: it also aids in retaining enchantments on magical items.\n\nI need a vial of it to increase the magical capacity of my shackles and make them powerful enough to stop our summoned friend from killing us all.\n\nBro'kin, a goblin friend of mine, can teach you to make it. He's in Alterac.", progress = "Have you found the oil I need? It would be so helpful if you were able to find some.", completion = "Stupendous! This should be the perfect coolant for my new bracers. If the enchantments don't last a century, then I'll give all my belongings to Servo.\n\nAll the mages of the Assembly will be in such awe after I finish this, &lt;name&gt;. You just wait and see.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][714] = {title = "Gyro... What?", objective = "Bring a Gyrochronatom to Lotwil Veriatus in the Badlands.", description = "<name>, you've done your job well beyond all standards.\n\n<Lotwil's obviously distracted by his work.>\n\nIf we ever meet in Kharanos, feel free to come apply for work.\n\nWhoops! Quick, grab the... yes, that. Thanks.\n\nNow I just need one more thing. It's a small part, but rather crucial, I'm afraid: a gyrochronatom.\n\nIf you could just go grab one and bring it to me, I should be ready to complete this.", progress = "Yes, yes, yes. Just a moment.\n\n<Lotwil continues to work on some kind of contraption.>", completion = "HA!\n\n&lt;Lotwil grabs the gyrochronatom from you.&gt;\n\nPerfect... just about done. No, really. I AM almost done now. This project is my top priority... at the moment. Let me pop this into place, and you can see for yourself what you've helped me create. It'll just take me a few more minutes... maybe... possibly longer. Well, maybe a lot longer. We'll see...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][715] = {title = "Liquid Stone", objective = "Bring a Healing Potion and a Lesser Invisibility Potion to Lucien Tosselwrench in the Badlands.", description = "I'm thinking those items you acquired for Lotwil are going to be the least of our worries, <name>. On the other hand, you've proven more than adept at the sciences Lotwil holds sacred, so how about helping me out?\n\nI need an invisibility potion and a healing potion; both might come in handy real soon if he pulls this off.\n\nIn return, I'll give you this recipe for a potion I've been developing while learning from Lotwil. It's based on some of the research he's been doing here in the Badlands.", progress = "He's getting closer to finishing. How are things going on your end?", completion = "YES!\n\nI mean, thank you, &lt;name&gt;. These will be helpful while traveling through the Badlands.", rewards = "You will receive:\n\nRecipe: Lesser Stoneshield PotionLesser Stoneshield Potion"}
MultiLanguageQuestData['en'][716] = {title = "Stone Is Better than Cloth", objective = "Bring some Patterned Bronze Bracers to Lucien Tosselwrench in the Badlands.", description = "I know how cheap Lotwil can be, <name>, so let me make you something for all your troubles. Maybe it'll even help protect you from the coming atrocity that is Lotwil's newest invention.\n\nI've been working with all the extra stones you collected for him, and I can make some nice bracers that you might want to use. They're enchanted, of course.\n\nI'll just need patterned bronze bracers crafted by a blacksmith so I can complete the bracers I'm making for you.", progress = "I wouldn't wait too long to get that bracer, <name>.\n\nWho knows what's going to happen next?", completion = "Here you go, &lt;name&gt;. Try these on.", rewards = "You will receive:\n\nEnchanted Stonecloth Bracers"}
MultiLanguageQuestData['en'][717] = {title = "Tremors of the Earth", objective = "Use the Sign of the Earth to activate the Pillars of Amethyst, Opal, and Diamond and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Garek.", description = "It has become obvious that we cannot ensure that Blacklash and Hematus will remain imprisoned in Lethlor. That black dragons have taken up residence there, and that the ogres managed to steal the Sign indicates that more drastic measures will have to be taken.\n\nThe drakes' prison is maintained by three runestones that may only be retrieved using the Sign of the Earth. Those runestones can then be used to break the seal which imprisons them.\n\n<name>... assure that their dreams are eternal.", progress = "Strong magics and powers held the drakes' prison for so long, but we cannot allow any possibility that Blacklash and Hematus may be released.", completion = "No longer will the Kirin Tor need to worry over the prisoners of Lethlor. I will return to report success to my master. Krasus will no doubt be pleased.", rewards = "You will be able to choose one of these rewards:\n\nBlazewind BreastplatePrismscale HauberkWarforged ChestplateMindburst Medallion\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][718] = {title = "Mirages", objective = "Retrieve the Supply Crate for Sigrun Ironhew.", description = "In our hurry to leave the Uldaman excavation site, we were forced to abandon many wagons and crates of supplies along the way. The local ogres from Camp Kosh have been on our abandoned equipment like vultures on a rotting corpse. Don't smell much better, either. Than the corpses, I mean.\n\nAnyways, they took the cart that was carrying all our weapons and such... so--well, this is a bit embarrassing--we haven't been able to get any food.\n\nWe're in a bit of a pickle here, suppose you could help us out?", progress = "The desert's a bad place to be hungry, my friend, let me tell you that.\n\nHey... what's that over there...", completion = "Thanks so much, &lt;name&gt;. While you were gone, I... er... swallowed a mouthful of sand. It...\n\nWell, enough of that, we'll go out and get some food tonight. Eat like kings!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][719] = {title = "A Dwarf and His Tools", objective = "Find Ryedol's Lucky Pick and return it to Prospector Ryedol south of Hammertoe's Dig Site.", description = "Hey, <name>. Be careful 'round here. There be Dark Iron dwarves all around--looked like the Shadowforge clan.\n\nThey just attacked the excavation site I was workin' at--killed nearly everyone there, including my boss Hammertoe. I barely escaped with me life.\n\nThe site's just to the north of here, and I'm tryin' to plan a way to get some of our supplies back, especially me lucky pick.\n\nThink you'd be up to helpin' me out some? One of those damned Dark Iron must have my pick! Could be anyone of them.", progress = "Not sure what the Shadowforge were lookin' for, but they definitely had a purpose.", completion = "Ye're me savior, &lt;class&gt;. I'm glad someone could teach those Shadowforge a lesson or two. Thanks for yer help.", rewards = "You will receive:\n\nRyedol's Hammer"}
MultiLanguageQuestData['en'][720] = {title = "A Sign of Hope", objective = "Find Prospector Ryedol and let him know Hammertoe Grez is alive.", description = "<There is text roughly scribbled in chalk on the map.>\n\n\"Ryedol, \nThey're taking me to Uldaman. Send help.\n-Hammertoe\"", progress = nil, completion = "Hammertoe's alive?! This is amazin', &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][721] = {title = "A Sign of Hope", objective = "Find Hammertoe Grez in Uldaman.", description = "<name>, can ye find him? Can you find Hammertoe in Uldaman?\n\nIf those dirty Shadowforge are holdin' him hostage to figure out what he knows about the titan excavations, then all of Ironforge could be in huge trouble.\n\nFor a long time now those Dark Irons have been lookin' for magics to make more powerful golems. Hammertoe was doin' the same, of course, but only to stop them.\n\nThey're probably keepin' him alive until they learn what he knows.Ye've got to hurry if you're gonna save him!", progress = nil, completion = "Yes? Ah'm sorry... &lt;cough&gt; Feel so weak. Can ye come closer, &lt;class&gt;?\n\nRyedol sent ye? Muradin be praised, that boy's not as slow in the head as I once thought.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][722] = {title = "Amulet of Secrets", objective = "Find Hammertoe's Amulet and return it to him in Uldaman.", description = "Ye're brave... <cough>... to come into Uldaman fer me, <class>.\n\nIf ye're really here to help... ol' Hammertoe, then... <cough>... you'll need to find... me amulet.\n\nDeepshadow's got it... Magregan Deepshadow. He's 'round here... in the ruins fer sure. That amulet'll lead 'em... <cough>...  right to the scrolls if he ain't stopped. It's up to you, <name>. Please... get that amulet.\n\nThe scrolls will surely help the Dark Irons create even more powerful golems. I just know it. I can feel it in me bones.", progress = "The Shadowforge clan... <cough> is dangerous. Be careful. <cough> You must find the amulet.", completion = "Ha! &lt;cough cough&gt;\n\nAh knew you'd find me amulet, &lt;name&gt;.\n\n Well done indeed, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][723] = {title = "Prospect of Faith", objective = "Take Hammertoe's Amulet to Prospector Ryedol in the Badlands.", description = "<Hammertoe holds his wounds and takes a moment to regain his composure before speaking again.>\n\nFind Ryedol, <name>. Bring 'im me amulet. <cough cough> He'll... <cough> figure out what to do. He knows I was seeking the origins of our people, and he... <cough>... knows it was also my mission to stop the Shadowforge clan. They must not be allowed to find the scrolls... <cough>", progress = "I'd say it was a bad day, but this is the Badlands: every day's a bad day.", completion = "Hammertoe's amulet? I think my spirits were higher when I thought he was dead. Knowin' fer sure only makes the pain worse. This amulet was his life's work. I can't let his death be in vain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][724] = {title = "Prospect of Faith", objective = "Take Hammertoe's Amulet to Historian Karnik in Ironforge.", description = "Okay, okay... who would know what to do?\n\nHistorian Karnik! That's it!\n\nHe's in Ironforge. He'll be able to help. He and Hammertoe were workin' together to find the lost artifacts in Uldaman.\n\nGuess the Shadowforge found out the two of them knew more than they were lettin' on.\n\nTell Karnik what's happened to Hammertoe and give him the amulet--he'll tell you what needs to be done next.", progress = "Ah, yes. Another traveler seeking something from the dwarves.\n\nSir, I'm truly sorry, but I've no time to answer meaningless questions right now.", completion = "Oh! Well, this is a different matter entirely. You probably don't realize the gravity of this matter yet, do you?\n\nI care deeply about Hammertoe's demise, but if he sent you here with his amulet, then he understood what's at stake.\n\nWe will have to take time to mourn his death later.\n\nLet me show you one of the reasons this amulet is so valuable.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][725] = {title = "Passing Word of a Threat", objective = "Find Advisor Belgrum and give him his note.", description = "<name>, run and find Advisor Belgrum as quickly as you can. Tell him what you've witnessed and ask him how he wants us to proceed. This note will explain more to him.\n\nIn the meantime, I will take the time to speak to Hammertoe's spirit. Maybe he knows something that will help us put a stop to those Shadowforge cretins' activities in the Badlands. We can only pray.", progress = "Hmm? Yes, <class>.", completion = "Ah, word from Historian Karnik. Excellent.\n\nI always have time for his business.\n\n&lt;Advisor Belgrum opens the note and begins to read.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][726] = {title = "Passing Word of a Threat", objective = "Speak to Historian Karnik.", description = "<Advisor Belgrum reaches the end of the note, and his eyes widen for a moment.>\n\nOch, these are evil tidings.\n\n<name>, please return to Historian Karnik and tell him on the king's authority to act on this information swiftly and decisively. He must halt the Shadowforge's activities in the Badlands.", progress = nil, completion = "You're treating this matter with an urgency I'd expect from the king himself, &lt;name&gt;.\n\nAll right, then. I know what'll bring the Shadowforge down.\n\nTheir presence in Uldaman can be slowed if we strike them at their base of operations: Angor Fortress.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][727] = {title = "To Ironforge for Yagyin's Digest", objective = "Give the Sigil of the Hammer to Gerrig Bonegrip in the Forlorn Cavern of Ironforge.", description = "The Tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The ... people I fled ... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Gerrig Bonegrip.  He is in a shop in Ironforge, in the Forlorn Cavern.  Show him this sigil and he'll think you one of them.  Ask him for Yagyin's Digest ... and bring it to me!", progress = "Hello.  Welcome to my shop, but watch what you touch.\n\nKnowledge can be deadly.", completion = "Oh.  Greetings, brother.\n\nAnd praise to the dwellers beneath.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][728] = {title = "To the Undercity for Yagyin's Digest", objective = "Bring the Sigil of the Hammer to Keeper Bel'dugur in the Undercity.", description = "The tablet tells much.  But not enough!  Not nearly enough!\n\nThere is a book, a digest that Yagyin wrote in ages past.  The... people I fled from... they keep this book in many places.  And their most learned study it.  It holds vast knowledge.  Knowledge to protect us!\n\nGo to Keeper Bel'dugur in the Undercity of Lordaeron.  Show him this sigil and he'll think you one of them.  Ask him for Yagin's Digest...and bring it to me!", progress = "Ah, we have an eager <class>, I see.  Are you here to learn from my collection?  Good!\n\nBut be warned: just as knowledge gives power to the strong...it will drive the weak mad.", completion = "Be discrete with your signs, &lt;class&gt;. There are those who do not believe the righteousness of our pledge.\n\nAnd there are those who would see us fail if they knew of us.\n\nWe must always be careful.  And watchful.  And patient.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][729] = {title = "The Absent Minded Prospector", objective = "Travel south and check on Prospector Remtravel.", description = "What an honor it was when Master Greywhisker assigned me to work under the guidance of the great Prospector Remtravel. At the academy in Ironforge everyone knew of Remtravel's great discoveries.\n\nBut the prospector is rather... um... oblivious ...to his surroundings.\n\nWe had uncovered evidence of a great society. Horrible golems sprang forth from the ground and overran the site. Remtravel never seemed to notice. I ran back to Auberdine for help.\n\nPlease travel south and see if the prospector is okay!", progress = nil, completion = "Hollee, is that you? I need some help chiseling this stone. Hand me my stone brush, I think I see something.\n\nHey, you're not Hollee! Don't suppose you've seen my stone brush?\n\nNever mind that now! I promised the League I'd send the mysterious fossil I found. Where did Hollee go?\n\nSo much work to be done! Now where is that mysterious fossil... and my brush... and Hollee...\n\nAnd who are you... 'tis no matter, so long as you're here to help.\n\nLet me know when you're ready to start looking.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][730] = {title = "Trouble In Darkshore?", objective = "Travel to Auberdine and look for signs of the dwarven excavation team.", description = "How nice it is to see a <class> interested in the great archeological wonders of our world.\n\nOftentimes our work is dismissed as mere hobby by our friends in the Alliance. But what many fail to realize is that recent discoveries in Khaz Modan have proven that a great and powerful force threatens all of Azeroth, from Lordaeron to Kalimdor.\n\nI am most worried about my crew that I sent to Darkshore. They haven't sent word in weeks.\n\nTravel to Auberdine and look for a clue as to their whereabouts.", progress = nil, completion = "I'm so glad Chief Archeologist Greywhisker sent for us....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][731] = {title = "The Absent Minded Prospector", objective = "Protect Prospector Remtravel as he searches for the mysterious fossil, then return to Archaeologist Hollee in Auberdine.", description = "So then, Hollee... oh that's right, you are not Hollee. Where's Hollee?\n\nBah, that's beside the point. We must find that stone brush... I mean the mysterious fossil! We must find that fossil. The Explorers' League in Darnassus will want some indication as to what I've been doing.\n\nLet me know when you are ready and we will hunt down that brush.... I mean fossil! We shall find something in writing to satisfy the League.\n\nSo are you ready yet?", progress = nil, completion = "Thank the stars Prospector Remtravel is safe! I told you he was absent minded. I can't believe he insisted on staying there with all of those horrible creatures lurking about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][732] = {title = "Tremors of the Earth", objective = "Retrieve the Sign of the Earth for Garek.", description = "I heard from Sigrun that you have been a great help to him. Perhaps I might enlist your help. I was sent here by my master, Krasus of the Kirin Tor, to put an end to the trouble brewing in Lethlor Ravine.\n\nI cannot divulge the exact nature of my assignment here or the tasks that I must undertake, but be assured it is of vital importance.\n\nA band of wandering ogres, sometimes seen near Camp Boff, stole an object called the Sign of the Earth; I must have it. Bring it to me, and I will tell you more.", progress = "The nomadic band of ogres travels between their camps across the Badlands; heat rising from the dry earth and the swirling winds will make it difficult to track their progress.  I have heard that sometimes they travel through Camp Boff.  If you are lost, you might try your search there.", completion = "Good tidings you bring bearing the Sign, &lt;name&gt;. The Sign of the Earth was created by the Dark Iron dwarves of Angor Fortress to bind two of Deathwing's ruthless lieutenants, the twins Blacklash and Hematus.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][733] = {title = "Scrounging", objective = "Get 7 pieces of Scrap Metal for Sigrun.", description = "It's going to be tough going here if I can't manage to scrounge up some materials to construct some defenses and other necessities. I've noticed that the ogres in the area seem to be well equipped with scrap metal. Maybe the stories of siege engines in the Badlands weren't so far off after all...\n\nAnyways, the Prospector's been getting worried about the state of our little camp, so I'd like to get working soon if I can.\n\nThe main ogre camp is at Dustbelch Grotto, a good trek to the west of here.", progress = "Well, I've made do with what I could, but... it's not much. Have you found any more supplies?", completion = "It's a start, &lt;name&gt;, and it'll have to do until we hear word from Ironforge or the Explorers' League.\n\nNow, if only I could find some salt somewhere for my quenching barrel...", rewards = "You will be able to choose one of these rewards:\n\nSalbac ShieldIronheel Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][734] = {title = "This Is Going to Be Hard", objective = "Speak to Lucien Tosselwrench in the Badlands.", description = "Wonderful, wonderful.\n\n<Lotwil looks up at you for a moment before going back to his shackles.>\n\nGo speak to Lucien, <name>. I need a cog #5. Bring it to me, will you?", progress = nil, completion = "Cog #5, huh? Yeah, this isn't going to be good.", rewards = nil}
MultiLanguageQuestData['en'][735] = {title = "The Star, the Hand and the Heart", objective = "Return the items on the Bonegrip's Note to Gerrig Bonegrip in Ironforge.", description = "Yagyin's Digest, eh?  Are you starting a new chapter of us, somewhere?  Never mind, it is not my place to ask.\n\nI will help you, for I have an extra copy.  We must aid each other, yes?  That is how we flourish.\n\nI require three items of power.  Bring them to me and I will give you the digest.\n\nI will not speak their names.  Ears may be on us.  But here, I will write them down.", progress = "Do you have the relics for which I asked?", completion = "You are resourceful, &lt;class&gt;.  If it truly is your charge to begin a new chapter of our order, then I believe you will run it well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][736] = {title = "The Star, the Hand and the Heart", objective = "Bring the items on Bel'dugur's Note to Keeper Bel'dugur in the Undercity.", description = "You need Yagyin's Digest?  Your plan, then, is to gather another flock?  Of course it is...and of course I will help you, <brother/sister>.\n\nBut you must help me too.\n\nI require three items of power.  Bring me these and the digest will be yours.\n\nI cannot utter the names of these items, but I will write them down.\n\nGet me the items on this list.  If you can do that, then you are truly worthy of opening your own chapter of our order.", progress = "How goes your mission, <class>.", completion = "I am impressed!  You possess great skill, or great fortune, to have gained these relics.  Either way, you are an asset to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][737] = {title = "Forbidden Knowledge", objective = "Bring Yagyin's Digest to Theldurin.", description = "I have the digest for you, <name>.  I need not tell you to take great care with it.  And to keep it far from unfriendly hands.  \n\nThis book holds many truths...\n\n...And the truth can burn.", progress = "Ho!  You were gone a long time.  Did you get the digest?", completion = "You got it!  Oh, hope glimmers!\n\nYour efforts may yet save us, &lt;name&gt;.  A monument they should make of you!  A shrine they should build!  May your name be praised until your grandchildren have grandchildren!\n\nUnless...THEY are freed and rise to the surface.   If that happens then you can forget about children.\n\nIf THEY are freed, then we're all worm food.", rewards = "You will receive:\n\nSkull of Impending Doom"}
MultiLanguageQuestData['en'][738] = {title = "Find Agmond", objective = "Find Agmond.", description = "Prospector Agmond was in charge of our excavation sites in the Badlands, to the southwest.  I say \"was\" because...well, I haven't heard from him in weeks.  I need you to find Agmond so I can get his report.\n\nLast I heard Agmond was at the southernmost dig site in the Badlands--a tiny operation past the Angor Fortress.  I'd start your search for him there.", progress = nil, completion = "This skeleton must be the unfortunate remains of Agmond.  His body is broken and battered, and his bones picked clean.", rewards = "You will receive:\n\nRipped Prospector BeltJadeGold Ore"}
MultiLanguageQuestData['en'][739] = {title = "Murdaloc", objective = "Slay Agmond's killer, Murdaloc.\n\nSlay 12 Stonevault Bonesnappers.\n\nReport to Prospector Ironband in Loch Modan.", description = "Agmond's tracks lead from the west.  It is easy to tell from the bloody smears across rock and sand that the dwarf crawled some distance.\n\nAnd here he died.\n\nUpon close inspection, the word \"Murdaloc\" is roughly scrawled in a patch of Badlands sandstone.\n\nScrawled next to Agmond's dead hand.", progress = nil, completion = "This is sobering news, &lt;name&gt;.  But Agmond had a strong arm and a fierce hammer-swing, and his skull was as thick as they come!  Although he was killed by those cursed troggs I'm sure he took a lot of them down with him.", rewards = "You will receive:\n\nRock Pulverizer"}
MultiLanguageQuestData['en'][741] = {title = "The Absent Minded Prospector", objective = "Take the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", description = "So the prospector wants to send the mysterious fossil to the Explorers' League in Darnassus? I don't feel right leaving Darkshore without him.\n\nHere, <name>, deliver the mysterious fossil to Chief Archaeologist Greywhisker in Darnassus.", progress = "What can I do for you, <race>?", completion = "Oh my! Leave it to Prospector Remtravel to discover such a find!", rewards = "You will be able to choose one of these rewards:\n\nHammerfist GlovesWindfelt GlovesRelic Hunter Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][742] = {title = "The Ashenvale Hunt", objective = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", description = "Attention, young adventurers!  The wilds of Ashenvale await you!\n\nThe Horde has established a strong presence in the lands north of the Barrens.  Our two outposts - Splintertree Post and the Zoram Strand Outpost - strive to bring glory to the Horde!  Those who would prove themselves should seek out guidance there.  Of note: Senani Thunderheart in Splintertree Post, directly north of the Barrens, seeks adventurers willing to take part in a great hunt of Ashenvale!", progress = nil, completion = "Welcome to the new frontier, &lt;name&gt;.  Ashenvale is a land of opportunity, one where a young &lt;class&gt; like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][743] = {title = "Dangers of the Windfury", objective = "Bring 8 Windfury Talons to Ruul Eagletalon in Bloodhoof Village.", description = "Thank you for taking the time to speak to me, <name>. I am Ruul, warrior and teacher.\n\nYou have obviously reached an age when you must prepare for your trials if you are to adventure much further out of Mulgore.\n\nIf you wish a test of your strength, start by seeking out the Windfury harpies to the southeast. They nestle along the mountain's edges away from the road.\n\nThey are one of our natural enemies here in Mulgore and will be a good gauge of your skill.", progress = "The Windfuries are deadly foes. Their strength in battle is only rivaled by their desire for fresh meat.", completion = "You have done well, &lt;name&gt;. You seem well prepared to travel onward. Let the wind always be at your back.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][744] = {title = "Preparation for Ceremony", objective = "Collect 6 Azure Feathers and 6 Bronze Feathers, and bring them to Eyahn Eagletalon in Thunder Bluff.", description = "<name>, my brother soon stands before Chief Bloodhoof, and it is my honor to make his headdress for him.\n\nI want to ask a favor of you while I finish tanning these leather straps. There is not time for me to find enough feathers, and I was wondering, would you gather more for me?\n\nYou can find feathers of the correct size from the harpies residing far to the north and northwest of Thunder Bluff. I need only 6 azure and 6 bronze feathers to complete the design.", progress = "This headdress will certainly be a wonderful gift for my brother.", completion = "Thank you for your help, &lt;name&gt;.\n\nMy part in my brother's ceremony is almost complete. Giving him his headdress and witnessing the ceremony are all my duty requires of me.", rewards = "You will be able to choose one of these rewards:\n\nBound HarnessTribal Warrior's Shield\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][745] = {title = "Sharing the Land", objective = "Kill 10 Palemane Tanners, 8 Palemane Skinners, and 5 Palemane Poachers, then return to Baine Bloodhoof in Bloodhoof Village.", description = "<name>, there are many conflicts that wound this land. It is my hope that you will not bear witness to as many of them as I have. Yet there is one that I would ask you to seek out. It will give you some sense of how terrible, if left unchecked, even a small threat can be to the land.\n\nPalemane gnolls have settled to the south of Bloodhoof and in a cave to the west. They disrespect our attempts to communicate with them, and they slay the wildlife of Mulgore unbridled.\n\nWords are no longer the answer.", progress = nil, completion = "&lt;name&gt;, it is good you've taken my task seriously. Respect of the land and its creatures is important. Death and life are a circle... a necessity. One cannot exist without the other. Take time to ponder this and do well to never forget it.", rewards = "You will receive:\n\nFlash Pellet"}
MultiLanguageQuestData['en'][746] = {title = "Dwarven Digging", objective = "Collect 5 Prospector's Picks.\n\nAt a forge, smash the Prospector's Picks to create Broken Tools.\n\nBring 5 Broken Tools to Baine Bloodhoof in Bloodhoof Village.", description = "There are dwarves preparing a dig site to the northwest.  They think secrets lie in the earth, and that is true, but hollowing and defiling the land is no way to earn its teachings.\n\nCollect the dwarven tools of digging, smash them, and return to me with the dwarves' broken tools.\n\nYou can smash the tools at a forge.  You will find one in Thunder Bluff, but any forge -- even a forge at the dwarven camp -- will suffice.", progress = "Hello, <name>.  Do you have the Broken Tools?  The dwarves' digging will enrage the kodos of Mulgore.  This defilement must be stopped!", completion = "Thank you, &lt;name&gt;.  This will calm the beasts of Mulgore.  And, spirits willing, it will teach the dwarves that hollowing the land is not the path to knowledge.", rewards = "You will be able to choose one of these rewards:\n\nFortified BindingsRough-hewn Kodo Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][747] = {title = "The Hunt Begins", objective = "Grull Hawkwind in Camp Narache wants you to bring him 7 Plainstrider Feathers and 7 pieces of Plainstrider Meat.", description = "You have a promising air about you, and will prove yourself to the tribe. Perhaps someday soon you will be welcomed into the great city of Thunder Bluff. But before that can happen you must prove yourself to my father, Chief Hawkwind.\n\nUp here on Red Cloud Mesa we pride ourselves on keen hunting skills. Tauren hunt out of necessity and for sport. Our supply of meats has run low and we require feathers for clothing. Hunt the nearby plainstriders and prove yourself by resupplying the village.", progress = "Providing meat and feathers for the tribe is the first step in proving yourself as a hunter before the Chief.", completion = "The &lt;race&gt; of Narache thank you, &lt;name&gt;. You show much promise.", rewards = "You will be able to choose one of these rewards:\n\nNomadic BeltPainted Chain Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][748] = {title = "Poison Water", objective = "Bring 6 Prairie Wolf Paws and 4 Plainstrider Talons to Mull Thunderhorn in Bloodhoof.", description = "Goblins and their servants have tainted our sacred water wells!  We cannot allow this.\n\nTo cleanse each well, I must create a cleansing totem, then you must bring the totem to the well and perform a cleansing ritual.\n\nFirst we will create a cleansing totem for the Winterhoof Water Well.  To do this, the land must offer its aid. Hunt prairie wolves for their paws and adult plainstriders for their talons.  They are to the southwest.\n\nReturn to me with the paws and talons, <name>.", progress = "Do you have the paws and talons, <name>?", completion = "You have done well, &lt;name&gt;.  I will take these and bind their power into a totem of cleansing.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][749] = {title = "The Ravaged Caravan", objective = "Morin Cloudstalker wants you to examine the contents of a supply crate at the Ravaged Caravan.", description = "A few days ago, we found a Venture Co. caravan traveling under guard on the northern shore of Stonebull Lake. We'd lost two of our number in an earlier battle, so we were quick to attack and lay waste to the caravan.\n\nWe left their supply crates, thinking that our torches would destroy anything of value, but given that Venture Co. salvagers have been spotted near the burned wagons, maybe we were wrong.\n\nPerhaps you could go to the caravan and examine the contents of the crates.", progress = nil, completion = "All sides of the crate are stamped with the sign of the Venture Co. Mining Division. Notes printed carefully on the side of the carton indicate that the contents are due for processing at one of their central plants.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][750] = {title = "The Hunt Continues", objective = "Grull Hawkwind in Camp Narache wants you to bring him 10 Mountain Cougar Pelts.", description = "A tauren skilled in the ways of the hunt knows that his prey is not for mere trophy. The beasts of the plains provide us with a means of survival. You will make quite an impression on the elders if you can bring back some highly valued Mountain Cougar Pelts. You can find the beasts lurking in the hills to the south.\n\nOur children need clothing and our tents need mending.", progress = "If you can provide pelts for the tribe I will pass word along to my father, Chief Hawkwind, of your generous deeds.", completion = "The &lt;race&gt; of Narache thank you for these provisions, &lt;name&gt;. With your skill in the ways of the hunt you will surely be revered in Thunder Bluff someday.", rewards = "You will be able to choose one of these rewards:\n\nNomadic BracersPainted Chain Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][751] = {title = "The Ravaged Caravan", objective = "Return the Venture Co. Documents to Morin Cloudstalker near Bloodhoof Village.", description = "Prying open the lid reveals a tightly packed assortment of ore and minerals, more evidence of the Venture Co.'s mining operation in Mulgore. On the top of the ore and minerals you remove a tightly bound sheaf of papers.\n\nUp in the foothills to the east, you can barely hear the sounds of work, and see smoke rising from a large fire.", progress = "Hail, <name>. Have you learned anything new about the Venture Co.'s plans and operations in our homeland?\n\nIf they plan to exploit our lands as they have others, the Outrunners will be quick to put an end to it.", completion = "It does indeed appear that the Venture Co. is attempting to rob us of our natural resources. It is good to know this for true, and now it seems, we must do something about it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][752] = {title = "A Humble Task", objective = "Chief Hawkwind wants you to search for his mother near the water well to the southeast of Camp Narache.", description = "All members of the tribe share in the harmony of life. We live together and work together.\n\nOur commitment to one another carries with it a high degree of responsibility. I ask of you now a humble task.\n\nMy mother set out this morning to fetch water from the well to the southeast of Narache. It has been quite some time now. Perhaps you could check on her for me while I attend to tribal matters here?", progress = nil, completion = "You traveled all this way just to help an old woman? My my, aren't you a keeper?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][753] = {title = "A Humble Task", objective = "Take a Water Pitcher from the water well.\n\nReturn the pitcher to Chief Hawkwind in Camp Narache which is northwest from the water well.", description = "I have traveled many paths through life and these old legs lack the vigor they once had. I can still perform my duties to the tribe. Sometimes it just takes an old woman a little longer to do the task.\n\nBut you look like an eager <class>. Let's put some of that youthful vitality to the test. Take a water pitcher from the well and bring it to my son, the Chief, in Camp Narache.\n\nRemember that even the most humble task can gain the recognition of elders.", progress = "You look as though you have returned from the plains. Do you have any word from Greatmother Hawkwind?", completion = "You carried this pitcher back at the Greatmother's bidding, I see.\n\nYour willingness to help others and provide for the &lt;race&gt; of Camp Narache leads me to believe you would make the tribe proud in Thunder Bluff someday.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][754] = {title = "Winterhoof Cleansing", objective = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well, then return to Mull Thunderhorn.", description = "I have crafted the totem to cleanse the Winterhoof Water Well.  Now, you must take it to the well and perform a cleansing ritual.  You will find it to the southeast, guarded by foul goblins!\n\nThis will not be an easy task, but you must do it if we are ever to use its waters again.\n\nFortune to you, <name>.", progress = "Do not delay, <name>.  The Winterhoof Well's taint must be removed!", completion = "News of your deed reached me moments ago -- already the beasts near the well drink from it eagerly.\n\nYou have done a great thing for the land, &lt;name&gt;.  And you have done a great thing for the &lt;race&gt; people.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][755] = {title = "Rites of the Earthmother", objective = "Travel to Seer Graytongue who lives in the hills directly south of Camp Narache.", description = "Your willingness to perform a humble task for the tauren of Narache and your eagerness to learn are noble traits, <name>. I believe one day you will be heralded in Thunder Bluff as a <class> of greatness.\n\nBefore that you must embark on the Rites of the Earthmother, of which there are three.\n\nThe first test is the Rite of Strength. Travel to Seer Graytongue and tell him Chief Hawkwind has sent you.\n\nYou will find the seer's abode directly to the south of Camp Narache, tucked away in the hills.", progress = nil, completion = "Chief Hawkwind sent you? Embarking on the Rites of the Earthmother is no small task...", rewards = "The following spell will be cast on you:\n\nMark of the Wild\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][756] = {title = "Thunderhorn Totem", objective = "Bring 6 Stalker Claws and 6 Cougar Claws to Mull Thunderhorn.", description = "To create the Thunderhorn Cleansing Totem, you must gather the claws of the predators of the Mulgore plains.  Hunt prairie stalkers for their stalker claws and flatland cougars for their cougar claws, then return to me.\n\nYou will find the prairie stalkers and flatland cougars to the east and west.", progress = "<name>, do you have the claws I sent you to gather?  The Thunderhorn Water Well grows more tainted with each passing hour!", completion = "Thank you, &lt;name&gt;.  The purity with which these beasts hunt is vital in the creation of the next cleansing totem.\n\nThe goblins will never learn the difference between contending with the land, and living in harmony with it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][757] = {title = "Rite of Strength", objective = "Kill Bristlebacks in Brambleblade Ravine and bring 12 Bristleback Belts to Chief Hawkwind in Camp Narache.", description = "The Rites of the Earthmother are the steps a young tauren needs to take to gain respect in Thunder Bluff.\n\nFirst you must pass the Rite of Strength. In this test you must prove your bravery by slaying enemies of the tribe.\n\nBristlebacks of Brambleblade Ravine to the east are encroaching on our tribal lands. They ambush our hunting parties and steal from the village by dark.\n\nShow your valor by slaying these villains and return to the Chief in Camp Narache with their belts as proof of your deeds.", progress = "Have you completed the Rite of Strength, <name>? I require proof of your valor against the enemy of our tribe, the Bristlebacks.", completion = "You have passed the first test of the Rites of the Earthmother. The tribe will be proud.", rewards = "You will be able to choose one of these rewards:\n\nRock MaceStone TomahawkWhittling KnifeElder's CaneBrave's Axe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][758] = {title = "Thunderhorn Cleansing", objective = "Use the Thunderhorn Cleansing Totem at the Thunderhorn Water Well, then return to Mull.", description = "The totem is ready, <name>.  And again, it is your task to perform the ritual of cleansing.\n\nGo to the Thunderhorn Water Well, north of the village, and use the Thunderhorn Cleansing Totem in your ritual.  After you do this, return to me.\n\nMay the spirits guide you.", progress = "The Thunderhorn Water Well is still tainted, <name>.  Please, you must perform the ritual!", completion = "Ancestors of the Thunderhorn clan spoke to me in a dream, praising you for your actions near their well.\n\nFor their gratitude, they wish to give you this...", rewards = "You will receive:\n\nThunderhorn Cloak"}
MultiLanguageQuestData['en'][759] = {title = "Wildmane Totem", objective = "Bring 8 Prairie Alpha Teeth to Mull Thunderhorn in Bloodhoof Village.", description = "There is but one water well left to cleanse, named after the Wildmane clan.  For this well to be pure, the land must offer the teeth of a fierce predator, the prairie wolf alpha.  Find the alphas to the north, then return to me when your hunt is finished.\n\nAlphas often wander around the base of our mighty city, Thunder Bluff.", progress = "<name>.  Do you have the teeth I asked for?", completion = "Very good, &lt;name&gt;.  I can feel the sacrifice of the land in this offering, and my spirit swells with sadness, and pride.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][760] = {title = "Wildmane Cleansing", objective = "Use the Wildmane Cleansing Totem at the Wildmane Water Well, then return to Mull Thunderhorn.", description = "Your cleansing of the Winterhoof and Thunderhorn wells is spoken among the spirits, young <name>.  The Wildmane Totem is made, and your last task lies ahead.\n\nThe Wildmane Water Well lies north of Thunder Bluff.  Perform the ritual!  Heal the land of the goblins' poisons!  Let clean water flow once again!", progress = "The last water well remains fetid and poisonous, <name>.  You must not delay!", completion = "You've done it.  You have cleaned the wells, and healed our land.  Bloodhoof village is grateful, &lt;name&gt;.\n\nMay the wind whisper your deeds for a hundred seasons, and may the waters of Mulgore remain clean forever.", rewards = "You will be able to choose one of these rewards:\n\nCeremonial TomahawkDreamwatcher Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][761] = {title = "Swoop Hunting", objective = "Bring 8 Trophy Swoop Quills to Harken Windtotem in Bloodhoof Village.", description = "The swoop is a cunning bird, and difficult to find and hunt.  A collection of Swoop Quills is a badge of cleverness and determination for a hunter.\n\nIf you are willing to take up this task, then enter the plains and hunt the swoop.\n\nBring me their quills, and bring honor to your clan.\n\nThe swoops may be found anywhere in Mulgore, but your eyes must be sharp to spot them, and your hooves must be quick to catch them.", progress = "Have you found the swoops, <name>.  Do you have their quills?", completion = "I know that gathering these quills was not an easy task, &lt;name&gt;.  In doing this, you prove that you are a &lt;class&gt; of merit.  It is good to have you at Bloodhoof Village.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][762] = {title = "An Ambassador of Evil", objective = "Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge.", description = "Ambassador Infernus was sent to Angor Fortress by Ragnaros himself to mind the Shadowforge seeking lost artifacts in Uldaman.\n\nIt has already meant tremendous casualties for our people, but it has obviously grown worse. I hesitate to guess how many artifacts they would be able to find and use against Ironforge.\n\nOur goal is simple, <class>. Return to the Badlands and destroy Ambassador Infernus. Once the threat is eliminated, return to Advisor Belgrum with proof of your victory.\n\nIt is in your hands now.", progress = "Time is of the essence, <name>. Ragnaros will not wait for us to prepare.", completion = "&lt;name&gt;, your dedication to Ironforge and to the dwarven people cannot be refuted. I thank you for your help in this matter.\n\nI shall send word to Historian Karnik informing him that you have succeeded, and I shall also have aid sent to the Badlands as soon as possible to help recover the excavation site. Thank you again.\n\nBefore you go, there is one more thing I would ask of you in the name of King Bronzebeard.", rewards = "You will receive:\n\nDwarf Captain's Sword"}
MultiLanguageQuestData['en'][763] = {title = "Rites of the Earthmother", objective = "Take the Totem of Hawkwind to Baine Bloodhoof in Bloodhoof Village. Follow the road out of Camp Narache.", description = "For you to continue with the Rites of the Earthmother you must pass two more tests. It is time for you to broaden your experience, <name>.\n\nTravel to Bloodhoof Village and seek out the Chief, Baine Bloodhoof, son of Cairne. There you may continue your journey and earn the acceptance of the elders of Thunder Bluff.\n\nTake this totem to Baine. He will recognize my carvings and help you on your path.\n\nFollow the road out of Camp Narache and travel with haste. Do not stray or you will lose your way.", progress = "What brings you to my village, <class>?", completion = "Word from my good friend, Chief Hawkwind! Ah, I can see by his carvings you are of a special breed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][764] = {title = "The Venture Co.", objective = "Kill 14 Venture Co. Workers and 6 Venture Co. Supervisors for Morin Cloudstalker at Bloodhoof Village.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", progress = "The Venture Co. was refused mining rights here in Mulgore, but it would seem that they do not take no for an answer. We <race> are not ones to mince words, however, and we have other ways of getting our message across.", completion = "I don't think there could be too much misinterpreting or ignoring of that signal, hm? The Venture Co. will know not to take the &lt;race&gt; lightly, or to be so arrogant as to believe we would allow them to steal the natural resources around us without protest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][765] = {title = "Supervisor Fizsprocket", objective = "Kill Supervisor Fizsprocket and return his clipboard to Morin Cloudstalker at Bloodhoof Village.", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", progress = "I seethe with anger at the thought of the atrocities the Venture Co. is willing to perpetrate against us in the name of profit.", completion = "My anger is somewhat lessened at the news that the villain Fizsprocket is dead. I will go through his personal effects and see if there is any additional information about what the Venture Co. has planned for the future. Thank you for your efforts, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nCompact Fighting KnifeGoblin Smasher\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][766] = {title = "Mazzranache", objective = "Bring a Prairie Wolf Heart, Flatland Cougar Femur, Plainstrider Scale and Swoop Gizzard to Maur Raincaller at Bloodhoof Village.", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I will need some hard-to-find animal parts to clean the infection from his bite: a wolf heart, cougar femur, plainstrider scale and swoop gizzard.\n\nHurry, time is of the essence.", progress = "My fever grows worse and I find my mind drifting into delirious nightmares... I should have known that I wouldn't be able to handle a beast my grandfather was unable to defeat...\n\nDo you have the ingredients for the remedy? I fear if I do not clean the infection soon, it will be the death of me.", completion = "Ah, thank you, &lt;name&gt;. Using the items you brought me, I will be able to create the remedy I need to stop the spread of the infection and, eventually, cure it completely. I owe you my life in thanks.\n\nBut I'll never forget that screeching call when Mazzranache came upon me, the blaze of color as its beak descended...\n\nBe wary on your travels.", rewards = "You will be able to choose one of these rewards:\n\nCliff Runner BootsPlains Hunter Wristguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][767] = {title = "Rite of Vision", objective = "Speak with Zarlman Two-Moons in Bloodhoof Village.", description = "The Rite of Vision, one of the Rites of the Earthmother, will help guide you toward earning the respect of the elders of Thunder Bluff.\n\nOur people have learned that the land is our most holy provider. In order to take part in the ritualistic vision, you must speak with the spiritual leader of the village, Zarlman Two-Moons.", progress = nil, completion = "I sensed you would be coming to me, &lt;class&gt;. I can always recognize one who is trying to pass the Rites of the Earthmother.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][768] = {title = "Gathering Leather", objective = "Bring 12 pieces of Light Leather to Veren Tallstrider in Thunder Bluff.", description = "Greetings, young one.  You have a gleam in your eye; I can tell you are eager to venture back to the plains for the hunt.  May you bring honor to your clan!\n\nI work with the skins of beasts, fashioning them into clothes and armor for the people of Thunder Bluff.\n\nIf you hunt beasts and bring me their skins, then I will fashion something for you.", progress = "Hello again.  Have you been hunting?  Do you have skins for me?", completion = "Ah, these are very nice pieces.  They'll make fine leather goods.\n\nHere, &lt;name&gt;.  Take this in trade...", rewards = "You will be able to choose one of these rewards:\n\nAnimal Skin BeltDouble-layered Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][769] = {title = "Kodo Hide Bag", objective = "Bring 4 Light Leather and 4 Coarse Thread to Veren Tallstrider in Thunder Bluff.", description = "The kodo beasts of Mulgore are strong and sturdy -- traits much respected among us.  If you are skilled in leatherworking and wish the knowledge to make a Kodo Hide Bag, then bring me supplies for my trade.\n\nDo this, and I will share my knowledge with you.", progress = "Do you have my supplies, <name>?", completion = "Ah, good.  Thank you, &lt;name&gt;.  My heart swells with pride to see youths interested in the craft of leatherworking.", rewards = "You will receive:\n\nPattern: Kodo Hide Bag"}
MultiLanguageQuestData['en'][770] = {title = "The Demon Scarred Cloak", objective = "Find someone who knows of Ghost Howl.\n\nProvided item: \n", description = "The ragged hide of Ghost Howl still bears a terrible wound, gained from the wolf's battles against the Burning Legion.\n\nPerhaps someone in Bloodhoof Village should know of Ghost Howl's demise....", progress = nil, completion = "I can barely believe my old eyes!  You defeated the great wolf Ghost Howl?  I look upon you with new respect, young &lt;class&gt;.  You are a hunter of extreme skills!\n\nLet me offer you something.  My days of hunting are over, but I would be honored if you used one of my weapons in your hunts.\n\nMay it strike true, and bring you renown.\n\nAnd let us hope that Ghost Howl's spirit has finally found peace.", rewards = "You will be able to choose one of these rewards:\n\nSkorn's HammerSkorn's Rifle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][771] = {title = "Rite of Vision", objective = "Collect 2 Well Stones and 2 Ambercorn and bring them back to Zarlman Two-Moons in Bloodhoof Village.", description = "In order to pass through the Rite of Vision, you must gather the reagents needed to make the Water of the Seers.\n\nI will need well stones, which can be found around the water wells in Mulgore. With those I will combine Ambercorn, which fall beneath the mighty trees in our land.\n\nThese reagents contain magical elements, and when brewed and consumed before the tribal fire, will cause you to encounter a vision. Follow it, and it will lead you to the next step of this holy quest.", progress = "Once you have gathered enough well stones from around the water wells and Ambercorn from beneath the trees, I will prepare the Water of the Seers for you.", completion = "I see you have learned to gather from our sacred land, &lt;name&gt;. It will take but a moment for me to brew the Water of the Seers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][772] = {title = "Rite of Vision", objective = "Consume the Water of the Seers in front of the tribal fire in Bloodhoof Village and follow the vision once it appears.\n\nProvided item: \n", description = "I now present you with the Water of the Seers.\n\nWhen you are ready, consume the waters near the tribal fire. Once you have ingested the holy waters, it will take a few moments before the vision materializes before the fire.\n\nAt that point, it is up to you to follow it to your destiny....", progress = nil, completion = "Be not afraid, &lt;name&gt;. You have successfully passed the Rite of Vision.", rewards = "You will be able to choose one of these rewards:\n\nRainwalker BootsSun-beaten Cloak\n\nThe following spell will be cast on you:\n\nMark of the Wild\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][773] = {title = "Rite of Wisdom", objective = "Travel to Red Rocks east of Thunder Bluff and speak with the Ancestral Spirit.", description = "To gain acceptance amongst the elders of Thunder Bluff you must next complete the Rite of Wisdom.\n\nNow that you have passed the Rite of Vision, the ancestral spirits of Red Rocks will give you the blessing of our ancestors. Only those who have drunk from the Water of Seers can gain the blessing.\n\nTravel east of Thunder Bluff, to Red Rocks and seek out the Ancestral Spirit, <name>.", progress = nil, completion = "You have shown great diligence in your yearning to pass the Rites of the Earthmother, &lt;name&gt;.\n\nWe, the Ancestral Spirits, represent the mighty &lt;race&gt; who gave their lives bravely to found and protect our great city of Thunder Bluff. I hereby pass the duty of that protection over to you.\n\nYou have passed the Rite of Wisdom, young &lt;class&gt;. Enter Thunder Bluff with pride.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][775] = {title = "Journey into Thunder Bluff", objective = "Speak with Cairne Bloodhoof in Thunder Bluff.", description = "You will now be revered within our great city. Any <race> worthy of completing the Rites of the Earthmother earns that honor.\n\nFor your final quest, seek out our noble leader, Cairne Bloodhoof, who dwells atop the highest mesa in Thunder Bluff.", progress = nil, completion = "Hail, young &lt;class&gt;. I see you found your way to my doorstep.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][776] = {title = "Rites of the Earthmother", objective = "Cairne Bloodhoof in Thunder Bluff wants you to bring him the Horn of Arra'chea.", description = "You have passed the Rites of the Earthmother and earned your place in Thunder Bluff.\n\nBut in order to maintain the spot that you strived so hard to achieve, you must continue to prove your worth to your people.\n\nWe are hunters, <name>. Down below in Mulgore there is a mighty kodo named Arra'chea. Show me your skills in the ways of tracking and hunting by bringing me the Horn of Arra'chea.", progress = "Have you tracked down Arra'chea yet?", completion = "Well done! A fine kill that was.\n\nI will send a gathering party to collect the carcass so we can retrieve the hide and meat.\n\nYou have done a great deed for your people, &lt;name&gt;.", rewards = "You will receive:\n\nKodo Hunter's Leggings"}
MultiLanguageQuestData['en'][777] = {title = "This Is Going to Be Hard", objective = "Bring Cog #5 to Lotwil Veriatus.", description = "Okay, here you go.\n\nI'm going to be over here... behind cover.\n\nFeel free to join me.", progress = "<Without looking up from the shackles, Lotwil holds out a hand and waggles his fingers impatiently.>\n\nThe cog, <name>, the cog!", completion = "Ah, perfect. Stand back while I prepare to make more history!\n\n&lt;Lotwil continues to work feverishly.&gt;", rewards = nil}
MultiLanguageQuestData['en'][778] = {title = "This Is Going to Be Hard", objective = "Defeat the Fam'retor Guardian and bring Lotwil's Shackles of Elemental Binding back to Lotwil Veriatus.", description = "Haha! Done! The shackles are done!\n\nIt's time, Lucien. It's time, Servo!\n\nAre you ready to bear witness to the perfect blend of alchemy, engineering, and the arcane, <name>?\n\nI shall summon forth a powerful elemental now. This is a groundbreaking day for all of us.", progress = "Not quite the outcome I was expecting. Could you get my shackles back?", completion = "Thank you, &lt;name&gt;. That was quite an ordeal, wasn't it?\n\nI'm not sure what could have gone wrong. It was a good thing my magics were here to help send the creature back to its home plane.\n\nPerhaps a little token of appreciation for all your hard work...", rewards = "You will receive:\n\nNifty Stopwatch"}
MultiLanguageQuestData['en'][779] = {title = "Seal of the Earth", objective = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", description = nil, progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.", rewards = nil}
MultiLanguageQuestData['en'][780] = {title = "The Battleboars", objective = "Grull Hawkwind in Camp Narache wants you to kill Battleboars and bring back 8 Battleboar Snouts and 8 Battleboar Flanks.", description = "The Battleboars of Brambleblade Ravine to the east are encroaching on our tribal hunting grounds. They are trained to be malicious by the Bristleback Quilboars with whom we are at war.\n\nGo and slay the vile creatures and bring back some snouts and flanks so that we can make stew for our young.", progress = "The aggression of the Battleboars is increasing. Have you sent them a clear message and brought back some snouts and flanks yet?", completion = "Most excellent. These ingredients will make a fine stew and the loss of those boars should be a fair lesson to those vile Bristlebacks.", rewards = "You will receive:\n\nNomadic VestTough Hunk of Bread"}
MultiLanguageQuestData['en'][781] = {title = "Attack on Camp Narache", objective = "Bring the Bristleback Attack Plans to Chief Hawkwind in Camp Narache.", description = "After carefully evaluating the map, you realize that what you discovered are the plans made by the Bristleback warchief for an extended siege on Camp Narache.\n\nSurely Chief Hawkwind could use this information!", progress = "You have a look of concern about you, <name>. What news do you bring?", completion = "This is quite alarming indeed! But with this information we can call on our brethren from Bloodhoof Village to help thwart the attack. You have saved the lives of many &lt;race&gt;, &lt;name&gt;.", rewards = "You will receive:\n\nThick Bark Buckler"}
MultiLanguageQuestData['en'][782] = {title = "Broken Alliances", objective = "Kill Boss Tho'grun and bring the Sign of the Earth to Gorn in Kargath.", description = "From the Horde's alliance with the dragon Deathwing during the Second War, we know that two of his lieutenants, Blacklash and Hematus, were imprisoned within Lethlor Ravine far to the east. We must silence our depraved allies of old to restore honor to the Horde!\n\nWe hired Tho'grun and his band of ogre mercenaries to help us obtain the Sign of the Earth, a key needed to unlock the drakes' prison. Tho'grun betrayed us though, overwhelming us and taking it for himself. Go to Camp Boff and take it back!", progress = "Tho'grun's betrayal... is there any wonder why the ogres are part of the Horde no longer? I will be glad to see him dead, and the Sign of the Earth returned.\n\nIf you've not dispatched him yet, then waste no time going to Camp Boff.  It is to the southeast of Kargath.", completion = "With Tho'grun dead, his corpse picked clean by the desert winds and scavenging buzzards, the ogres will be put into disarray. Though a small victory, this will lead to a much larger one\n\nThe Sign of the Earth is now in our possession, and we can open the black drakes' prison in Lethlor.  We shall free them from endless imprisonment, albeit to their doom!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][783] = {title = "A Threat Within", objective = "Speak with Marshal McBride.", description = "I hope you strapped your belt on tight, young <class>, because there is work to do here in Northshire.\n\nAnd I don't mean farming.\n\nThe Stormwind guards are hard pressed to keep the peace here, with so many of us in distant lands and so many threats pressing close.  And so we're enlisting the aid of anyone willing to defend their home.  And their alliance.\n\nIf you're here to answer the call, then speak with my superior, Marshal McBride.  He's inside the abbey behind me.", progress = nil, completion = "Ah, good.  Another volunteer.  We're getting a lot of you these days.\n\nI hope it's enough.\n\nThe &lt;race&gt; lands are threatened from without, and so many of our forces have been marshaled abroad.  This, in turn, leaves room for corrupt and lawless groups to thrive within our borders.\n\nIt is a many-fronted battle we wage, &lt;name&gt;.  Gird yourself for a long campaign.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][784] = {title = "Vanquish the Betrayers", objective = "Kill 10 Kul Tiras Sailors, 8 Kul Tiras Marines and Lieutenant Benedict and return to Gar'Thok in Razor Hill.", description = "Led by Admiral Proudmoore, the humans of Kul Tiras encroached on Durotar, violating the Warchief's pact made with Jaina Proudmoore in order to defeat Archimonde years ago.\n\nThe human aggression was repelled and Tiragarde Keep fell. But recently, the Admiral's reserves, led by Lieutenant Benedict, have retaken the keep and once again pose a threat to our homeland. These humans show no respect for diplomacy.\n\nProve your honor and travel south to Tiragarde Keep to eliminate the human invaders.", progress = "You have your orders, <name>. The safety of Durotar is in question. Complete the task before you or hang your head in shame.\n\nShow your honor and defeat the humans of Tiragarde Keep.", completion = "Word of your bravery travels fast, &lt;class&gt;. Tales of your victory at Tiragarde Keep will be heralded in Orgrimmar.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][785] = {title = "A Strategic Alliance", objective = "Seek out Lar Prowltusk on the western flank of Sen'jin Village.Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.\n\nThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.\n\nThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.\n\nSeek out Lar and assist as needed.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Thrall is a most wise and noble leader. His tenacity on the battlefield is matched only by his diplomatic tact.\n\nThe Darkspear Trolls have proven to be invaluable allies to orckind. Out of loyalty and honor we have sworn a pact of protection with them.\n\nThe Warchief has sent orders to make sure our Darkspear friends in Sen'jin Village are not under any direct threat. One of their most trusted scouts, Lar Prowltusk is keeping a close watch on their western flank.\n\nSeek out Lar and assist as needed.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][786] = {title = "Thwarting Kolkar Aggression", objective = "Lar Prowltusk outside of Sen'jin Village wants you to destroy the 3 sets of Attack Plans held within Kolkar Crag.", description = "Lower your voice, <class>. The Kolkar centaurs lie just over the ridge to the west in Kolkar Crag.\n\nLast night while they were raiding, I snuck into their village and discovered that the dirty beasts have a three-tiered attack planned on the trolls and orcs of Durotar.\n\nWe mustn't let their invasion come to fruition. Perhaps you can muster the might needed to infiltrate Kolkar Crag and destroy their attack plans.\n\nLast I saw, they had divided them up amongst three of their leaders.", progress = "The centaurs have proven to be a consistent nuisance to the Horde. Their intentions to lay siege to our homeland cannot be tolerated.", completion = "The Horde would surely prevail if the Kolkar centaurs were to attack. But by preventing such an attack, we have spared our mighty warriors unnecessary bloodshed.\n\nAnd as sure as there is sand in the Tanaris desert, we know that there will be blood spilled before these trying times are through.\n\nYou have served your people well, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nSeasoned Fighter's CloakHeavy Cord Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][787] = {title = "The New Horde", objective = "Report to Gornek in the Den.Throm'ka, <class>. I am Eitrigg, charged by Thrall to oversee the training of recruits.\n\nThe Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned.\n\nGornek will have further instructions for you.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Throm'ka, <class>. I am Eitrigg, charged by Thrall to oversee the training of recruits.\n\nThe Horde has changed from what it once was. There was a time where I left the Horde, disillusioned by the growing influence of the power-hungry pawns of the Burning Legion. During my exile, I was taken prisoner by a group of humans, but was rescued by the Warchief. Hearing his vision of the Horde free of demonic influence, guided by the shamans, I returned.\n\nGornek will have further instructions for you.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][788] = {title = "Cutting Teeth", objective = "Kill 10 Mottled Boars then return to Gornek at the Den.", description = "The first order of business will be to put a little strength in your backbone. I could send you out to the Barrens to hunt kodo, but well, in all honesty, you're more useful to us alive than dead.\n\nI believe you would find a good match with the mottled boars you'll find to the north of here.", progress = "I hope you haven't returned to try and convince me that you have completed your task, <name>? No, of course not. I would think better of you.", completion = "Hmmm, not bad, &lt;name&gt;. But don't let it get to your head...you'll fight tougher than boars in your career.\n\nNonetheless, you've proven yourself well, and your next trial will be against a considerably more dangerous opponent, so you'll need some extra protection.", rewards = "You will be able to choose one of these rewards:\n\nSoft Wool BootsBattleworn Leather Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][789] = {title = "Sting of the Scorpid", objective = "Get 10 Scorpid Worker Tails for Gornek in the Den.", description = "Powerful warrior and awkward novice alike have fallen to the venomous sting of the scorpid. You will find large numbers of scorpids northwest of here. Bring me ten of their tails as proof of your prowess in battle.\n\nThe antidote for their sting is actually made from venom extracted from their stingers. We keep large quantities of antidote for scorpid venom on hand to heal young bloods just like you...\n\nBut I'm sure you won't be needing any of that, will you?", progress = "The carapace of a scorpid isn't so thick that the strength of a determined warrior will be deterred. Strike strongly and without doubt, and the scorpids should prove easy prey.", completion = "There is an important lesson that you must take away from fighting scorpids. The smallest or largest of opponents can still send you to your doom. In fierce combat, any number of things can prove your downfall.\n\nI have no more to teach you, &lt;name&gt;. You have done well, and I will watch your progress with interest.", rewards = "You will be able to choose one of these rewards:\n\nSoft Wool BeltBattleworn Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][790] = {title = "Sarkoth", objective = "Kill Sarkoth and bring his claw back to Hana'zua.", description = "<class>! I thought I would die out here with none to know of it. While I was hunting the scorpids of the Valley, I came across a particularly vicious-looking one. Hurling myself at it, I managed to inflict a massive blow to its claw before it closed around my leg.\n\nI wasn't ready for its stinger though, and it sliced down and into my chest, cutting into my flesh and letting my blood. Please, you must kill the scorpid for me! My honor must be upheld! I fought it up on the plateau to the south.", progress = "Ahhh... my father always said I would never amount to much, and here, lying beneath a tree as life seeps away, I'm afraid it looks like he was right.\n\nAt least I wish to die knowing that my last enemy in life lays dead.", completion = "My blow was not enough to kill him, but looking at the damage I inflicted gives me some small measure of pride. That small measure will be all I have to sustain myself if I die, and in that light, the short list of my life's accomplishments fills me with anger.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][791] = {title = "Carry Your Weight", objective = "Furl Scornbrow in the Razor Hill watchtower wants 8 Canvas Scraps.", description = "Age has rendered me useless in battle. Now I make myself useful in other ways.\n\nFrom this vantage point I watch for invaders. As our strength here grows, I find myself blowing the signal horn less and less.\n\nTo pass the time I fashion goods to help younger, more able warriors defend our homeland.\n\nFor you, I can fashion you a bag for your belongings. If such an item would be of use to you, bring me some canvas, a material common to the humans and centaurs.", progress = "I fought proudly alongside the Warchief when these lands were pioneered. The scars of battle mark my skin.\n\nThe honor of the Horde has been upheld with the help of my axe and battlecry during the defeat of Archimonde, when the unholy alliance was made with the humans and elves, wrought from necessity.\n\nBut my position as watchman and provider has given me a new sense of worth.", completion = "Most excellent, &lt;name&gt;. Any good &lt;class&gt; will surely find a use for this bag on the battlefield.\n\nI salute your vigor and willingness to die in the name of the Horde!", rewards = "You will receive:\n\nHandmade Leather Bag"}
MultiLanguageQuestData['en'][792] = {title = "Vile Familiars", objective = "Kill 12 Vile Familiars.\n\nReturn to Zureetha Fargaze outside the Den.", description = "I trust the Valley of Trials will teach you much, young <class>.\n\nI was sent to the Valley to guide you, but I have discovered a growing taint here...\n\nA group that calls itself the Burning Blade has a coven here in the Valley of Trials.  They are skulking in a cave to the northeast, and their Vile Familiars have spilled from its mouth to cause havoc.\n\nAs your first task against the Burning Blade, I bid you, defeat these familiars. Slay many and, if you survive, return to me.", progress = "To prove yourself against the Burning Blade, you must first defeat its Vile Familiars.  Return to me when you have done this.", completion = "You have done well, &lt;name&gt;.\n\nAlthough the Vile Familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", rewards = "You will be able to choose one of these rewards:\n\nPrimitive ClubPrimitive Hand BladePrimitive HatchetPrimitive Walking Stick\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][793] = {title = "Broken Alliances", objective = "Use the Sign of the Earth to activate the Pillars of Diamond, Opal, and Amethyst and obtain the Runestones.\n\nPlace the runestones in the Seal of the Earth to free Blacklash and Hematus.\n\nSlay them and return Blacklash's Bindings, the Chains of Hematus, and the Sign of the Earth to Gorn.", description = "The Seal of the Earth is held by three runestones, held in the Pillars of Diamond, Opal, and Amethyst in Lethlor Ravine. Using the Sign of the Earth, you will be able to remove the runestones and unlock the Seal of the Earth.\n\nBe wary though, <name>, the black drakes Blacklash and Hematus are not to be trifled with. See them dead and return their bindings to me.\n\nTo reach the ravine, travel to the far eastern part of the Badlands.  Be careful though, for the ravine is home to countless drakes.", progress = "There are few enemies more deadly than dragonkind, and there were few dragons that fought as ferociously as Blacklash and Hematus.", completion = "The black dragonflight continues to ally with the renegade Blackrock orcs, and both must be brought into line, or removed. With Blacklash and Hematus dead, we can turn our attentions westwards, towards Blackrock Spire.", rewards = "You will be able to choose one of these rewards:\n\nBlazewind BreastplatePrismscale HauberkWarforged ChestplateMindburst Medallion\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][794] = {title = "Burning Blade Medallion", objective = "Bring the Burning Blade Medallion to Zureetha Fargaze, outside The Den.", description = "Through my divinations, I see that an item of power hides deep within the Burning Blade Coven, guarded by beasts and black magic.\n\nIt is called the Burning Blade Medallion, and your next task is to find it and remove it from the coven.\n\nBut be wary, for the medallion may be possessed by an agent of the Burning Blade, and if so then the agent's power would be greater than the familiars you have already encountered.\n\nGo, <name>.  You will find the coven in a cave, to the north and west.", progress = "Is your task complete, <name>?  Do you have the Burning Blade Medallion?", completion = "You retrieved it!  Well done!\n\nYour efforts within the Burning Blade Coven are key in rooting out this cult in the Valley of Trials.  But I fear they have further aims in our land.\n\nWe have not seen the end of them.", rewards = "You will be able to choose one of these rewards:\n\nDust-covered LeggingsJagged Chain VestRipped Pants\n\nYou will also receive:\n\nMinor Healing Potion"}
MultiLanguageQuestData['en'][795] = {title = "Seal of the Earth", objective = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", description = nil, progress = "The Seal of the Earth lies here, with three recessed alcoves for the Amethyst Runestone, the Opal Runestone, and the Diamond Runestone.", completion = "As you place the Runestones into the matching recesses, a violent rumbling shakes the earth as the Seal is broken.", rewards = nil}
MultiLanguageQuestData['en'][804] = {title = "Sarkoth", objective = "Bring the news of Hana'zua's plight to Gornek at the Den.", description = "Seeing the deed you have done for me steels my heart. I cannot fall so easily! I must endure!\n\nBut it remains that I cannot make the trek back to the Den unassisted. Please, <name>, return to the Den and tell Gornek of my situation. Perhaps he can help me.", progress = nil, completion = "From your description of the beast, I believe you must be speaking of Sarkoth! It is no wonder that Hana'zua was overtaken by it. Aid will be dispatched to him immediately, trouble yourself no more with Hana'zua's plight.\n\nHowever, I must say, I am most impressed to hear that you brought Sarkoth to death. It is a feat to be proud of, &lt;name&gt;. And that you would fight for a stranger's honor, while other tasks occupied your time, your own honor is heightened.", rewards = "You will be able to choose one of these rewards:\n\nSoft Wool VestBattleworn Chain Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][805] = {title = "Report to Sen'jin Village", objective = "Speak with Master Gadrin in Sen'jin Village.", description = "Your trials against the Burning Blade are finished... here in the Valley.  But I want you to report your findings.\n\nGo to the troll village of Sen'jin and seek out Master Gadrin.  Sen'jin Village is east out of the valley, then right at the fork.\n\nTell Gadrin of the Burning Blade, and that they have reached the Valley of Trials.  Discover from him if they have yet reached Sen'jin.\n\nGo, <name>, and be swift.  I fear the evil found in the Burning Blade Coven is but the herald of a larger threat...", progress = nil, completion = "Hm... your report comes at a bad time.  The Burning Blade is not seen here in Sen'jin, but their evil has taken seed off the coast, on the Echo Isles.\n\nThe orcs are friends of the Darkspear Trolls.  Honorable friends.  We want to help the orcs, but... we need help too.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][806] = {title = "Dark Storms", objective = "Bring Fizzle's Claw to Orgnil Soulscar in Razor Hill.", description = "We cannot allow the Burning Blade a foothold in Durotar!  We must destroy them before their evil festers!\n\nI have undergone my own investigations and found that a Burning Blade warlock, the goblin Fizzle Darkstorm, has camped within Thunder Ridge to the northwest.  There he and his cultist minions spread chaos.\n\nFind and defeat Fizzle, and bring me his dead claw!", progress = "Did you find Fizzle, <name>?  He, and rest of the Burning Blade, must be scoured from our lands!", completion = "Aha!  You got him!\n\nYou do your clan proud, &lt;name&gt;.  And because of you, Durotar is free of one more agent of evil.", rewards = "You will receive:\n\nTiger Hide Boots"}
MultiLanguageQuestData['en'][808] = {title = "Minshina's Skull", objective = "Retrieve Minshina's skull from the circle of power on the Echo Isles.\n\nBring it to Master Gadrin in Sen'jin Village.", description = "I hear the voice of my brother, Minshina, calling to me in my dreams.\n\nHe was taken by Zalazane, the warlock on the Echo Isles to the east. And he is dead.\n\nBut death is not freedom for my brother. Minshina's spirit was trapped within his own skull by Zalazane's magics. In my dreams I see it with other skulls, in a circle of power on the largest Echo Isle. As long as it remains there my brother's soul is doomed.\n\nPlease, <name>. Find the circle and retrieve Minshina's skull. Bring it to me.\n\nFree him!", progress = "Do you have my brother's skull, <name>?  Is he finally free?", completion = "Thank you, &lt;name&gt;.  You have saved Minshina.  You have saved my brother's spirit from slavery!", rewards = "You will receive:\n\nFaintly Glowing Skull"}
MultiLanguageQuestData['en'][809] = {title = "Ak'Zeloth", objective = "Speak with Ak'Zeloth in the Barrens.", description = "Since the last great war when the Burning Legion was defeated, I have searched for sources of demonic corruption in orc society.  The collar you brought me confirms my fears.\n\nIt belongs to the Burning Blade, a cult that rallies around an item of demonic power.  It is called the Demon Seed, and it resides in the Barrens atop Dreadmist Peak.  It must be destroyed!\n\nGo to Far Watch Post, on the border of the Barrens to the west, and speak with my assistant, Ak'Zeloth.  He will direct you further.", progress = nil, completion = "Neeru wants the Demon Seed destroyed, does he?  Strange...\n\nVery well.  If he wishes the seed gone, then I will tell you how to remove it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][812] = {title = "Need for a Cure", objective = "Find Kor'ghan in Orgrimmar and get the Venomtail Antidote. Then bring the antidote to Rhinag near the northwestern border of Durotar.", description = "<name>... your timing is perfect. I just hope I can compliment your haste as well.\n\nI was careless while fighting a few of the venomtails nearby, and one of them stung me deeply. I can feel its poison weakening me even as we speak. At this rate, I got maybe an hour left to live. But I'll need your help if I'm to do so...\n\nKor'ghan in Orgrimmar knows how to make the antidote. Find him... and hurry, <name>. I won't be able to last much longer. He should be in the Cleft of Shadow.", progress = "I'm almost glad I can't return to Sen'jin as I am now. My weakness and stupidity would surely be mocked.", completion = "&lt;name&gt;, you've saved my life. Thank you.\n\nPlease take this; I hope it can at least help you in your travels, if not bring you some coin. From what you say, I won't be usin' it anytime soon. Kor'ghan is gonna march me through more of his rituals until I prove myself. More killin' boars, more gatherin' scorpid tails...", rewards = "You will be able to choose one of these rewards:\n\nCharging BucklerLight Scorpid Armor\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][813] = {title = "Finding the Antidote", objective = "Bring 4 Venomtail Poison Sacs to Kor'ghan in Orgrimmar.", description = "Venomtails are some of the deadliest scorpids in Durotar. It was unwise for Rhinag to hunt them without having some of the antidote with him, but right now, chastising is the last thing he needs.\n\nBring me a few venomtail poison sacs from any of the venomtails near the entrance of Orgrimmar and I'll make an antidote for him.\n\nMake haste, <name>. One of our own needs your help.", progress = "Remember, no matter what creature you hunt, you would do well to study it and understand its behavior. That knowledge could save your life.", completion = "Here is the antidote, &lt;name&gt;. Take it to Rhinag as soon as you can, and be cautious.", rewards = "You will receive:\n\nVenomtail Antidote"}
MultiLanguageQuestData['en'][815] = {title = "Break a Few Eggs", objective = "Bring 3 Taillasher Eggs to Cook Torka in Razor Hill.", description = "Bah! I almost forgot I need to get breakfast ready.\n\n<name>, get yourself movin' and get me some taillasher eggs. I'll need at least three of them if I'm going to have enough for tomorrow's meal.\n\nThe Bloodtalon taillashers can be fierce, and protect their eggs to the death more often than not. They sometimes bury their eggs too deep in the earth to uncover safely, but if you head to the Echo Isles to the southeast of Sen'jin Village, you can usually find them all over those islands.", progress = "Breakfast, lunch, dinner! Who cares which meal it is? It still has to be cooked by someone--namely me!", completion = "You might be weak, but at least you're not clumsy, &lt;name&gt;.\n\nHere, take this and get outta my way. I've got cooking to do.", rewards = "You will receive:\n\nTough Hunk of BreadTough Jerky"}
MultiLanguageQuestData['en'][816] = {title = "Lost But Not Forgotten", objective = "Bring a sign of Kron's fate to Misha Tor'kren at the farmstead northwest of Razor Hill.", description = "<name>, please, can you help me? My son Kron went hunting days ago, and he still hasn't returned. He went west towards the Barrens to hunt crocolisks along Southfury River. I fear the worst.\n\nAs strong as he was, his stubborn pride has always drawn him into trouble. I warned him that the crocolisks were powerful and vicious. He grew angry and stormed off.\n\nIf you can't find him, at least bring me a sign of his fate... even if you have to open up the stomach of every crocolisk along the Southfury's banks.", progress = "I pray that Kron will return to me, but I'm almost certain I know his fate already.", completion = "Oh, my son... my beautiful son.\n\nUncertain of my son's fate, I have tormented myself since he left. Now that I know what's happened, perhaps I can finally begin to mourn.\n\nThank you, &lt;name&gt;. Please take this. I was going to give it to Kron as a gift when he returned successful. Now that I know he is dead, I cannot bear to look at it.", rewards = "You will receive:\n\nHandsewn Cloak"}
MultiLanguageQuestData['en'][817] = {title = "Practical Prey", objective = "Bring 4 Durotar Tiger Furs to Vel'rin Fang in Sen'jin Village.", description = "Many of the hides we use come from Durotar tigers, <name>. Blankets, armor, tents: there are a great many reasons we hunt the beasts, and many reasons we let them thrive at the same time.\n\nThe time has come for us to cull the flock, so to speak. Our numbers grow, and our needs are beginning to overwhelm our stocks. I need more hides if I'm to prepare suitable goods for our people.\n\nBring me 4 Durotar tiger furs, and I shall reward you. You can find them on the islands south of here.", progress = "I remember my first tiger hunt, <name>. I chose to hunt on the largest of the Echo Isles, and I sat perfectly still in the shadows of its foliage for almost a full day... watching... waiting.\n\nMy muscles were taut, and I was ready to strike. It was one of my greatest victories when that tiger finally took the bait.", completion = "I am pleased, &lt;name&gt;. Because of your help, our people will be protected, and not go cold as the seasons change.\n\nThank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][818] = {title = "A Solvent Spirit", objective = "Bring 4 Intact Makrura Eyes and 8 vials of Crawler Mucus to Master Vornal in Sen'jin Village.", description = "Although my eyes fail me, I still can see clearly enough. More often I must rely on my alchemical skills to aid me in magics that once came easily. But I refuse to take on an apprentice--no troll or orc worthy enough has ever come forward.\n\nAre you worthy? Yes, of course you are... of course you think you are.\n\nI need a few things. Will you get them for me?\n\nI need intact makrura eyes, and vials of crawler mucus. You can find them on any makrura or crawler in Durotar. We shall speak again soon.", progress = "Time is the true test of your strength and will. Lose patience or give in to weakness, and your true self will be shown.", completion = "Well done, young one... well done indeed.", rewards = "You will receive:\n\nReally Sticky Glue"}
MultiLanguageQuestData['en'][819] = {title = "Chen's Empty Keg", objective = "Find someone who knows about Chen's Empty Keg.", description = "A small placard on one of the ends of the keg says,\n\n\"Chen Stormstout-\n\nMay your spirit be raised and always raise your spirits.\"", progress = "Yes?", completion = "Well, I'll be...\n\nThis was one of Chen Stormstout's kegs. He traveled with Rexxar a long time ago. I haven't seen or heard about him in a kodo's age. I appreciate you bringing this to me, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][821] = {title = "Chen's Empty Keg", objective = "Bring 5 Savannah Lion Tusks, 5 Plainstrider Kidneys, and 1 Thunder Lizard Horn to Brewmaster Drohn in Ratchet.", description = "Would you like a taste of Chen's namesake? Ahh, the stormstout is a mighty brew. Chen taught the recipe to my mentor, and my mentor passed it on to me. I'll need you to get me a few things, but I can tell you this: the kick is worth it.\n\nBring me 5 savannah lion tusks from any savannah lion, 5 plainstrider kidneys from any plainstrider, and 1 thunder lizard horn from any species of thunder lizard. That should do the trick nicely.\n\nYou can find these ingredients throughout the Barrens.", progress = "How's the search going?", completion = "Haha... I never thought I'd make more of this stuff ever again.\n\nYou've stirred in me a great sense of nostalgia, &lt;name&gt;. Kind of reminds me of the last time I made a batch of trogg brew. Thank you. The memories warm my stomach.", rewards = "You will receive:\n\nStormstout"}
MultiLanguageQuestData['en'][822] = {title = "Chen's Empty Keg", objective = "Bring 5 Lightning Glands, 1 Thunderhawk Saliva Gland and 1 Kodo Liver to Brewmaster Drohn in Ratchet.", description = "Good stuff, that stormstout, huh?\n\nI have another recipe that I learned from Chen. Would you be interested? It won't take long to make, and it might be useful if you plan on adventuring some more.\n\nBring me 5 lightning glands from any stormhide, 1 thunderhawk saliva gland from greater thunderhawks, and a kodo liver from any of the Barrens' kodos.\n\nLike I said, this stuff has kick; it's the trogg brew that I mentioned to you before.", progress = "You working hard at finding those ingredients, <name>?", completion = "Haha! I knew you couldn't resist some of this brew. Come back again anytime you want some more, &lt;name&gt;. Just bring me more of the ingredients I had you collect.", rewards = "You will receive:\n\nTrogg Brew"}
MultiLanguageQuestData['en'][823] = {title = "Report to Orgnil", objective = "Speak with Orgnil Soulscar in Razor Hill.", description = "We at Sen'jin Village are not without our own troubles, and we thank you for your aid.  But the news you bring regarding the Burning Blade could be trouble for everyone.\n\nThere is an orc stationed at Razor Hill, Orgnil Soulscar, who polices Durotar from evils such as the Burning Blade!  Go to Orgnil and tell him of our plight, as well as your news from the Valley of Trials.  He will want to know these things.\n\nRazor Hill lies to the north.", progress = nil, completion = "Yes?  You have something to report?  Well then, let's have it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][824] = {title = "Je'neu of the Earthen Ring", objective = "Bring the Befouled Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", description = "The Earthen Ring is a shamanistic group dedicated to studying and preserving the elements.  They have forgotten more about crazy old gods, ancient legends and lore than most scholars will ever know.\n\nLucky for you, I know someone in the Earthen Ring here in Ashenvale.  Head over to Zoram'gar Outpost on the coast of the Zoram Strand; show Je'neu Sancrea what you found.  If anyone can figure out that globe's significance, it'd be him.", progress = "Ah, hello there.  I spend a great deal of time studying the water - all the elements really - so much so that sometimes I don't even notice people around me.\n\nIs there something I can help you with?", completion = "This globe... it is most disturbing.  Many of the more powerful elementals receive their power and energy through such devices.  To find one like this nearly intact is one thing - to find it so tainted is another.\n\nI will see that this globe is studied properly by the Earthen Ring.  Perhaps we can bring an end to this corruption of the elements.  Please - accept this as a fair exchange for bringing this globe to the attention of the Earthen Ring.", rewards = "You will be able to choose one of these rewards:\n\nDeftkin BeltDriftmire ShieldSoft Willow Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][825] = {title = "From The Wreckage....", objective = "Gar'Thok of Razor Hill wants you to retrieve 3 Gnomish Tools from the wreckage off the coast.", description = "One of my most observant scouts brings back word that the wreckage of Proudmoore's fleet still remains off the coast of Durotar, just east of Tiragarde Keep.\n\nIt is no secret that the humans, in alliance with those foul little creatures known as gnomes, have an advanced knowledge of mechanics. We must have a complete understanding of all our potential enemies. And our people will benefit from this new knowledge as well.\n\nSwim through the wreckage, <name>, and retrieve for me the tools of the Alliance.", progress = "Once we learn how the humans operate their strange machinery, we will stand a greater chance of defeating them in future battles.\n\nWith our new gained knowledge, the Horde only stands to grow in strength.", completion = "Your recovery mission was a success, &lt;class&gt;. I will see to it that these tools get to Orgrimmar with the next caravan.\n\nNicely done.", rewards = "You will be able to choose one of these rewards:\n\nDirt-trodden BootsSandrunner WristguardsWide Metal Girdle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][826] = {title = "Zalazane", objective = "Defeat Zalazane.\n\nKill 8 Voodoo Trolls and 8 Hexed Trolls.\n\nBring Zalazane's Head to Gadrin.", description = "The witchdoctor Zalazane dwells on the Echo Isles to the east.  They are the isles we once called home.\n\nFrom there he sends his trolls to the mainland, to hex our people and drag more of them under his sway.\n\nHe must be stopped.\n\nDefeat Zalazane and his minions -- former Darkspear trolls, now lost to us.  Bring me his head and I will know his reign of evil is over.", progress = "Is Zalazane defeated, <name>?", completion = "With Zalazane gone, our tribe can again sleep in peace.\n\nThank you, &lt;name&gt;.  The Darkspear tribe owes you much.  If you suffer from an ailment, visit my assistant Bom'bay, behind me.  His voodoo is strong...", rewards = "You will be able to choose one of these rewards:\n\nLightweight BootsVeiled Grips\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][827] = {title = "Skull Rock", objective = "Gather Searing Collars from the cultists in Skull Rock.\n\nBring them to Margoz at his camp.", description = "<name>.  The Burning Blade has infested the cave east of Orgrimmar known as Skull Rock.  Inside that cave they perform vile rituals, and burn their own flesh with Searing Collars.\n\nBy wearing these collars, I believe the cultists attune themselves to demonic power.  But to confirm this, I must have a collection of the collars to study.\n\nGo to Skull Rock and gather Searing Collars from the cultists you find there.  Bring them to me, and I will uncover their secrets.", progress = "Have you yet entered Skull Rock, <name>?  Do you have the Searing Collars?", completion = "Good.  Hiding within these collars is the secret behind the Burning Blade.  And I will uncover that secret...", rewards = "You will be able to choose one of these rewards:\n\nJagged DaggerSteady Bastard SwordStinging Mace\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][828] = {title = "Margoz", objective = "Speak with Margoz.", description = "One of our Shamans, Margoz, knows more of the Burning Blade's corruption.  He speaks of a cave called Skull Rock in the mountains - just outside Orgrimmar! - that shelters a large band of Burning Blade cultists.\n\nBefore you go to Skull Rock speak with Margoz.  He is wise and his council is valued.\n\nHe is camped to the northeast, between the coast and Drygulch Ravine.\n\nFollow his advice, but whatever Margoz says, <name>, I still want you to crush those cultists!", progress = nil, completion = "Welcome, &lt;name&gt;.  Word reached me of your coming, and of your exploits in Durotar.\n\nYou are a &lt;class&gt; of growing skill and renown.\n\nStay on the pure path, and your future will be great indeed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][829] = {title = "Neeru Fireblade", objective = "Bring an Example Collar to Neeru Fireblade in Orgrimmar.", description = "The Searing Collars you brought me are powerful, demonic implements.  Divining their origin is, I'm afraid, beyond my skills as a shaman.  We will need a warlock to study them.\n\nTake a searing collar to Neeru Fireblade.  Although he is a skilled warlock, he professes to use his powers to thwart demons, and claims his research in the occult is benign.  Be that true or false, we may need his aid against the demonic cult in Durotar.\n\nYou may find Neeru in Orgrimmar in the Cleft of Shadow.", progress = "My most humble greetings, <class>.  How might I help my <race> brother today?", completion = "Ah, and where did you get this?  Good Margoz in Razor Hill sent you to me, did he?\n\nWell, let me take a closer look...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][830] = {title = "The Admiral's Orders", objective = "Take Admiral Proudmoore's Orders to Gar'Thok in Razor Hill.", description = "You open the aged and weathered envelope and discover an official looking document. You recognize the seal of Admiral Proudmoore.\n\nThis looks important. Perhaps Gar'Thok, the commander of Razor Hill, would be interested in having this information.", progress = "There is a look of concern on your face, <class>. What have you there?", completion = "This does not bode well at all. You were wise to bring this information to my attention.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][831] = {title = "The Admiral's Orders", objective = "Deliver Admiral Proudmoore's Orders to Vol'jin in Thrall's chamber in Orgrimmar.", description = "Humans cannot be trusted. We fought alongside them with a weary heart, knowing they would betray us one day.\n\nAdmiral Proudmoore's death was not enough to stop his legacy of deceit. The human scum had his plans well laid out before he ever met his demise.\n\nHis reign won't even die with Benedict it seems. Who knows how long it will be before the next waves of Proudmoore's men land upon our shores.\n\nWe need to get these orders to Vol'jin in Orgrimmar immediately! He can be found in Thrall's chamber.", progress = "Can you not see that I am busy? This had better be pressing....", completion = "Countless times I urged the Warchief not to trust the humans, but personal pride is not what is at stake here.\n\nYou have served the Horde honorably, young &lt;class&gt;.\n\nNow excuse me, I must counsel Thrall on these matters at once....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][832] = {title = "Burning Shadows", objective = "Take this eye to Neeru Fireblade.", description = "<Words emanate from the pendant and into your mind.>\n\nGazz'uz?\n\nGazz'uz...report!\n\nThere is word of your discovery in Skull Rock.  You must prepare for an attack!\n\nGazz'uz, I order you to speak!  Speak or I will make sure Neeru Fireblade knows of your presence, and he will descend on you with swift brutality.\n\nDo not test your skills against Neeru...\n\n...Gazz'uz, are you there...?", progress = "You have something vital to report.  I can sense it behind your eyes.", completion = "&lt;Examines the Eye of Burning Shadow.&gt;\n\nIntriguing.  The voice you heard mentioned my name?  I am known for hunting down enemies of our Warchief, but...it is strange that I was singled out.  Stranger still that the Burning Blade cultists from whom you recovered this pendant have a name so close to my own.\n\nI must study this pendant.  I must study and, and must ponder the meaning of its message.\n\nThank you for bringing this to my attention, &lt;name&gt;.  You have done your people a great service.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][833] = {title = "A Sacred Burial", objective = "Lorekeeper Raintotem wants you to kill 8 Bristleback Interlopers at Red Rocks.", description = "Only the most valiant tauren are laid to rest at Red Rocks, our sacred burial ground. It is an honor bestowed upon the great warriors who helped found and defend Thunder Bluff and those who have given their lives for the greater good of their tribes and chieftains.\n\nBut it appears a foul menace has made its way onto our holy land. A band of Bristleback Interlopers is ravaging the grave site and I am too old and past my prime to drive them away.\n\nThey must be driven off with force, <name>.", progress = "The Bristleback Interlopers must be driven away from our sacred burial ground, <name>.", completion = "Well done. You have sent those foul Bristlebacks a clear message. They will think twice before attempting to meddle in this holy spot again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][834] = {title = "Winds in the Desert", objective = "Retrieve 5 Sacks of Supplies and return them to Rezlak near Orgrimmar.", description = "I'm Rezlak, one of Gazlowe's boys. Boss sent me to help the orcs here in Durotar. Things'd been going good except for the caravans. Can't manage to keep them safe! Makes my job a little harder, you know?\n\nThe last shipment--they promised it'd get through!--was snatched by the Dustwind harpies of...where was it...Razorwind Canyon?\n\nI gotta have those supplies or I'll never get anything done! Follow the big canyon to the south, you'll find the ravine cut right into the west and east sides of the walls.", progress = "I'm great at what I do, don't get me wrong, but this is ridiculous! What am I supposed to do, build sand castles?", completion = "Hey, now isn't that just the thing! You've got our supplies back for us. That's great. I'll be able to get back to work just as soon as I can find someone to haul these sacks for me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][835] = {title = "Securing the Lines", objective = "Kill 12 Dustwind Savages and 8 Dustwind Storm Witches for Rezlak near Drygulch Ravine.", description = "Gazlowe told me once, \"Rezlak. There's one thing you need to know in life, and that's if you want something done well, do it yourself.\"\n\nI can't deal with losing all our caravans, so I'm just going to take matters into my own hands. Drygulch Ravine lies through the eastern part of Razorwind Canyon. If we kill all the harpies there, the routes will be safe.\n\nOf course, there was one other thing that Gazlowe taught me, and that's \"You can get anything done for a price.\" So, going to help me out, <name>?", progress = "You wouldn't think it from a guy like my boss Gazlowe, but he always seemed to know the score. \"Don't be afraid to take that big step,\" he said.\n\nHarpies won't stop bothering us and the caravans won't stop being attacked unless we do something about it, eh?", completion = "I think I can breathe easy now, knowing that the harpies won't be bothering our supply caravans anymore. And not one moment too soon, either. I hear I'm being sent some fun little toys with the next shipment!\n\nYou're pretty good at what you do, &lt;name&gt;, you ought to track down my boss in Ratchet. I'll bet he could find some work for you.\n\nOh, and don't worry, I wouldn't forget to pay you for the service you provided me.", rewards = "You will be able to choose one of these rewards:\n\nHarpy Wing ClipperHickory ShortbowBlemished Wooden Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][836] = {title = "Rescue OOX-09/HL!", objective = "Escort OOX-09/HL to the shoreline beyond Overlook Cliff, then report to Oglethorpe Obnoticus in Booty Bay.", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-09/HL to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the shoreline beyond Overlook Cliff!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the shore, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", progress = nil, completion = "Oh, YOU'RE the great savior of OOX-09/HL!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance &lt;name&gt;, my robots and I are in your debt!", rewards = "You will be able to choose one of these rewards:\n\nGnomish Inventor BootsGnomish Water Sinking Device\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][837] = {title = "Encroachment", objective = "Kill 4 Razormane Quilboars, 4 Razormane Scouts, 4 Razormane Dustrunners and 4 Razormane Battleguards for Gar'Thok at Razor Hill.", description = "When we arrived, the Razormane quilboars possessed much of the land, and proved a thorn in our sides. Through our efforts we have driven out the largest part of their numbers, but still they remain well-fortified in some areas.\n\nIt has gone on long enough, however. For our own protection, we cannot allow the Razormane any hold in our lands. Their camps can be found to the west of here. Look for the brambles and you will find them. Today we drive them from Durotar, tomorrow, perhaps from all of Kalimdor.", progress = "Though they do possess some intelligence and some organization, I find it constantly amazing that the quilboars were able to capture and hold so much territory in Kalimdor. Perhaps they are more crafty an enemy than I give them credit for...", completion = "I will pass along word that the quilboars have been removed from their lairs, and that their structures may be set to fire. The removal of the Razormane from Durotar brings us closer to fully securing the borders of our new homeland.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][838] = {title = "Scholomance", objective = "Speak with Apothecary Dithers at the Bulwark, Western Plaguelands.", description = "On the island of Caer Darrow lies Scholomance - a school that serves as a stronghold for the Scourge.  Our enemy dwells within, safely allowed to pursue research that strengthens their power.  A door bars the way, and try as we might no entry is to be had without a proper key.\n\nApothecary Dithers is well versed on Scholomance, and has an idea how to obtain a key.  You have proved your value to me as someone who can get things done; I now entrust this task to you.  Speak with him on this matter.", progress = nil, completion = "Yes, &lt;class&gt;, the High Executor mentioned you might be the one to trust in the matter of the key.  I've dedicated a fair portion of my recent studies to the Scholomance, and I believe I know a means by which you can acquire one that will let you past the front door at will.\n\nThis task will not be easy, but such tasks seldom are.  You most assuredly look like the type to know this as fact.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][840] = {title = "Conscript of the Horde", objective = "Follow the western road from Razor Hill to the Barrens over a bridge.\n\nStop at the orc outpost across the bridge.\n\nGive Kargal Battlescar at the Barrens outpost your recruitment letter.", description = "Hmm, you look pretty strong.\n\nListen, my good friend Kargal needs some new recruits for Barrens duty. I know you want to do what's right for the Horde. Well, this is your chance.\n\nTake this recruitment letter to Kargal and see if he'll sign it.", progress = "What do you want, pup? If you're not here for recruitment, I don't have time for you.", completion = "Oh, so Takrin sent you? He's an excellent scout, I'm not sure what I'd do without him.\n\nI'll sign your recruitment letter, but what we really need is someone at the Crossroads.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][841] = {title = "Another Power Source?", objective = "Bring 10 Wastewander Water Pouches to Chief Engineer Bilgewhizzle in Gadgetzan in exchange for another power source.", description = "Let me guess - you didn't get whatever world-ending, nefarious deed you were doing done in time.  No wait, better still... you dropped it in the sand!  Well, whatever the reason, I do have additional power sources I will sell to you.  This time, however, it will cost you ten, YES TEN Wastewander Water Pouches!\n\nTimes are tough all around, <name>, and power sources don't grow on trees!  Hrm, but what if they did.  Maybe we could MAKE a power source tree...", progress = "Well, have you got the ten water pouches?", completion = "Very well, here is another power source.  I highly recommend you using it properly this time, unless you are eager to spend ten more water pouches for another water source.", rewards = "You will receive:\n\nModel 4711-FTZ Power Source"}
MultiLanguageQuestData['en'][842] = {title = "Crossroads Conscription", objective = "Follow the western road from Kargal's Far Watch Outpost.\n\nAt the T intersection, turn left and follow the road south. \n\nFind Sergra Darkthorn at the crossing of roads within the Crossroads.", description = "Take this signed recruitment letter to the Crossroads.\n\nSergra Darkthorn, curse her hide, is in charge there. She's a nasty shaman who will talk your head in circles before she lets you do anything useful. Thrall is convinced she's something special, but I'm not so sure.\n\nYou'll just have to decide for yourself, pup...", progress = "Well well well, what do we have here? Has Kargal deemed me worthy of another recruit?", completion = "Alright, &lt;name&gt;. You want to earn your keep with the Horde? Well there's plenty to do here, so listen close and do what you're told.\n\n I see that look in your eyes, do not think I will tolerate any insolence. Thrall himself has declared the Hordes females to be on equal footing with you men. Disrespect me in the slightest, and you will know true pain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][843] = {title = "Gann's Reclamation", objective = "Gann Stonespire wants you to kill 15 Bael'dun Excavators and 5 Bael'dun Foremen.\n\nBring Khazgorm's Journal to Gann Stonespire.", description = "In solitude I wander these roads.\n\nThe dwarves of Bael Modan show no respect for my land. Horrendous blasts drive holes deep into the ground as noisy machines rip apart the hills. Lands which once served as home and provider to my tribe are now riddled with destructive dwarves.\n\nAttempts at reaching a diplomatic resolution have failed. Now is the time for decisive action.\n\nDrive the dwarves from the Bael Modan excavation by force and bring to me the journal of their leader, Prospector Khazgorm.", progress = "Many innocent tauren lost their lives or were forced off their ancestral birthplace when the dwarves of Bael Modan arrived. My land must be reclaimed!", completion = "Khazgorm met the fate he earned. I feel no remorse for the fool. He was an infidel on these lands.\n\nMay his death serve as a warning to all those who threaten to disrupt our way of life.\n\nNow let me take a moment to study the dwarf's journal....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][844] = {title = "Plainstrider Menace", objective = "Collect 7 Plainstrider Beaks and return them to Sergra Darkthorn in the Crossroads.", description = "Your first prey will be easy.\n\nThe plainstriders to the east have been harassing our food supplies and have become a nuisance.\n\nPut down the plainstriders and return to me with their beaks.", progress = "Have you collected the plainstrider beaks?", completion = "Very good, &lt;name&gt;.  With the plainstriders gone we'll have an easier time keeping our supply chains intact.  And I hope you learned a few tricks out there in the Barrens, for your next prey has a little more fire in its blood than the plainstriders...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][845] = {title = "The Zhevra", objective = "Slay Zhevra Runners to collect 4 Zhevra Hooves for Sergra Darkthorn in the Crossroads.", description = "The zhevra, although not the fiercest beast in the Barrens, are a shade tougher than the plainstriders.  Don't worry -- we'll send you against bigger prey in good time, but for now your teeth could use a little more cutting.\n\nHunt the zhevra to the north and south, and collect their hooves.  Bring them to me and perhaps we'll next send you against something tougher.", progress = "How many zhevra have you slain?", completion = "Not bad, &lt;name&gt;.  Those zhevra hold a lot of strength in their legs.  A sharp kick from them can knock even a tauren on its haunches!\n\nIt looks like you have some strength in you too.  Are you ready for a real challenge?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][846] = {title = "Revenge of Gann", objective = "Gann Stonespire wants you to bring him 6 vials of Nitroglycerin, 6 bundles of Wood Pulp, and 6 samples of Sodium Nitrate.", description = "It is clear the prospector depended on explosives and those noisy vehicles to rip the ground apart. We can expect a new foreman to take over soon.\n\nI want to give the dwarves a taste of their own medicine. According to these plans if we combine nitroglycerin with wood pulp and sodium nitrate we can create an explosive charge. The rifleman, soldiers and officers in the Keep are known to have the supplies.\n\nCollect these items and bring them to me. I will fashion a charge that the dwarves won't forget!", progress = "I see you are back, <name>.\n\nWhile Khazgorm's death might delay the digging in my ancestral lands some, it will by no means bring a total end to the destruction.\n\nThe Keep at Bael Modan is an increasing military threat. Built to defend the dig site, it is now poised for offensive force as well.\n\nIf you have the ingredients I requested, I can fashion a charge that will make the hasty dwarves reconsider their actions here in the Barrens.", completion = "I see you are quite industrious, &lt;class&gt;.\n\nNo doubt we shall soon have a fitting surprise for those dwarves.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][847] = {title = "Guile of the Raptor", objective = "Speak with Tor'gan.", description = "This... this power.... Is this the power of the shamans that Tor'gan tried to show me? I must say, it is interesting. Tell Tor'gan that he has convinced me... for the time being. I will listen to what he has to say.", progress = nil, completion = "When the enchantment wears off, I will speak with Gor'mul. My thanks to you for your help in returning Gor'mul to the land of the living. I have no doubt he thanks you greatly as well.", rewards = "You will receive:\n\nCall of the Raptor"}
MultiLanguageQuestData['en'][848] = {title = "Fungal Spores", objective = "Bring 4 Fungal Spores to Apothecary Helbrim at the Crossroads.", description = "The oases of the Barrens hide a mystery.  Life energy flows from their waters, invigorating the plants and beasts that drink it.\n\nInvigorating, and altering.\n\nThere is a mushroom that grows near these oases.  Its spores hold properties that we, the apothecaries of Lordaeron, find useful.\n\nBring me these spores and you will earn our gratitude.", progress = "Do you have the spores, <name>?  There is a concoction I must send to my associate in Thunder Bluff, which requires the spores...", completion = "Ah, yes.  These are good specimens.  Potent.\n\nI am Forsaken, and we honor our contracts.  Here is your reward, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][849] = {title = "Revenge of Gann", objective = "Destroy the flying machine at Bael Modan and return to Gann Stonespire.", description = "Following Khazgorm's plans it should be no problem to fashion an explosive charge\n\nAh, there we go.\n\nNow, <name>, I am going to entrust you with a special task. Take this explosive stick and use it to blow up the flying machine at Bael Modan.\n\nNot only is the flying machine a key part of the site's infrastructure it also serves as a weapon of war. More importantly it is an icon of power and an insult to the memory of my tribe.\n\nMake me proud by completing this heroic task and you shall be rewarded.", progress = "Once the dwarven flying machine has been destroyed I will feel the sweet satisfaction of revenge.", completion = "You have done well, &lt;name&gt;! May you be revered in Thunder Bluff as a defender of sacred tauren lands and a champion of the lost tribe.", rewards = "You will receive:\n\nTotemic Clan Ring"}
MultiLanguageQuestData['en'][850] = {title = "Kolkar Leaders", objective = "Bring Barak's Head to Regthar Deathgate, west of the Crossroads.", description = "The centaurs have plagued the Tauren for years.  And recently, the Kolkar centaurs of the Barrens have grown into a real threat.  Normally they were disorganized in these lands, but new leaders have risen among them.  Rallying them.\n\nTo preserve our holdings here, these centaur leaders must be destroyed.\n\nBring me the head of Barak Kodobane.  He camps near the Forgotten Pools to the north.\n\nDefeat him, then return to me.", progress = "Hello, <name>.  Do you have Barak's Head for me?", completion = "Well done, &lt;name&gt;.  The centaur are low, brutish creatures, but a few have the wit and vision to lead.  And those are the most dangerous.\n\nBarak was such a centaur.  It is good that he is dead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][851] = {title = "Verog the Dervish", objective = "Bring Verog's Head to Regthar Deathgate, west of the Crossroads.", description = "The centaur Verog the Dervish wanders the Barrens, and will be difficult to find.  But he is based at the centaur command tent at the Stagnant Oasis to the southeast.  It may be possible to draw him to you.\n\nTravel to the Stagnant Oasis to the southeast and attack centaur near the command tent.  It will be dangerous, but if you can kill enough centaur then they should raise an alarm.  And Verog will come.\n\nBring me his head and I will place it with Barak Kodobane's.", progress = "Did you find Verog, <name>?", completion = "Very good.  You must have really stirred up those centaur -- our guards spotted activity down near the Stagnant Oasis, which was probably you.\n\nYou should be proud of your deed, &lt;name&gt;.  There is much bravery in you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][852] = {title = "Hezrul Bloodmark", objective = "Bring Hezrul's Head to Regthar Deathgate, west of the Crossroads.", description = "Hezrul Bloodmark is the leader of the Kolkar centaurs in the Barrens.  He is fierce, brutal and cunning.  Defeating him would disrupt and fracture the Kolkars, greatly reducing their threat to us.\n\nSo kill him.  As with Barak and Verog, bring me Hezrul's Head.\n\nHe leads his people from the Lushwater Oasis, to the south.", progress = "Is Hezrul defeated, <name>?", completion = "I commend you, &lt;name&gt;.  These centaur are undisciplined and cannot focus their rage as the orcs can, but they are fierce nonetheless.  In defeating them, your valor is proven.", rewards = "You will receive:\n\nBounty Hunter's Ring"}
MultiLanguageQuestData['en'][853] = {title = "Apothecary Zamah", objective = "Bring the Rendered Spores to Apothecary Zamah in Thunder Bluff, before the time limit is up.", description = "I have rendered the spores you gave me into an emulsion.  I must now send it to my associate, Apothecary Zamah.  If you were to carry this to her, she can offer you something from our stores of alchemical goods.\n\nShe is in the Pools of Vision, a cave beneath the shamans of Thunder Bluff.  The path to this cave is well hidden, but you may find it on the Spirit Rise bluff.\n\nDo hurry.  This emulsion will maintain its potency for only a short time, and must be resealed and processed before then.", progress = "You have something from Apothecary Helbrim?", completion = "Ah, the spores from the Barrens that Helbrim was gathering.  He garnered your aid in delivering them?  Good.\n\nAnd the emulsion is still potent, so you must have wasted no time in the delivery.  Well done, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nElixir of Minor FortitudeElixir of Minor AgilityMinor Rejuvenation PotionSwiftness Potion\n\nYou will also receive:\n\nCauldron Stirrer"}
MultiLanguageQuestData['en'][854] = {title = "Journey to the Crossroads", objective = "Speak with Thork at the Crossroads in the Barrens.", description = "I have foreseen your arrival, young <class>. Though perhaps you are not so young anymore.\n\nI think that it is time for you to move deeper into this land. I can sense that you are destined for great things.\n\nIt is the Crossroads that you must seek out, for our lives with the orcs have become intertwined and they need assistance. Continue down this road towards the east and follow it north to the Crossroads. Find Thork within its walls, he has the Earthmother's blessing.", progress = nil, completion = "It is good to see that more of our &lt;race&gt; allies have come to assist us from as far away as Thunder Bluff. Again, I welcome you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][855] = {title = "Centaur Bracers", objective = "Bring 15 Centaur Bracers to Regthar Deathgate, west of the Crossroads.", description = "The Kolkar are a threat to the Horde's claims in the Barrens; we must reduce the numbers of their troops.  And so, I have a bounty task for you.\n\nWhile in Kolkar territories, slay their warriors and collect centaur bracers.  Return when you have a heap of bracers and the Horde will reward you well.", progress = "How goes your hunting, <name>?", completion = "Nicely done.  I'm sure you've struck fear into the surviving centaurs, &lt;name&gt;.  If they have sense, they'll now calm themselves and stop their advances.\n\nBut I don't think they will, and that is unfortunate.\n\nUnfortunate...for them.", rewards = "You will be able to choose one of these rewards:\n\nOrcish Battle BowPointed AxeStonewood Hammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][857] = {title = "The Tear of the Moons", objective = "Feegly the Exiled wants you to retrieve for him the Tear of the Moons.", description = "The power was mine! In my very hands! And I want it back! Back I say!\n\nThose dirty excavators uncovered it... so beautiful it was. Deemed the Tear of the Moons, it was the first great discovery we made at Bael Modan.\n\nIt should have been mine! Mine I say!\n\nGeneral Twinbraid grew jealous of the power it gave me. He locked it away in the Keep. Called it cursed, he did! The fool!\n\nOthers wanted it and they had to be stopped! That bastard Twinbraid drove me off.\n\nNow I want it back. Back I say!", progress = "Where is the Tear of the Moons? I need it now! Need I say!", completion = "At last, the power is mine again! Mine I say!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][858] = {title = "Ignition", objective = "Get the Ignition Key and bring it to Wizzlecrank.", description = "I don't suppose Sputtervalve sent you? I'm in a bind here. I hopped in without realizing that I need a key to unlock the shredder's movement column. One of the other shredder operators asked me if everything was okay, and I panicked! Instead of telling him that I was missing my key, I told him there was some sort of mechanical problem.\n\nWe need to get out of here on the double! Go up to the control room at the top of the derrick, the supervisor should have a key for this shredder.\n\nHelp me out here!", progress = "Quick, we need to get out of here before someone gets suspicious!", completion = "Yep, this looks like the right key. Let me just make sure I know how to work this thing...\n\nHmm... rotation control... This regulates speed and stability... fine arm movement control. Just look at this! I can't believe the Venture Company could design something this much better than ours. I've got to get this back to Ratchet!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][860] = {title = "Sergra Darkthorn", objective = "Speak with Sergra Darkthorn at the Crossroads.", description = "If you wish to walk the hunter's path, then your journey leads to the Barrens.  Its beasts are strong-willed and fierce.  You will learn much by hunting there, and your spirit will grow.\n\nSpeak with Sergra Darkthorn.  She will be your first guide in the Barrens.\n\nSergra is at the Crossroads.  To reach her, travel east from Bloodhoof Village into the Barrens, then north as the road forks.  And have care as you travel--the Barrens holds great danger for the unprepared and unwary.", progress = nil, completion = "You want to hunt in the Barrens?\n\nYour eyes are eager, and young.  They're not yet squinted from tracking your prey across this land's dry plains.\n\nBut worry not. We'll toughen your body and your mind.  And we'll teach you that there is more to hunting than finding and killing your quarry.\n\nPrepare yourself.  Your journey begins.  Now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][861] = {title = "The Hunter's Way", objective = "Bring 4 Flatland Prowler Claws to Melor Stonehoof in Thunder Bluff.", description = "You are eager to explore, I can tell.  I too had the lust to wander, once...\n\nWander, and hunt.  For hunting is a Tauren's greatest honor.\n\nIf you truly wish to follow the ways of the hunter, then Melor Stonehoof can show you the path.  He is in Thunder Bluff, on the Hunter's Rise.\n\nAnd to show him your skill and resolve, bring him the claws of the flatland prowlers of Mulgore.  They are tough and cunning -- fitting prey for a young <class> on the hunter's path.", progress = "Greetings.  There is an air about you that tells me much.  Do we have business, you and I?", completion = "Skorn Whitecloud is a wise &lt;race&gt;.  He has hunted for years and years, and although his body is old, his spirit burns fiercely.  We are honored to have him with us.\n\nIf Skorn sent you to me, then  you too must have the hunter's spirit.  And to have gathered these claws shows your burgeoning skills.\n\nPerhaps you are ready to walk the path.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][862] = {title = "Dig Rat Stew", objective = "Bring 8 Dig Rats to Grub east of the Crossroads.", description = "A <class> like you must get pretty hungry out here in The Barrens. Me, I'm starving all day long.\n\nTell you what, I'll fix you up a nice stew. Just need a few dig rats.\n\nSeems those filthy dwarves at Bael Modan are overrun with everyone's favorite feast. Now head on down south to Bael Modan and bring me back some dig rats.\n\nYou can't call yourself a seasoned adventurer until you've spent some time killing rats! Haw!", progress = "Whack enough dig rats yet, <name>?", completion = "Normally I don't like to eat these rodents when they're so.... so... ripe. Like to let them rot for a few weeks to really bring out the flavor. But you look so hungry.\n\nLet me fix you some Dig Rat Stew. Ah, there we go.\n\nHere you go!", rewards = "You will receive:\n\nRecipe: Dig Rat StewDig Rat StewApothecary Gloves"}
MultiLanguageQuestData['en'][863] = {title = "The Escape", objective = "Protect Wizzlecrank and the stolen goblin shredder on the way to Sputtervalve in Ratchet.", description = "I suppose I'll learn as we go... Couldn't be too hard. Just some buttons here, and a lever or two... Well, are you ready to go?", progress = nil, completion = "Hopefully we'll be able to get something of value from the wrecked shredder prototype... my time's running out! I'll dispatch a salvage team to Wizzlecrank's location on the double.\n\nOh, let me give you something for your trouble, too.", rewards = "You will be able to choose one of these rewards:\n\nFlaring BatonGreasy Tinker's Pants\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][864] = {title = "Return to Apothecary Zinge", objective = "Bring the Sealed Field Testing Kit to Apothecary Zinge in the Undercity.", description = "\"Here you go, the power source is safely removed and the data is preserved.  Well, safe journeys and all that.  Hope the nefarious science experiment worked out for you and all.\"\n\nThe goblin turns away from you to attend to the demands of the Gadgetzan Water Company.  You secure the sealed testing kit for the journey back to the Undercity.  Apothecary Zinge waits for you and the sealed field testing kit there.", progress = "Welcome back.  At least, welcome back if you have returned with a sealed testing kit.  Otherwise, I will pretend not to notice your utter incompetence and spare my wrath from you until you do as you have been tasked and accomplish my task.", completion = "I will analyze this data immediately.  Perhaps Keever's insanity will prove to be my genius after all.\n\nAs for you...  you are useful to me, and I reward quite well those who remain useful.  Take this item, this coin, and most importantly my thanks along with them.\n\nCheck back with me from time to time - I wager that our working together on this project is not at an end.", rewards = "You will be able to choose one of these rewards:\n\nSkilled Handling GlovesMaster Apothecary CapeLoreskin Shoulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][865] = {title = "Raptor Horns", objective = "Gather 5 Intact Raptor Horns from Sunscale Scytheclaws, and bring them to Mebok Mizzyrix in Ratchet.", description = "The raptors of the Barrens are smarter than raptors in other lands.  And I think all that smarts is hiding in their horns!  If so, then I could grind their horns into powder and use it to make \"smart drinks.\"  I could sell them for a fortune!!!\n\nAnd you can help me.  Find me intact raptor horns from sunscale scytheclaws.  They roam in the southern Barrens, and in the northern Barrens near the border of Ashenvale Forest.", progress = "Did you get the horns, <name>?  Those things are going to make me a fortune!", completion = "Great, you got them!  Now I just need to ground them down and mix them with some wine, and...", rewards = "You will receive:\n\nRaptor PunchBarkeeper's Cloak"}
MultiLanguageQuestData['en'][866] = {title = "Root Samples", objective = "Bring 8 Root Samples to Mebok Mizzyrix in Ratchet.", description = "The herbs of the Barrens are not quite like herbs in other lands.  Their properties are mostly the same, but the oasis water here alters the plants; they are just slightly different.\n\nI want to study those differences... to see if they're exploitable!\n\nIf you are skilled in herbalism, then gather root samples off the herbs you find in the Barrens.  Bring back these samples so that I may compare them with herbs from other regions.", progress = "Hello, <name>.  Did you get those root samples?", completion = "Yes yes, these are very nice!  I will grow specimens from these roots and study them.  I hope to find new properties from them.  Hidden, valuable properties...!\n\nAnd don't worry -- if I do then you'll be the first to know.  Because I'll need someone to gather more!", rewards = "You will receive:\n\nSpore-covered Tunic"}
MultiLanguageQuestData['en'][867] = {title = "Harpy Raiders", objective = "Collect 8 Witchwing talons.\n\nReturn them to Darsok Swiftdagger at the Crossroads.", description = "The blasted harpies have been ravaging our caravan supplies for too long. It's time we slit a few of their throats and diminished their numbers.\n\nI've been snooping around their nests and figured out who leads who. The most devastating attack will destroy a good section of their lower chain of command and then we can work our way to the top.\n\nI'll start you off slow, take out Witchwing Harpies and Witchwing Roguefeathers in the Northwest and bring me 8 Witchwing talons. That should be a good start...", progress = "Cut up enough of them yet? Keep slicing and taking trophies. I want 8 Witchwing talons.", completion = "Oh, these are nice. Real nice... Good job, &lt;name&gt;. I look forward to seeing more of your work in the future.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][868] = {title = "Egg Hunt", objective = "Bring 12 Silithid Eggs and the Digging Claw to Korran at the Crossroads.", description = "Hey, <name>. I been sent to the Crossroads to watch over the land and take note of its happenings for my masters in Orgrimmar.\n\nOne object of my studies are the insect-like creatures found to the south in the Field of Giants. We know little of the creatures, so I be makin' it a point to discover more. They seem to have intelligence to them, more so than any normal animal.\n\nTake this digging claw and collect some of the creatures' eggs from their mounds, but be careful: if alerted, they will attack you.", progress = "Be careful with the eggs you find, <name>. If they break, they be no good to me.", completion = "You please me, &lt;name&gt;. The eggs and the tool. Well done.\n\nAnd for your reward...", rewards = "You will be able to choose one of these rewards:\n\nHarlequin RobesViolet Scale Armor\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][869] = {title = "Raptor Thieves", objective = "Bring 12 Raptor Heads to Gazrog at the Crossroads.", description = "Not long ago, a shipment of silver was stolen from our guard tower.  It was meant as payroll to the Crossroads' guards, and we want that silver back.\n\nThe strange thing is... we caught one of the thieves on the night of the theft.  And... it was a raptor!  Unbelievable!\n\nI don't know what raptors would want with silver.  But I don't care -- I want the raptors dead so they won't steal from us again!\n\nHunt raptors in the Barrens.  Collect for me their heads!", progress = "Do you have those heads, <name>?", completion = "You got rid of the raptors!\n\nThank you, &lt;name&gt;.  You are a &lt;class&gt; of worth.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][870] = {title = "The Forgotten Pools", objective = "Report back to Tonga Runetotem with your findings.", description = "Long ago, the Barrens was a lush place, teeming with life.  But war and cataclysm raged across the land, scorching it and leaving a dry husk.  Such is the way of things, and it saddens my heart.\n\nBut within the past few years, new oases have formed in the Barrens, and life stirs.  And deep down, we druids sense a power leaking its way to the surface.\n\nWe must find its source.  Travel to the Forgotten Pools, northwest of the Crossroads.  Search its waters for a source of power, then return here.", progress = "Have you been to the Forgotten Pools, <name>?  Did you find anything?", completion = "You found a fissure in the earth, with gases bubbling from it?  Strange.  This may be an answer to our questions, but we cannot yet be sure.\n\nBut it is a clue.  And I am grateful that you found it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][871] = {title = "Disrupt the Attacks", objective = "Of the Razormane tribe, kill 8 Water Seekers, 8 Thornweavers and 3 Hunters, and then return to Thork in the Crossroads.", description = "All the quilboars are our enemies, <name>. Some just prove to be more of a nuisance than others.\n\nThe Razormane tribe has been attacking our supply lines from Durotar, causing us no end of annoyance. I have scouts seeking the leader of these raids, but until then, any losses you can inflict on the filthy pig men would aid us.\n\nStart in the northeast towards Durotar. You can always tell their dens from the huge thorny vines that come up from the earth. Seek them out, and slay them.", progress = "The longer it takes to stop these attacks, the harder it will be to provide supplies for the people of the Crossroads.", completion = "You have done well, &lt;name&gt;. Those insolent quilboars will finally learn that the might of the Horde is not to be ignored.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][872] = {title = "The Disruption Ends", objective = "Kill 8 Razormane Geomancers, 8 Razormane Defenders, and Kreenig Snarlsnout.\n\nThen bring Kreenig Snarlsnout's Tusk to Thork at the Crossroads.", description = "One of my scouts witnessed an attack on a caravan from Durotar, <name>. The culprits are indeed the Razormane tribe of quilboars. One of the quilboars in particular is leading the raids: Kreenig Snarlsnout. He was seen northeast of here, just south of the road from Durotar. If the threat is to be ended, then Kreenig must die.\n\nTo be sure the attacks cease, though, I say we add insult to their injury. Kill Kreenig along with more of their tribe, and return to me when you have his tusk.", progress = "Cut off the head of their leader, and chaos ensues, <name>. Learn this lesson well. It will aid you in the future.\n\nThe boars will flounder without direction, and we will be able to take back the Barrens.", completion = "Well done, &lt;name&gt;. With Kreenig's death, there will be a definite decline in the attacks on our caravans.\n\nYour people should be proud to count you among them.", rewards = "You will be able to choose one of these rewards:\n\nBinding GirdleCinched Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][873] = {title = "Isha Awak", objective = "Bring the Heart of Isha Awak to Mahren Skyseer.", description = "The grand Isha Awak is lord of these waters.  Great is his strength, and solemn his pride.  The humans on the coast fear him, for he has consumed many of their number.\n\nBut I do not fear him.  I am grateful he is here.  He is a worthy challenge, and honorable prey.\n\nIf you are ready, then swim out and search for Isha Awak, the Deep Doom.\n\nHis spirit dwells in his heart, and to hear its beat is to know your fate.", progress = "Fear not the waters, <race>.", completion = "You now are one with Isha Awak, &lt;name&gt;.  His spirit is with you.  He lurks in your eyes...\n\nEyes that, one day, will learn to see.", rewards = "You will be able to choose one of these rewards:\n\nBranding RodWard of the Vale\n\nThe following spell will be cast on you:\n\nStrength of Isha Awak\n\nYou will also receive:\n\nBeastmaster's Girdle"}
MultiLanguageQuestData['en'][874] = {title = "Mahren Skyseer", objective = "Speak with Mahren Skyseer.", description = "You have hunted the beasts of the Barrens.  Your spirit is strong.  But a hunter must always be prepared.  A true hunter can stalk prey down any path.  Mountains and swamps will not sway <him/her>.\n\nNot even the sea.\n\nFind my sister, Mahren.  She hunts the great water beasts along the coast.  She will be your teacher in their ways.\n\nBut be wary in your search for her, for the Barrens' coast is held by humans.", progress = nil, completion = "My brother sent you, did he?  Then you must have proven yourself to him.  If you have earned the respect of Jorn, then you have my respect as well.\n\nAre you ready to tread farther down the hunter's path?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][875] = {title = "Harpy Lieutenants", objective = "Collect 6 Harpy Lieutenant Rings from Witchwing Slayers and return them to Darsok Swiftdagger at the Crossroads.", description = "Hahaha, <name>. Back for more? Good, I like to hear that.\n\nThis time I want you to assassinate some of the harpy lieutenants in the Dry Hills. Only Witchwing Slayers can be lieutenants, and you can tell them apart by the rings they carry. They are a nasty bunch, but they lead some of the underlings in that area. Taking out 6 of them will be a decisive strike against their matriarchy.\n\nMake sure they die painfully, <name>. We want those harpy wenches to know the idiocy of picking fights with the Horde.", progress = "Do you have 6 Harpy Lieutenant Rings yet? Justice must be dealt to them for their vicious attacks on the Horde.", completion = "Excellent work my friend. I think you'll go far within the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][876] = {title = "Serena Bloodfeather", objective = "Slay Serena Bloodfeather and return her head to Darsok Swiftdagger at the Crossroads.", description = "You did so well with the lieutenants and underlings that I'd like you to do one last thing for me.\n\nSerena Bloodfeather is the sister of a harpy named Bloodfeather who was slain by Rexxar quite a while ago. Apparently, these attacks on the Horde caravans are revenge for her sister's death.\n\nI need you to slit her throat and bring me back her head. I want to place it on the next caravan we send out... Give those harpies something to think about.", progress = "You're not getting anything until I see Serena's head.", completion = "HA! Well done, &lt;name&gt;! Very well done... I wasn't sure you were up to the task, but you've proved yourself quite the cut-throat. Thank you again for helping us suppress the Harpy epidemic. Here is your reward, use it well.", rewards = "You will be able to choose one of these rewards:\n\nElegant ShortswordHarpy SkinnerZhovur Axe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][877] = {title = "The Stagnant Oasis", objective = "Return to Tonga at The Crossroads, after investigating the Stagnant Oasis.", description = "Like the one you found at the Forgotten Pools, there may be fissures at the other oases in the Barrens.  If so, then perhaps the fissures are the oases' source of life.\n\nWe must test this.\n\nHere, take these seeds.  They are dead and infertile, but take them to the Stagnant Oasis to the southeast.  If there is a fissure there, then place the seeds within it...and observe.", progress = "Have you been to the Stagnant Oasis?  Was there a fissure beneath its waters?", completion = "Your findings are amazing!  The seeds I gave you were dried, and dead.  Whatever rests under these oases can create life from nothing!\n\nWe must study this more...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][878] = {title = "Tribes at War", objective = "Kill 6 Bristleback Water Seekers, 12 Bristleback Thornweavers and 12 Bristleback Geomancers and return to Mangletooth at Camp Taurajo in the Barrens.", description = "You must strike my enemies. <snort> You must help Mangletooth and the Razormane by weakening the Bristlebacks. Both tribes are very spiritual--tied to the earth and its power. <snort> It gives us strength in all things... especially war.\n\nIf you want to find out who really causes Thork <snort> and the Horde such anguish, then help Mangletooth! You attack the spiritual leaders of the Bristlebacks to the north; weaken them so the Razormanes can defeat them and rule the Barrens.", progress = "More information <snort> for the Horde when you've killed the Bristleback's wise ones, <race>.  Not a moment earlier! Mangletooth is no fool.", completion = "Yes, yes... filled with joy because finally &lt;snort&gt; the Bristleback know my tribe's pain, &lt;race&gt;. That is how I should feel, but that  is not the case.\n\nYou aid your people and they honor you. Mangletooth aids his people, and what do they do? They turn their backs on him. They forget him and leave him to rot in cage!\n\nI aid them even from locked behind bars and they send no one to save me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][879] = {title = "Betrayal from Within", objective = "Kill Nak, Kuz, and Lok Orcbane and bring their skulls to Mangletooth at Camp Taurajo in the Barrens.", description = "Three of my tribe came out of the Kraul to lead the raids against the Horde, <race>. <snort> They are ruthless and cunning, and if you defeat them, then your Crossroads and even most of the Barrens will learn peace... <snort> at least from the Razormane tribe. <snort>\n\nNak, Kuz, and Lok Orcbane are the ones you seek. They are far to the south  of the Barrens. One is a spell caster, another a tracker, and their leader, the one called Orcbane, <snort> a warrior. Kill them, <race>, like they have killed me.", progress = "How goes your hunt, <race>? \n\nThork thinks he knows the truth about who leads the raids against his people,  but he shall learn how wrong he is if you are successful.\n\nMy death is inescapable, but you have caused great pain to my enemies, so Mangletooth regrets nothing.", completion = "It is done then. Better it ends this way, says Mangletooth. &lt;snort&gt; They should have &lt;snort&gt; made sure I was dead when they turned their backs on me instead of leaving &lt;snort&gt; me here in this forsaken cage.\n\nThere is but one task left for you to finish, &lt;race&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][880] = {title = "Altered Beings", objective = "Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads.", description = "Your findings are incredible, <name>.  These oases hold properties that must come from an outside source.  Or perhaps an inside one.\n\nI want to know how these fissures are affecting the beasts who drink from the oases' water.\n\nHunt oasis snapjaws at the Lushwater and Stagnant Oases.  Bring me their shells so I may examine them.", progress = "How goes your collection?  Did you get the shells?", completion = "Thank you, &lt;name&gt;.  Studying the beasts of an area can tell much about the area itself.  We shall see what tale these shells tell.\n\nPlease accept my gratitude for your aid ... and perhaps you can use these coins.  I find that I do not need them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][881] = {title = "Echeyakee", objective = "Bring Echeyakee's Hide to Sergra Darkthorn at the Crossroads.", description = "Whitemist, Echeyakee in the Tauren tongue, is the king of the savannah cats.  He hunts with such stealth, they say he's like a thin, white mist on the earth.  And he kills so fast his prey have no time for fear, or pain.\n\nThe Tauren say he is both mercy and death.\n\nYou will learn if that's true, for I now set you on the path to hunt Echeyakee.  His lair is northeast of the Crossroads, among the bones of giant Kodo\n\nGo.  Blow this horn when you reach his lair.  Blow the horn, and he will come.", progress = "The great cat calls to you, <name>.", completion = "You've beaten Echeyakee, and though his days of hunting are over... his spirit is with you.  He will show you the strength found in subtlety, and the honor in mercy.\n\nYour path is still long, &lt;class&gt;.  Let's hope you stride it well.", rewards = "The following spell will be cast on you:\n\nEcheyakee's Grace\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][882] = {title = "Ishamuhale", objective = "Bring Ishamuhale's Fang to Jorn at Camp Taurajo.", description = "Ishamuhale, Speartooth, is the fiercest sunscale raptor of the Barrens.  He does not hunt for sport, nor for food.  He hunts because hunting is his passion.  He kills because it is his nature to kill.\n\nAnd you will learn of his nature, <name>, for your path now follows the taloned tracks of Ishamuhale.\n\nBegin the hunt.  Slay his favorite prey, a zhevra, then bring its carcass to the dead tree northwest of Ratchet.  Ishamuhale will smell the carcass and be drawn to it.\n\nBe ready when he comes.", progress = "<name>, have you bested Ishamuhale?", completion = "This fang is merely a token, but what it represents is profound.\n\nIshamuhale's strength is in you, &lt;name&gt;.  May you use it with temperance.  That is your burden.\n\nThat is your honor.", rewards = "The following spell will be cast on you:\n\nIshamuhale's Rage\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][883] = {title = "Lakota'mani", objective = "Bring the Hoof of Lakota'mani to Jorn at Camp Taurajo.", description = "The Hoof of Lakota'mani is a symbol of the strength of the great kodo.", progress = "<name>, when you approached I saw a new power in your stride.  Tell me -- has your spirit met with the great Lakota'mani?", completion = "Lakota'mani is called \"Earthshaker\" in our language, and his steps are like gathered thunder.  He is with you now, and his courage mingles with yours.  Together there is no conflict you cannot face.\n\nWalk tall, &lt;name&gt;.  Walk tall, Earthshaker.", rewards = "The following spell will be cast on you:\n\nLakota'mani's Thunder\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][884] = {title = "Owatanka", objective = "Bring Owatanka's Tailspike to Jorn at Camp Taurajo.", description = "When touched, sparks fly from the tailspike of Owatanka.", progress = "<name>, there is a new power behind your eyes!  You have met with the mighty Owatanka, have you not?", completion = "The thunder lizard Owatanka is called \"Bluebolt\" by the tauren, for within him resides a speed that belies his size.  It is said that lightning struck Bluebolt long ago and, fed from the sky's rage, the great beast's energy is without limit.\n\nMay his energy flow through you, &lt;name&gt;.  For you now keep pace with Owatanka.", rewards = "The following spell will be cast on you:\n\nSpeed of Owatanka\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][885] = {title = "Washte Pawne", objective = "Bring Washte Pawne's Feather to Jorn Skyseer at Camp Taurajo.", description = "The feather of Washte Pawne is painful to the touch.", progress = "There is new resolve within you, <name>.  A resolve born from pain...\n\nAre you burdened with the death of Washte Pawne?", completion = "The thunderhawk is a rare beast of the Barrens, and its death can portend great fortune, or great doom.\n\nBut Washte Pawne, called \"Spirit Biter\" in Taurahe, can bring neither... or both.\n\nThe pain you felt from hunting Spirit Biter is the pang all feel who make great gains at great costs.  The sting you felt is the pain of regret.\n\nBut I can see you have conquered this.  You have learned that regret turns to wisdom, and that through pain one gains strength.\n\nYou have learned much, &lt;name&gt;.", rewards = "The following spell will be cast on you:\n\nWashte Pawne's Resolve\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][886] = {title = "The Barrens Oases", objective = "Speak with Tonga Runetotem at the Crossroads.", description = "The druids of Thunder Bluff sense a strange power leaking into the Barrens, east of Mulgore.\n\nTonga Runetotem was sent to discover the source of this power, but we fear he will need aid.\n\nTravel to the Barrens and speak with Tonga.  He will be at the Crossroads.  To reach there, take the road east out of Bloodhoof village.  Enter the Barrens, then turn north when the road forks.  Continue north and  you will find the Crossroads.\n\nAnd do not leave the road, <name>, for the Barrens is a harsh land.", progress = nil, completion = "My brethren in Thunder Bluff were wise to send you, young &lt;class&gt;.  For the mystery of the Barrens is one that I alone cannot unravel.\n\nWith your aid, let us hope we can find answers to our questions.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][887] = {title = "Southsea Freebooters", objective = "Kill 12 Southsea Brigands and 6 Southsea Cannoneers for Gazlowe in Ratchet.", description = "I sure wish Vice Admiral Grezzlik did a better job of keeping the seas safe for our trading vessels. With all the gold the trade princes have poured into the Trade Fleets, it ticks me off to see so many pirates running willy-nilly, raiding my ships and stealing my goods!\n\nI heard that the Southsea Freebooters have set up a camp just south of here. They've been a real thorn in my side and if Grezzlik won't take care of them, well, maybe you can help me get rid of them.", progress = "I don't even want to think about the profits I've lost from pirate raiding, and now they set up camp on my doorstep? It's getting out of hand, Undermine's got to do something about it.", completion = "You did good, kid. A little more work like that, and it'll be one less thing I'll have to worry about. Hopefully they'll be convinced that they should relocate their operation elsewhere.\n\nIn the meantime, there is the small matter of getting back the goods they stole from me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][888] = {title = "Stolen Booty", objective = "Retrieve the Shipment of Boots and Telescopic Lens for Gazlowe in Ratchet.", description = "While I'd like to recover all my goods, I'm sure that's not possible. Still, there's a few things that I absolutely must have!\n\nAs you see, my observatory is ready to go, but it needs the smaller of the two lenses. The first arrived by caravan from Durotar, but the second was bound by ship, and never arrived. Also, I never got my boot shipment from Drizzlik in Booty Bay!\n\nHead down to the pirate camp and see if you can find them.", progress = "Did you find my things, <name>?", completion = "It's a relief to get all this stuff back, so thanks for your help, &lt;name&gt;. You know, I could use a &lt;race&gt; like you to help out with my operation here. If you're ever looking for work, don't forget about how well Gazlowe pays for service!", rewards = "You will be able to choose one of these rewards:\n\nWayfaring GlovesPadded Lamellar Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][889] = {title = "Spirit of the Wind", objective = "Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.\n\nIt will not last long, but it should be enough to help you travel throughout the Barrens.", description = nil, progress = "Bring Mangletooth 10 blood shards and I will bless you with great speed. You will run with zhevra and the wind will be jealous of you.\n\nIt will not last long, but it should be enough to help you travel throughout the Barrens.", completion = "Good. Go with Agamaggan's spirit as your guide, &lt;race&gt;. Return to me if you desire more of Agamaggan's magics.", rewards = "You will learn:\n\nSpirit of the Wind"}
MultiLanguageQuestData['en'][890] = {title = "The Missing Shipment", objective = "Bring Gazlowe's Ledger to Wharfmaster Dizzywig.", description = "I've been waiting forever for my last shipment of goods from Booty Bay! I'm pretty sure that it must have been stolen by the Freebooters, but just to make sure, will you go down to the dockside and ask Dizzywig if my goods were already put into my warehouse without my knowledge?\n\nHere, take my ledger down to Dizzywig and have him double check my inventory records against his logs.", progress = "Wares to send on the next ship, <name>?", completion = "Ah, Gazlowe sent you, did he? Just a moment, let me take a look here and check my own logs and make sure I didn't have Gazlowe's shipment sent to the wrong place.\n\nBet he's waiting for those boots from Drizzlek...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][891] = {title = "The Guns of Northwatch", objective = "Captain Thalo'thas Brightsun of Ratchet wants you to collect 10 Theramore Medals and slay Captain Fairmount, Cannoneer Whessan and Cannoneer Smythe.", description = "Yet another ship from my fleet has been lost to those overzealous humans at Northwatch Hold!\n\nThose bastards must be dealt with. Their paranoia has them in a state of frenzy. Trigger happy, reckless louts are shooting at anything in their sights.\n\nTravel south along the Merchant Coast to the Hold and lay siege to their forces. Bring me the medals of their soldiers as proof. And for the love of my fleet, slay Captain Fairmount and her overzealous cannoneers!", progress = "My fleet is in peril with Captain Fairmount and her damned cannoneers blasting away from Northwatch Hold. I want her soldiers to pay as well. Fill my hand with medals from their dead and I will know that vengeance has been given to my fallen privateers.", completion = "Alas, the righteous Alliance guns have been silenced. You shall be rewarded for your aid, &lt;name&gt;.\n\nNow to tend to the grim task of recovering the bodies of the dead....", rewards = "You will be able to choose one of these rewards:\n\nPrivateer MusketSea Dog Britches\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][892] = {title = "The Missing Shipment", objective = "Return Gazlowe's Ledger to Gazlowe in Ratchet.", description = "Everything looks square from my records, <name>. Go on back and tell Gazlowe he's out of luck. I wouldn't be surprised if it was the pirates that nabbed his goodies.\n\nNothing else I can do for him. Oh... though you could tell him that I've got some things from Undermine for him, when he has the time to come pick them up.", progress = "So, what did Dizzywig have to say?", completion = "No dice, eh? I guess it must have been the Freebooters then... Dizzywig's on the level, I'm sure he wouldn't cheat me like that. After all, he is on the payroll.\n\nLooks like I've got some goods to get back, &lt;name&gt;. What do you say?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][893] = {title = "Weapons of Choice", objective = "Bring a Razormane Backstabber, a Charred Razormane Wand and a Razormane War Shield to Tatternack Steelforge at Camp Taurajo in the Barrens.", description = "The Razormane quilboars to the south, beyond the Field of Giants, have no skilled blacksmiths from what I am told, but they've apparently started to develop sturdier weapons. I'd like to get my hands on a few different types to learn their techniques if possible.\n\nIf you wish to help bring honor to the Horde, then bring me examples of their weapons. Find me a dagger from their stalkers, a wand from their seers, and a shield from their warfrenzy. That should do nicely!", progress = "I, too, have doubts that the pathetic quilboars could attain any level of skill in the area of smithing, but I do as the Warchief commands, and I shall learn what I can about the Razormane tribe.\n\nI have had more menial tasks, and I do so willingly if it aids the orc people.", completion = "Excellent, excellent specimens indeed.\n\nThe quilboar are further along than I had expected.\n\nHere, &lt;class&gt;, take this and get out of my way. I'd better take a closer look at these weapons. We may have underestimated our enemy, and that's the kind of mistake we can't afford to make.", rewards = "You will be able to choose one of these rewards:\n\nDemolition HammerEverglow Lantern\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][894] = {title = "Samophlange", objective = "Access the control console at the Venture Company research site.\n\nProvided item: \n", description = "The Venture Company set up a small research facility far to the north of here, southwest of the Sludge Fen. I don't know very much about what they're doing, but did manage to discover that they're experimenting with something called a \"samophlange\".\n\nNow what the heck is a samophlange? Well, whatever it is, I want to examine it, so I need someone to go get it.\n\nI obtained a copy of their control system operating manual, you should be able to figure out how to disengage the samophlange from it.", progress = nil, completion = "A variety of buttons, levers and blinking lights are somewhat erratically arrayed on the face of the control console. A small gauge indicates that the apparatus is currently operating within optimal levels, and indicates that control valves one through three are currently open. There is a small keyhole set into the lower right side of the control panel.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][895] = {title = "WANTED: Baron Longshore", objective = "Bring the head of Baron Longshore to Gazlowe in Ratchet.", description = "WANTED!\n\nBaron Longshore, Captain of the Heedless\n\nCaptain Longshore of Gilneas leads vessels of the Southsea Freebooters, and is WANTED on charges of piracy. Remains must be in identifiable condition!\n\n-- Gazlowe", progress = "What's happening? Something I can help you with? Goods to ship, perhaps an engineering job?", completion = "Ahhhh! That sort of business. You know, I saw the Heedless once on the open seas. Fearsome ship, or was that boat... those sailors are so particular!\n\nAnyways, watching her glide across the water was quite a sight to see. I'm glad her infamous captain will trouble my ships no longer.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][896] = {title = "Miner's Fortune", objective = "Retrieve the Cats Eye Emerald from one of the Venture Co. Overseers or Enforcers for Wharfmaster Dizzywig at Ratchet.", description = "Being Wharfmaster of a busy port like Ratchet, I keep my finger on the pulse of information. I know all about the exchange of goods and money between here and Booty Bay.\n\nThe latest bit of news I've heard is about the Venture Company's Boulder Lode mine northeast of the Sludge Fen. One of the miners discovered an emerald the size of your fist. I know a few buyers who'd be interested in getting their hands on something like that, and I'd be willing to go half and half on its sale.", progress = "If only we knew which one of the miners had found the emerald, it'd be a walk in the park...", completion = "Look at the size of that thing, &lt;name&gt;! We're going to be rich! Let's see, according to the rates I've seen on gems going into Undermine, I should be able to figure out your cut--fifty percent, don't worry!\n\nNow let's see... I think this should do about right. Pleasure doing business with you, &lt;name&gt;.", rewards = "You will receive:\n\nA Sack of Coins"}
MultiLanguageQuestData['en'][897] = {title = "The Harvester", objective = "Bring the Harvester's Head to Jorn Skyseer.", description = "This strange, insect-like creature looks outside of the natural order, as though it does not belong in the Barrens.", progress = "You seemed troubled, <name>.  How go your lessons in the Barrens?  Did you find something that disturbs you?", completion = "I can tell nothing of the nature of this beast, for its spirit has fled.  But as you guessed, it does not belong in the Barrens.  I fear it may herald a grim future for our people...\n\nBut for now, prepare yourself, and let us hope that time unravels the mystery of this creature.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][898] = {title = "Free From the Hold", objective = "Safely escort Gilthares Firebough back to Captain Brightsun in Ratchet.", description = "Finally! Someone to rescue me!\n\nI can't believe you got past the guards. These zealots from Theramore are out of their minds. They sank our ship and imprisoned me, the only survivor. I was called an enemy and threat to the Alliance.\n\nMe! A threat to their great sham of an Alliance? I was a deckhand on a moonshine transport between Ratchet and Booty Bay.\n\nEnough talk. Help me get back to Ratchet will you? Let me know when you're ready and we'll make our break.", progress = "Yes?", completion = "And to think, we thought Firebough was long dead!\n\nYour heroics have earned you a place of honor with the Thalo'dan Privateers, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nBuckled BootsRiveted Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][899] = {title = "Consumed by Hatred", objective = "Bring 60 Bristleback Quilboar Tusks to Mankrik at the Crossroads.", description = "Perhaps you know the pain of uncertainty, perhaps not, <class>. But know this: I stand here every day, from the sun's rising till its decline, scouring the horizon for more of those monsters. I've killed every pig man I've come across since, but my thirst for their blood is far from quenched. Perhaps instead of heading north to the Crossroads I should have headed to Taurajo.\n\nYou, <class>--you  could help me.\n\nKill them. Kill as many as you can. Bring me their tusks, and we will celebrate their deaths together.", progress = "The quilboar will pay for this, <name>. I swear it.", completion = "&lt;class&gt;, you take my task seriously, and for that I thank you.\n\nAlthough my desire for revenge remains, I can at least smile seeing that the quilboars have felt pain themselves.", rewards = "You will be able to choose one of these rewards:\n\nBoar Hunter's CapeGrassland Sash\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][900] = {title = "Samophlange", objective = "Close off the Fuel Control Valve, the Regulator Valve and the Main Control Valve then use the control console again.", description = "The three control valves are currently opened. The various readings on the control panel lead you to presume that they must be shut off before the apparatus can be shut off.", progress = "Blinking lights on the control console indicate that the main control valves have not been closed off.", completion = "The lights indicating the three control valves dim as they are shut off. Green lights slowly fade into yellow, and the switch controlling the apparatus is now moveable, with the valves closed, it can be turned off.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][901] = {title = "Samophlange", objective = "Get the Console Key from Tinkerer Sniggles to use on the control console.", description = "With the apparatus deactivated, the control panel can be opened up and the samophlange removed from the console. With everything else in place, all that is left is to acquire the key to unlock the console.", progress = "The console lights are dimmed and the gauges and dials all read at their zero positions, everything idling.", completion = "Turning the key in the lock, the control console unlocks. A red light at the top of the console turns off and all power drains from the terminal.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][902] = {title = "Samophlange", objective = "Return the Samophlange to Sputtervalve in Ratchet.", description = "Pulling open the face of the control console reveals a dense jumble of wires, tubing and other strange mechanical objects--most of which seem to serve no practical purpose. Pushing them aside and digging deeper into the console, you find the samophlange. A tug removes it from its housing.", progress = "Oh, you're back, <name>! Do you have the samophlange?", completion = "This is... er... interesting... yes. I'll have it sent along to the Tinkers' Union headquarters in Undermine. I'm sure after some careful dissection and research, they'll be able to make some sense of it.\n\nBut, perhaps I'll have a little look myself first...", rewards = "You will be able to choose one of these rewards:\n\nEngineer's HammerWelding Shield\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][903] = {title = "Prowlers of the Barrens", objective = "Collect 7 Prowler Claws from Savannah Prowlers for Sergra Darkthorn in the Crossroads.", description = "Now it's time to go after something that really bites.  The prowlers of the Barrens are a tough breed.  Tough, resourceful, sly... and deadly.  You'll find them among the tall grasses.  You'll find many to the southwest of the Crossroads.\n\nBe wary as you hunt them, <name>, or you may find yourself no longer the predator, but instead the prey.", progress = "How goes your hunt, <name>?  Have you found the prowlers?", completion = "Ah, I see you've been busy, lurking in the grasses and hunting prowlers.  Do you think, then, it is time to face a champion among them?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][905] = {title = "The Angry Scytheclaws", objective = "Kill Sunscale raptors and collect their feathers. Use the feathers on the 3 Scytheclaw nests. Return to Sergra Darkthorn in the Crossroads.", description = "Now, <name>, the hunt deepens.  Now you must defeat your prey, and then find your way to its lair.\n\nHunt the sunscale raptors to the south.  Slay them and remove the feathers they wear.  Place the feathers on the scytheclaw nests southwest of the Stagnant Oasis. Show their brethren you do not fear them!", progress = "Have you been to the nests, <name>?", completion = "So you've been to the nests and placed the feathers of your prey within them.  That took a fair portion of courage, no doubt about it.\n\nDo you feel a little tougher, &lt;name&gt;?  Because you look tougher now then when you first came here.  I guess the Barrens is doing its job.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][906] = {title = "Betrayal from Within", objective = "Bring Lok's Skull to Thork at the Crossroads in the Barrens.", description = "Take Lok's head to Thork in the Crossroads, <race>. <snort> He should know what has happened to my tribe without any words--ha, not that he would believe Mangletooth helped in <snort> such things. But I am sure he'll reward you for carrying out such a great deed. <snort>\n\nI will continue to bless you with Agamaggan's power for as long as I remain in this cage, <race>. Until then, farewell.", progress = "Yes, what is it?", completion = "You found the Razormane leader and killed him yourself, &lt;name&gt;? Amazing.\n\nI am without words, but that does not mean I am without thanks. The people of the Crossroads would do well to respect your strength.\n\nI must admit, I thought the leader of these raids on our supply lines was another quilboar. Thank you again, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nBarkshell TunicDry Moss Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][907] = {title = "Enraged Thunder Lizards", objective = "Bring 3 Thunder Lizard Blood to Jorn Skyseer at Camp Taurajo.", description = "Now, <name>, you must face the great thunder lizards.  So large are the beasts, the ground rumbles as they stomp across the plains.  Take care as you fight them, for one false step and you may find yourself beneath their feet.\n\nYou will find the thunder lizards in the southern Barrens.  They are known as Stormsnouts, Stormhides and Thunderheads.  Return to me after you have bested them.", progress = "Are the thunder lizards defeated, <name>?", completion = "It is good to see you return with proof of victory.  And it is good to know you have done so with your bones unbroken.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][908] = {title = "Amongst the Ruins", objective = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n<name>, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][909] = {title = "Baron Aquanis", objective = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nOutlaw SabreWitch's Finger\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][910] = {title = "Down at the Docks", objective = "Take your ward to the docks of Ratchet in the Barrens.", description = "I have heard tales of the mighty ships that sail between Ratchet and Booty Bay!  That would be so cool to sail on the ocean and fight in many great sea battles.  Maybe I will be a mighty Horde sailor when I grow up!  Yeah!\n\nWould you take me to see the Ratchet docks, please?  I promise I won't get into the water or cause any trouble - I just want to see the big boats and smell the salty sea water!  Yeah!", progress = "Are we there yet?", completion = "Wow, the ocean is HUGE!  There were a lot of seagulls and stuff too - It's just as noisy and as bustling as I thought it would be.  There are pirates near by too - so cool!\n\nThank you for taking me to Ratchet, &lt;name&gt;.  That was so awesome!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][911] = {title = "Gateway to the Frontier", objective = "Take your ward to the Mor'shan Rampart in the northern part of the Barrens, just before entering Ashenvale.", description = "They say that Ashenvale is the new frontier, and that the Mor'shan Rampart in the Barrens is the gateway to it.  That would be so cool to be a pioneer, carving everything you need out of the untamed wilds!  They say that this is where the Horde and Alliance will clash the most in the future, and I want to be there <name>!\n\nWould you take me to the Mor'shan Rampart so I can see what the frontier looks like, please?  I wanna see where the Horde is driving out those smelly night elves!", progress = "Are we there yet?", completion = "Wow, Ashenvale is where real adventure happens!  Have you ever fought in Ashenvale, &lt;name&gt;?  When I become a hero when I grow up, I wanna come to Ashenvale and fight for the glory Horde!\n\nThank you for taking me to the frontier, &lt;name&gt;.  You're the best!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][912] = {title = "Stonesplinter Trogg Disguise", objective = "You will receive:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nKnowledge: Stonesplinter Disguise"}
MultiLanguageQuestData['en'][913] = {title = "Cry of the Thunderhawk", objective = "Find and slay a Thunderhawk, return its wings to Jorn Skyseer at Camp Taurajo.", description = "The thunderhawk, <name>, is a fierce beast.  It is time for you to face them.  You must find where it roams, and bring me its wings as proof of your successful hunt.\n\nDo this, and your time with me will near its end.", progress = "Is it done? Have you slain the thunderhawk?", completion = "You, like the thunderhawk, should be proud.  You have bested every foe we set you before, and have done so with strength, courage and honor.\n\nBut your path, &lt;name&gt;, continues.  In fact, you will find that true hunters forever strive, forever walk their path with the same pride you have shown me.\n\nNow, it is time to move on.", rewards = "You will be able to choose one of these rewards:\n\nCobalt BucklerWind Rider Staff\n\nYou will also receive:\n\nGloves of the Moon"}
MultiLanguageQuestData['en'][914] = {title = "Leaders of the Fang", objective = "Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane in Thunder Bluff.", description = "The druids in the Wailing Caverns, the Druids of the Fang, are an aberration.  They were part of an order of noble druids whose plan was to heal the Barrens, but now seek to remake that land to match their own, twisted dreams.\n\nThe Druids of the Fang have four leaders, and each possesses a dream gem.  Even now their faces haunt me!  Defeat the leaders and bring me their gems, and the Barrens may again know peace.\n\nGo, <name>.  You will find them lurking deep within the Wailing Caverns.", progress = "Memories of my nightmares haunt me, <name>.  Have you defeated the leaders of the fang and acquired their gems?", completion = "You have done it, &lt;name&gt;.  You killed the leaders of the Druids of the Fang.  My dreams are now free of their wicked faces, and you have helped save the Barrens from a cursed future.\n\nI thank you, &lt;name&gt;.  I thank you for myself, for the druids of Thunder Bluff, and for the land.", rewards = "You will be able to choose one of these rewards:\n\nCrescent StaffWingblade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][915] = {title = "You Scream, I Scream...", objective = "Get some Strawberry Ice Cream for your ward. The lad seems to prefer Tigule's brand ice cream.", description = "ICE CREAM!  Oh please please please could you get me some ice cream?!  Strawberry is my favorite flavor, and there's no better strawberry ice cream in the world than Tigule's Strawberry Ice Cream!  It's my favorite ice cream in the whole wide world!\n\nI had it once a long time ago when I was at the Shimmering Flats race track, but I heard that they might be selling them in town now!  Please?  Pretty please?  With Tigule's Strawberry Ice Cream on top??!?!", progress = "I wish they'd make more flavors of ice cream other than strawberry, but I guess I'm lucky that strawberry is my favorite!", completion = "Mmmmmmmmm!  I love their strawberry ice cream!  If there's one thing Tigule and Foror know to do, it's make ice cream!\n\nThank you very much &lt;name&gt; - this is the best treat ever!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][916] = {title = "Webwood Venom", objective = "Bring 10 Webwood Venom Sacs to Gilshalan Windwalker at Aldrassil.", description = "I came to Shadowglen to observe the webwood spiders that dwell in the Shadowthread Cave.  They are cousin to a much smaller variety of spider; I believe the world tree has had a profound effect on them, and I would like specimens to study to confirm this.\n\nFirst, I would like some of their venom.  Gather Webwood venom sacs from the spiders in and around the Shadowthread Cave, to the north.  I can then examine them for similarities with their smaller cousin's venom.", progress = "Did you gather the venom sacs, <name>?", completion = "Thank you, &lt;name&gt;.  When I return to Darnassus I will compare the venom within these sacs with the venom of other spiders.  It is my belief that it will have properties linked to the recent growth of our new world tree.", rewards = "You will be able to choose one of these rewards:\n\nThistlewood MaulThistlewood DaggerThistlewood StaffThistlewood Blade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][917] = {title = "Webwood Egg", objective = "Bring a Webwood Egg to Gilshalan in Aldrassil.", description = "Now that I have the spiders' venom, I'd like some live specimens to study.  Unfortunately, capturing a living, giant spider is more than I can ask of you, young <class>.  And a giant spider is more than I could handle myself!\n\nBut if you can find an unhatched egg, then delivering specimens will be much easier, and I can then arrange for the unhatched spiders to be contained.\n\nThere must be a nest deep in the Shadowthread Cave.  Please, search for an egg in the nest and return it to me.", progress = "Have you been inside the Shadowthread Cave, <name>?  Did you find a spider egg?", completion = "Ah, very good.  I will have this egg and the venom transported to Darnassus, then return there when my studies are done here.  I expect to find out a great deal from these specimens, &lt;name&gt;.  You have been a great help to me.", rewards = "You will be able to choose one of these rewards:\n\nWoodland ShieldWoodland TunicWoodland Robes\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][918] = {title = "Timberling Seeds", objective = "Bring 8 Timberling Seeds to Denelan at Lake Al'Ameth.", description = "The timberlings of Teldrassil are elementals of nature.  In some ways they reflect the natural order of plants and animals on our great tree.\n\nSo it is disturbing to see how angry the timberlings have become.\n\nI believe it has something to do with the soil.  I have been working on different methods of nurturing plants and would like to try them on timberling seeds.  Please, can you gather seeds from timberlings around Lake Al'Ameth and bring them to me?", progress = "Do you have the seeds?  I am eager to plant them.", completion = "You got them.  This is good!\n\nI will plant these seeds in special soil I have prepared.  I believe the seeds will sprout into timberlings who are much more docile.  Perhaps later you can see the results!", rewards = "You will receive:\n\nForest Mushroom Cap"}
MultiLanguageQuestData['en'][919] = {title = "Timberling Sprouts", objective = "Bring 12 Timberling Sprouts to Denalan at Lake Al'Ameth.", description = "Small timberlings are sprouting around the waters of Lake Al'Ameth.  I'm afraid these sprouts are beyond help -- we should try to clear them from the land before they grow large enough to cause trouble.\n\nWhen you're wandering the lake, if you see any timberling sprouts please take them.  Help keep our land clean!", progress = "Hello, <name>.  Have you found any sprouts near the waters?", completion = "That's a lot!  I'm afraid they're spreading at a dangerous rate.  I hope I can solve the riddle of what is tainting them.\n\nThank you for your help, &lt;name&gt;.  The land is a cleaner place from your efforts.", rewards = "You will be able to choose one of these rewards:\n\nGardening GlovesGraystone Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][920] = {title = "Tenaron's Summons", objective = "Speak with Tenaron Stormgrip atop Aldrassil in Shadowglen.", description = "<name>, is it? I heard that Tenaron has been asking for you. You'll find him in the highest room atop Aldrassil.\n\nWe may live long lives, but it's best you not keep him waiting too long.", progress = nil, completion = "Ah, &lt;name&gt;. I was hoping you'd be prompt in answering my summons. I have an important task that I would like you to perform.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][921] = {title = "Crown of the Earth", objective = "Fill the Crystal Phial and bring it back to Tenaron Stormgrip atop Aldrassil.", description = "It is time for you to set out to seek your destiny, <name>. But before you are ready to set out into the world beyond our enchanted forests, there is much you must learn about our recent history.\n\nMuch has changed with our people since the Battle of Mount Hyjal. Nordrassil lies a pale shadow of what it once was, its power used to defeat Archimonde and drive back the Burning Legion...\n\nThere is a task you must perform. Go to the moonwell north of Aldrassil and return me a phial of its water.", progress = "The moonwells hold the waters of the Well of Eternity, the ancient source of magic that has wrought so many horrors upon our world.\n\nThe druids take advantage of its properties, and the Sentinels revere the wells as shrines to Elune, but sorcery is forbidden to all.", completion = "So you have heard the first part of the aftermath of the Battle of Mount Hyjal. There is much more to be told and the task you have begun here will continue through the rest of your journey through Teldrassil and into Darnassus.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][922] = {title = "Rellian Greenspyre", objective = "Bring a Timberling Seed to Rellian Greenspyre in Darnassus.", description = "<name>, can you take one of the seeds you brought me to my friend, Rellian Greenspyre?  He is a druid in Darnassus, and when last we spoke he revealed his interest in my work with the Timberlings.  He had some ideas himself, and he will appreciate a specimen seed to work with.\n\nThank you, <name>.  You have been a great help to me.  I hope that, some day, you will see the fruit of my labors.\n\nYou will usually find Rellian walking the pathways of the Cenarian Enclave in Darnassus.", progress = "Hello...\n\nAnd how may I help you?", completion = "Ah, a timberling seed?  I wanted to try growing one of these to help Denalan with his studies.\n\nBut I'm afraid I've discovered that a corruption has grown in many of the timberlings, and seeds from such creatures carry their parent's taint.  They are beyond my talents to repair.\n\nDenalan is very skilled with things that grow.  He may find a cure for future timberlings.  He may be their only hope.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][923] = {title = "Tumors", objective = "Bring 5 Mossy Tumors to Rellian Greenspyre in Darnassus.", description = "There is a malevolence growing in the timberlings.  We are trying to find the source, but until we do...in order to keep Teldrassil safe we must cut down the timberlings who are beyond help.  Those that wander Wellspring Lake in northern Teldrassil are the most tainted.  They must be removed!\n\nDestroy the Timberlings you find there, and gather the mossy tumors growing upon them.  Bring the tumors to me so that they may be burned.", progress = "Have you been to Wellspring Lake, <name>?  Have you been hunting the timberlings there?", completion = "Well done!  These tumors are the symptom of the timberling's disease.  They are filled with a poison that we must cleanse from our new land.\n\nI will dispose of these tumors.  Thank you, &lt;name&gt;.", rewards = "You will receive:\n\nPruning Knife"}
MultiLanguageQuestData['en'][924] = {title = "The Demon Seed", objective = "Grab a Flawed Power Stone. Bring it to the Altar of Fire before the stone expires, then return to Ak'Zeloth.", description = "The Demon Seed is a powerful tool for the Burning Legion. It rests in a cave on Dreadmist Peak, above a demonic altar of fire.\n\nI have prepared power stones that when placed near the Seed will disrupt its connection to the Legion.\n\nTake a stone from the table and bring it to the altar of fire atop Dreadmist Peak. Travel west, then north when the road forks. The Peak will be to your left. The safest climb to the top is on its northern face.\n\nAnd hurry--the stone's power will consume itself in time.", progress = "The Demon Seed still exists.  I can sense its power...", completion = "Your task is complete.  You have destroyed the Demon Seed as Neeru bid.  But this is not the end...\n\nThe destruction of the Demon Seed sent waves of power through the ether, waves of staggering force.  I felt them, and I am sure other beings did as well.  Others who will wonder why their toy was broken...\n\nBut regardless of future troubles, I have something for you.  Neeru sent it as payment.  And he bid me thank you.\n\nSo, thank you.", rewards = "You will receive:\n\nBanshee Armor"}
MultiLanguageQuestData['en'][925] = {title = "Cairne's Hoofprint", objective = "Travel to Thunder Bluff to see about getting Cairne Bloodhoof's hoofprint for your ward.", description = "They say that Cairne Bloodhoof is one of the greatest heroes the Horde has ever seen.  When I grow up, I wanna be a hero of the Horde too!\n\nDo you know Cairne, <name>?  Could you do me a favor, please?  Could you get his hoofprint for me?  I dunno how to ask him, and he'd probably be too busy for someone like me... but you!  You're an adventurer just like he is!  I bet he'd give you his hoofprint easy!\n\nPlease?", progress = "When the orcs were alone and without friends, the tauren welcomed them to a strange land and shared with them without asking anything in return.  That's honor, <name>.", completion = "WOW!  You got Cairne's hoofprint for me!  Thank you very much!  And wow... he wrote a personal message on here - to me!  I knew he'd be totally cool, I just did!  Maybe someday I'll thank him myself... when I become a hero of the Horde!\n\nYou're the best, &lt;name&gt;.  Thank you for being so nice to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][926] = {title = "Flawed Power Stone", objective = "These stones are infused with magical energy, but purposefully flawed.  They are very unstable and once removed from the table they will consume themselves quickly.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nFlawed Power Stone"}
MultiLanguageQuestData['en'][927] = {title = "The Moss-twined Heart", objective = "Bring the Moss-twined Heart to Denalan at Lake Al'Ameth.", description = "The heart of Blackmoss the Fetid is covered with a dark, oily moss.  In fact, the only way to tell this is a heart is from its slow, rhythmic beat... A beat that continues even now.\n\nPerhaps Denalan will want to see this heart.", progress = "<name>!  You have something for me?", completion = "...What is this?  A timberling heart??  It's covered with a foul moss!\n\nThank you for bringing this to me, &lt;name&gt;.  I will examine the heart and, if fortune shines, determine the nature of the moss about it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][928] = {title = "Crown of the Earth", objective = "Bring the Partially Filled Vessel to Corithras Moonrage in Dolanaar.", description = "While there is more I could speak to you of the moonwells and of Teldrassil, I must send you along. Corithras Moonrage will be expecting you. I have poured the phial of water you brought to me into this vessel to bring to him.\n\nSeek out Corithras. You will find him at the moonwell in Dolanaar. Follow the road south from Aldrassil out of Shadowglen, and continue to follow the cobblestones as the road turns west.\n\nMind you stay on the road though, <name>. There are dangerous beasts in the forests of late.", progress = "Greetings, <class>. For what purpose do I owe the pleasure of our meeting?", completion = "Ah, I see. You were sent by Tenaron. Well then, it would seem we have much to talk about, much to do, and little time to do it in.\n\nI think we'd best get started.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][929] = {title = "Crown of the Earth", objective = "Fill the Jade Phial and bring it back to Corithras Moonrage in Dolanaar.", description = "First, let me tell you more of the task you must complete. The druids in Darnassus use the water of the moonwells of Teldrassil, and their moonwell must be replenished from time to time. Using these specially crafted phials, you can collect the water of the moonwells.\n\nTake this vessel to the moonwell outside of Starbreeze Village to the east, and fill it with some of its waters, then return to me. When you have completed your task, I shall continue the story where Tenaron left off...", progress = "Hello again, <name>. Have you completed your task?", completion = "After the Battle of Mount Hyjal, we were without direction. Nordrassil smoked from the fire it unleashed, and our immortality--the very essence of our beings!--was lost.\n\nIt was in this trying time that the Betrayer was freed from his prison, and Shan'do Stormrage disappeared. A dark time for all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][930] = {title = "The Glowing Fruit", objective = "Bring the glowing fruit to Denalan at Lake Al'Ameth.", description = "Hanging from beneath its fronds of this glowing plant is a large, round fruit.\n\nDenalan would want to study this fruit, you are certain.", progress = "<name>, you look like you have something to tell me.  Do you have news concerning the timberlings?", completion = "You found this on Teldrassil?  Intriguing... this fruit is exotic.  Perhaps its seeds were brought here from far off.  Perhaps even as far as Azeroth!  And there's something about this fruit... it seems to have reacted very strangely with the soil of Teldrassil.\n\nThank you, &lt;name&gt;.  Now if you'll excuse me, I must study this further...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][931] = {title = "The Shimmering Frond", objective = "Bring a Shimmering Frond to Denalan at Lake Al'Ameth", description = "The fronds on this plant shimmer in the forest light, giving it a twisting, pulsing aura.\n\nYou believe that Denalan would want a specimen of this.", progress = "You have something for me?", completion = "Where did you get this?  I haven't seen a plant like this since a sojourn I made to the Swamp of Sorrows... decades ago!  It's amazing that a specimen made its way to Teldrassil.  And it's grown to such a size!\n\nThank you, &lt;name&gt;.  Forgive my shortness of words, but there is a test I would like to perform on this frond...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][932] = {title = "Twisted Hatred", objective = "Kill Lord Melenas and bring his head to Tallonkai Swiftroot in Dolanaar.", description = "I must warn you, <name>, this matter must stay between us. The satyr are enough of an embarrassment to us already, and this one is much too close to home.\n\nHe is called Lord Melenas. He resides in the nearby cave of Fel Rock where he has gathered a large group of grell warriors. His heart is black as night, and he plots something most foul.\n\nYou must find him within his nearby cave just to the north of here, and bring me his head.", progress = "Did you kill Lord Melenas yet? It is vital that he be taken care of quickly and quietly, <name>. His continued existence is an embarrassment to us all.", completion = "With Lord Melenas laid to rest I can finally move on to other matters. Thank you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nFeral BracersViny Wrappings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][933] = {title = "Crown of the Earth", objective = "Fill the Tourmaline Phial and bring it back to Corithras Moonrage in Dolanaar.", description = "There is another moonwell southeast of the entrance to Darnassus, on the shores of the Pools of Arlithrien. The Sentinels are having problems patrolling the area because of attacks and the growing ill-temperedness of the Gnarlpine furbolgs.\n\nBe wary as you seek out the well, and keep your weapons close at hand.", progress = "At first the reports of crazed furbolg attacks were dismissed. Who could have thought that the peace-loving bear-men would turn to mindless rage? Yet another of the problems that plagues us here in our new home.", completion = "Shan'do Stormrage never returned, and the druids were in disarray, and to this day we still do not know what became of him. With Malfurion missing, Arch Druid Fandral Staghelm took over the leadership of the druids, convincing the Circle of Ancients in Darkshore that it was time for our people to rebuild, and that it was time for our people to regain their immortality.\n\nWith the approval of the Circle, Staghelm and the most powerful druids grew Teldrassil, the new World Tree.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][934] = {title = "Crown of the Earth", objective = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", description = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][935] = {title = "Crown of the Earth", objective = "Bring the Filled Vessel to Arch Druid Fandral Staghelm in Darnassus.", description = "Without the blessings of Alexstrasza the Life-Binder and Nozdormu the Timeless, Teldrassil's growth has not been without flaw. Strange beasts have been reported arising from the very ground of the tree, and crazed furbolgs attack passing travelers.\n\nI can only hope that the solution the Arch Druid is looking for will be found quickly. I will pour all the phials you brought into this vessel, for you to deliver to Darnassus.\n\nBring it to Fandral Staghelm, you will find him in the druid grove.", progress = "I know that I did not summon you, so I cannot help but wonder why it is you have come to speak with me.\n\nWhatever it is, please make it quick.", completion = "Ah yes, the water I had requested. Tenaron and Corithras certainly took their time in having it delivered... perhaps not choosing the most reliable of messengers... hmm.\n\nNonetheless, I can finally get back to my work then. The weight of Teldrassil's problems fall upon my shoulders. A yoke I would wish to soon be rid of.\n\nTake this, you may find some use for it.", rewards = "You will be able to choose one of these rewards:\n\nAshwood BowThicket Hammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][936] = {title = "Assisting Arch Druid Runetotem", objective = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", progress = nil, completion = "Greetings, &lt;class&gt;; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][937] = {title = "The Enchanted Glade", objective = "Acquire 6 Bloodfeather Belts and bring them to Sentinel Arynia Cloudsbreak in the Oracle Glade.", description = "I was dispatched with a small group of Sentinels here to protect the Oracle Tree from the harpies that have made nests all around the glade. Little by little we are trying to push them back.\n\nWhen the Oracle Tree attempted to send a runner to Darnassus with a report, the messenger was attacked and killed by a group of the harpies.\n\nIf you feel up to the task, go to their nests, slay them, and return their belts to me as proof of your deeds.", progress = "Their slashing talons and piercing beaks may prove a difficult match for your own abilities, <name>, but I have faith that you will not fail in this task.", completion = "I am impressed by what you have accomplished here in so short a time, &lt;name&gt;. Would that I could ask you to remain here to assist me with my duties... but I know in my heart that greater tasks lie ahead for you.\n\nI have noticed the Oracle Tree has just shed a piece of its bark. No doubt it has a task that it wishes completed. You should speak with it.", rewards = "You will be able to choose one of these rewards:\n\nShackled GirdleRain-spotted Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][938] = {title = "Mist", objective = "Escort Mist to Sentinel Arynia Cloudsbreak at the moon well near the Oracle Tree.", description = "The sabercat's fur is a distinctive gray color, blending into the surrounding forest. As she lays there, you observe that she is badly wounded, with deep lacerations across her back and stomach.\n\nShe raises her head and gazes at you, bright intelligence shining in blue eyes. She seems to wish to follow you.", progress = "Mist... It was my fault! The witches caught me off guard... I should not have let them take you...", completion = "Oh, thank you, &lt;name&gt;! I feared I would never see Mist again, knowing only her death in my heart, never to be united with my faithful companion. I owe you more than you can know, and you have my eternal gratitude.", rewards = "You will be able to choose one of these rewards:\n\nCord BracersCrag BucklerScout's Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][939] = {title = "Flute of Xavaric", objective = "Bring the Flute of Xavaric and 5 Jadefire Felbind samples to Eridan Bluewind in southern Felwood.", description = "You study the simple wooden flute you picked up after defeating Xavaric.\n\nThe knotted wood feels solid, but it seems as if the spirals and patterns in the surface begin to spin and move as you turn it over in your hands. Suddenly, you feel a sense of dread...\n\nYou shake your head, sure that your mind is playing tricks on you.\n\nIt's possible that other satyrs carry clues as to what you have found. Bring your findings to the druid, Eridan Bluewind, that lives in southern Felwood.", progress = "What is it, <class>? You look concerned.", completion = "I sense the suffering of ancient ones, &lt;name&gt;...\n\nHolding these items is almost unbearable...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][940] = {title = "Teldrassil", objective = "Deliver the Oracle Tree's report to Arch Druid Fandral Staghelm in Darnassus.", description = "The forest whispers of your feats of valor, <name>. As I felt the harpies forced from their nests, a greater calm spread across the forest, its creatures once again feeling safe. I have feared sending another messenger to the Arch Druid, but I know that you will see my message safely to him.\n\nDeliver this to him and know that the forest will see you safely along its paths to the forest of stone.", progress = "Hmm... You come with the spirit of the forest strongly within you, <class>. What business do you have with the Arch Druid of the Kaldorei?", completion = "I wondered why the Oracle Tree had not communicated with me for so long... It seems that some problems are lessened while others grow to greater concerns.\n\nI fear my work on Teldrassil shall never be completed, and our immortality never restored.\n\nNonetheless, you have done the Oracle Tree's task well, and should be rewarded for your diligence.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][941] = {title = "Planting the Heart", objective = "Plant the Tainted Heart in Denalan's Planter.", description = "I have removed that foul moss from the heart, but it remains tainted...\n\nTry placing the heart in my planter.  It is filled with a nutritive soil that may cleanse and heal the heart.", progress = "This planter is filled with soil, specially prepared by Denalan.", completion = "You place the heart within the planter, and it quickly digs itself in!\n\nA few seconds later it wriggles back out, cleansed.  It pulses slightly... beckoning for you to take it.", rewards = "You will receive:\n\nCleansed Timberling Heart"}
MultiLanguageQuestData['en'][942] = {title = "The Absent Minded Prospector", objective = "Take the mysterious fossil to Archaeologist Flagongut in Menethil Harbor.", description = "This fossil bears a striking resemblance to one I once saw in Ironforge. An archaeologist by the name of Flagongut brought it to our annual Explorers' League conference. He believed the fossil had a power which could be unlocked somehow.\n\nLast I heard Flagongut had holed up in the Deepwater Tavern in Menethil Harbor, awaiting escort to the Whelgar Excavation Site. Seek him out and show him Remtravel's fossil. Perhaps he can reveal the secrets of the past.\n\nThe ship to Menethil departs from Auberdine.", progress = "What ya got there, friend?", completion = "Oh my! You say this came from the distant lands of Kalimdor?\n\nAmazing! Simply amazing!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][943] = {title = "The Absent Minded Prospector", objective = "Archaeologist Flagongut in Menethil Harbor wants you to bring him the Stone of Relu and Flagongut's Fossil.", description = "Prospector Whelgar now holds the original fossil at his site in the Wetlands. When I discovered the Stone of Relu, I believed it to be the key to unlocking the mystery of the fossil.\n\nWhile I traveled on the road to meet Whelgar, I was attacked by raptors and the relic was lost. I don't know which one of the mottled beasts swallowed the relic but if you can retrieve it, I can unleash the power of these artifacts.\n\nBring me both the Stone of Relu, and the original fossil he holds.", progress = "With the Stone of Relu I will be able to release the hidden secrets of my fossil as well as Remtravel's fossil from Darkshore, <name>.", completion = "Most excellent, &lt;name&gt;!\n\nNow to see if I can use the stone to decipher the powers of the fossils.", rewards = "You will be able to choose one of these rewards:\n\nRelic BladeSkullchipper\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][944] = {title = "The Master's Glaive", objective = "Gather information, then use the Phial of Scrying to create a Scrying Bowl. Use the bowl to speak with Onu.", description = "It is strange that the naga are here, in Darkshore.  But stranger still...are the Twilight's Hammer.  That cult worships the old, old lords of the earth.  Lords defeated long ago.\n\nThe Master's Glaive, to the south, is a place where such an old lord fell.\n\nGo there and look for more Twilight's Hammer cultists.\n\nTake this phial of scrying.  Use it to create a scrying bowl after searching the Master's Glaive.  Then speak to me through the bowl.", progress = "The Master's Glaive, <name>.\n\nGo there, then speak with me again.", completion = "The Twilight's Hammer is at the Master's Glaive?\n\nUnfortunate.\n\nThe old lord impaled by the glaive is long dead, but that does not mean slivers of his power do not still remain.\n\nThe Twilight's Hammer must be seeking this power.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][945] = {title = "Therylune's Escape", objective = "Help Therylune escape, then tell Therysil at the Shrine of Aessina that her sister is safe.", description = "Help!\n\nI was wandering around the Master's Glaive, and these dirty cultists surrounded me.  Lucky I'm good at hiding!!\n\nCan you help me out of here?  And I need to send word to my sister Therysil that I'm all right.  She's in Ashenvale to the south, at the Shrine of Aessina.", progress = nil, completion = "My sister was where??  Therylune doesn't mind getting herself dirty, but still!  That's a long way to wander, and the Master's Glaive is an unwholesome place...\n\nWell thank you, &lt;name&gt;.  It was very nice of you to let me know she's all right.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][947] = {title = "Cave Mushrooms", objective = "Bring 5 Scaber Stalks and 1 Death Cap to Barithras Moonshade in Auberdine.", description = "I am devising a potion that requires rare mushrooms, mushrooms that grow only in a certain cave.  The cave lies behind Cliffspring Falls, to the east and slightly north along the mountains.\n\nI would go there myself, but I was advised by the Grove of the Ancients to stay away from that place.  Our venerable allies sense that the cave is the hiding place for a new evil in Darkshore.\n\nPlease, <name>, gather the mushrooms for me.  And while doing so, scout the cave to confirm the Ancients' fears.", progress = "Do you have my mushrooms, <name>?  Have you been to the cave?", completion = "Many thanks, &lt;name&gt;.  These mushrooms are fine specimens!\n\nAnd when you were at Cliffspring Falls, did you find anything to confirm the warnings of the Ancients?\n\nThe Ancients are wise, but I had hoped that, this time, they were wrong.", rewards = "You will receive:\n\nGustweald CloakRed-speckled Mushroom"}
MultiLanguageQuestData['en'][948] = {title = "Onu", objective = "Speak with Onu at the Grove of the Ancients.", description = "Onu, an Ancient of Lore at the Grove of the Ancients, knows of your journey to Cliffwater Falls and wishes to speak with you.  The grove lies to the south, nestled near the mountains.\n\nThe Ancients are patient and wise, <name>.  But if Onu seeks your counsel concerning what you saw in the falls, then I fear it is urgent.", progress = nil, completion = "&lt;name&gt;.  You are here.\n\nGood.\n\nWe have matters...to discuss.  You and I.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][949] = {title = "The Twilight Camp", objective = "Find a clue in the Twilight's Hammer camp at the Master's Glaive.", description = "The Twilight's Hammer's purpose at the Master's Glaive is not known.  But it must be dark.\n\nSearch through their camp at the Glaive... Search for some thing that may teach us their intentions.\n\nFor we must learn their intentions before a plan is made.", progress = nil, completion = "This book is hand printed in an ancient language, and illustrated by a master artist.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][950] = {title = "Return to Onu", objective = "Bring Onu the recovered Insane Scribbles.", description = "Peering into the Twilight Tome is maddening.  Text begins to swim and dance after only a moment's glance, and once beautiful scrollwork twists into grotesque shapes.\n\nTearing away one page of insane scribbles is all that is possible before a swoon overtakes you.", progress = "<name>.  You return.", completion = "A chaotic, primal magic surrounds this parchment of scribbles.  I sense the work of the old ones in it.\n\nLet us hope it reveals the purpose of the Twilight's Hammer in Darkshore...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][951] = {title = "Mathystra Relics", objective = "Bring 6 Mathystra Relics to Onu at the Grove of the Ancients.", description = "The parchment you found at the Master's Glaive is a page from an ancient text...written by elves!  It is heavily cursed and tainted by the corruption of the Twilight's Hammer, but it seems the cult is using ancient elven magic to bring their old masters back to our world.\n\nTravel to the ruins of Mathystra to the northeast, and search for ancient relics among the grass and broken stones.  Through their study, we may divine how the Twilight's Hammer intends to exploit the magic of the elves.", progress = "<name>.  Has your rooting through the Ruins of Mathystra been fruitful?", completion = "Thank you.  These relics are from a time when Mathystra shone.  That once great bastion of the elves has faded, but shards of its magic remain.  Let us hope we can unlock the secrets of that place before our enemies...\n\nBe vigilant, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nHardwood CudgelWoodsman Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][952] = {title = "Grove of the Ancients", objective = "Deliver Fandral's message to Onu in the Grove of the Ancients in Darkshore, south of Auberdine.", description = "If you had enough time to run messages for the Oracle Tree, then I'm sure that I can press you into service to deliver a message to the Grove of the Ancients in Darkshore, due south of Auberdine.\n\nYou will most likely have to secure transport on a hippogryph, but I have faith enough in you that you can manage that. Take this to Onu, the Ancient of Lore. He has been awaiting word from me, even as I waited for news from the Oracle Glade.", progress = "Ah. <class>. How may Onu assist you?", completion = "Ah. Thank you, &lt;name&gt;. It is strange, though. The Arch Druid always seems in such a hurry. The forest knows that all shall come to pass in the appointed time. Shan'do Stormrage understood that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][953] = {title = "The Fall of Ameth'Aran", objective = "Study the tablets which tell of Ameth'Aran and of its fall, then return to Sentinel Tysha Moonblade in Darkshore.", description = "To the east you will find the ruins of Ameth'Aran. It is now inhabited by the restless spirits of the Highborne that once dwelt within its walls, but once it was a place where the servants of Azshara freely practiced their powerful magics.\n\nI was sent to explore the ruins and came across two large tablets, scrawled with the stories of Ameth'Aran and its fall. While I read the runes, I was accosted by the spirits, and fled.\n\nPlease, if you can, venture to the ruins and decipher the tablets in my place.", progress = "When you have studied the tablets and learned of Ameth'Aran's fall, I will take the knowledge on to Auberdine, and inform the Circle of Ancients.", completion = "We have few records from the time around the War of the Ancients, especially near the destruction of the Well of Eternity. Given the upheaval and cataclysmic events that were taking place, it is no big surprise.\n\nThank you, &lt;name&gt;. With your help, my work here is finished, and I will be able to deliver a full report to the Circle.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][954] = {title = "Bashal'Aran", objective = "Find the source of the strange blue aura in the ruins of Bashal'Aran.", description = "The ruins of Bashal'Aran to the east are overrun with demonic minions. The sprites and satyrs that have taken up residence in the area feed upon the magical energies of the area, their powers growing from continued exposure.\n\nEven with that, I have noticed that there is one shrine they will not approach. On the western side of the ruins, atop a small bluff, a strange blue aura permeates... There must be an explanation to the demons' reluctance.\n\nI would like you to investigate it.", progress = nil, completion = "Ahh... To what could I possibly owe the exceedingly special honor of a &lt;race&gt; such as yourself as company. Truly it says much of my current companions--with no offense to my hosts, the noble grells and satyrs--that your presence could be considered an improvement.\n\nBut please, do not let my uncivil tongue drive you from the place. It has indeed been many years, decades even, since I had civil accompaniment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][955] = {title = "Bashal'Aran", objective = "Acquire 8 Grell Earrings for Asterion in Bashal'Aran.", description = "If I were to relate the story of my life, I have no doubt it would surpass the limits of your patience. Let us say that mine has been a long and painful life, and this spectral form is perhaps the worst torment of all.\n\nI am held here by the means of magic. Though my words may seem disingenuous, I assure you I would be grateful beyond words if you would help me find the means of my imprisonment. A seal binds me, and by examining the earpieces of the sprites and grells, I may find a trace of it.", progress = "Once I have the earrings, I will cast the spell to search for the whereabouts of the seal that binds me. For centuries I have thought on the freedom destroying the seal would bring to me... Perhaps those centuries have taken a toll upon my mind that I might never recover...", completion = "Indeed... The grells of Bashal'Aran do not possess that which I am searching... however they have come into contact with it recently. Recently... I would reckon that by your time, not mine. Recent for me stretches into the veil of the past, almost another Age...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][956] = {title = "Bashal'Aran", objective = "Obtain the Ancient Moonstone Seal and bring it to Asterion in Bashal'Aran.", description = "If the grells have come into close contact with the seal that binds my eternal prison, I suspect I know the cause. No doubt the seal has come into the possession of the satyr that lead them.\n\nI feel strongly that this must be true, <name>. One of the satyr must surely possess it. If you can obtain it, you would bring me so close to passing the bars of my prison that tears would come to my eyes.", progress = "The pillars of this shrine are as the bars of a prison to me, <name>. No strength I still possess might break them, and no magic I wield might destroy them...\n\nFor a thousand years and more I have stared at them, wondering if at long last I outlived even the stone, would I be free? Or would it be invisible bars that held me then...", completion = "It... it is hard for me to even believe that what I hold now is that which has held me for so long. Let us waste no time, &lt;name&gt;. When the seal is destroyed, I might walk the forests of the earth freely again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][957] = {title = "Bashal'Aran", objective = "Destroy the Ancient Moonstone Seal at the ancient flame in Ameth'Aran, then return to Asterion in Bashal'Aran.", description = "It was the craft of one of the most powerful of the Highborne that created the seal that formed my prison. In Ameth'Aran, the ruins to the south that are twin to these, persists even today an ancient flame, blue in color. In this flame this seal could be destroyed.\n\nBe wary in the ruins, <name>...", progress = "In truth, <name>, I am afraid... Afraid that your coming--all of this--is merely a figment of a deranged mind. Can you know the torture that this is? I... Please, you must go quickly.", completion = "I am freed, &lt;name&gt;! I can now see with my own eyes the changes that have come to our world... Only bits and pieces have I known. To think that when I last walked freely, the Well still stood and the Highborne held court with Azshara, our beloved queen.\n\nI sense that my jailor, my former master, Athrikus, still lives... Already my feelings of hopelessness will give way into thoughts of vengeance.", rewards = "You will be able to choose one of these rewards:\n\nExplorer's VestVagabond LeggingsElven Wand\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][958] = {title = "Tools of the Highborne", objective = "Retrieve 7 Highborne Relics for Thundris Windweaver in Auberdine.", description = "<class>. A task I would ask of you.\n\nHave you seen the ruins of Ameth'Aran? If not, you will find them on the eastern side of the main road, some ways to the south. Once they were the home of many powerful Highborne, now they are a testament to the destruction their dabblings produced.\n\nI have been told by the Sentinels that the spirits of the Highborne persist, and that they wield their ancient magical implements. Those relics must be appropriated, so that we might destroy them.", progress = "If only the tools of their undoing could have been destroyed in the cataclysm that destroyed our world... Nonetheless, we must do what we can to ensure that the horrors of our past are not repeated in the future.", completion = "Though it is surely a figment of my imagination, I feel as though I can almost feel the taint of foul Highborne magic upon them. I will have these destroyed, so that their long dormant evil might never be released again.", rewards = "You will receive:\n\nIvy Cuffs"}
MultiLanguageQuestData['en'][959] = {title = "Trouble at the Docks", objective = "Crane Operator Bigglefuzz in Ratchet wants you to retrieve the bottle of 99-Year-Old Port from Mad Magglish who is hiding in the Wailing Caverns.", description = "Oops!\n\nHad a little mishap, as you can see! The morning cargo shipment from Booty Bay was huge. Huge I say! Never seen so many crates. Well, I was trying to expedite things so I started unloading a bit more than I could handle. That's when everything came tumbling down.\n\nBefore I knew what was going on, I saw that menace, Mad Magglish, go running off with a bottle of 99-year-old port. Chased him all the way to Wailing Caverns. No way I was going in there.\n\nMaybe you're brave enough to find him?", progress = "The dockmaster has been on my case ever since Mad Magglish made off with that 99-year-old port. I guess that bottle was intended as a gift for Gazlowe from none other than Baron Revilgaz himself.\n\nIf you're brave enough and patient enough to seek out Mad Magglish and get that port back, I'll see to it you get a nice reward.", completion = "Superb! And just as I was about to lose my job too! I will see to it that Gazlowe gets this gift immediately.\n\nThank you, &lt;name&gt;. Nicely done, I say!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][960] = {title = "Onu is meditating", objective = "I am meditating on your task, <name>.  Meditating on reasons why the Twilight's Hammer and naga are here.\n\nWhen you are ready, use the phial of scrying to create a scrying bowl.  Then, contact me through the bowl.\n\nIf you have lost your phial of scrying, then here is another.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nPhial of Scrying"}
MultiLanguageQuestData['en'][961] = {title = "Onu is meditating", objective = "The finding of Twilight's Hammer cultists is troubling.  I must meditate on their intentions...\n\nWhen you have more information, speak to me through a scrying bowl.  If you require a phial of scrying in order to create a bowl, then...here is another.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nPhial of Scrying"}
MultiLanguageQuestData['en'][962] = {title = "Serpentbloom", objective = "Apothecary Zamah in Thunder Bluff wants you to collect 10 Serpentbloom.", description = "The Royal Apothecary Society, based in the great Undercity of Lordaeron, has sent me here for a very specific service, <name>. Perhaps you wish to aid me, and in turn The Dark Lady in our efforts to advance the Forsaken.\n\nRecently I studied a rare specimen of flora named Serpentbloom. I believe in greater quantities this herb has great potential.\n\nUnfortunately Serpentbloom can only be found in the darkest recesses of the Wailing Caverns, a dangerous cave system located in the Barrens.", progress = "I am eager to see if you can gather enough Serpentbloom from the Wailing Caverns. I've sent many to do my bidding but none have returned.", completion = "Ah, splendid specimens. You have done well, &lt;name&gt;.", rewards = "You will receive:\n\nApothecary Gloves"}
MultiLanguageQuestData['en'][963] = {title = "For Love Eternal", objective = "Free the spirit of Anaya Dawnrunner and bring her pendant back to Cerellean Whiteclaw in Auberdine.", description = "In the aftermath of the battles at the Well of Eternity, I heard that Ameth'Aran had been destroyed, its people dead, including my love, Anaya.\n\nI would never have thought, thousands of years later, that memories of Anaya would still haunt my dreams. Wandering the woods of Darkshore in a stupor, I found myself in the ruins of Ameth'Aran... where I saw the haunted spirit of my beloved.\n\nShe must be freed, but I lack the heart to do it. Her spirit must be destroyed.", progress = "With a great sorrow in my heart, I followed the Shan'do Stormrage into hibernation, and took my sorrow to my dreams, sleeping for the passing of thousands of years.", completion = "Thank you, &lt;name&gt;. Perhaps it would have been better... if I had done it myself. But even after these thousands of years, I could not bear to raise my hand against my beloved.\n\nPlease, I would be alone with my grief...", rewards = "You will receive:\n\nTear of Grief"}
MultiLanguageQuestData['en'][964] = {title = "Skeletal Fragments", objective = "Bring 15 Skeletal Fragments to Apothecary Dithers at the Bulwark, Western Plaguelands.", description = "The key to Scholomance is called a Skeleton Key.  It must be forged from the remains of a skeleton - several actually - and hardened by only the strongest of metals within a suitable mold.  A signet of power from a being who naturally can open the portal to Scholomance will make the key ultimately function.\n\nFirst thing's first though, <name>.  We'll need skeletal fragments for the key's forging.  Skeletons inside Andorhal should yield what we need, but the ones outside the walls might work too.", progress = "Kill many and kill often, <class> - we'll need a decent supply of suitable skeletal fragments to make up the outer layer of the key.  They don't call it a Skeleton Key for nothing, you know.", completion = "This'll work, &lt;name&gt;!  My turn now - I will imbue these with a suitable temper that will allow them to survive the intense forging process they will eventually go through.\n\nThe next step will be to get an appropriate mold for the key.  I know a goblin blacksmith in Tanaris that has in the past made molds for similarly macabre items.  He works for whom goblins usually work for - the highest bidder.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][965] = {title = "The Tower of Althalaxx", objective = "Find Balthule Shadowstrike near the Tower of Althalaxx in Darkshore.", description = "Hail, young <race>. I am Elissa Starbreeze, and it is my charge to protect Auberdine from harm.\n\nTo this end, I sent Balthule Shadowstrike to observe the strange happenings around the Tower of Althalaxx to the northeast.\n\nIt is past time that he should have returned. I worry that he has encountered some unforeseen danger in the forest. I would be most appreciative if you would find him and see that he is doing well.", progress = nil, completion = "Elissa sent you? Then it is good tidings you bring. I have troubling news to report to her, and had no means with which to deliver it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][966] = {title = "The Tower of Althalaxx", objective = "Collect 4 Worn Parchments for Balthule Shadowstrike near the Tower of Althalaxx.", description = "A group of warlocks has taken up residence around and inside the tower. I would have returned to Auberdine to report to Elissa earlier, but I was afraid that I might miss something while I was away.\n\nDelgren suspected such a company might be gathering at the tower, but did not know why.\n\nA few scraps of parchment that the warlocks carry have found their way to my hands, but I need more to complete the puzzle. I warn you not to venture into the tower, however, the warlocks there are much more powerful!", progress = "Have you found any more of their scrolls? I should be able to piece together a larger picture of the cult if you can find them.", completion = "Many thanks, &lt;name&gt;. This should shed some light on this warlocks' gathering...\n\nHmm... the Cult of the Dark Strand... I have never heard of this group before. Having no knowledge of their history, it is all but impossible to say what their plans must be.\n\nThere is no more time to delay. Warning must be delivered to Delgren immediately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][967] = {title = "The Tower of Althalaxx", objective = "Deliver Balthule's letter to Delgren the Purifier in Ashenvale Forest.", description = "My master, Delgren the Purifier, is a paladin who has graciously offered his assistance in defending our forests from the forces of the demons and undead. He has taught me much about the Holy Light and the art of battle.\n\nDelgren must know of the cult's operations immediately.\n\nYou will find him far south of here at Maestra's Post in Ashenvale Forest. Be swift, I fear the Dark Strand's threat grows with each passing hour.", progress = "You have some business with me, <class>?", completion = "If you don't mind my saying, you seem a bit well-equipped for a messenger, hm? I suppose Balthule wanted to be certain that his letter reached my hands. Let's see what he has to say...\n\nThis is disturbing news. When undead or demonic forces are found, I help the Sentinels destroy them.\n\nAt first I was unaccustomed to the manners of the night elves, but I have grown to respect them greatly as allies.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][968] = {title = "The Powers Below", objective = "Bring the Book: The Powers Below to Gerrig Bonegrip in the Forlorn Cavern, Ironforge.", description = "Although terribly worn and scratched, the title of this book can still be read upon its cover:\n\nThe Powers Below\n\nInside the book is a listing of unpronounceable names with foreboding titles, methods of worship, and preferred sacrifices...many of which include living, humanoid creatures.\n\nOn the inside cover of the book are the words: \"Bonegrip's Runes and Dooms, The Forlorn Cavern, Ironforge.  Proprietor: Gerrig Bonegrip.\"\n\nIf Bonegrip sells books like this, perhaps he'll buy this one back.", progress = "Hello, sir.\n\nMay I interest you in one of my tomes?", completion = "Ah, a copy of The Powers Below.  An interesting text, this is.  And some might find it useful...\n\nBut this one's in sad shape.  And look here!  There are notes in the margin of almost every page!\n\nHm...I know this copy.  I sold it to Bolgar last year.  Are you...a friend of his?  Yes, I thought you were.  You have that same fire behind your eyes!\n\nWell, by definition, a friend of Bolgar's is a friend of mine.  And we take care of our own, yes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][969] = {title = "Luck Be With You", objective = "Collect 4 Frostmaul Shards for Witch Doctor Mau'ari in Everlook.", description = "Ah, I can tell just by lookin' at ya -- you be wantin' to make a lucky charm. Mau'ari always knows!\n\nTo da south. you'll find a canyon, an' giants made a' solid ice. The giants sometimes be carryin' dem, but ya can always gather da shards yerself from da canyon. These shards have a powerful reflective quality.\n\nBring back 4 frostmaul shards, and my lucky charm will be yours.", progress = "Bring back da shards, and I be tellin' you more!", completion = "Ahh, yes... I will make da charm for ya now. Just you wait!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][970] = {title = "The Tower of Althalaxx", objective = "Collect a Glowing Soul Gem and return it to Delgren the Purifier at Maestra's Post.", description = "Balthule's letter is dire. This Cult of the Dark Strand is a thorn in my side that must be removed. I have been dealing with some of the Dark Strand scum northeast of here at Ordil'Aran. One of their number possesses a soul gem that I believe holds the secret to the cult's power.\n\nBring it to me, and I will be able to decipher the secrets held within.", progress = "Have you acquired that soul gem?", completion = "Hmm, some dark magic enchants this soulstone. Let's see what's trapped inside, shall we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][971] = {title = "Knowledge in the Deeps", objective = "Bring the Lorgalis Manuscript to Gerrig Bonegrip in the Forlorn Cavern in Ironforge.", description = "As you might know, I collect lore.  Old lore.  Powerful lore.  Lore that opens doorways, and lore that can awaken Those Who Sleep.\n\nThere are rumors of an old piece of lore, the Lorgalis Manuscript, at the bottom of Blackfathom Deeps in Ashenvale.  That place is the old dwelling of long-dead elves.  Elves who held great knowledge before their city fell to ruin.\n\nSearch Blackfathom Deeps for the manuscript.  Do this, and I will not forget it.  Not even after ... the end days.", progress = "The journey to Ashenvale is long, and your task is not easy.  But if you get me the manuscript, <name>...then your reward will be great.", completion = "You found the manuscript!  What a joyous day this is!  Copies will be made and distributed, and the ancient knowledge of Lorgalis will finally be known to my brothers and sisters!\n\nYour service to us is more than you know, &lt;name&gt;.  But I hope that this gift shows you the gratitude we extend to our allies.", rewards = "You will receive:\n\nSustaining Ring"}
MultiLanguageQuestData['en'][972] = {title = "Water Sapta", objective = "Take the water sapta and find the corrupted pool of water in Silverpine, <name>. I have great faith in your abilities.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWater Sapta"}
MultiLanguageQuestData['en'][973] = {title = "The Tower of Althalaxx", objective = "Bring Ilkrud Magthrull's Tome to Delgren the Purifier at Maestra's Post.", description = "Ilkrud Magthrull. Yes, I have knowledge of him. He is a powerful orc warlock that makes his residence at the Fire Scar Shrine,  a place of great evil in southwestern Ashenvale.\n\nHe had been little more than an annoyance until now, and I had not dealt with him, but it seems that his time has come.", progress = "You look a bit shaken up, <name>. Are you well?", completion = "It was a grand thing you did today, &lt;name&gt;. You should be quite proud of yourself for having faced down a warlock of such power.\n\nNow, let's see what we can learn from Ilkrud's writings.", rewards = "You will be able to choose one of these rewards:\n\nClergy RingStaff of the Purifier\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][974] = {title = "Finding the Source", objective = "Krakle in Un'Goro Crater wants you to find the hottest area of Fire Plume Ridge.\n\nWhenever you find a hot spot, right click the thermometer to check the temperature. Keep looking until you find the hottest one.", description = "The hot springs here are a source of mystery to me. Where does the heat come from?\n\nLooking at how close the pools are to Fire Plume Ridge, I really wonder if the volcano might have something to do with it. I created a thermometer to take readings of the temperatures at the volcano, and I'd like to find the hottest part. It gives the measurements in degrees Kraklenheit!\n\nHere, take it, and take readings of the temperatures at the ridge whenever you see a hot spot!", progress = "I'd go there myself, but... I'm a little scared of the fire elementals there!", completion = "Yes, I definitely see the correlation here between the temperature of the volcano and the hot springs. I'll have to double-check my equations for accuracy, but it seems like the distance and the rate that the heat is transferred... Hmm...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][975] = {title = "Cache of Mau'ari", objective = "Speak to Witch Doctor Mau'ari again in a moment to receive the lucky charm.", description = "Now, before I give ya dis charm, I better explain how ta use it.\n\nIf you carry da charm with ya, you'll find dat certain items will drop from creatures ya fight. If you don't have da charm with you, you won't find them. Understand?\n\nYou'll know these special items by the name -- they be called E'ko. If you find any of these items, just bring dem to ol' Mau'ari, and she help ya out.\n\nWait here while I fix your charm.", progress = nil, completion = "Here it is, &lt;name&gt;. Remember, ya have ta carry it with you. Why don't ya head back to da wilds, an' see what ya be findin' there?", rewards = "You will receive:\n\nCache of Mau'ari"}
MultiLanguageQuestData['en'][976] = {title = "Supplies to Auberdine", objective = "Speak with Delgren the Purifier at Maestra's Post after seeing Feero safely through Ashenvale Forest.", description = "Delgren has asked me to deliver messages and supplies to Sentinel Starbreeze in Auberdine, but I am loathe to leave on my own. Dangerous foes operate in the forest, and I do not wish to risk letting these supplies and information fall into the wrong hands.\n\nIf you and others could act as my guards, I could leave now. With your protection, I have no doubt that we can see these goods safely to Auberdine.", progress = "The Sentinels have a great need for supplies to reinforce themselves in Darkshore.", completion = "You have done well today, &lt;class&gt;. The items we sent to aid Auberdine will be of immediate use in dealing with the dark threats that infest the forest.\n\nTake these with my heartfelt thanks.", rewards = "You will be able to choose one of these rewards:\n\nEverglow LanternChestplate of Kor\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][977] = {title = "Are We There, Yeti?", objective = "Collect 2 Pristine Yeti Horns for Umi Rumplesnicker in Everlook.", description = "Now that I have what I need to cover the mechanical moving parts, I only need one other thing. Well, actually two. Two horns!\n\nThe ice thistle patriarchs and matriarchs have the largest horns, so of course, those are the ones I want. That type of yeti inhabits a cave to the southeast. There are plenty of them there; you shouldn't have any problem finding them.\n\nRemember, I only want the best looking ones -- no beat up or broken horns, please!", progress = "I've just about finished attaching the fur, <name>. Please, hurry back with those horns!", completion = "I can't wait to show my friends! Now, just wait a moment while I attach these...\n\nPerfect!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][978] = {title = "Moontouched Wildkin", objective = "Collect 10 Moontouched Feathers from Winterspring, then return to Erelas Ambersky in Rut'theran Village.", description = "Wildkin feathers from the Hinterlands appear to contain traces of magical qualities. These powers... they don't seem to be wielded by the creatures, it's more like they are simply inherent to the species -- part of their very essence.\n\nDuring my studies, I heard that a large population of wildkin inhabit the snowy lands of Winterspring. Could these creatures have the same powers? Please help me find an answer, <name>. Go to Winterspring and gather feathers that have dropped to the ground, then return to me.", progress = "Where could these powers have originated from? I think we are on the right track to find the answer, <name>.", completion = "Now I can compare the feathers... Let's see...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][979] = {title = "Find Ranshalla", objective = "Find Ranshalla in eastern Winterspring.", description = "Yes, yes, these feathers seem to hold the same magical enchantment that I noticed previously... While I am not certain what we might find, I urge you to continue searching for answers, <name>.\n\nA colleague of mine recently traveled into Winterspring to observe the wildkin there, in their own habitat. Why don't you catch up with her and see what she has found?", progress = nil, completion = "Hi! Erelas sent you? Great, I was just preparing to travel up to the caves now, and I wouldn't mind company.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][980] = {title = "The New Springs", objective = "Travel to Winterspring and speak with Donova Snowden.", description = "Now, I've heard about other hot springs in a place called Winterspring, far to the north of here. The strange thing is, there are no volcanoes anywhere near them. Interesting, I know.\n\nWell, if you want to find out more, you should head to Winterspring and speak to a friend of mine. Her name is Donova Snowden, and she is currently staying by the hot springs there.\n\nThanks again for helping me with my thermometer! See you later!", progress = nil, completion = "Hi there, &lt;name&gt;. Yes, what Krakle told you is true...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][981] = {title = "The Tower of Althalaxx", objective = "Talk to Delgren the Purifier at Maestra's Post.", description = "For all the work that you have done, you deserve to be well rewarded. Return to Delgren and tell him that Athrikus Narassin lies stilled by your hand, and the Cult of the Dark Strand is beaten and scattered.", progress = nil, completion = "I knew you would be up to the task, &lt;name&gt;.\n\nI sense great deeds before you, and that you will right many of the wrongs that plague our lands. Bear my blessings, &lt;name&gt;, as well as this gift.", rewards = "You will be able to choose one of these rewards:\n\nPious LegwrapsSeraph's Strike\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][982] = {title = "Deep Ocean, Vast Sea", objective = "Recover the Silver Dawning's Lockbox and the Mist Veil's Lockbox for Gorbold Steelhand in Auberdine. Both items should be found aboard the wreckage of the ships to the north of the village.", description = "Off the coast of Darkshore to our north are two wrecked ships - the Silver Dawning and the Mist Veil.  Some time ago, both ships ran afoul of the blasted murlocs as they sailed across the vast sea into Auberdine.  They now lie at the bottom of the ocean as trophies for those fiends.\n\nBoth captains didn't make it out that night, and their logs and other effects are still below in lockboxes.  I'd like for you to recover them for us; it would mean a lot to the crew members still around these parts.", progress = "The captains of those ships were good night elves, and they deserve a better fate than they were given.  Perhaps tending to their personal effects will be the best way to put their spirits to rest.", completion = "You've done us here in Auberdine a great service, lad.  We'll make sure that their effects are properly taken care of.\n\nAs for you, please have this.  It is the least I can do for someone with the bravery to set things right.", rewards = "You will be able to choose one of these rewards:\n\nWelldrip GlovesNoosegrip Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][983] = {title = "Buzzbox 827", objective = "Collect 6 Crawler Legs and place them in Buzzbox 827.", description = "Hey! Help me with my latest invention, the buzzbox. You can talk to people far away!\n\nMaybe you've already seen them, they're boxes with levers on them. The only problem is they need constant maintenance.\n\nEach one suffers from a different problem, but I made a really smart decision. I placed each one near creatures that have the proper parts to fix that particular machine. Right now Buzzbox 827 is on the fritz. It's just south of Auberdine, real close. It takes 6 Crawler Legs to fix it. I'll pay ya...", progress = "Buzzbox 827 sits with an eerie silence. A single flashing light indicates that it needs 6 Crawler Legs to be placed in its holding box.", completion = "As you place the Crawler Legs inside the machine, you hear gears begin to grind. Judging from the banging sounds coming from the Buzzbox, you believe the Crawler Legs are being put in their proper place. Soon the machine begins to hum, and you hear a tiny voice calling out from within.\n\n\"Hello? Uhh... Hello! You fixed it! This is Wizbang by the way! Thanks a lot... Hey, you wouldn't want to fix another one, would ya?\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][984] = {title = "How Big a Threat?", objective = "Find a corrupt furbolg camp in Darkshore and return to Terenthis in Auberdine.", description = "Some of my brethren were rescued from a corrupt furbolg in Teldrassil, and I've vowed to stop any more atrocities before more of our kind are injured... or worse.\n\nI have seen a couple hints of corruption in Darkshore already, but I have yet to find any widespread signs. I think it would be logical if the investigation continued with the furbolgs. Would you find one of their camps, and return to me if you see any signs of corruption?", progress = "How goes your search, <name>?", completion = "This is terrible news indeed, &lt;name&gt;.\n\nWith the furbolgs this close to Auberdine, we will have to prepare ourselves for the inevitable.\n\nThank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][985] = {title = "How Big a Threat?", objective = "Kill 8 Blackwood Pathfinders and 5 Windtalkers and return to Terenthis in Auberdine.", description = "You've already proven adept at scouting our enemy, <name>. Do you have what it takes to fight them as well?\n\nNot all adventurers prefer straightforward combat to the art of stealth and evasion.\n\nIf you think you're up for the task, then the furbolg camp south of Auberdine is currently the biggest threat to our people. You'll find some of the Blackwood tribe there. Kill 8 pathfinders and 5 windtalkers, and return to me here.", progress = nil, completion = "Wash the blood from your garments, &lt;name&gt;, and do not mourn what you had to do. Instead, give thanks. You have lessened the threat to our people here in Auberdine, even if Darkshore is still in jeopardy from the effects of fel moss.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][986] = {title = "A Lost Master", objective = "Find 5 Fine Moonstalker Pelts and return them to Terenthis in Auberdine.", description = "<name>, your skills have already helped me in my endeavor. Could I impose on you again to help Grimclaw and his master Volcor? In addition, I can craft you a magical cloak that will allow you to walk unhindered by Darkshore's creatures while you look for him.\n\nTo create the cloak, I'll need five fine moonstalker pelts from a moonstalker sire or matriarch to have enough material. The cats can be found near Wildbend River to the south, or even farther south near Ashenvale.", progress = "I can't in good conscience permit you to seek Volcor until I've crafted that cloak for you.", completion = "These will do nicely, &lt;name&gt;. I shall set to work on the cloak immediately.\n\nGive me a few moments, then return to me.\n\nOh, one more thing: after you've used the enchantment on the cloak you'll be limited in your interactions with others. If you can help it, do no more than speak to others. Much more than that could dispel the illusion.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][990] = {title = "Trek to Ashenvale", objective = "Find Raene Wolfrunner in Ashenvale.", description = "<name>, my mistress, Raene Wolfrunner, awaits you in the city of Astranaar within Ashenvale. With your help, perhaps we can at least ease some of the corruption that's taken hold there.\n\nHead south from here and stay close to the road--you'll find your way there without issue if you follow those directions.", progress = nil, completion = "Ah, a &lt;class&gt; from Darkshore. Selarin has done well to send you here so quickly, &lt;name&gt;. I wish your trip here wasn't under such dire stress. Perhaps with your help we can improve matters.\n\nI would start my visit by speaking to the other citizens of Astranaar. Some could surely use your aid.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][991] = {title = "Raene's Cleansing", objective = "Find Teronis in Ashenvale.", description = "<name>, a longtime friend of mine is also aiding the Sentinels here in Ashenvale, but he has yet to return.\n\nHe had leads on finding an item that he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left here, he mentioned seeking out a gem for the rod.\n\nHe mentioned the gem possibly being hidden at the shrine in Lake Falathim at the base of the mountain to the west. The gem was being held there before it was overrun.\n\nFind my friend, <name>, please.", progress = nil, completion = "Teronis' body lies broken atop the island. For some unknown reason, the murlocs have left it alone.\n\nThe deep slashes across his corpse obviously came from the weapons and claws of the murlocs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][992] = {title = "Gadgetzan Water Survey", objective = "Use the untapped dowsing widget near the pool of water by Sandsorrow Watch. Once you have collected the sample, return the tapped dowsing widget to Senior Surveyor Fizzledowser in Gadgetzan.", description = "We've got a position open for a temporary junior-grade surveyor in the Gadgetzan Water Company, if you're interested!\n\nWith the nomads seizing all our wells, we need to exploit more free sources of water!  There is water to be had in the desert, but only to those smart enough to survey them first.\n\nTake this dowsing widget and tap a sample of the water by the pool near Sandsorrow Watch.  It's right in sight of the trolls around there.  Bring the tapped widget back to me when you're done!", progress = "Welcome back, Junior Surveyor <name>!  Have you completed your assignment yet?", completion = "What's this?  You were ambushed by some sort of bad mojo creepy-crawly?  Oh, this does not bode well for the Gadgetzan Water Company, no indeed...\n\nI guess I should have told you about the reports coming in on some crazy bug-creatures that appear to be sucking up all the water in the desert.  At first, I thought it was just a crock.  We have enough trouble with the nomads as is; I thought it was just more of their shenanigans.  Well, now we know at least!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][993] = {title = "A Lost Master", objective = "Find Volcor in Darkshore and give him the Enchanted Moonstalker Cloak.", description = "The cloak is complete, <name>. The time has come to find Volcor. I can only hope we are in time.\n\nThe cloak's magic, once invoked, will not last long; perhaps five minutes. It will be up to you to know when to use it: I would suggest waiting until you find Grimclaw.\n\nIf what he has told me is true, you will find his master in a cave south of here. Grimclaw will be alongside the road waiting for you. Signal to him by waving when you see him, and he'll point the way towards his master.", progress = nil, completion = "Wonderful! Terenthis found someone to help me.\n\nAnd look, a moonstalker cloak...&lt;cough&gt; Oh... that hurts. Thank you, &lt;name&gt;.\n\nThe furbolgs wounded me before I managed to evade them. Give me a moment, and I should be fine to talk some more.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][994] = {title = "Escape Through Force", objective = "Protect Volcor until you reach the road, then speak to Terenthis in Auberdine.", description = "All right, <name>, force it is. Let's get out of here as soon as you're ready. We'll fight our way down to the road--Grimclaw should still be there. Once there, we can part ways.\n\nTerenthis will want to hear your version of the story immediately, so head to Auberdine after we make it out of here.", progress = nil, completion = "&lt;name&gt;! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.", rewards = "You will receive:\n\nSteadfast Cinch"}
MultiLanguageQuestData['en'][995] = {title = "Escape Through Stealth", objective = "Escape the Furbolg cave and meet Terenthis in Auberdine.", description = "All right then... if you're sure, we'll sneak out of here. Let us leave when you're ready.\n\nRemember, after you've escaped, meet Terenthis back in Auberdine. I'll head there on my own since I'll probably be moving faster than you.", progress = nil, completion = "&lt;name&gt;! I'm pleased to see you've returned successfully. Your assistance to Volcor has given me faith that we can overcome the challenges facing us here in Darkshore and beyond.", rewards = "You will receive:\n\nScarab Trousers"}
MultiLanguageQuestData['en'][996] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][997] = {title = "Denalan's Earth", objective = "Bring the package of Rare Earth to Denalan at Lake Al'Ameth.", description = "Are you heading to the south?  To Lake Al'Ameth?  If so, then I have a task I might ask of you...\n\nMy colleague Denalan has a camp along the eastern end of the lake, where he is studying and experimenting on the plant life of Teldrassil.  He requested a package of rare earths from Darnassus and it was late, only recently arriving here in Dolanaar.\n\nCan you take the package to him?", progress = "You have something for me?", completion = "Ah, it's here!  I have waited for this rare earth for quite some time.  I hope it's still fresh...\n\nThank you for bringing it to me, &lt;name&gt;.  You are a &lt;race&gt; who is generous with his time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][998] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][999] = {title = "When Dreams Turn to Nightmares", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1000] = {title = "The New Frontier", objective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", progress = nil, completion = "Greetings, &lt;class&gt;.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1001] = {title = "Buzzbox 411", objective = "Collect 3 Thresher Eyes from Darkshore Threshers in the deep sea near Buzzbox 411.", description = "A tiny voice crackles from deep within the machine.\n\n\"Wizbang here! The next Buzzbox is north of Auberdine, on the beach\n\nSo, that Buzzbox is number 411 and it needs 3 Thresher Eyes for its repairs. They're just off the coast! The darkshore threshers... *Hic*... Sorry about that...\n\nJust like last time, when you give the Buzzbox the goods, it'll spit out your reward. *Hic*... What? No, I'm fine!\"", progress = "The machine's hatch is open and it seems to wait expectantly for 3 Thresher Eyes to be placed inside.", completion = "The Buzzbox hums to life soon after you place the Thresher Eyes inside. There is a moment of static before you hear a familiar tiny voice call out.\n\n\"Crawler wine is the best...\" *hic*\n\n\"What? Oh, you fixed it already? Wow, you're a fasht one. Sho, would ya like to fix another?\"\n\nYou believe you hear a liquid being poured into a cup, followed by loud gulping sounds.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1002] = {title = "Buzzbox 323", objective = "Collect 6 Moonstalker Fangs and place them in Buzzbox 323.", description = "The Buzzbox gives a burst of static as you hear Wizbang begin to speak.\n\n\"The next Buzzbox is number 323. Ish north of Auberdine but... where's the ale? Wha? Oh, ish on the road sho ya shouldn't have trouble finding it near the bridge.\"\n\nWizbang mumbles something incoherent before you hear a loud gulping sound.\n\n\"Thish one needs Moonstalker Fangs... 6 of 'em.\"", progress = "Though you have yet to place the 6 Moonstalker Fangs inside, you believe you hear the sounds of static and incoherent gnome ramblings coming from within. Could someone else have fixed the machine already?", completion = "The Buzzbox suddenly leaps into action, and you can hear the distinct sounds of teeth being ground to dust coming from within.\n\n\"Sho, ya made it! Thatsh exshellent newsh... Sho... Why doncha move along? Oh! Unless you want another job!\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1003] = {title = "Buzzbox 525", objective = "Collect 4 Grizzled Scalps from Grizzled Thistle Bears to the south of Auberdine and place them in Buzzbox 525.", description = "Over the boiling noises and dripping sounds coming from the machine, you hear Wizbang's wavering voice call out.\n\n\"Nexsht onesh far south down the road. Shouldn't be hard to find... jusht off to the shide... near a fensh. I think I hid it in shum bushesh... Bushessh. Hehehe... Yesh, Buzzbox 525 takes grizzled scalps from thoshe grizzled thistle bears. Boy thash a mouthful. Grizzshled... Hehehe...\"\n\nYou hear more gulping sounds as the machine cuts out. Then, suddenly, it bursts back to life.\n\n\"4!\"", progress = "You hear singing coming from Buzzbox 525.\n\n\"Though crawler wine's shweet, and thresher ale fine, and moonstalker moonshine ish grand. There's nothing sho dear, as a thistle bear beer, and shoon I shall have shome on hand!\"\n\nThe hatch is open and awaits the 4 grizzled scalps as you hear the song repeated over and over.", completion = "\"Sho yash gotsh the scalps in? That'sh sho great... Wha? Well, yesh I shuppose ya have realized that I can speaksh to ya without the materials in the machine. But I was telling the truth when I shaid they were broken!\n\nSee, in addition to being communimacation toolsh, the Buzzboxes also brew and distill fine liquor. Shorry for any deceptshion, but the nightelves do not apprecimerate my liquor trade in their townsh. I put shomething special in thish box to show my gratitude for yer effortsh. Enjoy!\"", rewards = "You will receive:\n\nWizbang's GunnysackWizbang's Special Brew"}
MultiLanguageQuestData['en'][1004] = {title = "The New Frontier", objective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", progress = nil, completion = "Greetings, &lt;class&gt;.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1005] = {title = "What Lurks Beyond", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1006] = {title = "What Lies Beyond", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1007] = {title = "The Ancient Statuette", objective = "Bring the Ancient Statuette to Talen, in his camp near the Zoram Strand.", description = "I would charge you with a task, <name>.\n\nI was on my small vessel, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws!  I fled, carrying what supplies I could to make this meager camp.\n\nBut when I reached the shore and ran... my prized possession was lost.\n\nPlease, <name>, find the site of my ambush, along the coast to the north, and search for an ancient statuette.  It is the reason I have braved the dangers of the Zoram Strand.", progress = "Have you found the statuette, <name>?", completion = "You found it!  Thank you, &lt;name&gt;!\n\nThe old city of Zoram holds many secrets, and this statuette may be the key to many of them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1008] = {title = "The Zoram Strand", objective = "Bring 20 Wrathtail Heads to Shindrell Swiftfire in Astranaar.", description = "There is evil lurking on our northwestern coast, known as the Zoram Strand.\n\nIt is the resting place of the doomed city of Zoram, destroyed during the Sundering and submerged beneath the seas.  It has been lost to the night elves for ages.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must slay these fiends and throw them back to the depths!\n\nReturn to me when your mission is complete.", progress = "We cannot allow the naga to invade our coasts, <name>.  It is vital that you go to the Zoram Strand and complete your mission.", completion = "Very well done, &lt;name&gt;.  Your actions in the Zoram Strand against the naga are commendable.\n\nI know your feat was not easily accomplished, for the strength and guile of the naga is well known to the night elves.  We know this, for we share a history with them.\n\nIt is a history I care not to repeat.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1009] = {title = "Ruuzel", objective = "Bring the Ring of Zoram to Talen near the Zoram Strand.", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to its ancient lock.\n\nThat key is a ring, the Ring of Zoram.  It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on an isle on the northern edge of Zoram.  Please, <name>, retrieve the ring for me!", progress = "It is said that the Ring of Zoram is the key to any lock within the city.  Do you have it, <name>?", completion = "You found the ring!  Thank you, &lt;name&gt;.  Please take this as payment, and know that your deeds today will remain forever in my memory.", rewards = "You will receive:\n\nRobes of Antiquity"}
MultiLanguageQuestData['en'][1010] = {title = "Bathran's Hair", objective = "Bring 5 Bathran's Hair to Orendil Broadleaf in Ashenvale.", description = "There is a plant that once grew in the old ruins of Bathran's Haunt to the north.  The plant was called Bathran's Hair and was known to cure ailments of the spirit.\n\nThere is a sick child in the village, and I believe it is more than just a physical illness.  Will you go to Bathran's Haunt and search it for Bathran's Hair?  I may need it to properly treat the child.\n\nBathran's Haunt lies north of Maestra's Post and just south of the border to Darkshore.", progress = "Have you gathered the Bathran's Hair, <name>?  The child's health grows weaker by the hour...", completion = "Ah, you have the hair!  Now I will mix a cure for the child, and pray my concoction works.\n\nAnd... Forsaken are at Bathran's Haunt?  Very troubling to hear, that is.  Very troubling indeed...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1011] = {title = "Forsaken Diseases", objective = "Bring a Bottle of Disease to Kayneth Stillwind in Forest Song.", description = "The Forsaken, the undead arm of the Horde, have crept into Ashenvale, lurking at our ruins and our barrows.  We believe their goal is to spread disease amongst the lands of the night elves.  We must confirm this!\n\nThe Forsaken have a camp south of here, near the Dor'Danil Barrow Den, where they create poisons and diseases and place them in bottles.  Fight your way into that camp and steal a bottle of disease.  Return with such a bottle.  I will test it and find its purpose.", progress = "Did you find the camp, <name>?  Do you have a bottle of disease?", completion = "Very good, &lt;name&gt;.  Now... by testing the contents of this bottle, the goals of the Forsaken will be revealed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1012] = {title = "Insane Druids", objective = "Kill the druids: Taneel Darkwood, Uthil Mooncall, Mavoris Cloudsbreak; then return to Kayneth Stillwind in Forest Song.", description = "When I struggled with the Forsaken's poisons, I had a vision.  I had a vision of the druids in the Dor'danil Barrow Den, poisoned... murdered by the undead!  They are now errant ghosts, severed from their bodies and driven mad.\n\nSo that the druids' spirits might some day find peace, you must enter the Dor'danil Barrow Den and destroy its once great leaders: Taneel Darkwood, Uthil Mooncall and Mavoris Cloudsbreak.\n\nDo this, then return to me.", progress = "The anguish of the Dor'danil druids still haunt my dreams, <name>.  You must destroy their leaders!", completion = "I felt the anguish of the Dor'danil Barrows lessen, and knew you had completed your task.\n\nIt was grim work you did, &lt;name&gt;, for the spirits you destroyed were merely victims of the Forsaken's evil.  But with their destruction, let us hope the other maddened spirits find peace.", rewards = "You will receive:\n\nEmil's Brand"}
MultiLanguageQuestData['en'][1013] = {title = "The Book of Ur", objective = "Bring the Book of Ur to Keeper Bel'dugur at the Apothecarium in the Undercity.", description = "<name>, Shadowfang Keep holds a book, the Book of Ur, which would be much prized in my collection.  Ur was a great mage of Dalaran before the coming of the Scourge, his studies in other worlds are of much value to ... certain parties among the Forsaken.\n\nEnter Shadowfang Keep and find the book.  Bring it to me, and I will report your service to our Dark Lady...", progress = "Did you find the book, <name>?", completion = "Very good.  This book will add nicely to my collections of the workings of Ur.  His knowledge was great, but his conscience held him from true power.  And so when the Scourge came and his strength was tested, it failed.\n\nWe of the Forsaken cannot afford such weakness, if we are to survive...\n\n...If we are to conquer.", rewards = "You will be able to choose one of these rewards:\n\nGrizzled BootsSteel-clasped Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1014] = {title = "Arugal Must Die", objective = "Kill Arugal and bring his head to Dalar Dawnweaver at the Sepulcher.", description = "Arugal still resides in Shadowfang Keep. We cannot claim Silverpine as a strategic stronghold for the Dark Lady until Arugal is slain.\n\nI shall see to it that his magic is eradicated, <name>. But I leave it in your hands to see that Arugal meets the death he so deserves.\n\nTravel to Shadowfang Keep and put an end to Arugal's foul spells once and for all. Bring to me the vile wizard's head!", progress = "With Arugal's death we stand to increase the Dark Lady's stronghold on Lordaeron.", completion = "Silverpine Forest is finally free from the vice of that wretch Arugal. You have done the Dark Lady a great service, &lt;name&gt;. Your tenacity shall be rewarded.", rewards = "The following spell will be cast on you:\n\nArcane Intellect\n\nYou will receive:\n\nSeal of Sylvanas"}
MultiLanguageQuestData['en'][1015] = {title = "The New Frontier", objective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", progress = nil, completion = "What makes you think I wish to be pestered by the likes of you, &lt;class&gt;?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1016] = {title = "Elemental Bracers", objective = "Collect 5 Intact Elemental Bracers and use the Divining Scroll on them. Afterwards, bring the Divined Scroll to Sentinel Velene Starstrike at the Silverwind Refuge.", description = "Take this divining scroll--it can determine the creator of these elementals. But you will need something from them to use as a reagent to focus scroll's magic--their bracers should do nicely.\n\nA few intact bracers from the creatures should be enough. The other bracers will be useless for our purposes, but they may be worth something to a merchant if you wish to sell them. Once you have the intact bracers attempt to use the scroll. Return to me with the results and we shall proceed from there.", progress = "Since you must destroy the bracers to kill the elementals, it will probably be difficult to find the specific ones that contain the information the divining scroll needs. You can trade bracers with others in order to obtain the ones you need, or perhaps you have the divined paper already?", completion = "Well done, &lt;name&gt;, this should give us the information we need to have the culprit discovered. How would you feel about taking out the mage who fills our pools with corrupt elementals? The corruption of Ashenvale and beyond makes my stomach turn on its own--to have a wizard actively attempting to destroy it further sickens me to no end. We shall make him pay.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1017] = {title = "Mage Summoner", objective = "Slay Sarilus Foulborne and bring his head to Sentinel Velene Starstrike in Silverwind Refuge.", description = "There's only one undead mage in the Barrens capable of defiling this many water elementals. He's also the only one foolish enough to try. Sarilus Foulborne is probably sitting at the top of Dreadmist Peak, laughing at me.\n\n<name>, you must go into enemy territory and destroy this miscreant. I have had enough of his idiocy and we must show him what happens to those who annoy the Sentinels.\n\nDestroy him and bring me his head. Be wary though, the Horde may be watching for you.", progress = "Is it done? Is Sarilus Foulborne dead?", completion = "Now I can see that repugnant smile wiped from his face forever. You have done very well, &lt;name&gt;. Take this, the Light of Elune, drink of it when all seems lost and death is near. It may save you, Goddess willing.", rewards = "You will receive:\n\nLight of Elune"}
MultiLanguageQuestData['en'][1018] = {title = "The New Frontier", objective = "Speak with Arch Druid Hamuul Runetotem on the Elder Rise of Thunder Bluff about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid Hamuul Runetotem on the Elder's Rise of Thunder Bluff for more information!", progress = nil, completion = "Greetings, &lt;class&gt;.\n\nI am pleased to see the likes of you taking an interest in the well being of nature; tales of your mighty deeds precede you, and you are welcomed here.  Seeing you before me instills the feeling of confidence that the Cenarion Circle will get the proper aid it needs.\n\nOur connection with the Cenarion Circle in Moonglade transcends racial and political divides.  Remember this as you work on behalf of the Circle, and you will do well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1019] = {title = "The New Frontier", objective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", progress = nil, completion = "What makes you think I wish to be pestered by the likes of you, &lt;class&gt;?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1020] = {title = "Orendil's Cure", objective = "Bring Orendil's Cure to Pelturas Whitemoon in Astranaar.", description = "<name>, I have created a cure that I believe will help the afflicted child.  Take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south, then east.", progress = "I must apologize, for I have no time to speak.  My child, Relara, is deathly ill!", completion = "This is from Orendil?\n\nHis skill with herbs and healing is great.  This cure gives me hope, when before I had little...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1021] = {title = "Vile Satyr! Dryads in Danger!", objective = "Find Anilia in Xavian.", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n<name>, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", progress = nil, completion = "Judging by the gaping wound in her side, Anilia is on the verge of death.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1022] = {title = "The Howling Vale", objective = "Go to the Howling Vale and study the Tome of Mel'Thandris, then return to Sentinel Melyria Frostshadow at Forest Song.", description = "Though we have put many resources and much effort into driving the remaining demons from the Felwood to the north, our successes have been few. We have been able to keep much of the demonic presence from Ashenvale.\n\nTo the north, near the Felwood border, the ruined shrine of Mel'Thandris has been overtaken by mysterious wolf-men. Their chilling calls have led the area to be known as the Howling Vale. The Tome of Mel'Thandris kept at the shrine may shed some light on why these wolf-men have come.", progress = "The tome of the shrine is a mysterious object. It is not a book in the traditional sense. The leaves of the tome were blessed by Mel'Thandris herself, and records events of import in its pages.\n\nIt is hard for me to explain. If you go to the shrine, you will understand.", completion = "The Tome of Mel'Thandris works in strange ways. The events it records, the events it shows... No one truly understands why it does what it does.\n\nNonetheless, it is clear that what Priestess Starsong received--this Scythe of Elune--bears further investigation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1023] = {title = "Raene's Cleansing", objective = "Find the Glowing Gem and return to Raene Wolfrunner in Astranaar with Teronis' Journal.", description = "As you rummage through Teronis' belongings, you find a journal that is still in good condition.\n\nYou take the journal and leave Teronis' corpse as is.\n\nThe only thing left to do is find the gem Teronis was seeking. Raene mentioned it being in the area. Perhaps the murlocs have it...", progress = "Ah, welcome back, <name>.", completion = "This is terrible, &lt;name&gt;. Teronis is dead?!\n\nThe time for mourning will come, but for now we must focus our efforts. I shall send some of the Sentinels to recover Teronis' body as soon as possible.\n\nYou have Teronis' journal and the gem he was seeking. Do you think you're capable of completing his task? I would rest much better knowing his death was not in vain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1024] = {title = "Raene's Cleansing", objective = "Find Shael'dryn at the moonwell to the northeast.", description = "You'll have to do the research yourself, but from what notes Teronis has made, it sounds like your next course of action is to find the other pieces of the rod Dartol created. I would start by heading to the moonwell east of Iris Lake. When you're ready, follow the road and turn north when you reach a small sitting area on your left.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", progress = "Hello. How are you?", completion = "Oh, Raene sent you? It must be serious indeed. What can I help you with?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1025] = {title = "An Aggressive Defense", objective = "Kill 1 Den Watcher, 2 Ursas, 10 Totemics, and 12 Warriors of the Foulweald tribe, and then return to Raene Wolfrunner in Astranaar.", description = "Before you travel to the moonwell I have another task that will aid the people of Ashenvale if you would like to test your skills.\n\nAlong the road heading east before the Falfarren River, furbolgs have been attacking travelers. Their tortured minds feeding upon fear, and their appetites satiated by the blood of innocents.\n\nAid the Sentinels in protecting the lands by showing those monsters the same mercy they have shown our kind.\n\nI believe their camps are south of the road... be careful.", progress = nil, completion = "You have done well, &lt;name&gt;. Thank you.", rewards = "You will receive:\n\nMoist CornbreadMelon Juice"}
MultiLanguageQuestData['en'][1026] = {title = "Raene's Cleansing", objective = "Find the Wooden Key and a piece of Dartol's Rod before returning to Shael'dryn at the moonwell.", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nIf your goal is to find the next piece of the rod, then you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here, near Felwood. Once you have it, look for a small glade west of the road near the Felwood border... the chest should be hidden around there.", progress = "It upsets me so that the treants have become corrupt. I wish I could do more to help them.", completion = "I'm pleased to see you're back, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1027] = {title = "Raene's Cleansing", objective = "Find the final piece of Dartol's Rod and return to Shael'dryn at the moonwell.", description = "The final piece of the rod was given to the druids of Dor'danil for safekeeping. I have no idea where they hid it. I'm sorry I can't help you more than that.\n\nAll I can tell you is to follow the road that leads towards the Barrens. The druids took shelter to the east of that road, but they won't be of much help to you: they were killed recently... it's something I don't like to think about much.\n\nWhen you find the final piece, bring it to me and I will help you reconstruct the rod.", progress = "Did you find the final piece of the rod, <name>?", completion = "You found the final piece? Wonderful for you... and for Raene.\n\nI guess we'll have to see about repairing it, won't we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1028] = {title = "Raene's Cleansing", objective = "Find the hidden shrine and re-enchant Dartol's Rod.", description = "Here is the completed rod, <name>. Reconstructing it was simple... it's finding the shrine that has the power to recharge it that will be the hard part.\n\nWith some focus and effort it shouldn't be too hard for someone like you, who's already accomplished so much.\n\nHead southeast of here--there are very few paths, so be careful--and keep your eyes to the north. The shrine is hidden within the mountains that surround this glade.\n\nOnce there, place the rod within the shrine... the rest is magic. Hehe.", progress = "You can sense a subtle yet powerful force within the shrine and surrounding trees.\n\nYou begin placing the rod within the shrine and a soft thrumming noise emits from around you as the shrine begins to glow...", completion = "After the glow dies, you can see the re-enchanted rod within the shrine's basin.", rewards = "You will receive:\n\nDartol's Rod of Transformation"}
MultiLanguageQuestData['en'][1029] = {title = "Raene's Cleansing", objective = "Return to Raene Wolfrunner in Astranaar.\n\nProvided item: \n", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nGood luck, <name>.", progress = nil, completion = "You've recreated the rod Teronis had set out to find? That's wonderful to hear.\n\nTeronis would be proud to see his quest is continuing even after his tragic passing.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1030] = {title = "Raene's Cleansing", objective = "Find an uncorrupted furbolg, and using the power of Dartol's Rod of Transformation, speak to him.\n\nProvided item: \n", description = "Alas, I'm not completely certain what he had in mind next.\n\nIf what he said was true about the rod's power, then it will allow you to take on another form altogether. Which form, I do not know.\n\nPerhaps he meant to use its powers to get closer to the tainted furbolgs, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was safe from the effects of Fel Moss.\n\nI would start your search southeast of Mystral Lake.", progress = nil, completion = "Yes, yes... you are one of my kind, but still whole. Still clean.\n\nI am unsure how you have escaped the atrocities the night elves have visited upon our people, but I am glad to know that I am no longer alone.\n\nCorruption now runs through the veins of our kin, young one, corruption brought down upon us by the prideful night elves. They are the ones who did this to our people... They are the ones I blame for being cast out of my tribe.\n\nAt night I can still see the campfires burning in the darkness.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1031] = {title = "The Branch of Cenarius", objective = "Kill Geltharis and return the Branch of Cenarius to Illiyana at Forest Song.", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", progress = "Have you found them? What did Anilia say? Where is she?", completion = "Anilia died? No... that can't be! It was just yesterday that we were running and playing together in the woods.\n\nI guess those days are over...", rewards = "You will be able to choose one of these rewards:\n\nFaerie MantleBrightscale Girdle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1032] = {title = "Satyr Slaying!", objective = "Bring 16 Satyr Horns to Illiyana in Forest Song.", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", progress = "Please, help me avenge Anilia's death.", completion = "Thank you, kind &lt;race&gt;. My sister's spirit is gladdened by your efforts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1033] = {title = "Elune's Tear", objective = "Bring Elune's Tear to Pelturas in Astranaar.", description = "I had hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through my child.  We must find more powerful medicine!  Thankfully, Orendil spoke to me of further remedies to try should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the isle on Iris Lake, east of Astranaar.  Orendil said the stone will wash away corruption... please, <name>, bring me Elune's Tear and pray it will end my child's sickness!", progress = "<name>, did you find Iris Lake?  Do you have the Tear?", completion = "Oh, you found it!  I will place the tear in a stew, and pray that it will cure her.\n\nThank you!  Thank you, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1034] = {title = "The Ruins of Stardust", objective = "Bring 5 Handfuls of Stardust to Pelturas in Astranaar.", description = "Elune's Tear washed clear some of my daughter's sickness.  Her nightmares are lessened and I thank the goddess for her blessing.  But ... fever still rages within her.\n\nOrendil told me of a frosted dust found among the Ruins of Stardust.  Perhaps it will abate Relara's fever.  Gather some of the dust, then please return to me.\n\nThe Ruins of Stardust lie to the south, <name>.  May Elune speed your journey.", progress = "Do you yet have the Stardust, <name>?", completion = "You gathered the dust!  I will create a poultice from these -- it should bring down Relara's fever.\n\nThank you again, &lt;name&gt;.  Without your help, my child would surely perish.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1035] = {title = "Fallen Sky Lake", objective = "Retrieve a Fallen Moonstone from the Shadethicket Oracle, then bring it to Pelturas in Astranaar.", description = "Relara's fever has passed, but she is still very weak.  I do not believe time alone will give her back the strength she has lost.  I believe it will take the power of a moonstone.\n\nWe used to gather moonstones at Fallen Sky Lake to the southeast... until the Shadethickets came.\n\nTheir leader, a Shadethicket Oracle, gathered up all the fallen moonstones and hoards them.  Now, you must retrieve a moonstone from the Oracle.\n\nAnd to do that, I fear that you must slay him.", progress = "Did you face the Shadethicket Oracle, <name>?  If so, then please hand me the fallen moonstone.  Relara has strength left for only a few more breaths!", completion = "Oh, &lt;name&gt;, you have saved my daughter!  I know the power of the moonstone will give back my daughter her strength!\n\nI can never repay you fully for the aid you have given me, but... please, take this.  Other than Relara, it is my most dear possession.", rewards = "You will be able to choose one of these rewards:\n\nSnapbrook ArmorBeastial ManaclesLuminescent Amice\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1036] = {title = "Avast Ye, Scallywag", objective = "Speak with Fleet Master Firallon aboard the Crimson Vale off the coast of Stranglethorn Vale.", description = "<name>... yeah, I've heard of you.  I've heard that you're no friend of Booty Bay - just like us Bloodsail Buccaneers.  Fleet Master Firallon is looking for hale and hearty <men/women> just like you for a special mission.\n\nIf you're interested, head on out to the Crimson Veil and speak with him below decks.  She's anchored off the Wild Coast east of here, next to the Riptide and the Damsel's Luck.", progress = nil, completion = "Avast ye, scallywag.  I hears that ye be the type for a bit o' the skullduggery.  Well, if yer no friend of Booty Bay, then ye might have a special place with the Bloodsail Buccaneers.\n\nArrrrr...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1037] = {title = "Velinde Starsong", objective = "Speak with Thyn'tel Bladeweaver at the Warrior's Terrace in Darnassus.", description = "Velinde Starsong was my predecessor here in Ashenvale Forest. At first it seemed she had the situation in Felwood under control, but little by little her efforts faltered. One day, she simply disappeared.\n\nI was sent here to continue her work. I'm afraid I know nothing of the priestess, however. Perhaps Thyn'tel Bladeweaver, one of the commanders of the Sentinels, knows further details of her disappearance that I was not a party to.\n\nSurely she will understand the import of such information.", progress = nil, completion = "Velinde Starsong? That the priestess disappeared some time ago is almost certainly common knowledge. As to further details about the events that surrounded her departure... it would take good reason for me to divulge such information.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1038] = {title = "Velinde's Effects", objective = "Search through Velinde's chest for her journal, then return it along with the key to Thyn'tel Bladeweaver in Darnassus.", description = "The Tome of Mel'Thandris showed you this? I suppose there would be little harm in allowing you to examine her belongings. This key will allow you to open the chest where we stored her things in the Sentinels' bunkhouse. She kept a journal of her duties, if there is anything to be learned, it will be from that.\n\nI should tell you, the Sentinels believe that she had her own reasons for leaving, and expect that she could return at any time. The priestess has done much in the past to earn our trust.", progress = "What'd you find out?", completion = "It seems that Velinde's disappearance is more troubling than it originally appeared. Even still, I cannot believe that she has come to a bad end. Perhaps it would be beneficial for us to make contact with her.\n\n&lt;name&gt;, since you have shown a vested interest in this matter, I would like to enlist your aid.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1039] = {title = "The Barrens Port", objective = "Speak with Wharfmaster Dizzywig in Ratchet.", description = "Ratchet is the only port in the Barrens. Most likely Velinde found a trading vessel in Ratchet to take her to Blackwater Cove in Azeroth. We've had limited dealings with the goblins that run the port, but the master of the dock should have information about the comings and goings of ship passengers.\n\nFollow the road southeast through Ashenvale and you will find yourself in the Barrens. Watch your step, <name>, warriors of the Horde patrol the land. You will be safe at the port, though.", progress = nil, completion = "&lt;race&gt;, eh? Must admit, we don't get much of your type out here. Looking for someone, eh? Just give me a moment, I'm sure I have it written in one of my ledgers.\n\nLot of people travel through here, though, so just give me a moment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1040] = {title = "Passage to Booty Bay", objective = "Take a boat to Booty Bay and speak with Caravaneer Ruzzgot.", description = "Ah yes, finally found it. Should have told me she passed through here that long ago. Let's see.\n\nVelinde. Booked passage to Booty Bay on the Black Osprey. I don't have anything here saying otherwise, so I'd assume it arrived in port safely.\n\nNot much more help I can be to you, but she asked about overland travel over on that side of the world, and I mentioned Ruzzgot, a caravan driver based out of Booty Bay. Might be that this Velinde traveled with him.\n\nMove along, now. I haven't all day for you.", progress = nil, completion = "Yes? Now, it doesn't look to me like you're the sort with goods that need shipping, so either you're looking for a job with my caravan--and there's no jobs to be had now--or you're probably talking to the wrong goblin.\n\nSo which one is it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1041] = {title = "The Caravan Road", objective = "Speak with Clerk Daltry in Darkshire.", description = "Turns out I was wrong about you, and that isn't something that happens everyday.\n\nIt just so happens that I remember this Velinde you're looking for. Isn't every day that a night elf priestess that wants to travel with a dirty old--but great for your shipping needs!--caravan like my own.\n\nWe split up on the way north, she was headed for Darkshire. The clerk there keeps all sorts of records. Might know something useful.\n\nBe careful in the jungle, it is a deadly place even at the best of times.", progress = nil, completion = "With all the strange happenings of the last few years, I keep as good records of strangers as I can. Never know when it might come in handy... though it's usually not pleasant business when it does. Not to suggest anything about this Velinde you're looking for.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1042] = {title = "The Carevin Family", objective = "Speak with Jonathan Carevin in Darkshire.", description = "No, I don't have any records of a Velinde Starsong staying in Darkshire... though, if you don't mind me saying, I can hardly imagine a night elf priestess taking a room in the inn, if you get my meaning?\n\nThese wolf-men you mentioned though, that's something I've heard about. Just the other day, Calor came into town with a string of their heads. He works with the Carevin family. Hunters of demons, undead, and other monstrosities. Speak with Jonathan, he's the head of the household.", progress = nil, completion = "Dark times these are. Ill news is whispered from every swaying branch, and evil can be found under every rock.\n\nAnd in such times an unknown stranger enters my home and asks of worgen... I'll ask no forgiveness for my suspicions, only answers.\n\nAnd answers, I will have.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1043] = {title = "The Scythe of Elune", objective = "Look for signs of the Scythe of Elune then return to Jonathan Carevin in Darkshire.", description = "Your story rings true... I do not entirely understand your motives, but if your business here in Duskwood involves ridding the forest of worgen in any number, then I can forgo understanding for results.\n\nThere is a mine to the south that has been overrun with worgen... They appeared out of nowhere, but from what we know, that is where they first were found.\n\nGo about your business, but I would ask that if you find anything of import, you share it with me. We will accept any aid in our war against evil.", progress = "The woods are perilous for the unprepared. Keep your weapons close at hand and your wits even closer, or your next journey into the haunted forest may be your last.", completion = "It is an interesting story you tell, &lt;name&gt;. Though the Carevin family's influence is not large enough that we might find the root of these troubles and finish them once and for all, we will do what we can to contain the worgens' numbers in Duskwood.\n\nAlready I have instructed Calor to make this his first priority.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1044] = {title = "Answered Questions", objective = "Return to Thyn'tel Bladeweaver in Darnassus.", description = "We shall rein in the worgen problem, have no worry of that. This evil that your friend introduced to our woods will be contained, and I bear her no ill will for her actions. Strange events are afoot in these times, <name>, and the darkness knows no respite.\n\nI will keep you no longer. I suspect that there are others that should hear of what you have found in the mines of Duskwood.", progress = nil, completion = "So this is the fate of Velinde, is it? The high priestess will be disappointed to hear of this, they were good friends before her disappearance. Still, the Scythe of Elune was surely granted to her as a boon by our goddess, and it is unsettling to me that it has fallen out of her servants' hands.\n\nAnother matter for another time, however. I owe you my thanks in no small amount for what you have accomplished.", rewards = "You will be able to choose one of these rewards:\n\nLunaris BowMoonbeam Wand\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1045] = {title = "Raene's Cleansing", objective = "Kill Ran Bloodtooth and 4 Bloodtooth Guards and return to Krolg near Lake Mystral.", description = "The night elves are as old as time, but their arrogance destroys their very world. And now it destroys our lives too. But that can no longer be controlled...\n\nI blame the elves for much, but we are still responsible for our actions. Even beyond the corruption, we are capable of great evil.\n\nRan Bloodtooth is one such evil. Power hungry, lusting... the corruption has only made him stronger. My hatred for the elves burns, but I do not wish ill upon their children, so we must police our own.", progress = "Have you slain Ran yet, my friend?\n\nEven the Night elves do not truly deserve his wrath. His hatred burns even brighter than my own, but his mind is no longer his own. He is a threat to all the natural creatures of this forest.", completion = "You have done well, my friend.\n\nThe forest is still tainted, but at least we know we have done a small part to return it to its former glory. If you wish to return to me again, I would enjoy the company of my own kind.\n\nBe well. Perhaps our tribes will meet again under less violent times.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1046] = {title = "Raene's Cleansing", objective = "Bring Ran Bloodtooth's Skull and Dartol's Rod of Transformation to Raene Wolfrunner in Astranaar.", description = "Return to your own tribe and let them know of your victory here.\n\nShow them your trophy, and bask in the glory...", progress = "The Sentinels do what they can here in Ashenvale, but it's thanks to humans like you that we have gained the ground we have.", completion = "So, this is the skull of the fiercest furbolg threat in Ashenvale?\n\nI am more than pleased with your abilities, &lt;name&gt;. The Sentinels cannot thank you enough. I hope we can rely on you again in the future to help our people.\n\nI shall put this skull and Dartol's Rod in a place of reverence for others to see.\n\nTeronis would be proud. Thank you again.", rewards = "You will be able to choose one of these rewards:\n\nGlacial StoneGutterblade\n\nYou will also receive:\n\nRing of Pure Silver"}
MultiLanguageQuestData['en'][1047] = {title = "The New Frontier", objective = "Speak with Arch Druid Fandral Staghelm at the Cenarion Enclave of Darnassus about the Cenarion Circle's call to explore the frontiers of Kalimdor.", description = "Attention, heroes!\n\nThe Cenarion Circle seeks able bodied individuals to assist them in exploring the vast new frontiers of Kalimdor!  A forbidden wasteland of unimaginable dangers lies far to the west of Tanaris and Gadgetzan, and the Circle needs willing and honorable proxies to act in their stead.\n\nAll interested individuals should seek audience with the Cenarion Circle.  Speak with the Arch Druid in Darnassus, Fandral Staghelm, for more information!", progress = nil, completion = "What makes you think I wish to be pestered by the likes of you, &lt;class&gt;?  Wait - let me stop the important duties I attend to on a daily basis so I can help you locate a doodad somewhere.  By all means, the welfare of Darnassus - nay, all of Teldrassil - should come second to the acquisition of a bauble for your collection.\n\nThe fools in Moonglade waste my time with their call for assistance, and now I must endure this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1048] = {title = "Into The Scarlet Monastery", objective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity.", description = "Whilst the Dark Lady tends to the pressing issue of the Lich King's advance to the north, I am seeing to it that matters closer to home are being taken care of accordingly.\n\nNo doubt, the human pests who call themselves the Scarlet Crusade are proving to be the sharpest thorn in our side domestically. Tirisfal Glades is literally crawling with the little red ants.\n\nTravel to the Monastery, <class>, and lay waste to High Inquisitor Whitemane and her top lieutenants.", progress = "Perhaps I was not explicit in my orders, <class>. I want High Inquisitor Whitemane killed once and for all. And while you're at it, take out her top brass as well.\n\nKill that zealot, Scarlet Commander Mograine. Lay waste to Herod, the Scarlet Champion. And slaughter Houndmaster Loksey and his filthy mutts too.\n\nNow begone!", completion = "You have served the Dark Lady well, &lt;class&gt;. 'Twas no small task I asked of you.\n\nYour loyalty to the Forsaken has been noted. And your tenacity in combat will be remembered.", rewards = "You will be able to choose one of these rewards:\n\nSword of OmenProphetic CaneDragon's Blood Necklace\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1049] = {title = "Compendium of the Fallen", objective = "\nRetrieve the Compendium of the Fallen from the Monastery in Tirisfal Glades and return to Sage Truthseeker in Thunder Bluff.", description = "The Earthen Ring had pure intentions towards our plagued brethren. But who is to know the motivations of those whispering in the ears of the Elder Council?\n\nThe Forsaken whom we have allied with have a history wrought with deceit. Too hasty was our pact. Perhaps Cairne would have been wise to heed the warnings from Orgrimmar.\n\nDeep within the Scarlet Monastery lies the Compendium of the Fallen, guarded by crazed human zealots. Their method is forged from insanity but their research might prove useful.", progress = "Cairne is a brave and noble leader and I would trust him with my own life. But it is others that I do not trust in this political climate.\n\nOnce I have a chance to gather all the knowledge available I can provide sound council to the Chieftain.\n\nHave you had a chance to travel to Tirisfal Glades? To the Scarlet Monastery? The Compendium of the Fallen is just one piece in this complicated puzzle...", completion = "The Compendium of the Fallen! I was beginning to wonder if the very book existed!\n\nYou have served the tauren of Thunder Bluff well, &lt;name&gt;. Your dedication shall not be forgotten.", rewards = "You will be able to choose one of these rewards:\n\nVile ProtectorForcestone BucklerOmega Orb\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1050] = {title = "Mythology of the Titans", objective = "Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge.", description = "The future is inevitable! We hurl ourselves towards it like falling raindrops to the Great Sea.\n\nBut perhaps, by studying the past, we can know what to expect and be better prepared for the unknown.\n\nBefore dire troubles fell upon Lordaeron, there was a bastion of knowledge tucked away in the Tirisfal Glades. It is rumored that a book called Mythology of the Titans was housed in the library of the old Monastery.\n\nBring it to me and perhaps together we can unlock the secrets of the past!", progress = "The Monastery was a seminary for Paladins-in-training. Once a stronghold of the Light, it fell into the hands of the crazed zealots of the Scarlet Crusade.\n\nThe Crusade believed their goal a noble one: to purify the land of the undead plague. But insanity tainted their plight and now they stand enemies to all.\n\nBring Mythology of the Titans to me so I can study it and house it here in Ironforge.\n\nThe corrupt halls of the Monastery are no place for such a historical treasure.", completion = "You have rescued the sacred text!\n\nYour journey was long and acquiring the book was undoubtedly no easy task. But  the dwarves of Ironforge stand to benefit from your success.\n\nThank you, &lt;name&gt;, on behalf of the Explorers' League.", rewards = "You will receive:\n\nExplorers' League Commendation"}
MultiLanguageQuestData['en'][1051] = {title = "Vorrel's Revenge", objective = "Return Vorrel Sengutz's wedding ring to Monika Sengutz in Tarren Mill.", description = "Even though my will is free, I can serve the Dark Lady no more. I feel my time on Azeroth has come to an end. My life force is shattered.\n\nInterrogator Vishas did this to me! Tortured me for weeks! Took my wedding ring and gave it to his wife. The bastard!\n\nRevenge... I want revenge!\n\nThe pompous fool bragged about his precious wife, Nancy, who lived along Lake Lordamere. Track the wench down, slay her and return my wedding ring to my wife, Monika in Tarren Mill.\n\nHeed my last wishes....", progress = "What do you want, stranger?", completion = "Vorrel led such a troubled existence. And what a good mate he was...\n\nDamn those filthy humans!\n\nVorrel is gone, never to enjoy undeath again. At least I can take solace in the revenge you took in his name. For that I thank you.\n\nNow let me be to mourn....", rewards = "You will be able to choose one of these rewards:\n\nMantle of WoeGrimsteel Cape\n\nYou will also receive:\n\nVorrel's Boots"}
MultiLanguageQuestData['en'][1052] = {title = "Down the Scarlet Path", objective = "Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore.", description = "We of the Scarlet Crusade lay claim to strongholds from Hearthglen to Tirisfal Glades. We are quite proud of our bastions of cleansing throughout Lordaeron.\n\nYou have proven yourself against the undead in Desolace. But the true threat of the plague lies in Lordaeron.\n\nTravel to the town of Southshore, in the Eastern Kingdoms. Seek out a crusader named Raleigh the Devout. Give him this letter of commendation bearing my seal and he will escort you to a place of honor in our Scarlet Monastery.", progress = "Who goes there? What do you want from me?", completion = "Brother Anton still spreads the word of the Scarlet Crusade? Oh my....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1053] = {title = "In the Name of the Light", objective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine,  Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore.", description = "I once served the Scarlet Crusade with honor, loyalty and pride. I believed their cause to be a noble one: to rid Azeroth of the undead.\n\nBut as I spent time at the Monastery in Tirisfal Glades I realized that their grasp on reality was slipping. They now think everyone is plagued who doesn't wear the tabard of the Crusade. Innocent men and women were tortured because they were supposedly plagued. \n\nThe Scarlet Crusade must be crushed in the name of the Light. You, <name>, must destroy the deranged regime.", progress = nil, completion = "While disciples of the Light never revel in the loss of life, we must accept that on occasion, such sacrifices must happen for the greater good of the Kingdom and the planet.\n\nThrough your deeds in the Monastery you have spared many innocent lives, &lt;name&gt;. I salute your tenacity.", rewards = "You will be able to choose one of these rewards:\n\nSword of SerenityBonebiterBlack MenaceOrb of Lorica\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1054] = {title = "Culling the Threat", objective = "Bring Dal Bloodclaw's Skull to Raene Wolfrunner in Astranaar.", description = "Directly to the north of Astranaar are the Thistlefur furbolg. My scouts report that their numbers have grown greatly over the past few months. If they grow too great, they may find the courage to attack Astranaar directly.\n\nKill as many of their kind as you can, but bring me their chieftain's skull as proof that their efforts have been stifled... for now.\n\nI shall remain here in Astranaar and await word from you. Elune be with you.", progress = "The furbolgs' corruption has caused Ashenvale to become a fraction of its former glory.", completion = "Well done, &lt;name&gt;.\n\nWe are under constant threat from the furbolg. Hopefully this will keep them at bay for a bit longer.", rewards = "You will receive:\n\nRestoring Balm"}
MultiLanguageQuestData['en'][1055] = {title = "Raene's Cleansing", objective = "Return to Shael'dryn at the moonwell.", description = "The rod, now complete, lies in your hands. Shael'dryn will want to hear of your success.", progress = nil, completion = "You've done it, &lt;name&gt;! Well done!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1056] = {title = "Journey to Stonetalon Peak", objective = "Travel to Keeper Albagorm on Stonetalon Peak.", description = "The forest spirits tell me you are brave and willing to travel.\n\nTo the south, not far from Mystral Lake, there lies a tunnel named The Talondeep Path. Through this tunnel you will come to an area known as Windshear Crag in the Stonetalon Mountains. Once there, journey to the southwest past Cragpool Lake and then north, up the steep slope until you reach Stonetalon Peak.\n\nThere awaits Keeper Albagorm. Heed his bidding, <race>.\n\nThe journey will be perilous.", progress = nil, completion = "Finally, you arrive. I see Faldreas has listened to the forest spirits....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1057] = {title = "Reclaiming the Charred Vale", objective = "Keeper Albagorm on Stonetalon Peak wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", description = "As a protector of the forest spirits you can undoubtedly guess why I am alarmed.\n\nYou have traveled through these mountains to reach this peak. Surely you have seen the travesty which has befallen the land. Greed has led to the destruction of these sacred hills.\n\nThe Charred Vale to the south was set afire by the greedy mechanized army of industrialists. Worse yet, the Bloodfuries that have encroached on the land refuse us passage in to begin regrowth.\n\nDrive the wretched harpies out, <name>!", progress = "There is much work to be done before the Charred Vale can be restored to the lush forest it once was.\n\nClear the area of those foul menaces, <name>! Only then can we begin to reclaim what belongs to nature.", completion = "Now that the Bloodfuries have suffered such a great loss, perhaps the true work of restoring the land can begin....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1058] = {title = "Jin'Zil's Forest Magic", objective = "Witch Doctor Jin'Zil at Malaka'jin wants 5 portions of Stonetalon Sap, 5 Twilight Whiskers, 30 Courser Eyes and a Fey Dragon Scale.", description = "So excited I am!\n\nThree little cages for three little elves! But what shall we do with our lovely tree-hugging friends? Why, let's give them a taste of... what do they call it... forest magic!\n\nI'll need a good mess of Stonetalon sap. From those horrid felines, bring me some twilight whiskers. This calls for plenty of courser eyes, of course -- can never have enough eyes. Oh, and lest we forget, a precious scale from a fey dragon.\n\nHurry to Stonetalon Peak, <name>, so I can brew some forest magic!", progress = "Look at our poor little elf friends. All caged up with no forest to frolic in!\n\nNow were you able to find me some sap? How about the whiskers from the twilight runners? Don't suppose you have that fey dragon scale on you?\n\nAnd eyes! I'll need so many eyes! You just can't mix up a fierce forest magic brew without a good helping of eyes!", completion = "Oh how happy these little woodland nymphs shall be! We'll make them feel right at home with this special concoction!", rewards = "You will be able to choose one of these rewards:\n\nVoodoo MantleHexed Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1059] = {title = "Reclaiming the Charred Vale", objective = "Travel to Falfindel Waywarder on the border of Thousand Needles and Feralas.", description = "The Bloodfuries have been subdued. But they will regroup soon enough if action is not taken.\n\nFar south of the Barrens lies a land known as Thousand Needles. If you travel west in Thousand Needles until you reach the lush forest's edge of Feralas, you will find a druid named Falfindel Waywarder.\n\nThis great and wise druid is capable of calling forth great forest spirits which can aid in the reclamation of the Charred Vale.\n\nSend word of our need! Seek him out at once!", progress = nil, completion = "Keeper Albagorm was wise to send you with such urgency.\n\nLet us see if we cannot call forth aid from the great forest to travel to the Charred Vale before it is too late.", rewards = "You will be able to choose one of these rewards:\n\nTempered BracersConstable Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1060] = {title = "Letter to Jin'Zil", objective = "Deliver Darsok's letter to Jin'Zil within his cave in Malaka'Jin, in Stonetalon.", description = "You've done so well for me, <name>. You're a regular lucky rabbit's foot and there's something I want you to see.\n\nThe harpies are not from around the Barrens. They come from a place called Stonetalon, far to the northwest of here. Though it is probably a dangerous place for you, I need this letter delivered to an old friend of mine who lives there, a witch doctor by the name of Jin'Zil.\n\nHe'll be happy to know that Serena Bloodfeather is dead, and I think you'll find Stonetalon an interesting place.", progress = "You seem a shady character. You have something for me to see?", completion = "Ahh, a letter from Darsok. I have not heard from him in many years.\n\nSo the last of the Bloodfeathers are dead, eh? That is good news, I can remember when my friend Rokhan went with that crazy mok'nathal to kill her older sister. Ah, to be young again, like you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1061] = {title = "The Spirits of Stonetalon", objective = "Speak with Seereth Stonebreak in the Stonetalon Mountains.", description = "The spirits of the Stonetalon Mountains are angered, for goblins and their servants are plundering and burning the land.  So the land has cried out, and those who listen for such things... have heard.\n\nSeereth Stonebreak, a promising shaman of the Horde, was sent to Stonetalon.  She reports massive deforestation at the hands of the goblins, and requests aid.\n\nMeet Seereth in Stonetalon.  To reach her, follow the road west of the Barrens' Crossroads.  She is camped near the Greatwood Vale.", progress = nil, completion = "Ah, a &lt;class&gt;.  Very good.  We will need your skills to deal with these plunderers!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1062] = {title = "Goblin Invaders", objective = "Kill 15 Venture Co. Loggers, then return to Seereth Stonebreak on the border of Stonetalon and the Barrens.", description = "The goblin-run Venture Company moved into the Stonetalon Mountains, chopping down trees and burning huge stretches of forest.  The spirits of this place are nearly blind with pain and rage.  We must stop the Venture Company!\n\nHead northwest, beyond the Greatwood Vale and into the Windshear Crag.  You will find the goblins and their servants at work--show them the Horde will not allow the exploitation of Stonetalon.  Show them in the language they best understand...\n\nViolence.", progress = "The Greatwood Vale lies to the northwest, <name>.  Go.  Strike fear into those who would pillage this land!", completion = "Bravely done, &lt;name&gt;.\n\nWe may ultimately need the wisdom of tauren elders to calm the spirits of Stonetalon, but...\n\nRidding the Venture Company of its personnel is a good first move against them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1063] = {title = "The Elder Crone", objective = "Speak with Magatha in Thunder Bluff.", description = "To truly tend the spirits of Stonetalon we must consult the tauren elders.\n\nI do not know many of their leaders' names, but I do know of one: Magatha.  I have heard that she is very old, and she knows much.  If anyone can marshal spiritual aid from the tauren, it is she.\n\nMagatha resides in the tauren capital of Thunder Bluff, on Elder Rise -- the city's northeastern bluff.  Speak with Magatha, and tell her of the peril of Stonetalon Mountains.", progress = nil, completion = "I bid you greetings.  You are here seeking counsel?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1064] = {title = "Forsaken Aid", objective = "Speak with Apothecary Zamah in the Pools of Vision in Thunder Bluff.", description = "The tauren have a bond with the land, and it pains me to hear of Stonetalon's plight.  But I fear that to heal the land, we must first remove the disease upon it.\n\nIs it not fortunate, then, that the Forsaken are allied with us?  They know much of disease.  I believe they can aid us, and by doing so they will strengthen the trust between our people.\n\nSpeak with Apothecary Zamah.  She is a scholar and an emissary of the Forsaken.  You will find her in the Pools of Vision below the Spirit Rise.", progress = nil, completion = "Magatha sent word of your coming, &lt;name&gt;.  Although my heart beats no longer, I still feel sorrow for the spirits of Stonetalon.\n\nThe Forsaken are eager to offer what help we can.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1065] = {title = "Journey to Tarren Mill", objective = "Bring Zamah's Note to Apothecary Lydon in Tarren Mill.", description = "To rid Stonetalon of the Venture Company, we must take extreme measures.  Extreme, but without bloodshed.\n\nA colleague of mine may have just the tool we need.  His name is Lydon; he dwells in the town of Tarren Mill in the Hillsbrad Foothills, in the distant land of Lordaeron.\n\nTo reach Hillsbrad, travel by zeppelin to our capital, the Undercity.  Then go north to Tirisfal Glades, southwest to Silverpine, and south to Hillsbrad.\n\nSeek Lydon and bring him this note.  It details our needs to him.", progress = "Ah, are you here with my new test subjects?", completion = "A note from Zamah?  Her needs must be great to send word from so far.  Let us see what she says...\n\nAh, splendid!  I know exactly what to do!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1066] = {title = "Blood of Innocents", objective = "Bring 5 Vials of Innocent Blood to Apothecary Lydon in Tarren Mill.", description = "I will create a toxin to bleed the violence from the Venture Company, rendering them weak and docile.  That should fix the Horde's problem in Stonetalon, yes?\n\nBut to create the toxin, I will need the blood of innocents, a difficult ingredient to obtain.\n\nFortunately the Syndicate, a group of human brigands in this area, employ shadow mages... and those mages collect innocent blood for their own, unsavory purposes.\n\nYou can find the Syndicate shadow mages in Durnholde Keep to the southeast.", progress = "Did you find the Syndicate Shadow Mages, and collect from them the blood?", completion = "Very good!  I trust the Syndicate gave you little trouble?\n\nAs I mentioned, the blood of innocents is not an easy thing to obtain.  We are lucky the Syndicate shadow mages did the difficult work for us.\n\nNow hold a moment while I create my concoction...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1067] = {title = "Return to Thunder Bluff", objective = "Bring Lydon's Toxin to Apothecary Zamah in Thunder Bluff.", description = "Here is the toxin.  If you use it against the Venture Company it should produce favorable, perhaps even contagious, results.  I must say, it is quite exciting to see my work applied in the field!\n\nBut before using it, take it to Apothecary Zamah.  She must create a delivery method for the toxin to maximize its effect.", progress = "You have returned, <name>.  Do you bring aid from Apothecary Lydon?", completion = "A toxin from Apothecary Lydon?  Very good.  If I know Lydon, then this toxin will be quite effective against the Venture Company...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1068] = {title = "Shredding Machines", objective = "Kill the shredders XT:4 and XT:9, then return to Seereth Stonebreak at the border of the Stonetalon Mountains and the Barrens.", description = "There is a relation to the spiritual magic of shaman and the natural magic of druids.  This is why we shaman can hear the plea of the spirits of Stonetalon.  Many of their whisperings are lost to me, but one message, one vision, is clear...\n\nI saw a vision of two man-shaped machines in Windshear Crag, northwest of Greatwood Vale, felling trees with impossible speed.  These metal beasts must be stopped!\n\nIn my vision, the machines were marked with strange symbols:\n\nXT:4 and XT:9.", progress = "The tree spirits wail at the loss of their brethren, <name>.  You must destroy the shredders XT:4 and XT:9, or I fear Stonetalon will never be healed.", completion = "The destruction of the machines XT:4 and XT:9 have soothed many of the spirits of Stonetalon, &lt;name&gt;.  With their loss, let us hope the Venture Company will remove itself from these mountains.\n\nFor if they do not, then I fear the atrocities this place has suffered will pale to what lies ahead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1069] = {title = "Deepmoss Spider Eggs", objective = "Bring 15 Deepmoss Eggs to Mebok Mizzyrix in Ratchet.", description = "Spider egg omelettes are a new fad in Booty Bay!  The problem is... Booty Bay's got no eggs.\n\nI smell an opportunity!\n\nIn Windshear Crag and Sishir Canyon, in the Stonetalon Mountains to the northwest, lives the deepmoss spider.  Bring me its eggs and I'll pay a bundle!\n\nIn Windshear Crag, the eggs will be clustered under what trees remain.\n\nIn Sishir Canyon... well, if you have a weak stomach then maybe you should just collect the eggs at Windshear Crag...", progress = "Did you get the eggs, <name>?  I already made a shipping deal with Wharfmaster Dizzywig!", completion = "You got them!  Thank you!\n\nI'll have these sent to Dizzywig and get them shipped to Booty Bay.  I can already taste the profits!\n\nHere is your cut, &lt;name&gt;.  I couldn't have made this deal without you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1070] = {title = "On Guard in Stonetalon", objective = "Find Kaela Shadowspear overlooking the valley entering Windshear Crag in the Stonetalon Mountains.", description = "Hello, <name>.\n\nYou seem to be full of wanderlust by the looks of you. Have you been to the Stonetalon Mountains? It is a land plagued by the Venture Co. and other enemies of the night elves.\n\nRecently, Sentinel Wolfrunner sent my friend Kaela Shadowspear there to investigate what's happening to the land, but I have yet to hear word back from her. I'm even more concerned because the Alliance sent a gnome mage along with her... a sign of trouble for sure.\n\nWould you find her and report back to me?", progress = nil, completion = "Ah, you've come from Ashenvale at the behest of Tara--how I miss her, my homeland and friends. She must be doing well with the Sentinels to be sequestering adventurers for other tasks. I'm proud of her.\n\nIt is a pleasure to meet you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1071] = {title = "A Gnome's Respite", objective = "Kill 10 Venture Co. Loggers, and 10 Venture Co. Deforesters and return to Gaxim Rustfizzle in Stonetalon.", description = "You see, <name>, I'm a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences, and it's my goal... nay, my DUTY! to show the night elves that a blend of magic, mixtures, and mechanisms can help save their forests.\n\nBut it's a hard fought war, and the goblins reproduce like rabbits it seems. I haven't even had time to build my newest inventions!\n\nI need some time to plan and organize. But to do that, I need your help keeping the goblins at bay in Windshear Crag to the east...", progress = "How goes the battle on your end, <name>?", completion = "Thanks so much for your help, &lt;name&gt;. You're actually back just in time.\n\nI think I've got a perfect plan... explosives. No, that's not the plan, but it's part of the plan.\n\nSee, I've been using high explosives--don't worry, they're not as dangerous as everyone thinks--to scare the goblins back a bit. I can herd 'em pretty good with a few key detonations along the mountains' edges, but I've been low on supplies now for a few days...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1072] = {title = "An Old Colleague", objective = "Speak to Lomac Gearstrip in Ironforge.", description = "The device I'm thinking about is my most advanced version to date. But we'll need a special potion if it's to work. I'm thinking we might as well get the good stuff since this mission could be your last.\n\nAnd for that, we're going to need some potent explosives: Nitromirglyceronium.\n\nThe only person who can make NG-5 is an old friend of mine: Lomac Gearstrip. Look for him in Tinker Town.\n\nYou talk him into making us some NG-5, I'll get to work on placement for my devices.", progress = nil, completion = "Ahhh.... Gaxim sent you, huh? How do I know you're not lying to me?! Hmm? Hmm...?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1073] = {title = "Ineptitude + Chemicals = Fun", objective = "Bring 4 Minor Mana Potions and 2 Elixirs of Minor Fortitude to Lomac Gearstrip in Ironforge.", description = "Hahaha... you need Nitromirglyceronium to stop goblins from destroying a forest?!\n\nI don't care if you know Gaxim or not... I'll give you the stuff just to see you or them explode into itty bitty pieces.\n\nThere's a problem though: I'm all out.\n\nBut I'll tell you what, you bring me the correct potions, and I'll make some up for you right away.\n\nThe least you can do is prove you've got some skill as an alchemist before I just give you a sample of my greatest creation.", progress = "I can't make any Nitromirglyceronium if I don't have the potions... they're vital to its creation.", completion = "This'll do nicely.\n\nIf I didn't know better, stranger, I'd say you knew somethin' about alchemy. Good, good... the world's not all about swords and sorcery, you know?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1074] = {title = "Ineptitude + Chemicals = Fun", objective = "Bring the Nitromirglyceronium back to Gaxim Rustfizzle in Stonetalon.", description = "Here you go, stranger. Take heed with it though... it's volatile stuff.\n\nIf you're really a friend of Gaxim's, then tell him I say hello. If you're not, then have fun blowin' yerself up.", progress = "Ah, goodie goodie, you're back.", completion = "Your task has been done flawlessly, &lt;name&gt;.\n\nNG-5 is the unequivocal component in the recipe to ignite the wagons of dynamite.\n\nWhat? Yes, dynamite... wagons of it. It's the perfect distraction, I tell you... just wait and see.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1075] = {title = "A Scroll from Mauren", objective = "Find Collin Mauren in Stormwind.", description = "Okay, now for the remote detonation part of my plan... oh, I haven't explained that yet, have I?\n\nOkay, so the short of it is this: with a little magic, I can make it so the explosives go off while you're not around. I'm putting together a device that'll allow you to push just one button and have the NG-5 explode when you're ready.\n\nBut I need a spell from a friend in Stormwind--Collin Mauren is his name. You can find him in the mage quarter there. He's human, so he shouldn't be hard to miss.", progress = nil, completion = "Now, this spell you need; one that will allow you detonate explosives from a distance... hmmm.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1076] = {title = "Devils in Westfall", objective = "Bring Dust Devil Debris to Collin Mauren in Stormwind.", description = "Ah, I think I have it. A messaging spell... I believe that's the effect he's looking for.\n\nI'll have to create a scroll with the spell impressed upon it. To do that I'll need debris from a dust devil.\n\nWhile I gather the rest of the components, why don't you head to Westfall and find one of the foul creatures? They are dangerous, but I'm sure it's nothing you can't handle if you're willing to subject yourself to one of Gaxim's experiments.\n\nI'll be here when you return.", progress = "Hello, <name>. Have you found the component I need?", completion = "Allow me just a few moments and I shall have your scroll ready for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1077] = {title = "Special Delivery for Gaxim", objective = "Bring the Scroll of Messaging to Gaxim Rustfizzle in Stonetalon.", description = "Here you are, <name>. This should do nicely.\n\nPlease give my regards to Gaxim when next you see him. I look forward to hearing about this adventure when it sees its completion.\n\nFare well.", progress = "Haha! you're back! Do you have it? Do you have the spell?", completion = "This is perfect, &lt;name&gt;! Well done.\n\nThis spell, mixed with the NG-5, shall make the perfect remote explosive.\n\nWe'll be able to create the perfect distraction for you so you can sneak in and steal the Venture Co.'s letters and engineering plans.\n\nThat will surely slow down their deforestation acts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1078] = {title = "Retrieval for Mauren", objective = "Bring 8 Crystalized Scales to Collin Mauren in Stormwind.", description = "Travelers keep asking me about the Stonetalon Mountains. It seems to be a popular place for adventure--it doesn't matter if you're seeking wyvern, elementals, or you have business with the Venture Co.\n\nWithin the Charred Vale, deep in Stonetalon, there used to be a species of basilisks whose scales, when ground to dust, made a wonderful reagent for some spells I've created.\n\nIf those basilisks still live, I would love to have a few of their scales.\n\nTake your time, it is no rush, but I can pay well.", progress = "Hello again, <name>.\n\nHave you already returned from the Vale in Stonetalon with those scales?", completion = "This is perfect, &lt;name&gt;. Thank you greatly.\n\nPerhaps one day in the future I'll be able to help you as you have helped me.", rewards = "You will receive:\n\nSpellcrafter Wand"}
MultiLanguageQuestData['en'][1079] = {title = "Covert Ops - Alpha", objective = "Retrieve the Venture Co.'s Engineering Plans from the lumber mill in Windshear Crag.", description = "This is it, <name>. Pay close attention. The devices are done, and ready to be used.\n\nTake these pages--they'll explain more about the detonators and explosives, and where you should place them.\n\nRemember, the success of your mission doesn't depend on how much destruction you cause. Plan Alpha's success depends on you bringing back the Venture Co.'s engineering plans from inside the lumber mill south of Cragpool Lake.", progress = "Did you get the plans, <name>?", completion = "Truly amazing! This is a huge blow to the Venture Co.\n\nWe'll be able to find weaknesses in their machines and also incorporate their designs into our own creations. This is a wonderful day, indeed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1080] = {title = "Covert Ops - Beta", objective = "Retrieve the Venture Co. Letters from Windshear Mine at the east end of Windshear Crag.", description = "Plan Beta's just like Plan Alpha, <name>.\n\nWe cause a distraction and then steal their precious letters.\n\nThe key is to get their letters... remember that.\n\nThe pages I gave you already will tell you where to plant the explosives. Just get back here alive and with those letters....", progress = "How'd it go, <name>?", completion = "Incredible, &lt;name&gt;! Kaela and the Sentinels will be so happy. With your skill and my creations, we're unstoppable.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1081] = {title = "Reception from Tyrande", objective = "Find Tyrande Whisperwind in Darnassus.", description = "<name>, I am sure Tyrande Whisperwind herself would like to thank you for taking part in this mission.\n\nIt may not appear so on the surface, but what you've helped start could very well strengthen our foothold in the Stonetalon Mountains.\n\nIf you consider yourself our ally against these atrocities, go see Tyrande in the Temple of the Moon in Darnassus.", progress = nil, completion = "Hello, &lt;name&gt;. I have indeed heard your name before, and although you are still full of youth, I am pleased to see the path you have set for yourself.\n\nYou would do me a great honor if you would accept this as a gift of appreciation.", rewards = "You will be able to choose one of these rewards:\n\nEfflorescent RobeGrizzly TunicWildwood Chain\n\nYou will also receive:\n\nBand of Elven Grace"}
MultiLanguageQuestData['en'][1082] = {title = "Update for Sentinel Thenysil", objective = "Return to Sentinel Thenysil in Ashenvale.", description = "<name>, you have done a great deed by lending a hand here.\n\nThe Sentinels of Ashenvale will reward you well if you informed them that Gaxim and I are alive. Tell them we are well on our way to stopping the Venture Co. and healing the lands.\n\nFind Tara Thenysil in Astranaar; she will be pleased to see you've returned with good news.", progress = nil, completion = "Thank you, &lt;name&gt;. You have done a service to the Sentinels.\n\nI'm glad to see Kaela... and even Gaxim, are doing well.\n\nYou've earned our appreciation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1083] = {title = "Enraged Spirits", objective = "Bring 8 Smoldering Embers from any of the fire elementals in the Charred Vale to Kaela Shadowspear in Stonetalon.", description = "I'm unsure what the Venture Co. did to the Vale, but it's obvious they were overpowered by the creatures there.\n\nThey set the forest aflame, and used their inventions of destruction to decimate as much of the Vale as possible.\n\nBut in their ignorance they also released something else: burning spirits, elementals of flame, stone and rage.\n\nThe land has no chance to see Elune's smile while these creatures roam free.\n\nBring me their smoldering embers to show you've reduced their numbers.", progress = "The first time I saw the Charred Vale I almost wept, <name>.", completion = "The remains of our enemy... your strength serves us well, &lt;name&gt;. Thank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1084] = {title = "Wounded Ancients", objective = "Bring a piece of Corroded Shrapnel to Kaela Shadowspear in Stonetalon.", description = "It seems obvious to me that the protectors of the Vale--the treants--had something to do with the Venture Co. being driven back. Unfortunately, even those once great guardians have now become corrupt.\n\nGaxim thinks their corruption is somehow linked to the weapons the goblins used during their retreat.\n\nI told him I'd collect a sample from a wounded treant and allow him to study it in order to figure out if that's true.\n\nBring me some of the shrapnel so the gnome can tell me more...", progress = "I have a feeling Gaxim will find a use for the shrapnel regardless of how the Venture Co. has used it in the past.", completion = "Thank you, &lt;name&gt;.\n\nThis should be more than sufficient for Gaxim to figure out how the treants were corrupted. I shall give this to him right away.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1085] = {title = "On Guard in Stonetalon", objective = "Speak to Gaxim.", description = "The situation here in Stonetalon is obviously grave for a night elf and gnome to be working together.\n\nThe Venture Co. has devastated these lands and I've spent most of my time putting an end to the destruction.\n\nDo not judge Gaxim prematurely; he understands the need for us to work together.\n\nIf you wish to aid us, then start by speaking to Gaxim.\n\nI'm sorry I cannot send you back to Tara with good news yet. Perhaps soon.", progress = nil, completion = "Treacherous... treacherous and dangerous, that's what this land is.\n\nBut I'm here to show the night elves that it's a little safer with the help of good ole engineering and a dash of magic.\n\nSee, swearing off magic completely won't help the night elves--they need it. The world needs it. And with engineering and alchemy to boot, you can't go wrong. The possibilities are endless.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1086] = {title = "The Flying Machine Airport", objective = "Bring the Toxic Fogger to the Venture Co. sky port, then return to Apothecary Zamah.", description = "The toxin is ready.  All that remains is its delivery.  You, <name>, must make that delivery.\n\nThe Venture Company must have a means of sending messages and light cargo between its headquarters and its operations in Stonetalon.  It is likely a small sky port -- not big enough for a zeppelin, but perhaps for a flying machine.  You must search the areas in Stonetalon under control of the Venture Company and find this sky port, if it exists.  If you find it, then place the toxin there.\n\nPlace it, and run.", progress = "You must find the Venture Company airport if it exists, <name>.", completion = "You found the port?  Well done, &lt;name&gt;!  I am sure the goblins were quite surprised from your delivery!  Let us hope that toxin finds its way to their headquarters.\n\nYou have served your people well, and I advise you to ignore any guilt you might harbor for poisoning the Venture Company.  They are deserving of far worse.\n\nAnd if there is one mote of wisdom the Forsaken might teach its allies, it is this:\n\nDo not shy from dark paths... if those paths lead to victory.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1087] = {title = "Cenarius' Legacy", objective = "Kill 4 Sons of Cenarius, 4 Daughters of Cenarius and 4 Cenarion Botanists for Braelyn Firehand near Sun Rock Retreat.", description = "You cannot imagine the hatred I possess for this wretched land. The ilk of Cenarius and the kaldorei druids at the peak employ their pathetic powers to stifle the flow of magic, even so far south of their pathetic holdings... their beloved forests.\n\nWould that I could return to Jaedenar and exult in the flow of magic, but my master will not allow me to return until my work is done.\n\nI have no doubt you love the night elves and their allies as little as I. Aid me, and both our ends might be satisfied.", progress = "Here, channeling magic is like drawing water from a well with a bucket full of holes.", completion = "Already I can feel it... yes... power so sweet... the rushing flood. The kaldorei are foolish to spurn the gifts of this world, to reject the coursing of magic as it flows singing through your veins.\n\nWhat a pale mockery life is without its burning embrace!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1088] = {title = "Ordanus", objective = "Bring Ordanus' head to Braelyn Firehand near Sun Rock Retreat.", description = "They thought that they could halt the flow of magic. They were mistaken. They thought that they could hide Ordanus, but I will have his head!\n\nMagic grants me true sight. Yes... there he is. A crossroads... At the top of a great tree in Ashenvale Forest. A name... Raynewood. One of the eldest sons of the forest god. They spirited him away from the peak before I could find him, but his time runs short.\n\nBring it to me and I will share with you a mighty gift.", progress = "When my master bade me to the peak of Stonetalon, I expected that all I would need was to lay waste to the night elves that crawled the sacred ruins of our ancient temple of Azshara, their touch despoiling its sanctity... but Ordanus had slipped my grasp.", completion = "I knew Ordanus once, long ago. He had the arrogance of his kind, holding himself above even the Highborne.\n\nHis head does not rise so high now, does it, &lt;name&gt;?\n\nI promised you a reward, and you shall have it. Attend to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1089] = {title = "The Den", objective = "Travel to the Den on Stonetalon Peak. Using the Gatekeeper's Key, obtain the druids' hidden items. Use these items to open the Talon Den Hoard.", description = "The druids built the Talon Den on Stonetalon Peak, where they keep many powerful items.\n\nThey devised a complex scheme to keep them from falling into the wrong hands.\n\nLuckily, I managed to... extract some details from one of them.\n\nHidden in a small lantern at the entrance of the Den, you will find the Gatekeeper's Key--with it you will be able to open caches around the Den. The items from these caches will allow you to open their hoard, located in one of the central areas.", progress = "Three keyholes are carved into the stone.", completion = "As the three keys are slid into their matching openings, in the middle of the glowing light a number of items appear.", rewards = "You will receive:\n\nSacred BandPanther ArmorJuggernaut Leggings"}
MultiLanguageQuestData['en'][1090] = {title = "Gerenzo's Orders", objective = "Get the mysterious ore from Piznik after he finishes mining it.", description = "You know, I was once the second most important person here at this site. That all changed when Gerenzo took over. Fired my boss, Ziz Fizziks, and sent me down to work in the mines. Ziz told me to stay here and gather information, though. His new boss will pay us well if we can find out what Gerenzo's plans are.\n\nAnyways, what I do know is that Gerenzo has ordered large amounts of this gold-green ore to be mined. I can get you a sample to bring to Ziz, but you'll have to watch for patrols while I get it.", progress = "Look out, there are patrols and workers constantly walking by this area, and it might get ugly if we get caught.", completion = "Thanks, &lt;name&gt;. It was looking a little dicey there for a second and we've probably drawn far too much attention to ourselves.\n\nThe important part is that we have the ore sample, though, and we should get it to Ziz as soon as possible.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1091] = {title = "Kaela's Update", objective = "Bring the Venture Co. Letters to Kaela Shadowspear.", description = "<name>, take these letters to Kaela. I'm sure she'll want to know about this. Or at least the Sentinels will.\n\nMake sure you tell her how successful we were and how we couldn't have done it without a little bit of magic.", progress = "Yes, <name>? What can I do for you?", completion = "This is interesting indeed.\n\nYou and Gaxim have done very well, &lt;name&gt;. Thank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1092] = {title = "Gerenzo's Orders", objective = "Deliver the Unidentified Ore to Ziz Fizziks in the Stonetalon Mountains.", description = "I guess I'd better think about getting out of here, also. It won't take long for word of what happened here to spread to the higher ups, and I'm sure they wouldn't take too kindly to meeting me again.\n\nI'll sneak out and meet with Ziz. Hopefully, he'll be able to find me a new job!\n\nI'll try and clean up this mess a little, but you should take the ore sample to Ziz right away. He told me that he'd set up camp somewhere on the western side of Windshear Crag. Good luck.", progress = "Something I can help you with?", completion = "Ahhh, I knew that I did the right thing by telling Piznik to stay behind. I'm sure the engineers in Undermine will be most interested to look at this...\n\nOf course I'll want to keep a little piece for myself, but what they don't know won't hurt them, yes?", rewards = "You will receive:\n\nDredge Boots"}
MultiLanguageQuestData['en'][1093] = {title = "Super Reaper 6000", objective = "Get the Super Reaper 6000 Blueprints for Ziz Fizziks in the Stonetalon Mountains.", description = "Terrible what the Venture Company has done here, eh? What were they thinking? Goblin company hiring a gnome!\n\nLucky for me, Sputtervalve knows a genius when he sees one. Hired me just after I'd been kicked out!\n\nTells me they built some enormous woodcutting machine, and Sput' wants me to steal the plans for him. Unfortunately, Gerenzo--bloody gnome--wants me dead on sight... maybe you could steal the plans for me? You should be able to find them on one of their operators.", progress = "Did you find those plans? I'm eager to impress the new boss. Hopefully, once he's convinced of my loyalty--well, as much as he can be convinced... goblin's honor, you know?--he'll feel comfortable making use of my rather impressive genius.", completion = "Hey, is that what I think it is? Great!\n\nNow, let's see. Ugh... how am I supposed to understand this stuff... can't figure out the way gnomes think. Lemme tell you, I'm surprised they could build the wheel, let alone those flying machines they like so much.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1094] = {title = "Further Instructions", objective = "Deliver the Sealed Envelope to Sputtervalve in the Barrens.", description = "This envelope has all the information I was able to snatch as they booted me out the door... Venture Company internal documents, some manuals, technical things... Oh, and of course the Super Reaper 6000 blueprints.\n\nSputtervalve has taken up residence at Ratchet in the Barrens. Shouldn't have much trouble finding him, he's a little green fellow.", progress = "Hello there! How can I help you?", completion = "Fizziks, eh? Can't say I trust him, but this information seems good enough. What I wouldn't give to have the Venture Company out of my hair.\n\nThey do come up with some good machines though... I can't deny that we've benefited from using some of the improvements they've devised.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1095] = {title = "Further Instructions", objective = "Bring the new orders to Ziz Fizziks in the Stonetalon Mountains.", description = "The matter of this gnome that has been hired by the Venture Company has caused a bit of a stir in Undermine. The trade princes do not approve of Razdunk's consorting with this Gerenzo.\n\nRiddlevox has asked me to take care of the problem, and I'm sure he was instructed to do so by one or more of the trade princes. Of course, the Director didn't tell me that. Let's just say I have a hunch.\n\nWhatever the case, Gerenzo must be removed, and it would be a fitting test to have Fizziks take care of him.", progress = nil, completion = "Eliminate Gerenzo? Now there is a prospect that I have no objections to.\n\nGnomes are bad enough as it is, but what I learned about Gerenzo only makes it worse. Apparently, he was one of the head engineers in Gnomeregan, where he was working on their secret project--we could never infiltrate Dun Morogh well enough to find out specific details. It was a failure. Our reports say that whatever it was literally exploded in their faces.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1096] = {title = "Gerenzo Wrenchwhistle", objective = "Bring Gerenzo Wrenchwhistle's Mechanical Arm to Ziz Fizziks in the Stonetalon Mountains.", description = "I met Gerenzo once, but let me tell you, he's not easy on the eyes. His flesh looks like it's rotting away, and he's grafted metal and gears onto his body, replaced some of his limbs with mechanical ones.\n\nNortheast of here, far above Cragpool Lake, up near the water wheel is where Gerenzo watches over the entire site. There's no way I could fight my way up there, not to mention take on Gerenzo... But you look like you might be able to make it.\n\nIf you kill him for me, I'll make it worth your while!", progress = "Sputtervalve will want some sort of proof that Gerenzo's dead. I think his mechanical arm will probably do.", completion = "Look at that thing... it'd take a gnome to come up with something like that. I can't understand why you'd cut off an arm, and replace it with that, when you could just keep both arms and add a third!\n\nGnomes, I tell you...\n\nAt least Gerenzo's out of commission. Hopefully that'll be enough proof, and Sputtervalve will assign me to one of the Tinkers' Union workshops in Gadgetzan or maybe even Undermine.", rewards = "You will be able to choose one of these rewards:\n\nEngineer's CloakDraftsman Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1097] = {title = "Elmore's Task", objective = "Speak with Grimand Elmore.", description = "There's a dwarven weaponsmith in Stormwind, Grimand Elmore, who sent word that he needs help with a delivery.  I believe he wants a package sent to his homeland in the north.\n\nYou have a sturdy pair on you!  So if you're interested in some legwork then speak with Grimand.  We could use you down here, but we must also keep our ties strong with the dwarves.\n\nYou can find Grimand Elmore at the weapon shop in the Dwarven District of Stormwind, in the northeast section of town.", progress = nil, completion = "You're here to help with my delivery?  Very good!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1098] = {title = "Deathstalkers in Shadowfang", objective = "Find the Deathstalker Adamant and Deathstalker Vincent.", description = "In preparation for an assault on Shadowfang, two deathstalkers were sent to the keep to gather intelligence.  It has been many days and they have not returned, but we must receive their report if we're to have any hope of a successful attack!\n\nSo here is your task, <name>.  Go to Shadowfang Keep to the south and find the Deathstalkers Adamant and Vincent.  Find them, and if they require aid then give it.\n\nThis mission is as dangerous as is it critical, <name>.  Do not fail.", progress = nil, completion = "Vincent's body lies broken, and still.\n\nAlthough Deathstalker Adamant will send his report to Hadrec... whatever additional details Vincent gained must remain with him.\n\nBut clutched in his hand is a small trinket...", rewards = "You will receive:\n\nGhostly Mantle"}
MultiLanguageQuestData['en'][1099] = {title = "Goblins Win!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGoblin Prize Box"}
MultiLanguageQuestData['en'][1100] = {title = "Lonebrow's Journal", objective = "Read Henrig Lonebrow's Journal.", description = "You slowly open the weathered journal of Henrig Lonebrow....", progress = "From your look of concern, I can tell that something is amiss....", completion = "You say you found this journal on a deceased dwarf? Give me but a moment to peruse the pages...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1101] = {title = "The Crone of the Kraul", objective = "Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar.", description = "Poor Heralath! And this dwarf... Lonebrow. What a brave soul he was.\n\nWe must not let their valiance go for naught. This crone... Charlga Razorflank ... must be stopped.\n\nSurely, infiltrating the Kraul will be perilous. There isn't time to send word to Darnassus. <name>, assemble a party to slay the crone.\n\nBring me Razorflank's Medallion as proof of demise.", progress = "So long as Charlga Razorflank is mustering a force in Razorfen Kraul, these lands are in great danger.", completion = "The crone has been laid to rest. This is fantastic news, &lt;name&gt;.\n\nIn these times of peril, it is refreshing to see one as brave as yourself.\n\nWith Razorflank's minions taken care of, our studies in the area can continue. Perhaps now we can gain further knowledge of exactly what happened to corrupt the resting place of Agamaggan.\n\nHowever, I fear the answer to that question lies in treachery as well...", rewards = "You will be able to choose one of these rewards:\n\nBerylline PadsStonefist GirdleMarbled Buckler\n\nYou will also receive:\n\nFalfindel's Blaster"}
MultiLanguageQuestData['en'][1102] = {title = "A Vengeful Fate", objective = "Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff.", description = "Cairne is a noble leader for uniting our people here on Thunder Bluff.\n\nBut I cannot forgive those who drove us from our ancestral lands as easily as some. My people inhabited the southern Barrens for decades. The land was holy to us. But we were driven off by numerous foes.\n\nA vengeful fate awaits the crone, Charlga Razorflank, who musters a foul army from within Razorfen Kraul.\n\nBring me Razorflank's heart and I can die in peace, <name>.", progress = "Once I know the foul beasts of Razorfen Kraul have been driven from their foul lair, I will be able to rest in peace, knowing that revenge has been served.\n\nHave you the driven the quilboar from the Kraul? Do you bring to me good news in the form of Razorflank's heart?", completion = "I see the nasty tribe of Razorfen Kraul now knows the pain of my people. Serves the foul beasts right.\n\nTo drive one from a holy land is a sin worthy of the most severe revenge.\n\nThank you, &lt;name&gt;, for aiding me in my plight.", rewards = "You will be able to choose one of these rewards:\n\nBerylline PadsStonefist GirdleMarbled Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1103] = {title = "Call of Water", objective = "Bring a Water Sapta to Tiev Mordune in Silverpine Forest if you failed to speak to the Minor Manifestation of Water.", description = "Greetin's, <brotha/sista>! Have you too come to purify the waters here and prove your understandin' to Islen?\n\nI've just defeated the corrupt water spirit meself, and I'm just 'bout to put da bracers and remaining drops o' water on the brazier.\n\nWhat's dat? Ahhh. Tiev understan' all too well when somethin' goes wrong. Well, Tiev can help you plenty if you be needin' to see the pure water spirit again.\n\nBring me a water sapta from Islen as proof that you be ready, an' I'll wait to turn in me parts.", progress = "Ya have the sapta, brotha?\n\nI know another that had trouble after defeating da corrupt water spirit--seems he waited too long and he came out of the spirit world too quick fer his taste. Hate to see dat happen to another, so I'll just wait here fer a bit to make sure no one else be needin' me help.", completion = "Ahhh, den yur ready...\n\nI'll put me items in the brazier den, and you c'n talk wit' da spirit too.\n\nAn' dontchu worry none 'bout seein' into da spirit world wit' da sapta... ol' Tiev know a trick or two 'bout how da sapta magic works.\n\nCome now, head down wit' me to the shrine and let's speak to da spirits together, brotha.", rewards = nil}
MultiLanguageQuestData['en'][1104] = {title = "Salt Flat Venom", objective = "Bring 6 Salty Scorpid Venoms to Fizzle Brassbolts in the Shimmering Flats.", description = "I have so many designs for our rocket car!  So many!  And I must try them all!!\n\nI'm working on a new type of fuel.  One that burns really really really hot!!  I haven't gotten the mixture perfect, but I think I know what I need...\n\nThe scorpids who wander the Shimmering Flats have a venom with lots and lots of salt in it.  It's very unique!  And it's just what I need!\n\nBring me venom and trust me -- our car will fly!!", progress = "Hi hi hi!  Did you get that venom??", completion = "All right!  This venom is going to work great!  Thanks, &lt;name&gt;!\n\nNow I just need to boil it down, apply skipper-otomer, add a nega-catalyst, and... Drat!  Where are my notes!?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1105] = {title = "Hardened Shells", objective = "Bring 9 Hardened Tortoise Shells to Wizzle Brassbolts in the Shimmering Flats.", description = "My brother is working on a new fuel for his rocket car.  He's brilliant, he really is.  So brilliant that... I think that new fuel he's designing is strong enough to eat right through the car's chassis!\n\nI want to reinforce its fuel tanks before that happens.\n\nThe tortoises out on the flats have very hard shells.  I want to use them to create new tanks for our rocket car.  Tanks that can hold my brother's new fuel.\n\nYou look responsible enough.  Will you get me those shells?", progress = "My brother is making progress with his new fuel design, and that has me worried.  I need to start work on a tortoise shell fuel tank as soon as possible!\n\n<name>, do you have those shells yet?", completion = "You got them!  Thanks, &lt;name&gt;!\n\nWow, these shells are harder than I thought!  Heh, when I work with them I'll probably bend a whole box full of tools!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1106] = {title = "Martek the Exiled", objective = "Bring Fizzle's Letter to Martek the Exiled in the Badlands.", description = "I'm developing a new engine that'll make the car go so fast!  Fast enough to fly, I know it!  I just need to make pistons that can handle very very heavy stress.  All my trials have failed because I can't make pistons hard enough!\n\nBut there is someone who might know how.\n\nHis name is Martek the Exiled.  He is a great smith and knows more about metal than anyone.  Take him this letter, I know he can help!\n\nBut he's far far away -- in Azeroth, in the Badlands, in a camp, with a goblin!\n\nFind him!", progress = "Well, you found me.  Good for you.\n\nAre you here about that axe I made for Gath'Ilzogg?  Or are you here to reclaim Duchess Pamay's honor?\n\nActually, I don't care which it is.  If you're here to fight, then let's get it over with...", completion = "Fizzle sent you?  Well that changes things!  Of course I'll help you.  Fizzle and his brother are two of the few people who don't want me dead!\n\nSo Fizzle wants to make pistons, eh?  Pistons strong enough to take whatever stresses he has planned, and if I know Fizzle, then this new car of his is a volcano on wheels!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1107] = {title = "Encrusted Tail Fins", objective = "Bring 10 Encrusted Tail Fins to Wizzle Brassbolts in the Shimmering Flats.", description = "Our rocket car is the fastest thing on the flats!  So fast that ... I'm afraid friction is going to tear it apart!\n\nTo prevent that I need to create a composite to coat the car's moving parts.  It must be hard but not brittle, and must be resistant to salt corrosion, or time spent on the Shimmering Flats will eat it away.\n\nHave you heard of the Vile Reef, <name>?  It's off the coast of Stranglethorn Vale.  Saltscale murlocs live there, and their tail fins are a crucial ingredient of my composite.", progress = "Do you have the tail fins?  If I can't protect our car from its own speed, then it won't last long in these races.", completion = "Thank you, &lt;name&gt;!  After I grind these down and fuse them with a few other ingredients, the composite will be ready.  And after that, the car will be safe from its own speed.\n\nSafe, as long as it doesn't hit anything...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1108] = {title = "Indurium", objective = "Bring 10 Indurium Flakes to Martek the Exiled in the Badlands.", description = "I'm not out here just to stay away from people.  There is a wealth of metal in the Badlands, <name>, if you have the guts to get it.\n\nThe metal's called indurium and as luck would have it, it is rumored to possess high resistance to heat and stress.  It might work for Fizzle's car.\n\nBut let's make sure.  Get me samples of indurium and I'll test its properties.\n\nTrue indurium ore lies deep in Uldaman, but the Stonevault troggs of the Badlands sometimes have flakes of it on them.  Bring me those flakes.", progress = "Did you find any indurium flakes, <name>.  I have my forge heated up and ready to test them.", completion = "Ah yes, these will do fine.  Now let's put them in some heat and see how they fare...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1109] = {title = "Going, Going, Guano!", objective = "Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity.", description = "As you can see, <name>, we're up to some very.... interesting experiments at the Royal Apothecary Society.\n\nAs the Master here, it is my job to oversee the most ambitious of our alchemical attempts. So much work and so little time!\n\nYou look well traveled for a <class>. Perhaps you can aid me.\n\nI'm in need of a rare substance. It's foul material; it comes from a rare species of bats only found in the muck-hole known as Razorfen Kraul. Bring to me the guano from the Kraul Bats so we can begin our work...", progress = "Ah, I see you have returned. Were you able to procure any Kraul Guano?", completion = "Splendid! This is just the start we needed, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1110] = {title = "Rocket Car Parts", objective = "Bring 30 Rocket Car Parts to Kravel Koalbeard in the Shimmering Flats.", description = "Heh heh, with all the races they're running here, it's no surprise that a few mishaps happen along the way.  If you look around the Shimmering Flats then you'll see evidence of past crashes -- scraps of rocket car parts are littered everywhere!\n\nAnd those parts are worth money to the gnomes and goblins.  They're always looking for more contraptions to slap onto their cars.\n\nSo go out and get me parts.  Bring me a heap and I'll pay you well.", progress = "<name>, have you been out into the Flats?  Did you bring back that load of parts I wanted?", completion = "Whoa, look at all that!  There's some good stuff in that heap of junk.  I'm sure I can pawn it off for a hefty sum.\n\nAnd... is that an ear I see squashed between those two sheets of metal??  Ouch!  Heh, I sure wouldn't want to be that pilot!\n\nThanks, &lt;name&gt;.  Here's your pay.  And here's some advice, free of charge...\n\nIf you look hard enough, you can always find profit in someone else's tragedy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1111] = {title = "Wharfmaster Dizzywig", objective = "Bring Kravel's Parts Order to Wharfmaster Dizzywig in Ratchet.", description = "I make it my job to get people what they need, and the gnomes over there need a parts order filled.  Their parts were shipped to Ratchet a week ago, but I haven't been able to make the trip.\n\nSo, are you ready for some legwork?  Go to Ratchet and give this parts order to Wharfmaster Dizzywig -- he'll probably be at the docks.\n\nDo this for me, and I'll have more jobs for you.\n\nJobs, my friend, with serious profit potential...", progress = "Speak up!  Tell me, are you dropping off or picking up?", completion = "Oh yes.  Parts for Kravel.  I'm glad you're here.  These things have been sitting out here for days, and I was afraid they'd rust!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1112] = {title = "Parts for Kravel", objective = "Bring Kravel's Parts to Kravel Koalbeard in the Shimmering Flats.", description = "Here's Kravel's package, <name>.  And when you deliver it, tell him... if he wants more special orders, then he'll have to pay his tab!", progress = "Did you make it to Ratchet and get those parts?", completion = "Great, you got them!  Now we need to get them to the gnomes.  But first...\n\nLet's take out one small item...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1113] = {title = "Hearts of Zeal", objective = "Master Apothecary Faranell in the Undercity wants 20 Hearts of Zeal.", description = "Why do I need a rare type of guano, you might ask. Well, for this experiment I want to see what effect two diametrically opposed chemical substances can have on each other, especially when both are combined with an ever-toxic agent to ensure the most... ghastly results.\n\nIn the northeastern peaks of Tirisfal Glades lies the Scarlet Monastery. There the crazed disciples of the Scarlet Crusade congregate, both inside and outside the halls. Which you slay matters not, any of them may have the heart I need.", progress = "Have you returned from the Scarlet Monastery? I'll need many hearts for this delightful experiment!\n\nNo doubt, Varimathras and the Dark Lady will be pleased to be rid of the Scarlet Scum as well...", completion = "My what an abundance of gore you have brought me, &lt;name&gt;! Your efforts have been most excellent!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1114] = {title = "Delivery to the Gnomes", objective = "Bring the Delicate Car Parts to Fizzle Brassbolts in Shimmering Flats.", description = "Now that I have what I need, give these parts to Fizzle Brassbolts.  He's been waiting a long time for them -- I'm sure he won't miss the little piece I removed from his order...\n\nAnd I wouldn't bother mentioning it to him.  It was small and worthless.\n\nTrust me.", progress = "You have something for me?  That's great!  let's see it!", completion = "There they are!  My hydro ratchets and repeater bolts!  These will do just fine.  Thank you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1115] = {title = "The Rumormonger", objective = "Talk to Krazek in Booty Bay.", description = "Now that we've done a service for the gnomes, it's time to do the goblins a favor!  \n\nI hear that the goblin racer pilot, Nazz Steamboil, didn't always use that name.  I wonder why he changed it.  I wonder if it's a secret, and... I wonder if he values that secret.\n\nIf anyone knows the truth, then it's Krazek of Booty Bay, on the southern tip of Stranglethorn.  Speak with Krazek and ask him about our goblin pilot.\n\nIf you can get useful information from him, then we might just turn a profit from it.", progress = nil, completion = "You want to know about Nazz Steamboil?  He's a racer pilot out in the Shimmering Flats, isn't he?\n\nYeah, I might be able to find something out about him... but it won't be easy.  Or fast.\n\nOr cheap.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1116] = {title = "Dream Dust in the Swamp", objective = "Bring 10 Specks of Dream Dust to Krazek in Booty Bay. Dream Dust is gathered from the dragon whelps of the Swamp of Sorrows.", description = "Getting the information on Nazz is quite a favor, <name>.  Yes, quite a favor.  But you've come all the way from the Shimmering Flats to get it... are you willing to travel some more?\n\nWhile I contact my sources, why don't you gather something for me, eh?\n\nHm... what will it be?  How about dream dust, from the dragon whelps of the Swamp of Sorrows.  Yes, I'd love some dream dust for my snuff pouch!\n\nGet it for me, <name>, and I'll give you the information you seek.", progress = "Back so soon?  Do you have my dream dust?", completion = "Well, look at that.  You found the dream dust!\n\nAnd how did you like the swamp, &lt;name&gt;?  It's not easy to get a hot meal there, is it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1117] = {title = "Rumors for Kravel", objective = "Bring the Goblin Rumors to Kravel Koalbeard in the Shimmering Flats.", description = "I had to use some of my favors, and gave away a rare bottle of elven wine, and did some heavy deducing myself!  But I found the information you seek.\n\nHere, I wrote a letter with some very interesting bits on our friend, Nazz Steamboil.  Do with it what you will -- it's too dangerous for me to use.\n\nJust don't tell anyone where you got it!", progress = "Did you get anything on Nazz Steamboil?  Anything he might want to keep a secret??", completion = "Well well!  This is interesting... very interesting.  Heh, perhaps I should bow to the goblin pilot the next time I see him.\n\nThis is worth plenty, &lt;name&gt;.  I'm sure Nazz will pay a small fortune to keep his secret... a secret.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1118] = {title = "Back to Booty Bay", objective = "Bring Kravel's Scheme to Crank Fizzlebub in Booty Bay.", description = "<name>, you're a <class> I can trust, both to get the job done and to keep your mouth shut while doing it.\n\nI've been brewing up a new scheme.  It's risky, but if it works then we could both make a bundle!  And I think you're just the person to see it through.\n\nTo start, you must go back to Booty Bay.  I apologize, good <name>.  I know my last task took you there.  But this time, speak with Crank Fizzlebub.\n\nGive him this letter.  And if he requires aid, do your best to help him.  It will be worth the effort.", progress = "Hello hello.  And what brings a noble <race> such as you down to Booty Bay?", completion = "I see.  Kravel has a big scheme planned.  He has a sinister mind -- I like that about him.\n\nSo you'll need something to addle wits, eh?  Something powerful...\n\nI wonder if the mixture Zanzil feeds his zombies could be used...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1119] = {title = "Zanzil's Mixture and a Fool's Stout", objective = "Bring the Fool's Stout back to Kravel in the Shimmering Flats.", description = "I figured out how to use Zanzil's mixture with stout to make a powerful libation.  A Fool's Stout.  I think it'll be just what Kravel needs, but try it out and let me know how it works.\n\nAnd <name>, don't keep this stuff too long without using it.  Zanzil's mixture has a weird effect on the stout's yeast, kicking it into high gear.  So it won't stay fresh forever.", progress = "Hello, <name>.  Was Fizzlebub able to help us?", completion = "Wonderful!  Fizzlebub came through!  I'll remember that next time I see him.\n\nAnd thank you, &lt;name&gt;.  You're doing a great job, and we both stand to make a lot of money from this...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1120] = {title = "Get the Gnomes Drunk", objective = "Bring the Fool's Stout to the Gnome Pit Boss.", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the gnomes, then here -- take the stout and give it to the gnome pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", progress = "Hi!  You have something for me?", completion = "Stout?  How considerate!  Thank you!\n\nWe shouldn't be drinking with the race coming up, but... maybe my boys could do with just a little.  Besides, it can't be that strong, can it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1121] = {title = "Get the Goblins Drunk", objective = "Bring the Fool's Stout to the Goblin Pit Boss.", description = "We need to try the Fool's Stout on one of the pit crews.  If you want to try it on the goblins, then here -- take the stout and give it to the goblin pit boss.\n\nAnd don't wait too long.  This stout will go bad eventually.", progress = "What are you looking at?", completion = "What do we have here?  Booze, eh?\n\nWell, I don't mind if we have just a little...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1122] = {title = "Report Back to Fizzlebub", objective = "Bring the Fool's Stout report to Crank Fizzlebub in Booty Bay.", description = "That Fool's Stout worked great!  I placed a bet on the next race, and... let's hope the crew you got drunk did a number on their car!\n\nThere's only one more task for you -- take this note back to Crank Fizzlebub in Booty Bay.  He'll want to know of the successful test.\n\nAnd hopefully we can get more of that Fool's Stout for future races!", progress = "Hello <name>.  How'd that stout work out?  It's strong stuff, isn't it?", completion = "It says here that the fool's stout was a success.  That's good news!\n\nIf you ever want more of the stuff, then let me know and I'll have you gather more of Zanzil's Mixture.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1123] = {title = "Rabine Saturna", objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris and Un'Goro.  He is located in Nighthaven, the main village of Moonglade.\n\nI want to impart on you the importance of your presence.  There are growing tensions between the night elves of Darnassus and the Cenarion Circle in Moonglade.  Look beyond racial boundaries and tap into the wisdom of your ancestors in dealings with the Circle there, <name>.  Good luck.", progress = nil, completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  The tauren have shown an incredible propensity to the tenets of Cenarius, and by their proxy the Horde is welcomed within the safety of this glade.  The preservation of Azeroth is a common goal we both share.\n\nYou are among friends here, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1124] = {title = "Wasteland", objective = "Speak with Layo Starstrike near the Valor's Rest graveyard of Silithus, showing him Rabine's Letter.", description = "West of Un'Goro Crater, via the northwestern ridge, is a harsh wasteland - Silithus.  Few know that an ancient war was waged there between the night elves and a malign, alien power.  The evil was sealed, but now we suspect that forces work to stir this... unspeakable horror.\n\nSeek out Layo Starstrike, one of our agents in Silithus; look for him at Valor's Rest, the final resting spot for the fallen of the wastes.  Give him this letter, and he will give you his trust accordingly.", progress = "This is a dangerous land to be so casual, <class>.  What brings you to the wastes of Silithus?", completion = "Rabine sent you, did he?  Well, consider yourself welcomed here... as much as this desolate and forsaken land can welcome someone.\n\nI wasn't alive during the time of the great tribulations that took place here, but there are parts of this desert that might as well be eerie pictures of that forgotten past.  With your help, the Cenarion Circle might be able to bring finality to a threat that was supposed to have died generations ago.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1125] = {title = "The Spirits of Southwind", objective = "Free the spirits of 8 Tortured Druids and 8 Tortured Sentinels in Southwind Village, and then return to Layo Starstrike at the Valor's Rest graveyard of Silithus.", description = "To our southwest lies a tragic site - the ruins of Southwind Village.  This is where our work should begin, <name>.\n\nFrom what we've learned, this village was once a night elf base of operations for Silithus.  It's long since overrun by the silithid hives that infest the wastes.  I can only imagine the horror of the village's initial sundering...\n\nThe tortured spirits of fallen druids and sentinels wander the ruins aimlessly.  Explore this locale, freeing the souls of these wretched beings as needed.", progress = "Alliance or Horde, it doesn't matter - no being deserves to be trapped on this world as a tortured spirit.  The freeing of these souls will make things right, <name>.", completion = "I had thought that maybe the huge swirling hive near the ruins of the village had played a part in its demise.  It would seem that your work has proven this to be correct; the proximity of the hive poses a threat to any future work we may do here.\n\nI thank you for your benevolence in freeing the souls of the fallen; such work is never easy, I know.  When you're ready, however, I'd like to ask for your assistance once more...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1126] = {title = "Hive in the Tower", objective = "Scale the tower of Southwind Village and locate a means to stir the silithid hive into activity. Bring back anything unusual you may uncover when doing so to Layo Starstrike at the Valor's Rest graveyard of Silithus.", description = "The hive needs to be addressed in Southwind Village, and I think I know a way to get at them.  It's been my experience that the silithid hives are very sensitive to their environment; this explains their attacks when hearing the death wails of the spirits.\n\nThe silithid are strongest in the tower - the one with the mass of wasps circling it.  Scale the tower and jostle the hive into activity.  Report back what you learn, but be careful!  If you uncover anything that might help, bring it to me.", progress = "Well, did it work?  You're still in one piece, which is good news.  Did you find anything?", completion = "What the... what is it?\n\nIt has the shape of a... box, maybe?  It's encrusted over something fierce.  Wait, there's a portion here that's exposed... is that a book underneath all this gunk?\n\nI think you've stumbled across quite the find here, &lt;name&gt;... well, at least I hope it is.  Perhaps it is a journal or a log from ancient times, preserved in this shell.\n\nI think I know a way to find out what this is.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1127] = {title = "Fool's Stout", objective = "Bring 12 of Zanzil's Mixture to Crank Fizzlebub in Booty Bay.", description = "So you want some Fool's Stout, eh?  Thinking of heading back to the races...?\n\nAll right, bring me more of Zanzil's mixture and I'll make some more stout for you.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nFool's Stout"}
MultiLanguageQuestData['en'][1130] = {title = "Melor Sends Word", objective = "Speak with Melor Stonehoof in Thunder Bluff.", description = "<name>, Melor Stonehoof has heard of your deeds, and has set a path before you.\n\nIf you wish to take it, then go to Thunder Bluff and speak with Melor.  You will find him on Hunter's Rise.", progress = nil, completion = "So, &lt;name&gt;, you have come.  Now, are you prepared to journey through distant lands?\n\nIf so, young &lt;class&gt;, then listen on...", rewards = nil}
MultiLanguageQuestData['en'][1131] = {title = "Steelsnap", objective = "Bring Steelsnap's Rib to Melor Stonehoof in Thunder Bluff.", description = "At times we hunt for food.  At times we hunt for honor.  And at times we hunt to earn the Earthmother's teachings.\n\nBut the hunt I now set upon you is none of these things.  It is to slay a creature outside the Earthmother's blessing.\n\nThe hyena Steelsnap roams the Thousand Needles, south of the Barrens.  He is a tyrant, attracting other hyenas to him and spreading fear and bloodshed among more peaceful beasts.\n\nFind Steelsnap, <name>.  Find him, and defeat him.", progress = "Have you defeated the foul Steelsnap, <name>?", completion = "In defeating the creature Steelsnap, you have cleansed the Thousand Needles of a horrible taint.\n\nAnd that, &lt;name&gt;, is your lesson this day.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1132] = {title = "Fiora Longears", objective = "Speak with Fiora Longears on the docks at Auberdine in Darkshore.", description = "Oh, to be at sea once again!  To feel the kiss of the wind, and to have the waves rock me like my blessed mother, long ago!\n\nOh, I wish I had your fortune, good <class>, for I see the sea in your future!\n\nIt's my job to tell eager souls of the land of Kalimdor, the land of opportunity!  If you're willing to try your luck across the sea, then take a ship from here to the lovely port of Auberdine.  Speak there with my partner, the elf, Fiora Longears.\n\nShe'll start you on your Kalimdor adventure!", progress = nil, completion = "Good day to you!  You were sent by Mr. Flint in Menethil Harbor?  Well Mr. Flint is a strong judge of character.  If he sent you, then there's no doubt you belong here in Kalimdor!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1133] = {title = "Journey to Astranaar", objective = "Speak with Shindrell Swiftfire in Astranaar.", description = "If you're fresh off the boat from Menethil, then the first thing you should do is... go to Astranaar.  I'm sure an eager member of the Alliance such as you can do some real good there.  Speak with Shindrell Swiftfire and offer your services.\n\nBut don't bother mentioning who sent you.  Shindrell does not know me...", progress = nil, completion = "You are here to offer your services to the Alliance, &lt;name&gt;?  We welcome the aid, for although its beauty remains... Ashenvale Forest is not the peaceful place it once was.", rewards = nil}
MultiLanguageQuestData['en'][1134] = {title = "Pridewings of Stonetalon", objective = "Bring 12 Pridewing Venom Sacs to Shindrell Swiftfire in Astranaar.", description = "We are not in open war with the Horde, but our peace is fragile.  We often find their agents moving against us, but they do so covertly.\n\nOne such advance was revealed to us from hidden sources in Theramore, claiming that the orcs collect venom from the pridewings near Mirkfallon Lake, in the Stonetalon Mountains to the south.  Orc assassins then use the venom on their secret death raids against the Alliance!\n\nIf this is true, then we must stop them, <name>.  We must deny them their source of venom.", progress = "Do you have the pridewing venom sacs, <name>?  We cannot allow the orcs to use the beasts' poisons against us!", completion = "Thank you, &lt;name&gt;.  It saddens me to order the slaughter of creatures who may not willingly aid our enemies, yet it is my duty to do so.\n\nYour heart might weep for the pridewings you slew, my friend, but may your heart then swell in knowing that your allies are safe from the pridewings' venom.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1135] = {title = "Highperch Venom", objective = "Bring 10 Highperch Venom Sacs to Fiora Longears in Theramore.", description = "As you may know, wyverns are often tamed by orcs for use as mounts.  But what is less known is that the venom of a wyvern, in some circles, is more valuable than the beast itself.  So if you're not afraid to do a little wyvern hunting, then... I have a job for you.\n\nThere is a place called Highperch in the land of a Thousand Needles, west of here.  The Highperch wyverns have a potent venom.  Potent, and valuable.", progress = "Did you find Highperch, <name>?  Any luck with the wyverns there?", completion = "Ah, most of these are nearly bursting with venom, &lt;name&gt;.  Such are normally only gathered from young wyverns, or fertile females.  It must have been quite a slaughter up there in Highperch!", rewards = "You will receive:\n\nWindborne Belt"}
MultiLanguageQuestData['en'][1136] = {title = "Frostmaw", objective = "Bring Frostmaw's Mane to Melor Stonehoof in Thunder Bluff.", description = "<name>, it is now time for you to travel to far-off lands.  You are ready.\n\nYou now hunt Frostmaw, a yeti in the Alterac Mountains.  He is elusive, his white coat blending into the snows of his mountain home.  He rarely shows himself.\n\nBut I will show you how to entice a creature such as he.  Here, take this scroll.  On it I have written how Frostmaw may be lured.\n\nNow go, <name>.  Your journey is long and many challenges lay waiting.  When you return with Frostmaw's mane, only then is your task complete.", progress = "Have you been to the Alterac Mountains, <name>?  Did you face the elusive Frostmaw?", completion = "Both strength and cunning were needed to find and defeat Frostmaw, &lt;name&gt;.  You have both.\n\nYour path has taken you to the valleys of Thousand Needles and to the high mountains of Alterac.  It will one day lead you through all the Earthmother's lands, for such is the way of the hunter.", rewards = "You will receive:\n\nSpirit Hunter Headdress"}
MultiLanguageQuestData['en'][1137] = {title = "News for Fizzle", objective = "Speak with Fizzle Brassbolts in the Shimmering Flats.", description = "Indurium has an amazing resistance to heat!  I'm sure it will work for Fizzle's pistons.  But he'll need true indurium ore, not just the flakes.\n\nTo get the ore, it must be mined from deep within Uldaman, on the northern borders of the Badlands.  That is the true source of indurium.\n\nSend Fizzle Brassbolts my regards, and tell him what I told you.\n\nSafe travels, <name>.  And it won't surprise me if we meet again -- once Fizzle learns of indurium he'll probably send you to Uldaman to acquire it!", progress = nil, completion = "&lt;name&gt;, you're back!  You found Martek?  You spoke with him?  What did he say?  Can he help??\n\nTell me, tell me, tell me!!", rewards = "You will be able to choose one of these rewards:\n\nFizzle's Zippy LighterGnomish Mechanic's Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1138] = {title = "Fruit of the Sea", objective = "Collect 6 Fine Crab Chunks for Gubber Blump in Auberdine.", description = "I love crab.  Crabs are the fruit of the sea!  You can bake it, barbecue it, boil it, and broil it.  They're pan fried, deep fried, and stir fried.  There's crab salad, crab soup, crab stew, pepper crab, lemon crab, whipper root crab, and Ironforge surprise crab.  That's... that's about it.\n\nI'm here fishing right now, so I can't get any fine crab chunks.  You can pick them out of reef crawlers and encrusted tide crawlers.  You can make a lot with it.  You can bake it, barbecue it, boil it...", progress = "...lemon crab, whipper root crab, and Ironforge surprise crab.  That's about it.\n\nOh, hello there <name>.  Do you have them fine crab chunks I was telling you about?", completion = "Wow, these fine crab chunks are what I need.  Thanks &lt;name&gt;!  I found this while I was fishing a while ago, and I have no use for it.  Maybe you can do something with it.  It sure don't make any good crab dishes.\n\nI told you all about crabs, right?", rewards = "You will be able to choose one of these rewards:\n\nShucking GlovesCrustacean Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1139] = {title = "The Lost Tablets of Will", objective = "Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge.", description = "We've slowed the Shadowforge clan by cutting them off from Blackrock Spire, but Hammertoe's quest is still unfulfilled. His death must not be in vain. He dreamt of finding the Tablet of Will: a stone shard inscribed with magic by the titans themselves to help imbue their creations with life--making them have a will of their own, or so the legends say.\n\nWe must still recover the Tablet before the Shadowforge clan finds it.\n\nReturn to Uldaman, find the tablet, and return here immediately.", progress = "Hammertoe's quest must be actualized, <name>. I owe him that much.\n\nYour return to Uldaman is imperative not only to that goal, but also to the safety of all dwarven kind. With the tablet in the hands of the Dark Irons who knows how powerful their army of golems would become.", completion = "&lt;Advisor Belgrum shakes his head in disbelief as you hand him the stone shard.&gt;\n\n&lt;name&gt;, this is amazing. I shall have this brought to the king's mages as soon as possible. They will want to study it to find out if the legends are true. But that is a discussion for another time: you have aided our people more than I would have ever expected--thank you.", rewards = "You will receive:\n\nMedal of Courage"}
MultiLanguageQuestData['en'][1140] = {title = "The Tower of Althalaxx", objective = "Free the trapped Highborne souls in Night Run and Satyrnaar, then return to Delgren the Purifier at Maestra's Post.", description = "The writing of the orcs is little better than the scribblings of a child. Many of my order scoffed when I chose to learn their tongue, but I have found it beneficial to gain further understanding of my enemies.\n\nFrom Ilkrud's scribblings, it appears that Athrikus still possesses two soulgems, and they are being held in Night Run and Satyrnaar, satyr-held areas in northeast Ashenvale.\n\nBe careful out there, <name>, the satyrs' blood-soaked temples can be unsettling even for a seasoned <class> such as yourself.", progress = "I heard whisper once that the satyrs' history is somehow related to that of the night elves, but I have found my esteemed hosts reticent to speak of the matter.", completion = "Perhaps the satyrs have been allowed to persist in the forest for too long. I will speak with Elissa about it when next I travel to Auberdine.\n\nNonetheless, with the soulgems destroyed, Athrikus' power will be greatly diminished. We must seize on this opportunity to eliminate him and his cult.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1141] = {title = "The Family and the Fishing Pole", objective = "Catch 6 Darkshore Grouper for Gubber Blump in Auberdine.", description = "I love fishing.  The Blump family is known for fishing.  My name is Gubber Blump; I fish.\n\nThere's a kind of fish I like to catch around these parts called Darkshore grouper.  I used to go out on a boat to fish for grouper, but no boats have been going out since them mean ol' murlocs moved in.  I bet they been eating up all the grouper too.\n\nSay, you wanna help me catch Darkshore grouper?  I'd give you a bona fide Blump Family Fishing Pole if you did!  It's a real good pole to catch fish with.", progress = "There's plenty of good dishes you use Darkshore groupers for.  They're good to eat, but I think it's more fun catching them.\n\nYou caught any Darkshore groupers yet?", completion = "Them's some real nice groupers, &lt;name&gt;!  Thanks for helping me out!\n\nYou're at least as good of a fisherman as my cousin, Graun Blump.  She also has a beard and she smells kinda funny, but that don't do nothing to stop her fishing.  I reckon you have what it takes to use a Blump Family Fishing Pole.", rewards = "You will receive:\n\nBlump Family Fishing Pole"}
MultiLanguageQuestData['en'][1142] = {title = "Mortality Wanes", objective = "Find and return Treshala's Pendant to Treshala Fallowbrook in Darnassus.", description = "I have not long to live... so... so... weak.\n\n...the b-b-brave dwarf, Lonebrow, has been sent to w-w-warn Falfindel...\n\nBut before I... d-d-die...\n\n...my wife, Treshala... her pendant of bonding to me... stolen... by one of the f-f-foul aggressors...\n\nFind it p-p-please... and return it to Treshala in Darnassus...\n\n...along with w-w-word of my lonely... death.", progress = "What brings you to my home, <race>?", completion = "No!\n\n'Tis not fair. Oh, cruel and intolerable world!\n\nI must now carry this burden of grief and not let Heralath's work die with him.\n\nYou were brave to journey from such a dangerous place, &lt;name&gt;. But please leave me now.\n\nIn solitude I shall mourn.", rewards = "You will be able to choose one of these rewards:\n\nMourning ShawlLancer Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1143] = {title = "The Tower of Althalaxx", objective = "Kill Athrikus Narassin and bring his head to Balthule Shadowstrike near the Tower of Althalaxx.", description = "I see. Well, if what you say is true, then now is the time to strike. I believe Athrikus resides at the top of the tower. Be careful though, he is surrounded by many powerful warlocks, much more deadly than the ones you faced before.", progress = "Athrikus Narassin is an ancient and powerful warlock. Perhaps we should wait for Delgren's assistance, but he obviously had much faith in you to send you alone.", completion = "With the death of Athrikus, I hope that the demonic forces in this area will be driven back. I have no doubt that they will regroup and return, but then we shall be even more prepared to meet their threat.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1144] = {title = "Willix the Importer", objective = "Escort Willix the Importer out of Razorfen Kraul.", description = "At last, help has arrived!\n\nYou have no clue how long I've been held prisoner here. I can't remember the last time I saw the outside of this place.\n\nYou see, I am an entrepreneur. Always out for a copper, as they say. I caught wind that Mebok Mizzyrix was paying well for Redleaf Tuber from this here pig pen. I figured it would be an easy in, easy out kind of affair. As you can see, I was a bit wrong!\n\nAnyway, if you'd be so kind as to help me get out of here, I'll make it worth your while.", progress = nil, completion = "Thanks again, friend! I told you I'd make it worth your while.", rewards = "You will be able to choose one of these rewards:\n\nMonkey RingSnake HoopTiger Band\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1145] = {title = "The Swarm Grows", objective = "Deliver Korran's Sealed Note to Belgrom Rockmaul in Orgrimmar.", description = "Many travelers who've come through the Crossroads helped me gather eggs from the Field of Giants, and many of them have tales of how deadly the creatures are. I've heard enough to consider them insects a much larger threat than my masters first thought.\n\nI need a courier to travel to Orgrimmar to meet Belgrom Rockmaul. It be no simple matter, and someone who would take the task seriously should go.\n\nBelgrom usually be found outside the warriors' guild house.", progress = "I envy you, <class>. You have the look of someone who's been outside the walls of Orgrimmar for a while.\n\nI myself would travel in the name of the Warchief if Thrall didn't have need of my skills here in the city. But he leads us well, and I trust his judgement--I remain here for as long as he needs me.", completion = "Ah, a note from Korran. He has been a loyal servant for some time now. I was wondering how his duties were going in the Crossroads.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1146] = {title = "The Swarm Grows", objective = "Deliver Belgrom's Sealed Note to Moktar Krin in Thousand Needles.", description = "So, Korran has come to a similar conclusion about these insects--they seem to be a larger threat than we assumed.\n\nA few days ago a hunter returned to me from Thousand Needles nearly dead. He was with a raiding party sent to drive a dwarven excavation team out of the Shimmering Flats. During the attack, more of these insects erupted from a cave in the dig site and nearly killed the party.\n\nThey were led by Moktar Krin, and they've taken refuge on the border of the Shimmering Flats. Bring him this note.", progress = "War brings my group and I to the Shimmering Flats, <class>. What brings you here?", completion = "Don't mind the thundering echoes off the mountains' walls. The goblins and gnomes are out among the Flats racing one another in atrocities created by what they call science. There are bigger threats here in Thousand Needles, one of which killed more than half my war party.\n\nBut we remain here until we hear word from Belgrom in Orgrimmar. Until then, we hold our position here, and stay vigilant.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1147] = {title = "The Swarm Grows", objective = "Kill 5 Silithid Searchers, 5 Silithid Hive Drones, and 5 Silithid Invaders and return to Moktar Krin in Thousand Needles.", description = "Hmm. Seems Belgrom thinks those monsters are a threat. He wants them pushed back into whatever depths they crawled up out of.\n\nI guess killing the dwarves sent by the Explorers' League wasn't enough--now I have to send a half-dead war party into another battle. We won't be able to do it ourselves; not while we're in this condition. The dig site's to the south of here. There shouldn't be anymore dwarves to deal with. Feel up to wielding a blade or staff and doing your part to aid us?", progress = nil, completion = "Ha! That ichor you're covered in actually makes you prettier, &lt;name&gt;! It certainly does make you reek at the same time though. Don't stand too close to the kodo; you'll either start a stampede or cause them to go into heat.\n\nI think my companions would agree that your smell alone is proof you've done your part to help us against those insect creatures. Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1148] = {title = "Parts of the Swarm", objective = "Bring 1 Silithid Heart, 5 Silithid Talons, and 3 Intact Silithid Carapaces, to Korran at the Crossroads.", description = "You inspect the carapace carefully. As you turn it over in your hands you realize that the chitinous plating is interlaced in such a way that makes it incredibly strong. It's unlike anything you've ever seen. You inspect the rest of the corpse further and realize that these creatures are very powerful and highly evolved.\n\nLooking down at the carapace again, you think that Korran would enjoy studying more of these creatures. It could help him figure out what these creatures are, and where they come from.", progress = "Ah, it been a long time since you've come to see me, <name>. What can I do for you today? You be looking like you've seen the face of battle recently. Good... good for the Horde and good for you. The more battle you've seen, the more helpful you'll be; stronger, too.", completion = "Ahh, you've seen Moktar recently? He always be lookin' out for me. I'm sorry to hear he spends his time watching over his little war band instead of seeing battle, but I'm sure he be takin' great joy in killing members of the Explorers' League.\n\nYou be smart to bring me these specimens, &lt;name&gt;. Along with the eggs we be findin' in the Field of Giants, these should give me a good start in figuring out what these insects are, and what they be wantin'.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1149] = {title = "Test of Faith", objective = "If you have faith, leap from the planks overlooking Thousand Needles.", description = "So, you have sought me out, or perhaps destiny brings you to me? No matter. You are here now, and so your journey will begin anew.\n\nMany facets make up a being: the spirit, the body, the mind. Some of these can be measured by a culture's traditions. Others we can only hope exist within ourselves. If you agree, I shall test some of the facets within you.\n\nIf you pass, then you shall become stronger. If you fail, then you will realize the vastness of the Nether.\n\nThe first is a Test of Faith.", progress = "Faith. It is far more important than some realize.\n\nIt does not matter what you believe sometimes. It is just important that you believe in something.", completion = "It is not until faced with unforeseen adversity that we begin to see how strong our spirits are. You took the leap of faith even though you had no guarantees that you would survive. Your mind is open, and your spirit is prepared for what is to come.\n\nIf you are willing, then the next of your tests is ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1150] = {title = "Test of Endurance", objective = "Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles.", description = "I'm pleased to see your courage remains steadfast in light of what you've already done. Since your faith is intact, the time has come to test your body.\n\nFirst is a test of endurance. Go to the Roguefeather Den west of Freewind Post. Make your way to the depths of their lair and destroy their foodstuffs. By then you should have provoked their fury, and if you are able to survive long enough, Grenka Bloodscreech herself will come for you--kill her and bring me her claw to complete your test.", progress = "You must be prepared spiritually, physically and mentally for the challenges that lie ahead of you.\n\nToo often do we rush forward before we are ready. I consider it my duty to the youth, no matter which tribe they belong to, to prepare them for the dangers they may face after they leave the sanctity of their home.", completion = "Grenka was powerful, even by &lt;race&gt; standards. You should be proud of your accomplishment this day.\n\nDuring your test of faith you displayed strength of spirit, and now you have shown endurance in battle by taking on the Roguefeather harpies, but the time has come for a new test.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1151] = {title = "Test of Strength", objective = "Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles.", description = "During the time of the Old Gods, elementals inhabited much of this world. They worshipped the Old Gods, and the Gods, through their power, kept the elementals bound to this world. When the Old Gods were banished, the elementals faded from our world and now only return at the bidding of powerful mages.\n\nThere are exceptions though. Some elementals were powerful enough to remain here on their own. One such elemental is Rok'Alim.\n\nTo test your strength, find Rok'Alim in Thousand Needles and slay him.", progress = "Rok'Alim is also called the Pounder by the centaur tribes in Thousand Needles because of the thundering his fists make as he pummels the creatures brave, or stupid, enough to stand in his path.", completion = "The Test of Strength is done. You have shown strength and bravery, and you are now prepared for the final test before these rites are completed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1152] = {title = "Test of Lore", objective = "Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", description = "Your time with me is just about finished. I am knowledgeable, but the Test of Lore is not mine to give. There are lessons to be learned and places to visit that others claim domain over.\n\nIf you are prepared, then seek out Braug Dimspirit--he is a shaman of great wisdom. He will test you further, so heed his words, <name>.\n\nWhen you are ready, find the tunnel that connects the Stonetalon Mountains with Ashenvale: Braug dwells near there. And be careful, <name>, the night elves may wish to impede your test.", progress = nil, completion = "The days and nights grow colder throughout the world as goblins rape the land, and the night elves point fingers at the younger races. The Forsaken and orcs are not the only ones to blame for the hardships found throughout Kalimdor and Lordaeron. Many of the intelligent races have contributed to the world's pain. Dorn knows this, and he has sent you to me because you have shown the attributes necessary to realize it also.\n\nNow you stand before Braug.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1153] = {title = "A New Ore Sample", objective = "Find an Unrefined Ore Sample on a Gravelsnout Digger or Surveyor and bring it to Tatternack Steelforge at Camp Taurajo in the Barrens.", description = "<class>, you have done well in helping me in the past. The warchief is pleased thus far with what I've accomplished, and asks me to continue with renewed determination. My honor dictates that I give you proper recognition to the warchief for all you have done, but first I would ask you for your help again.\n\nTravelers recently came from the south from a place called Thousand Needles. There they killed a kobold who had an unusual ore sample, but they would not sell it. I want a sample of that ore to examine.", progress = "I saw the travelers again--the ones that would not sell me a sample of the ore. I spit at them for not helping the warchief.\n\nMay they die in battle like cowards and not like warriors as should be the right of all people who ally themselves with the Horde.", completion = "A good sample, &lt;name&gt;. A good sample indeed.\n\nThose travelers can no longer lord over me the ore they found, now that you have been successful.\n\nI shall get to work on it immediately. If it proves strong enough, I will send a weapon crafted from the material back to the warchief to show him our success.\n\nI shall not forget your help, &lt;class&gt;.", rewards = "You will receive:\n\nOrcish War Sword"}
MultiLanguageQuestData['en'][1154] = {title = "Test of Lore", objective = "Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains.", description = "You have passed Dorn's tests, and now you seek to pass your next trial. Very good. But up until now, your challenges have been childish. It is easy to test your body--your mind is another matter completely.\n\nI shall explain it simply: find the book I name, study it, and answer my question about its contents.\n\nWhat book, you must be asking? The Legacy of the Aspects. It can be found at the bottom of Dor'danil in southern Ashenvale, protected by the dead druids and their slayers.", progress = "Bring me the book after you've studied it. I will not ask you your question until after you have given me the book.", completion = "This is the book I named. There is hope you will answer my question correctly then... unless you've forgotten to study its contents.\n\nWhen you are prepared, speak to me again and I shall ask a question of you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1159] = {title = "Test of Lore", objective = "Find Parqual Fintallas in Undercity.", description = "Well done, <name>. You have passed the first portion of the Test of Lore, but there is still another question to be answered. But that question is not mine to ask.\n\nSeek out Parqual Fintallas in Lordaeron City. He was a great historian for the humans before the Plague overtook him. Now he continues to seek enlightenment, but of a different nature.\n\nHe will have another requirement of you before he asks you anything, but you have done masterfully thus far--I'm sure you will overcome his obstacle.", progress = nil, completion = "Braug sent you? Impossible.\n\n&lt;Parqual looks you up and down.&gt;\n\nBraved Dor'Danil, took a leap of faith, fought and overpowered a powerful elemental? Bah! You're probably a farce; some adventurer that overheard talk in a tavern. And now you think you have what it takes to pass my test. So be it... &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1160] = {title = "Test of Lore", objective = "Find The Beginnings of the Undead Threat, and return it to Parqual Fintallas in Undercity.", description = "I will tell you what you must seek, and I will even ask you my question, but not because you wish to prove yourself. Knowledge is far more important than strength. Even as others seem to pass you by in ability, your knowledge of the world will be more valuable.\n\nGo to the Monastery in the north of Tirisfal Glades. In the library there, a book called Beginnings of the Undead Threat resides. It was used by the now-corrupt paladins there to train them to fight my kind.\n\nBring it to me.", progress = "I hope you made the Scarlet Crusade suffer some before stealing the book from them.\n\nMy views of their kind are not unwarranted. The Crusade may have been followers of the Light at one time, but now, they seek to destroy any creatures that have not sided with their religion. They believe all undead, Forsaken or otherwise, must be cleansed, and those traveling in their lands must either be insane, or subject to the undead's powerful magics. Idiots. Idiots and fools; all of them.", completion = "This is the book I sent you to search for.\n\n&lt;Parqual slowly caresses his hand over the top of the book as he stares down at it.&gt;\n\nSo now you wish a question to prove your mind is as powerful as your body and spirit. If you have studied the book long enough, then I shall ask you your question and you can be done with these tests!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1164] = {title = "To Steal From Thieves", objective = "Bring Kenata, Fardel, and Marcel Dabyrie's Heads to Genavie Callow in Undercity.", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, her and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", progress = "Kill them all and bring me their heads!", completion = "You stand before me as a figure of vengeance, and I bow down before you in thanks.\n\nWith that cow's death, and knowing that their seed will no longer spread over the face of Azeroth, I can put my energy into something more lucrative. I hope you looted their farmstead after you finished them off.", rewards = "You will be able to choose one of these rewards:\n\nGrim PauldronsGallan Cuffs\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1166] = {title = "Overlord Mok'Morokk's Concern", objective = "Overlord Mok'Morokk in Brackenwall Village wants you to retrieve his grog, snuff and strongbox in Dustwallow Swamp.", description = "Bow before Overlord Mok'Morokk!\n\nRexxar make me mighty leader of Stonemaul Clan!\n\nMe good leader. Me keep clan safe.\n\nBig dragons come and make fire at old home. Me smart ogre. Find new home for clan here.\n\nLeave old home so fast, me forget stuff. Tiny <race>, go get my things. Go south and find my yummy grog, my snuff and my strongbox. Me like you after you do that. You look in Den of Flame and Stonemaul Ruins... they be there, me sure!", progress = "Me thirsty for grog. Me miss snuff too. Where is strongbox? You go get for Overlord Mok'Morokk.\n\nGo find south in old home. Me too busy leading ogres to get.", completion = "You good &lt;race&gt;. Me miss things very much. Me like you now.", rewards = "You will receive:\n\nEnormous Ogre Boots"}
MultiLanguageQuestData['en'][1167] = {title = "The Tower of Althalaxx", objective = "Speak with Balthule Shadowstrike near the Tower of Althalaxx.", description = "Before confronting Athrikus, it would probably be wise for you to consult with Balthule. I have no doubt he has been vigilant in his watch of the Tower, and he may have information about recent developments.", progress = nil, completion = "Ah, it's good to see you again, &lt;name&gt;! The strangest things have been happening around here, I'm glad you showed up!\n\nIt was very strange, &lt;name&gt;. Everything seemed normal--well, as normal as things get around here--and then suddenly there was a blinding flash of light from the upper room of the tower. Then came the screams. The cries split the air, and lightning struck the ground from time to time. What's going on?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1168] = {title = "Army of the Black Dragon", objective = "Tharg in Brackenwall Village wants you to kill 10 Firemane Scouts, 10 Firemane Ash Tails, and 5 Firemane Scalebanes.", description = "Mok'Morokk was made Overlord by Rexxar. He care more for power than he care for ogres.\n\nBlack dragons kill many ogre. Kill Tharg's wife. Mok'Morokk tell us to run. Make us come here.\n\nOgre should fight. Ogres not good at running. Mok'Morokk care only about Mok'Morokk.\n\nMe call Stonemaul Ruins home. Me like it in the south. This place not home.\n\nHelp ogres fight army of the black dragon. Me want revenge. Me want to go home.", progress = nil, completion = "You kill many of the black dragon army. You brave &lt;race&gt;.\n\nMake Tharg happy.", rewards = "You will be able to choose one of these rewards:\n\nTharg's ShoelaceTharg's Disk\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1169] = {title = "Identifying the Brood", objective = "Draz'Zilb in Brackenwall Village would like you to bring him 7 Searing Tongues and 7 Searing Hearts.", description = "Whilst that craven fool, Mok'Morokk, wallows in power and Tharg wrestles the demons of sorrow and vengeance and vies for leadership of the clan, I seem to be the only one concerned with identifying the source of aggression on our old home.\n\nWhy the puzzled stare, <name>? Expecting me to speak like an uncouth ruffian merely because I am an ogre?\n\nNow back to business, bring to me the hearts and tongues from the whelps and hatchlings. I shall trace the root of this evil...", progress = "With the hearts and tongues of scorched offspring of the black dragon army, I can decipher what wretched beast introduced her spawn into our home. Perhaps with a greater knowledge of our aggressors, we can seek to destroy them once and for all and reclaim Stonemaul Village from ruin.\n\nOf course, convincing Mok'Morokk to move his lethargic, fat mass out of this muck hole is going to be an epic quest in and of itself...", completion = "'Twas a perilous affair, no doubt, collecting all of these hearts and tongues. I shall delve into the depths of the arcane to trace the origin of the black menace which has descended upon our former home.", rewards = "You will be able to choose one of these rewards:\n\nScorched CapeRustler Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1170] = {title = "The Brood of Onyxia", objective = "Speak with Overlord Mok'Morokk in Brackenwall Village.", description = "Stonemaul Village was invaded by the brood of Onyxia. But why would the daughter of the black dragonlord, Deathwing, descend upon our lands?\n\nThis is most troubling. Surely, Onyxia was driven here for a purpose beyond laying siege to a small band of ogres.\n\nNotify Mok'Morokk at once! Action must be taken.", progress = nil, completion = "Why you tell me 'bout dragons? Me no like dragons. Me like it here. No dragons here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1171] = {title = "The Brood of Onyxia", objective = "Speak with Draz'Zilb in Brackenwall Village.", description = "You leave me alone now. Go tell Draz'Zilb we stay here. No black dragon here.", progress = nil, completion = "That lazy coward!\n\nMok'Morokk displayed strength when Rexxar was our leader. But soon after Rexxar's departure Mok'Morokk fell prey to temptations of power. Rather than lead, he demanded. He does not serve his people but rather expects us to serve him.\n\nSomething must be done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1172] = {title = "The Brood of Onyxia", objective = "Draz'Zilb in Brackenwall Village wants you to destroy 5 Eggs of Onyxia.", description = "Onyxia's brood has been scattered across the Dragonmurk. It is imperative that no more whelps be permitted to hatch.\n\nMake haste to Wyrmbog in the south of Dustwallow Marsh. Surely, she has made her lair there. Track down the evil dragon's eggs and destroy them.\n\nWe will never reclaim Stonemaul Village if the surrounding area remains a breeding ground.\n\nAs for Mok'Morokk... I have other plans for the sod.", progress = "You must hurry to the Dragonmurk, <name>. With Onyxia's eggs riddled around the Wyrmbog, we face overwhelming numbers unless something is done quickly.\n\nDestroy her eggs! Don't let the black dragon plague spread across our homeland!", completion = "Splendid! It will be sometime before Onyxia can produce more eggs.\n\nOn behalf of my people, I thank you, &lt;name&gt;.\n\nI have asked much of you so far. Perhaps you can do the Stonemaul Clan one last service.\n\nMok'Morokk is not fit to lead us. Tharg would make an excellent leader but is hindered by his injuries and age. Drive Mok'Morokk from this place by force. Only then can we appoint a new leader to return us to our proper home in the south.", rewards = "You will be able to choose one of these rewards:\n\nEncarmine BootsBoots of Zua'tec\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1173] = {title = "Challenge Overlord Mok'Morokk", objective = "Defeat Mok'Morokk and report the news to Draz'Zilb in Brackenwall Village.", description = "You dare challenge Overlord Mok'Morokk?\n\nHaw!\n\nMe crush tiny <race>!\n\nYou tell me when ready for good beating.", progress = nil, completion = "That cowardly fat mass Mok'Morokk fled like a scared child. You have done a great service, &lt;name&gt;.\n\nNow my people can appoint a new leader, one who will help us reclaim our old home once and for all.", rewards = "You will be able to choose one of these rewards:\n\nFiendish SkivChillnail Splinter\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1174] = {title = "Gnomes Win!", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGnome Prize Box"}
MultiLanguageQuestData['en'][1175] = {title = "A Bump in the Road", objective = "Kill 10 Saltstone Basilisks, 10 Saltstone Crystalhides and 6 Saltstone Gazers for Trackmaster Zherin on the Shimmering Flats.", description = "After the big crash with the goblins' Red Thunder racer and a basilisk, Kronkrider hired me on to take care of the track. I don't know what all the animals out on the flats are feeding on to grow so big, but we have to be careful to thin them out so they won't wander onto the track when a race is going on.\n\nTell you what. If you want to go out and make a little profit, go out and remove the basilisks from the area.", progress = "It's bad enough having to clear out the wreckage of the racers without having to pick them out of burnt animal parts.", completion = "I hope you didn't kill any of the basilisks on the tracks themselves! It takes a long time for the carcasses to decay in the sun, and I'd rather not have to take a shovel out to clean up.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1176] = {title = "Load Lightening", objective = "Get 10 Hollow Vulture Bones for Pozzik in the Shimmering Flats.", description = "When it comes to racing, every bit counts! Whether it's a minor tweaking on the power output, a slight slackening on the tension coils, or lightening the weight of the frame, you have to take everything into account.\n\nWe use vulture bones for a lot of the minor structural tweaks we make to our racers, which offer the perfect balance of strength and weight. Even better, it's easy for us to get more, as the salt flats are littered with vultures.\n\nBring me some and I'll give you a good price on them.", progress = "Do you have those bones for me? I was just about to start working on lightening the steering rig, but I don't want to open her up without all the parts I need.", completion = "Great! I can get the crew working on this right away. Thanks, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1177] = {title = "Hungry!", objective = "Mudcrush Durtfeet in northern Dustwallow wants 8 Mirefin Heads.", description = "Mud big ogre.\n\nMe hungry.\n\nGo bash fishy. Bring Mud food.\n\nYou feed Mud or Mud eat you.", progress = "Gimme food or me eat you.", completion = "Me like fishy head!\n\nMe no eat you now.", rewards = "You will be able to choose one of these rewards:\n\nMud's CrushersDurtfeet Stompers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1178] = {title = "Goblin Sponsorship", objective = "Speak to Gazlowe in Ratchet.", description = "Our racing team is the pride of goblins everywhere. You'd be surprised at some of the people who contribute in one way or another to our team.\n\nYou know Gazlowe? He tracks down parts from around the world for us. He even came down to work on one of our rigs once!\n\nA few weeks ago, he said he'd send us a new prototype fuel regulator but it hasn't come yet. He's usually very prompt... Maybe you wouldn't mind going to Ratchet to ask him about it? I wouldn't be so pushy, but the gnomes are gaining on us!", progress = nil, completion = "Pozzik sent you, huh? You know, Pozzik was one of the most respected tinkerers in Undermine before he retired to start working on the racers.\n\nThe first thing he did when he joined the team was develop the two engine model racers. Could be that the businesses will suffer without him working with the Tinkers' Union, but who cares, right? There's nothing like the races!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1179] = {title = "The Brassbolts Brothers", objective = "Bring the crate of crash helmets to Wizzle Brassbolts in the Shimmering Flats.", description = "You ever heard of the Shimmering Flats?  It's a stretch of salt flats way over in Kalimdor, just south of the Thousand Needles canyon.  It's a great place for racing because, well, it's so flat!\n\nA couple of gnome brothers are out there, friends of mine, trying out their new rocket car, and from what I hear it's fast!  Heh, so fast that their pilots keep crashing.  Giving themselves concussions.\n\nSo they asked me for some Siege Engine helmets, but I have duties here.  I can't make the trip!\n\nCan you?", progress = "Watch where you're stepping!  Watch watch watch!!  This is delicate stuff you see here, and if we're to win then it must all work perfectly!", completion = "Ah!  Longbeard sent you with a load of helmets!  Hooray!\n\nNow maybe we can talk a pilot into driving our car...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1180] = {title = "Goblin Sponsorship", objective = "Speak with Wharfmaster Lozgil in Booty Bay.", description = "Back to what you came here about. I know I promised Pozzik that I'd deliver a new fuel regulator for him, but I still haven't received it yet. Revilgaz over in Booty Bay said he'd have it shipped over, but it might be it slipped through the cracks somehow.\n\nIf that's true, there's not much we can do about it. We can at least find out if it was dispatched from Booty Bay.\n\nCheck in with Wharfmaster Lozgil over there, he should be able to check the cargo records.", progress = nil, completion = "Shipments to Ratchet? Let me just check the logbooks...\n\nNo, the most recent shipment I have on record of going out to Ratchet were boots from Drizzlik. Hasn't been much else, other than building supplies and tools. Definitely no race parts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1181] = {title = "Goblin Sponsorship", objective = "Speak with Baron Revilgaz in Booty Bay.", description = "I'm afraid I can't be of much more help to you, <name>. If you'd like to follow up on it more, I'd suggest you go hit up the Baron himself. If there's anyone who knows Revilgaz's business, it's Revilgaz.\n\nYou'll find him at the tavern across the harbor, top floor.", progress = nil, completion = "Oh, sure of course I know what you're talking about. Nope, can't help you though. Some of my men were supposed to go track down the blueprints for the fuel regulator, but they came back empty-handed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1182] = {title = "Goblin Sponsorship", objective = "Bring the Fuel Regulator Blueprints to Baron Revilgaz in Booty Bay.", description = "See, the Venture Company shredders out in Lake Nazferiti (in northern Stranglethorn) have been equipped with a new model fuel regulator. I was thinking that Pozzik would be able to take advantage of it, if he could get some details. Unfortunately, Cozzle, the foreman out there, appears to be a little more clever than I gave him credit for.\n\nYou seem like you might have more luck finding the blueprints though. I know he keeps them in his house, but they're almost certainly under lock and key.", progress = "Much as I hate to admit it, that gnome team they have out there is pretty good. Our boys need every edge they can get.", completion = "Now, let me just get a copy of these blueprints for my own notes and you can bring these straight to Pozzik. Wouldn't want him to think that one of his sponsors was abandoning him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1183] = {title = "Goblin Sponsorship", objective = "Deliver the Fuel Regulator Blueprints to Pozzik on the Shimmering Flats.", description = "You should be all set to go. Give Pozzik my regards and tell him that if he ever needs anything, not to hesitate to ask. I'll be waiting for the news that he breaks the track record soon!", progress = "<name>! Did you manage to track down the fuel regulator?", completion = "I was hoping that it would be already assembled, but this does present the unique opportunity to improve on the design from the ground up. Thanks, &lt;name&gt;. I'll be able to sketch up some improved schematics, build the thing, and have it installed real soon.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1184] = {title = "Parts of the Swarm", objective = "Return to Belgrom Rockmaul in Orgrimmar.", description = "Head back to Belgrom in Orgrimmar and tell him Moktar be doing his bidding well out in the Thousand Needles. Tell him also, that me studies progress, and I hope to be havin' learned more soon. That should please him greatly.", progress = nil, completion = "I'm appreciative of your efforts, &lt;class&gt;. The warchief will enjoy hearing how tenacious you have been in your duties.\n\nOh, of course I will mention your name to him. He speaks to me often and values my opinions greatly.\n\nGo now, I have much to do. And if you speak to Korran soon, and he has news of these creatures, then return to me--I would think they are a threat that must be taken seriously.", rewards = "You will be able to choose one of these rewards:\n\nDryleaf PantsBleeding Crescent\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1185] = {title = "Under the Chitin Was...", objective = "Hey, it's you again!  Well, I mean you - as in the you that is <name>!  Yes - that you!\n\nHey, let me start over!\n\nThat object you found in Silithus - it was in fact a book.  It was a journal written in a very ancient dialect of what we now call the Darnassian tongue.  It'll take a while, but I'm going to go over it very thoroughly.  I thought you should know that what you found was extremely valuable for the Circle.\n\nThe den mother's all excited and everything!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1186] = {title = "The Eighteenth Pilot", objective = "Speak with Razzeric on the Shimmering Flats.", description = "I'm going to be busy with working on integrating this new fuel regulator to our racer designs, but if you'd like to help out the team some more, talk to Razzeric. He's our pilot--well, our eighteenth pilot, to be exact--and he likes to add his own little modifications to the racers.\n\nHe's a little off his rocker, though, so try not to act too surprised.", progress = nil, completion = "You're the &lt;race&gt; that's been helping Pozzik out, right? I was like you once, running around the pit area, helping with whatever work the mechanics would let me do.\n\nNow look at me! The goblin racing team's pilot extraordinaire!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1187] = {title = "Razzeric's Tweaking", objective = "Retrieve the Seaforium Booster for Razzeric in the Shimmering Flats.", description = "Pozzik's a great mechanic, I know that, but he's afraid to just load on the firepower and grab on for the ride. Not me, though.\n\nAfter Pozzik finishes with a racer, I take a little time to put my own modifications on--you know, loosening up the controls, removing parts of the frame, and adding more juice!\n\nI ordered a seaforium booster from Shreev at the Gizmorium in Gadgetzan, but apparently the zeppelin it was being sent on crashed in Dustwallow Marsh! I gotta have it, <name>!", progress = "How'm I supposed to show my face around the track without a little extra kick to get me going? It's a travesty, I tell you.", completion = "Just take a look at this beauty! Fifteen pounds of solid seaforium power! Once I get this strapped on to the side of my racer, I'll be around the track so fast I'll beat the gnomes twice!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1188] = {title = "Safety First", objective = "Bring the Seaforium Booster to Shreev in Gadgetzan.", description = "But wait, what's this? Shreev left the safety on. That will limit the amount of power I can draw from the booster at any time. I told him I wanted it off! This is no good.\n\nYou have to take this to the Gadgetzan Gizmorium in the Tanaris Desert and have Shreev remove this.", progress = "As I'm sure you know, the Gizmorium can service all of your tinkering needs! How can I help you?", completion = "Only Razzeric would take a look at this and say that I'd somehow put some sort of safety lock on it. This booster is almost completely seaforium explosives. I already modified it so that more of its payload would be delivered upon use, but Razzeric is never content unless he goes to eleven!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1189] = {title = "Safety First", objective = "Return the Modified Seaforium Booster to Razzeric on the Shimmering Flats.", description = "There, I did what Razzeric wanted. Just tell him to be careful when he sets this off. If he makes the slightest mistake, he won't be moving forward, he'll just be a burnt spot on the track.\n\nWould be a shame, too, if that happened. Who knows if our nineteenth driver would be any good?", progress = "Can you believe Pozzik put a bucket of sand on the racer? How am I supposed to hit my maximum speed with a bucket of sand under the seat?", completion = "Now that's more like it! I wish I could see the look on the gnomes' eyes when they see me set this baby off.\n\nToo bad I'll be too busy pulling off a new course record!", rewards = "You will be able to choose one of these rewards:\n\nRazzeric's Customized SeatbeltRazzeric's Racing Grips\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1190] = {title = "Keeping Pace", objective = "Have Zamek create a diversion, then steal Rizzle's plans for Pozzik on the Shimmering Flats.", description = "The Brassbolts brothers have discovered a new building material, that's the only explanation that makes sense. Their cars have been operating faster than before, but their designs, and all the other data we've gathered from their runs is identical.\n\nWhat we do know, is that Rizzle Brassbolts has been focused on the plans for this new discovery almost constantly.\n\nZamek can create a diversion for you, so that you can steal those plans from them.", progress = nil, completion = "Scribbled in a hasty, hurried hand, a scroll of notes and designs for the refinement of some raw material.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1191] = {title = "Zamek's Distraction", objective = "Let's go!", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1192] = {title = "Indurium Ore", objective = "I'd like to integrate indurium into different parts of our racers, but I need large amounts of raw indurium to create these parts.\n\nYou can find indurium ore in the Uldaman excavation in the Badlands, across the sea in Khaz Modan.\n\nThe gnomes are getting their own supply of it, so it's important we get our own to keep pace with them.", description = nil, progress = "I'd like to integrate indurium into different parts of our racers, but I need large amounts of raw indurium to create these parts.\n\nYou can find indurium ore in the Uldaman excavation in the Badlands, across the sea in Khaz Modan.\n\nThe gnomes are getting their own supply of it, so it's important we get our own to keep pace with them.", completion = "Excellent! I'll get the crew to work right away on the parts we'll need for the next race.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1193] = {title = "A Broken Trap", objective = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.  A hastily written note lies next to the trap, and strangely enough it details exactly what is needed to repair it: a thorium widget and some frost oil.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly.", description = nil, progress = "A large, broken trap lies before you.  From the looks of it, the ogres have tried to repair the trap but to no avail.  A hastily written note lies next to the trap, and strangely enough it details exactly what is needed to repair it: a thorium widget and some frost oil.  Were the trap repaired, an ogre passing near it might get trapped, and could be avoided.\n\nClearly, it would seem fortuitous that very few ogres know how to read.\n\nClearly.", completion = "The thorium widget slides effortlessly into place, creating a conduit to pour the frost oil down.  Once the last drops of oil have been emptied into it, the trap snaps into position.\n\nWoe be to any unwary ogre that should just so happen to wander by!", rewards = nil}
MultiLanguageQuestData['en'][1194] = {title = "Rizzle's Schematics", objective = "Bring the Sample of Indurium Ore to Pozzik on the Shimmering Flats.\n\nProvided item: \n", description = "Rizzle's schematics describe the process of the refinement of indurium ore. From his scrawls, it is apparent that indurium ore is being obtained from the dwarven excavation site of Uldaman in the Badlands.\n\nMuch of the other notes relate to the heat resistant properties.\n\nUsed as a paperweight for the plans is a hunk of what appears to be unrefined indurium ore.", progress = nil, completion = "Indurium? Interesting... If it is capable of resisting heat to the degree that you say, it would explain the performance increase the gnomes have displayed of late.\n\nThis sample you've brought to me will be invaluable, also. I will be able to perform some tests on this, but I'll need more for this to actually be of any use to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1195] = {title = "The Sacred Flame", objective = "Return a Filled Etched Phial to Zangen Stonehoof in Thunder Bluff.", description = "The Galak centaur in the Thousand Needles are protecting an artifact from the time of the centaurs' creation.\n\nWe would like to retrieve it, but we require a phial of water from one of the night elves' moonwells.\n\nTo collect the water, you will first need to obtain one of the phials carried by the dryads near the Raynewood Retreat in the heart of Ashenvale Forest. There is a moonwell near the western bank of the Falfarren River, south of the main road, where you can fill the phial.", progress = "Once we have the filled phial, we can send it along to my associate, Rau, in the Thousand Needles. He was the one who requested the phial of water, so he'll better know how we can make use of it.", completion = "Very good. This should fill Rau's request just fine. Could you deliver this to him? You might enjoy spending some time out in the Needles.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1196] = {title = "The Sacred Flame", objective = "Deliver the Filled Etched Phial to Rau Cliffrunner at the Freewind Post.", description = "Bring the filled phial to Rau Cliffrunner at the Freewind Post in southeastern Thousand Needles. You can get to the Thousand Needles by taking the Great Lift at the southern edge of the Barrens.\n\nI wouldn't be surprised if you can help us out further.", progress = "I don't suppose you've been sent by Zangen, hm?", completion = "Hm, yes, this phial of water will serve our purposes perfectly. Because of the shared ancestry of the dryads and the centaurs, the water of the moonwells will enable us to breach the protection of the eternal flame surrounding the centaur relic.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1197] = {title = "The Sacred Flame", objective = "Retrieve the Cloven Hoof for Rau Cliffrunner at the Freewind Post.", description = "Using the water you brought, you will be able to temporarily douse the flame that holds the centaur relic. It will not work permanently, however, so you will have to be quick about it.\n\nYou will find Splithoof Crag, the centaurs' stronghold, to the north of here. The flame is kept in Splithoof Hold, a heavily guarded part of the crag.\n\nBe careful, though, the Galak centaur have great numbers here, and will be rather reluctant to surrender something so dear to them.", progress = "I am eager to put my hands upon the Cloven Hoof. Have you taken it yet?", completion = "I sense a strange energy emanating from the Hoof... I have no doubt that we will discover surprising new information about the centaur from its study.\n\nMy thanks, &lt;name&gt;. Now I must begin to decipher the mysteries you have brought to me.", rewards = "You will be able to choose one of these rewards:\n\nCliffrunner's AimAzure Sash\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1198] = {title = "In Search of Thaelrid", objective = "Seek out Argent Guard Thaelrid in Blackfathom Deeps.", description = "Many rumors circulate these days about the union of the Twilight's Hammer and the naga in Blackfathom Deeps on the coasts of Ashenvale.\n\nMy role here with the Argent Dawn is to collect as much information as I can, so we know when and where help is needed.\n\nIt has been weeks now since I sent a scout to check on the activity at Blackfathom Deeps. Argent Guard Thaelrid has not yet reported back.\n\nMy other scouts are preoccupied with pressing matters.\n\nSeek out and aid Thaelrid for me, <name>.", progress = nil, completion = "Dawnwatcher Shaedlass was good to send you. There is indeed a wicked plot underway in this corrupted place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1199] = {title = "Twilight Falls", objective = "Bring 10 Twilight Pendants to Argent Guard Manados in Darnassus.", description = "Empowered by the ancient rites of the chaotic Old Gods the members of the Twilight's Hammer strive to bring about the return of their dark patrons and spread death and terror across the world.\n\nWe believe that the Twilight's Hammer has allied with the naga and are amassing in Blackfathom Deeps on the coast of Ashenvale.\n\nWhatever evil plan brews in the depths of the old temple must be thwarted.\n\nWage war on the Hammer and bring back proof of your deeds. Your efforts will be rewarded handsomely.", progress = "Blackfathom Deeps was once an ancient night elf temple. It once housed a most powerful moonwell. Who knows what evil brews there now at the hands of the Twilight's Hammer.\n\nHave you made any progress in ridding their presence?", completion = "You are no doubt of brave and noble blood, &lt;name&gt;. The Argent Dawn commends you for your efforts against evil.", rewards = "You will receive:\n\nNimbus BootsHeartwood Girdle"}
MultiLanguageQuestData['en'][1200] = {title = "Blackfathom Villainy", objective = "Bring the head of Twilight Lord Kelris to Dawnwatcher Selgorm in Darnassus.", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Selgorm in Darnassus, <name>, please.", progress = "Time is a precious commodity, <class>.\n\nMy role here in Darnassus is to ensure that the Argent Dawn thrives and that the evil forces encroaching upon Kalimdor are thwarted.\n\nState your business quickly or be on your way.", completion = "Kelris has eluded us for quite some time.\n\nIt seems as though whenever evil made its presence known in these parts, Kelris had played a role. For some time we considered him dead or missing.\n\nBut this makes perfect sense. By ending his reign you have spared the lives of many innocent people.\n\nBy the light! To sacrifice someone to a servant of an Old God for one's personal gain is beyond reproachful!\n\nYou have done a great deed, &lt;name&gt;. I salute you on behalf of the Argent Dawn.", rewards = "You will be able to choose one of these rewards:\n\nGravestone ScepterArctic Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1201] = {title = "Theramore Spies", objective = "Kill 9 Theramore Infiltrators, then return to Nazeer Bloodpike in Brackenwall Village.", description = "The Horde and Alliance hold an uneasy truce.  Outlying skirmishes and covert actions are taken by one side against the other, and it is our duty to ensure the Horde is on top!\n\nNow is the chance to do just that.\n\nAlliance infiltrators have taken positions east of Brackenwall Village.  They spy on the village and report our movements to Theramore, which we cannot allow.\n\nHunt down the infiltrators and slay them.  Send a clear message to their superiors that we will not tolerate their spies' presence!", progress = "Did you find the infiltrators, <name>?", completion = "Good work.  Their infiltrators are skilled, but they're not good enough to escape the watchful eye of the Horde!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1202] = {title = "The Theramore Docks", objective = "Bring the Captain's Documents to Nazeer Bloodpike in Brackenwall Village.", description = "<name>, two of our spies were sent to steal documents from a ship at the Theramore docks.  They gained the papers but were discovered, and were forced to throw the documents into the sea.\n\nOne spy later escaped, but was unable to recover the prize.  He reported his failure to me, and I now charge the task to you.\n\nThe documents are in a footlocker, in the waters somewhere beneath the Theramore docks.  Find those documents, <name>, and bring them to me.", progress = "Did you find the documents, <name>?  They hold information vital to the stability of the Alliance and, hence, vital to the security of the Horde.", completion = "I commend you, &lt;name&gt;.  This was not an easy mission.  But the documents you gained are valued greatly by our superiors.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1203] = {title = "Jarl Needs a Blade", objective = "Bring Razorspine's Sword to \"Swamp Eye\" Jarl at Swamplight Manor.", description = "I have cutting to do.  I can't tell you what I'm going to cut, but... I need myself a blade.  A certain blade...\n\nSome people call it a sword.  I call it a swing blade.\n\nYou help me?  Those fish-men, you know, murlocs or whatever they're called.... There's one they call Razorspine, carries a big sword, lives north of here near the beach. That's the sword I need!\n\nBut don't sleep on this.  What I'm cutting won't keep forever...", progress = "You have my blade??", completion = "That's a good blade.  It has a good swing.  It's a good swing blade.  Thank you.  Thank you, thank you, thank you!!!  Now I want to try it....  \n\nLater.  I'll try it later.  But like I was saying... thanks.", rewards = "You will receive:\n\nReedknot RingArtisan's Trousers"}
MultiLanguageQuestData['en'][1204] = {title = "Mudrock Soup and Bugs", objective = "Bring 8 Forked Mudrock Tongues to Morgan Stern in Theramore.", description = "I'm working on a dish I call \"Mudrock Soup and Bugs.\"  I still need the major ingredients, and... well, I don't think I'd last long trudging through Dustwallow Marsh!\n\nSo, <name>, can you do some hunting for me?  First, I need the tongues of Mudrock turtles.  You can find Mudrocks along the coast, mostly around the bay.\n\nBut I don't want just any tongues!  I hear that the tongues of some Mudrocks are forked...\n\nThey say the forked tongues have a distinct flavor, and I want that flavor in my dish...", progress = "Did you get the forked tongues?", completion = "These will do fine!  Thank you, &lt;name&gt;!\n\nNow I'll try different cooking techniques on these tongues to find the best way to bring out their flavor.\n\nEventually I'll have a dish worthy of serving at the Blue Recluse in Stormwind!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1205] = {title = "Deadmire", objective = "Bring Deadmire's Tooth to Melor in Thunder Bluff.", description = "Deadmire is an ancient crocolisk in Dustwallow marsh.  And it is his time to die.\n\nOld bones grind as he pulls his huge body through the swamp, and although he still moves with the strength and speed of youth, his aging body tortures the great spirit within it, a spirit whose flame will not waver.\n\nYet now he lives in constant, maddening pain.  You must end the life of this noble creature, <name>.  You must lead Deadmire to peace.", progress = "Do you have the tooth of Deadmire, <name>?  Have you ended the creature's suffering?", completion = "Very good, &lt;name&gt;.\n\nI am sure the hunt was not easy, but it is good to know the beast's pain has finally ended.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1206] = {title = "Jarl Needs Eyes", objective = "Bring 20 Unpopped Darkmist Eyes to \"Swamp Eye\" Jarl at the Swamplight Manor.", description = "Eye juice is good juice for drinking.  Too bad most critters only have two eyes.\n\nBut spiders have lots of eyes.  Lots and lots.  And Darkmist eye juice is tasty.  Smooth and salty!  Unpopped spider eyes... I taste them already.\n\nDarkmist spiders are west of here, in the Darkmist Cavern.  You figure the spiders are named after the cave... or is it the other way around?", progress = "Where are those eyes?", completion = "You got the eyes!  You got the eyes!  Tasty, tasty spider eyes!\n\nSome eyes... when you stare at them they stare back. Eat those last.  They keep you company... out in the swamp.\n\nHello, little spider eyes.  Hello!  You taste like chicken.  Gooey, salty chicken!\n\nMmmh.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1218] = {title = "Marsh Frog Legs", objective = "Bring 10 Marsh Frog Legs to \"Swamp Eye\" Jarl in Dustwallow Marsh.", description = "I like cooking.  Good swamp cooking.  Fried green frog legs and the like.\n\nAnd I'm all out of legs. The manor is overrun with frogs, though. Giant marsh frogs. Think you could bring me some of those legs? Nothin' to it, really. Just bop 'em on the head and bring me the legs.\n\nThen I'll make a stew and stew it up and suck it down and give you some too.\n\nDo you like stew?", progress = "Spice.  We could all use some spice in our life.  You agree?", completion = "Ah, that's the spice!  Now here's some swampy good stew.", rewards = "You will receive:\n\nFrog Leg Stew"}
MultiLanguageQuestData['en'][1219] = {title = "The Orc Report", objective = "Bring the Spy's Report to Lieutenant Aden in Theramore.", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is written in orcish... and it looks important.", progress = "Do you have a report to make?", completion = "Hm... I can't read orcish very well, but this looks like a report... written by an orc spy!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1220] = {title = "Captain Vimes", objective = "Bring the Spy's Report to Captain Garran Vimes.", description = "Captain Vimes should see the orc report you found, <name>.  He knows the orcish language better than most.  And he should know that there are Horde spies near Theramore!\n\nThe captain is in the barracks, on the northeastern side of Theramore Isle.", progress = "You have something for me?", completion = "A report from an orc spy!  How did you find this?  No matter -- let's see what it says...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1221] = {title = "Blueleaf Tubers", objective = "Grab a Crate with Holes.\nGrab a Snufflenose Command Stick.\nGrab and read the Snufflenose Owner's Manual.\n\nIn Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers.\n\nBring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.", description = "Blueleaf tubers are a delicacy around the world!  But they're rare, very rare.  The only place to find them is here in the Barrens, deep in the earth, in Razorfen Kraul.\n\nAnd even then, they're impossible to find unless you know just where to look!  That's why I've trained these snufflenose gophers to find them for me.  They have great noses and can smell a tuber from fifty paces away.\n\nIt won't be easy, but if you get me some tubers I'll pay you handsomely.", progress = "Do you have the tubers, <name>?", completion = "Great, you got them!  I can sell these to my contacts for a bundle!\n\nThanks for the delivery, &lt;name&gt;!  You are a great partner.", rewards = "You will receive:\n\nA Small Container of Gems"}
MultiLanguageQuestData['en'][1222] = {title = "Stinky's Escape", objective = "Escort \"Stinky\" Ignatz, then speak with Morgan Stern in Theramore.", description = "Great, finally something that doesn't want to eat me!\n\nI need help handling the critters around here, and you fit the mold, <buddy/lady>.\n\nThe cook Morgan Stern is researching a new recipe, and he sent me out here to gather bogbean leaves.  I guess he thinks they're tasty.\n\nAnyway, while looking for a bogbean plant... I got myself surrounded!  Can you help me out of here, and watch my back as I look for the bogbean?", progress = nil, completion = "Mr. Ignatz was just here with the bogbean leaves, and he told me you helped him out of some real trouble.\n\nThank you, &lt;name&gt;.  I will ask my uncle to treat you to a feast the next time you visit the Blue Recluse in Stormwind.", rewards = "You will receive:\n\nElixir of Fortitude"}
MultiLanguageQuestData['en'][1238] = {title = "The Lost Report", objective = "Bring the Spy's Report to Nazeer Bloodpike in Brackenwall Village.", description = "Sifting through the loose dirt, the severed hand of an orc is found.  And clutched in the hand is a bone-carved tube.  And in the tube is a dirt-stained parchment.\n\nThe parchment is a report made by an orc who spent weeks spying on the city of Theramore.\n\nAfter scanning the parchment, it is clear that it must be brought to the orc spymaster in Brackenwall Village.", progress = "You have something for me?", completion = "Good work, &lt;name&gt;.  Our agent, Marg Nighteye, was stationed outside Theramore.  He was charged to spy on the city.  \n\nThis is his latest report, and it may be his last -- from your testimony, I fear that Marg met his end in the swamp...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1239] = {title = "The Severed Head", objective = "Bring the Defiant Orc Head to Nazeer Bloodpike in Brackenwall Village.", description = "Vigorous digging reveals the head of a male orc, raggedly severed at the neck.  His lips are frozen in a snarl, and its dark eyes stare defiantly.", progress = "You have another matter to report, <name>?", completion = "This is the head of Marg Nighteye!  As I feared, he is dead.\n\nLook at the wound on his neck!  Could a weapon have made that ragged cut, or did some beast slay our agent?\n\nThis is a mystery we must solve, &lt;name&gt;.  We must discover if Marg's death was at the hands of the Alliance!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1240] = {title = "The Troll Witchdoctor", objective = "Take the Defiant Orc Head to Kin'weelay in the Grom'gol Base Camp in Stranglethorn Vale.", description = "We must know the events surrounding Marg's death!  And the only way to do that, <name>, is through the witch-magic of trolls.\n\nBring Marg's head to Kin'weelay in Stranglethorn Vale, at the Grom'gol Base Camp.\n\nKin'weelay is the most powerful witchdoctor of the Darkspear trolls.  If anyone can speak to Marg Nighteye's spirit, it is he.", progress = "There is an angry spirit about you, brother.  What brings you to Kin'weelay?", completion = "Ah, I now see.  The spirit of this orc is bound in our world, boiling with rage from a task yet undone.\n\nWell, let us have words with this angry orc...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1241] = {title = "The Missing Diplomat", objective = "Find Jorgen in Stormwind City.", description = "Recently a diplomat was sent to Theramore to meet with Jaina Proudmoore. That diplomat never arrived.\n\nI believe the Defias are involved in this plot, but I'm not sure how. The diplomat's disappearance still eludes public attention, but it can't remain that way for long.\n\nAgents of the king are already scouring the city for clues, but I have my own contacts I would like involved.\n\nIn the Valley of Heroes is an old friend of mine named Jorgen. Find him, give him this note, and follow his instructions.", progress = "Hmph, you better have good reason to interrupt a man and his fishin'. I don't take kindly to peddlers, let alone beggars.", completion = "Hmm... &lt;Jorgen looks up at you through squinted eyes.&gt;\n\nAll right. I'll help ya, but not because I want to, but because I'm obligated.\n\nAnd let's get one thing straight: you're knowin' far more than you should to begin with. Let's keep this our little secret, and don't go blabbin' at any taverns about anything you find out. Understand?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1242] = {title = "The Missing Diplomat", objective = "Delivery Jorgen's Sealed Note to Elling Trias in Stormwind City.", description = "Take this here note to Elling Trias. Don't say nothin' else to him. Just be polite and wait for him to respond. And don't worry, he will.\n\nI'm gonna only impress this on ya once more, <name>: treat this matter seriously, and keep your yapper shut.\n\nYa can find Trias at his cheese shop, Trias' Cheese, in the Trade District. Good luck.", progress = "Hello, <name>. Is there something I can do for you? Perhaps you'd like to try some of our special Trias cheddar? Or a block of Darnassian bleu?", completion = "I'm sorry, a letter for me? Well, I'll be... not often you get a delivery that's not a crate or barrel when all you do is work. Let's see what this is about.\n\n&lt;Elling looks up at you while he opens the letter.&gt;\n\nYou look a little tense, you okay, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1243] = {title = "The Missing Diplomat", objective = "Give the Sealed Note to Watcher Backus in Duskwood.", description = "Jorgen, you ol' sonuva.... So, that's how it's going to be, huh?\n\nAll right, I can deal with that. I hope he finds the Twisting Nether that much sooner!\n\nHere's what's gonna happen, <name>. I'll start using my contacts here, but you're doing most of the footwork so I save some coin.\n\nHead to Darkshire in Duskwood and find Watcher Backus--he usually patrols the north road right outside of town. Just tell him you're looking into any Defias activity for me and he'll help you out with any information he can.", progress = "Not too safe to be traveling about in the woods, <name>. Be careful, and if you see anything suspicious or dangerous, contact the Watchers immediately. Don't try and take anything on yourself. We're not responsible for anything terrible that might happen to you.\n\nBut we both know you're gonna ignore me and fight whatever comes out of the darkness anyway, don't we? Haha, yeah, you adventurer types... all the same.", completion = "Oh, Trias sent you, huh? That's a little different.\n\nFeel free to fight whatever monstrosities come at you from the darkness. I'm sure you'll be able to handle it pretty easily if you're the type to be hanging around with the likes of him.\n\nSo, what does my friend need of me on such a gloomy day as this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1244] = {title = "The Missing Diplomat", objective = "Find the Defias Docket and return it to Watcher Backus in Duskwood.", description = "Defias activity? Well, there's always some activity; even if they keep to themselves we consider them a threat.\n\nBut now that I think about it, there was a recent sighting that seemed odd. It must have been a couple weeks ago, but some of their agents had gathered around Addle's Stead. From the report, I'd guessed something big went down.\n\nWhy don't you check there first and bring me back anything you find?\n\nThe farmstead is south of the road from Westfall just as you enter Duskwood.", progress = "Be careful out there, <name>. I know Trias was the one to send you here, but that doesn't mean there isn't anything lurking out in the woods that couldn't cause you some trouble... especially with you investigating the Defias.", completion = "You're back safe and sound. Couldn't ask for much more than that, could you?\n\nNow, let's see what we have here. This looks pretty official as far as any Defias documents I've seen. But it could be a dupe just to throw you off track of whatever it is you're looking for.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1245] = {title = "The Missing Diplomat", objective = "Bring the Defias Docket to Elling Trias in Stormwind.", description = "Whoa, this looks way too complex to be something to just lead you astray. I shouldn't even be looking at this stuff. Take it to Trias--he'll be able to make sense of it. And DON'T let anyone get in your way. This is bigger than me. It might even be bigger than him, but we'll see.\n\nAnd do me a favor, <name>, don't tell anyone I helped you. If my superiors found out I knew about any of this and didn't share it with them they'd probably hang me.", progress = "I see you're back, and in one piece. We both know you're not here for cheese, so let's cut out the pleasantries. Was Backus any help, or have you even left for Duskwood yet?", completion = "Yeah... this is an interesting read. Jorgen and DeLavey were smart to bring me in on this.\n\nSeems the Defias have been trying pretty hard to complete this plan of theirs. Hmm... what's this? \"Fist\"? That's a familiar name.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1246] = {title = "The Missing Diplomat", objective = "Speak to Dashel Stonefist in Stormwind.", description = "Yeah, now that I think about it... Dashel... Dashel something... What was his name? FIST! Dashel Stonefist. They call him Fist in some circles--probably on account that he likes to get in brawls.\n\nYou can find him in Old Town usually--right smack dab in the center of it. Go talk to him. If you have to, use a sword or something heavy and blunt to persuade him to open up some. And don't hesitate. If he's in this as deep as these papers suggest, then he's not going to give you any information willingly.", progress = nil, completion = "What?!\n\nYou come into me alley and ask questions about me personal business? Business which you obviously have nothing to do with.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1247] = {title = "The Missing Diplomat", objective = "Speak to Elling Trias in Stormwind.", description = "So yeah... um... I might know something 'bout that meeting at Addle's Stead. Happened a few weeks back I think. I really didn't have any part in it. Me part was done when plan A failed... damn adventurers.\n\nThe guy we got on the inside for plan B came out of Menethil; guy called Slim. That's all I know regarding their backup plan.", progress = nil, completion = "Good to see you're still alive, &lt;name&gt;. So, it went well with Dashel then, huh?\n\nI've been reading up more on this plan of theirs, and although it doesn't state the name of the diplomat they were after, it does talk about this plan B they enacted after failing on their first attempt to capture him.\n\nThis Slim that Dashel mentioned doesn't have any other name written here, but if you say he's in Menethil, then that's a start.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1248] = {title = "The Missing Diplomat", objective = "Speak to Mikhail in the Wetlands.", description = "A contact of mine retired in the Wetlands at the harbor city of Menethil. He should be willing to help on your word alone if you tell him you're working for me. His name is Mikhail. He mentioned becoming a bartender before leaving Stormwind a few years ago.\n\nSpeak to him, find this Slim, and find out if there's anything else to know about this kidnapped diplomat. We need to find out where they've taken him, or at least who he is. The docket doesn't mention anything about their plans after he's captured.", progress = nil, completion = "Welcome, welcome, welcome, &lt;name&gt;. Good of you to join us. Perhaps an ale today? Or some mutton?\n\nName your pleasure and I'll see to it that you're taken care of. My name is Mikhail, and I look forward to serving you.\n\nHmm? What's that? Trias? Keep your voice down, my friend. This isn't something for the whole tavern to hear about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1249] = {title = "The Missing Diplomat", objective = "Subdue Tapoke Jahn before he escapes, and then return to Mikhail in Menethil.", description = "You say Elling sent you here? Well then, the hospitality I expressed is now tenfold. Anything you need, just ask. I will do my best to aid you.\n\nHmm, Slim, you say? Not sure the name sounds familiar, but I'll keep my eyes out for him.\n\nDon't look now, <name>, but the gentleman over by the exit is looking over here. He's listening to our conversation a little too intently if you catch my meaning? If I were you, I'd do what you can to subdue him before he makes a break for the door.", progress = "Did he slip away? He looked a little shady the way he was watching us.", completion = "Caught him, huh? Good for you. I'm surprised that was Slim.\n\nI'll be honest, I never thought I'd miss the excitement of some of the more devious underground activities. I guess old habits die hard. Don't mention that to Elling--he'd probably try and get me to come back to Stormwind if he heard I missed the action.\n\nI'm glad I could at least be of a little service to you while you were in Menethil. If you need anything else, just ask.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1250] = {title = "The Missing Diplomat", objective = "Speak to Mikhail in the Wetlands.", description = "The Defias didn't pay me well enough to die for their cause. They took the king. Yeah, the king of Stormwind, not some lowly diplomat. He was on his way to Theramore to meet with Jaina Proudmore--it was a big deal apparently, and a big secret. But it's not just the Defias that are involved. They're working with someone. I think they knew this was bigger than them.\n\nMy part was just to get their man on board the king's ship while it was in the harbor. The guy's name was Hendel. That's all I know. I swear!", progress = nil, completion = "THE KING?! I mean... the king? The real king? Are you joking? You didn't mention you were looking for the king's kidnappers. I didn't even hear he was missing--that would explain his son being crowned some.\n\nI'll send word to Elling right away. He'll want to know you're on the trail.\n\nI would never have guessed Jahn would sell out Stormwind for some lousy coin. Even a rogue's got to have honor when it comes to some things.\n\nThe key now is to find this Hendel. And I think I can help with that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1251] = {title = "The Black Shield", objective = "Bring the Blackened Iron Shield to Krog in Brackenwall Village.", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "What's that you have there, <name>? Evidence from the remains of the Shady Rest Inn?", completion = "I grant that humans have strange decorating tastes, but would they use a plain iron shield to adorn their fireplace? Perhaps this shield was placed there by the ones who burned the inn.\n\nA warning? A threat?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1252] = {title = "Lieutenant Paval Reethe", objective = "Bring Reethe's Badge to Captain Garran Vimes in Theramore.", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing away debris and ash caked onto the object reveals the insignia of a gold anchor on white enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found anything of interest at the Shady Rest Inn?", completion = "It's never good news when a guard's badge is brought to me.\n\nSometimes it's a man or woman who's fallen in battle, and I'm left to bring the news to the grieving family. Other times we never find out what happened to them. And other times it's even worse than that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1253] = {title = "The Black Shield", objective = "Bring the Blackened Iron Shield to Captain Garran Vimes in Theramore.", description = "An iron shield, blackened by the fire that raged through the inn, is affixed to the crumbling chimney, one of the few remaining parts of the structure that once made up the Shady Rest Inn.\n\nThe shield can be removed from the brick of the chimney.", progress = "Have you found evidence from the site of the Shady Rest Inn?", completion = "Hm, I'm no expert with the construction of arms and armor. Their use, yes, but not their making.\n\nThis shield seems as ordinary as any, excepting the damage from the fire that engulfed the inn.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1258] = {title = "... and Bugs", objective = "Bring 12 Pristine Crawler Legs to Morgan Stern in Theramore.", description = "Another component of my new recipe is the shelled leg of a giant crab.  And the crabs they have in Dustwallow -- Muckshells they call them -- just won't do!  I'm afraid the only suitable crabs live far away, in the Swamp of Sorrows.\n\nThe shell of the crab leg is a key element of the dish's presentation so I need pristine, unscarred legs.  An adult crab might only have one or two such legs, and I need a lot in order to research my dish.\n\nSo, <name>... are you willing to travel?", progress = "My research with the Mudrock tongues is progressing nicely.  I trust your crab hunt goes well?", completion = "These are wonderful specimens, &lt;name&gt;!  The shells are in perfect condition, and the meat is pink and tender.  The blood of a chef is in your veins, I'm sure of it!", rewards = "You will receive:\n\nBaroque Apron"}
MultiLanguageQuestData['en'][1259] = {title = "Lieutenant Paval Reethe", objective = "Find out more about Reethe from Adjutant Tesoran in Theramore.", description = "I don't recognize the name of Lieutenant Paval Reethe. Your best bet would be to check with Adjutant Tesoran. He keeps track of all the records for the Theramore guard, from personnel to their equipment.\n\nHe should be able to tell you who this Reethe is with a quick check of his books.", progress = nil, completion = "Hello, &lt;name&gt;. You'd like information about a specific member of the Theramore guard? Reethe, was it?\n\nJust give me a moment to find the right book.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1260] = {title = "Morgan Stern", objective = "Speak with Morgan Stern in Theramore.", description = "I'm developing a new menu for the restaurant.  It will be filled with rural dishes with a \"bayou\" theme.  I think my clientele at the Blue Recluse will love them!\n\nI sent my nephew Morgan to Theramore, a city on the edge of the Dustwallow Marsh.  He's there gathering recipes from the locals, and I must know what he found so far.\n\nThe trip to Theramore is long.  Too long for me.  But I bet a young <class> like yourself would jump at the chance to travel, yes?", progress = nil, completion = "Oh, my uncle sent you, did he?\n\nWell I've been researching recipes and I have some leads, but I need help.\n\nHelp from someone willing to get his feet wet.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1261] = {title = "Marg Speaks", objective = "Bring the Jeweled Pendant to Nazeer in Brackenwall Village.", description = "Cursed muckshell!  You can't kill Marg!  Ah, but I am dead.  So it must have slain me...\n\nBut my mission!  My mission!  You, <name>, must complete it.\n\nWhile near Theramore, I spied a group of Alliance soldiers camped on the beach.  And one soldier wore a pendant... a pendant laden with more gems than any soldier could afford!\n\nThat night I snuck into their camp and stole the pendant, but on my return to base a muckshell crab-man killed me!\n\n<name>, you must find that muckshell and recover the pendant!", progress = "<name>, did you discover Marg's fate?", completion = "This pendant was worn by a soldier of Stormwind??\n\nThank you, &lt;name&gt;.  You have revealed the secret of Marg's death.  But this pendant is a new mystery to solve, one that may have dire effects on the Alliance, and the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1262] = {title = "Report to Zor", objective = "Bring the Jeweled Pendant to Zor Lonetree in Orgrimmar.", description = "It is strange that the pendant Marg stole was in the hands of common soldiers.  Perhaps its owner was in disguise, or perhaps the soldiers themselves stole it!\n\nRegardless of which is true, this is a noble's pendant and we must discover its true owner if we are to unravel its mystery.\n\nTake the pendant to Zor Lonetree in Orgrimmar.  He is well schooled in Alliance politics, and will know if this pendant has a history among the nobles of Stormwind.", progress = "You traveled from Brackenwall Village in Dustwallow?  How fares Nazeer, and how fare his efforts in the marsh?", completion = "This pendant was crafted with great skill and precision, &lt;name&gt;.  No orc would covet such a jewel...\n\nBut many humans would.\n\nI will have this pendant studied.  In time let us hope that its mysteries will be revealed to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1263] = {title = "The Burning Inn <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1264] = {title = "The Missing Diplomat", objective = "Find Commander Samaul in Dustwallow Marsh.", description = "The beginning of every month the Kul Tiras Marines all get paid and usually leave Theramore for somewhere else. A lot of them come here to womanize, carouse, and just have a good time. One of those groups I'd consider regulars here at the tavern, and I believe this Hendel is among them.\n\nCommander Samaul in Theramore would be able to help you find him if Hendel's still stationed there. He's completely loyal to Proudmoore, but if you drop Elling's name, he should help you out... discreetly.", progress = nil, completion = "A pleasure to meet you, &lt;name&gt;. I am Commander Samaul. I'm in charge of Miss Proudmoore's forces here in Theramore.\n\nAlthough I'm quite busy, if you have any questions, please feel free to speak up. I might have to keep it short, but there's no reason for me to be rude if you need my help.\n\nIf you plan on traveling out of the city, I'd suggest you be careful. Besides ogres, orcs and murlocs, the southern part of the swamp is filled with black dragons.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1265] = {title = "The Missing Diplomat", objective = "Search Sentry Point for any sign of Private Hendel.", description = "Hendel? Yes, I know the man. But why would you need one of my soldiers?\n\nElling sent you to find him? Hmm, I don't like the sound of that. Elling wouldn't have you come to me first if your business wasn't troubling. I understand if you can't tell me what this is about, but know this: I have a duty to protect these lands. If you're going to cause a disturbance, then I suggest you inform me of whatever you can.\n\nI believe Hendel was stationed at the first tower outside of Theramore. Be cautious.", progress = "Yes, <name>?", completion = "The man you seek, the one known as Hendel, is not here. Other sources have brought to the Lady Proudmoore information I believe you already know. She has asked me to find you, and give you aid in your venture. If you would allow it, I will tell you where to find Private Hendel so we can bring him to justice.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1266] = {title = "The Missing Diplomat", objective = "Find Private Hendel in Dustwallow Marsh.", description = "Private Hendel is to the west of here. He's currently on guard duty protecting some of Theramore's infiltrators while they rest. They've been keeping tabs on the Horde base, Brackenwall, and looking for anything else that might threaten our borders.\n\nYou should have no problem finding him; just look for the tents along the road.\n\nI have another matter to attend to, but I shall catch up to you soon enough. You can always find me in the Lady Proudmoore's tower if you have any problems.", progress = nil, completion = "Hello, citizen. This is a dangerous place to be wandering about. I wouldn't hang around too long if you value your life.\n\nIf you keep your questions short, I'll see if I can help you. Just keep your eyes open for any of those filthy ogres. Rumor has it there's a Horde base somewhere in the swamps. The infiltrators are doing what they can to find it, but the process has been slow going and we've had little progress.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1267] = {title = "The Missing Diplomat", objective = "Speak to Jaina Proudmore in Dustwallow Swamp.", description = nil, progress = nil, completion = "Let me be first to thank you for all you've done, &lt;name&gt;. You have been an incredible blessing to my people and the people of Stormwind. I am sorry I couldn't make your acquaintance under better circumstances.\n\nUnderstand also that I cannot overtly thank you for your efforts, but I assure you again, it is appreciated.\n\nWhen you visit Theramore in the future, seek me out and I shall try to keep you apprised of the situation.\n\nThank you again, &lt;name&gt;.", rewards = "You will receive:\n\nJaina's Signet Ring"}
MultiLanguageQuestData['en'][1268] = {title = "Suspicious Hoofprints", objective = "Report about the suspicious prints at the Shady Rest Inn to Krog in Brackenwall Village.", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", progress = nil, completion = "Hoofprints... It could have been the quilboar, I suppose. Or maybe even the centaur. Their presence in the Barrens is not insignificant, and I would not think it a stretch to commit such an act.\n\nDid I tell you? It wasn't just that the inn was burned down... The owner's woman and pup were killed. Bad business, that.\n\nNonetheless, I will send Kagoro to find where the tracks lead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1269] = {title = "Lieutenant Paval Reethe", objective = "Bring Reethe's Badge to Krog in Brackenwall Village.", description = "A glint of light on the ground catches your eye from underneath the rubble. Brushing debris and ash caked onto the object reveals the insignia of a gold anchor on white, enameled on the surface: the sign of Theramore.\n\nUnderneath the anchor is embossed the name \"Lieutenant Paval Reethe\".", progress = "Have you found any leads on what happened at the Shady Rest Inn?", completion = "I know this human, Paval Reethe. Pathetic, even for his kind. He deserted his fellow soldiers and is now hiding out in the woods.\n\nI sent Ogron out to track him down. Some of the others suspect he's been stealing from our supplies. I think I saw Ogron heading off to the southeast.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1270] = {title = "Stinky's Escape", objective = "Escort \"Stinky\" Ignatz, then speak with Mebok Mizzyrix in Ratchet.", description = "Great, finally something that doesn't want to eat me!!\n\nI need help handling the critters around here, and you fit the mold, <buddy/lady>.\n\nA goblin from Ratchet named Mebok Mizzyrix needs some bogbean leaves for a potion, or something... I honestly don't care why -- his money was good and I know this swamp, so here I am.\n\nToo bad I got myself surrounded before I found the bogbean!  Can you help me out of here, and watch my back as I look for Mebok's plant?", progress = nil, completion = "Stinky was here with the herbs I ask of him, and he told me you helped him out of a bind.  Good work!  A friend of Stinky's is a friend of mine!\n\nHe asked me to give you this if I ever saw you, right before he walked back south toward the marsh.", rewards = "You will receive:\n\nElixir of Fortitude"}
MultiLanguageQuestData['en'][1271] = {title = "Feast at the Blue Recluse", objective = "My nephew said you aided him with his research in Dustwallow, and that you helped his associate out of a tight spot.  Well, we Sterns stick together and we don't ignore our friends!\n\nSo wash your hands, <name>, because we're about to throw a party in your honor!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nMoist Towelette"}
MultiLanguageQuestData['en'][1272] = {title = "Finding Reethe <CHANGE INTO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1273] = {title = "Questioning Reethe", objective = "Go with Ogron to speak with Reethe, then return to Krog in Brackenwall Village.", description = "It took a long time, but I found Reethe. He hide good for a human.\n\nOgron worried that he might be crazy after so much time in swamp. You come with me for we go get answers from him.", progress = nil, completion = "Hmph. It is good that Reethe will no longer be lurking around the swamp, but it is a shame that humans are built so frail that he could not recover from a little arrow wound.\n\nIt seems that this thread of the mystery has led nowhere, and we must look elsewhere.", rewards = "You will be able to choose one of these rewards:\n\nEyepokerBlasting Hackbut\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1274] = {title = "The Missing Diplomat", objective = "Find Bishop DeLavey in Stormwind Keep.", description = "Excuse me, <sir/madam>. Bishop DeLavey asked me to approach adventurers that might be able to help him with a delicate matter.\n\nIf you could quietly head to Stormwind Keep and speak to him at your earliest convenience, I'm sure he would appreciate your help. Again, please be discreet. It is a matter of some importance.", progress = nil, completion = "Hello, &lt;name&gt;. I am Bishop DeLavey.\n\nNo doubt if you're asking me about my business here in the keep then young Thomas has succeeded in requisitioning you to help our kingdom. He has always been adept at following my requests.\n\nI'm afraid I don't have time to elaborate much, so allow me to be blunt... and please, try to keep this from becoming common knowledge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1275] = {title = "Researching the Corruption", objective = "Gershala Nightwhisper in Auberdine wants 8 Corrupt Brain stems.", description = "Foolish blood elves toil with demonic magic. Have they not witnessed what happened with the naga and with the satyrs of Kalimdor?\n\nI fear that the blood elves will meet a similar deformation. Azeroth cannot afford to give birth to another vile race of monsters.\n\nI wish to study the brain stems of the satyr and naga so that I might deduce what fate the elves are headed toward. In Blackfathom Deeps, on the coast of Ashenvale, you will find both satyr and naga.\n\n'Tis a long journey, <name>.", progress = "Once I have enough samples to study, my true work can begin. With the corrupted brain stems of both the satyr and naga of Blackfathom Deeps I can try to draw a correlation between the mutations.\n\nPerhaps with that gained knowledge we can prevent the blood elves from delving deeper into deformity and evil.", completion = "You have traveled far and undoubtedly faced great peril.\n\nYour actions have been selfless. 'Tis for the good of all Azeroth that you help me with my research. I thank you, &lt;name&gt;, for all that you have done.\n\nNow if you'll excuse me I have much work to do....", rewards = "You will be able to choose one of these rewards:\n\nBeetle ClaspsPrelacy Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1276] = {title = "The Black Shield", objective = "Show the Blackened Iron Shield to Mosarn in Thunder Bluff.", description = "Ah, I remember now! Mosarn is a well-respected blacksmith in Thunder Bluff. I knew I had heard his name somewhere, before.\n\nIn thanks, the Earthen Ring awarded me with a set of armor crafted by Mosarn. Very good work.\n\nPerhaps he can tell you more about the shield he crafted.\n\nIt's not much of a lead, but since we didn't get anything useful out of Reethe, it's all we have.", progress = "Hello there, <class>. Something I can help you with?", completion = "Yes, you are certainly correct. This is a shield that I made.\n\nI'm afraid there's not much more I can tell you though, &lt;name&gt;. I craft so many different shields and sets of armor, I can't keep track of them all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1281] = {title = "Jim's Song <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1282] = {title = "They Call Him Smiling Jim", objective = "Speak with Captain Garran Vimes on the top floor of Foothold Citadel.", description = "I can't help it if I feel sorry for ol' Jim there. He wasn't always like that. Ran an inn out in the marsh for a while, wonderful place.\n\nLook, I don't really want to talk about it. Bring it up with Captain Vimes if you really have to. He's stationed on the top floor of Foothold Citadel, the large barracks to the east of Lady Jaina's tower.", progress = nil, completion = "James Hyal's his real name. He opened an inn at the edge of the Barrens. Wanted to make a nice place for travelers to stop over...\n\nMight be he was thinking too big, but the inn did do well for a while. Then we lost control of the roads in the marsh, and the ogres took over.\n\nJames was too stubborn to give up his dream for safety within our walls, and the Shady Rest Inn was burnt to the ground. We're investigating, but haven't had much luck. If you want to help out, see what you can find in the rubble.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1283] = {title = "Fire at the Shady Rest <CHANGE TO GOSSIP>", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1284] = {title = "Suspicious Hoofprints", objective = "Report about the suspicious prints at the Shady Rest Inn to Captain Garran Vimes in Theramore.", description = "Rows of hoofprints lead away from the still-smoking skeleton of the Shady Rest Inn. There are at least a few visible impressions, with more rows of prints almost imperceptible in the soft mud of the marsh.", progress = nil, completion = "Hoofprints, eh? It is true that there is an extraordinary amount of centaur activity in the lands near the Dustwallow Marsh. In brief excursions into the Barrens, we found their camps and holdings dotting the area.\n\nI'll send out Falgran Hastil, one of our trackers, to see if he can find where the tracks lead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1285] = {title = "Daelin's Men", objective = "Return the information about Reethe to Captain Garran Vimes in Theramore.", description = "Reddon... Redpath... Ah, here it is! Lieutenant Paval Reethe.\n\nJoined the Theramore guard along with most of the recruits that came across the sea with Lady Proudmoore. Enlisted with the marines of Kul Tiras at the age of sixteen. Distinguished service, promotions...\n\nListed as missing.", progress = nil, completion = "Missing? That would be Tesoran's kind way of saying traitor.\n\nNo doubt he's one of those fools so blindly loyal to Admiral Daelin that he turned traitor.  Isn't that a delicious irony? The deserters accuse us of betraying the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1286] = {title = "The Deserters", objective = "Get information about Reethe from Balos Jacken and the deserters in Dustwallow Marsh.", description = "It has been a struggle maintaining a presence in the marsh, but through strength of our resolve, we have been able to maintain several defensive watchtowers throughout the area.\n\nThe latest information and scouting reports I have received indicate that a group of deserters has squatted in our abandoned tower at Lost Point, southeast of the inn.\n\nThe local lieutenant seems to be Balos Jacken. See if you can get some information out of him.\n\nBe warned, <name>. He may be a tough nut to crack.", progress = nil, completion = "Did Vimes send you? Couldn't do his dirty work himself, could he...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1287] = {title = "The Deserters", objective = "Speak with Captain Garran Vimes in Theramore about Reethe.", description = "Reethe? That coward?\n\nWe threw him out of camp because he insisted on raiding the supplies of the ogres up at Brackenwall Village. We're not so many in number that we could stand up to those mindless brutes.\n\nHe crossed the line one too many times, so we left him to fend for himself.\n\nNow, I helped you out... So, why don't you help us out and forget you bumped into us?", progress = nil, completion = "I will send Lieutenant Caldwell to deal with the deserters at Lost Point. In addition, I will instruct him to find Reethe. The marsh is not so big and trackless that he should be unable to find him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1288] = {title = "Vimes's Report", objective = "Bring Vimes's Report to Lady Jaina Proudmoore in Theramore.", description = "You've done some good work, <name>, best I've seen from an amateur.\n\nLady Proudmoore asked that I keep her apprised of this delicate situation, and I haven't spoken to her for some time now.\n\nI was going to deliver my report to her later, but it seems more fitting that you should be the one to speak with her about it. You can probably answer her questions better than I could.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1301] = {title = "James Hyal", objective = "Speak with Vincent Hyal in Menethil Harbor.", description = "Before working here at the Blue Recluse, I was trained by one of the best chefs and innkeepers I'd ever met. His name was James Hyal. Everything I have and everywhere I've gotten in life is thanks to him.\n\nI wonder how he's doing. His brother Vincent and he went to work in a tavern in Menethil Harbor, but I haven't heard from him recently.\n\nIf you ever happen to be headed in that direction, maybe you could say hello to him for me?", progress = nil, completion = "James? Oh, he left quite some time ago.\n\nFelt the second wind of patriotism, I suppose. Not hard to see why he would. With all the insanity in Lordaeron, many people joined up with Jaina Proudmoore when she went across the sea.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1302] = {title = "James Hyal", objective = "Speak with Clerk Lendry at Foothold Citadel in Theramore.", description = "My brother James went with Lady Proudmoore across the sea. Last I heard, the fighting had settled down over there, and James was setting up an inn somewhere on the continent. Wherever he is, I'm sure he's doing good business. Damn fine cook he was.\n\nI haven't heard from him for a while now--too busy with his inn, I'd wager--but the clerk in Theramore could probably point you to him. Look for him on the top floor of that keep near the middle of the city. What's it called... Foothold Citadel, that's it.", progress = nil, completion = "James Hyal, James Hyal... Why does that name sound so familiar?\n\nOf course! The Shady Rest Inn incident. If you have any information about what happened there, I would urge you to speak with Captain Vimes about it. He's handling the investigation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1318] = {title = "Unfinished Gordok Business", objective = "Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul.\n\nAccording to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings.", description = "Now you da king, so maybe you get prized Gordok artifact back from creepy elf who calls himself Prince!  Da king before you failed, just like all da other kings since Tortheldrin - da creepy elf - stole it from old timey Gordok king!\n\nArtifact is called da Gauntlet of Gordok Might.  Old timey stories say only da one true king da Gordok can get it back.  Old timey story also say creepy elf is still around here - you find it and it will become mighty gauntlet you wear forever!  Yar, I show you!You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nGordok's HandguardsGordok's GauntletsGordok's GlovesGordok's Handwraps\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1319] = {title = "The Black Shield", objective = "Show the Blackened Iron Shield to Caz Twosprocket in Theramore.", description = "I'm sorry I can't be of much help, <name>, but I can refer you to someone who would be. Caz Twosprocket, one of our best blacksmiths, works the forge at the smithy.\n\nTake the shield to him, and see what he can tell you.", progress = "Something for me to look at?", completion = "Hm... interesting piece of iron you have here. Definitely not made by any of the blacksmiths I know over on this side of the sea, and it's certainly not my work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1320] = {title = "The Black Shield", objective = "Speak with Captain Garran Vimes in Theramore.", description = "Ah, I almost missed this... The leather strap on the back must have burned off, but it seems like it was made to fit a large person. I'd guess a tauren, actually.\n\nThat's about all I can tell you. Tell Captain Vimes I'm sorry I couldn't be of more help.", progress = nil, completion = "That's not much information to work on, but we'll have to keep it in mind. Hopefully some of the other pieces of this mystery will fall into place, and paint a more helpful picture of what happened.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1321] = {title = "The Black Shield", objective = "Show the Blackened Iron Shield to Do'gol in Brackenwall Village.", description = "Hmm... I don't see anything out of the ordinary with this shield. We should have Do'gol, the blacksmith, take a look at it, and see if he can tell us more about it, but I wouldn't hold out hope...", progress = "Something for me, <class>?", completion = "This is good shield. Very strong, heavy, good. But Do'gol don't need it. I make shields, not buy them, &lt;name&gt;.\n\nYou should know that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1322] = {title = "The Black Shield", objective = "Acquire 5 Acidic Venom Sacs for Do'gol in Brackenwall Village.", description = "Hmmm, there's writing right here on the rim of the shield, but it's hard to read from all the burned stuff.\n\nI need acid to make it clear. Venom from the darkmist spiders would do good. The spiders have taken over an old mine, the Darkmist Cavern, northwest of the village. Get me some of their sacs and I can clean this up.", progress = "Did you get them sacs from the spiders?", completion = "I don't like spiders that are so big I can't sit on them and squish them.\n\nThanks for getting them, &lt;name&gt;. Now I rip them open and pour them onto the shield...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1323] = {title = "The Black Shield", objective = "Talk with Krog in Brackenwall Village.", description = "Oh, I think I might have dropped too much acid onto the shield. Let me just rub a little...\n\nHm, kind of hard to read, but it looks like the name Mosarn. Never heard of him. Maybe Krog knows. Krog knows many people.", progress = nil, completion = "Mosarn? Sounds familiar... I can't put my finger on it. Maybe it'll come to me later.\n\nIt probably isn't important. A shield can come from anywhere and not mean anything...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1324] = {title = "The Missing Diplomat", objective = "Defeat Private Hendel in Dustwallow Marsh.", description = "What?! You come here accusing me of allying with the Defias, and think I'll just stand here while you insult me?! Something tells me you've had this coming for a long time.", progress = "Hello again, <name>. I hope you don't mind the assistance, but we couldn't have Hendel escaping, or worse, wind up dead.", completion = "I assure you, we're all quite upset about current events, but allow us to take him back to Theramore for some questioning, and we'll see about finding the King.\n\nI'm sure my lady Proudmore would like to thank you for your help. Speak to her when you have a moment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1338] = {title = "Stormpike's Order", objective = "Bring Stormpike's Request to Furen Longbeard in Stormwind.", description = "There is a dwarven armorsmith whose work I admire greatly.  His name is Furen Longbeard, and his skill is unmatched.  I need a new shield, and I must have one of his!\n\nThe problem is... Furen is far to the south, in the dwarven district within Stormwind.  In human lands!  I can't imagine why he would live there, so far from Ironforge.  The humans must pay him a king's ransom to keep him there!\n\nSo, if you want to travel and don't mind making some money, then will you send Furen my request for a shield?", progress = "A letter from the dwarven lands?  I wonder who would call from so far to the north...\n\nPlease, let me see the order.", completion = "Ah, a request from one of the Stormpikes.  That's a proud clan, full of quality dwarves.  Rich ones, too.\n\nThank you, &lt;name&gt;.  I'll get to work on Mountaineer Stormpike's shield by the end of the day.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1339] = {title = "Mountaineer Stormpike's Task", objective = "Speak with Mountaineer Stormpike.", description = "I hear Mountaineer Stormpike is looking for a runner.  Someone to do a little traveling for him.  How about it?  Are you the <race> for the job?\n\nIf so, then you'll find Stormpike at the top of the northern guard tower.", progress = nil, completion = "That's right.  I have a task that I can't do while I'm guarding.  In fact, it'll take you far from Loch Modan.\n\nYour perfect chance for adventure!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1358] = {title = "Sample for Helbrim", objective = "Bring the Wolf Heart Sample to Apothecary Helbrim in the Barrens.", description = "A colleague in Kalimdor, Apothecary Helbrim, is researching the effects of Lordaeron toxins on the beasts of Kalimdor.  He would be very interested in a sample of the wolf hearts Renferrel sent me.\n\nHelbrim is stationed in the Barrens, in a village known as the Crossroads.  To reach him, you must travel via zeppelin to the orc capital of Orgrimmar, then travel south, by foot, to Durotar.  Head west into the Barrens, and you will soon reach the Crossroads.", progress = "You have a package for me?", completion = "Ah, very good.  If initial reports are true, then the toxicity of these hearts could lead to further advances in our knowledge of poisons.\n\nThis is a welcome delivery, &lt;name&gt;.  Your reward is well earned.", rewards = "You will be able to choose one of these rewards:\n\nBrewer's GlovesLong Draping Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1359] = {title = "Zinge's Delivery", objective = "Bring the Wolf Heart Samples to Apothecary Zinge in the Undercity.", description = "The wolf hearts you acquired possess a quality unseen in similar specimens.  There is a toxicity to them that should be deadly to the very wolves in which the hearts beat!\n\nIt's quite incredible, and we must study it further.  I kept a few samples of the hearts acquired.  Take them to my colleague, Apothecary Zinge.  You will find her in our headquarters in the Undercity.", progress = "You have something for me?", completion = "Ah yes, the heart samples of which Renferrel spoke.  I am eager to experiment with these... it is always of interest to the Royal Apothecary Society when new forms of toxins are discovered.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1360] = {title = "Reclaimed Treasures", objective = "Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge.", description = "I had myself a fine job as a digger at the Uldaman excavation site in the Badlands... that is until those blasted troggs showed up.  I escaped with my hide barely intact, and nothing else.  In the chaos, I left my most treasured possession.  It's safe from the troggs in my chest, sure, but it's right in the thick of 'em.\n\nI'd be in your debt, both in honor and coin, if you could fetch it for me!  A chest with my name on it is at the end of the North Common Hall.  That's the one you need to get in.", progress = "Well now, we're you able to get slap around those troggs long enough to get into my chest and nab my treasure?", completion = "Ah, I feel complete again - thank you kindly.\n\nSome dwarves may treasure the luster of metal, and some may treasure the glint of gems... but a Stoutarm without a treasured stein in hand is hardly a Stoutarm at all!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1361] = {title = "Regthar Deathgate", objective = "Speak with Regthar Deathgate.", description = "A warrior of the Horde, Regthar Deathgate, is recruiting agents for a mission into the land of Desolace.  Speak with him if you wish to volunteer.  He is stationed in the Barrens, in a series of bunkers west of the Crossroads.\n\nAnd sharpen your weapons.  Desolace is a place torn by war.", progress = nil, completion = "Yes, I am recruiting.  This mission leads into Desolace, against the centaur there.  I will be brief so that you may quickly begin.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1362] = {title = "The Kolkar of Desolace", objective = "Speak with Felgur Twocuts at Ghost Walker Post in Desolace.", description = "The Kolkar centaur live in Desolace, and their forces have spread into the Barrens.  This is a known fact and we have Horde agents dealing with them here.\n\nBut as long as the centaur are strong in Desolace, they will always pose a threat.  It is time we rid ourselves of that threat.\n\nSpeak with Felgur Twocuts at Ghost Walker Post in Desolace.  He was sent to gather intelligence on the centaur.  He will know how to best deal with the Kolkar of Desolace.", progress = nil, completion = "You are here on orders from Regthar?  Then you are here to deal with the centaur.  Good.\n\nI hope you're rested.  I don't know how our campaign against the centaur will end, but I know the struggle will be long.\n\nHave a seat, and listen.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1363] = {title = "Mazen's Behest", objective = "Speak with Acolyte Dellis in Stormwind.", description = "As caretaker of the works here in the library of the Academy of Arcane Arts and Sciences, it is my responsibility to ensure all the magical tomes and scrolls are accounted for at all times. Who knows what folly would unfold if some of these enchanted texts were to fall into the wrong hands?\n\nWhich reminds me... my assistant, Dellis, made a horrible mistake last week. He's quite able in the library but incompetent when he leaves the gates of Stormwind. Be a hero, and help old Dellis out, would you?", progress = nil, completion = "It wasn't my fault. Really it wasn't.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1364] = {title = "Mazen's Behest", objective = "Retrieve Khadgar's Essays on Dimensional Convergence and deliver them to Watcher Mahar Ba in Nethergarde Keep.", description = "Master Mazen's directions were quite clear: Deliver a very important essay to Watcher Mahar Ba in Nethergarde Keep.\n\nBut I had never been to the Blasted Lands before! The journey was frightening!\n\nWhen I got to the Swamp of Sorrows, I made a wrong turn and ended up surrounded by horrible plant-like swamp creatures. They lurched as if to attack me so I ran. But in my haste I dropped the essay. One of the beasts took it I am sure.\n\nCould you please try to retrieve it and deliver it to Mahar Ba?", progress = "What brings you to Nethergarde Keep, <race>?", completion = "Ah, most splendid!\n\nFor some time I had feared my request for Khadgar's Essays on Dimensional Convergence had been overlooked by Master Mazen of the Academy of Arcane Arts and Sciences.\n\nHe must be bogged down with requests considering the many strange happenings going on.\n\nNow, if you'll excuse me, I need to begin my research at once. To finally glimpse the insight of one as great as Khadgar excites me to no end.", rewards = "You will be able to choose one of these rewards:\n\nTeacher's SashWanderlust Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1365] = {title = "Khan Dez'hepah", objective = "Bring Khan Dez'hepah's Head to Felgur Twocuts in Desolace.", description = "The Kolkar are not the only centaur of Desolace.  Many clans wander these dry plains, fighting and dying against each other.  And it is good that they fight among themselves, for they are strong and brutal.  If the centaur united against us, they would be a fierce foe.\n\nWe must deal with them before they unite.\n\nYour first task is to disrupt the Kolkar clan.  Do this by killing its leader, Khan Dez'hepah.\n\nThe Kolkar Village is northeast of here.  Go, and may fortune go with you.", progress = "<name>, have you defeated Khan Dez'hepah?", completion = "Well done.  This swift act against the Kolkar is an effective show of strength, and strength is what the centaur understand best.\n\nThe death of the Kolkar leader will not only disrupt that clan, but give pause to the others.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1366] = {title = "Centaur Bounty", objective = "Bring 15 Centaur Ears to Felgur Twocuts in Desolace.", description = "Now that you scared the centaur clans, it's time to bleed them.  When traveling Desolace, hunt centaur.  I don't care which clan you hunt.  Just gather ears.  A hoard of ears.\n\nBy weakening their numbers you will weaken their resolve, and stamp out any thoughts of expansion.\n\nGood hunting, <name>.", progress = "How is your collection of ears, <name>?  Large?", completion = "By now, the centaur must know your name.  I'm sure they know it, and respect it, and fear it.  And just as they know you, they know the banner under which you ride.\n\nThe banner of the Horde.", rewards = "You will be able to choose one of these rewards:\n\nLilac SashBraced Handguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1367] = {title = "Magram Alliance", objective = "Gain a Friendly reputation with the Magram, then speak with Warug.", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Magram then slay their foes, the Gelkis.  This will earn you respect among the Magram.  When you earn enough, then meet with the Magram spokesman Warug, on the outskirts of the Magram Village, in southeast Desolace.", progress = "Leave!  The Magram do not speak with the weak.  We kill them!\n\nIf you want to speak with me, then show me you are strong.  Return after you slay many Gelkis.", completion = "The Gelkis cry when they hear your name, &lt;name&gt;.  They fear you and they hate you.  They hate you like they hate the Magram!\n\nMaybe you are strong like the Magram.  We will see...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1368] = {title = "Gelkis Alliance", objective = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", description = "To beat the centaur, we must use their hatred against them.  We will ally with one of the clans and through them, we will learn how to defeat all the clans.\n\nIf you choose to ally with the Gelkis then slay their most hated rival, the Magram.  After you earn the respect of the Gelkis, meet with the Gelkis shaman Uthek the Wise, on the outskirts of the Gelkis Village, in southwest Desolace.", progress = "Your two feet step on Gelkis earth.  You are not welcome here!\n\nProve you seek friendship with the Gelkis.  Kill Magram centaur.  Return when the ground is wet with Magram blood.", completion = "The earth speaks to me.  And it says you have killed many Magram.  This is good.\n\nIf you are a friend of the Gelkis, then listen.  I have more tasks for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1369] = {title = "Broken Tears", objective = "Maintain your reputation with the Magram, and bring 3 Broken Tears to Warug in the Magram Village.", description = "The Gelkis think our centaur mother, Theradras, protects us.  They are stupid.  No one protects the centaur.  The Magram do not need protection!  We are the strongest!\n\nShow the Gelkis they are stupid.  Go to the cave in their village.  They hoard crystals in that cave, the tears of Theradras.  Destroy the tears and bring me the broken pieces!", progress = "If you are not our enemy, then you will do what I ask!", completion = "You got the tears!  Now the Gelkis will know that Theradras will not help them.  She will not cry when we crush them!  The Magram will rule!\n\nYou are smart to help us, &lt;name&gt;.  We are the strongest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1370] = {title = "Stealing Supplies", objective = "Bring 6 bags of Crudely Dried Meat to Uthek the Wise in the Gelkis Village.", description = "When we are not at war, we hunt for meat.  Meat gives us strength, and full bellies fight harder than empty ones.\n\nIt is the same with the Magram.  They store extra meat so they may fight longer between hunts.  If you raid their village to the east and take their stores of meat, then their strength will fail.", progress = "Return after you further prove your worth to the Gelkis!", completion = "Good.  I can hear the loud Magram bellies grumble from their village, far away!\n\nI will give this meat to the Gelkis.  And we will fight for many days without rest.\n\nWhat you did is good for the Gelkis, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nSilver StarFeathered ArrowExploding Shot\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1371] = {title = "Gizmo for Warug", objective = "Maintain your reputation with the Magram, and bring an Advanced Target Dummy to Warug in the Magram Village in Desolace.", description = "Long ago, a little gnome came to Desolace.  He had horses and a cart, and the cart held strange things.  Funny things.  Things that burned different colors.  Things that moved and weren't alive.  I killed the little gnome, but before that... he made me laugh.\n\nI kept my favorite thing from his cart.  It was a human made of wood and it waved at me until I hit it and broke it.\n\nI want a new one.  Get me a new one!", progress = "If you are not our enemy, then you will do what I ask!", completion = "Yes, this is what I had!  I will make it move again.  It makes me laugh!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1372] = {title = "Nothing But The Truth", objective = "Speak with Apothecary Faustin at Beggar's Haunt.", description = "Our expeditionary force was sent at Varimathras's behest to survey lower Azeroth.\n\nWhile out scouting I noticed a human Infiltrator spying on Beggar's Haunt. Before I could apprehend him, some of our orcish... brethren... captured him and took him to Stonard, their stronghold in Swamp of Sorrows.\n\nI want to... help... our orcish allies. They did not see our camp here but nonetheless I want to lend a hand.\n\nWork with Faustin here to develop a... truth serum for our friend in Stonard.", progress = nil, completion = "Zraedus was just telling me about the nosey little Infiltrator before you arrived.\n\nQuite a problem, indeed. The last thing we need is a busybody sniffing around Beggar's Haunt.\n\nI am sure the orcs of Stonard would be quite anxious to hear what our friend has to say. Seeing that they are our allies, ahem, we must help them to get any information they can from the human.\n\nWork with me, &lt;name&gt;, and we will deliver a truth serum to Stonard.\n\nFor the Horde!\n\n...did I get that right?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1373] = {title = "Ongeku", objective = "Maintain your reputation with the Gelkis, and bring a Draenethyst Shard to Uthek the Wise in the Gelkis Village in Desolace.", description = "You have more to prove, and your next task will take you far, so for now the Gelkis will fight the Magram without you.\n\nThe earth whispers many secrets to those who listen.  One secret I hear is of a red crystal.  It is called draenethyst, and it is new to our earth.  It comes from a place where mountains fly, and where demons rule.\n\nBring me a shard of draenethyst, and it will make my magic strong!  The shard is in a place called the Swamp of Sorrows, held by the lost one Ongeku.", progress = "Show me you are a friend of the Gelkis, <name>.", completion = "Yes, this is the shard of which the earth whispered.  I can feel strong magic in it!  I will use this magic against the enemies of the Gelkis.\n\nYou have done one more task for us, &lt;name&gt;.  Maybe soon, we will call you friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1374] = {title = "Khan Jehn", objective = "Bring the Khan Jehn's Head to Uthek the Wise in the Gelkis Village in Desolace.", description = "The earth speaks to me, and it says that the Magram grow weak.  Now it is time to kill their Khan!\n\nBring me the head of the Magram Khan, Jehn!", progress = "Show me you are a friend of the Gelkis, <name>.", completion = "Khan Jehn was strong, but stupid.  He thought his own strength was great.  He did not see that earth magic is stronger.  The Magram centaur will now fall without their leader, and the Gelkis will one day rule!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1375] = {title = "Khan Shaka", objective = "Maintain your reputation with the Magram, and bring the Head of Khan Shaka to Warug in the Magram Village in Desolace.", description = "You help the Magram, and I like you.  Now, kill the Khan of the Gelkis!  He is Khan Shaka, and I want his head!  I want to stare at his head and laugh at him!", progress = "Do tasks for the Magram, and I will help you.", completion = "Khan Shaka is dead!  I will place his head on a pike, and keep it with me so Shaka can see the strength of the Magram!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1380] = {title = "Khan Hratha", objective = "Maintain your reputation with the Gelkis, and bring the Maraudine Key Fragment to Uthek the Wise in the Gelkis Village.", description = "<name>, you helped us against the Magram.  Now, help us beat the Maraudine!  Kill the head of their clan, Khan Hratha!\n\nTo face him, blow the Maraudine War Horn.  It is atop a high bluff in the Valley of Spears.\n\nBut to blow the horn, you must gain a warhorn mouthpiece.  These are rare, carried only by trusted Maraudine centaur.\n\nAfter the horn is blown, centaur will come.  Kill them until Hratha appears.\n\nKhan Hratha holds the piece of... a key.  Bring it to me...", progress = "Is Khan Hratha dead?  Do you have the key fragment?", completion = "He is dead!  Khan Hratha is dead!  And now the Maraudine will fall!  When the Gelkis rule this land, &lt;name&gt;, we will remember you.  And the spirits of the earth will sing your name for all time.", rewards = "You will be able to choose one of these rewards:\n\nGelkis Marauder ChainUthek's Finger\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1381] = {title = "Khan Hratha", objective = "Maintain your Magram reputation, and bring the Maraudine Key Fragment to Warug in the Magram Village in Desolace.", description = "The Gelkis Khan is dead, and now the Maraudine will fall!  Kill the Maraudine Khan, Hratha!\n\nTo face him, blow the horn on the high bluff in the Valley of Spears.  But to blow the horn, you need a mouthpiece.  To get a mouthpiece, kill Maraudine centaur.  Keep killing until you find a mouthpiece.  Then blow the horn.\n\nDo this and Maraudine centaur will come to the tower.  Kill them until Khan Hratha appears.  Hratha holds the piece of a key.  Give this piece to me...", progress = "Do what I ask.  Prove to me that you are an ally of the Magram!", completion = "Khan Hratha is dead!  Now the Magram are the strongest of the centaur!  We will crush the others, and rule Desolace!\n\nWe will remember, you, &lt;name&gt;, and you will be spared our hooves when all others are trampled.", rewards = "You will be able to choose one of these rewards:\n\nMagram Hunter's BeltCeremonial Centaur Blanket\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1382] = {title = "Strange Alliance", objective = "Gain a Friendly reputation with the Gelkis, then speak with Uthek the Wise.", description = "We are fortunate the centaur clans fight among themselves, for if they joined into a single force then they would be unstoppable.  Yes, we are fortunate, and we should press our advantage.\n\nOne of the centaur clans, the Gelkis clan, is in brutal war with the Magram clan.  If we attack the Magram, then perhaps an alliance may be struck with the Gelkis.\n\nSpeak with Uthek the Wise, in the outskirts of the Gelkis camps in southwestern Desolace.  Through her we might strike an alliance with the Gelkis.", progress = "Be gone!  The Gelkis do not want you here.  Leave now!!\n\nReturn after killing many Magram, and then I will speak with you.", completion = "Your name is whispered among the Gelkis.  You have much Magram blood on your hands.  This is good.\n\nMaybe it is also good if we speak.  Speak of what you can do for the Gelkis, and what we can do for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1383] = {title = "Nothing But The Truth", objective = "Apothecary Faustin at Beggar's Haunt needs 5 Shadow Panther Hearts, Mire Lord Fungus and some Green Whelp Blood.", description = "I have just the right serum in mind. It will deal with the truth in precisely the way the truth should be dealt with.\n\nFor this concoction I will need several Shadow Panther hearts from the Swamp. I also require the enchanted fungus off of the Mire Lord who resides there. I am sure one as able as you, <name>, can persuade him to part with some.\n\nThe last item I'll need for the serum is the blood of a dreaming whelp, like the ones that live outside Itharius' cave in the swamp.\n\nNow, off you go!", progress = "That Infiltrator in Stonard will surely.... open up... after he drinks my special serum. Haha!\n\nThe ingredients required are by no means easy to procure. Shadow Panthers are common in the Swamp but collecting enough hearts for our purpose can be daunting. And the Mire Lord can be such a fussy beast.\n\nAs for the Deepstrider tumor, they are terribly difficult to find. But the chemical reaction I can draw from it is second to none.", completion = "Splendid, &lt;name&gt;! And just in time too. From what Zraedus tells me, the Infiltrator has recovered from his wounds and is ready to be questioned by the orcs.\n\nGive me but a moment to prepare the pois-- I mean prepare the truth serum.", rewards = "You will be able to choose one of these rewards:\n\nCloak of BlightCragwood Maul\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1384] = {title = "Raid on the Kolkar", objective = "Maintain your reputation with the Gelkis, and bring 10 Crude Charms to Uthek the Wise in the Gelkis Village in Desolace.", description = "The Kolkar centaurs think their magic is strong.  They do not know magic!  They would not know magic if it bit them!\n\nYou will show them their magic is weak.  Go to the Kolkar  to the northeast and kill them.  Take their charms.  Bring me the charms and I will throw them in the fire and laugh!", progress = "You have the charms?  You showed the Kolkar they are weak?", completion = "You do a good thing for the Gelkis.  The Kolkar are weak and will die.  Their magic is pathetic and will not save them.  You showed them this, and their fear will make them even more feeble!\n\nAnd in our lands, the feeble soon die.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1385] = {title = "Brutal Politics", objective = "Gain a Friendly reputation with the Magram, then speak with Warug.", description = "Desolace is a land at war.  The centaurs wage war with each other, and we believe the victor among them will spill out and threaten our strongholds.  That, we cannot allow\n\nWe must learn how to beat the centaurs, and to do that... we must ally with one of the clans.  The Magram centaurs war with the Gelkis.  If you fight the Gelkis then the Magram might consider an alliance.\n\nEarn the favor of the Magrams then speak with Warug, in the Magram village in southeastern Desolace.", progress = "You will go now, or the Magram will crush you!  To be our friend, you must kill Gelkis.", completion = "Many Gelkis fall to you.  I like that.  Maybe you can do more things I like.  Maybe you and the Magram can be friends.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1386] = {title = "Assault on the Kolkar", objective = "Maintain your reputation with the Magram. Kill 12 Kolkar Centaurs, 12 Kolkar Scouts and 6 Kolkar Maulers, then return to Warug in the Magram Village in Desolace.", description = "The Kolkar think they are strong, but we laugh at them!  We laugh and we kill them!  You kill them too.  Show me you can kill Kolkar like we do. Head north and slay them all!", progress = "Are you afraid of the Kolkar?  Why do you not kill them?  Maybe you forgot how to kill.  Hurry and kill Kolkar before they are dead!", completion = "The Kolkar fear you now!  I hope you laughed when you killed them.  It is better to laugh when you kill, so the enemy can see he is weak.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1387] = {title = "Centaur Bounty", objective = "Bring 15 Centaur Ears to Corporal Melkins at Nijel's Point in Desolace.", description = "Many clans make up the centaur race.  Each has its own leader and agenda, but all the clans have one thing in common.  Cruelty.\n\nIf we are to ever find peace, then the centaurs must be removed.  And so I put you on the task to do just that.\n\nWhile wandering Desolace, hunt centaur and take their ears.  Bring me many, many ears.\n\nDo this in service of the Alliance, <name>, and we will be one step closer to war's end.", progress = "Do you have a report, <name>?", completion = "Ah, the ears.  Well done.\n\nYour service to the Alliance is unquestioned, &lt;name&gt;.  The blood you spilled in Desolace will, no doubt, save countless lives.", rewards = "You will receive:\n\nRing of Calm"}
MultiLanguageQuestData['en'][1388] = {title = "Nothing But The Truth", objective = "Give Faustin's Truth Serum to Deathstalker Zraedus at Beggar's Haunt.", description = "Everything is proceeding according to plan, <name>. I want you to give this truth serum to Deathstalker Zraedus and he'll show you how to administer it.... properly.\n\nHaha!", progress = "I hope you have proven yourself of use to our dear friend, Apothecary Faustin.", completion = "I knew old Faustin would come up with something good! You were a tremendous help, no doubt.\n\nNow let's get down to business, shall we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1389] = {title = "Draenethyst Crystals", objective = "Bring 6 Draenethyst crystals to Magtoor at The Harborage in the Swamp of Sorrows.", description = "The lost ones who live in the Fallow Sanctuary look as we look, but they are monsters... driven mad by the rigors of our journey to Azeroth.  Once our brethren, they now live in the Fallow Sanctuary to the east, catching or killing any who wander near.\n\nAnd they have stolen something sacred to us--draenethyst crystals.\n\nWe lack the force to enter the Fallow Sanctuary and reclaim our stolen draenethyst from among their huts and campfires, but without those crystals... we too may lose our way.", progress = "Do you have the crystals?", completion = "Thank you, &lt;name&gt;.  We, are in your debt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1391] = {title = "Nothing But The Truth", objective = "Take Zraedus's Brew to Infiltrator Marksen in Stonard.", description = "We need to operate with a certain amount of discretion. After all, it's not like you're going to waltz in there and convince the fool to drink Faustin's concoction here, right?\n\nBut if there's one thing those humans cannot deny it's the booze. I'll take Faustin's serum and mix it into this ale. I guarantee the poor sap will show no reluctance when it comes to chug-a-lugging a brew.\n\nMake haste to Stonard in the Swamp of Sorrows, <name>. And keep our little mission nice and quiet...", progress = "Please have mercy on me! I have information that goes beyond alliance boundaries. While I am no sympathizer of the Horde, there is political treachery going on that must be revealed!", completion = "A drink for me? How kind. It's been days since they've allowed me to drink. Let me drink this down and then I'll tell you what I've learned....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1392] = {title = "Noboru the Cudgel", objective = "Bring Noboru's Cudgel to the leader of The Harborage in the Swamp of Sorrows.", description = "Noboru has plagued the Draenei of the Harborage for months, and his cudgel is a symbol of the brutality they have suffered at the hands of the lost ones.", progress = "Greetings.  And welcome to the Harborage.", completion = "You have gained the weapon of the dreaded Noboru?  Is he then dead?\n\nThis is a joyous day for the Harborage.  Noboru and his gang were a terror to us, wandering the swamps and killing any Draenei who crossed his path.  He was a direct threat to our survival, and we did not have the strength to face him.\n\nWe are fortunate to have a friend in you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1393] = {title = "Galen's Escape", objective = "Escort Galen out of danger, then find his camp in the Swamp of Sorrows and open his strongbox.", description = "Please help!  These creatures are going to eat me!\n\nHelp me out of here, and I'll give you a great treasure!  It's in my camp in the swamp north of Stonard, but it's locked in a strongbox that can be opened through a trick that only I know.\n\nIf you help me escape, then I'll teach it to you.", progress = "The keyhole of this strongbox is filled with black resin.  It is impossible to open.", completion = "The keyhole of this strongbox is filled with black resin.  It is impossible to open.\n\nBut Galen told you of a hidden latch on the box's bottom... \n\n...After a quick search the latch is found.  The latch is flipped, and the strongbox opens...", rewards = "You will receive:\n\nVisionary Buckler"}
MultiLanguageQuestData['en'][1394] = {title = "Final Passage", objective = "Speak to Dorn Plainstalker in Thousand Needles.", description = "You have done well, <name>. You have passed my test, and the tests before mine. Return to Dorn in Thousand Needles. He will sense the change within you, and see that your mind, body and spirit are strong enough that you should be rewarded for your efforts.\n\nStay true to the balance you've shown throughout these trials, <name>. Dorn will test you again in the future if you do.", progress = nil, completion = "Ah, &lt;name&gt;. It has been a long time since you have last stepped into my home. It seems like many moons have passed since you took your first leap that set you upon your path.\n\nAnd now you return to me stronger than you once were... more enlightened. This pleases me. And you should be justly rewarded for seeing my tests to the end.", rewards = "You will be able to choose one of these rewards:\n\nWindstorm HammerDancing Flame\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1395] = {title = "Supplies for Nethergarde", objective = "Bring the Crate of Powerstones to Quartermaster Lungertz, before the powerstones expire.", description = "This crate of powerstones needs to go to Nethergarde Keep, in the Blasted Lands.  They won't hold their power for long, so we can't ship them with the next caravan.\n\nYou must take them, and you must take them quickly.\n\nBring them to Quartermaster Lungertz in Nethergarde Keep.  To reach the keep, you must travel east through Deadwind Pass, then east through the Swamp of Sorrows, then south through the Blasted Lands.\n\nUse caution, <name>.  You will travel through dangerous lands, yet you must not fail.", progress = "Hello!  Don't mind all the commotion, it's just business as usual at Nethergarde Keep.\n\nYou have something for me?", completion = "Ah, the powerstones!  The mages will be happy to see these!\n\nMany thanks, &lt;name&gt;.  I know your trip from Darkshire was not an easy one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1396] = {title = "Encroaching Wildlife", objective = "Kill 8 Young Sawtooth Crocolisks, 10 Sorrow Spinners and 10 Swamp Jaguars then return to Watcher Biggs in the Swamp of Sorrows.", description = "My caravan was destined for the eastern coast, but we did not reach our goal.  Lost Ones attacked us, killing guards and dashing supplies.\n\nI alone survived their assault.  I have sworn to protect what supplies remain, but wild creatures skulk near.  Please, help me defend my camp from the beasts!", progress = "The swamp creatures press close, <name>.  Please, you must defend the camp!", completion = "The sounds of animals are now faint, more distant.  Thank you, &lt;name&gt;.  Now let's hope they don't return!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1398] = {title = "Driftwood", objective = "Bring 8 pieces of Sundried Driftwood to Watcher Biggs in the Swamp of Sorrows.", description = "I owe you greatly, <name>.  An honorable heart beats within you.  And now I have another task for which I humbly ask your aid.\n\nIf I'm ever to reach Nethergarde, then I must fix this wagon.  And for that... I will need wood.  Strong, dry wood--not the spongy, tangled wood of the swamp's trees.\n\n<name>, go east to the coast and search for driftwood that has been dried by the sun.  Bring it to me.", progress = "Did you find any driftwood, <name>?", completion = "This wood is light, but tough.  Thank you, &lt;name&gt;.  It will work nicely.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1418] = {title = "Neeka Bloodscar", objective = "Speak with Neeka Bloodscar.", description = "The Badlands is harsh and lies close to the Alliance-held land of Loch Modan, so communication between Stonard and the Badlands outpost of Kargath is often cut.\n\nProve yourself, <name>.  Travel to the Badlands and speak with Neeka Bloodscar, head scout of the Kargath outpost.  Speak with her, and then send her report back to me.", progress = nil, completion = "Helgrum wants a report, eh?  I sent an outrunner to Stonard not three days past.  Did he fail his mission?  If Stonard does not have my report, then it appears he did fail.\n\nLet's hope the next runner I send has more skill, or more luck.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1419] = {title = "Coyote Thieves", objective = "Bring 30 Coyote Jawbones to Neeka Bloodscar in Kargath.", description = "Have you spent many days in the Badlands, <class>?  Have you felt its heat? Have you faced the beasts that wander its dusty plains?  It's time you did.\n\nCrag coyotes are a tough breed.  Tough, and bold enough to creep into Kargath and steal from our food supplies.  Help rid the outpost of these thieves!\n\nHunt crag coyotes, <name>.  Hunt them and bring me their jawbones.  Bring me enough, and maybe I'll believe it when you say you know the Badlands.", progress = "Do you have the jawbones?", completion = "That's a nice collection of jawbones, &lt;name&gt;.  Now those coyotes won't be tearing through our supplies for scraps.\n\nWell done.  The coyotes of the Badlands aren't easy prey.  Your deed shows me that you might just survive here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1420] = {title = "Report to Helgrum", objective = "Bring Neeka's Report to Helgrum the Swift in Stonard.", description = "I wrote a fresh report for Helgrum in Stonard.  Bring it to him.\n\nAnd if you consider yourself an outrunner, then don't lose your way.  Or fall to an enemy.", progress = "You returned.  You have a report?", completion = "Thank you, &lt;name&gt;.  From Neeka's report, I see the Alliance is not without its own problems.  And we may find that some enemies are shared between us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1421] = {title = "The Lost Caravan", objective = "Find the Caravan Chest in the Fallow Sanctuary, obtain the Wizards' Reagents and bring to Watcher Biggs.", description = "I was stunned during the attack by the Lost Ones, but before my sight went black I spied one of our wagons being dragged to the Fallow Sanctuary, the lost one village to the north.\n\nA caravan chest with valuable reagents was in that wagon, reagents vital to the studies of the wizards of Nethergarde Keep.  Find the chest and get those reagents, <name>.  Get them and bring them to me.", progress = "Do you have the wizard's reagents, <name>?", completion = "Ah, you found them!  With these, the wizards in Nethergarde may continue their work.  I do not know what it is that they do, but it is linked to the Dark Portal in the Blasted Lands, and is vital to the security of the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1422] = {title = "Threat From the Sea", objective = "Speak to Katar in the Swamp of Sorrows.", description = "While I begin work on your weapon, why don't you talk to Katar? He mentioned needing help with patrols along the beach, and I'd rather see you keep your wits and weapons prepared instead of getting drunk with some of the other louses I share this camp with.", progress = nil, completion = "Be silent a moment, &lt;class&gt;. Even over the dull roar of the sea you can still hear those disgusting gurgles from the fish men.", rewards = nil}
MultiLanguageQuestData['en'][1423] = {title = "The Lost Supplies", objective = "Bring the Lost Supplies to Quartermaster Lungertz.", description = "This barrel is small yet sturdy.  Its seams are sealed with a yellow, pungent wax.  Stamped on the bottom of the barrel are the words:\n\nQUARTERMASTER LUNGERTZ\n\nNETHERGARDE KEEP", progress = "You have something for me?", completion = "Ah, thank you &lt;name&gt;!  So many supplies are lost from Darkshire to here.  It's good to see that some are recovered.", rewards = "You will receive:\n\nBox of Supplies"}
MultiLanguageQuestData['en'][1424] = {title = "Pool of Tears", objective = "Fel'zerul in Stonard wants you to gather 10 Atal'ai Artifacts.", description = "The Warchief sent us to investigate strange happenings at The Temple of Atal'Hakkar.\n\nThe Atal'ai trolls are a tribe of dark casters, known for practicing forbidden magic. You can imagine how astonished we were when we arrived here to discover the temple had been sunk.\n\nThe green dragons now guard the site, claiming to be protectors of Azeroth.\n\nWe need to discover what happened. Explore around the Pool of Tears and gather Atal'ai artifacts. From those I can begin to piece together this puzzle.", progress = "No one knows what dark practices went on inside The Temple of Atal'Hakkar. But we do know that great and powerful forces of magic were used.\n\nWe must learn as much as we can about such magic. Perhaps the spells of the Atal'ai will prove of use to the Horde.\n\nOnce you have gathered enough Atal'ai artifacts from around the Pool of Tears, I can begin to understand what the trolls were hoping to accomplish and what went so horribly wrong.", completion = "Your diligence in collecting the Atal'ai artifacts is worthy of praise, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1425] = {title = "Deliver the Shipment", objective = "Bring the Shipment to Nethergarde to Quartermaster Lungertz in Nethergarde Keep.", description = "While I fix this wagon, <name>, I have one last task for you.\n\nI have packed the most vital supplies saved from the ogre attacks.  Take them to Nethergarde Keep.  The keep is nestled in the northern hills of the Blasted Lands, keeping watch over the Dark Portal.\n\nTo reach Nethergard, follow the road east.  When it branches head south into the Blasted Lands, then turn left at the next fork.  Follow the road, <name>, and be wary.", progress = "You have business with me?", completion = "What?  A package from Biggs' caravan?  We thought it, and he, were lost.\n\nThank you, &lt;name&gt;.  With luck, these supplies will carry the much needed reagent, Azoran Crystals.  Our stock is running low...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1426] = {title = "Threat From the Sea", objective = "Kill 10 Marsh Murlocs, 10 Marsh Inkspewer, and 10 Marsh Flesheater, then return to Katar in the Swamp of Sorrows.", description = "I have no love for the sea, nor any creature I've seen come from its depths. It is a powerful but blind mistress; callous and brutal. It would bring me great pleasure to slay the fish men by the hundreds if it were within my power. But I garner some pleasure from watching their deaths at the hands of any who do the Horde's will.\n\nWhich brings us to you, <class>. How many can you slay? Would you test yourself against their most powerful kind?", progress = "I am patient. Patient and everlasting like an old kank stone from Draenor. The fish men shall not make it past our borders--not while I still stand. If we had an army at our disposal I would cleanse this world and all others of their presence. I feel my hatred seethe just speaking about them.", completion = "The sea seems vast and relentless, but you have stained her with the blood of her own spawn. The fish men know pain. Their stupidity will force them to refortify their ranks from the devastation you've caused, and that is good.\n\nLet their gurgling screams overshadow the sea's roar long into the night. I shall smile every time I hear one of them silenced.\n\nReturn to me if you wish to slay more of the fish men. I will gladly reward you again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1427] = {title = "Threat From the Sea", objective = "Speak with Tok'Kar in the Swamp of Sorrows.", description = "Before you take rest, speak to Tok'Kar again. While you were gone I believe he finished a few weapons. For your help here, he would offer one of them to you. You would do well to test its strength against the fish men when you are ready... but only to please me further.", progress = nil, completion = "Ah, &lt;name&gt;, you've returned. Good. I've finished crafting more weapons for our fight against the murlocs. For bringing us the fresh sawtooth meat, and for bringing a small smile to Katar's face, I offer one of them to you.", rewards = "You will be able to choose one of these rewards:\n\nTok'kar's Murloc ShankerTok'kar's Murloc BasherTok'kar's Murloc Chopper\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1428] = {title = "Continued Threat", objective = "Kill 10 Marsh Inkspewers, 10 Marsh Flesheaters, and 10 Marsh Oracles, then return to Katar in the Swamp of Sorrows.", description = "It pleases me to see your hatred for the fish men grows with mine.\n\nFind more of their kind along the beach, and when you've had your fill of combat, return to me. We shall speak then of a reward for your diligence.", progress = "Not until the sea and all her children are silenced will I be pleased... especially those disgusting fish men.", completion = "Well done, &lt;class&gt;. I call for more of their blood. Let all the fish men perish.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1429] = {title = "The Atal'ai Exile", objective = "Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands.", description = "While you were braving the dangers of the Pool of Tears, one of my scouts returned with a scroll written in blood on dried flesh. It seems to be a judicial sentence against a priest of the Atal'ai tribe.\n\nThis priest was sentenced to a fate worse than death amongst the Atal'ai.\n\nHe was exiled to live far north in the Hinterlands, with the Witherbark trolls.\n\nI will bundle these artifacts. You are to seek out the exile and discover their true use. Return to me once your journey is complete.", progress = "You are brave to come here. Brave or foolish...", completion = "You bring me the summoning artifacts of the Atal'ai?\n\nI see Jammal'an the Prophet is leading the disciples of the Chamber of Blood towards their chosen fate. Has Hakkar returned to the Temple I wonder? Has their fate been met?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1430] = {title = "Fresh Meat", objective = "Bring 10 Monstrous Crawler Legs to Dar in the Swamp of Sorrows.", description = "There's a high demand for the succulent taste of crawler meat among my customers; especially the meat from the monstrous crawlers.\n\nIf you plan on heading to the coast, then I could easily make it worth your while to bring me back some of their legs to have transported back to Orgrimmar.\n\nThe coast is to the east from here, and you should have no problem finding the creatures scurrying along the beaches and under the sea.", progress = "I have a cask of wine waiting for your success, <name>. It's only right I taste the goods before I have it shipped back to my customers.", completion = "Ah, this should be perfect. I can't wait to taste these after they are prepared perfectly over an open fire. You should take a sample of it with you on your travels. It truly is delicious.", rewards = "You will receive:\n\nGrilled King Crawler LegsLeather Chef's Belt"}
MultiLanguageQuestData['en'][1431] = {title = "Alliance Relations", objective = "Speak to Keldran in Orgrimmar.", description = "Be still, <class>, and allow me to share with you something important to our people, but far from obvious.\n\nWe are a proud race, and the war with the humans tried even Thrall's great patience. You see, our Warchief is wise and prudent, and he continues to put his people first. Ultimately, he is a diplomat, and in his time with the humans he learned much of their ways.\n\nIf the tale I've started piques your interest, then find Keldran near the western exit of the city. His hovel is there.", progress = nil, completion = "Putanni, noble &lt;class&gt;. I am Keldran, student of magic... and other mystical arts.\n\nThe business Craven sent you here to speak to me about requires a touch more subtlety than you've previously needed, but that does not mean you can not still aid our cause.\n\nPlease, make yourself comfortable, and I shall tell you why the Warchief has need of my aid... and yours.\n\nIt starts with appearances, &lt;name&gt;. How the Horde sees itself. How our allies see us. And most importantly, how our enemies see us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1432] = {title = "Alliance Relations", objective = "Speak to Takata Steelblade in Desolace.", description = "As the Alliance progresses deeper and deeper into Kalimdor, incorrect conclusions may be drawn about the Horde making pacts with the Burning Legion. The Warchief cannot allow that to happen. And with his blessing, I am taking control of overseeing them removed.\n\nI have agents in the area of Desolace at the Ghost Walker Post north of the great Kodo Graveyard. Head south of the Charred Vale in the Stonetalon Mountains and you shall come across it. When you arrive, seek out Takata Steelblade.", progress = nil, completion = "Greetings, &lt;class&gt;. You bring news from Orgrimmar; that is good.\n\nThe demon infestation overwhelms this area even more than the smell of centaur dung. The horse-men claim this land as their own, but clearly there are influences out of their control that will crush them if not kept in check.\n\nIt does not please me that we aid the centaur indirectly, but it is for the good of the Horde, so I do my duty for the Warchief, even if it means helping the warlocks within the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1433] = {title = "Alliance Relations", objective = "Speak to Maurin Bonesplitter in Desolace.", description = "The Burning Blade have many agendas, but know that they are evil to their core, their spirits corrupted, and their destruction is the only way to thwart their objectives.\n\nKeldran sent Maurin with me because of his knowledge of the Blade and their warlock ways.\n\nHe has control of our plots against the Blade while I deal with the other demonic threats here in Desolace.\n\nSpeak to him, and he will guide you in his designs.", progress = nil, completion = "Ah, yes. Aid from those loyal to the Warchief is always appreciated.\n\nMy name is Maurin. I am here at the behest of Keldran and the Warchief cub Thrall. It is my desire to aid the youngling leader against the evils that threaten his rule.\n\nCome, come closer, &lt;class&gt;. I shall explain to you my plan for removing the festering boil that is the Burning Blade.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1434] = {title = "Befouled by Satyr", objective = "Slay 7 Hatefury Rogues, 7 Hatefury Felsworn, 7 Hatefury Betrayers, and 7 Hatefury Hellcallers, and return to Takata Steelblade in Desolace.", description = "A demon infestation does not occur without other influences--something else allows evil to gain a foothold.\n\nIt may start with a weakened spirit, a needless desire for power; perhaps it's a thirst for revenge, or the appeal for final justice. When we are beset by pain, evil takes advantage of us--evil such as the satyr.\n\nTies have been made between them and the Burning Blade, and Thrall would have them slain. Seek them out to the northeast of here, and return to me when you've driven them back.", progress = "I was warned by a tauren companion that the satyr are not all they appear to be. He believes there is something more to them, that their evil is a twisting of their true nature. But I have not seen such things.\n\nI see only the ruthless slaughter of the weak and the corruption of those who seek dark power.\n\nI will continue in my duty of annihilating them until the Warchief directs me otherwise. Until then, I take no pity on them.", completion = "You have done well, &lt;class&gt;. You have shown honor and dedication.\n\nWhen our campaign in Desolace is done, the Warchief will know that you aided us in our actions here, and that you helped make his will manifest.\n\nI thank you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1435] = {title = "The Burning of Spirits", objective = "Return the Burning Gem and 15 Infused Burning Gems to Maurin Bonesplitter in Desolace.", description = "Death is most desirable for those despicable creatures that turn their back on their liege for such selfish reasons. But death is not enough when dealing with those that have given themselves over to the darkness.\n\nTake this gem. When one of the Burning Blade's near death, activate its magic. The spell shall pull the corrupted spirit out of its victim, leaving an infused gem behind.\n\nBring me these infused gems so I may dispose of them properly.\n\nGo now, and may you elude death.", progress = "I have tried to make the magics as simple as possible. Drawing the spirit of your victim out of its injured form should be child's play. Do not rely on the gem's power to slay your foe completely. You must only activate the gem when they are close to death, or it will be useless.", completion = "Ah, you've returned successful. That is good. Give me the gems and I shall put them someplace safe....\n\nMy tasks for you are complete, &lt;class&gt;. Speak to Takata when you are rested. He may have other tasks for you, or perhaps needs you to return to Orgrimmar to inform Keldran of our progress here in Desolace.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1436] = {title = "Alliance Relations", objective = "Speak to Keldran in Orgrimmar.", description = "The fight goes well, <name>. Perhaps the Warchief will allow us to return to our homes before the seasons change if we continue to make such great strides in our battle against the demons and their underlings.\n\nReturn to Keldran and let him know what we have done. I am sure he will reward you for your efforts here. His cause is important to him, and he will take pride in knowing that the Warchief respects his concerns.", progress = nil, completion = "You have returned from Desolace more than successful, &lt;name&gt;. Thank you.\n\nThank you for your efforts, your time, and your understanding to my plea. Thrall understands and desires peace between the Horde and Alliance, and by taking measures to insure our appearance is acceptable, we will not provoke any further threats of unnecessary violence.\n\nI am indebted to you.", rewards = "You will be able to choose one of these rewards:\n\nGloves of KapelanSwiftrunner Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1437] = {title = "Vahlarriel's Search", objective = "Find and search Tyranis and Dalinda Malem's wagon in Desolace.", description = "I am Vahlarriel, <name>. I've come here to discover the whereabouts of two missing nobles of a Darnassian merchant family--House Malem. The father of the house fears the worst, and I am to do everything I can to find his missing children. I have yet to start my search for Tyranis or Dalinda, but I am hopeful I shall not be here long.\n\nLast word tells of them passing through the Stonetalon Mountains a few weeks ago.\n\nIf you find their wagon, please, come find me immediately.", progress = nil, completion = "As you rummage around the remains of the wagon, it becomes obvious that it was attacked by both spells and weapons. The battle seemed one-sided and quick; there's no blood to be found, and no remains of any bodies.\n\nWhoever attacked the wagon was efficient and swift.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1438] = {title = "Vahlarriel's Search", objective = "Find Dalinda Malem in Desolace.", description = "Find both Dalinda and Tyranis if you can and come back to me with your findings. Start your search at this fortress. I will contact my superiors in Darnassus immediately and let them know the situation.\n\n<name>, there is something else I wish to impress upon you. My superiors have shown some concern over Tyranis' and his motives for coming here. It is more important to them that Dalinda is found and brought back safely. Tyranis is to be... gauged before he is taken home.", progress = nil, completion = "Thank Elune someone has finally come to help. Please, &lt;class&gt;, I need your help. My brother Tyranis and I were captured and brought here by the Burning Blade. I think they mean to sacrifice me to their demon masters!\n\n I knew coming to Desolace was a mistake, but Tyranis has recently begun craving knowledge of all things arcane--even against the wishes of our people. He decided to make this trek even after hearing tales of this land's demon infestation.\n\nI fear the worst for him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1439] = {title = "Search for Tyranis", objective = "Find Tyranis Malem in Desolace.", description = "We were brought here after the orcs slaughtered all our guards and servants. Oh, the terrible things they did to them! I thought surely they would kill us right there and then, but it became obvious they had other plans.\n\nTyranis attempted to speak to them. I think he wanted to impress them with his knowledge of the arcane... I'm not sure why.\n\nPlease, I can't leave here until I know what's happened to my brother. Find him, then come back for me when his fate is known.", progress = "I fear Tyranis will attempt to learn the Burning Blade's secrets and count himself among their kind if they allow it--he has always adored the power magic brings to those who are seduced by it.\n\nI'm not sure I could endure returning home to my family with news of Tyranis' spirit flirting with such dangers. It's a terrible enough crime among my kind to pursue such things, but to become that which we attempt to protect ourselves from, well, that's apprehensible.", completion = "This is terrible! But I suppose it was necessary. If it wasn't by your hand, it would have surely been by that of my people's. I suppose I should thank you--please forgive me if it doesn't seem sincere. I mean no offense.\n\nWith the knowledge of my brother's fate in hand, it seems the time for my escape has come. If you are still willing, I will accept your aid in escaping this horrible place.\n\nWhen you are ready, we can make our way to safety.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1440] = {title = "Return to Vahlarriel", objective = "Escort Dalinda Malem from Thunder Axe Fortress and then return to Vahlarriel Demonslayer in Desolace.", description = "So, the time is now then? I appreciate your efforts, and if the situation does not lend itself, then allow me to thank you now for everything you've done for me and my family. If you're ready, then there is nothing else for me here--we can leave when you feel the time is right.", progress = nil, completion = "Thank you, &lt;name&gt;. Dalinda made it safely back here to Nijel's Point, and in much better condition than I could have asked for. The fact that she arrived here under her own power was a good sign. I hope you're well?\n\nIt pains me to know that both Tyranis and Dalinda didn't return, but the embarrassment of Tyranis' decisions is hers to endure. It is something she will have to deal with when she returns to Darnassus.", rewards = "You will be able to choose one of these rewards:\n\nGrappler's BeltGloves of InsightGarrison CloakMoonlit Amice\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1442] = {title = "Seeking the Kor Gem", objective = "Bring a Kor Gem to Thundris Windweaver in Darkshore.", description = "Greetings, <name>. What can I do for one who follows a holy path?\n\nAh, yes, Stilwell, the blacksmith... from long ago. I remember him well, though, I have not heard his name in some time.\n\nHe never struck me as an impudent man, so I can only assume his desire for a Kor gem is noble.\n\nIf you truly wish for one of the gems, then you must head to the northwest of Ashenvale. You will find Blackfathom Deeps there within some ancient ruins. The naga who still use the gems are down below. Do not go alone, <class>.", progress = "I would be less trustful of one not on a holy path if they came asking about a Kor gem. But I trust your kind more than some of my kin. I do not judge your entire order based on the actions of just one of your fallen kind.", completion = "This is indeed the gem Stilwell desires, but before I can allow you to bring it to him, it must be purified of corruption--the naga wenches imbue the gems with power, that much is true, but of their own, evil kind.\n\nLet Stilwell know that its power is intact, and it should work well for whatever ritual he wishes it to be part of.\n\nI hope you know what you're doing, &lt;class&gt;, this is no simple item you possess.", rewards = "You will receive:\n\nPurified Kor Gem"}
MultiLanguageQuestData['en'][1444] = {title = "Return to Fel'Zerul", objective = "Return to Fel'Zerul in Stonard.", description = "Jammal'an the Prophet sentenced me to exile from The Temple of Atal'Hakkar. I once felt the high priest was a worthy leader.\n\nHis unyielding faith in his prophecy will bring about the destruction of the Atal'ai. If it hasn't already.\n\nWhen I expressed my concerns, I was labeled an infidel and ousted from the temple.\n\nThose artifacts you brought to me are harmless. But if Jammal'an has found the proper fetish enchantment for the summoning ritual, the world lies in great peril....", progress = nil, completion = "It has been quite some time since we spoke, &lt;class&gt;. I hope your journey was successful.\n\nWhat knowledge did you gain from the exiled Atal'ai in the Hinterlands?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1445] = {title = "The Temple of Atal'Hakkar", objective = "Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard.", description = "So he spoke of Jammal'an's prophecy?\n\nThe Atal'ai spiritual leader believes once Hakkar returns to Azeroth from the Nether, the god will grant the Atal'ai tribe immortality.\n\nFoolish trickery to bring about a premature doomsday if you ask me.\n\nBut you say the exile spoke of enchanted fetishes? This concerns me greatly. If these are in fact the key to the Atal'ai ritual which caused this mess, we must understand their intrinsic powers.\n\nVenture into the Temple, and seize the fetishes!", progress = "If the Atal'ai fetishes hold the power to summon Hakkar and fulfill Jammal'an's prophecy they must be seized. Such powers must be understood by the Horde!", completion = "Brave &lt;class&gt;, you have proven yourself to be a great champion of the Horde.\n\nNow this collection of fetishes of Hakkar must be dealt with at once!", rewards = "You will receive:\n\nGuardian Talisman"}
MultiLanguageQuestData['en'][1446] = {title = "Jammal'an the Prophet", objective = "The Atal'ai Exile in The Hinterlands wants the Head of Jammal'an.", description = "My Witherbark companions don't take kindly to strangers around their home.\n\nMe? I don't have a home anymore. I was exiled from my people, the great Atal'ai tribe of the Swamp of Sorrows.\n\nOur spiritual leader, Jammal'an, had what he called a prophecy. He believes the summoning of the god, Hakkar will bring the Atal'ai immortality.\n\nBut I urged caution. What if the prophecy was nothing more than manipulation?\n\nI want revenge for my exile. Bring me Jammal'an's head. Maybe then my people will be free.", progress = "Once Jammal'an has been removed, I stand a chance of returning to my people.\n\nWith Jammal'an as their spiritual leader, the Atal'ai face certain destruction.", completion = "Jammal'an's reckless trust of false visions led my people to their eternal doom.\n\nI thank you, &lt;class&gt;, for avenging my exile. I mourn for my people. I have no home to return to.", rewards = "You will be able to choose one of these rewards:\n\nRainstrider LeggingsHelm of Exile\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1447] = {title = "The Missing Diplomat", objective = "Defeat Dashel Stonefist in Stormwind.", description = "Yeah, you're obviously not the smartest <class> to come into Stormwind, but you're about to be one of the dumbest to never leave.\n\nHave you met me friends?", progress = "I didn't mean anything by the comment 'bout you being a stupid <class>. We're friends, right? No hard feelings?", completion = "So, you came to me for a reason. What is it you need?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1448] = {title = "In Search of The Temple", objective = "Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar.", description = "There was a time when I was young and full of vigor like you, <class>.\n\nBut now I'm old and unable to explore the world like I once did. Ah, the things I saw!\n\nBut there was one mystery that eluded me. For my final quest, the Explorers' League sent me in search of The Temple of Atal'Hakkar. It was rumored to be located in the Swamp of Sorrows.\n\nBecause of my frail state, I traveled the skies by gryphon in search of it but never found it.\n\nHelp an old dwarf out? Perhaps you will have better luck on foot.", progress = "I have traveled the world from the jungles of Azeroth to the snowy peaks of Khaz Modan.\n\nNever before have I asked for help in my adventures. But my old bones are tired.\n\nNothing would leave me feeling more satisfied than knowing that I completed my final quest for the Explorers' League\n\nIf you'd be so kind as to help me search for the Temple of Atal'Hakkar, <class>, I'd greatly appreciate it.\n\nScour the Swamp of Sorrows and report back with your findings!", completion = "The Temple of Atal'Hakkar has been sunk beneath the Pool of Tears? And surrounded by the green dragonflight?\n\nAn amazing discovery, &lt;class&gt;. But obviously something has gone terribly wrong.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1449] = {title = "To The Hinterlands", objective = "Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands.", description = "As I mentioned earlier, I attempted to scout the temple on my own from the air. Well, I wasn't exactly alone.\n\nI traveled to the renowned gryphon aviary at Aerie Peak in The Hinterlands. There I enlisted the aid of one of their finest pilots. The pilot fell off his mount, down into the swamp...\n\nIn my old age the poor fellow's name eludes me. The master of the aviary would remember, no doubt.\n\nJourney there and seek out Falstad Wildhammer.\n\nWe need to find out what happened to that pilot.", progress = nil, completion = "What do you want, laddy? Can't you see I've got problems to take care of here? Who has time to stand around yapping with some &lt;race&gt; chatterbox?\n\nThere are trolls coming out of the woodwork! Make it snappy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1450] = {title = "Gryphon Master Talonaxe", objective = "Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary.", description = "So you're a glorified errand <boy/girl> for some old Explorers' League geezer, eh?\n\nWell you listen to me, <class>. I don't know who your old buddy was flying around with down in Azeroth. Do I look like Gryphon Master Talonaxe to you? Do I?\n\nIf you're so interested in the flight assignments why don't you ask the gryphon master? If I catch you idling around here for much longer, I'm going to put you to some real work.\n\nNow get a move on.", progress = nil, completion = "Ah, yes. Of course I remember sending one of my gryphon riders to lend a hand to Brohann Caskbelly.\n\nAlways had a soft spot in my heart for the Explorers' League. My father helped with the initial excavation team that discovered Uldaman as a matter of fact.\n\nI sent who I thought was my best gryphon rider at the time with Brohann. He was a chap by the name of Rhapsody Shindigger.\n\nAnd what a gryphon jockey he was! Well until...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1451] = {title = "Rhapsody Shindigger", objective = "Seek out Rhapsody Shindigger in The Hinterlands.", description = "Rhapsody took quite a liking to the booze. Now don't get me wrong -- all of us dwarves up here at the aviary love a good ale when the time is right.\n\nBut ol' Shindigger took to the liquor like a gryphon takes to the skies. And a damned shame it was, too. No one could fly like Rhapsody.\n\nFirst sign of trouble was when he came stumbling back from that mission with your buddy, Brohann. All went down hill quickly after that. Had to let him go.\n\nLast I heard, he's set up a brew camp to the east of here...", progress = nil, completion = "Hiccup!\n\nI'm a-lookin' right at you but you keep bobbing up and down. Makin' me dizzy. Hoho!\n\nHiccup!\n\nWhoa! Did ya feel that? Ground is a-shakin', my friend. I need a drink.\n\nHiccup!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1452] = {title = "Rhapsody's Kalimdor Kocktail", objective = "Rhapsody Shindigger in The Hinterlands wants you to bring him 3 Roc Gizzards, 3 Groddoc Livers and 3 Ironfur Livers.", description = "Hiccup!\n\nSo that crazy fool Brohann sent ya? My we had quite an adventure...Hiccup!\n\nIf ya want me to tell ya what happened down in the swamp, I'm gonna need me something stiff to drink. It wasn't a pretty scene, ya see. Hiccup!\n\nTell ya what... bring me what I need to whip up a Kalimdor Kocktail and I'll tell ya all about it.\n\nGonna need some Roc gizzards from Tanaris... and let's see... some Groddoc and Ironfur livers from Feralas...\n\nA nice stiff Kalimdor Kocktail... that'll get me talking!", progress = "Ya ever had a Rhapsody Malt? One of my finest brews, if I do say so myself. Hiccup!\n\nBut if I'm gonna relive the horrors of that fateful flight over... hiccup... the swamp, well I'm gonna need me something a wee bit stronger. Hiccup!\n\nDon't suppose you found me those gizzards and livers I need to add that extra kick to my Kalimdor Kocktail?\n\nHiccup!", completion = "I see ya had no trouble at all getting me what I need! Musta been quite a stint you had over there in far-off Kalimdor.\n\nIt won't take but a moment for me to extract what I need from these gizzards and livers. Hiccup!\n\nThen I can distill me a fierce ol' drink and finally tell ya what ya wanna know.\n\nHiccup!\n\nGetting shivers just thinking about that ol' swamp.\n\nHiccup!\n\nLemme whip up a drink real fast.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1453] = {title = "Reclaimers' Business in Desolace", objective = "Speak to Kreldig Ungor in Desolace.", description = "There's work to be done in Desolace, <name>. It's an atrocious place, befouled by centaur and other nasties. But if you're looking for a good week's honest work, then head there, meet with Kreldig Ungor, and tell him I sentcha.\n\nYou can find him holed up at Nijel's Point--it's a little cozy camp hidden in the mountains of northern Desolace. Just head east if you enter from the Stonetalon Mountains. It's easy to miss, so be on the lookout.", progress = nil, completion = "Glad to see the Reclaimers aren't in short supply of work, or adventurers willing to help out.\n\nI'm Kreldig, &lt;name&gt;. You've made a smart move helpin' out the Reclaimers. Everyone needs something these days: they've lost a family heirloom, a magic item, a loved one. You never can tell. But with the Reclaimers around, there's no reason, for the right price, everyone can't find what they've lost.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1454] = {title = "The Karnitol Shipwreck", objective = "Find Karnitol's Chest in Desolace.", description = "My first order of business is for the mage Karnitol--a noble of some sort in Stormwind. Seems his ship was attacked by sea giants while off the coast in the northwest of Desolace. He and his servants tried to bring one of his more valuable chests ashore, but when the sea giants attacked in droves, he chose to abandon it and teleport himself and his servants to safety.\n\nHe wants us to find the chest and its contents, and return it to him in Stormwind.", progress = nil, completion = "You notice the chest does not seem to have any water damage.\n\nThe second thing you notice is that the top has been forced open, and whatever magical traps were set to safeguard it have long been triggered--this much is obvious from the burn marks around its edges.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1455] = {title = "The Karnitol Shipwreck", objective = "Return to Kreldig Ungor in Desolace.", description = "You take a few moments to figure out what pried the chest open, and you notice along the sides and top of the chest, long, deep scratches that reveal that something other than a man or giant took interest in it. The marks don't appear as if they were caused by dagger or sword.\n\nAfter going through the chest you find it to be completely empty.\n\nNot having another course of action, you close the chest and prepare to leave. Kreldig will be disappointed.", progress = nil, completion = "Welcome back to Nijel's Point, &lt;name&gt;. So, tell me what you found.\n\nWhat!? Nothing? An empty chest ain't gonna get us paid, I'm afraid.\n\nTell me more about these marks you saw... these slashes.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1456] = {title = "The Karnitol Shipwreck", objective = "Find Karnitol's Satchel and return it to Kreldig Ungor in Desolace.", description = "Intriguing.\n\nWell, we might not be without hope quite yet.\n\nAlong that same coast, but to the north near Ranazjar Isle, there're night elf ruins at the bottom of the ocean. A tribe of naga, the Slitherblade, make that their home. I think that'd be our best bet.\n\nIf a scouting party went that far south, then they must've been pretty powerful. If you're gonna find Karnitol's belongings, I'd start with the more powerful naga: the tidehunters or sea witches.", progress = "No offense to whoever Nijel is, but this camp ain't the most comfortable place I've spent a night, if you know what I mean, <name>.", completion = "This is great, &lt;name&gt;! You found Karnitol's belongings!\n\nThose blasted naga, always causing trouble. I think I'd rather spend my life at war with the Horde than have to go against their kind. You've done a great service to the Reclaimers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1457] = {title = "The Karnitol Shipwreck", objective = "Bring Karnitol's Satchel to Roetten Stonehammer in Ironforge.", description = "Take Karnitol's things back to Roetten in Ironforge and he'll pay you for a job well done.\n\nHaha, if you're not careful, he's gonna be so pleased with ya that he'll ask you to join us full time.\n\nAgain, great job, <name>.\n\nBe careful on your way back, and don't take too much time--Karnitol's not the most of patient of men, but he's very generous nonetheless.", progress = "Business is booming, <name>, and I don't have a lot of time for questions. If you've got business with the Reclaimers, then let's hear it. If not, I'm gonna have to ask you to talk to one of me underlings--they're adept enough at taking care of things 'round here.", completion = "Ah, the Karnitol business in Desolace. Excellent!\n\nSo, the chest was destroyed, but the items are all here, huh? Well, I'll let him be the judge of that. One good part about this business I got going on here is that if they're not satisfied, I can tell 'em to shove it! They're relyin' on us to find their stuff... not make sure it's all pretty and in good shape when they get it back.\n\nGood work, &lt;name&gt;. Let's see about gettin' you paid.", rewards = "You will be able to choose one of these rewards:\n\nHellion BootsSanguine Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1458] = {title = "Reagents for Reclaimers Inc.", objective = "Bring 10 Hatefury Claws, and 10 Hatefury Horns to Kreldig Ungor in Desolace.", description = "One of my tasks out here involves picking up some reagents for Leftwitch, a gnome mage in Kharanos . Roetten seems to think it's easy coin in the bank since we're out here already. He doesn't really care that we're short-handed as is.\n\nThe first few items on his list should be easy enough to get, and it'd be a good chunk of coin for anyone helping me out.\n\nI need some horns and claws from the Hatefury satyr to the east of here. Bring 'em back to me and we'll get started on the rest of the list.", progress = "Despicable creatures, the satyr. Story says they're somehow tied to the night elves, but I'm not so sure I believe it.\n\nI think they get that on account of that one elf that brought them into the war few years back. World's never been the same since. Lot more dangerous, and a lot scarier.", completion = "Good good, &lt;name&gt;. Not sure if these are of any good quality, but if Leftwitch wanted a specific type, he should have specified before sending the Reclaimers out here to begin with.\n\nWhat say you to getting on with the next item on his list?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1459] = {title = "Reagents for Reclaimers Inc.", objective = "Bring 7 vials of Scorpashi Venom and 3 Aged Kodo Hides to Kreldig Ungor in Desolace.", description = "Next on Leftwitch's list is... let's see... hmm. Oh, here it is.\n\nSimple enough, but pretty explicit in his directions. He needs venom from the scorpashi, and hide from some kodo. The fine print says both are from specific creatures: the venom's got to come from any of the scorpashi, and the hide's got to come from an aged kodo, not the dying or ancient ones.\n\nMages, I tell ya, some of the stuff they want... it's just weird.", progress = "Sorry I couldn't tell you where to find the kodo or the scorpashi. I'm not terribly familiar with the area, and I haven't had time to explore.", completion = "Your help here's a boon, &lt;name&gt;. You're cutting my time spent here in Desolace by half at least. I'll be back in Ironforge warming my feet in no time with your help.\n\nWhen we get this list taken care of, and I'm back home, look me up, I'll buy you an ale for sure.\n\nBut until then, let's get the rest of these reagents gathered.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1462] = {title = "Earth Sapta", objective = "Speak to Seer Ravenfeather for another Earth Sapta.", description = nil, progress = nil, completion = "Take this and remember, it is sacred.", rewards = "You will receive:\n\nEarth Sapta"}
MultiLanguageQuestData['en'][1463] = {title = "Earth Sapta", objective = "Speak to Canaga Earthcaller for another Earth Sapta.", description = nil, progress = nil, completion = "I give you one in good faith. You already proved yourself once, but me tinkin' you should be more careful in the future.", rewards = "You will receive:\n\nEarth Sapta"}
MultiLanguageQuestData['en'][1464] = {title = "Fire Sapta", objective = "Speak to Telf Joolam for another Fire Sapta.", description = nil, progress = nil, completion = "May fire burn within your heart, &lt;name&gt;.\n\nThe elements await you.", rewards = "You will receive:\n\nFire Sapta"}
MultiLanguageQuestData['en'][1465] = {title = "Vahlarriel's Search", objective = "Return the Malem Pendant to Vahlarriel Demonslayer in Desolace.", description = "As you continue your search of the wagon you find not only a pendant, but also footprints leading off towards the south. In the distance you can see smoke rising from a large fort. The smoke is from a kept fire, not the burning of buildings, and your instincts tell you that the Malems, if still alive, were taken that direction.\n\nYou think Vahlarriel at Nijel's Point should not only see the pendant you've found, but also know about the signs of life to the south.", progress = nil, completion = "Infuriating! This entire fiasco!\n\nThe two of them were warned about how dangerous coming here would be. Now they're both missing... or worse.\n\nYou said you saw tracks heading to a fort nearby? That may be our best bet.\n\nFrom what the locals have said, that fortress is infested with members of the Burning Blade--orcs who have dedicated themselves to demon causes. They may not represent the majority of the Horde's beliefs, but they are evil and will slay you on sight if you're caught spying.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1466] = {title = "Reagents for Reclaimers Inc.", objective = "Bring 10 Felhound Brains, 10 Nether Wings, and 10 vials of Doomwarder Blood to Kreldig Ungor in Desolace.", description = "This is the last of the items, and I won't lie, it ain't pretty. I'm also expecting this to take you a little bit longer than the other items.\n\nSo, enough with the warning, let's get this started. Leftwitch says he needs: ten brains from either mana eaters, mage hunters, or ley hunters. Ten nether wings from a nether maiden, sister or sorceress. And... ten vials of doomwarder blood from a doomwarder captain, or lord.\n\nSimple enough, huh? Sheesh... if you wanna pass on this one, I'd understand.", progress = "I didn't even realize these demon things were in Desolace. Last I read, centaur pretty much owned the land after the night elves picked up and left years ago.\n\nI wonder why they took up here, and how.", completion = "Honestly? I wouldn't have thought it. You're amazing, &lt;name&gt;. Taking on demons for a mage's experiments, and coming back in one piece to boot. Great job!\n\nI'm personally gonna tell Roetten about you when I get back to Ironforge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1467] = {title = "Reagents for Reclaimers Inc.", objective = "Bring Leftwitch's Package back to Roetten Stonehammer in Ironforge.", description = "To get paid, you're gonna have to get back to Ironforge and speak to Roetten himself. He'll love getting Leftwitch's package out of the way anyway. Just give him this and it should be enough to get your booty.\n\nAnd don't worry, I'm still going to put in a good word for you when I get back. I shouldn't be in Desolace much longer.", progress = "Well met, <name>. Business is booming, the sounds of anvils being struck rings throughout Ironforge, the bellows blow the fires hot, and me wife's making me a pie for dessert after tonight's dinner. Could life be any grander?", completion = "Ah, the package for Leftwitch from Desolace. Excellent. I 'preciate the work, and your timeliness, &lt;class&gt;. Glad to have you aboard for at least this small bit of work.\n\nI got your payment right here. Let it be known that Reclaimers Inc. always pays well for a hard week's work.", rewards = "You will be able to choose one of these rewards:\n\nAuric BracersStormfire Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1468] = {title = "Children's Week", objective = "Use the Human Orphan Whistle to talk with the child you will be looking after during Children's Week.\n\nProvided item: \n", description = "You're willing to help us here at the orphanage?  Bless you, friend; your aid during Children's Week will be invaluable.\n\nTake this whistle.  You will only be able to use it for a short amount of time - typically not longer than Children's Week itself.  When you use it, you will be able to talk with the child you've agreed to look after.  Using it again will dismiss the child.\n\nBy all means <name> - use the whistle and meet your ward!  I'm sure the child will be most eager to meet you.", progress = nil, completion = "Um... hi.  My name is Randis, and I guess you're looking after me?  You're an adventurer, like my mom and dad were.  I'm happy to meet you.\n\nI hope we'll have a lot of fun together.  I have some things I'd like to do, and the matron says you'll be like a big brother to me during this week.  I'd like that a whole bunch, yes sir.", rewards = nil}
MultiLanguageQuestData['en'][1469] = {title = "Rhapsody's Tale", objective = "Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind.", description = "Before the flight, I drank me a whole keg of stout. Hiccup!\n\nAnd what a flight it was. Zipping around with Brohann following me. Didn't see no temple though. Hiccup!\n\nWell, didn't see no temple till I got a little too tipsy and fell off my mount. I plunged right into the water and was sucked down. Found myself surrounded by a bunch of creepy trolls. Sure swam out of there fast! Even made off with this troll souvenir. Here, take it to Brohann and let him know his temple is down there, indeed. Hiccup!", progress = "At long last you have returned, <name>. It has been quite some time since we last spoke. I thought perhaps you had forgotten about my quest.\n\nDid you locate that wily gryphon rider? Did he have anything to report?", completion = "Rhapsody Shindigger! That's right... how could I forget such a name?\n\nSo he knew about the sinking of the temple all along? Well, that certainly would have saved you some leg work.\n\nBut this Atal'ai artifact! Why, it's quite a find!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1470] = {title = "Piercing the Veil", objective = "Bring Venya Marthand 3 Rattlecage Skulls.", description = "Greetings, child. I can see that you are still young in the ways of the warlock, power still eluding your grasp. I can sense your eagerness to learn.\n\nAnd you will learn.\n\nThere is no strength in ignorance. Knowledge is our greatest power. Through its application, we can control the chaotic magics and beings of the void, bending them to our will.\n\nI will show you how to bind a servant to your will, but first you must bring me three skulls of the rattlecage skeletons near the abandoned smithy.", progress = "Your power is little now, though I suspect already you sense the possibilities.\n\nEven the dead might feel alive, with that power coursing through us.", completion = "Though you are still untested and young in your learning, you have proven that you possess sufficient ability to master the summoning and binding of an imp. Do not be deceived by an imp's size. Though it lacks physical strength, it possesses powers and a cleverness that will serve you well.\n\nAttend me carefully, &lt;name&gt;, for I will not repeat this lesson, and I will leave its mastery to you.", rewards = "You will learn:\n\nSummon Imp\n\nThe following spell will be cast on you:\n\nTeach Summon Imp\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1471] = {title = "The Binding", objective = "Using the Runes of Summoning, summon and subdue a voidwalker, then return the Runes of Summoning to Carendin Halgar in the Magic Quarter of the Undercity.", description = "Surely you have seen the circle of summoning below us? Only there will you be able to draw forth an unbound voidwalker.\n\nUsing these runes, you will be able to draw it forth, and then you must dominate it through strength of arms and magic.\n\nWhen it is subdued, it will be indentured to you. Come to me then, and I will elucidate the spell of summoning, so that it may serve you to whatever end you wish.", progress = "I expect to hear of your success, <name>. Not meeting my expectations will be the least of your worries, however, should you fail.", completion = "You have done well, &lt;name&gt;. Now, I will impart to you the spell used for summoning the voidwalker.\n\nThe power that it unleashed upon you is now yours to command. Use it wisely.", rewards = "You will learn:\n\nSummon Voidwalker\n\nThe following spell will be cast on you:\n\nTeach Summon Voidwalker\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1472] = {title = "Devourer of Souls", objective = "Speak with Godrick Farsan in the Temple of the Damned.", description = "A sayaad is a devourer of souls, dominator of wills, tempter of hearts. A creature of profound evil and singular mind.\n\nFolk tales told by righteous and wicked alike use their common name: succubus for females, incubus for males.\n\nThe demon must be lured into our world with a stimulus - the hearts of pure and loving mortals. The sayaad will be unable to resist. Then you can dominate it, and make it your own.\n\nSpeak with my assistant, Godrick Farsan, within the temple. He will help you find your bait.", progress = nil, completion = "You were sent by Carendin? &lt;name&gt;, then.\n\nDo not think light of me because my sight is gone. I see things that lie behind now, with clarity I had never known. What I once thought a curse, is now a boon.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1473] = {title = "Creature of the Void", objective = "Recover Egalin's Grimoire and bring it to Carendin Halgar in the Temple of the Damned.", description = "It seems the consensus that you are ready to learn to summon a voidwalker.\n\nA being created of the chaos that lies beyond, if you summon one but cannot control it, you will be torn asunder.\n\nThe first voidwalker was summoned by Egalin, and in his grimoire is the process explained.\n\nUnfortunately, it was stolen from us by an agent of the Scarlet Crusade who has it secreted away in his base at a tower to the west. Bring it to me, and I will impart the knowledge to you.", progress = "Egalin was the teacher that taught me. With hardly a look, he was able to command the voidwalker he had summoned.\n\nWhen it came my turn to try, I was overconfident. Do not trifle with the powers that you wield, <name>, they can consume even the vigilant.", completion = "Ah, this is excellent. Like as not, Perrine was ignorant to the true power of the musty book he had stolen from us.\n\nIt will not fall out of our hands again. Observe, &lt;name&gt;, the structure of the spell, the manner in which your power must be channeled.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1474] = {title = "The Binding", objective = "Using the Pure Hearts, summon and subdue a succubus, then return the Pure Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", description = "Using these hearts, cast a spell at the summoning circle to open a doorway for the succubus to come through. Your powers are greater now, and you will need all of them to defeat the succubus. \n\nBeware its charms, <name>, many a strong mind has been bound to its will. When overcome, the succubus will be returned to the void, and I will teach you the spell to summon it forth at your command.", progress = "Of the powers from beyond the void, the succubus is one of the most dangerous, as the weak are most easily wrapped around its fingers.\n\nRemember that now and in the future.", completion = "Again, you have done well, &lt;name&gt;. It has been quite some time since I have seen a young &lt;class&gt; with as much potential as you. Be assured that I will continue to watch your progress, and prepare and assist you in your future trials.\n\nFor now, let me show you the summoning spell for your newly dominated succubus.", rewards = "You will learn:\n\nSummon Succubus\n\nThe following spell will be cast on you:\n\nTeach Summon Succubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][1475] = {title = "Into The Temple of Atal'Hakkar", objective = "Gather 10 Atal'ai Tablets for Brohann Caskbelly in Stormwind.", description = "According to legend, The Temple of Atal'Hakkar is a holy shrine dedicated to the ancient god, Hakkar the Soulflayer. Maintained by a vicious tribe of trolls named the Atal'ai, the temple is rumored to be impenetrable.\n\nNow sunk beneath the Pool of Tears, retrieving artifacts from the temple is even more difficult. But that's what I need you to do, <name>.\n\nAid me by gathering the intact Atal'ai Tablets. Bring them to me and I will return to the Explorers' Guild a hero. Together we will share the glory.", progress = "As dusk slowly descends upon my career I turn to you, <name>, to help me in my final quest for the Explorers' League. If my old bones could muster the strength to brave the Swamp of Sorrows and the sunken temple I would be fighting right alongside you.\n\nPride makes it hard for me to ask for your help in collecting the Atal'ai Tablets. But old age forces the necessity.\n\nPlease help me, <name>. I want to retire from the Explorers' League having completed their final bidding.", completion = "The Atal'ai Tablets! Thank you, &lt;name&gt;!\n\nOnce I deliver these to the Explorers' League our names shall go down in history together. You have helped an old dwarf fulfill his final obligation in life. For that I am eternally grateful.", rewards = "You will receive:\n\nGuardian Talisman"}
MultiLanguageQuestData['en'][1476] = {title = "Hearts of the Pure", objective = "Bring the hearts of Dalin Forgewright and Corma Villard to Carendin Halgar in the Temple of the Damned.", description = "Coaxing a succubus will require the hearts of the pure. But is any mortal without vice?\n\nThrough bits of overheard stories, I found two humans that should do.\n\nThe first is Dalin Forgewright, who has dedicated himself to the care of the Lordaeron refuges, whom are refused by their kin at the Greymane Wall.\n\nThe other is Corma Villard, a woman who remains faithful to her lost love, wandering the Wetlands for a sign of her.\n\nDeliver their hearts to Carendin. But first, let me show you your quarry.", progress = "I have been pleasantly surprised by the speed of your progress so far, <name>. Bring me the hearts and you will impress me once again.", completion = "The heart of a goodly man seems much the same as any, when you see it like this, don't you think?\n\nPerhaps we possess something of a... different... view on the subject. These will do, though. I have no doubt that a succubus would be attracted by their purity.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1477] = {title = "Vital Supplies", objective = "Speak with Watchmaster Sorigal.", description = "Our mages are conducting research at Nethergarde Keep in the Blasted Lands, research vital to our understanding of the Dark Portals. They require nearly constant supplies, but our supply line to Nethergarde is tenuous.\n\nYou must help ensure the supplies make it to Nethergard.  Report to Watchmaster Sorigal in Darkshire, and do as he asks.  This task will take you into hostile lands, <name>.  Prepare yourself.", progress = nil, completion = "Andromath sent you?  Very good.  I have an important task for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1478] = {title = "Halgar's Summons", objective = "Speak with Carendin Halgar in the Undercity.", description = "Ah, <name>! I just received word from Carendin Halgar that he would like to see you for further training.\n\nYou should be proud of yourself, <name>. It's not every day that Master Halgar personally sees fit to instruct a young warlock.\n\nYou'll be able to find him in the Magic Quarter of the Undercity, near the Temple of the Damned.", progress = nil, completion = "Good, I see Ageron managed to find you, &lt;name&gt;. Let us waste little time with small talk and pleasantries and focus on your training. There is still much you have to learn.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1479] = {title = "The Bough of the Eternals", objective = "Take the orphan to the bank of Darnassus. The bank itself is hollowed out of a tree known as the Bough of the Eternals.", description = "I've heard stories about how the night elves have their bank in a tree - one that looks like a bear!  That's so cool!  Night elves are neat how they like nature and stuff, but bears are just totally awesome!\n\nWould you take me to see the bear-tree in Darnassus, please?  There's a boat that will take us close to there, and it shouldn't take very long.  Please, please, please!", progress = "Are we there yet?", completion = "Wow, it was cooler than I even imagined - the Bough of the Eternals!  I didn't think it'd be so big, but it was!  Did you see the bird on top of it too?!  I wonder how they got the branches to look like that!\n\nThanks for taking me to Darnassus, &lt;name&gt;.  You're awesome!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1480] = {title = "The Corrupter", objective = "Bring the Flayed Demon Skin to Maurin Bonesplitter in Desolace.", description = "The torn skin smells rotten, and is remarkably pliable for something that appears to be dry and fragile.\n\nAs you unroll it, you can clearly see the red markings of some kind of language on one side. At the bottom of the skin is a very clear symbol that you guess is a signature of some kind.\n\nPerhaps it is something Maurin could tell you more about?", progress = "The Burning Blade begin to realize how weak they truly are. Their magics are pathetic, their strength feeble.\n\nTheir only power comes from those they serve, and not from any understanding of true power and knowledge.", completion = "Hmm, these runes are indeed a language, &lt;name&gt;, an old language. They seem remotely similar to the Eredun language, but the differences are drastic. If I am not mistaken, this is a contract of some kind.... Here, yes, this symbol is the demon's signature: Lord Azrethoc.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1481] = {title = "The Corrupter", objective = "Bring a Shadowstalker Scalp to Maurin Bonesplitter in Desolace.", description = "I believe I can find this demon lord given the proper reagents.\n\nIf he is indeed as powerful as I suspect, I will need items gathered from deadly creatures. But you act in the Warchief's name, so I am sure you will accept my task.\n\nFirst, I will have to break any wards he has against scrying. For this, I will need the scalp from a satyr--but not any satyr. The scalp must come from a Hatefury shadowstalker.\n\nSearch for them among the ancient ruins in the northeast of Desolace.", progress = "Do not bring me an incorrect scalp, <class>. Using the incorrect reagents could cause our deaths. The demon lord may have contingency spells on his person to slay those who would scry upon him.\n\nFate has already dealt me enough pain.", completion = "The shadowstalkers were unable to slay you, &lt;class&gt;. Impressive... most impressive.\n\nThis scalp will do nicely for my spell. While you were away, I was able to gather some of the other reagents needed for the spell.\n\nI am almost ready. I only need a focus for the spell--something to project an image of the demon lord and his whereabouts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1482] = {title = "The Corrupter", objective = "Bring an Oracle Crystal to Maurin Bonesplitter in Desolace.", description = "An oracle crystal would do nicely. They are crafted by the naga for their oracles to use.\n\nNorthwest of here, along the coast, is a vast coral reef that the naga have taken as their home when this close to the shore. You can find their oracles there. The Slitherblade are deadly and will not react kindly to your intrusions, so be careful and make haste.\n\nWhen you return, we shall see about finding this demon lord Azrethoc.", progress = "I am ready for the oracle crystal, <class>. Finding and destroying this Lord Azrethoc would garner a great deal of favor with the Warchief for both of us. We would do well to work together and to do so swiftly so we may further our own ends and curry favor with the Warchief.", completion = "A precious oracle crystal... flawless... beautiful. Indeed.\n\nWe shall begin immediately. Finding this demon lord should be our primary concern, and its slaying demands our utmost attention.\n\nTake a step back, &lt;class&gt;, and let us see what this demon is, and where he may be found.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1483] = {title = "Ziz Fizziks", objective = "Speak with Ziz Fizziks in Windshear Crag.", description = "The Venture Company stole many of the best goblin minds, but from time to time, we get the opportunity to steal some back.\n\nA while ago, the Venture Company outfit in the Stonetalon Mountains hired Gerenzo Wrenchwhistle--a gnome! Their other engineer, Ziz Fizziks, was so taken aback by this, he pleaded with me to find him new employment with the Tinkers' Union. I set him on a few tasks, but he might need help.\n\nMaybe you could look in on him for me? He's stationed at the western edge of Windshear Crag.", progress = nil, completion = "I thought those Venture Company higher-ups were slave drivers, but then I met Sputtervalve, the cruelest of them all!\n\nHa! Though it's better than being out of a job, I suppose... Or worse, working with that Gerenzo. If you're here to help, I've got something for you to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1484] = {title = "The Corrupter", objective = "Speak to Takata Steelblade in Desolace.", description = "This creature is far more dangerous than I had anticipated.  No doubt Takata questions my abilities to take on such a creature, and it would insult his honor if he were not informed about what just happened.\n\nSpeak to the swordsman, tell him you are willing to slay the demon if he would allow it, but do not press too hard. It is better if he thinks it his own idea.", progress = nil, completion = "I witnessed what just occurred with Maurin and the demon lord. That creature, even as an apparition, seems to have more power than my warlock companion. I wonder if he's up to the task of defeating the monster? It would serve the Warchief better if I go myself, but with my responsibilities here, I would disgrace my clan if I turned my back on my duties here to battle this evil for my own honor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1485] = {title = "Vile Familiars", objective = "Bring 6 Vile Familiar Heads to Ruzan.", description = "Those warlocks who came before us have earned the distrust of the Horde, and while we are tolerated, we are not loved.\n\nThis has not brought the warlocks closer together, however, as many choose to live reclusively, dabbling in their magics alone. I will not seek to lead you down one path or the other, but only help you in your maturation.\n\nBefore I teach you the art of summoning, bring me six heads of the vile familiars from the cave to the northeast.", progress = "It is important that you can control the beings that you summon through your magic. There are few enough interested in learning the ways of the <class> that I would risk throwing your life away by teaching you something before you are ready.", completion = "Throughout your training as a &lt;class&gt;, you will learn to call forth beings of many sorts. Some may not seem it, but all are useful tools.\n\nDo not be fooled by the imp's small size. As you no doubt noticed, it is still a formidable adversary.", rewards = "You will learn:\n\nSummon Imp\n\nThe following spell will be cast on you:\n\nTeach Summon Imp\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1486] = {title = "Deviate Hides", objective = "Nalpak in the Wailing Caverns wants 20 Deviate Hides.", description = "As Naralex descended deeper into his nightmare, a strange breed of beasts arose from beneath the Barrens into the Wailing Caverns.\n\nThese deviate creatures have strange, otherworldly properties. While evil in nature, it is my opinion that some good can come from their existence here in Kalimdor. I believe their hides will be of particular use in the ways of leatherworking.\n\nIf you feel up to the task, venture into the caves below and retrieve some deviate hides.", progress = "I am very interested in examining the hides from the deviate creatures who have infested these caves. Have you had any luck in collecting some, <class>?", completion = "Your efforts shall not go unnoticed in gathering these hides, &lt;name&gt;.\n\nThank you for your dedication.", rewards = "You will be able to choose one of these rewards:\n\nSlick Deviate LeggingsDeviate Hide Pack\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1487] = {title = "Deviate Eradication", objective = "Ebru in the Wailing Caverns wants you to kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs.", description = "Naralex had a noble goal.\n\nOur great leader aspired to enter the Emerald Dream and help regrow these harsh lands back into the lush forest it once was. But something went terribly wrong.\n\nNaralex's dream turned into a nightmare and corrupt creatures began to inhabit the caverns.\n\nWhile some Disciples of Naralex seek to awake our master, my concern is with ridding these caves of the evil beasts.\n\nBrave the caverns, <name>, and eradicate the deviate spawn.", progress = "<name>, we, the Disciples of Naralex, need your help. Our numbers are dwindling with our master trapped in his twisted nightmare. We have not the forces necessary to deal with the corrupt creatures which now haunt these caverns.\n\nI beg of you, enter the caves and wage war on the deviate creatures!", completion = "As a Disciple of Naralex, I commend your bravery, &lt;name&gt;.\n\nYour aid in ridding the caverns is the first step in our long plight to see the Barrens restored.\n\nThank you and may you prosper.", rewards = "You will be able to choose one of these rewards:\n\nPattern: Deviate Scale BeltSizzle StickDagmire Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1488] = {title = "The Corrupter", objective = "Slay Lord Azrethoc and Jugkar Grim'rod and return to Takata Steelblade in Desolace.", description = "Although I have no knowledge of this Lord Azrethoc, I agree with Maurin, he must be stopped; especially if he is attempting to gain influence over the Burning Blade to further his goals.\n\nYou have already shown you wish to aid the Warchief, and I would trust you to gather a party to slay the demon lord and his warlock servant.\n\nWhen you are ready, head directly south,  and return to me when the threat has been ended.", progress = "Glory to the Horde, and death to our enemies, <name>!\n\nThe demons in Desolace pose a greater threat than ever before. My hope of returning to the Warchief dwindles as more and more of the foul creatures seem to appear.\n\nI sometimes wish it was only the centaur we had to deal with.", completion = "A mighty victory for us all, &lt;name&gt;. Let us rejoice in your success. I trust now that our future here is not as bleak as I once thought.\n\nThe demons will be slain, the Burning Blade will fail in their efforts, and we may one day have a place we can safely call home again.", rewards = "You will be able to choose one of these rewards:\n\nBasalt BucklerEnforcer Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1489] = {title = "Hamuul Runetotem", objective = "Speak with Hamuul Runetotem.", description = "The shells you brought me have a taint, one I have never before seen.  I am certain the water of the Oases is the cause, and I can sense the confusion they cause this land.  It is as if the land dreams and cannot awake.\n\nThe Wailing Caverns must be the source of the taint.  But before you go there, speak with Hamuul Runetotem, the elder druid.  I sent word to him of the happenings in the Barrens.  He is wise, and can offer you counsel.\n\nYou will find him in Thunder Bluff, on the Elder Rise.", progress = nil, completion = "I bid you greetings, &lt;name&gt;.  You are welcome here, and I suggest you gather all your strength.  For the task we now set before you ... is a dire one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1490] = {title = "Nara Wildmane", objective = "Speak with Nara Wildmane.", description = "I entered the land of dreams, and dreamed of a cult of druids who dwell in the Wailing Caverns.  I saw that their goals were once noble, but they have lost their way.  They are now servants of the taint seeping through the Barrens.\n\nI am old and my strength fails.  I could not long dwell in that dreaming place and know little more of the tainted druids.  But Nara is young and her spirit is fierce.  She remained in the dreaming when I fled.\n\nSpeak with Nara.  She is in the tent, over yonder.", progress = nil, completion = "Yes, it is true.  I know of the druids in the Wailing Caverns.  I have seen their twisted, scaled faces.  I know their crimes, and I know their plans.\n\nYou must stop them, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1491] = {title = "Smart Drinks", objective = "Bring 6 portions of Wailing Essence to Mebok Mizzyrix in Ratchet.", description = "Ok, so the raptor horns didn't work so well.  But that's all right -- no one got rich on their first try!  And besides, I think I found something that'll work even better in my smart drinks!\n\nThere is a substance called Wailing Essence, and I think it is the cause of the strange plants and animals in the Barrens.  Get me some and I'll try it in my drink!\n\nI heard the essence gathers in ectoplasmic creatures in the Wailing Caverns to the west.  Hunt those creatures and gather the essence.", progress = "Where is my wailing essence?", completion = "Great, you got it!  I can't wait to try it out.  This is going to make me a fortune, I just know it!\n\nThank you, &lt;name&gt;.  Take this, and after I'm rich I'll send you more, I promise!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1492] = {title = "Wharfmaster Dizzywig", objective = "Bring the Secure Crate to Wharfmaster Dizzywig in Ratchet.", description = "I have need to send a crate of potions, reagents and other items to my associates in the Old World. Little time I have to actually see them to the dock at Ratchet, and the last caravan has already left.\n\nIf you could, please take this to Wharfmaster Dizzywig. He will ensure that it is placed on the next boat to Blackwater Cove.", progress = "You seek passage on the next ship, or have some item you wish to send aboard it?", completion = "A small enough crate. Yes, I should be able to find room for this aboard the ship. It sails with the next tide, I trust this is soon enough? Excellent. Let me just enter it into my ledger.\n\nAll taken care of! Good day to you, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1498] = {title = "Path of Defense", objective = "Bring 5 Singed Scales to Uzzek at Far Watch Post in the Barrens.", description = "As a warrior, one of our most crucial tasks is... protection.  We are the shield of the Horde, and we keep our weaker brethren safe.  If you are to join in our ranks, then you must prove your mettle to me.\n\nGo to Thunder Ridge in Durotar, where live the lightning hides and thunder lizards.  Hunt the beasts!  Show me you are tougher than they!  Brave their assaults and bring me a stack of their singed scales as proof.\n\nDo this, and then I will teach you.", progress = "Do you have the scales, <name>?  Unless you can withstand the attacks of the thunder lizards, you will not benefit from my instruction.", completion = "Ah.  I see you have defeated the thunder lizards, which proves you are tough.  Now I will show you how tough skin and shrewd movements can combine to form an impenetrable wall of defense.\n\nLearn your lesson well, &lt;name&gt;.  And be ready for future instruction.", rewards = "The following spell will be cast on you:\n\nPath of Defense\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1499] = {title = "Vile Familiars", objective = "Speak with Zureetha Fargaze.", description = "Zureetha has been sending novices like yourself to help cull the numbers of the creatures in the cave near where you fought the vile familiars.\n\nI think it would be good for you to gain experience by assisting her. Be sure to tell her that you assisted with the imp problem, she'll probably have a reward for you.", progress = nil, completion = "You have done well, &lt;name&gt;.\n\nAlthough the vile familiars were merely pets of the darker powers within the Burning Blade, your success against them foretells greater deeds ahead.", rewards = "You will be able to choose one of these rewards:\n\nPrimitive Hand BladePrimitive Walking Stick\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1500] = {title = "Waking Naralex", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][1501] = {title = "Creature of the Void", objective = "Retrieve the Tablet of Verga for Gan'rul Bloodeye in Orgrimmar.", description = "So few warlocks remain... We risk much, but the risks are warranted. You must quickly reach maturity in your ability if you are to be of use to the Horde and to the Warchief.\n\nIt is time that you learned a new summoning spell.\n\nFirst, you must recover the Tablet of Verga, which was stolen by warlocks of the Burning Blade and is now kept at their lair in Skull Rock to the east of the city. With the tablet, I will show you the runes necessary to summoning a voidwalker.", progress = "Do you have the Tablet of Verga, <name>? If not, I do not wish to speak with you until you do.", completion = "Good. I hope you inflicted some other losses on the Burning Blade when you went to retrieve this.\n\nThey have been a source of great annoyance for the Warchief, and a great blight upon warlocks as a whole.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1502] = {title = "Thun'grim Firegaze", objective = "Speak with Thun'grim Firegaze in the Barrens.", description = "It is vital that a warrior's weapon is one of quality.  And if there is an orc who can craft quality weapons, then that orc is Thun'grim Firegaze.  He is a hermit who dwells atop the hills east of the Crossroads.\n\nIf you seek a weapon, warrior, then you should seek Thun'grim.  To find him, first travel to the Crossroads to the west, then strike east into the hills.  His camp is high on a hilltop.", progress = nil, completion = "My eyes have long dried out from staring into the forge's flame,  but some things I can still see.  I can see you want something.\n\nAnd if you found your way here, then I can guess what you desire.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1503] = {title = "Forged Steel", objective = "Bring the Forged Steel Bars to Thun'grim Firegaze in the Barrens.", description = "I will give you a weapon, <name>, but first you must aid me.  The Razormanes to the northwest came into my camp a few nights past.  They would not meet me in combat, but they know my eyes are bad--a few distracted me with snorts while others stole from me!  The cowards!\n\nThey took an iron chest, and within it were some forged steel bars.  If you can recover them then I will give you the weapon you seek.\n\nSearch for the iron box within the quilboar camps, and return with the forged steel bars.", progress = "Do you have my steel bars?", completion = "You found them!  And all the bars are here, which doesn't surprise me.  I didn't think the Razormanes would know what to do with fine steel like this.\n\nThank you, &lt;name&gt;.  Here is your reward.  May it serve you well.", rewards = "You will be able to choose one of these rewards:\n\nThun'grim's AxeThun'grim's MaceThun'grim's DaggerThun'grim's Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1504] = {title = "The Binding", objective = "Using the Glyphs of Summoning, summon and subdue a voidwalker, then return the Glyphs of Summoning to Gan'rul Bloodeye in Orgrimmar.", description = "Now, observe the Tablet of Verga, for it contains the glyphs you will need for the summoning. Take them to the circle in Neeru Fireblade's tent on the other side of the cavern. There you will be able to call for the voidwalker.\n\nYou must defeat it using whatever physical and magical means you have at your disposal. When this is completed, return to me with the glyphs of summoning and I will demonstrate how you may bind the creature to your will.", progress = "The voidwalker is a powerful creature. I remember when it was I that was in your shoes, <name>. Over the years, my own voidwalker has grown to fight me less, though I suspect that is only because it hopes I will let my guard down.\n\nRemember that, <name>.", completion = "You have done well, &lt;name&gt;. I will show you how to summon the voidwalker similar to the one you just defeated.\n\nYou should know that we have high expectations for you, and you have, so far, matched them.\n\nDo not let it go to your head, however, as the tasks that still lie before you will make this seem as simple as waking in the morning.", rewards = "You will learn:\n\nSummon Voidwalker\n\nThe following spell will be cast on you:\n\nTeach Summon Voidwalker\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1505] = {title = "Veteran Uzzek", objective = "Speak with Uzzek at Far Watch Post.", description = "The Horde honors its warriors because their strength is unquestioned.  But the truly great warriors are great students as well.\n\nSeek out Uzzek.  He is a veteran of many battles and now instructs young warriors in the ways of combat.  You will find him south of Far Watch Post, the orc garrison on the border of the Barrens and Durotar.", progress = nil, completion = "Hello, young one.  Here for some instruction, are you?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1506] = {title = "Gan'rul's Summons", objective = "Speak with Gan'rul Bloodeye in Orgrimmar.", description = "You there. <name>, right?\n\nI hope your schedule isn't busy, because Gan'rul wants to see you right away. You'll find him with the senior warlocks in the Cleft of Shadow.\n\nBased on my past dealings with Gan'rul, your summons is either a very good thing or a very bad thing.", progress = nil, completion = "Good. I was afraid Ophek wouldn't reach you.\n\nIt is time that I further your &lt;class&gt; training. Any business you have currently will have to wait.\n\nI trust there will not be a problem with this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1507] = {title = "Devourer of Souls", objective = "Speak with Cazul in the Cleft of Shadow.", description = "The time has come for you to learn more of the summoning magics. You will learn to summon a sayaad, a creature of incredible mental powers. It can lull those of weak minds into its servitude--but have no fear! I feel certain that you will be equal to the challenge.\n\nA sayaad can only be summoned when baited with an item that represents great devotion and love. I leave it to you to find such an object.\n\nA suggestion? Speak with Cazul... There seems to be little the ancient warlock does not know.", progress = nil, completion = "Hm... &lt;name&gt;. You are still new to your path, but I sense the possibility for greatness in you.\n\nYou were born with gifts, &lt;name&gt;. See that they do not go to waste.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1508] = {title = "Blind Cazul", objective = "Speak with Zankaja in Orgrimmar.", description = "If Gan'rul has sent you to me, it must be that you are to summon a succubus, a female of the sayaad race, and need an object to use for enticement.\n\nHmm... If you trust a blind man to lead you, <name>, then listen. In the bluffs of Orgrimmar, west of the wind rider tower, lives Zankaja. She waits for the return of her mate.\n\nGo to her.", progress = nil, completion = "Have you come with news of Dogran? He was to have returned days ago, and I have heard nothing...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1509] = {title = "News of Dogran", objective = "Speak with Gazrog at the Crossroads.", description = "My mate, Dogran, was recently sent to the Crossroads for duty. It was a promotion, and he was very proud.\n\nI was sad, of course, but I didn't let him know that. And worried, too. The Barrens is a more dangerous place than Orgrimmar, and I feared the worst.\n\nNow it's been a week after he should have returned, and I have received no word from him...\n\nPerhaps you could go to the Crossroads and see if they have any news? He worked with Gazrog, who should still be stationed there.", progress = nil, completion = "Zankaja? That's Dogran's mate, right?\n\nYeah, I've heard from him, but it's not the sort of news we should let get back to her...\n\nNo, he's not dead. But he is injured and a prisoner of the quilboar.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1510] = {title = "News of Dogran", objective = "Speak with Ken'zigla at the Malaka'jin.", description = "He was stationed at Camp Taurajo, where we've been trying to weed out the quilboar. He led a few grunts to one of their camps, where he was hurt bad. The others made it back and tried to rescue him. He was in bad shape, his wounds festered, so they were afraid to move him without patching him up first.\n\nThey sent a message here, requesting a healing draught from the trolls at the Malaka'jin at the base of the Stonetalon Mountains. We sent someone to get it, but they haven't returned yet.", progress = nil, completion = "Another orc, eh? I hope you haven't come for the other. He didn't make it. Those goblins did him in good.\n\nHe said he needed a healing draught, but not much else.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1511] = {title = "Ken'zigla's Draught", objective = "Bring Ken'zigla's Draught to Grunt Logmar at Camp Taurajo.", description = "I figured there might be another coming to get the draught, so I prepared it anyways.\n\nHere you go, <name>. Mind you, you should only give half of it to him! That will give him enough strength to move without bleeding himself dry. Wait a night, then give him the other half.\n\nAnyways, you'll want to bring this to Logmar at Camp Taurajo. From what the first one told me, he should have an idea where this Dogran is.", progress = "Yes, what is it?", completion = "Well, it's about time! Dogran has been dying out there, waiting for this.\n\nWe need to get this out to him right away, but most of the grunts stationed here are out on a foraging mission.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1512] = {title = "Love's Gift", objective = "Bring the Dirt-caked Pendant to Gan'rul Bloodeye in Orgrimmar.", description = "Zankaja is young and beautiful. To be chained to an invalid... I will not allow her to suffer that injustice.\n\nLeave me, <name>. And thank you. I may end my life in glorious battle, instead of a lifeless husk.\n\nAnd please, I would ask you not to tell my mate of this... I do not want guilt on her conscience.", progress = "You have returned. Are you ready to battle a succubus?", completion = "If you tell me that this will suffice, then I trust you, &lt;name&gt;. Allow me to clean it though... Pristine and shining, it may be even more enticing to a succubus.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1513] = {title = "The Binding", objective = "Using Dogran's Pendant, summon and subdue a succubus, then return Dogran's Pendant to Gan'rul Bloodeye in Orgrimmar.", description = "Take this to the summoning circle in Neeru's tent, <name>. Summon forth a foul succubus, then show it your mastery. I believe in the strength of your magic. As always, though, be wary, for pride and overconfidence has overcome many a promising warlock.\n\nWhen you have defeated it, return the pendant to me so that I might deliver the news to Zankaja.", progress = "When I look upon a succubus, my heart begins to soar... But at the same time, I can almost sense my soul's ebb, drifting away like the tides.\n\nBe wary, my friend.", completion = "Success! Be sure I expected nothing less from my star pupil.\n\nYou have proven your worth, and gladly will I show you the method of summoning your subdued succubus. Go now, you have much to learn, and when next I see you, I will expect you to have found true mastery over your succubus.\n\nLeave the sorrow of Dogran and Zankaja to those of us who are longer in years, but remember it, and hold it as protection against the wiles of the dark power you have learned to summon today.", rewards = "You will learn:\n\nSummon Succubus\n\nThe following spell will be cast on you:\n\nTeach Summon Succubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][1514] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][1515] = {title = "Dogran's Captivity", objective = "Bring Ken'zigla's Draught to Dogran in the Barrens.", description = "You've made it this far, so if you want to see this through to the end, I won't stop you. I can't spare you any additional manpower though, you'll be on your own.\n\nDogran is being held in a quilboar camp to the north of here. Look for a group of two huts. He'll be heavily guarded--that is, if they haven't killed him yet, or he hasn't succumbed to his wounds.\n\nGood luck.", progress = "Urrrghhhh...", completion = "Foul tasting brew...\n\nI can feel the strength in me now, enough to hobble away... But my leg, I will have lost it for the rest of my life. My arm, too.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1516] = {title = "Call of Earth", objective = "Bring 2 Felstalker Hooves to Canaga Earthcaller in the Valley of Trials.", description = "The time is now, young <class>. You've grown strong and your spirit endures like the earth. Following the shaman's path shows you have wisdom before even proving yourself.\n\nThe element of earth will guide your destiny, becoming part of you if you are ready. But you must stand before the earth itself. If you are ready, then you will see things only shaman know of.\n\nSeek out the Felstalkers to the north, and take from them two of their hooves. Return to me then, and we shall speak more of your future.", progress = "Patience is earth's greatest virtue. The earth witnesses the cycle of all things: the mountains becoming deserts; rivers becoming canyons. The earth is the most stubborn and wise of all the elements and it does not tolerate impatience.\n\nThe earth beckons you now because a time of conflict draws near. When you return to me successful, then you shall be that much closer to being made whole.\n\nOthers will be envious of your wisdom and hate you for their ignorance.", completion = "Excellent. Your success shows that you are prepared.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. Earth will protect you, but only if shown the proper respect. Like the other elements, even earth can be fickle. Earth is the basis for life, and by observing its laws, you will gain greater wisdom. Never forget the secrets earth shares with you.\n\nI shall make a sapta for you now, and by accepting it, you will realize your path.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1517] = {title = "Call of Earth", objective = "Find Spirit Rock and drink the Earth Sapta.\n\nProvided item: \n", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the strong willed to see the elements as no one else can. Your spirit will be connected to the element the sapta was created for, and only a select few shaman know the recipe.\n\nThe sapta is always drunk in a holy place, and never anywhere else--remember that.\n\nSeek out Spirit Rock southwest of here--it is found at the end of the Hidden Path. Drink your sapta there, and... well, you shall see.", progress = nil, completion = "Ah... &lt;name&gt;... pleased is the earth to have you here.\n\nBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.\n\nStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1518] = {title = "Call of Earth", objective = "Bring the Rough Quartz to Canaga Earthcaller in the Valley of Trials.", description = "Take this rough quartz from me and bring it to Canaga Earthcaller as proof of our meeting. He will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast many others.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.", progress = "I wish to be the first to welcome you fully to the first of four paths that will forever lead you in your destiny.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised.\n\nIf not, then be gone with you until you have found your way.", completion = "Excellent!\n\nThe totem I will craft for you is more than a symbol of your status among &lt;class&gt;--it has abilities beyond that. One use of the totem is as a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you.\n\nThe trainers will know when you are ready for greater knowledge.\n\nBut for now, take this earth totem...", rewards = "You will learn:\n\nStoneskin Totem\n\nThe following spell will be cast on you:\n\nStoneskin Totem\n\nYou will also receive:\n\nEarth Totem"}
MultiLanguageQuestData['en'][1519] = {title = "Call of Earth", objective = "Bring 2 applications of Ritual Salve to Seer Ravenfeather in Camp Narache.", description = "The time has come, young <class>. Your body ages and grows strong, and your spirit endures like the earth. I see it within you-you have wisdom already.\n\nThe earth guides our people, and it speaks to us, as it will to you in time. But you must be tested. If you are ready, then you shall see things only our kind know of.\n\nSeek out the Bristleback shamans in their ravine to the east, and take from them a salve they use in their rituals. Return to me only when you have enough for your own potion.", progress = "The earth is patient, and will wait for you until you are ready because she knows in time all things erode and are reborn. It is the cycle of things. Mountains become deserts. Rivers become canyons. The earth is the most stubborn and wise of all the elements.\n\nYou must learn patience and stamina above all things. The earth calls for you now because she feels you are ready. Consider this your rebirth if you succeed. You will never be able to go back to ignorance afterwards.", completion = "Good, &lt;name&gt;. Your return here signifies that you are indeed prepared for the next step.\n\nOf all the elements, earth represents the foundation of all things. It is your strength, your stamina, and your patience. The Earth Mother will protect you, but only if you show her proper respect. She is the basis for life, and by observing her laws, you will gain a greater wisdom. Never forget the secrets she shares with you.\n\nI shall make your sapta for you now, and by accepting it, a new path will open before you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1520] = {title = "Call of Earth", objective = "Find Kodo Rock and drink the Earth Sapta.\n\nProvided item: \n", description = "A sapta is a drink created to bind our spirits to the elements. Fused with magic, the potion will allow the open minded to see the elements as no one has seen them before. Your spirit will forever be tied to the element the sapta was created for, and only a select few of our kind know the secrets of its creation.\n\nThe sapta is always imbibed in a holy place, and never anywhere else.\n\nSeek out the shaman shrine to the east of here and drink of the sapta.", progress = nil, completion = "Ah... &lt;name&gt;... pleased is the earth to have you here.\n\nBound together in body and spirit, you will go forward knowing that the mountains are your strength; the plains, your patience; and the world itself your essence.\n\nStanding before the earth humbly is all that is required of you for you to pass this rite. But the others are not as passive. They may be chaotic and often violent, but such is the nature of the elements. Dual natures opposing one another, you must come to learn these things intricately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1521] = {title = "Call of Earth", objective = "Bring the Rough Quartz to Seer Ravenfeather in Camp Narache.", description = "Take this rough quartz from me and bring it to Seer Ravenfeather as proof of our meeting. She will craft a totem for you, and this pebble will be the heart of it. As small as it may seem, you will come to find that size does not matter, and that even the smallest of things can outlast mountains.\n\nBe patient, <name>. Remain strong. And seek wisdom. This is what earth asks of you. In the end, you shall become one with the earth--respect it as it shall respect you.", progress = "Greetings, <name>. You would not return to me if you had not accomplished your task. May I be the first to welcome you fully to the first path of four that will forever rule your travels.\n\nIf you have the stone the earth gave to you, I will give you the totem it promised. If not, then I pity you. There is much pride to be had when you've fully dedicated yourself to the elements.", completion = "Splendid.\n\nThe totem I will craft for you is more than a symbol--it has abilities beyond that. One use of the totem is a focus for spells. Those spells are tied to the earth, and as you earn greater and greater wisdom, more of the earth's abilities will be made accessible to you. Trainers found throughout Kalimdor will know when you are ready for greater knowledge and will let you know as much when you visit them.\n\nBut for now, take this earth totem...", rewards = "You will learn:\n\nStoneskin Totem\n\nThe following spell will be cast on you:\n\nStoneskin Totem\n\nYou will also receive:\n\nEarth Totem"}
MultiLanguageQuestData['en'][1522] = {title = "Call of Fire", objective = "Find Kranal Fiss in the Barrens.", description = "Fire be witcha, mon. I see you be strong in da ways of earth already, an' me tinkin' you be ready to talk to Kranal.\n\nKranal live north of da Crossroads in da Barrens. He be strong in da ways of da elements and can teach ya da ways of fire... if you tink you be ready.\n\nHe be easy ta find, just don' go too far--ya go too far an' ya find yerself in da elves' lands.", progress = nil, completion = "Hmmm, Searn sent you to me, did he?\n\nWell then, Searn could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, &lt;name&gt;. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1523] = {title = "Call of Fire", objective = "Find Kranal Fiss in the Barrens.", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", progress = nil, completion = "Hmmm, Xanis sent you to me, did he?\n\nWell then, Xanis could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, &lt;name&gt;. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1524] = {title = "Call of Fire", objective = "Bring the Torch of the Dormant Flame to Telf Joolam in Durotar.", description = "You are powerful enough to wield the totem of fire, but that does not mean you are ready.\n\nAlong the Southfury River in Durotar, before the Great Sea, lies a hidden trail to one of the highest peaks in the land. Find your way to the top and you shall find one of our holy shrines watched over by Telf Joolam--the Shrine of the Dormant Flame.\n\nTake this torch to him--it marks that you attempt to tame fire. Return it to me aflame by the brazier at the shrine and I will see you are given the totem of fire.", progress = "Greetin's, <name>. You've found yourself at the Shrine of the Dormant Flame. Only those knowledgeable enough in the shamanistic arts will ever learn the secrets of this place and the power it holds. I'm sorry you made the trip all this way, only to be turned back now--the journey up here is far from safe after all--but I am the keeper of the shrine, and I cannot allow just anyone to wander around here.", completion = "Ah, my mistake, &lt;name&gt;. I apologize. I did not realize you possessed the Torch. I am pleased to make your acquaintance.\n\nMany adventurers find their way here while looking for lost treasure or the promise of mystical creatures to slay, only to be turned away from a seemingly empty shrine. But we know the truth, do we not, &lt;name&gt;?\n\nThis shrine holds a greater secret from the mundane members of the Horde. To us, it is sacred.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1525] = {title = "Call of Fire", objective = "Bring 1 Fire Tar and 1 Reagent Pouch to Telf Joolam in Durotar.", description = "But you did not come here for a history lesson, did you? You came for the Eternal Flame and fire totem.\n\nThe first step is to create a sapta and bind you to the flame.\n\nI can create the fire sapta for you if you bring me two items. The first is fire tar, a simple item usually carried by Razormane spellcasters in eastern Barrens.\n\nThe second item will be more dangerous: a reagent pouch from one of the cultists of the Burning Blade. You can find them in a cave above the ravines northeast of Razor Hill.", progress = "I have enough ingredients for a sapta of fire if you can find the reagent pouch and some fire tar. The Burning Blade fanatics carry the proper components for most of their spells in those pouches, and usually have enough of the items I need that we will not have to search much farther for anything else.\n\nThe saptas are always made from ingredients that are closely tied to their respective elements. It makes our work easier because of the warlocks' ties to fire.", completion = "These will do nicely, &lt;name&gt;.\n\nFire is more than chaos and destruction--do well to remember that. It is also about life, and creation. All things are tied together in such a way. Forces oppose one another, but at the same time, one cannot exist without the other. Both extinguish one another, but also give one another meaning. Always remember this.\n\nUsing different types of magic in conjunction with one another will show not only true skill, but great wisdom.", rewards = "You will receive:\n\nFire Sapta"}
MultiLanguageQuestData['en'][1526] = {title = "Call of Fire", objective = "Defeat the Minor Manifestation of Fire, and place the Glowing Ember in the brazier atop the Shrine of Eternal Flame.", description = "The fire sapta is finished. The time has come for you to face the flame. Use the sapta at the shrine and head to the top of the mountain to face the manifestation there. He will not attack until you are ready, but he will realize you are able to see him.\n\nStrike him down swiftly, <name>, for he shall only grow in power the longer you take to slay him. Once he is defeated, place his glowing embers within the brazier and light the torch.", progress = "The brazier stands about a third your height, and looks normal, save for the inscriptions along its smooth metal rails. The metal shows no signs of wear from the weather, and the bowl seated at the top of it feels cool to the touch.", completion = "A white hot flame ignites within the bowl as you place the ember within. You can feel the magical effects of the sapta coursing through your body and the fire dances rhythmically before you.\n\nYou place the top of the torch within the basin, and it immediately catches on fire.", rewards = "You will receive:\n\nTorch of the Eternal Flame"}
MultiLanguageQuestData['en'][1527] = {title = "Call of Fire", objective = "Bring the Torch of Eternal Flame to Kranal Fiss in the Barrens.", description = "Torch firmly in hand, you turn away from the brazier and look out over Durotar. You feel an excitement tugging at your spirit as the wind picks up and forces the flame to dance violently.\n\nYou start off down the path back to the Barrens in search of Kranal Fiss.", progress = "Yes, <name>? What do you have there?", completion = "Your spirit burns brighter than any torch I've ever seen, &lt;name&gt;, and for that, you should be proud.\n\nIf you continue down this path, the elements will be yours to command, and our brethren will look to you for guidance and wisdom. Let me be the first to congratulate you and present to you your newest totem.", rewards = "You will learn:\n\nSearing Totem\n\nThe following spell will be cast on you:\n\nSearing Totem\n\nYou will also receive:\n\nFire Totem"}
MultiLanguageQuestData['en'][1528] = {title = "Call of Water", objective = "Find Islen Waterseer in the Barrens.", description = "Water be in ya future, mon. I see you be strong in da ways of fire already, an' me tinkin' you be ready to talk to Islen.\n\nIslen live along the coast of da Barrens. If ya head south along the Southfury River, ya canna miss her--look fer da big shark! She be strong in da ways of da elements and can teach ya da ways of water... if you tink you be ready.\n\nShe be easy ta find, just don' go too far south--she be jus' beyond Ratchet.", progress = nil, completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1529] = {title = "Call of Water", objective = "Find Islen Waterseer in the Barrens.", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.", progress = nil, completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1530] = {title = "Call of Water", objective = "Find Brine in Southern Barrens.", description = "If there is one lesson you must learn of water, it is this: water means rebirth.\n\nIts power flows, erodes, and makes clean all manner of things. You will find its ability to heal and replenish incomparable, but only when it is pure.\n\nWhen you understand that water, when polluted, can devastate all that it touches, you will appreciate how vital a resource it is.\n\nIf you wish the water sapta, find Brine deep in Southern Barrens. Her home is continually molested by the quilboar there.", progress = nil, completion = "Yes?\n\nMmm, I have a feeling I know what you're going to ask me: what would possess someone to live out here in the deepest part of the Barrens, the threat of quilboar all around, and no protection? Well, we all have our reasons to justify why we act the way we do. The real question is, what brings a lowly &lt;race&gt; to the deepest reaches of the Barrens to speak to a woman who obviously has no concern for her own well-being?\n\nI'm willing to bet we both know the answer to that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1531] = {title = "Call of Air", objective = "Find Prate Cloudseer in Thousand Needles.", description = "You be makin' headway now, mon. Your be ready to prove yerself worthy of the air totem, but first, ya must fin' Prate Cloudseer in Thousand Needles. She be willin' ta tell ya how to get yer air totem if ya treat her wit enough respect.\n\nHead south through the Barrens, and after ya reach Thousand Needles, head east. You'll find her hiddin' in a hole wit' her boyfriend--haha, don' tell her I be dissin' her none--she not take it too kindly.", progress = nil, completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.", rewards = "The following spell will be cast on you:\n\nSwift Wind\n\nYou will receive:\n\nAir Totem"}
MultiLanguageQuestData['en'][1532] = {title = "Call of Air", objective = "Find Prate Cloudseer in Thousand Needles.", description = "The winds of Kalimdor rush to meet you and you shall be counted among some of our most powerful <brothers/sisters>. I am proud to see you have come this far and have such a promising future.\n\nThe element of air is a difficult one to control, but I have faith that your skills will overcome any obstacles that are placed in front of you.\n\nHead to the very south of the Barrens, and enter Thousand Needles. It is there, far to the east, that you will find Prate Cloudseer. She will teach you more.", progress = nil, completion = "For the time being, I shall give you what you need to focus your spells and to call upon the spirits of air. Take this totem, and when you are ready, train with me some more.", rewards = "The following spell will be cast on you:\n\nSwift Wind\n\nYou will receive:\n\nAir Totem"}
MultiLanguageQuestData['en'][1534] = {title = "Call of Water", objective = "Fill the Empty Blue Waterskin at the Ruins of Stardust in Ashenvale and return to Brine in the Barrens.", description = "Take this waterskin and head deep into the lush forest the night elves call Ashenvale. It is to the far north of the Barrens.\n\nOnce you've entered the forest, travel west. Along the mountains that separate Stonetalon and Ashenvale, and beyond Lake Mystral, you will find a holy place: the Ruins of Stardust. At the center of the lake you will find a small fountain.\n\nBring me a sample of the fountain's water. It will be the final component you'll need before I send you back to Islen.", progress = "Do you have the water yet, <name>? Tales say the ruins were protected by large creatures of nature that do not care for visitors, but those could be myths to scare off the enemies of the night elves.\n\nRegardless, be careful.", completion = "Wonderful, &lt;name&gt;. With all three samples gathered, I can create for you a vial of the purest water any living creature will find. It will be used in the next steps of your rite of passage.\n\nI am pleased to count you among our kind, &lt;name&gt;. You do all &lt;class&gt; proud, and I look forward to hearing about your exploits in the future.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1535] = {title = "Call of Water", objective = "Fill the Empty Brown Waterskin at the watering hole below Brine's hut and return it to her in the Barrens.", description = "To find understanding and gain the sapta from me, you must seek out only the purest forms of water. As you fetch the samples for me, take note of your surroundings. Be aware of the creatures that rely on the water, that protect it. See how it affects forests and deserts. Witness how the very substance that sustains life will force creatures to take lives.\n\nWe shall start with a simple task: down below my hut there is a pond of the precious liquid. Fill this skin with it and return to me.", progress = "I am just about prepared to send you on your other tasks. Have you filled the skin yet?\n\nI know how protective the quilboar can be. Even such a small water source is a vast hoard of wealth to them. They have great feasts when even the slightest rain comes to the Barrens. Water is sacred to their kind because it is so scarce. Do you understand?", completion = "I thought some bloodshed might ensue if you tried to take water from the pool. It is a pity the quilboar do not realize that all living things are tied together; that their greed only perpetuates the pain and suffering of their people. How much could they accomplish if they were to put their differences aside and their clans came together.\n\nAgain, a pity, but more than likely a boon for the other races of the Barrens.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1536] = {title = "Call of Water", objective = "Fill the Empty Red Waterskin at the well in Tarren Mill and return to Brine in the Barrens.", description = "Long ago I followed some companions into the Hillsbrad Foothills. We defended ourselves from some tenacious humans who make their home there and we found ourselves in a small town the Forsaken had taken over: Tarren Mill.\n\nIt was there I found a most peculiar thing: in the center of town was a small well of fresh spring water. I'm not sure the plagued citizens of the town even realize its value--it's a small holy vestige in an unhallowed sea.\n\nBring me a sample of that water in this waterskin.", progress = "The well remaining pure within the town reminds me of stories told to me when I was younger, <name>. Even in times of great pain and sorrow one can find a sliver of hope, a small symbol to rally around. The orc people see Thrall this way. He survived against great odds and rose up to lead our people through his strength and example.\n\nI'm not sure any orc has suffered as much as he has, but at the same time, I'm not sure any orc is as strong as he is either.", completion = "This is good, &lt;name&gt;. You're dedicated to the task at hand and have the ability to seek out that which is needed.\n\nOne more sample is all I need to create the reagent needed for your sapta. Islen will be pleased as well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1558] = {title = "The Stonewrought Dam", objective = "Take the orphan to the Stonewrought Dam in Loch Modan. You should take him to the middle of the dam so he can see out over the giant waterfall.", description = "Ironforge is where all the dwarves and gnomes live.  Near there is a place called Loch Modan, and the dwarves built a HUGE dam there.  They say it's one of the biggest things anyone's ever made.  Wow!\n\nCould you take me to Loch Modan and see the dam there, please?  I think it is the Stone... um... Stonewrench Dam?  Stonewrought?  It's big - that's for sure.  I'd like to look out over the big waterfall.  I promise I won't lean over too far!", progress = "Are we there yet?", completion = "WOW - the dam was WAY bigger than I thought!  I could barely hear myself talk from the sound of all the rushing water!  Hey, do you think it would ever run out of water?  Man, what would happen if that dam ever broke!  WOW, that would be scary!\n\nThanks for taking me to see the dam.  That was very kind of you.  I told you I wouldn't lean over too far!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1559] = {title = "Flash Bomb Recipe", objective = "So you're an engineer, eh?  Well, for your help in getting me those pearls, here's the recipe for flash bombs.\n\nGood luck, and try not to blind yourself!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSchematic: Flash Bomb"}
MultiLanguageQuestData['en'][1560] = {title = "Tooga's Quest", objective = "Show Tooga the way back to his wife, Torta.", description = "I am so lost!\n\nMy wife, Torta, sent me out to fetch dinner and I must have taken a wrong turn somewhere.\n\nWould you be so kind as to lead me back to Torta? She's waiting for me just south of Steamwheedle Port.", progress = "Where is Tooga?", completion = "So he couldn't find his way back on his own? Figures.\n\nWell, I guess you deserve something for your troubles....", rewards = "You will be able to choose one of these rewards:\n\nChelonian CuffsBand of the Great Tortoise\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1578] = {title = "Supplying the Front", objective = "Bring 6 Copper Axes and 6 Copper Chain Belts to Thorvald in the southern guard tower of Loch Modan.", description = "The mountaineers of Loch Modan are fighting troggs, and having a busy time of it!  They need constant supplies of new armor and weapons if we're ever to get a handle on those troggs.\n\nThat's why my colleague Thorvald is there, trying to keep the mountaineers in good gear.  So if you were to make some copper axes and copper chain belts and bring them to Thorvald, he would be obliged.  He might even share his knowledge with you.\n\nThorvald is in Loch Modan's southern guard tower.", progress = "I have no time to chat.  Do you have business with me?", completion = "Ah, apologies!  I didn't realize you were here to help resupply our troops.  The stuff you made will be a big help!\n\nHere are plans for some armor.  I hope you find them useful.", rewards = "You will receive:\n\nPlans: Heavy Copper Longsword"}
MultiLanguageQuestData['en'][1579] = {title = "Gaffer Jacks", objective = "Bring 8 Gaffer Jacks to Wizbang Cranktoggle in Auberdine.", description = "I came to Auberdine because of the quiet.  I want to invent my inventions where it's quiet, because after a night of drinking I don't like all the noise of Ironforge!\n\nSo I took a ship to Auberdine and had a little too much to drink on the way.  I dropped my box of gaffer jacks overboard!  I need my gaffer jacks!\n\nI don't know exactly where I dropped them, but if you fish for them in the ocean you might get lucky...", progress = "Did you find my gaffer jacks, <name>?  Without my gaffer jacks I can't tune my stintle pegs!", completion = "I can't believe you found them!  You must be the luckiest &lt;race&gt; in Kalimdor!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1580] = {title = "Electropellers", objective = "Bring 12 Electropellers to Wizbang Cranktoggle in Auberdine.", description = "We know you're lucky, but... just how lucky are you, <name>?\n\nOne night I was wandering the roads of Darkshore.  I was looking for a good river or lake to try my new self-propelled, exploding duck decoy and I think I was a little tipsy... because I passed out and awoke hours later in Auberdine.  My hair was singed and my bag of electropellers was gone!  I must have dropped them in the water!\n\nI need those electropellers!  Maybe you can fish them out of some lake or stream in Darkshore...", progress = "Did you find any electropellers?  I'll need them if I'm to continue my research on duck decoys...", completion = "I can't believe it!  You found them!  You are the best fisherman I've ever seen!\n\nThank you, &lt;name&gt;.  And here, take these.  Although you're so good and you probably don't need them, they will help you with your fishing.", rewards = "You will receive:\n\nAquadynamic Fish Lens"}
MultiLanguageQuestData['en'][1581] = {title = "Elixirs for the Bladeleafs", objective = "Bring 6 Elixirs of Lion's Strength and 2 Elixirs of Minor Defense to Syral Bladeleaf in Dolanaar.", description = "Our herb and alchemy shop is booming, but my husband spends so much time mixing potions that we never have time for each other.\n\nCan you help us?\n\nIf you can bring me a supply of pre-made elixirs, then I would be happy to trade with you.  I have some rare herbs that you might find useful.", progress = "Hello, <name>.  Do you have the elixirs to trade?", completion = "These are nicely mixed.  You take great care in your trade, &lt;name&gt;, and that is important for an alchemist.\n\nHere are your herbs, freshly gathered.  May you use them well.", rewards = "You will receive:\n\nEarthrootMageroyal"}
MultiLanguageQuestData['en'][1582] = {title = "Moonglow Vest", objective = "Bring 1 Embossed Leather Gloves, 5 Embossed Leather Boots and 5 Embossed Leather Cloaks to Lotherias in Darnassus.", description = "We in Darnassus, especially we craftsman, are quite busy.  Young adventurers are eager to test themselves in the wilderness, and are in constant need of supplies.\n\nIf you can help me fill my orders of leather goods, then perhaps I can teach you an advanced leatherworking technique.", progress = "Greetings, <name>.", completion = "Yes, these are good pieces. You have a skilled hand and an eye for detail. Your future as a leatherworker is promising.\n\nHere, &lt;name&gt;. Let me show you the pattern to make the Moonglow Vest.", rewards = "You will receive:\n\nPattern: Moonglow Vest"}
MultiLanguageQuestData['en'][1598] = {title = "The Stolen Tome", objective = "Retrieve the Powers of the Void for Drusilla La Salle.", description = "You there! <name>, right?\n\nI hope you're sure about becoming a warlock, because if you can't hold your own, you're likely to get pulled under.\n\nI'm to teach you, but I need to make sure you're strong enough first.\n\nThere was a novice studying at the Abbey who ran off to join the Defias Brotherhood. Why do I care? Well, he stole some important books.\n\nOne of those happens to be a book I've wanted for myself, the Powers of the Void. Steal it for me, they have it hidden at their tent in the Vineyards.", progress = "It was too conspicuous for me to steal the book myself. What luck one of their own patsies did the dirty work for me.", completion = "Excellent... I was never able to gain access to this text, it was held in a protected wing of the library that would have looked suspicious for me to be loitering around.\n\nWell, you did a good job in getting this, and I'm convinced that you can probably handle your own imp, so there's no reason for me not to show you how to summon one.", rewards = "You will learn:\n\nSummon Imp\n\nThe following spell will be cast on you:\n\nTeach Summon Imp\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1599] = {title = "Beginnings", objective = "Bring 3 Feather Charms to Alamar Grimm in Anvilmar.", description = "You must be the new warlock everyone's been whispering about. Must be someone's taken a liking to you if they've asked me to take time away from my research to start your training.\n\nDon't worry, I won't hold it against you.\n\nThe simplest of the summoning spells you will learn is that of the imp. Before I impart this to you, however, you must prove that you have the necessary magical and physical ability.\n\nBring me three feather charms from the frostmane novices from the cave to the southwest.", progress = "Those feather charms the novices carry have some sort of magical power to them. It will be interesting to research them. I wouldn't have expected it from the trolls.", completion = "Very good, very good! You've done well, &lt;name&gt;. Perhaps the interest that is being shown in you is deserved, after all.\n\nThat'll be for the others to decide--assuming your imp doesn't overpower you and nip your career in the bud. For now, I'm satisfied that you'll probably survive your first few months as a &lt;class&gt;.\n\nA word about the imp, &lt;name&gt;. As a &lt;race&gt; knows, don't let its size fool you, its magic can be very dangerous.", rewards = "You will learn:\n\nSummon Imp\n\nThe following spell will be cast on you:\n\nTeach Summon Imp\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1618] = {title = "Gearing Redridge", objective = "Tormus Deepforge  wants you to bring 4 Runed Copper Belts and 4 Heavy Copper Mauls to Verner Osgood in Redridge.", description = "We dwarves aren't the only ones fighting.  Our human allies have their hands full too!\n\nRedridge is under periodic attack from blackrock orcs, and their supply of equipment is always low.  If you were to help them out, I'm sure their resident blacksmith, Verner Osgood, would teach you a trick or two.", progress = "I hope you're here with good news from Ironforge.  Because I'm at my wit's end!", completion = "Thank you, &lt;name&gt;.  This will help me out tremendously.  With the Blackrock orcs attacking from Stonewatch Keep and the Redridge gnolls lurking in the foothills to the north, I'm always fixing armor and making new weapons for our troops.\n\nThe supplies you brought will give me a moment's peace.  I will have enough time to teach you something...", rewards = "You will receive:\n\nPlans: Ironforge Breastplate"}
MultiLanguageQuestData['en'][1638] = {title = "A Warrior's Training", objective = "Speak with Harry Burlguard.", description = "You've shown yourself to be a competent warrior, <name>.  But you're still young and have a lot to learn.\n\nSpeak with Harry Burlguard--he's usually in the Pig and Whistle tavern, in the Old Town of Stormwind.  Harry is an old veteran and a good teacher.  He can show you a few moves that'll keep you breathing longer.", progress = nil, completion = "Oh ho!  Have a drink with me, lad.  You look tough on the outside, but let's see if your gut can handle a few mugs of the Pig and Whistle's strongest!!\n\nOr... were you here for a lesson?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1639] = {title = "Bartleby the Drunk", objective = "Speak with Bartleby.", description = "Yeah, I can teach you.  But first I wanna see what moves you have already.\n\nSee that drunk over there at the end of the bar?  Bartleby?  I want you to get his mug.\n\nHah, and if you know Bartleby then you know he won't just give it to you.", progress = nil, completion = "Hello, fancy boy!  What's a prissy thing like you doing in the Pig and Whistle?  Be careful, or you might break a nail...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1640] = {title = "Beat Bartleby", objective = "Beat Bartleby, then talk to him.", description = "You want what??  You're crazy!\n\nThe only way you'll get this mug is if you pry it from my cold, dead fingers...", progress = "The only way you'll get this mug is if you pry it from my cold, dead fingers...", completion = "You're a lot tougher than you look!", rewards = nil}
MultiLanguageQuestData['en'][1641] = {title = "The Tome of Divinity", objective = "Here in Stormwind, I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTome of Divinity"}
MultiLanguageQuestData['en'][1642] = {title = "The Tome of Divinity", objective = "Speak to Duthorian Rall in Stormwind.", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.", progress = nil, completion = "Hello again, &lt;name&gt;. How goes your studies of the Tome of Divinity?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1643] = {title = "The Tome of Divinity", objective = "Search the Trade District of Stormwind for Stephanie Turner.", description = "Your task then, <name>, is to find someone here in Stormwind that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light.", progress = nil, completion = "Oh, hello, luv. How go your adventures? Oh, I'm so glad to hear you're doing well.\n\nOh, me? Thank you for asking--I'm doing well, all things considered.\n\nThe increase in tradesmen has kind of put a damper on the amount of leather and cloth people are willing to part with these days, so it's been tougher to make clothing for the children at the orphanage, but we'll manage. By \"we\" I mean my husband and I. He's up in Ironforge trying to seek help from the citizens there.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1644] = {title = "The Tome of Divinity", objective = "Bring 10 Linen Cloth to Stephanie Turner in Stormwind.", description = "Bless their hearts, most of them have no families because of the Scourge attacks in the last decade.\n\nMy husband John collects the materials for me to make the shirts and pants for the children, but I haven't even had time to do that. I've been too focused on keeping food on their plates, and a roof over their heads.\n\nWhat's that? You'd be willing to help? Oh, thank the Light, and thank you, <name>.\n\nIf you could bring me some linen cloth so I can sew clothes for the kids, that would help me out so much.", progress = "I hope my John is having better luck in Ironforge. He so dislikes his trips there because it leaves the kids and me alone, but he knows it must be done. He's so kind-hearted.\n\nSome years have been easier than others, but this one's been rougher by far. It's almost as though something in the air is signaling a huge change. Who knows though?", completion = "Thank you, &lt;name&gt;, thank you so much!\n\nThe children will be so pleased, and you've saved me so much time. I'll now be able to focus on the children's other needs, and hopefully my John will be able to return home sooner than we thought.\n\nThank you again, &lt;name&gt;. I knew I could rely on the charity of others. The Light be with you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1645] = {title = "The Tome of Divinity", objective = "A pleasure to meet you, <name>. I am responsible for putting paladins on the path to greater virtue as they devote themselves to the Light and defend Azeroth from the Scourge and other threats.\n\nThe time has come for you to take your first step towards being truly virtuous. If you accept it, I will give you a Book of Divinity. In studying it, you shall learn some about the Light, and what is expected of you. If you understand it, and are capable, then you will succeed in attaining greater abilities.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTome of Divinity"}
MultiLanguageQuestData['en'][1646] = {title = "The Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge.", description = "In all things, a paladin must reflect the Light which supplements our strength. To strive to be divine for one of our kind does not mean we strive for godhood--we strive to be good in all actions.\n\nAlthough called upon to smite evil in these harsh times, you must always remember that it's aiding others that will truly set you apart from the citizens of Azeroth. Compassion, patience, bravery--these things mean as much to a paladin as strength in battle.\n\nKnow this well, and never forget it.", progress = nil, completion = "Welcome back, &lt;name&gt;. You've spent time reading the book, I hope?\n\nThen you should be prepared to have yourself tested. There are always tasks to be done throughout the city and our lands; acts of compassion and understanding; people who need help; creatures to slay.\n\nBy proving you have the patience to help others, especially those who are less fortunate, you prove that you are a servant of the Light and of sound mind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1647] = {title = "The Tome of Divinity", objective = "Search the outer ring of Ironforge for John Turner.", description = "Your task then, <name>, is to find someone here in Ironforge that is in need of aid. Someone who is pure of heart and motive. Perhaps someone helping others. Perhaps someone in need of a guide. Regardless, the person must have noble intent and be relying on your kindness.\n\nDo this, and return to me when you are finished. Then, we shall discuss more of your path and what it means to be a paladin of the Light. I will remain here in the temple for your return. Other paladins will need my guidance also.", progress = nil, completion = "THE ORPHANAGE OF STOR... oh, sorry, didn't mean to shout at you, sir,\n\nMy name is John Turner. How are you?\n\nGood, good, glad to hear things go well for you. I've had a long day of work already, and I miss my wife terribly, but that's the price you have to pay when there are mouths to feed and backs to clothe.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1648] = {title = "The Tome of Divinity", objective = "Bring 10 Linen Cloth to John Turner in Ironforge.", description = "My wife and I run an orphanage in Stormwind, mostly for children who have lost parents due to the attacks by the Scourge in the last decade. I come to Ironforge every month or so to see about collecting more supplies from the citizens here, and talk to the various groups to see if they can do anything to help.\n\nThis trip's been agonizingly slow, and not very productive.\n\nIf I could just get some more linen for my wife to make some clothes, I could finally send a shipment home.", progress = "What with the influx of tradesmen here and throughout Azeroth, there's a smaller supply of items we use to make clothes for the children of our orphanage. Helping me collect linen so my wife can make new clothes for them is very noble of you, <name>. Thank you.\n\nHopefully, I'll be able to return home to my wife soon.", completion = "This is so wonderful of you, &lt;name&gt;. Thank you again.\n\nYou're a noble man for doing this for me. It's no wonder you've chosen to follow the Light. I wish there was some way I could repay you for all you've done... what's that? It's the least you could do? See? That's what I'm talking about, &lt;name&gt;, noble to the end.\n\nBe safe, and may the Light protect you in your travels.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1649] = {title = "The Tome of Valor", objective = "Speak to Duthorian Rall in Stormwind.", description = "Valor, and all the virtues that go along with it, are like rare minerals: you must cherish them when you find them because of their value, but you must also take time to harvest them... refine them. When mixed together properly, a strong alloy is formed, sometimes unbreakable by even the most powerful blows.\n\nThis strength, your faith, your bravery, must be tested. You must learn to never lose faith and realize that with the power of the Light, you can overcome things that most others cannot.", progress = nil, completion = "Ah, you wish to petition me for a test of valor. Splendid.\n\nThere are many tasks throughout the city and surrounding lands that hold much challenge, and they could use a man with your skills.\n\nThis test should not be taken lightly, &lt;name&gt;. This, like many things along our path, could take our lives. The Church always wishes to bolster its ranks, but it understands the sacrifices needed to ensure the paladins serving it are worthy.\n\nAre you prepared?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1650] = {title = "The Tome of Valor", objective = "Find Daphne Stilwell in Westfall.", description = "Good! Your lack of hesitation is a sure sign that you are prepared and eager to test yourself. So be it.\n\nAt the very ends of Westfall's Longshore, a small house overlooks the ocean. There, a couple lives, the Stilwells. Jordan is an incredible smith, and he's gone to Ironforge to meet with the dwarves for a while. But this has left Daphne, his wife, alone and unprotected.\n\nReports suggest that the Defias have all but taken over the area, Daphne may need some protection from the villains. Go there.", progress = nil, completion = "Hello, &lt;name&gt;. I'm assuming by all that armor and weapon of yours, you're either here to try and take my land, or the Church finally sent someone to help protect me while my Jordan's gone.\n\nWell, let me introduce myself: I'm Daphne Stilwell. It's a pleasure.\n\nNow, you're not too late... I've only killed a half dozen of the scum since last sun up. They've been a little slow getting 'round the bend up there, but they probably saw you coming, which means they'll probably be here any minute.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1651] = {title = "The Tome of Valor", objective = "Defend Daphne Stilwell from the Defias attack.\n\nNeither of your spirits must be released from their mortal coils if you wish to succeed.\n\nAfter you are successful, speak to Daphne Stilwell again.", description = "Now, they'll be coming again soon, I'd wager, so get yourself ready.\n\nI've got myself a gun in the house. I'll grab it and be ready to help you out, but for the most part, you're on your own.\n\nI've no idea how many they'll send, but I'm sure it'll be more than the few they sent earlier.\n\nAsk the Light for whatever blessings you can because... did you hear that? I think they're coming.\n\nWe make our stand near the house!", progress = "We'll make our stand at the house!", completion = "We've done it, &lt;name&gt;! Thank you for your help. You were truly amazing out there. I never thought a &lt;class&gt; could handle so many enemies at once.\n\nYou've truly shown bravery in the face of overwhelming odds.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1652] = {title = "The Tome of Valor", objective = "Speak to Duthorian Rall in Stormwind.", description = "Please, return to Duthorian and let him know that I'm safe for now. I have you and the Church to thank for that.\n\nHe'll send word to Ironforge to let my Jordan know that he has nothing to fear.\n\nOh, how I miss my husband. I can't wait till he returns.", progress = nil, completion = "So, we meet again, &lt;name&gt;, and you are in high spirits, I see.\n\nThe Stilwell home will be safe for another day, and from your story I see that there was no shortage of danger to be found. Well done.\n\nDaphne and Jordan have helped the Church greatly, and having you protect their property--and their very lives--was the least we could do for them.\n\nFor your valor, you will be rewarded.", rewards = "You will learn:\n\nSense Undead\n\nThe following spell will be cast on you:\n\nSense Undead\n\nYou will also receive:\n\nBastion of Stormwind"}
MultiLanguageQuestData['en'][1653] = {title = "The Test of Righteousness", objective = "Speak to Jordan Stilwell in Ironforge", description = "Actually, I have no doubt that Jordan himself would like to thank you, and seeing as I need a messenger to send word that his wife is safe, I think you'd be a perfect choice.\n\nJordan was to be a paladin of the Light before his dedication to his father's craft took him on another path--he's intimately familiar with our way of life and is considered among our most faithful.\n\nHe should still be in Ironforge--he likes to work outside the gates during the day, something about the cool mountain air.", progress = nil, completion = "Good day, &lt;name&gt;. The Light is with you, I trust?\n\nWhat's that? You were sent by Duthorian!? My wife, how is she? I knew there was going to be trouble if I left. Please tell me she's... oh, thank goodness. I'm so glad that she's safe. The Defias were a threat long before these attacks, but now the King's advisors cannot deny it.\n\nWhat else did Duthorian have to say?\n\nYou're the one that was sent to protect my wife? Then I thank you again, &lt;name&gt;. I couldn't think of a better test of valor than that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1654] = {title = "The Test of Righteousness", objective = "Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge.", description = "I'd like to reward you if you'd be willing to accept such a thing? Don't misunderstand me, my generosity is dependent on how much help you can be, but I see us both benefiting greatly from such an alliance.\n\nI will craft for you a weapon worthy of what you've accomplished, a symbol of paladinhood and the Light, but you must gather the items I need to craft it. I've already started taking notes on the items, it just requires someone brave and skilled enough to recover them. What do you say, <class>?", progress = "The items you're seeking will be difficult to acquire, but I can assure you, the weapon I will craft for you will be worth the effort.\n\nIt will be my finest work to date, and only a small payment for the service you've done me.", completion = "This is wonderful! You've gotten all the items.\n\nI should have no problem forging you a grand weapon with these. I've actually had the plans for doing this for some time, I just never had the opportunity to gather the goods. Thank you, &lt;name&gt;.\n\nIt feels good to have my father's hammer again... and a Kor gem, I never thought I'd see one of these myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1655] = {title = "Bailor's Ore Shipment", objective = "Bring Jordan's Ore Shipment to Bailor Stonehand in Loch Modan.", description = "Ach, ya startled me, <man/woman>! Can't ya see I was lost in thought?\n\nWhat's that? Jordan's shipment... fer Ironforge. Ahhh, yeah, I know whatcha speak of. Mo'grosh ogres... dat's who took me ol' friend's ore shipment. Caravan was headin' here from the Wetlands and was ambushed. The guard who survived their attack just passed away a few days ago--healer couldn't get to 'em fast enough.\n\nIf you want the shipment, you'll have to head northeast across the Loch. It's got to be there somewhere.", progress = "So, any luck yet? Haha, those ogres didn't get the best of ya yet, did they?", completion = "Yup yup, this is it. Ha! If I'd known you were really gonna head out there and fight some o' them ogres, I woulda given you a list of things to get instead of just this one thing. But, you're not here doin' business for me, are ya?.\n\nA deal's a deal; Jordan wanted a shipment of me alloy, that's what he's gonna get.\n\nTell 'em hello fer me, and be safe, &lt;class&gt;.", rewards = "You will receive:\n\nJordan's Refined Ore Shipment"}
MultiLanguageQuestData['en'][1656] = {title = "A Task Unfinished", objective = "Bring the Bundle of Furs to Innkeeper Kauth in Bloodhoof Village.", description = "<name>, please, I beg of you, can you help me? I have not finished my tasks here on the Mesa--I'm in the middle of my Rite of Strength--and my father asked me to deliver these furs to the inn in Bloodhoof.\n\nI'm far from rested enough to complete both my rite and this task for my father. Would you mind going on for me?\n\nThe inn is pleasant and a perfect place to rest during your long travels. I'm sure you'll agree once you see it.", progress = "Yes, young one? What can Kauth do for you?\n\nThe journey here from the Mesa can be a tremendous burden for some, but a welcome sight for others. Which is it for you, I wonder?", completion = "Ah, the furs I was expecting. Thank you.\n\nThese came faster than I had expected. They will make good blankets for anyone who wishes to stay here.\n\nPlease feel free to stay as long as you like. My inn is always open and all of our people are welcome here. And don't underestimate a good night's rest, it can make a great difference while you're out traveling.", rewards = "You will be able to choose one of these rewards:\n\nTough Hunk of BreadRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1657] = {title = "Stinking Up Southshore", objective = "Toss three Forsaken Stink Bombs into the heart of Southshore in Hillsbrad, and return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", description = "Celebrate Hallow's End in style... by bringing grief to our enemies in Southshore!\n\nTake one of these specially crafted stink bombs.  It is filled with an odiferous funk that no human - or any weak-willed beast for that matter - can stand to smell.  You'll need to throw it right in the heart of Southshore for it to do its job, so be prepared for a fight against the Alliance!\n\nWhen you've completed this task... this tribute to our liberation, return to me!", progress = nil, completion = "Ah, well done!  I hope the Alliance chokes on the foul gift we've given them, much like we were forced to choke on the yoke of enslavement to the Scourge!\n\nYou've kept the ideas of Hallow's End true, &lt;name&gt;, and for that I salute you.  As an extra bonus, let me share some of these Hallow's End treats I have with you.  I think you might find them to be quite the enjoyable diversion!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][1658] = {title = "Crashing the Wickerman Festival", objective = "Locate the Forsaken's Wickerman Festival in Tirisfal Glades. Return to Sergeant Hartman in Southshore once you've done so.", description = "I need brave individuals to head up to Tirisfal Glades and check out the Wickerman Festival.  I'm not going to lie - heading up there will be dangerous.  The guards at the festival will be exceptionally vicious.  Still, we need to know how big the festival is this year, and how much trouble the Forsaken are going to cause us during Hallow's End.\n\nIf you're up for it, head to Tirisfal and scout out the festival.  Return to me with the information, and I'll make sure you're well compensated.", progress = "Have you gone up to Tirisfal Glade and checked things out?  They usually hold the festival close to the Undercity...", completion = "Well done, &lt;name&gt;.  The Wickerman Festival will continue to be trouble so long as the abominable Forsaken are allowed to haunt the remnants of Lordaeron.  It is NOT a fitting tribute to that once proud kingdom, let me tell you...\n\nHere's some coin for any repairs you might need, and in the spirit of the season I've also included some treats you might like.  Happy Hallow's End - let's keep it as safe as possible here in Southshore.", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][1661] = {title = "The Tome of Nobility", objective = "Speak to Duthorian Rall in Stormwind.", description = "I greet you once again, <name>. I am more proud to call you <brother/sister> than ever before--your dedication is a tribute to us all.\n\nThe time has come for me to bestow a great gift upon you. But know this, for now I give you this freely, but later, when time permits, this will be a much greater challenge to all paladins who choose to undertake my quest.\n\nSpeak to me again and I shall grant you a great boon.", progress = nil, completion = "Congratulations, and may the Light protect you.", rewards = "You will learn:\n\nSummon Warhorse\n\nThe following spell will be cast on you:\n\nSummon Warhorse"}
MultiLanguageQuestData['en'][1665] = {title = "Bartleby's Mug", objective = "Bring Bartleby's Mug to Burlguard", description = "Ok, here's my mug.  Wait!  Let me finish what's in it first... there we go.", progress = "I saw your fight with Bartleby.  Nicely done!  Did you get his mug?", completion = "There it is!  He sure didn't want to part with it, but you were persuasive.  Well done.\n\nNow for your lesson...", rewards = "The following spell will be cast on you:\n\nPath of Defense\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1666] = {title = "Marshal Haggard", objective = "Speak with Marshal Haggard.", description = "You've learned a few moves, but you could still use a decent weapon.  I bet if you spoke with Marshal Haggard he could help you.\n\nMarshal Haggard lives in a manor in Elwynn Forest, at the Eastvale Lumber Camp.  He's retired now but he collected a lot of gear during his career.\n\nLet him know I sent you, and with luck he'll have a spare weapon to offer.", progress = nil, completion = "Who's that?  Burlguard, is that you?  You'll have to step a little closer.  My eyes aren't what they used to be.  Walking up like that, I thought you were a gnoll!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1667] = {title = "Dead-tooth Jack", objective = "Retrieve Haggard's Badge from Dead-tooth Jack's camp, and return to Marshal Haggard.", description = "Burlguard sent you, did he?  Yes, I have spare weapons around here, but first I have a task for you...\n\nA while ago a Defias villain Dead-tooth Jack tricked me.  It was dark and he was wearing a Stormwind tabard and I thought he was Marshal Dughan.  He said he needed my old Stormwind Marshal's badge and I gave it to him... and then he laughed and ran off before I could catch him!\n\nGet back my badge!  Dead-tooth Jack probably has it stowed in his camp to the south.", progress = "Do you have my badge? I don't want to think of the mischief Dead-tooth Jack could cause with it.", completion = "Great, you found it!  I feared it was gone forever, used by the Defias to impersonate a Stormwind official.  Well that won't happen now, thanks to you.\n\nHere are some weapons I used when I was a Marshal.  I kept them in great shape--take your pick!", rewards = "You will be able to choose one of these rewards:\n\nHaggard's AxeHaggard's HammerHaggard's DaggerHaggard's Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1678] = {title = "Vejrek", objective = "Bring Vejrek's Head to Muren Stormpike in Ironforge.", description = "If you want to rise in the ranks of the warriors, then you better be tough.  I can teach you new moves but before that, prove to me you can handle yourself against real foes.\n\nVejrek is the toughest troll you'll find in these parts, and he's who you have to beat.  He has a hut in the foothills just south of Frostmane Hold\n\nBring me Vejrek's head and I'll know you have mettle.", progress = "Have you been to Vejrek's hut, <name>?  Is that troll stink I smell on you?", completion = "Vejrek sure was an ugly one, eh?  Nicely done, &lt;name&gt;!  You have what it takes, now let's start your lesson...\n\nYou may not know it, but a strong defense is very important to a &lt;class&gt;.  It keeps him standing against foes that'd fell others, and that's what your allies need.", rewards = "The following spell will be cast on you:\n\nPath of Defense\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1679] = {title = "Muren Stormpike", objective = "Speak with Muren Stormpike.", description = "Hello, warrior!  You show a lot of promise, but you still need to learn some tricks and Muren Stormpike is just the dwarf to teach you.\n\nYou can find Muren at the Hall of Arms in the Military Ward of Ironforge.  Talk to him when you're ready to learn what it is to be a warrior.", progress = nil, completion = "Ah, &lt;name&gt;.  I heard the warriors of Dun Morogh bouncing your name around.  I hope you haven't spent all your time in the breweries!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1680] = {title = "Tormus Deepforge", objective = "Speak with Tormus Deepforge.", description = "Now that you've learned some moves, it's time to get you a decent weapon.  Speak with Tormus Deepforge.  He can make you a weapon I'm sure you'll like.\n\nYou'll find Tormus here in Ironforge, at the Great Forge.", progress = nil, completion = "Muren sent you, did he?  Yes, I can make you a nice weapon... but before I do that, I have a favor to ask of you.\n\nDon't worry.  It's plenty dangerous and could mean your death; it's exactly the sort of job a &lt;class&gt; wants.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1681] = {title = "Ironband's Compound", objective = "Bring a load of Umbral Ore to Tormus Deepforge in Ironforge.", description = "My mentor, Sturgy Ironband, had a compound south of Helm's Bed Lake in eastern Dun Morogh.  There he taught blacksmithing and he was the best.\n\nBut one day, one of his students brought him a load of strange ore.  Master Ironband called it umbral ore and was eager to work with it, but soon after it arrived... a band of Dark Iron dwarves attacked his compound.  They killed everyone!\n\nEnter Ironband's compound, <name>, and avenge my master's death.  And bring me the load of umbral ore that caused it.", progress = "Have you entered Ironband's Compound?  Did you find the umbral ore?", completion = "You found it! Well done!\n\nI hope you killed a host of Dark Iron dwarves while searching.  I fear that Ironband's compound won't be the last place we see them.\n\nBut thank you for the ore, &lt;name&gt;.  I'm eager to work it and find its properties.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1682] = {title = "Grey Iron Weapons", objective = "Here are some weapons, hot off the anvil and made with the new umbral ore you brought me!\n\nPlease, <name>, take your pick!", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nUmbral AxeUmbral MaceUmbral DaggerUmbral Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1683] = {title = "Vorlus Vilehoof", objective = "Bring the Horn of Vorlus to Elanaria in Darnassus.", description = "Before I can teach you, you must show me your resolve.\n\nThe satyr Vorlus Vilehoof has found one of our remote moonwells, southeast of the Ban'ethil Barrow Den.  He now splashes within it, defiling its pure waters with his filth.\n\nFind Vorlus at the moonwell and destroy him.  Bring me his horn as proof and I will begin your advanced training as a warrior.\n\nThe path to the moonwell is hidden well, <name>, but stay focused and alert and you will find it.", progress = "Do you have the horn, <name>?  Is our moonwell free of the fiend Vorlus?", completion = "Well done, &lt;name&gt;.  It is good to know Vorlus is defeated and our moonwell cleansed, and it is good to see young warriors eager to keep our beloved Teldrassil free of corruption.\n\nNow let us begin your training...", rewards = "The following spell will be cast on you:\n\nPath of Defense\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1684] = {title = "Elanaria", objective = "Speak with Elanaria.", description = "Greetings, warrior.  Your skill grows, but there is more to your profession than you may believe.  To further progress, you must soon find a teacher.\n\nThe warrior Elanaria dwells in Darnassus, at the Warrior's Terrace.  She can instruct you.", progress = nil, completion = "I bid you greetings, &lt;name&gt;.  Your name rings loudly in Darnassus, for you show promise.  But we shall soon see if you possess the strength of will to follow the path of the &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1685] = {title = "Gakin's Summons", objective = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", description = "Isn't that how it always works? Was looking for you all day and couldn't find you, now when I'm not expecting it, you come and walk right up to me.\n\nI've wasted enough time trying to find you, so I won't delay you any longer. Master Gakin's summoned you for additional training. Seems to me you should seek him out as soon as possible.\n\nYou'll find him in the basement of the Slaughtered Lamb tavern. By the way, you might want to keep that particular location quiet. Don't want word spreading about it.", progress = nil, completion = "About time you showed up. Though, perhaps I should have sent someone more capable than Remen to find you.\n\nNo matter.\n\nYou've gone too long without training, and a &lt;class&gt; without training isn't like to keep his head on his shoulders for long.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1686] = {title = "The Shade of Elura", objective = "Bring 8 loads of Elunite Ore and the Medallion of Elura to Elanaria in Darnassus.", description = "You have learned much, <name>.  Now we will craft you a weapon.  A warrior's weapon.\n\nTo do this, you must travel to Darkshore.\n\nLong ago a ship crashed upon the rocks near the Auberdine lighthouse, scattering many crates of elunite ore along the ocean floor.\n\nFirst, you must defeat the elunite's guardian, the Shade of Elura.  Once the ship's captain, she cursed herself to roam the deeps and protect her shipment for all time.  Defeat her, gain her medallion, and gather the crates of lost Elunite.", progress = "Have you defeated the Shade of Elura, <name>?  And do you have the lost elunite ore?", completion = "Bravely done, &lt;name&gt;.\n\nYou have given the Shade of Elura much deserved peace, and we will use the gathered elunite to make a fine weapon for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1687] = {title = "Spooky Lighthouse", objective = "Take the orphan to see the lighthouse off the coast of Westfall.", description = "Sometimes late at night, our matrons at the orphanage will tell us spooky stories.  Those RULE!  There's one about a ghost that haunts a lighthouse in Westfall.  They say he was a pirate captain who had his ship taken from him by other pirates.  Wow!\n\nCould you please take me to the lighthouse in Westfall?  I wanna see if the ghost of that captain is there!  I promise to stay close to you; I won't run off or anything!", progress = "Are we there yet?", completion = "WOW, that was a real life ghost!  That was so awesome - I can't wait to tell everyone back at the orphanage.  Captain Grayson... he even looked like a pirate!  When I grow up I wanna be a ghost pirate too!\n\nThanks for taking me to Westfall, &lt;name&gt;.  I know there are scary things out there in the wilds of Westfall, and I hope I wasn't too much of a pain.  You're awesome!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1688] = {title = "Surena Caledon", objective = "Retrieve Surena's Choker for Gakin the Darkbinder in Stormwind.", description = "I had a student named Surena Caledon. She stood where you stand now, eager to learn of warlock magic, and possessing no small bit of talent. More than that she was young and pleasing to the eye. Had I seen it then, the traitorous trollop!\n\nThe thieving wench ran off with one of the Defias, Erlan Drudgemoor. While her loss is of little importance, I gifted her a bloodstone choker that I must have.\n\nHer life means nothing to me now. You will find her at the Brackwell Pumpkin Patch. Retrieve what is mine.", progress = "Even the older and wiser can be unmanned by the wiles of youth and beauty, <name>. A piece of advice you would do well to remember throughout your life.", completion = "Surena was talented, but not enough so to gain mastery of &lt;class&gt; magic on her own. It's a shame to see talent wasted, but sometimes it is necessary.\n\nI hope my investment in you will bear different results.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1689] = {title = "The Binding", objective = "Using the Bloodstone Choker, summon and subdue a voidwalker, then return the Bloodstone Choker to Gakin the Darkbinder in Stormwind.", description = "By retrieving my choker and besting Surena, you've proven that you're at least as capable as she was.\n\nWith that said, I can tell you're direly in need of training. You can manage the flows of magic, yes, but being a warlock is much more than that.\n\nI will show you how to command a voidwalker, but before I can, you must call one forth at a summoning circle and subdue it using whatever weapons--physical and magical--you have at your disposal. Use the magic of this choker at the summoning circle below.", progress = "I cannot show you how to control a voidwalker until you have overtaken one.", completion = "You did better than I expected, &lt;name&gt;, but as well as I'd hoped. Now, you can learn to command your subjugated voidwalker, an ally you will find valuable in the trials that are sure to stand before you.\n\nI have nothing more to teach you at the present, but I am far from done with you, &lt;name&gt;.", rewards = "You will learn:\n\nSummon Voidwalker\n\nThe following spell will be cast on you:\n\nTeach Summon Voidwalker\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1690] = {title = "Wastewander Justice", objective = "Take down 10 Wastewander Bandits and Thieves east of Gadgetzan, then report back to Chief Engineer Bilgewhizzle.", description = "You there!  It's time for you to be a big helper to the Gadgetzan Water Company.\n\nThe Wastewander nomads out in the Tanaris desert have seized almost all the water wells!  Without access to them, our water supply will dry up in no time.  If you want to get in our good graces, then you'll help us bring justice to those nomads!\n\nHead east of here and bring down ten Wastewander Bandits and Thieves, then report back to me on the double.  Justice waits for no man... goblin... bah, just get on it!", progress = "Back so soon?  I hope you were able to bring some goblin-style justice to those Wastewander Bandits and Thieves like I asked you to!", completion = "Now that's what I call efficiency!  You've helped thin out the nomad's numbers enough now that we can start to think about how we can win back those water wells.\n\nThe Gadgetzan Water Company thanks you for your help, but we're far from done in dealing with those foul nomads.  Listen close - here's what we need next...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1691] = {title = "More Wastewander Justice", objective = "Take down 10 Wastewander Shadow Mages, 8 Wastewander Rogues, and 6 Wastewander Assassins for Chief Engineer Bilgewhizzle in Gadgetzan.", description = "We need you to take on the stronger ranks of the Wastewander nomads now.  You've done a good job thus far, but if we are to take back those water wells, then it only makes sense to do it against as few nomads as possible!\n\nThis time around we need you to take down their rogues, assassins, and shadow mages.  You'll find them east and southeast of here.\n\nI'm not going to lie to you - they're a nasty lot.  Do this for us though, and we'll be on our way to taking back what is rightfully ours!", progress = "Well, were you able to take out those nomads like I asked?  The Gadgetzan Water Company is developing plans based on your success here!  Don't let us down, now...", completion = "Top notch work, &lt;name&gt;... top notch!  You've thinned down the nomad population to a point where we can actually take the fight to them!\n\nIf you haven't already, talk to Spigot Operator Luglunket here; he gives a bounty on any of the Wastewander water pouches you may have run across while bringing those nomads to justice!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1692] = {title = "Smith Mathiel", objective = "Bring the Case of Elunite to Smith Mathiel.", description = "I have placed the elunite you gathered into a case.  Take it to the blacksmith Mathiel, and he will craft for you an elunite weapon.\n\nMathiel is to the south, on the other side of this building.", progress = "Greetings, young <class>.  How might my skills serve you?", completion = "Ah, elunite ore.  This is a fine metal to work with, for it is blessed by the goddess Elune herself.  It would be an honor to craft weapons with it.\n\nPlease wait while I work...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1693] = {title = "Weapons of Elunite", objective = "<name>, I have crafted these weapons with the elunite you brought to me.  Please, take whichever most suits you.\n\nAnd I must thank you.  Working with elunite is both an honor and a pleasure.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nElunite AxeElunite HammerElunite DaggerElunite Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1698] = {title = "Yorus Barleybrew", objective = "Speak with Yorus Barleybrew.", description = "Yorus Barleybrew has issued a challenge to all able warriors of the Alliance.  He waits at the Lakeshire Inn, in Redridge, and pledges a grand reward to anyone able to pass his trial.", progress = nil, completion = "Hah!  So you heard of my challenge, did you?\n\nWell sit down and listen.  Have a drink, and savor it... because it might be your last.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1699] = {title = "The Rethban Gauntlet", objective = "Enter the Rethban Caverns, reach the first fork, and return to Yorus Barleybrew within the time allowed.\n\nYou must not die and release your spirit.", description = "I call my challenge the Rethban Gauntlet.  To pass the trial, all you must do is enter the Rethban Caverns, to the first fork, then return here.  Easy!  Except there are a few wrinkles...\n\nYou have to return within an hour.\n\nThere are whole heaps of Redridge Gnolls in the way.\n\nBefore you start, you have to take a swig of my family's signature drink: Barleybrew Scalder!\n\nSo what do you say?  The Rethban Caverns are in the foothills north of Lakeshire.  Are you ready to run the Rethban Gauntlet?", progress = "Time is wasting, <name>.  If I were you, I'd get going...", completion = "You made it!  Well done!  Three cheers for &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1700] = {title = "Grimand Elmore", objective = "Bring Furen's Notes to Grimand Elmore.", description = "I made a copy of my notes on the techniques I learned while making your armor, and I need them sent to Grimand Elmore.  He's here in the Dwarven District, in the weapon shop.\n\nAnd duck when you give these to him.  He's fiercely proud of his skills, and won't like the idea of learning something from me...", progress = "Hello, and well met.  How might I be of service to you?", completion = "Furen wrote this?  How dare he!  Why, I taught him everything he knows!  To think he could teach me something is outrageous!  Outrageous!\n\nHm... but there is something in his notes that I'd like to try...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1701] = {title = "Fire Hardened Mail", objective = "Gather the materials Furen Longbeard requires, and bring them to him in Stormwind.", description = "So I gave you a nice shield, but we don't have to stop there.  I know the secrets to make extremely hard mail armor.  It's not easy and it takes very rare materials, but if you're willing to do the legwork then I'll make a piece for you.\n\nWhat do you say, <name>?  If you're up for the challenge, then I'll give you a list of what to get and where to get them.", progress = "How goes the scavenger hunt, <name>?  Do you have the materials?", completion = "You got it all?  Amazing!  I was afraid those chimaeras would eat you up for sure!\n\nWell let's get started on that armor...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1702] = {title = "The Shieldsmith", objective = "Bring the Cask of Scalder to Furen Longbeard.", description = "You really showed what you were made of when you ran the Rethban Gauntlet, <name>.  And I'm true to my word.  I'll get you the reward I promised...\n\nExcept it's in Stormwind.\n\nTalk to my friend, Furen Longbeard, in the Dwarven District of Stormwind.  He's the best shieldsmith you'll ever meet, and he owes me a big favor.\n\nHere, take Furen this cask of Barleybrew Scalder and ask him for a shield.  He'll give you a nice one.", progress = "Hello!  Dry times, don't you think?", completion = "Ah, Barleybrew Scalder.  Great stuff!  So you've been to see Yorus, eh?\n\nI can get you a shield, yes sir!  You won't find a better one, and that's no lying!", rewards = "You will receive:\n\nFuren's Favor"}
MultiLanguageQuestData['en'][1703] = {title = "Mathiel", objective = "Bring Furen's Notes to Mathiel.", description = "I made a copy of my notes on the techniques I learned while making your armor, and need them sent to the blacksmith Mathiel.  He lives in Darnassus which is quite a long way off, but I'm sure he'll be very grateful to learn what I've learned.", progress = "I bid you greetings, <class>.", completion = "These are interesting, very interesting indeed.  My dwarven colleague Furen has made quite a grand discovery!\n\nThank you, &lt;name&gt;.  It will be an honor to apply his new techniques to my own craftings.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1704] = {title = "Klockmort Spannerspan", objective = "Bring Furen's Notes to Klockmort Spannerspan.", description = "I made a copy of my notes on the techniques I learned while making your armor, and need someone to take them to Klockmort Spannerspan.  He's a gnomish blacksmith in Ironforge and when he learns what I've learned... I bet he'll pull off his own beard in excitement.", progress = "Good day, or morning or evening.  I can't tell from way down here.  So do you have business for me?", completion = "Oh my!  These notes are amazing!  And what's more... they're incredible and they're stupendous and they make my knees go all a-wobbly!\n\nFuren had a breakthrough!  A real breakthrough!  I can't wait to try out his new technique!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1705] = {title = "Burning Blood", objective = "Bring 20 vials of Burning Blood and 1 Burning Rock to Grimand Elmore in Stormwind.", description = "I hate to admit that Furen might have really found something.  But to be sure I'll need to try his techniques on a new piece of armor.  If you help me with the materials, <name>, then you can have the armor.\n\nTo make this armor, I need samples of burning blood and a burning rock.\n\nThe only place I know to get them is Duskwood.  The Nightbane worgen based in the Roland's Doom mine have burning blood, and their leader Gutspill will have the rock.\n\nMay fortune grant you speed, <name>.", progress = "<name>, do you have the burning blood and rock?  I'll need them to complete the armor.", completion = "Nice work!  Now if you'll excuse me, I have some work to do myself...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1706] = {title = "Grimand's Armor", objective = "I can barely believe it!  Furen's technique was a success, and this armor should withstand tremendous levels of stress.\n\nHere you are, <name>.  And thank you.  I wouldn't have believed Furen's discovery if you hadn't gathered the materials I needed to test it myself.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nFire Hardened Coif"}
MultiLanguageQuestData['en'][1707] = {title = "Water Pouch Bounty", objective = "Bring 5 Wastewander Water Pouches to Spigot Operator Luglunket in Gadgetzan.", description = "Greetings <name> - the name's Luglunket, and we've got an important job for you if you're up for it!  Huzzah!\n\nNothing would please me more as a seasoned spigot operator to take any Wastewander water pouches you might find out in the desert.  That's our water anyway - the nomads have just stolen it is all!  The Gadgetzan Water Company will offer you an official care package for every five you turn in.  Most importantly though, you're helping Gadgetzan help itself!", progress = "Got the five Wastewander water pouches we need?  If you do, then the Gadgetzan Water Company Care Package, Model 103-XB, will be yours!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me.", rewards = "You will receive:\n\nGadgetzan Water Co. Care Package"}
MultiLanguageQuestData['en'][1708] = {title = "Iron Coral", objective = "Bring 20 loads of Searing Coral to Klockmort Spannerspan in Ironforge.", description = "I want to try Furen Longbeard's new techniques on my own piece of armor.  And because you helped Furen and he helped me, you're welcome to the armor after I make it!\n\nTo finish the piece, I need a special coral, searing coral.  It grows in only one place--along the coast south of Menethil Harbor in the Wetlands.\n\nBring me enough searing coral and I'll get right to work on the armor.  And hurry, <name>.  I'm so eager to get started it's making my toes twist!", progress = "Hello hello, <name>!  Do you have the searing coral?  I can't wait to get to work!", completion = "That's the stuff!  Well done!  Now let me get this smelted and hammered so I can apply Furen's technique with my own and then we can see what happens!\n\nOh my, oh my!  I just know the armor will be very very very tough!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1709] = {title = "Klockmort's Creation", objective = "Here's your armor, <name>.  Furen's process worked brilliantly!  Perfectly!  Marvelously, truly!\n\nYou could run this armor over with a siege engine and it would spring right back into shape!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nFire Hardened Gauntlets"}
MultiLanguageQuestData['en'][1710] = {title = "Sunscorched Shells", objective = "Bring 20 Sunscorched Shells to Mathiel in Darnassus.", description = "My colleague, Furen Longbeard, made a discovery which I am eager to test.  I wish to try it on a new armor that I am researching, for I believe Furen's techniques will produce superior results.\n\nWill you help me?  If you gather what I need to make the armor, then I will make an extra piece for you.\n\nI need the sunscorched egg shells of the Highperch Wyverns who dwell at Highperch, in Thousand Needles.  Search for the shells below their nests, and return to me when you have a sufficient amount.", progress = "Do you have the shells, <name>?  They are quite strong, and can be rendered into a lacquer I will use to coat the links of my new mail armor.", completion = "Ah, thank you.  These will work splendidly!\n\nI will begin fashioning the armor immediately...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1711] = {title = "Mathiel's Armor", objective = "I have finished with your piece of armor, and I am quite pleased.  Furen's new techniques meshed perfectly with my own and I am sure this armor will prove to be quite resilient.\n\nThank you, <name>.  And may this serve you well in future battles.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nFire Hardened Leggings"}
MultiLanguageQuestData['en'][1712] = {title = "Cyclonian", objective = "Bring the items on Bath'rah's Parchment to Bath'rah the Windwatcher in Alterac.", description = "I have spent ages watching this site.  I watch, so that one day I might see the great Cyclonian fall.  But I have not yet found a champion to defeat the wind lord.\n\nPerhaps you are that champion.\n\nProve it to me.  Gather the items I need to summon Cyclonian, and I will know you are a great warrior.  Perhaps then you can defeat him and gain his whirlwind heart.\n\nIf so, then I will infuse the heart's power in a weapon, and I will give that weapon to you.\n\nHere is a parchment with the items I need.", progress = "Do you have the items, <name>?  Gathering them is the proof I need that you have the strength to face Cyclonian.", completion = "You have gathered the items for my spell, and have shown me your strength and cunning.  But the next stage of our quest is even more perilous.\n\nLet us hope your strength does not falter.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1713] = {title = "The Summoning", objective = "Bring the Whirlwind Heart to Bath'rah Windwatcher.", description = "I am ready to perform the ritual to summon Cyclonian.  When he is summoned, you must defeat him and take his whirlwind heart.  This I will use to instill a weapon with Cyclonian's power.\n\n<name>, are you ready to face the wind lord?", progress = "<name>, I must have the whirlwind heart!", completion = "You did it!  You defeated Cyclonian and gained the Whirlwind Heart!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1714] = {title = "Essence of the Exile", objective = "The cauldron bubbles.  Its vapors beckon...", description = nil, progress = "The cauldron bubbles.  Its vapors beckon...", completion = "The charms sink slowly into the cauldron's depths...\n\nA large bubble rises to the surface of the liquid and breaks...\n\n...And a churning lump of molten rock is revealed.", rewards = "You will receive:\n\nEssence of the Exile"}
MultiLanguageQuestData['en'][1715] = {title = "The Slaughtered Lamb", objective = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", description = "Hmph. Times past, all warlocks in Khaz Modan were trained under the auspices of the masters of Gnomeregan, but now that we've all been forced to relocate into this rat's hole in Ironforge, and Magni's decided to keep a careful watch on us, we're forced to send our novices to Stormwind for training.\n\nLuckily, Gakin's no slouch, so you'll still learn what you need to know, but it burns my blood!\n\nAnyways, you'll find Gakin in the basement of the Slaughtered Lamb in Stormwind.", progress = nil, completion = "Sent by Blackwrench, were you? Damn warlocks in Ironforge need to get things sorted out. There's only so much room and so many teachers in Stormwind. With all the increased traffic, we're sure to attract attention sooner or later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1716] = {title = "Devourer of Souls", objective = "Speak with Takar the Seer in the Barrens.", description = "A sayaad is a devourer of souls, dominator of wills, and tempter of hearts. It knows nothing but evil.\n\nSalacious tales refer to the demon by its common name: succubus for females, incubus for males.\n\nA stimulus is required to beckon the creature. With a symbol of love as bait, it will surely answer your call. Defeat it, and make it your tool.\n\nIt will be hard to find a thing of this nature, though. You should speak with Takar the Seer. You will find him in the Barrens of Kalimdor near Camp Taurajo.", progress = nil, completion = "Was your crossing difficult, &lt;name&gt;? You have come a long way to speak with me. But fear not, I know why Gakin has sent you, and he was wise to, for I can help you in your search.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1717] = {title = "Gakin's Summons", objective = "Report to Gakin the Darkbinder in the Mage Quarter of Stormwind.", description = "<name>! Didn't expect to see you around these parts, but I was instructed to keep an eye out for you.\n\nIt's past time you got some more training, so you should stop in to see Gakin the next time you're in Stormwind. He'll be waiting for you.", progress = nil, completion = "I'm glad someone was able to get a hold of you, &lt;name&gt;. I was beginning to fear the worst. It would be a shame to lose you, after the time we've invested in you.\n\nWe can talk later, though. Your training is the only important thing now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1718] = {title = "The Islander", objective = "Speak with Klannoc Macleod.", description = "Your renown as a warrior grows, <name>.  Now it is time to pit yourself against your peers and see where you stand.\n\nThere is an island off the coast of the Barrens, south of Ratchet.  It is called Fray Island and it is a place where warriors meet.\n\nMeet, and fight.\n\nSpeak with the chief warrior of Fray Island, Klannoc Macleod.  If he finds you worthy, then Klannoc will lead you further down the warrior's path.\n\nTo reach Fray Island, search for the sand bar shallows along the Merchant Coast.", progress = nil, completion = "Hello, &lt;class&gt;.  It's good to see you made it to Fray Island.  I hope you find it to your liking...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1719] = {title = "The Affray", objective = "Kill Big Will, then speak to Klannoc Macleod on Fray Island.", description = "If you want to learn from me, then you must first pass The Affray.  It is a challenge we on Fray Island like to offer rising warriors who think they're tough, and if you can pass this test then I'll know you are.\n\nTo begin, walk into the middle of that crowd yonder and step on the grate.  That'll tell Twiggy Flathead you're ready, and he'll send challengers against you.\n\nBeat all the challengers and he'll call out Big Will.  Kill Big Will, and return to me in the time we allow.", progress = "Have you completed your challenge?", completion = "Well done, &lt;name&gt;.  You have passed The Affray!\n\nYou are a worthy &lt;class&gt;, and I am honored to teach you...", rewards = "The following spell will be cast on you:\n\nPath of the Berserker\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1738] = {title = "Heartswood", objective = "Retrieve the Heartswood from Ashenvale and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", description = "In preparation for your coming, I used my sight to look over the world and through the mists of time. I have found what it is you seek.\n\nIn the War of the Ancients, two lovers fell together in battle. Where they took their last breaths, a tree known as the heartswood grew, a symbol of their undying love.\n\nThat should be enough to tempt a succubus. You will find it in the ruins of Ordil'Aran in the northwestern part of the forest of Ashenvale.", progress = "Was your search a success, <name>?", completion = "Yes, I can tell this will do nicely, let me just work with it for a moment...\n\nTakar is a resourceful fellow to have around, isn't he? If only I could persuade him to move back to civilization.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1739] = {title = "The Binding", objective = "Using the Heartswood Core, summon and subdue a succubus, then return the Heartswood Core to Gakin the Darkbinder in the Slaughtered Lamb.", description = "Using the heartswood core, you will be able to cast a spell at the summoning circle in the crypt below to open a portal for the succubus to pass through.\n\nBe careful, <name>, succubi have overrun even the strongest of minds.\n\nOnce you have bested and returned it to the void, return to me and I will show you how to call and control it.", progress = "Sometimes I wonder if Surena was not a succubus in disguise, sent to warp and twist my mind... Ha! I give her too much credit, I think.", completion = "Well done, well done, &lt;name&gt;. I see we've done right in deciding to train you. Your performance certainly does not disappoint.\n\nI've no qualms in showing you the way to control your newly bound succubus. Observe carefully.", rewards = "You will learn:\n\nSummon Succubus\n\nThe following spell will be cast on you:\n\nTeach Summon Succubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][1740] = {title = "The Orb of Soran'ruk", objective = "Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan in the Barrens.", description = "When demons of the Legion fall out of favor, their spirits are imprisoned within orbs and distributed to their mages and warlocks.\n\nMany were carried by their servants in Azeroth. Even fragmented, they still possess the powers of the demons trapped inside.\n\nThe orb of Soran'ruk was broken into two pieces, one was further broken to be used by the acolytes of the Twilight's Hammer in Blackfathom Deeps. The other, larger piece, was possessed by a wizard in Shadowfang Keep. Find them and I can reform it.", progress = "It took me many years to collect the pieces of the orb of Zargain, but it has served me well, as I am sure the orb of Soran'ruk will serve you.", completion = "Yes... The orb was not greatly fragmented, and almost all of the pieces are here. It is a simple thing to recreate them, to make Soran'ruk whole again.\n\nI have dedicated my life to the study of the Burning Legion's orbs and their recreation. You have done me a favor collecting these pieces to study, and I will give you them back--fully reconstructed--in a form of your choosing.", rewards = "You will be able to choose one of these rewards:\n\nOrb of Soran'rukStaff of Soran'ruk\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1758] = {title = "Tome of the Cabal", objective = "Speak with Krom Stoutarm in Ironforge.", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Krom Stoutarm can help you with this. An itinerant warlock these days, he spends his days hoarding ancient texts and skulking about the library in Ironforge.", progress = nil, completion = "Tome of the Cabal? Hmm... sounds familiar. I've never seen it here before, though--and believe me, I remember every book I read.\n\nHmm...\n\nAh, yes! I have seen references to it in library cataloguing books.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1778] = {title = "The Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge.", description = "I'm going to see about making plans to return home soon. Hopefully, Stephanie is doing well back in Stormwind. I can't wait to see her again. Till next we meet, <class>.", progress = nil, completion = "So, you've returned so quickly, huh? And what pray tell have you accomplished in your time away from here?\n\nWere you able to help a noble cause? Perhaps you've learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Impressive, &lt;name&gt;, those are surely the actions of one who follows the Light.\n\nSuch sacrifice will always be rewarded in time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1779] = {title = "The Tome of Divinity", objective = "Take the Symbol of Life and speak to Muiredon Battleforge in Ironforge.\n\nProvided item: \n", description = "I want you to take this, <name>. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now I want you to prove just how adept you've become in both combat, and power.\n\nMy husband Muiredon returned recently from an encounter with some Dark Iron dwarves, and he barely escaped with his life--he's over there having his wounds healed by one of our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May the Light shine upon you.", progress = nil, completion = "*cough*\n\nGood day to ya, &lt;class&gt;. Don't mind me wounds, the good priest 'ere'll take care of ol' Muiredon in time. Not needin' the power of that Symbol of Life ya got there quite yet.\n\nSo, me wife sent ya o'er to speak to me, huh? Fair 'nough. I'll take the time to talk to ya--I'll tell ya exactly wut happened to Muiredon and his best friend Narm, a &lt;class&gt; jus' like yerself.", rewards = nil}
MultiLanguageQuestData['en'][1780] = {title = "The Tome of Divinity", objective = "Speak to Duthorian Rall in Stormwind.", description = "I'll take these to the children this very day. Please be safe, good <class>. It is not often <men/women> of your character show their faces in the city, but you've proven that the paladins here in Stormwind shall never turn their backs on those in need.\n\nFarewell.", progress = nil, completion = "You've returned so quickly, &lt;name&gt;. And what have you accomplished in your time away from the Cathedral?\n\nHave you helped a noble cause? Perhaps you've learned the value of charity or some more about your obligations to the citizens of Azeroth. Tell me, who have you helped and how.... Well, I'm impressed, &lt;name&gt;, those are surely the actions of one who follows the Light and values others above oneself.\n\nSuch sacrifice will always be rewarded in time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1781] = {title = "The Tome of Divinity", objective = "Take the Symbol of Life to Gazin Tenorm in Stormwind.\n\nProvided item: \n", description = "Take this, <name>. It is called the Symbol of Life.\n\nYou've proven charitable and patient, and now the time has come to see if you're powerful enough to focus one of the Light's greatest gifts.\n\nMy friend Gazin returned recently from an encounter with some Defias in Elwynn near Heroes' Vigil--he barely escaped with his life. He's near the altar having his wounds healed by our priests.\n\nTake the Symbol and speak to him. If you can help him, then we will speak again soon. May you bask in the Light's glory.", progress = nil, completion = "*cough*\n\nPleasure to meet you, &lt;class&gt;. Don't mind my wounds, the good priest here can take care of ol' Gazin this time. I won't be needing the power of that Symbol of Life you've got there... not yet anyway.\n\nSo, Duthorian sent you to speak to me, huh? Fair enough. I'll tell you exactly what befell me and my friend Henze. And with any luck, and some skill on your part, perhaps you can still help us all.", rewards = nil}
MultiLanguageQuestData['en'][1782] = {title = "Furen's Armor", objective = "Here's your armor, <name>.  This will stand up to the strongest assaults or my name isn't Furen Longbeard!\n\nAnd I have to thank you.  I learned a lot while working with the materials you brought me.  I think I'll have another breakthrough one day!\n\nI'm going to send what I learned to other blacksmiths of the Alliance.\n\nI'll tell them you were a big help, and maybe they'll want to return the favor.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nFire Hardened Hauberk"}
MultiLanguageQuestData['en'][1783] = {title = "The Tome of Divinity", objective = "Take the Symbol of Life and resurrect Narm Faulk in Dun Morogh.", description = "We was spyin' on some of the Dark Iron dwarves that've bunkered down south of Helm's Bed Lake. We knew they was up to no good, so Narm an' me thought we'd take a closer look--got ta see their leader given orders to some o' his men.\n\nNarm an' me took the chance to kill a few of 'em, but they proved tougher than we thought, an' more of 'em got the jump on us. Narm tol' me to run an' get support, so 'ere I am.\n\nNarm needs help, an' I'll not rest till he gets it.\n\nC'n ya help, <name>?", progress = nil, completion = "I can't thank you enough, brother.\n\nI can only assume that Tiza and Muiredon sent you here to aid me if you carry the Symbol of Life.\n\nIt's true, I fell to the Dark Iron while trying to attain one of the scripts: I was able to hold on long enough to allow Muiredon to escape, but the Light had almost embraced me fully when you came along. The fact that you were powerful enough to use the Symbol means great things for you, but there's time to speak of that later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1784] = {title = "The Tome of Divinity", objective = "Retrieve a Dark Iron Script from the Dark Iron dwarves near Helm's Bed, and return to Muiredon Battleforge in Ironforge.", description = "Before I fell in battle, Muiredon and I had almost defeated one of the Dark Iron spies near that small house. We witnessed their captain passing orders to them, and sought to kill him and take the orders.\n\nSome of the council in Ironforge do not yet believe the presence of Dark Iron dwarves exists in Dun Morogh. By attaining one of those scripts, we'll not only have proof of their movements, but possibly an idea of what they're planning.\n\nGet one of those scripts and take it back to Muiredon, <name>.", progress = "Yer back! I'm glad to see it, <name>. My wounds are healed and I'm about ready to return to Helm's Bed lake as soon as I c'n convince me wife that I'll be fine.", completion = "Haha! You've done it! Ya saved Narm, and ya found the proof me wife needs to take to the council. Yer a blessin' o' the Light if I ever saw one... not includin' me wife o' course.\n\nThank ya again, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1785] = {title = "The Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge.", description = "I c'n see me wife's o'er there beamin' wit pride already. Ya better get yer tuchus o'er there pronto. I be thinkin' she'd have some words wit ya.\n\nLight be witcha, mighty <class>. I'll be lookin' fer ya on the battlefield against the Scourge and dem Dark Irons when the time comes.", progress = nil, completion = "You've done all of Ironforge a great favor today, &lt;name&gt;. I'm proud to count you among us, and if you feel you're ready, I would like to bless you with this scroll. The Symbol of Life would only have worked when used by a &lt;class&gt; who was ready for one of the Light's greatest blessings--the power to restore the dead back to life.\n\nI will teach you the ability to resurrect your companions. Use it wisely, &lt;name&gt;, and thank you, on behalf of myself, my husband, and Ironforge.", rewards = "You will learn:\n\nRedemption\n\nThe following spell will be cast on you:\n\nRedemption\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1786] = {title = "The Tome of Divinity", objective = "Take the Symbol of Life and resurrect Henze Faulk in Elwynn.", description = "Henze and I had made it to Heroes' Vigil, an island in the middle of Stone Cairn Lake in northeastern Elwynn. We'd heard the Defias had infiltrated our borders and we wanted proof to take to the king's advisors.\n\nWe caught sight of a couple of the scum going over some documents, and we attacked. Unfortunately, we were quickly overwhelmed by more of the mages.\n\nHenze held them off for me while I escaped... the daft fool, going and being brave.\n\nHe's out there now, Henze is. Can you help us, <name>?", progress = nil, completion = "Thank you, brother.\n\nSeeing you wield the Symbol of Life, may I assume Duthorian or Gazin sent you?\n\nI fell to the Defias spell casters while Gazin and I tried to get their plans from them: I was able to hold on long enough to allow Gazin to escape, but in the end, their magics overwhelmed me.\n\nBut you were able to bring me back: the ability to use the Symbol doesn't come to just anyone, &lt;name&gt;. It bodes well for you that you were able to empower it with your own faith.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1787] = {title = "The Tome of Divinity", objective = "Retrieve a Defias Script from the Defias Rogue Wizards in Elwynn, and return to Gazin Tenorm in Stormwind.", description = "We'll have time to talk more about the Symbol at a later time. What's important now is to get those papers we saw the Defias going over. If we can get our hands on them, we'll be able to prove the Defias have infiltrated Elwynn and hopefully gain some insight into what their plans are.\n\nI'm in no shape for battle as of now, <name>. Do you think you're strong enough to get those papers from the Defias here on the island?\n\nIf you're able to get them, bring them back to Gazin and let him know I'm all right.", progress = "Is Henze safe, <name>? Were you successful?\n\nBetween your skill with a weapon, and the power of the Light, I'd imagine Heroes' Vigil is safe from any Defias threat, but that's for the King and his advisors to say.", completion = "Wonderful! You made it, and saved Henze. The Light is with you for sure, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1788] = {title = "The Tome of Divinity", objective = "Speak to Duthorian Rall in Stormwind.", description = "I'll take the script to the King's advisors after Duthorian's taken a look at them, but in the meantime, you should go speak to Duthorian now. He'll be wanting to pat you on the back for sure!\n\nThank you again, <name>. I hope we meet again. You're surely an ally I'm proud to call friend.You will learn:\n\n", progress = nil, completion = nil, rewards = "You will learn:\n\nRedemption\n\nThe following spell will be cast on you:\n\nRedemption\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1789] = {title = "The Symbol of Life", objective = "If you fail to help Narm after you've used the Symbol of Life, <name>, then return to me and I shall give you another.\n\nIt is important to both my husband and I that you return successful. Please, make haste.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSymbol of Life"}
MultiLanguageQuestData['en'][1790] = {title = "The Symbol of Life", objective = "Make haste, <name>, more than one life hangs in the balance if you fail.\n\nIf for some reason you fail to help Gazin and Henze, then return to me and I will give you another Symbol of Life for your travels.\n\nDon't mistake my aid as simple charity, you must prove yourself worthy like any other <class> and continual failure may reflect upon you later.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSymbol of Life"}
MultiLanguageQuestData['en'][1791] = {title = "The Windwatcher", objective = "Speak with Bath'rah the Windwatcher.", description = "Now that you've learned your berserker's stance, you'll want a nice weapon to use it with.\n\nTalk to Bath'rah the Windwatcher, a troll hermit who lives between the Alterac Mountains and the Western Plaguelands.  He is a skilled weapon maker and a powerful shaman.\n\nTo find Bath'rah, go to the river that flows along Tarren Mill's eastern flank.  Follow it north--Bath'rah is camped near ruins that rest along the river's eastern bank.", progress = nil, completion = "You have traveled far, young &lt;class&gt;.  I see fire in your eyes.  You seek a weapon of great power, yes?\n\nI can help you with your quest.  And you can help me with mine.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1792] = {title = "Whirlwind Weapon", objective = "I have the whirlwind heart, and am ready to place it within your vessel of choice.\n\nChoose your weapon, <name>, and know that its power is the power of Cyclonian.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nWhirlwind AxeWhirlwind SwordWhirlwind Warhammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1793] = {title = "The Tome of Valor", objective = "It has been proven that the Light is with you, <name>, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?\n\nBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTome of Valor"}
MultiLanguageQuestData['en'][1794] = {title = "The Tome of Valor", objective = "It has been proven that the Light is with you, <name>, but as times grow more dangerous, it becomes important to know what strength lies beneath the flesh. When demons, dragons, or any other evil set foot in your lands, your mettle will be tested. Will you be strong enough?\n\nBravery, regardless of the situation, is as much a part of paladinhood as the Light, your armor, and your weapon. Protecting the weak, and not losing faith are two more lessons you must master while you study in the Cathedral of Light.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTome of Valor"}
MultiLanguageQuestData['en'][1795] = {title = "The Binding", objective = "Using the Tome of the Cabal, summon and subdue a felhunter, then return the Tome of the Cabal to Strahad Farsan in Ratchet.", description = "If you are sufficiently prepared, then we should begin. Let me explain the process to you.\n\nI will begin by creating the basic summoning circle. When that is finished, my acolytes will use the rods of channeling to create the greater circle.\n\nOnce that is done, read the incantation from the Tome of the Cabal, and the felhunter will be pulled forth. Be careful, <name>. A felhunter is a powerful foe, and I'd like to see you keep your head on your shoulders.", progress = "Every <class> should have a felhunter at his command. Though it be difficult to tame, the powers it brings to its master far outweigh the cost.", completion = "I must say I'm impressed, &lt;name&gt;. When I faced down my felhunter, I barely escaped with my life. I sense that you have the potential to become one of the most powerful warlocks of this era.", rewards = "You will learn:\n\nSummon Felhunter\n\nThe following spell will be cast on you:\n\nTeach Summon Felhunter\n\nYou will also receive:\n\nBox of Souls"}
MultiLanguageQuestData['en'][1796] = {title = "Components for the Enchanted Gold Bloodrobe", objective = "Bring Robes of the Arcana to Menara Voidrender in the Barrens.", description = "The first item I will aid you in creating is a robe. You will gather the items for me, and we will put them together. Afterwards, assuming you succeed, you will have the first of many items that will make you more powerful and aid you in your struggles.\n\nTo start, you must have crafted Robes of Arcana. A tailor can make this for you, or perhaps you can purchase one from someone else--I'd be most impressed if you could make it yourself--but regardless, bring me the robes, and we shall go from there.", progress = "How goes your search for the robes, <name>? Have you created them yourself? Such personal touches I find make the imbuing of magic that much sweeter. It gives you a greater sense of accomplishment. But I understand if you choose the quicker path and have it made for you--there's something to be said for such... ambition.", completion = "This will do nicely, &lt;name&gt;.\n\nAll magical items must begin with an item of high quality. The more effort and skill put into an item, the greater the magics it can hold. Rare and more expensive components hold the magic better. You will not regret having the robes fashioned into the ones we will make for you later on.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1798] = {title = "Seeking Strahad", objective = "Speak with Strahad Farsan in the Barrens.", description = "It is time you learned the felhunter summoning, <name>. I do not have the reagents and items necessary to teach you here, so you will have to seek out another, Strahad Farsan, another of our inner circle.\n\nHe makes his residence in the goblin port of Ratchet. I will send word ahead of you to inform him of your coming.", progress = nil, completion = "&lt;name&gt;? Ah, of course. Our latest prodigy. The real thing can't live up to the legend, I'm afraid.\n\nNo matter, you've come here to learn, not to hear me make jokes to myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1799] = {title = "Fragments of the Orb of Orahil", objective = "Speak to Menara's acolytes inside the tower above Ratchet and choose one of their paths to follow.\n\nAfterwards, bring an Infernal Orb to Tabetha in Dustwallow Marsh.", description = "Good, then we shall begin.\n\nThe first thing you must do is speak to my acolytes inside. Choose one of their paths to follow--they will explain more.\n\nSecond, you must travel to Desolace and find an Infernal Orb from one of the warlocks of Mannoroc Coven. It is that orb that you will cleanse with the help of a mage named Tabetha deep in southern Dustwallow Marsh. She will aid you because of our history together.\n\nAgain, do not come back until you have done both things I've asked.", progress = "And obviously not being a mage, I wonder if I can trust you at all. I can smell the power of the arcane on you, but you seem to have eluded the stank of corruption that comes so willingly with your kind.\n\nYes, a <class>... a <class> has come to ask for my help.\n\nWell, what is it I can do for you, <name>?", completion = "Oh, so Menara sent you. Fair enough... I suppose you may stay as my guest for the time being. But you must be on some pressing business--perhaps you're here seeking lost power? Maybe I'm mistaken. Maybe corruption isn't too far away from you after all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1800] = {title = "Lordaeron Throne Room", objective = "Take your ward to the old Lordaeron Throne Room that lies just before descending into the Undercity.", description = "The orphan matrons at my home tell mighty stories of battle and lore at night if we are good and do our chores.  One story was about how Lordaeron fell, and about how the evil Arthas took his own father's life to become ruler.\n\nHe had no honor, <name>!  When I grow up and become a mighty Horde warrior, my blade will be guided by honor - never evil!\n\nWould you take me to see the throne room, please?  It is just before where you would go down into the Undercity.", progress = "Are we there yet?", completion = "That throne room was scary, &lt;name&gt;!  Even though it was empty, it felt like a great evil had happened there.  I felt mad... but I also felt sad too.  I understand why the matrons tell us such stories; I will never betray my people like that!\n\nThank you for taking me to the throne room, &lt;name&gt;.  I learned a lot.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1801] = {title = "Tome of the Cabal", objective = "Speak with Jorah Annison in the Undercity.", description = "It will take more than a simple summoning circle to bring forth a felhunter for you to challenge.\n\nMy three acolytes and I will assist in creating the magic circles. You require a copy of the Tome of the Cabal, which has been lost to us for some time. It was written by the first group of warlocks to summon a felhunter unaided.\n\nPerhaps Jorah Annison can help you with this. He's employed as a cartographer in the Undercity these days, but still knows more of ancient texts than any I know.", progress = nil, completion = "Map making! Pictures, estimations of reality. I have no use for such things.\n\nIn books, narrative, description! That is where truth lies. I would trade all the maps in this store for one book on the rise of necromancy, or a tale of the Dark Lady's triumph.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1802] = {title = "Tome of the Cabal", objective = "Retrieve the Moldy Tome and Tattered Manuscript for Krom Stoutarm in Ironforge.", description = "It was lost, but there's some idea as to where it might be found.\n\nThere was only one copy ever made and it was vandalized at some point, a large portion of it ripped from the binding. Rumor has it that it somehow passed into the hands of the centaur of Thousand Needles.\n\nThe rest was lost off the coast west of Southshore, where it was to be transported to Menethil Harbor by boat. It never arrived.\n\nIn exchange for this knowledge, all I ask is that if you find it, bring it to me to see.", progress = "Did the rumors prove true, <name>?", completion = "Fantastic! Now I may join the ranks of the few that have spied its contents.\n\nI can't wait to further peruse this text. This is a great day, &lt;name&gt;! If you will just allow me to glance at it before you leave. I'm sure that Strahad will be willing to send me a copy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1803] = {title = "Tome of the Cabal", objective = "Retrieve the Moldy Tome and Tattered Manuscript for Jorah Annison in the Undercity.", description = "Ah! I see that you are a warlock of similar tastes to mine. Indeed, acquiring the Tome of the Cabal is a worthy aspiration. Did you know that it was once held within the walls of Lordaeron? It was vandalized though, almost half its pages removed. Who would commit such a heinous act?\n\nThat half is lost, though rumor says that it fell into the hands of the centaur of the Thousand Needles.\n\nThe rest of the text was to be transferred to Ironforge, but was lost in transit on the coast west of Southshore.", progress = "It may be that you are chasing after fairy tales, <name>, but truth can be found at the center of even the wildest rumors.", completion = "Well well well! What do we have here?\n\nThis is impressive, &lt;name&gt;. I wouldn't have thought it possible, but here it is in my very hands, the complete Tome of the Cabal.\n\nAllow me to leaf through its pages for just a moment before you are off again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1804] = {title = "Tome of the Cabal", objective = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", description = "Well, ah, it's hard to let it go. But you found it, and you have more important things to do with it, of course. Just, please, be sure to mention to Strahad that I wanted a copy.\n\nWhile you were out, he sent a message for you. He wanted me to tell you that for his acolytes to assist with the summoning, you'll have to acquire three rods of channeling.\n\nHe might not know where to find them, but I do! They were last used by the orcs of the Dragonmaw clan in the Wetlands. I'd check their spellcasters!", progress = "Haven't seen you around these parts for a while. Have you found the tome and the rods?", completion = "Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.\n\nThis will be interesting. It's been some time since a young &lt;class&gt; took on a felhunter to make his own.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1805] = {title = "Tome of the Cabal", objective = "Bring the Reconstructed Tome and 3 Rods of Channeling to Strahad Farsan in Ratchet.", description = "This is one of the most interesting texts I have perused in the last few years. The selection here is sparse--mostly books on geography--and I have already read them all. I should hope that Strahad would send me a copy of this tome when he has the chance.\n\nSpeaking of him, he sent word to me while you were away. For your task, you must obtain three rods of channeling.\n\nFor allowing me to look at this text, I will share a secret: You can find the rods on orcs of the Dragonmaw Clan in the Wetlands.", progress = "Yes, <name>? Of what service can I be to you?", completion = "Well done! The Tome of the Cabal and three pristine--slightly scratched, I suppose--rods of channeling.\n\nThis will be interesting. It's been some time since a young &lt;class&gt; took on a felhunter to make his own.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1806] = {title = "The Test of Righteousness", objective = "Wait for Jordan Stilwell to finish forging a weapon for you.", description = "Why don't we go over to the forge and get started on this? I've been preparing for your arrival for some time, so it shouldn't take long at all.\n\nWhen we're done, you'll be far more prepared to defend the Light than you have been, this much I swear.\n\nI'll be somewhat honest, <name>, seeing the results of your exploits makes me somewhat envious. But knowing that I can contribute to your adventures in my own significant way does bring me some joy.", progress = nil, completion = "Here it is, &lt;name&gt;. A weapon worthy of a champion of the Light such as yourself. I've named it after a great dwarven &lt;class&gt; who was a friend of mine. His name was Verigan... Bosch Verigan. Please take it on behalf of myself and my wife. We owe you a great debt, and the world will be a safer place with one of your skill traveling the land.", rewards = "You will receive:\n\nVerigan's Fist"}
MultiLanguageQuestData['en'][1818] = {title = "Speak with Dillinger", objective = "Speak with Deathguard Dillinger in Brill.", description = "I was told Deathguard Dillinger has a job for someone like you.  If you're willing to show your value to the Dark Lady's forces, then report to Dillinger immediately.\n\nDeathguard Dillinger's post is on the west end of Brill, near the graveyard.", progress = nil, completion = "You're here for a mission?  Good.  I have an important one, and one that will test your skill in combat... and your resolve in the defense of the Forsaken.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1819] = {title = "Ulag the Cleaver", objective = "Kill Ulag the Cleaver, then speak with Deathguard Dillinger.", description = "When the Scourge swept through Tirisfal Glades, we captured one to study.  He had a free mind, and called himself Ulag the Cleaver.  But, although his will was free, he was still enthralled by the Lich King.\n\nWe hoped to find a way to break the king's control over Ulag, but we failed.  Now, finally, it is time to free him.  \n\nFree him, and kill him.\n\nActivate the skull stone trigger near the mausoleum to the north.  This will lift the magical seal that binds him.\n\nThen... be ready, <name>.", progress = "Your task is yet undone, <name>.  It is not wise for a <class> to show fear...", completion = "Well done, &lt;name&gt;.  Ulag was no minor agent of the Scourge.  You have shown the Deathguards, and hence the Dark Lady, that you are a &lt;class&gt; of skill and resolve, and are worthy of further instruction.", rewards = "The following spell will be cast on you:\n\nPath of Defense\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][1820] = {title = "Speak with Coleman", objective = "Speak with Coleman Farthing.", description = "You have proven your value to the Dark Lady, now perhaps you can prove yourself to one of her subjects.\n\nColeman Farthing awaits a warrior who is willing to be his instrument of revenge against the Forsaken's enemies.\n\nYou will find him in the Gallow's End Tavern in eastern Brill.", progress = nil, completion = "Yes, it is true.  I have need for your skills in combat.  My means are small, but my task aids both me and the Forsaken's cause.  Do it, and your reward will be twofold.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1821] = {title = "Agamand Heirlooms", objective = "Bring Coleman Farthing the Agamand Family Axe, the Agamand Family Sword, the Agamand Family Mace and the Agamand Family dagger.", description = "The Agamand family were my employers in life, and they were the cause of my death!  It is fitting that the Agamands are now mindless minions of the Lich King.\n\nNow I would have their last vestiges of honor.  Go into their family crypt and rob them of their family heirlooms: a sword, an axe, a dagger and a mace.  Bring them to me!\n\nThe Agamand family crypt is at the north end of the Agamand mills, protected by lurking scourge and dead Agamands.", progress = "Do you have the heirlooms, <name>?", completion = "Ah!  You retrieved them!  Now the last semblance of honor and memory is stripped from the cursed Agamand lands.  The family truly is no more!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1822] = {title = "Heirloom Weapon", objective = "I will keep three of the weapons you returned to me, as mementos of my pain and loss.  But please, <name>, choose your favorite of the heirlooms and keep it for yourself.\n\nMay it serve you greater than it served its cursed, former owners.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nHeirloom AxeHeirloom HammerHeirloom DaggerHeirloom Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1823] = {title = "Speak with Ruga", objective = "Speak with Ruga Ragetotem.", description = "You are a warrior of skill and growing renown.  Perhaps you are ready for Ruga Ragetotem's trial?  If so, then find Ruga in Camp Taurajo in the Barrens.\n\nHe awaits those warriors who answer his call.", progress = nil, completion = "You are here for my trial, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1824] = {title = "Trial at the Field of Giants", objective = "Bring 5 twitching antennae to Ruga Ragetotem at Camp Taurajo", description = "To pass this trial, you must travel south to the Field of Giants.  There you will find a host of crawling, insect creatures.  They are new to the Barrens and I do not like what they herald.\n\nBring me their still-twitching antennae, and waste no time, <name>, for harvested antennae will not twitch for long.  Bring me the antennae in the time allowed, and you will pass the trial.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nRuga's Bulwark"}
MultiLanguageQuestData['en'][1825] = {title = "Speak with Thun'grim", objective = "Speak with Thun'grim Firegaze in the Barrens.", description = "Thun'grim Firegaze, an orc blacksmith of renown, has heard of your continued deeds of valor in service of the Horde.  He would like to fashion for you a suit of armor, and bids you speak with him immediately.\n\nThun'grim is camped east of the Crossroads in the Barrens.", progress = nil, completion = "Yes, you have come.  This is good, for we have much to discuss, you and I.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1838] = {title = "Brutal Armor", objective = "Bring to Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston.", description = "I have heard tales of your strength and valor, and wish to make for you a suit of armor, a companion to aid you as tales of your great deeds grow.\n\nBut the fashioning of this armor will be a quest unto itself, <name>.  I will need your help, and the help of other smiths of the Horde.\n\nHere, take this scroll.  I spent many nights, struggling with near-blind eyes, writing that which I need for the armor.  Bring me the items on this scroll and I will create for you the first piece of the suit.", progress = "Do you have the items on my scroll, <name>?", completion = "You brought all that I asked.  Now, I will do my part...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1839] = {title = "Ula'elek and the Brutal Gauntlets", objective = "Speak with Ula'elek in Durotar.", description = "The troll smith Ula'elek will craft for you the brutal gauntlets.  He dwells in Durotar, in Sen'jin Village with his Darkspear brethren, and he awaits your coming.", progress = nil, completion = "Greetings, &lt;name&gt;.  Old Thun'grim sent word to me of your coming, but had he kept silent your presence here would not have surprised me.\n\nThe spirits follow your progress, young &lt;class&gt;, and they tell me that many foes have fallen before you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1840] = {title = "Orm Stonehoof and the Brutal Helm", objective = "Speak with Orm Stonehoof in Thunder Bluff.", description = "Orm Stonehoof is respected greatly for his skill.  He will make for you the brutal helm.\n\nSeek him out in Thunder Bluff, near the pool by the city's great, central totem.", progress = nil, completion = "Greetings, &lt;class&gt;.  I am Orm, and Thun'grim tells me you wish a helm made?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1841] = {title = "Velora Nitely and the Brutal Legguards", objective = "Speak with Velora Nitely in the Undercity.", description = "It is said that, before her death, Velora Nitely was one of the finest armorsmiths in Lordaeron.  Death, it seems, has not decreased her talents.  Speak with Velora--she will make your brutal legguards.\n\nVelora plies her trade in the Undercity of Lordaeron, in the trade quarter.", progress = nil, completion = "You are here for leg armor?  Great!\n\nUm... am I making the armor for you, or are you making it for me?\n\nThat was a joke.  Was it funny?  I can't tell... I lost my sense of humor the same time I lost my sense of smell.  Which was about the same time I stopped breathing.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1842] = {title = "Satyr Hooves", objective = "Bring 7 Uncloven Satyr Hooves to Ula'elek at Sen'jin Village in Durotar.", description = "I can make you a pair of brutal gauntlets, and great magic will they hold.  But first, you must collect this magic and bring it to me.\n\nThe satyrs dwell in northeastern Ashenvale because of the forest's power.  They feed off its purity, leeching and corrupting.  You can tell which satyrs have drawn the most of Ashenvale's magic by their swollen, uncloven hooves.\n\nThese hooves hold great power.  I will need them for your gauntlets' crafting.", progress = "Do you have the hooves, <name>?  The magic within them is strong.", completion = "Ah, you have them!  Now, just as the Satyrs leeched the strength of Ashenvale, I will leech the power held within these hooves and harness it into my crafting...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1843] = {title = "Brutal Gauntlets", objective = "Thank you, <name>.  These gauntlets are my best work.  Take them. In wearing them, you bring honor to me and my ancestors.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBrutal Gauntlets"}
MultiLanguageQuestData['en'][1844] = {title = "Chimaeric Horn", objective = "Bring a Galvanized Horn to Orm Stonehoof in Thunder Bluff.", description = "I will make you the helm, but you must show me you are worthy of it.\n\nNestled in the northwestern reaches of the Stonetalon Mountains there lies the Charred Vale.  It was once a verdant place, but is now defiled and ashen, and what creatures remain there are mad with pain and despair.\n\nThat place is where I send you, <name>.\n\nYou must go to the Charred Vale and find a chimaera matriarch.  Slay her, free her of her misery.  Bring me her galvanized horn as proof, and I shall make for you the helm.", progress = "Do you have the horn?  Is the matriarch free of pain?", completion = "You have completed your task, &lt;name&gt;, and shown me your worth and resolve.  The helm will be yours...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1845] = {title = "Brutal Helm", objective = "I give this helm to you.\n\nGreat deeds brought you to me, <name>, and Earthmother willing... even greater deeds lie before you.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBrutal Helm"}
MultiLanguageQuestData['en'][1846] = {title = "Dragonmaw Shinbones", objective = "Bring 8 Sturdy Dragonmaw Shinbones to Velora Nitely in the Undercity.", description = "To make the brutal leg guards, I need a brace of sturdy shinbones.  The Dragonmaw orcs of the Wetlands have nice, thick shinbones.  I'll need theirs.\n\nBut they must be sturdy.  Be sure to test the shinbones as you collect them.  If you can break them with your bare hands, then they won't be sturdy enough to work with.", progress = "I'm waiting for those shinbones, <name>.  They'll make a nice frame for your leg guards.", completion = "Well done!  These all look strong.  I think they'll do quite nicely.  How did those orcs mind you taking their shins, &lt;name&gt;?  Complain much?\n\nThat was another joke.  You're not laughing.\n\nI'm not very funny these days, am I...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1847] = {title = "Brutal Legguards", objective = "Here are your legguards, <name>.  Let me know how they fit or if you need any modifications.  I aim to please!  At least I used to.\n\nThese days I don't care much for my craft.  But it beats being a mindless minion of the Scourge!\n\nI guess.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBrutal Legguards"}
MultiLanguageQuestData['en'][1848] = {title = "Brutal Hauberk", objective = "I am sure you endured much hardship and shed much blood on my task, <name>.  Here is the product of your toil.\n\nMay you wear it well, and may you one day return here with stories of its service to you.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBrutal Hauberk"}
MultiLanguageQuestData['en'][1858] = {title = "The Shattered Hand", objective = "Steal Tazan's key, then use it to open his Satchel and deliver its contents to Therzok in the Cleft of Shadow in Orgrimmar.", description = "I'll leave it to you to get Tazan's satchel open, and return to me with its contents. The locking mechanism is complex, so it would probably be easiest if you obtained the key.\n\nAs you didn't find it on Tazan's body, I can only assume that he left the key in the care of another... Ah, yes, that's right. He had an assistant named Gamon. A drunkard, you'll most likely find him at the tavern. Perhaps you could quietly relieve him of the key.", progress = "Is it not vexing to have the subject of your desire within your grasp, but to have no way of getting to it?", completion = "Hmmm, now this is interesting. You've more than proved your worth with this, &lt;name&gt;. I am quite impressed. Consider yourself the newest member of the Shattered Hand. And take this, it will be a great help to you in the future, I think.", rewards = "You will receive:\n\nBlade of Cunning"}
MultiLanguageQuestData['en'][1859] = {title = "Therzok", objective = "Speak with Therzok in the Cleft of Shadow in Orgrimmar.", description = "Lower your voice, <name>. Yeah, I know your name. Was told to keep an eye out for an orc by your description.\n\nFrom what we've heard about you, you can handle yourself in combat, and aren't opposed to a little sneakery from time to time.\n\nAm I right?\n\nAnyways, you should go see Therzok in Orgrimmar. He's got an offer for you to hear.", progress = nil, completion = "Very good, I'm glad Kaplak was able to get a hold of you.\n\nWe have some things to speak of, not the least of which is your future with the Hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1860] = {title = "Speak with Jennea", objective = "Speak with Jennea Cannon in Stormwind.", description = "We mages have a task that needs doing.  One that is vital to the safety of Stormwind and Elwynn forest.\n\nJennea Cannon has the details.  She studies in the wizard's sanctum, in the mage district of Stormwind.  You should make your way to her with haste.", progress = nil, completion = "You have been sent to aid me in my task, &lt;name&gt;?  Good.  It is heartening to see young mages eager to help in our cause...\n\nWhat cause, you ask?  In time, young one.  You shall know... in time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1861] = {title = "Mirror Lake", objective = "Bring a Mirror Lake sample to Jennea Cannon in Stormwind.", description = "This world has been victim to massive mystic struggles, which tore magic currents from once stable channels.  We struggle to determine the effects these changes have caused, and some of us fear the worst!\n\nBut I will reveal more of this later.  Right now, we need you to gather information.\n\nHere, take this flask.  Go to the base of the waterfall at Mirror Lake, southwest of the Stormwind gates, and retrieve a sample of the water there.  Return it to me so that I might test it for magical taints.", progress = "Do you have the sample, <name>?  The flow of magic in Stormwind and Elwynn has been altered, and I must know if it is seeping into the water.", completion = "Thank you, &lt;name&gt;.  I will test this water for magical properties.  Let us hope that it contains none, or we may find that those who drink from Mirror Lake for too long will be adversely affected.\n\nHere, &lt;name&gt;.  Take this orb or staff as a token of your service.  May it serve you well.", rewards = "You will be able to choose one of these rewards:\n\nLey OrbLey Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1878] = {title = "Water Pouch Bounty", objective = "Back again, <name>?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", description = nil, progress = "Back again, <name>?  If you have five more Wastewander water pouches, then I have a care package with your name on it!", completion = "Excellent - the more water pouches we are able to reclaim, the further away from disaster we'll all be!  Keep 'em coming, and I will be sure to reward you for every five water pouches you bring me.", rewards = "You will receive:\n\nGadgetzan Water Co. Care Package"}
MultiLanguageQuestData['en'][1879] = {title = "Speak with Bink", objective = "Speak with Bink in Ironforge.", description = "<name>!  Bink, my gnome colleague in Ironforge, sends word.  She has a task that needs doing and won't rely on anyone but a mage to do it!  Are you that mage, <name>?\n\nIf so, then speak with Bink.  She spends her time in the Hall of Mysteries in the Mystic Ward of Ironforge.", progress = nil, completion = "Oh, I can see you have promise, yes you do! But it takes more than promise to be a good &lt;class&gt;.  And if you're not a good &lt;class&gt;, then you're a bad &lt;class&gt;.  And bad mages are part of the problem, yes they are!\n\nOops, I'm getting ahead of things.  Let's begin at the start!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1880] = {title = "Mage-tastic Gizmonitor", objective = "Bring Bink her Mage-tastic Gizmonitor.", description = "We mages do more than just waggle our fingers and make pretty sparks!  We control magic, the base fabric of our world!  And that takes great care, and resolve.  And knowledge... so much knowledge!\n\nOne of my devices, the mage-tastic gizmonitor, collects and stores that knowledge in huge amounts!  But it's lost!  When we fled our home of Gnomeregan, I left it in a chest in one of our huts outside the city, and now the place is crawling with leper gnomes!\n\nPlease, <name>, retrieve my gizmonitor!", progress = "Did you find the gizmonitor?  I must have it before its energy supply runs out!", completion = "Oh, splendid day!  When I made the gizmonitor I never realized how dependent on it I would become.  Now I can begin my studies anew!\n\nThank you, &lt;name&gt;!  And here--these were my first tools as a &lt;class&gt;.  They're a little scratched but they're well tested.  Take your pick--I'm sure you'll find either of them useful.", rewards = "You will be able to choose one of these rewards:\n\nArcane OrbArcane Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1881] = {title = "Speak with Anastasia", objective = "Speak with Anastasia Hartwell.", description = "<name>, Anastasia Hartwell has a task for someone of your talents.  Speak with her in the Magic Quarter of the Undercity, and prepare yourself for your first task for the mages of the Forsaken.", progress = nil, completion = "Greetings, &lt;name&gt;.  You were wise to answer my call, and wiser still if you heed what I next say...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1882] = {title = "The Balnir Farmstead", objective = "Bring Balnir Snapdragons to Anastasia Hartwell in the Mage Quarter of the Undercity.", description = "The Plaguelands to the east are an aberration.  Devised by the Lich King, they spread their magic into the soil, corrupting and killing all that live.  Although there is a certain charm to the destructive forces of the plague, we, the mages of the Forsaken, believe it is unruly and must be curtailed.\n\nBut first, we must measure how far it has spread into Tirisfal.  Go to the Balnir Farmstead in eastern Tirisfal.  In the garden are flowers--snapdragons.  Gather these and return.", progress = "Do you have the snapdragons?  That breed of flower is highly receptive to magic energies, and studying the snapdragons so close to the Plaguelands can tell us if the plague has entered Tirisfal Glades.", completion = "Ah, a fine specimen this is.  I will send it to be studied by our apothecaries to determine the extent of the Plagueland's taint.\n\nWell done, &lt;name&gt;.  For your services, I present to you this choice: an orb or staff.  Whichever you choose, you will find it quite useful.", rewards = "You will be able to choose one of these rewards:\n\nArcane OrbArcane Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1883] = {title = "Speak with Un'thuwa", objective = "Speak with Un'thuwa.", description = "Un'thuwa, tribal mage of Sen'jin Village, detects a disturbance in the magic currents of Durotar and asks for aid.  Speak with Un'thuwa and do what you can to help him.\n\nDo this, and in time further secrets will be revealed to you.", progress = nil, completion = "Hail, &lt;name&gt;.  Praise to you, for my call for aid is now answered.  Let us hope you are up to the task...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1884] = {title = "Ju-Ju Heaps", objective = "Destroy 4 Ju-Ju Heaps, then return to Un'thuwa in Sen'jin Village.", description = "The warlock Zalazane of the Echo Isles has disrupted the normal flow of magic in Durotar.  He does this through tainted fetishes, ju-ju heaps, which he has placed among his huts on the main Echo Isle.\n\nThese heaps corrupt our wildlife and give power to the warlocks and infernal creatures that lurk in the land's dark corners.\n\nYou must destroy the ju-ju heaps, <name>, before the flow of magic is forever altered.", progress = "You must hurry, <name>.  Destroy the ju-ju heaps!", completion = "I sense that Zalazane's ju-ju heaps were destroyed, and with time, and luck, the flow of magic in Durotar will return to normal.\n\nA great deed you have done for your people, &lt;name&gt;.  And you have shown your worth to us, the mages of the Horde.", rewards = "You will be able to choose one of these rewards:\n\nLey OrbLey Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1885] = {title = "Mennet Carkad", objective = "Speak with Mennet Carkad in the Rogues' Quarter of the Undercity.", description = "<name>? Not quite what I was expecting, considering Carkad himself has taken an interest to you. Looks can be deceiving though, right?\n\nEither way, you should go see him as soon as possible. You wouldn't want to know what happened to the last few that chose to ignore his summons.", progress = nil, completion = "Hm. No doubt you made your way here at first mention of my summons, yes? Of course. I would expect no less from a prospective Deathstalker.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1886] = {title = "The Deathstalkers", objective = "Get Astor's Letter of Introduction and return it to Mennet Carkad in the Rogues' Quarter.", description = "If you wish to join the Deathstalkers, Lord Varimathras' elite guard, you will have to prove your worth.\n\nI will not lie to you, <name>, this task could mean your death.\n\nI have some things that need attending to. I require the personal effects of Astor Hadren, a messenger who travels between Silverpine and the Undercity. I will leave the method of procurement to your discretion.\n\nIt will be better for you if you know less of the nature of this business. Succeed and I shall tell you more.", progress = "Success to report?", completion = "Well done, &lt;name&gt;. You've passed the first part of this test. Hopefully Andron will not have caught wind of your activities, and we will be able to convince him that you are, in fact, the messenger he is expecting.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1898] = {title = "The Deathstalkers", objective = "Speak with Andron Gant in the Undercity.", description = "The letter of introduction should be enough to convince Andron that you are the messenger he's been waiting for. I've met Andron before, he doesn't quite have the mental capacity to be that suspicious.\n\nLord Varimathras suspects that Andron has been providing aid to some other group. He wishes to know what organization this is and requires proof of it.\n\nI want you to speak with Andron, and obtain this information. You'll find him at his shop near the Apothecarium.", progress = "Hello. Something I can do for you?", completion = "Ah, yes, I've been expecting you. I have no doubt our mutual acquaintances are pleased with the information that I have provided so far?\n\nI suppose there's no point in asking you, I doubt they would burden you with this knowledge. Why place so much trust in the messenger, hm?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1899] = {title = "The Deathstalkers", objective = "Bring Andron's Ledger to Mennet Carkad in the Rogues' Quarter of Undercity.", description = "You'll find the ledger with the information your employers seek on the bookshelf behind me. Deliver it with my regards, and tell them that I would prefer it if they sent you, if they find enough value that they should wish to continue our arrangement.", progress = "Success, <name>?", completion = "Well, this is certainly more information than I suspected to get out of Andron. Give me a moment to peruse it, before I set you to your next task.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1918] = {title = "The Befouled Element", objective = "Bring the Befouled Water Globe to Mastok Wrilehiss at Splintertree Post, Ashenvale.", description = "The slain elemental has produced an intensely glowing globe of water.  The contents of the globe are, at best, disgusting.  It would be safe to assume that whatever has befouled the water of Mystral Lake is most likely present in the water of the globe.\n\nIt's not exactly common knowledge who might be interested in such a find; perhaps the person who originally sent you out to the lake, Mastok Wrilehiss at Splintertree Post, might have an idea.", progress = "Yeah, what do you need?", completion = "You find a nasty ball of water and decide to bring it to me?  Who am I, the Earthen Ring or something?\n\nActually, that does give me an idea... perhaps you do need the Earthen Ring for this.  I mean, if it helps clear up the situation at the lake for good, then I'm all for it.\n\nYou know who the Earthen Ring are, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1919] = {title = "Report to Jennea", objective = "Speak with Jennea Cannon in Stormwind.", description = "Your knowledge of the craft grows, young <name>.  Are you now ready to begin your true lessons?  Are you ready to take your place in the secret war we wage?\n\nIf so, then speak with Jennea Cannon, in the wizard's sanctum in the mage district of Stormwind.  She has a task for you which will open your first window into the invisible world.", progress = nil, completion = "&lt;name&gt;, I have a mission for you, here in the &lt;class&gt; district.  Listen closely, for there is no time to waste.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1920] = {title = "Investigate the Blue Recluse", objective = "Obtain a Cantation of Manifestation and a Chest of Containment coffers from behind Jennea Cannon. Bring 3 Filled Containment Coffers to Jennea at the Wizard's Sanctum.", description = "A disturbance has been reported at the Blue Recluse tavern in the Mage Quarter.  Strange, invisible creatures now wander the tavern, and I fear a mana rift has formed there.\n\nI want you to investigate the tavern and capture those creatures.  Use the cantation of manifestation in the tavern to make the creatures visible, subdue them then use a containment coffer to capture them.  When you have enough, return to me with your filled coffers, your empty coffers and the cantation.", progress = "Have you captured the creatures, <name>?  They must be studied in order to determine the reason behind their arrival.", completion = "Very well done!  I will study these creatures and, with diligence and luck, determine how they slipped into our world.\n\nYour value to the society of mages grows, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1921] = {title = "Gathering Materials", objective = "Bring 10 Linen Cloth and the 6 Charged Rift Gems to Wynne Larson in Stormwind.", description = "You have served your fellow mages well, and now it is time to don your wizard's robe.  Wynne Larson can make your robe, but you must bring her the needed materials  \n\nThe robe will be made of linen which is easy to find, but you must also gain charged rift gems, and the only known location of the gems is in the Silver Stream Mine of Loch Modan, left in crates by the dwarven miners' league.\n\nGather the linen and the gems and bring them to Wynne Larson at the Larson Clothiers in the Mage District.", progress = "Hello, <name>.  Jennea told me you would come.  Do you have something for me?", completion = "Yes, these are great pieces of linen.  I can make a fine robe with them.  And after I weave the rift gems into it, we'll have a garment fit for a &lt;class&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1938] = {title = "Ur's Treatise on Shadow Magic", objective = "Bring Ur's Treatise on Shadow Magic to High Sorcerer Andromath in Stormwind.", description = "Long ago, three mages studied in this tower until one fell to the dark arts.  He was urged to turn away from that evil magic, but he could not resist.  And so he was banished.\n\nThe fallen mage's new domain is the tower of Ilgalar in Redridge, and he took with him a powerful book--Ur's Treatise on Shadow Magic.\n\nWe, the mages of Stormwind, would have that book returned.  Enter the tower of Ilgalar, find the tome in his library, and bring it to me.", progress = "Do you have the book, <name>?  Its secrets are not meant for the untrained, and plumbing its depths can lead to doom and ruin.", completion = "I feared that Morganth had hidden the book elsewhere, or that he had found a way to open it and read its contents.\n\nIt is good to see that he did not, and that the seals we placed on Ur's Treatise on Shadow Magic still hold.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1939] = {title = "High Sorcerer Andromath", objective = "Speak with High Sorcerer Andromath.", description = "High Sorcerer Andromath wishes to speak with you, <name>.  He is at the top of the wizard's sanctum, in the mage's district of Stormwind.\n\nIt would be wise to speak with him, for Andromath is one of the most powerful mages not locked away in Dalaran.  Council with him is high council indeed.", progress = nil, completion = "Greetings, &lt;name&gt;.  I am pleased to see you, and hope you have time to listen to an old man's words...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1940] = {title = "Pristine Spider Silk", objective = "Bring 8 Pristine Spider Silk to Wynne Larson in Stormwind.", description = "Your service has been unwavering, <name>.  I think, perhaps, it is time you had a finer garment, one more suiting your station as an adept mage.  If you gather the needed materials, then we will arrange the robe made.\n\nYou must enter Duskwood and hunt carrion recluse spiders.  Extract their silk, but only the finest, most pristine silk will do.  When you have enough, take it to Wynne Larson, here in the mage district at the Larson Clothiers.  She will craft your robe.", progress = "Ah, yes.  The mages of the Wizard's Sanctum said you'd speak with me.  Do you have the required silk?", completion = "Nice specimens, these.  I'll get right to work!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1941] = {title = "Manaweave Robe", objective = "Here is your robe.  It's one of my best made yet!  Wear it with pride, and when people ask... tell them you got it at the Larson Clothiers!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nManaweave Robe"}
MultiLanguageQuestData['en'][1942] = {title = "Astral Knot Garment", objective = "Your garment is ready!  And that silk you gathered was so nice... you don't mind if I made it a little short so that I'd have some silk left over for me, do you?\n\nI'm only joking.  It'll fit you great, and will be perfect for both adventure and formal dining.  Enjoy!", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nAstral Knot RobeAstral Knot Blouse\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1943] = {title = "Speak with Deino", objective = "Speak with Deino.", description = "The troll mage Deino has need of your assistance, <name>.  She resides in Orgrimmar, in the Darkbriar Lodge.", progress = nil, completion = "Good, you have come.  My task is not an easy one, but vital to the society of mages.  If you aid me, I am sure you will find it worthwhile.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1944] = {title = "Waters of Xavian", objective = "Bring the Xavian Water Sample to Deino in Orgrimmar.", description = "The fabled city of Xavian lies nestled deep within eastern Ashenvale, and tales of its ancient knowledge are well known among the learned.  It is said that the waters of Xavian hold vast magical powers.\n\nI would have a sample of those waters, from their source.\n\nTake this flask and go to Xavian.  Gather water from the bottom of its highest waterfall, and return to me.  And use care as you move through that ancient city--satyrs now hold the ruins and do not like mages prying into their affairs.", progress = "I am pleased you have returned with your skin intact, <name>.  Do you have the water sample?  I am eager to study its properties.", completion = "Ah, very good.  I trust the satyrs of Xavian gave you little trouble?\n\nThank you, &lt;name&gt;.  I will study this sample of Xavian water immediately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1945] = {title = "Laughing Sisters", objective = "Bring 12 Laughing Sister's Hairs to Kil'hala at the Crossroads.", description = "For your services, I have arranged for the creation of your new robes, provided you can gather the needed materials...\n\nFor these robes, you must return to Ashenvale for the locks of hair from laughing sisters--dryads who gather near the Raynewood Retreat.\n\nWhen you have their hair, bring it to Kil'hala, a troll tailor at the Crossroads in the Barrens.  He will be expecting you, and will fashion your robes.", progress = "Greetings, <name>.  Deino said you would come, and would bring the laughing sisters' hair.  Do you have it?", completion = "Ah, this hair will weave into a fine robe, &lt;name&gt;.  It is a pity the laughing sisters had to die to part with it, though I do doubt they would ever give it willingly.\n\nA pity, but only a small one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1946] = {title = "Nether-lace Garment", objective = "Here is your nether-lace, <name>.  It is both comfortable and durable, and holds the magic of the laughing sisters' hair.\n\nEnjoy, and if you find it amenable, please mention so to Deino.  She is a <class> on whose good side I wish to stay...", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nNether-lace RobeNether-lace Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1947] = {title = "Journey to the Marsh", objective = "Speak with Tabetha.", description = "Now it is time for you to earn your mage's wand.  To begin this quest, speak with the human hermit Tabetha in Dustwallow Marsh.  You will find her shack deep in the marsh, west of Theramore.\n\nSpeak with her, for her knowledge is vast.  You will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruins.", progress = nil, completion = "Quiet!  I'm in a delicate juncture and mustn't be disturbed!\n\nOne moment...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1948] = {title = "Items of Power", objective = "Bring 1 Jade and the Bolt Charged Bramble to Tabetha in Dustwallow Marsh.", description = "The building of a mage's wand is not easy.  Rare substances are required, and a vessel must be made that can store great quantities of magical energy.  You must gather these things and bring them to me.\n\nI have written onto this parchment that which you need, and instructions on how to get it.  Bring me exactly what is on this list, and follow my written directions to the letter, for if you do not then when we make your wand things might go... badly.", progress = "Hello, <name>.  Do you have the items I require?", completion = "Aha!  You got the jade and made the bramble!  Well done!\n\nIs that smoke I see rising from your ears?  You might have gotten too close when the lightning struck the totem sticks, but don't worry.  Being hit by lightning is good luck!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1949] = {title = "Hidden Secrets", objective = "Speak with Magus Tirth in the Shimmering Flats.", description = "To make your wand, there are key passages in a certain book that I must read.  The book is called Rituals of Power, written by the Magus Tirth.\n\nI do not have a copy of his book, and none of the world's great libraries possess it.  So you must speak with Tirth and gain it from him.\n\nGood luck.  Tirth used to be a great mage and scholar, but now he spends his time at the gnome and goblin races in the Shimmering Flats, drinking and gambling.", progress = nil, completion = "What?  Speak up!  These old ears aren't as sharp as they used to be.\n\nWell, I hope you're here with a fresh mug of ale or some hot tips on the next race!  If not, then you best keep walking... because I have a polymorph wand with your name on it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1950] = {title = "Get the Scoop", objective = "Find the phrase to Tirth's strongbox, then return to Tirth.", description = "I can help you with the book, but first you have to help me!\n\nThe tome you seek is in my magically locked strongbox.  To open it a special phrase must be uttered, and I can't remember the phrase!  Normally my assistant helps me remember these things but he's nowhere to be found.\n\nIf you want my book, then find my apprentice!  Ask around the race track--if you're lucky then someone has seen him.  Either drag him back here, or at least get my magic phrase from him so we can open my box!", progress = "What are you waiting for?  I need my magic phrase!", completion = "Ah, now I remember...\n\nI had forgotten about that little curse I put on Johnson.  I can't remember why I did it but I'm sure it served him right, the little ingrate!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1951] = {title = "Rituals of Power", objective = "Bring the book Rituals of Power to Tabetha in Dustwallow Marsh.", description = "Hm... now that I think about it, I don't have my book!  You see, I had some gambling debts and to pay them off I sold the last copy of Rituals of Power to a member of the clergy....\n\nA member of the Scarlet Brotherhood.  He must have taken it to their library in the Scarlet Monastery in Tirisfal Glades!\n\nIf you want that book, then you'll have to go to the monastery to find it.  And sorry about all the trouble.  I'm not myself these days...", progress = "Greetings, <name>.  Did you find the book, Rituals of Power?", completion = "That's it!  It's just what I need to prepare for the ritual to create your wand!  I hope it wasn't too much trouble to find...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1952] = {title = "Mage's Wand", objective = "Speak with Tabetha after her ritual.", description = "I'll go make the wands now.", progress = nil, completion = "Here are the wands I made.  Take your pick!", rewards = "You will be able to choose one of these rewards:\n\nIcefury WandNether Force WandRagefire Wand\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1953] = {title = "Return to the Marsh", objective = "Speak with Tabetha.", description = "It is time, <name>, for you to speak with Tabetha... the hermit of Dustwallow Marsh.  She will instruct you on the creation of a powerful mage's implement.\n\nTabetha's shack lies deep in Dustwallow Marsh, west of Theramore.", progress = nil, completion = "Ah, yes.  You are here for an orb or a staff, &lt;name&gt;?  Very well.  I will aid you in its construction.\n\nBut be forewarned--the process is a perilous one and could mean your death.\n\nOr my death.  Definitely someone's death... \n\nBut let's hope it's someone else's death, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1954] = {title = "The Infernal Orb", objective = "Bring an Infernal Orb to Tabetha in Dustwallow Marsh.", description = "The first step is to acquire an orb with power.  The warlocks of the Burning Blade have nice, high quality orbs... it's too bad they've bound demons into them!  But we can fix that, yes we can.\n\nGo to Desolace and snatch an infernal orb from a Burning Blade summoner.  You'll find summoners at the Mannoroc Coven.\n\nWhen you have the orb, return to me.", progress = "Do you have an infernal orb, <name>?", completion = "Oh, that's a nice one!  No, I don't mean it's \"nice\" like cool juice is nice on a hot day.\n\nIn fact, it's very NOT nice now that I think about it.  Not the juice.  The orb!\n\nFocus, &lt;name&gt;!  We'll need you focused if we're ever to finish our task!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1955] = {title = "The Exorcism", objective = "Kill the Demon of the Orb, then speak with Tabetha.", description = "Now that we have a summoner's orb, we must exorcise the demon within it.  I can do that.  That's the easy part.\n\nYou're the one who has the hard job.  You're the one who has to kill the demon once it's out.\n\nAnd you'll have to be quick.  If you take too long then he'll jump back in the orb and we'll have to start over!\n\nSo get yourself ready.  Prepare your strongest spells and keep your potions handy, and go get a friend if you have one.  Because this isn't going to be pretty.", progress = nil, completion = "Nicely done, &lt;name&gt;!  You gave that demon a lesson he won't soon forget.\n\nHe'll think twice before he sticks his ugly head back in this world, looking for the stupid mortal who beat him.  Probably with friends this time.  Big, scaly friends who'd want nothing more than to tear you into little &lt;race&gt; pieces.\n\nI didn't scare you, did I...&lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1956] = {title = "Power in Uldaman", objective = "Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh.", description = "Now that the demon has been removed, we must gain a power source.  Unfortunately, the best power sources are usually the oldest and the hardest to get.  It's neat how fate likes to take a bite out of you sometimes, isn't it?\n\nSo you're going to need to go to Uldaman and defeat the obsidian sentinel there.  He's big, he's tough, and his power source packs a punch!\n\nI wish you the best of luck, <name>.  And if you don't get lucky then, well... it was nice knowing you.", progress = "Have you been to Uldaman, <name>?  Did you defeat the obsidian sentinel?", completion = "You did it?  Well done!\n\nI was chatting with some of my colleagues and when your name came up they said, \"You know that &lt;name&gt; sure works well under stress!\"\n\nBut when I told them I sent you to Uldaman against the obsidian sentinel, they said I was crazy!  They said, \"Tabetha, you're crazy!  There's no way &lt;name&gt; could take on that sentinel!\"\n\nAnd I said, \"We'll see,\" and then they said \"Yeah, we'll see...\"\n\nWell we sure showed them, didn't we!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1957] = {title = "Mana Surges", objective = "Kill 12 Mana Surges in the allowed time limit.", description = "We are almost finished, but this last step is the most perilous, <name>.\n\nI have the empty summoner's orb and am ready to empower it.  We will do this by harnessing the energy of a mana rift.  I'll cast a spell that will temporarily open a rift, from which creatures, mana surges, will pour out.  You must defeat the mana surges and their power will be released, which I will then collect.\n\nKill enough mana surges before the rift closes and I will place all their collected energy in your orb.", progress = "You have not killed the required amount of mana surges, <name>.", completion = "You did it!  I never doubted you for a second!  Ok, maybe for just a second, or two... but basically I didn't have much doubt.\n\nHonest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1958] = {title = "Celestial Power", objective = "You should be proud of yourself, <name>.  Many mages have fallen to the creatures you faced.\n\nThe Celestial Orb is ready.  Or if you'd like I can mount it atop a staff.  It's up to you.  I'd prefer the orb, but who am I to judge?", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nCelestial OrbCelestial Stave\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][1959] = {title = "Report to Anastasia", objective = "Speak with Anastasia Hartwell.", description = "The mages of the Undercity have noted a magical disturbance within the city, and have sent word for mages of the Horde to investigate.\n\nAnastasia Hartwell can tell you more.  Speak with her in the Magic Quarter in the Undercity.", progress = nil, completion = "It is true.  A magical disturbance has been detected in our city.  We are not yet sure of its origin, or whether it is malign or benign.  We must first gather more information...\n\nAnd that, &lt;name&gt;, brings us to your task.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1960] = {title = "Investigate the Alchemist Shop", objective = "Obtain a Cantation of Manifestation and a Chest of Containment Coffers from behind Anastasia Hartwell. Bring 3 Filled Containment Coffers, the Chest of Containment Coffers and the Cantation of Manifestation to Anastasia in the Undercity.", description = "Algernon's alchemist shop in the Apothecarium is the locus of a strange disturbance.  Invisible creatures, made solely of magic, wander the shop--there must be a reason, and we must find it!\n\nInvestigate the disturbance and capture those creatures.  Take a chest of coffers and a scroll from behind me.  Use the scroll at the shop to make the creatures visible, subdue them with your spells, then throw down a coffer to capture them.  Return with the filled coffers, the empty coffers and the cantation.", progress = "Have you investigated the disturbance, <name>?  Have you captured the creatures?", completion = "Very good, &lt;name&gt;.  The creatures within these containment coffers will be studied by our finest minds, and the reason behind their presence in the Undercity will be determined.\n\nIf their appearance is caused by a rift in the natural flow of magic, then we must determine if the rift was random.  If it was not random, but instead an attack by some magical force, then we must prepare for future, more serious disturbances.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1961] = {title = "Gathering Materials", objective = "Bring 10 Linen Cloth and 6 Dalaran Mana Gems to Josef Gregorian.", description = "It is time for you to don your first mage's robes, <name>.  They are a sign of your station, and a testament to your worth.\n\nTo gain the robes, you must gather the mana gems from the Dalaran mages of Silverpine.  Their beliefs are similar to ours and so killing them is somewhat distasteful, but if they lack the strength to resist us, then they do not deserve their lives.\n\nBring the gems and a supply of linen to Josef Gregorian at the Magic Quarter's tailor shop.", progress = "Anastasia said you would come to me, and I am prepared to fashion your robes.  Do you have the gems and the linen?", completion = "This is very good material, and although I lack the talent to gauge the quality of these mana gems, we'll soon know if they possess the power needed to create spellfire robes...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1962] = {title = "Spellfire Robes", objective = "Here are your robes, <name>.  Wear them well.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nLesser Spellfire Robes"}
MultiLanguageQuestData['en'][1963] = {title = "The Shattered Hand", objective = "Kill Tazan and bring his Satchel to Therzok in the Cleft of Shadow in Orgrimmar.", description = "The Warchief is too subtle in his methods. He is cautious to unleash the might of the Horde. Once we were stronger, mighty conquerors all. That pride we must regain, and the Shattered Hand will do so.\n\nWe build strength from the shadows and strike at the exposed, secretly laying our enemies low. A task you must complete for me, to prove your worth.\n\nThe troll Tazan trades with the pirates near Ratchet. He has information I must have. Kill him and bring me his satchel.", progress = "It is a fool who believes a charge with axe drawn is more dangerous than a knife in the dark.", completion = "Hm, while I am glad to hear that Tazan is no longer with us, a locked satchel does us no good. We need the information kept within.\n\nThis should prove a worthy second challenge for one who wishes to join the Shattered Hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1978] = {title = "The Deathstalkers", objective = "Deliver Andron's Ledger to Varimathras in the Hall of the Dark Lady in the Undercity.", description = "The Syndicate? I would never have suspected. It seems the lords of Alterac have fallen far in the years since their betrayal.\n\nLord Varimathras will be pleased to learn of this, and as you were so instrumental in this discovery, it would be fitting if you were the one to deliver it to him.\n\nAh, and how could I forget?\n\nWelcome to the Deathstalkers.", progress = "Yes?", completion = "Hmm, this is interesting. The Deathstalkers have performed their duties admirably in ferreting this out.\n\nFrom what I understand, you also deserve commendation for your performance. I hope that this will become routine for you, &lt;name&gt;, my Deathstalkers always have use of a good man.", rewards = "You will receive:\n\nBlade of Cunning"}
MultiLanguageQuestData['en'][1998] = {title = "Fenwick Thatros", objective = "Kill Fenwick Thatros and bring his head back to Mennet Carkad in the Rogues' Quarter of the Undercity.", description = "Lord Varimathras has just sent me a missive about a threat to the Forsaken that must be immediately removed. His name is Fenwick Thatros, one whom Lord Varimathras believes is a leader of the undead that have taken root in Silverpine Forest.\n\nYour name came to mind immediately, <name>. I have faith enough in your abilities that you will carry out this mission flawlessly.\n\nThe latest reports from the Deathstalkers in Silverpine indicate that Thatros can be found near the decrepit dock on Lordamere.", progress = "I have placed the utmost faith in you to perform this service for Lord Varimathras.", completion = "You've done well, &lt;name&gt;. It occurs to me that you have performed many services for the Deathstalkers, proving your worth, and that perhaps it is time that we furthered your training in the shadow arts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][1999] = {title = "Tools of the Trade", objective = "Find the Dalaran Status Report and return it to Mennet Carkad in the Rogues' Quarter of the Undercity.", description = "The wizards of the Kirin Tor at Ambermill have stored away important documents pertaining to the current state of Dalaran. This we know from the admissions of one of our prisoners. Lord Varimathras has placed the duty of recovering them in the hands of the Deathstalkers.\n\nThis task falls to you, <name>. You will need some equipment, however, and the knowledge of lockpicking. Speak with Estelle Gendry, our outfitter, and ask her for a set of tools before you set out.", progress = "Have you located the documents, <name>?", completion = "Very good, &lt;name&gt;! You have learned the fine art of lockpicking well, and faster than I could have possibly expected.\n\nI see that I was right to place my trust in you. Believe me, boy, I foresee that you will go far in this line of work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2000] = {title = "Rokar Bladeshadow", objective = "Speak with Rokar Bladeshadow in Durotar.Too much idle time for you, <name>. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.\n\nSo it is I've decided you should learn the art of lockpicking.\n\nUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Too much idle time for you, <name>. It's time that you learned more of our trade. Just last night, five of our number were found dead in one of the cracks in Orgrimmar, with few leads. There are those that oppose us, using our own methods against us.\n\nSo it is I've decided you should learn the art of lockpicking.\n\nUnfortunately, it is a skill that my hands are not well suited to. You should seek out Rokar, who lives in the hills near Durotar. Even in his old age, I suspect he still has the touch for it.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2038] = {title = "Bingles' Missing Supplies", objective = "Find and return Bingles' supplies:\n\nBingles' Wrench, Bingles' Screwdriver, Bingles' Hammer, and Bingles' Blastencapper.", description = "As if crashing into the Loch wasn't bad enough, troggs from the nearby island attacked me and stole my tools and special Blastenheimer Blastencapper explosives. With no gyrocopter and no explosives, the movement has no chance!\n\nGet my tools back and find my Blastencapper explosives, <name>. For Gnomeregan!", progress = "<name>! Where are my things?!", completion = "You've done the movement a great service, &lt;name&gt;. The troggs and leper gnomes infesting Gnomeregan will soon feel the brunt of a gnomish air assault!", rewards = "You will receive:\n\nBingles' Flying Gloves"}
MultiLanguageQuestData['en'][2039] = {title = "Find Bingles", objective = "Find Bingles Blastenheimer in Loch Modan.", description = "We've lost contact with Bingles! He was sent on a reconnaissance mission over Gnomeregan and hasn't reported back in over a week. I just know he's gone and blown himself up.\n\nHe was last seen flying over the Loch. Perhaps you can investigate, <name>.", progress = nil, completion = "So Gnoarn doesn't trust my reconnaissance abilities? I wonder why...\n\nNevermind that, I need your assistance! Nay! The movement needs your assistance!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2040] = {title = "Underground Assault", objective = "Retrieve the Gnoam Sprecklesprocket from the Deadmines and return it to Shoni the Shilent in Stormwind.", description = "Gnomeregan has fallen under the control of those dastardly troggs! The situation is grave but perhaps you can help, <name>.\n\nDeep in the Deadmines is a functional goblin shredder. Find that shredder and bring back the intact power supply. With the shredder's power supply, we can give our gyrodrillmatic excavationators the power they need to break through the rocky underground borders of Gnomeregan, opening the way for a gnomish assault!", progress = "Have you found the Gnoam Sprecklesprocket, <name>?", completion = "Well done, &lt;name&gt;. Thanks to you, Gnomeregan is one step closer to its day of liberation!", rewards = "You will be able to choose one of these rewards:\n\nPolar GauntletsSable Wand\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2041] = {title = "Speak with Shoni", objective = "Speak with Shoni the Shilent in Stormwind.", description = "Perhaps... Perhaps you can help us in the battle for Gnomeregan.\n\nIn Stormwind you will find the commander of our underground assault crew, Shoni the Shilent. Shoni needs assistance with her gyrodrillmatic excavationators.\n\nYou will probably find her amongst the dwarves in Stormwind.\n\nGood luck, <name>.", progress = nil, completion = "Do you bring word from central command?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2078] = {title = "Gyromast's Revenge", objective = "Find Gelkak's First Mate, the Threshwackonator 4100, and lead it back to Gelkak.", description = "Landlubber, ye needs to find me first mate.\n\nTake this'n key, puts it in his gulliver an' bring him back here to serve the Cap'n.\n\nThem murlocs an' their chief ain't gonna be too happy once me first mate gets a hold of em!", progress = "Where be me first mate, <name>? Shackles n' sharks fer ye soon if ye don't hurry!", completion = "Yarrr... Ye be provin' yerself to be more than a yella sea dog, landlubber.\n\nThe Cap'n may promote ye to poop deck swabby if ye be keepin' this up...", rewards = "You will receive:\n\nElixir of Water Breathing"}
MultiLanguageQuestData['en'][2098] = {title = "Gyromast's Retrieval", objective = "Find and return the three pieces of Gelkak's Key to Gelkak Gyromast.", description = "A pirate's life ain't an easy one, landlubber. It ain't all about plunderin' and booze! Alas, me ship be sunk just off shore thanks to them pesky Threshadons.\n\nWhat I be needin' is me first mate back in workin' order!\n\nWhen I washed up'n shore, the key for me first mate broke on the rocks and was pilfered by the beasties of Darkshore. Out of the corner of me eyes I saw some of them Ragin' Crawlers, Ferocious Foreststrider, and murloc rummaging through the wreckage....", progress = "Have ye found me broke down key, landlubber?", completion = "Avast ye scurvy sea dog! Ye did it! Soon me first mate be back in workin' order and them beasties won't know what hit em!\n\nHrm, have ye seen me first mate?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2118] = {title = "Plagued Lands", objective = "Capture a living Rabid Thistle Bear and bring it back to Tharnariun.\n\nShould you fail to capture a Rabid Thistle Bear and lose your trap, return to Tharnariun Treetender and request another trap.", description = "A sickness spreads across the Darkshore, gripping the minds and bodies of all it touches.\n\nThe Thistle Bears have been hit the hardest by this plague. The once noble beasts are now an instrument of destruction - rabid and frenzied. I may have a cure for this ailment.\n\nTake this trap to the forest and lay it on the ground. Any Rabid Thistle Bear that crosses the light shall become docile for a short time. Once the bear is docile, it shall follow you. Lead it back here, <name>.", progress = "Have you brought me the sick animal, <name>?\n\nShould you fail to spring the trap, do not fret - Tharnariun's Hope is eternal. If you require another trap, abandon your task and report back to me.", completion = "Our work has only just begun, &lt;name&gt;. Are you prepared for your next task?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2138] = {title = "Cleansing of the Infected", objective = "Cleanse the forest of 20 Rabid Thistle Bears and return to Tharnariun Treetender in Darkshore.", description = "As I had feared, the cure does not work.\n\nIt saddens me greatly to order the death of any of nature's beasts, but the sick and tainted thistle bears must be put down.\n\nReturn to the forest and destroy 20 rabid thistle bears, <name>. It will most certainly not put a stop to the plague but it will slow down the damage the animals are doing to our forest and its inhabitants for a short time.", progress = "Is your task complete?", completion = "You have done Auberdine a great service, &lt;name&gt;, but your task is not yet complete.\n\nReturn to me once you have rested.\n\n...and &lt;name&gt;, prepare your mind and soul for more bloodshed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2139] = {title = "Tharnariun's Hope", objective = "Find and kill the Den Mother.", description = "The survival of our people and lands comes at unfortunate costs, <name>.\n\nYou have spilled the blood of nature's servants; many sick animals you have felled. The people of Auberdine are indebted to you, for the forest's pain is eased - even if only for a moment.\n\nI have one final task for you, but be warned, you will have to kill again. It is my hope that this will be the last time I call upon you, <name>.\n\nIn a cave to the northeast, near Bashal'Aran, resides the Den Mother. Slay her.", progress = nil, completion = "You have fought for Auberdine with bravery and honor, &lt;name&gt;. In our war torn lands, death and despair are common. Many will not rise to meet the challenge of life in our new home, choosing instead to hide in their homes or escape to the more fortified lands of the Alliance.\n\nThank you, &lt;name&gt;. Perhaps someday soon we shall fight along side as comrades versus another foe.", rewards = "You will be able to choose one of these rewards:\n\nEvergreen GlovesTimberland Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2158] = {title = "Rest and Relaxation", objective = "Speak with Innkeeper Farley at the Lion's Pride Inn.", description = "Every adventurer should rest when exhaustion sets in - and there is no finer place to get rest and relaxation than at the Lion's Pride Inn!\n\nMy best friend, Innkeeper Farley, runs the Lion's Pride. If you tell him I sent you, he may give you the special discounted rates on food and drink.\n\nTo find the Lion's Pride Inn, travel south along the road from here -- you can't miss it!", progress = nil, completion = "Rest and relaxation for the tired and cold -- that's our motto! Please, take a seat by the fire and rest your weary bones.\n\nWould you like to try a sampling of some of our fine food and drink?", rewards = "You will be able to choose one of these rewards:\n\nSmall PumpkinRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2159] = {title = "Dolanaar Delivery", objective = "Bring the Dolanaar Delivery to Innkeeper Keldamyr.", description = "Greetings, young <class>.  Can you offer me aid?  I have a package of herbs that I must deliver to the town of Dolanaar.  But I still have business with the druids of Shadowglen and cannot yet leave.\n\nCan you deliver this package for me?  It must be sent to Innkeeper Keldamyr, at the Dolanaar inn.  It lies along the road, to the south.", progress = "How might I be of service to you, young one?  Are you here to rest in the inn?  Do you require a hearthstone?", completion = "Ah yes, the delivery of herbs from Shadowglen.  It is a shame Porthannius could not bring it himself, for we have much to discuss, he and I.  But I am glad to get the herbs nonetheless, and I am glad you came.\n\nWhile you are here, please, rest yourself.  Heroes must keep their strength and spirits high, and must find rest and solace whenever they may.  For to neglect one's peace of body and mind is a sure path to failure.\n\nSo... rest.", rewards = "You will be able to choose one of these rewards:\n\nDarnassian BleuRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2160] = {title = "Supplies to Tannok", objective = "Deliver the Crate of Inn Supplies to Tannok Frosthammer in Kharanos.", description = "Hey! You look like a hearty adventurer. If you're planning on braving the pass, do you suppose you could bring a package to the inn in Kharanos?\n\nYou were planning on stopping at the inn, right? If you make it through the pass, you'll definitely want to take a breather there.\n\nAnyways, bring this to Tannok Frosthammer, the innkeeper's assistant. I can't get through the pass myself, and it'll be days until a Mountaineer escort comes through!", progress = "Hi there! Come in, take a seat by the fire and warm yourself with a flagon of ale.", completion = "Ah, at last, the supplies from Hands! I was beginning to worry, we've had scarce word from Anvilmar ever since the troggs overran the pass.\n\nThanks for bringing this to me, &lt;name&gt;. And please, make yourself comfortable. You must be tired after your journey.", rewards = "You will be able to choose one of these rewards:\n\nTough JerkyRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2161] = {title = "A Peon's Burden", objective = "Bring Ukor's Burden to Innkeeper Grosk in Razor Hill.", description = "Excuse me?  Can you help me?\n\nI have a load of food here.  I walked along the road and braved scorpids and spiders and worse!  I brought the food to the Valley of Trials because I thought they needed it and I like to help out.  But they don't need any food!  Now I have to take it back to Razor Hill and I'm afraid of all the beasts along the way...\n\nCan you take it for me?  I'm just a peon, but you're a hero.  You fear nothing!\n\nTake it to Innkeeper Grosk at the Razor Hill inn.  Thank you!", progress = "Welcome to Razor Hill!", completion = "Ah, this is the food Ukor brought to the Valley of Trials.  Did they not need it?  Well, I guess they like to starve you heroes in training.  Builds spirit, they say!\n\nThank you for returning the food.  I'll stick it back on the shelves... but here, let me offer you some refreshment first!\n\nAnd don't forget to rest here in the inn.  You may be a brave &lt;class&gt; ready to take on the world, but if your energy is sapped you won't be doing yourself, or the Horde, much good.", rewards = "You will be able to choose one of these rewards:\n\nTough Hunk of BreadRefreshing Spring Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2178] = {title = "Easy Strider Living", objective = "Bring back 5 Strider Meat to Alanndarian Nightsong in Auberdine.", description = "Do you smell that delicious aroma? It's my secret recipe, <name>--fresh strider stew. Delicious!\n\nPerhaps you would be interested in learning the recipe?\n\nBefore I teach you the recipe, you will need to prove that you can handle the beasts.\n\nNow, I don't expect you to go out and tame one and ride it back to me, but if you can kill a few and bring back some of their succulent meat, I may be persuaded to show you the ways of strider stew.", progress = "The pot is empty and I'm hungry! What's taking you so long?", completion = "Fantastic! Try it and tell me what you think, &lt;name&gt;!", rewards = "You will receive:\n\nRecipe: Strider StewStrider Stew"}
MultiLanguageQuestData['en'][2198] = {title = "The Shattered Necklace", objective = "Search for the original creator of the shattered necklace to learn of its potential value.", description = "You have found a tarnished necklace, though the tarnish belies intricate and magical craftsmanship.  The necklace has been shattered, as its setting appears to be missing three gems.  On the underside of the necklace is the faint imprint of the city seal for Ironforge.  Below the seal are three tiny, engraved letters: \"TdK\".\n\nIf there is anything to be gleaned from the necklace, you will need to learn about its origins.  Perhaps the seal and the initials are a start...", progress = "You've got the wrong gnome, pal!  I was never there!  You can't prove anything!\n\nWait a second... who are you?  What the... where did you find this necklace at?", completion = "Yes... I am the jeweler who made this necklace.  I also am not in the business of handing out information as though it were free.  Information is never free, friend.  If I am going to help you out, you need to help ME out first.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2199] = {title = "Lore for a Price", objective = "Bring five silver bars to Talvash del Kissel in Ironforge.", description = "I am a jeweler of great renown here in Ironforge!  Well, former renown anyway... I have fallen onto hard times due to the chicanery of a competitor!  A bad reputation in this business spells financial disaster.  As a result, I find myself without a copper to my good-though-currently-sullied name.\n\nI want you to get me five silver bars to finish an order I received - the first in what seems like an eternity.\n\nYou get me those five silver bars, and I'll answer your questions on the necklace.", progress = "Have you got the five silver bars I asked for?  I will share my sad tale of woe with you concerning the necklace you now possess... but only after I get those bars!  Please, help a gnome out, won't ya?", completion = "You're all right in my book; I don't care what everyone else has been saying... I kid, I kid!  Seriously, thank you my friend.\n\nNow, the necklace you have is one of my finest creations, but it is missing three gems that help bind magic power to it.  I crafted it for a paladin some time ago.  He was on a self-appointed quest to clear out the \"evil taint\" present at an excavation site in the Badlands called Uldaman.\n\nWell... that paladin died in Uldaman, and that was just the beginning of my woes.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2200] = {title = "Back to Uldaman", objective = "Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who had it last.\n\nProvided item: \n", description = "A competitor of mine started a rumor that my necklace cursed the paladin.  Needless to say, no one wants to buy cursed items from a jeweler.\n\n<name>, I'll make you a deal - find the gems and I'll reassemble the necklace, so long as you'll advertise that I do NOT make cursed items!\n\nTry looking for clues in Uldaman; maybe see if the paladin's body is down there, since he's the one who we know had it last!  When you find the gems you should use this; it'll allow you to contact me here in Ironforge.", progress = nil, completion = "Reading the journal reveals that after much effort, the paladin had identified the location of all three missing gems:\n\nThe Shadowforge dwarves hid the ruby in their barricaded area as they battled the Troggs for control of Uldaman.\n\nThe troggs stashed the topaz in an urn located near some unusual inhabitants of Uldaman - Alliance dwarves!\n\nFinally, the trogg elder himself took the sapphire as his own.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2201] = {title = "Find the Gems", objective = "Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n\n* The sapphire has been claimed by Grimlok, the trogg leader.", description = "The paladin's journal has provided perhaps the only clues that Uldaman will yield as to the location of the necklace's gems.  If the paladin's scribing remains accurate, then the Shadowforge dwarves and the troggs that vie for control of the dig site will need to be dealt with.\n\nArmed with this knowledge, the search for the gems begins in earnest.  When all the gems have been acquired, Talvash in Ironforge should be notified via the Phial of Scrying as per his instructions.", progress = "Talvash's image comes into focus from the waters of the scrying bowl.\n\n\"Wow, you're still alive!  Did you manage to find the gems?  Are you truly the savior of my reputation I have hoped for?  Please tell me you didn't waste a charge on the phial just to chat; those things are NOT cheap, and I'm already in dire financial straits.\"", completion = "Yep, those indeed are the three gems.  Good job!  Unfortunately, your work isn't quite over just yet.\n\nNo, I'm not trying to pull a fast one here, silly &lt;class&gt;.  This is about making magic jewelry - Talvash del Kissel quality-level jewelry!  You need a strong power source to give it some oomph.  Well, that necklace has no more oomph to give.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2202] = {title = "Uldaman Reagent Run", objective = "Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath.", description = "I've heard about a newly discovered plant called the magenta fungus caps.  They grow in clusters at the Uldaman dig site and can be found in the early tunnels and deep within the less-explored areas.  I want to study their potential use in alchemy, and that's where you come in.\n\nFind the magenta cap clusters and bring me a dozen caps.  Be warned, the clusters may spew out poison spores if jostled.\n\nDo this for me, and I'll whip up a batch of one of my famous restorative elixirs for you!", progress = "Have you obtained the magenta fungus caps I need for my alchemical work?  No caps - no reward!", completion = "Well done &lt;name&gt;, you've proven your worth once again!  The caps will be an interesting study, you betcha.\n\nAnd now, as promised, enjoy a taste of one of my more potent restorative brews from my personal stock...\n\nIf you are a skilled alchemist, then perhaps we might have some additional business to conduct.  Regardless, I thank you for your assistance!", rewards = "You will receive:\n\nRestorative Potion"}
MultiLanguageQuestData['en'][2203] = {title = "Badlands Reagent Run II", objective = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Jarkal Mossmeld in Kargath.", description = "You have been most helpful to me, <class>.  I would reward you with the very recipe for the brew I gave you earlier... but I would ask of you a task that is quite dangerous.  Hear my request.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be warned.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years.", rewards = "The following spell will be cast on you:\n\nRestorative Potion\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2204] = {title = "Restoring the Necklace", objective = "Obtain a power source from the most powerful construct you can find in Uldaman, and deliver it to Talvash del Kissel in Ironforge.", description = "You are going to need to find some \"oomph\" for the necklace, and Uldaman is probably the best place for it, actually.  I guess there are a lot of constructs running around in there, yeah?  Well, take out the biggest, baddest construct in that place and grab its power source!  I am pretty sure I can fuse that source into the necklace.\n\nWithout that power source, fixing the necklace will be impossible.  Come back to me here to Ironforge when you have it, and we'll get it all fixed up for you!", progress = "You didn't even stop to tidy yourself up after leaving Uldaman, did you.  You just came straight here, lingering dungeon odors be damned.  Well, let's hope this visit is merely an odiferous one, and not a useless one to boot.\n\nDo you have the power source for the necklace?", completion = "Well I'll be - I sure am glad to see you and this power source in one piece.  It will take me a moment to magically fuse the power source with the necklace now that the gems have been reunited with it.  Once it is done, however, the necklace will be yours!\n\nYou're excited, aren't you?  All tingly with anticipation?  Now where did I put that spell focus at...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2205] = {title = "Seek out SI: 7", objective = "Deliver Keryn Sylvius's package to Master Mathias Shaw at the Stormwind Barracks.", description = "The badge? Oh, it's nothing, fish - nothing you could handle anyhow. By the looks of you, I'd say Mathias is likely to mistake you for the cheese delivery <boy/girl> instead of a proper rogue. Regardless, I've been assigned a job and I've made a promise to deliver on that job.\n\nSpeaking of which, deliver this package to Mathias and he may give you a small task or two.\n\nGet cracking.", progress = "Can I help you, <class>?", completion = "You found me - and by looking at you, I'd say the run and subsequent search may have been a great strain on your system, both mentally and physically.\n\nWould you like Renzik to show you the way to an inn or are you ready for some work?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2206] = {title = "Snatch and Grab", objective = "Find the Defias Dockmaster and recover the Shipping Schedule for Master Mathias Shaw.", description = "Our operatives in the field are reporting heavy Defias activity south of Goldshire. The reports indicate that the Defias have taken over Jerod's Landing and are now using it as a way to smuggle large quantities of contraband from Redridge to Westfall.\n\nI need you to infiltrate the dock house and get me that shipping schedule, <name>. You will probably find it buried deep in the pockets of the Dockmaster.\n\n...and <name>, should you be discovered, SI:7 will disavow all knowledge of your existence.", progress = "Your mortality wanes with every moment you waste loitering in the barracks, <class>.", completion = "I am astonished... Astonished that Keryn finally found a recruit that could possibly have the makings of a proper &lt;class&gt;. Take this blade, &lt;name&gt;. A day will come when you will be called upon again to serve the SI:7. Hone your skills, keep your eyes open and that blade sharp.\n\nYou won't see us coming but you'll feel it when we get there...", rewards = "You will receive:\n\nBlade of Cunning"}
MultiLanguageQuestData['en'][2218] = {title = "Road to Salvation", objective = "Speak with Hulfdan Blackbeard in Ironforge.", description = "Another lost soul looking for guidance, eh? I suppose you want to find a purpose - your purpose. I've seen it a thousand times, another hero looking for work.\n\nWell, today's your lucky day, friend. Hogral's got the cure for your ailment.\n\nHere's what you do: Take this road here up to Ironforge and make your way to the Forlorn Cavern. Once there, locate the thieves' guild and speak with Hulfdan Blackbeard. He'll put you on the road to salvation.", progress = nil, completion = "So ye think yer a right scoundrel? Destined to be one o' Blackbeard's chosen few - an officer o' the Hidden Circle?\n\nOnly a good fer nothin' scallywag would think so highly o' hisself.\n\nThat's exactly what we be lookin' fer! Welcome aboard, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2238] = {title = "Simple Subterfugin'", objective = "Find Onin MacHammar by Gnomeregan.", description = "Ye see, the King be strip mining the quarry fer ore and gems. More riches than any one dwarf should see in ten lifetimes.\n\nThe Hidden Circle has values, <name>. We value valuables. Can ye understand?\n\nNow we feels the King should be sharing some of that booty, but we don't want ol' 'Stinkbeard' to know he's sharin' - if ye catch me drift.\n\nWe needs ye to speak with Onin MacHammar over by Gnomeregan and bring back a report. The crafty dwarf has hidden hisself amongst the lepers. Be careful.", progress = nil, completion = "Shhhh! Keep it down you daft fool. They'll hear us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2239] = {title = "Onin's Report", objective = "Take Onin's Report back to Hulfdan in Ironforge.", description = "The Quarry? Yap, I see those monstrous armored steam tanks come by this post near every day.\n\nMy contacts to the east tell me that the tank starts off at Ironforge, makes a pickup at the Gol'Bolar Quarry, stops over at Kharanos to refuel and then for some blasted reason, it takes the long way around past Gnomeregan, before reaching Ironforge to drop off the shipment.\n\nIt's all in the report, <race>. Take it back to Hulfdan so he can plan the next step.", progress = "Did ye enjoy the stench of leper gnome? I only ask because ye got a crazy smile on yer face.\n\nWhat news do ye bring from Onin?", completion = "Long route? In the name o' me own beard!\n\nYe done good, &lt;name&gt;. Take this dagger and be gone with ye. The Circle will call upon ye again when step three be ready to be set into motion.\n\nWhat's step three? It comes right after step two - me putting me boot up yer backside.\n\nInterested?", rewards = "You will receive:\n\nBlade of Cunning"}
MultiLanguageQuestData['en'][2240] = {title = "The Hidden Chamber", objective = "Read Baelog's Journal, explore the hidden chamber, then report to Prospector Stormpike.", description = "Now for the task at hand.\n\nThere is a secret chamber, the Chamber of Khaz'mul, that must be explored.  The problem is that the chamber's behind a huge, locked door!  It's a lucky thing I know how to open it.\n\nI've described everything in my journal, here on the table.  My band and I are stuck here for now... so you, <name>, must find the chamber of Khaz'mul for us!\n\nRead my journal, explore the chamber, then report to Prospector Stormpike at the Explorers' League in Ironforge.", progress = nil, completion = "You have seen the Chamber of Khaz'mul?  Amazing!  Baelog was sure it existed, but I must admit that I had my doubts.\n\nThank you, &lt;name&gt;.  With luck your finding will incite our leaders to renew their efforts to retake Uldaman.  And if it is ever again under Ironforge control, then the secrets of the Chamber of Khaz'mul will be ours!", rewards = "You will be able to choose one of these rewards:\n\nDwarven ChargeExplorer's League Lodestar\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2241] = {title = "The Apple Falls", objective = "Take Jannok's Rose to Syurna in Darnassus.", description = "They say I'm 'lovestruck,' whatever that means.\n\nSure, I spend my every waking moment thinking about Syurna. Sure, my home is full of paintings and drawings of Syurna. Sure, I often go days without eating, sleeping, or drinking, while I lament about the love we could have had. Is that so wrong?\n\nNow she won't see me! ME! I've tried sending her messages but she won't even talk to another person unless they are a rogue.\n\nCould you deliver this flower to her? Don't forget to tell her it's from Jannok.", progress = "Oh, isn't this wonderful. You've brought flowers for your own funeral.", completion = "Had I saved every flower that dolt, Jannok, had sent me, I would have had the means to open a shop. Regardless, it seems as if Jannok's latest courier may prove to be useful.\n\nInterested in some work, &lt;class&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2242] = {title = "Destiny Calls", objective = "Find Sethir the Ancient and bring back any clues that you may discover to Syurna.", description = "We believe there is one being that may be able to help us understand what is happening to the forests of Teldrassil. Unfortunately, getting the creature to cooperate has proven disastrous.\n\nHe hides on a branch at the outskirts of the Oracle Glade. All who have so far approached the satyr, whether through force or diplomacy, have met with doom. Perhaps stealth is the answer, <name>.\n\nFind what Sethir the Ancient carries in his packs and report back to me.", progress = "Have you anything to report from Sethir the Ancient, <name>?", completion = "This is grim news, &lt;name&gt;. It would seem that the sickness which has gripped the forests and rivers of Darkshore has begun to taint our home.\n\nYou have served us well, but there is nothing more you can do here. Take this blade as a reward for your service to Teldrassil.", rewards = "You will receive:\n\nBlade of Cunning"}
MultiLanguageQuestData['en'][2258] = {title = "Badlands Reagent Run", objective = "Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and  5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands.", description = "<name>, I could use your aid if you're up for it.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.  Watcha wanna do?", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done!  These should last me for a little while, at least.  Here is your pay as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2259] = {title = "Erion Shadewhisper", objective = "Contact Erion Shadewhisper in Darnassus.", description = "Do not worry, <name>, I am not sending you to see Syurna. Erion requires your presence at the Cenarion Enclave. Make haste!", progress = nil, completion = "It is time to branch out, &lt;race&gt; - the world awaits.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2260] = {title = "Erion's Behest", objective = "Travel to Stormwind City and seek council with Renzik \"The Shiv.\"", description = "Word of your deeds has spread far and wide, <name>. So far, in fact, that Stormwind Intelligence has asked for you by name.\n\nThe journey is taxing and not without peril, but an opportunity to train under SI:7 should not be taken lightly.\n\nA new world awaits you, <name>. Make your way to Old Town in Stormwind and speak with Renzik \"The Shiv\" at SI:7 headquarters.", progress = nil, completion = "You have answered SI:7's calling, &lt;name&gt; and journeyed from distant shores to join our ranks, however, there is much for you to learn.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2278] = {title = "The Platinum Discs", objective = "Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon.", description = "The centerpieces of this treasure chamber are four huge platinum discs, each adorned with numerous sigils of an unknown origin.  Touching them makes your hand tingle.  Just after touching the discs, the visage of a large stone watcher springs forth.\n\n\"Salutations.  I am a keeper of knowledge.  The Creators' synthesis of the Earthen has been chronicled and stored here for this world in the Discs of Norgannon.\"\n\nYou have uncovered a wealth of previously undiscovered worldly lore!", progress = "The voice of the stone watcher seems to resonate within your very inner being:\n\n\"You must first satisfy the data assimilation prerequisite of Discs of Norgannon; once you fulfill this requirement, you will then be permitted to obtain a portable version of the stored data.  Please be sure you have fully explored the information within this repository first.\"", completion = "Following the instructions of the stone watcher, you once again access the Discs of Norgannon now that you have learned about the history of the Earthen, the troggs, and the dwarves.  A faint, brief hum is heard from within the discs.  The stone watcher then speaks:\n\n\"The discs have now been synthesized.  Access the Discs of Norgannon once more to receive your personal copy.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2279] = {title = "The Platinum Discs", objective = "Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge.", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The Explorers' League in Ironforge is such a group, known throughout the Alliance; perhaps they can make good use of it.", progress = "Yes, may I help you with something?  I assure you I am a very busy right now.  If it is grave importance to the Explorers' League, however, then I am all ears!", completion = "What do you have there... oh my.  You found this where?\n\nNo, really?\n\nYou spoke to whom about what?\n\nNO, REALLY?!\n\nMy fine &lt;class&gt;, you may have just made the archaeological find of the year!  By the Gods who am I kidding, the find of the century!  If these discs are what I think them to be, then this could be the very key we have been looking for!  This may well prove outright once and for all the legitimacy of the Dwarves' enchanted creation!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2280] = {title = "The Platinum Discs", objective = "Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff.", description = "Touching the Discs of Norgannon once again makes your hand tingle.  This time, however, a strange grinding noise is heard from inside the discs.\n\nYour backpack suddenly becomes heavier than it was before.  Inside, you discover a miniature version of the discs!\n\nNo doubt, an item of this sort would be invaluable for someone interested in the ancient history of Azeroth.  The sages of Thunder Bluff are such historians, known throughout the Horde; perhaps they can make good use of it.", progress = "Yes young one, I see you marching into my tent with intensity in your stride... with determination in your purpose.  You seek my counsel is some matter of grave importance to the Horde?  Perhaps you wish a mystery of the universe revealed to you?", completion = "What are these here then?\n\nImpressive, young one!  These discs, in them I sense secrets that the earth has held on to tightly for many years.  You were very wise to bring them here to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2281] = {title = "Redridge Rendezvous", objective = "Venture forth to Lakeshire in the Redridge Mountains and speak with Lucius.", description = "Sending you out in the field now would be suicide. Renzik doesn't need another dead rogue on his hands. Don't fret, though, <name> - Renzik is going to get you up to speed.\n\nMake your way to the Redridge Mountains and speak with an associate of SI:7 named Lucius. You will find him hanging around the docks of Lakeshire with the other shady good-for-nothings.", progress = nil, completion = "Ah, so your fingers are a little fat, eh? Don't worry, &lt;name&gt;, I've turned more useless thieves than you into accomplished rogues.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2282] = {title = "Alther's Mill", objective = "Open Lucius's Lockbox, recover the Token of Thievery and return it to Lucius in Lakeshire.", description = "We've been training thieves here for years! After all, not every rapscallion is born with the grace and finesse of old Lucius.\n\nUp off the road here you'll find Alther's Mill. I got a chest up there with something important inside. Go get it for me! Bring back that token and you'll receive your Certificate of Thievery!", progress = "Did I forget to mention the orcs?\n\nI hear they have been nosing around up by the mill.", completion = "Cracked it open, did you? Nice work, &lt;name&gt;.\n\nIf you die now, we can rest easy knowing it was due to your own stupidity and not inexperience.", rewards = "You will receive:\n\nCertificate of Thievery"}
MultiLanguageQuestData['en'][2283] = {title = "Necklace Recovery", objective = "Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged.", description = "We've got work for you, that is if you've got the guts to do it!\n\nDeep in the Badlands is the Uldaman dig site.  We've heard a tale about some idiot paladin who died there recently.  Why we even care is that he had a very valuable necklace on him.  It's supposedly got three large gems: a ruby, a sapphire, and a topaz.\n\nThe shot: we want it, and we're payin' TOP SILVER to get it.  It may be damaged, but that's neither here nor there; we'll fix whatever scratches are on it.", progress = "Well, do you have the necklace?  You won't see a copper from us if you don't have that necklace!", completion = "Mmmm salvage!  I can smell the necklace from here.  Now let's look at that beauty...\n\nHey, what do you think you're trying to do here?  This necklace is missing the gems!  You think we wouldn't notice?  Even Malton could see that the gems are gone.\n\nWell, maybe you didn't steal them... but this necklace is worthless without those gems!  Your job isn't done here yet, not by a long shot!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2284] = {title = "Necklace Recovery, Take 2", objective = "Find a clue as to the gems' whereabouts in the depths of Uldaman.", description = "As sure as Malton is a dummy, those gems are still in Uldaman somewhere.  You're going to have to go back there and look for them.\n\nLike I said before, if the information we have is correct then there's a ruby, a sapphire, and a topaz that go with the necklace.  Find them and put them in the necklace.\n\nAs to where the gems are, who knows?  Maybe you'll get lucky and find the corpse of the Paladin.  If he's not been stripped clean already, then maybe he's got them on him still.", progress = nil, completion = "You seem to have found the remains of the paladin that Dran had mentioned from before.  Searching the remains uncovers what would appear to be his journal.  The book is in poor condition, as dried blood has stained most of the text in the book.  What you can read, however, is gibberish; it is written in the native tongue of the humans, to the best of your knowledge.\n\nYou will need the book translated if you are to glean any knowledge from it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2298] = {title = "Kingly Shakedown", objective = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", description = "So there we were, about to start plottin' out phase III when a couple o' Magni's blockheads come bargin' in here talkin' bout some kind o' heist and arresting some o' the Hidden Circle.\n\nWell nobody puts the iron on old Blackbeard! The argumentations got heavy and thick and somehow yer name weres blurted out!\n\nMe advice? Take the first Gryphon out o' Ironforge and get to Stormwind. Get yerself to Old Town and once there, talk to an old friend o' mine named Renzik \"The Shiv.\"", progress = nil, completion = "It's always good to have one of Hulfdan's rogues among our ranks!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2299] = {title = "To Hulfdan!", objective = "Travel to Ironforge and speak with Hulfdan Blackbeard.", description = "Where have you been, <name>? Hulfdan's been looking all over the place for you. We thought the king may have put you in irons.\n\nGet to Ironforge as soon as possible and speak with Hulfdan!", progress = nil, completion = "Keep yer voice down, &lt;name&gt;, the guards may hear ye.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2300] = {title = "SI:7", objective = "Travel to Stormwind and seek out Renzik \"The Shiv.\"", description = "Renzik was looking for you, fish.\n\nI wouldn't keep Mathias's second in command waiting if I were you.", progress = nil, completion = "Are you ready to get to work or do you need to take a nap before we get started?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2318] = {title = "Translating the Journal", objective = "Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands.\n\nProvided item: \n", description = "At an impasse of sorts, you know that you will need the book translated into a language you can understand.  There certainly are a number of people in the world who could do it; the closest location that might have someone who could, however, is the Kargath outpost in the Badlands.  Perhaps that is a good place to start.", progress = nil, completion = "Mighty &lt;class&gt;, I know what you are doing out here in the Badlands.  I know you seek my gift of tongues.  You're after the parts to that necklace you found in Uldaman.\n\nSurprised?  Don't be - it's my job to know such things.  Instead, let's discuss what you're going to do for a translated journal.  Trust me - I'm the only one you'll find that can translate it.\n\nBetter still, let me make you a better offer than Dran Droffers is, and it'll let you still complete your deal with them.  Interested now, yes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2338] = {title = "Translating the Journal", objective = "Let Jarkal borrow the necklace. In exchange, he will translate the journal for you.", description = "Droffers and Son Salvage aren't smart enough to restore the magic in the necklace, but I am.  All I want to do is study the necklace so I can learn to make them myself.  To do that, I will need your necklace.  Let me borrow it, and in exchange for the time I get to study it I will translate the journal for you.  While you are searching for the gems, I should have enough time to learn what I need to.\n\nIt's a simple deal, and no one else will be the wiser.  Whatcha wanna do?", progress = "You've thought about it, yes?  You're a smart <class> if you take this deal - you and I will get what we both want, and Droffers and Son Salvage will think they're getting what they want.", completion = "You know a good deal when you see one - I knew I could count on you.\n\nIt will be just a moment while I cast a spell to quickly translate the human tongue into a form you will understand.  I am a troll of my word; ask anyone in the Horde about Jarkal Mossmeld.  Now, let's get this started...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2339] = {title = "Find the Gems and Power Source", objective = "Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman.\n\nFrom the journal, you know...\n* The ruby has been stashed in a barricaded Shadowforge area.\n* The topaz has been hidden in an urn in one of the Trogg areas, near some Alliance dwarves.\n* The sapphire has been claimed by Grimlok, the trogg leader.", description = "Here is the journal, translated for you to read on your own.  The crux of it says dwarves hid the ruby, the troggs hid the topaz, and a trogg named Grimlok has the sapphire.\n\nLook - you're going to need a power source to make the necklace work again.  Dran Droffers doesn't know this.  To find one, here's what I'd do: go as deep as you can in Uldaman and kill whatever construct there is the strongest.  No doubt whatever that is would have it.\n\nWhen you have everything collected, come back here!", progress = "You've got another trip into the depths of Uldaman in store for yourself if you don't have the gems and a power source capable of channeling magical power back into the necklace.\n\nYou'll be getting the gems back to deliver to the goons in Orgrimmar; I will be keeping the power source, since it will be the thing that will make the necklace work in the first place...", completion = "Very well done, &lt;class&gt;.  Now the fruits of our redirection will pay themselves out handsomely.  I'm finished with the necklace itself, and I am confident I can duplicate the construction process consistently.\n\nBut first, I will use a specially prepared incantation to quickly analyze those gems before you take them and the necklace back to Orgrimmar.  This will take just a brief moment to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2340] = {title = "Deliver the Gems", objective = "Deliver the Necklace and Gem Salvage to Dran Droffers in Orgrimmar.", description = "Any necklace setting and gem will work, so long as they are the same material.  This power source, however, is what will bring the magic back to the necklace... I hope.\n\nI'll gladly supply the gems needed for your version of the necklace, so long as the power source actually works.\n\nHead to Orgrimmar and keep your end of the bargain with Droffers and Son Salvage.  Just keep your mouth shut about our deal, and when you get back I might have a wonderful surprise for you.", progress = "Well, look who it is!  Took your sweet time getting here, I see.  Let's hope this isn't a waste of my time!  You'll not get paid unless you have everything I asked for.  And trust me on this - we'll be double and triple checking everything!", completion = "Yep, it's all here.  Say, mind if we keep the bag too?  No?  Thanks, appreciate it!  Har!\n\nThis necklace will be our greatest haul yet!  Don't feel too bad though; I'm sure the necklace wouldn't fit you anyway.  Har again!\n\nA deal is a deal, so here's your fee for the salvage.  Our business is done here for now; check back later to see if we have more work.  Until then, beat it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2341] = {title = "Necklace Recovery, Take 3", objective = "Visit Jarkal Mossmeld in Kargath to see if he was successful.", description = "As Dran and Malton Droffers begin to squabble over their new salvage, half of the deal is now complete.  A trip to the Badlands is now in order to finish things up, as Jarkal Mossmeld in Kargath might have a special reward waiting for you there.", progress = nil, completion = "The power source you gave me exceeded every expectation I had for it.  I was able to make both you and me a necklace, and I have enough left over to make at least three more.  They will fetch quite the fee, with Droffers and Son Salvage none the wiser.\n\nHere you go, my friend.  I give you my thanks on a splendid job... and something quite special for your trouble.", rewards = "You will receive:\n\nJarkal's Enhancing Necklace"}
MultiLanguageQuestData['en'][2342] = {title = "Reclaimed Treasures", objective = "Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity.", description = "Sweeping the bat pens with this broom is not befitting a Garrett!  I've earned a little coin from this accursed job, and I'm willing to spend it on you to better my station.\n\nThe Garrett family weapon of choice is locked away in our chest in the South Common Hall of Uldaman from when we Garretts toiled there as diggers.  Without it, I will be stuck here forever - literally - sweeping up after these infernal bats.\n\nReclaim my family's treasure and bring it to me!  Help me restore my birthright!", progress = "The sweeping never ends... these bats are prolific in their mockery of me and my broom.  Please tell me you've reclaimed my family's treasure!  I've offered you my silver - is that not enough?!", completion = "At last - a broom worthy of a Garrett.  You're bloody well worth every silver I spent on you, I say!\n\nDo you hear me, foul bats?  I now wield the Garrett family weapon of choice!  Tremble, bats, tremble!!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2358] = {title = "Horns of Nez'ra", objective = "Return the Horns of Nez'ra to Arantir's Shadow in Lakeshire.", description = "Many years ago, the Horns of Nez'ra were stolen from Ravenholdt manor. Across continents and oceans I have searched, only to discover that these insignificant beasts have had it in their possession all along.\n\nSlay every Blackrock orc you cross until the Horns of Nez'ra are recovered. Should you recover the horns, find me in Lakeshire.\n\nDo this for me and your name shall be known to Ravenholdt, <name>.", progress = "Do you have the demon prince's horns?", completion = "To deny Ravenholdt the artifact, would be to deny one's own existence. Well done, &lt;class&gt;. You may yet walk among the assassins of Ravenholdt.\n\nAs a young &lt;class&gt; adventuring in Darkshore, I discovered a tea that replenishes energy in combat. It has served me well throughout the years and now I pass on a taste of the thistle tea to you. Drink of it when you tire, &lt;name&gt;, and fight with vigor once more!", rewards = "You will receive:\n\nThistle Tea"}
MultiLanguageQuestData['en'][2359] = {title = "Klaven's Tower", objective = "Steal the Defias Tower Key, break into the Defias Tower and uncover the contents of the Duskwood Chest. Take whatever information you find back to Mathias Shaw in Stormwind. Read Kearnen's Journal to gain insight about the tower.", description = "I've been staking out this tower for weeks, <name>. Recently a major shipment came through from Duskwood, and along with it came those guards.\n\nWhat are they? Your guess is as good as mine. I can tell you one thing - they aren't human.\n\nAnyhow, the shipment had a chest - which is what I assume those abominations are guarding. The zombie with the spikes holds a key we'll need.\n\nGet that key, get in the tower, and uncover whatever is in that chest. Take your findings back to Mathias.", progress = "Any news from Agent Kearnen?", completion = "This would explain the Defias drones you and Kearnen saw outside of the tower, &lt;name&gt;. It would also explain the Venture Company's involvement with the Defias and the strange shipments out of Duskwood.\n\nAccording to this book, the Zanzil trolls in Stranglethorn have discovered a way to raise the dead through potions... or to be more specific: poison.\n\nYou'll be of no use to SI:7 without a firm understanding of poisons, &lt;name&gt; -- especially with the recipe to create undeath at our fingertips.", rewards = "The following spell will be cast on you:\n\nPoisons\n\nYou will receive:\n\nRecipe: Thistle Tea"}
MultiLanguageQuestData['en'][2360] = {title = "Mathias and the Defias", objective = "Travel to Westfall and find Agent Kearnen for your debriefing.", description = "Not a moment too soon, <name>. SI:7 reconnaissance is reporting unusually heavy Defias activity in Westfall.\n\nIt would seem that the Defias have taken over an abandoned Alliance watch tower southeast of Sentinel Hill and are using it as a base of operations to smuggle in goods from the Redridge supply route.\n\nGet to Westfall and contact Agent Kearnen for your debriefing. You will find her hidden near the tower.\n\n...and <name>, should you be discovered, SI:7 will disavow all knowledge of your existence.", progress = nil, completion = "Mathias finally sent another agent to back me up, eh? Well I hope he's ready to hear some bad news.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2361] = {title = "Restoring the Necklace", objective = "I gladly give you this necklace, mighty <class>.  You have done me an invaluable service, and for that I thank you.  Wear it with pride, and make sure you mention loudly and repeatedly who made it for you!\n\nAlso, if you could toss in the fact that it really isn't cursed, that would be great.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTalvash's Enhancing Necklace"}
MultiLanguageQuestData['en'][2378] = {title = "Find the Shattered Hand", objective = "Journey to Orgrimmar and speak with Shenthul at the Cleft of Shadow.", description = "You have served the Deathstalkers well, <name>, but perhaps it is time for you to venture outward. While you have shown aptitude in the ways of stealth and deception, you still require much training.\n\nThe Deathstalkers have allies within the Shattered Hand. Seek out those that would assist us - find Shenthul in Orgrimmar.", progress = nil, completion = "So, you are what our mighty allies have sent Shenthul? How uninspiring....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2379] = {title = "Zando'zan", objective = "Speak with Zando'zan at the Cleft of Shadow.", description = "Your determination alone is not enough to overcome the obstacles that lay ahead of us.\n\nSpeak with Zando'zan to begin your training as an operative of the Shattered Hand.\n\nIt is only when you have mastered the practices of stealth and thievery that you may take the next step towards your destiny.", progress = nil, completion = "Perhaps Zando'zan was wrong. Zando'zan apologizes.", rewards = nil}
MultiLanguageQuestData['en'][2380] = {title = "To Orgrimmar!", objective = "Speak with Shenthul at the Cleft of Shadow in Orgrimmar.", description = "A master of stealth and deception you are not, however, all of that can and will change. You've obviously impressed those in charge with your meager skills, as the great Shenthul has asked for you by name.\n\nTake the road north of here to Orgrimmar and speak with Shenthul in the Cleft of Shadow.", progress = nil, completion = "It is important that the Shattered Hand remains vigilant in the face of the changes Thrall wishes to bring about to the Horde. Our numbers alone will not be enough to overcome his rule - stealth and deception must be mastered.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2381] = {title = "Plundering the Plunderers", objective = "Bring the Southsea Treasure back to Wrenix the Wretched in Ratchet. Do not forget to get an E.C.A.C. and Thieves' Tools from Wrenix's Gizmotronic Apparatus. You will need both of these items to complete your mission.\n\nShould you be attacked by any unusually hostile parrots, use your E.C.A.C.!", description = "I don't mean to scare you, <name>, but the last five thieves I sent to steal the southsea treasure came back to me in pieces.\n\nSouth along the coast you'll find Tide Razor, the southsea freebooter's ship. Nestled in the hold is the payoff - the southsea treasure. On the second level of that ship is the pirate's den, a place where they train all of their thieves.\n\nBoard that ship, steal the treasure, and bring it back to me. Use the pirate's den if you need to practice your thievery, but be careful!", progress = "Well, at least you still have all of your body parts. Did you find the treasure?", completion = "Incredible! Improbable! Simply amazing! You've got talent, &lt;name&gt;. Either that or you're the luckiest man alive!\n\nHere's your cut of the action. I'm sure you would make better use of this stuff than I could.", rewards = "You will receive:\n\nThistle Tea"}
MultiLanguageQuestData['en'][2382] = {title = "Wrenix of Ratchet", objective = "Travel to Ratchet and speak with Wrenix the Wretched.", description = "Zando'zan has seen it! Yes, the day comes! Thrall's death... the dagger in his back, poison seeping through to his every vein... Zando'zan has said too much.\n\n<name>! Zando'zan has a task for <name>! <name> must travel to Ratchet, east of the Crossroads, and speak with Wrenix the Wretched. Go!", progress = nil, completion = "Another one? The last five that crazy troll sent me ended up as shark food. Let's hope you fare a little better, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2383] = {title = "Simple Parchment", objective = "Read the Simple Parchment and speak to Frang in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", progress = "What's that you have there?  A parchment?  You're not a scholar, I hope...", completion = "Ah, that's my parchment.  I heard you'd be coming to the Valley, &lt;name&gt;.  I'm glad to see you made it--let's hope you survive the trials ahead. Like I said, as you gain in power, come to me--I will do what I can to train you in the ways of the &lt;class&gt;.\n\nGood luck, &lt;name&gt;, and return to me whenever you feel ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2398] = {title = "The Lost Dwarves", objective = "Find Baelog in Uldaman.", description = "The dig site at Uldaman wasn't always overrun.  We Ironforge dwarves used to control the area, but... that was before the troggs came.  They came so fast and in such numbers that not even dwarven might could stop them!\n\nIn fact, their attack was so sudden that I fear some of our people may be trapped behind enemy lines.\n\nMy friend Baelog led a small band of dwarves deep within the site just before the troggs showed up.  If he and his company live, then I want you to find them.", progress = nil, completion = "It's about time you showed up!  I was in danger of losing a bet with Olaf!\n\nHe wagered that his beard would grow to his knees before he saw another living &lt;race&gt;.  Well here you are, and as you can see Olaf's beard has a few more inches to go.\n\nThanks, &lt;name&gt;.  I'll split the winnings with you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2399] = {title = "The Sprouted Fronds", objective = "The fronds Denalan planted within his garden have sprouted and grown.  They tremble, eager to be picked....", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSprouted Frond"}
MultiLanguageQuestData['en'][2418] = {title = "Power Stones", objective = "Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands.", description = "A while ago, I had an incident with the Shadowforge Dwarves.  They brought me to Angor Fortress to study two types of strange stones from Uldaman.  I discovered that the stones were sustained, stable power sources if treated correctly.  It's amazing the things one can find in that old dig site!\n\nAnyway, after I told them the secret of the stones they kicked me out of Angor Fortress and began digging for more in Uldaman.\n\nI want those stones for myself!  Bring me both types and I'll pay you plenty!", progress = "Do you have the power stones, <name>?  I have a robotic rodent that needs a power supply...", completion = "That's great, you found some!  Thanks a lot, &lt;name&gt;.  You're the most dependable &lt;race&gt; I've met!\n\nI can't wait to try these on some devices I've been tinkering with.  I bet that, under the right circumstances, devices powered with these stones will keep going, and going, and going...", rewards = "You will be able to choose one of these rewards:\n\nEnergized Stone CircleDuracin BracersEverlast Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2438] = {title = "The Emerald Dreamcatcher", objective = "Bring the Emerald Dreamcatcher to Tallonkai Swiftroot in Dolanaar.", description = "I was once given an emerald dreamcatcher from Gaerolas Talvethen, the warden of the druids in the Ban'ethil Barrow Den. This powerful amulet is able to siphon energy from the Emerald Dream, bestowing luck upon those who carry it.\n\nSadly, I have not been able to retrieve it from my dresser in Starbreeze Village... Although Starbreeze was once a tranquil place, it has now succumbed to the corruption of the furbolg that reside there.\n\nPerhaps you would be willing to recover my dreamcatcher, <class>?", progress = "Please move swiftly. I can only hope that my emerald dreamcatcher has been unharmed by the furbolg.\n\nHave you recovered it yet, <name>?", completion = "My emerald dreamcatcher is of great importance to me. It is a gift only given to few. Thank you for returning it, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2439] = {title = "The Platinum Discs", objective = "Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge.", description = "This object is an incredible find.  The ancient Titans, or the Creators as these discs refer to them as, are the link to our enchanted creation, if the lore stored in here is correct!  We'll need to invest as much research time into this as possible.\n\nAs for you, heroic <class>, take this voucher to Dinita Stonemantle at the vault.  It grants you what I think is a fitting for such a tremendous find!\n\nReturn to me directly when you are ready; there is much more to do for the Explorers' League!", progress = "Welcome to the Vault of Ironforge, <name>.  What may I do for you today?", completion = "As yes, a voucher from the Explorers' League... and quite the valuable one, might I add.\n\nThe Explorers' League lends me the authority to offer you a choice in your compensation directly from their vault.  You are to receive this item, and you may choose between five superior healing potions or five greater mana potions as your reward.", rewards = "You will be able to choose one of these rewards:\n\nSuperior Healing PotionGreater Mana Potion\n\nYou will also receive:\n\nThawpelt Sack"}
MultiLanguageQuestData['en'][2440] = {title = "The Platinum Discs", objective = "Take the reward voucher to Bena Winterhoof in Thunder Bluff.", description = "I shall focus my energies on these discs; they will reveal their true workings to me in due time.\n\nAs for you <name>, I will now reward you for your diligence in bringing this to my attention.  Take this voucher to Bena Winterhoof, the alchemy trainer for Thunder Bluff.  She will give you a special item I believe you will find appealing, and she will supply you with a choice of potions from my personal stock.\n\nReturn to me soon, as I sense there is much more at hand for us to do regarding this find.", progress = "Greetings, <class>!  Are you here for alchemy training, or perhaps something else?", completion = "Well &lt;name&gt;, you must have pleased Sage Truthseeker greatly for him to give you this item.  You are also to be granted a gift from his cache of potions; you may choose between 5 superior healing potions or 5 greater mana potions as your reward.", rewards = "You will be able to choose one of these rewards:\n\nSuperior Healing PotionGreater Mana Potion\n\nYou will also receive:\n\nThawpelt Sack"}
MultiLanguageQuestData['en'][2458] = {title = "Deep Cover", objective = "Travel to the Venture Co. Tower, north of the Sludge Fen and contact the Shattered Hand's covert operative, Taskmaster Fizzule.\n\nWhen the tower is in sight, use the Flare Gun to signal your arrival to Taskmaster Fizzule. Fire off TWO flares, then approach Taskmaster Fizzule and perform the Shattered /Salute.\n\nThese actions must be performed in the correct order, as Fizzule will attack and terminate any person he does not recognize.\n\nProvided item: \n", description = "The Venture Company... Perhaps you have heard of them?\n\nFor one year we have worked on planting an agent deep within their ranks. Through much hard work and careful planning, we succeeded.\n\nRecently we received word that the Venture Co. are planning something on a grand scale. Go north of the Sludge Fen to the Venture Co. tower and contact our undercover agent, Taskmaster Fizzule.\n\nWhen you find the tower, use this flare gun, then approach Fizzule and show him the salute of the Shattered Hand.", progress = nil, completion = "It's good to see another agent of the Shattered Hand in these parts, however, the flare may have been a little too much!\n\nNext time you need to speak with me, blow into this whistle twice and I'll know you are an ally.", rewards = "You will receive:\n\nFizzule's Whistle"}
MultiLanguageQuestData['en'][2459] = {title = "Ferocitas the Dream Eater", objective = "Tallonkai Swiftroot in Dolanaar wants you to kill 7 Gnarlpine Mystics and find the Missing Jewel.", description = "The emerald... It is missing! My dreamcatcher has been damaged!\n\nThere is a band of Gnarlpine mystics located to the north of Starbreeze. I have heard reports that their leader, Ferocitas the Dream Eater has been wearing a necklace that glows green in the night. Now seeing my dreamcatcher, I am sure that he has stolen my emerald... He would never realize that its power is useless to him.\n\nFind this missing jewel, <name>. And, while you're there, clear out some of the corrupted mystics as well.", progress = "Ferocitas and the Gnarlpine mystics must return what is mine.  Please retrieve the emerald so that I may repair my emerald dreamcatcher.", completion = "Now I can repair my dreamcatcher.  Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2460] = {title = "The Shattered Salute", objective = "Perform the Shattered Salute on Shenthul.", description = "As a rogue of the Shattered Hand, it is imperative that you learn the Shattered Salute. It is the only way to truly identify another member of the Hand.\n\nWatch, learn, repeat.", progress = "Practice!", completion = "Well done, &lt;name&gt;. You are now ready to proceed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2478] = {title = "Mission: Possible But Not Probable", objective = "Steal Silixiz's Tower Key from Foreman Silixiz, then kill two Mutated Venture Co. Drones, two Venture Co. Patrollers, and two Venture Co. Lookouts.\n\nAssassinate Grand Foreman Gallywix and take his head, then pick the lock on Gallywix's lockbox and steal the Cache of Zanzil's Altered Mixture. Take the Cache and Gallywix's Head back to Shenthul in Orgrimmar for further instruction.", description = "You will need to steal the tower key from Foreman Silixiz, <name>. Once you've got the key in your possession, hold on to it - I may need it later.\n\nRemember, the poison has weakened everything in this tower. Use your abilities to bring chaos and destruction to its inhabitants. Slay them all -- show no mercy!\n\nOnce everything inside lays in a bloodied heap, pick Gallywix's lockbox and steal the cache of Zanzil's mixture held inside. Take both the head of Gallywix and the mixture to Shenthul in Orgrimmar.", progress = "What have you to report, <name>?", completion = "Poor Fizzule, he was a good agent -- one of our best. Alas, it is the price we pay, &lt;name&gt;. Being a field agent of the Shattered Hand is dangerous work.\n\nYou have performed your duty well, &lt;class&gt;. It would be a shame if you did not live to serve us again.", rewards = "You will receive:\n\nRecipe: Thistle Tea"}
MultiLanguageQuestData['en'][2479] = {title = "Hinott's Assistance", objective = "Travel to Tarren Mill in Hillsbrad Foothills and deliver the Sample of Zanzil's Mixture to Serge Hinott.\n\nTo get to Tarren Mill, take the Zeppelin to the Undercity and follow the road south through Silverpine and towards Hillsbrad. Follow the signs!", description = "Take a sample of the mixture to Serge Hinott in Tarren Mill.\n\nIf anyone can cure you, it's Serge. Live long enough and Serge will show you the ways of poison creation and use.", progress = "What's this???", completion = "You look deliciously pale, &lt;class&gt;. And what is that foul aroma you are giving off? I must know!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2480] = {title = "Hinott's Assistance", objective = "Wait for Serge Hinott to complete the cure.", description = "I have never seen such wondrous results from a poison! Zanzil you say? Never heard of him, however, I must commend him on the creation of this concoction.\n\nSo, I am to cure you of this and then teach you how to make use of the poison?\n\nGive me a few moments to examine the toxin, <name>.", progress = nil, completion = "The cure is ready! Drink this anti-toxin and the creeping madness will stop, however, I will not be able to do anything about the smell.", rewards = "The following spell will be cast on you:\n\nPoisons\n\nYou will receive:\n\nHinott's Oil"}
MultiLanguageQuestData['en'][2498] = {title = "Return to Denalan", objective = "Rellian Greenspyre wants you to speak with Denalan at Lake Al'Ameth.", description = "I have just received word that  Denalan at Lake Al'Ameth has discovered what may be the cause of the tumors that plague the timberlings. Please speak with him, and tell him I sent you.\n\nMake haste, <name>; he needs our help.", progress = nil, completion = "Ah, so Rellian sent you to aid me. I am glad you arrived here so soon.\n\nI have discovered something quite disturbing!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2499] = {title = "Oakenscowl", objective = "Denalan at Lake Al'Ameth wants you to collect the Gargantuan Tumor from Oakenscowl.", description = "In a cave along the southern bank of the lake, a timberling named Oakenscowl is spreading corruption to all the creatures that make Lake Al'Ameth their home.\n\nI dared not get too close, but even from a distance, it is obvious: Oakenscowl is being poisoned by the largest tumor I have ever seen...  I would call it gargantuan, even.\n\n<name>, you have already done much to aid my efforts, but I ask of you one more task. Hunt down Oakenscowl and collect the tumor; remove this source of corruption from my home.", progress = "Have you located Oakenscowl yet, <race>?", completion = "I knew you were more than capable of ridding the lake of that horrible beast.\n\nIt is a distressing situation; Oakenscowl was once a grand leader amongst his kind... but corruption does not discriminate between the lowly and the noble.\n\nThe size of this tumor is quite disturbing, but I must study it to learn more about the disease that upsets the timberling population.\n\nThank you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nDirtwood BeltMoss-covered Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2500] = {title = "Badlands Reagent Run", objective = "Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar.", description = "<class>, I would make use of your services.  I am an alchemist of some note, and I seek your aid in acquiring some reagents found out in the Badlands.\n\nI need the following items to replenish my stocks: five buzzard gizzards, ten crag coyote fangs, and five rock elemental shards.  Obviously, you can get them off of the beasties themselves; if you're not the fighting type, then find friends who are.\n\nAcquire these items for me, you'll get some coin out of the deal.\n\nWell, what say ye?", progress = "Have you gotten the things I need yet?  You won't get paid unless you bring me those reagents.", completion = "Ah, well done &lt;name&gt;.  These should last me for a little while at least.  Here is your pay, as promised.\n\nIf you're interested, I have some more reagents I could use.  These, however, are only found in the depths of the Uldaman excavation.  They will not be easy to get, but I will make it worth your while if you are interested in helping me again.\n\nPerhaps something more than some shiny coins, yes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2501] = {title = "Badlands Reagent Run II", objective = "Use the empty thaumaturgy vessels on scorched guardian dragons found in the Badlands. Once you have them filled, bring them to Ghak Healtouch in Thelsamar.", description = "You have been most helpful to me, <name>.  I would like to reward you with the very recipe for the brew I gave you earlier, but I must ask of you a favor that is quite dangerous.\n\nThis lockbox contains three empty thaumaturgy vessels; they are imbued with an attunement aura that will drain the blood of a scorched guardian dragon.  Using one on the beast will anger it greatly, so be careful.  Once you have all three filled, bring them to me.\n\nDo this, and the recipe will be yours.", progress = "Have you used the vessels to get me the scorched guardian dragon blood I need?  Yes, I know it is a dangerous task... but the recipe for my restorative brew awaits your success.  Risk and reward, my friend... risk and reward...", completion = "From one alchemist to another, I salute you.  Here, take this recipe and commit it to your knowledge.  May it bring you the success and rewards that it has brought me over the years!", rewards = "The following spell will be cast on you:\n\nRestorative Potion\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2518] = {title = "Tears of the Moon", objective = "Priestess A'moora in the Temple of the Moon at Darnassus wants you to bring her Lady Sathrah's Silvery Spinnerets.", description = "Lady Sathrah was once beloved of Elune. Graceful and pure, the spider spun her silver threads through the moonlight, catching the evening mist. The silvery dew had strong healing powers and was kept here in the temple.\n\nBut of late, Sathrah has descended into madness. Her future generations are now threatened as well.\n\nFind Lady Sathrah, <name>, and end her suffering. She dwells along the northern borders of Teldrassil, near Wellspring Lake. Gather her silvery spinnerets and bring them back to me.", progress = "I regret the task that I have asked you to carry out; but Lady Sathrah is beyond hope.\n\nIt is our hope to offer the sacrifice of the spinnerets to Elune. With this sacrifice, Elune will bless Sathrah so that she might be reborn, and at peace.", completion = "The forest mourns for Lady Sathrah, but it was something that had to be done.\n\nThank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2519] = {title = "The Temple of the Moon", objective = "Sister Aquinne wants you to speak with Priestess A'moora in the Temple of the Moon.", description = "A once great creature of the forest is in need of help, <race>.\n\nThere is a difficult task that must be done.\n\nPlease seek out Priestess A'moora; she will explain things to you. Find her to the southeast of here, inside the Temple of the Moon.", progress = nil, completion = "So, Sister Aquinne sent you?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2520] = {title = "Sathrah's Sacrifice", objective = "Priestess A'moora wants you to place Lady Sathrah's silvery spinnerets at the fountain inside the temple, and then return to her.", description = "Now you must finish the task to which you have been appointed. Take the spinnerets and offer Lady Sathrah's sacrifice to Elune; lay the great spider to rest.\n\nInside this temple, find the central fountain. There is where you may leave the sacrifice.  The holy waters will purify and cleanse the corruption that drove Sathrah mad.\n\nWhen you have completed this, return to me.", progress = "Have you placed the sacrifice at the fountain, <name>?", completion = "The loss of Lady Sathrah is distressing, but in this way only may she be reborn with a renewed spirit.\n\nMay Elune willingly accept the sacrifice that you have offered her.", rewards = "You will be able to choose one of these rewards:\n\nLace PantsCushioned Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2521] = {title = "To Serve Kum'isha", objective = "In your journeys throughout the Blasted Lands, should you ever come across a Flawless Draenethyst Sphere, take the item back to Kum'isha the Collector.\n\nBe warned, this gem is one of the most rare crystals in all of Azeroth. Any creature in these lands could be holding a Flawless Draenethyst Sphere.\n\nYou will be rewarded for each Flawless Draenethyst Sphere you have collected.", description = "<race>, can your miniscule brain comprehend the rarity of a flawless sphere of draenethyst? Draenei have spent lifetimes in search of just one of these crystals, only to meet horrible fates, their purpose unfulfilled.\n\nSo you stand before Kum'isha, knowing what Kum'isha has requested and still wish to assist? Very well, <race>... At any time during your travels across these lands, should you find a flawless sphere of draenethyst, return it to me and I shall reward you with riches beyond your wildest dreams.", progress = "I have dedicated my life to the search of flawless draenethyst spheres. A lifetime, <race>!", completion = "Do my eyes deceive me? Impossible! Where did you... How...\n\nPerhaps now a rift can be opened, returning us to our homeland.", rewards = "You will receive:\n\nEmerald Encrusted Chest"}
MultiLanguageQuestData['en'][2522] = {title = "Kum'isha's Endeavors", objective = "Find and return a Flawless Draenethyst Sphere to Kum'isha the Collector.", description = "Even though the portal conjuration was a failure, I remain hopeful that my next attempt will be successful.\n\nThe hope of the Draenei is as fervent as your greed for trinkets, <race>. Go back out into these cursed lands and recover another flawless draenethyst sphere.\n\nOf course, the choice to take on this task is completely left to you *grin*.", progress = "Have you found another flawless draenethyst sphere?", completion = "Simply amazing. I had doubted that you could find another sphere, yet here it is, pulsating in my hands.\n\nWell done, &lt;name&gt;!\n\nShould you find anymore--and I believe this to be an impossibility--return them to me and I shall reward you again.", rewards = "You will receive:\n\nEmerald Encrusted Chest"}
MultiLanguageQuestData['en'][2523] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][2541] = {title = "The Sleeping Druid", objective = "Bring a Shaman Voodoo Charm to Oben Rageclaw in the Ban'ethil Barrow Den.", description = "The Gnarlpine shaman that inhabit this place have discovered a way of separating a sleeping druid's spirit from the physical body. The furbolg have animated my physical form and are using it to attack anyone that attempts to explore the Ban'ethil Barrow Den. I am now trapped in the Emerald Dream, powerless to stop this.\n\nYou must help me. The Gnarlpine shaman carry a strange charm which is used to perform this ritual, and I'd like to examine it. Please, <name>, bring one to me.", progress = "If I can examine the charm, I may be able to figure out how to break the enchantment. Have you found one?", completion = "Thank you, &lt;name&gt;.\n\nWhat an odd trinket this is... I can sense the vile aura emanating from it; this is a very powerful enchantment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2561] = {title = "Druid of the Claw", objective = "Oben Rageclaw wants you to kill his soulless body, and then use the Voodoo Charm.", description = "After examining this charm, <name>, I see now what must be done. Please take it, and do as I ask.\n\nYou are to explore the deepest areas of the Ban'ethil Barrow Den. There, you will find my soulless body... Although I regret what I am about to tell you, I see no other way to free myself from the control of the Gnarlpine.\n\nIn order for me to escape them, you must kill my physical form.  Once that is done, use the voodoo charm on my fallen body. After you have completed this task, please return to me.", progress = "<name>, be wary when approaching my physical form; the enchantment it is under is quite powerful.", completion = "I am finally free of the control of the Gnarlpine. Thank you, &lt;name&gt;.\n\nMy spirit may now rest peacefully forever in the Emerald Dream.\n\nPerhaps one day we may meet again, young &lt;class&gt;. But, for now, please accept this reward as a symbol of my gratitude.", rewards = "You will be able to choose one of these rewards:\n\nSleeping RobesBrushwood Blade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2581] = {title = "Snickerfang Jowls", objective = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", description = "It is a well known fact that hyenas possess tremendous strength in their jowls, but the strength to snap through three inches of thorium steel? Impossible, improbable, and yet I have seen this demonstrated with my own eyes.\n\nVenture forth, into the Blasted Lands, and bring me three snickerfang jowls. As you search for the snickerfang, be on the lookout for boars and scorpoks: The initial assay also requires two blasted boar lungs and one scorpok pincer to complete.", progress = "You smell foul, <name>. Have you been traipsing in sulfur fields? And where are my components?!", completion = "How do you feel, &lt;name&gt;? You radiate with the aura of the snickerfang--your strength, unmatched by mortals!\n\nUnfortunately, with the components you brought to me, I could only make enough of the assay for one tablet. I will require more components, should you require another tablet.", rewards = "The following spell will be cast on you:\n\nRage of Ages\n\nYou will receive:\n\nR.O.I.D.S."}
MultiLanguageQuestData['en'][2582] = {title = "Rage of Ages", objective = "Bring three Snickerfang Jowls, two Blasted Boar Lungs, and one Scorpok Pincer to Bloodmage Drazial.", description = "Ah, <name>, welcome back. It seems you enjoyed the effect of the robust, operational imbue, derived from snickerfang. Be warned, while the immediate effect is a titanic burst of strength, the long term effects on your spirit and intelligence could be hazardous.\n\nWith that said, do you require more? If so, bring me another three snickerfang jowls, two blasted boar lungs, and one scorpok pincer.", progress = "Do you have the beast organs?", completion = "There you go! Remember, use it sparingly. If you require another, come see me after you finish the one you currently have in your possession.", rewards = "You will receive:\n\nR.O.I.D.S."}
MultiLanguageQuestData['en'][2583] = {title = "A Boar's Vitality", objective = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", description = "Within these blasted lands exists two species of boar: the ash-mane boar and the helboar.\n\nIt would appear that the stamina of these beasts renders them nearly immune to harm, as the other animals find them too difficult to kill and consequently, not worth the effort.\n\nWe need to perform further analysis, <name>. Should you bring me three blasted boar lungs, two scorpok pincers, and one basilisk brain, I shall create a divine elixir from the residue of the assay. You will be my first test subject!", progress = "Where are the organs, <name>!?", completion = "The spirit of the boar illuminates your being, &lt;name&gt;! I wonder, do you believe yourself to be as invulnerable as these beasts?", rewards = "The following spell will be cast on you:\n\nSpirit of Boar\n\nYou will receive:\n\nLung Juice Cocktail"}
MultiLanguageQuestData['en'][2584] = {title = "Spirit of the Boar", objective = "Bring three Blasted Boar Lungs, two Scorpok Pincers, and one Basilisk Brain to Bloodmage Drazial.", description = "When I first administered the elixir, <name>, I could tell that one or two applications would not satiate your appetite. Even now, I can see the hunger in your eyes. The concoction has addictive properties of which, seemingly, the most strong of will cannot resist.\n\nSo be it! Should you require more of the lung juice cocktail, venture back into the wasteland and find for me three blasted boar lungs, two scorpok pincers, and one basilisk brain.", progress = "Where are the organs, <name>!?", completion = "I must warn you, &lt;name&gt;, do not attempt to mix the formulas I have created. The chemical properties of the formula you most recently ingested will always take precedence over former enchantments; thus, rendering the other formulation null.", rewards = "You will receive:\n\nLung Juice Cocktail"}
MultiLanguageQuestData['en'][2585] = {title = "The Decisive Striker", objective = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", description = "Have you ever watched them in battle, <name>? The scorpoks, I mean. Have you ever seen the grace and agility with which they move? The decisiveness of their strikes?\n\nIf only we could somehow isolate that agility and encapsulate it, we would be wealthy beyond our... I mean... it would be a boon for the scientific community.\n\nAssist me, <name>, and I shall allow you a sampling of the assay.\n\nIn order to create a stable sample, I will need three scorpok pincers, two vulture gizzards, and one blasted boar lung.", progress = "Where are the organs, <name>!?", completion = "Fascinating. This has been the most difficult of all assays to analyze.\n\nTake a pinch of this residual salt and place it under your tongue. You should experience a slight feeling of euphoria followed by a state of unprecedented agility and quickness.", rewards = "The following spell will be cast on you:\n\nStrike of the Scorpok\n\nYou will receive:\n\nGround Scorpok Assay"}
MultiLanguageQuestData['en'][2586] = {title = "Salt of the Scorpok", objective = "Bring three Scorpok Pincers, two Vulture Gizzards, and one Blasted Boar Lung to Bloodmage Drazial.", description = "You live! This is good news, indeed. I assume you are back for more of the scorpok assay?\n\nVery well, <name>, back to the wasteland with you and do not return until you have collected three scorpok pincers, two vulture gizzards, and one blasted boar lung.", progress = "Where are the organs, <name>!?", completion = "Fine work, &lt;name&gt;. Here is one sample of the assay for you and the remaining nine will be used in my research.\n\nAnytime you require more of the ground scorpok assay, return to me and we shall work out a deal.", rewards = "You will receive:\n\nGround Scorpok Assay"}
MultiLanguageQuestData['en'][2601] = {title = "The Basilisk's Bite", objective = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", description = "These wastelands are riddled with redstone basilisk, <name>. These basilisk have adapted and flourished, more so than any of the other wildlife within the region.\n\nI have watched from afar as they hunt and go about their daily activities - the beasts exhibit a thought process more complex than even some humanoids.\n\nI must study their brains!\n\nRetrieve ten of their brains for me, <name>. The compound cannot be complete, however, without two vulture gizzards to form the base of the solution.", progress = "Have you returned with the requested organs?", completion = "This is wondrous, &lt;name&gt;! My offering to you is a taste of the inner workings of the redstone basilisk.\n\nShould the compound be to your liking, more can always be made... for a price.", rewards = "The following spell will be cast on you:\n\nInfallible Mind\n\nYou will receive:\n\nCerebral Cortex Compound"}
MultiLanguageQuestData['en'][2602] = {title = "Infallible Mind", objective = "Bring ten Basilisk Brains and two Vulture Gizzards to Bloodmage Lynnore.", description = "Your focused concentration has dwindled so soon? More research must be done!\n\nOh yes, the price remains the same, <name>. Venture forth into the blasted lands and return to me with ten brains from the redstone and two vulture gizzards.", progress = "Have you returned with the requested organs?", completion = "Yes, yes, give me a moment and more of the compound will be ready for your consumption, &lt;name&gt;.\n\nTake it... and &lt;name&gt;, do not attempt to consume these experimental concoctions in rapid succession. The results could be disastrous.", rewards = "You will receive:\n\nCerebral Cortex Compound"}
MultiLanguageQuestData['en'][2603] = {title = "Vulture's Vigor", objective = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", description = "Death does indeed have wings in these blasted lands, <race>. I have witnessed the black slayers and bonepickers feasting upon the corpse of many a fallen explorer - sometimes feeding upon the most vile and disease ridden of carcasses. It is a wonder, then, how their internal systems overcome the pestilence that claims these lands.\n\nAssist me in my studies, <name>! Gizzards I need! Two snickerfang jowls will also be required for the base of the concoction.\n\nYou shall be rewarded two-fold for your efforts.", progress = "Do not waste my time, <name>. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Most excellent! I shall get to work immediately. Perhaps a cure for many of the ailments of the world is to be found!\n\nAh yes, your reward - of course, should you require more of the gum, return to me and another task you shall be given.", rewards = "The following spell will be cast on you:\n\nSpiritual Domination\n\nYou will receive:\n\nGizzard Gum"}
MultiLanguageQuestData['en'][2604] = {title = "Spiritual Domination", objective = "Bring ten Vulture Gizzards and two Snickerfang Jowls to Bloodmage Lynnore.", description = "I see that the inner fire has dwindled. Would you say the spiritual euphoria lasted an hour?\n\nIf it's more of the gizzard gum you desire, then more of the gizzards I require. Back to the wastelands, <name>. Do not return until you have recovered ten gizzards and two jowls.", progress = "Do not waste my time, <name>. We have nothing to discuss, unless you have recovered the items I have requested.", completion = "Perhaps one day I shall be able to isolate the active enzymes of this assay and produce a much more efficient resultant. Unfortunately, you will have to settle for what I am currently able to produce. Return to me should you require more gizzard gum.", rewards = "You will receive:\n\nGizzard Gum"}
MultiLanguageQuestData['en'][2605] = {title = "The Thirsty Goblin", objective = "Collect a Laden Dew Gland and bring it to Marin Noggenfogger in Gadgetzan.", description = "I've got an idea, see. I've heard of some strange creatures called dew collectors that live to the southwest... and that they are able to store water in special glands.\n\nI think that if I could get one of these glands, I could create a drink that would quench my terrible thirst! Do you think you could help me, <name>?\n\nLook for the cactus garden, <name>; that's where you'll find the dew collectors.", progress = "Please, tell me you found the dew collectors?", completion = "Oh, wonderful! Give it here -- let me drink it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2606] = {title = "In Good Taste", objective = "Marin Noggenfogger wants you to speak with Sprinkle in Gadgetzan.", description = "Blech! This stuff tastes terrible! So much for that idea...\n\nWait, what's that? Oh, I know, I know, you think I shouldn't give up on this stuff. Well, okay then.\n\nUhhhh, I have an idea! Brilliant! Take this dew to my friend Sprinkle -- she's an excellent chef. Tell her what we're up to here and that we want to make it go down a little easier.\n\nI mean, if it's going to taste that bad, it at least should have some kick to it... And I'm just not feeling it...", progress = "So old Marin's up to it again, eh? What's this concoction made from?", completion = "Marin's a good guy, don't get me wrong -- just a little... eccentric, I'd say.\n\nAnd of course he needs my help, yet again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2607] = {title = "The Touch of Zanzil", objective = "Speak with Doc Mixilpixil in the cellar of the Barracks.", description = "It appears as if you've brought back more information than even I expected. This certainly is a strange turn of events, <name>.\n\nA cure? Hrm... Go down to the cellar and speak with Doc Mixilpixil - he may be able to help.", progress = nil, completion = "It's about time! Just put the cheese on the table and skedaddle. Osborne will pay you on the way out.", rewards = nil}
MultiLanguageQuestData['en'][2608] = {title = "The Touch of Zanzil", objective = "/Lay down to be examined by Doc Mixilpixil. How can he find the cure if he can't find the cause?", description = "Oh my, you look like death. Correction - I've seen death, you look worse than death. You, <sir/miss>, would be what death coughed up at his last physical.\n\nHah! You hear that Noarm? Write that one down!\n\n*Cough* Hrm yes, in order for me to help you, I'll need to draw some blood. Don't worry, it only hurts the first few... fifty times or so... /lay down when you're ready for the treatment, <name>.", progress = "When you're ready for the examination, /lay down on the ground and I'll begin the phlebotomy.", completion = "Give me a moment to confer with my colleagues, &lt;name&gt;. Dr. Montgomery, Mr. Noarm, let us conference!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2609] = {title = "The Touch of Zanzil", objective = "Bring Doc Mixilpixil one bundle of Simple Wildflowers, one Leaded Vial, one Bronze Tube, and one Spool of Light Chartreuse Silk Thread. The 'itis' doesn't cure itself, young <fella/lady>.", description = "It's unanimous, <name>. You've got the 'itis.'\n\nLuckily, I have a cure for the 'itis.'\n\nHere's what I need: One bundle of simple wildflowers, one leaded vial, one bronze tube, and last but certainly not least, one spool of light chartreuse silk thread. Ol' Emma left a spool of it for me at 'The Finest Thread.' You can find the shop along the canals.\n\nHurry along now, <name>, and try not to touch anyone until you're cured. Oh, and Dr. Montgomery says you need a shower -- his words, not mine.", progress = "If you want the 'itis' cured, you're going to have to try harder than that, <name>. Where are the reagents for the cure?", completion = "What am I doing? What does it look like I'm doing? I'm devising a cure for your 'itis!' Don't get indignant with me now, &lt;name&gt;!\n\nJust a few more seconds. There! Just spray this, um, fantastic smelling medicine on yourself and you'll be as good as new.", rewards = "You will receive:\n\nEau de Mixilpixil"}
MultiLanguageQuestData['en'][2621] = {title = "The Disgraced One", objective = "Speak to Dispatch Commander Ruag in Stonard.", description = "Regret. It is all I have now. One bad decision resulting in several horrible outcomes. If only I had waited for those orders. Maybe they would have detailed the horrors that awaited us in those cursed lands! Maybe they were to redirect us to another detail? Ultimately, it was my fault. All of it was my fault.\n\nSo here I stand, awaiting orders. I must know. I must have those orders.\n\nDispatch Commander Ruag resides in Stonard. Find him and find out what became of the orders.", progress = nil, completion = "Thrall's Grasp... The story is still fresh in my mind.\n\n&lt;Commander Ruag shakes his head.&gt;\n\nTerrible thing that happened to that regiment. The horde lost some of its best soldiers when that battalion was destroyed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2622] = {title = "The Missing Orders", objective = "Speak to Bengor.", description = "The orders? What could you possibly want with the orders?\n\nWhat are you implying, <name>? Of course I relayed those orders! The soldiers I sent the orders with were ambushed and brutally beaten by murlocs. Only one survived, if you can call that surviving. He can hardly speak, cannot walk, and must be fed through a tube. If you want to know what happened to those orders, speak with Bengor. I'm sure he is around here somewhere... and, <name>, be mindful of what you stick your nose into - it may get bitten off.", progress = nil, completion = "Swamp tal... talk.. talker...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2623] = {title = "The Swamp Talker", objective = "Retrieve the Warchief's Orders and return them to the Fallen Hero of the Horde.", description = "Orders were given by the dispatch commander. We took... took orders. On way to Blasted Lands, ambushed.\n\nMurlocs... Many murlocs... One named Swamp Talker. Took orders from my hands as spear thrust into my skull. East... cave....\n\n<Bengor passes out.>", progress = "Awaiting orders.", completion = "It is worse than I imagined. Nineteen of my men could have been spared from the agony which they faced. If only I had not acted so irrationally.\n\nYou must help them, &lt;name&gt;! I am powerless to act.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2641] = {title = "Sprinkle's Secret Ingredient", objective = "Sprinkle in Gadgetzan wants you to collect a Violet Tragan and return it to her.", description = "When I was a kid, my sister used to do all the cooking. It was horrible! I could barely stomach some of her concoctions -- until I found what I like to call my \"secret\" ingredient! Add it to anything, and... WOW! It tastes great!\n\nWhat is it, you ask? It's a mushroom called the Violet Tragan. If you want me to help you turn this horrid-tasting brew into something edible, head to the Hinterlands, and look for a small lake there.\n\nOh, and remember, the Violet Tragan can only be found underwater.", progress = "Under the waters of that lake -- it's the only place where the Violet Tragan can be found.  Hope you're good at holding your breath!", completion = "That's the stuff, &lt;name&gt;!\n\nIt looks so good, I might just...  Haha, gotcha!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2661] = {title = "Delivery for Marin", objective = "Sprinkle wants to you take the Violet Powder to Marin Noggenfogger in Gadgetzan.", description = "Here's the Violet Powder, <name>. Take it to Marin and tell him he owes me a favor!", progress = "Oh, <name>, you're finally back.  What have you brought?", completion = "Violet Powder, eh? Let's give it a try -- it sure couldn't make it any worse, that's for sure!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2662] = {title = "Noggenfogger Elixir", objective = "Marin Noggenfogger wants you to speak to him again after he creates his elixir.", description = "Now, to mix this powder in with the dew.\n\nCome back and talk to me in a minute... after I have perfected the fabulous Noggenfogger Elixir!", progress = nil, completion = "Drink this! It's absolutely wonderful!!!\n\nI knew I had it in me... Oh thanks again, &lt;name&gt; for your help, but please, stand a little to the side, will you? You're blocking my business! I'm going to make millions on the fabulous Noggenfogger Elixir, millions!\n\nWhat's that? Sprinkle says I owe her a favor? Oh, that Sprinkle, such a kidder!", rewards = "You will receive:\n\nNoggenfogger Elixir"}
MultiLanguageQuestData['en'][2681] = {title = "The Stones That Bind Us", objective = "Free nine Servants of Razelikh, three Servants of Sevine, three Servants of Allistarj, and three Servants of Grol. Return to the Fallen Hero when your task is complete. You must remain within close proximity of the stones or the process will fail.", description = "It will take more than you alone to overcome the forces of Razelikh and his subordinates.\n\nGather a suitable group of adventurers and free my men of their eternal torture! Eighteen stones you must shatter.\n\nFight hard and die with honor, <name>.", progress = "It is no easy task, <name>. Do not give up!", completion = "You have done it, &lt;name&gt;! The poor, tortured souls can finally rest.\n\nOur work is not yet over, &lt;name&gt;. We have much to discuss and much more to accomplish.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2701] = {title = "Heroes of Old", objective = "Open the chest and claim your reward.", description = "Please, take from this a relic of old. We no longer have a use for the item.\n\nMay it serve you well in your fight against the legion.", progress = nil, completion = "You are temporarily blinded by the sparkle and gleam.", rewards = "You will receive:\n\nShard of the Splithooves"}
MultiLanguageQuestData['en'][2702] = {title = "Heroes of Old", objective = "Speak to Corporal Thund Splithoof.", description = "You have honored me with your nobility and heroism, <name>.\n\nYou have also honored them...", progress = nil, completion = "Indeed, you have honored us all. Our thanks alone are not sufficient.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2721] = {title = "Kirith", objective = "Find out what became of Lieutenant Kirith.", description = "As one chapter of your adventure closes, another one begins, <name>.\n\nOne of my men is still unaccounted for, lost somewhere in the Blasted Lands. I am talking about Lieutenant Kirith, of course.\n\nAs I had mentioned earlier, we were both imprisoned and tortured by Allistarj, but poor Kirith, his strength of will faltered. I could hear the experiments from my cage; the tortured screams rang through the halls of the cave. That was the last I saw or heard of Kirith.", progress = nil, completion = "Trebor? Trebor sent you?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2741] = {title = "The Super Egg-O-Matic", objective = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", description = nil, progress = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", completion = "You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.\n\nIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that's speedy service!", rewards = "You will receive:\n\nEgg Crate"}
MultiLanguageQuestData['en'][2742] = {title = "Rin'ji is Trapped!", objective = "Escort Rin'ji out of the Quel'Danil Lodge, then find his hidden secret at the Overlook Cliffs to the east.", description = "Hey <race>!\n\nRin'ji lost axe and was captured! Please, help Rin'ji escape. Me know that <race> like you don't like Rin'ji's kind, but Rin'ji begs! Must get out of here!\n\nGot something for nice <race> if <he helps Rin'ji out of here/she helps Rin'ji out of here>...\n\nRin'ji is hiding something secret at the Overlook Cliffs.", progress = nil, completion = "This troll tablet must be the \"secret\" that Rin'ji was talking about.\n\nCovered with strange markings, you can not decipher what the tablet says.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2743] = {title = "The Cover of Darkness", objective = "Return to the Fallen Hero of the Horde with your findings.", description = "Let us not mince words, <race>; my time here is limited.\n\nYou must destroy the triad of power which protects the demon lord, Razelikh. Doing so will not be as simple a task as freeing a damned soul.\n\n<Kirith grins.>\n\nYou see, each of Razelikh's underlings wears a third of an amulet of Razelikh's creation around their neck. The very same amulet you will need in order to summon the arch demon.\n\nReturn to Trebor and tell him what is required to summon Razelikh. He will be able to instruct you further.", progress = nil, completion = "The demon lord displays a cunning almost as calculated as his brutality, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2744] = {title = "The Demon Hunter", objective = "Speak with Loramus Thalipedes in Azshara.", description = "The triad is protected by Razelikh.\n\nIn exchange for their servitude, Razelikh granted each of them nearly unlimited power within the Blasted Lands. The amulet pieces are each attuned to the lifeforce of their owner, granting them immortality. As long as they remain within the Blasted Lands, they cannot be slain, their life spans extended until the end of days.\n\nThere is one who may be able to assist you further, <name>. Travel to Azshara and find the demon hunter, Loramus Thalipedes. Search the islands.", progress = "What are you doing here?", completion = "I will help you. Although, I do not think you fully understand what you are up against.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2745] = {title = "Infiltrating the Castle", objective = "Speak to Tyrion in Stormwind Castle.", description = "Hmm, an interesting tale, and not one to be taken lightly. Yeah, I can help you, but what you need to do is divvy out a form of justice that's not... legal, if you're to see this through to the end.\n\nLescovar and Marzon need to be dealt with, and swiftly. Do you think you're capable of such a thing?\n\nYou decide. If so, then make haste to the castle and find an old friend of mine, a gnome named Tyrion. He's been watching Lescovar now for a couple weeks. He should be able to help you end this.", progress = nil, completion = "What the...?! Don't sneak up on me like that! And keep your voice down! What in the name of the Shadow are you doing sneakin' up on me for? Can't you see I'm busy, you daft fool?\n\nWhat do you mean, what am I doing? I'm waiting for the next Dark Portal to open, what the heck do you think I'm doing? Speak your peace and be off with you... 'fore the guards notice the two of us hiding in the bushes together. I have a reputation to maintain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2746] = {title = "Items of Some Consequence", objective = "Bring 3 Silk Cloth and 2 of Clara's Fresh Apples to Tyrion in Stormwind.", description = "Trias wants the timetable pushed up some, huh? Okay, we can do that, but I'm not ready. And know this, I'm doing the hard part, but you're the one that's going to get <his/her> hands dirty, understand? Good.\n\nOkay, I'll need you to get me a few things before I can put my plan into effect. I got the perfect disguise that'll get Spybot past those guards.\n\nBring me some silk and a couple apples. The silk's up to you, but Clara's little farm right outside the city has the perfect sized apples.", progress = "I've been watching Lescovar for a couple weeks now. Trias has never trusted him, but we didn't suspect he was involved in anything to do with the Defias Brotherhood. We were following leads that tied him to the Twilight's Hammer. Either way, he's become more dangerous than this city can deal with, and that's where we come in.\n\nGet me those items and we can put my plan into effect.", completion = "These will do nicely, &lt;name&gt;. Great job.\n\nI have the rest of the gear I'll need in my pack... thank the Light I just got a tailor friend of mine to make me a silk bag. I was running out of room carrying all my gear around.\n\nBefore Spybot heads in, let's get the details set so you know what you have to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2747] = {title = "An Extraordinary Egg", objective = "I have seen very few eggs retrieved from Feralas in extraordinary condition. These are eggs of the rarest sort...", description = nil, progress = "I have seen very few eggs retrieved from Feralas in extraordinary condition. These are eggs of the rarest sort...", completion = "Well now, you have one -- amazing!\n\nI hope you always remember the good you have done today.", rewards = "You will receive:\n\nBox of Goodies"}
MultiLanguageQuestData['en'][2748] = {title = "A Fine Egg", objective = "A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres' incantations.", description = nil, progress = "A fine egg is one that will, in ideal conditions, hatch free of the evil effects of the Gordunni ogres' incantations.", completion = "Very good, &lt;name&gt;. I will be sending this egg to Darnassus where I hope it will soon hatch!\n\nPlease accept this as a symbol of my gratitude.", rewards = "You will receive:\n\nBox of Spells"}
MultiLanguageQuestData['en'][2749] = {title = "An Ordinary Egg", objective = "Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.", description = nil, progress = "Ordinary hippogryph eggs hatch about half the time. We do our best to nurture them and with a little luck, they will hatch.", completion = "So, you have found an ordinary egg, &lt;name&gt;? Please give it to me... And we can only hope for the best.\n\nI don't have much, but please accept this reward. If you ever find yourself in Feralas again, know that I am always here to take the eggs you find there.", rewards = "You will receive:\n\nBox of Rations"}
MultiLanguageQuestData['en'][2750] = {title = "A Bad Egg", objective = "These are the eggs that cannot be saved -- they will never hatch.", description = nil, progress = "These are the eggs that cannot be saved -- they will never hatch.", completion = "I am afraid I have bad news for you, &lt;name&gt;. This egg is too far gone. I can take it from you so that it may be disposed of properly.\n\nPlease don't be discouraged; we cannot save them all. If you find yourself in Feralas again, please try again. Bring another egg for the Super Egg-O-Matic!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2751] = {title = "Barbaric Battlements", objective = "Bring two Patterned Bronze Bracers, two Bronze Greatswords, and two Sharp Claws to Orokk Omosh in Orgrimmar.", description = "Twenty generations of Omosh have held this hammer, <name>. A hundred thousand tons of metal we have molded. Tragically, it all ends at Orokk, failure of the Omosh: Without kin and incapable of producing offspring.\n\nI cannot let the secret recipes of Omosh die with me! Someone must continue the legacy, Omosh or not!\n\nProve to Orokk you are capable, <name>. Bring for Orokk the following: Two patterned bronze bracers, two bronze greatswords, and two sharp claws. Bring them for Orokk and we shall continue.", progress = "Bronze, <name>! More bronze!!", completion = "The bloodline will fade but perhaps the legend of Omosh will continue!\n\nYou have proven that you are a blacksmith, &lt;name&gt;. For the blacksmith the reward is the satisfaction of seeing their weapons and armors coated in the blood of their enemies!\n\nMay the breastplates you create for the generations ahead be drenched in the blood of your enemies!", rewards = "You will receive:\n\nPlans: Barbaric Iron Breastplate"}
MultiLanguageQuestData['en'][2752] = {title = "On Iron Pauldrons", objective = "Bring four Bronze Battleaxes and four Bronze Warhammers to Orokk Omosh in Orgrimmar.", description = "Orokk sees the eagerness in your eyes, <name>. Like a sponge you soak in the wisdom of the Omosh.\n\nThree lessons I shall teach!\n\nReturn to the anvil, soak in the heat of the forge, create for Orokk four bronze battleaxes and four bronze warhammers. Only then will you learn of the iron pauldron.", progress = "Show me your dedication, <race>.", completion = "You do Orokk proud, &lt;name&gt;. Read, learn of iron shoulders!", rewards = "You will receive:\n\nPlans: Barbaric Iron Shoulders"}
MultiLanguageQuestData['en'][2753] = {title = "Trampled Under Foot", objective = "Bring four Green Iron Helms, four Green Iron Bracers, and two Green Iron Leggings to Orokk Omosh in Orgrimmar.", description = "Only two more lessons Orokk will teach, <name>. Your muscles ache, I know, but continue on for the Omosh!\n\nBring to Orokk four green iron helms, four green iron bracers, and two green iron leggings - for this you learn and your enemies suffer!", progress = "Their skulls will crack under the pressure of your boots!", completion = "You remind Orokk of his grandfather, Chief Gorokk of Omosh! Read, learn of the iron boot.", rewards = "You will receive:\n\nPlans: Barbaric Iron Boots"}
MultiLanguageQuestData['en'][2754] = {title = "Horns of Frenzy", objective = "Bring two Solid Iron Mauls, two Silvered Bronze Boots, and two Silvered Bronze Gauntlets to Orokk Omosh in Orgrimmar.", description = "The final lesson Orokk teaches you, <name>. To the sacred anvil and forge you return! Bring for Orokk two solid iron mauls, two silvered bronze boots, and two silvered bronze gauntlets.\n\nSee the fear in their eyes as you approach!", progress = "Show the iron who is in charge, <name>!", completion = "Astounding! You have learned the way of the Omosh, &lt;name&gt;!", rewards = "You will receive:\n\nPlans: Barbaric Iron Helm"}
MultiLanguageQuestData['en'][2755] = {title = "Joys of Omosh", objective = "Watch and learn the Omosh Dance of Joy.", description = "Orokk is not crying, <name>. Soot is in eye.\n\n<Orokk wipes a tear away.>\n\nThere is one last Omosh family secret Orokk will teach you. Orokk will die happy, thanks to <name>.\n\nLearn Omosh dance of joy and then you learn fist of iron!", progress = nil, completion = "&lt;Orokk pants.&gt;\n\nIt has been a very long time since Orokk has done the Omosh dance of joy. Learn now, &lt;name&gt;!", rewards = "You will receive:\n\nPlans: Barbaric Iron Gloves"}
MultiLanguageQuestData['en'][2756] = {title = "The Old Ways", objective = "Bring four Steel Breastplates and four Steel Plate Helms to Aturk the Anvil in Orgrimmar.", description = "In the time of legends, Aturk would crush the skulls of his enemies and grind the bone into a fine powder for use in filament. Long gone are those days, <race>. The Warchief calls for peace among the clans. Old enemies are now only watched with weary eyes!\n\nUnbelievable, I know, but such is the will of Thrall.\n\nEnough lamenting! You are here to learn, and learn you will! Bring me four steel breastplates and four steel helms and you will gain a taste of war!", progress = "Aturk, like time, waits for no one! Hurry up fool!", completion = "It seems you are but another complacent lemming of the Warchief, &lt;name&gt;. How disappointing.\n\nHow I long for a glorious death upon the battlefield. Instead, I am stuck here, by order of Thrall, to teach infants how to craft! Watch and learn, child!", rewards = "The following spell will be cast on you:\n\nTeach Orcish War Leggings\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2757] = {title = "Booty Bay or Bust!", objective = "Speak with McGavan in Booty Bay.", description = "Listen, kid, you're not gonna learn anything hanging around here.\n\nI know a guy who knows a guy. He hangs around the smithy in Booty Bay. If you show him this insignia, he'll tell you all about mithril.\n\nSo whadd'ya say? Leave this kid stuff to the babies in diapers, <name> -- it's time to move on.\n\nIf you're interested, his name's McGavan. Show him this trinket and he'll recognize your commitment.", progress = "A rare breed your kind be, matey. Let me see that insignia.", completion = "By Blackhoof's back hair -- finally, one worthy of the Mithril Order!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2758] = {title = "The Origins of Smithing", objective = "Bring six Golden Scale Bracers to Hank the Hammer in Stormwind.", description = "When I was about your age, a dwarf by the name of Galvan took me under his wing and trained me in the ways of the armorsmith. Before he left for Booty Bay, he made me promise to train all those with the desire and determination to advance in the craft of blacksmithing -- so here I am -- all these years later.\n\nSo, now it's time for you to learn a little something. Make me six golden scale bracers and you will learn where smithing comes from, <name>.", progress = "Could you be the next Galvan protege?", completion = "Very good, &lt;name&gt;! Listen and learn.\n\nBlacksmithing never comes from here! \n\nBlacksmithing never comes from here! \n\nBlacksmithing only comes from here! \n\nAnd now you know the origin of blacksmithing.", rewards = "You will receive:\n\nPlans: Golden Scale Gauntlets"}
MultiLanguageQuestData['en'][2759] = {title = "In Search of Galvan", objective = "Speak with McGavan in Booty Bay.", description = "Although Galvan left Booty Bay many years ago, members of the order still remain in town, hoping to one day find another worthy of Galvan's tutelage.\n\nTake this insignia and present it to McGavan in Booty Bay.\n\nIf you actually make it that far, he'll know that you are worthy. I have faith, <name>!", progress = "A rare breed your kind be, matey. Let me see that insignia.", completion = "By Blackhoof's back hair -- finally, one worthy of the Mithril Order!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2760] = {title = "The Mithril Order", objective = "Speak with Galvan the Ancient in Stranglethorn Vale.", description = "Most of our recruits never make it to Booty Bay, <name>. The shine of the insignia is enough to trigger the loot lust in even the staunchest of blacksmiths. Fools they be, as the insignia is a drop in the bucket compared to the wealth of items you'll see!\n\nFind Galvan the Ancient and show him this pin. His residence is far to the north, between Zul Gurub and the Mosh'Ogg ogre mound.", progress = "Hail! Come closer; show Galvan what you have.", completion = "Ah, many years it has been since one has been worthy of the Mithril Order's initiation. We will start now!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2761] = {title = "Smelt On, Smelt Off", objective = "Bring forty Mithril Bars and forty Iron Bars to Galvan the Ancient in Stranglethorn.", description = "Many blacksmiths believe that mining and smithing are separate, independent jobs; but can there be blacksmithing without mining? Ah ha -- it is an impossibility! The accomplished blacksmith must also be an accomplished miner.\n\nShow Galvan that you are capable, <name>. Bring me forty bars of iron and forty bars of mithril. For this, Galvan will teach you the ways of the ornate mithril pants!", progress = "After such mining, your muscles bulge and your body aches!", completion = "Your work ethic is impeccable, &lt;name&gt;! You are starting to understand the ways of Galvan mineralogy! Take this and learn from it all that you can.", rewards = "You will receive:\n\nPlans: Ornate Mithril Pants"}
MultiLanguageQuestData['en'][2762] = {title = "The Great Silver Deceiver", objective = "Bring forty Mithril Bars and five Truesilver Bars to Galvan the Ancient in Stranglethorn.", description = "It is said that truesilver is stronger and more durable than mithril. Galvan does not disagree with this assessment of the minerals, but contrary to its name, truesilver is not true! Mithril is a far nobler mineral! HAH! Regardless, for this lesson you will need to find the great silver deceiver, <name>.\n\nBring me forty bars of mithril and five bars of truesilver. In exchange, you will be taught the secret of ornate mithril gloves and more importantly, learn that truesilver is a liar!", progress = "After such mining, your muscles bulge and your body aches!", completion = "She's a cruel mistress, is she not, &lt;name&gt;? I'm speaking of truesilver, naturally. Aye, Galvan spent over a decade in the mountains of Alterac learning this lesson. Take this and learn from it all that you can!", rewards = "You will receive:\n\nPlans: Ornate Mithril Gloves"}
MultiLanguageQuestData['en'][2763] = {title = "The Art of the Imbue", objective = "Bring forty Mithril Bars and four Citrines to Galvan the Ancient in Stranglethorn.", description = "The harvesting of precious gems is of utmost importance to our craft, <name>. Few gems are more precious than the citrine. The magical properties we imbue into our goods are amplified greatly by the presence of citrine.\n\nFor this lesson, we will fortify forty bars of mithril with four citrines. The result will be a better understanding of magical gemology and the knowledge to create ornate mithril shoulders.", progress = "After such mining, your muscles bulge and your body aches!", completion = "One can barely keep their eyes from leaving its splendor, &lt;name&gt;. Aye, citrine is a glorious gem.\n\nPay attention and learn what such a discovery may teach us!", rewards = "You will receive:\n\nPlans: Ornate Mithril Shoulder"}
MultiLanguageQuestData['en'][2764] = {title = "Galvan's Finest Pupil", objective = "Speak with Trenton Lighthammer in Gadgetzan.", description = "If you are ready to conclude your training with Galvan, you should journey to Gadgetzan.\n\nThere, you will find my finest pupil: Trenton Lighthammer. He has much to teach you in the ways of ornate mithril. Otherwise, remain here and learn!\n\nOh, Gadgetzan is in Tanaris, of course!", progress = nil, completion = "Galvan the Ancient sent you??\n\n&lt;Trenton bows.&gt;\n\nIt is a great honor to meet another of the master's pupils!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2765] = {title = "Expert Blacksmith!", objective = "Claim your reward from Galvan the Ancient!", description = "When you first came to me, I knew that you would turn out to be one of my finest pupils! It was without hesitancy that you gave up a trinket of some power to McGavan. You did this only so that you could meet me. Such blind faith and devotion to the craft should be rewarded.\n\nYou have attained expertise over blacksmithing, <name>. Reap the rewards!", progress = "Claim your reward!", completion = "It is only fitting that you receive a trinket of far greater power than the one you sacrificed to get here. Use it in good health, &lt;name&gt;.", rewards = "You will receive:\n\nSignet of Expertise"}
MultiLanguageQuestData['en'][2766] = {title = "Find OOX-22/FE!", objective = "Take the distress beacon to Oglethorpe's homing robot in a cave near Feral Scar Vale.", description = "You have uncovered some sort of strange, egg-shaped device made from metal.  Fiddling with one of its knobs springs the egg to life, as it opens up into some sort of gnomish robotic contraption!  A voice from inside the robotic egg crackles to life.\n\n\"My name's Oglethorpe Obnoticus, and my homing robot has crashed!  I will reward you for its recovery; please take this beacon to the robot!\"\n\n\"I now have computed the coordinates of the robot for you; it is in a cave near Feral Scar Vale!\"", progress = "You appear to have uncovered the wreckage of... a robotic chicken?  The voice from within the egg crackles to life again:\n\n\"Yes, excellent work!  This is indeed my homing robot, though my sensors indicate that it needs a jump start before it can fly back to Booty Bay for repairs.  Go ahead and place the beacon inside the rover - the beacon will take care of the rest!\"", completion = "You place the egg... distress beacon... inside the chicken... homing robot.\n\nHums and whirs are heard from inside the robot as it struggles to stand up.  After the robot comes to life, Oglethorpe's voice is heard once more, but now from inside the robot:\n\n\"OOX-22/FE is working at least, but it needs major repairs!  It is much too heavy for you to carry it... but I think I have an idea.  Are you up for watching over it some more?\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2767] = {title = "Rescue OOX-22/FE!", objective = "Escort OOX-22/FE to the dock along the Forgotten Coast, then report to Oglethorpe Obnoticus in Booty Bay.", description = "The gnome's voice crackles once again from the robot:\n\n\"I need to move OOX-22/FE to an open, safe place so it can begin a lengthy take-off procedure.  It has built-in cloaking, but I need time on my end to make it operational again.  Escort the robot from its current location to, let's say, the dock along the Forgotten Coast!  That should be a perfect place, and long enough, to get things online!\"\n\n\"Escort it safely to the dock, and then come talk to me in Booty Bay!  Oglethorpe Obnoticus - out!\"", progress = nil, completion = "Oh, YOU'RE the great savior of OOX-22/FE!  I cannot even begin to express my thanks for your assistance!  My homing robot series needs more development, but your recovery has saved me countless hours of extra rebuilding time, as well as many gold pieces in manufacture costs!\n\nPlease, take your choice of any of these items I have.  Thank you again for your generous assistance &lt;name&gt;, my robots and I are in your debt!", rewards = "You will be able to choose one of these rewards:\n\nFailed Flying ExperimentChainlink Towel\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2768] = {title = "Divino-matic Rod", objective = "Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan.", description = "Sergeant Bly stole from me!  He said he'd only borrow it, but he stole my cherished divino-matic rod!!  Without that rod how will I know where to dig new water holes??\n\nFind Bly and bring me my rod!  I heard he led his band of ill-reputed adventurers to go treasure hunting in Zul'Farrak to the west.  I bet you'll find him there.\n\nLet's hope the trolls took care of him, because if you have to fight him for the rod then you're in for a serious fight.", progress = "Did you find Sergeant Bly?  Did you get my divino-matic rod?", completion = "You found it!  Well done, &lt;name&gt;!  Did you have to fight Bly for it?  I hope you knocked him and his band down good and hard!", rewards = "You will be able to choose one of these rewards:\n\nMasons Fraternity RingEngineer's Guild Headpiece\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2769] = {title = "The Brassbolts Brothers", objective = "Speak with Wizzle Brassbolts in the Shimmering Flats.", description = "Have you met the Brassbolts brothers?  They're over in the Shimmering Flats, in Kalimdor, racing their rocket car against the goblins.  They usually win which is no surprise--the goblin car blows up so much it barely ever crosses the finish line!\n\nBut even then, the Brassbolts brothers are always looking for new ways to make their car go faster, and Wizzle told me he needs a very rare component for his next experiment.\n\nHe probably needs help getting that part.  Speak to him and find out.", progress = nil, completion = "Ah, you want to help me?  Great!\n\nThere's a part I want for an experiment I'm working on, and I need a brave &lt;class&gt; like you to help me get it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2770] = {title = "Gahz'rilla", objective = "Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats.", description = "Deep in Zul'Farrak, the sand troll city in Tanaris, there is a sacred pool.  From that pool the trolls summon a huge beast!  Gahz'rilla!  He's so fierce that even his scales crackle with energy.  It's that energy I want to harness for my car!\n\nBring me the electrified scale of Gahz'rilla!\n\nBut the summoning of Gahz'rilla is a well-kept secret of the trolls.  To face him, you must first wrest the secret from them.", progress = "Do you have the scale?  I can't wait to try different ways to harness its energy!", completion = "Wow, you got the scale!  Thanks, &lt;name&gt;.  I can't wait to get to work on this thing!\n\nSo you saw Gahz'rilla?  Was he as big as they say??", rewards = "You will receive:\n\nCarrot on a Stick"}
MultiLanguageQuestData['en'][2771] = {title = "A Good Head On Your Shoulders", objective = "Bring two Mithril Coifs and one Ornate Mithril Shoulder to Trenton Lighthammer.", description = "It seems as if master had this planned from the start. I was not taught to create the items which you learned to create and you were not taught the items which I learned to create.\n\nThe master is wise, <name>. We shall teach each other!\n\nShow me how to make a mithril coif and ornate mithril shoulders and I shall show you how to create an ornate mithril helm.", progress = "Have you completed the crafting of the items, <name>?", completion = "Excellent! A fair tradeoff, if I do say so myself. Watch and learn, &lt;name&gt;!", rewards = "The following spell will be cast on you:\n\nTeach Ornate Mithril Helm\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2772] = {title = "The World At Your Feet", objective = "Bring two Heavy Mithril Boots and one Ornate Mithril Pants to Trenton Lighthammer.", description = "At last year's All-Valley Blacksmithing Championship, all those who watched saw my leg get swept from under me by a cowardly dog from the Venture Co. Foundry. What they didn't know, however, was the reason I was able to continue and ultimately win the tournament: That's right, ornate mithril boots!\n\nI will need to learn how to craft ornate mithril pants for this year's tournament, however, as a Venture Co. shredder is an entrant! Teach me the way of the pants and learn the way of the boot!", progress = "Have you completed the crafting of the items, <name>?", completion = "The world will be at your feet, &lt;name&gt;! Let them all come at your legs, for you are now unsweepable!", rewards = "The following spell will be cast on you:\n\nTeach Ornate Mithril Boots\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2773] = {title = "The Mithril Kid", objective = "Bring two Heavy Mithril Breastplates and one Ornate Mithril Gloves to Trenton Lighthammer.", description = "Around these parts I am known as the Mithril Kid. I supply ornate mithril to adventurers from around the world.\n\n<Trenton whispers.>\n\nLittle do they know that I do not know the technique to fashion ornate mithril gloves. Shhhh! This will be our little secret.\n\nTeach me the technique to create ornate mithril gloves, <name>, and in exchange, I will show you the resultant of the culmination of my training under Galvan: the ornate mithril breastplate.", progress = "Have you completed the crafting of the items, <name>?", completion = "Thank you for all that you have taught me, &lt;name&gt;. The master and commander of the ornate mithril set will soon be in your possession.\n\nBehold!", rewards = "The following spell will be cast on you:\n\nTeach Ornate Mithril Breastplate\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][2781] = {title = "WANTED: Caliph Scorpidsting", objective = "Bring the head of Caliph Scorpidsting to Chief Engineer Bilgewhizzle in Gadgetzan.", description = "WANTED: Caliph Scorpidsting!\n\nThe Gadgetzan Water Company of Gadgetzan, Tanaris will pay a high bounty for the head of Caliph Scorpidsting, leader of the Wastewander outlaws.  His crimes include:\n\n1.  Murdering Gadgetzan Water Co. employees!\n2.Stealing Gadgetzan Water Co. resources!\n3.Seizing Gadgetzan Water Co. property!\n\nBring proof of Caliph Scorpidsting's demise to Chief Engineer Bilgewhizzle for an immediate reward!", progress = "Yes <class>, I am an official of the Gadgetzan Water Company.  What can I assist you with?", completion = "Finally - justice is served!  You have struck a mighty blow against those vile nomads!  With Scorpidsting's demise, this might be just the thing to finally push those squatters off of Gadgetzan's water wells!\n\nBy the authority of the Gadgetzan Water Company, I gladly award you with this bounty.  You've done a great service for us all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2782] = {title = "Rin'ji's Secret", objective = "Oran Snakewrithe, a well known scholar on matters concerning the Witherbark trolls, may be able to decipher the tablet. She is known to reside within the Magic Quarter of the Undercity.", description = "The tablet is covered with Witherbark troll markings. Rin'ji's secret truly is a mystery... \n\nIt's possible that you might have something quite valuable on your hands here. On the other hand, quite the opposite is also possible. A Witherbark troll in distress would probably do anything to find his way out of trouble...", progress = "Well, now, what is this?", completion = "This tablet... Quite unusual... Where did you find this, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2783] = {title = "Petty Squabbles", objective = "Speak with the Fallen Hero of the Horde at the border of the Blasted Lands and the swamp.", description = "We fight the wrong enemy, <name>.\n\nThe true power in these lands continues to grow in strength and number while we squabble over scorched earth with orcs.\n\nDo we continue to fight a war in these lands against the Horde, only to be routed one day by the armies of the Burning Legion? It is futile.\n\nPut your differences aside, <name>, speak with the fallen hero of the Horde. He knows the truth behind the Blasted Lands.", progress = nil, completion = "The Alliance wishes to assist?\n\nI thought to never see this day again. A day in which the Alliance fights side by side with the Horde against a common enemy.\n\nIt shall be... we will unite.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2784] = {title = "Fall From Grace", objective = "Listen to the Fallen Hero of the Horde tell his story.", description = "Hear my story, <race>.", progress = "Listen to what I have to say.", completion = "As a spirit, I am powerless, &lt;name&gt;. Assist me. Allow me to regain my honor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2801] = {title = "A Tale of Sorrow", objective = "Listen to the Fallen Hero of the Horde tell his story.", description = "Before we may continue, you must hear my story.", progress = "Listen to what I have to say, <name>.", completion = "The time to act is now, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2821] = {title = "The Mark of Quality", objective = "Bring 10 Thick Yeti Hides to Pratt McGrubben in Feathermoon Stronghold.", description = "My philosophy on leatherworking is that the work must be the best quality possible - no compromises.  Anyone who says that quality doesn't matter is trying to sell you ocean-front property in Dun Morogh!\n\nIn my latest pursuit of high-quality materials, I have run across thick yeti hides.  The Yeti are native to Feralas, with many found in Feral Scar Vale.  I want some, and I'll give you a choice of one of my leather goods for a stack of ten.  If that sounds fair to you, then we're in business.", progress = "A stack of ten thick yeti hides will net you a choice of one of my crafted items.  Because I care about quality, I am able to ensure you'll get a good item!\n\nIf you can't seem to find yetis, I know where some might be.  Try looking just inland of the Forgotten Coast, around Feral Scar Vale.", completion = "Did you stop and examine the texture of these hides?  Properly treated, these hides could very well be stronger than iron.  Not many people know about these hides, and that in combination with the vast treating solutions I know will allow me to potentially make items with a true mark of quality... thanks to you, of course!\n\nAnd now, please choose from what I am able to offer you for your service!", rewards = "You will be able to choose one of these rewards:\n\nPratt's Handcrafted BootsPratt's Handcrafted Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2822] = {title = "The Mark of Quality", objective = "Bring 10 Thick Yeti Hides to Jangdor Swiftstrider in Camp Mojache.", description = "I take pride in my leather work, and I feel it shows; quality should never be compromised.  Anyone who says that quality doesn't matter would also have you believe that the earth does not keep secrets!\n\nIn my latest pursuit of high-quality materials, I have discovered thick yeti hides.  Yetis are native to Feralas, often found west of here in Feral Scar Vale.  I'll give you a choice of one of my leather goods for a stack of ten.  If that is agreeable to you, then we are set!", progress = "Were you able to get a stack of ten thick yeti hides?  My leather goods are second to none, and I'll share a sampling with you should you have the hides.\n\nIf you can't seem to find yetis, I know where some might be.  Try looking west of here, just inland of the Forgotten Coast around the Feral Scar Vale.", completion = "Ah, excellent!  These hides, when given a special treatment, are as resilient as iron I tell you!  It will take many tries in order to get the right mix down for the tanning, but I am confident they will bring my mark of quality to the next level.\n\nAs for you, &lt;name&gt;... your assistance has proven invaluable to me.  Please take your choice from these items I have crafted.", rewards = "You will be able to choose one of these rewards:\n\nJangdor's Handcrafted BootsJangdor's Handcrafted Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2841] = {title = "Rig Wars", objective = "Retrieve the Rig Blueprints and Thermaplugg's Safe Combination from Gnomeregan and bring them to Nogg in Orgrimmar.", description = "Gnome technology - two years ago its most common use was as a punch line. Times certainly have changed. Now they've got a new rig built that's better than all our shredder models combined. I need the blueprints, <name>!\n\nUnfortunately, the plans are locked away in a safe near Mekgineer Thermaplugg. To make matters worse, the combination to the safe is only known by Mekgineer Thermaplugg.\n\nDo whatever you have to do to get that combination, <name>. Then crack open that safe and bring back those blueprints!", progress = "I don't see any blueprints. Did you hide them somewhere on your body or are you just standing around here to irritate me?", completion = "I knew you could do it, &lt;name&gt;! Sovik on the other hand, he had his doubts.\n\n\n\nNow that we have the blueprints in our possession, it is only a matter of time before we figure out all of the gnomish innovations that went into the creation of the rig and make them goblin innovations for our new shredder models.", rewards = "You will be able to choose one of these rewards:\n\nCivinad RobesTriprunner DungareesDual Reinforced Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2842] = {title = "Chief Engineer Scooty", objective = "Speak with Scooty in Booty Bay.", description = "As soon as we got word from Kernobee about the new gnomish rig, Scooty and I began work on the Transpolyporter 6000: The fastest and most reliable way to Gnomeregan.\n\nIt's finally ready for passengers to board, <name>. If you want to give it a try, go to Booty Bay and talk with Scooty at the wind rider roost. To get to Booty Bay, take the boat from Ratchet.\n\nOf course, you could always try and make the run to Gnomeregan through the dwarf infested mountains of Dun Morogh!", progress = nil, completion = "She's a beauty, isn't she? Pinnacle of goblin transport technology -- only exploded a dozen or so times.\n\nDon't worry, &lt;name&gt;, I've got her all fixed up. She won't blow up on you - and if she does, it'll be quick and painless.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2843] = {title = "Gnomer-gooooone!", objective = "Wait for Scooty to calibrate the Goblin Transponder.", description = "As long as you have the transponder in your possession, all you need to do is step on the pad and you'll be teleported to Gnomeregan.\n\nYou may experience some unusual side effects, but none of those should be permanent... anymore.\n\nI almost forgot the most important part - getting back. When you're ready to come back, just step on the transpolyporter pad in Gnomeregan!\n\nNow to calibrate the transponder to your size and weight.", progress = nil, completion = "All done! When you're ready, just step on the pad.", rewards = "You will receive:\n\nGoblin Transponder"}
MultiLanguageQuestData['en'][2844] = {title = "The Giant Guardian", objective = "Locate the lost night elf girl.", description = "I am no good, <name>. I was 'spose to be watchin' over my little friend, Shay, and somehow, she got away from me. I'm not all that sure what happened, really, but last time I saw her, we was walkin' through the ruins just north of here.\n\nEverythin' was goin' fine, but then I turned around, and... she was gone.\n\nNow I jus can't quite figure out what I should do here. Got any ideas, <name>? I'm awful worried.\n\nHey, how 'bout you go look fer Shay? Yer legs can travel much faster 'n mine.", progress = nil, completion = "Oh, I am so glad you found me! I must admit, I am a bit lost... But isn't this a beautiful place?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2845] = {title = "Wandering Shay", objective = "Pick up Shay's Bell from the chest.\n\nEscort Shay Leafrunner to Rockbiter's camp.", description = "Do you think you could help me find my way back to my friend, Rockbiter? He was supposed to be watching me... But I do have a tendency to wander off now and then. There are just so many things to see, and I get so distracted.\n\nThere is one thing that will always work to get my attention, though.\n\nInside this chest, you'll find a bell that is very precious to me. I just love the sound of it. You have my word, if I wander off, all you have to do is ring it and I'll come running back.", progress = "I was gettin' worried 'bout ya! Thank you so much for bringin' Shay home, <name>.", completion = "What? You say dis bell will work when Shay runs off? Well, how 'bout that!\n\nSince you did so much fer me, here ya go, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nGranite GripsVinehedge Cinch\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2846] = {title = "Tiara of the Deep", objective = "Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh.", description = "Long ago I possessed a beautiful piece of jewelry, the Tiara of the Deep.  And not only was it pretty--it held great power for those with the knowledge to use it.\n\nSo when word of the tiara reached the Hydromancer Velratha, she had to have it.  She sent agents to my home and they stole it while I was away.  The thieves!\n\nI want my tiara back!  Go to Zul'Farrak, the troll city in Tanaris, find Velratha and wrench the tiara from her.  Return it to me and you'll earn my favor.", progress = "Do you have the tiara, <name>?  Has Velratha learned the price of crossing me?", completion = "Wonderful!  You found it!  And what's just as important--Velratha no longer has it!  Thank you, &lt;name&gt;.  I am forever in your debt!\n\nAnd if I sounded a little... mean before, pay it no mind.  You'll find me a much nicer person to those who haven't stolen from me.", rewards = "You will receive:\n\nSpellshifter RodGemshale Pauldrons"}
MultiLanguageQuestData['en'][2847] = {title = "Wild Leather Armor", objective = "Bring 10 Thick Leather to Pratt McGrubben in Feathermoon Stronghold.", description = "<name>, you're becoming quite skilled as a leatherworker!  I know some patterns you might be interested in... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  The armor made using it is second to none for people of your skill, guaranteed.\n\nI'll teach this to you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", progress = "Like I said, you'll be working for me while you learn about Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to come by.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well &lt;name&gt;, I'm glad to have you on board.  You've made a smart decision as a leatherworker; those who wear leather armor will be clamoring to you once you learn how to make any of the Wild Leather armor pieces.\n\nLet's get to work - where do you want to start?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2848] = {title = "Wild Leather Shoulders", objective = "Bring 6 Thick Armor Kits and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", description = "Wild Leather shoulders support the wearer's frame extremely well, offering top notch protection of the upper arms and the shoulders themselves.  As with all Wild Leather armor, a potent but random benefit is applied to the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", progress = "Do you have the six thick armor kits and the wildvine I require?\n\nDon't think of making armor kits as monotonous work; the steady fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armor.\n\nSee - there's a real reason behind what you're making for me...", completion = "These armor kits are of solid quality, &lt;name&gt;.  If there is one thing I demand in not only my work, but the work of those in my employ, it is quality.\n\nYou've done well to earn this pattern; I hope it brings you the rewards it has brought me.", rewards = "You will receive:\n\nPattern: Wild Leather Shoulders"}
MultiLanguageQuestData['en'][2849] = {title = "Wild Leather Vest", objective = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest blends with the wildvine to produce a product that offers maximum protection of the torso while allowing for the potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  It's a tall order, but one you should have little difficulty in filling for me.", progress = "Do you have the two Turtle Scale breastplates and gloves I ordered?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAnd the gloves... well, they're just for my own benefit.  Remember, you're working for me!", completion = "These are some very nice pieces here, &lt;name&gt;.  The craftsmanship and care put in to making these alone would fetch several silver more than the average piece made.\n\nYou've filled my order, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!", rewards = "You will receive:\n\nPattern: Wild Leather Vest"}
MultiLanguageQuestData['en'][2850] = {title = "Wild Leather Helmet", objective = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Pratt McGrubben in Feathermoon Stronghold.", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random enhancement to the frame of the helm.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, two Nightscape headbands, and a wildvine.  Complete this order and the pattern will be yours!", progress = "I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.\n\nHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet.  The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.", completion = "This Nightscape equipment you have supplied fills the order perfectly, &lt;name&gt;.  I expect no less from a leatherworker of your caliber.\n\nYou have definitely earned this pattern.  I give it to you freely, and hope you will profit from it accordingly.", rewards = "You will receive:\n\nPattern: Wild Leather Helmet"}
MultiLanguageQuestData['en'][2851] = {title = "Wild Leather Boots", objective = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", description = "You've learned quite a bit now, <name>; still, there is more for you to learn.  Next are Wild Leather boots, the cornerstone of any set.\n\nThese boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need an order of two Nightscape pants and two Nightscape boots filled.  I also will require two wildvines... not just one.  When you have all this, let me know.", progress = "The order on the pants, boots, and wildvines needs to be filled before you get the pattern, <name>.  Are you finished?\n\nFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor's edge between comfort and function.  With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.", completion = "Once again, you've filled a complex order with the skill of a seasoned professional.  You have earned this pattern, as well as my thanks.", rewards = "You will receive:\n\nPattern: Wild Leather Boots"}
MultiLanguageQuestData['en'][2852] = {title = "Wild Leather Leggings", objective = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Pratt McGrubben in Feathermoon Stronghold.", description = "With the basics down, you are ready to master more complex fare, <name>.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor this pattern, I need an order of two Turtle Scale helms, two Turtle Scale bracers, and two wildvines filled.", progress = "Do you have the Turtle Scale bracers and helms ready?  Don't forget the two wildvines I need!\n\nBy now, you're starting to realize the potential power that lies in Wild Leather armor.  An armor that has no boundaries in application is nearly invaluable to a leatherworker.  The limits are only in the quantities of resources to make the items - not the quality of the finished products!", completion = "Again, you've filled an order without flaw.  Perhaps some day I will come to YOU seeking knowledge, eh &lt;name&gt;?\n\nHere is the pattern for the leggings, along with my thanks.  Commit this lore to your knowledge, and let your finished products tap into your impressive skills!", rewards = "You will receive:\n\nPattern: Wild Leather Leggings"}
MultiLanguageQuestData['en'][2853] = {title = "Master of the Wild Leather", objective = "Give Pratt's Letter to Telonis, the master leatherworker of Darnassus.", description = "Well <name>, you are the definition of diligence.  There is one pattern left for Wild Leather armor; you've mastered the others.  I won't require you to toil needlessly for the pattern.  You've earned it outright, and then some... but I cannot give it to you myself.  My teacher, the one who brought me into the craft, is the one who must reward you.\n\nTake this letter to Telonis; he teaches leatherworking in Darnassus.  Show him the letter, and let him acknowledge you as an equal, as I do.", progress = "Greetings, <race>... from your countenance I can tell you are a leatherworker as am I.  Have you come to draw from my skills, or perhaps you have other business with me?", completion = "Ah yes, Pratt sent you.  Though he is a human, he reminds me of us night elves sometimes.  His dedication and his talents with leather are impressive.  For him to compliment you so in this letter, it is a sign of respect I acknowledge.\n\nI am aware that he has taught you the art of Wild Leather.  Allow me to finish your training with this pattern.  Make good use of it; few in the world know the secrets of Wild Leather cloaks.", rewards = "You will receive:\n\nPattern: Wild Leather Cloak"}
MultiLanguageQuestData['en'][2854] = {title = "Wild Leather Armor", objective = "Bring 10 Thick Leather to Jangdor Swiftstrider in Camp Mojache.", description = "<name>, your skill as a leatherworker precedes you.  I possess leatherworking lore you would be wise to acquire... Wild Leather armor!  Wild Leather taps into the potent and chaotic properties of wildvines, found in areas of lush vegetation and on some of the creatures there.  Armor made using it is second to none for a crafter of your skill, guaranteed.\n\nI'll teach you, but you'll be working for me for a while.  The first cost is simply ten pieces of thick leather.  After this, we'll talk specifics.", progress = "We must be clear; you shall be apprenticed to me while you learn the art of Wild Leather armor.  Because wildvines are both potent and chaotic, it yields a random but strong benefit to the already strong armor you will be making.  This knowledge, however, was not easy for me to acquire.\n\nThe initial cost to begin this process is ten pieces of thick leather.\n\nOnce that is done, we'll get to the work you need to do in order to obtain the patterns.", completion = "Well &lt;name&gt;, I'm glad to have you on board as my apprentice.  You've made a wise decision as a leatherworker; those who make use of leather armor will be clamoring to you once you learn how to master the art of Wild Leather.\n\nLet's get to work - where do you want to start?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2855] = {title = "Wild Leather Shoulders", objective = "Bring 6 Thick Armor Kits and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", description = "Wild Leather shoulders support a wearer's frame extremely well, offering superior protection of the upper arms as well as the shoulders.  As with all Wild Leather armor, a random yet very potent enhancement is imbued within the item as the wildvine is stitched in.\n\nFor this pattern, I will require six thick armor kits and a wildvine.  That shouldn't be too tall of an order for you to fill.", progress = "Do you have the six thick armor kits and the wildvine I require?\n\nThink of making armor kits as a lesson in steady and reliable crafting; the consistent fashioning method you develop as you ply your trade on these kits helps develop your skills for the intricate work needed to make Wild Leather armors.\n\nEvery lesson has a purpose, <name>.  It is important to embrace each one accordingly.", completion = "These armor kits are of solid quality, &lt;name&gt;.  If there is one thing I demand in not only my work, but in the work of those I give tutelage to, it is quality.\n\nYou've done well to earn this pattern; I hope it brings you the rewards it has brought me.", rewards = "You will receive:\n\nPattern: Wild Leather Shoulders"}
MultiLanguageQuestData['en'][2856] = {title = "Wild Leather Vest", objective = "Bring 2 Turtle Scale Breastplates, 2 Turtle Scale Gloves, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", description = "Wild Leather vests are the staple of any Wild Leather armor set.  The frame of the vest and the wildvine weave within it produces a product that offers maximum protection of the torso while allowing for potent magic to work its way through the garment.\n\nFor this pattern, I will require two Turtle Scale breastplates, two sets of Turtle Scale gloves, and a wildvine.  This is not an easy lesson, but it is one you certainly have the skill to complete.", progress = "Do you have the two Turtle Scale breastplates and gloves?  Also, don't forget the wildvine!\n\nEven with the earliest patterns, we learn that the fundamentals of shape translate well into more difficult garments.  Though different items, the shape of the Turtle Scale breastplates prepares you for the detailing needed to make a Wild Leather vest.\n\nAs you progress through your lessons, the skills I teach will become as art.", completion = "These are some very nice pieces here, &lt;name&gt;.  The craftsmanship and care put in to making these show you have chosen to dedicate yourself fully to these tasks.\n\nYou've met my requests, and with that comes your reward.  The knowledge of making Wild Leather vests is now yours!", rewards = "You will receive:\n\nPattern: Wild Leather Vest"}
MultiLanguageQuestData['en'][2857] = {title = "Wild Leather Helmet", objective = "Bring 2 Nightscape Tunics, 2 Nightscape Headbands, and a Wildvine to Jangdor Swiftstrider in Camp Mojache.", description = "A Wild Leather helmet offers the wearer superior protection to the vital areas of the head without a sacrifice in comfort.  As with all Wild Leather armor, the integrated wildvine yields a powerful but random magic imbuement to the helm's frame.  Leather wearers will definitely want this piece!\n\nFor this pattern, I will need two Nightscape tunics, 2 Nightscape headbands, and a wildvine.  Complete this lesson and the pattern will be yours!", progress = "I need those tunics and headbands made, and I also need that piece of wildvine before I will share with you the knowledge of Wild Leather helmets.\n\nHead gear is highly coveted amongst adventurers, whether it be a disarmingly simple headband or a full-covering helmet.  The fundamentals of creating valued head gear remain constant, no matter what the cosmetic appearance of the gear is.", completion = "This Nightscape equipment you have supplied perfectly meets the requirements I have given to you, &lt;name&gt;.  I expect no less from a leatherworker of your caliber.\n\nYou have earned the honor of crafting Wild Leather helmets.  I give this pattern to you freely, and hope you will profit from it accordingly.", rewards = "You will receive:\n\nPattern: Wild Leather Helmet"}
MultiLanguageQuestData['en'][2858] = {title = "Wild Leather Boots", objective = "Bring 2 Nightscape Pants, 2 Nightscape Boots, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", description = "Your knowledge of Wild Leather armor grows, <name>; still, there is more for you to learn.\n\nWild Leather boots are the cornerstone of any set.  Such boots are crafted to cradle the foot in comfort while bracing it against the hazards of adventuring.  The soft soles are a blessing to those seeking quiet movement in footwear.\n\nFor this pattern, I need two Nightscape pants and two Nightscape boots crafted.  I also will require two wildvines... not just one.  When you have these items, we will proceed.", progress = "The pants, boots, and wildvines need to be delivered to me before you learn the pattern, <name>.  Have you done as I asked?\n\nFrom the earliest pair of boots we learn how to make, we start to understand that a quality boot needs to ride a razor's edge between comfort and function.  With both, we are able to create items that allow the wearer to ignore fatigue that would cripple those wearing lower quality goods.", completion = "Once again, you have produced items with the skill of a seasoned professional.  You have earned this pattern, as well as my congratulations.", rewards = "You will receive:\n\nPattern: Wild Leather Boots"}
MultiLanguageQuestData['en'][2859] = {title = "Wild Leather Leggings", objective = "Bring 2 Turtle Scale Helms, 2 Turtle Scale Bracers, and 2 Wildvines to Jangdor Swiftstrider in Camp Mojache.", description = "You are ready to master more complex lessons, <name>.  Wild Leather leggings are some of the sturdiest and powerful leather gear around.  The waist, thighs, calves, and the vitals - all are given tremendous protection.  Coupled with the enhancement that the wildvine provides, adventurers who own it will thank you each time they see you.\n\nFor you to gain this pattern, I need two Turtle Scale helms, two Turtle Scale bracers, and two wildvines.", progress = "Do you have the Turtle Scale bracers and helms ready?  Don't forget the two wildvines I require.\n\nBy now, you're starting to realize the potential power that lies in Wild Leather armor.  An armor that has no boundaries in application is nearly invaluable to a leatherworker.  The limits are only in the quantities of resources to make the items - not the quality of the finished products!", completion = "Again, you've completed my task without flaw.  Perhaps some day I will come to YOU seeking knowledge, eh &lt;name&gt;?\n\nHere is the pattern for the leggings, along with my thanks.  Commit this lore to your knowledge, and let your finished products tap into your impressive skills!", rewards = "You will receive:\n\nPattern: Wild Leather Leggings"}
MultiLanguageQuestData['en'][2860] = {title = "Master of the Wild Leather", objective = "Give Jangdor's Letter to Una, the master leatherworker of Thunder Bluff.", description = "<name>, you have learned all I am able to teach you.  There is, however, one remaining pattern for Wild Leather armor.  I will not require you to toil needlessly for this; you've earned it outright, and then some.  This pattern, however, is one that I cannot freely share with you.\n\nMy teacher, the one who brought me into the craft, is the one who must reward you.  Take this note to Una; she teaches leatherworking in Thunder Bluff.  Show her the letter, and let her acknowledge you as an equal, as I do.", progress = "Greetings, <race>... from your countenance I can tell you are a leatherworker as am I.  Have you come to draw from my skills, or perhaps you have other business with me?", completion = "Ah yes, Jangdor sent you.  I am pleased to see that one of my finest students now has a student of his own.\n\nHis dedication and his talents with leather are impressive.  For him to compliment you so in this letter, it is a sign of respect I acknowledge.\n\nI am aware that he has taught you the art of Wild Leather.  Allow me to finish your training with this pattern.  Make good use of it; few in the world know the secrets of Wild Leather cloaks.", rewards = "You will receive:\n\nPattern: Wild Leather Cloak"}
MultiLanguageQuestData['en'][2861] = {title = "Tabetha's Task", objective = "Speak with Tabetha in Dustwallow Marsh.", description = "Rumor is that Tabetha, a mage colleague who lives deep in Dustwallow Marsh, has a bone to pick with a certain sand troll in Zul'Farrak.  If you speak with Tabetha she can tell you more.\n\nAnd bring some friends with you, <name>.  If Tabetha has you go to Zul'Farrak then you're not going to want to go alone.\n\nYou will find Tabetha's cottage west of Theramore, and just north of the Stonemaul Ruin.", progress = nil, completion = "That's right.  I do have a bone to pick with a troll.  A few bones.  All her bones!\n\nWant to help me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2862] = {title = "War on the Woodpaw", objective = "Bring 10 Woodpaw Gnoll Manes to Hadoken Swiftstrider in Camp Mojache.", description = "The gnolls... they are more than a nuisance.  They are a constant threat to the existence of this very camp!  It is irrelevant whether they are indigenous to Feralas or not; if we do not strengthen our resolve against them, we will find ourselves driven out of the entire region.\n\nThe gnoll attacks against the camp have become more fevered as of late.  We need your aid in thinning their numbers; bring to me ten of their manes, and I will reward you handsomely for your effort.\n\nGo!", progress = "We drive them back, and yet they still attack!  Someone or something must be driving them into a frenzy... oh, you have returned, eh <name>?  Do you have the manes I require for the bounty to be met?", completion = "This is proof of a good start, &lt;name&gt;.  Your skills as a soldier are to be commended.\n\nYou are not the only one I ask that task of.  Many before you have fought them, and in times past our efforts have kept them at bay.  Recently though, their attempts to push northward into our area of influence have increased dramatically.  Their attacks have also become more savage... almost as if they were desperate.\n\nI have a plan though, &lt;name&gt;, that might settle things once and for all against them...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2863] = {title = "Alpha Strike", objective = "Kill 5 Woodpaw Alphas and return to Hadoken Swiftstrider within one hour.", description = "The plan is for various leaders of the gnolls - Alphas as they call themselves - to be taken down within rapid succession.  If we're able to execute this sort of swift and precise devastation against them, it would cause chaos in their ranks.  Perhaps it would also drive a message through their thick flea-bitten heads that we can and will destroy them!\n\nI want you to be the messenger of my will; eliminate five of their Alphas within one hour for this to work <name>, or we'll remain at this impasse!", progress = "Time is running out, <name>!  If you're not here to report that you've taken out the Alphas, then you're wasting time!", completion = "You've done as I have asked, and for that I salute you.  Take this small reward as compensation for your efforts, &lt;name&gt;.\n\nWith their numbers thinned and their leaders slain, the gnolls will think twice about storming the camp.  This doesn't conclude the issue at hand, however...\n\nThere must be some reason why the gnolls have been whipped into such a frenzied state.  Before they have a chance to regroup though, I want to find out what is causing it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2864] = {title = "Tran'rek", objective = "Speak with Tran'rek in Gadgetzan.", description = "My cousin Tran'rek is in a tight spot.  He promised me a load of scarab shells weeks ago and he hasn't delivered.  He's my cousin, so I'd hate to have to send someone to Gadgetzan to break something on him.\n\nCan you speak to Tran'rek for me?  Let him know he needs to get that delivery together before I do something rash?\n\nGadgetzan is in northern Tanaris, in Kalimdor.", progress = nil, completion = "Hello!\n\nOh, you spoke to my cousin Krazek?  How is he?  I hope Booty Bay is treating him well...\n\nScarab shells, you say?  Well... let me tell you a story...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2865] = {title = "Scarab Shells", objective = "Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan.", description = "The scarabs of Tanaris have very hard shells!  Hard enough to use as a building material for lots of things.  So many things!\n\nIn fact, those shells are so useful... the scarabs were hunted all to near extinction!\n\nI know where there are more scarabs, and if you promise to bring me their shells then I'll tell you where they are.  Promise?\n\nOk, the scarabs have a colony in Zul'Farrak.  I guess the trolls don't hunt them for their shells.\n\nBut you can!  Go to Zul'Farrak and get me uncracked shells!", progress = "Do you have the shells?  My cousin in Booty Bay is waiting for a load of them, and he's getting impatient!", completion = "Oh, great!  You got them!\n\nThanks, &lt;name&gt;.  You're a real lifesaver!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2866] = {title = "The Ruins of Solarsal", objective = "Explore the Ruins of Solarsal and investigate the presence of the naga there.", description = "To our south are the Ruins of Solarsal; this is an area that far pre-dates modern times.  We explored the ruins initially and found nothing of note; as such, we left it in peace.\n\nVery recently, the Hatecrest naga have occupied these ruins in alarming numbers.  At first, we considered it as the precursor for an attack.  Though that threat is still possible, we believe there might be something else going on.\n\nGo there, explore the ruins, and look for anything that stands out to you. Good luck, <name>.", progress = nil, completion = "Examining the gazebo reveals some interesting and unusual things in contrast to the surrounding ruins.\n\nFirst, the gazebo is clearly a more recent construction than the other objects in the ruins.  Second, the gazebo has a small series of glyphs engraved into the sides of it; the glyphs repeat in their pattern, but it otherwise is unknown in origin and meaning.  Third, the stone of the gazebo itself is warm to the touch.\n\nThis certainly quantifies as \"standing out\" in the search of the ruins!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2867] = {title = "Return to Feathermoon Stronghold", objective = "Return to Shandris Feathermoon in the Feathermoon Stronghold and report your findings.", description = "With the discovery of the strange gazebo in the heart of the Ruins of Solarsal, the time has come to return to Feathermoon Stronghold and report to General Shandris Feathermoon what has been discovered here.", progress = nil, completion = "Welcome back, &lt;name&gt;.  Your report on this gazebo is most... disturbing.  It would seem that even if the naga there were not planning on an attack, their continued presence bodes ill for our push into Feralas.  At any rate, here is compensation for your investigation.\n\nIt would seem that Feathermoon Stronghold is in dire need of additional assistance concerning the Hatecrest naga.  I'd like to offer you the task, if you are so inclined.  There is much to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2869] = {title = "Against the Hatecrest", objective = "Bring 10 Hatecrest Naga Scales to Latronicus Moonspear in Feathermoon Stronghold.", description = "The best course of action at this point is to assume that, regardless of what the naga are up to, they will eventually move to secure the island for their own.  We need to take aggressive steps to counter that threat before it is too late.\n\nBring me ten Hatecrest Scales that are in good condition; it should be obvious to you how to acquire them.  You'll cut your teeth on the naga for the first time, and we'll have a weakened naga presence on Sardor Isle - both are prospects that play to our advantage.", progress = "<name>, if you're here to verify the task given to you, then excellent - it is ten Hatecrest scales I seek.  If you are here for chit-chat, then I am currently unavailable for such trivialities.\n\nKnow this - we night elves are not warmongers.  Our race is dedicated to the preservation of peace and harmony.  This does not mean, however, that we will not proactively protect our own interests.  This is my duty to General Feathermoon, and to the stronghold.", completion = "Yes, yes, these scales are more than satisfactory.  Actually, I think I will send these down to Pratt for him to take a look at.  Maybe he can craft something useful out of them.\n\nAs for you, I have another mission I want to send you on.  But first, here is your bounty for the scales.  Your continued service to the General and Feathermoon Stronghold at large is a blessing in the face of adversity.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2870] = {title = "Against Lord Shalzaru", objective = "Eliminate Lord Shalzaru, and then bring the Mysterious Relic he uncovered to Latronicus Moonspear in Feathermoon Stronghold.", description = "<name>, new scouting reports have given us a good idea on the naga chain of command.  Royalty is present amongst their rank and file, and they're the ones calling all the shots.\n\nSpecifically, we've identified one of the crueler royals as Lord Shalzaru.  Scouts report that he himself has uncovered an odd relic during a recent naga excavation in a cave south of the main ruins, across the water on the Isle of Dread.\n\nPut a stop to it by putting a stop to him, and bring me his relic so we can study it.", progress = "Bringing down Lord Shalzaru would certainly set their plans back weeks, if not months.  On top of that, the relic he uncovered is of definite interest to us.\n\nHave you performed the mission given to you, <name>?", completion = "Well played, &lt;name&gt;! Lord Shalzaru's demise will throw the naga into disarray for some time, if not permanently.  The threat they pose is now under more of our control than it has ever been, and we have you to thank for it.\n\nHere is more bounty money from the stronghold treasury - you've earned every copper.  You and yours are welcome in Feathermoon Stronghold anytime, my friend.\n\nOne more thing before you depart, &lt;name&gt;... if you could...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2871] = {title = "Delivering the Relic", objective = "Deliver the Mysterious Relic to Vestia Moonspear in Feathermoon Stronghold.", description = "If you would be so kind as to deliver the relic to my wife Vestia, I would appreciate it.  She's not only a fine priestess for our community, but she is one of the most well-versed scholars you'll find anywhere.  I couldn't make heads or tails of this device even if there was a wager involved.  My wife though, if anyone can figure out what this thing is, she could... and we need to know!\n\nShe's just around the bend, no doubt studying.  Thanks, <name>.", progress = "Yes, may I assist you?\n\nHold on, you're the <class> that has been helping General Feathermoon and Latro out with the naga threat, yes?  I'm Vestia, Latro's - erm, rather, Latronicus' wife.  It is a pleasure to meet you!\n\nI'm sorry, you're here on business, of course.  Do you have something for me - from him, perchance?", completion = "Interesting... this came from the Ruins of Solarsal, you say?  Well, Latro's right that I need to look at this.  At first glance, it seems non-indigenous to the ruins.  Then again, this isn't of naga design... not something as alien as this.\n\nIt is going to take some time to research this item.  Once my research on it is done, maybe I will make use of your talents, should you be around.\n\nHere, take one of these extra items we have; I hope you'll find some use for it!", rewards = "You will be able to choose one of these rewards:\n\nDawnrider's ChestpieceSentinel's Guard\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2872] = {title = "Stoley's Debt", objective = "Speak with Stoley in Steamwheedle Port.", description = "My old buddy Stoley owes me a very special bottle of rum.  He tends the bar at Steamwheedle Port in Tanaris, Kalimdor,  and he promised me that the rum there is stronger than anything we can find in Booty Bay.  He's so confident that he says if I try that rum and don't agree with him, then he'll double the money he owes me!\n\nWell, I think he's not as confident as he was when last we spoke, and now he's afraid to give me that rum.  But I don't back down from wagers, so why don't you talk to him for me...", progress = nil, completion = "Ah, so you've been speaking with MacKinley, have you?\n\nIt's not what he thinks!  I'm not afraid to give him some Steamwheedle Bilge Rum...\n\nI just don't have any rum to give him!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2873] = {title = "Stoley's Shipment", objective = "Bring Stoley's Shipment to Stoley in Steamwheedle Port.", description = "I owe \"Sea Wolf\" MacKinley in Booty Bay some rum, to settle a bet, but I'm all out of rum!  Captain Cuergo stole my last shipment, and he has it stowed in that walled pirate town to the south.\n\nIf you can find my shipment of rum and return it to me, then I can prove to MacKinley that Kalimdor's booze beats the dirt out of Booty Bay!", progress = "Did you find my shipment of rum, <name>?", completion = "Great, thanks for the shipment!  Now MacKinley and I can finally settle our wager.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2874] = {title = "Deliver to MacKinley", objective = "Bring Stoley's Bottle to \"Sea Wolf\" MacKinley in Booty Bay.", description = "Thanks again for your help, <name>.  Here's a bottle of Steamwheedle bilge rum.  Take it to MacKinley and he can finally put to rest his crazy beliefs about Booty Bay booze.", progress = "Did Stoley cough up my booze?", completion = "Hm, let's try this...\n\nI can't believe it!  This stuff is... terrible!  That's great!\n\nWell I guess Stoley can keep the money he owes me.  He's true to his word about Steamwheedle bilge rum.  That stuff is as thick as gravel and burns like lava!", rewards = "You will be able to choose one of these rewards:\n\nSwashbuckler SashShinkicker Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2875] = {title = "WANTED: Andre Firebeard", objective = "Bring Andre's Head to Security Chief Bilgewhizzle in Steamwheedle Port.", description = "The vile pirate Andre Firebeard is wanted for crimes against Steamwheedle and Gadgetzan.\n\nBy decree of governing counsel, any who read this are hereby authorized to use lethal force during the apprehension of Andre and his abettors.\n\nBy further decree, should Andre be deceased, or otherwise indisposed, during the time of his hearing, his head may act as proxy, and deliverance of such head to Security Chief Bilgewhizzle constitutes a binding, and tenderable, contract.", progress = "You look a little dazed.  Have you been reading our legal documents?", completion = "Ah, Andre's head.  So I guess he'll make his trial after all!\n\nMuch appreciated, &lt;name&gt;.  Now if you'll just sign here, I can issue you payment for services rendered.\n\nDon't worry about the small print.  It's harmless, and... I don't think there's a magnifying glass small enough to read it anyway.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2876] = {title = "Ship Schedules", objective = "Report the Ship Schedules to an authority in Steamwheedle Port.", description = "This scroll contains the schedules of shipments between Steamwheedle Port and Booty Bay. Both past and future shipments are included, along with ship names, with large 'X's next to some ships' journeys, and annotations like \"GREAT LOOT\" and \"HARD FIGHT\" next to others.\n\nSomeone at Steamwheedle Port would want to see this document.", progress = "You look out of breath.  You have something to tell me?", completion = "Oh my, this looks to be a list of ship departures and arrivals, with accurate dates and times and everything!  If the captain of a pirate ship got his hands on this, he could have himself a field day!\n\nYou say you got this from a pirate?  Well that's disturbing news...\n\nThank you, &lt;name&gt;.  I'm glad you took it from him, and I'm glad that pirate's eating dirt right now!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2877] = {title = "Skulk Rock Clean-up", objective = "Kill 10 Green Sludges and 10 Jade Oozes, and then report back to Fraggar Thundermantle in Aerie Peak.", description = "We Wildhammers remember the past, more than our brothers in Ironforge.  If you want to make friends here, then you get your hands dirty for us!\n\nThe Horde abandoned their positions in the Hinterlands around Skulk Rock; it's now overrun with nasty sludges and oozes.  We've got plans on that area, but first we need a clean-up crew to make a hole for us.\n\nThat's where you come in, Sunshine!  Head down there and take out ten green sludges and ten jade oozes, then report back to me here.  Move out!", progress = "Make no effort to negotiate the mission at hand, <race>!  If the gods had wanted those oozes killed, they would have miracled it done by now, wouldn't they?!", completion = "Well look at you, helping out the Wildhammers!  You're a &lt;class&gt; of action, and action is what we respect around here.\n\nYour little clean-up mission is a lot more important than you might think it is.  With folks thinning out the oozes and sludges, we'll be able to extend our sphere of influence in no time. Here - have a little something in addition to just making new friends here in Aerie Peak!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2878] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][2879] = {title = "The Stave of Equinex", objective = "Energize Troyas' Stave and find the Equinex Monolith.", description = "This stave might be the Stave of Equinex! The Stave of Equinex is actually a key, used to unlock the Equinex Monolith in the Ruins of Ravenwind, on the mainland west of the Dream Bough.\n\nFind the four flames that still burn in those ruins: Samha, Imbel, Byltan, and Lahassa. Retrieve their essence and then while standing by the Equinex Monolith, use the essences to energize the stave. If this is truly is the Stave of Equinex, you will be able to unlock the Monolith and gather a sacred artifact from it.", progress = "The Equinex Monolith stands silently among the ruins. What could it be holding?", completion = "Holding the energized stave is almost impossible. Its power rumbles through your body.\n\nYou reach out to the cold surface of the Equinex Monolith...\n\nA small door opens, allowing you to reach in and take the artifact inside.\n\nBeams of light fill the area around the Equinex Monolith.", rewards = "You will receive:\n\nA Sparkling Stone"}
MultiLanguageQuestData['en'][2880] = {title = "Troll Necklace Bounty", objective = "Bring 5 Troll Tribal Necklaces to Fraggar Thundermantle in Aerie Peak.", description = "Get this straight, <race> - we are NOT part of the Alliance!  The Wildhammers are independent, relying on deeds and actions to prove one's worth, rather than the blather of those who use jibber-jabber to bolster their do-nothing attitudes!\n\nIf you're looking for friends here, then prove your worth to us first!  The foul trolls that choke the hillsides of the Hinterlands sometimes carry tribal necklaces.  Bring five of them to me, and we'll mark it down as a step in the right direction for you.", progress = "I want five of those tribal necklaces the trolls carry on them.  If you need it spelled out further, then killing one of them stands you a good chance of getting one!\n\nProve your worth to the Wildhammers!", completion = "Now that's what I am talking about!  See - these necklaces prove that you're willing to get your hands dirty.  We Wildhammers value that in those we associate with.\n\nYou keep this up, and you'll be in our good graces yet.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2881] = {title = "Troll Necklace Bounty", objective = "You've done it already, but we will continue to accept any troll tribal necklaces you find and are willing to turn in.  By turning them in to me, you'll continue to improve your standing amongst the Wildhammers; if you're willing to fight for us, then we'll be willing to fight for you!\n\nI need five troll tribal necklaces for them to count, <name>.", description = nil, progress = "You've done it already, but we will continue to accept any troll tribal necklaces you find and are willing to turn in.  By turning them in to me, you'll continue to improve your standing amongst the Wildhammers; if you're willing to fight for us, then we'll be willing to fight for you!\n\nI need five troll tribal necklaces for them to count, <name>.", completion = "Another set of necklaces means that there are fewer trolls in the Hinterlands we have to worry about!  You've done it again, &lt;name&gt;.  Keep up the good work!", rewards = nil}
MultiLanguageQuestData['en'][2882] = {title = "Cuergo's Gold", objective = "Find Cuergo's gold!", description = "This map shows a stretch of beach with a southern face.  Below the map are words, elegantly written...\n\n\nSouth of Wheedle\nSouth of home\nFind a mast and flag and bones\nDig you there, if you be bold\nDig and claim Cuergo's gold!\nA key you'll need and a key you'll see\nThe men you face take blood as fee.", progress = "This chest is locked!", completion = "Captain Cuergo's hidden treasure awaits!", rewards = "You will receive:\n\nCuergo's Hidden Treasure"}
MultiLanguageQuestData['en'][2902] = {title = "Woodpaw Investigation", objective = "Find the gnoll battle plans somewhere in the gnoll camps to the south of Camp Mojache.", description = "Gnolls aren't the sharpest tools in the shed, but they will no doubt have some sort of documented strategy on their recent activity.  If we were to find those plans, then we'd have a clearer idea of what is making them so worked up.\n\nI want you to head back to the Woodpaw and find anything that might resemble their battle plans.  They have to have something; their attacks have been too coordinated to be done without them.  Find them, and return to me when you have them.", progress = nil, completion = "Examining the map reveals it to be the battle plans that Hadoken Swiftstrider wants.  Numerous arrows that perhaps represent troop movements are drawn on the map, though most seem to be headed toward the south rather than to the north where Camp Mojache lies.\n\nAnother section of the map has a picture of what you think is a large insect of some kind, with various tick marks under it.  From the looks of the gnolls, it perhaps represents their losses against the unknown bugs...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2903] = {title = "The Battle Plans", objective = "Bring the Woodpaw Battle Plans to Hadoken Swiftstrider in Camp Mojache.", description = "With the battle plans of the gnolls discovered, all that now remains is to bring the plans back to Hadoken Swiftstrider in Camp Mojache.  Perhaps he or someone there can make further sense of what the gnolls are up to.", progress = "Welcome back <name> - were you able to find some tangible evidence as to the plans of the gnolls?", completion = "Ah, this is exactly what we needed.  While I am not so skilled at ciphering what most of the scrawling on this map is, I've seen enough battle plans in my day to understand what is happening with the gnolls.  It looks like they are currently fighting a two front war.  One is with us... but it seems that their main energy has been against a foe to their south.\n\nThere's more at hand here than meets the eye.  Perhaps it is time to figure out who this other foe they face really is.", rewards = "You will be able to choose one of these rewards:\n\nEarthclasp BarrierRushridge Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2904] = {title = "A Fine Mess", objective = "Escort Kernobee to the Clockwerk Run exit and then report to Scooty in Booty Bay.", description = "<Kernobee groans.> Wha.. What happened?\n\nThe last thing I remember is being captured by a group of dark iron dwarves, beaten to within an inch of my life and then thrown in here with these filthy troggs.\n\nGet me out of here, <name>!\n\nHere's the plan: Lead me to the exit; if we make it out alive, you go to Booty Bay and let Scooty know that I went to Ratchet to warn Tinkerwiz of the dark iron's involvement in the making of that super rig.\n\nLet's get going!", progress = nil, completion = "I suppose you should be rewarded for bringing Kernobee back to us in one piece, &lt;name&gt;. If you go back to Gnomeregan, these might give you the edge you'll need in defeating that good-for-nothing backstabber, Mekgineer Thermaplugg.", rewards = "You will be able to choose one of these rewards:\n\nFire-welded BracersFairywing Mantle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2922] = {title = "Save Techbot's Brain!", objective = "Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge.", description = "When our beloved city Gnomeregan fell, a rogue spark must have jolted my poor creation, Techbot.  It once aided me and my associates with its countless gizmos and limitless store of information, but its positronic brain has polarized.  Now it's negatronic... and Techbot's behaviors are reversed.  It roams Gnomeregan in a frenzy!\n\nBut perhaps it can be salvaged.  Perhaps, if you can retrieve Techbot's memory core and bring it to me, I can discover the cause of the polarization and fix my poor Techbot.\n\n", progress = "Did you find Techbot?  Did you retrieve its memory core??", completion = "Oh, this is wonderful!  Thank you, &lt;name&gt;!  I'll get to work immediately!!\n\nPoor, poor Techbot... Don't feel bad.  We'll get you fixed.\n\nNow, where did I put that plug for my hydro-jack swivel spanner...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2923] = {title = "Tinkmaster Overspark", objective = "Speak with Tinkmaster Overspark in Ironforge.", description = "Tinkmaster Overspark is very upset with the fate of his mechanical creation, Techbot.  I remember Techbot as a kind and helpful tool for the gnomes, but Overspark tells me it's malfunctioned.\n\nVery sad.  But with luck perhaps he can be fixed!\n\nSpeak with Tinkmaster Overspark, in Tinker Town in Ironforge.  He would welcome your help.", progress = nil, completion = "Yes it's true.  Techbot has gone rogue!  Please, can you help me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2924] = {title = "Essential Artificials", objective = "Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge.", description = "A nigh-universal mechanical component--the essential artificial--was of great use to the tinkers and smiths of Gnomeregan.  But during the frantic exodus from our city, no one remembered to take any of these devices with them!  And I need a large supply of them for work I will soon undertake.\n\nPlease, go into Gnomeregan and get me some essential artificials.  You'll find them in the deeper areas of our city, held in containers called artificial extrapolators.\n\nThank you, <name>, and please hurry!", progress = "Do you have the essential artificials?", completion = "You got them!  Now I can begin my new experiments!\n\nI can't thank you enough, &lt;name&gt;!  You're bravery has advanced gnomish research by a leap and a bound!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2925] = {title = "Klockmort's Essentials", objective = "Speak with Klockmort Spannerspan in Ironforge.", description = "A gnome friend, Klockmort Spannerspan, sent word to me from Ironforge.  He tells me he needs help on a dangerous, but essential, mission into Gnomeregan, the once great gnome city now contaminated and filled with mad gnomes and their devices.\n\nI must stay here, but my heart aches to help my friend.  If you can go in my stead, then I would be much indebted to you.\n\nYou may find Klockmort in Tinkertown, in Ironforge.", progress = nil, completion = "I do!  I do need help with a mission into Gnomeregan.  And you're just the &lt;class&gt; to do it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2926] = {title = "Gnogaine", objective = "Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers to collect radioactive fallout. Once it is full, take it back to Ozzie Togglevolt in Kharanos.", description = "Since the accident, all Gnoarn thinks about or talks about is cleansing Gnomeregan of the trogg infestation and finding a cure for the sickness that plagues it, <name>.\n\nLuckily, Razzle and I are close to some kind of cure - either that or the recipe for a really powerful rum. We won't know until we test! Naturally, in order to test our theory, we're going to need a few things; namely, fallout from the irradiated troggs in Gnomeregan. Fill up this phial with the green glow and bring it back!", progress = "Can't you see we're trying to cure an entire species of gnomes here??! We need more of the green glow!", completion = "Excellent work! The time has come to test the new formula. If this works, not only should that captured leper gnome be cured, but I should have a full head of hair! Stand back!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2927] = {title = "The Day After", objective = "Speak with Ozzie Togglevolt in Kharanos.", description = "You don't think I was always bald, do you? No <sir/ma'am>! It was the radiation leak in Gnomeregan that caused this tragic hair loss. Before that day, I had the only gnomefro in all of Azeroth.\n\n<Gnoarn shakes his fist in the air.>\n\nDamn those damned dirty troggs - damn them all!!\n\nPerhaps it's not too late, <name>. We may still be able to save it - the city I mean! Speak to Ozzie Togglevolt in Kharanos. He and his partner Razzle are working on a solution.", progress = nil, completion = "I thought the loss of that outstanding head of hair would have been the end of him for sure, but he survived!\n\nI was standing right next to him when he was hit by the radiation bolt. Those delightful brown locks of hair hit the floor in clumps! Clusters! The horror of it all was only compounded when Gnoarn completely freaked out! Oh yes, freaked out I say! Gnoarn touched his bald head in disbelief, the look in his eyes screamed revenge, &lt;name&gt;! Then he turned his anger towards the troggs!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2928] = {title = "Gyrodrillmatic Excavationators", objective = "Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind.", description = "It's terrible, <name>. We are not going to have enough parts to get our fleet of gyrodrillmatic excavationators to Dun Morogh.\n\nWhat we need are spare parts, <name>. What better place to get the spare parts for our vehicles than Gnomeregan? I hear that bots and mechs roam around that place like cattle on an open range.\n\nWhat I need you to do is go to Gnomeregan and tear apart those robots. Bring me back their robot guts. Two dozen should be sufficient.", progress = "If this were a race, you would have lost by now.", completion = "This will do nicely, &lt;name&gt;. One gyrodrillmatic excavationator fixed; 398 left to go.", rewards = "You will be able to choose one of these rewards:\n\nShoni's Disarming ToolShilly Mitts\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2929] = {title = "The Grand Betrayal", objective = "Venture to Gnomeregan and kill Mekgineer Thermaplugg. Return to High Tinker Mekkatorque when the task is complete.", description = "I trusted Thermaplugg, <race>. Never did I expect that he would betray me and the entire gnomish people. And for what? Power? Wealth? All things that he would have had in time. Now we have been displaced from our home and that madman is in charge. The king of nothing....\n\nWe will retake Gnomeregan, <name>. We will not stop until the city is back in our control. If you wish to join in our fight, a simple task I ask of you: Kill the betrayer. Destroy Mekgineer Thermaplugg.", progress = nil, completion = "I like to think that the last thing that went through his head as he collapsed to the ground was your foot, &lt;race&gt;. With Thermaplugg dead, our plans to retake Gnomeregan are one step closer to becoming a reality.", rewards = "You will be able to choose one of these rewards:\n\nCivinad RobesTriprunner DungareesDual Reinforced Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2930] = {title = "Data Rescue", objective = "Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge.", description = "When we fled Gnomeregan, we left so much data behind!  Vitally important data!\n\nI need the data on a prismatic punch card, from a Matrix Punchograph 3005-D high security terminal, deep in Gnomeregan.  You must access the terminal, but to do that you first need clearance... and to get that you must access lower security terminals-- models -A, -B and -C.  And to do THAT you need security punch cards, starting with white... and we left all the punch cards in the city.\n\nIt's a catastrophe!  Can you help?", progress = "Do you have the prismatic punch card??", completion = "You did it!  You found the prismatic punch card and recovered the lost data!  Vitally, critically, immeasurably important data that we could not live another moment without!\n\nYour service to the gnomes will be long remembered, &lt;name&gt;.", rewards = "You will receive:\n\nRepairman's CapeMechanic's Pipehammer"}
MultiLanguageQuestData['en'][2931] = {title = "Castpipe's Task", objective = "Speak with Master Mechanic Castpipe in Ironforge.", description = "Master Mechanic Castpipe in Ironforge has need of adventurers!  He's organizing bands to reenter Gnomeregan on a data retrieval mission of top security and importance.\n\nCastpipe might not be a member of the Enlightened Assembly of Arcanology, Alchemy and Engineering Sciences like I am, but he's still a smart gnome so if he thinks it's important, then by my calculations there's an eighty-four percent probability that it really is important!\n\nThose are good odds!", progress = nil, completion = "I'm organizing data extraction missions into Gnomeregan.  If you're here for that, then listen up!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2932] = {title = "Grim Message", objective = "Gather Witherbark Skulls and place on Nimboya's Pike. Place Nimboya's Laden Pike at one of the Witherbark Villages in the Hinterlands, then return to Nimboya in Stranglethorn.", description = "The Witherbark trolls were once allies to the Horde, but they betrayed Thrall... and that must be punished!\n\nHere, take my pike and go to the Hinterlands, far to the north.  You will find it northeast of Tarren Mill, a village held by our allies, the Forsaken.\n\nWhen you enter the Hinterlands, hunt Witherbark trolls.  Gather their skulls and drive my pike into the ground at one of their smaller villages, Hiri'watha or Zun'watha.\n\nShow them their vile actions are of consequence!", progress = nil, completion = "Word reached me of your deed.  A grim deed, but one of honor.  Let us hope the Witherbarks heed your message.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2933] = {title = "Venom Bottles", objective = "Bring a Venom Bottle to an apothecary in Tarren Mill.", description = "These bottles hold a vile, green venom.\n\nConsidering the number of bottles in this village, the Witherbarks must deem it very important.  Perhaps an apothecary in nearby Tarren Mill would like a sample.", progress = "Hello, gentle <class>.  The day has been long and not a single experiment successful...I hope you bring good news to me.", completion = "Ah, and what is this?  It appears to be venom... from some arachnoid creature I deem.  And where did you get it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2934] = {title = "Undamaged Venom Sac", objective = "Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill.", description = "I must have a fresh sample of the venom you brought me.  The spiders from which it was gathered must dwell in the Hinterlands -- hunt them until you find an undamaged venom sac and bring it to me.  You will find many spiders near the troll city of Shadra'Alor.\n\nDo not tarry, <name>, for the venom sac must be fresh when you deliver it.", progress = "Do you have the undamaged venom sac, <name>?  I yearn to run experiments with its fresh venom, and have ordered a collection of small, terribly cute animals on which to test it!", completion = "Oh, splendid!  The venom is quite fresh and I'm sure very deadly.  Thank you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2935] = {title = "Consult Master Gadrin", objective = "Speak with Master Gadrin in Sen'jin Village.", description = "The venom from the broodguards wasn't as potent as the venom you brought originally.  It must have come from a different spider.\n\nI want a fresh sample of that venom.  To find out where it came from, you must consult with a troll who knows the Witherbark well--Master Gadrin in Sen'jin Village.  Travel to Durotar and speak with Gadrin.  With luck, he'll know where the Witherbarks get their venom.", progress = nil, completion = "Ah, so you want fresh venom from the spider of the witherbarks, yes?  Well, sit down... you're not going to like what I have to tell you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2936] = {title = "The Spider God", objective = "Read from the Tablet of Theka to learn the name of the Witherbark spider god, then return to Master Gadrin.", description = "The Witherbarks worship a spider god, and from her they collect their most potent venom.  So if you want the venom, then you must summon their god!\n\nTo do that, you must know her true name, and that name is on a tablet buried in Tanaris, in the troll city of Zul'Farrak, in a tomb guarded by Theka the Martyr.\n\nDefeat Theka and find and read his tablet to discover the spider god's name.  When you know it, return to me.", progress = "Do you know the spider god's name?", completion = "Ah, Elortha no Shadra... speak this name only in whispers, for its utterance carries much weight in the realms of the spirit.\n\nI will put it to parchment and create for you a spell of summoning...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2937] = {title = "Summoning Shadra", objective = "Defeat Shadra at the altar of Shadra'Alor, then bring her venom to Apothecary Lydon in Tarren Mill.", description = "Take his parchment, and read it at the altar of Shadra'Alor, deep within the witherbark realm in the Hinterlands.  This will summon Shadra the spider god.", progress = "Did you get the venom?", completion = "Sweet, you got it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2938] = {title = "Venom to the Undercity", objective = "Bring Faranell's Parcel to Master Apothecary Faranell in the Undercity.", description = "The venom you gathered from the Witherbark's spider god is quite a find!  I've been able to kill nearly two dozen rabbits with just a drop of the stuff.  Granted, some of those rabbits were very young and small enough to fit in the palm of one's hand so I'm certain their resistance to toxins was low, but it can't be denied that this poison is powerful!\n\nI'd like a sample sent to my superior, Apothecary Faranell in the Apothecarium of the Undercity.  I am positive he would want to test this himself.", progress = "Word was sent of your coming, <name>.  You have a parcel for me?", completion = "Ah, very good.  Lydon mentioned the poison in this parcel is the most potent he has come in contact with, and is busy working on new applications with it.\n\nWith luck, we will find many.\n\nThank you, &lt;name&gt;.  Your service to the Royal Apothecary Society is undeniable.", rewards = "You will be able to choose one of these rewards:\n\nRoyal Highmark VestmentsHonorguard ChestpieceAegis of Battle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2939] = {title = "In Search of Knowledge", objective = "Talk to Daryn Lightwind in Rut'theran Village.", description = "While the ruins of Feralas can be quite dangerous, they have much to tell of what has happened here.\n\nSearching through the rubble to the south a few days ago, I discovered what appears to be a normal stave. However, I just can't shake the feeling that there is something more to it. Angelas and I have been poring over our books here, but we can't find a thing about it.\n\nI have a colleague in Darnassus that may be able to tell us what this is, <name>. Why don't you go talk to her and see if she can help us?", progress = nil, completion = "Oh, so Troyas Moonbreeze sent you?\n\n&lt;mutters&gt;...always bothering me with his wild notions that he found something important...\n\nLook, &lt;name&gt;, I'll be blunt. Troyas always thinks he has found something important in those ruins. The truth is, anything that was truly valuable was probably hoarded away long ago by the ogres or the harpies that now reside there.\n\nYou're welcome to take a look around, but I don't know if you'll find any books here that will help you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2940] = {title = "Feralas: A History", objective = "Ask Daryn Lightwind if you may borrow her book.", description = "This book looks as if no one has opened it for quite a long time. Its covers are quite worn, and its pages yellowed, but after examining it, you notice that it might be just what Troyas is looking for.\n\nYou pick it up, but realize you should probably ask before borrowing it.", progress = nil, completion = "So, you'd like to borrow Feralas: A History?\n\nLet me think...\n\nI will allow you to borrow this book, &lt;name&gt;, but only if you do something for me first.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2941] = {title = "The Borrower", objective = "Take the letter to Curgle Cranklehop in Tanaris.", description = "I have studied many subjects in my time, and my latest fascination is with the snapjaw that occupy the beach in the Hinterlands. There's one in particular I'd like to see, a giant snapjaw named Gammerita. I'd like to go myself, but my research keeps me here. I think a picture of her would be the next best thing.\n\nTake this letter to Curgle Cranklehop in Tanaris. She has created an invention for me that can capture a picture. She called it a \"snapshot,\" I think...", progress = "A letter -- for me?", completion = "Are you another one of Daryn's interns? She's quite a knowledgeable historian, &lt;name&gt;. You should be grateful to be studying under her leadership.\n\nNow, let me get the Super Snapper FX. You're gonna love it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2942] = {title = "The Morrow Stone", objective = "Return the Sparkling Stone and the Stave of Equinex to Troyas Moonbreeze in Feathermoon Stronghold.", description = "The moment the artifact is removed from the Monolith, you feel the energy in the Stave of Equinex begin to fade.", progress = "I am glad you have returned, <name>. I am eager to hear of your findings.", completion = "I have been reading since you left, &lt;name&gt;. This stone you have found is called the Morrow Stone. While I am not entirely sure what its purpose is yet, you can be sure that it is something of great significance to be hidden away inside the Equinex Monolith the way it was.\n\nI will continue my studies, and I hope I will be able to count on you in the future, &lt;name&gt;. Thank you for all your help.", rewards = "You will be able to choose one of these rewards:\n\nCairnstone SliverSeedtime Hoop\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2943] = {title = "Return to Troyas", objective = "Deliver the book to Troyas Moonbreeze in Feathermoon Stronghold.", description = "Here it is, <name>. Please, take care of my book.\n\nNow, hurry along. I'm sure Troyas is eager for your return.", progress = "Hello, <name>. Have you been to Darnassus?", completion = "You have brought a book along. Excellent!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2944] = {title = "The Super Snapper FX", objective = "Use the Super Snapper FX to take a snapshot of Gammerita, then return to Daryn Lightwind in Rut'theran Village.", description = "Have the first look at my new invention, <name>. All you need to do is target whatever it is you'd like to take a picture of, and push the button.\n\nWhat was that creature from the Hinterlands that you mentioned? Gammerita? Well, good luck finding her. I'm sure Daryn will be quite pleased with the snapshot you return to her.\n\nIn any case, here's the Super Snapper. Have fun!", progress = "So, you have finally returned, <name>. And you've brought the contraption that Curgle built for me -- perfect.", completion = "Well! Curgle's invention lived up to its expectations.\n\nDon't get too excited, but do know that I am pleased with your work, &lt;name&gt;.\n\nNow, where did I leave that book...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2945] = {title = "Grime-Encrusted Ring", objective = "Figure out a way to remove the grime from the Grime-Encrusted Ring.", description = "You have uncovered what appears to be a ring from the corpse of one of the Dark Iron dwarves.  It is difficult to tell what kind of ring it is, however; dirt and hardened residue cake the item completely, making wearing it impossible.  You think you can make out the slight luster of precious metal and maybe even the glint of a gem under the residue.\n\nIf you are going to make use of this ring, you are going to need to find something to get the hardened residue off of it.", progress = "The gnomish contraption before you bears a plaque calling it \"The Sparklematic 5200\".  The gist of the machine, from reading the instructions below the plaque, is to scrub away dirt that an item might have.  The machine has a coin slot, accepting three silver coins to start the process once the item is placed inside it.\n\nIt would seem as though the grime-encrusted ring you found earlier is just the thing to try in this machine!", completion = "You place the ring inside the Sparklematic 5200 and deposit a silver coin into the slot.\n\nPainful grinding noises emanate from the machine as it begins to jerk around violently.  One can only guess what is happening with the ring inside the machine...\n\nThe machine suddenly stops, trumpeting its cessation with a simple \"Ding!\"  The item receptacle opens up to reveal a small box that is neatly wrapped with a red bow.  It would appear that the Sparklematic 5200 also gift wraps!", rewards = nil}
MultiLanguageQuestData['en'][2946] = {title = "Seeing What Happens", objective = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", description = "We want you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nWhen you've found out what happens, return to Ironforge.  We'll have a lot to analyze when you're done!", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2947] = {title = "Return of the Ring", objective = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", description = "Opening the box produced by the Sparklematic 5200 reveals what you had suspected - a shiny ring!  Wearing the ring, you feel magic power surge through you body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Ironforge.  Next to that, three small initials are engraved: \"TdK\".  This may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or return it to this person.  Decisions, decisions...", progress = "Hey, easy there partner - I'm a very important businessman!  I am sure that the courier is just simply late with the delivery of the rent... wait... you're not my landlord.\n\nWell, of course you aren't - silly me!  You've come to me seeking the finest jeweler in all of Ironforge, one who does NOT make CURSED items!  Yes!\n\nUm... what do you need?", completion = "A ring, you say?  Let's see... yep, I made that ring by golly.\n\nBefore Gnomeregan went up, I had a small shop there.  Perhaps it's one I left behind when I ran for the hills; it's a simple design, and I made several like it.  Maybe it's from someone who didn't make it out.\n\nDark Iron dwarves had this?  Well, that puts a new layer of conspiracy on the nine different layers already floating about.  Maybe the authorities would like to know; it's wasted on the likes of me.\n\nNow, back to the ring...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2948] = {title = "Gnome Improvement", objective = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge.", description = "Listen <name>, that ring is yours, sure... but I can make you a better one!  That design, like I said, is really simple.  I am a lot more skilled now, and for the mere fee of thirty silver coins I'll spruce it up for you!  Well, a little more than thirty, actually...\n\nI'm in a tight spot right now; all my material stock is all dried up.  If you bring me a bar of silver and a moss agate, I'll add a silver and agate lattice to the ring that will give it a little more pizzazz!\n\nTrust me!", progress = "Do you have the materials I need?  I wouldn't ask you for them if I wasn't down on my luck...", completion = "Ah, exactly what I needed!  Someday, when I find myself out of this hole that I am unjustly in, I will make for you, for EVERYONE the finest trinkets in all of Azeroth!  Until then, thanks for being a sport about the reagents.  I'd normally charge ten times what I have charged you for a ring of this quality...\n\nSpeaking of rings, here's your new one!", rewards = "You will receive:\n\nTalvash's Gold Ring"}
MultiLanguageQuestData['en'][2949] = {title = "Return of the Ring", objective = "You may either keep the ring, or you may find the person responsible for the imprint and engravings on the inside of the band.", description = "Opening the box produced by the Sparklematic 5200 reveals a shiny ring!  Donning the ring, you feel magic power surge through your body.\n\nInside the band is a small but nonetheless discernable imprint of the seal of Orgrimmar.  Engraved letters are next to it, but only the first three stand out even after cleaning: \"NOG...\"\n\nThis may signify either the initials of the previous owner, or perhaps the initials of the ring's crafter.  Keep the ring... or find \"NOG\" - decisions, decisions...", progress = "You'd think that we would find a way on our own to outdo those filthy little gnomes.  I would even wager that they stole that rig from us to begin with!  Bah, those greasy, grimy... erm, yes?  You need something?", completion = "A ring from Gnomeregan?  Let's see... not mine, but interesting.\n\nThe Gnomeregan thing - couldn't have happened to a nicer bunch of numbskulls.  For years they're a joke, and now almost overnight they're making better rigs than us?\n\nDark Iron dwarves had the ring?  That's even more interesting!  You know, maybe the gnomes stole their crazy golem plans and modified them.  Those Dark Irons, they'd definitely want some major payback.  It's certainly worth investigating.\n\nYou know, about that ring...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2950] = {title = "Nogg's Ring Redo", objective = "Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar.", description = "No, no, no - I'm not all of the sudden saying that the ring is mine.  I normally don't do this, but your information about the Dark Irons was very useful.  I'll improve your ring for you, better than whomever made this simple little thing could have ever done.  Probably some gnome...\n\nIf you bring me a bar of silver, a moss agate, and thirty silver coins for my trouble, I'll add a silver and agate lattice to the ring that will strengthen the magic inside of it.  Interested?", progress = "Do you have the materials I need?  I can't improve on this design without everything I asked for.", completion = "Here's your ring, better than before.  Thanks again for the information about those Dark Iron dwarves.  This seems like a reasonable lead as to how those gnomes suddenly were struck with goblin-like inspiration.", rewards = "You will receive:\n\nNogg's Gold Ring"}
MultiLanguageQuestData['en'][2951] = {title = "The Sparklematic 5200!", objective = "Insert a Grime-Encrusted Item into the Sparklematic 5200, and be sure to have three silver coins to start the machine.", description = "This contraption stands out amongst the gnomes holding out against the madness outside the room.  A small plaque on the device reads \"The Sparklematic 5200\", followed by some text:\n\n\"Grime and residue ruining your sparklies?  The Sparklematic 5200 puts the shine back in shine-tastic!  Insert the item you wish to clean and deposit three silver coins in the coin slot.  Give The Sparklematic 5200 a moment for operation, and voila!  Your valuables will emerge clean and shiny!\"", progress = "It would seem that the device needs some sort of grime-encrusted object to clean and three silver coins to get the contraption working.  So long as both are present, the Sparklematic 5200 should work...", completion = "You insert the grime-encrusted item and three silver coins into the Sparklematic 5200.  The machine surges to life in an almost frenzied attempt to purge the grime from the unknown item.  Loud, violent churning sounds beat from the heart of the machine.  The metal frame of the beast creaks and groans as it lurches from side to side...", rewards = nil}
MultiLanguageQuestData['en'][2952] = {title = "The Sparklematic 5200!", objective = "As quickly as it started, the Sparklematic 5200 comes to an abrupt halt.  A simple \"ding\" is heard from the machine, and the mouth of the machine spirals upward.  Inside the Sparklematic 5200 is a small box wrapped in a little bow.  The machine would appear to wrap an object up after eliminating its grime-encrusted status.  Even if the machine didn't work, at least the item is now wrapped in a pretty box.\n\nWell, there is one way to find out if it cleaned the item or not...", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSparklematic-Wrapped Box"}
MultiLanguageQuestData['en'][2953] = {title = "More Sparklematic Action", objective = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", description = nil, progress = "The Sparklematic 5200 is empty, awaiting a grime-encrusted object to clean and three silver coins to start!", completion = "The Sparklematic 5200 comes to life, lurching to and fro.  Inside, the helpless grime that has encrusted the object placed within it is being pulverized by the machine's gnomish cleaning agent.\n\nThe Sparklematic 5200 comes to a halt, heralded by a familiar \"ding!\"  The item receptacle of the machine spirals open, revealing a neatly wrapped box.", rewards = "You will receive:\n\nSparklematic-Wrapped Box"}
MultiLanguageQuestData['en'][2954] = {title = "The Stone Watcher", objective = "Learn the purpose of the Stone Watcher of Norgannon, and then interact with the Uldum Pedestal in the Tanaris desert.", description = "\"Salutations - I am a guardian of entry.  Unless you have the Plates of Uldum already integrated with your disc set, I will not allow for entry into the Uldum compound.\"\n\nThe appearance of the Stone Watcher of Norgannon must be the reaction that was hoped for in sending you out to the Tanaris desert with the platinum discs.  As instructed, you will need to find out what the story behind the Stone Watcher is before continuing on.", progress = "The purpose of the stone watcher must be learned before continuing on...", completion = "The stone watcher's voice resonates with power and authority:\n\n\"Your discs will be returned to you once you access the pedestal.  When you have obtained the Plates of Uldum and incorporated them into your existing disc set, you may then enter the complex.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2962] = {title = "The Only Cure is More Green Glow", objective = "Travel to Gnomeregan and bring back High Potency Radioactive Fallout. Be warned, the fallout is unstable and will collapse rather quickly.\n\nOzzie will also require your Heavy Leaden Collection Phial when the task is complete.", description = "Not only was your sample insufficient in quantity, it was also impure.\n\nWhat we require is more green glow. The troggs are obviously not irradiated sufficiently to fulfill our needs. You will have to go into Gnomeregan and bring back some radioactive fallout, straight from the tap. I am speaking of the irradiated slimes, lurkers and horrors. Be warned, the containment of this type of fallout is difficult. You may need to make several attempts with the phial until a suitable sampling is recovered.", progress = "Hrm, you're not glowing. That's a good sign.", completion = "&lt;Ozzie examines you.&gt; Impressive, you still have all of your limbs. Now it's time to see what this stuff can do!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2963] = {title = "Portents of Uldum", objective = "Speak with Historian Karnik in the Hall of Explorers within Ironforge.", description = "Greetings once again, <name>!  Your discovery inside Uldaman has set the Explorers' League abuzz with excitement.  The League has been working to unlock the secrets of the miniature platinum discs you found.  Your fortuitous arrival here in the Hall allows me to share with you that we are quite possibly on to something!\n\nHistorian Karnik has uncovered some important clues as to the true origins of the Valley of the Watchers in the Tanaris desert.  He would like to speak with you as soon as possible!", progress = nil, completion = "I am glad you're maintaining your interest in exploration, &lt;name&gt;!  With your natural talent and moxie, we could crack open secrets that we never thought were possible!\n\nThe Discs of Norgannon in Uldaman were a repository of vast information; you were only permitted to access the top layers, as it were, of the information stored there.  The Creators were rumored to have more repositories located throughout Azeroth.  This now brings us to Uldum...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2964] = {title = "A Future Task", objective = "Speak with High Explorer Magellas in Ironforge.", description = "Well <name>... we seem to be at a temporary dead end here.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We'll need to do quite a bit of research on this to come up with a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to head out and recover them.\n\nThe High Explorer needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again aiding the League.", progress = nil, completion = "We're all in agreement then - the best plan of attack is putting this on hold until we can narrow down the areas where these plates might lie hidden.  You've brought us this far &lt;name&gt;, and I hope you will be the one to head back in to the field to unlock Uldum for us all!\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons!", rewards = "You will be able to choose one of these rewards:\n\nScrying WandThorium Flight Blade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2965] = {title = "Portents of Uldum", objective = "Speak with Nara Wildmane on the Elder Rise in Thunder Bluff.", description = "Ah, <name>, it is fortuitous that you have come to me again.  Your revelations at the Uldaman dig site have certainly given us sages much discuss.  I was doing just that with one of the druids, Nara Wildmane, when it dawned on me that her past adventuring experiences may have some great importance as to the next step we need to take.\n\nI would like for you to speak with her concerning her travels to the Valley of the Watchers in the Tanaris desert.  She waits for you on the Elder Rise.", progress = nil, completion = "There is a place deep in the Tanaris desert called the Valley of the Watchers.  The discs that you recovered... their translated glyphs make mention of a place called Uldum.  Most think this place to be a myth.\n\nI know this to be false; Uldum exists.  I've been there.  Well... outside, at any rate.\n\nThe crux is this, &lt;name&gt;: we think there is a connection between the discs and Uldum, and we want you to go there.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2966] = {title = "Seeing What Happens", objective = "Bring the miniature platinum discs to the gates of Uldum in Tanaris and look for clues as to the connection between the two.", description = "Sage Truthseeker and I would like you to take the miniature discs you found to the sealed gates of Uldum.  We... we aren't sure what will happen when you do this.\n\nThis sounds risky, sure, we acknowledge that.  It might, however, do nothing.  You might need to use the discs on something.  Perhaps the doors unlock when you have the discs in your possession.  Be open to try anything, and be ready for anything to happen.\n\nLearn what you can, then return to me. We will have much to discuss.", progress = "This familiar looking pedestal sticks out of the hot sand.  Perhaps there is something to its presence here...", completion = "As you touch the pedestal, the miniature discs from Uldaman hum and glow in your backpack.  A familiar feeling tingle washes over your hands, as the image of another Stone Watcher springs to life in front of the gates of Uldum.\n\n\"Salutations.  I am a guardian of entry.  The discs that have been used for access are missing the correct entry discs, the Plates of Uldum.  Please incorporate these plates with the disc structure and repeat your access sequencing.  Thank you.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2967] = {title = "Return to Thunder Bluff", objective = "Speak with Nara Wildmane in Thunder Bluff.", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Thunder Bluff and inform the Nara Wildmane of your discovery.", progress = "Welcome back <name>.  Were you able to use the discs to your advantage, or was it for naught?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself.  I don't know whether to be excited by that prospect, or be terrified.\n\nWe may need to risk everything to ensure that those secrets the earth keeps which would destroy us all remain just that - secrets.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2968] = {title = "A Future Task", objective = "Speak with Sage Truthseeker in Thunder Bluff.", description = "Well <name>... we seem to be at an unfortunate impasse.  We know what we need - the Plates of Uldum - but we have no idea where they might be.  We will research this, and then devise a solid plan of attack.  I have a couple ideas where to start looking; I have high hopes that soon, we'll be asking you to rejoin our efforts to discover the truth.\n\nSage Truthseeker needs to be informed on this, <name>; no doubt, he also wants to thank you personally for once again heeding the call.", progress = nil, completion = "We're all in agreement then - the best course of action is to wait until we can narrow down the areas where these plates might lie hidden.  You've brought us this far &lt;name&gt;, and I hope you will be the one to head back in to the field to confront the secrets of Uldum.\n\nAllow me to give you this honorarium in the meantime; this should cover any expenses you've encountered in assisting us, and a little something extra.  Be sure to check back with us soon... Uldum beckons us all, young one.", rewards = "You will be able to choose one of these rewards:\n\nCave Crawler's Mail TreadsTempered Thorium Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2969] = {title = "Freedom for All Creatures", objective = "Using the Bamboo Cage Key, free the Sprite Darters from the pen in the Grimtotem camp. At least 6 Sprite Darters and Kindal Moonweaver must survive.\n\nYou have 6 minutes before Kindal decides it is time to retreat and you fail the quest.", description = "The filthy Grimtotem clan are capturing faerie dragons, <name>. Jer'kai and I have no idea what they plan on doing with them, but they're obviously up to no good.\n\nWe're not powerful enough to fight our way into the camp and free the captured dragons, but perhaps with your help...\n\nIf you're willing, and you have some strong friends, release the creatures from their cage with this key and make sure they escape with their lives. I'll be by your side the entire time. Jer'kai will remain here.", progress = "We cannot allow the Grimtotem clan to destroy these beautiful creatures. They must be released from captivity!", completion = "Thank Elune, &lt;name&gt;! You are a great blessing to us and to the darters you saved. Jer'kai and I would never have been able to help the dragons ourselves--your intervention in the Grimtotem's affairs will be remembered.\n\nSpeak to Jer'kai now... I have to prepare for our retribution. Just because the faerie dragons are free, it doesn't mean they will remain so. Jer'kai and I will now go on the offensive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2970] = {title = "Doling Justice", objective = "Kill 12 Grimtotem Naturalists, 10 Grimtotem Raiders, and 6 Grimtotem Shamans before returning to Jer'kai Moonweaver in Feralas.", description = "As she's already told you, Kindal and I will now take the fight to the Grimtotem. Together, we should still be able to pick off some of the tauren without much threat to ourselves, but we'd love some help if you're willing and able.\n\nYou've seen the camp below us, but there are more to the east. Using your own tactics, deal as much damage to the tauren as you can. We can all meet back here after they've felt the sting of Kindal's arrows and your own weapons.", progress = "Kindal needs time to prepare, but our kills already number in the dozens. The Grimtotem clan is more than aware of our presence in the area, and they seek us out like vipers.\n\nThey'll do everything in their power to take our heads from our bodies. You should be alert... they'll be coming for you too now that you've interfered.", completion = "Kindal was right about you, &lt;name&gt;--you do have a knack for this. You are a more seasoned adventurer than the both of us, and for that we thank you.\n\nThe Grimtotem clan is much more hostile than most tauren... I wonder if their own kind frowns upon their actions. I wouldn't be surprised. As you are probably aware, many races on Azeroth have ties to less kindly counterparts.\n\nBut that is a discussion for another day.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2972] = {title = "Doling Justice", objective = "Take Jer'kai's Signet Ring to High Priestess Tyrande Whisperwind in Darnassus.", description = "Out here in the wilderness, Kindal and I have meager means to reward your help, but we don't want you to feel unappreciated. Take my signet ring. If you ever find yourself in the boughs of Teldrassil, go to the Temple of the Moon in the heart of Darnassus. There you will find my High Priestess Tyrande Whisperwind. The ring will let her know that we are well and give credit to your story.\n\nWe both thank you, <name>.", progress = "Hello, child. It pleases us to have more powerful adventurers here in the temple. If you have the time, will you share a tale or two with the younger adventurers? I know many of them would benefit from your wisdom.\n\nI'm sorry, look how rude of me. You've come to the Temple seeking our aid, and I impose on you. Please, forgive me. Tell me what the servants of the Light can do for you.", completion = "That's an amazing story, &lt;name&gt;. It pleases us that you've not only helped dragonkind, but also one of our own priestess. Jer'kai was right to send you to me. I will make sure she has her ring returned to her--I have scouts heading the direction of Feralas soon. This will be one more thing for them to investigate while on their mission.\n\nThank you again, and please, make yourself at home while you're here.", rewards = "You will be able to choose one of these rewards:\n\nFirwillow WristbandsNightscale Girdle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2973] = {title = "A New Cloak's Sheen", objective = "Bring 10 Iridescent Sprite Darter Wings to Krueg Skullsplitter in Camp Mojache.", description = "Well met, <class>. I've traveled with my companions down to the Feralas on a mission for our Orgrimmar masters.\n\nMy life-mate Korrin finds great pleasure in new clothing, so I aim to make her a new cloak adorned with the gossamer wings of faerie dragons. Would you be able to help me? Sprite darters with gorgeous wings I want are west of Camp Mojache.", progress = "The sprite darters can be dangerous critters when provoked. Be careful when dealing with them, <class>. And be even more careful of any night elves in the area. The pestering fools tend to hold up in the forests also.\n\nWhen you've gotten enough of the wings, let me know, I'll be sure to reward you well!", completion = "Wonderful, &lt;class&gt;! These will do nicely. There are enough here to make a cloak for Korrin, and possibly even more! Thank you.\n\nI hope the trip wasn't too dangerous? The area of Feralas is not known for being forgiving, but you've obviously done well enough.\n\nThank you again, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2974] = {title = "A Grim Discovery", objective = "Bring 20 Grimtotem Horns to Krueg Skullsplitter in Camp Mojache.", description = "What!? You came across tauren in the area? You're joking! What did they look like!?\n\nThe Grimtotem clan! You found some of them? Belgrom, one of our masters, has an interest in their kind... he's even put a bounty on them.\n\nYou have to go back, <class>. Go back and bring me their horns... piles of them if you can. The Grimtotem are not to be trifled with or underestimated. Go back and slay them; let the rivers in Feralas run red with their dark blood.", progress = "Take my words seriously, <class>, the Grimtotem clan is evil. If you've found their whereabouts, then it's up to you to return and strike the first blow against their clan... before they can come into our own lands and raze our own villages, or pilfer our lands.", completion = "These are good horns, &lt;class&gt;. Well done. I'll take these from you and be sure to tell Belgrom as soon as we return to Orgrimmar. You've helped me twice now, and for that, you have my mark. Perhaps in the future I can help you! Good luck to you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2975] = {title = "The Ogres of Feralas", objective = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Ogres, 10 Gordunni Ogre-Magi, and 5 Gordunni Brutes.", description = "The effects of the Gordunni Ogre tribe can hardly go unnoticed in this area. Look around, <name>; their very presence scars this land. We must push them back before they expand even further into Feralas.\n\nFollow the river north, and you will find their outpost. Decrease their numbers, <name>. We must show them that their kind is not wanted here.", progress = "Move swiftly, <name>. Or is the task I requested too difficult?", completion = "Excellent, &lt;name&gt;. In time, the land will heal. We must not give up.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2976] = {title = "A Grim Discovery", objective = "Bring the Crate of Grimtotem Horns to Belgrom Rockmaul in Orgrimmar.", description = "What?!\n\nAh, so I did mention a bounty, didn't I? Well, that'll teach me to open my mouth, won't it?\n\nYou did the work, so I suppose it is only right you reap the greatest reward from it. Take the horns, I'll have them put in a crate for you. Find Belgrom Rockmaul in the Valley of Honor, he'll want to know what you saw and he'll reward you for your hard work.\n\nBe well, <class>, and thank you again for everything you've done.", progress = "Be quick, <class>, I have much to complete today.", completion = "The Grimtotem!? This is interesting. You say you came across them while hunting in Feralas? Truly?\n\nMy peers will want to hear your news, &lt;class&gt;. Tell me more and I'll count out your coin while you do so.\n\nAnd before you go, know that I give you thanks for the information you've passed on to me this day.", rewards = "You will be able to choose one of these rewards:\n\nBattlehard CapeJademoon Orb\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2977] = {title = "Return to Ironforge", objective = "Speak with Historian Karnik in Ironforge.", description = "You access the pedestal again; the platinum discs suddenly appear once more in your backpack.\n\nWith the knowledge of the stone watcher learned and the discs returned to your possession, the time has come to return to Ironforge and inform the Explorers' League of your discovery.", progress = "Welcome back <name>.  Were you able to use the discs to your advantage, or did it end up being a wild goose chase?", completion = "You were missing some discs?  Interestingly enough, it seems that the discs of Norgannon are only parts of the complete set - like keys on a key ring, if you will.\n\nIf we can find the Plates of Uldum, then we could actually access the Uldum complex itself!  Imagine actually exploring the place where the Creators worked without having to bring a huge shovel!\n\nNot that there's anything wrong with shovels... or digging...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2978] = {title = "The Gordunni Scroll", objective = "Bring the Gordunni Scroll to Rok Orhan in Camp Mojache.", description = "Picking up the soiled scroll, you notice that it seems to be depicting some sort of meeting or ceremony. Rok Orhan would be interested in this scroll, and what it might mean to the Gordunni.", progress = "What is this?", completion = "This scroll... You found this in the Gordunni Outpost?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2979] = {title = "Dark Ceremony", objective = "Rok Orhan in Camp Mojache wants you to find a Gordunni Orb.", description = "These seem to be plans for some sort of dark ceremony, <name>. From what I can make out, this ritual is conducted by the Gordunni mage-lords.\n\nFind one of these mage-lords, and from him, gather an orb.\n\nThe orb of a mage contains great power, and will help us discover more about this ceremony and the magic that the Gordunni wield.", progress = "We must discover more about why the Gordunni are here, <name>.", completion = "This orb will provide us with more information about the Gordunni... which we will then use in planning their downfall, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2980] = {title = "The Ogres of Feralas", objective = "Rok Orhan in Camp Mojache wants you to kill 10 Gordunni Shaman, 10 Gordunni Warlocks, and 5 Gordunni Maulers.", description = "Now that you have proven that you are a true fighter, I trust that you possess the courage to continue with the task at hand.\n\nTravel to the High Wilderness, southwest of here. There lie some abandoned and destroyed structures, on land that once belonged to the night elves. Look for these ruins, and when you see the withered trees and desecrated terrain, you will find the Gordunni. Push them back.\n\nThese ogres are much stronger than the ones you faced previously, <name>. Be aware.", progress = "Have you found the ruins, <name>?", completion = "You have proven yourself to be a trustworthy and dependable ally, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2981] = {title = "A Threat in Feralas", objective = "Belgrom Rockmaul wants you to speak with Rok Orhan in Camp Mojache.", description = "Feralas is an ideal location for an accomplished <class> to prove <himself/herself>. A tribe of ogres called the Gordunni are the dominant military force there, and their numbers are growing. They must be stopped before they threaten our presence in Feralas.\n\nA warrior I know of named Rok Orhan resides at Camp Mojache in Feralas; go to her. She will tell you more of the situation when you arrive.", progress = nil, completion = "So, Belgrom sent you. You are just in time, &lt;race&gt;.\n\nLet me explain the situation, and then you can decide if you are up to the challenge... But if Belgrom sent you, I am sure your courage is unquestionable.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2982] = {title = "The High Wilderness", objective = "Angelas Moonbreeze wants you to kill 8 Gordunni Warlocks, 8 Gordunni Shaman, and 8 Gordunni Brutes.", description = "Although it is dangerous, Troyas and I have been investigating the ruins that cover the forests of Feralas.\n\nLately, though, Troyas has been going on his own to the High Wilderness, and I really worry about him. The Gordunni Ogres have taken over that area, and they don't take kindly to anyone that enters their territory.\n\nI was hoping you might be willing to travel to the ruins to the southeast and clear out some of the ogres. Make it a little safer for my Troyas, and I will be extremely grateful.", progress = "Be watchful around the Gordunni, <name>. Their magic seems to wreak havoc on the very land they stand on.", completion = "I am very grateful you were able to do this for me.\n\nNow, please, don't mention a word to Troyas about this...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2983] = {title = "Call of Fire", objective = "Find Kranal Fiss in the Barrens.", description = "It's been some time since you were tested last, <name>. You've been patient thus far in your studies, but it's time for you to learn about greater powers... it's time you learn real power. The element of fire is yours if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the blasted night elf lands, you've gone way too far.", progress = nil, completion = "Hmmm, Swart sent you to me, did he?\n\nWell then, Swart could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, &lt;name&gt;. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2984] = {title = "Call of Fire", objective = "Find Kranal Fiss in the Barrens.", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about destruction... and chaos. The element of fire is yours for the understanding, if you're prepared to pay for it.\n\nSeek out Kranal Fiss in the Barrens. He lives in a small dwelling north of the Crossroads, but be mindful, if you've reached the night elf lands, you've gone too far.", progress = nil, completion = "Hmmm, Narm sent you to me, did he?\n\nWell then, Narm could always be trusted, so that must mean you're ready to take part of the next sapta--the sapta of fire.\n\nI see it in your eyes already, the burning, the desire. You've tasted power, and now you're ready for more of it. Patience, &lt;name&gt;. Remember what earth taught you. Power and destruction will come easily, but you must still know when to stay your hand.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2985] = {title = "Call of Water", objective = "Find Islen Waterseer in the Barrens.", description = "You look ready for your next test, <name>. You've been patient in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.", progress = nil, completion = "The wind approaches you quickly from the horizon; the earth is steady beneath your feet; and your spirit is already warmed by fire--I would say it is time for you to learn about the purity of water.\n\nYour path has led you this far, and your spirit will give you the strength to carry on even further. But the first step is yours to take.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2986] = {title = "Call of Water", objective = "Find Islen Waterseer in the Barrens.", description = "Long has it been since you were last tested, <name>. You have shown patience thus far in your studies, but the time has come for you to learn more. The time has come for you to learn about the purity of water.\n\nSeek out Islen Waterseer in the Barrens. She is along the eastern coast, south of the Southfury River and Ratchet. You will find her there at her fishing hut. Good luck to you, <name>.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2987] = {title = "Gordunni Cobalt", objective = "Orwin Gizzmick in Camp Mojache wants 12 samples of Gordunni Cobalt.", description = "I just arrived here in Feralas, and I've heard that the Gordunni Ogres that inhabit the wilds here have some interesting minerals. Who knows what they are up to, but they sure are protective of that stuff! They don't leave it just lying around; no, they bury it to protect folks like me from getting their hands on it.\n\nIf you'd be willing, I'll give you my shovel. Go to the Gordunni Outpost north of here and dig me up some Gordunni cobalt. Look for the blue glow, then start digging!", progress = "Get on up there and start digging!\n\nI've got places to go and people to see -- time is money!", completion = "Perfect! I will take these along as I continue my travels, &lt;name&gt;. I'm sure I can find someone that will pay a pretty penny for this cobalt.\n\nHere, take this for your trouble.", rewards = "You will be able to choose one of these rewards:\n\nBoots of the MaharishiStargazer Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2988] = {title = "Witherbark Cages", objective = "Check the cages at the two Witherbark villages, then return to Gryphon  Master Talonaxe.", description = "The son of our mightiest gryphon is gone! Swiftwing's heir, Sharpbeak, was lost while hunting with his parents a few days ago, and we believe it was the trolls who took him.\n\nYou must aid us!  Search the cages in the two Witherbark troll villages to see if Sharpbeak is there.", progress = "Have you searched the cages, <name>?  We must find Sharpbeak!", completion = "Sharpbeak wasn't at the villages?  Hm... this is grim news.  That gryphon is destined to lead the next generation of gryphons.  If he is lost then the strength and spirit of our fleet will suffer immensely.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2989] = {title = "The Altar of Zul", objective = "Check the top of the Altar of Zul, then return to Gryphon Master Talonaxe.", description = "Sharpbeak was not with the Witherbark trolls.  Perhaps the Vilebranch trolls took him.  Go to the Altar of Zul on the western edge of Vilebranch territory and search for the gryphon child.", progress = "Hurry, <name>!  If the Vilebranch trolls have Sharpbeak, then who knows what they might be doing with him!", completion = "Sharpbeak wasn't there?  That is bad news, but it is good news too...\n\nIt is good that he was not at the Altar of Zul for the Vilebranch trolls are known for performing sacrifices.\n\nI thank you for all of your aid, but I'm afraid I have an even greater task ahead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2990] = {title = "Thadius Grimshade", objective = "Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands.", description = "Take this feather to Thadius Grimshade, the diviner.  He left Aerie Peak years ago to pursue darker knowledge, but in his heart he is still a Wildhammer!\n\nAnd perhaps his talents can help us find Sharpbeak.\n\nThis feather was taken from the nest where the gryphon child sleeps.  If you give it to Thadius then, with luck, he can use his divining magics to find Sharpbeak.\n\nGood luck, <name>.  You will find Thadius in the Blasted Lands, in the mage tower of Nethergarde Keep.", progress = "<name>, you come bearing a gift?", completion = "Ah, yes.  This feather belongs to a fine gryphon.  One destined for great things... if he can survive into adulthood undamaged.\n\nYou wish to find him?  Then listen close, brave &lt;class&gt;...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2991] = {title = "Nekrum's Medallion", objective = "Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands.", description = "I'll find out where your gryphon is, but first you have to do something for me.  There's a troll in Zul'Farrak, Nekrum Gutchewer, who possesses a medallion I would very much like to study.  Bring me that Medallion and I'll use my powers to find Sharpbeak.\n\nZul'Farrak is across the ocean to the west, in the desert of Tanaris.", progress = "Do you have Nekrum's Medallion, <name>?  There are powers hidden within it that I am eager to discover.", completion = "Ah, the medallion of Nekrum.  It is rumored to have given the troll an unnatural long life, but at a cost.  I hope to discover a way to reap the medallion's power while avoiding its... unpleasant side effects.\n\nYou have done me a service, &lt;name&gt;.  I shall now uphold my end of our bargain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2992] = {title = "The Divination", objective = "Wait until Grimshade performs the ritual of divination.", description = "Give me room while I perform a ritual of divination.  I will find the connection between the feather you brought me and its owner, and follow that connection to Sharpbeak himself.\n\nThat is... I will if all goes according to plan.  If it does not, then... you better close your eyes.", progress = nil, completion = "The ritual was a success.  I have seen Sharpbeak and can tell you how to find him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2993] = {title = "Return to the Hinterlands", objective = "Speak with Gryphon Master Talonaxe.", description = "Sharpbeak is held in a cage, high on a cliff at the top of Jintha'Alor in the Hinterlands.  The key to this cage is possessed by the high priestess of the Vilebranch trolls, Vile Priestess Hexx.\n\nThere.  I have done my part.  I bid you fortune on your quest, <name>.", progress = nil, completion = "You've spoken with Grimshade?  What did he say?\n\n...What?  The Vilebranch trolls have Sharpbeak?  That's unbearable!  We must organize a force to get him back!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2994] = {title = "Saving Sharpbeak", objective = "Fight to the top of Jintha'Alor, kill Vile Priestess Hexx for the key to Sharpbeak's cage, and save Sharpbeak.", description = "We must save Sharpbeak!\n\nFight your way to the top of Jintha'Alor in the heart of Vilebranch territory, gain the key to Sharpbeak's cage from the vile Priestess Hexx, and then find and save Sharpbeak!", progress = "Save Sharpbeak!", completion = "Swiftwind and Keenclaw returned with their child moments ago, and are fussing over him like new parents.  Seeing them together again is enough to give even this old dwarf mist in the eyes...\n\nWe cannot repay you enough for what you have done, &lt;name&gt;.  The gryphons of Aerie peak, and their riders, will sing your name for a long, long time.", rewards = "You will be able to choose one of these rewards:\n\nGryphon Rider's StormhammerGryphon Rider's Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][2995] = {title = "Lines of Communication", objective = "Oran Snakewrithe in Undercity wants you to travel to the Hinterlands and burn the Highvale Records, Highvale Report, and Highvale Notes.", description = "The Quel'Danil Lodge is a center of communication for the high elves of the Hinterlands. Their ambassadors are working to establish relationships with other races, with whom they share their knowledge of the Witherbark trolls that inhabit the area in the southern Hinterlands. All of the documents regarding the communications are kept at the lodge.\n\nWe don't need the Highvale building alliances with others, <name>.\n\nDestroy the Highvale documents.  We need to burn their lines of communication... literally.", progress = nil, completion = "Perfect, &lt;name&gt;. While the Highvale work to recover their lost information, we will be able to seal off the lines even further...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2996] = {title = "Seeking Strahad", objective = "Speak to Strahad Farsan in Ratchet.", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak. He is powerful even though he may be small. He can teach you about more powerful summonings--I feel you are ready. Go to him now. He is in Ratchet... above the port town next to his tower.", progress = nil, completion = "A busy day in Ratchet, isn't it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.\n\nIs that hatred I see in your eyes, &lt;name&gt;? Good, we will put that to good use.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2997] = {title = "Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge.", description = "Hello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should make your way up to Ironforge to speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.\n\nYou can find her upstairs in the Hall of Mysteries. If you've never been there, it's in the Mystic Ward. Good luck to ya, <name>.", progress = nil, completion = "Well met, &lt;name&gt;. I hope the Light shows you the true path and keeps you safe from evil.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2998] = {title = "Tome of Divinity", objective = "Speak to Duthorian Rall in Stormwind.", description = "Greetings, <brother/sister>. Duthorian Rall, one of our most influential paladins, was speaking about you recently. I overheard him talking about how it was time you be put to the test some... along with some very complimentary things about how well you've performed thus far.\n\nIf I were you, I'd head to Stormwind and speak to him when you have time. I'm sure he's in the Cathedral of Light--that's where he spends most of his time.", progress = nil, completion = "It is beautiful here in Stormwind, is it not?\n\nYour timing actually couldn't have been better, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][2999] = {title = "Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge", description = "Hello, <name>. I know you're busy helping out the people of Dun Morogh, but when you have the time, you should go upstairs and speak to one of our most respected ilk: Tiza Battleforge. She's the one the younger paladins go to when it's time they learn more about the Light and what's expected of ya.", progress = nil, completion = "Well met, &lt;name&gt;. I hope the Light shows you the true path and keeps you safe from evil.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3000] = {title = "Tome of Divinity", objective = "Speak to Tiza Battleforge in Ironforge.", description = "Hello, <name>. I know you're busy helping out the people of Azeroth, but when you have the time, you should return to Ironforge and speak to one of the most respected paladins of your home: Tiza Battleforge. She's the one the younger dwarven paladins go to when it is time they learn more about the Light and what's expected of all of us.\n\nYou can find her upstairs in the Hall of Mysteries which is located in the Mystic Ward.", progress = nil, completion = "I greet you, and bid you welcome, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3001] = {title = "Seeking Strahad", objective = "Find Strahad Farsan in Ratchet.", description = "I have taught you skills in the past, but the time has come for another to teach you. He is in Ratchet, and his name is Strahad. He is human, but do not let that fool you into thinking he is weak, nor is he your enemy... at least for now. He is powerful and should be respected. He can teach you about greater summonings, summonings I feel you are prepared for. Go to him now.\n\nYou can find him in Ratchet... above the port town next to the tower there.", progress = nil, completion = "A busy day in Ratchet, isn't it? How I enjoy watching the toil of a port city. So much mystery, so much adventure... so much ignorance.\n\nIs that hatred I see in your eyes, &lt;name&gt;? Good, we will put that to good use.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3002] = {title = "The Gordunni Orb", objective = "Bring the Gordunni Orb to Uthel'nay in the Darkbriar Lodge in Orgrimmar.", description = "Although I know my enemy well, I am a warrior, <name>. I cannot begin to tell you what this orb is capable of.\n\nI know of a mage in Orgrimmar that will be able to tell us more about the orb. Take it to him.", progress = "What have you brought me, <race>?", completion = "Fascinating, &lt;name&gt;...\n\nThis orb is very powerful, but also very dangerous.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3022] = {title = "Handle With Care", objective = "Bring the Carefully-packed Crate to Erelas Ambersky in Rut'theran Village.", description = "<name>, I can see you yearn to be dedicated to my worthwhile cause. Yes, of course, you can do something for me!\n\nTake this crate of eggs to Erelas Ambersky. He is a druid that cares for these eggs, helping them to hatch and then training the young hippogryphs. You will find him in Teldrassil, in a small village to the south called Rut'theran.", progress = "Another shipment from Curgle, I assume?", completion = "Thank you for your help, &lt;name&gt;. The hippogryph population simply wouldn't flourish if it weren't for us. Ah, but I am sure you understand all too well, having traveled to Feralas yourself, and seen the devastation of the Gordunni there.\n\nWell, as you can see, I am hard at work here, so you'd best be on your way.\n\nThanks again, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3042] = {title = "Troll Temper", objective = "Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan.", description = "The Sandfury trolls of Zul'Farrak make a tempering agent from sandstones, and I can use that to temper the goods I craft, yes I can!  It is highly prized by connoisseurs, so if you bring me a good supply of the temper, then I'll reward you well.\n\nZul'Farrak is northwest of Gadgetzan.  Good luck.", progress = "Did you bring me the temper, <name>?", completion = "Ah, this is very nice temper indeed!  And so much of it!  I'll be at work for days before I use it all!\n\nThank you, &lt;name&gt;.  Please, take this as payment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3062] = {title = "Dark Heart", objective = "Talo Thornhoof in Camp Mojache wants Edana Hatetalon's Dark Heart.", description = "Edana Hatetalon is the queen of the Northspring harpies that reside in the ruins to the west. She is pure evil; I have heard that her heart is one of crystal. She is void of any emotion aside from the hate she feels towards all others. You must face Edana and bring me back her dark heart.\n\nI have heard of a horn that harpies carry -- blowing it by the Hatetalon stones, in the northern part of the ruins, will summon the queen.\n\nImagine her surprise when it is not her kin calling her, but her death.", progress = "The hate that Edana spreads across the land must be stopped.", completion = "Now I know that Edana is truly dead. This heart; I will keep it in memory of what did here for me, &lt;name&gt;. Thank you.", rewards = "You will be able to choose one of these rewards:\n\nWingcrest GlovesStronghorn Girdle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3063] = {title = "Vengeance on the Northspring", objective = "Talo Thornhoof wants you to kill 4 Northspring Harpies, 4 Northspring Roguefeathers, 4 Northspring Windcallers, and 4 Northspring Slayers.", description = "In my day, I was a seasoned hunter. There wasn't any creature around that I feared. Until...\n\nI was out in the forest, sharpening my blade after a tough battle, when I was ambushed. Harpies surrounded me, and I barely managed to drag myself to safety.\n\nEven now, I can still hear their cries echoing...\n\nI was never the same after that. But the hate boils inside of me -- I must get even, after all these years.\n\nThe Northspring harpies can be found to the west of here. <name>, get my revenge.", progress = nil, completion = "Thank you, &lt;name&gt;. You have put an old tauren's mind at peace.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3065] = {title = "Simple Tablet", objective = "Read the Simple Tablet and speak to Frang in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the warrior trainer Frang. He would have words with you when you're ready. You'll find him outside the Den, taking cover in the shade.", progress = "Another <race> to bolster the ranks. Good enough for me.\n\nYou'll probably have a hard time hefting a good weapon like an axe, but a spear's just as good as anything else.\n\nWelcome to the Valley of Trials.", completion = "You'll find this place fitting as you continue to train in the &lt;class&gt; ways. If you have any questions, feel free to ask anyone around, and when you feel you're ready, come back to me for training. I've mastered as much as any &lt;class&gt; here in the Valley and can pass that knowledge on to you... for a price.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3082] = {title = "Etched Tablet", objective = "Speak to Jen'shan in the Valley of Trials.", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.", progress = "Jen'shan see a mighty <class> before her and da spirits approve.\n\nDa path of da <class> is one of our oldest walks of life. Da Horde turned to us when they be just strugglin' to survive on Azeroth, and they ask us to teach them, to show them the secrets of many tings. They were strong already: strong in shaman ways; strong in warrior ways. But the <class> path not be their path... then.", completion = "Now we teach them those things, and they teach us others. We become one race... almost. We be allies for long time now. So you remember to help them. And Jen'shan remember to help you.\n\nJen'shan teach you da ways of the &lt;class&gt;--teach you good. You never forget, &lt;class&gt;'s be respected greatly by da tribe. You be havin' a large role to play in da future... you never forget that.\n\nWhen you feel da need, come to Jen'shan. She teach you as much as she can when she feel you ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3083] = {title = "Encrypted Tablet", objective = "Read the Encrypted Tablet and speak to Rwag in the Valley of Trials.", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", progress = "Welcome to the Valley of Trials, <name>. You wouldn't be here if you hadn't gotten my tablet, so I will get to the point.\n\nI am Rwag and I am responsible for training the rogues, thieves, and cutpurses here in the Valley. I'm the one the Hand will turn to if you're not ready for what's to come. But don't worry, the Hand won't be controlling everything you do, but it would be wise to work with them if they have need of your talents.", completion = "Until such time comes, you'll be under my tutelage. I will show you the ropes as some folks say. Whenever you feel prepared, come to me and I will see about training you further. Until then, practice your skills and keep them honed to a razor's edge. You'll never know when you'll need even the most insignificant ability.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3084] = {title = "Rune-Inscribed Tablet", objective = "Speak to Shikrik in the Valley of Trials.", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", progress = "Ah, welcome, <name>. I'm pleased you have arrived. My days have become long and even busy what with so many students to teach, but the coming of one of your ilk brings me a great sense of accomplishment--I remember the days when I was taught by one of your shamans.", completion = "As you probably know, the elements give us our power. Fire, earth, water and air--these are our tools.\n\nOur strength comes from the spirits of our ancestors. We are the leaders of our people. Like Thrall is to the Horde, so shall we be to the villages and towns we visit. They will look to us for wisdom and protection. To be better prepared, you must train often. When you feel you've gained more power, come to me and I shall teach you what I can.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3085] = {title = "Hallowed Tablet", objective = "Read the Hallowed Tablet and speak to Ken'jai outside the Den in the Valley of Trials.", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the priest trainer Ken'jai. He would have words with you when you're ready.", progress = "So ya made it... good good! Da spirits tol' me you be comin' to see Ken'jai soon enough. Let me be one o' da first to welcome ya to da Valley of Trials. Dis place not be your home fer long, but while it is, why dontcha make da best o' it.", completion = "As ya test yeself, ya'll find ya have better an' better control o'er da spirits--ya'll be callin' on dem fer greata an' greata tings...  dat's where ol' Ken'jai come in. You come talk to ole Ken'jai when ya feel yer ready. If da spirits agree, den we see 'bout teachin' ya more powerful abilities... but only if da spirits agree.\n\nGo now, talk to da rest of da Valley's people. Speak to me again later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3086] = {title = "Glyphic Tablet", objective = "Read the Glyphic Tablet and speak with Mai'ah near the entrance to the Den in the Valley of Trials.", description = "Ah, while you were gone a tablet came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the mage trainer Mai'ah. She would have words with you when you're ready.", progress = "Ya look to please Mai'ah already, <name>. Dat be good. You give Mai'ah respect, and Mai'ah maybe give you respect back. But enough o' dat, you be here to learn 'bout magic, not hear Mai'ah talk.\n\nThere be only one ting Mai'ah can no teach you 'bout magic, <name>, and dat's how to stop da corruptin'.", completion = "You be among da most powerful beings on da planet, &lt;name&gt;... there no arguin' dat. And everyone know it... know it good, too!\n\nBut ya must be weary! 'cause it not orc, or elf, or dwarf dat you should be scared of... it be da tings you can'na see. Magic be powerful. Make you do tings you may not want to do. Make ya tink you more powerful then you really be. Be patient. Be smart.\n\nWhen ya tink you be ready for trainin', come back to Mai'ah. She teach you what you ready to learn, no problem.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3087] = {title = "Etched Parchment", objective = "Read the Etched Parchment and speak to Jen'shan in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the hunter trainer Jen'shan. She would have words with you when you're ready.", progress = "Ah, so you come at last. Good. Jen'shan be waitin' for you.\n\nMany tink it be an easy path, but Jen'shan tell you dat not true. Mastering da beasts of Durotar and beyond take as much skill as masterin' the arcane arts or speakin' to our ancestors.\n\nFirin' a bow or rifle may not be as dangerous to you as castin' a spell, but it sure be as dangerous to your enemy.", completion = "When we finish speakin', you should talk to da rest of da citizens in da Valley. They ask you to do tings for them... tings that will test your skill and teach you some of da dangers of this land.\n\nAs you grow in experience and wisdom, you be needin' Jen'shan to show you better techniques and skills. Come back to Jen'shan often. I will let you know what I can teach you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3088] = {title = "Encrypted Parchment", objective = "Read the Encrypted Parchment and speak to Rwag in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the rogue trainer Rwag. He would have words with you when you're ready.", progress = "Shhh, not so loud. I don't trust Nartok over there. Anyone that has to hide deeper in a cave than I do shouldn't be trifled with.\n\nI trust you had no problem finding your way around?", completion = "Now that you know where I'm holding up, I should let you know: the Shattered Hand's asked me to look out for you. They want me to train you and keep you informed of anything they might need. Even if you're not interested in helping them yet--which you'd be a fool not to be--I'll do what I can to train you... for a small fee. Come back to me anytime you think you're ready, and we'll see what you're ready to learn.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3089] = {title = "Rune-Inscribed Parchment", objective = "Read the Rune-Inscribed Parchment and speak to Shikrik in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nRead it when you have time. If I'm not mistaken, it came from the shaman trainer Shikrik. She would have words with you when you're ready.", progress = "So, you've arrived. I was beginning to wonder when you would show yourself. I sent the parchment some time ago--I wasn't sure if it had arrived.\n\nBut enough chatter... you're here because you have been chosen, chosen to lead the spiritual lives of our people.", completion = "You will be the conduit in which our ancestors communicate. You will have the power of the elements at your beck and call. Sundering your enemies will be child's play; healing your allies as easy as breathing. Keep these things in mind as you face new challenges, and come back to me as often as you'd like. I will remain here to teach you new spells and set you on the correct path when you are ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3090] = {title = "Tainted Parchment", objective = "Read the Tainted Parchment and speak to Nartok inside the Den in the Valley of Trials.", description = "Ah, while you were gone a parchment came for you, <name>.\n\nI usually avoid dealing with warlocks if I can help it, but I think you should read it when you have time. If I'm not mistaken, it came from your newly-appointed trainer Nartok. He would have words with you when you're ready.", progress = "Finally, you've arrived... and discretely also. Good.\n\nOur world is full of fools, <name>. Even the mighty Thrall has greater flaws than most can see. He turns his back on the power needed to make this land ours completely! We're not the same people who were manipulated and used by creatures from the Nether. We are our own people. We are proud... and we are strong.", completion = "And now you've joined our ranks also. Don't misunderstand, &lt;name&gt;. Just because you have access to power that many will be jealous of, it does not mean you will be accepted easily. Thrall allows our kind into Orgrimmar because we are still his fellow kin--he cannot turn his back on us, or we would become as pathetic as the humans who enslaved him. My point is: be careful. You can be powerful, but if you are foolish, then you are as good dead.\n\nIf you need training in spells then return to me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3091] = {title = "Simple Note", objective = "Read the Simple Note and speak to Harutt Thunderhorn in Camp Narache.", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the warrior trainer Harutt. If this note is from Harutt, I wouldn't take long in reading it's contents.", progress = "Ah, at last, you've arrived, <class>. I did not lie in my note, <name>. We are a special breed also, not unlike the druids or shamans of our tribe. You are just as important. We are the ones called upon to defend our borders, to hunt the centaur, and to go to war.", completion = "Each of us plays a role in our tribe. Each of us must also go through all the same rites. Do not ever let your pride tell you otherwise.\n\nI remain here to train new warriors that seek the glory of battle and who follow the ways of our oldest ancestors. When you feel ready, come back to me and I will do what I can to train you further. Go with the tribe's blessing, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3092] = {title = "Etched Note", objective = "Read the Etched Note and speak to Lanka Farshot in Red Cloud Mesa.", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the hunter trainer Lanka. If this note is from Lanka, I wouldn't take long in reading it's contents.", progress = "Welcome to Camp Narache, <name>. I hear good things about you. Your bloodline is strong, and many of the elders consider you skilled already. But that we will test.\n\nThe plains of Mulgore will be your home for sometime--you should do your best to learn it very well. One day you will travel to unfamiliar lands to master greater skills. You must be ready.", completion = "And it is my job to make sure you are prepared by teaching you the basics of our profession--how to tame your pet, how to fire your rifle, and many other skills that will become necessary.\n\nHunters are a strong part of our tradition and history, &lt;name&gt;. You would do well to remember how important you are to the tribe. You will be respected and revered if you serve our people well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3093] = {title = "Rune-Inscribed Note", objective = "Read the Rune-Inscribed Note and speak to Meela Dawnstrider in Camp Narache.", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the shaman trainer Meela. If this note is from Meela, I wouldn't take long in reading it's contents.", progress = "As quickly as water falls from the sky, here you are before me. I am pleased by your haste. It means you realize both the importance of our meeting and you being here. I am no leader, but I do understand the elements, and I can speak to the spirits of our people. I will teach you to do the same.", completion = "We will meet many times in the days to come. Each time you will hopefully leave my company a little more powerful... a little more prepared. Like the Eternal Flame, your spirit will burn bright and hot.\n\nGo now, &lt;name&gt;. Go and test yourself. I will be here for you when you need.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3094] = {title = "Verdant Note", objective = "Read the Verdant Note and speak to Gart Mistrunner in Camp Narache.", description = "Just a moment ago a messenger was looking for you, <name>. I believe she was sent by the druid trainer Gart. If this note is from Gart, I wouldn't take long in reading its contents.", progress = "You have arrived. This is good. Our ancestors' spirits have become restless throughout Mulgore and beyond, but I cannot tell why. It will forever be your duty to learn to listen to nature's spirits, and act as their avatar. Be mindful of that.", completion = "Though we share a common bond, do not expect much welcome from the night elves. Their pride still limits their sight, but that is none of our concern. The teachings of the Earthmother are all you must concern yourself with, and I will teach you what I know as you grow in wisdom.\n\nReturn to me often, &lt;name&gt;. You will find that the Earthmother grants incredible abilities to those who are most dedicated.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3095] = {title = "Simple Scroll", objective = "Read the Simple Scroll and speak to Dannal Stern in Deathknell.", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warrior trainer Dannal. I would take some time to read it before heading out again.", progress = "Ah, so you've arrived. Good. I overheard that a few others were able to escape \"death\" and were heading into town. Perhaps that resilience will pay off in the future also.\n\nYou may thank Sylvanas for your freedom... freedom of mind and body. Though you still remain tortured by the plague and its effects, you are now free to come and go as you see fit.", completion = "I will be here to train you as you grow in experience... find me as often as you like. I charge a minimal fee, but you'll find everything I can teach you to be worthwhile.\n\nGo now and test your skill. Many more things will become known to you as you gain experience, some of which I am unable to discuss with you here. Just know that Sylvanas will need warriors with your type of strength in the future. You will be the backbone of our salvation. Do not forget it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3096] = {title = "Encrypted Scroll", objective = "Read the Encrypted Scroll and speak to David Trias in Deathknell.", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the rogue trainer David Trias. I would take some time to read it before heading out again.", progress = "So you've made it? Good, we'll have need of more rogues as time goes on. The Shadowstalkers will probably wind up finding you when they think the time's right, so don't go and slip up or do anything you might regret. They need talented agents... not pickpockets and fools.", completion = "I spend most of my time here in the inn keeping an eye out for new faces and just keeping tabs on up-and-coming prospects. Keep your nose clean and I'll do what I can to teach you a few things. Just come back to me whenever you want, and we'll see if you're ready for a new skill or two.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3097] = {title = "Hallowed Scroll", objective = "Read the Hallowed Scroll and speak to Dark Cleric Duesten in the church in Deathknell.", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the priest trainer Duesten. I would take some time to read it before heading out again.", progress = "Ah, so between fire, plague, rioting, and much worse, one more of the \"faithful\" comes to my door. Well, let me bid you welcome, <class>. And allow me a moment to explain a thing or two before you decide it's time for you to seek whatever drives you forward: the Holy Light no longer concerns you, the spirits of your forefathers are fairy tales, and creatures from the Nether don't want you.\n\nDo you understand me so far?", completion = "There is only one thing you must know: we have survived through will alone. It is faith in ourselves that separates us from others, and with our powers, we will cause great change in all of Azeroth. The weak will come to lean on you. The lepers will call you Lord. And the ignorant will look to you for guidance. It is my duty to make sure you have the necessary tools so when the time comes, you are prepared. As you grow in experience, seek me out. I will teach you greater powers if you are ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3098] = {title = "Glyphic Scroll", objective = "Read the Glyphic Scroll and speak to Isabella in the church in Deathknell.", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the mage trainer Isabella. I would take some time to read it before heading out again.", progress = "I knew you would come to me, <name>. Not because you do not have the will to follow your own path, but because we are kindred spirits. We both have felt pain. We have both suffered. And now we want the power to take back what we know is ours: this land, our lives, our destinies. But there is much for you to learn still.", completion = "You must return to me often if you are to become powerful enough to destroy those who would oppose us. The rules of magic still apply to you, &lt;name&gt;. You will still find corruption follows you like hungry wolves in the night. You will find its caress is not unlike an addiction, an old lover still wanting to be by your side. But these things can be staved off. These things will only control you if you allow them to.\n\nGo now, return to me when you've grown more powerful.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3099] = {title = "Tainted Scroll", objective = "Read the Tainted Scroll and speak to Maximillion in Deathknell.", description = "Ah, while you were off dealing with the mindless Scourge, this scroll arrived for you. I would think it's some matter of importance as it seems it bears the seal of the warlock trainer Maximillion. I would take some time to read it before heading out again.", progress = "I bid you welcome, brother. I knew you would come. It was only a matter of time.\n\nWhat I said interested you, didn't it? I hit a chord... something inside you knew what I claimed was truth. Good.\n\nKnow this though: I am no traitor to Sylvanas. If anything, she would appreciate my claims considering it was her own beliefs that has put the Forsaken in the position it is now.", completion = "I mentioned a slave still being a slave, no matter the master. Do you remember? We both know that it is that type of control--that type of power--that now drives us. We seek to have creatures serve us. We know we are more powerful and deserve more respect than others give us ... and so now we look to take it.\n\nI will be your ally in this struggle--the struggle for our own freedom. Freedom to seek our own allegiances. When you feel ready, return to me and I will teach you all I know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3100] = {title = "Simple Letter", objective = "Read the Simple Letter and speak to Llane Beshere in Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Llane, our local warrior trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, you got my letter, <name>... good.\n\nThere's been an influx of warriors in Elwynn recently--which is good for Stormwind, but bad for the kobolds and Defias in the area.", completion = "Get yourself squared away, learn the layout of the land, and come back to me whenever you need training. I'll be here night or day.\n\nThe Knights of the Silver Hand have done well in making this place fairly safe, but as you meet the other citizens, I think you'll find they all have problems they could use some help with--help a &lt;class&gt; can give them. Good luck.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3101] = {title = "Consecrated Letter", objective = "Read the Consecrated Letter and speak to Brother Sammuel in Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Brother Sammuel, our local paladin trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Finally! We meet face to face, brother to brother. I welcome you to Northshire. This will be your home for a short time while you learn the ins and outs of how things are done, but know that Stormwind is not far off, and sooner or later, your path will take you there. But until then, be patient... Knight of the Silver Hand.", completion = "In the meantime, you should know one or two other things. You are a symbol to many here in this land--act accordingly. The Holy Light shines within you, and it will be obvious to both your allies and your enemies.\n\nAlso, as you gain in wisdom and power, you will need to train to learn new abilities. That's where I come in. When you feel you've gained some experience here in Northshire, come back to me and I will teach you what I feel you are ready to learn. Good luck... &lt;class&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3102] = {title = "Encrypted Letter", objective = "Read the Encrypted Letter and speak to Jorik Kerridan in the stable behind Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Jorik, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "You made it here in one piece, and it doesn't look like too many people saw you. Good enough for me. I don't like to have much attention drawn to me back here... nice and quiet. I'm sure you can understand.\n\nHave any trouble yet? I'm glad to hear not. That'll change soon enough.", completion = "You're gonna find a number of outfits that covet our skills, &lt;name&gt;. Adventurers, SI:7... heck, even the Defias Brotherhood wouldn't mind a spy or two inside Stormwind. But you remember this, you're your own man. Don't let nobody bully you into doing something you don't wanna do! Besides, we hold all the cards... at least, we do before the game's done. Know what I mean?\n\nAnyway, just wanted to introduce myself and let you know that I'm here if you need any training. Come by anytime.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3103] = {title = "Hallowed Letter", objective = "Read the Hallowed Letter and speak to Priestess Anetta in Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Priestess Anetta, our local priest trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, at last you've come. I knew you would find your way to me. The Holy Light shines upon you, and the path you've chosen. These times are harsh--the Burning Legion still has a presence upon Azeroth, the entirety of Kalimdor seeks new ways to defend itself from its own tribulations, and it is up to you to aid as many as you can.", completion = "As you grow in experience, return to me and I will do what I can to impart my knowledge upon you. Until then, go with compassion in your heart, and let wisdom be your guide. Remember, the world only becomes a better place if you make it so.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3104] = {title = "Glyphic Letter", objective = "Read the Glyphic Letter and speak to Khelden Bremen inside Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Khelden, our local mage trainer. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Hello, <name>. I am Khelden. Is there something I can do for you?", completion = "Haha, I knew my note would not dissuade you from your path. So, you're prepared then, are you? Prepared to accept your fate? Prepared to challenge the gods and any other forces that stand before you in the pursuit of knowledge and power?\n\nI will not lie, &lt;name&gt;, you will be feared as much as respected. But also know this, I will be here for you when you need training. Simply seek me out as you grow more powerful.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3105] = {title = "Tainted Letter", objective = "Read the Tainted Letter and speak to Drusilla La Salle next to Northshire Abbey.", description = "I was asked to bring this to your attention as soon as you returned from the kobold camps, <name>. It appears to be a letter sealed with the insignia of Drusilla, one of our local trainers. I wouldn't hesitate to read it before you go about any other business here in the Abbey.", progress = "Ah, so you've arrived, and not a moment too soon, <name>. Some of the guards were over here a moment ago and were giving me curious looks... pathetic mundanes.", completion = "As you grow in power, you will be tempted--you must always remember to control yourself. I will not lie--corruption can come to any practitioner of the arcane; especially one who deals with creatures from the Twisting Nether. Be patient, and be prudent... but do not let that repress your ambition.\n\nAs you grow more powerful, return to me and I will teach you more about our ways.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3106] = {title = "Simple Rune", objective = "Read the Simple Rune and speak to Thran Khorman in Coldridge Valley.", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Blast it's cold today, ain't it? It's like the snow never goes away, <name>.\n\nYou've probably noticed already, but there are gnomes now living in our city. That's because they went and got themselves blown out of their own home. Don't go spreadin' this 'round, but I can hardly blame them--I think I woulda resorted to explosives too if Ironforge were infested with Dark Irons or the like.", completion = "Other things you'll probably see too, just so yer in the know: dwarves usin' magic in a fight 'stead of a rifle. Some of us takin' to worshippin' the Holy Light like some of the humans, and, last but not least, troggs. You'll learn more 'bout them later, but what you need to know now is that I'm here to help ya.\n\nI be here to teach ya how to be a real &lt;class&gt;. Anytime ya think ya need more trainin', come back to me and I'll see what I can do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3107] = {title = "Consecrated Rune", objective = "Read the Consecrated Rune and speak to Bromos Grummner in Coldridge Valley.", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the paladin trainer Bromos. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "So, you've made it! And not a second too soon. There's much to be done in Coldridge Valley and beyond. I'm gonna need your help as much as you're gonna need mine!\n\nYou're a Knight of the Silver Hand now, be ready to play the part.", completion = "The humans have taught us a great deal about the Holy Light and how important their order is to them... and to protecting all of Azeroth. We have a great respect for how it is steeped in tradition, and how just one figure, one sacrifice, can make the difference between pain and salvation.\n\nThe two of us are gonna be working together for a bit. Any time you think you're ready, come back to me and we'll see about getting you some training. Can't have you go out into the world unprepared, now, can we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3108] = {title = "Etched Rune", objective = "Read the Etched Rune and speak to Thorgas Grimson in Coldridge Valley.", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the hunter trainer Thorgas. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Ya made it! Good to hear! Betcha didn't have to track me to find the place either. Haha!\n\nOur profession is pretty steeped in tradition, <name>. Learning the ways of the land. Learning to track a bear through the mountains. Even just surviving on wits alone takes a great deal of courage and cunning. Think you're capable?", completion = "One thing you should always remember is that you gotta respect the world you're livin' in. The beasts that choose to fight along side you; the shine of your weapon; the weight of your ammo; the bite of a bitter wind; all these things you need to know intimately.\n\nI'll do what I can to help you, but most of the work's up to you. Anytime you think you're ready, come back and talk to me. I'll train you when I can.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3109] = {title = "Encrypted Rune", objective = "Read the Encrypted Rune and speak to Solm Hargrin in Coldridge Valley.", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "You made it! Great!\n\nWe've got an influx of activity lately, so I'm glad to count another of the Ironforge clan among our numbers. Nothin' like a cold blade in your hand and a shadow to keep you one step ahead, and if you're here, you know exactly what I mean!", completion = "Anyway, as you start peekin' around Coldridge you'll probably have need of training at some point. You just come back to me whenever you feel you need it and I'll teach you what I know--a trick here, a maneuver there. You know, the stuff that keeps you alive and makin' a little extra coin.\n\nKeep an eye out on our gnomish friends too... they kinda got the short end of the stick what with Gnomeregan being... destroyed. They'll need our help to feel welcome.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3110] = {title = "Hallowed Rune", objective = "Read the Hallowed Rune and speak to Branstock Khalder in Anvilmar.", description = "While you were helping me out, this rune was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the priest trainer Branstock. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Ach! Ya made it, <name>! Wonderful!\n\nI was gonna say, I was about to lose faith that ye'd arrive at all... get it, lose faith? It's a joke, lad... aww, nevermind. Ya didn't come here for me bad jokes anyway.", completion = "I'm the one who can train ya as you start to find your way around Coldridge Valley. When ya feel yer ready, come back to me and we'll see about maybe teaching you a new spell or two to fend off the valley from them blasted troggs.\n\nYa got the Light on yer side, along with all of Ironforge, &lt;name&gt;... no pressure on ya to become somethin' special.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3112] = {title = "Simple Memorandum", objective = "Read the Simple Memorandum and speak to Thran Khorman in Coldridge Valley.", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warrior trainer Thran. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Ah, well, another memorandum from a <race> on a mission... isn't this quaint.\n\nNo, no, I ain't teasin' ya, little one. Gotta respect your tenacity, that much is fer sure. I'd be just as peeved if Ironforge was taken by Dark Iron dwarves, so don't be thinkin' I don't feel for your plight...", completion = "Well, seein' how this is your prime directive, or whatever yer callin' it these days, I gave my word I'd do whatever I can to make sure you and yours were ready to take back your home... and that's just what I'm gonna do.\n\nAny time you feel yer ready, come back to good ol' Thran and I'll be happy to share my knowledge wit ya. There's some cost to me trainin' ya, but it won't be too expensive. Good luck.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3113] = {title = "Encrypted Memorandum", objective = "Read the Encrypted Memorandum and speak to Solm Hargrin in Coldridge Valley.", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the rogue trainer Solm. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Glad to see you got my note and came over. Sorry about pretendin' it was a memorandum from your higher-ups... no offense intended. I just knew the two of us, along with others of our kind, gotta stick together.\n\nNot many think it's the best thing in the world to have your kind and my kind holed up in the same city, but I think we can work things out just fine. What do you think?", completion = "I pretty much keep to myself around here so we don't get a bad rap for things gone missing, but if you need anything, some training or somethin', just come back anytime.\n\nYou and me got an understandin'. We know when it comes down to it you can only trust family... and that's just what we got going on here, isn't it? Regardless of Gnomeregan being... overrun, and whatever else is thrown our way, we got one another to back each other up. Right?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3114] = {title = "Glyphic Memorandum", objective = "Read the Glyphic Memorandum and speak to Marryk Nurribit inside Anvilmar above Coldridge Valley.", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the mage trainer Marryk. Take a gander at it and go find him inside Anvilmar when you've a chance.", progress = "Yeah, what's that, <race>? Speak up, if you don't mind. I don't hear so good after a few ales.", completion = "Oh, yeah! Arcane Arts... of course.\n\nHere's what you need to know, &lt;name&gt;: Don't get into too much trouble. Save some coin to buy me an ale... or any spells ya might want. And stay the heck away from Gnomeregan. Other than that, have a good day! I'll be here if you need me or want to train... or whatever.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3115] = {title = "Tainted Memorandum", objective = "Read the Tainted Memorandum and speak to Alamar Grimm inside Anvilmar above Coldridge Valley.", description = "While you were helping me out, this memorandum was given to me to pass on to you. Take some time to read it when you have a chance. I'm thinkin' it came from the warlock trainer Alamar. Take a gander at it and go find him inside Anvilmar when you've a chance.\n\nAnd watch yerself, <name>, your kind ain't too trusted 'round these parts.", progress = "Wonderful! You got my memorandum obviously.\n\nIgnore the fools around you, <name>. The Holy Light?! The sword and shield?! These aren't paths for ones as open minded as us. Look at what \"normal\" magic did to our home. Coupled with  those damned tinkerers, our race almost became extinct. And now we have to rely on the dwarves-- they'd rather spend time allying with humans than help us rebuild our own home. We're like second-class citizens. Have you seen the way they look at us?", completion = "But none of that matters. What matters is that you've seen your own Holy Light! You know where power truly comes from. You realize that having our own allies is much more... prudent. Special allies. Allies that, no matter the task, will obey till their last breath.\n\nAnd that's where I come in, &lt;name&gt;. I can train you in the beginnings of those special powers. Seek me out often and I will do what I can to teach you more spells.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3116] = {title = "Simple Sigil", objective = "Read the Simple Sigil and speak to Alyissia in Shadowglen.", description = "This sigil was given to me by a messenger from our warrior trainer, Alyissia. It seems Alyissia would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "You made it. I'm so glad.\n\nMuch has happened over the last few years, <name>: the creation of Teldrassil, the corruption of many of the forest creatures here and abroad, discovery of lands we thought lost to us like Feralas... so much, in so little time. But those are just some of the reasons we are here, the most important being to protect our kind from further evil.", completion = "Soon you will see others from different races in the boughs of our home--do not let it cause any prejudice within you. They are welcome. They will aid us when they can. Not all of them will be altruistic, but they should be granted some amount of trust.\n\nBut none of this matters now. Now we must focus on you, and how you can aid our people. I am here for that very purpose. I will train you in the ways of a &lt;class&gt; as you become stronger. Return to me whenever you wish and I will do what I can to aid you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3117] = {title = "Etched Sigil", objective = "Read the Etched Sigil and speak to Ayanna Everstride at the top of Aldrassil in Shadowglen.", description = "This sigil was given to me by a messenger from our hunter trainer, Ayanna. It seems Ayanna would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "You've arrived, and none too soon, <name>. Welcome to Shadowglen.\n\nI trust my sigil found you in good spirits and health?\n\nAs I said previously, I am here to train you as a <class>; to tame beasts to aid you in battle; to use a bow with unerring accuracy; to respect the lands which we call home and also the lands beyond.", completion = "As you experience what Shadowglen has to teach you, come see me--I will be able to help you understand more about your role as a &lt;class&gt; and what you are capable of.\n\nThese are dangerous times, &lt;name&gt;, do not take for granted the skill of your pets--there are things in this world more dangerous than you can imagine. Go with Elune and return to me again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3118] = {title = "Encrypted Sigil", objective = "Read the Encrypted Sigil and speak to Frahun Shadewhisper in Shadowglen.", description = "This sigil was given to me by a messenger from our rogue trainer, Frahun. It seems Frahun would have words with you when you have a moment. Read it and bring it to him afterwards.", progress = "Hello, <name>. I'm glad you found me. I was thinking that perhaps you got lost on the way here.\n\nNothing really new has happened in Shadowglen since I sent you my sigil, but I'll leave all the information gathering to you. Speak to the rest of the people around Aldrassil if you'd like.", completion = "Until then, know that our kind are needed more than ever in this tenuous time. Peace with the other races can fail at any moment, and there is much talk about members of the Horde looking to sow even greater seeds of distrust. Remember that.\n\nAs you gain in power and feel more prepared, come back to me here and I will see about getting you some training. It's important that you know how to handle your weapon of choice, among other things.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3119] = {title = "Hallowed Sigil", objective = "Read the Hallowed Sigil and speak to Shanda in Aldrassil.", description = "This sigil was given to me by a messenger from our priest trainer, Shanda. It seems Shanda would have words with you when you have a moment. Read it and bring it to her afterwards.", progress = "It pleases me to see you've arrived so quickly, <name>. Welcome.\n\nAs you've probably heard, all of Teldrassil is stirring with the comings and goings of travelers. Even members of the Alliance have even been allowed access onto Teldrassil's boughs in order to meet with other Kaldorei who prepare for the adventures ahead.", completion = "Do not concern yourself with the world below Teldrassil for now. There will be time for that later. Go now and speak to the others in Shadowglen--they can tell you more about what events have transpired. Help them in any way you can, and anytime you feel you need more training, come back to me and I will teach you what I can.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3120] = {title = "Verdant Sigil", objective = "Read the Verdant Sigil and speak to Mardant Strongoak, in the tree Aldrassil in Shadowglen.", description = "This sigil was given to me by a messenger from our druid trainer, Mardant. It seems Mardant would have words with you when you have a moment. Read it and bring it to him afterwards.", progress = "Ah, young <class>. I see you're eager to continue your studies. Good.\n\nI wonder, have you spent much time in the Emerald Dream already? Perhaps you're not prepared for that yet... In time, I'm sure.\n\nBut until then, we should discuss other matters.", completion = "I will be your mentor and guide for now. It is my duty to teach you how to interpret not only what the spirits communicate to us, but also the complexities and secrets of the Emerald Dream.\n\nAs you learn and grow in power, you will learn more of our sleeping trance. But until then, return to me as often as you like and I will teach you what I can in the ways of our kind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3121] = {title = "A Strange Request", objective = "Take the Shrunken Head to Neeru Fireblade in Orgrimmar.", description = "Neeru Fireblade in Orgrimmar has what I need to get started here! He has mixed up a concoction that I need for my... well, you'll see.\n\nOff with you now -- to Orgrimmar. Here, take this with you. It's a shrunken head that I promised Neeru in exchange for the herbs. It's the head of some poor dwarf I ventured across in the forest. I'm sure Neeru will be pleased.\n\nYou'll find Neeru in the Cleft of Shadow.", progress = "Yes?", completion = "I have been waiting for Uzer'i to deliver this...\n\nLet me give you the herb mixture I prepared for his... well, experiments...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3122] = {title = "Return to Witch Doctor Uzer'i", objective = "Deliver Neeru's Herb Pouch to Witch Doctor Uzer'i in Feralas.", description = "Here are the herbs, <name>. Take them to Witch Doctor Uzer'i.\n\nPlease let him know that I am satisfied with the shrunken head.", progress = "Have you spoken to Neeru?", completion = "This is just what I need to prepare the muisek vessel, &lt;name&gt;.  Soon we will see if my latest incantations prove to be as powerful as I had hoped.\n\nPlease, a moment. I must perform the ritual and apply the herbs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3123] = {title = "Testing the Vessel", objective = "Travel to the Hinterlands, and locate the Wildkin. Kill 10, and use the Muisek Vessel to shrink and capture the fallen Wildkin.\n\nBring 10 Wildkin Muiseks and the Muisek Vessel to Witch Doctor Uzer'i in Feralas.", description = "This will be a test; both of the ritual I performed, and of your abilities. Take this vessel, <name>. With it, you will have the power to shrink and capture a creature inside of it.\n\nTravel to the Hinterlands and look for creatures known as Wildkin that were once pets of the night elf goddess Elune. The vicious, primitive, or savage owlbeasts are your targets, <name>. Kill 10, and use the muisek vessel to shrink and capture them before their spirits can escape.", progress = "Were you able to capture the wildkin?\n\nIf you succeed, we will be ready to shrink and capture the muisek of creatures of Feralas.", completion = "Upon a violent death, the muisek of a creature may escape and seek revenge. Shrinking the creatures, as you did, &lt;name&gt;, prevents the muisek from escaping. Now we may use it as we please!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3124] = {title = "Hippogryph Muisek", objective = "Kill 10 Frayfeather Hippogryphs of any type, then use the Muisek Vessel to shrink and capture them.", description = "Since you have proven that you are both trustworthy and gifted with the ability to use the muisek vessel, I now wish you to capture another creature.\n\nHippogryphs have been loyal companions to the night elves for many years; their spirits are loyal and steadfast.\n\nYour task is to kill 10 frayfeather hippogryphs, and quickly, shrink and capture them with the vessel, so that their muisek may be preserved. You will find the hippogryphs in the High Wilderness, to the south of here.", progress = "Were you able to capture the hippogryphs?", completion = "After killing an animal, if we allowed the muisek to escape, it may take the form of an even greater creature. We would never be safe from its vengeance.\n\nThis is a dangerous job I have given you, &lt;name&gt;. Again, you have completed it well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3125] = {title = "Faerie Dragon Muisek", objective = "Kill 8 Sprite Darters or Sprite Dragons. Use the Muisek Vessel to shrink and capture the fallen Faerie Dragons.", description = "<name>, next I must have you capture a creature that in appearance, may look quite fragile, yet its powerful spirit is what we are truly after. The faerie dragons that I speak of have served the night elves as their allies. We must capture one so that the horde may benefit from this strength of spirit as well.\n\nHere is the muisek, <name>. Kill 8 sprite darters or sprite dragons, and capture their muisek. They may be found to the west of here.", progress = "Were you able to capture the muisek of the faerie dragons?", completion = "Thank you, &lt;name&gt;. Now the spiritual powers of the faerie dragon will be available to us.\n\nI hope you willing to perform another task for me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3126] = {title = "Treant Muisek", objective = "Kill 3 Wandering Forest Walkers. Use the Muisek Vessel to shrink and capture the fallen Treants.", description = "The wandering forest walkers that can be found meandering through the forest are our next target, <name>. Night elves have enlisted treants as allies to fight against the horde. Their movement may be slow, but their role as protectors is undeniable.\n\nSoon we will be able to use this power for our own benefit.\n\nFind 3 wandering forest walkers; kill them, and use the muisek vessel to shrink and capture them.", progress = "Were you able to capture the wandering forest walkers?", completion = "Thank you, &lt;name&gt;. Our muisek collection is almost complete.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3127] = {title = "Mountain Giant Muisek", objective = "Kill 7 Land Walkers or Cliff Giants. Use the Muisek Vessel to shrink and capture the fallen Mountain Giants.", description = "The last task I will require of you is to travel to the northwest and find the final enemy.\n\nThe mountain giants left the mountains to aid the night elves when the burning legion appeared in the world. You will know them by their massive size and the way the ground begins to shake as you travel along their rocky terrain.\n\nI am eager to harness power of that size. Kill 7 mountain giants, then use the muisek vessel to capture their powerful muisek.", progress = "Were you able to capture the mountain giants?", completion = "Just imagine the possibilities of what we now possess, &lt;name&gt;. Along with the materials that you have collected, I will be able to forever trap the muisek of these creatures into whatever I wish.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3128] = {title = "Natural Materials", objective = "Bring 2 Splintered Logs, 6 Encrusted Minerals, 20 pieces of Resilient Sinew, and 40 Metallic Fragments to Witch Doctor Uzer'i in Camp Mojache.", description = "I will need certain materials to complete my endeavor... You may do this alongside the other tasks I will give you.\n\nI'll need a splintered log from a treant of Feralas. Encrusted minerals, these can be found on the mountain giants and faerie dragons to the west. Also, find me some resilient sinew from the owlbeasts of the Hinterlands or hippogryphs of Feralas. Finally, I'll need a large amount of metallic fragments from any of these creatures I mentioned.", progress = "Were you able to collect the materials I need?", completion = "Excellent! These materials, combined with the muisek, should yield just the results we've been wanting.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3129] = {title = "Weapons of Spirit", objective = "Witch Doctor Uzer'i wants you to wait for a moment while he prepares the weapons.", description = "Imbuing the muisek into the weapons is a difficult process. Now that I have all of the required materials and the muisek of the creatures that you captured, I may begin. Please wait; I will return in a moment.", progress = nil, completion = "As promised, you have your choice, &lt;name&gt;. The muisek of the creatures has been forever sealed into the power of these weapons.\n\nYou may now wield their energy as your own. Use it well.", rewards = "You will be able to choose one of these rewards:\n\nForce of the HippogryphSpirit of the Faerie DragonStrength of the TreantWill of the Mountain Giant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3130] = {title = "Against the Hatecrest", objective = "Report to Latronicus Moonspear in Feathermoon Stronghold.", description = "At this point, I am going to direct you to my second, Latronicus.  He's been keeping a close eye on the naga forces to date.  I'll assess the general situation here in regards to the naga; as much as I want to commit a full force to move against them, leaving the stronghold open to direct attack from the Horde - or worse - seems less than optimal.\n\nAnyway, Latronicus awaits.  Good work thus far, <name>.  Keep it up.\n\nYou're dismissed.", progress = nil, completion = "Excellent, &lt;name&gt; - I value a \"can do\" attitude in those who I work with.\n\nI've been tasked by General Feathermoon to address the naga in a direct manner.  My plans are two fold: one, we will weaken their forces both in number and in command, and two, we will uncover what they are up to in the ruins.  With your help, we'll counter the naga presence without sacrificing the general security of the stronghold.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3141] = {title = "Loramus", objective = "Listen to Loramus Thalipedes tell his story.", description = "So you wish to battle demons? You would do well to listen to my tale.", progress = "Do not interrupt me, <race>.", completion = "So be it...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3161] = {title = "Gahz'ridian", objective = "Marvon Rivetseeker in Tanaris wants you to collect 30 Gahz'ridian Ornaments.", description = "<name>, I'm a scientist, but also a treasure hunter at heart!\n\nLong ago, when trolls used to occupy this land, they created large amounts of ornaments modeled after Gahz'rilla, a hydra they worshipped as a deity. These ornaments are carved out of an element that I call \"Gahz'ridian,\" after the hydra god.\n\nI did find some myself, but I'd like to have some more to study -- maybe you can find some?\n\nI even invented a detector that makes finding the Gahz'ridian a snap! Just put it on, and the search begins!", progress = "Are you having any trouble?\n\nYou can find Gahz'ridian just about anywhere in Tanaris, <name>, so keep looking!", completion = "Perfect; these ornaments are perfect for my studies. Thanks so much for the help, &lt;name&gt;.\n\nOh, can I get my helmet back?", rewards = "You will be able to choose one of these rewards:\n\nSurveyor's TunicStaff of Lore\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3181] = {title = "The Horn of the Beast", objective = "Take Margol's Gigantic Horn to Mountaineer Pebblebitty.", description = "The gigantic horn has numerous scratches and cracks. An unusual metal object is lodged into the rough surface.\n\nUpon further examination, you notice that the metal is actually a broken axe head. On the metal, the following words are etched:\n\nProperty of Mountaineer Pebblebitty.\n\nWhen you try and dislodge the broken axe head, it shatters into a million pieces.\n\nWoops!", progress = "No, I will not open the gate.", completion = "What have you got there? A fake obviously!\n\nI've been face to face with Margol and I know for a fact that her horn is at least eight times larger than the one you've got in your hands, &lt;name&gt;. You probably got that off of a stormsnout in the Barrens. No sir, you can't fool Pebblebitty!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3182] = {title = "Proof of Deed", objective = "Take Margol's Gigantic Horn to Curator Thorius in Ironforge.", description = "You expect me to believe a story like that? The real horn would have had my broken axe head still lodged into its surface.\n\nListen, take that obvious fake to Curator Thorius in Ironforge. If he can validate your claim, you will receive a proof of deed. Bring that proof back to me and I'll give you the key to the Searing Gorge.\n\nGet going!", progress = "Why hello there young man. Would you like a tour of the museum?", completion = "What's this?\n\nOh my, I don't believe it! Do you realize what you've got here, &lt;race&gt;? This is the horn of Margol the Rager! Margol, the bane of every archaeologist that ever set foot in the Searing Gorge.\n\nMay I keep it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3201] = {title = "At Last!", objective = "Take the Proof of Deed back to Mountaineer Pebblebitty.", description = "I can't believe Pebblebitty doubted the authenticity of the horn. Between you and me, I think she's just jealous. I know she really wanted to kill that beast herself, what with the 'incident' and all.\n\nSo you need a proof of deed? After the contribution you just made to the museum, it won't be a problem.\n\n<Curator Thorius begins to fill out a large document.>\n\nThere we go! You can take that back to Pebblebitty.", progress = "I don't believe it.", completion = "I don't know how someone as weak as you overcame Margol, but a deal is a deal. Here is the key.\n\nIf anything happens to you after this, it will be your own fault.", rewards = "You will receive:\n\nKey to Searing Gorge"}
MultiLanguageQuestData['en'][3221] = {title = "Speak with Renferrel", objective = "Speak with Apothecary Renferrel at the Sepulcher.", description = "While you were out helping our deathstalkers, Apothecary Renferrel sent you a summons.  He did not give me details, but he wanted to speak with you about the wolf hearts you had given him.", progress = nil, completion = "Ah, very good.  There is a matter regarding the wolf hearts you brought to me earlier that demands our attention.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3261] = {title = "Jorn Skyseer", objective = "Speak with Jorn Skyseer at Camp Taurajo.", description = "Your time with me is over, <name>.  To learn more, you must go to Camp Taurajo to the south and speak with Jorn Skyseer.  He will continue your guidance.", progress = nil, completion = "Greetings, young one.  You are here to walk the hunter's path?\n\nVery good.  Let us begin.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3281] = {title = "Stolen Silver", objective = "Bring the Stolen Silver to Gazrog in the Crossroads.", description = "You may have killed the raptors, but the silver they stole must be recovered!  I have reports that the raptors have a large grouping of nests south of Ratchet, known as the Raptor Grounds.  It is likely that they brought our stolen silver there.\n\nGo to this raptor haven and search for the stolen silver.  When you find it, return it to me.", progress = "Do you have the silver?", completion = "Aha!  So the raptors did hide the silver at their lair.  It's hard to believe these beasts would have the desire for silver.  Perhaps the stories of their intelligence are not as far from the mark as I thought!\n\nThank you, &lt;name&gt;.  Take this as a reward for your service to us, and know that the guards of the crossroads owe their next month's pay to you.", rewards = "You will be able to choose one of these rewards:\n\nRambling BootsSettler's Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3301] = {title = "Mura Runetotem", objective = "Speak with Mura Runetotem in the Sepulcher.", description = "My clanmate, Mura Runetotem, traveled to Silverpine so that she might aid our undead allies.  Silverpine is an ailing forest, a dying forest, and it was Mura's hope to bring it new life.  Perhaps the strange life found here in the Barrens can help her work in Silverpine.\n\nTake a sample of the shells you gathered, and bring it to Mura in Silverpine.  She is staying at the Sepulcher.  With luck, studying the shell will give her the insight she needs to heal that dying place.", progress = "I can smell the dust of the Barrens on you, <class>.  You have traveled far.", completion = "Ah, what is this?  This shell has an inner glow, as if it still pulses with life.  Amazing!  I must study it further.\n\nThank you, &lt;name&gt;.  With luck, this shell will hold a secret I can use to aid the poor land of Silverpine.", rewards = "You will be able to choose one of these rewards:\n\nJackseed BeltSower's Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3321] = {title = "Did You Lose This?", objective = "Wait for Trenton to finish his work.", description = "You have done much for the Order, <name>. The sheer dedication it takes to get this far would have turned away any ordinary person. There is no doubt in my mind, or in the mind of Galvan, that you are one of us.\n\nWhich is why I think you deserve a little reward. It is nothing really, just a trinket. You may be familiar with its properties, as I do believe it is what brought you to us in the first place.", progress = "Today we finalize our celebration of your commitment to the Order.", completion = "Rise and be recognized, &lt;name&gt;, blacksmith of the Mithril Order.", rewards = "You will receive:\n\nGlimmering Mithril Insignia"}
MultiLanguageQuestData['en'][3341] = {title = "Bring the End", objective = "Andrew Brownell wants you to kill Amnennar the Coldbringer and return his skull.", description = "In the Barrens lies a horrid mess of tangled vines called Razorfen Downs. While our first observations of this place revealed little threat, our recent findings are much more serious...\n\nThe quilboar of Razorfen Downs have aligned themselves with the Scourge. A Lich named Amnennar the Coldbringer rules them now, using the power of his massive consciousness to control their every move.\n\nAmnennar has a direct telepathic link to Ner'zhul; we must sever this bond, <name>. An end must come to the Coldbringer.", progress = "This matter is of utmost importance, <name>. We must stop any attempt by the Scourge to bolster their ranks.", completion = "The loyalty of a Lich is unswerving, &lt;name&gt;. Let them know that such loyalty will only bring them destruction.", rewards = "You will receive:\n\nVanquisher's SwordAmberglow Talisman"}
MultiLanguageQuestData['en'][3361] = {title = "A Refugee's Quandary", objective = "Bring Felix's Box, Felix's Chest and Felix's Bucket of Bolts to Felix Whindlebolt in Anvilmar.", description = "We drove the troggs out of Gnomeregan, but then it all went so horribly wrong!  Now our home is completely irradiated, and we gnomes have been scattered all over Dun Morogh.\n\nIn my haste to get away from the radiation, I lost all my personal belongings and tools.  It was the trolls that got them.  They stole my chest, my box, and my bucket of bolts!  They took them back to their camps southwest of Anvilmar.\n\nI'm no adventurer - could you find my things and bring them here to me, please?", progress = "Oh goodness <name>, this town is not well suited for the likes of me.  There are as many nasty creatures here as there were in Gnomeregan before the accident!\n\nDo you have my belongings?  If you don't, then who knows what the trolls have done with them now...", completion = "Huzzah, you've found them!  You're an absolute savior, my friend.  Here, it's not much, but it's something for the trouble I've put you through!  Thank you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3362] = {title = "Thistleshrub Valley", objective = "Tran'rek in Gadgetzan wants you to kill 8 Gnarled Thistleshrubs and 8 Thistleshrub Rootshapers.", description = "Have you ever seen Thistleshrub Valley? It's a mighty dangerous place, <name>.\n\nThose strange beasts there, I don't trust them for a minute! Gnarled thistleshrubs and thistleshrub rootshapers, that's what I think they were called...\n\nAnyhow, I want to get into the valley, but with so many of those thistleshrubs around, there's no way I'm going back there. But here's where you come in -- if you clear some of them out, I just might think about going back. What do you think, <name>? Help me out?", progress = nil, completion = "They're that big? I might have to rethink my plan...\n\nBut you did hold up your end of the bargain, so here's what I promised.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3363] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][3364] = {title = "Scalding Mornbrew Delivery", objective = "Take a Scalding Mornbrew to Durnan Furcutter inside Anvilmar before it gets cold in five minutes!", description = "Gah!  I was supposed to get this delicious scalding mornbrew to Durnan Furcutter inside Anvilmar a while ago now, but I had to deliver one to Grelin here first.  I'll never make it to Anvilmar before the brew runs cold!\n\nYou look fast.  Maybe you can make it.  This cup will only stay hot for five more minutes, and Durnan didn't order \"chilly\" mornbrew, so get going.  Anvilmar is to the northeast, a settlement dug into the mountain.\n\nThanks, <name>, and don't forget to bring me back my mug!", progress = "Aye, I'm Durnan Furcutter.  You have something for me?", completion = "Ah good, now this will hit the spot.  Allow me to take a small break while I enjoy this scalding mornbrew!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3365] = {title = "Bring Back the Mug", objective = "Return Nori's Mug to Nori Pridedrift.", description = "Now that hit the spot!  Nothing like a piping hot - nay, SCALDING mornbrew on a cold winter's day to warm your cackles of yer soul.\n\nHere ya go <name> - be a pal and take this empty mug back to Nori for me, would ya now.", progress = "I trust the scalding mornbrew got to Durnan on time!  Did you remember to bring me back my mug?", completion = "Excellent, &lt;name&gt;!  You'd be surprised how many couriers I meet who forget to do something as simple as bring back the mug.  Mugs don't grow on trees, or so they tell me!\n\nHere's a little something for the effort.  Thanks again for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3366] = {title = "The Glowing Shard", objective = "Travel to Ratchet to find the meaning behind the Nightmare Shard.", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3367] = {title = "Suntara Stones", objective = "Help Dorius get back to Ironforge.", description = "<Dorius groans.>\n\nI'm badly injured, <race>. Feel... light headed... World spinning... Bleeding... internally.\n\nI must get back to Ironforge. Help me, <name>.", progress = "I'm not going to make it...", completion = "This letter was dropped by Dorius when he was shot.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3368] = {title = "Suntara Stones", objective = "Take the Singed Letter to Thorius in Ironforge. He is in the Hall of Explorers.", description = "Brother,\n\nIf you are reading this letter, I am no more. How it got to you, I do not know, but thank and reward the ones responsible.\n\nAbout the stones: They exist and the Dark Irons have them in their possession. Their leader, Lathoric the Black, is using the power of the stones to enslave my excavation team. They were taken to the cauldron. Their minds are twisted, working night and day to complete something called Obsidion.\n\nHelp them, brother. It is the final wish of a dead man.\n\n-Dorius", progress = "<Thorius sobs.>", completion = "&lt;Thorius wipes his face dry.&gt;\n\nIn the name of the Light, he will have his wish. This I vow.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3369] = {title = "In Nightmares", objective = "Bring the Nightmare Shard to Hamuul Runetotem on Elder Rise.", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, <name>, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can.\n\nHamuul Runetotem on Elder Rise is who you need to find. Head to Thunder Bluff. I cannot say more.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n&lt;Hamuul peers into the shard&gt;\n\nOh... I didn't... Well.\n\n&lt;name&gt;, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that you should not concern yourself with.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again.", rewards = "You will be able to choose one of these rewards:\n\nTalbar MantleQuagmire Galoshes\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3370] = {title = "In Nightmares", objective = "Bring the Nightmare Shard to Mathrengyl Bearwalker in Darnassus.", description = "This shard holds great secrets; it is the pure essence of the Emerald Dream. However, what I see in this shard is not a dream; one would call this sort of a vision a nightmare.\n\nI do not wish to alarm you, <name>, but I think it is best if you deliver this shard into the hands of a wise druid as soon as you can... \n\nMathrengyl Bearwalker in the Cenarion Circle is who you need to find. Head to Darnassus. I cannot say more.", progress = "May I help you with something?", completion = "Falla sent you to me? Well now, let's see that shard that you say she was so hesitant to talk about...\n\n&lt;Mathrengyl peers into the shard&gt;\n\nOh... I didn't... Well.\n\n&lt;name&gt;, thank you for delivering this to me. It isn't wise to speak of things such as this, though, I advise you. These are matters that the Cenarion druids alone must attend to.\n\nLet's just say that things in the Emerald Dream are not as we thought...\n\nPerhaps in the future, our paths may cross again.", rewards = "You will be able to choose one of these rewards:\n\nTalbar MantleQuagmire Galoshes\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3371] = {title = "Dwarven Justice", objective = "Return to the Searing Gorge and find Dorius's archaeology unit.", description = "There is an empty, vacuous hole, where my heart used to be, <name>. The loss of Dorius is not one that I will soon recover from. I must see his final wish through - the perpetrators of this cold blooded murder must be brought to justice.\n\nReturn to the Searing Gorge and fulfill his last request: Free his men. The Dark Iron dwarves force their slaves to work in a sweltering mine called the Slag Pits. Search there for Dorius' men.", progress = nil, completion = "Forget about me, help the others.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3372] = {title = "Release Them", objective = "Find the Mysterious Artifact being guarded by the Twilight's Hammer Idolaters in the northwest quadrant of the Searing Gorge and bring it to the Altar of Suntara in the Slag Pit.", description = "Release them, <race>. Even after their bodies give out, the power of the Suntara forces them to complete their tasks.\n\nThe altar of Suntara is the key. Go northwest; in the hills above the cave... Twilight's Hammer guard a relic. Retrieve it and place it on the altar of Suntara.\n\n<The dying archaeologist collapses.>", progress = "The altar is empty.", completion = "You place the mysterious artifact on the altar of Suntara.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3373] = {title = "The Essence of Eranikus", objective = "Place the Essence of Eranikus in the Essence Font located in this lair in the Sunken Temple.", description = "As you touch the gem, a deep voice resonates in your mind.\n\n\"Mortal, heed this plea.  I am Eranikus of the Green Dragonflight, keeper of this accursed temple.  My charge to ensure that the trolls never again bring forth their abomination of a god has for now ended in failure.  As I imbue this gem with part of my essence, I sense my grip on the Dream twisting into chaos.  Please - place this gem into the essence font in my lair, and let our magic there purge the taint from my psyche so that I may rest.\"", progress = "As you near the essence font that Eranikus told you of, his voice once again touches your mind.\n\n\"Yes mortal, this essence font will redeem what untainted element of my psyche remains imbued in this gem.  Place the gem inside the font, and let the magic of the Green Dragonflight cleanse the corruption and taint from my being.  Only then will I find true release, and only then will the Dragonflight be able to reassert their stewardship over the Atal'ai.\"", completion = "You place the gem inside the essence font.\n\n\"Thank you mortal, you have - no... this, this cannot be! No!  The corruption of this accursed god even taints the sanctity of a Green Dragonflight essence font!  No please, I feel my essence ripping from me!  THE PAIN!  I feel the grip of an eternal nightmare taking hold on me...\"\n\n\"Mortal, I implore you!  Find one of the Green Dragonflight to stop this... help me... I am chained in darkness... forever in agony... please do not torture...\"", rewards = "You will receive:\n\nChained Essence of Eranikus"}
MultiLanguageQuestData['en'][3374] = {title = "The Essence of Eranikus", objective = "Bring the Oathstone of Ysera's Dragonflight and the Chained Essence of Eranikus to Itharius in the Swamp of Sorrows. It is there that you will make your choice to aid Ysera's Dragonflight or not.", description = "You engage the Oathstone, and Itharius speaks directly to your mind through the stone.\n\n\"By accepting the charge placed in this Oathstone, you agree to aid my cause and the cause of Ysera's Dragonflight in redeeming the corrupted soul of Eranikus.  The first sacrifice, one of many you and I will no doubt make, will be to relinquish the gem to me that has chained what free-willed part of Eranikus' psyche remains.\"\n\n\"Do this <name>, and we will work together to redeem a soul worthy of redemption.\"", progress = "Here we are <name>, at yet another crossroads.  The time has come to make another choice.  What choice do you make, mortal?", completion = "You have made your choice, and so it begins.  Your choices have been, to date, what I would consider to be the correct ones; your actions and deeds henceforth will determine whether this is to continue.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3375] = {title = "Replacement Phial", objective = "Bring a Mana Potion, Coal, and Sweet Nectar to Talvash del Kissel in Ironforge to get a replacement for Talvash's Phial of Scrying.", description = "Um... you need another phial of scrying?  You're kidding, right?  What did you do with the first one?!  We have a lot of work ahead of us here, <race>.  Those phials don't grow on trees!  Actually, I wish they did, because I'd go there and pick one off since I don't have another one!!\n\nin order to make you one, I need the following: a mana potion, a piece of coal, and some sweet nectar.  Don't ask why, just bring me what I ask and I'll make you a new one.", progress = "To make another phial I need a mana potion, a piece of coal, and some sweet nectar.\n\nThat, and a whole lotta patience apparently.", completion = "The mighty adventurer delivers.  Hooray for me.  By the way, I lied - I had another phial.  Ungh, take it.\n\nWell, what did you expect?!  \"Oh, here, have another one!  I'm just some goofball who has nothing better to do than hand out magical communication devices to adventurers!\"  Rest assured though, what you have given to me will be enough make you another phial when you lose that too.\n\nPlease prove me wrong and don't lose the new one, okay?", rewards = "You will receive:\n\nTalvash's Phial of Scrying"}
MultiLanguageQuestData['en'][3376] = {title = "Break Sharptusk!", objective = "Bring the head of Chief Sharptusk Thornmantle to Brave Windfeather in Red Cloud Mesa.", description = "<name> - I have heard of you, newcomer.  Perhaps it is you that will help us, where others have failed.\n\nWe tauren have carved a home out of this land, but not without a cost.  The Bristleback quilboars of Brambleblade Ravine, led by Chief Sharptusk Thornmantle, have made our lives difficult with their continued war against us.  I charge you to bring me the chief's head!\n\nHe will be found in the ravine to the east in their makeshift village.", progress = "Sharptusk will trouble us no more once you have brought me proof of his death.  It is his head that I seek, <name>.\n\nWe <race> live for the hunt, and there is no greater hunt than against one that is cunning enough to perhaps hunt us back.  If you are successful in this task, young one, you will start to learn what I mean.", completion = "Justice has been served on this day by your swift actions, &lt;name&gt;.  Let this deed serve as a warning to all who would threaten our home.\n\nYou have earned this reward to help you on your sojourn, young &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nPainted Chain LeggingsNomadic Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3377] = {title = "Prayer to Elune", objective = "Hear Zamael tell his tale.", description = "Will you assist me, mortal? Hear my tale.", progress = "Allow me to finish my story.", completion = "I have accepted my fate here in this cage, but the prayer must be found.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3378] = {title = "Prayer to Elune", objective = "Find the Prayer to Elune and take it to Astarii Starseeker in Darnassus.", description = "Will you assist me, mortal? Will you find the prayer to Elune?\n\nAs I stated, the prayer was etched onto a golden tablet. One of these idol worshipping scoundrels must have it on their person.\n\nIf you do recover my prayer, take it to Astarii Starseeker in Darnassus. It matters little that my faith has been rekindled after the countless malevolent actions that I have taken against this world and its inhabitants, but my prayer must be heard. Absolution is the last thing I expect.", progress = "What brings you to the Temple of the Moon, <name>?", completion = "Elune smiles upon you this eve, &lt;name&gt;. You have returned a lost soul to her. Please accept this as a token of our gratitude.", rewards = "You will be able to choose one of these rewards:\n\nKaylari ShouldersRunesteel Vambraces\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3379] = {title = "Shadoweaver", objective = "Kill the group of Shadow Silk Poachers that wander the Searing Gorge. Nilith has reason to believe that there are five of them that need to be exterminated. Return to Nilith in the Searing Gorge when this task is complete.", description = "The spiders of the Searing Gorge are an invaluable source of shadow silk. As you know, shadow silk is highly sought after by the artisans of our trade.\n\nRecently, a group of poachers has encroached upon these lands, carelessly slaying spiders en masse without so much as a thought as to the long term effect of their actions. The first task I ask of you, then, is a simple one: Find them... and end them.\n\nBegin your search to the north.\n\nIf you require assistance, speak with Raze.", progress = "What information do you have?", completion = "Excellent work, &lt;name&gt;.\n\nI am sure that this is a piece of shadoweave that you have not yet seen.", rewards = "You will receive:\n\nShadowy Bracers"}
MultiLanguageQuestData['en'][3380] = {title = "The Sunken Temple", objective = "Find Marvon Rivetseeker in Tanaris.", description = "There are restless spirits in this world, <name>. There are spirits that have been tainted by their isolation, bound to an ancient evil...\n\nI have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. He has studied many ancient areas of the world, and was last known to have left his home in Ratchet to study the troll ruins in Tanaris.", progress = nil, completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3381] = {title = "A Meeting with the Master", objective = "Bring 2 Undamaged Hippogryph Feathers to Sanath Lim-yo in Azshara if you wish to speak to his master.", description = "Ah, a young <race> come to speak to Sanath. What a wonderful day! I am so honored to have you grace me with your presence. Thank you!\n\nPlease... do not be so arrogant to assume my sarcasm was a compliment. Let us get one thing straight: I don't like you. But this little conversation doesn't have anything to do with us--it has to do with my master.\n\nBring me a couple hippogryph feathers for my arrows and I'll give you leave to see him. He's asked that I send adventurers to him if they proved worthy enough.The following spell will be cast on you:\n\n", progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nTeleport to Azshara Tower\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][3382] = {title = "A Crew Under Fire", objective = "Defend Captain Vanessa Beltis, her crew and the Horizon Scout's passengers against the naga attack. Captain Vanessa Beltis must survive.", description = "We were just off the coast looking for a safe haven to make anchor. The sun hadn't been down for more than an hour when they attacked... those damned naga!\n\nI'm not sure what they were looking for, but it's clear they didn't find it--they've already come back once. A couple of my scouts are on watch at the entrance of the valley to give us fair warning when the next attack comes.\n\nI'm sorry you've come along now, <name>, but it's out of my hands.\n\nAre you ready for the fight of your life?", progress = "This is going to be a tough battle...", completion = "You've done it! Thank you! Surely this was one of the most brutal battles I've ever taken part in. I can't thank you enough.\n\nI only wish more of my crew could have lived through this trial.\n\nI would ask you to speak to any surviving passengers from the Horizon Scout. Some of them had business in the area, and may have a request or two of you if you're willing. Again, thank you for all your help.", rewards = nil}
MultiLanguageQuestData['en'][3385] = {title = "The Undermarket", objective = "Slay Trade Master Kovic and his minion Clunk. Retrieve the Trader's Satchel from his corpse and return it to Nilith.", description = "They call themselves the Undermarket: Cutthroat traders that will sell, move, trade and do just about anything for the right price.\n\nIt gets worse, <name>. They have set up a base of operations here in the Searing Gorge. Trade Master Kovic is heading up the operation and has close ties with the Dark Iron dwarves of the region.\n\nWe must strike hard and send a message to their leadership. Slay Trade Master Kovic and his minion Clunk. Bring back his trader's satchel when the job is done.\n\nTo the Cauldron!", progress = "The Trade Master still lives?", completion = "You have struck a decisive blow against the Undermarket. Their leaders will think twice before sending more cronies into the gorge.\n\nOh, and I also found nothing of use in the trader's satchel. You may keep whatever you find inside.", rewards = "You will receive:\n\nShadowy BeltKovic's Trading Satchel"}
MultiLanguageQuestData['en'][3402] = {title = "The Undermarket", objective = "Speak with Vizzklick in Gadgetzan.", description = "I want you to personally deliver the news of Kovic's defeat to Vizzklick in Gadgetzan. He will be so happy to hear that Kovic is dead that I'm certain he'll give you some grand reward.", progress = nil, completion = "Kovic slain??! This is a glorious day, &lt;name&gt;! For years that scoundrel has been running shady undermarket trades, undercutting honest, hard working traders all over the world.\n\nYou deserve a fine reward for this accomplishment! And a fine reward you shall have!", rewards = "You will receive:\n\nPattern: Shadoweave Mask"}
MultiLanguageQuestData['en'][3421] = {title = "Return Trip", objective = "I will return you to Sanath's camp now.\n\nDo not mind his bad manners--he is rude to everyone save for the master. Perhaps he shall learn his lesson one day.", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nTeleport from Azshara Tower"}
MultiLanguageQuestData['en'][3441] = {title = "Divine Retribution", objective = "Listen as Velarok Windblade tells his story.", description = "Hear my tale, adventurer.", progress = "Allow me to finish mo... <race>.", completion = "Have you heard enough? Are you prepared to act?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3442] = {title = "The Flawless Flame", objective = "Collect 4 Hearts of Flame and 4 globes of Golem Oil and return the items to Velarok Windblade.", description = "You have made the right decision, <name>.\n\nWe must strike where we will do the most damage: the four sentry towers.\n\nWith the four towers in flames, we can initiate an offensive before they have time to react.\n\nYou will need the proper tool to set the towers ablaze. To make the tool requires some materials.\n\nBring me four hearts of flame and four golem oil and I shall craft the torch of flawless flame.\n\nThe golems and elementals in these lands should be your first target.", progress = "Have you collected the materials?", completion = "Well done, &lt;name&gt;. We are almost ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3443] = {title = "Forging the Shaft", objective = "Bring 8 Thorium Plated Daggers to Velarok Windblade.", description = "To hold the flawless flame, we will need a shaft and a casing. You must first find a suitable shaft.\n\nThe Dark Iron taskmasters and slavers of the cauldron use weapons of enchanted thorium, an extremely sturdy alloy. If you bring me eight thorium plated daggers, I can break the alloy down and reforge a shaft.", progress = "Eight, <name>. I need eight!", completion = "You're an exceptional laborer, &lt;name&gt;. Have you ever considered a change of vocation? Perhaps a detective? Junk collector? Oh, I know, one of those silly gnomes that crawl across the beaches of Azeroth with their metal detecting contraptions, looking for lost treasure. Yes, that would be an ideal position for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3444] = {title = "The Stone Circle", objective = "Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet.", description = "I once entered the foreboding chambers of the Sunken Temple. The evil in that place penetrates all that enter; I barely managed to find my way out, wading through the ooze that now covers the floors. All I can remember is stumbling through a large circular room, filled with serpent statues...\n\nRecently, I discovered a round stone that appeared to have the same serpent symbol imprinted on it. I had it packed up and shipped to my workshop in Ratchet. Retrieve it, and I might be able to tell you more.", progress = "Ratchet is not far from here, <name>. The journey shouldn't take long.", completion = "Yes... This is the stone.\n\nIt's all coming back to me now, &lt;name&gt;...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3445] = {title = "The Sunken Temple", objective = "Find Marvon Rivetseeker in Tanaris.", description = "I have heard of a place that lies deep below the surface of the earth -- banished there by powers greater than I have ever seen.\n\nIf you wish to learn more of this place; the Sunken Temple, seek out a goblin named Marvon Rivetseeker. Much like Troyas and I, he has studied many ancient areas of the world. He was last known to have left his home in Ratchet to study the troll ruins in Tanaris.\n\nGood luck finding him; he hasn't been heard from in some time.", progress = nil, completion = "Yes, the Sunken Temple, I can say that I have seen it with my own eyes. Perhaps you'd like to hear more about it?\n\nYou look like the adventurous type -- I know things that may intrigue you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3446] = {title = "Into the Depths", objective = "Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows.", description = "Inside the temple, I found a circular room with six balconies, each one with a serpent statue on the edge. Curious, I pushed one of them to see what would happen, and it was a trap! I nearly fell to my death from the explosion. Laying there on the ledge, I looked down and noticed that there was another statue at the base of the room; an altar of sorts... Hakkar, I think it was called.\n\nI think that this altar is the secret -- you must bring this token to the altar in the Sunken Temple.", progress = "Upon examining the statue, you notice a depression in its side, just the size of the token that Marvon gave you...", completion = "You push the stone circle into the opening, and you hear it lock into place.\n\nNow that the stone is in place, you may continue... but what should you do next?\n\nPerhaps you should examine this altar further...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3447] = {title = "Secret of the Circle", objective = "Travel into the Sunken Temple and discover the secret hidden in the circle of statues.", description = "My memories are cloudy, but I will tell you what I can. The circle of statues in the Sunken Temple, while dangerous, I believe that they hold the secret to unlock an even greater treasure.\n\nFrom the main altar, I was able to activate a series of lights. I think that if you can uncover what these lights mean, you might be able to unlock whatever secrets are hiding in this room.\n\nI warn you though, <name>. Great evil lies in the temple. It's likely that anything valuable will be fervently guarded...", progress = nil, completion = "The eye of the idol glitters brightly even in the half-darkness of the temple. Its transparency reveals something shiny behind it. Sliding it to the side, you reach in and grasp what lies inside the statue.\n\nThe Atal'ai treasure is now yours.", rewards = "You will receive:\n\nHakkari Urn"}
MultiLanguageQuestData['en'][3448] = {title = "Passing the Burden", objective = "Speak to Tymor in Ironforge.", description = "I've recently been handed the responsibility of investigating Azshara--a once beautiful area the elves called home. This would be back when they practiced magic. It's now a more dangerous place than it is beautiful, but that doesn't stop us from turning over every stone for answers to our past.\n\nA companion of mine named Tymor offered to help me investigate the area since he takes a particular interest in such things.\n\nHe owns a small place to the right of the Hall of Mysteries here in the city.", progress = nil, completion = "Ah, Karnik sent you, did he? I expected to hear from him soon. I've discovered such wonderful things about Azshara.. I know night elves have incredible life spans, but everyone forgets some of the more... unfortunate events in their lives sometimes. That's not meant as a criticism, just an observation.\n\nLong ago, there were cities created by the elves filled with knowledge about magic and other lost arts. Being a student of such things, I started my investigation. What I found was quite thrilling.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3449] = {title = "Arcane Runes", objective = "Using the Drawing Kit, make rubbings of the Rune of Beth'Amara, the Rune of Jin'yael, the Rune of Markri, and the Rune of Sael'hai before heading to the small island off of the southern peninsula of Azshara and signaling Pilot Xiggs Fuselighter to pick them up.", description = "Magic was once as revered as Elune herself to some elves. Some of their most powerful mages created runes and tablets citing rules of the arcane and insights into their findings. They would leave these for all to ponder in public places.\n\nI would very much like rubbings of these runes from the Ruins of Eldarath. I have a kit for you to make the rubbings with, but it will be up to you to find them. Be careful though, the Explorer's League isn't the only one interested in Eldarath.", progress = "Well, well, well, glad to see you made it out here, <name>. Did you get the rubbings for Tymor?\n\nAs dangerous as this place is, there hasn't been too much action along the coast. That might be on account of the naga swimming underwater, but that's not my problem... I patrol the skies.", completion = "Good to see you safe and sound, &lt;name&gt;. I hope things weren't too tough for you.\n\nI'll get these to Tymor right away. He'll be thrilled to take a look at these things.\n\nGo ahead and toss the flare gun... probably won't be any good to you anymore anyway, and I already got a new one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3450] = {title = "An Easy Pickup", objective = "Speak to Xiggs Fuselighter in Ironforge.", description = "I want the rubbings delivered to my tower, but there's no need to have you go all the way there. I'll just have them air-lifted out of Azshara.\n\nXiggs Fuselighter owes me a favor or two and will be in the area soon--he's signed on to patrol the coast. Speak to him before you leave. He can give you a flare gun to signal him with. When you have the rubbings, just head to wherever he tells you and then give them to him so he can get them to my tower safely. He should be in the hangar in the Military Ward.", progress = nil, completion = "What can I do for you, &lt;name&gt;? Kinda busy at the moment preparing my ship for a long trip. I just came over to see some of the tank pilots--I need some wendigo manes to line my cockpit and they usually have extra.\n\nI can give you a minute if you're brief... one of the boys just took off to Steelgrill's Depot to see if the pilots down there have extra manes for me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3451] = {title = "Signal for Pickup", objective = "Speak to Xiggs Fuselighter and get a Standard Issue Flare Gun from him in Ironforge.", description = "Ah, so Tymor sent you, huh? Yeah, I owe him a favor or two. What's that? Why, that little devil. Yeah, I can help him out with that. So you'll need a flare gun and a location... easy enough.\n\nThere's a small island off the southern peninsula of Azshara that we've made a landing pad on. You take this flare gun, and use it there. I'll see your signal and come by to pick up this... whatever it is he wants.", progress = nil, completion = "Here's my standard issue flare gun, and be patient after you fire off the gun--there are only a couple charges in one of these, and it might take me a minute to get to you depending on how far out to sea I am. Just look out to sea after you fire off the flare.", rewards = "You will receive:\n\nStandard Issue Flare Gun"}
MultiLanguageQuestData['en'][3452] = {title = "The Flame's Casing", objective = "Find and return a Symbol of Ragnaros to Velarok Windblade.", description = "We need one final piece to form the torch.\n\nIn the mountains to the northwest you will find a large encampment of Twilight's Hammer. It is rumored that they carry symbols and idols that pay homage to their god. These symbols and idols could carry sufficient enchantment to form a magical casing. Bring me a single symbol of Ragnaros and I will try to extract the magic from the item to create the casing.", progress = "Without a suitable source of arcane energy, the torch of retribution cannot be completed.", completion = "The symbol radiates foul magic; perfectly suited for our task.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3453] = {title = "The Torch of Retribution", objective = "Wait for Velarok Windblade to complete the Torch of Retribution.", description = "Give me a moment to combine the pieces and apply the necessary enchantments.", progress = "Do not interrupt the channeling process.", completion = "There is one final task that you must complete.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3454] = {title = "The Torch of Retribution", objective = "Take the Torch of Retribution.", description = "The torch must now be bound to its owner. Pick up the torch, <name>.", progress = nil, completion = "You grab the torch with both hands; waves of hatred and anger pulse through your being.", rewards = "You will receive:\n\nTorch of Retribution"}
MultiLanguageQuestData['en'][3461] = {title = "Return to Tymor", objective = "Return Tymor's Drawing Kit to him in Ironforge.", description = "Tymor didn't give me anything to pay you with, so I suggest you take it up with him when you get back to Ironforge. I'm sure he'll still be in his place in the Mystic Ward. Just go knockin' and make sure he pays you good. This place ain't no picnic... that's for sure.\n\nThanks again for helping him out though, and good luck.\n\nOh, and I don't need the drawing kit. Why don't you just bring it back to Tymor when you go to see him?", progress = "You're back! Excellent. Do you have my drawing kit also?", completion = "Wonderful! I'm so glad to hear it.\n\nI'm really excited to get to my tower and go over those rubbings. I'm so envious of you... going to a place like Azshara. That's any student of the arcane's dream, I would guess.\n\nWell, we never spoke about any kind of reward since you were just working for the Explorer's League, but you deserve something.", rewards = "You will be able to choose one of these rewards:\n\nSteelsmith GreavesSkullspell Orb\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3462] = {title = "Squire Maltrake", objective = "Speak with Squire Maltrake.", description = "Speak with my envoy, Squire Maltrake. He will further instruct you as to the use of the Torch of Retribution.", progress = nil, completion = "Are you prepared to make your strike?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3463] = {title = "Set Them Ablaze!", objective = "Set the North, South, East, and West Sentry Towers on fire by using the Torch of Retribution inside each of the buildings.", description = "Listen well, <name>. While the four towers can never be destroyed, you can use the torch of retribution to set them ablaze for a very long period of time: A fire that no element or force can subdue.\n\nWhile they are ablaze, no guard or sentry unit can inhabit the watch posts and thus, their first line of defense is nullified.\n\nYou must enter each tower and use the torch of retribution within their fortifications. Beware the lookouts posted by the Dark Irons, <name>.", progress = "Are you lost, <name>?", completion = "It is glorious! Is it not glorious master?", rewards = "You will be able to choose one of these rewards:\n\nDragonflight LeggingsDrakefire HeadguardAxe of the Ebon Drake\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3481] = {title = "Trinkets...", objective = "Open the chest.", description = "The chest appears locked.", progress = nil, completion = "The chest opens at your touch. How much cheese could possibly be in here? There is only one way to find out.", rewards = "You will receive:\n\nHoard of the Black Dragonflight"}
MultiLanguageQuestData['en'][3483] = {title = "Signal for Pickup", objective = "Ah, another flare gun, huh? That I can do.\n\nAnd don't forget, southern tip of Azshara. It's a small little island that's been turned into a landing pad. You can't miss it if you're in the right spot.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nStandard Issue Flare Gun"}
MultiLanguageQuestData['en'][3501] = {title = "Everything Counts In Large Amounts", objective = "Bring Kum'isha Imperfect Draenethyst Fragments and be rewarded for each one you turn in.", description = "Although you may never find a flawless sphere of draenethyst, you will undoubtedly uncover various imperfect fragments of the draenethyst in your exploration of these lands.\n\nWhile it is doubtful that Kum'isha will be able to use the flawed fragments to return home, the pieces may serve other, useful purposes for the draenei.\n\nReturn any piece of flawed draenethyst fragments that you may find and I shall reward you.", progress = "Have you had any luck in your exploration?", completion = "You truly disgust me, &lt;race&gt;. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.", rewards = "You will receive:\n\nKum'isha's Junk"}
MultiLanguageQuestData['en'][3502] = {title = "One Draenei's Junk...", objective = "Bring Kum'isha Imperfect Draenethyst Fragments. Any form of monster in the Blasted Lands could be carrying a fragment.", description = "Well, after that display of voracious greed, I feel nauseous.\n\nRegardless, I shall not dwell too long on your material addiction.\n\nFor each imperfect draenethyst fragment you turn in, I shall reward you with more junk. My junk heap gets smaller while your junk heap gets larger. On Draenor we call this a 'win-win' situation.", progress = "Well? Draenethyst? Remember?\n\n<Kum'isha clenches his fist and knocks on your head.>\n\nIs anybody home?", completion = "You truly disgust me, &lt;race&gt;. A grown man drooling over a pile of junk? Pitiful! Take your reward and get out of my sight.\n\nSounds familiar? It should, because I say it a thousand times per day.\n\nOh how I loathe this world.", rewards = "You will receive:\n\nKum'isha's Junk"}
MultiLanguageQuestData['en'][3503] = {title = "Meeting with the Master", objective = "There was a time when I could ask whatever I wished from those who sought out my master.  But now, you need only ask and I will send you to him.\n\nIt is upsetting to me, but I do not question his orders.  I can only take enjoyment in making fun of the ridiculous clothes you wear or the pathetic look on your face.  Even that bores me...\n\nEven this rambling bores me!  Do you wish to see my master or not?", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nTeleport to Azshara Tower"}
MultiLanguageQuestData['en'][3504] = {title = "Betrayed", objective = "Deliver the Sealed Letter to Ag'tor to Ag'tor Bloodfist in Azshara.", description = "Betraying, thieving elf! That's what I call her--that's all she'll ever be!\n\nI may have made a grave mistake, <name>. I trusted a blood elf. \n\nShe claimed Azshara would hold great riches... powerful items. I simply send some warriors with her to protect her and I would be rewarded. Well, look who's the fool--she's killed them all.\n\nI want vengeance, <name>, but I can't afford to send anyone else. Find Ag'tor at Valormok, north of the Haldarr Encampment. He'll tell you more.", progress = "Ah, Belgrom wizened up and finally sent someone not in his ranks to aid us, did he?\n\nThis camp used to be a dozen warriors strong, <name>, but now they're all dead. That mage, Rimtori, has slain them all. She played Belgrom like a lute... seduced him even. It's none of my business, but between you and I, she is quite the temptress. That's probably why I'm still out here helping Belgrom--I probably would have done the same thing.", completion = "We've sent everything we had at her and her workers, but they are strong in battle. None have bothered to return. I'm assuming some have died, but I'm sure others simply ran... cowards.\n\nBut now that reinforcements have arrived, perhaps there's still something we can do. Perhaps we can still punish her for lying and betraying Belgrom.\n\nWhat do you say, are you in?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3505] = {title = "Betrayed", objective = "Kill 10 Blood Elf Reclaimers, and 10 Blood Elf Surveyors before seeking out Magus Rimtori's camp. Once you've found it, look for something that might be important to her that can be used to draw her into a fight.", description = "I thought as much.\n\nWe start our crusade against her workers along the southern bluffs on the northern peninsula of Azshara. Kill them with bloody rage--let them know they've betrayed the wrong allies.\n\nDo not concern yourself with her yet--she spends most of her time with her bodyguards searching Azshara. It would be prudent after you've slain her workers to find her personal camp. Scouting out where we can attack her would be wise. Perhaps there is something there we can use to provoke her.", progress = "The title of the book is emblazoned on the black leather cover in gold leaf--Kaldorei Tome of Summoning. As you open the pages you can see that the book is very old but in superb condition.\n\nYou assume the text is of some ancient language... perhaps Kaldorei?\n\nYour instincts tell you that you should return here once you've finished doling out retribution on the blood elves for their betrayal.", completion = "You begin to skim some of the pages until you come to a page that's marked by a thin, black strip of silk cloth.\n\nAs you try to decipher the script, you see a diagram on the bottom of one of the pages. A quick look around at the scene before you and you realize that the crystals, the circle, and even some of the other components on the ground are set up in a similar pattern as the diagram.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3506] = {title = "Betrayed", objective = "Destroy the arcane focusing crystal tied to Magus Rimtori and then slay her. Afterwards, take the Head of Magus Rimtori to Ag'tor Bloodfist in Azshara.", description = "A few more moments of thought brings a few ideas to mind, one of which brings a smile to your face: perhaps destroying the crystals would upset the blood elf responsible for the slaughter of so many orcs and the betrayal of Belgrom?\n\nYou continue to decipher more of the script and pictures and realize that one of the crystals is tied to the creator of the circle--the others are tied to something far more sinister.\n\nYou close the book and begin to decide which crystal to destroy.", progress = "How goes your slaughter of the blood elf traitors, <name>? Have you made any progress?\n\nI hope you are the one strong enough to bring that dog to her knees! She deserves nothing but a painful death for all that she has done!", completion = "RAR!! Incredible!\n\nYou've done it! Belgrom will be pleased! Finally the spirits of dozens of our warriors can be at peace. Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3507] = {title = "Betrayed", objective = "Speak to Belgrom Rockmaul in Orgrimmar.", description = "Return to Belgrom in Orgrimmar. He will want to see her head for himself! We'll return there shortly.\n\nAh, this is indeed a good day. Thank you for your help, <name>.", progress = "I remember you, <class>. I asked you to go to Azshara to destroy that wench that betrayed me! That seems like many moons ago. Don't tell me that Ag'tor and the others are dead also!", completion = "HAHA! Look at you now, pathetic woman! I spit on your remains!\n\nThank you, &lt;name&gt;. Thank you from the bottom of my heart! This is indeed a great day!\n\nI would give you a kingdom if it were in my power! But perhaps you will settle for this.\n\n\n\nHaha! Stupid blood elf, look at you now... in a burlap sack and missing your body! You should never have betrayed Belgrom!", rewards = "You will be able to choose one of these rewards:\n\nPyrestone OrbBelgrom's Hammer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3508] = {title = "Breaking the Ward", objective = "Wait for Loramus to complete the enlightenment spell.", description = "You are foolhardy, <name>. It is an admirable quality of your kind - to blindly enter battle when you have little to no chance of success. I will assist you, if only to see just one of Razelikh's minions fall.\n\nTo break the ward placed over Razelikh's subordinates will take time and require the acquisition of rare artifacts.\n\nBe still, I must first perform the enlightenment ritual. The information I gather will assist me in forging weapons of great power.", progress = nil, completion = "The name of the beast must be found.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3509] = {title = "The Name of the Beast", objective = "Speak with Lord Arkkoroc in Azshara. Begin your search at the waters edge to find the Temple of Arkkoran.", description = "There is only one way to harm the demon lord and his minions. A weapon of power must be forged bearing his true name.\n\nWhen such a weapon is forged, the demon and all under his command are vulnerable.\n\nA lesser deity resides in Azshara: Lord Arkkoroc. You must seek him out but be warned, his minions will stop at nothing to destroy you if you are discovered.\n\nUndoubtedly, you will have to pay a price for such information.", progress = nil, completion = "A demon lord?\n\n&lt;Lord Arkkoroc laughs.&gt;\n\nPerhaps the one can assist you with this information; but first, you must assist the one.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3510] = {title = "The Name of the Beast", objective = "Slay Hetaera and bring back Hetaera's Bloodied Head, Hetaera's Beaten Head, and Hetaera's Bruised Head to Lord Arkkoroc.", description = "She kills my children, mortal. She that calls herself the ruler of these oceans. A false god, nothing more. Crush her and bring back all of her heads.\n\nFor that, you will be given the name that you seek and something else of equal importance.\n\nShe roams the clutch... Hetaera she is called.\n\n<Lord Arkkoroc points to the southwest.>\n\nGo!", progress = "<Lord Arkkoroc bends down to inspect you.>\n\nWhere are they?", completion = "Finally, one worthy of the wisdom of Arkkoroc!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3511] = {title = "The Name of the Beast", objective = "Take the temper back to Loramus Thalipedes.", description = "As promised, I will reveal the name of the demon lord, Razelikh the Defiler. First, however, I must prepare something of utmost importance for your journey.\n\nThe weapon you seek to create requires a temper. Give me a moment to drain the blood from these heads.\n\n<Lord Arkkoroc squeezes the heads in between his gigantic fists, draining them of their blood.>\n\nTake the temper back to Loramus along with the name of the beast: Rakh'likh.", progress = "You return! Astounding, <race>. Did you discover the true name?", completion = "The temper will add the necessary vitriol we require for the forging of the weapons. There is but one more step in their creation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3512] = {title = "In Eranikus' Own Words", objective = "Travel to the eastern part of Winterspring and speak with Umbranse the Spiritspeaker.", description = "<name>, our first step will be to devise a method to speak with Eranikus through the gem.  He lies in a precarious state between sleep and death now, twisted within a weave of nightmares.  Though the essence you have given me is badly tainted, there is a chance we can reach him.\n\nTravel far to the icy lands of eastern Winterspring and seek one of our mortal allies, Umbranse the Spiritspeaker.  He is a human medium who speaks for the dead.  Though Eranikus is not truly dead, he may be of aid to us still.", progress = nil, completion = "Itharius was wise to send you to me.  While he is not dead as you understand death, Eranikus will soon give us advice in his own words.  For now though, I cannot directly help you... at least not yet.\n\nI will lend my skill at death-speaking to you, but first I need the help of one who - unlike me - is not limited by the frailties of old age.  My most potent augury device has been taken from me against my will, and unless I have it back we will be at a loss to help Eranikus.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3513] = {title = "The Runed Scroll", objective = "Take the Runed Scroll to the northern guard tower in the Barrens.", description = "The official-looking scroll is wrapped tightly with a silvery ribbon. You're sure someone would be interested in seeing this, but who?\n\nThere is an outpost close to the Ashenvale border to the north, and if the information on this scroll involves the night elves, this would be the place to take it.", progress = "Whaddya got?", completion = "Well now... Where did you find this?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3514] = {title = "Horde Presence", objective = "Kill the leader of the Talon Den, Rynthariel the Keymaster.", description = "This scroll is from that scheming dryad Rynthariel, Keymaster of the Talon Den on Stonetalon Peak.\n\nShe'll not be making any more contact with the messenger you looted this from, heh, but we must stand our ground here. The Horde will not tolerate her outrunners here.\n\n<name>, travel to the Talon Den. Kill Rynthariel, and then put up a symbol for all to see. Take this Horde flag, <name>. Put it up in the Talon Den so that they will not be so rash as to send another messenger through our territory again.", progress = nil, completion = "You're a tough one! Ridding the Den of Rynthariel is a major step, &lt;name&gt;. They will be slow to regroup, and so we can count on less Alliance runners in the Barrens. They will think again before sending another this way.\n\nThank you.", rewards = "You will be able to choose one of these rewards:\n\nTrailblazer BootsJutebraid Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3517] = {title = "Stealing Knowledge", objective = "Find the Tablet of Beth'Amara, the Tablet of Jin'yael, the Tablet of Markri, and the Tablet of Sael'hai before returning to Jediga in Azshara.", description = "I admit, <name>, I've made the most of my situation in Azshara. Belgrom's punishment has had its share of benefits.\n\nBefore I left, I did some research and you would be surprised how many valuable items are lying around.\n\nI'll tell you more about my deals, and even give you a cut of the profits, if you help me gather some of them.\n\nThere are tablets throughout the Ruins of Eldarath to the east that I need. All four are named after Highborne wizards. Get them for me and we'll talk some more.", progress = "The tablets I'm having you gather should bring in a pretty copper or two to the right parties. I'll tell you who we need to deliver them to after you've found them. But I'm no fool... you'll get your share after I have proof that they've been delivered.\n\nSo get to it--we don't have all day. I might have to find someone else to help me.", completion = "Perfect, &lt;name&gt;, and in good condition also. These should get us a good price from all the parties concerned.\n\nLet's not dawdle around here any longer than we have to. We have some money to make.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3518] = {title = "Delivery to Magatha", objective = "Bring the Tablet of Beth'Amara to Magatha in Thunder Bluff.", description = "The first tablet goes to a tauren female... one called Magatha. She is among the elders in Thunder Bluff, and is one of the proponents of the alliance between the tauren and the Forsaken. She, more than anyone among the elders, feels the tauren and their ways can help the Forsaken find a path back to being human.\n\nBring her the Tablet of Beth'Amara. The tablet may be the link she needs in finding a way to help the Forsaken... or so she claims.", progress = "Yes, <name>. What can I do for you? I have many matters I must attend to, so please, be quick.", completion = "Ah, at long last, the Tablet of Beth'Amara. I was wondering if my partnership with Jediga had failed or if the poor orc had found her death in Azshara. I am glad she was successful.\n\nBeth'Amara was one of the Highborne's most influential alchemists. The wizard alone was said to have mastered transmuting metals among other things.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3519] = {title = "A Friend in Need", objective = "Speak to Dirania Silvershine in Shadowglen.", description = "Ughhh... I was bitten very badly by a spider named Githyiss the Vile while exploring the spider cave very close to here. I am sure I have been seriously poisoned; you must help me.\n\nPlease tell Dirania Silvershine. She will be able to help me.\n\nHurry... I'm so dizzy...", progress = nil, completion = "Oh dear; I was wondering why I hadn't seen Iverron yet today. And I've always warned him about those spiders...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3520] = {title = "Screecher Spirits", objective = "Capture the spirits of 3 screechers in Feralas, then return to Yeh'kinya in Steamwheedle Port.", description = "I seek the spirits of the vale screechers of Feralas.  They are the cousins of an old, old god, and their spirits are linked to him.\n\nTake this bramble wand and go to Feralas.  Find and defeat vale screechers in southern and central Feralas, then wave my bramble over their fallen bodies.  This will coax their spirit to reveal itself.  Touch the spirit and collect its essence.\n\nReturn to me with my bramble and with the collected essence, and I will tell you more of the old god of which I spoke.", progress = "Have you collected the essence of the screecher spirits, <name>?", completion = "You have done well, &lt;name&gt;.  Perhaps now it is time to reveal more...\n\nThere is an ancient prophecy among the trolls, where the dead god Hakkar, the Soulflayer, will one day return to this earth.  Some say the coming of Hakkar will bring joy and glory to trollkind, while others believe his resurrection marks the end of all things.\n\nI do not believe this myth, but I do know the essence of Hakkar holds great power, and this power should be kept from those who would abuse it...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3521] = {title = "Iverron's Antidote", objective = "Collect 7 Hyacinth Mushrooms, 4 Moonpetal Lilies, and 1 Webwood Ichor for Dirania Silveshine in Shadowglen.", description = "We may be able to help Iverron, as I know of an antidote that should help with the poison. It requires some ingredients, though, before I can make it.\n\nI'll need Hyacinth mushrooms. You can find these growing under trees, or you may collect them from the grell south of here; they seem to have taken a liking to them. I'll also need Moonpetal lilies, which only grow around watery pools.\n\nThe last ingredient may prove the most difficult. From the very spiders that poisoned Iverron, collect Webwood ichor.", progress = "Please, collect the ingredients, <name>. Iverron needs our help.", completion = "Thank Elune that you have gathered these ingredients so quickly!\n\nIn just a moment, I will have the antidote prepared.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3522] = {title = "Iverron's Antidote", objective = "Bring Iverron's Antidote to Iverron before the time limit is up. Iverron can be found by the cave to the north.", description = "The antidote is ready, <name>. Please see that Iverron drinks it.\n\nThere is something that you should know -- the antidote -- it will only remain viable for 5 minutes. You must get it to him in time.\n\nSpeed be with you, <name>.", progress = "Oh... <name>, I'm so glad you have returned.", completion = "What is this, &lt;name&gt;?\n\nOh, I knew Dirania would be able to help me!\n\n\n\nI'm always getting into trouble and Dirania, well, she always manages to help me out of it.\n\nI am feeling much better, but I think I will sit here for a while longer, until I feel completely better. Well, that, and I was hoping you'd clear a path for me through those vicious Webwood spiders...", rewards = "You will be able to choose one of these rewards:\n\nSedgeweed BritchesBarkmail Vest\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3523] = {title = "Scourge of the Downs", objective = "If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him.", description = "Outstanding!  My name is Belnistrasz, and I thank you for rescuing me.  I had given myself up for dead... or worse, as a meal for these Scourge-infested vermin.  Yes - I said Scourge all right; they've brokered some sort of deal with the Quilboar here, and this nightmare is a result.\n\nListen... rather than just flee, I want to make a difference for all of our sakes.  Would you be up to helping me out to that end?  It's probably dangerous, but you seem to be the type not to worry about that too much.", progress = "I'm not one for politics; I care not if your affiliations are for either Horde or Alliance.  I am more interested in squelching direct and dire threats to all the races... and we have quite a large one in here.\n\nIf you're willing to be a true hero for all people, then hand me the oathstone I have given you as a sign of commitment.  I'm... not from around these parts; an oathstone is important to people of my kind as a bond of agreement.", completion = "Fantastic, I thought you looked to be the heroic type!  We've got our work cut out for us &lt;name&gt;, I'm not going to lie to you.  If we stay focused on the task at hand, we should be able to come out on top.\n\nNow, let me bring you up to speed on what's been going on...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3524] = {title = "Washed Ashore", objective = "Recover Sea Creature Bones from the beached sea creature just south of Auberdine, and then return with it to Gwennyth Bly'Leggonde in Auberdine.", description = "Majestic sea creatures are known to launch themselves at the Darkshore coastline, beached there until they die. Lately, these beasts have been washing ashore in ever-increasing numbers.  I've been sent here by the Temple of the Moon to investigate, but the presence of murlocs along the water has made my research difficult.\n\nThere is a giant creature washed ashore just south of Auberdine that is ringed by the foul Greymist murlocs.  Could you go there and retrieve bones from the creature for our study?", progress = "It is only recently that these creatures started landing on the coast of Darkshore in such alarming numbers.  I can't help but think that this is an ill omen of some sort.  Recovering a sample of that creature's bones to the south would help us in Darnassus assess this situation!", completion = "I hope the murloc did not give you much trouble in collecting this for us!  I will be sure to get this on the next hippogryph to Darnassus.  The Temple of the Moon has given me some funds to hand out for assistance; please have some with our thanks.\n\nYour success here emboldens me to offer you a chance to aid the Temple of the Moon further, if you are interested...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3525] = {title = "Extinguishing the Idol", objective = "Escort Belnistrasz to the Quilboar's idol in Razorfen Downs.\n\nProtect Belnistrasz while he performs the ritual to shut down the idol.", description = "Near the entrance is an idol that functions as a macabre oven for the Quilboar; the beasts... they literally consume their abductees from the Barrens.  I can shut down the idol and bind them from using it again, but I need your aid in doing so.  My plan: escort me to the idol.  Once we arrive, I'll commence the ritual.  I'll barely be able to communicate with you, let alone defend myself.  Protect me while I shut down the idol.  If they take me down, then it's all over for us.\n\nAre you with me?!", progress = nil, completion = "Belnistrasz's sudden departure has left behind a burning brazier.  As you stare in to the flame, the image of a great-winged red dragon fills your mind.  A more graveled version of Belnistrasz's voice speaks directly to you.\n\n\"Indeed mortals, you are the heroes I had hoped you would be.  Thanks to you the butchery these beasts were perpetrating is a thing of the past.  My faith in mortals such as yourself has been once more renewed.  Take this as a reward befitting of a hero.\"", rewards = "You will receive:\n\nDragonclaw Ring"}
MultiLanguageQuestData['en'][3526] = {title = "Goblin Engineering", objective = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n<name>, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well &lt;name&gt;, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked &lt;name&gt;, and you might learn something.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3527] = {title = "The Prophecy of Mosh'aru", objective = "Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris.", description = "The ancient prophecy of Mosh'aru speaks of a way to contain the god Hakkar's essence.  It was written on two tablets and taken to the troll city of Zul'Farrak, west of Gadgetzan.\n\nBring me the Mosh'aru tablets!\n\nThe first tablet is held by the long-dead troll Theka the Martyr.  It is said his persecutors were cursed into scarabs and now scuttle about his shrine.\n\nThe second tablet is held by the hydromancer Velratha, near the sacred pool of Gahz'rilla.\n\nWhen you have the tablets, bring them to me.", progress = "Do you have the tablets of the Prophecy of Mosh'aru, <name>?\n\nWhen I gain the tablets, I will study them, and learn how to contain the essence of Hakkar!", completion = "Ah, this is good.  I can fuse these ancient tablets together, and then study their hidden secrets.\n\nMy debt to you grows, &lt;name&gt;.  And it will grow further still.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3528] = {title = "The God Hakkar", objective = "Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris.", description = "Now it is time to capture the essence of the avatar of Hakkar.\n\nTake the Egg of Hakkar to the Sanctum of the Fallen God in the Sunken Temple in Azeroth.  Invoke the egg's power to stir the dead god.\n\nHe will send his minions against you.  Defeat his bloodrinkers and take their Hakkari blood, then use the blood to dowse the eternal flames that hold Hakkar's spirit.  When all the flames go out, the avatar of Hakkar will enter our world.\n\nDefeat him, and place his essence within the Egg of Hakkar.", progress = "Have you defeated the avatar of Hakkar, <name>?  Has his essence yet empowered the egg I gave you?", completion = "The essence of Hakkar has been collected!  Even now the Egg stirs with life!  Could the myths of Hakkar be true?\n\nThat must not be true, for it is then I fear what Hakkar may do if birthed again.  I will keep this egg safe and be sure it does not fall into evil hands.\n\nYour labors with me are finished, &lt;name&gt;.  You have touched a legend, and your actions may one day change the face of our world.", rewards = "You will be able to choose one of these rewards:\n\nAvenguard HelmLifeforce DirkGemburst Circlet\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3541] = {title = "Delivery to Jes'rimon", objective = "Bring the Tablet of Jin'yael to Jes'rimon in Orgrimmar.", description = "I have a fence in Orgrimmar. He resides in The Drag. He's difficult to nail down if you don't know where to look, but if you go looking in one of the highest buildings there you should have no problem finding him.\n\nDo me a favor though, don't go shouting to all of Kalimdor that he's there and what his business is--it'd be bad for both of us.\n\nHe'll give us more than a fair price for the Tablet of Jin'yael. I'm not sure why, but you should have seen how excited he was to hear about its whereabouts.", progress = "Yes, what you be needin', mon? I got many tings to be takin' care of today, and you not be on me agenda as one of them. Pester me, and I make sure that changes.", completion = "Ahhh, Jediga be sendin' her package all the way from Azshara. Good. I be waitin' on this.\n\nJediga, now that be a fine woman... deadly too. What could be better?\n\nLook at this... the tablet be in perfect condition. You make a good messenger, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3542] = {title = "Delivery to Andron Gant", objective = "Bring the Tablet of Markri to Andron Gant in Undercity.", description = "Andron Gant is my next contact. He usually holds himself up in the Undercity... right near the Apothecarium.\n\nHe was a little more loose-lipped when it came to speaking about what he wanted the Tablet for. Apparently some of the mages of Undercity are looking to study some of the arcane spells the highborne used. They think this tablet will help them. Markri was adept at summoning creatures; especially elementals.\n\nTake the Tablet of Markri and return to me for your part of the reward.", progress = "Well... <hic>... isn't this a surprise? An adventurererere... <hic>!\n\nWhat c'n I do for you... <hic>?", completion = "Here, take some coin... get yerself... &lt;hic&gt;... some new armor or something....\n\nThis'll bring a shiny gold or two to the right... &lt;hic&gt; people.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3561] = {title = "Delivery to Archmage Xylem", objective = "Bring the Tablet of Sael'hai to Archmage Xylem in Azshara.", description = "This final tablet goes to someone very dangerous, <name>. Heed me when I tell you that I trust this person far less than anyone else I've asked you to meet with.\n\nArchmage Xylem has a tower up in the hills overlooking Azshara. He's human, but he acts like no human I've met... or killed. He exudes power, and I dare not ask him what he plans on doing with the tablet.\n\nHe came to me, but told me that his bodyguard Sanath would help me get to the tower when I was ready to meet him. Look north for Sanath.", progress = "What can I help you with, <name>?", completion = "Ah, the Tablet of Sael'hai... how long I've longed to study it.\n\nThank you, &lt;name&gt;. You may tell Jediga that she has done well. This will definitely be worth the payment she asked for.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3562] = {title = "Magatha's Payment to Jediga", objective = "Deliver Magatha's Note to Jediga in Azshara.", description = "Take this note to Jediga. Tell her the payment will be here for her when she returns. And tell her I am pleased with her work.\n\nGo swiftly, <name>. Tell your master I will be awaiting her here.", progress = "Well, what did Magatha say? The old crone... I bet she was less than polite.", completion = "Ah, good. She was much more reasonable than I expected... at least towards you. I half expected her to have you punished for my insolence in sending someone in my place. She must really want that tablet. Interesting.\n\nSomething to ponder another time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3563] = {title = "Jes'rimon's Payment to Jediga", objective = "Deliver Jes'rimon's Note to Jediga in Azshara.", description = "Take this letter to Jediga. Let her know that our deal has been beneficial and I be pleased with her work.\n\nYou tell her she come back to Orgrimmar fast and Jes'rimon make sure he take good care of her.\n\nTell her that, and maybe in the future I have need of your services again, <name>.", progress = "Have you spoken to Jes'rimon yet?\n\nHe's a boar among trolls, but his information is usually accurate and his jobs well paying.\n\nIf you can stand his attitude then you stand to make some good coin from his business endeavors.", completion = "I can see he was more than pleased by the looks of his note.... a little too pleased.\n\nPerhaps some day I'll take time to make sure he knows how much I appreciate his advances also. Well, at least there's one reason to look forward to spending more time in Azshara.\n\nHere's your share of our payment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3564] = {title = "Andron's Payment to Jediga", objective = "Deliver Andron's Note to Jediga in Azshara.", description = "Here... take... <hic> this to Jediga. Good luck to ya!", progress = "Have you met with Andron yet? He rarely leaves Undercity, so I don't think it'd be too hard to find him.", completion = "Perfect... wait a minute.\n\nHaha! What'd you tell him when you delivered the tablet, &lt;name&gt;? He overpaid us way too much! Not that I'm complaining. Did you tell him the deal changed? Or was he drunk again?\n\nDoesn't matter... here, take an extra share also.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3565] = {title = "Xylem's Payment to Jediga", objective = "Deliver Xylem's Note to Jediga in Azshara.", description = "What is it? Oh yes, your payment. Of course.\n\nTake this and be off with you. I'm sure Jediga is awaiting oh so patiently for your return.", progress = "Well, what did Xylem have to say? He didn't do anything to you, did he? Cast a spell on you? Con you into doing work for him?", completion = "No problems? None at all? Well, that's something to be said... I expected him to show some sort of reluctance or to at least betray our deal. Hmm, maybe he can be trusted after all.\n\nWell, no need to dwell on it that much. Here's your share. Thank you for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3566] = {title = "Rise, Obsidion!", objective = "Slay Lathoric the Black and Obsidion, and return to Thorius in Ironforge with the Head of Lathoric the Black and the Heart of Obsidion.", description = "It... It... It was all a trap.\n\nForgive... me.\n\nKill the bastard... Kill him for us... for Thorius.", progress = "I don't believe you! Show me proof!", completion = "&lt;Thorius' face turns white.&gt;\n\nThis... this cannot be. My own brother? He set this all up?\n\n&lt;Thorius' face contorts in anger.&gt;\n\nHe betrayed me, he betrayed Ironforge! It seems as if the influence of the Old Gods is still strong in these lands. I fear that if my brother - a once noble and honorable man - was so easily turned to the will of Ragnaros, no one is safe.", rewards = "You will be able to choose one of these rewards:\n\nCenturion LegplatesLordrec HelmetRing of Fortitude\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3567] = {title = "To the Top", objective = "Would you like to see the view atop one of the twin colossals? I can send you there, <race>.\n\nDo consider how you will get down, though. This is a one way trip only.", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nTwin Colossals Teleport"}
MultiLanguageQuestData['en'][3568] = {title = "Seeping Corruption", objective = "Fill all 4 Empty Vials at the tide pools along the coast of the Ruins of Eldarath in Azshara before returning to Chemist Cuely.", description = "See that tauren behind me--the one who looks like she's going to be ill at any moment? She was in Azshara recently. She claims she was wounded by some naga while making her way through the Ruins of Eldarath.\n\nAfter fighting off a few of them, she took a break on the beach and drank from one of the tide pools. Now she's feeling nauseous... among other things.\n\nI'd like to find out what she drank. Take this box, in it are some empty vials I labeled. Fill each at different pools and come back.", progress = "You know where this is leading, don't you, <name>? There's no way she can survive... look at her. The best thing for her now is to aid us in finding a cure for the plague. This water she drank might have a clue that helps us figure out how. She's going to die anyway--she might as well die doing something noble for our people before she does. Don't you agree?", completion = "Wonderful. You're back before she died. Good, good.\n\nLet's get started on this then, shall we?\n\nI've been studying her symptoms for some time now, and it's quite ugly. I'm surprised she's still standing. She's vomited three or four times all over the place... quite a pleasant odor.\n\nGive me just a moment to put something together to test on our... friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3569] = {title = "Seeping Corruption", objective = "Give Cuely's Elixir to Thersa Windsong in Undercity.", description = "Give this to Thersa. Perhaps it will cure her... perhaps not. We really won't know until after she drinks it.", progress = "I've come to Undercity because I heard their alchemists have been studying long and hard on how to find a cure for their own illness. It was suggested that perhaps they could help me too.\n\nAlthough this place makes me feel far from welcome, I had no choice--the sickness that found me is tearing me up inside and I needed their help immediately.", completion = "Chemist Cuely has been very accommodating... disturbingly so. But if he says this will help me, then I have no other choice. I don't have time to find any other solution. I've already spoken to priests and shamans, none of which could help me.\n\nLet us hope that the Earthmother watches over my spirit.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3570] = {title = "Seeping Corruption", objective = "I never dreamed the elixir would take hold that quickly. Thank you, <name>. I will get to work on the rest of these samples right away. I'm sure they'll be usable by the Lady Sylvanas and the Forsaken soon enough.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3601] = {title = "Kim'jael Indeed!", objective = "Search the Thalassian Base Camp for Kim'jael's Compass, Scope, Stuffed Chicken and Wizzlegoober, then return them to him in Azshara.", description = "Kim'jael indeed!! Do you know what Kim'jael means to the Blood elves, <name>? Little rat... or something like that. The big bullies!\n\nThey hired me to help them scout the area looking for some sort of lost treasures. Of course I jumped aboard the moment they said \"treasure\" and the amount they were willing to pay, but of course, they turned on me and tried to kill me... ME!\n\nGoes to show you, you can't trust a Blood elf.\n\nThe problem is, they still have my equipment and I can't get it back. Help me out?", progress = "Those stinkin' Blood elves. I tell ya, if I was as strong as you are, I'd go down there and teach them a thing or two myself! But I'll have to settle with payin' you to take care of 'em for me.", completion = "Haha! You got them good, didn't you?!\n\nThis is great! That'll teach those Blood elves to betray their partners... especially someone as loyal as a goblin merchant! Bah, Blood elves...!\n\nWell, the least I can do for you is pay you for your time... just like I said I would.\n\nHere you go... those should be useful.", rewards = "You will receive:\n\nM73 Frag Grenade"}
MultiLanguageQuestData['en'][3602] = {title = "Azsharite", objective = "Recover twenty Crystallized Azsharite from southern Azshara. You may use the Felhound to assist you in 'sniffing' out the location of cleverly hidden deposits.\n\nReturn to Loramus when the task is complete.", description = "The ancient cliff giants of the southern region of Azshara consume the rock and buildings of the land for sustenance. The excrement from their consumption is a highly malleable and extremely strong crystal known as Azsharite.\n\nThe formations litter the southern arc, but few are ever recovered due to the extremely violent nature of the giants.\n\nYou are to venture south and recover enough of the Azsharite for the creation of the weapon's body. My felhounds will aid in the recovery of the crystal.", progress = "Evil does not sleep, fool. You will have time for rest when you are finally dead. Now, bring me those crystals.", completion = "Your tasks in Azshara are complete, mortal. I must now forge the necessary components for the next step in your adventure.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3621] = {title = "The Formation of Felbane", objective = "Take the Shipment to Galvan the Ancient in Stranglethorn Vale.", description = "The weapons are ready to be forged. You must take the tempered azsharite to one with the ability to harness fel energy.\n\nIn Stranglethorn Vale such a blacksmith exists. Galvan the Ancient, leader of the Mithril Order, will craft the weapons to your specifications. You will find his encampment between Zul'Gurub and the Mosh'Ogg ogre mound.\n\nMay your determination and faith carry you through this ordeal. Should you fail, know that your God smiles down upon you, mortal.", progress = "Loramus, eh? It has been many years since I have heard that name.", completion = "My goodness, I can only imagine what you went through to get these materials. Few venture into Azshara and return alive, let alone those that face demi-gods and giants!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3625] = {title = "Enchanted Azsharite Fel Weaponry", objective = "Wait for Galvan to finish forging the weaponry.", description = "<name>, the creation of each weapon will take some time.\n\nAdditionally, you may only use the power of the Felcurse once per three minutes. Its weakening properties against Razelikh the Defiler and his minions may be variable in duration. This is why you must release the Felcurse only when the moment is right!\n\nNow give me a moment to craft your weapon, <name>.", progress = "To interrupt the forging process could result in an imperfect weapon. Be patient, <name>.", completion = "&lt;Galvan wipes the sweat from his brow.&gt;\n\nA finer demon slayer has never existed, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nEnchanted Azsharite Felbane DaggerEnchanted Azsharite Felbane StaffEnchanted Azsharite Felbane Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3626] = {title = "Return to the Blasted Lands", objective = "Return to the Fallen Hero of the Horde.", description = "The hour of redemption is near, <name>. You must return to the Blasted Lands with your new-found weaponry and speak with the Fallen Hero of the Horde to receive your final objective.", progress = nil, completion = "You look battle hardened, &lt;name&gt;. Are you prepared to face Razelikh and his minions?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3627] = {title = "Uniting the Shattered Amulet", objective = "Slay Grol the Destroyer, Lady Sevine, and Archmage Allistarj. From their corpses take the Amulet of Grol, the Amulet of Sevine, and the Amulet of Allistarj.\n\nRemember to USE your Enchanted Azsharite Fel Weaponry to weaken the triad. They cannot be killed otherwise - but use them wisely...", description = "To reach the Defiler, you must first destroy the triad of power and recover the amulet pieces. When you recover all three pieces, return to me and I shall give you further instruction.\n\nGo <name>! To the Blasted Lands! Sevine, Allistarj, and Grol must fall!", progress = "The three shall form the one, the one shall light the way.", completion = "The amulet of Razelikh the Defiler is once again complete but he senses the disruption in his chain of command. He knows you come for him...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3628] = {title = "You Are Rakh'likh, Demon", objective = "Destroy Razelikh the Defiler and return the Severed Horn of the Defiler to the Fallen Hero of the Horde. You will also need to return the Ward of the Defiler so that the Fallen Hero can destroy it, preventing it from ever falling into the wrong hands.", description = "Razelikh's lair is atop the highest mountain in the Blasted Lands. The only way to the lair is through the use of the teleport runes near the mountain. As long as you hold the amulet, you can freely transport up to the lair. Once you reach the lair, you must conjure the beast. The amulet is your key, <name>. Use it on the Altar of the Defiler.\n\nShould you defeat the Defiler, bring back his horn. It will become a symbol of hope for all that view it - proof that heroes do exist in this war torn world.", progress = "There is nothing left to fear.", completion = "Today is a day that will be remembered for all eternity. The demonic overlord of the Blasted Lands has finally fallen!", rewards = "You will receive:\n\nNecklace of SanctuaryDemon's BloodDemon Hide Sack"}
MultiLanguageQuestData['en'][3629] = {title = "Goblin Engineering", objective = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n<name>, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well &lt;name&gt;, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked &lt;name&gt;, and you might learn something.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3630] = {title = "Gnome Engineering", objective = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n<name>, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3631] = {title = "Summon Felsteed", objective = "Speak to Strahad Farsan in the Barrens.", description = "Hmph. I say you're not prepared, but that is not my decision. Strahad feels otherwise, and it is his decision to make... this time.\n\nHe wishes to speak to you, and quickly. You'll find him still above Ratchet in the Barrens, at his little tower there with his acolytes.\n\nDo not dawdle long.", progress = nil, completion = "So, you've decided to grace my presence again. How kind of you.\n\nMy acolytes wondered if you'd ever show up. I told them there was no doubt. When power is concerned, you are drawn in like a moth to the flame.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3632] = {title = "Gnome Engineering", objective = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  Gnome engineering represents by far the superior of the two!  It's about the construction of wonderful gadgets and devices that make life better!\n\n<name>, read this manual.  If you want to learn more on gnome engineering, then take that manual to Tinkmaster Overspark here in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3633] = {title = "Goblin Engineering", objective = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  Clearly, goblin engineering is the choice of all brilliant engineers.  Learn to master the world through the judicious use of high explosives and fantastic gear!\n\n<name>, read this manual.  If you want to learn about goblin engineering, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well &lt;name&gt;, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked &lt;name&gt;, and you might learn something.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3634] = {title = "Gnome Engineering", objective = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Tinkmaster Overspark in Ironforge.", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely often work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take that manual to Tinkmaster Overspark in Ironforge.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task!", progress = "Yes, yes, what needs of yours might I address today?  Clearly, I have the time to do such since all I do is stand here while our beloved city lies in a cloud of irradiated death.", completion = "Ah, a young engineer interested in pursuing the one, true discipline of engineering!  Well forgive my melodrama, friend.  While our situation remains dire, it still is always a good day to see another engineer respond to the clarion call of true engineering!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3635] = {title = "Gnome Engineering", objective = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", progress = "Hello there!  If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance.  Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh?  Well, you've come to the right gnome.  While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today.  If you're a capable student, I'll teach you what I know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3636] = {title = "Bring the Light", objective = "Archbishop Bendictus wants you to slay Amnennar the Coldbringer in Razorfen Downs.", description = "The Scourge is a persistent threat to the Alliance, a fact I am sure you know quite well. Recently, we have come across some very peculiar findings, <name>.\n\nIn the Barrens lies a horrid tangle of briars called Razorfen Downs. While once it was the home of simple quilboar, now it has become apparent that a pact was made with the Scourge, creating creatures far worse... They are now ruled by the lich, Amnennar the Coldbringer.\n\nAlign yourself with the Light, <name>; put an end to this evil union.", progress = "Amnennar must be eradicated. Go, swiftly.", completion = "Thank you , &lt;name&gt;. The Scourge will now think twice before attempting to bolster its ranks again.\n\nMay you be blessed by the Light.", rewards = "You will receive:\n\nVanquisher's SwordAmberglow Talisman"}
MultiLanguageQuestData['en'][3637] = {title = "Gnome Engineering", objective = "If you wish to learn more about Gnome Engineering, take the Manual of Engineering Disciplines to Oglethorpe Obnoticus in Booty Bay.", description = "Engineering at the expert level breaks into two disciplines: gnome and goblin.  While I think it is a waste, you should be aware of gnome specialization.  They make items and gadgets that claim to change the world, but rarely work.\n\n<name>, read this manual.  If you wish to learn how to make metal paper weights, then take the manual to Oglethorpe Obnoticus in Booty Bay.   Remember - membership is permanent and prevents joining the other discipline, so make sure you are sure before finishing his task.", progress = "Hello there!  If you've come about a homing robot that may have smashed through a wall of your domicile, then I will refer you to my barrister in advance.  Otherwise, what can I do for you today?", completion = "You've come to learn about gnome engineering, eh?  Well, you've come to the right gnome.  While the ruling faction of Gnomeregan may use politics to ostracize those they view as an intellectual threat, they know that knowledge is something they cannot control.\n\nThey and I both know that when I left Gnomeregan, they lost one of their greatest gnome engineers alive today.  If you're a capable student, I'll teach you what I know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3638] = {title = "The Pledge of Secrecy", objective = "If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan.", description = "Goblin engineering is about practical uses for high profit and higher explosive power!  Our schemata allow us to make powerful bombs and mighty weaponry; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a goblin engineer, that's that.  There is no access to gnome engineering at all.\n\nIf you still want to become a goblin engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", progress = "If you've signed the document and are ready to hand it to me, then that is that.  You've been told that this is a one way trip.  If you're ready, then hop on board!", completion = "Welcome aboard, Goblin Engineer &lt;name&gt;!  You soon will have access to the most powerful engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your goblin-oriented engineering work.  From there, we'll help you build a plan to maximize your goblin engineering talents!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3639] = {title = "Show Your Work", objective = "Bring 20 Big Iron Bombs, 20 Solid Dynamite, and 5 Explosive Sheep to Nixx Sprocketspring in Gadgetzan.", description = "As your mentor, I want samples of your work.  You're a skilled engineer; there is no question of this, <name>.  What I hope to do though is analyze them for ways to emphasize goblin-oriented techniques in your future efforts.  I need the following: twenty big iron bombs, twenty sticks of solid dynamite, and five explosive sheep - and keep the safeties armed!\n\nSubmit these items to me and I will issue you your own Goblin Engineer Membership Card; it is required for access to all goblin engineering trainers!", progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Goblin Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any goblin engineer trainer anywhere in the world.", completion = "Here is your first Goblin Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any goblin engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a goblin engineer, always a goblin engineer.", rewards = "The following spell will be cast on you:\n\nGoblin Engineering\n\nYou will receive:\n\nGoblin Engineer Membership Card"}
MultiLanguageQuestData['en'][3640] = {title = "The Pledge of Secrecy", objective = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge.", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nThe secrets I will share with you are of such a magnitude that the signing of the Pledge of Secrecy is absolutely critical.  I signed one, as did my brother and sister gnome engineers.  You will be joining quite the auspicious fold, Engineer <name>!", completion = "Welcome aboard, &lt;name&gt;!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3641] = {title = "Show Your Work", objective = "Bring 6 Mithril Tubes, an Accurate Scope, and 2 Advanced Target Dummies to Tinkmaster Overspark in Ironforge.", description = "As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, <name>.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!", progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Here is your first Gnome Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a gnome engineer, always a gnome engineer.", rewards = "The following spell will be cast on you:\n\nGnomish Engineering\n\nYou will receive:\n\nGnome Engineer Membership Card"}
MultiLanguageQuestData['en'][3642] = {title = "The Pledge of Secrecy", objective = "If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Oglethrope Obnoticus in Booty bay.", description = "Gnome engineering is about engineering theory shaped to serve our needs!  Our schemata allow us to make devices that control the world around us; the manual you read covered this.\n\nThe manual also covered our ages old oath of secrecy on our schemata.  Once you become a gnome engineer, that's that.  There is no access to goblin engineering at all.\n\nIf you still want to become a gnome engineer, sign this document pledging life-long secrecy and speak with me again.  Think about it carefully, <name>.", progress = "If you've signed the document and are ready to hand it to me, then that is that.\n\nWhile I may vehemently disagree with Gnomeregan - especially that fool Tinkmaster Overspark - politically, the Pledge of Secrecy transcends everything else!  You must agree to commit a single path and stay true to that path throughout your life.", completion = "Welcome aboard, &lt;name&gt;!  You soon will have access to the most advanced engineering schemata anywhere on Azeroth.\n\nNow that you have committed yourself to the pursuit of this knowledge, it is time to examine your gnome-oriented engineering work.  From there, we'll help you build a plan to maximize your gnome engineering talents!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3643] = {title = "Show Your Work", objective = "Bring 6 Mithril Tubes, an Accurate Scope, and a 2 Advanced Target Dummies to Oglethorpe Obnoticus in Booty Bay.", description = "As your mentor, I want some samples of your work.  You're a skilled engineer; there is no question of this, <name>.  What I hope to do though is to analyze your work for ways to emphasize gnome-oriented techniques in your future efforts.  I need the following samples: six mithril tubes, an accurate scope, and two advanced target dummies.\n\nSubmit these items to me and I will issue you your own Gnome Engineer Membership Card; it is required for access to all gnome engineering trainers!", progress = "Once I receive your crafted engineering items for my review, I will hand you a genuine Gnome Engineer Membership Card!  So long as the card is valid, you will have unlimited access to any gnome engineer trainer anywhere in the world.", completion = "Here is your first Gnome Engineer Membership Card!\n\nThis card has its dues paid for in advance for fourteen days; all cards expire after two weeks of activity.  When it does, pay your next set of dues to any gnome engineer trainer in order to get another card; without the card, your membership will temporarily lapse and you cannot access new schemata.\n\nThis never affects what you already know; once a gnome engineer, always a gnome engineer.", rewards = "The following spell will be cast on you:\n\nGnomish Engineering\n\nYou will receive:\n\nGnome Engineer Membership Card"}
MultiLanguageQuestData['en'][3644] = {title = "Membership Card Renewal", objective = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", description = nil, progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears.", rewards = "You will receive:\n\nGoblin Engineer Membership Card"}
MultiLanguageQuestData['en'][3645] = {title = "Membership Card Renewal", objective = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", description = nil, progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears.", rewards = "You will receive:\n\nGnome Engineer Membership Card"}
MultiLanguageQuestData['en'][3646] = {title = "Membership Card Renewal", objective = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", description = nil, progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of goblin engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to goblin engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears.", rewards = "You will receive:\n\nGoblin Engineer Membership Card"}
MultiLanguageQuestData['en'][3647] = {title = "Membership Card Renewal", objective = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", description = nil, progress = "In order to renew your membership card, you will need to pay the renewal fee of two gold pieces.", completion = "Since you're a practitioner of gnome engineering and are in good standing, I am able to renew a lapsed membership card for the fee of two gold pieces.  Once this fee is paid, you will be reissued a new membership card.  This will allow access to gnome engineering schemata from appropriate trainers.\n\nThis card will last for two weeks of activity, at the end of which your membership fees will become due again!  If you want to access schemata, you'll need to bring your dues out of arrears.", rewards = "You will receive:\n\nGnome Engineer Membership Card"}
MultiLanguageQuestData['en'][3661] = {title = "Favored of Elune?", objective = "Collect 15 Wildkin Feathers from the Hinterlands for Erelas Ambersky in Rut'theran Village.", description = "Wildkin are quite unpredictable creatures, <name>. Capable of incredible gentleness, these creatures will show extreme ferocity if something they deem important is threatened.\n\nThese beasts are rumored to have been created by Elune, and I am interested in finding if this is really the truth.\n\nRecently, I heard about a population of wildkin living in the Hinterlands -- Vicious, Primitive, and Savage Owlbeasts. They can be found amongst the wildlife there. Will you gather some wildkin feathers for me?", progress = "Try to avoid them if you can, <name>. The Wildkin may misread your interest as an intent to do them harm...", completion = "Thank you for bringing these to me, &lt;name&gt;.\n\nWhat did you learn of the Wildkin?\n\nPerhaps these feathers will tell us more. Ferocious monsters, or simply misguided pets? One day I'd like to know the truth...\n\nI am going to continue my research -- please come back and talk to me again after some time has passed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3681] = {title = "Tome of Divinity", objective = "Speak with Duthorian Rall in Stormwind.", description = "Sorry to interrupt your travels, <race>, but I thought you should know that word was sent from Stormwind recently asking that paladins report there for training.\n\nIf I didn't know any better, I'd say your close to reaching a special time and it's time you started studying the Tomes.\n\nLook for Duthorian Rall in Stormwind. He usually trains paladins in the Cathedral of Light.", progress = nil, completion = "Welcome to the Cathedral of Light, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3701] = {title = "The Smoldering Ruins of Thaurissan", objective = "Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information.", description = "Venture to the smoldering ruins of Thaurissan in the Burning Steppes and gather as much information as possible.\n\nIt is said that mysterious relics litter the ruins. Perhaps you should start your search there, <name>. Beware the Thaurissan guardians: Assassins that guard the ruins, keeping whatever secrets may still be buried there protected.", progress = "Do you bring new information?", completion = "Oh my! This information explains quite a lot about Thaurissan.\n\nThere is much more to learn!", rewards = "You will receive:\n\nRing of the Aristocrat"}
MultiLanguageQuestData['en'][3702] = {title = "The Smoldering Ruins of Thaurissan", objective = "Listen to Royal Historian Archesonus recant the history of Thaurissan.", description = "Would you like to hear a brief history of the Dark Iron dwarves?", progress = "Allow me to finish telling you the story of Thaurissan.", completion = "Shall we proceed?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3721] = {title = "An OOX of Your Own", objective = "You've recovered three of my OOX homing robots!  You've gone above and beyond what you needed to, so I will give you something special for all your help.  It is a miniature version of the very same robot that you have come to know and love, the OOX!\n\nI normally wouldn't let anyone have such a potentially lethal device, but you've been a real help.  Besides - the combat mechanisms and the homing logic on this one have been disabled.\n\nOther than that, it's an OOX by golly!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nMechanical Chicken"}
MultiLanguageQuestData['en'][3741] = {title = "Hilary's Necklace", objective = "Find Hilary's Necklace, and return it to Hilary in Lakeshire.", description = "My friend Hilary lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", progress = "Hi.  I miss my necklace.  My daddy got it for me.  Daddy says that there are monsters in the lake.  Did you beat up any monsters?", completion = "Thank you for finding my necklace mister &lt;class&gt;... you are very kind!  My kitty thanks you too - isn't that right Effsee?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3761] = {title = "Un'Goro Soil", objective = "Bring 20 Un'Goro Soil samples to Ghede on the Elder Rise of Thunder Bluff.", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  The Cenarion Circle wants to study this soil in large quantities; go into the wilds of Un'Goro and acquire enough of it for our continued research.\n\nThe rich soil will stick out in piles from time to time, and some of the beasts might have usable samples on their being.  Take them all outside to Ghede; just look for the piles of dirt and the tauren barking orders.  He means well, just don't get him riled up though!", progress = "At ease, Private.  If you're here to unload soil from Un'Goro - outstanding then!  Otherwise, disappear.", completion = "Oh that's right Private &lt;name&gt;, don't make any effort to help me unload this soil up on to the piles!  If the Great Spirits had wanted it done they would have miracled it up there, now wouldn't they?!\n\nArch Druid Runetotem wants to speak with you again, but for his next task you find that a journeyman's understanding of Herbalism would be helpful.  If you don't know it though, he'll still find a use for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3762] = {title = "Assisting Arch Druid Runetotem", objective = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", progress = nil, completion = "Greetings, &lt;class&gt;; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3763] = {title = "Assisting Arch Druid Staghelm", objective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", progress = nil, completion = "Well now, &lt;class&gt;... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3764] = {title = "Un'Goro Soil", objective = "Bring 20 Un'Goro Soil samples to Jenal at the Cenarion Enclave in Darnassus.", description = "The soil of Un'Goro Crater is reportedly enriched with potent magical qualities.  I want to know facts from falsehoods; go into the wilds of Un'Goro and acquire enough quality samples of soil for our continued study.\n\nYou may think that collection tasks are beneath you; that sort of attitude does not endear yourself to me or the Cenarion Circle.  Bring the samples to Jenal, who is no doubt wasting time outside behind this tree; just look for the piles of dirt.  He will handle the logistics - not I.", progress = "Ah yes, the dirt.  The Arch Druid wants twenty loads per adventurer, and twenty loads he shall get.  Let those who conspire against us fall to the wayside!", completion = "Unload your precious cargo here, noble &lt;class&gt;.  It must have been quite the burden... not unlike the burden I carry being a visionary.  Here is an honorarium for your work, as dictated by the Arch Druid himself.\n\nArch Druid Staghelm wants to speak with you again &lt;name&gt;, but for his next task you will be aided if you have a journeyman's understanding of Herbalism.  If you don't know it though, you will still be able to aid the Circle!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3765] = {title = "The Corruption Abroad", objective = "Travel to Gershala Nightwhisper in Auberdine.", description = "Stormwind -- such a bustling hub of activity.\n\nI have traveled from afar to seek help. Often it is heard that brave adventurers roam these city streets.\n\nMy brother, Gershala, requires assistance in Darkshore. He resides in the seaside town of Auberdine.\n\nThe journey is a long and epic one. It is for this reason that I ask the help of a seasoned <class> such as yourself.", progress = nil, completion = "Ah, so my brother, Argos, sent you? I realize you must be weary from your travels. But we have much to talk about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3781] = {title = "Morrowgrain Research", objective = "Take the Arch Druid's Seed Voucher to Mathrengyl Bearwalker in the Cenarion Enclave of Darnassus.", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds blossom into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I intend to unravel this mystery.\n\nTake this to Mathrengyl downstairs, and he will give you some seeds so you can get started.  If you run out, you will need to purchase more from him.", progress = "Peace and serenity be yours, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out, we have more that can be provided.  Unfortunately though, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.\n\nThose who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.", rewards = "You will receive:\n\nPacket of Tharlendris Seeds"}
MultiLanguageQuestData['en'][3782] = {title = "Morrowgrain Research", objective = "Take the Seed Voucher to Bashana Runetotem in Thunder Bluff.", description = "With what we call an Evergreen Pouch, we have cultivated Tharlendris seeds in the soil from Un'Goro Crater.  These seeds have blossomed into an array of random, potent herbs.  One result is morrowgrain, a mysterious herb we know little about; I very much hope to unravel this mystery for the Circle.\n\nTake this voucher over to my daughter Bashana, and she will give you some seeds so you may assist us.  If you run out, you will need to purchase more from her.", progress = "Peace unto you, friend.  You are here on business from the Arch Druid himself, yes?", completion = "Yes, this voucher is good for twenty packets of seeds.  If you run out of seeds, I do have more that I am able to sell to you.\n\nUnfortunately &lt;name&gt;, Tharlendris seeds are quite costly to produce in significant numbers.  This is why the Cenarion Circle asks that those who are assisting us help out by offsetting some of the cost.  Those who return with morrowgrain find that the reward the Arch Druid offers far makes up for the cost.", rewards = "You will receive:\n\nPacket of Tharlendris Seeds"}
MultiLanguageQuestData['en'][3783] = {title = "Are We There, Yeti?", objective = "Collect 10 Thick Yeti Furs for Umi Rumplesnicker in Everlook.", description = "My friends are always coming up with great ideas. I've never felt like I could match them... until today! I just drew up the plans for something great! If you promise not to tell, I'll let you in on the secret... \n\nI'm going to make a mechanical yeti! Not only are my friends sure to be freaked out when they see it, but when they get over that, I know they'll be impressed!\n\nI need thick yeti fur from the ice thistle yeti to start with. Will you help? You'll find them to the southeast.", progress = "I've got lots to get started on here. Please get me those furs as soon as you can!", completion = "These furs are perfect, &lt;name&gt;. We're off to a great start here!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3784] = {title = "Assisting Arch Druid Runetotem", objective = "Speak with Arch Druid Hamuul Runetotem in Thunder Bluff.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Thunder Bluff is most interested in seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Hamuul Runetotem is spearheading this research.\n\nPlease - if you are interested, speak with him directly on the Elder Rise within Thunder Bluff proper.", progress = nil, completion = "Greetings, &lt;class&gt;; I am glad you are interested in assisting our research.  There is much to do, and I would be doing you a disservice if I informed you that the work this entails is not dangerous.  Hopefully this will not scare you off... but from the looks of you, I take it that danger is something that you have dealt with before.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3785] = {title = "Morrowgrain Research", objective = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Mathrengyl Bearwalker in Darnassus.", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them here to me in the enclave.  Please don't bother the Arch Druid; he's a very busy man, and he doesn't need to be disturbed every time someone returns with another batch of morrowgrain!", progress = "Yes <name>, have you grown some morrowgrain for the Arch Druid's important research?  The work he is doing for the Cenarion Circle is very important, and your assistance will not go unnoticed!", completion = "Well done &lt;name&gt;, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain is a continuous one; if you wish to continue aiding us, then please return to me when you have cultivated additional morrowgrain for us.", rewards = "You will receive:\n\nCenarion Circle Cache"}
MultiLanguageQuestData['en'][3786] = {title = "Morrowgrain Research", objective = "Use an Evergreen Pouch with a Packet of Tharlendis Seeds and two Un'Goro Soil samples to try and cultivate samples of Morrowgrain.\n\nBring 10 Morrowgrain to Bashana Runetotem in Thunder Bluff.", description = "Here's your Evergreen Pouch that you'll need to use the Tharlendis seeds with.  You also need to have Un'Goro soil samples on hand to use as fertilizer for the seeds.  Just use the pouch when you have everything; the pouch will take care of the rest.\n\nWhen you have enough morrowgrain, bring them to me here on Elder Rise.  Please don't bother the Arch Druid; he'll be very busy with the research, as well as the multitude of concerns he has!", progress = "Yes <name>, have you grown some morrowgrain for the Arch Druid's important research?  The mysterious properties of Un'Goro Crater become clearer with each passing day, thanks to the help you are giving us.", completion = "Well done &lt;name&gt;, I will be sure to give these to the Arch Druid himself when he has need of them.  Meanwhile, please accept this as a token of the Cenarion Circle's appreciation.\n\nOur need for morrowgrain, for now, is constant; if you wish to continue aiding us, then please return when you have cultivated more of it.", rewards = "You will receive:\n\nCenarion Circle Cache"}
MultiLanguageQuestData['en'][3787] = {title = "Jonespyre's Request", objective = "Speak with Quintis Jonespyre in Feathermoon Stronghold.", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides in Feathermoon Stronghold, Feralas.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", progress = nil, completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3788] = {title = "Jonespyre's Request", objective = "Speak with Quintis Jonespyre in Feathermoon Stronghold.", description = "Excuse me, friend...\n\nA colleague of mine would like to speak with you about the research you are doing in conjunction with the Cenarion Circle.  He is a druid by the name of Quintis Jonespyre, and he resides here in Feathermoon Stronghold.  He would like to confer with you about morrowgrain... and he very much would like for you to keep our discussion from the ears of the Arch Druid.\n\nIf you're interested, speak with him; no doubt, all will be revealed once you do.", progress = nil, completion = "I thank you for coming, weary traveler!  Allow me to introduce myself - I am Quintis Jonespyre, druid and humble servant of Malfurion and the Cenarion Circle.  My colleagues (General Shandris Feathermoon and the Protectorate - mayhap you've heard of us) and I wanted to talk with you about the work you are doing for Fandral Staghelm in Darnassus.\n\nBefore we get much further, I'd like to ask that our discussion stay between just us.  If you have no problem with this, then we may proceed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3789] = {title = "Assisting Arch Druid Staghelm", objective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", progress = nil, completion = "Well now, &lt;class&gt;... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3790] = {title = "Assisting Arch Druid Staghelm", objective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", progress = nil, completion = "Well now, &lt;class&gt;... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3791] = {title = "The Mystery of Morrowgrain", objective = "Bring 10 Morrowgrain to Quintis Jonespyre in Feathermoon Stronghold.", description = "Let me to be frank with you, <name>.  I'm interested - nay, concerned with why the Arch Druid in Darnassus is using the name of the Cenarion Circle as well as the Circle's resources to procure vast amounts of morrowgrain.  I'm a researcher - curses are my specialty.  I've heard that morrowgrain, under the right conditions, exude qualities like other herbs used in primitive curses.\n\nI want to know more, and I ask for your help.  Bring me ten morrowgrain, and I will be sure to take care of you.", progress = "I'm looking for ten morrowgrain - that should be enough to at least get my research started.  I'll no doubt burn through a lot of those going down wrong paths, but such is the nature of research.", completion = "Gah, these morrowgrain make me feel... weird.  What in the name of Elune is Staghelm up to with these things?\n\nAnyway, thank you again for your help.  Here's a little something... you know, for the effort.  My research on morrowgrain is going to take a while, and I no doubt am going to need more.  While I'm at it, I suppose I could take the time to see if morrowgrain have some pertinent alchemical uses.  Still, I feel uncomfortable even being around them.", rewards = "You will be able to choose one of these rewards:\n\nQuintis' Research GlovesBark Iron Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3792] = {title = "Morrowgrain to Feathermoon Stronghold", objective = "Hello again, <name>.  My research is progressing fairly well, but if you have five more Morrowgrain I'd be happy to take them off your hands.  Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel.  Still, my research demands I buckle down and get through this.", description = nil, progress = "Hello again, <name>.  My research is progressing fairly well, but if you have five more Morrowgrain I'd be happy to take them off your hands.  Well... happy is a figurative term in this case; the more I am around them, the more uncomfortable I feel.  Still, my research demands I buckle down and get through this.", completion = "Thanks &lt;name&gt;; I'll just store these out of the way for the time being.  While I don't command the resources that Staghelm does, I am able to give you a little something for your trouble.  Anyway, who knows what will happen if Staghelm keeps getting Morrowgrain after Morrowgrain.  There's something fishy going on, mark my words.\n\nRemember that I'm always looking for more Morrowgrain.  I'll take them in quantities of five at a time.", rewards = "You will receive:\n\nPacket of Tharlendris Seeds"}
MultiLanguageQuestData['en'][3801] = {title = "Dark Iron Legacy", objective = "Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major.Greetings, <name>. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", description = "Greetings, <name>. I am Franclorn Forgewright. Yes, the Franclorn Forgewright responsible for the stonewrought method of architecture. You have undoubtedly passed through or stood upon one of my creations in your adventures across our war torn world.\n\nYou are probably wondering why I am here and what it is that I want from you - both valid questions.\n\nI need your assistance, of course. In exchange for your assistance, I shall grant you the key to the depths of my accursed city.", progress = nil, completion = "Whether it is greed which brought you here or an act of selfless devotion, what you are about to undertake is for the good of us all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3802] = {title = "Dark Iron Legacy", objective = "Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright.", description = "You will find Fineous Darkvire beyond the Ring of Law, in the Hall of Crafting. Kill the miserable cur and recover Ironfel.\n\nTake Ironfel to the Shrine of Thaurissan and place the hammer in its rightful place: In the hands of the statue erected in my honor.\n\nWhen this is done, the compartment in which I stored the master key will open. More importantly, Ironfel will remain forever in my grasp. Should they make an attempt to remove the hammer; both the statue and hammer will shatter, lost forever.", progress = "The statue looms ominously above you.", completion = "The hammer slides firmly into place, within the grasp of the massive Dark Iron monument. A tiny compartment opens at the base of the statue. Inside you find...", rewards = "You will receive:\n\nShadowforge Key"}
MultiLanguageQuestData['en'][3803] = {title = "Morrowgrain to Darnassus", objective = "The Arch Druid is always looking for additional morrowgrain for the Cenarion Circle's continued research.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will reward you accordingly.", description = nil, progress = "The Arch Druid is always looking for additional morrowgrain for the Cenarion Circle's continued research.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will reward you accordingly.", completion = "Excellent - this morrowgrain will no doubt please the Arch Druid.  I must admit though... just being near them makes me feel a little uncomfortable.  I can only imagine how difficult it is for the Arch Druid to tolerate them in such large numbers!\n\nThis is for you, &lt;name&gt;.  The Cenarion Circle thanks you for your continued support.", rewards = "You will receive:\n\nCenarion Circle Cache"}
MultiLanguageQuestData['en'][3804] = {title = "Morrowgrain to Thunder Bluff", objective = "The Arch Druid is always looking for more morrowgrain for the Cenarion Circle's research project on Un'Goro Crater.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will award you accordingly.", description = nil, progress = "The Arch Druid is always looking for more morrowgrain for the Cenarion Circle's research project on Un'Goro Crater.  We take them in increments of ten, and award you with a cache of goods you should find useful.  When you have ten, let me know and I will award you accordingly.", completion = "Excellent - this morrowgrain will no doubt help when the time comes.  We know that the night elves are conducting similar research into these herbs, though it isn't clear to what end they will use them for if they discover anything.  The Arch Druid thinks that the need for morrowgrain will remain until we've figured out the mysteries behind this herb.\n\nThis is for you, &lt;name&gt;.  The Cenarion Circle thanks you for your continued support.", rewards = "You will receive:\n\nCenarion Circle Cache"}
MultiLanguageQuestData['en'][3821] = {title = "Dreadmaul Rock", objective = "Venture forth to the Burning Steppes and find out what became of Sha'ni Proudtusk.", description = "Sha'ni was sent to investigate reports of strange ritualistic activity coming from the Firegut ogres of the Burning Steppes over three weeks ago.\n\nGoretooth tells me that he hasn't heard from anyone in that platoon and that it's best that I move on and focus on the task at hand. Can you believe it? That's my wife!\n\nI can't leave my post, <name>, but I must know what became of Sha'ni. Travel to the Burning Steppes and search for her.", progress = nil, completion = "My poor Thal'trak.\n\nWe were planning on moving in with my mother and father in the Hinterlands after our tours were over. Now those plans are ruined!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3822] = {title = "Krom'Grul", objective = "Recover Sha'ni's Nose-Ring from Krom'Grul and return it to Thal'trak in Kargath. Search the various caves and mines in Dreadmaul Rock.", description = "My whole platoon was captured, <name>. All were slain - except me.\n\nTheir leader, Krom'Grul, wanted to save me for some sort of ritual.\n\nI was chained to this altar and brutalized by the beast. My physical being ceased functioning after an hour of this torture. The beast then ripped my wedding nose-ring off of my face and stuck it on his finger. I had never seen such savagery!\n\nFind Krom'Grul and kill him! Take my ring back to Thal'trak.\n\nAnd <name>, tell him that we will meet again... in another life.", progress = "Did you find Sha'ni? Is she ok?", completion = "&lt;Thal'trak collapses.&gt;\n\nWe were going to move to the Hinterlands. Did she tell you? This was going to be her last mission.\n\n&lt;Thal'trak sobs.&gt;\n\nI don't want it, &lt;name&gt;. Keep it, throw it away, I don't care! The ring means nothing to me now. Not without her...", rewards = "You will receive:\n\nSha'ni's Ring"}
MultiLanguageQuestData['en'][3823] = {title = "Extinguish the Firegut", objective = "Slay 15 Firegut Ogre-Mages, 7 Firegut Ogres, and 7 Firegut Ogre Brutes, and return to Oralius when you are finished.", description = "We must strike at our enemies before they strike at us!\n\nI'll make this brief, soldier.\n\nThe Firegut ogres of the Burning Steppes are allies of the Blackrock orcs. They work closely with those vile orcs, keeping the mineral rich Dreadmaul Rock guarded and the supply lines open at all times.\n\nLeave your mark, <name>. Cripple their forces and return to me when the job is done.\n\n<Oralius grabs at the air and makes a choking motion.>\n\nI WILL KILL YOU, WINKY!", progress = "There is not nearly enough blood on your uniform, soldier!", completion = "Outstanding, soldier! The orcs and ogres will be reeling from this blow for minutes, maybe even hours!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3824] = {title = "Gor'tesh the Brute Lord", objective = "Find Gor'tesh, somewhere to the west of Dreadmaul Rock. Kill Gor'tesh and then take Gor'tesh's Lopped Off Head back to Oralius in Burning Steppes.", description = "They're reeling I tell you! Our next strike must be decisive.\n\nThe brute lord, Gor'tesh, must be slain. More importantly, his head must be returned to me so that I may prepare the third phase of our attack on the Firegut ogres.\n\nBe warned, soldier, Gor'tesh rules not from Dreadmaul Rock but from a Blackrock orc structure to the west of Dreadmaul Rock.\n\nYour orders, then, are simple. Find Gor'tesh and chop off his fat head. Return to me when the job is done.\n\nSHUT UP, WINKY!", progress = "Oh glorious day! Have you returned with the head?", completion = "Just look at it, soldier. Disgusting! When the remaining Firegut ogres see this fat mug stuck on a pike sitting at the top of their mountain, mass hysteria will ensue!\n\n&lt;Oralius cackles wildly.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3825] = {title = "Ogre Head On A Stick = Party", objective = "Take Gor'tesh's Lopped Off Head and place it at the top of Dreadmaul Rock. Look for a soft dirt mound to plant the pike.", description = "Just one last thing you must do, soldier.\n\nI've taken the liberty of putting Gor'tesh's head on a pike. Now all you have to do is take this head to the top of Dreadmaul Rock and stick it into the ground. Once you do that, watch as those cowardly ogres run for their lives! After you've had your fun, come back to me and I'll reward you for all of your hard work.\n\n<Oralius seems to be losing touch with reality.>", progress = "So? Did you paint any pictures of the event?", completion = "Outstanding work, soldier! Simply amazing! Oh I'll get the medal of bravery for this, er, I mean you'll be rewarded handsomely for this!", rewards = "You will be able to choose one of these rewards:\n\nMaddening GauntletsChoking Band\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3841] = {title = "An Orphan Looking For a Home", objective = "Speak to Quentin in Thousand Needles.", description = "Oh, hello, <name>. I'm so glad to see you again. How was your trip to Darnassus?\n\nWell, you'll be happy to know that we've made quite a bit of progress while you've been gone. We even saved a nest full of eggs. Unfortunately, the mother died before we got to her.\n\nSay, would you want one for a pet? They look to hatch soon, so they'll need a good <father/mother>. What do you say?\n\nIf you're really interested, take one of the eggs to Quentin at the race tracks in Shimmering Flats. He'll tell you more.", progress = "Why hello, <class>.\n\nDon't let my location fool you, I'm really not here for the races... as entertaining as they may be.\n\nI'm actually here in Thousand Needles investigating all I can to find out how salvageable the land is. It has become my crusade of sorts to revitalize and replenish the area with new, fertile soil. Perhaps I'll find there's a water source nearby.\n\nTell me you haven't noticed how odd the transition between Feralas and Thousand Needles is. Strange magic was afoot when that happened.", completion = "Ah, a sprite darter egg, and one near maturation, if I'm not mistaken. Remarkable you've found one, let alone in this good a condition. They're rarely seen in Feralas these days. I understand there were various poachers in the area trying to capture and kill them for many reasons. Too bad really... such beautiful creatures when they reach adulthood.\n\nHow did you come across such a find?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3842] = {title = "A Short Incubation", objective = "Bring 2 Elixir of Fortitudes to Quentin in Thousand Needles.", description = "The Moonweavers, huh? Most intriguing. I wish the sprite darters could truly appreciate what it means to have those two look after them. They are both quite capable.\n\nSo, they gave you the egg as a gift. Well, then you should be responsible for it for as long as you desire. It appears it's almost ready to hatch, but we should ensure it's healthy and no damage has been done to it.\n\nI only need two elixirs of fortitude for a small spell to protect the egg. I have the rest of the components here with me.", progress = "The longer I stay here, the more tempted I am to partake in these races, <name>. Truly boggling...\n\nHave you found the elixirs yet? Once I can tell if the egg is going to be healthy or not, I'll return it to you to hold onto until it's prepared to hatch.\n\nLet me know.", completion = "Wonderful. These will do nicely. Give me a moment to mix together my components and we shall see how well this egg is going to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3843] = {title = "The Newest Member of the Family", objective = "Take your Fragile Sprite Darter Egg to the Hinterlands and speak to Agnar Beastamer, but hurry, you only have 1 hour to find him before the hatchling within the egg dies.", description = "A magnificent specimen, <name>. If this creature survives gestation, then it'll be a healthy pet indeed!\n\nThere is one last thing I would suggest doing if you plan on following through with this--head to Aerie Peak in the Hinterlands. Speak to a dwarf there named Agnar Beastamer, he's a master animal handler and should be able to guide you in the final steps of incubation.\n\nBut hurry, <name>, this egg is fragile and will not last long without proper care.", progress = "Greetin's, <name>. How can I be of service to ya?", completion = "Well, well, well... I haven't seen one of these in a dragon's age. Faerie dragon, if I'm not mistaken... looks to be of the sprite darter variety. Excellent, excellent indeed.\n\nWell, if this little fella's gonna hatch and live to be strong and healthy, then we should get some food for it. Good ya got it to me in time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3844] = {title = "It's a Secret to Everybody", objective = "Look around in the pond for a clue about who this wrecked raft may belong to.", description = "A destroyed raft rests along the shoreline. Considering this is only a small pond, it is not clear as to how it ended up here, although looking at the trees tells you that the water level may not be constant.\n\nPerhaps a little exploration in the area might uncover more clues...", progress = nil, completion = "A water-logged pack rests at the bottom of the pond.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3845] = {title = "It's a Secret to Everybody", objective = "Examine the items inside the pack and bring them to their owner.", description = "Grabbing onto it, you pull the pack back to the shore. Perhaps if you examine the items inside the pack, you might find out more about who it belongs to.\n\nThere are a few stray travelers at Marshal's Refuge. Perhaps you might find out more there.", progress = "Hi there. I've seen you before... Haven't I?", completion = "Oh... Yes, these things do look familiar... well, kind of...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3861] = {title = "CLUCK!", objective = "Find some Special Chicken Feed and return to your befriended chicken. When you find it, /cheer at it before trying to give it the Special Chicken Feed.", description = "\"Cluck... cluck... cluck... BACAW!\n\nCluck... cluck... cluck.\"\n\nThe chicken looks up at you and then starts to scratch its claws into the ground. You think it is spelling out a word, but you are not sure what it is. Could it be... S-A-L-D-E-A-N? Before you can ask, the chicken turns away and goes about its business.", progress = "The chicken stares at you with dark, cold eyes. It waits for you hungrily.\n\n\"BACAAAW!\n\nCluck...cluck...cluck.\"", completion = "\"BACAW!!!\"\n\nThe chicken starts to gobble up the feed you put down.\n\nAfter a moment, the chicken looks around, startled. It uncomfortably shuffles back and forth. Is this chicken pregnant? You think you better check underneath it.", rewards = "The following spell will be cast on you:\n\nSummon Chicken Egg"}
MultiLanguageQuestData['en'][3881] = {title = "Expedition Salvation", objective = "Bring a Crate of Foodstuffs and Research Equipment to Williden Marshal in Un'Goro Crater.", description = "I don't know how you made it here, but you're a sight for sore eyes!  I'm Williden Marshal, and I lead a non-aligned expedition troupe.  Our latest and greatest endeavor has met with what seems like countless disasters, the most serious of which being that we underestimated the savagery of Un'Goro Crater!\n\nAs we fled our base camps in the southwestern and northeastern parts of the crater, we left behind vital supplies.  You look like you're capable enough - can you help us by getting them back?", progress = "If we're going to have any chance of getting out of here alive, we'll need our big crate of foodstuffs.  Also, getting at least some of our research equipment back would be a blessing in a sea of misery.", completion = "You got both our foodstuff AND our research equipment back!  You've not only saved the expedition, you've also saved our lives.  I and the rest of my team can't thank you enough; we just might make it here for a while now thanks to you.\n\nWhile we don't have much, I'm certainly not going to leave you high and dry for the invaluable help you've given us.  Thank you, &lt;name&gt; - you've got a friend in Marshal Expeditions!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3882] = {title = "Roll the Bones", objective = "Bring 8 Dinosaur Bones to Spark Nilminer in Un'Goro Crater.", description = "You'd think that being chief digger for Marshal Expeditions means I like digging.  There might be worse things to do in this world... but none really leap to mind.\n\nWe were supposed to be digging in Terror Run - FANTASTIC name by the way - for dead stegodons and diemetradons.  Well, there are plenty of live ones there too!  Wil and Hol are still all about studying this death trap, so we need those dinosaur bones.  Between you and me though, bringing some from live ones will work out just as well.", progress = "Think whatever you want of me, but they're not going to care if the bones they get to research are from ones from ancient stegodons and diemetradons or the ones that almost devoured us wholesale when we were trying to set up our camps.  I'll just be happy if we get out of here alive...", completion = "Excellent, these should do the trick.  And now, if you'll permit me...\n\nTHANKS FOR DIGGING ALL OF THESE BONES OUT OF THE GROUND FOR US AND NOT HURTING THE NATIVE BEASTS IN ANY WAY.\n\nWhether you really did or didn't, I don't want to know.  Let's keep it that way, shall we?  Here - maybe this will keep your lips shut on the whole thing.  Anything to get out of here alive, I say!", rewards = "You will be able to choose one of these rewards:\n\nArchaeologist's Quarry BootsExcavator's Utility Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3883] = {title = "Alien Ecology", objective = "Use the Scraping Vial to collect a Hive Wall Sample from one of the Gorishi hive hatcheries in Un'Goro Crater. Look for the chambers with the hanging larval spawns.\n\nBring the Hive Wall Sample to Hol'anyee Marshal in Un'Goro Crater.", description = "Just because we've suffered a setback doesn't mean that research must stop!  We were investigating the Gorishi insects in the southern part of the crater before winding up here.  Their presence is alien to the ecology of Un'Goro, and we want to find out why.\n\nIn their hive network must be larval hatcheries.  You can identify these places by their hanging larval spawns.  Use this vial to take a sample of the hive wall near any of the hatcheries.  Bring it back to me for study, but be careful!", progress = "Do you have the sample of the Gorishi hive for me to study, <name>?", completion = "Yes, this will do nicely.  You've been a great help... I wish I could give you more than this, but being virtually stranded in the middle of a savage land does limit what I can and cannot give.  Rest assured though - the research done here would not have been possible without your assistance!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3884] = {title = "Williden's Journal", objective = "Return the journal to Williden Marshal somewhere in Un'Goro Crater.", description = "You have uncovered a mangled journal.  Parts of it remain legible, with a Williden Marshal claiming ownership over the contents therein.  If the journal is accurate, then Williden may be found somewhere in the northern part of the Crater; according to the journal, he and his companions sought higher ground from the savage beasts of the Crater once their base camps were overrun.", progress = "Hello there!  I and my companions are happy to see some living beings here other than overgrown savage beasts!  What brings you into the Un'Goro Crater?", completion = "Well look at this - my journal!  I thought it was lost, much like almost everything else we brought into Un'Goro.  I thank you kindly for returning this to me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3901] = {title = "Rattling the Rattlecages", objective = "Kill 12 Rattlecage Skeletons, and then return to Shadow Priest Sarvis in Deathknell when you are done.", description = "You've shown your potential to the Forsaken under normal circumstances <name> - now let's see you under pressure.\n\nThe Rattlecage skeletons, more mindless minions of the Lich King, are a tougher foe than the zombies you have faced thus far.  Again, thin their numbers and prove yourself to the Forsaken.  Do not tarry - when you are done, speak to me again.", progress = "Those who dally in this task might as well end up wandering about aimlessly like our fallen brothers and sisters in the village.  Let's hope you will fare better than them, yes?", completion = "I am finished with you, &lt;name&gt; - you have shown yourself to be worthy of the freedom that you have been given.  Many will stand against you for what you have become, but know that no matter what they may try to do against us, we are free and will not be shackled again.\n\nTake these and be on your way.  You have much to accomplish, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nFlax BootsScavenger TunicRoamer's Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3902] = {title = "Scavenging Deathknell", objective = "Search Deathknell and the vicinity for 6 pieces of Scavenged Goods, and return them to Deathguard Saltain.", description = "You there!  If you're looking for something to make yourself useful, then listen up!\n\nWe need fresh out-of-the-ground recruits to head into Deathknell and search for any sort of useful equipment.  Most likely, they'll be in stacks of boxes.  We expect more recruits to be rising soon, and unless we want them to stumble about naked we had better get to scavenging!\n\nWell get to work, you miserable bag of bones!  I'm not going to reward those without some hustle.", progress = "Have you managed to scavenge up some useful items for us?  There is no shame in reusing that which has been tossed aside.  No one is going to give us any handouts - we Forsaken will fend for ourselves!", completion = "Great work &lt;name&gt;, I knew you weren't useless.  Here - have one of the better items I've found out of the lots that have been collected so far.", rewards = "You will be able to choose one of these rewards:\n\nFlax BeltRustmetal BracersShort Duskbat Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3903] = {title = "Milly Osworth", objective = "Speak with Milly Osworth.", description = "You've shown yourself a dependable <class>, <name>.  Dependable, and not afraid to get your hands dirty, eh?\n\nI have a friend, Milly Osworth, who's in some trouble.  She's over with her wagon on the other side of the abbey, near the stable.  I'm sure she could use a pair of hands like yours.", progress = nil, completion = "Oh, Deputy Willem told you to speak with me?  He's a brave man and always willing to help, but his duties keep him stuck at Northshire Abbey and I'm afraid the problem I have today is beyond him.\n\nPerhaps you can help me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3904] = {title = "Milly's Harvest", objective = "Bring 8 crates of Milly's Harvest to Milly Osworth at Northshire Abbey.", description = "A gang of brigands, the Defias, moved into the Northshire Vineyards while I was harvesting!  I reported it to the Northshire guards and they assured me they'd take care of things, but... I'm afraid for my crop of grapes!  If the Defias don't steal them then I fear our guards will trample them when they chase away the thugs.\n\nPlease, you must help me!  I gathered most of my grapes into buckets, but I left them in the vineyards to the southeast.\n\nBring me those buckets!  Save my harvest!", progress = "Do you have my harvest, <name>?", completion = "Oh thank you, &lt;name&gt;!  You saved my harvest!  And I hope you showed a few of those Defias that they can't cause trouble around here.\n\nWe might be short on guards these days, but we're lucky to have heroes like you to protect us!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3905] = {title = "Grape Manifest", objective = "Bring the Grape Manifest to Brother Neals in Northshire Abbey.", description = "Now that my crop is saved, take this Grape Manifest to Brother Neals.  He manages the store of food and drink in Northshire, and I'm sure he'll be delighted to hear that he has fresh grapes.\n\nYou'll find Brother Neals in the abbey, in the bell tower... where he likes to taste his wine.", progress = "You look to be in fine spirits!  Come!  Have a seat, and have a drink!", completion = "Let's see here...\n\nOh my!  Milly's grapes have been saved!  When she told me that brigands overran her vineyards I nearly despaired, but my faith in the Light did not waver!\n\nAnd through your bravery,  we now have grapes for more wine!  May the Light bless you, &lt;name&gt;, and keep you safe!", rewards = "You will be able to choose one of these rewards:\n\nWine-stained CloakLatched Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3906] = {title = "Disharmony of Flame", objective = "Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment.", description = "The elders have felt a disturbance amongst the elements. The Dark Iron dwarves have summoned a foul spirit into our world that threatens to plague our lands with an eternal draught. This disharmony of flame must be investigated.\n\nTravel to Blackrock Mountain, through the Chasm of Flame, into the quarry. It is there that you shall find this lord of fire: Overmaster Pyron.\n\nEnd the disruption and return to me.", progress = "The elements are still in disarray, <name>.", completion = "This cannot be... it must not be. The destruction of Pyron has merely lifted a veil. Within the depths of Blackrock is a much more insidious source of corruption.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3907] = {title = "Disharmony of Fire", objective = "Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart.", description = "I can taste the foulness in the air that surrounds you, <name>. There is another, hidden in the depths of Blackrock, who does control this foulness.\n\nThe wind and earth cry his name: Lord Incendius... but someone... something... commands this being. He is merely an emissary.\n\nFind him and discover where his master hides. Return to me when you have collected this information.", progress = "The flames will soon overtake these lands. Make haste, <name>!", completion = "&lt;Thunderheart clutches the Tablet of Kurniya.&gt;\n\nRagnaros... here...\n\nThe elders were right to fear the corruption emanating from Blackrock Mountain. A general of the Old Gods! IN OUR WORLD! We must reassess our position here in Kargath. We must decide on whether we stay and fight or run for fear of a new sundering.\n\nBe wary of any further exploration in Blackrock Mountain, &lt;name&gt;. A far greater evil than anything that exists in this world resides in those fiery depths.", rewards = "You will be able to choose one of these rewards:\n\nSunborne CapeNightfall GlovesCrypt Demon BracersStalwart Clutch\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3908] = {title = "It's a Secret to Everybody", objective = "Take Linken's Sword to Donova Snowden in Winterspring.", description = "You see, I have no idea how I ended up here. No one really knows -- it's a secret to everybody! I just can't seem to remember anything...\n\nThese items you brought to me, though... I am remembering something.\n\nMy sword. I am supposed to strengthen it somehow, but I'm really not sure why. Sorry I can't tell you more, but I just don't remember!\n\nAnyhoo, I do know where you can take it -- Donova Snowden in Winterspring. You'll find her by the hot springs. She can temper the sword by the pools there.", progress = "My, my... So Linken did finally get around to sending me his sword.", completion = "Well, of course I can temper this sword. While I'm working, you can explain what took Linken so long to get this to me. He's not usually one to forget things...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3909] = {title = "The Videre Elixir", objective = "Seek out Gregan Brewspewer in northern Feralas. From him, learn how you may acquire the Videre Elixir, then return to Donova Snowden in Winterspring.", description = "Now, what's this? Linken... FORGOT?\n\nOh, I see... Lost his memory...\n\nWell, here is his sword. It's not complete, though. I know of the one that can finish it, but... speaking with him may prove difficult.\n\nListen, I know of someone that will be able to help you. It's too much to explain right now, but you must somehow acquire a Videre Elixir. The only one I know that can help you with that is Gregan Brewspewer. He's hard to track down, but last I knew he was camping in the wilds of Feralas.", progress = "Back already?", completion = "I'll need one vial to make sure that this is truly the elixir... Yes... This is the stuff.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3911] = {title = "The Last Element", objective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", description = "There is work to be had for those venturing into the depths, <name>.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nLagrave's Seal"}
MultiLanguageQuestData['en'][3912] = {title = "Meet at the Grave", objective = "Go to the graveyard outside Gadgetzan, and use the Videre Elixir. Follow the rest of Donova's instructions to find Gaeriyan.\n\nProvided item: \n", description = "This elixir will allow you to speak with one that you would not normally even see...\n\nTake the Videre elixir, along with Linken's sword, to the graveyard just outside Gadgetzan in Tanaris. Once there, drink the potion. You may be quite surprised at the results, but do not be alarmed.\n\nIn your \"other\" form, head due north until you reach the mountains. You'll find the one you need to speak with in one of the rocky crevices. His name is Gaeriyan.\n\nRemember, he will only speak to you in that form...", progress = nil, completion = "It has been long since any have come to talk with me...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3913] = {title = "A Grave Situation", objective = "Resurrect, then look for the gravestone that Gaeriyan told you to find.", description = "If you return to the graveyard, <name>, you will find a gravestone there... Not just any gravestone; this one will stand out from the others. Secrets lie within it.\n\nPush on the stone, and you will learn of these secrets...", progress = "This must be the gravestone that Gaeriyan mentioned...", completion = "You push on the stone firmly, and it slides away, revealing a small depression underneath it.\n\nPlacing Linken's Sword into the depression, you realize that it fits perfectly...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3914] = {title = "Linken's Sword", objective = "Deliver Linken's Superior Sword to Linken in Un'Goro Crater.", description = "After a strong flash of light, you are able to pick up the sword again. It has been transformed!", progress = "Oh! I remember you! You are... No, don't tell me!", completion = "My sword... It's finished!\n\nNow, if only I could remember why I needed this...\n\nHere, let me at least pay you for your work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3921] = {title = "Wenikee Boltbucket", objective = "Bring the Broken Samophlange to Wenikee Boltbucket.", description = "I think I might have broken that Samophlange.  That's not good, because I already told some colleagues in Undermine about it and they were very intrigued.  We must find a way to fix it!\n\nTake the broken samophlange to Wenikee Boltbucket, just south of Mor'shan Rampart, the horde outpost between the Barrens and Ashenvale.  She is very clever and inquisitive.  If you show her the samophlange I bet she'd jump at the chance to fix it.", progress = "I'm very busy with my work, <class>.  Unless you have something for me, it'd be best if you moved along...", completion = "Oh, what's this?  A samophlange, you say?  What's a samophlange??\n\nAh... but look at the way it moves when you handle it.  And there's the sound of intricate gears inside.  Oh my!  I want to fix it and see what it does, don't you??", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3922] = {title = "Nugget Slugs", objective = "Bring 15 Nugget Slugs to Wenikee Boltbucket in the Barrens.", description = "I want to fix this samophlange, but to do that I'm going to need some supplies.  I ran out of seventeen-point-five gauge nugget slugs and I'm going to need a bunch of those for the work ahead.\n\nThe closest place to get them is the Sludge Fen to the east.  The Venture Company usually keeps them in their tool buckets.  Go to the Sludge Fen and look in the tool buckets you find there, then return to me when you've gathered enough nugget slugs.", progress = "Do you have the nugget slugs, <name>?  I've been eyeing this Samophlange and I can't wait to tinker with it.", completion = "Great, you got them!  Now I can get to work...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3923] = {title = "Rilli Greasygob", objective = "Bring the Broken and Battered Samophlange to Rilli Greasygob in Orgrimmar.", description = "Well, that didn't work.  I put some extra gauges on the samophlange to measure its structural integrity, and they read the integrity at an all-time low.  I could add some more dials and maybe a lever or two to try and fix it, but... I think that might make things even worse.\n\nYou should take the samophlange to Rilli Greasygob.  He used to work for the Venture Company -- if anyone knows how to fix it, it's Rilli.\n\nYou can find him at Nogg's Machine Shop in Orgrimmar, in the Valley of Honor.", progress = "Mind your head!  I don't want it to get in the way of my work!", completion = "What's this?  Why, it's a samophlange!  Where did you get this thing?  Have you been poking around the Venture Company holdings in the Barrens?\n\nYou must be very brave, or very stupid.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3924] = {title = "Samophlange Manual", objective = "Bring the Samophlange Manual to Rilli Greasygob in Orgrimmar.", description = "I think I can fix the samophlange, but I'm going to need the user's manual first.  When I was in the Venture Company I had a rival, Boss Copperplug, who hoarded the secrets of the samophlange, giving out small bits of knowledge on the device to those he trusted.  I wasn't one of the trusted few...\n\nBoss Copperplug used to stay at the Boulder Lode Mine in northeastern Barrens.  Get the manual from him, and if he's given pages from it to anyone, you'll have to collect them too.", progress = "Do you have the manual?", completion = "You got the manual!  I can't wait to read it and find out how to fix the Samophlange!  I spoke with Sputtervalve in Ratchet--he wanted to thank you for your help, and wanted to reward your efforts.\n\nI want to thank you too, and if I ever get this thing fixed I'll let you know...", rewards = "You will be able to choose one of these rewards:\n\nTork WrenchSamophlange Screwdriver\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][3941] = {title = "A Gnome's Assistance", objective = "Find J.D. Collie in the cave at Marshal's Refuge.", description = "Thinking... Thinking... I know I came here for something important...\n\nI have an idea, <name>. In the cave over there is a gnome named J.D. that was very kind to me when I first arrived here. Perhaps in my disoriented state, I might have mentioned something to her.\n\nWhy don't you go ask her if she knows anything? Oh, but be careful -- she's always messing with those crazy glowing crystals I've seen in the crater. I'm not quite sure what she's up to in there!", progress = nil, completion = "Stay where you are for just a moment... I am testing out a new combination of crystals...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3942] = {title = "Linken's Memory", objective = "Find Eridan Bluewind in southern Felwood.", description = "Oh... Linken? Yeah, he's a funny one. When he first got here, he was mumbling about all kinds of strange things. Probably got bumped on the head pretty hard, I imagine.\n\nSomething he said kinda stuck with me though -- that he was making some sort of totem; said he had to talk to someone named Eridan Bluewind... in a place called Felwood, I think?\n\nI doubt he could tell you much now, though. If you want to know more, maybe you should look for Eridan yourself?", progress = nil, completion = "Hello, &lt;class&gt;. Is there something I can help you with?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3961] = {title = "Linken's Adventure", objective = "Take the Silver Totem of Aquementas to Linken in Marshal's Refuge.", description = "To think all this time that the reason Linken came here was to rid us of Blazerunner... He seems like such an ordinary guy, but I did notice that he's not at all interested in any of my experiments or gadgets like most gnomes would be. He must be a true warrior at heart.\n\nBring the totem to him. See if that helps him remember why he came here.", progress = "Hi, again, <name>!", completion = "Did J.D. help you at all?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3962] = {title = "It's Dangerous to Go Alone", objective = "Travel to Fire Plume Ridge, south of Marshal's Refuge.\n\nFind Blazerunner and use the totem to remove his protective aura. Once he has been defeated, acquire the Golden Flame from the cave.", description = "<name>, I finally remember now... I did come here to fight Blazerunner. I was on a journey, and this was to be the last step.\n\nBut I am no longer the hero... You are. All that you have done -- you must finish this now, not me.\n\nBlazerunner guards an artifact called the Golden Flame. It provides power more vast than anything else I have ever known, and it is dangerous in the hands of one with an evil heart.\n\nYou will want to bring others with you -- it's dangerous to go alone. Take this as my advice.", progress = "Blazerunner is almost invincible behind the aura he has created by using the Golden Flame. Only you have the power to remove it with the Silver Totem of Aquementas.", completion = "Thank you, &lt;name&gt;.\n\nThe Golden Flame will now be returned back to my homeland, where it may be protected, never again to be used for evil.\n\nWithout you, I'd still have no idea who I am! Since you did so much for me, I'd like you to have something special...\n\nTake any one you want!", rewards = "You will be able to choose one of these rewards:\n\nLinken's Sword of MasterySpirit of Aquementas\n\nYou will also receive:\n\nLinken's Boomerang"}
MultiLanguageQuestData['en'][3981] = {title = "Commander Gor'shak", objective = "Find Commander Gor'shak in Blackrock Depths.\n\nYou recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort.", description = "Poor Gargal... didn't even see it coming. WHAM! The arrow landed dead center on the top of his head. He was no genius before but now...\n\n<Galamav grimaces.>\n\nWhen we dislodged the arrow, we noticed a rolled up note attached to the shaft. On the note was a crudely drawn picture of an orc behind bars with the signature of Commander Gor'shak attached.\n\nIf he's still alive in the Depths, you'll have to find him.\n\nA trap you say? Well no kidding, numb hooves! That's why you're going!", progress = nil, completion = "We haven't got much time. Listen carefully, &lt;race&gt;. What I have to tell you is classified and for your ears only.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][3982] = {title = "What Is Going On?", objective = "Defend Gor'shak.", description = "I was sent here under the auspices of Thrall. Do you actually think these buffoons could capture me? I allowed myself to be captured so that I could gather intelligence.\n\n<Gor'shak whispers.>\n\nThe Princess of Ironforge has been kidnapped by Emperor Thaurissan. Princess Bronzebeard is in this very city! I bet old Magni's heart almost stopped when he heard that news.\n\n<Gor'shak laughs.>\n\nShhh! Do you hear that? Guards coming! DEFEND YOURSELF!", progress = "Defend yourself, fool!", completion = "That was a close call. They have been alerted to your presence... more will surely come.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4001] = {title = "What Is Going On?", objective = "Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar.\n\nYou recall Gor'shak mentioning that Kharan is being held in a cell nearby.", description = "So far, my communication with the dwarf, Kharan, in the cell across the hall, has been limited. I have, however, managed to convince him that I, rather -we- mean him no harm.\n\nGo speak with him and gather as much information about the Princess and her captors as possible. Take that information back to the Warchief.\n\nThrall does not want the Princess harmed, but instead, has some grand plan laid out, which includes her being safely returned to Ironforge. Kharan already knows all of this... Go!", progress = "What brings you to these hallowed grounds?", completion = "This is a chance for the Horde to change the political climate of our war torn world forever. Listen carefully, &lt;name&gt;.\n\nFailure of this mission is not an option.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4002] = {title = "The Eastern Kingdoms", objective = "Speak with Thrall if you are prepared to take on the mission he has planned.", description = "You bring excellent information, <name>.\n\nAs Warchief, it is my duty to do what is best for the Horde. To ensure that the generations that come after us are not forced into a hopeless existence.\n\nThe opportunity to shape our future alliances has fallen into our collective laps. A move to help the dwarves could greatly strengthen our relationships in the Eastern Kingdoms. This, then, is why you must not fail!\n\nAre you prepared?", progress = nil, completion = "There is no going back beyond this point, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4003] = {title = "The Royal Rescue", objective = "Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell.", description = "This strike against the Dark Iron dwarves, if successful, will send a shockwave throughout their entire kingdom.\n\nPrincess Bronzebeard is under the control of Emperor Thaurissan. To free her, you must kill the Emperor. Be warned, your task is doubly dangerous, as Bronzebeard will attack you without question while under the control of the Emperor.\n\nDO NOT HARM HER!", progress = nil, completion = "What have you done!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4004] = {title = "The Princess Saved?", objective = "Return to Thrall!", description = "You have slain my husband, <race>! My child will be born into this world without a father.\n\n<Princess Moira points directly at you.>\n\nI assure you, this child will be the next ruler of the kingdom of Ironforge. You and your kind shall be hunted down until the end of days for this wrongful act.\n\n<You think that Princess Moira may be suffering from the residual effect of Thaurissan's spell.>\n\nLeave me be, <race>. I am certain your warchief will be eager to hear the results of his meddling.", progress = nil, completion = "&lt;Thrall is taken aback by the information you have presented to him.&gt;\n\nA new threat now looms on the horizon. As Magni's years dwindle down, the way shall be opened for this unborn Dark Iron to become ruler of Ironforge.\n\nYou have accomplished what I asked of you and for that, you shall be rewarded.\n\nNow leave me, &lt;name&gt;! I must confer with Sylvanas and Cairne.", rewards = "You will be able to choose one of these rewards:\n\nThrall's ResolveEye of Orgrimmar\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4005] = {title = "Aquementas", objective = "Take the Book of Aquor, the Silvery Claws, and the Irontree Heart to Tanaris.\n\nUse the Book of Aquor to summon Aquementas.\n\nAfter you have the completed totem, take it to J.D. Collie in Marshal's Refuge.", description = "Take this bag of supplies with you to Tanaris. Travel to Lost Rigger Cove, and look for a circle of stones.\n\nThe eastmost peninsula is the secret...\n\nFrom this circle only, read from the book of Aquor; summon the only creature that can transform the items you collected into a totem to fight Blazerunner.\n\nAquementas will not be pleased to be awakened, but remember, you must remain in the circle for him to transform the items.", progress = "So you're back, eh? Hmm... Let me take a look at that, <name>.", completion = "Blazerunner, you say...\n\nYes, I am aware that a strong elemental resides in the charred center of the crater. We all just keep our distance; none have been able to penetrate the powerful aura that surrounds him. Many have been pushed from the rocky paths onto the ground below when trying to face him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4021] = {title = "Counterattack!", objective = "Bring a Piece of Krom'zar's Banner to Regthar Deathgate, west of the Crossroads.", description = "The Horde commends your successes against the Kolkar, but the Kolkar themselves are maddened.  I have reports that a contingent of Kolkar has traveled to the Barrens from their home in Desolace, to seek vengeance.  My latest report was that, even now, they move against these bunkers, from the west!\n\nFace the Kolkar invaders, and end their threat in the Barrens.  Kill them until their leader, Warlord Krom'zar, appears.  Defeat him and bring me a piece of his banner as proof.\n\nWe're counting on you, <name>.", progress = "Do you have the banner?", completion = "You have done it!  You have defeated the Kolkar!\n\nI will be sure Thrall receives word of your actions here, &lt;name&gt;.\n\nStand tall.  You do yourself, and the Horde, proud.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4022] = {title = "A Taste of Flame", objective = "Show Cyrus Therepentous the Black Dragonflight Molt you received from Velarok Windblade.", description = "The flight is aware of your work in the Searing Gorge.\n\nShow it to me, <race>. The molt, imbecile.", progress = "<Cyrus's eyes form two blazing spheres.>", completion = "&lt;Cyrus examines the molt.&gt;\n\nYou have proven that you are not entirely useless, mortal.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4023] = {title = "A Taste of Flame", objective = "Show Cyrus Therepentous proof of your worth.\n\nYou have a feeling that Cyrus already knows that you are unworthy.", description = "You seek out the Flight? Present to me proof of your worth, mortal.", progress = "<Cyrus's eyes form two blazing spheres.>", completion = "&lt;Cyrus examines the molt.&gt;\n\nYou have proven that you are not entirely useless, mortal.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4024] = {title = "A Taste of Flame", objective = "Travel to Blackrock Depths and slay Bael'Gar.\n\nYou only know that the giant resides inside Blackrock Depths. Remember to use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence.\n\nReturn the Encased Fiery Essence to Cyrus Therepentous.", description = "I wish to taste the searing flames of the mountain of fire. To let the molten fires of Blackrock cascade across my being. That essence, that searing heat, it is what I crave.\n\nBael'Gar resides in the Depths of Blackrock: A being of pure flame, born of the fires of Ragnaros. Slay Bael'Gar and from his smoldering remains bring for me a piece of his inner fire.\n\nUse the molt on his remains to safely extract the inner flame.\n\nSucceed and be rewarded.", progress = "Has the giant been felled?", completion = "&lt;Cyrus snatches the fiery essence from your hands.&gt;\n\nYES!\n\nTake your prize and be gone. Leave my sight at once!", rewards = "You will be able to choose one of these rewards:\n\nShaleskin CapeWyrmhide SpauldersValconian Sash\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4041] = {title = "The Videre Elixir", objective = "Bring me an Evoroot, and sure, I can make ya that Videre Elixir.\n\nI know all kinds of things about herbs and alchemy... Why, let me tell you the story about the time I transmuted gold from the cheese I was going to eat for lunch... hey... Where are you going?", description = nil, progress = "Bring me an Evoroot, and sure, I can make ya that Videre Elixir.\n\nI know all kinds of things about herbs and alchemy... Why, let me tell you the story about the time I transmuted gold from the cheese I was going to eat for lunch... hey... Where are you going?", completion = "So, you pulled a fast one on ol' Miblon, eh?", rewards = "You will receive:\n\nVidere Elixir"}
MultiLanguageQuestData['en'][4061] = {title = "The Rise of the Machines", objective = "Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania.\n\nYou recall Theodora mentioning the golems and elementals of that region as being a source for these shards.", description = "The machines made themselves known to us during our initial forays into the Searing Gorge. Upon further investigation we discovered that they were being imported from Burning Steppes, possibly Blackrock Depths. That is what we need you for, <name>.\n\nYour first task is to venture to the Burning Steppes and recover elemental shards from the rock automatons and lesser rock creations of the region. Once you have collected a sufficient amount, return to me and I shall determine their source of origin.", progress = "Do not take this task lightly, <name>!", completion = "&lt;Theodora lays the fragments out before her.&gt;\n\n&lt;Theodora carefully examines the fragments with an enormous monocle.&gt;\n\nInteresting. Etched into the structural foundation of each of these fragments are... initials.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4062] = {title = "The Rise of the Machines", objective = "Take the Elemental Shard Sample to Lotwil Veriatus.\n\nYou recall Theodora saying that Lotwil was stationed in a camp to the east.", description = "G.L.A.\n\nThose are the 'initials' imprinted on the elemental shards. Below the initials are a rank marking of some sort. The machinations you destroyed in the Burning Steppes were of 'Rank IV.' I assume that this is a lowly rank.\n\nTake this shard sample to Lotwil Veriatus in the camp to the east. He is a scholar of some renown in the field of elemental sciences. He may be able to assist us in our search.", progress = "What have you got there, <race>?", completion = "&lt;Lotwil's face turns white.&gt;\n\nI... I know these markings.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4063] = {title = "The Rise of the Machines", objective = "Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach. You know this because you are psychic.", description = "This can't be Argelmach! Argelmach was killed ten years ago. How can I be sure? I was the one who killed him.\n\nHe was a despicable dwarf, hell-bent on twisting my life's work to meet his diabolical needs. It seems that the wicked always find a way to escape justice.\n\nIf this is Argelmach's handiwork then he must be destroyed. I will need samplings of his latest creations. With the proper samples, I may be able to stop this uprising. The creations guard Argelmach in Blackrock Depths.", progress = "Was it him? Was he really alive?", completion = "What is this?!? This head is not flesh. This is some sort of dark iron creation: A shadow of Argelmach - ANOTHER machine! I suspect that your destruction of Argelmach will be short lived as another shall rise to take 'its' place soon.", rewards = "You will be able to choose one of these rewards:\n\nAzure Moon AmiceRaincaster DrapeBasaltscale ArmorLavaplate Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4081] = {title = "KILL ON SIGHT: Dark Iron Dwarves", objective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete.", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nAny and all of General Angerforge's forces within Blackrock Depths must be annihilated.\n\nAngerforge's men are ruthless killers, responsible for the mass murder of the 109th division of the Kargath Expeditionary Force. Heroes are warned to exercise extreme caution when confronting these brutes.\n\nAny person who destroys the first line of General Angerforge's forces in Blackrock Depths shall receive a tribute.", progress = nil, completion = "This first strike should put a crease in Angerforge's pants. Now, move along soldier. I have work to complete, battles to plan, enemies to crush!\n\nCheck the wanted signs for more work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4082] = {title = "KILL ON SIGHT: High Ranking Dark Iron Officials", objective = "Venture to Blackrock Depths and destroy the vile aggressors!\n\nWarlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete.", description = "By order of Warlord Goretooth, commander of the Kargath Expeditionary Force:\n\nHead of the K.E.F. reconnaissance division, Grandmaster Lexlort, has returned with news of the whereabouts of high ranking Dark Iron officials. Through locked gate, near the heart of the city, they train their forces to snuff out our men. Travel to Blackrock Depths and destroy them!\n\nCompletion of this mission will result in a tribute.", progress = nil, completion = "Angerforge is undoubtedly... angry. Return to me when you receive a third tribute and we shall proceed with Operation: Death to Angerforge. I cannot go into any detail of what this entails, but rest assured, it involves somebody dying.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4083] = {title = "The Spectral Chalice", objective = "The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.", description = nil, progress = "The spectral chalice floats in the air, slowing rising and falling... as if to the beat of a dying heart.", completion = "The gems make no sound as they fall into depths of the chalice...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4084] = {title = "Silver Heart", objective = "Collect 11 Silvery Claws and 1 Irontree Heart for Eridan Bluewind in Felwood.", description = "I do not know the one you speak of, <name>.\n\nBut worry not; if your friend was on a journey to find me, I do know what it was he desired.\n\nIn the heart of Un'Goro Crater dwells evil of the purest form. This evil takes the shape of an elemental called Blazerunner... protected by an aura that none can dispel...\n\nNone... except those with enough power to do so. I can teach you of this power, <name>.\n\nFirst, do as I ask. Collect 11 Silvery Claws and 1 Irontree Heart from the creatures in Felwood, then return.", progress = "I can tell you more of the power required to defeat Blazerunner, but first, you need to gather the things I require.", completion = "Very well, &lt;name&gt;. I can see you are serious about helping your friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4101] = {title = "Cleansing Felwood", objective = "Bring 15 Blood Amber to Arathandris Silversky in Felwood.", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", progress = "I know Felwood suffers, <name> - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n&lt;name&gt;, the time has come to cleanse Felwood.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4102] = {title = "Cleansing Felwood", objective = "Bring 15 Blood Amber to Maybess Riverbreeze in Felwood.", description = "Plants give life to Felwood, yet even they suffer the taint of corruption.  I know ways to cleanse them, but I cannot give out such knowledge to those I don't know or trust.  Prove to me that you will truly aid the cause of the Cenarion Circle!\n\nTo the north lie the Irontree Caverns.  The Warpwood elementals present there are now beyond hope of cleansing.  I ask you to bring me their sap - blood amber it is called - so I may study it in the hopes of saving other forms of life here.", progress = "I know Felwood suffers, <name> - I suffer along with it!  I must remain steadfast in my conviction; were the knowledge I possess to fall into the wrong hands, it would spell disaster for all of Felwood.\n\nBring to me the blood amber drawn from the slain Warpwood elementals, and I will trust you enough to help me enact a means to fight the corruption.", completion = "This blood amber will be used to find a means of defeating the corruption present in Felwood.  You've proven to me that you're willing to do whatever it takes for the Cenarion Circle.  I trust you now, friend.\n\nIt might seem odd that killing the elementals proved yourself to me, but the end of saving countless sentient beings must justify the means we take.  You and I can now focus on the preservation of life through the salves I can make.\n\n&lt;name&gt;, the time has come to cleanse Felwood.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4103] = {title = "Salve via Hunting", objective = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", description = nil, progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, &lt;name&gt;!  Wherever they are, use the salve I have given you to purify them.", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4104] = {title = "Salve via Mining", objective = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", description = nil, progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make.", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4105] = {title = "Salve via Gathering", objective = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", description = nil, progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work &lt;name&gt; - every bit of this, once we purify it, will help us take back Felwood.  Here, take some doses of Cenarion plant salve and head into the forest.  The reclaiming of the land from the corruption waits for no &lt;race&gt;!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4106] = {title = "Salve via Skinning", objective = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", description = nil, progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need.  Here - take these plant salves and use them to reclaim Felwood from the corruption.  We must persevere, &lt;name&gt;!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4107] = {title = "Salve via Disenchanting", objective = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", description = nil, progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, &lt;name&gt;.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4108] = {title = "Salve via Hunting", objective = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", description = nil, progress = "Possessing a Cenarion beacon allows one to see a corrupted soul shard on those tainted beasts that are put down for the greater good.  I grind shards into a usable reagent that goes into making Cenarion plant salve.  We will use that salve to turn corrupted plants into healthy ones again.\n\nIn exchange for these shards, I will give you some Cenarion plant salves I have already prepared.", completion = "Very well then, here are your Cenarion plant salves.  Scour Felwood for corrupted plants, &lt;name&gt;!  Wherever they are, use the salve I have given you to purify them.", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4109] = {title = "Salve via Mining", objective = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", description = nil, progress = "If you possess a Cenarion beacon while mining in Felwood, you will be able to see tainted vitriol that corrupts a vein of raw metal.  I know how to purify that vitriol and turn it into a reagent that goes into making Cenarion plant salve.  You will then use that salve on plants you find in the wild that need saving.\n\nIf you have collected any tainted vitriol, I'll give you some Cenarion plant salve I have already prepared.", completion = "Very well then, here's some Cenarion plant salve.  If you find more vitriol when you mine in Felwood, remember to hold on to it for me!  The more of it you find, the more salve I will be able to make.", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4110] = {title = "Salve via Gathering", objective = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", description = nil, progress = "A Cenarion beacon allows a seasoned herbalist to spot insidious fel creep - a malfeasant product of Felwood's corruption.  My work here has taught me the knowledge of purifying fel creep into a cleansing reagent... used in what we now refer to as Cenarion plant salve.\n\nWhen you gather herbs in Felwood, you should encounter the fel creep so long as you have the beacon.  In exchange for what you bring to me, I will give you pre-made Cenarion plant salve.", completion = "Excellent work &lt;name&gt; - every bit of this, once we purify it, will help us take back Felwood.  Here, take some doses of Cenarion plant salve and head into the forest.  The reclaiming of the land from the corruption waits for no &lt;race&gt;!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4111] = {title = "Salve via Skinning", objective = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", description = nil, progress = "A Cenarion beacon will allow a well-trained skinner to spot patches of tainted skin from bounty gathered in Felwood.  I convert these seemingly useless patches into a thick paste that serves as a quickening agent for Cenarion plant salve.  When you skin your kills here in Felwood, be sure to have a beacon on you!\n\nWhen you collect tainted patches, bring them to me and I will give you some Cenarion plant salves that I have already made.", completion = "This is exactly what I need.  Here - take these plant salves and use them to reclaim Felwood from the corruption.  We must persevere, &lt;name&gt;!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4112] = {title = "Salve via Disenchanting", objective = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", description = nil, progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, &lt;name&gt;.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][4113] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4114] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4115] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4116] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4117] = {title = "Corrupted Whipper Root", objective = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4118] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4119] = {title = "Corrupted Night Dragon", objective = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a night dragon plant.  The fruits that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply four Cenarion plant salves to the night dragon.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4120] = {title = "The Strength of Corruption", objective = "Talo Thornhoof at Camp Mojache in Feralas wants you to kill 12 Angerclaw Grizzlies and 12 Felpaw Ravagers in Felwood.", description = "Being a hunter, I strive to emulate the strengths I see in my opponents. It is possible to turn the battle in your favor by simply knowing your enemy well, <name>.\n\nIn a place called Felwood, north of Ashenvale, the creatures have been tainted by a substance called fel. The bears and wolves have been driven mad by it, but I believe that they have also grown even stronger as well.\n\nGo, <name>. Travel to Felwood and face these beasts. Learn for yourself if they are truly as strong as I believe.", progress = "Everything touched by the fel emanates a strange green glow... I sense it is evil, but at the same time, very powerful.", completion = "It sounds from your descriptions as if the creatures show a mindless ferocity...\n\nStay alert, &lt;name&gt;. It would be in your best interest to learn more of the corruption. Always know your enemy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4121] = {title = "Precarious Predicament", objective = "Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge.\n\nYou recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody.\n\nYou will also be required to hand over your Thorium Shackles to Lexlort.", description = "Do you truly believe that you will make it to your rendezvous point with me in custody? You actually expected to break into a heavily fortified Blackrock fortress to capture a prized asset of theirs without alerting anyone or anything to your presence?\n\nYou will be destroyed!", progress = "I will take this traitorous filth, <name>.", completion = "Your heroics will not go unrecognized, &lt;name&gt;. You have earned this tribute. The Warlord will speak with you now in regards to the final mission.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4122] = {title = "Grark Lorkrub", objective = "Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress.\n\nWhen you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody.\n\nProvided item: \n", description = "I tracked him across the Searing Gorge, through the mountain, and into the Burning Steppes. That traitor was caught red-handed giving the Blackrock orcs vital information about our day to day operations. I'm speaking of Grark Lorkrub.\n\nHe now sits in the Burning Steppes, safely under their protection - or so he thinks.\n\nTake these shackles, <name>. Find Grark, place the shackles on him and lead him through Blackrock Mountain. Do this and a tribute is yours.", progress = nil, completion = "Can you not see the power we gain by joining the legion of Blackrock?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4123] = {title = "The Heart of the Mountain", objective = "Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes.", description = "For years I have sought a certain gem.  It is called the Heart of the Mountain and it's the size of your fist!  The Dark Iron dwarves have it locked in their vault and, try as I may, they won't let me purchase it.\n\nSo I must resort to force.\n\nFight your way to the Lower Vault of Blackrock Depths, breach its secret safe and gain the Heart.  To do that, you must defeat Watchman Doomgrip, and he won't appear until you've opened every relic coffer in the vault!\n\nGood luck.", progress = "Do you have the Heart of the Mountain?  To me, its value is without limit.", completion = "You have the heart!  Amazing!  It is even more beautiful than I imagined!\n\nPlease, &lt;name&gt;, take this as payment!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4124] = {title = "The Missing Courier", objective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", description = "An associate of mine, Ginro Hearthkindle, is looking for assistance concerning the location of a courier and the parcels he was carrying.  It has been a week or so since the courier went missing; our own searches have proved fruitless, and we're at an impasse.  Unfortunately, I have had to declare the courier as missing in action.\n\nIf you have the time and resources to spare, please speak with Ginro.  He should be here in the Stronghold - perhaps in his quarters.", progress = nil, completion = "Latro sent you to me, I presume.  While I think it is a lost cause at this point, I'll take whatever assistance you can offer.  I must admit... I'll be glad once I can put my mind to rest on this matter.  Every day I set out into the wilds of Feralas looking for signs of Raschal, and every night I have come back with nothing to show for my work save gnoll teeth and disappointment.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4125] = {title = "The Missing Courier", objective = "Locate the courier's boat somewhere along the coast of Feralas.", description = "It's been about a week since Raschal, the courier, set out for Thalanaar.  He knows Feralas well; he's been with us since General Feathermoon led the expeditionary forces here.  I know his plan was to take a row boat down the coast and try and traverse across southern Feralas to avoid the Horde camp.\n\nI couldn't find his boat, but maybe you can.  Maybe it is hidden, or maybe it was sunk.  Regardless, it might hold a clue as to where he is.  If you uncover something, please let me know.", progress = nil, completion = "You have found what appears to be a wrecked row boat.  Through the slightly muddy water you see gaping holes riddling the port side; the boat is nearly shredded down to its simple wooden frame.  Whatever broke this boat most likely tried to snap it in two.  A small crest of the Feathermoon Stronghold is painted on the starboard side.\n\nIn the mud at the base of the boat, a glint of something metallic catches your eye...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4126] = {title = "Hurley Blackbreath", objective = "Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos.", description = "The Dark Iron dwarves, led by the villain Hurley Blackbreath, stole one of the Thunderbrew's best recipes, Thunderbrew Lager.  The villains!  They don't deserve such a fine brew!\n\n<name>, I have a tough task for you.  Go to the Blackrock Depths in the Burning Steppes, destroy any kegs of Thunderbrew Lager you find, and bring back our recipe for Thunderbrew Lager!\n\nPlease, get that recipe back, even if you have to turn Blackrock Depths upside down to do it!", progress = "Do you have the recipe, <name>?  I can't stand the idea of those Dark Iron dwarves drinking my family's drink!", completion = "You found it!  Well done!  And I hope you gave those Dark Irons, and Hurley Blackbreath, a good thumping!\n\nThe Thunderbrews are at your service, &lt;name&gt;.  You are a hero of heroes!", rewards = "You will be able to choose one of these rewards:\n\nSwiftstrike CudgelLimb Cleaver\n\nYou will also receive:\n\nDark Dwarven Lager"}
MultiLanguageQuestData['en'][4127] = {title = "Boat Wreckage", objective = "Return to Feathermoon Stronghold and show Ginro Hearthkindle the Discarded Knife you have found.", description = "Running your hand along the mud, your fingers graze the handle of a knife.  It looks well cared for, and it might be safe to assume that whoever was on the boat might have lost it.  Perhaps the large chunk of the missing boat might have something to do with the loss.\n\nYou grab the knife, remembering that Ginro Hearthkindle in the Feathermoon Stronghold instructed you to return to him with any found clues.  You get the feeling, however, that you are not quite alone in the water...", progress = "Ah, welcome back <name>.  I hope that you were able to uncover some clue as to Raschal's ultimate fate, as tragic as that may be.", completion = "Interesting... I believe that this is Raschal's knife.  You say you found it at the bottom of the water, along with his boat?  Well, just the knife's discovery might not be enough to connect this to Raschal's disappearance; we do, however, have an unconventional option available to us to try and learn more.\n\nHave you ever heard of psychometry?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4128] = {title = "Ragnar Thunderbrew", objective = "Speak with Ragnar Thunderbrew.", description = "Ho, <name>.  I heard that Ragnar Thunderbrew is steaming mad about someone stealing his ale.  He's looking for stalwart adventurers, and willing to pay plenty.\n\nTalk to Ragnar if you're interested.  He's at the Thunderbrew Distillery in Kharanos, in Dun Morogh.", progress = nil, completion = "You're right I'm mad!  I've been robbed!  Robbed of one of our family recipes!  How dare they!  As if I didn't have enough cause to hate the Dark Iron dwarves!  Now, oh... now they're in for it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4129] = {title = "The Knife Revealed", objective = "Take the Discarded Knife to Quintis Jonespyre in Feathermoon Stronghold.", description = "The Stronghold's resident druid, Quintis Jonespyre, has some... unusual skills.  One of them involves psychometry - the ability to reveal an item's history by touch.  Don't ask me how he does it; I chalk it up to magic I do not and choose not to understand.  I do know, however, two things: one, I've seen it work and two, the bum owes me.\n\nTake the knife up to Quint in his little tree-house here, and tell him for me that his Kalimdor Hold 'Em debt will be paid if he works his mojo on that knife.", progress = "Ginro sent you, eh?\n\nMy psychometric readings are fairly draining on the psyche... but so are my losses at Kalimdor Hold 'Em.  They call me \"King of the Bad Beats\" here in the Stronghold.  Unlucky at cards... lucky at mastering the secrets of nature, I guess.\n\nAnyway, of course I'll do it.  This may be just the breakthrough we need to uncover Raschal's fate.  If you would hand me the knife, we can get started.", completion = "Thank you, &lt;name&gt;.\n\nWhile psychometry isn't an exact art by any stretch of the imagination, I've used it in times past to give insight into situations that others have chalked up to lost causes.  I think using it on the knife you've uncovered will give us a glimpse into what happened to Raschal.\n\nIt will only take a moment to do, but it isn't what I'd call a caster-friendly task.  Bear with me on this.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4130] = {title = "Psychometric Reading", objective = "Speak with Ginro Hearthkindle in Feathermoon Stronghold.", description = "I'm a little wobbly still, sorry.  Anyway, I received some useful visions.\n\nRaschal takes two large leather backpacks from his boat and goes inland; he returns to the boat, however.  I see gnoll scalps... he ran into some gnolls - Woodpaw I think they're called.  He's very worried - almost terrified - about something.  So much so, that he is not paying attention to water elementals forming behind him.  The images... stop there.\n\nI need to rest, sorry <name>.  Tell Gin what I've seen.  He needs to know.", progress = nil, completion = "Thanks for passing along Quint's visions to me, &lt;name&gt;.  I'll try to remember to be a little easier on him the next time we play cards.\n\nRaschal can hold his own in a fight, and gnolls aren't anything that would get him worried - nay, terrified.  Still, maybe you and yours can act on this new information and make the breakthrough we desperately need.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4131] = {title = "The Woodpaw Gnolls", objective = "Search the Woodpaw Gnoll camps of southern Feralas for evidence of the courier's belongings or the courier himself.", description = "Our \"friends\" the Woodpaw might have gotten Raschal in the end, but something tells me that's not what occurred.  Still, they're the best place to start looking.\n\nI wish I had clearer insight as to what to do, but all I have right now is 'Search the Woodpaw camps - go.'  I do know that gnolls will keep items they scavenge and fight over them; maybe they ran across the backpacks Quint mentioned.  I hadn't risked a head-on fight in past searches, but with Quint's vision on this I say rip into them.", progress = nil, completion = "Tacked up on a nearby tree are two large leather backpacks.  Each bears a small insignia of the Feathermoon Stronghold on the front of the pack...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4132] = {title = "Operation: Death to Angerforge", objective = "Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete.", description = "You have done an exemplary job, <name>. It is now time to send you on your last mission.\n\nGeneral Angerforge, the Dark Iron responsible for coordinating the attacks on the 109th division of the K.E.F. and the mass slaughter of our forces must be brought to justice.\n\nThis will undoubtedly be your most grueling mission, but should you succeed, you will be richly rewarded.", progress = "Has the Butcher of Blackrock been disposed of?", completion = "Finally! The villain been brought to justice! You are a remarkable individual, &lt;name&gt;. Wear this medallion as a symbol of your stalwart dedication to the Horde and the K.E.F.", rewards = "You will receive:\n\nConqueror's Medallion"}
MultiLanguageQuestData['en'][4133] = {title = "Vivian Lagrave", objective = "Speak with Shadowmaster Vivian Lagrave in Kargath.", description = "Shadowmaster Vivian Lagrave is in need of your services.  She is in the Badlands, in the orcish outpost of Kargath, pursuing rumors of a certain brew made by the Dark Iron dwarves of Blackrock Depths.\n\nSpeak with Vivian.  She awaits you.", progress = nil, completion = "Thank you for coming, &lt;name&gt;.  This place is not without a stark charm, but it lacks the amenities of the Apothecarium.\n\nEnough with the pleasantries.  To business, yes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4134] = {title = "Lost Thunderbrew Recipe", objective = "Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath.", description = "It is rumored that the Dark Iron Hurley Blackbreath has stolen a recipe for ale.  This ale, Thunderbrew Lager, is said to infuse its imbiber with great strength and courage.  We wish to study the drink.  Perhaps, we will find other applications for its virtues... applications more in line with Forsaken objectives.\n\nDelve into Blackrock Depths, find Hurley, take from him the recipe for Thunderbrew lager and bring it to me.\n\nAnd to find him, you may have to entice him by threatening his precious ale.", progress = "Do you have the recipe for the Thunderbrew Lager, <name>?", completion = "Very good.  I will send this recipe to the Apothecarium to be studied, and in time we will unlock its secrets.  One day, the dwarves of the Alliance may find the virtues of this drink used against them!\n\nI find that terribly amusing.  Perhaps death has an affect on one's sense of humor... do you think?", rewards = "You will be able to choose one of these rewards:\n\nSwiftstrike CudgelLimb Cleaver\n\nYou will also receive:\n\nSuperior Healing PotionGreater Mana Potion"}
MultiLanguageQuestData['en'][4135] = {title = "The Writhing Deep", objective = "Now that Raschal's last known whereabouts have been discovered, continue your search for him or his remains in the Writhing Deep. According to the note, it is located to the south of the Woodpaw gnoll camps.\n\nProvided item: \n", description = "Inside the backpacks are two items: the first is a parcel of goods that was bound for Thalanaar, and the second is a note hastily penned to an unknown reader.\n\nThe note tells of discovering insidious bug-like creatures south of the gnoll camps in a place called the Writhing Deep.  The author felt the need to investigate it personally, as though it was a serious threat to all of Feralas.  The note is signed, \"Raschal of Feathermoon\".\n\nIt would seem that you have located where Raschal ultimately went.", progress = nil, completion = "You have discovered a large pod of an alien nature.  The texture of the pod appears mucous, though hardened protrusions stick out from random parts of it.  The pod itself has the height and width to easily encompass a humanoid inside of it... and from the faint humanoid shape visible through the skin of the pod, you surmise that this is what it indeed encapsulates.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4136] = {title = "Ribbly Screwspigot", objective = "Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes.", description = "My brother Ribbly has always been a drain to his family, taking our money and wasting it on one scheme after another.\n\nWell, his last scheme must have been his worst, because Baron Revilgaz of Booty Bay just put a price on poor Ribbly's head.  I can't tell you how happy this makes the Screwspigots!  Our little Ribbly's finally worth something!\n\nBut now he's hiding out, deep in Blackrock Depths.  Please, find him and bring him to me!\n\nOr, if he won't come, then that's ok... just bring me his head.", progress = "Do you have Ribbly?  Or, at least a part of him?", completion = "Aha!  You found him!  And... it appears that my little brother didn't want to come quietly.  It's a pity.  I would have liked to see the look on his face when I told him our plans to turn him in to Revilgaz.\n\nThank you, &lt;name&gt;.  You've made my family very happy.  And Ribbly's never looked as peaceful as he does now.", rewards = "You will be able to choose one of these rewards:\n\nRancor BootsPenance SpauldersSplintsteel Armor\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4141] = {title = "Muigin and Larion", objective = "Collect 15 Bloodpetals and return to Muigin.", description = "See Larion over there? It's HIS fault we're here!\n\nI told him we were going the wrong way, but would he listen? And would you believe that he's the one that won't speak to me? Well, until he changes his mind, let's have a bit of fun with him.\n\nHave you noticed the strange plant-like creatures around here? They're nothing but trouble, really, but I think if trained properly, I could get them to obey commands.\n\nFirst thing though, I'll need some samples to study. Do you think you could collect some?", progress = "Larion's got something coming, that's for sure!", completion = "I hope they didn't give you too much trouble, &lt;name&gt;. I try to steer clear of them -- they're wild!\n\nI tried jumping over one... I was attacked! Plants just shouldn't be acting that way!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4142] = {title = "A Visit to Gregan", objective = "Take a Bloodpetal to Gregan Brewspewer in Feralas.", description = "I'm not quite sure what to make of this, <name>. The plants... they seem to have some minimal intelligence.\n\nI'm no expert, though. But, I do know someone that is!\n\nHead to northern Feralas, and look for a buddy of mine named Gregan Brewspewer. He's an expert on this sort of thing.\n\nI'm sure Gregan can help us out here. You'll find him out in the wilderness; he's not the type to live in a big city.", progress = "I live out here in the forest... Peaceful.\n\nWell, at least I thought it would be. I get more visitors out here than I ever did when I lived in Ironforge!", completion = "Bloodpetal, eh? Hmmm... Well, you better explain the plan, and then I'll tell you whether or not I can help you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4143] = {title = "Haze of Evil", objective = "Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater.", description = "To tell you the truth, <name>, I've never seen any plants like this in my travels. Perhaps I should take a trip to this crater...\n\nAt any rate, I think I know just the thing Muigin's looking for -- Atal'ai haze. It's horrid stuff, hard to collect, but it's just what he needs to control the little monsters.\n\nYou'll need to visit the temple of Atal'Hakkar in the Swamp of Sorrows. The Atal'ai haze can be collected from the deep lurkers, murk worms, or oozes found there. Good luck, <name>!", progress = "Larion's still not speaking to me! He sure knows how to hold a grudge.", completion = "I admit, I'm a bit hesitant to touch that stuff, &lt;name&gt;! But if Gregan says it'll work, then I'm willing to give it a try!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4144] = {title = "Bloodpetal Sprouts", objective = "Here's the plan, <name>: Go out and collect some bloodpetal sprouts -- you know, the plants that haven't fully sprouted yet, and bring them here. Then I'll see what the Atal'ai haze can do.\n\nYou may think I'm vengeful... Actually, you'd be right about that! \n\nTruth is, I know the way out of here, but until Larion will admit that I'm right, I'm staying right here!\n\nSo off with you, find those bloodpetal sprouts and let's have some fun!", description = nil, progress = "Here's the plan, <name>: Go out and collect some bloodpetal sprouts -- you know, the plants that haven't fully sprouted yet, and bring them here. Then I'll see what the Atal'ai haze can do.\n\nYou may think I'm vengeful... Actually, you'd be right about that! \n\nTruth is, I know the way out of here, but until Larion will admit that I'm right, I'm staying right here!\n\nSo off with you, find those bloodpetal sprouts and let's have some fun!", completion = "Here goes nothing, &lt;name&gt;! This will get Larion's attention!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4145] = {title = "Larion and Muigin", objective = "Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge.", description = "See Muigin over there? It's HIS fault we're lost!\n\nI'm the one that knew the way, but he insisted he knew a shortcut, and we ended up here!\n\nTo make matters worse, now he keeps sending his crazy plant pests to annoy me. I'm so angry that I'm not planning on talking to him any time soon, but these pests are too much to handle.\n\nWhy don't we try to limit his supply, first thing. Go out and hunt some Bloodpetals, then return to me.", progress = nil, completion = "Thanks for your help, &lt;name&gt;, but I'm afraid I have some bad news...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4146] = {title = "Zapper Fuel", objective = "Deliver the Unloaded Zapper and 5 samples of Atal'ai Haze to Larion in Marshal's Refuge.", description = "You're in luck, <name>! I've been working on some of my own experiments while Marvon's been gone, and one of them is a short range bug zapper. With just a few adjustments, it should be great for ridding yourself of those Bloodpetal pests.\n\nI can let you have one of my zapper prototypes, but you'll still need to collect the fuel. You can get the necessary Atal'ai haze that the zapper needs in the temple of Atal'Hakkar. The deep lurkers, murk worms, or oozes are the ones you'll need to get it from.", progress = "This is exhausting, <name>. Those things just won't leave me alone!", completion = "So, Marvon wasn't around? Well, show me what you got, anyway.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4147] = {title = "Marvon's Workshop", objective = "Travel to Marvon Rivetseeker's workshop in Ratchet.", description = "I managed to spy on what Muigin was doing, and he's actually growing the darn things over there!\n\nI think the only solution here is to... no, not go talk to him... What are you thinking? The solution is to fight back!\n\nWe'll need the help of my friend, Marvon, who has a workshop in Ratchet.  I'm sure he'll be able to create some sort of gadget that will help us.", progress = nil, completion = "Marvon's been gone quite a long time now, &lt;name&gt;. He went off to Tanaris to study some of the ancient troll ruins.\n\nNow, what was it that you said you needed?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4148] = {title = "Bloodpetal Zapper", objective = "For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin's little friends...\n\nIf he weren't so stubborn, we could be on our way home, already... But until then, I'll just have to show him that his little prank doesn't bother me at all!", description = nil, progress = "For the zapper to work, it needs a sample of the target creature. Head out into the crater and collect a Bloodpetal sprout. Then I can calibrate it to work on Muigin's little friends...\n\nIf he weren't so stubborn, we could be on our way home, already... But until then, I'll just have to show him that his little prank doesn't bother me at all!", completion = "Looks like this is going to work perfectly, &lt;name&gt;. Now remember, if you see any of those pests around, don't hesitate to use that zapper!", rewards = "You will receive:\n\nBloodpetal Zapper"}
MultiLanguageQuestData['en'][4161] = {title = "Recipe of the Kaldorei", objective = "Collect 7 Small Spider Legs for Zarrin in Dolanaar.", description = "Long ago, the night elves were called the kaldorei, a name that means \"children of the stars.\" Learning of the past is an important step in your path as a <class>, <name>, so listen well to what I have to tell you.\n\nThe kaldorei have always taken much pride in their harmonious relationship with nature. This means that we only take from nature what is necessary, and that we return in kind. This balance has afforded us much, <name>.\n\nGo out and collect seven small spider legs -- no more than that, and return to me.", progress = "Remember the balance, <name>. I wish you to develop an understanding and a strong empathy for the living forests.", completion = "Always remember what I have shown you today, &lt;name&gt;. You are part of the balance that the night elves strive to keep intact, even during troublesome times.", rewards = "You will receive:\n\nRecipe: Kaldorei Spider KabobKaldorei Spider Kabob"}
MultiLanguageQuestData['en'][4181] = {title = "Goblin Engineering", objective = "If you wish to learn more about Goblin Engineering, take the Manual of Engineering Disciplines to Nixx Sprocketspring in Gadgetzan.", description = "Expert engineering yields two distinct disciplines: gnome and goblin.  I only bother to mention goblin engineering because I'm a fair trainer.  They like to make things that blow up, and they rarely care what is in the way - even themselves.\n\n<name>, read this manual.  If you want to learn how to blow yourself up, then take it to Nixx Sprocketspring in Gadgetzan.   Remember - membership is permanent and prevents joining the other discipline, so make sure this is what you want before finishing his task.", progress = "I can smell fresh recruits much like I can an excellent blasting powder - from a mile away.  Have you come seeking to learn about the mastery of the explosion?", completion = "Well &lt;name&gt;, you were wise to seek my tutelage!  Any schlep can become an expert at the basics of engineering - the gnomes and their irradiated home of Gnomeregan are proof of that.  It takes a strong mind and a steady hand (emphasis on STEADY) though to master the discipline of Goblin Engineering.\n\nKeep your ears perked &lt;name&gt;, and you might learn something.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4182] = {title = "Dragonkin Menace", objective = "Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete.", description = "Life in the Burning Steppes is rife with conflict.\n\nJust look at this place! We know very little of what happened to these buildings, but we do know that at one time, before the great explosion, this was all part of the Redridge mountain range.\n\nEnough lamenting! We have a problem, <name>. You may have noticed the dragonkin below this ridge. We need assistance in pushing them back. Kill as many as you can and return to me. Succeed and perhaps we can talk of other things.", progress = "How goes the dragon hunt?", completion = "Superb slaying, &lt;name&gt;. Now that we know you can handle yourself around dragonkin, we can talk of more pressing matters.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4183] = {title = "The True Masters", objective = "Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon.", description = "We had always assumed that the Blackrock orcs were a product of their savage upbringing. What we have found here, in their homeland, tells us another story.\n\nIndeed, it is bloodlust and thirst for conflict that empowers them, but the black dragonflight are the beings whom control the orcs of Blackrock. We suspect that it is the black dragonflight that fuels them with rage and hostility.\n\nTake this letter to Magistrate Solomon. He will know what must be done.\n\n<Helendis hands you a sealed letter.>", progress = "Greetings, <name>. Have we met before? You look vaguely familiar.", completion = "&lt;Magistrate Solomon opens the sealed letter from Helendis and begins reading.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4184] = {title = "The True Masters", objective = "Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon.\n\nBolvar resides in Stormwind Keep.", description = "This is grim news, <name>. To discover that our mortal enemies are merely pawns of a much greater threat is disheartening. There is no possible way that Lakeshire could survive an attack from both the Blackrock orcs and the black dragonflight. Should Lakeshire fall to this menace, Darkshire would fall next, and then what? Goldshire? Stormwind itself?\n\nYou must take this information to Highlord Bolvar Fordragon in Stormwind at once! If this does not merit the aid of Stormwind, nothing will and all is lost.", progress = "What brings you to Stormwind Keep?", completion = "Dragons? Impossible!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4185] = {title = "The True Masters", objective = "Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor.", description = "Solomon paints a dreary picture. Still, we cannot afford to send our thinly spread troops to the aid of Lakeshire on speculation. I will need proof of these claims before I can act.\n\nSpeak with Lady Prestor, <name>. She is a learned woman and knows much of dragons and dragonkin. She may be able to shed some light on this situation.", progress = "<Bolvar watches you intently.>", completion = "&lt;Bolvar cups his chin as if in deep thought.&gt;\n\nWhile I respect Lady Prestor's stance, I believe that there is a solution to this dilemma that may put all of our concerns to rest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4186] = {title = "The True Masters", objective = "Take Bolvar's Decree to Magistrate Solomon in Lakeshire.", description = "I am going to empower you as an acting deputy of Stormwind, <name>.\n\nReturn to Magistrate Solomon in Lakeshire and deliver this decree.", progress = "Any news from Bolvar?", completion = "It could have been worse, I suppose...\n\n&lt;Magistrate Solomon looks you over.&gt;\n\nIt appears as if the fate of Lakeshire rests squarely on your shoulders.\n\n&lt;You notice Magistrate Solomon blinking rapidly. He appears to be crying.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4201] = {title = "The Love Potion", objective = "Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths.", description = "Oh, the pains of love!  My dear Private Rocknot is immune to my charms.  I am spurned!  It's maddening!\n\nYou must help me!  We succubi know much of love, and I can make a potion to beat down the iron walls around Rocknot's heart.  To make it, I need these items: the herb gromsblood, giant silver veins from the cliff giants of Azshara, and water from the Golakka Springs Crater in Un'Goro.  You can place the water in this vial.\n\nPlease, <name>, help a poor soul in her quest for happiness!", progress = "Do you have the ingredients?  The hole in my heart threatens to consume me!", completion = "Oh, you've done it!  I can now make my potion and use it on Rocknot.  Finally, he will fall victim to my charms!\n\nThank you, &lt;name&gt;.  You are a champion of love!", rewards = "You will be able to choose one of these rewards:\n\nManacle CuffsNagmara's Whipping Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4221] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4222] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4223] = {title = "The True Masters", objective = "Speak with Marshal Maxwell in the Burning Steppes.", description = "<Magistrate Solomon sighs.>\n\nYou must return to the Burning Steppes, <name>. As a deputy of Stormwind, you will be required to report to Marshal Maxwell. Good luck.", progress = nil, completion = "&lt;Marshal Maxwell laughs.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4224] = {title = "The True Masters", objective = "Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task.\n\nYou recall Marshal Maxwell telling you to search for him in a cave to the north.", description = "What? You thought you were the first? How many soldiers must we lose before Stormwind acts?\n\nWe had accumulated enormous amounts of intelligence pertaining to the Blackrock menace before we lost our commanding officer, Marshal Windsor. With Marshal Windsor went all of our precious information.\n\nWhat we need is that documentation. Speak with Ragged John, <name>. He was with Windsor when they were attacked by a Blackrock raiding party.  He was last seen in a cave to the north.", progress = "Have you spoken with John yet?", completion = "I could have warned you, but what fun is that?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4241] = {title = "Marshal Windsor", objective = "Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor.\n\nYou recall Ragged John talking about Windsor being dragged off to a prison.", description = "So that good for nothing coward says that Windsor is alive, eh?\n\nSuit up, deputy, you are going in to find him. If Windsor is alive, you are to bring him back. If he's dead, I want proof.\n\n<Maxwell laughs.>\n\nI bet you are getting tired of hearing that, aren't you?", progress = nil, completion = "Where is he! I'll murder him!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4242] = {title = "Abandoned Hope", objective = "Give Marshal Maxwell the bad news.", description = "Bolvar is a fool. I was gathering his precious 'proof' so that I could shove it down his throat.\n\nHe is a blind buffoon. Proof stands two feet away from him and he does not see.\n\nAs for my data, it's lost. Gone. Unrecoverable.\n\nShould I ever find Ironfoe and make it out of this labyrinth, my first stop will be Stormwind, to place my hammer in between that reptile's eyes.\n\nLeave me, <name>.", progress = nil, completion = "He's gone mad, apparently.\n\n&lt;Maxwell lowers his head in mourning.&gt;\n\nIt is unfortunate that a once proud and noble warrior would be turned into a blithering head case. I GUESS we've reached a dead end...\n\nI must reward you for your efforts thus far, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nConservator HelmShieldplate SabatonsWindshear Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4243] = {title = "Chasing A-Me 01", objective = "Find A-Me 01 in Un'Goro Crater.", description = "Unfortunately, something's happened to one of my greatest inventions. You've seen mechanical squirrels, yes? Well, to get closer to the apes of Un'Goro Crater, I created a mechanical ape to blend in with their kind--I call her A-Me 01.\n\nShe has scrying gems for eyes so I could see everything she saw. She made it to Fungal Rock--the apes' lair--just east of here, and that's when I lost contact. The last thing I saw was one of their alpha males rushing up to say hello to her!\n\nCan you help me find her?", progress = nil, completion = "As you look A-Me 01 over, you see two huge dents tarnishing what Karna obviously feels is a well-crafted piece of engineering. One dent decorates A-Me 01's shoulder, the other is on her head.\n\nNo power seems to be running through her components as you investigate further.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4244] = {title = "Chasing A-Me 01", objective = "Find a Mithril Casing and return to A-Me 01 in Un'Goro Crater.", description = "A little further investigation shows a panel that slides open. Clearly written above some wiring is the statement, \"Replace Mithril Casing And Turn Power Off Then On.\"\n\nTaking a moment to replace the panel, you wonder if it'll be that simple to fix A-Me 01 and get her back to Karna Remtravel near Marshall's Refuge.\n\nOnly trying it will tell.", progress = "The panel in which the mithril casing goes is still closed shut. The rest of A-Me 01 remains inert.", completion = "You remove the panel from A-Me 01's back yet again and carefully remove the old mithril casing that seems to have burnt out. The new one slides into place easily. The only thing left to do, assuming the mithril casing was the problem, is to flip the switch to the \"Off\" position, and then back to the \"On\" position.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4245] = {title = "Chasing A-Me 01", objective = "Escort A-Me 01 back to Karna Remtravel in Un'Goro Crater.", description = "Checking to see if you're prepared to lead A-Me 01 back to Karna Remtravel, you flip the switch to the \"Off\" position. Glancing around once again to make sure none of the gorillas are coming, you prepare to see what happens when you flip the switch back to the \"On\" position.\n\nThis is your last chance... are you sure this is what you want to do?", progress = "Have you been able to help A-Me? That mithril casing you mentioned being destroyed was a good guess at what was wrong. I'm sure if you replace that, she'll reactivate and be able to come home.", completion = "Oh, you've done it! Wonderful! Thank you, &lt;name&gt;.\n\nOh, my poor, A-Me. Look at all those dents. We'll get her up and running perfectly with just a little work.\n\nThank you again, &lt;name&gt;. I really appreciate it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4261] = {title = "Ancient Spirit", objective = "Escort Arei to safety, then speak with Kayneth Stillwind in Forest Song, in eastern Ashenvale.", description = "Felwood was once a peaceful and serene land... Until the legion took hold. The infernals, destruction, chaos...\n\nThe skull of Gul'dan ensured that none were spared here. All fell to the corruption.\n\nEven now, as a spirit, I still find myself trapped, bearing the suffering of this land. Help me find my way home. Please, <name>, tell me you will lead an ancient spirit away from here, where I may finally rest.\n\nOnce I am free, seek out Kayneth Stillwind, a druid that resides in Forest Song, to the east.", progress = nil, completion = "Yes, &lt;name&gt;. Felwood has been through much hardship. Thank you for what you have done.\n\nOne day, we may be able to reclaim Felwood from the corruption; every kind deed helps.", rewards = "You will be able to choose one of these rewards:\n\nEthereal Mist CapeClouddrift Mantle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4262] = {title = "Overmaster Pyron", objective = "Slay Overmaster Pyron and return to Jalinda Sprig.\n\nYou recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?", description = "The last five of my mages that went snooping around in Blackrock Mountain came back extra crispy with a permanent orange gnomefro - or worse.\n\n<Jalinda picks up some ashes from the ground and releases them into the air.>\n\nOne nasty bugger in particular, Overmaster Pyron, seems to be causing quite a bit of trouble. We need that elemental terminated so that our expedition crew can make its way into Blackrock Depths!\n\nHe guards the entrance at the Blackrock Quarry.", progress = "<Jalinda appears to be staring at your head.>", completion = "Incendius? Oh dear...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4263] = {title = "Incendius!", objective = "Find Lord Incendius in Blackrock Depths and destroy him!", description = "Are you sure Pyron said 'Incendius' when he died?\n\n<Jalinda swallows hard.>\n\nLord Incendius is purported to be a minion of Ragnaros! Oh dear, oh dear... whatever will we do?\n\nDo you think you can handle another mission? I don't have anybody else to send, <name>!\n\nWe will never get a team in if Incendius continues to raise Pyron from the ashes.\n\nYou'll have to find and destroy Lord Incendius!", progress = nil, completion = "Oh dear! Are you sure Incendius said 'Ragnaros?'\n\n&lt;Jalinda hands you something and pats you on the wrist as she fades deep into thought.&gt;", rewards = "You will be able to choose one of these rewards:\n\nSunborne CapeNightfall GlovesCrypt Demon BracersStalwart Clutch\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4264] = {title = "A Crumpled Up Note", objective = "You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all.", description = "The note has stains covering its surface. The text is barely legible, but you make out the following:\n\n...sweet irony...\n\n...the fall of the broken Alliance...\n\n...if it were not for General Angerforge's diligence, we may have never discovered the pattern to the encryption...\n\n...Argelmach is almost done with the decryption of Windsor's notes.\n\nOur lord will rise from the depths and crush any that remain...\n\n-Emperor Dagran Thaurissan.", progress = "<Marshal Windsor eyes the note in your hand.>\n\nWhat do you have there, <name>?", completion = "&lt;Marshal Windsor takes the note and begins reading.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4265] = {title = "Freed from the Hive", objective = "Free Raschal from the Zukk'ash hive.\n\nReturn to Ginro Hearthkindle in Feathermoon Stronghold and let him know that Raschal is alive and well.", description = "The pod splits opens some when you touch it, revealing a night elven male who is surprisingly still alive.  He seems to be in good health, though deeply stunned.  As you help him down from the pod, he stirs to life.\n\n\"Thank Elune - you've saved me, friend!  I... I'm Raschal, and I awoke paralyzed inside this pod after these bugs overwhelmed me.  Were you sent by the Stronghold?\"\n\nIt would seem that you've found the missing courier!", progress = nil, completion = "Welcome home, &lt;name&gt;.  Raschal checked in just a little while ago and told me what happened.\n\nI... no, the entire Stronghold can't even begin to thank you for your great deed; Raschal would have been dead without your timely aid, and your assistance came to us without even so much as the whisper of a mercenary's fee.  You bear the mark of a true hero.  Know that you will always have a friend in Ginro Hearthkindle.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4266] = {title = "A Hero's Welcome", objective = "Speak with Shandris Feathermoon in Feathermoon Stronghold.", description = "<name>, General Shandris Feathermoon would like to speak with you personally.  No doubt she wants to thank you for your service to the Stronghold, but I do know that she also wants to talk to you about the insect creatures that you and Raschal faced in southern Feralas.  The reports of those Zukk'ash insects are... frightening, to say the least.\n\nGeneral Feathermoon is waiting for you in the main compound.", progress = nil, completion = "&lt;name&gt;, I give you my warmest thanks for the aid you've given us.  Your bravery in the face of overwhelming odds has warranted a reward worth a thousand times greater.  Nevertheless, I hope you accept this on behalf of the entire Stronghold.\n\nNow, if I may... I'd like to ask for your aid one more time.  In light of the discovery of the Zukk'ash hive here in Feralas, I think you're the best choice for this mission.", rewards = "You will be able to choose one of these rewards:\n\nCeremonial Elven BladeSanctimonial Rod\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4267] = {title = "Rise of the Silithid", objective = "Bring Raschal's Report to Gracina Spiritmight in Darnassus.", description = "I am entrusting you with a copy of the report Raschal made on the infestation of southeastern Feralas.  While the main report is being filed in Darnassus, I want you to give this copy to an associate of the Protectorate.  Her name is Gracina Spiritmight; she is a priestess who dwells in the Temple of the Moon in Darnassus.  She has broad knowledge on these kinds of creatures, and her receiving this report would benefit us all.\n\nYou're dismissed - good luck, <name>; may Elune watch over us all.", progress = "Welcome to this blessed temple, friend.  Your arrival here from Feathermoon Stronghold has been foretold to me.  Do you have the report Shandris Feathermoon asked you to bring?", completion = "We night elves know of the terror outlined in this report.  Shandris was wise to send this, and you, to me.\n\nThese creatures will consume Feralas rapidly; they are nothing short of one of the greatest menaces we all will ever face.  The insects you and the courier encountered are known as the silithid.  They are mere tools of one of the greatest threats that both the Horde and Alliance will ever face.\n\nI pray we will have the resolve to defeat them before they destroy us.", rewards = "You will be able to choose one of these rewards:\n\nGloves of the DuneMarauder's Handwraps\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4281] = {title = "Thalanaar Delivery", objective = "Bring the Undelivered Parcel to Falfindel Waywarder in Thalanaar.", description = "This parcel of goods you found in the Woodpaw gnoll camps was supposed to be delivered to the small way-station of Thalanaar in southeastern Feralas.  Regardless of the missing courier's fate, the task of delivering the parcel remains unfinished.\n\nExamining the parcel in detail reveals a hand written name of \"Falfindel Waywarder\" on the outside of the packaging.  Perhaps this is the parcel's ultimate recipient.", progress = "Welcome to Thalanaar, <class>.  Do you need assistance of some sort?", completion = "Elune be praised, the delivery from Feathermoon Stronghold has finally arrived!\n\nYour presence here indicates to me that perhaps some ill fate may have befallen Raschal, our usual courier.  I hope that everything works out.  I know that recently, the Woodpaw have become highly agitated from some source to their south.  Maybe he fell to the wilds there; I would be careful, friend.\n\nRegardless, thank you again.  Here is payment for this parcel's delivery.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4282] = {title = "A Shred of Hope", objective = "Return Marshal Windsor's Lost Information.\n\nMarshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge.", description = "<Marshal Windsor shakes the note excitedly.>\n\nDo you realize what this means, <name>?\n\nPerhaps all is not lost! From what I can ascertain, the information is being held by two Dark Iron dwarves: General Angerforge and the golem lord, Argelmach. I have a feeling that they won't just hand over the information if we ask nicely.\n\nI hope you are ready to battle.\n\nVenture forth and find these two villains! Destroy them and return my lost information.", progress = "Soon this grand subterfuge will be over.", completion = "&lt;Marshal Windsor snatches the two tablets from your hands.&gt;\n\nWe need to get out of here!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4283] = {title = "FIFTY! YEP!", objective = "Oralius wants 50 Blackrock Medallions. Chances are high that these medallions can be found on the orcs in the Burning Steppes.", description = "I'm going to let you in on a little secret, soldier. Come a little closer.\n\nI'M THE ONLY SANE ONE HERE!\n\nLook at these people! Would you believe that they're all insane!? Well they are! NUTS! CRAZY!\n\n<Oralius lowers his voice.>\n\nLet's just keep that between me, you, and my pal Captain Winky.\n\n<Oralius grabs at the air and squeezes.>\n\nAnyhooooo... I'm collecting badges to go along with my ogre ear collection. Orc is the flavor of the day. Fifty. GO!\n\n<Oralius blows into a horn.>\n\nSHIP IT!", progress = "<Oralius is talking into a rather large, severed ogre ear.>\n\nBurning Steppes to control, come in control.", completion = "You've done it! Your reward is: RUB MY BELLY! GO ON! RUB IT!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4284] = {title = "Crystals of Power", objective = "Collect 7 Power Crystals of each color: red, blue, yellow, and green. Bring them to J.D. Collie at Marshal's Refuge.", description = "I'm sure you've noticed 'em, <name>. They're everywhere!\n\nWhat am I talking about? Why, the crystals, of course!\n\nThe crystals... They're all over the crater. Most people ignore them, but I have a strange feeling that they hold power within them. I've been doing experiments here with them for a while, but I can't seem to find anything. Well, I haven't yet, anyway.\n\nSay, I'm running a little low on the crystals I have here -- think you might be able to collect some more for me?", progress = "I just know I'm onto something here, <name>!", completion = "Now I will continue my experiments! Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4285] = {title = "The Northern Pylon", objective = "Discover the location of the Northern Crystal Pylon in Un'Goro Crater.", description = "What could they be for? I can't get the thought out of my head!\n\nIt's driving me crazy --  that the rumors I have heard about the crystal pylons are all true. Call me gullible, but I'll usually believe anything people tell me.\n\nAnyway, I have heard that there is one of the crystal pylons fairly close. Somewhere in the north... Please locate it, <name>. I just know they exist.", progress = "Have you visited the pylon, <name>?", completion = "I know the stories are true, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4286] = {title = "The Good Stuff", objective = "Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions.", description = "Captain Winky tells me that the Dark Irons in the Depths got all the good stuff. Ain't that right, Winky?\n\n<Oralius does his best impersonation of a pirate.>\n\nARRR MATEY! IT BE RIGHT!\n\nSee what I'm saying? You need to get in there and bring me back some samples of the good stuff.\n\nGet in there and shake your moneymaker!", progress = "I can't be bothered right now, <name>. Me and Winky got a meeting to attend.", completion = "&lt;Oralius starts rummaging through the mountainous pile of fanny packs.&gt;\n\nOH WONDERFUL!\n\n&lt;Oralius sticks his large nose into the pile and takes a whiff.&gt;\n\nDELICIOUS! Look at all these goodies!\n\nTake one for yourself, &lt;name&gt;. There's plenty to go around.", rewards = "You will receive:\n\nA Dingy Fanny Pack"}
MultiLanguageQuestData['en'][4287] = {title = "The Eastern Pylon", objective = "Discover the location of the Eastern Crystal Pylon in Un'Goro Crater.", description = "During my stay here, I have heard strange rumors about mysterious pylons existing out in the wilderness of the crater, <name>. I guess that they are quite large, with crystals lining their interiors.\n\nAlthough I've never seen one, I can't help but think that the rumors are true -- and that the pylons have something to do with all the crystals we found\n\nSo why don't you help me put my curiosity to rest? Supposedly, there is one in the eastern area of the crater. Do you think you can find it?", progress = "Have you visited the pylon, <name>?", completion = "Un'Goro is such a strange place, &lt;name&gt;. When you enter the crater, it's as if you are in a completely different world...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4288] = {title = "The Western Pylon", objective = "Discover the location of the Western Crystal Pylon.", description = "My experiments so far have not yielded any positive results, <name>. I can't help but hope that you can find a solution by searching for one of the pylons that I have heard exist.\n\nPerhaps if we combine certain colors at them... but I get ahead of myself. Let's find them first!\n\n<name>, search the western area of the crater; a pylon is said to be somewhere in that area.", progress = "Have you visited the pylon, <name>?", completion = "There are many hidden areas of the crater along the sides. Try exploring the winding paths if you can't think of anywhere else to look, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4289] = {title = "The Apes of Un'Goro", objective = "Bring 2 Un'Goro Gorilla Pelts, 2 Un'Goro Stomper Pelts, and 2 Un'Goro Thunderer Pelts to Torwa Pathfinder at the entrance of Un'Goro Crater.", description = "This crater has many strange creatures--they seem to be nobler versions of the creatures found throughout my homeland and beyond. I cannot explain it, but this place cries of the Earth Mother. I pay homage to her every time I track one of her beautiful creatures across its basin.\n\nIf you too wish to feel the enlightenment that accompanies such a great feat, then head to the north. There you'll find great apes who are a test for any mortal's strength. Bring me their pelts... prove your strength.", progress = "Have the creatures here bested you already, <name>?\n\nDo not be dissuaded so easily. Tracking and defeating the apes of Un'Goro is no simple task, even for a great hunter.", completion = "So, you have proven strong, strong enough to best the great apes of Un'Goro--that is good. The challenge was small compared to Lar'korwi, but I will not take such a great victory away from you.\n\nThese pelts will make wonderful clothing for my tribe. You have helped me and proven worthy.\n\nBefore you set off on another task, let us give praise to the Earth Mother and thank the spirits of those apes you killed--they must know their deaths will not be wasted.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4290] = {title = "The Fare of Lar'korwi", objective = "Find the carcass of Lar'korwi's freshest kill and steal a Piece of Threshadon Carcass before returning to Torwa Pathfinder in Un'Goro Crater.", description = "Once, a long time ago, a brother of mine took some meat from one of Lar'korwi's kills. He didn't know it at the time, but Lar'korwi saw him from the forest. Lar'korwi followed my brother for days, destroying everything he touched. My brother, scared, finally decided to run from the Crater and leave Lar'korwi behind.\n\nLar'korwi killed him not far from this spot.\n\nIf you want to provoke Lar'korwi, find a fresh kill of his and take some of the meat from it.\n\nReturn to me afterwards.", progress = "Do not take my words lightly, <name>. If you truly wish to face this creature, then you must be careful... and smart. It will take a great deal of strength and insight to draw out Lar'korwi and defeat him.", completion = "This will do nicely, &lt;name&gt;. It seems Lar'korwi eats well these days. Although, I wonder where he found a threshadon in this area. Odd.\n\nRegardless, I will hold onto this until you are ready for your confrontation with the beast. Do not worry for my safety--I am sure you've angered Lar'korwi enough that he will not kill me until after he's tasted your flesh.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4291] = {title = "The Scent of Lar'korwi", objective = "Bring 2 Ravasaur Pheromone Glands to Torwa Pathfinder near the entrance to Un'Goro Crater.", description = "I'm actually surprised he has not come for you yet, <name>. But all is well, for I have a final plan that will bring the monster to us.\n\nBeing the dominant male gives Lar'korwi rights to breed with any female he chooses--and he chooses many of them. You'll find many ravasaur eggs to the west of here. Get close to them and you should provoke an attack by his mates. The females produce an awful smell from a gland in their heads that allow males to know they are ready to breed. Bring me two of those glands.", progress = "Be careful, <name>. Getting close to any of nest of eggs surely will provoke the mothers... even if you've already secured a gland from one. The mothers can be just as deadly as Lar'korwi himself when they fight to protect their young. But, if you are successful, then we shall have a definitive way of bringing Lar'korwi out from hiding.", completion = "Ah, fine specimens, &lt;name&gt;. The two pieces you've found should be perfect for baiting Lar'korwi into the open. I cannot wait to see the outcome of your fight with the monster. He is a massive thing with claws as sharp as the finest blades. You will look into his eyes and you will know death.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4292] = {title = "The Bait for Lar'korwi", objective = "Using the contents of Torwa's Pouch, summon Lar'korwi and defeat him. Then bring Lar'korwi's Head to Torwa Pathfinder near the entrance to Un'Goro Crater.", description = "This will be the most difficult part because there is some complexity to the plan. To the north of here, you will find a small trail into the mountains. It was here I saw Lar'korwi last. You will know you are in the right area because of all the bones from massive creatures that once wandered nearby. Take the meat you recovered and place it there. Then, rub this mixture I created on the meat. If both lures mingled together do not bring Lar'korwi to you, then I know nothing else that will.", progress = "Do not let fear overpower you, <name>. Fear is the great betrayer... you must remain strong!\n\nTake the meat, place it in the small valley, and then use the gland on it. Only then will death come for you.", completion = "The Earth Mother be praised! You've done it! Fair play to you, &lt;name&gt;. You have proven to be a great hunter in your own right. Your spirit is strong. Your bravery unmatched. And your strength has been fortified. I bow down to your skills.\n\nOnly the greatest of my ancestors could have accomplished something so incredible. Congratulations.", rewards = "You will be able to choose one of these rewards:\n\nPlainstalker TunicOutrider Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4293] = {title = "A Sample of Slime...", objective = "Gather Felwood Slime Samples from any of the slimes in Felwood. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most corrupt. Bring 5 of the Corrupted Felwood Samples you find to Chemist Fuely.", description = "Felwood is a forest far north of the Barrens, even farther than Ashenvale. There, slimes are found all around pools of water blessed by the touch of Fel. The Scourge decimated the area with attacks of Infernals and other demonic magics--the slimes supposedly crept up through the earth during these attacks.\n\nGather samples of Felwood slimes and we will use the testing equipment next to me to create a control group for our tests against other samples you gather.", progress = "I will need at least five corrupted samples for our control group, <name>. Continue to gather Felwood slime samples until you're able to give me that which we'll need. The Lady Sylvanas decrees it...", completion = "Ah, excellent. These samples will do nicely. I thank you for your help.\n\nOnce we've gathered all the samples of slimes, we'll be able to determine more. I am beginning to suspect that Lady Sylvanas' hunch was not only correct, but more insightful than even she could have predicted. These samples are very interesting. Just seeing how they've reacted with my compounds... hmm, yes, we'll definitely need to investigate further.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4294] = {title = "... and a Batch of Ooze", objective = "Gather Un'Goro Slime Samples from any of the slimes in Un'Goro Crater. Then, using the Testing Equipment next to Chemist Fuely in Undercity, see which of your samples are the most pure. Bring 5 of the Pure Un'Goro Samples you find to Chemist Fuely.", description = "Have you heard of the Un'Goro Crater, <name>? It is near the Tanaris desert, and it is a magnificent place: lush, vibrant, full of creatures and plant life.\n\nIt is there you must go. Word has reached me that the place seems completely untainted by outside hands. Explorers are just now discovering its secrets.\n\nI would like to test the slimes or oozes there. If it is true--that they are uncorrupt--then I would like to see how such creatures have evolved.", progress = "Yes, <name>? How goes your search?", completion = "Truly amazing, &lt;name&gt;. This Un'Goro Crater is holding many more secrets than I expected. I wonder what else we will discover as we test further.\n\nSimply amazing... look at the purity of these samples. Hmm, I wonder what it could mean. They seem to be elemental in nature, but... something more. They remind me of... of the Old Gods. We've found traces of them throughout Azeroth, and now I wonder if these creatures aren't related to them somehow.\n\nWe shall have to test further.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4295] = {title = "Rocknot's Ale", objective = "Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I'm getting sober!  I know this because sobriety blurs my vision... and it's making you look like the <race> I slew last week!", description = nil, progress = "Oh, ale!  I would kill for some Dark Iron ale!!  Quick, I'm getting sober!  I know this because sobriety blurs my vision... and it's making you look like the <race> I slew last week!", completion = "What's this?  Ah!  It smells like Dark Iron Ale!  Drink has blurred my sight, but I can tell that you, sir, are a real friend!", rewards = nil}
MultiLanguageQuestData['en'][4296] = {title = "Tablet of the Seven", objective = "Bring the Tablet Transcript to Maxwort Uberglint in the Burning Steppes.", description = "I came to the Burning Steppes, following the legends of the Seven.  They were dwarves of great knowledge and power, and if you have knowledge and power, then wealth is sure to follow.\n\nThat's what I want.  Wealth!\n\nIf we can learn more of the Seven, then maybe we can get rich together.  The ruins of Thaurissan is rumored to keep the Tablet of the Seven, which holds knowledge of the ancient dwarves.  Find this tablet, copy its text and bring it to me.  Let's discover its secrets together!", progress = "Do you have the writings of the Seven, <name>?  Have you learned the secrets from their tablet?", completion = "Ah, you found the tablet!  And your transcription is superb!  Are you sure you're a &lt;class&gt; and not a scribe?\n\nHere you are, &lt;name&gt;.  Here is the payment I promised.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4297] = {title = "Food for Baby", objective = "Bring 5 Silvermane Stalker Flanks to Agnar Beastamer in Hinterlands.", description = "Sprite darters are omnivores--that means they eat both meat and vegetation. If your egg here's gonna hatch, we best be prepared. Some good eats for these little guys are flanks of meat, raw and juicy, believe it or not. I was never able to find out why, but it has somethin' to do with Elune's plan for the elves... maybe they were to be protectors or somethin', I don't know.\n\nI'll take care of the egg for now, why don't you get me some good Silvermane stalker flanks for 'em to eat when he's hatched.", progress = "Find that meat yet, <name>? Your little egg here's just about ready to hatch. If he don't have a good enough first meal, then he might not make it past his first week, and I'd hate for that to happen.\n\nCan't much lie to ya, <name>. I'm jealous of you gettin' this egg to begin with. Don't make me regret helpin' ya out like this.", completion = "These'll do nicely, and if I'm not mistaken, your little egg's just about ready to hatch. How does it feel? You know, you about to be a father? Haha, didn't think ya'd have to deal with such responsibility, now did ya?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4298] = {title = "Becoming a Parent", objective = "Speak to Agnar Beastamer in the Hinterlands.", description = "Whoa, it was a lot more ready than I thought...", progress = nil, completion = "Here, take the egg... better you have it so it bonds to you and looks to you to be its dadda.\n\nCongrats, &lt;name&gt;. You're a parent... kinda.", rewards = "You will receive:\n\nSprite Darter Egg"}
MultiLanguageQuestData['en'][4300] = {title = "Bone-Bladed Weapons", objective = "Bring 8 White Ravasaur Claws to Jes'rimon in Orgrimmar.", description = "Hmm, maybe there be somethin' you can do for the Hand now that me think 'bout it. Yes, Jes'rimon could use your help for sure.\n\nIn Un'Goro Crater there be raptors with deadly claws. Some of those raptors sometimes have white claws instead of ones black like death. The Hand have... clients... that like weapons crafted from these claws. Bring me many of those white claws, and me pay you good coin. Do it fast enough, and maybe me help you in other ways.", progress = "Me clients are not so patient, <name>. Have you gotten any of the claws yet?", completion = "Ah, these do nicely. Thank you, &lt;name&gt;. An' you be here long before they needed... that be good.\n\nMaybe we have a weapon fashioned for you from the claws. What do you say?", rewards = "You will be able to choose one of these rewards:\n\nWhite Bone BandWhite Bone ShredderWhite Bone Spear\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4301] = {title = "The Mighty U'cha", objective = "Bring U'cha's Pelt to Torwa Pathfinder at the entrance of Un'Goro Crater.", description = "While you have been exploring Un'Goro, I have seen other things that a mighty hunter such as yourself would relish in. One such sight was a huge ape among the other gorillas to the north. You have been to that cave before, but this time, I wonder if you'll survive the encounter if you accept my task.\n\nI call him U'cha, and he is one of the Earth Mother's greatest sons, of that you can be sure. Defeat U'cha and bring me his pelt. Do this, and I will defend your right to call yourself a great hunter.", progress = "U'cha... the beast was magnificent. Huge and red, with teeth the size of daggers. His arms as thick as tree trunks, and as fast as any mountain lion I have ever laid eyes upon. You should consider yourself lucky to find such a test of bravery--my people would go generations without seeing such a creature.", completion = "Well done, &lt;name&gt;. I am pleased. You have done a great thing here today.\n\nU'cha was one of the greatest apes I had ever seen. The fact that you have bested his strength speaks well of your own strength... and courage.\n\nIt is only fitting that I give you this as a sign of respect. You have earned it.", rewards = "You will be able to choose one of these rewards:\n\nBeastsmasherBeastslayer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4321] = {title = "Making Sense of It", objective = "Speak with J.D. Collie in a moment.", description = "The information you have given me about the pylons is very interesting...\n\nGive me a moment to do some calculations, <name>. Speak to me again in a moment and I should be able to give you the answer we have been looking for.", progress = nil, completion = "Alright, &lt;name&gt;. This is fascinating... I can only hope that my diagrams are correct! I compiled everything into this manual, which you can have.\n\nI believe I can answer any questions you have about the crystals now, &lt;name&gt;.", rewards = "You will receive:\n\nCrystal Pylon User's Manual"}
MultiLanguageQuestData['en'][4322] = {title = "Jail Break!", objective = "Help Marshal Windsor get his gear back and free his friends. Return to Marshal Maxwell if you succeed.", description = "We need to get out of here, <name>. Help me get my gear back from the supply area and free my friends. If we make it out of here, you are to proceed to Morgan's Vigil and speak with Marshal Maxwell. He will give you further instruction.", progress = "You look exhausted, <name>. Perhaps you should have a seat by the fire and relax.", completion = "Amazing, &lt;name&gt;. Simply amazing. Windsor stormed through here not five minutes ago. He makes some grand claims but purports that they are supported by his evidence. He is on his way to Stormwind now to confront Bolvar and ... Lady Prestor.", rewards = "You will be able to choose one of these rewards:\n\nBlade of ReckoningSkilled Fighting Blade\n\nYou will also receive:\n\nWard of the Elements"}
MultiLanguageQuestData['en'][4324] = {title = "Yuka Screwspigot", objective = "Speak with Yuka Screwspigot in the Burning Steppes.", description = "Although my little brother Ribbly has been worthless his whole life, I think, finally, he has some value!  But... we might need your help to capitalize on Ribbly's newfound worth.\n\nMy sister Yuka has been looking for him for weeks, and tracked him to the Burning Steppes.  She sent word to me, asking for some hired hands.\n\nSo, what do you say?  Want to help?  If so, then speak with my sister.  You'll find her holed up in Flame Crest, a cave northwest of Dreadmaul Rock.", progress = nil, completion = "Yes, I'm looking for my brother.  We must find him and retrieve him, bless his heart.\n\nBut if we can't bring all of him... then his head will suffice.", rewards = nil}
MultiLanguageQuestData['en'][4341] = {title = "Kharan Mighthammer", objective = "Travel to Blackrock Depths and find Kharan Mighthammer.\n\nThe King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison.", description = "You have been to the smoldering ruins of Thaurissan? Did you happen to run into a pitiful lout named Kharan Mighthammer? The dwarf that was supposedly watching over my baby girl!\n\n<The King sobs.>\n\nAnd now she's gone, <name>!\n\nI have had my men turn the Steppes upside down. The only clue they have as to the whereabouts of my daughter is that she may be inside the Depths. For all I know, she could be dead!\n\nKharan is supposedly being held prisoner there... find him! I want answers!", progress = nil, completion = "Please, let me explain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4342] = {title = "Kharan's Tale", objective = "Listen as Kharan Mighthammer tells his story.", description = "Please, hear me out before passing judgement!", progress = "Allow me to finish telling my story.", completion = "As you can see, there was nothing I could have done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4343] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4361] = {title = "The Bearer of Bad News", objective = "Return to Ironforge and deliver the bad news to King Magni Bronzebeard.", description = "You must take this information back to King Magni, <name>. He will know what to do!", progress = nil, completion = "&lt;King Magni slams his fist down in anger.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4362] = {title = "The Fate of the Kingdom", objective = "Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan.", description = "It would seem as if my old adversary, Dagran Thaurissan, has me and the kingdom of Ironforge at his mercy.\n\nYou may be my last hope, <name>. You must rescue my dear daughter, Moira!\n\nThere is only one way to make sure that the spell Thaurissan has cast on Moira is broken: Kill him.\n\nAnd <name>, do not harm her! Remember, she is being controlled by Thaurissan! The things she may do or say are a result of Thaurissan's evil spell!", progress = nil, completion = "&lt;Princess Bronzebeard weeps over the loss of Emperor Dagran Thaurissan.&gt;\n\nWhy???", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4363] = {title = "The Princess's Surprise", objective = "Return to Ironforge and speak with King Magni Bronzebeard.", description = "Thaurissan was a great and honorable dwarf. You ruined my life and the life of my unborn child!\n\n<You think that Princess Bronzebeard may still be suffering from the residual effect of the Emperor's spell.>\n\nReturn to Ironforge and tell my father that the heir to the Kingdom of Ironforge will be a Dark Iron dwarf.\n\nWhether he approves or not, it shall be.", progress = nil, completion = "&lt;King Magni Bronzebeard is visibly upset.&gt;\n\nIt seems that even in death, Thaurissan has won.\n\nYou are dismissed, &lt;name&gt;. Before you leave, you may choose your reward from the royal vault.", rewards = "You will be able to choose one of these rewards:\n\nMagni's WillSongstone of Ironforge\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][4381] = {title = "Crystal Restore", objective = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", description = nil, progress = "The Pylon table allows you to combine green power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to heal yourself or your allies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Restore"}
MultiLanguageQuestData['en'][4382] = {title = "Crystal Force", objective = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", description = nil, progress = "The Pylon table allows you to combine green power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to increase your spirit.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Force"}
MultiLanguageQuestData['en'][4383] = {title = "Crystal Ward", objective = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", description = nil, progress = "The Pylon table allows you to combine green power crystals with red power crystals.\n\nAccording to J.D.'s manual, this combination can be used to strengthen the protection you have against physical damage.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Ward"}
MultiLanguageQuestData['en'][4384] = {title = "Crystal Yield", objective = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", description = nil, progress = "The Pylon table allows you to combine red power crystals with blue power crystals.\n\nAccording to J.D.'s manual, this combination can be used to weaken an enemy's defenses.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Yield"}
MultiLanguageQuestData['en'][4385] = {title = "Crystal Charge", objective = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", description = nil, progress = "The Pylon table allows you to combine red power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a large explosion that can inflict damage on your enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Charge"}
MultiLanguageQuestData['en'][4386] = {title = "Crystal Spire", objective = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", description = nil, progress = "The Pylon table allows you to combine blue power crystals with yellow power crystals.\n\nAccording to J.D.'s manual, this combination can be used to create a shield that does damage to enemies.", completion = "Arranging the crystals on the table, you carefully align the colors. As you push the last one into place, a burst of light fuses the crystals together.\n\nThe resulting combination is now yours.", rewards = "You will receive:\n\nCrystal Spire"}
MultiLanguageQuestData['en'][4401] = {title = "Corrupted Songflower", objective = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a songflower plant.  A pungent, unhealthy odor emanates from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply some Cenarion plant salve to the songflower.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4402] = {title = "Galgar's Cactus Apple Surprise", objective = "Bring Galgar 10 Cactus Apples. You remember him saying that they could be found near cactuses.", description = "It sure gets hot out here in the Valley of Trials.\n\n<Galgar wipes his brow.>\n\nIf only I had some cactus apples, I could make my famous cactus apple surprise! Nothing cools you off faster than a piece of that delicious treat.\n\nI'll tell you what, <name>. If you bring me 10 cactus apples, I'll make you a few portions of cactus apple surprise to take with you on your adventures. If you're interested, you can find cactus apples growing near the cactus plants around here.", progress = "Have you finished collecting cactus apples?", completion = "Wonderful, &lt;name&gt;! As promised, here is your cactus apple surprise plus a little something extra.", rewards = "You will receive:\n\nCactus Apple Surprise"}
MultiLanguageQuestData['en'][4403] = {title = "Corrupted Windblossom", objective = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a windblossom plant.  The berries that hang from the plant appear rotten and poisonous.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply two Cenarion plant salves to the windblossom.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
MultiLanguageQuestData['en'][4421] = {title = "The Corruption of the Jadefire", objective = "Kill 11 Jadefire Felsworns, 9 Jadefire Shadowstalkers, 9 Jadefire Rogues, and Xavathras. Return to Eridan Bluewind in Felwood when the task has been completed.", description = "Not many seek adventure here... Felwood's corruption is widespread and indiscriminate.\n\nAs part of the Emerald Circle, I seek to heal this land, but there are some that wish it to fester.\n\nThe ones I speak of are the Jadefire satyrs that dwell to the northwest of here, at the Ruins of Constellas. Led by a particularly cruel satyr named Xavathras, they continue to spread the disease to any creatures they encounter.\n\nWe must defend this land that was once ours. Defeat Xavathras and destroy his minions.", progress = "The corruption here drives the creatures into madness...", completion = "Ridding Felwood of Xavathras is only the first step in a long process. It will take much work to repair the damage that has been done here.\n\nI sense that there is something much larger than just the satyrs at work here, but we will only know the truth with time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4441] = {title = "Felbound Ancients", objective = "Travel to Darnassus and use Eridan's Vial to collect a Vial of Blessed Water from the Temple of the Moon. Return to Eridan with the filled vial.", description = "The flute you found was carved from an ancient protector, the treant allies that have faithfully protected the night elves.\n\nThe satyrs have been able to corrupt anything they come in contact with, which includes the ancients that made Felwood their home. By the use of the fel, the spirit of the ancient has been bound and tortured, never completely released. The felbind you found is no doubt related.\n\nWe must try to purify the flute, <name>. Bring me blessed water from the Temple of the Moon in Darnassus.", progress = "The water will hopefully release the spirit of the ancient, and allow it to be at peace.", completion = "Thank you, &lt;name&gt;. Now, we must pray that we can undo the damage that has been done...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][4442] = {title = "Purified!", objective = "Speak to Eridan again in a moment.", description = "Using the water of Elune, I will attempt to purify the flute. We must end this suffering...\n\nMay Elune guide my hands and heart.\n\nSpeak with me again in a moment.", progress = nil, completion = "With the blessed water, I was able to break the link between the flute and the ancient spirit. I do believe though, that if you were to use this flute in a sacred spot, you may be able to summon the ancient spirits.\n\nPerhaps you might try the ruins in the southern part of Irontree Woods. Many corrupted treants inhabited this area at one time, and it is possible that they may still reside there, even in spirit form.", rewards = "You will receive:\n\nFlute of the Ancients"}
MultiLanguageQuestData['en'][4443] = {title = "Corrupted Whipper Root", objective = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", description = nil, progress = "You have found a sickly, corrupted version of what appears to be a whipper root plant.  The visible roots of the plant appear tough and leathery, and a slimy film hangs from the plant.  It desperately needs some sort of attention if it is to be turned back to normal.", completion = "You apply three Cenarion plant salves to the whipper root.  It immediately begins to shed its corrupted form, blossoming into a vibrant and healthy plant.", rewards = nil}
