MultiLanguageQuestData['en'][5891] = {title = "Salve via Disenchanting", objective = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", description = nil, progress = "The power of a disenchanted magical item is felt by the essence it creates.  I've devised a way to turn raw essence used by enchanters into a suitable reagent for creating Cenarion plant salve.  You don't need a Cenarion beacon for this; any suitably disenchanted item that yields lesser nether essences will work.\n\nI just need a single lesser nether essence; in exchange, I will give you Cenarion plant salves.  The essence is extremely potent - a little definitely goes a long way!", completion = "Here are some Cenarion plant salves - I only need one lesser nether essence for this, &lt;name&gt;.  Essence is by far the most potent item I can make use of to turn swords into plowshares, as it were.  If you need more salve, then find me here!", rewards = "You will receive:\n\nCenarion Plant Salve"}
MultiLanguageQuestData['en'][5892] = {title = "Irondeep Supplies", objective = "Bring 10 Irondeep Supplies to the Alliance Quartermaster in Dun Baldar.", description = "Before the fighting started, we stored supplies for Dun Baldar in the Irondeep mine.  The troggs that surfaced there weren't much of a problem when we had spare troops to guard the mine, but now that we're fighting with the Horde we can't maintain control of Irondeep.\n\nWe need the supplies in Irondeep, <name>.  Enter the mine and bring me a load of them.", progress = "Do you have the supplies, <name>?  We can never have enough!", completion = "Well done!  I'll put these supplies to good use!  Thanks, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5893] = {title = "Coldtooth Supplies", objective = "Bring 10 Coldtooth Supplies to the Horde Quatermaster in Frostwolf Keep.", description = "The Coldtooth mine to the north was once an ideal place to store extra supplies, but now that the fighting with the Stormpikes grows fierce, we do not always have the spare warriors to station at the mine and protect it.  And so, control of the mine often falls to the Alliance, or to underground denizens...\n\nBut we still need our supplies, <name>!  Go to the Coldtooth mine and bring me a load of them.  And be wary of enemies as you go; the tides of battle shift quickly in that place...", progress = "Have you been to the Coldtooth mine, <name>?  Do you have the supplies I asked for?", completion = "Ah, you got  them.  Good work, &lt;name&gt;!  These supplies are a little musty from sitting in that dark mine for so long, but we'll make use of them nonetheless.\n\nThank you, &lt;name&gt;.  Your deeds are vital to the maintenance of our fighting forces.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5901] = {title = "A Plague Upon Thee", objective = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Mickey Levine at the Bulwark in Tirisfal Glades.", description = "So, to bring pain and strife to the Scarlet Crusade, I want to take their precious lumber mill from them. I'm sure the loss of such a resource will cause them a great deal of harm in defending and rebuilding the town for their own reasons. Will you help me, <name>?\n\nStart by taking this jar to Plaguewood in the Eastern Plaguelands. Fill it with the termites you find in their mounds throughout the woods. Come back when you have enough.", progress = "Do you have the termites yet, <name>? I am sure it is obvious to a smart <class> like yourself.\n\nOnce we have enough of them, we'll make sure no one can use the lumber mill ever again!", completion = "These will do nicely, &lt;name&gt;. Thank you.\n\nIf you're ready, we can get on with the next step.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5902] = {title = "A Plague Upon Thee", objective = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item: \n", description = "Now that we have plenty of termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; someplace high, like on a crate or something.\n\nAfter you open it, the rest should take care of itself. Just come back here and I'll reward you for helping me.", progress = nil, completion = "The termites are obviously getting restless as you place the barrel on top of the crate.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5903] = {title = "A Plague Upon Thee", objective = "Use the Empty Termite Jar on the Termite Mounds in Eastern Plaguelands. After you've gathered 100 Plagueland Termites, return to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", description = "I've tried many times to rout out the Scarlet Crusade through force alone, but to no avail. So, as an alternative, I've decided to make their lives more difficult.\n\nIf you are willing to help, I want to infest that lumber mill with the most terrible species of termites ever found.\n\nIn Plaguewood, near the once-great Stratholme, there is a breed that survived the plague and the Scourge combined. Find their mounds and fill this jar with them, so we can prepare them to be unleashed on the Crusade.", progress = "Did you find the termite mounds, <name>? I've heard they are all over Plaguewood.", completion = "These will do nicely, &lt;name&gt;. Thank you. Just look at them... so many of them all huddled up. I almost feel bad for the Crusade, but then again, it was never their mill to take, now, was it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5904] = {title = "A Plague Upon Thee", objective = "Find someplace suitable in the center of the Northridge Lumber Mill in Western Plaguelands to place the Barrel of Plagueland Termites.\n\nProvided item: \n", description = "Now that we have the termites, take this steel reinforced barrel to the Northridge Lumber Mill south of Hearthglen--you'll find it to the west of the road that leads you up to the town.\n\nOnce there, place the barrel in the center of the lumber mill; find someplace suitable, like on a crate and then open it. The termites should do their work from there and make the mill useless to the Crusade.", progress = nil, completion = "The termites are obviously getting restless as you place the barrel on top of the crate.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5921] = {title = "Moonglade", objective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", description = "All druids are welcome in the sacred lands of Moonglade, regardless of the current tensions in the Cenarion Circle between Arch Druid Staghelm and Keeper Remulos - Moonglade's guardian.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.", progress = nil, completion = "\"And so it begins, Father Cenarius.  And so it begins.\"\n\nDendrite makes a quick, invisible gesture in the air above him.  A slight aura of power falls over him.\n\n\"The first perspective of nature you must adapt to is that of the bear.  I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5922] = {title = "Moonglade", objective = "Use the spell \"Teleport: Moonglade\" to travel to Moonglade. When you arrive, speak with Dendrite Starblaze in the village of Nighthaven.", description = "All druids are welcomed to the sacred lands of Moonglade, tauren and night elf alike.  Keeper Remulos - Moonglade's guardian - keeps watch over all druids who hibernate there.  Now that you're learning the ways of the Claw, I'll teach you the spell that lets you transport yourself there.  Cast it whenever you seek Moonglade's knowledge or solace.\n\nAs for your first lesson, travel to Moonglade and speak with Dendrite Starblaze in Nighthaven about the path you're now on.  Good luck, young druid.", progress = nil, completion = "\"And so it begins, Father Cenarius.  And so it begins.\"\n\nDendrite makes a quick, invisible gesture in the air above him.  A slight aura of power falls over him.\n\n\"The first perspective of nature you must adapt to is that of the bear.  I will put you on the path to understanding this aspect of druidic life, but it is you that must embrace it and propagate it - now and forever!\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5923] = {title = "Heeding the Call", objective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", progress = nil, completion = "I'm glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5924] = {title = "Heeding the Call", objective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", progress = nil, completion = "I'm glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = nil}
MultiLanguageQuestData['en'][5925] = {title = "Heeding the Call", objective = "Speak with Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", description = "Excuse me, friend...\n\nIt has come to my attention that Mathrengyl Bearwalker has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Mathrengyl is the direct assistant to the Arch Druid himself, and is one of the most sage and august druids you'll find in Teldrassil.\n\nHe is located in the Cenarion Enclave of Darnassus, on the second floor of Fandral Staghelm's tree.", progress = nil, completion = "I'm glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5926] = {title = "Heeding the Call", objective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", progress = nil, completion = "I am glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5927] = {title = "Heeding the Call", objective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", progress = nil, completion = "I am glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5928] = {title = "Heeding the Call", objective = "Speak with Turak Runetotem on the Elder Rise of Thunder Bluff.", description = "Excuse me, friend...\n\nIt has come to my attention that Turak Runetotem has put out word that he wishes to speak with you.  It seems that your training as a druid is about to take on a new life, and he will be training you personally.  Turak is one of the Arch Druid's assistants; he is known as a wise and patient druid, and he should teach you well.\n\nHe is located in Thunder Bluff, inside the Cenarion Circle's main tent on the Elder Rise.", progress = nil, completion = "I am glad you found your way here today, young &lt;class&gt;.  The time has come for you to take a large step into a much larger world.\n\nInside each of Cenarius' children is the call to serve nature.  Animals and plants are our friends as well as our charges.  We choose to devote our lives as preservers of balance for their sakes as well as our own.  Your first step into this world will be to learn of the ways of the bear, and to learn strength of body and heart.\n\nReady yourself!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5929] = {title = "Great Bear Spirit", objective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5930] = {title = "Great Bear Spirit", objective = "Seek out the Great Bear Spirit in northwestern Moonglade and learn what it has to share with you about the nature of the bear. When finished, return to Dendrite Starblaze in Nighthaven, Moonglade.", description = "In the northwest part of Moonglade resides the home of a wise and noble being we call the Great Bear Spirit.  For all druids, it has served as a tutor and mentor into the first true natural understanding of the bear.  All druids at one point seek the spirit's wisdom, and you shall be no exception.\n\nGo to the Great Bear Spirit now and learn what it will teach.  When it is satisfied with you, return to me here in Nighthaven.  We will then see if you have truly taken account of the lessons it teaches.", progress = "Return only when the Great Bear Spirit has released you back unto me.  Your training cannot continue without its blessing.", completion = "Dendrite makes another invisible gesture in the air above him as you approach.  Another aura of power comes over him, and he smiles ever so slightly.\n\n\"I sense wisdom in you, young one, that was not present when we first met.  You gaze upon me with strength and knowing intent, though this intent is yet not focused.  You will now learn to focus your strength and adopt the nature of the bear into your work.\"", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5931] = {title = "Back to Darnassus", objective = "Return to Darnassus and speak with Mathrengyl Bearwalker in the Cenarion Enclave.", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Mathrengyl Bearwalker walks truly in balance with nature, even as he dwells precariously close to where the balance has faltered.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.", progress = nil, completion = "Welcome back, &lt;name&gt;.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We have come to rely on its wisdom and its power to fuel our purpose.  The time has now come for your first test of this purpose.  Listen closely...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5932] = {title = "Back to Thunder Bluff", objective = "Return to Thunder Bluff and speak with Turak Runetotem on the Elder Rise.", description = "The time has come for us to part ways, young one, as the application of your lessons takes you back to whom that sent you to me.  Though the tauren are thought to be young in the ways of Cenarius, Turak Runetotem walks with much balance in the presence of nature.  Listen to his instructions, and you will soon complete your first lessons into your role as a protector of balance.\n\nGo now, young one.  We shall meet again.", progress = nil, completion = "Welcome back, &lt;name&gt;.  I sense that your first meeting with the Great Bear Spirit is the same as it is with all druids when they first start down the path of the Claw... a little bewildering, but very intense.  I know it was that way with me.\n\nThe Great Bear Spirit has been a part of Azeroth as long as Azeroth has existed in the heavens.  We &lt;race&gt; listen closely to such spirits, and we all prosper from its purpose.  Now, the time has now come for your first test of this purpose.  Listen closely...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5941] = {title = "Return to Chromie", objective = "Take the Bundle of Relics to Chromie in Andorhal.", description = "You have gathered many relics of the battle of Darrowshire.  Each time you returned with more, my heart yearned for my village... yearned to protect it from its fate.\n\nI know that cannot be, but Chromie, that strange gnome in Andorhal, tells me it is possible.  She says you can save Darrowshire!\n\nShe asked me to gather together the relics, and to have you bring them to her.  She said that she awaits you in the ruined inn of Andorhal.", progress = "I have been in contact with your friend Carlin.  He feels great pain for the doom of his village, but he speaks very highly of you and knows that you can set things right.\n\nOh, but I'm drifting from the subject at hand... <name>, do you have the relics I asked for?", completion = "Ah yes, there they are.  Together they weave a powerful spell, one that will raise the spirits of Darrowshire.\n\nWith that spell, and with a little luck, we can save Joseph Redpath!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5942] = {title = "Hidden Treasures", objective = "Bring Joseph's Key to Joseph's Chest.", description = "Daddy told me to give you this key.  He said it opens a chest out back behind the house.\n\nHe also wanted me to thank you.  Did you do a favor for him?  Did you tell him you found my doll?\n\nWell here's the key.  And thank you <name>.  Thank you!  You're a very nice <man/lady>!", progress = "This chest is old and covered in grime.", completion = "The key fits the lock, and the chest opens...", rewards = "You will receive:\n\nRing of ProtectionArchlight TalismanMagebane Scion"}
MultiLanguageQuestData['en'][5943] = {title = "Gizelton Caravan", objective = "Escort the Gizelton Caravan through Mannoroc Coven. Talk with Smeed at Scrabblescrew's Camp for your reward.", description = "You look like a capable <race>. Perhaps you're looking to make some money? Cork and I started this caravan to make a bundle of money; little did we know the dangers of turning a buck!\n\nUp ahead is Mannoroc Coven... normally the demons ignore us but something has the kodos spooked this time. I'll pay you to protect the caravan past Mannoroc Coven. Once we are safely past you can receive your reward from our business associate Smeed at Scrabblescrew's Camp.", progress = nil, completion = "Not sure it's a prosperous proposition to be paying so much money to protect the Gizelton Caravan. Cork and Rigger only make one gold piece a week, but as long as they keep paying for my kodos I can care less how they run their business.", rewards = "You will be able to choose one of these rewards:\n\nSidegunner ShottieKodo BranderStudded Ring Shield\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][5944] = {title = "In Dreams", objective = "Escort Taelan Fordring out of Hearthglen.", description = "For so long, I have been a puppet of the Grand Crusader. What reason was there to fight against what the Scarlet Crusade had become? It has been decades, yet the memories of my father; those precious memories, they are what have kept me alive.\n\nI have dreams, stranger. In these dreams my father is with me. He stands proudly at my side as I am inducted into the Order. We battle legion of Scourge, side by side. We bring honor to the Alliance, to Lordaeron.\n\nI want not to dream anymore.\n\nTake me to him.", progress = "<Tirion regains his composure.>", completion = "The death of my son at the hands of these monsters will not pass without incident. Take solace in knowing that the Order is reborn.\n\nI now take my place as Highlord of the new Order of the Silver Hand.\n\nThese possessions of my past - they are all that I have to offer for all that you have done. Please, take these as a symbol of my gratitude; all have served me well over the years.\n\nMay we meet again, in better times, and reminisce of days long past... battles hard fought... dreams redeemed.", rewards = "You will be able to choose one of these rewards:\n\nMark of FordringOrnate Adamantium BreastplateShimmering Platinum WarhammerShroud of the ExileFordring's Seal\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][5961] = {title = "The Champion of the Banshee Queen", objective = "Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead.", description = "It pleases me greatly to see the battle hardened join our cause. Our numbers grow in size and strength as each day passes. Perhaps you are prepared to test your mettle, <class>?\n\nAmong the first of my champions was Nathanos, now known as the Blightcaller. Few exist with more dedication or vigor amidst our ranks.\n\nSeek him out in the Eastern Plaguelands. He resides at the Marris Stead; occasionally roaming the decimated wastes, slaying all Scourge and Alliance filth that cross his path.", progress = nil, completion = "Surely the Dark Lady does not believe you worthy to meet her champion. You are here to feed my hounds, yes? There could be no other reason for this interruption.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][5981] = {title = "Rampaging Giants", objective = "Rivern Frostwind wants you to kill 4 Frostmaul Giants and 4 Frostmaul Preservers.", description = "Around 4,000 years ago, Tyrande Whisperwind saved the life of the frostsaber queen, at the hands of rampaging giants. Since then, the frostsabers have been allies of the night elves.\n\nThese same giants that once were a danger to the frostsabers, still exist not too far from here. They are called the frostmaul, and they have taken over the large valley to the south.\n\nProve your loyalty to the frostsabers; kill these giants in the name of the frostsaber queen, Shy-Rotam!", progress = nil, completion = "Excellent, &lt;name&gt;. Your determination has been duly noted.", rewards = nil}
MultiLanguageQuestData['en'][6001] = {title = "Body and Heart", objective = "Use the Cenarion Moondust on the Moonkin Stone of Auberdine to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Mathrengyl Bearwalker in Darnassus when you are done.", description = "Directly east of Auberdine lay many moonkin caves.  The one closest to Auberdine has a Moonkin Stone inside it.  Lunaclaw, the defender of the stone, will face you only when Cenarion Moondust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Moondust, <name>... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!", progress = "When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized.  Until that time, I cannot help you further.", completion = "You have finally taken your large step into a much larger world, &lt;name&gt;.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a &lt;class&gt; of the Claw!", rewards = "The following spell will be cast on you:\n\nBear Form\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][6002] = {title = "Body and Heart", objective = "Use the Cenarion Lunardust on the Moonkin Stone between Mulgore and the Barrens to bring forth Lunaclaw. From there, you must face Lunaclaw and earn the strength of body and heart it possesses.\n\nSpeak with Turak Runetotem in Thunder Bluff when you are done.", description = "On land west of Taurajo in the Barrens - just before it turns into Mulgore - lies a Moonkin Stone.  The moonkin are special beasts, not native to these parts.  Lunaclaw, the stone's defender, will face you when Cenarion Lunardust is applied to it.  Lunaclaw possesses within it a strength that you must use as one of the Claw.\n\nYou've earned the right to use this Cenarion Lunardust, <name>... now show me that you've earned the right to possess the strength of body and the strength of heart needed as a druid!", progress = "When you have faced the challenge that lies before you, your understanding of strength of body and strength of heart will be fully realized.  Until that time, I cannot help you further.", completion = "You have finally taken your large step into a much larger world, &lt;name&gt;.  I sense the teaching of the Great Bear Spirit within you, and I sense that you have received the strength that Lunaclaw possessed.\n\nThere are no further obstacles in your way... let me now teach you what it means to be a &lt;class&gt; of the Claw!", rewards = "The following spell will be cast on you:\n\nBear Form\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][6004] = {title = "Unfinished Business", objective = "Kill 2 Scarlet Medics, 2 Scarlet Hunters, 2 Scarlet Magi and 2 Scarlet Knights before returning to Kirsta Deepshadow in Western Plaguelands.", description = "I was sent as a scout to do some damage and gauge the strength of Hearthglen's defenses. Some people in the Alliance feel the little town has more than historical importance. It's not my job to question what that importance is, but regardless, I'm in no shape to continue until I rest up.\n\nIf you're willing, I'd pay handsomely for some help. Start south of here at their camp near the small bulwark they've set up. If you prove strong enough, maybe I could get your help with my main goal.", progress = "How is it going, <name>? Are they stronger than you thought? I hope not. If I'm going to follow through here, then it's going to require a heck of a lot more strength than what I've already asked you to do.", completion = "Well done, &lt;name&gt;. I'm amazed you dealt with them so quickly. Thank you.\n\nI have yet to meet anyone that approves of the Scarlet Crusade and their methods. I believe in the Light as much as anyone else in Stormwind, but they've demonstrated that they only want to kill anyone not loyal to their movement... even innocents.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6021] = {title = "Zaeldarr the Outcast", objective = "Bring Zaeldarr's Head to Caretaker Alen at Light's Hope Chapel.", description = "Can you believe that, after all the trouble we have in the plaguelands... we have to worry about thieves too?  And not just normal thieves, troll thieves.\n\nAnd not just normal troll thieves.  Dead troll thieves!\n\nThey're led by this big, dead troll named Zaeldarr the Outcast, and they come here at night and steal bodies from the pit below, then take them back to their evil, dead troll hideout--the Undercroft to the west.\n\nGo there and take out Zaeldarr, <name>.  I'm sick to death of his mischief!", progress = "Did you find the hideout, <name>?  Did you take care of Zaeldarr?", completion = "Great, you got him!  And I hope you taught his gang a lesson too!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6022] = {title = "To Kill With Purpose", objective = "Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot.", description = "You kill with purpose while you remain on my stead.\n\nYour first task is to feed my hounds.\n\nTake this mortar and pestle and travel to Corin's Crossing. Once there, you will find a robust selection of Scourge to slaughter. From their fresh carcasses I need living rot. Take that living rot and grind it up in the mortar, then let it sit to coagulate. Bring the coagulated rot back here.\n\nAnd imbecile, realize that living rot from the undead doesn't remain 'living' for very long. You must kill quickly!", progress = "Are you crying? If this is too 'tedious' for you, 'hero,' I recommend that you head back to the Dark Lady and inform her of the horrible mistreatment you received at my farmstead.\n\nNow get out of my sight!", completion = "Disappointing. I was hoping that I'd be feeding you to my hounds, instead.\n\n&lt;Nathanos sighs.&gt;\n\nWell, at least they'll have something to eat.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6023] = {title = "Unfinished Business", objective = "Kill Huntsman Radley and Cavalier Durgen before returning to Kirsta Deepshadow in Western Plaguelands.", description = "My real mission was to weaken the Scarlet Crusade's outlying forces and then infiltrate Hearthglen to gauge their numbers. I'm still in no shape to do it on my own, so perhaps I could ask you to aid me again, <name>? From what information I gathered before being discovered, the Crusade has two important members that are the backbone of their forces outside the town: Huntsman Radley and Cavalier Durgen. Kill them, and we're making progress. They should be along Hearthglen Pass outside the town proper.", progress = "Have you found them yet, <name>? With the two of them taken care of, I can proceed to enter Hearthglen to take a closer look at their setup. I can't do it without your help. Please, find Radley and Durgen for me.", completion = "Thank you, &lt;name&gt;. You've been more help than I could have hoped for. The air here just seems to suck my will. I feel tired, and I can tell I'm not getting any better the longer I'm here.\n\nI'm not really sure how I'm going to infiltrate Hearthglen itself and report on how strong the Scarlet Crusade's presence is.\n\nBut that's another matter, before you leave, here, take this... as payment for your help. Thank you again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6024] = {title = "Hameya's Plea", objective = "Kill Infiltrator Hameya. Use his key on the Mound of Dirt behind the Undercroft.", description = "Kill me.  Before it's too late.\n\nI am Hameya.  While traveling to Zul'Mashar, my brethren and I ate some bad meat... and we changed.  We are infected.\n\nI can feel the lich's words now, urging me to reach Zul'Mashar and infect more of my people.  I cannot resist, and so I wrote this scroll before my will left me.\n\nI buried a chest in dirt next to a wagon behind this crypt, but only my key will open it.  I have the key.  If you want my treasure, then find me.\n\nKill me.  Before it's too late.", progress = "This chest buried here is securely locked.", completion = "Hameya's chest is opened!!", rewards = "You will receive:\n\nHameya's SlayerHameya's Cloak"}
MultiLanguageQuestData['en'][6025] = {title = "Unfinished Business", objective = "Enter Hearthglen and find a high vantage point from which you can see the town and gauge the Scarlet Crusade's forces, then return to Kirsta Deepshadow in Western Plaguelands.", description = "What? Really? You want to know more? But you've already done so much for me, <name>. I couldn't possibly ask you to enter Hearthglen itself on my behalf.\n\nAre you sure, <name>? Hearthglen is much more dangerous than the Pass--I cannot provide you any protection  or even information about what you might face.\n\nWell, if you really are willing to help, then enter the town and find a high place to gain a good view of the town. From there you can gauge their numbers and report them back to me. But be careful....", progress = "It's a dangerous task, <name>. I envy your courage.", completion = "You've done it, &lt;name&gt;! Thank you!\n\nI'll return to Elling... I mean Stormwind as soon as I can. Here, take this coin, it's the least I can do for you. You're a credit to your people, &lt;name&gt;. Thank you and good luck.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6026] = {title = "That's Asking A Lot", objective = "Smokey LaRue wants you to get 2 Thorium Bars, 1 Golden Rod, 8 Hi-Explosive Bombs, and 8 Unstable Triggers.\n\nYou will have to find a blacksmith and an engineer for these items.", description = "These here Argent Dawn people commissioned ol' Smokey to do a little demolition work for 'em. Smokey's mammy ain't raised no dummy. When gold coin is slapped on the table, Smokey's services are available. That's my motto!\n\nNow I'd be willing to split the commission with you if you're willing to do a little legwork. Here's the deal: I'm going to head over to Plaguewood and mark the buildings we need destroyed. You gather the components for the bombs. Meet back here when you've got everything. Deal?", progress = "Trust ol' Smokey, <race>. The reward will be worth it. These Argent Dawn folk don't mess around when it comes to payment.", completion = "I can pay you half up front and half when the job is done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6027] = {title = "Book of the Ancients", objective = "Get the Book of the Ancients and return it to Azore Aldamort at the tower in Ethel Rethor.", description = "<name>, I entrust you with the Gem of the Serpent. Place this gem on the Serpent Statue's hand on Ranazjar Isle, a small island northwest of here. Placing it will summon the one who protects the Book of the Ancients. This book contains the secrets of the naga, secrets that have been kept for centuries.  Bring this book to me, and we will learn much about our scaled foes!", progress = "Ah, <name>!  It's good to see you again.  Do you have the Book of the Ancients?", completion = "The long lost Book of the Ancients!  I will ensure this book is passed on to the high council.  You've done well today, and for that you are to be thanked... as a hero should be thanked!", rewards = "You will be able to choose one of these rewards:\n\nSilkstream CuffsArcmetal Shoulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6028] = {title = "The Everlook Report", objective = "Deliver the Everlook Report to Argent Officer Pureheart at Chillwind Camp, Western Plaguelands.", description = "I am looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Pureheart at Chillwind Camp; it's a ways from here, located along the southern fringe of the Western Plaguelands.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from her!", progress = "Greetings, <class>.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Chillwind Camp.  I might also have some work for you...", completion = "Very resourceful, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6029] = {title = "The Everlook Report", objective = "Deliver the Everlook Report to Argent Officer Garush at the Bulwark, Western Plaguelands.", description = "I'm looking for a responsible individual to aid me in a small but nonetheless important matter.  I'm here as a representative of the Argent Dawn's interests to the local governance of Everlook.  I need to get a progress report to Argent Officer Garush at the Bulwark; it's a ways from here, located along the western fringe of the Western Plaguelands, east of Tirisfal Glades.\n\nIf I may be so bold - this would be a perfect means to introduce yourself to my superior and perhaps earn some work from him!", progress = "Greetings, <class>.  On behalf of the Argent Dawn, I offer you safety and shelter while you are here at Bulwark.  I might also offer you the chance to fight for a cause that's worth fighting for!", completion = "Resourceful for a human, Gregor is.  He's been dealing with the Steamwheedle Cartel for some time now, and has become an expert on the \"art\" of goblin negotiations.  Though it's true that the goblins' primary loyalties lie with those who have the largest coin purses, they also know and respect the value of diplomacy.  If anything, it provides them with repeat customers...\n\nAt any rate, the Argent Dawn acknowledges you for your effort.  Please have this, with our thanks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6030] = {title = "Duke Nicholas Zverenhoff", objective = "Deliver the book, \"Studies in Spirit Speaking\", to Duke Nicholas Zverenhoff at Light's Hope Chapel, Eastern Plaguelands.", description = "A recluse medium found in these parts by the name of Umbranse has provided the Argent Dawn with quite a literary masterpiece... one that amounts to quite possibly the largest collection of jibber-jabber I've ever seen written.\n\nOne of the Dawn's most respected leaders, Duke Nicholas Zverenhoff, is a brilliant linguist.  Could you take this to him for me - for a reward, of course?  Light's Hope Chapel - that's where he's currently at, far in the eastern part of the Eastern Plaguelands.", progress = "May the Light guide you in these troubling times, <class>.  What brings you here to this beacon of hope in the middle of darkness and despair?", completion = "This... this is a very special book you have brought me.  I'd like to tell you that \"special\" in this case means \"unique and quite possibly illuminating\", but that remains to be seen.\n\n\"Ooooooo?\"  Who in their right mind thinks this up?\n\nWell now, I've heard of this Umbranse that Gregor spoke of, so this isn't without merit.  I'll do my best to decipher it.  As for you... please, have this - courtesy of the Argent Dawn.  While you are here, perhaps there are some other things you can aid us with.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6031] = {title = "Runecloth", objective = "Bring 30 Runecloth to Meilosh in Timbermaw Hold.", description = "In Timbermaw, we are content.  We do not like strangers.  This is good for us, but it is bad for trade.\n\nNot long ago, a rare night elf friend came to Timbermaw and she wore a runecloth cloak.  runecloth is rare among us, but the cloak was so fine my people want me to make more runecloth clothing.\n\nWill you bring me runecloth?  If you bring me enough, then I will give you something in trade.", progress = "Do you have the runecloth?  My people are eager for more items of runecloth!", completion = "Ah, you brought the cloth.  Such fine material it is!\n\nThank you, &lt;name&gt;.  You are a true friend.  Please accept this in exchange.", rewards = "You will be able to choose one of these rewards:\n\nShadowskin SpauldersBricksteel Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6032] = {title = "Sacred Cloth", objective = "Bring 2 Mooncloth to Meilosh in Timbermaw Hold.", description = "Although the people of Timbermaw delight in the feel of runecloth, it is not sacred to us.  But mooncloth is sacred.\n\nBring me a small supply of this holy cloth, and I will teach you a secret fashioning technique.", progress = "Have you brought the mooncloth, <name>?", completion = "Ah, very good.  This mooncloth will be used for garments sacred to our people.  Thank you, &lt;name&gt;.  Now I will train you.", rewards = "You will learn:\n\nMooncloth Boots\n\nThe following spell will be cast on you:\n\nMooncloth Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6041] = {title = "When Smokey Sings, I Get Violent", objective = "Travel to Plaguewood, northwest of Light's Hope. Destroy 8 Scourge Structures by using Smokey's Special Compound at the Mark of Detonation planted inside each building. Smokey has had the Ziggurats and Slaughterhouses marked.\n\nOnce you plant the bomb, leave the building and marvel at your handiwork.\n\nBy the way, Smokey's Special Compound is rather... unstable.", description = "While you were gathering the supplies, I had some of my people handle marking the Scourge buildings we need demolished.\n\nHere's the plan: I'm going to give you ten sticks of my special compound. You're going to take them over to Plaguewood and plant them inside the Scourge structures that I've had marked for detonation.\n\n<Smokey snaps his fingers.>\n\nBing! It's just that easy.", progress = "I got supplies left over to make a few more sticks of the special compound. Just let ol' Smokey know if you need more.", completion = "You're much darker than I remember. You got that look going for you; the look that says, 'I've been charred by a high explosive bomb.'\n\n&lt;Smokey laughs.&gt;\n\nAnyhow! Here's your cut of the loot. I've thrown in a little something extra to help soothe the burns.", rewards = "You will be able to choose one of these rewards:\n\nSmokey's Explosive LauncherSmokey's Fireshooter\n\nYou will also receive:\n\nMoist ToweletteSmokey's Drape"}
MultiLanguageQuestData['en'][6042] = {title = "Un-Life's Little Annoyances", objective = "Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished.", description = "You cannot take two steps off of this farm without running into one of those obnoxious bats. I want to be able to take the hounds out and slaughter Scourge without being accosted by any damned, dirty bats. Obviously, I have better things to do with my time than mindlessly kill bats day in and day out. You, however, do not.\n\nWhat? Your training? This is your training! Now get out of my sight and don't come back until you've killed a fair number of those winged demons. Don't disappoint me.", progress = "It could have been worse. I could have had you collecting bat guano.\n\n<Nathanos stares at you in contemplation.>\n\nHrm... Hey! Wait a minute. Where are you going?", completion = "It's incredible what a little anger and rage can get accomplished.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6061] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame an Adult Plainstrider. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", description = "As a tauren, it is important to follow the traditions of our ancestors by fighting mighty creatures. By besting these creatures, we are able to intake their spirits, allowing us to become closer to the Earthmother.\n\nIn the same way, taming a beast to fight alongside us helps us become one with nature around us. Eventually, you will learn to tame a beast of your choosing. But all things take practice, and you have much to learn. Begin by taking this taming rod; you must tame an adult plainstrider.", progress = "Practice your skills, <name>. Tame the adult plainstrider.", completion = "Signs have appeared to me from the Earthmother; you have done well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6062] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Dire Mottled Boar. Practice your skills, then return the Taming Rod to Thotar in Razor Hill.", description = "It is an admirable skill to command one's authority over nature. As a hunter, you must strive to learn to use the force and power inherent to any creature of your choosing.\n\nGaining control of an animal is not an easy feat; it is a task that you must undertake with much determination.\n\nFor your first assignment, take this taming rod and use it to tame a dire mottled boar. You can find them quite close to Razor Hill. Practice your skills in battle with the boar at your side, then return to me.", progress = "Good luck, young <class>.", completion = "You have done well, &lt;name&gt;. I believe you are ready for your next task.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6063] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Webwood Lurker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", description = "As a hunter, it is important to remember the responsibility you hold in your hands. Nature is not a power that can be bent to obey our desires; it is one that is to be respected and acknowledged as something stronger than your very existence.\n\n<name>, you must prove your understanding of this before you will gain the ability to tame an animal to be your companion.\n\nYour first task is to take this taming rod. With it, you will be able to tame a webwood lurker. Tame it, and practice your skills as a hunter.", progress = "You will learn, <name>, and one day you will be a great <class>.", completion = "Excellent, &lt;name&gt;! You are quite a fast learner.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6064] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Large Crag Boar. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", description = "Hi there, <lad/lass>! So, you'd be wanting to know how you can gain a pet of your own?\n\nWell, let's get started. There's nothing more important than yer equipment when it comes to hunting, but we can chat about my new Shrapnel Blaster some other time. Fer now, let's focus on something I'm sure you're quite interested in: a pet!\n\nThe best way to learn is for you to try out several creatures as companions and see what ya like. So, find a large crag boar, then use the taming rod to tame it.", progress = "Don't worry, lad! You'll get ta try a few before you'll need to decide on just one.", completion = "I know, I know; you're wondering what's next, aren't ya?!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6065] = {title = "The Hunter's Path", objective = "Speak with Yaw Sharpmane in Bloodhoof Village.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, it is time for you to begin your training.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6066] = {title = "The Hunter's Path", objective = "Speak with Yaw Sharpmane in Bloodhoof Village.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I do believe that you are ready...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6067] = {title = "The Hunter's Path", objective = "Speak with Yaw Sharpmane in Bloodhoof Village.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Yaw Sharpmane in Bloodhoof Village. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I do believe you are ready...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6068] = {title = "The Hunter's Path", objective = "Speak with Thotar at Razor Hill.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I do believe you are ready, as well....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6069] = {title = "The Hunter's Path", objective = "Speak with Thotar at Razor Hill.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I believe you are ready to be trained...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6070] = {title = "The Hunter's Path", objective = "Speak with Thotar at Razor Hill.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Thotar at Razor Hill. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I believe that it is time for me to train you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6071] = {title = "The Hunter's Path", objective = "Speak with Dazalar in Dolanaar.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, it is time, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6072] = {title = "The Hunter's Path", objective = "Speak with Dazalar in Dolanaar.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I believe that it is time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6073] = {title = "The Hunter's Path", objective = "Speak with Dazalar in Dolanaar.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, it is time to train you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6074] = {title = "The Hunter's Path", objective = "Speak with Grif Wildheart in Kharanos.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I believe that it is time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6075] = {title = "The Hunter's Path", objective = "Speak with Grif Wildheart in Kharanos.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, I believe that it is time for you to be trained...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6076] = {title = "The Hunter's Path", objective = "Speak with Grif Wildheart in Kharanos.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Grif Wildheart in Kharanos. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, &lt;class&gt;, it is time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6081] = {title = "Training the Beast", objective = "Speak with Ormak Grimshot in Orgrimmar.", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Orgrimmar. There you must speak to one of our most revered hunters, Ormak Grimshot. He will give you the ability to train your new pet. You will find him in the Valley of Honor.\n\nGood luck, <name>.", progress = nil, completion = "A young &lt;class&gt;, I see. Yes, I will grant you the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go, &lt;class&gt;. We will speak again, at a later date.", rewards = "You will learn:\n\nTraining Lesson\n\nThe following spell will be cast on you:\n\nBeast Training\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6082] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame an Armored Scorpid. Practice your skills, then return to Thotar at Razor Hill.", description = "The final creature you need to tame is one you should strive to emulate; the armored scorpid. It strikes quickly and confidently; to control a force such as this is your fate as a hunter.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing; this creature will be yours to command. Under your control, your pet will gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", progress = "Were you able to tame the scorpid?", completion = "You have learned all I can teach you, &lt;name&gt;. It is time for you to take what you have learned here and choose a pet of your own.\n\nHere you are, &lt;name&gt;. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.", rewards = "You will learn:\n\nTaming Lesson\n\nThe following spell will be cast on you:\n\nTame Beast\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6083] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Surf Crawler. Practice your skills, then return the Taming Rod to Thotar at Razor Hill.", description = "The advantage a pet affords you against your rivals is duly noted, <name>. When you gain control over another creature, you are adding to your own strength. Your pet must become an extension of yourself.\n\nThe next task requires you to turn from the land; you will find the next creature in the waters off the coast. Across from Sen'jin Village, near the Echo Isles. look for a spirited crab called the surf crawler. Use the taming rod to tame it, then practice your skills.", progress = "You need to practice in order to gain the skills you need to effectively control your pet. Have you tamed a surf crawler?", completion = "You are a swift learner, &lt;name&gt;. You have done well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6084] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Snow Leopard. Practice your skills, then return to Grif Wildheart in Kharanos.", description = "Those crag boars are quite burly; maybe you'd like something with a little more finesse? Alright then, I've got jus' the thing. South and east of here, you'll find large white cats called snow leopards. Just like an elegantly-carved rifle, behind their beautiful exterior lies a powerful fighter, capable of doing extreme damage. You'll find them to be much more agile an' swift than the boar you tamed.\n\nTake this taming rod and see how you like the snow leopard.", progress = "What do you think of the snow leopard, <name>?", completion = "When I feel you've learned enough, I will grant you the ability to choose any pet of your liking.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6085] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame an Ice Claw Bear. Practice your skills, then return the Taming Rod to Grif Wildheart in Kharanos.", description = "Perhaps you'd like a creature that possesses little more than brute strength. The ice claw bear is an excellent companion for a fledgling hunter like yourself, and can be found east of Kharanos. Here is the taming rod; try this animal as a pet and see if ya like it!\n\nWhen you return, I'll give ya the skills you will need to tame an animal of your choosing; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as ya like.", progress = "Have you tamed the ice claw bear yet?", completion = "Here you are, &lt;name&gt;. I will now give ya the power to tame a beast, as well as call it and dismiss it as you please.\n\nFind yerself a good, loyal pet, and enjoy the hunt!", rewards = "You will learn:\n\nTaming Lesson\n\nThe following spell will be cast on you:\n\nTame Beast\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6086] = {title = "Training the Beast", objective = "Speak with Belia Thundergranite in Ironforge.", description = "<name>, ya now have the power to tame a pet, but you must also gain the skills ta train it.\n\nTravel to Ironforge and find the Hall of Arms. There you must speak to one of our most revered animal trainers, Belia Thundergranite. She'll give ya the power to train your new pet, so get goin', <lad/lass>!\n\nBelia is a friendly sort; you should have no problems gaining her approval. Good luck, <name>.", progress = nil, completion = "A new recruit, eh? You're on your way to becoming a great &lt;class&gt;, I see.\n\nYes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember that the key to getting the most from your new pet is to respect it and treat it well. In turn, your pet will be your most loyal friend.", rewards = "You will learn:\n\nTraining Lesson\n\nThe following spell will be cast on you:\n\nBeast Training\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6087] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Prairie Stalker. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", description = "You have a fiery spirit, hunter, readily awaiting your next challenge.\n\nYour next task is to gain the companionship of a wolf known as the prairie stalker. This creature is swift and fearless; in taking this beast as your pet, you must also take on these qualities.\n\nDuring a battle, you will learn how you and your pet will become a team. In the end you must work as one, muscle to muscle.\n\nHere is the taming rod, <name>. Tame a prairie stalker and practice your skills.", progress = "Have you found a prairie stalker?", completion = "Yes... The Earthmother believes that you are ready for the next lesson.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6088] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Swoop. Practice your skills, then return the Taming Rod to Yaw Sharpmane in Bloodhoof Village.", description = "The final task that I have for you requires that you tame a creature that inhabits the sky. The swoop is a difficult opponent, but as your ally, you will acquire its sharp attacks and threatening presence.\n\nBy the will of the Earthmother, when you return I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", progress = "You will soon be ready, <name>.", completion = "You have learned all I can teach you, &lt;name&gt;. May the blessings of the Earthmother guide you in choosing a pet.\n\nHere you are, &lt;name&gt;. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride and honor the Earthmother.", rewards = "You will learn:\n\nTaming Lesson\n\nThe following spell will be cast on you:\n\nTame Beast\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6089] = {title = "Training the Beast", objective = "Speak with Holt Thunderhorn on Hunter Rise in Thunder Bluff.", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Thunder Bluff. There you must speak to one of our most revered hunters, Holt Thunderhorn. If he deems you worthy, he will give you the ability to train your new pet.\n\nHolt has bested the most powerful and feared beasts of Azeroth, and commands many strong creatures of his own. His ties to the Earthmother are strong, and you can learn much from him. Good luck, <name>.", progress = nil, completion = "A young &lt;class&gt;, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nNow, go forth. May the Earthmother guide you on your path. We shall speak again, at a later date.", rewards = "You will learn:\n\nTraining Lesson\n\nThe following spell will be cast on you:\n\nBeast Training\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6101] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Nightsaber Stalker. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", description = "The variance of nature is something that can be relied upon, <name>. It is predictable in the way that it never remains the same; it is always changing.\n\nThe tasks I give to you will help you to see and appreciate the vast differences of the creatures you may choose as your companion.\n\nTake this taming rod and use it to tame a nightsaber stalker, found to the south. Practice your skills as a hunter. Then you will begin to understand the similarities and differences of nature.", progress = "Understanding the balance between nature and oneself is a way of life for every <race>.", completion = "I see your commitment and that you have understood what I have taught you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6102] = {title = "Taming the Beast", objective = "Use the Taming Rod to tame a Strigid Screecher. Practice your skills, then return the Taming Rod to Dazalar in Dolanaar.", description = "You have tamed two creatures that inhabit the land, now you must tame one that soars the skies. Use the taming rod to tame a strigid screecher, found west of here. Practice your skills with this mighty owl at your side.\n\nWhen you return, I will bestow you with the skills you will need to tame an animal of your choosing to be your companion; this creature will face the challenges you face, and gain experience alongside you. I will also show you how to call it and dismiss it as you wish.", progress = "I am proud of your accomplishments, <name>. Have you finished the last task I gave you?", completion = "You have learned all I can teach you, &lt;name&gt;. May I offer you one more piece of advice: use discretion when choosing your first pet. Will you choose a creature of the land, of the water, or of the sky? Whatever it may be, without doubt, your pet will be with you for quite some time.\n\nHere you are, &lt;name&gt;. I will now give you the power to tame a beast, as well as call it and dismiss it as you see fit. Use your new skills with pride; you have earned them.", rewards = "You will learn:\n\nTaming Lesson\n\nThe following spell will be cast on you:\n\nTame Beast\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6103] = {title = "Training the Beast", objective = "Speak to Jocaste in the Cenarion Enclave, in Darnassus.", description = "You now have the power to tame a pet, but you must also gain the skills to train it.\n\nTravel to Darnassus. There you must speak to one of our most revered hunters, Jocaste. She will give you the ability to train your new pet, so make haste.\n\nWhile Jocaste may seem stern, she is always pleased to see another hunter rising through the ranks. Treat her with respect and she will return in kind. Good luck, <name>.", progress = nil, completion = "A fledgling &lt;class&gt;, I see. Yes, I can bestow you with the skills you need to train and guide your pet. Not only will you be able to teach your pet new abilities, you will now be able to feed your pet, as well as revive it, should it fall in battle.\n\nRemember, &lt;name&gt;, always respect the balance and live in awe of nature around you. Now, go forth. We shall speak again, at a later date.", rewards = "You will learn:\n\nTraining Lesson\n\nThe following spell will be cast on you:\n\nBeast Training\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6121] = {title = "Lessons Anew", objective = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.", description = "You're now ready to learn about poison and the power we as druids have over it, <name>.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.", progress = nil, completion = "Greetings young &lt;class&gt;, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings in Auberdine, and the village there has been unable to cure it.  To that end, a representative there has asked Moonglade for aid and we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6122] = {title = "The Principal Source", objective = "Use the Empty Cliffspring Falls Sampler to draw a sample of water from the mouth of the cave by the falls.\n\nDeliver the Filled Cliffspring Falls Sampler to Alanndarian Nightsong in Auberdine, Darkshore.", description = "The Cliffspring Falls in Darkshore serves as the principal source of drinking water for the region, and now I suspect it is the principal source of the poison that is harming the local fauna - deer specifically.  Use this sampler to draw some water from the mouth of the cave; be careful, as dangerous naga now reside in a cave by the falls.\n\nOnce filled, deliver it to Alanndarian Nightsong in Auberdine.  She is the one that requested our aid, and you will work with her to address this malady.", progress = "You're the one that the Cenarion Circle in Moonglade sent?  That's wonderful!  We've quite the crisis our hands here regarding the poor deer, and we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By Elune, this water is disgusting!  No wonder the deer are sick.\n\nSomething is polluting the water, and in turn corrupting Darkshore's entire water table.  Sick deer have been seen all over area, and not just by the river.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6123] = {title = "Gathering the Cure", objective = "Bring 5 Earthroot and 12 Lunar Funguses to Alanndarian Nightsong in Auberdine so she may make a curative salve.", description = "The water will serve as the base of the curative salve I'll make for the deer.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if we're unlucky and you aren't one then you'll need to find one to help us out.\n\nFinally for potency, I need some lunar fungus.  Finding lunar fungal blooms is easy enough; they're all over the place in caves just to the east of here.  Moonkin reside in the caves and they're irritable as of late, so be careful.", progress = "Have you got the reagents I need to make the salve?  The deer aren't getting any better on their own, so we better hurry to help them out!", completion = "This is good, &lt;name&gt;, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6124] = {title = "Curing the Sick", objective = "Use the Curative Animal Salve on 10 Sickly Deer that are located throughout Darkshore; doing so should cure them. Sickly Deer have been reported starting south of the Cliffspring River to the north of Auberdine and extending all the way into southern Darkshore where the edge of Ashenvale begins.", description = "The amount of salve made out of the reagents you brought me is good enough for ten doses, <name>.  While I work with the village to try and make some more salve, I'd like for you to help us get a head start.  All around Darkshore are sickly deer; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend Auberdine's thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!", progress = nil, completion = "You have done well in tending to the sickly deer of Darkshore; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  There are those in Darnassus who choose to recognize this threat... and there are those who ignore the growing signs.  I hope you will not be one to put blinders on about what facts stare you in the face, &lt;name&gt;.\n\nRegardless, you've proven your worth as a friend of nature and the Circle - take this as a symbol of such.", rewards = "You will receive:\n\nVeildust Medicine Bag"}
MultiLanguageQuestData['en'][6125] = {title = "Power over Poison", objective = "Return to Mathrengyl Bearwalker in the Cenarion Enclave, Darnassus.", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Mathrengyl Bearwalker in Darnassus, <name>.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.", progress = nil, completion = "Welcome back - I've been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation in Auberdine.  This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.\n\nYou handled yourself with grace under pressure.  For that, I can find no better way to reward you than with permanent power over poison.  Use it well, &lt;name&gt;... use it well.", rewards = "The following spell will be cast on you:\n\nCure Poison\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][6126] = {title = "Lessons Anew", objective = "Travel to Moonglade and speak with Dendrite Starblaze in the village of Nighthaven.", description = "You're now ready to learn about poison and the power we as druids have over it, <name>.  Cenarius has blessed us with the ability to purge even the most foul of poisons with but a mere incantation.  This gift is not to be taken lightly... and to ensure you learn this lesson, you'll work to address the effects of poisonings as a layman would.\n\nTravel to Moonglade and speak with Dendrite Starblaze; he awaits your arrival to begin your lesson.", progress = nil, completion = "Greetings young &lt;class&gt;, I'm glad to see you ready and eager to learn about the curing of poisons.\n\nWhile most druids in the past were put through pre-planned trials, your work will involve no such thing.  There has been a rash of animal poisonings at the Crossroads in the Barrens, and they're unable to bring it under control.  Someone there has requested Moonglade for aid, so we are sending you there to aid them.  This is no exercise - the work you'll do is quite real.  Bear this in mind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6127] = {title = "The Principal Source", objective = "Use the Empty Dreadmist Peak Sampler to draw a sample of water from a pool at the top of the peak.\n\nDeliver the Filled Dreadmist Peak Sampler to Tonga Runetotem at the Crossroads, Barrens.", description = "Dreadmist Peak to the northwest of the Crossroads is most likely a primary candidate as to the source of the spread of the poison.  Its airy peaks have pools of water that influence the weather patterns.  I suspect the water is now tainted by the demon-worshipping Burning Blade.\n\nUse this sampler to draw water from the pool at the very top of the peak.  Once filled, deliver it to Tonga Runetotem at the Crossroads.  He is the one that requested our aid, and you will work with him to address this malady.", progress = "You are the one that the Cenarion Circle in Moonglade sent, yes?  This is most fortuitous for us!  We are stymied in our effort to bring balance to the sickly gazelles that wander the northern Barrens; we're happy for all the help we can get.\n\nDo you have the sample of water that Dendrite Starblaze said you'd have?  He notified me that you'd draw one so we could work on a cure together...", completion = "By my ancestors, this water is disgusting!  No wonder the gazelles are sick.\n\nSomething is polluting the water, and in turn beginning to wreck the northern Barrens ecosystem.  Sick gazelles have been sighted all north of the east-west road here.  While this water is most likely a primary source of the sickness spreading, there's something else at work here.\n\nThis water, believe it or not, will help us formulate a cure.  While I research this water, I have need of some items to formulate a cure...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6128] = {title = "Gathering the Cure", objective = "Bring 5 Earthroot and 5 Kodo Horns to Tonga Runetotem at the Crossroads so he may make a curative salve.", description = "The water will serve as the base of the curative salve I shall make for the gazelles.  For curative properties, I need some earthroot.  Herbalists know how to find it, so if you are not familiar with this skill you'll need to find one to help us out.\n\nFinally for potency, I need kodo horns - mere chips and fragments will not suffice.  Kodos you can handle wander the northern part of the Barrens; bring some down for the greater good of the balance <name>, and fetch the horns for me.", progress = "Have you got the reagents I need to make the salve?  The gazelle aren't getting any better on their own, so we better not tarry in our effort to save them!", completion = "This is good, &lt;name&gt;, so much so that it should be enough to make some ample doses of the salve - at least enough to start to make a difference.\n\nMaking a cure for poisons can be quite difficult at times because each one often requires a very specific antidote to counteract it.  Imagine being able to cure a poison at will without having to worry about the exact ingredients of what the antidote must be!\n\nNow, let me get to work on this!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6129] = {title = "Curing the Sick", objective = "Use the Curative Animal Salve on 10 Sickly Gazelles that are located throughout the northern part of the Barrens; doing so should cure them. Sickly Gazelles have been reported north of the east-west road that runs through the Crossroads.", description = "I was able to make enough salve for ten doses of curing, <name>.  While I work with local authorities to try and make some more salve, I'd like for you to help us get a head start.  All around the northern Barrens are sickly gazelles; use the salve on them and cure their malaise.\n\nDendrite Starblaze in Moonglade will want to talk to you when you're done, I'm sure.  Please extend our thanks to the Cenarion Circle there... and let me say thanks to you directly for the help you've given!", progress = nil, completion = "You have done well in tending to the sickly gazelles of the Barrens; they are unwitting victims of a greater taint and corruption that is spreading all throughout the land.  You &lt;race&gt; are most eager to understand the ways of Cenarius; you, like your elders in Thunder Bluff, are proving that the need for balance transcends artificial racial barriers.\n\n&lt;name&gt;, you've proven your worth as an friend of nature and the Circle - take this as a symbol of such.", rewards = "You will receive:\n\nVeildust Medicine Bag"}
MultiLanguageQuestData['en'][6130] = {title = "Power over Poison", objective = "Return to Turak Runetotem on the Elder Rise, Thunder Bluff.", description = "You've learned what it means to cure poison without the benefit of spiritual aid.  Remember what others must endure in fighting poisonous afflictions as you soon embrace your newfound power over poison.\n\nYou should now return to Turak Runetotem in Thunder Bluff, <name>.  He, no doubt, has a very important spell to teach you now that the student understands the lesson given unto <him/her>.\n\nFarewell, young druid.  We shall speak again.", progress = nil, completion = "Welcome back - I've been following your progress on this lesson since you left, and I must admit I was surprised to learn about the situation at the Crossroads.  This does bear some further investigation, as the introduction of such poisons into the environment is most upsetting to the balance.\n\nYou handled yourself with grace under pressure.  For that, I can find no better way to reward you than with permanent power over poison.  Use it well, &lt;name&gt;... use it well.", rewards = "The following spell will be cast on you:\n\nCure Poison\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][6131] = {title = "Timbermaw Ally", objective = "Grazle wants you to prove yourself by killing 5 Deadwood Warriors, 5 Deadwood Pathfinders, and 5 Deadwood Gardeners.", description = "The Timbermaw are the only furbolg tribe to escape the corruption. However, many other races kill furbolg blindly now, without bothering to see if they are friend or foe. For this reason, the Timbermaw furbolg trust very few.\n\nAre you interested in proving yourself? Drive back the corrupted Deadwood tribe of Felwood and we may one day consider you an ally. You'll find the first Deadwood tribe - warriors, pathfinders and gardeners - to my west.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6132] = {title = "Get Me Out of Here!", objective = "Escort Melizza Brimbuzzle, then speak with Hornizz Brimbuzzle at the Kodo Graveyard in Desolace.", description = "Get me out of here!\n\nI came up to the Valley of Spears to talk to the Maraudines.  I thought I could do a little business with them... but they don't want to talk!  I think they want to eat me!\n\nGet me out of here and my brother Hornizz will pay you big!  He's at our camp next to the kodo graveyard, to the east.\n\nLet's hurry, <name>.  Not two minutes ago I heard some centaurs talking about getting wood for their cookpot...", progress = "Have you seen my sister Melizza?  She's always on the go, which gets her into trouble all the time.", completion = "My sister Melizza said you'd be coming.  Thanks a lot for getting her out of the jam she was in; it's too bad that she's already probably found herself in a new one!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6133] = {title = "The Ranger Lord's Behest", objective = "Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge.\n\nYou must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen.", description = "The high elves of the Quel'Lithien lodge possesses something that belongs to me, <class>: A document detailing my life as a mortal.\n\nBefore you ask; no, you most certainly are not privy to such information. Just do as I tell you, worm: Recover the registry.\n\nAnd imbecile, be sure to leave as much strife and grief as possible in your wake. Leave them suffering...", progress = "Do not leave me waiting, <class>.", completion = "I trust you did not read the registry. Not even you would do something that idiotic...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6134] = {title = "Ghost-o-plasm Round Up", objective = "Bring 8 Ghost-o-plasms and the Crate of Ghost Magnets to Hornizz Brimbuzzle in Desolace.", description = "There's a valley to the southeast, the Valley of Bones, haunted by Magram ghosts.  Sounds scary, doesn't it?  Well think how scary it is to the Magram!  If we captured ghost energy from that place, I bet it'd be worth plenty to those centaurs.\n\nHere, take this crate of ghost magnets.  If you place one between the two big skeletons in the valley, the Dead Goliaths, then ghosts will wander to it.  Distance yourself, take out the ghosts and get their ghost-o-plasm--that's what we'll sell to the Magram.", progress = "Where's my ghost-o-plasm, <name>?", completion = "There it is!  Looks like you got some of it on you too.  Kinda slimey, eh?\n\nWell, thanks a lot for all the trouble, &lt;name&gt;.  This stuff will be worth a fortune... if I can convince the centaurs what it is!", rewards = "You will be able to choose one of these rewards:\n\nCondor BracersAnchorhold Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6135] = {title = "Duskwing, Oh How I Hate Thee...", objective = "Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller.\n\nIt is said that Duskwing roams the countryside to the north of Marris Stead.", description = "Up until now, you have completed the missions I have assigned; even if not in the most timely manner.\n\nI suppose you think that you are ready for a challenge. Yes... Yes, imbecile, perhaps you are ready for a more involved set of missions.\n\nThe albino demon bat, Duskwing, roams the countryside just north of here. Track him down and destroy him. Return to me with a patch of his white fur and you shall be rewarded.", progress = "I would not recommend that you take on this challenge alone, <class>.", completion = "Excellent work, imbecile. I shall fashion this fur into something you can use.", rewards = "You will be able to choose one of these rewards:\n\nDuskwing GlovesDuskwing Mantle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6136] = {title = "The Corpulent One", objective = "Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete.", description = "Past the Argent Dawn encampment of Light's Hope and west of Northdale, you will find the corpulent maggot beast, Borelgore.\n\nI've lost entire regiments to that monster. His size knows no bounds! The more he eats the greater his girth becomes...\n\nWhile I would not suffer any emotional harm should the beast devour you, I would prefer that you were the victor. Borelgore has been known to devour others who tried to hunt him.", progress = "Have I told you lately that I hate you?", completion = "Keep this up and I may have to promote you from imbecile to mental deficient, first class.", rewards = "You will be able to choose one of these rewards:\n\nIchor SpitterSkullstone HammerSarah's Guide\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6141] = {title = "Brother Anton", objective = "Speak with Brother Anton in Desolace.", description = "My brother in arms, Brother Anton, heard rumors of an undead infestation in distant Kalimdor, in a land known as Desolace.  Anton immediately booked passage to that place, to seek and destroy the undead menace!\n\nHe is looking for those with the bravery and resolve to aid him.  If your heart is true, then speak with Anton.  He is in Desolace, in the Alliance town of Nijel's Point.", progress = nil, completion = "I received word of aid arriving from the east.  Are you the source of these rumors?  Have you come here to help the Scarlet Brother in its crusade?\n\nIf so, then listen close...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6142] = {title = "Clam Bait", objective = "Find 10 pieces of Soft-shelled Clam Meat and bring it back to Mai'Lahii at Shadowprey Village.", description = "You have the look of a fisherman, <class>! I love to fish - been fishing all my life. The best bait to use is soft-shelled clam meat; the fish just can't resist, you know what I mean?\n\nUp north you will find a wrecked ship off the coast. Soft-shelled clams are littered throughout the area. If you bring me back 10 pieces of soft-shelled clam meat, I will give you something in return.", progress = "I can't wait to go fishing with some fresh soft-shelled clam meat; did you bring me the 10 pieces of it I need?", completion = "Perfect mon, this is just what the witch doctor told me to do for my headache. He says, \"Mai'Lahii - go fish. It'll make you feel better\"\n\nWell, I feel better already, thanks mon!", rewards = "You will be able to choose one of these rewards:\n\nPardoc GripsRingtail GirdleBracesteel Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6143] = {title = "Other Fish to Fry", objective = "Slay 7 Slitherblade Myrmidon, 7 Slitherblade Naga, and 5 Slitherblade Sorceresses, and then talk to Drulzegar at Shadowprey in Desolace.", description = "Maybe you heard or maybe you haven't... my crew and I was out fishing near Ranazjar Isle, north of the wrecked ship off the coast up north. We used to fish there all the time; now all I do is think of a way to seek revenge for my fallen comrades.\n\nThe naga attacked us one morning, killing everyone except me.\n\nMe conscience can't handle the guilt, <class>; I need you to go and fry them naga for me. I'll make the effort worth your while; you think you can help me with that?", progress = nil, completion = "As sweet as it is hearing the news that the naga have been vanquished, my heart still feels empty. For the rest of my life I will be dedicated to having them all killed.\n\nHere mon, your reward as I promised. It's small in comparison to the gratification of knowing the naga fried for their hated act upon my crew.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6144] = {title = "The Call to Command", objective = "Travel to the Undercity and speak with Varimathras.", description = "The order has come down, <class>. Varimathras himself has requested that I send my most 'capable' agents back to the Undercity for a highly sensitive tactical operation.\n\nUnfortunately, my most capable agents were killed over three years ago. In their stead I have a collection of brain dead riff-raff.\n\n<Nathanos stares coldly at you.>\n\nTravel to the Undercity at once and report to Varimathras. Do not embarrass me, <class>!", progress = nil, completion = "The Grand Crusader sits safely in the Scarlet Bastion while his forces pour into your lands, desecrate your structures and monuments and murder your people.\n\nThe Dark Lady has commanded that I deal with this insect once and for all. You will become the instrument of the Forsaken's reckoning.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6145] = {title = "The Crimson Courier", objective = "Return to Eastern Plaguelands and track down the Crimson Courier. Kill the Courier and recover the Grand Crusader's Command.\n\nTake the command to Nathanos Blightcaller for further instruction.", description = "Just as the body cannot survive without the head, the head cannot survive without the body. The defenses of the Scarlet Crusade's command inside Stratholme are almost impenetrable. We must, instead, cut the body out from under the head.\n\nMy Deathstalkers have been collecting data on the activity of the Crusade outside of Stratholme. Each day, a report is sent from their central command to Tyr's Hand. This report is the key, <race>! Find the Crimson Courier and recover that report. Return it to Nathanos.", progress = "Succeed now and you will have almost earned my respect, <class>.", completion = "&lt;Nathanos laughs.&gt;\n\nExcellent! Finally! An opportunity to destroy the Scarlet Oracle!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6146] = {title = "Nathanos' Ruse", objective = "Travel to Tyr's Hand, southeast of the Marris Stead. Once there, take a bite of the Rotten Apple. While under the guise of the Scarlet Crusade, deliver the Grand Crusader's Command to Crusader Lord Valdelmar.", description = "I have made some adjustments to this command. Should our little ruse work, they will expose the Scarlet Oracle and we shall strike!\n\nNow pay attention, <class>. You are to deliver this command to the Crusader Lord, Valdelmar.\n\nHow? You are going to hand it to him, imbecile.\n\nTake the command and this rotten apple to Tyr's Hand. When you cross into the city, eat the apple. You will transform into something more... palatable to the humans. Take the command and hand it to the Crusader Lord, Valdelmar.", progress = "This is unacceptable, soldier!", completion = "Where have you been? We had thought the Scourge had captured you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6147] = {title = "Return to Nathanos", objective = "Return to Nathanos Blightcaller with the new information.", description = "The Grand Crusader makes an unusual request. Hrm, regardless... what he asks will be done. Return to the Scarlet Bastion and notify him that the Oracle will be en route shortly.\n\nWe will take every precaution to ensure that she makes it to Stratholme unharmed.", progress = nil, completion = "The fools! My deception went unnoticed! Prepare yourself, &lt;class&gt;. We must strike with cold cunning!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6148] = {title = "The Scarlet Oracle, Demetria", objective = "The Scarlet Crusade is on the move. Somewhere along the road from Tyr's Hand to Stratholme you will find the Oracle, Demetria, and her entourage. Hunt her down and slay her. Return to Nathanos Blightcaller should you succeed.", description = "Demetria is chief advisor to the Grand Crusader. She is called the Oracle due to her 'otherworldly' senses. She has successfully assisted the Crusade in several of their victories against the Scourge.\n\nWhile this ruse was successful in exposing her, if she truly does possess psychic powers, she will undoubtedly be expecting some sort of trouble. You are going to provide that 'trouble.'\n\nTrack down the Oracle and terminate her. They should be moving out of Tyr's Hand as we speak. Make me proud, worm.", progress = "What is your status, <name>?", completion = "They will be reeling from this blow for years! Well done, &lt;name&gt;! You have earned not only my respect but also this reward.", rewards = "You will be able to choose one of these rewards:\n\nGorewood BowStormragerSacred Protector\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6161] = {title = "Claim Rackmore's Treasure!", objective = "Find Rackmore's Silver Key. Find Rackmore's Golden Key. Find and open Rackmore's Chest.", description = "Rackmore's log tells of how his ship was sailing for Feathermoon Stronghold when it was attacked by seafaring creatures.  To prevent his treasure from falling into enemy hands, he hid his chest on Ranazjar Isle.\n\nTo open the chest requires two keys, a silver and a gold.  These keys were lost, but if the keys and the chest are found, a treasure awaits!", progress = "This chest is securely locked.", completion = "Chest opens to reveal Rackmore's treasure!", rewards = "You will receive:\n\nCaptain Rackmore's WheelCaptain Rackmore's Tiller"}
MultiLanguageQuestData['en'][6162] = {title = "A Husband's Last Battle", objective = "Kill Overlord Ror and return his claw to Dreka'Sur at Bloodvenom Post in Felwood.", description = "My husband traveled Felwood for the honor of our clan, doing battle against the Shadow Council and other corrupt atrocities!\n\nAfter he escaped death numerous times, I received a letter from him saying that a druid asked him for help against a great befouled furbolg named Overlord Ror--the two were never heard from again.\n\nI want this Ror's clawed hand, <name>. I want it to pay for leaving me a widow! I believe the creature is to the south... near the Ashenvale border.", progress = "Do you have the beast's claw yet, <name>? It will pay for its crimes. I don't care if it's corrupt or just angry for living in such a dismal forest. No furbolg will live for long committing such crimes against my family!", completion = "You bring honor to me for following through with your word. My husband died in battle--he would have been proud of that. But I could not rest until I knew that the creature that has forced me to live my life alone paid for what it had done.\n\nThank you again, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6163] = {title = "Ramstein", objective = "Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos.", description = "I was overwhelmed. On this very stead, I stood... held my ground in defense of Lordaeron. The farm and all on it were waylaid by a gigantic wave of Scourge.\n\nThe wretch. The filth. It hovered above me, entrails hanging from its gaping chest cavity.\n\nI woke as Scourge. For so long I was helpless. My mind had coalesced with the Lich King's.\n\nShe came for me... somewhere, somehow, I knew she would. Free.\n\nAnd now, I must have my vengeance - my vengeance on that which took from me my life. Destroy it.", progress = "After Sylvanas freed me, I hunted the beast across these wastes for months. It fled to the safety of Stratholme. The bastard...", completion = "I wonder... did it beg for mercy? Could it know what mercy is?\n\n&lt;Nathanos spits.&gt;\n\nI will hang this beast's head upon my wall.\n\nYou have earned a spot amongst one of my champions, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nRoyal Seal of AlexisElemental Circle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6164] = {title = "Augustus' Receipt Book", objective = "Bring Augustus' Receipt Book to Augustus the Touched in Terrordale.", description = "I'm ready for business!  What you do want?\n\nOh wait... I can't open up shop without my receipt book.  How am I to keep track of things without my receipt book?\n\nI must have left it in town somewhere.  I had a room in the inn... the book must be there.\n\nBring me my book.  Please, bring it to me!  Bring me my book and you'll see!  I'll set up shop and you'll see that my prices are INSANE!", progress = "Do you have my receipt book?  I can't wait to get back to business!", completion = "There it is!  And oh my!  I forgot how full it was!\n\nThis is a glorious day, &lt;name&gt;!  Stupendous!  Insanely good, I say!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6181] = {title = "A Swift Message", objective = "Bring Lewis' Note to Thor the gryphon master.", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Thor, our gryphon master.  He's just down the hill; bring him my note, and then take a gryphon to Stormwind.", progress = "You look like you're in a hurry.  Well, then you came to the right place!", completion = "You have to get this note to Stormwind?  That's not a problem, you can take one of my gryphons!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6182] = {title = "The First and the Last", objective = "Speak with Mathias Shaw in Old Town Stormwind. He resides in the Barracks.", description = "Nathanos Marris was the first and last of the human ranger lords. A disciple of Sylvanas Windrunner, now the Banshee Queen of the Forsaken.\n\nWe had thought that Nathanos had been killed in action in the defense of Lordaeron five years ago. Although his corpse was never recovered, it was assumed that he did not make it out of the Eastern Plaguelands.\n\nMathias Shaw has been investigating the disappearance and may have some new information. Report to him at once. He resides in Old Town, at the Barracks.", progress = nil, completion = "After some reports of unusual Forsaken activity in the Eastern Plaguelands, SI:7 agents were dispatched to investigate. The results of that investigation are unsettling.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6183] = {title = "Honor the Dead", objective = "Speak with Mathias Shaw again if you wish to accept his task.", description = "Five of my best field agents were assigned the Marris case. One returned, only to end up dead in his sleep three days later.\n\nWhat little information we did manage to get out of him was incoherent gibberish. We made out two words: \"Nathanos,\" and \"Blightcaller.\"\n\nI do not have the available manpower to continue this investigation and Ravenholdt will not assist us. We must get to the bottom of this; if only to provide closure to the families of the deceased. Will you help?", progress = nil, completion = "&lt;Mathias nods.&gt;\n\nI had faith that Bolvar would send me men and women of honor - the most dedicated soldiers of the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6184] = {title = "Flint Shadowmore", objective = "Travel to Chillwind Camp in the Western Plaguelands and meet up with your contact, Flint Shadowmore.", description = "The only information we have thus far, then, is that Nathanos Marris may have been slain by this Blightcaller. We assume the Blightcaller is the same fiend that disposed of my agents.\n\nFlint Shadowmore, another SI:7 operative, is stationed at the Alliance encampment of Chillwind Point in the Western Plaguelands. Seek him out; he will debrief you on the current situation in the Plagues and give you an assignment.\n\nGood luck, <name>.", progress = nil, completion = "The first mission will be straight up, &lt;name&gt;. You go in, you come out. Recon...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6185] = {title = "The Eastern Plagues", objective = "Scour the Eastern Plaguelands for clues as to the \"Blightcaller\" and the missing SI:7 agents. If you find any SI:7 Insignias, return them to Flint Shadowmore at Chillwind Camp.", description = "As I said, your first mission is one of reconnaissance. Nothing fancy, <name>. You must travel to the Eastern Plaguelands and look for any clues as to this Blightcaller.\n\nBe on the lookout for information about our missing operatives. We have to assume that they are dead and if they are dead, they must have a corpse... somewhere.\n\n<Flint swallows hard.>\n\nAll SI:7 agents carry this insignia.\n\n<Flint shows you his SI:7 insignia.>\n\nBring any of those that you may find back to me.", progress = "An... Any luck??", completion = "Rutger. Fredo. Turyen. All... dead...\n\n&lt;Flint clutches the insignias tightly.&gt;\n\nWhere were they? Did you discover any more information about this bastard, the Blightcaller?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6186] = {title = "The Blightcaller Cometh", objective = "Return to Stormwind and inform Highlord Bolvar Fordragon of the fate of Nathanos Marris.", description = "<The blood appears to have completely drained from Flint's face.>\n\nNa... Nathanos did this? Nathanos is the Blightcaller?\n\nWhy? He was... was so noble - a ranger lord respected by all. The only human ever allowed to train under the high elves. Now a ruthless agent of the Forsaken?\n\nI... I am sorry to ask this of you, <name>, but Highlord Fordragon must be informed of this turn of events at once. Please, return to Stormwind and deliver the news.", progress = nil, completion = "No. It... NO! How? An agent of the Forsaken? The CHAMPION of the Banshee Queen???\n\n&lt;Highlord Bolvar Fordragon slumps in defeat.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6187] = {title = "Order Must Be Restored", objective = "Assemble an army and travel to the Eastern Plaguelands. Launch a full assault on Nathanos Blightcaller and any Horde filth that may attempt to protect him.\n\nKeep your wits about you, <name>. The Horde will defend the ranger lord with their very lives.", description = "Do you know how many ranger lords exist in this world? How many human ranger lords have ever existed?\n\nNathanos' accomplishments were unprecedented. He was a tactical genius, responsible for Alliance victories spanning a decade of conflict.\n\nAnd now... the champion of the Forsaken.\n\nNo. This cannot be. Order must be restored.\n\nGather an army, <name>. Return to the Plagues with your army and destroy the Blightcaller.\n\nI wish you luck, <name>. Truly, you will need it for this battle.", progress = "<Highlord Bolvar Fordragon is lost in thought.>", completion = "It is a tragedy. I think... I believe that our kind is cursed, &lt;name&gt;. We are cursed to lose our greatest warriors; our most noble heroes; our most gifted scholars.\n\nWe are indebted to you and I assure you, &lt;name&gt;, wherever Nathanos Marris is now, he smiles down upon you.", rewards = "You will be able to choose one of these rewards:\n\nGorewood BowStormragerSacred Protector\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6221] = {title = "Deadwood of the North", objective = "Nafien would like you to kill 5 Deadwood Den Watchers, 5 Deadwood Avengers, and 5 Deadwood Shamans.", description = "There is a camp of Deadwood furbolgs directly to our southwest.  Corruption permeates the camp, and I wish to put an end to it before they become a problem.\n\nThe Deadwood tribe is evil, but it is the effects of the fel that pollutes their minds.  Their hostility is not truly an innate quality, yet they cannot be helped.  For this reason, I am deeply saddened by having to fight my own brethren.\n\nPlease, <name>, do what must be done, and do not mention the details; they upset me far too much.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6241] = {title = "Winterfall Activity", objective = "Salfa wants you to kill 6 Winterfall Totemics, 6 Winterfall Den Watchers, and 6 Winterfall Pathfinders.", description = "The Timbermaw tend to stay to themselves, <name>. While we do allow safe passage to those that have proven they can be trusted, we try to avoid other furbolg tribes if at all possible.\n\nLately I have noticed that the Winterfall tribe has become increasingly hostile towards us. They seem to be in a state of rage, completely engulfed by their own fear and hatred of anything they do not understand.\n\nIf you could reduce their numbers this would help us greatly, <name>.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6261] = {title = "Dungar Longdrink", objective = "Bring Osric's Crate to Dungar Longdrink the gryphon master.", description = "<name>, I gathered into this crate everything Lewis asked for.  Can you take it to him?\n\nIf you've already spoken to Thor in Westfall, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Lewis as fast as you can.  We don't want our fighting men and women in Westfall to go without fresh equipment!", progress = "Is that sweat on your brow, lad?  You've been running too much.  Next time, take a gryphon!", completion = "A crate for Westfall, eh?  Have you been to Westfall before?  If so, then it's no problem, my friend.  I have plenty of gryphons trained to fly that route!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6281] = {title = "Continue to Stormwind", objective = "Buy a gryphon ride from the gryphon master Thor, then bring Lewis' Note to Osric Strang, in the shop Limited Immunity, in the Old Town of Stormwind.", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Lewis' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", progress = "You've been traveling, eh?  Have you been anywhere interesting?", completion = "Ah, a note from Quartermaster Lewis?  I'm not surprised he needs more gear.  Sentinel Hill is far away, in a land Stormwind has all but forgotten.\n\nWell thank you, &lt;name&gt;.  Here's some money to cover your travel costs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6282] = {title = "Harpies Threaten", objective = "Maggran Earthbinder in Sun Rock Retreat wants you to slay 7 Bloodfury Harpies, 7 Bloodfury Ambushers, 7 Bloodfury Slayers and 7 Bloodfury Roguefeathers.", description = "Tauren take pride as the protector of these lands. Undoubtedly you can guess why I am alarmed with the number of harpies that dwell here in Stonetalon.\n\nThe Bloodfuries are the source of the increasing number of harpies in Kalimdor; they encroach upon all likes of life preventing the innocent from leaving their boundaries.\n\nI need you to cull the harpies, <name>!", progress = "Do not be weary of Charred Vale; many evil creatures reside in those hills. Stay strong <name>, and you shall prevail over this threat to our people. Go now and strike hard - our children shall never know of the evil of what was.", completion = "This is most excellent news! Tell me again how you cast fear into the cold hearts of those vile harpies. The Bloodfuries have been dealt a serious blow!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6283] = {title = "Bloodfury Bloodline", objective = "Maggran at Sun Rock Retreat wishes you to slay Bloodfury Ripper and bring her remains as proof of your deed.", description = "Limiting the number of Bloodfury Harpies will not be enough. The only true cure for their disease would be to slay their leader, Bloodfury Ripper!\n\nShe is all but a queen to those filthy creatures. Slay her and their numbers will surely diminish.\n\nGo back into the Charred Vale and you will find her along the western hills. She will not be easy to vanquish, but the reward will be great.", progress = "Bloodfury Ripper is a nasty creature! You will have success finding her along the western hill line in the Charred Vale.\n\nThe bloodfuries will be helpless with out... surely we can vanquish them forever!", completion = "Already I feel the anger leave me. What will I do with my time? Knowing evil moves near my land kept my thoughts moving, though now they are silent. Perhaps this is a good thing... maybe now I can focus on the good, as all Tauren should.\n\nPlease accept this as a reward for your troubles.", rewards = "You will be able to choose one of these rewards:\n\nSpritekin CloakScreecher Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6284] = {title = "Arachnophobia", objective = "Kill Besseleth and bring Besseleth's Fang to Maggran at Sun Rock Retreat.", description = "Warning: Proceed into Sishir Canyon west of here at your own risk.\n\nBesseleth and her eight-legged children of the forest have claimed this canyon as their webbed lair.\n\nMaggran Earthbinder in Sun Rock Retreat has placed a bounty on Besseleth. Slay her and bring proof of your killing to Maggran; there you will receive your reward for disposing this eight-legged menace.", progress = "Besseleth is a ruthless predator... I fear for those that travel Webwinder Path at night. It's then that she and her children prey upon innocent travelers. I myself fell prey to her two-foot fang of death, but luckily I was able to fend her off and get to safety. I would give anything to see that monster destroyed.", completion = "Good hunting, &lt;name&gt;! Besseleth is an old predator in these parts... I will miss her not. Take this reward as a token for being the forest champion.\n\n\n\nPerhaps now many more will travel to Sun Rock Retreat without fearing what lurks in the dark.", rewards = "You will be able to choose one of these rewards:\n\nClaystone ShortswordClear Crystal Rod\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6285] = {title = "Return to Lewis", objective = "Buy a gryphon ride to Sentinel Hill from the gryphon master Dungar Longdrink, then take Osric's Crate to Lewis at Sentinel Hill.", description = "The gryphon master in Westfall is Thor.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Thor, so just speak with me again when you're ready to take a gryphon to Westfall.  Once there, you can deliver Osric's Crate to Quartermaster Lewis.", progress = "You're back from Stormwind?  Did Osric send the armor?", completion = "Great, you brought the armor!  We'll get this divvied to those who need it immediately.\n\nThank you, &lt;name&gt;.  Your efforts have been a great help to us.  And now that you're no stranger to gryphons, I hope you'll come and lend your aid to Sentinel Hill often!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6301] = {title = "Cycle of Rebirth", objective = "Tammra Windfield at Sun Rock Retreat wants you to gather 10 Gaea Seeds.", description = "Industrial greed and continuous war have wrecked the lands of Stonetalon. Only the blessings of the Earthmother can cure such injury.\n\n<name>, I will require you to seek a special seed, the Gaea seed. They are only found here in Stonetalon Mountain, north of Sun Rock Retreat at Mirkfallon Lake, near the water's edge.\n\nOnce you bring me the seeds I will imbue them with shamanistic power to speed their growth.", progress = "The continuous destruction caused by war and those that seek a profit from lumber pains me deeply. To aid the cycle of rebirth and replenish the lands, I need Gaea seeds. Do you have them, <class>?", completion = "Ah, &lt;name&gt;, you have the Gaea seeds. Watch and see how the blessing of the Earthmother can cause even these small kernels of life to bloom and flourish.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6321] = {title = "Supplying the Sepulcher", objective = "Bring Podrig's Order to Karos Razok.", description = "Executor Hadrec asked me to take stock of our equipment at the Sepulcher.  With the Scourge, and worse, lurking in the woods, he doesn't want the Deathguards to lack gear they might need.\n\nI found that we are, in general, well stocked, but we do need more weapons to replace those lost in the field.\n\nHere is a requisition order of what is needed, for the weapon dealer Gordon Wendham in the Undercity.  Take the order to our bat master, Karos Razok, and speak with him about transport to the Undercity.", progress = "You appear to be on official business...", completion = "Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6322] = {title = "Michael Garrett", objective = "Bring Gordon's Crate to Michael Garrett.", description = "I have placed the Sepulcher's supplies into this crate.  If you have already visited the Sepulcher and spoken with their bat master, then you may ride a bat back to him.\n\nSpeak with the Undercity's bat master, Michael Garrett.  He can provide you with a bat to the Sepulcher.", progress = "If you must travel a long distance, then a bat is your best option.", completion = "This crate must reach the Sepulcher in Silverpine?  That is easily done; our bats fly there daily.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6323] = {title = "Ride to the Undercity", objective = "Buy a bat ride to the Undercity from the bat master Karos Razok, then take Podrig's Order to Gordon Wendham in the Undercity.", description = "One of my bats can take you to the Undercity, for a small fee.  Speak with me again when you are ready so that we may arrange your transport.\n\nYou will find Gordon Wendham in the Trade Quarter of the Undercity.  That is the same quarter where my bat will land.", progress = "I keep my weapons in top condition.  They are cleaned and ready for use.", completion = "An order from the Sepulcher?  Very well.  It is an honor to serve those who serve our Dark Lady.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6324] = {title = "Return to Podrig", objective = "Buy a bat ride to the Sepulcher from the bat master Michael Garrett, then bring Gordon's Crate to Deathguard Podrig in the Sepulcher.", description = "The bat master in the Sepulcher is Karos Razok.  If you have already met him, then I can give you a bat to fly back to him.\n\nOur bats will always fly to the Undercity, but to travel to more remote locales their rider must first visit the area and speak with its bat master.\n\nYou have met Karos in the Sepulcher, so you may now fly bats there.  Speak with me again when you are ready.", progress = "<name>, you return.  Do you have our supplies from the Undercity?", completion = "Good work, &lt;name&gt;.  These weapons will ensure our Deathguards don't get caught unprepared.\n\nYou have done a valuable service for our Dark Lady.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6341] = {title = "The Bounty of Teldrassil", objective = "Bring Nessa's Collection to Vesprystus.", description = "The fishermen of Rut'theran village do very well, for the fish here are extremely large and abundant.  I would like to compare the bounty here with that of the mainland.\n\nI have a collection of fish bones and scales that I would like taken to a colleague of mine in Darkshore.  His name is Laird, he is a fish vendor in the village of Auberdine.\n\nBring my collection to our hippogryph master, Vesprystus, and speak to him about traveling to Auberdine.", progress = "How may I help you?  Are you in need of transport?", completion = "Ah, you wish to get this to Auberdine?  Very well...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6342] = {title = "Flight to Auberdine", objective = "Ride a hippogryph to Auberdine from the hippogryph master Vesprystus, then bring Nessa's Collection to Laird.", description = "From Rut'theran, there are two methods of travel to Auberdine: by ferry and by hippogryph.  Both are quick and reliable, but if you have not yet flown to Auberdine by hippogryph, then I suggest you do.\n\nIt is sound advice to speak with the hippogryph master in every town that has one.  Once you speak to the master, you can then fly there from other towns.\n\nHere is Nessa's collection.  Speak with me again when you are ready to fly to Auberdine and deliver Nessa's collection to Laird.", progress = "Have you come from Teldrassil?  Tell me, how is the fishing there?", completion = "A package from Nessa?  Thank you, &lt;name&gt;!  She told me she would send me samples of the fish caught near Rut'theran village.  She thinks they may be very different from the fish caught here...\n\nMy!  This jawbone is nearly twice the size of the same fish found here.  And these scales are as big as a closed fist!  Amazing!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6343] = {title = "Return to Nessa", objective = "Bring Laird's Response to Nessa Shadowsong.", description = "I must send a response to Nessa.  She'll be very interested to know how different the fish here are from those along Teldrassil's coastline.  We can only guess the cause, but it is my suspicion that the world tree itself is affecting the wildlife around it!\n\nPlease, take this response to Nessa.  If you wish to take a hippogryph back to Rut'theran then speak with the hippogryph master Caylais Moonfeather.  If you wish to take the ferry, then one regularly departs from the dock to the northwest.", progress = "<name>, you're back from Auberdine?  Did you speak with Laird?", completion = "This is very interesting.  The fish here are large, but I didn't think the difference in bounties between here and the mainland was so great.  There must be a reason for this...\n\nWell thank you, &lt;name&gt;.  I will discuss with the villagers the news you brought.  Perhaps, one day, we will find the root of this oddity.  But until then, we shall reap its benefits!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6344] = {title = "Nessa Shadowsong", objective = "Speak with Nessa Shadowsong.", description = "A friend of mine, Nessa Shadowsong, is a fishing merchant in Rut'theran Village.  She needs a parcel taken to Darkshore, and is looking for someone to help her.\n\nIf you're interested, then to reach Nessa you must take the portal in Darnassus to Rut'theran Village.  You will find the portal west of the Temple Gardens.", progress = nil, completion = "Yes, I have need of a courier who will take a package to Darkshore.  Will you help me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6361] = {title = "A Bundle of Hides", objective = "Bring the Bundle of Hides to the wind rider master Devrak in the Crossroads.", description = "I have a bundle of hides from the animals of the Barrens, and must get them to Thunder Bluff.  A colleague there, Ahanu, will use the hides to create leather goods.\n\nWill you take the hides to him for me?\n\nThe quickest way to Thunder Bluff is on the back of a wind rider.  Bring the bundle of hides to Devrak, our wind rider master in the Crossroads, and speak to him about transport to Thunder Bluff.", progress = "Are you here for a wind rider?  You have something to transport?", completion = "If you must take these hides to Thunder Bluff, then you are speaking to the right orc!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6362] = {title = "Ride to Thunder Bluff", objective = "Buy a wind rider to Thunder Bluff from the wind rider master Devrak, then bring the Bundle of Hides to Ahanu in Thunder Bluff.", description = "For a small fee, I will give you a wind rider to Thunder Bluff.  There's no faster way to the city!\n\nIf that is acceptable, speak to me again when you are ready to go.\n\nIf you're taking those hides to Ahanu, then I think he's at Hewa's Armory, at the base of the wind rider tower in Thunder Bluff.  And that's right where you'll land!", progress = "There is dust on your shoulders that must be from the Barrens.  You have spoken with my friend Jahan?", completion = "Ah, a new bundle of hides.  I will get to work on these immediately!\n\nThank you, brother.  You have done me a great service.  Here are some coins to pay for your time and travel costs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6363] = {title = "Tal the Wind Rider Master", objective = "Bring Ahanu's Leather Goods to Tal in Thunder Bluff.", description = "I have prepared leather goods for Jahan to sell at the Crossroads.  Will you bring them to him?\n\nIf you have already been to the Crossroads and spoken to their wind rider master, then you can fly one of our Thunder Bluff wind riders back to him.\n\nTake the leather goods to Tal, our wind rider master in Thunder Bluff, and speak with him to arrange transport to the Crossroads.", progress = "Greetings, <class>.  What can I do for you?", completion = "You need to take this to the Crossroads, eh?  That's not a problem.  If you've already been there and spoken to Devrak, then you can take one of my wind riders back to him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6364] = {title = "Return to Jahan", objective = "Buy a wind rider to the Crossroads from the wind rider master Tal, then bring Ahanu's Leather Goods to Jahan Hawkwing.", description = "In order to fly to a town, you must have already been there and spoken with the wind rider master of that town.  You have been to the Crossroads and spoken to their wind rider master Devrak, so for a small fee you can take a wind rider to him from here.\n\nSpeak with me again when you are ready.  Once at the Crossroads, you can then deliver the leather goods to Jahan Hawkwing.", progress = "<name>, you are back from Thunder Bluff?  Did you deliver the hides to Ahanu?", completion = "Ahanu sent me finished products?  Very good.  There are many hunters and adventurers in the Crossroads now and business is lively.  I am sure I'll sell these goods very soon.\n\nThank you for all your efforts, &lt;name&gt;.  I am in your debt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6365] = {title = "Meats to Orgrimmar", objective = "Bring Zargh's Meats to Devrak in the Crossroads.", description = "I have some choice cuts of meat that I want to send to a friend.  Her name is Gryshka, the innkeeper in Orgrimmar.  Will you deliver the meat for me?\n\nThe fastest way to Orgrimmar is on a wind rider.  Take the meats to the Crossroads wind rider master, Devrak, and speak with him about transport to Orgrimmar.", progress = "You need to get somewhere fast?  Then you're talking to the right <race>!", completion = "You have to get this meat to Orgrimmar?  That is no problem.  For a small fee, my wind rider can take you there.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6381] = {title = "New Life", objective = "Plant 10 Gaea Seeds in Gaea Dirt Mounds, and then return the remaining Enchanted Gaea Seeds to Tammra at Sun Rock Retreat.", description = "As you have seen, <class>, though the land is in pain, the cycle of life is a powerful thing. Now we must do our part help it along. You must plant these seeds at the center of the destruction, to the west, in the Charred Vale. Beware, for harpies and angry fire elementals still plague the scarred land.\n\n<name>, take these enchanted Gaea seeds and plant them in fertile mounds of soil. The cycle of life must go on!", progress = "These seeds you plant are strong, resisting corruption, and making a foothold for other life. They will grow and grow, first preventing corruption and healing the scarred land, and then one day, restoring Stonetalon to a lush forest, once again.\n\nHave you planted all of the Gaea seeds?", completion = "This is great victory for the land. In time, other things will come to pass: the Venture Co. will pack up their buzz saws and axes, the angry fire spirits will calm, and the harpies will be pushed out by the land.\n\nOnly then &lt;name&gt;, will Stonetalon be truly at peace.\n\nYou have done well &lt;class&gt;; take one of these items as thanks for the new life you have created here today.", rewards = "You will be able to choose one of these rewards:\n\nWindseeker BootsSandspire Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6382] = {title = "The Ashenvale Hunt", objective = "Speak with Senani Thunderheart at Splintertree Post, Ashenvale.", description = "Your strength impresses me, <class>.  Your willingness to embrace the hunt gives me confidence that you could move on to bigger game... and bigger challenges.\n\nThe forests of Ashenvale represent a vast untamed wild that the Horde seeks to impose its own will upon, both politically and spiritually.  If you seek to prove yourself in an unproven land, seek the guidance of Senani Thunderheart in Splintertree Post.  The outpost is due north of the path leading from the Barrens.", progress = nil, completion = "Welcome to the new frontier, &lt;name&gt;.  Ashenvale is a land of opportunity, one where a young &lt;class&gt; like yourself is able to find boundless chances to prove their mettle.  Look around the outpost here, and be sure to travel out to the Zoram Strand, as the Horde has another outpost there as well.\n\nYour presence here tells me that you've come to learn more about the hunt.  Listen close, and I will gladly share with you what you need to know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6383] = {title = "The Ashenvale Hunt", objective = "There are three legendary creatures that make up the Ashenvale Hunt; you may seek them and test yourself against their cunning and might.  In the process, you will hopefully learn something about yourself.  The creatures are: the bear Ursangous, the nightsaber cat Shadumbra, and the hippogryph Sharptalon.\n\nThe creatures of the Ashenvale Hunt are powerful, and you may find that you'll need aid in bringing them down.  If you should best them, bring me proof of your deed.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6384] = {title = "Ride to Orgrimmar", objective = "Buy a wind rider to Orgrimmar from the wind rider master Devrak, then bring Zargh's Meats to Gryshka in Orgrimmar.", description = "For just a few coins I will have a wind rider bring you to Orgrimmar.  When you get there, you can take Zargh's Meats to Gryshka.  Her inn is in the Valley of Strength, not far from the Skytower, where my wind rider will drop you off.\n\nSpeak with me again when you are ready for the journey.", progress = "Something smells good!  You don't have raw meat on you, do you?", completion = "Oh, wonderful!  Those are fine cuts!  These are from Zargh, are they?  That &lt;race&gt; sure knows his way into a lady's heart...\n\nOh, I can't wait to cook it.  But not too much!  Meat is best served rare, don't you think?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6385] = {title = "Doras the Wind Rider Master", objective = "Bring Gryshka's Letter to Doras in Orgrimmar.", description = "I've written a letter of thanks to Zargh.  Will you deliver it for me?  If you've already been to the Crossroads and spoken with their wind rider master, then you can fly a wind rider back there.\n\nTake my letter to Doras, the wind rider master of Orgrimmar, and speak with him about transport to the Crossroads.", progress = "Do you need one of my wind riders?", completion = "You have to get this to the Crossroads in the Barrens?  Yes, I can get you there...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6386] = {title = "Return to the Crossroads.", objective = "Buy a wind rider to the Crossroads from the wind rider master Doras, then bring Gryshka's Letter to Zargh at the Crossroads.", description = "My wind riders are trained to fly to many different places, as long as you have already been to that place and spoken with the wind rider master there.\n\nYou have been to the Crossroads and spoken to their wind rider master Devrak, so now you can fly directly to him from here.  Once you're at the Crossroads, you can deliver Gryshka's letter to Zargh.\n\nSpeak with me when you are ready to go.", progress = "Have you returned from Orgrimmar?  Did Gryshka like the meat I sent her?", completion = "Hah!  I guess she liked it!  Nothing brings red to a lady's cheeks like a big, juicy steak!\n\nThank you, &lt;name&gt;.  You've done me a great service.  Here is some money for your trouble, and don't be surprised if I invite you to my wedding!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6387] = {title = "Honor Students", objective = "Bring Brock's List to Thorgrum Borrelson in Thelsamar.", description = "I see a lot of young dwarves at my door, eager to learn the trade of mining.  And if there's one thing a miner needs more than anything, it's a pick!\n\nI have a list of mining students who scored high in their lessons and earned an honorary pick.  Take my list to Golnir Bouldertoe in Ironforge.  He'll get the picks ready.\n\nThe fastest way to Ironforge is on a gryphon, so bring the list to our gryphon master, Thorgrum Borrelson, and speak with him about transport to Ironforge.", progress = "Have you had your fill of Thelsamar so soon?  Are you ready to leave for another city?", completion = "You have to get this to Ironforge, eh?  For a small fee I can put you on the back of one of my gryphons, and it'll take you there.  How does that sound?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6388] = {title = "Gryth Thurden", objective = "Bring the Honorary Picks to Gryth Thurden in Ironforge.", description = "Here are the honorary picks for Brock's students.  If you've already been to Thelsamar, then you should fly a gryphon back there!\n\nTake the picks to our gryphon master, Gryth Thurden, and speak with him about a ride back to Thelsamar.", progress = "You look like you have somewhere to go.  Need one of my gryphons?", completion = "You have to get these to Thelsamar, eh?  That won't be a problem.  As long as you've already been to Thelsamar and spoken to Thorgrum Borrelson, then you can take one of my gryphons back to him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6389] = {title = "A Plague Upon Thee", objective = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Nathaniel Dumah at Chillwind Camp in Western Plaguelands.", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", progress = "Have you done it, <name>? Have you released the termites? The Light help us if the Scarlet Crusade were able to hold onto both the mill and Hearthglen. They should have neither. They're just capitalizing on the victims of the last war and should be put down like rabid animals!", completion = "Haha! Thank you, &lt;name&gt;! You've done it! My father's spirit can now rest and I can live in peace.\n\nThank you again. If there is anything I can do for you, please, just ask.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6390] = {title = "A Plague Upon Thee", objective = "Release the Plagueland Termites in the Northridge Lumber Mill, then return with the Barrel of Plagueland Termites to Mickey Levine at the Bulwark in Tirisfal Glades.", description = "You look around the lumber mill for something suitable to open the barrel with. You find a crowbar that looks like it will do the trick.\n\nYou set your feet and pray that you'll be able to get out of the mill before the termites get to you.", progress = "Have you done it, <name>? Have you released the termites in the lumber mill?\n\nIt was bad enough that my family lost their jobs and lives, but then to see the place where my childhood was spent taken over by those disgusting so-called holy men... pfah!!", completion = "Thank you, &lt;name&gt;. Here, take this coin. I'm sorry it's not more, but try to take some joy in helping destroy the Scarlet Crusade's efforts!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6391] = {title = "Ride to Ironforge", objective = "Buy a gryphon to Ironforge from the gryphon master Thorgrum Borrelson, then bring Brock's List to Golnir Bouldertoe in Ironforge.", description = "For just a few coins, one of my gryphons will take you to Ironforge.  From there, deliver Brock's list to Golnir Bouldertoe.  You'll find him in the Deep Mountain Mining Guild.  That's in the Great Forge District of Ironforge, which is right where my gryphon will drop you off!\n\nSpeak to me again when you're ready for the journey.", progress = "What can I do for you, sir?", completion = "Ah, the lastest list of Brock's best pupils.  I have a batch of honorary picks ready to go.  I just need to chisel in the names of the students...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6392] = {title = "Return to Brock", objective = "Buy a gryphon to Thelsamar from the gryphon master Gryth Thurden, then bring the Honorary Picks to Brock Stoneseeker in Thelsamar.", description = "For a small fee you can buy a gryphon ride to Thelsamar... as long as you've already been there.  Gryphons will only fly you to places you've already been, so be sure to speak with every gryphon master you see so you can fly to him later.\n\nYou've already been to Thorgrum, the gryphon master of Thelsamar, so now you can return to him.  And once in Thelsamar, you can deliver the picks to Brock Stoneseeker.\n\nSpeak with me when you're ready to go.", progress = "Ah, <name>.  Have you returned from Ironforge?", completion = "You brought the picks.  Great!  I'll get these to my mining students.  I'm sure they're eager to use them on the ore deposits of Loch Modan.\n\nThank you for your help, &lt;name&gt;.  I am in your debt, but I hope this money will at least cover your travel costs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6393] = {title = "Elemental War", objective = "Bring 10 Incendrites to Tsunaman at Sun Rock Retreat.", description = "The Tribunal of the Tides has sent me to wage war on the fire elementals here in Stonetalon Mountain. Neptulon the Tidehunter, Lord of all water elementals, has taken a personal interest in seeing our fiery cousins extinguished.\n\n<name>, you can help me gain favor with the Tribunal by destroying the fire elementals in Charred Vale. When destroyed, the fire elementals leave Incendrites. Return these to me and be rewarded.", progress = "The Tribunal of the Tides grows impatient. They seek to end this war that has raged across all dimensions for eons. My brethren are anxious to hear news of the glorious victory over the hated fire elementals. Have you the Incendrites that I require?", completion = "The water spirits within me bubble with the excitement. &lt;name&gt;, you have given me a glorious victory to report to the Tribunal of the Tides.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6394] = {title = "Thazz'ril's Pick", objective = "Bring Thazz'ril's Pick to Foreman Thazz'ril.", description = "<name>, you are a dependable <race>.  Can I count on you for another task?\n\nSome time ago I was surveying the cave to the north for minerals, and I left my favorite pick behind.  When I later returned to retrieve it I found the cave was filled with vicious beasts!  Will you go into the cave, the Burning Blade Coven, and get my pick?\n\nI left it in a chamber with waterfalls.  My pick has a spell on it so you can see it in the dark, so you won't have to worry about finding it... just what's guarding it!", progress = "Have you entered the Burning Blade Coven, <name>?  Did you find my pick?", completion = "Great, you got it!  Thanks a lot, &lt;name&gt;.  This is my favorite pick!  Now if my peons ever finish chopping down these trees, maybe we can find a nice cave to mine!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6395] = {title = "Marla's Last Wish", objective = "Bring Samuel Fipps' Remains to Marla's Grave, then return to Novice Elreth.", description = "My friend Marla Fipps lived with her husband Samuel before the plague, but when the plague came Samuel succumbed and joined the Scourge's ranks.\n\nMarla was spared an undeath only to die at the hands of her now mindless husband.  So strong was her love, however, that her last dying wish was to be buried with her beloved Samuel.\n\nSamuel Fipps roams at a ruined camp along the road northeast of Deathknell.  Defeat him and grant Marla's wish: bury him at her grave, in the first row of our graveyard.", progress = "We must respect our dead, <name>.  It is one of the ways in which we differ from the Scourge...", completion = "You have done a good deed today, &lt;name&gt;.  Although our struggle against the Scourge continues, let us hope that Marla and Samuel will find peace together in their final resting place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6401] = {title = "Kaya's Alive", objective = "Tell Tammra Windfield in Sun Rock Retreat the good news.", description = "Tell Tammra Windfield, Kaya's aunt who's at Sun Rock Retreat, about the good news! Kaya is alive! We had thought she was lost after the brutal attack on our village. Follow the path to the west to get to Sun Rock Retreat.", progress = nil, completion = "My goodness, my niece Kaya is alive! That is good news indeed. Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6402] = {title = "Stormwind Rendezvous", objective = "Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived.", description = "You are to meet with Windsor at the gates of Stormwind.\n\nWhat Windsor is about to unveil will shake the very foundation of the kingdom!\n\nDo not attempt to venture there alone, <name>. You must amass an army! Gather your compatriots. To arms!", progress = nil, completion = "Before we begin, I ask that you first gather an army. We face a dragon, after all!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6403] = {title = "The Great Masquerade", objective = "Follow Reginald Windsor through Stormwind. Protect him from harm!", description = "It has been quite the adventure, friend. I owe you a great debt of gratitude. Perhaps, when all is said and done...\n\nAs you have no doubt ascertained by now, Lady Prestor is Onyxia: Brood of Deathwing, twin to the tyrant of the Spire, Nefarian.\n\nFor too long she has held our kingdom in her captivating gaze. Even the Highlord is controlled by her trickery - a puppet. It all ends today... The spell will be broken.\n\nWorry not, for together, we shall be victorious!\n\nAre you ready?", progress = "I... I... I was powerless.", completion = "&lt;Bolvar holds the shattered medallion.&gt;\n\nThe magic held within must be reignited. The dragon's eye must be attuned.\n\nWindsor's sacrifice has freed our Kingdom, but the threat of Onyxia and her kin is ever looming.\n\nThis medallion is what held my mind and body captive. It is also what gave me access to Onyxia's own mind - to her secrets. Albeit the visions are muddled now, some things I do remember.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6421] = {title = "Boulderslide Ravine", objective = "Explore deep into the cave at Boulderslide Ravine and bring back 10 Resonite Crystals for Mor'rogal at Sun Rock Retreat to investigate.", description = "Something is amiss here in Stonetalon. Can you feel the tension in the air, <name>?\n\nSoutheast of here lies a deep cave in Boulderslide Ravine. The kobolds there are frantically mining a rare crystal called Resonite. I need you to bring back some ore samples so that I can understand what's happening in that cave.  I also need you to investigate the depth of that cave.\n\nGo young <class>, it's imperative I know what evil lurks under these mountains.", progress = "What news have you discovered from Boulderslide Ravine? I recall some legend that deals with Resonite... I just cannot place my hoof on it. Perhaps knowing what lies at the bottom of the cave will illuminate their devious intentions.", completion = "Ah... Yes! That's it; the Resonite crystals have a trace of Earthen magic. The kobolds must have dug deep uncovering an Earthen.\n\nLegend states that the Earthen are creatures created by the Titans.  They were used to create the land our feet walk on. This most definitely is a threat that cannot be ignored.\n\n&lt;Mor'rogal shakes his head.&gt;\n\nPerhaps I can enchant these ore samples to use against this kobold plot.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6441] = {title = "Satyr Horns", objective = "Collect 16 Satyr Horns for Pixel in Splintertree Post.", description = "Heya! I've been traveling through Ashenvale, heading towards Ratchet, and decided to make a stop here at Splintertree. I'm always looking for an opportunity, and it seems that satyr horns are in high demand in Ratchet these days.\n\nAfter asking around here, it seems that the satyrs in Night Run, Satyrnaar, and Xavian all have the type of horns I am looking for. I'm no match for those satyrs... but you look like you might be!\n\nTell you what, you collect the horns for me and I'll make it worth your time.", progress = "I hope you can be quick about getting those horns, <name>. I'm heading back to Ratchet soon!", completion = "These are perfect, &lt;name&gt;! Thanks for helping me out!\n\nOh, and this is for your time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6442] = {title = "Naga at the Zoram Strand", objective = "Bring 20 Wrathtail Heads to Marukai along the Zoram Strand.", description = "There is evil lurking here along the coast, <race>.\n\nIt is the resting place of the doomed city of Zoram, long destroyed and submerged beneath the seas.  Lost, and nearly forgotten.\n\nNow, the naga have returned, and for what reason we do not know.  But reason matters little; we must defend the land we have worked so hard to claim as our own.\n\nReturn to me with 20 of their heads! Throw the naga back to the depths!", progress = "The naga increase in numbers, <name>. Please complete this task for me.", completion = "We could use more of your kind around here, &lt;name&gt;. Thank you for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6461] = {title = "Blood Feeders", objective = "Xen'zilla at Malaka'Jin needs you to kill 10 Deepmoss Creepers and 7 Deepmoss Venomspitters.", description = "We Trolls here at Malaka'Jin have prospered from the land; Stonetalon Mountain offers great hunting for us to live on.\n\nLately, we have attracted the wrong dinner guests... the spiders in these mountains have been raiding our camps at night looking to steal our hunt.\n\nIf you were to help us kill off these ghastly beasts we at Malaka'Jin would be in your debt. Spiders are everywhere in Stonetalon - just head north from here and you will see what I am talking about.", progress = "Hey mon, have you slain the hairy blood feeders? I fear none here in Stonetalon but I don't go walking around here at night... if you know what I mean mon!\n\nAs long as I stay off their dinner plate then all is well.\n\nGood luck to you, <class>!", completion = "Sweet, mon! Good news, perhaps we will have fewer unwanted dinner guests tonight.\n\nMany thanks, &lt;name&gt;.  We are forever in your debt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6462] = {title = "Troll Charm", objective = "Bring 8 Troll Charms to Mitsuwa at the Zoram'gar Outpost.", description = "My kinfolk were traveling here with many sacred troll charms, but the Thistlefur furbolgs attacked and killed them before they reached Zoram'gar!  Those vile Furbolgs!\n\nI miss my brothers and sisters who were killed, but we will meet again in the afterlife.  However, their troll charms hold great value in this world.  It is an outrage that the furbolgs have them!\n\n<name>, you must retrieve the charms!  They are in chests in Thistlefur Hold, a cave at the end of Thistlefur Village, north of Astranaar.", progress = "Did you find the charms, <name>?  Every moment the furbolgs possess those sacred items, my blood boils with rage!", completion = "You found them!  Thank you!  Thank you, &lt;name&gt;!  You do not know how great a thing you have done for me.\n\nA troll without his charm is like an orc without his battle scars...\n\nWorthless.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6481] = {title = "Earthen Arise", objective = "Open the Resonite cask with the Enchanted Resonite Crystal, and then slay Goggeroc. Return to Mor'rogal with the news and Enchanted Resonite Crystal.", description = "You have uncovered a dark threat to the land, <class>. The Resonite cask you have found in that cave houses a slumbering Earthen by the name of Goggeroc.\n\nI have changed the mixture of the Resonite crystals that you gathered with my shamanistic powers. Take the enchanted Resonite crystal and smash open the Resonite cask, which houses the Earthen.\n\nWhen awakened, Goggeroc will be weakened... Slay him, <name>!", progress = "I fear if we do not dispose of this threat immediately, all of Stonetalon will be lost. The might of an Earthen can not be matched by any means. When awakened, Goggeroc will be weak from his long slumber, this will be the opportunity that you must take advantage of... go now <name>!", completion = "You bear good news, &lt;class&gt;! I fear the possibilities of what an Earthen would mean to Kalimdor.\n\nSlaying Goggeroc was a task for no one less than a hero. You have done well; all of Stonetalon and Kalimdor are indebted to you, noble &lt;class&gt;.\n\nAccept this as your reward most honored one.", rewards = "You will be able to choose one of these rewards:\n\nOwlbeard BracersWolfmane Wristguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6482] = {title = "Freedom to Ruul", objective = "Escort Ruul, then speak with Yama Snowhoof in Splintertree Post.", description = "Eh?  Who are you?\n\n<name>?  You're no furbolg.  They are cursed!  They thought I was a bear and captured me, and now they starve me!  My strength is failing...\n\nHelp me escape, then speak with my sister Yama at the Splintertree Post to the east.\n\n<name>! I must escape!", progress = nil, completion = "You found my brother!  He was captured by the Thistlefurs?  That is terrible news to hear, for although many Furbolgs are noble creatures, the Thistlefurs are corrupt.\n\nThank you for rescuing my brother, &lt;name&gt;.  I do not want to think of how they treated poor Ruul.  He will likely sleep long after this ordeal...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6501] = {title = "The Dragon's Eye", objective = "You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist.", description = "A fragment of the shattered medallion is all that I can offer.\n\nYou must find another of dragon blood willing to assist you in forging a new key. Once you secure this key, you must travel to the Wyrmbog in Dustwallow Marsh. It is there that you will find her lair, <name>.\n\nWhere to find other flights willing to help? Sadly, I do not know... They are said to exist. Some may even work and live among us, disguised as one of the humanoid races. I wish you luck.", progress = "I sense an aura of evil radiating from you, <race>. What could you hold that emits such an aura?", completion = "I should have known - a piece of the black dragon brood mother, Onyxia. How revolting...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6502] = {title = "Drakefire Amulet", objective = "You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire.", description = "It is a piece of the dragon; a scale - enchanted and transformed. Whole, it could have granted access to the beast's lair. Shattered, it is useless.\n\nIt is possible to repair the item, but to do so would require the blood of a black dragon champion. There is one... He is known as General Drakkisath, ruler of the dragonspawn armies of Nefarian. Perhaps you have heard of him?\n\nReturn with his blood, <race>, and I shall enchant the fragment into something that will grant you access to Onyxia's lair.", progress = "The flow of time does not stop or slow, <race>. While my life is eternal, yours is not. Waste not the time that you have...", completion = "This amulet will grant you the access that you seek. The lair of Onyxia can be found in Dustwallow Marsh. As long as you hold the amulet, her wards cannot prevent you from entering.\n\nThe Blue Flight wishes you luck, &lt;name&gt;.", rewards = "You will receive:\n\nDrakefire Amulet"}
MultiLanguageQuestData['en'][6503] = {title = "Ashenvale Outrunners", objective = "Kill 9 Ashenvale Outrunners, then return to Kuray'bin at Splintertree Outpost.", description = "We received reports that Ashenvale outrunners left Silverwing Outpost not long ago, and now sneak near our territories in the forest.  We don't want them gathering intelligence on our defenses!\n\nSneak through the forests south of our post here and east of the Alliance outpost of Silverwing.  Find and slay the outrunners, then return to me.", progress = "I await reports of your outrunner kills, <name>.", completion = "Very good, &lt;name&gt;.  Your hunting skills are impressive...\n\nThe loss of those outrunners helps blind the Alliance, and when they lack intelligence they are less likely to launch attacks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6504] = {title = "The Lost Pages", objective = "Find the 12 missing pages of the Shredder Operating Manual, and put them together to form Chapters 1, 2, and 3. Return the pages to Gurda Ragescar near Splintertree Post.", description = "I just picked up this shredder from Ratchet and I was on my way back to the Warsong Lumber Camp, where I am supposed to be on duty. I was given a manual on how to operate the shredder, but on the trip back, a huge gust of wind blew it from my hands. The pages went everywhere, and all I was left with was the cover.\n\nThe pages could be just about anywhere by now, I suppose... but I don't know how to use the shredder without them! Will you find them for me?", progress = "I hope you find the pages soon, <name>! I really need to get back to work!", completion = "Reading isn't my strong point... but now I'll be able to get back to work! Thanks, &lt;name&gt;!", rewards = "You will be able to choose one of these rewards:\n\nShredder Operating GlovesOilrag Handwraps\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6521] = {title = "An Unholy Alliance", objective = "Bring Ambassador Malcin's Head to Varimathras in the Undercity.", description = "Malcin claims he is outside Razorfen Downs. This ambassador must be slain--his mission a failure in the eyes of the Lich King.\n\nHis presence there does explain much of what we've discovered about the area--some of the quilboar have grown frightfully powerful while showing signs of the Plague in their own way. Truly that must be a sign of some sort of deal they've struck.\n\nFind Malcin and slay him, <name>. Return to me after the deed is done.", progress = "Have you found the Ambassador, <name>? Is he dead?\n\nWe cannot afford to allow the Scourge to take a foothold on Kalimdor. They are enough of a threat to our own borders to have to deal with them on two fronts.\n\nThe only optimistic sign from the events you've told me about is that the crone seemed uncorrupted. She must know deep in her spirit that the Scourge may bring great power, but that the Barrens would not truly be hers if she were to agree to their deal.", completion = "Good. Well done, &lt;class&gt;.\n\nNow that Malcin is dead, we can at least know that the Scourges advances will be halted. The Dark Lady thanks you for your efforts and wishes to reward you with a gift.\n\nAlthough we do not know the extent of the Scourges influence within the Downs, I am sure we will discover their plots soon enough.", rewards = "You will be able to choose one of these rewards:\n\nSkullbreakerNail SpitterZealot's Robe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6522] = {title = "An Unholy Alliance", objective = "Take the Small Scroll to Varimathras in the Undercity.", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", progress = "What business is it you wish to speak of, <name>? You must feel it is important if you continue to pester me.", completion = "I recognize the insignia on this scroll, &lt;name&gt;. You found this on that crone who reigns over Razorfen Kraul? Interesting.\n\nThe Scourge aren't content with one continent it seems. This Ambassador Malcin--the one who wrote the note--is one of the Scourge's plagued servants, a human diplomat to the kingdom of Lordaeron before things... changed.\n\nIf the Scourge are trying to gain a foothold in Kalimdor, then it is up to us to act.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6523] = {title = "Protect Kaya", objective = "Escort Kaya Flathoof to Camp Aparaje, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", description = "Thank you for rescuing me! We must leave quickly before they discover that I am free. Please escort me to Camp Aparaje. From there, I know my way.\n\nMy father, Makaba Flathoof, will be desperate to know that I am safe.", progress = nil, completion = "Kaya is alive! &lt;name&gt;, I have you to thank for rescuing her.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6541] = {title = "Report to Kadrak", objective = "Report to Kadrak at the watch tower in northern Barrens.", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", progress = nil, completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6542] = {title = "Report to Kadrak", objective = "Report to Kadrak at the watch tower in northern Barrens.", description = "Have you ever been to Ashenvale, to the north? The horde has recently set up an outpost on the Zoram Strand there, and we can always use some new recruits to help defend our new fronts.\n\nIf you think you are up to it, see Kadrak in the northern Barrens, at the watch tower. He is heading up the Ashenvale campaign and can give you further orders.", progress = nil, completion = "Ashenvale is a divided land, but our most recent efforts have been very successful. We not only have an outpost at the Zoram Strand, but another just north of here called Splintertree.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6543] = {title = "The Warsong Reports", objective = "Open the Bundle of Reports. Take the Warsong Reports to the Warsong Scout, Warsong Runner, and Warsong Outrider. Bring back the updates they give you to Kadrak at the northern watch tower in the barrens.", description = "I recently deployed a few scouts into Ashenvale and I need a runner to take them their orders, and bring me back a report of what they have observed.\n\nYour first stop should be the Zoram'gar Outpost, along the coast to the west, at the Zoram Strand, to locate the first runner. You also need to stop at Splintertree Post, to the north, and along the road to the east, near Azshara. You will find a scout and an outrider there.\n\nGive them each a report, and from them, get an update on their findings.", progress = "Hurry, <name>. They must receive their reports; it is urgent.", completion = "I can see that you are one that can be counted on. These updates are crucial to our plans to further our presence in Ashenvale. We can now plan our next move.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6544] = {title = "Torek's Assault", objective = "Escort Torek on his attack against Silverwing Outpost and Duriel Moonfire, then report to Ertog Ragetusk at Splintertree Post.", description = "Hey!  <class>!  Come here!\n\nMy raiders and I are about to attack the Silverwing Outpost to the west.  Our target is its leader, Duriel Moonfire.  Scouts report the outpost is defended heavily with sentinels and warriors.  The battle will be glorious!\n\nDo you want to share in the glory, <name>, and aid us?  If so, then when it's over you can report our success to my superior, Ertog Ragetusk in Splintertree.\n\nWhat do you say.  Are you with us?", progress = nil, completion = "So Torek's attack was successful!  Well done, &lt;name&gt;.  Night elves are decent foes.  A little skinny, but strong and fierce!  I'm sure the battle was something to see...\n\nAnd I hope you gained a scar or two!", rewards = "You will be able to choose one of these rewards:\n\nPolished Walking StaffSlatemetal Cutlass\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6545] = {title = "Warsong Runner Update", objective = "So you're here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.\n\nYou'd best learn fast if you expect to keep up here. The threat of the naga grows, <name>. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.\n\nBut if you'd like to pitch in with that effort, speak with one of the others here at the outpost.", description = nil, progress = "So you're here with my orders? Always good to see a new recruit with an exuberant nature and a strong will.\n\nYou'd best learn fast if you expect to keep up here. The threat of the naga grows, <name>. I have observed and have taken up defenses against several attacks on this outpost since I arrived here.\n\nBut if you'd like to pitch in with that effort, speak with one of the others here at the outpost.", completion = "Well, my update will explain all of this to Kadrak. You must return this to him as quickly as possible.", rewards = "You will receive:\n\nWarsong Runner Update"}
MultiLanguageQuestData['en'][6546] = {title = "Warsong Outrider Update", objective = "Much danger lies along this path, <name>. You'd do best to remember this while traveling in these lands. The threat of the alliance is quite near.\n\nWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale.  I have also discovered that the naga have taken over a large area of the land of Azshara.\n\nIt's good to see that we are still bolstering our numbers -- be ready for what lies ahead, <name>.", description = nil, progress = "Much danger lies along this path, <name>. You'd do best to remember this while traveling in these lands. The threat of the alliance is quite near.\n\nWe are faced by enemies on all fronts. The satyr are a formidable and prevalent force in eastern Ashenvale.  I have also discovered that the naga have taken over a large area of the land of Azshara.\n\nIt's good to see that we are still bolstering our numbers -- be ready for what lies ahead, <name>.", completion = "Take my update to Kadrak. Swiftly, &lt;name&gt;.", rewards = "You will receive:\n\nWarsong Outrider Update"}
MultiLanguageQuestData['en'][6547] = {title = "Warsong Scout Update", objective = "Keep an eye out, <race>. The elves are often hiding in the shadows...\n\nWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.\n\nI assume you have my next orders from Kadrak?", description = nil, progress = "Keep an eye out, <race>. The elves are often hiding in the shadows...\n\nWe must always be watching. We have worked very hard to claim this land, and the elves are looking for a chance to take it from us.\n\nI assume you have my next orders from Kadrak?", completion = "Let Kadrak know of the success we have had here holding off the night elves. Our plans are going well.", rewards = "You will receive:\n\nWarsong Scout Update"}
MultiLanguageQuestData['en'][6548] = {title = "Avenge My Village", objective = "Kill 8 Grimtotem Ruffians and 6 Grimtotem Mercenaries, and then return to Makaba Flathoof near the southeastern edge of Stonetalon.", description = "The Grimtotem Clan raided my village and killed most everyone. I killed all I could, but barely escaped with my life.\n\n<name>, all I wish now is that more of them are dead. You will find them just to the west of here.", progress = "Have you killed them yet?", completion = "&lt;name&gt;, I thank you... but I will never forget what the Grimtotem have done to my village.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6561] = {title = "Blackfathom Villainy", objective = "Bring the head of Twilight Lord Kelris to Bashana Runetotem in Thunder Bluff.", description = "Strength has left me. Your help is needed!\n\nLong ago this site was a great temple of Elune. But misfortune led to ruin when the corruption of an Old God seeped up from beneath the earth and tainted the sacred Moon Well.\n\nAku'Mai, servant of the Old God, rose from the waters.\n\nThe Twilight's Hammer cultists have allied with the naga to occupy these grounds. The cultists, led by Kelris, sacrifice innocents to Aku'Mai for power.\n\nSlay Kelris and bring his head to Bashana in Thunder Bluff, <name>, please.", progress = "May the Earthmother be with you, <name>.\n\nPeace between the earth and all her people should be our goal. She has a grand plan for nature, and we all have a role to play in that plan.", completion = "Kelris has eluded the Argent Dawn for some time.\n\nFor some time they considered him dead or missing.\n\nBy ending his reign you have spared the lives of many innocent people, &lt;name&gt;.\n\nEarthmother be praised! To sacrifice another to a servant of an Old God for personal gain is beyond disgusting!\n\nYou have done a great thing this day. Kelris was a creature of evil and sought to bring the world back to a time of chaos by worshipping such creatures as the Old Gods. Thank you, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nGravestone ScepterArctic Buckler\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6562] = {title = "Trouble in the Deeps", objective = "Speak to Je'neu Sancrea in Ashenvale.", description = "Je'neu Sancrea is in need of aid. He is at the Zoram'gar Outpost in Ashenvale. The Night elf forest is to the north of the Stonetalon mountains. You can reach it by traveling through Windshear Crag or by heading north through Barrens. Zoram Strand is far to the west of the forest. Be careful, <name>. There are forces there that will not take to your presence kindly.", progress = nil, completion = "Tsunaman sent you? Excellent. Then we have matters to discuss.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6563] = {title = "The Essence of Aku'Mai", objective = "Bring 20 Sapphires of Aku'Mai to Je'neu Sancrea in Ashenvale.", description = "Within the beginning tunnels of Blackfathom Deeps, large sapphire clusters can be found along the cave walls. Recently it was noted that the naga were harvesting the crystals. Until it can be discerned why, I sense we should stop the naga from succeeding. The crystals have great elemental power and if used inappropriately, could make for a powerful arcane component.\n\nWill you help me, <name>? Blackfathom Deeps can be found along Zoram Strand to the north of our outpost.", progress = "How goes your search for the crystals, <name>? Have you witnessed the naga harvesting them? I pray to my ancestors we find the reason they are collecting such things.", completion = "Well done, &lt;name&gt;. These are the crystals I spoke of. Intriguing...\n\nI can feel the power within them. The spirits of water cling to them. Whatever the naga were going to use these for... well, let us be glad they are no longer in their hands.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6564] = {title = "Allegiance to the Old Gods", objective = "Bring the Damp Note to Je'neu Sancrea in Ashenvale.", description = "Some poor handwriting is scrawled on the crumpled up note:\n\n\"Yes, tell all the priestesses to bring the crystals to me. The water elemental spirits are strong within them and they will aid our aquamancers greatly in their own summonings.\n\nBy controlling the power within the crystals, we will appease Aku'Mai. One day we will have enough power to bring Aku'Mai back to us and the world will return to its greatest era! An era of rule by the Old Gods!\"", progress = "Yes, <name>? What is it you need? There is still much I must learn about the crystals the naga are gathering.", completion = "This is interesting indeed. I am glad you have brought it to my attention.\n\nNow we have a name for our troubles... Lorgus Jett.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6565] = {title = "Allegiance to the Old Gods", objective = "Kill Lorgus Jett in Blackfathom Deeps and then return to Je'neu Sancrea in Ashenvale.", description = "This Twilight's Hammer follower cannot be allowed to complete his plan. The Twilight's Hammer do not understand the spirits of nature. They believe in the Old Gods--creatures of chaos and destruction that were long ago defeated. This Lorgus cannot be allowed to succeed. You must stop him, <name>. I cannot do it myself--I am too weak.\n\nGo into Blackfathom Deeps, find him, and kill him. Return to me here at Zoram'gar when it's done.", progress = "Have you found him yet, <name>? Lorgus must be stopped!", completion = "Very good!! Thank you, &lt;name&gt;. We may not have stopped the Twilight's Hammer completely, but at least you have staved off another of their plans to return the Old Gods to power.\n\nWho knows what other plans they have manifesting, but we can rest easy for now.", rewards = "You will be able to choose one of these rewards:\n\nBand of the FistChestnut Mantle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6566] = {title = "What the Wind Carries", objective = "Listen to Thrall.", description = "It is good to see you again, <name>. The wind carries with it news from the Eastern Kingdom.\n\nSit, listen.", progress = "Patience, <name>. Pay attention!", completion = "Are you prepared to take on this task?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6567] = {title = "The Champion of the Horde", objective = "Seek out Rokaro at Shadowprey Village in Desolace.", description = "Rexxar, one of my most loyal champions, has discovered a way into the lair of the dragon. However he has left Azeroth to join our expedition into Outland.\n\nHowever, he left his companion, Rokaro, in Shadowprey Village with this information. You are to seek him out.", progress = nil, completion = "There is but one way into the dragon's lair, &lt;race&gt;.\n\nYou see, only the strongest of the Black Dragonflight are allowed entry into the lair of the brood mother. Many trials must be passed and the key to enter ceremoniously enchanted by General Drakkisath himself!\n\nSince you are not of black dragonkin, you may have some difficulty in obtaining passage.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6568] = {title = "Mistress of Deception", objective = "Deliver Rokaro's Letter to Myranda the Hag in the Western Plaguelands.", description = "Illusion and disguise. That is how you will fool the Black Dragonflight, and gain what you seek.\n\nThough I could teach you something of the skills of deception, you need the help of a master.\n\nI know of one who could do this. In the Western Plaguelands, you will find Myranda the Hag, once a master illusionist of Lordaeron. She has helped us in the past, and if she believes the cause worthy, she may help you.\n\nTake this message to her.", progress = "It is not often I see one of the Horde in these parts of Lordaeron. What is it that you have for Myranda?", completion = "&lt;Myranda holds the note, pauses, then smiles.&gt;\n\nHow is he? Rexxar, I mean. Oh, come now, do not look so confused. The letter was left intentionally blank. It carried with it the intentions and thoughts of its creator. Judging from its contents, it is no wonder Rexxar left it as such. Imagine if you were captured or slain and this information discovered!\n\nOh, nevermind! Myranda will help you, &lt;race&gt;. I owe the Warchief a favor or two.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6569] = {title = "Oculus Illusions", objective = "Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete.", description = "So the <race> wishes to become one of the Black Flight, eh?\n\nThe creation of the illusion you require is trivial, but the components required for the divination are quite difficult to obtain. The Warchief has entrusted you with this mission, so Myranda must assume you as capable.\n\nTravel to the upper citadel of Blackrock Spire and slay enough of the black dragonspawn to fill up one of your packs with their eyes.\n\nReturn to Myranda when you have gathered enough of the reagent.", progress = "The eyes of that which we wish to mimic are the most important ingredient of any illusion, <name>.", completion = "Let Myranda have a look, &lt;race&gt;.\n\nOh yes, these will do nicely.\n\nWith these reagents, Myranda will create for you a medallion that will grant an illusion capable of fooling the black dragonflight's gatekeeper.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6570] = {title = "Emberstrife", objective = "Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife.\n\nProvided item: \n", description = "I have attuned this medallion with the magic necessary to create and maintain an illusion within the bounds of the den of Emberstrife.\n\nEmberstrife is an ancient drake; an old gatekeeper of Nefarian, burdened with the duty to test those dragonspawn that would ascend to the rank of elite guard to Onyxia.\n\nTravel to the Wyrmbog of Dustwallow Marsh and enter the lair of Emberstrife. Once there, put on the amulet and follow where your destiny may lead!", progress = nil, completion = "Have we run so low on able soldiers that Nefarian is sending me whelps? You will never pass my tests, broodling.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6571] = {title = "Warsong Supplies", objective = "Collect the Warsong Supplies: Warsong Saw Blades, Logging Rope, Warsong Oil, and the Warsong Axe Shipment for Locke Okarr in Splintertree Post.", description = "We are in short supply of a few items at the Warsong lumber camp!\n\nPixel at Splintertree Post has our shipment of saw blades. It'll take a trip to Booty Bay to pick up a crate of axes from Wharfmaster Lozgil.\n\nOur shipment of oil and rope will be more difficult. The rope was pilfered by the Thistlefur and Foulweald furbolgs, and the satyrs intercepted the delivery of the oil and are now using it for detestable rituals in Night Run, Satyrnaar, and Xavian!\n\nCan you help me?", progress = "I hope you can come through with the supplies! I'm in big trouble if I don't deliver them soon!", completion = "Excellent, &lt;name&gt;. You've saved me a lot of work!\n\nBut don't think that I'm not grateful!", rewards = "You will be able to choose one of these rewards:\n\nWarsong SashWarsong BootsWarsong Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6581] = {title = "Warsong Saw Blades", objective = "Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.\n\n..But what sort of payment do you have for me? You can't just take them, you know! My time isn't cheap!\n\nWhat I really need is a good gun to carry with me on my travels. A girl's gotta protect herself, you know? There's a gun I really like that I'm sure an engineer would have no problem making.\n\nSo, if you bring me a deadly blunderbuss, I'll give you the saw blade shipment. Do we have a deal?", description = nil, progress = "Direct from Ratchet, the Warsong saw blades! Yep, I have them right here.\n\n..But what sort of payment do you have for me? You can't just take them, you know! My time isn't cheap!\n\nWhat I really need is a good gun to carry with me on my travels. A girl's gotta protect herself, you know? There's a gun I really like that I'm sure an engineer would have no problem making.\n\nSo, if you bring me a deadly blunderbuss, I'll give you the saw blade shipment. Do we have a deal?", completion = "This is perfect -- just the thing! Well, here's the shipment.", rewards = "You will receive:\n\nWarsong Saw Blades"}
MultiLanguageQuestData['en'][6582] = {title = "The Test of Skulls, Scryer", objective = "You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife.\n\nYou know that Scryer can be found in Winterspring.", description = "We are Deathwing's children, whelp. Our dominance over the lesser Aspects must be enforced.\n\nIf you are truly worthy of ascension, the lesser dragonflight will wilt in your presence.\n\nFind their champions and lay waste to them in the name of our Father!\n\nTravel to Winterspring and track down the mighty blue drake, Scryer. Crush him and any of the Blue Flight that stand in your path. Tear out his skull and return it to me.", progress = "<Emberstrife hisses.>", completion = "One of ssseveral complete...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6583] = {title = "The Test of Skulls, Somnus", objective = "Destroy the drake champion of the Green Flight, Somnus. Take his skull and return it to Emberstrife.", description = "Just as our Father crushes the Aspects themselves, so too must we strive to bring chaos and destruction to their children.\n\nYou must test your battle prowess against the sleepless dreamers: The children of the Green Flight.\n\nTravel to the Swamp of Sorrows and track down Somnus, drake champion of the Green Flight. Let flow your hatred; dominate the insect... Return to me with his skull...", progress = "Do not return here until you have bathed in the blood of our enemies and drank in their suffering.", completion = "Another complete...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6584] = {title = "The Test of Skulls, Chronalis", objective = "Guarding the Caverns of Time in the Tanaris Desert is Chronalis, child of Nozdormu. Destroy him and return his skull to Emberstrife.", description = "The time watchers, children of Nozdormu - Lord of the Centuriesss...\n\nIt is three that guard the Caverns of Time, but only one that holds the interests of the Black Flight: The Time Shifter, Chronalis, favored drakeling of Nozdormu.\n\nSsstrike at this champion, a blow to make even the stoic sands of time weep. Return to me with his skull.", progress = "Ironically, whelp, time is of the essencccce.", completion = "The most hated remainsss...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6585] = {title = "The Test of Skulls, Axtroz", objective = "Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife.", description = "It was over the mountains of Grim Batol that our Father raged against the combined might of the Aspects. The cowardly act of the betrayer, Alexstrasza, bought the other Aspects enough time to escape from Father's wrath.\n\nSssuch a shameful act...\n\nThe Red Flight now guards Grim Batol, their lieutenant, Axtroz, must be destroyed. Return the skull of Axtroz to me. For Father, whelp!", progress = "Changesss... I sense them taking place in you, whelp. Pass this test and only ceremony remains.", completion = "I had doubted your dedication, whelp. You persisted, dominating our enemies, bringing honor to our flight.\n\nI must now prepare the skulls for your ascension.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6601] = {title = "Ascension...", objective = "It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rokaro and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next.", description = "From the skulls of our enemies is shaped a medallion. You know this medallion, yesss? You have no doubt seen it worn by your elders.\n\nTake it, whelp. Return to the Spire and present it to General Drakkisath. The General will place the final enchantment upon the medallion, attuning the trinket to your spirit.\n\nYou will wear the finished medallion as a badge of honor, symbolizing your ascension to one of our most guarded ranks: Guardian to the brood mother.\n\nGo!", progress = "Do not panic, <name>!", completion = "It is merely dragon-talk, &lt;name&gt; - more hot air than actual substantive information. Pompous, aggressive behavior is to be expected from their kind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6602] = {title = "Blood of the Black Dragon Champion", objective = "Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rokaro.", description = "How would you feel about paying a visit to the General? No illusions, this time.\n\nCeremony? A pretty word to describe the bloodletting that amuses the Black Dragonflight.\n\nAll this amulet requires is the blood of General Drakkisath. Primitive security. There are other ways to receive the General's blood.\n\nGo to Blackrock Spire and kill Drakkisath. Return with his blood and I will activate the key to Onyxia's lair.", progress = "Drakkisath is not to be trifled with, <name>. He is responsible for the death of thousands.", completion = "&lt;Rexxar grins.&gt;\n\nThe story of your heroics will be told for years to come, &lt;name&gt;. The Drakefire Amulet is the key to the lair of Onyxia. Gather your forces and conquer in the name of the Horde!", rewards = "You will receive:\n\nDrakefire Amulet"}
MultiLanguageQuestData['en'][6603] = {title = "Trouble in Winterspring!", objective = "Find Donova Snowden near the hot springs in Winterspring.", description = "There's trouble in Winterspring!\n\nWhy, sure, I spend some time out in the wilds and know about these things... I'm always mighty proud to say it. I consider the hours I spend out there in the hills to be golden. Help you cultivate quick reflexes, a cool head and a keen eye...\n\nIt takes judgement, brains and maturity to appreciate the wilderness in the way that I do.\n\nNow, what was I talking about?\n\nAh yes, trouble. See Donova Snowden at the hot springs and she can tell you more.", progress = nil, completion = "Well, hi there! So Meggi told you of the trouble I have found here?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6604] = {title = "Enraged Wildkin", objective = "Speak with Jaron Stoneshaper at Starfall Village.", description = "Have you noticed the abandoned camp to the south of here? It looks like the wildkin went crazy and destroyed just about everything they could find!\n\nI heard a rumor that one of the survivors of the attack is resting at Starfall Village, west of here. I'm sure curious about what happened... aren't you?", progress = nil, completion = "Aye, what can I do for you?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6605] = {title = "A Strange One", objective = "Speak with Winna Hazzard in Felwood.", description = "I just got back from Felwood, <name>. On my way through, I stopped at Bloodvenom Post and I met a very odd character... She seemed intent on one thing, and I suppose I could tell you what that is, but I think she'd like to explain it to you herself.\n\nIf you're interested, head to Bloodvenom Post in western Felwood and look for Winna Hazzard.\n\nWho knows, she might need your help...", progress = nil, completion = "Ah, &lt;class&gt;. I see that there is hope yet. Are you here to assist me?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6606] = {title = "A Little Luck", objective = "Speak with Witch Doctor Mau'ari in Everlook.We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "We can always use a little luck, eh? A small advantage is all it takes to turn things in your favor...\n\nI happened to make the acquaintance of a rather eccentric witch doctor some time back. She made me a lucky charm... for a price. Believe me, though, it was well worth it!\n\nMaybe you'd be interested in one of your own? Find Witch Doctor Mau'ari in Everlook. I'm not giving mine up!You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6607] = {title = "Nat Pagle, Angler Extreme", objective = "Nat Pagle wants you to catch the following fish:\n\nMisty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.\n\nA Sar'theris Striker from the Sar'theris Strand in Desolace.\n\nFeralas Ahi from the Verdantis River of Feralas.\n\nSavage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.\n\nReturn to Nat Pagle when you have reeled them all in!", description = "Can't say I really enjoy fishin' much. Figure I been at it for a good 20 or 30 years now.\n\nI reckon people are driven to do what they do for different reasons.\n\nNow, I'm not saying you need to fish for 30 years or catch every fish in the sea to become a master fisherman. I reckon you just need to be determined - determined enough to sit on your duff for hours at a time, doin' nothin'.\n\nI'll tell you what, catch me a few rare fish and I'll teach you a thing or two. Here's a list:", progress = "Anything bitin' today?", completion = "Now that's a fine catch!\n\nCome over here, lemme show you how to set a few lines.", rewards = "You will learn:\n\nFishing\n\nThe following spell will be cast on you:\n\nArtisan Fishing\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6608] = {title = "You Too Good.", objective = "You think Lumak is trying to tell you that he can no longer help you improve your fishing skill. You may want to try to find his friend, Nat Pagle, a human fishing off one of the islands south of Theramore (at least that's what you think Lumak said).", description = "Lumak no can teach <name> no more. You too good! Find Lumak friend, Nat Pagle. Is human but no eat! Is Lumak friend! Nat teach you fish gooder.\n\nYou find Nat in Dustwallow Marsh, south of Humie town, Thermorosomethinglikedat. Nat probably fishing. Go now!", progress = nil, completion = "'Course, you must be a friend of Lumak's.\n\nFishin'? I can tell you all 'bout fishin'.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6609] = {title = "I Got Nothin' Left!", objective = "Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!", description = "I'm a dwarf fer cryin' out loud, <lad/missy>! I ain't been designed to fish! I mean look at me! I'm practically made outta stone.\n\nI got nothin' left - ye tapped me out. I've taught ye all I know, flipflop!\n\nDon't ye get it? Ah, fine. I got an ol' friend over on Kalimdor who can help ye out. 'Is name be Nat Pagle, a fine lad. Find him on the islands south o' Theramore. Git goin'!", progress = nil, completion = "I've always got room on my island for visitors... I reckon...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6610] = {title = "Clamlette Surprise", objective = "Dirge Quikcleave wants you to get the following items:\n\n12 Giant Eggs. You will find those on the Rocs wandering Tanaris or any other species of large bird.\n\n10 pieces of Zesty Clam Meat. You can find those in clams, naturally!\n\n20 pieces of Alterac Swiss. Get thee to a cheesery!\n\nGather all of the items and return to Dirge.", description = "Ever heard of a clamlette? Of course you haven't! It's my latest and greatest culinary masterpiece. Oh, <name>, just thinking about a clamlette makes my mouth water.\n\nUnfortunately, I'm all out of supplies to make any! How about I make you a deal? You gather the supplies I need to make a clamlette and I'll teach you the finer points of exotic cuisine and I'll even throw in a couple of clamlettes to boot! Deal??\n\nHere's what I need:", progress = "My cravings are going to be the end of me! Hurry, <name> - before I dip into my own supply.", completion = "You are in for a special treat, &lt;name&gt;. Watch and learn!", rewards = "You will learn:\n\nCooking\n\nThe following spell will be cast on you:\n\nArtisan Cook\n\nYou will also receive:\n\nClamlette Surprise"}
MultiLanguageQuestData['en'][6611] = {title = "To Gadgetzan You Go!", objective = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", description = "How you expect Zamja teach you anything? You got all of Zamja's cooking mojo and still you crave more!\n\nZamja can't help. Fat <race> needs to go to Gadgetzan. You find a little goblin named Dirge there - he help you, fatty.\n\nWhen you become big cook on the block, you come back and teach Zamja, ok? Now go!", progress = nil, completion = "&lt;Dirge spits out some leather sandal bits.&gt;\n\nPfftooey...\n\n&lt;Dirge hacks loudly.&gt;\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6612] = {title = "I Know A Guy...", objective = "Travel to Gadgetzan in the Tanaris desert and speak with Dirge Quikcleave about advancing your cooking career.", description = "I can tell by yer cooking spoon that ye know what yer doin'. Unfortunately, I can't teach ya nothin'.\n\nLuckily fer ye, I know a guy. He's a goblin and probably the best cook on Kalimdor.\n\nAyep, that's the bad news, <lad/missy> - ye got to travel to Kalimdor. Git to Gadgetzan and find Dirge Quikcleave. He'll set ya straight.", progress = nil, completion = "&lt;Dirge spits out leather.&gt;\n\nPfftey...\n\n&lt;Dirge hacks loudly.&gt;\n\nWhat? I'll have you know that leather is surprisingly high in protein and low in carbohydrates, &lt;race&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6621] = {title = "King of the Foulweald", objective = "Place Karang's Banner on the Foulweald Totem Mound. Do not let the furbolgs destroy the banner. Defeat Chief Murgut and bring Murgut's Totem to Karang Amakkar at Zoram'gar.", description = "<name>, another tribe of Furbolgs,  the Foulweald, live southeast of Astranaar.  They are not as many as the Thistlefur, but their ferocity poses a future threat.  With a show of force, we can remove that threat.\n\nTake this banner, go to the Foulweald village and place it on their totem mound.  They will try to destroy the banner, but hold your ground until their chief, Murgut, appears to save face for the tribe.  Bring me the totem he carries.\n\nGather your allies, <name>.  This is no task for a single <class>.", progress = "Did you defeat Chief Murgut, <name>?  Did you retrieve his Foulweald Totem?", completion = "Good work, &lt;name&gt;.  Issuing that challenge to the Foulwealds and defeating their leader sends them a strong message:\n\nThe Horde is not to be trifled with.\n\nI don't believe that tribe will be giving us much trouble for a long time.", rewards = "You will be able to choose one of these rewards:\n\nBoorguard TunicCobalt Legguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6622] = {title = "Triage", objective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Horde Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nTriage bandages will be supplied.\n\nGood luck, doctor.", progress = "Miraculous work, doctor. Simply miraculous.", completion = "Doctor &lt;name&gt;, welcome to Horde Trauma.", rewards = "You will learn:\n\nFirst Aid\n\nThe following spell will be cast on you:\n\nArtisan First Aid\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6623] = {title = "Horde Trauma", objective = "Travel to Hammerfall in the Arathi Highlands and speak with Doctor Gregory Victor about joining the ranks of Horde Trauma.", description = "Doctor <name>, I presume. It is a pleasure to see you again.\n\nI have some wonderful news for you! Doctor Gregory Victor, chief physician of Horde Trauma has made a personal request for you to join him at Hammerfall. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great Doctor Gregory Victor! Do not squander this opportunity!", progress = nil, completion = "Wonderful. Put on your scrubs, we are to start at once!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6624] = {title = "Triage", objective = "Save patients by using Triage Bandages to tend to their wounds. You must save 15 patients before 6 of them die from their injuries.\n\nRemember the order of triage! Critically Injured Soldiers die the fastest followed by Badly Injured Soldiers. Injured Soldiers take the longest to die and should be saved AFTER your Critically Injured and Badly Injured Soldiers have been triaged.", description = "Good day, doctor. You will be tested on your ability to triage patients accordingly this afternoon. Should you pass your examination, you will join the prestigious ranks of Alliance Trauma.\n\nNow pay attention! The critically injured must be tended to first. After the criticals come the badly injured. The injured should be tended to last. You must save 15 patients to pass this exam. You will fail should 6 of your patients die in triage.\n\nGood luck, doctor.", progress = "Miraculous work, doctor. Simply miraculous.", completion = "Doctor &lt;name&gt;, welcome to Alliance Trauma.", rewards = "You will learn:\n\nFirst Aid\n\nThe following spell will be cast on you:\n\nArtisan First Aid\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6625] = {title = "Alliance Trauma", objective = "Travel to Theramore in the Dustwallow Marsh and speak with Doctor Gustaf VanHowzen about joining the ranks of Alliance Trauma.", description = "Doctor <name>, I presume. It is a pleasure to see you.\n\nI have some wonderful news for you! Gustaf VanHowzen, chief physician of Alliance Trauma has made a personal request for you to join him at Theramore. This could be the opportunity of a lifetime! I would give anything to be given a chance to study under the great doctor, Gustaf VanHowzen! Do not squander this opportunity, doctor!", progress = nil, completion = "Wonderful. Put on your scrubs, we are to start at once!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6626] = {title = "A Host of Evil", objective = "Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs.", description = "The Forsaken do not pass on their... illness... from what I have seen. This diplomat seems to be granting undeath to would-be followers. I am beginning to think he is one of the Scourge.\n\nFor now, my concern is not with him though, it's with the growing ranks around him. They creep from the shadows daily, almost begging him for more power.\n\nI'm not powerful enough to fight them on my own, <name>. What do you say? Are you up for some hunting?", progress = "How goes the hunt, <name>? Seeing just this small sample of this diplomat's power here removes any doubt I had that the Scourge are one of the greatest threats this world has ever seen.", completion = "Thank you, &lt;name&gt;! The work you've done will be a great help, I'm sure.\n\nI will continue my study of this diplomat and the rest of the quilboar here. If you seek greater adventure, I'd find a few friends and head into the cave that looks like a great boar maw just over there. I'm sure once you're inside you'll find greater challenges to face.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6627] = {title = "Test of Lore", objective = "Answer Braug Dimspirit's question successfully and then speak to him again. He will remain in Stonetalon Mountains when you are ready.", description = "You have brought me the book, and now it is time for your question. Are you ready?\n\nTime is not an issue, <class>, so do not feel pressured. You may take as long as you like to answer.", progress = "Life is full of questions, <class>. You will never be able to answer all of them, but with some time and study, perhaps you will become a little more knowledgeable.", completion = "Well done, &lt;class&gt;. You have studied the text I asked you to, and now you have passed another of our tests.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6628] = {title = "Test of Lore", objective = "Answer Parqual Fintallas' question successfully and then speak to him again. He will remain in the Undercity until you are ready.", description = "So the time is once again upon us. As a student of lore, you have shown great tenacity by undertaking my task.\n\nAnd so now I offer you your question. If you are ready, speak to me again, and take all the time you need, <name>--there is no pressure to answer quickly.", progress = "There is only one rule I feel you must know if you wish to survive in this world: the more you know, the more you'll see.\n\nIf you study, if you observe, then you will begin to see things in the world that no other <race> will see.", completion = "Well done, &lt;name&gt;. I had my doubts if you studied the text I asked you to get, but you've answered correctly.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6629] = {title = "Kill Grundig Darkcloud", objective = "Kill Grundig Darkcloud and 6 Grimtotem Brutes, and return to Makaba Flathoof near the southeastern edge of Stonetalon.", description = "<name>, you've done a fine job killing Grimtotem. If you dare, Grundig Darkcloud and his personal band of brutes is by far the worst of the lot. He was the one who led the brutal attack on my village.\n\nYou will find him in Grimtotem Post a bit further up the path to the west. Kill him, and I will be forever grateful.", progress = "Have you killed Grundig Darkcloud and his personal band of Brutes?", completion = "Grundig Darkcloud is dead! &lt;name&gt;, I will always be grateful for what you've done here today.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6641] = {title = "Vorsha the Lasher", objective = "Keep Muglash safe as he travels to the brazier. Help him by putting the brazier out, then protect him as you fight against the Naga.\n\nIf you are successful, return to the Zoram'gar Outpost and inform the Warsong Runner of the death of Vorsha the Lasher.", description = "Vorsha the Lasher... the fiendish hydra that roams the seas...\n\nShe has attacked our outpost, each time unprovoked, laying waste to anything that falls in her path.\n\nBut I am ready, <name>. I have prepared to best the hydra and end these attacks on Zoram'gar.\n\nThe naga honor the wicked nature of this beast with a brazier that remains lit on an island just off the coast. I believe that if we put it out, Vorsha will appear in anger.\n\nWe will need help, so be sure to bring some strong allies.", progress = nil, completion = "I have witnessed many naga attacks since I arrived here. It puts my mind at ease that Vorsha will no longer roam freely.\n\nWe are in your debt, &lt;name&gt;.", rewards = "You will receive:\n\nHorn Ring"}
MultiLanguageQuestData['en'][6642] = {title = "Favor Amongst the Brotherhood, Dark Iron Ore", objective = "Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.\n\nFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.", description = nil, progress = "Dark Iron, while plentiful in the Depths, is still a valued commodity amongst the Brotherhood. The sacred arms and armaments of Ragnaros favor Dark Iron.\n\nFor every 10 pieces of Dark Iron Ore you offer, favor amongst the Brotherhood you will gain.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.", rewards = nil}
MultiLanguageQuestData['en'][6643] = {title = "Favor Amongst the Brotherhood, Fiery Core", objective = "Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.\n\nMany of the Brotherhood have been lost in their search for Fiery Cores.\n\nOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.", description = nil, progress = "Woe unto those that tempt fate inside the Molten Core. Death comes swiftly - the punishment dealt without mercy.\n\nMany of the Brotherhood have been lost in their search for Fiery Cores.\n\nOffer 1 Fiery Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.", rewards = nil}
MultiLanguageQuestData['en'][6644] = {title = "Favor Amongst the Brotherhood, Lava Core", objective = "The Thorium Brotherhood sympathizes with your plight, <race>. This is why Lokthos has been empowered to bargain.\n\nOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.", description = nil, progress = "The Thorium Brotherhood sympathizes with your plight, <race>. This is why Lokthos has been empowered to bargain.\n\nOffer 1 Lava Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.", rewards = nil}
MultiLanguageQuestData['en'][6645] = {title = "Favor Amongst the Brotherhood, Core Leather", objective = "Many of the sacred recipes require the skin from Ragnaros' chosen pets.\n\nOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.", description = nil, progress = "Many of the sacred recipes require the skin from Ragnaros' chosen pets.\n\nOffer 2 Core Leather, skinned from the smoldering corpses of the Core Hounds of the Molten Core and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.", rewards = nil}
MultiLanguageQuestData['en'][6646] = {title = "Favor Amongst the Brotherhood, Blood of the Mountain", objective = "The tears of the Fire Lord are a rare find indeed.\n\nOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.", description = nil, progress = "The tears of the Fire Lord are a rare find indeed.\n\nOffer 1 Blood of the Mountain and you shall be granted favor amongst the Brotherhood.", completion = "Your offering has been accepted. Favor you have gained. Continue and you shall be allowed access to the ancient trades.", rewards = nil}
MultiLanguageQuestData['en'][6661] = {title = "Deeprun Rat Roundup", objective = "Capture 5 Deeprun Rats by using the Rat Catcher's Flute. Lead the rats back to Monty. Don't forget to turn in the flute when you're finished.", description = "Avast ye scallywag. Arrrr... Arrrr ye looking fer work? We gots a serious rat problem down here an' not enough hands on the poop deck.\n\nWhat do ye say? All ye needs to do is take this here rat catchin' flute and play the melody around the vermin. They'll follow ye to the ends of the world!\n\nJust capture five of the little buggers and bring em back here. We needs em alive.\n\nArrrrr...", progress = "Yarrr... Swabby, what be takin' ye so long?", completion = "These'll werk nicely, matey. Me brother needs em still tickin' and kickin,' else they go sour... Ye don't want to taste no sour rat kabob.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6662] = {title = "Me Brother, Nipsy", objective = "Take the Carton of Mystery Meat to Nipsy at the Stormwind Deeprun Tram Depot.", description = "Me brother, Nipsy, runs a rat kabob operation on the other side of Deeprun. Ye needs to take this here crate o' rats to him before they go bad. Get a move on!\n\nYe have ridden a tram before, aye? It's easy. Just step aboard when she arrives and enjoy the ride. An' keep yer arms and legs inside durin' the ride, lest ye be peglegged fer life.", progress = "<Nipsy puts his index finger through one of the air holes in the carton.>\n\nAlive and kicking... and just in time!", completion = "Poor Monty. Ever since the Gnomeregan incident, he hasn't been the same. That boy has never seen an ocean in his life, let alone being some kind of pirate.\n\n&lt;Nipsy sighs.&gt;\n\nAt least he keeps the flow of twitching critters coming.", rewards = "You will receive:\n\nDeeprun Rat Kabob"}
MultiLanguageQuestData['en'][6681] = {title = "The Manor, Ravenholdt", objective = "Take the Seal of Ravenholdt to Fahrad at Ravenholdt Manor, hidden away in the hills of Hillsbrad.\n\nYour cunning will be tested along the way. Be prepared.", description = "<name>,\n\nRavenholdt has taken an interest in you, young thief. We have been watching. Your style is a bit awkward but nothing we couldn't fix.\n\nShould you be prepared to embark on a career as a disciple of Master Ravenholdt and member of the Assassin's League, you have only to bring the Seal of Ravenholdt (attached to this letter) to Ravenholdt Manor.\n\nYour first task is to find the manor, hidden away in the hills of Hillsbrad and demonstrate your cunning.\n\nRegards,\n\nFahrad", progress = "Did you meet Milton?\n\n<Fahrad laughs.>", completion = "Most excellent, young thief.\n\nYou look a bit beaten down, but no worse for the wear.\n\nA long journey awaits you - long and rewarding. Are you prepared to finally embrace your destiny among the masters of Ravenholdt?\n\nSpeak with the guards outside. They will get you started.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6701] = {title = "Syndicate Emblems", objective = "We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population!\n\nWe've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally.\n\nPick their pockets clean and turn the emblems in to me or one of the other guards.\n\nStart at Durnholde, south of here.", description = nil, progress = "We have been entrenched in a battle with the Syndicate for years. What they lack in skill they make up for in numbers. It's impossible to kill them off fast enough to have any noticeable impact on their population!\n\nWe've found that the best way to deal with their size is to pilfer their emblems. Once an emblem is stolen the shamed member is 'dealt' with internally.\n\nPick their pockets clean and turn the emblems in to me or one of the other guards.\n\nStart at Durnholde, south of here.", completion = "Hey, nice work! Keep this up and the other rogues might stop spitting on you.", rewards = nil}
MultiLanguageQuestData['en'][6721] = {title = "The Hunter's Path", objective = "Speak with Dazalar in Dolanaar.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, it is time to train you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6722] = {title = "The Hunter's Path", objective = "Speak with Dazalar in Dolanaar.", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Dazalar in Dolanaar. He can put you on the path to earning a pet of your own.", progress = nil, completion = "Yes, it is time to train you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6741] = {title = "More Booty!", objective = "I need more armor scraps, <name>!  Do you have any?", description = nil, progress = "I need more armor scraps, <name>!  Do you have any?", completion = "Thanks again, &lt;name&gt;.  You do the Horde proud...", rewards = "The following spell will be cast on you:\n\nPolished Armor"}
MultiLanguageQuestData['en'][6761] = {title = "The New Frontier", objective = "Speak with Mathrengyl Bearwalker at the Cenarion Enclave of Darnassus.", description = "I have relegated my second, Mathrengyl Bearwalker, to deal with Moonglade's call for aid.  Speak to him on this matter - NOT me.\n\nLet me give you some... friendly... advice.  It is I who led us out of the darkness - NOT the Cenarion Circle in Moonglade - when all was lost for our race.  Teldrassil gives us all new life!  They would have you believe otherwise, and to believe their propaganda would be a fool's task.\n\nI'll leave it to you to decide whether or not you're a fool.", progress = nil, completion = "Yes &lt;class&gt;, thank you for coming.  I apologize about the misunderstanding... the air is thick with mistrust between the Arch Druid here and Keeper Remulos in Moonglade.  Each suspect the other of chicanery, and the fact that strange corruptions of Teldrassil continue unabated are still an issue here.  It does little to quell mistrust.\n\nRegardless, our duty to the Cenarion Circle remains... even if those who lead it may disagree with one another.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6762] = {title = "Rabine Saturna", objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade. Moonglade lies between Felwood and Winterspring, accessible through a path out of Timbermaw Hold.", description = "For this task, Keeper Remulos' majordomo in Moonglade - Rabine Saturna - seeks aid in exploring the vast wastelands far to the west of Tanaris... and even further west of Un'Goro.  You should find him in Nighthaven, the main village of Moonglade.\n\nWhile your work will no doubt be of tremendous benefit to us all, I advise you to tread gingerly.  There are tensions between Darnassus and Moonglade... ones that may grow over the course of time.", progress = nil, completion = "I am Rabine Saturna, and on behalf of Keeper Remulos and all of the denizens of this sacred glade I bid you welcome.\n\nI appreciate your interest and eagerness to assist the Cenarion Circle.  I also know that Arch Druid of Darnassus expressed his displeasure to you in your lending us aid.  Rest assured that it is for the greater good, and that you will be safe from any ill-conceived repercussions you may be the target of.\n\nYou are among friends here, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6781] = {title = "More Armor Scraps", objective = "<name>, we need more armor scraps to supply our troops!", description = nil, progress = "<name>, we need more armor scraps to supply our troops!", completion = "These are some good pieces, &lt;name&gt;.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!", rewards = "The following spell will be cast on you:\n\nPolished Armor"}
MultiLanguageQuestData['en'][6801] = {title = "Lokholar the Ice Lord", objective = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", description = nil, progress = "I come from Thunder Bluff, <race>. Cairne himself has seen to it that I assist the Frostwolf Clan in these dire times.\n\nBut let us not waste any more time. You must strike down our enemies and bring to me their blood. Once enough blood has been gathered, the ritual of summoning may begin.\n\nVictory will be assured when the elemental lord is loosed upon the Stormpike army.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!", rewards = nil}
MultiLanguageQuestData['en'][6804] = {title = "Poisoned Water", objective = "Use the Aspect of Neptulon on poisoned elementals of Eastern Plaguelands. Bring 12 Discordant Bracers and the Aspect of Neptulon to Duke Hydraxis in Azshara.", description = "A force of elemental scouts was sent to the eastern plaguelands of Lordaeron, and the disease of that place twisted and infected them.  The Waterlords cannot allow this affront to our purity!\n\nTake this vial.  In it is a quantity of one aspect of Neptulon.  If used on the plagued elementals it will fight the poison within their bodies and cure them!  But their inner conflict will drive them into a surging madness.\n\nDefeat the discordant surges and bring me their bracers of binding.", progress = "Do you have the bracers?", completion = "You have done well, &lt;class&gt;.  The corrupted elementals you cured were an outrage to all bodies of water.  Our strength lies in our purity and if we are to win our war with the others, we must remain strong.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6805] = {title = "Stormers and Rumblers", objective = "Kill 15 Dust Stormers and 15 Desert Rumblers and then return to Duke Hydraxis in Azshara.", description = "We, the elementals of water, wage war with those beings of the lesser elements.  If you are truly our ally in this conflict, then show me your conviction!\n\nFar to the south, in the desert land of Silithus, the servants of air and earth scurry in a corner of rock named the Crystal Vale.  They protect items of power from smaller beings, mortals, and although I do not know why they do this, I wish to foil their efforts.\n\nGo to the Crystal Vale in Silithus and defeat our enemies, then return to me.", progress = "Cowardice is not a thing we hold in regard, <class>.  Go to Silithus and prove your bravery.", completion = "Your bravery is proven, as is your worth to us.  Perhaps I may have future tasks for you, tasks more befitting a valued ally of the Waterlords.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6821] = {title = "Eye of the Emberseer", objective = "Bring the Eye of the Emberseer to Duke Hydraxis in Azshara.", description = "You have shown me that you can defeat our enemies and perform missions to further the cause of the Waterlords.  But until now you have only faced lesser foes... if pitted against a powerful enemy, can you prevail?\n\nThat is your new task.\n\nHigh up in Blackrock Spire the orcs have captured a servant of fire, the Pyroguard Emberseer.  Find his place of imprisonment, slay his captors, and then slay the emberseer.  Bring me his eye and it will show me your worth.", progress = "Do you have the Eye, <class>?  Do you have the strength to enter Blackrock Spire?", completion = "Ah, so you do have the strength.  And you have the cunning as well, for Blackrock Spire is more than a match for brute strength alone.\n\nIndeed &lt;name&gt;, you may yet prove a valued ally to us...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6822] = {title = "The Molten Core", objective = "Kill 1 Fire Lord, 1 Molten Giant, 1 Ancient Core Hound and 1 Lava Surger, then return to Duke Hydraxis in Azshara.", description = "<name>, perhaps it is time to give you a real test.  Are you ready?\n\nAt the bottom of Blackrock Depths is a passage to the Molten Core.  This is a stronghold of our enemy, held by the most powerful servants of fire on this world.\n\nGo to the Molten Core, <name>.  Show me you have the strength and the will to defeat what you find there.\n\nAnd if you have allies among your people, then rally them.  Nothing short of an army can hope to enter the Molten Core and live.", progress = nil, completion = "You have done what most of your kind would think impossible.  You have faced the beings of the Molten Core, and triumphed!\n\nFor so small a creature, you have displayed great resource.\n\nSome day, perhaps we might strike a true allegiance between your kind and the Waterlords.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6823] = {title = "Agent of Hydraxis", objective = "Earn an Honored faction with the Hydraxian Waterlords, then talk to Duke Hydraxis in Azshara.", description = "If you truly wish an allegiance with us, then I invite you to wage war on our foes, the servants of air and earth and fire.  Each defeat you heap upon them will weaken their foothold here, and further prove your adherence to our cause.\n\nThe campaign will be long, but if you persevere then your glory and honor will be great.", progress = "Your campaign is not yet done, <name>.  Go out and defeat our enemies, the servants of air and earth and fire, and one day perhaps you will earn a place in the hall of the Waterlords.", completion = "Your exploits against our enemies ring through the chambers of the Waterlords, &lt;name&gt;.  It was thought by some that your form is too small and fragile to fight in our war, but you have made great gains.  You have earned respect among us, an unbelievable feat.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6824] = {title = "Hands of the Enemy", objective = "Bring the Hands of Lucifron, Sulfuron, Gehennas and Shazzrah to Duke Hydraxis in Azshara.", description = "<name>, your service is of great value to us, so we are reluctant to send you on this last mission for we do not want to lose such a useful agent.\n\nBut its success would further our war efforts tremendously and... it was deemed worth risking you.\n\nWe want these captains in the Molten Core destroyed: Lucifron, Sulfuron, Gehennas and Shazzrah.  Kill them and bring me their hands!\n\nThis task will take every resource you possess, <name>, but if can do it then the Firelords will be dealt a terrible blow.", progress = "Have you defeated Lucifron and the others, <name>?  Do you have the hands of the enemy?", completion = "You have the hands!  You defeated the fire captains!  I would not have thought it possible, had I not known you and what you are capable of.\n\n&lt;name&gt;, your exploits are without number, but word of this last feat will send waves among the Waterlords.  Your name may one day be legend to us.\n\nSpeak with me again, &lt;name&gt;.  I may have yet another task...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6825] = {title = "Call of Air - Guse's Fleet", objective = "We must prepare the new fleet of War Riders, <race>! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.\n\nI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!", description = nil, progress = "We must prepare the new fleet of War Riders, <race>! My riders are set to make a strike on the central battlefield; but first, I must wet their appetites - preparing them for the assault.\n\nI need enough Stormpike Soldier Flesh to feed a fleet! Hundreds of pounds! Surely you can handle that, yes? Get going!", completion = "The fleet feeds on their flesh. It consumes the enemy.\n\nFlight is imminent!", rewards = nil}
MultiLanguageQuestData['en'][6826] = {title = "Call of Air - Jeztor's Fleet", objective = "You've worked hard, <name>, but we have only just begun!\n\nMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!\n\nMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.\n\nMake haste, soldier!", description = nil, progress = "You've worked hard, <name>, but we have only just begun!\n\nMy War Riders must taste in the flesh of their targets. This will ensure a surgical strike against our enemies!\n\nMy fleet is the second most powerful in our air command. Thusly, they will strike at the more powerful of our adversaries. For this, then, they need the flesh of the Stormpike Lieutenants.\n\nMake haste, soldier!", completion = "More! More! Bring more for they are soon to be ready!", rewards = nil}
MultiLanguageQuestData['en'][6827] = {title = "Call of Air - Mulverick's Fleet", objective = "I was locked up in a dwarven hellhole for days. You better believe I want revenge!\n\nWe must plan carefully.\n\nFirst, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.", description = nil, progress = "I was locked up in a dwarven hellhole for days. You better believe I want revenge!\n\nWe must plan carefully.\n\nFirst, my war riders need targets to gun for - high priority targets. I'm going to need to feed them the flesh of Stormpike Commanders. Unfortunately, those little buggers are entrenched deep behind enemy lines! You've definitely got your work cut out for you.", completion = "Not enough! I would expect this level of work from an initiate, but you, &lt;name&gt;? Come on, soldier! HUSTLE! More flesh is needed!", rewards = nil}
MultiLanguageQuestData['en'][6844] = {title = "Umber, Archivist", objective = "Take the Encrusted Silithid Object to Umber - the Cenarion Circle's archivist - in the village of Nighthaven, Moonglade.", description = "There's plenty to do here still, but I think taking this back to the Circle for analysis is key.  Trust me - the work will still be here once this is all said and done.  If it's a journal inside this sticky chitin, then the Circle would finally have a window into the past!\n\nTake this to the Circle's archivist in Nighthaven.  His name is Umber, and the man's brilliant.  Touched, sure, but brilliant nonetheless!  Umber's salvaged tomes in far worse shape than this.  If it can be saved, he can do it.", progress = "Why, hello there!  Hrmm...\n\nLet me be a little honest with you, friend... you smell a bit ripe.  Whiffy, one might say.  Now I'm not making a personal assailment of your being.  I'm just saying... in the future, you may want to freshen up a little after coming in from the field.  It will make those first impressions a little more positively impressionable!\n\nAnyhoo... what can I do for you?", completion = "Well great monkey toads!  What have you got here?  It's sort of book shaped, I guess... I'll try and crack this shell on it.\n\nLayo sent you to me from Silithus?  I've only heard very hushed rumblings - which I guess aren't all that hushed when you think about it - about the horrors that are going on out there.  Couple that with my lack of pleasure for anything bug-like, and you've got the recipe for me needing to stay here with the books!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6845] = {title = "Uncovering Past Secrets", objective = "Speak with Rabine Saturna in the village of Nighthaven, Moonglade.", description = "Anyway, you should check back with me relatively soon... that is if you want to know what was in here.  As soon as I find out what it is, and if it's indeed a book, I'd be happy to share that information with you.\n\nIn the meantime, I'd check in with the den mother of this little bear camp, Rabine.  No doubt he'll want to know what crazy antics you've been up to.  Never leave the den mother waiting, <name>... that is, unless you want to be doused in honey.\n\nIt's happened, trust me.", progress = nil, completion = "Ah, &lt;name&gt; - I had hoped you would stop by.  I am glad to see you well.\n\nI received notice you would be coming in from the field, and I wanted to personally express the Cenarion Circle's gratitude for the assistance you've given us thus far.  No doubt there are more secrets to uncover from Silithus; your delivery to Umber should prove most interesting once uncovered.  Please, accept this as a token of our continued appreciation for your aid.\n\nThank you, generous &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nRing of Living StoneGlowing Crystal Ring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6846] = {title = "Begin the Attack!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6847] = {title = "Master Ryson's All Seeing Eye", objective = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6848] = {title = "Master Ryson's All Seeing Eye", objective = "Recover Master Ryson's All Seeing Eye from the Winterax caves and return it to Master Ryson.\n\nBe warned, it is said that Master Ryson's All Seeing Eye carries with it a terrible curse!", description = "Your war in the heart of Alterac means nothing to the Syndicate, <class>. We will do as we have always done: Wait until a clear victor rises from the ashes and rubble of this madness and then strike.\n\nThat, however, is not why we are here now. The All Seeing Eye has been lost - taken by the Winterax trolls of the region.\n\nRecover the Eye and our services shall be yours - for whatever time remains for your side.\n\nReturn to me once you acquire the eye so that I may examine you.\n\n<Master Ryson grins.>Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6861] = {title = "Zinfizzlex's Portable Shredder Unit", objective = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Stormpike lumber camp.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nZinfizzlex's Portable Shredder Unit"}
MultiLanguageQuestData['en'][6862] = {title = "Zinfizzlex's Portable Shredder Unit", objective = "Master Engineer Zinfizzlex wants you to bring him the following:\n\n*30 Thorium Bars.\n\n*50 Mithril Bars.\n\n*75 Iron bars.\n\n*1 Steamsaw.", description = "I'm as anxious as you are to try out my portable shredder unit, <race>, but before I can make the kit, I'm going to need materials - lots of materials!\n\nTo be exact, I'm going to need a mountain of thorium, mithril, and iron. I will also need one steamsaw per unit. You'll have to get those at the lumber mill.\n\nWhen I was nosing around in here (before my capture) I noticed a pile of steamsaws at the Frostwolf lumber camp.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nZinfizzlex's Portable Shredder Unit"}
MultiLanguageQuestData['en'][6881] = {title = "Ivus the Forest Lord", objective = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", description = nil, progress = "The Frostwolf Clan is protected by a taint of elemental energy. Their shaman meddle in powers that will surely destroy us all if left unchecked.\n\nThe damage has grown too great for the Circle to control! Ivus must be called to our aid.\n\nThe Frostwolf soldiers carry elemental charms called storm crystals. We can use the charms to conjure Ivus. Venture forth and claim the crystals, <name>!", completion = "Well done, &lt;name&gt;. I will use the power of this charm to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause.", rewards = nil}
MultiLanguageQuestData['en'][6901] = {title = "Launch the Attack!", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][6921] = {title = "Amongst the Ruins", objective = "Bring the Fathom Core to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", description = "The Twilight's Hammer has moved into the Moonshrine Ruins of Blackfathom Deeps.  Their presence can only serve to coerce the elements into working against us.  If left unchecked, this region will be theirs for good.\n\n<name>, go into Blackfathom and find the ruin's fathom stone; it should be somewhere close in the water.  In it is a fathom core - a device that when properly read it will relate a history of all elemental activity.  If I have it, I and the Earthen Ring can maybe do something to stop them!", progress = "Have you been successful in locating the fathom core?  Without it we'll have no idea what the Twilight's Hammer is exactly up to down there.", completion = "This is exactly what I need!  A fathom core is an incredible well of information that we will be able to draw much good from.  Whatever the Twilight's Hammer is up to in there - and believe me when I say it is no good - my comrades and I will now uncover.\n\nYou've done well here today; the Earthen Ring looks upon you warmly for assisting us.  You've also helped the Horde as a whole, and for that you should be proud.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6922] = {title = "Baron Aquanis", objective = "Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale.", description = "The defeated water elemental has left behind a strange water globe.  You surmise that the object somehow fed the beast energy.  Inside the globe, a putrid-looking form of water sloshes about.  The globe itself seems impervious to any sort of physical force.\n\nIf anyone can make any sense of this item, it would be Je'neu Sancrea of the Earthen Ring.  He is located at the Horde's Zoram'gar Outpost in Ashenvale.", progress = "Ah, hello again <name>.  I was just reading the waves the sea, much like I always do.  What brings you to the outpost?", completion = "This... this is quite the find, &lt;name&gt;.\n\nYou acquired this from Baron Aquanis in Blackfathom, you say?  Baron Aquanis has long been thought of as a corrupted elemental power; this globe will prove what exactly had corrupted him.  While it would be no surprise if it turned out to be the Twilight's Hammer, our studies will also show how they did it as well.\n\nYou did well in bringing this to me.  Please - take this, along with the Earthen Ring's warmest regards.", rewards = "You will be able to choose one of these rewards:\n\nOutlaw SabreWitch's Finger\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][6941] = {title = "Call of Air - Vipore's Fleet", objective = "The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.", description = nil, progress = "The elite Frostwolf units that guard the lines must be dealt with, soldier! I'm tasking you with thinning out that herd of savages. Return to me with medals from their lieutenants and legionnaires. When I feel that enough of the riff-raff has been dealt with, I'll deploy the air strike.", completion = "The flight will be ready soon. Continue your efforts!", rewards = nil}
MultiLanguageQuestData['en'][6942] = {title = "Call of Air - Slidore's Fleet", objective = "My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.\n\nThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.\n\nOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!", description = nil, progress = "My gryphons are poised to strike at the front lines but cannot make the attack until the lines are thinned out.\n\nThe Frostwolf warriors charged with holding the front lines wear medals of service proudly upon their chests. Rip those medals off their rotten corpses and bring them back here.\n\nOnce the front line is sufficiently thinned out, I will make the call to air! Death from above!", completion = "Keep em coming, soldier! The Aerie gryphons will be ready to strike in no time at all!", rewards = nil}
MultiLanguageQuestData['en'][6943] = {title = "Call of Air - Ichman's Fleet", objective = "Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.\n\nReturn to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!", description = nil, progress = "Their spirits are low, soldier. After our last failed air strike against the Horde, they refuse to fly! It is up to you to bolster their morale.\n\nReturn to the battlefield and strike at the heart of the Frostwolf's command. Take down their commanders and guardians. Return to me with as many of their medals as you can stuff in your pack! I promise you, when my gryphons see the bounty and smell the blood of our enemies, they will fly again! Go now!", completion = "Can you see it? Look at them, soldier! They're coming around... Soon, Ichman's flight will once again strike at the heart of the valley! Stormpike will rule the skies!", rewards = nil}
MultiLanguageQuestData['en'][6961] = {title = "Great-father Winter is Here!", objective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", progress = nil, completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6962] = {title = "Treats for Great-father Winter", objective = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Orgrimmar.", description = "Hey, can you do Greatfather Winter a favor, um, little <boy/girl>?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Greatfather Winter there, &lt;name&gt;.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort.", rewards = "You will receive:\n\nSmokywood Pastures Gift Pack"}
MultiLanguageQuestData['en'][6963] = {title = "Stolen Winter Veil Treats", objective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", progress = nil, completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Orgrimmar b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6964] = {title = "The Reason for the Season", objective = "Speak with Sagorne Creststrider in the Valley of Wisdom of Orgrimmar about the Feast of Winter Veil.", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Sagorne Creststrider.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", progress = nil, completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us tauren.  Nowadays, it seems as though others have turned the legend of this season of renewal into something that helps to sell candies and presents.\n\nIt's no surprise that Furmund is bitter about that sort of change.  He and other tauren like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6981] = {title = "The Glowing Shard", objective = "Travel to Ratchet to find someone that can tell you more about the glowing shard.\n\nThen, deliver the shard as you are directed.", description = "The shard is a brilliant green, and although solid, what looks like smoke swirls just below the surface. You can't help staring into the depths of the crystal; at the same time, you know there is something very disturbing about it.\n\nMaybe you should see if anyone in Ratchet can tell you more about this strange shard.", progress = "Hello, <race>. What can I do for you?", completion = "Oh... I have never seen anything like this...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6982] = {title = "Coldtooth Supplies", objective = "Bring 10 Coldtooth Supplies to the Alliance Quartermaster in Dun Baldar.", description = "The Coldtooth mine is a storage depot for the Horde.  I can't stomach the food they give their troops, and the state of their arms and armor is atrocious!  But... in times like these when supplies are so important, we can use what they have.\n\nEnter the Coldtooth mine and bring me back their supplies.  That will help keep the Alliance in fighting shape, and remove much needed equipment from the Horde's warriors.\n\nGood luck, <name>.  The mine is to the distant south, deep in Horde territory.", progress = "Did you enter the Coldtooth mine in Horde territory, <name>?  Did you raid their supplies?", completion = "You got them!  Well done, &lt;name&gt;!  I'll go through these supplies and get them ready for our own troops!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6983] = {title = "You're a Mean One...", objective = "Locate and return the Stolen Treats to Kaymard Copperpinch in Orgrimmar. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.", description = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, <name>.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats <name>, take them b-b-back to Smokywood Pastures in Orgrimmar, and t-t-tell them I n-n-need to be unfrozen!", progress = "<name> - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][6984] = {title = "A Smokywood Pastures' Thank You!", objective = "Speak with Great-father Winter in Orgrimmar.", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, <name>.  For that, we'd like to offer you a special gift... presented by none other than Great-father Winter himself!\n\nPlease, speak with Great-father Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", progress = nil, completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", rewards = "You will receive:\n\nSmokywood Pastures Special Gift"}
MultiLanguageQuestData['en'][6985] = {title = "Irondeep Supplies", objective = "Bring 10 Irondeep Supplies to the Horde Quartermaster in Frostwolf Keep.", description = "The Stormpike dwarves are using the Irondeep mine as a storage depot.  I want you to raid that mine and bring me its supplies.  This will curtail the Stormpikes' efforts in Alterac Valley, and will provide us with needed equipment!\n\nBe wary, <name>.  The Irondeep mine is deep in Alliance territory, and control of the mine is as shifting as the snows of Alterac.", progress = "Did you enter the Irondeep mine, <name>?  Did you raid its supplies?", completion = "You got them!  Nicely done, &lt;name&gt;!  And I hope you saw a few dwarves during your raid, and shed their blood for the Frostwolves!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7001] = {title = "Empty Stables", objective = "Locate a Frostwolf in Alterac Valley. Use the Frostwolf Muzzle when you are near the Frostwolf to 'tame' the beast. Once tamed, the Frostwolf will follow you back to the Frostwolf Stable Master. Speak with the Frostwolf Stable Master to earn credit for the capture.", description = "The war in the valley has taken its toll on our soldiers. We must revitalize our forces!\n\nIf we can fill up the stables, the Wolf Riders will once more be able to ride out into the field of battle.\n\nTake this muzzle and track down the frostwolves that inhabit the nearby forest. Once you find a wolf, use the muzzle to tame the beast. Bring the tamed beast back to me so that I may place it in the stable.\n\nWhen we have enough wolves stabled, the Wolf Riders will rejoin their patrol on our front lines.", progress = "Without your help, the Frostwolf Wolf Riders would not have mounts to ride into battle. You do us a great service!", completion = "I can only hope that those charged with collecting ram hides are as determined as you, &lt;name&gt;.\n\nAt this rate, we will have the stables full in a matter of hours!", rewards = nil}
MultiLanguageQuestData['en'][7002] = {title = "Ram Hide Harnesses", objective = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!", description = nil, progress = "While some of our soldiers are busy capturing wolves for the stable master, others must provide for the simple necessities that riding requires. I am speaking of riding harnesses, of course.\n\nYou must strike at the indigenous rams of the region. The very same rams that the Stormpike cavalry uses as mounts!\n\nSlay them and return to me with their hides. Once we have gathered enough hides, we will fashion harnesses for the riders. The Frostwolf Wolf Riders will ride once more!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!", rewards = nil}
MultiLanguageQuestData['en'][7003] = {title = "Zapped Giants", objective = "Use Zorbin's Ultra-Shrinker to zap any kind of giant found in Feralas into a more manageable form. Bring 15 Miniaturization Residues found on the zapped versions of these giants to Zorbin Fandazzle at the docks of the Forgotten Coast, Feralas.", description = "I'm going to have to do something about the giants if I stay out here!  They're certainly not good for business, now are they?\n\nI've been working on a variant of a gnomish shrinking ray, but I'm using superior GOBLIN technological advances in its construction!  In an effort to avoid inconveniences for myself such as death, I'd like for you to try it out on any of the giants in Feralas.  You should find miniaturization residue on them after you shrink them - bring me back some!", progress = "Miniaturization residue, I assure you, is a valuable commodity when it comes to engineering!  Well, it is valuable in that it helps me make sure the zapper won't do something as disappointing as explode on the user.\n\nOh, I mean for the zappers other than the one I gave you.  Absolutely!", completion = "Splendifimous!  Not only am I glad to see that you've returned with the residue, but also with all your major appendages intact!  That is, well, there was never any danger in using the Ultra-Shrinker, now was there!\n\nI do appreciate your effort on my behalf, &lt;name&gt;.  Truly, you are a friend to goblins everywhere.  Accept this as a token of my appreciation!", rewards = "You will receive:\n\nZorbin's Mega-Slicer"}
MultiLanguageQuestData['en'][7021] = {title = "Great-father Winter is Here!", objective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", progress = nil, completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7022] = {title = "Greatfather Winter is Here!", objective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", progress = nil, completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7023] = {title = "Greatfather Winter is Here!", objective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Ironforge.", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Ironforge!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", progress = nil, completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7024] = {title = "Great-father Winter is Here!", objective = "Speak with Greatfather Winter; he is located near the Smokywood Pastures vendor area in Orgrimmar.", description = "Have a wondrous Winter Veil, friend!  Be sure to say hello to Greatfather Winter, who's currently in Orgrimmar!  If you've been nice this year, you'll receive wondrous treats on the day of the Feast of Winter Veil.  Be sure to tell him what you hope to get this year!\n\nAlso, be sure to stock up on treats to give those who've been nice this year.  We have a great selection to choose from.  Fresh from our farm to your plate - it's Smokywood Pastures wholesome goodness!", progress = nil, completion = "Ho ho hello.  I am Greatfather Winter, and I - courtesy of the fine folks of Smokywood Pastures... \"Fresh from our farm to your plate, it's Smokywood Pastures wholesome goodness\" - would like to wish you a fantastic Feast of Winter Veil.\n\nIf you've been good this year, maybe you will receive treats from Smokywood Pastures as your treat for the Feast of Winter Veil.  Huzzah.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7025] = {title = "Treats for Greatfather Winter", objective = "Bring 5 Gingerbread Cookies and an Ice Cold Milk to Greatfather Winter in Ironforge.", description = "Hey, can you do Greatfather Winter a favor, um, little <boy/girl>?\n\nNot to needlessly talk about myself in the third person, but Greatfather Winter has been at this all day and he could use a treat himself.  Some gingerbread cookies and ice cold milk to wash them down with would really hit the spot.  Think you could be a friend to the Greatfather and fetch some for me?", progress = "All this talk of treats has given me a hankering for some myself.  Mmmm... gingerbread cookies and milk...", completion = "You're quite the helper to ol' Greatfather Winter there, &lt;name&gt;.  Have a great Feast of Winter Veil.\n\nHere's a little something... you know, for the effort.", rewards = "You will receive:\n\nSmokywood Pastures Gift Pack"}
MultiLanguageQuestData['en'][7026] = {title = "Ram Riding Harnesses", objective = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!", description = nil, progress = "The Stormpike Brigade cannot charge into battle bareback! We require harnesses for our mounts, after all, we are not savages.\n\nWhile we could easily slay the rams that roam near our base for the leather required to fashion a harness, doing so would be idiotic. We need those rams for mounts.\n\nYou must strike at our enemy's base, slaying the frostwolves they use as mounts and taking their hides. Return their hides to me so that harnesses may be made for the cavalry. Go!", completion = "Well done, soldier. I will notify you when I have stockpiled enough of the hides.\n\nCarry on!", rewards = nil}
MultiLanguageQuestData['en'][7027] = {title = "Empty Stables", objective = "Locate an Alterac Ram in Alterac Valley. Use the Stormpike Training Collar when you are near the Alterac Ram to 'tame' the beast. Once tamed, the Alterac Ram will follow you back to the Stable Master. Speak with the Stable Master to earn credit for the capture.", description = "Just look at the stables, <name>! Empty! The Stormpike Brigade has no rams to ride - the cavalry is defunct.\n\nYou must help us, soldier. Take this training collar and enter the wilds of this valley. Locate the Alterac rams that roam throughout the area and use the collar to snare one. When you have captured a ram, return it to me and I shall place it in our stable.\n\nWhen we have enough rams, the ram rider commander will be notifed. With your help, the cavalry will be reborn!", progress = "Without your help, the Stormpike Ram Riders would not have mounts to ride into battle. You do us a great service!", completion = "The stables will be full in no time at all. Keep up the good work!", rewards = nil}
MultiLanguageQuestData['en'][7028] = {title = "Twisted Evils", objective = "Collect 15 Theradric Crystal Carvings for Willow in Desolace.", description = "The crystal caverns of Terramok lie to the west, deep within Maraudon... It is an ancient place with much history. And I am looking to get my hands on some of it, <class>. Relics of the old gods lie hidden behind the giant doors.\n\nIf you are willing to brave the twisted evils found in Maraudon, I believe I can make it worth your time. Collect the theradric crystal carvings you find, and return them to me.\n\nOnce I get the carvings, I will be able to... study them. These powers have been too long at rest...", progress = "Don't ask questions!\n\nYou have my request.", completion = "Ha ha ha! I knew you'd be back.\n\n&lt;Willow mutters.&gt;\n\n...So easy to convince.\n\n...Will do anything for the right price. Heh heh heh...", rewards = "You will be able to choose one of these rewards:\n\nAcumen RobesSprightring HelmRelentless ChainHulkstone Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7029] = {title = "Vyletongue Corruption", objective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village.", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the orange crystal pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, <name>...", completion = "Thank you for returning this, &lt;name&gt;. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.", rewards = "You will be able to choose one of these rewards:\n\nWoodseed HoopSagebrush GirdleBranchclaw Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7041] = {title = "Vyletongue Corruption", objective = "Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon.\n\nUse the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge.\n\nHeal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point.", description = "A satyr known as Vyletongue has corrupted the caverns of Maraudon, stunting the growth of many of the plants inside.\n\nTake this vial, <name>. Fill it at the corrupted orange pool found inside the caverns; the coating inside the vial will counter the toxins, turning it into a healing agent.\n\nFind the Vylestem vines inside the orange caverns, and use the purified liquid on them. The corruption will be purged from the plant, but do know that Vyletongue will still control it. He may use it against you...", progress = "If you are able to heal the plant, it will again begin to grow. We must do what we can, <name>...", completion = "Thank you for returning this, &lt;name&gt;. With the remaining liquid you brought me, I can continue my studies.\n\nWhile there is still much to do, you have helped to heal some of the corruption that Vyletongue spread through Maraudon. Please take this with my gratitude.", rewards = "You will be able to choose one of these rewards:\n\nWoodseed HoopSagebrush GirdleBranchclaw Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7042] = {title = "Stolen Winter Veil Treats", objective = "Locate the Smokywood Pastures investigator that has gone missing in the snowy regions of the Alterac Mountains.", description = "Listen... not to shatter the magic of the season here, but Smokywood Pastures could use some assistance - the kind you adventuring types are known to give.\n\nWe're missing an important shipment of treats that was restocking us for the season, and now we're missing the agent of Smokywood Pastures that we sent out to the field to find it!  Please - the shipment was last reported in the Alterac Mountains, and that's where our man went to look for it.\n\nSee if both are out there, safe and sound!", progress = nil, completion = "Y-y-you can h-h-hear me!  Thank the b-b-bottom line!\n\nI'm not really a s-s-snowman - my n-n-name is Sacks, and I w-w-work for the Ironforge b-b-branch of Smokywood Pastures... I g-g-got sent out here to look for a m-m-missing package, when I was attacked by a c-c-creature I have never seen b-b-before!\n\nSo v-v-very cold...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7043] = {title = "You're a Mean One...", objective = "Locate and return the Stolen Treats to Wulmort Jinglepocket in Ironforge. It was last thought to be in the possession of the Abominable Greench, found somewhere in the snowy regions of the Alterac Mountains.", description = "A c-c-creature called \"The Abominable Greench\" is the one w-w-who stole our shipment of t-t-treats, <name>.  Be c-c-careful though!  He is t-t-the one who turned me into this s-s-snowy mess!\n\nYou're g-g-gonna need some help in f-f-facing him.  I've seen him w-w-wander all around where the y-y-yeti are; he's s-s-surely here s-s-somewhere!  F-f-find the treats <name>, take them b-b-back to Smokywood Pastures in Ironforge, and t-t-tell them I n-n-need to be unfrozen!", progress = "<name> - our Feast of Winter Veil will be ruined without those treats to restock!  Graccu himself will miss out on sharing his delicious meat pies with all the good boys and girls this season...", completion = "You found it!  You've saved Smokywood Pasture's Feast of Winter Veil!\n\nPoor Sacks... we'll be sure to send a team out there and figure out a way to unfreeze him.  Hopefully, he'll be back in time for the day of the Feast; he'll need to make up missed time working though.  Still, this wouldn't even be possible if it weren't for you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7044] = {title = "Legends of Maraudon", objective = "Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond.\n\nFind a way to speak with Celebras.", description = "A dark satyr called Lord Vyletongue spread his evil through these twisting caves, poisoning the minds of all inside. He still resides beyond the purple crystals.\n\nVyletongue also created a living symbol of his corruption called Noxxion that dwells beyond the orange crystals. Together, they have stolen the two parts of my brother's scepter. Celebras, my brother... he wanders blindly inside, cursed by corruption.\n\nYou must help him! Find the pieces, and speak to my brother... somehow.", progress = "I have awoken from a nightmare that seemed it would never end...", completion = "Now that you have recovered the two parts of my scepter, I have hope that Maraudon may one day be rid of the Vyle corruption.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7045] = {title = "A Smokywood Pastures' Thank You!", objective = "Speak with Greatfather Winter in Ironforge.", description = "We at Smokywood Pastures appreciate the recovery of the stolen treats, <name>.  For that, we'd like to offer you a special gift... presented by none other than Greatfather Winter himself!\n\nPlease, speak with Greatfather Winter, and he will give you your Feast of Winter Veil gift from us here at Smokywood Pastures.  From our farm to your plate, it's always Smokywood Pastures wholesome goodness... thanks to you, of course!", progress = nil, completion = "Ho ho hello, adventurer!\n\nThe goblins told me that you have earned a special gift this holiday season, and I am pleased to give it to you.  Here you go - have a wondrous Feast of Winter Veil this and every season in the future.", rewards = "You will receive:\n\nSmokywood Pastures Special Gift"}
MultiLanguageQuestData['en'][7046] = {title = "The Scepter of Celebras", objective = "Assist Celebras the Redeemed while he creates the Scepter of Celebras.\n\nSpeak with him when the ritual is complete.", description = "My scepter was once a source of hope for me. Its power allowed me the freedom to travel quickly through these caverns. I had hoped to bring peace to the spirit of my uncle... It is a task that I now pass to you.\n\nFor the two parts to once again become one, I will need your assistance in performing the ritual. Please follow me, and listen to my instructions while I channel the energy required to reunite the rod with the diamond.\n\nTogether, we shall create the Scepter of Celebras once again!", progress = "If you wish to restart the ritual, please abandon our first attempt and then speak to me again.", completion = "Please take this, and know that the power allotted to you now must be used for good. Continue your journey through the caverns, and with hope, you will find the remains of my uncle. Much danger awaits you, &lt;name&gt;.\n\nSpeak with me again should the need arise.", rewards = "You will receive:\n\nScepter of Celebras"}
MultiLanguageQuestData['en'][7061] = {title = "The Feast of Winter Veil", objective = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to Cairne Bloodhoof in Thunder Bluff.", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a student of legends to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to Cairne Bloodhoof in Thunder Bluff.  I know for a fact he'd be interested in hearing that others have taken an interest in the lore of our people.", progress = "I bid you welcome to Mulgore and our humble community of Thunder Bluff, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public though over the years.  Yes, I know that the goblins are helping to revive the season for their own ends, the fact that our people reflect upon it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young &lt;class&gt;.  I salute your wisdom.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7062] = {title = "The Reason for the Season", objective = "Speak with Historian Karnik at the Explorer's League in Ironforge about the Feast of Winter Veil.", description = "Gifts, treats, presents... bah, I say!\n\nThose goblins pollute the true meaning of this season - the Feast of Winter Veil.  This is a time of renewal; the land slumbers under a blanket of snow brought forth by Greatfather Winter, who is NOT the bumbling fool over there in the red suit!\n\nIf you're interested in learning what the Feast is all about for yourself, ask Historian Karnik at the Explorer's League.  I'm sure he'll be surprised that someone cares about history rather than getting presents.", progress = nil, completion = "The Feast of Winter Veil, you say?  Alas, in times past it held a more substantial meaning to us dwarves.  Nowadays, it seems as though others have turned the legend of Greatfather Winter into something that helps to sell candies and presents.\n\nIt's no surprise that Goli is bitter about that sort of change.  He and other dwarves like him cling to our past like a banner of war.  While I think a little celebration is always good, it is important to remember the origins of the Feast.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7063] = {title = "The Feast of Winter Veil", objective = "Feel free to read the book, \"The Feast of Winter Veil\", to learn more about the holiday. When you are finished with the book, deliver it to King Magni Bronzebeard in Ironforge.", description = "Here - if you are interested in learning more about the Feast of Winter Veil, read this book.  While I think our recognition of the legend is the appropriate one, I'm enough of a scholar to appreciate the collection of all information into a single source.\n\nWhen you're done, take the book to King Magni Bronzebeard.  I know for a fact he'd be interested in hearing that others have taken an interest in the older legends.", progress = "I bid you welcome to the Kingdom of Ironforge, friend.  I always take an interest in those who choose to take an interest in the kingdom, its people, and its lore.  Is this why you are standing before me?", completion = "The legends and lore surrounding the Winter Veil are ones that have faded from the forefront of public thought over the years.  While I recognize that the goblins are helping to revive the season for their own ends, the fact that the citizenry thinks about it at least in some form does good to keep such lore alive.\n\nYour desire to go beyond the material and learn about our past is an admirable trait, young &lt;class&gt;.  I salute your erudite nature.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7064] = {title = "Corruption of Earth and Seed", objective = "Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace.", description = "Deep in Maraudon lives an evil creature of chaos--Princess Theradras is an elemental force of earth related to the Old Gods. Ages ago, she and Zaetar, first son of Cenarius, began a relationship. The offspring of their time together became known to the people of Kalimdor as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now hold Zaetar's remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", progress = nil, completion = "This is most wonderful news, &lt;name&gt;! Thank you!\n\nI will speak with Marandis and ask his wisdom on the topic of Zaetar's remains, but at least you have overcome the hardest of the tasks.\n\nI was told that if we were successful in our mission, I had permission to reward those who aided us. I was given these items as tokens from our people--you may choose one.", rewards = "You will be able to choose one of these rewards:\n\nThrash BladeResurgence RodVerdant Keeper's Aim\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7065] = {title = "Corruption of Earth and Seed", objective = "Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace.", description = "In the depths of Maraudon lives a creature of chaos and evil, <name>. Princess Theradras is an elemental force of earth related somehow to the Old Gods. Ages ago, she was sought out by Zaetar, first son of Cenarius. The offspring of their... relationship are the creatures known as centaur. Ever-thankful creatures, the centaur killed Zaetar, and now Theradras keeps his remains. My quest here is to find those powerful enough to slay Theradras so we may recover Zaetar's remains before returning to Stonetalon.", progress = nil, completion = "This is most wonderful news, &lt;name&gt;! Thank you!\n\nAlthough it concerns me that you were not able to bring back Zaetar's remains, who am I to question the will of Cenarius' first born. Perhaps now the will of the centaur will break and their thirst for blood will lesson--we can only hope.\n\nIf successful in our mission, I was given these items to reward any who aided us. You may choose one as a token of thanks.", rewards = "You will be able to choose one of these rewards:\n\nThrash BladeResurgence RodVerdant Keeper's Aim\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7066] = {title = "Seed of Life", objective = "Seek out Remulos in Moonglade and give him the Seed of Life.", description = "The misbegotten centaur--my sons and daughters--have need of their father.\n\nLook around you--this place rings of hope and all that my father Cenarius preaches. It sprung from me! And I cannot take that away from them... not even for their crimes against me.\n\nBut there is one thing I would ask of you to ease my brother's mind. Take this... it is the first seed that fell from the life my remains nourished. Tell him my spirit remains here, and that I live on. I am sure he will understand.", progress = "You have the scent of corruption on you, <name>... much like many adventurers these days. But something about you is different. Is there something you've come to speak to me about? You have an aura about you that seems familiar, but I cannot place it.\n\nPlease, I implore you, tell me why you've sought an audience with me.", completion = "So my brother has finally found peace? I am proud to have lived to see this day. In all his arrogance and anger, I truly thought he was lost to us, but this... this symbol of his sacrifice only proves that he is not lost--he has only been reborn. He takes his place in nature as was his duty.\n\nThank you, &lt;name&gt;. By bringing this to me, you have secured a small amount of hope that I thought I had once lost. This seed will be important to the people of this war-torn land some day... I can sense it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7067] = {title = "The Pariah's Instructions", objective = "Read the Pariah's Instructions. Afterwards, obtain the Amulet of Union from Maraudon and return it to the Centaur Pariah in southern Desolace.", description = "Though exiled as a heretic, my beliefs still ring true--that alone drives me onward. But for my destiny to be complete, I need the aid of an outsider... one not of any centaur tribe.\n\nThe task requires someone to enter the holy halls of Maraudon--a tomb my people protect, and only the most devout are ever allowed to enter.\n\nIf you agree to aid me, then you need only nod. I will pass you a parchment with my instructions on it. Read it over and consider my words.", progress = "What did you decide, <name>? Can you help me? Will you set foot on holy ground to help me forge one great centaur tribe!?", completion = "This is it, &lt;race&gt;! This is it! Now I can begin the great task of uniting the tribes. Thank you.\n\nTake this for your efforts, please. I hope when next we meet, it will be on much different terms.", rewards = "You will receive:\n\nMark of the Chosen"}
MultiLanguageQuestData['en'][7068] = {title = "Shadowshard Fragments", objective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar.", description = "Strong magics be found in the centaur holy place... the holy place of Maraudon. The Desolace tribes of centaur protect that place wit' their lives, but they canna stop us from takin' what we need.\n\nYou, you head to this Maraudon place and find the rock creatures made of shadowshard. You bring me the purple crystals, and Uthel'nay make you somethin' for your time.\n\nThe place be dangerous, so maybe you be bringing some friends.", progress = "You find the crystals yet? Rituals of power, spells of great strength--those shadowshards maybe very helpful in all kind of arcane magics.", completion = "Ah, these be perfect for me magics. Here, you take one of these trinkets and be on your way... me got much studyin' to do.", rewards = "You will be able to choose one of these rewards:\n\nZealous Shadowshard PendantProdigious Shadowshard Pendant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7070] = {title = "Shadowshard Fragments", objective = "Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh.", description = "I've recently begun testing various crystals and their arcane properties. Lady Proudmoore has given me leave to ask travelers heading into Desolace to seek out a place called Maraudon. Within the ruined temple are great elementals composed of purplish stones I've named shadowshards.\n\nIf you decide to head that direction and find some of the crystals, I would be very thankful. I could even fashion you a trinket from them if you so desired.", progress = "Have you made the trip yet? I realize it'd be quite dangerous, but if you were successful, it would very much be worth it.", completion = "These are perfect, &lt;name&gt;. I actually had other adventurers return from there also and from them I was able to fashion these... please, feel free to take one for your hard work. And thank you again for more samples to study.", rewards = "You will be able to choose one of these rewards:\n\nZealous Shadowshard PendantProdigious Shadowshard Pendant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7081] = {title = "Alterac Valley Graveyards", objective = "Assault a graveyard, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", description = "The graveyards in Alterac Valley are prized territories.  Both the Horde and the Alliance fight savagely for these sacred grounds.  Are you, <name>, ready to join that fight?\n\nI want you to assault an enemy graveyard.  Find a graveyard with a Horde banner in its midst, and pull it from the ground!  Do that, and your task will be complete....\n\nBut if you can also hold the graveyard for a few minutes, then our troops will soon come to relieve you.", progress = "<name>, you have not yet assaulted a graveyard.  Return to me when this task is complete!", completion = "Well done!  Graveyards are vital to our control of Alterac Valley.  When you capture one, you help ensure the Alliance's sovereignty here.\n\nGo now, &lt;name&gt;.  Reenter the battle, and if you see a graveyard under the Horde's control... you know what to do!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7082] = {title = "The Graveyards of Alterac", objective = "Assault a graveyard, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", description = "The battle lines of Alterac Valley are ever shifting.  Territories swing back and forth as we meet our opponents in deadly combat.  And graveyards, <name>, are where battles rage most fierce.\n\nI want you to attack an Alliance held graveyard!  Find a graveyard with an Alliance banner in its midst and pull it from the ground.\n\nDo that and your task for me will be complete, but... if you hold the graveyard for a few minutes, then it will be ours and troops will come and relieve you.", progress = "Attack a graveyard held by the Alliance!", completion = "Well done, &lt;name&gt;!  With each graveyard under our control, the spirits of our enemies will wander more lost and aimless.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7101] = {title = "Towers and Bunkers", objective = "Capture an enemy tower, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", description = "Towers and bunkers are important positions, and we must capture and hold them all!  So to that end, I want you to attack a bunker that is controlled by the enemy.\n\nTo do that, enter one with an Alliance banner.  You will see another banner inside.  Pull out that banner, and a white Horde banner will appear in its place.  Well done!\n\nAt that point your task for me will be complete, but if you hold the place long enough, and if the Alliance doesn't take it back, then it will be destroyed!", progress = "You haven't yet assaulted a bunker, <name>!  Are you waiting for others to claim your glory?", completion = "I heard of your mission's success!  That pleases me...\n\nOur troops can now charge forward with impunity, and show the Alliance that Alterac Valley is no place for them!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7102] = {title = "Towers and Bunkers", objective = "Destroy the banner at an enemy tower or bunker, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", description = "Towers and bunkers are key defensive positions, and so we must hold as many as possible!  I want you to attack a tower or a bunker in Alterac Valley.\n\nTo do that, enter a tower with a Horde banner atop it.  You will see another enemy banner inside.  Pull out that banner, and a white Alliance banner will appear in its place.  Well done!\n\nAt that point your mission for me will be complete, but hold the area long enough, and if the Horde doesn't take it back, then it will be destroyed!", progress = "You haven't yet assaulted a tower, <name>!  What are you waiting for?", completion = "I received a field report stating you helped secure an enemy banner.  Well done, &lt;name&gt;!  With their ranged troops out of position we can move the line of battle forward!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7121] = {title = "The Quartermaster", objective = "Speak with the Stormpike Quartermaster.", description = "<name>, our quartermaster charged me to direct new recruits to him.  He needs supplies from caches stored in the mines of Alterac, and he'll probably send you to get them.\n\nFollow the road.  You'll find our quartermaster to the west.", progress = nil, completion = "It's good to see fresh troops here, &lt;name&gt;, but with a little luck you'll get into some action and won't be fresh for long!\n\nSpeak with me again.  I have tasks I must discuss with you....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7122] = {title = "Capture a Mine", objective = "Capture a mine that the Stormpike does not control, then return to Sergeant Durgen Stormpike in the Alterac Mountains.", description = "The mines in Alterac Valley hold more than just minerals.  Both the Frostwolf and Stormpike have cached excess supplies in the Irondeep and Coldtooth mines... that's not a bad idea, if we could only maintain control of them!\n\nCapture a mine, then return to me.  To capture a mine, enter one that we do not control and kill its leader.  When you do that, the mine will be ours, and we'll send troops to protect it!", progress = "You haven't captured the mine yet, <name>!\n\nAfter we control a mine, it will be much easier to gather minerals and supplies from it.", completion = "You did it!  Well done, &lt;name&gt;!\n\nWhen we control a mine and have troops stationed there, it's much easier to gather minerals and supplies from it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7123] = {title = "Speak with our Quartermaster", objective = "Speak with the Frostwolf Quartermaster.", description = "<name>, the Frostwolf Quartermaster is looking for recruits, for tasks that lead into the mines of Alterac Valley.  Speak with him; he will tell you more.\n\nFollow the road west into the bunker, then take the west exit and you'll find our quartermaster.", progress = nil, completion = "Hail, &lt;name&gt;!  It is good to see a &lt;class&gt; like yourself, eager to do his part for the Horde.  Speak with me again, for I have vital tasks for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7124] = {title = "Capture a Mine", objective = "Capture a mine, then return to Corporal Teeka Bloodsnarl in the Alterac Mountains.", description = "As battle rages over the landscape of Alterac Valley, so too does it rage through the Coldtooth and Irondeep mines.  Both are rich sources of minerals and both are used to store supplies; it's no wonder they are so highly valued!\n\nHelp our war effort, <name>!  Capture one of the mines for the Horde!  To capture a mine, enter one that we do not control and kill its leader.  When that is done, the mine will be ours and we'll send troops to protect it!", progress = "You haven't yet captured a mine, <name>!  Find one that we do not control and defeat it's leader!", completion = "You captured a mine!  With our own warriors protecting it, it will be much simpler to extract minerals from its depths, or gather supplies that have been cached there.\n\nWell done, &lt;name&gt;.  The deed you have done is a great boon to our battle efforts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7141] = {title = "The Battle of Alterac", objective = "Enter Alterac Valley, defeat the Horde general Drek'thar, and then return to Prospector Stonehewer in the Alterac Mountains.", description = "The Explorers' League believes there are artifacts in Alterac Valley, but the Frostwolf orcs won't let us explore.  We can't allow the Horde to stop our scholarly pursuits!  Defeat the Frostwolf general, Drek'Thar.  With him dead, the orcs will lose their edge.\n\nDrek'Thar is in Frostwolf Keep, in the south of Alterac Valley.  Vanquish him, and then return to me.", progress = "Go, <name>.  Go to Alterac Valley and defeat the orc general!", completion = "Well done, &lt;name&gt;!  With the Horde's nose bloodied after the death of their general, we'll have the breathing room we need to explore!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7142] = {title = "The Battle for Alterac", objective = "Enter Alterac Valley and defeat the dwarven general, Vanndar Stormpike. Then, return to Voggah Deathgrip in the Alterac Mountains.", description = "The Stormpike dwarves and their allies have invaded Alterac Valley, and we must drive them out!  To win the battle for Alterac, we must defeat their general, Vanndar Stormpike!\n\nYou will find Vanndar in Dun Baldar, in the north of Alterac Valley.\n\nDestroy him, <name>, and then return to me.", progress = "We will not suffer the dwarves in our home!  Fall upon our foes and defeat their leader, general Stormpike!", completion = "Well done, &lt;name&gt;!  Stormpikes have no hope in this foolish invasion.\n\nHah!  So far, all they've done is get their general killed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7161] = {title = "Proving Grounds", objective = "Travel to the Wildpaw cavern located southeast of the main base in Alterac Valley and find the Frostwolf Banner. Return the Frostwolf Banner to Warmaster Laggrond.", description = "Hail, <class>. It has been a long time since we have had the chance to answer the call of battle. The old feelings are slow to rise but once awakened, the blood does rush. The battle rage returns...\n\nAll newcomers to the Valley must first complete the rite of battle.\n\nDeep within the Wildpaw gnoll cave is a banner of the Frostwolf. Venture forth and recover the banner. Return it to me and I shall grant you the Frostwolf initiate's insignia.", progress = "Wake up! Wake up, <name>! This is not a dream. You really are entrenched in the midst of a raging battle!", completion = "That burning sensation you feel is your soul being awakened. Your spirit has accepted the call to arms.\n\nYou are now one of the Frostwolf, &lt;name&gt;. Congratulations.\n\nCarry this insignia with you at all times. As you advance among the ranks of Frostwolf, I will replace the insignia with other, more powerful insignias.\n\nPerhaps someday you will be exalted among the Frostwolf Clan. Should that day ever come, you will be granted the Eye of Command.", rewards = "You will receive:\n\nFrostwolf Insignia Rank 1Peeling the Onion"}
MultiLanguageQuestData['en'][7162] = {title = "Proving Grounds", objective = "Travel to the Icewing Caverns located southwest of Dun Baldar in Alterac Valley and recover the Stormpike Banner. Return the Stormpike Banner to Lieutenant Haggerdin in the Alterac Mountains.", description = "You've arrived just in time, <class>. These Frostwolf savages just won't give up! We must show them the might of the Stormpike. They must bow to our superiority.\n\nBefore you make your way to the field of battle, you will want to join the rank of Stormpike.\n\nSouthwest of Dun Baldar, you will find the Icewing Caverns. Planted deep within the caverns is a Stormpike Banner. Venture forth and recover that banner. Return it to me, and you will have earned a Stormpike initiate's insignia.", progress = "Beware the harpies of the region, <class>. They'll not think twice to rip out your throat!", completion = "Take and wear this insignia with pride, &lt;name&gt;. As your rank among the Stormpike grows, so too will the insignia. Return to me as you gain honor with Stormpike, and I shall replace your insignia with other, more powerful insignias.\n\nPerhaps someday you will grow to be a legend on this field of battle. Should that day ever come, you will be granted the Eye of Command.", rewards = "You will receive:\n\nStormpike Insignia Rank 1The Frostwolf Artichoke"}
MultiLanguageQuestData['en'][7163] = {title = "Rise and Be Recognized", objective = "<Warmaster Laggrond salutes you.>\n\nIt is your time, <name>. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", description = nil, progress = "<Warmaster Laggrond salutes you.>\n\nIt is your time, <name>. You have done much for the Frostwolf Clan and in doing so, earned a place as not only a soldier of Frostwolf but also as a friend.\n\nWell done! Present your initiate's insignia.", completion = "This new insignia reflects your rank amongst the Frostwolf. Keep it on you at all times.\n\nAnd &lt;class&gt;... Die with honor!", rewards = "You will receive:\n\nFrostwolf Insignia Rank 2"}
MultiLanguageQuestData['en'][7164] = {title = "Honored Amongst the Clan", objective = "It is good to see you again, <class>. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, <name>. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", description = nil, progress = "It is good to see you again, <class>. I had not expected you to return. Alas, you have proven yourself a brave and honorable soldier of the Frostwolf.\n\nYour time has come again, <name>. You have earned a new ranking and as such, a new insignia denoting this rise in stature.\n\nPresent your insignia.", completion = "&lt;Warmaster Laggrond salutes.&gt;\n\nGo, &lt;name&gt;! Continue your defense of the Frostwolf. This war must be won! For Drek'Thar! For the Warchief!", rewards = "You will receive:\n\nFrostwolf Insignia Rank 3"}
MultiLanguageQuestData['en'][7165] = {title = "Earned Reverence", objective = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", description = nil, progress = "So many slain. Blood drenches the fields. Yet... You live... You have persevered. You have led our armies to many victories. For this, then, soldier, you have earned a new rank.\n\nPresent your insignia.", completion = "&lt;Warmaster Laggrond roars.&gt;\n\nThey have already begun telling tales of your deeds, soldier. The Stormpike shakes in fear when your name is uttered. Carry on!", rewards = "You will receive:\n\nFrostwolf Insignia Rank 4"}
MultiLanguageQuestData['en'][7166] = {title = "Legendary Heroes", objective = "Your radiate command and power, <class>. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", description = nil, progress = "Your radiate command and power, <class>. Exalted in the eyes of Frostwolf - the enemy cowers at the mention of your name.\n\nRise, Hero of Frostwolf. Rise and be honored!\n\nPresent your insignia.", completion = "Soon, all on the field of battle will be under your watchful eye. Command of the Valley and its troops will be yours!", rewards = "You will receive:\n\nFrostwolf Insignia Rank 5"}
MultiLanguageQuestData['en'][7167] = {title = "The Eye of Command", objective = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander <name>.", description = nil, progress = "Drek'Thar sings your praises. Kalimdor is abuzz with tales of your heroics. The Warchief glows - your stalwart defense of our clan has pleased him greatly.\n\nYou have earned the Eye of Command.\n\nPresent your insignia, Commander <name>.", completion = "Channel the power of the insignia. Let the enemy hear your words. The might of the Horde is unquestionable!", rewards = "You will receive:\n\nFrostwolf Insignia Rank 6"}
MultiLanguageQuestData['en'][7168] = {title = "Rise and Be Recognized", objective = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, <class>. The time has come.\n\nPresent your insignia.", description = nil, progress = "Most do not live long enough to rise above their own mediocrity. You have proven yourself to be an exemplary soldier, <class>. The time has come.\n\nPresent your insignia.", completion = "Let our enemies see that a soldier of rank has struck them down! Fight for the glory of Stormpike!", rewards = "You will receive:\n\nStormpike Insignia Rank 2"}
MultiLanguageQuestData['en'][7169] = {title = "Honored Amongst the Guard", objective = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", description = nil, progress = "The base buzzes with news of your exploits in the Field of Strife! You have struck mighty blows against our enemy - crushing their morale! For this, you have earned a rank of honor among the Stormpike.\n\nPresent your insignia.", completion = "The king has been made aware of your battlefront heroics, &lt;class&gt;. Continue in your stalwart defense of the Stormpike Guard!", rewards = "You will receive:\n\nStormpike Insignia Rank 3"}
MultiLanguageQuestData['en'][7170] = {title = "Earned Reverence", objective = "I must know, <name>. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", description = nil, progress = "I must know, <name>. When you look directly into the eyes of the enemy, do you see fear? Do they now cower in your presence? They must realize that they are defeated!\n\nYou have earned reverence among the Guard. Present your insignia!", completion = "When we first met, I would have never guessed that a hero was in the making. Carry on, soldier!", rewards = "You will receive:\n\nStormpike Insignia Rank 4"}
MultiLanguageQuestData['en'][7171] = {title = "Legendary Heroes", objective = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", description = nil, progress = "Before me stands an exalted hero of the Alliance.\n\n<Lieutenant Haggerdin salutes.>\n\nFew have earned such a rank among the Stormpike. I have watched the enemy fall before you. I have seen their resolve crumble in your presence. When you enter the fray, you become the beacon of hope for our forces!\n\nPresent your insignia.", completion = "Surely it will be you who carries the Eye of Command!", rewards = "You will receive:\n\nStormpike Insignia Rank 5"}
MultiLanguageQuestData['en'][7172] = {title = "The Eye of Command", objective = "Let them hear your voice, Commander <name>! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.", description = nil, progress = "Let them hear your voice, Commander <name>! Let them know fear. Show them what power the Stormpike holds in their rank!\n\nPresent your insignia.", completion = "It is you who must lead our troops to victory, Commander! The soldiers are under your command. They will follow your direct orders. Lead them.... Crush the Frostwolf.", rewards = "You will receive:\n\nStormpike Insignia Rank 6"}
MultiLanguageQuestData['en'][7181] = {title = "The Legend of Korrak", objective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Warmaster Laggrond.", description = "The invading Stormpike are not the only threat in the region, soldier. The war in the Valley is waged on two fronts. The cannibal Winterax trolls also vie for power.\n\nThey are lead by Korrak the Bloodrager - a cruel and cunning beast.\n\nA strike against Korrak could prove to be a crushing blow to the Winterax clan. Slay the beast and be rewarded!You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nBloodseekerIce Barbed SpearWand of Biting Cold\n\nYou will also receive:\n\nRune of Recall"}
MultiLanguageQuestData['en'][7201] = {title = "The Last Element", objective = "Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals.", description = "There is work to be had for those venturing into the depths, <name>.\n\nThe Dark Irons have mastered creation of extremely powerful golems.\n\nInitial reports from our spies indicate that the dwarves use a unique power source to give their creations incomparable killing power.\n\nJust imagine what we could do with our abominations if we could get our hands on this essence of the elements! Turn that city upside down if you must, but do not return until you have found the essence! Payment will be worth the risk.", progress = "<Rubs her hands together.>\n\nShow them to me!", completion = "Wonderful! I will have these sent by courier to the Undercity at once!\n\nAs for you - here is payment, as promised. Keep the change, you filthy beast!", rewards = "You will receive:\n\nLagrave's Seal"}
MultiLanguageQuestData['en'][7202] = {title = "Korrak the Bloodrager", objective = "According to legend, the leader of the mighty Winterax trolls appears at will to wreak havoc on the denizens of Alterac Valley.\n\nShould Korrak make himself known, destroy him and return to Lieutenant Haggerdin in the Alterac Mountains.", description = "The indigenous Winterax trolls of the region are ruthless savages that would love nothing more than to have our bones added to their foul stew.\n\nWe must show them our might!\n\nWe have recovered tomes from their caves that detail their leadership hierarchy. The artifacts indicate that their leader, Korrak the Bloodrager, tends to remain hidden until given a reason to make his presence known.\n\nDeath to Korrak would mean death to Winterax Clan! Slay him and return.You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nBloodseekerIce Barbed SpearWand of Biting Cold\n\nYou will also receive:\n\nRune of Recall"}
MultiLanguageQuestData['en'][7221] = {title = "Speak with Prospector Stonehewer", objective = "Speak with Prospector Stonehewer in the Dun Baldar garrison.Ah, <name>, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar. She's recruiting for a vital mission into enemy territory. You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar. There's plenty to do for a hardworking <class> who's not afraid to get <his/her> hands dirty.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Ah, <name>, reporting for duty are you?  Great, the Stormpikes can use everyone we can muster!\n\nSpeak with Prospector Stonehewer in Dun Baldar.  She's recruiting for a vital mission into enemy territory.  You'll find Stonehewer in the bottom of the Dun Baldar garrison.\n\nAnd keep an eye out as you go through Dun Baldar.  There's plenty to do for a hardworking <class> who's not afraid to get <his/her> hands dirty.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7222] = {title = "Speak with Voggah Deathgrip", objective = "Speak with Voggah in Frostwolf Keep.A <class>?  Good!  We are glad to see you in Alterac, <name>. Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip. He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "A <class>?  Good!  We are glad to see you in Alterac, <name>.  Interloping dwarves and their allies invade our valley, and we welcome all in the Horde to join us in righteous slaughter!\n\nSpeak with Voggah Deathgrip.  He is looking for agents for an important mission into the Alliance's stronghold in Alterac Valley!\n\nYou will find Voggah in Frostwolf Keep.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7223] = {title = "Armor Scraps", objective = "Bring 20 Armor Scraps to Murgot Deepforge in Dun Baldar.", description = "Battles rage constantly in Alterac Valley, and the supplies we get from Ironforge are not enough to outfit our experienced troops.\n\nIf you find armor scraps from the battlefield, aid the war effort and bring those scraps to me!", progress = "Did you bring any armor scraps, <name>?", completion = "These are some good pieces, &lt;name&gt;.  I can use them to fashion new equipment for our troops.\n\nIf my supply level gets high enough, then maybe our seasoned fighting units will enter the field!", rewards = "The following spell will be cast on you:\n\nPolished Armor\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][7224] = {title = "Enemy Booty", objective = "Bring 20 Armor Scraps to Smith Regzar in Frostwolf Village.", description = "When you fight the enemy, gather the scraps of their armor and bring them to me.  I'll use those scraps to make armor for our own troops!", progress = "How goes the hunting, <name>.  Do you have any armor scraps for me?", completion = "These will do nicely.  I'll melt them down and patch them up and you'll never know they came from those Stormpike cowards!\n\nThanks, &lt;name&gt;.  And let me polish up that armor of yours...", rewards = "The following spell will be cast on you:\n\nPolished Armor\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][7241] = {title = "In Defense of Frostwolf", objective = "Venture to Alterac Valley, located in the Alterac Mountains. Find and speak with Warmaster Laggrond - who stands outside the tunnel entrance - to begin your career as a soldier of Frostwolf. You will find Alterac Valley north of Tarren Mill at the base of the Alterac Mountains.", description = "The drums of war sound off in a distant land, <class>. The favored clan of your Warchief is under attack from the nefarious Stormpike Guard of Ironforge.\n\nBy the looks of you, I can discern that you are indeed battle hardy and prepared to take on the cause of the Frostwolf.\n\nIt is you who must now take the next step in your evolution.\n\nNorth of Tarren Mill, in Alterac,  you will find the entrance to Alterac Valley. It is there that you will find Warmaster Laggrond. Hurry <class>, for the battle is upon us!", progress = nil, completion = "To become a soldier of Frostwolf, one must first be tested...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7261] = {title = "The Sovereign Imperative", objective = "Travel to Alterac Valley in the Hillsbrad Foothills. Outside of the entrance tunnel, find and speak with Lieutenant Haggerdin.\n\nFor the glory of Bronzebeard!", description = "We are fighting a brutal battle in the valleys of Alterac. The cannibalistic Winterax trolls attack us from one side and the savage Frostwolf Clan from the other. Both must be exterminated in the name of King Magni Bronzebeard! The taking, culling, and turning of that land is a sovereign and territorial imperative to the kingdom of Ironforge.\n\nAlas, soldiers do not grow on trees! Report to Lieutenant Haggerdin outside Alterac Valley to begin your tour of duty and honor amongst the Stormpike.", progress = nil, completion = "Let's get to work!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7281] = {title = "Brotherly Love", objective = "Travel into Stormpike territory and slay Commander Karl Philips. Return to Commander Louis Philips when the task is complete.", description = "Tragic... My brother faces me on the field of battle: A commander for the Stormpike.\n\nOf the four Stormpike Commanders, he is undoubtedly the most dangerous. Perhaps if he is slain, the Banshee Queen could turn him as she did me - show him the error of his ways...\n\nDeep within enemy territory you will find my brother. Slay him and return to me. I trust that you are capable of completing this mission, soldier.\n\nAnd soldier, do not go alone.", progress = nil, completion = "Your heroics will not go unnoticed, &lt;name&gt;.\n\nI must waste no time if he is to be saved. Sylvanas must be contacted!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7282] = {title = "Brotherly Love", objective = "Travel into Frostwolf territory and slay Commander Louis Philips. Return to Commander Karl Philips when the task is complete.", description = "He must be put out of his misery, soldier! He knows not what he does. He has become a mindless servant of the dreaded Banshee Queen.\n\nVenture forth, across the Field of Strife, to the depths of Frostwolf territory. Find my brother and destroy him. His torment must come to an end.", progress = nil, completion = "You did remember to burn the corpse, didn't you?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7301] = {title = "Fallen Sky Lords", objective = "Travel to Frostwolf territory and search for Wing Commander Slidore, Wing Commander Vipore, and Wing Commander Ichman. Return to Commander Duffy should you complete your mission.", description = "We got them held prisoner, <race>. I'm talking about their Wing Commanders. It was a furious battle in the skies but they finally fell! Unfortunately, our best pilots were shot down in a counterattack against Frostwolf Keep. You gotta find out what happened to them.\n\nSearch Tower Point West and Frostwolf Keep. These were their last known locations. Search these areas thoroughly.", progress = nil, completion = "Unbelievable! You did free them, right? Right??? Well at the very least we know where they were held.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7302] = {title = "Fallen Sky Lords", objective = "Find out what became of Wing Commander Guse, Wing Commander Jeztor, and Wing Commander Mulverick. Return to Commander Mulfort should you complete your mission.", description = "Our air support is in shambles, <name>. The Wing Commanders were shot down over enemy territory. You must find out what became of them so that we can attempt a rescue!\n\nGuse was last seen flying over the Icewing Bunker. Jeztor's War Rider was spotted near the Stormpike lumber mill. Mulverick... that reckless fool was seen crashing near the Dun'Baldar North Bunker.\n\nThat's all the information I have. Move out! Search through the areas thoroughly.", progress = nil, completion = "Well done! The information you recovered will be invaluable to our cause.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7321] = {title = "Soothing Turtle Bisque", objective = "Bring 10 pieces of Turtle Meat and some Soothing Spices to Christoph Jeffcoat in Tarren Mill.", description = "Who says that the undead don't know anything about cooking? Take my secret recipe for Turtle Bisque, for example. I've known folks that would come back from the dead just to enjoy a bowl! Heh, heh...\n\nSpeaking of which, I haven't been able to make any lately.  I used to head over to Lake Lordamere myself to hunt snapjaws, the nasty things, but I can't pull myself away from my work here.\n\nIf you bring me some Turtle Meat from the snapjaws and soothing spices, I'll show you how it's done!", progress = "Any luck finding the ingredients?  I'll tell you, the alliance maggots are far too numerous in this area now... In my opinion, they have come far too close already...", completion = "My soothing turtle bisque will keep you warm on a cold night... if you care about that kind of thing.", rewards = "You will receive:\n\nRecipe: Soothing Turtle BisqueSoothing Turtle Bisque"}
MultiLanguageQuestData['en'][7341] = {title = "A Fair Trade", objective = "Greetings, <race>. I am Kolark, Bounty <class> from Thunderbluff. Much of the world I have traveled and much I have seen.\n\nMy journeys across the South Seas led to the discovery of these wonderous thorium headed arrows. Alas, I have an endless supply of the arrows but have exhausted my supply of shells. Bah, no self respecting Tauren would ever be caught dead using a flimsy bow. The arrows are useless!\n\nI will offer a trade: An even exchange of thorium shells for my thorium headed arrows. Deal?", description = nil, progress = "Greetings, <race>. I am Kolark, Bounty <class> from Thunderbluff. Much of the world I have traveled and much I have seen.\n\nMy journeys across the South Seas led to the discovery of these wonderous thorium headed arrows. Alas, I have an endless supply of the arrows but have exhausted my supply of shells. Bah, no self respecting Tauren would ever be caught dead using a flimsy bow. The arrows are useless!\n\nI will offer a trade: An even exchange of thorium shells for my thorium headed arrows. Deal?", completion = "Excellent! I am a Tauren of my word, &lt;race&gt;. The arrows are yours.", rewards = "You will receive:\n\nThorium Headed Arrow"}
MultiLanguageQuestData['en'][7342] = {title = "Arrows Are For Sissies", objective = "Can you believe this rubbish?! The last shipment of ammunition from Kharanos was botched! All we have for ammo now are these flimsy, good for nothing arrows! What in the world am I going to do with 500,000 thorium headed arrows?\n\nI'll tell you what, kid. If you can bring me thorium shells, I'll trade you thorium headed arrows - straight up! Deal?", description = nil, progress = "Can you believe this rubbish?! The last shipment of ammunition from Kharanos was botched! All we have for ammo now are these flimsy, good for nothing arrows! What in the world am I going to do with 500,000 thorium headed arrows?\n\nI'll tell you what, kid. If you can bring me thorium shells, I'll trade you thorium headed arrows - straight up! Deal?", completion = "A done deal if I ever saw one! The arrows are yours.", rewards = "You will receive:\n\nThorium Headed Arrow"}
MultiLanguageQuestData['en'][7367] = {title = "Defusing the Threat", objective = "Find the Frostwolf Explosives Expert and kill him. Return to the Stormpike Explosives Expert when the task is complete.", description = "The Frostwolf have their front lines and bases booby trapped, <class>. You have to watch your step when invading enemy territory.\n\nIf you want to make a solid strike against them, you must destroy their source of anti personnel munitions - I'm talking about their explosives expert. If you kill him, you are safe to disarm the mines. As long as he is kept down, the mines will also stay down.\n\nYou will probably find him in a tower near the Iceblood Garrison. Good luck!You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7368] = {title = "Defusing the Threat", objective = "Find the Stormpike Explosives Expert and kill him. Return to the Frostwolf Explosives Expert when the task is complete.", description = "I know all about landmines. I'm the one that lays all the mines on the front lines here, after all.\n\nIf you want to defuse the Stormpike mine fields, all you have to do is kill their explosives expert. That dwarven coward is no doubt hiding in the first tower on the Field of Strife. Take him out and those landmines won't come back after they've been disarmed.\n\nIf you do happen to kill him, come back here and let me know. No good deed should go unrewarded.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7383] = {title = "Crown of the Earth", objective = "Fill the Amethyst Phial and bring it back to Corithras Moonrage in Dolanaar.", description = "All was not well with Teldrassil, however. Staghelm's carefully made plans for the new World Tree had borne out as he had hoped, but there was one small problem, a problem to which many of the troubles on Teldrassil may be attributed.\n\nHowever, I will not get into that yet. You must visit the last moonwell, to the northwest in the Oracle Glade. Under the boughs of the Oracle Tree lies the first and most powerful of our wells. Retrieve a phial of its water and return to me.", progress = "Along with the druids, the Oracle Tree and the Arch Druid have been carefully monitoring the growth of Teldrassil. But though we have a new home, our immortal lives have not been restored.", completion = "To be in the presence of the Oracle Tree... it is almost to feel wisdom take form. Let me continue the telling...\n\nWith Teldrassil grown, the Arch Druid approached the dragons for their blessings, as the dragons had placed upon Nordrassil in ancient times. But Nozdormu, Lord of Time, refused to give his blessing, chiding the druid for his arrogance. In agreement with Nozdormu, Alexstrasza also refused Staghelm, and without her blessing, Teldrassil's growth has been flawed and unpredictable...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7385] = {title = "A Gallon of Blood", objective = "You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, <name>.", description = nil, progress = "You have the option of offering larger quantities of the blood taken from our enemies. I will be glad to accept gallon sized offerings, <name>.", completion = "The blood of our enemies has been shed. I shall mix this blood with the rest that has been gathered. Once the offering is complete, the Ice Lord shall show these Stormpike dogs the full wrath of the Frostwolf Clan!", rewards = nil}
MultiLanguageQuestData['en'][7386] = {title = "Crystal Cluster", objective = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, <name>.", description = nil, progress = "There are times which you may be entrenched in battle for days or weeks on end. During those longer periods of activity you may end up collecting large clusters of the Frostwolf's storm crystals.\n\nThe Circle accepts such offerings, <name>.", completion = "Well done, &lt;name&gt;. I will use the power of these charms to augment the magic that has already been gathered. When enough power has been amassed, I shall focus the collected energies and call upon the Forest Lord to aid our cause.", rewards = nil}
MultiLanguageQuestData['en'][7429] = {title = "Free Knot!", objective = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", description = nil, progress = "It's called the Gordok Shackle Key - well, that's what these \"tons o' fun\" keep calling it.  I think any of the ogres might have it, but I'm not sure if any specific ones do.  Maybe the guards have a better chance of having one...\n\nWhat am I talking about - you have it already, don't you?!  Is that it there??!", completion = "Oh, thank you for freeing me!  You - ranked number one.  Everyone else - ranked number two or lower.\n\nI knew my life was destined for more than just being an appetizer to some ogre!", rewards = nil}
MultiLanguageQuestData['en'][7441] = {title = "Pusillin and the Elder Azj'Tordin", objective = "Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary.\n\nReturn to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations.", description = "I had let my guard down for only one moment, stranger. In my haste to escape the grip of the fallen Prince, I was robbed. A most foul demon, the imp Pusillin, pilfered my book of incantations and the key to the once great halls of Eldre'Thalas.\n\nI no longer hold interest in the key, as I have exchanged my immortality for freedom, but I desperately need my book of incantations.\n\nFind the imp, Pusillin, and recover my book.\n\nSearch the Warpwood Quarter of Dire Maul for Pusillin.", progress = "I regret nothing, stranger. The Queen has long since passed. The works of the Shen'Dralar have been marred by the madness of Prince Tortheldrin. I seek only freedom... Escape...", completion = "You have found it! A curse upon that miserable imp. Alas, my material possessions are meager at best. You may choose from what I have to offer.", rewards = "You will be able to choose one of these rewards:\n\nSpry BootsSprinter's Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7461] = {title = "The Madness Within", objective = "You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated.\n\nEnter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum.\n\nReturn to the Shen'dralar Ancient in the courtyard should you complete this quest.", description = "Have you heard enough? Are you a <man/woman> of action?\n\nThis madness must come to an end. The age of the immortals has long since passed. Destroy the guardians surrounding the pylons to lower the force field. When this is done, destroy Immol'thar. With the Prince's power greatly reduced, attack and end him. Lay the spirits of this city to rest, adventurer.", progress = "Be wary, adventurer. The Prince is... persuasive.", completion = "We thank you, hero.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7462] = {title = "The Treasure of the Shen'dralar", objective = "Return to the Athenaeum and find the Treasure of the Shen'dralar. Claim your reward!In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will be able to choose one of these rewards:\n\n", description = "In the library, Athenaeum, you will find an ancient chest hidden beneath the stairway. Take from it that which you desire.You will be able to choose one of these rewards:\n\n", progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nBonecrusherBackwood HelmSedge Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7463] = {title = "Arcane Refreshment", objective = "Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence.", description = "A <race> mage! How wonderous. I have not seen one of your kind for... oh what is it going on now? 500 years!\n\nI have something that will quench your thirst, but first you must do a task for me.\n\n<Lydros snickers.>\n\nThere is an anomaly in Eldre'Thalas. A water elemental has taken residence in the east wing. His presence must be catalogued!\n\nVenture to the Warpwood Quarter and extract a portion of the elemental essence of the Hydrospawn. Return it to me and I shall teach you a useful cantrip.", progress = "Yes? Do I know you?", completion = "Wonderful! Who are you again? Oh it matters not. What was I supposed to give you? Hrm... well you are a &lt;class&gt;, perhaps you will find this useful.", rewards = "You will learn:\n\nConjure Water\n\nThe following spell will be cast on you:\n\nConjure Water\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7481] = {title = "Elven Legends", objective = "Search Dire Maul for Telmius Dreamseeker. Report back to Sage Korolusk at Camp Mojache with whatever information that you may find.", description = "Several years ago, a lone elven master named Telmius Dreamseeker fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", progress = "My associate, the night elf scholar, Runethorn, is recruiting her allies for this task.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7482] = {title = "Elven Legends", objective = "Search Dire Maul for Telmius Dreamseeker. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find.", description = "Several years ago, a lone elven master named Telmius Dreamseeker fled the devastation of his homeland with several ancient elven artifacts in tow.\n\nOur search for this lost master lead us from the ruins of Quel'Thalas, through the Burning Steppes, across the great expanses of the sea, to Feralas.\n\nWe suspect that the elf sought sanctuary in the halls of Eldre'Thalas (what is now known as Dire Maul).\n\nYou must find him, adventurer. Whether alive or dead, the knowledge he carried must be recovered!", progress = "My associate, the tauren sage, Korolusk, is recruiting his allies for this task.", completion = "A shame... a tragedy. The items are lost you say? No trace of him, eh?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7483] = {title = "Libram of Rapidity", objective = "Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity.", description = "Master Dreamseeker lost the Libram of Rapidity in the east wing. The Libram will allow for a minor haste cantrip to be placed upon your equipment. Parlor tricks, really...\n\nRegardless, if you are interested, you will need to present the Libram along with some basic reagents.\n\nHrm... I believe it also requires blood of heroes, a pristine black diamond, and large brilliant shards. I could be wrong!\n\n<Lydros shrugs.>", progress = "What is it? I have much cataloguing to do!", completion = "&lt;Lydros yawns.&gt;\n\nAs promised, the Arcanum of Rapidity. Don't spend it all in once place.\n\n&lt;Lydros snickers.&gt;", rewards = "You will receive:\n\nArcanum of Rapidity"}
MultiLanguageQuestData['en'][7484] = {title = "Libram of Focus", objective = "Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus.", description = "This libram almost aroused interest in one of the younger Lorekeeper's familiars. Poor thing, it was only a few weeks old.\n\nThose among you who are more magically inclined might find this item interesting.\n\nThe Libram of Focus was lost in this wing. I can only assume one of the Highborne spirits holds it in their possession.\n\nBring the Libram along with some large brilliant shards, skin of shadow, and a pristine black diamond and I shall conjure the Arcanum.", progress = "You again? What could you possibly want now?", completion = "Don't hurt yourself when applying the enchantment, &lt;race&gt;.", rewards = "You will receive:\n\nArcanum of Focus"}
MultiLanguageQuestData['en'][7485] = {title = "Libram of Protection", objective = "Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection.", description = "He wept like an infant at the loss of this libram. Mind you, I myself have wept over texts - there is no greater loss than that of knowledge and history - but to cry over this nearly useless jumbling of incantations? Preposterous! It left me to believe that the Prince was doing him a favor in flaying the flesh from his bones.\n\nBring the Libram along with a pristine black diamond, large brilliant shards, and a frayed abomination stitching and I shall recreate the Arcanum.\n\nOh, and check the north wing.", progress = "My patience prevents your suffering.", completion = "Yes, yes... Calm yourself. As promised, here is your Arcanum.", rewards = "You will receive:\n\nArcanum of Protection"}
MultiLanguageQuestData['en'][7486] = {title = "A Hero's Reward", objective = "Claim your reward from Hydraxis' Coffer.", description = "<name>, your services to the Warlords surpassed all we could expect from the denizens of this world.\n\nWe do not understand your people's notions of gratitude, or rewarding good works, but in this case... perhaps a reward is warranted.\n\nUnder the surf at the southern base of this island, you will find a coffer.  In it you will find your... reward.\n\nGo, <name>.  Claim your reward.", progress = nil, completion = "Hydraxis' voice descends from the waters' surface...\n\n\"Choose that which best suits you, &lt;name&gt;.  May it protect you against the foes of the Waterlords.\"", rewards = "You will be able to choose one of these rewards:\n\nOcean's BreezeTidal Loop\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7487] = {title = "Attunement to the Core", objective = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", description = "Rifts stir, tear, and collapse all around us, <race>. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.The following spell will be cast on you:\n\n", progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nAttunement to the Core\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][7488] = {title = "Lethtendris's Web", objective = "Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", description = "The mage Lethtendris, a vicious blood elf whose brutality is matched only by her twisted addiction to magic, has fled into Dire Maul.  She has created a device, a web to ensnare the magical energies of that place and we fear that, if left unchecked, she will cause irreparable damage to our world!\n\nStop her, <name>.  Find her and retrieve her web.  She is likely near the satyrs in Warpwood Quarter of Dire Maul.  Bring the web to me so that its power may be released safely back into the wilds...", progress = "Do you have the web, <name>?  Its concentrated magical energy must be dissipated!", completion = "You retrieved the web!  Well done, &lt;name&gt;!  Lethtendris, like many elves of her ilk, are blind to the dangers the abuse of magic can cause to our world.  They believe they are masters of magic; they do not realize that they are slaves to their own addiction.  Her death saddens me, but it was necessary.\n\nThank you, &lt;name&gt;.  I will have the energies within the web released safely over a wide area, and then I'll destroy it to prevent future magical exploits.", rewards = "You will receive:\n\nLorespinner"}
MultiLanguageQuestData['en'][7489] = {title = "Lethtendris's Web", objective = "Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas.", description = "The blood elf Lethtendris has overstepped her bounds.  So eager was she to gather magical power that she defied her brethren and created a device of insidious design, a web meant to siphon the tainted magical energies of Dire Maul.  Even now she gathers those energies and plans to release them against her enemies.\n\nLethtendris must be stopped.  Find her within the Warpwood Quarter of Dire Maul, defeat her and bring her web to me so that it might be returned to more clear-headed blood elves for study.", progress = "<name>, do you have Lethtendris's Web?", completion = "You have done well, &lt;name&gt;.  This web holds within it vast stores of the magic of Dire Maul, and I fear what damage may be unleashed if those energies were harnessed by one so irresponsible as Lethtendris.  I am saddened by her death, but I know that she could never part with her web while alive.\n\nThank you, &lt;name&gt;.  I will send the web to students of magic more responsible than Lethtendris.  They will be the new wardens of its power.", rewards = "You will receive:\n\nLorespinner"}
MultiLanguageQuestData['en'][7490] = {title = "Victory for the Horde", objective = "Take the Head of Onyxia to Thrall in Orgrimmar.", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to your Warchief.", progress = "<Thrall's stoic demeanor changes for a split second when he sees the enormous head of Onyxia. The mighty Doomhammer was nearly unsheathed.>", completion = "This is a great victory for the Horde, &lt;name&gt;. So many times you have honored your Warchief. It is time for the Warchief to honor you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7491] = {title = "For All To See", objective = "Seek out Overlord Runthak in the Valley of Strength.", description = "Overlord Runthak awaits your arrival in the Valley of Strength.\n\n<Thrall salutes you.>\n\nDo not keep your public waiting, hero.", progress = nil, completion = "Choose your reward and let the celebration of your glorious victory begin.", rewards = "You will be able to choose one of these rewards:\n\nOnyxia Blood TalismanDragonslayer's SignetOnyxia Tooth Pendant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7492] = {title = "Camp Mojache", objective = "Speak with Talo Thornhoof at Camp Mojache in Feralas.", description = "Talo Thornhoof, a Tauren elder in Feralas, sends a request for aid.  He offered few details, but he did say that he needs agents for a matter both delicate... and dire.\n\nServe the Horde, <name>.  Go to Camp Mojache in Feralas and speak with Talo.", progress = nil, completion = "Ah, it is good to see a &lt;class&gt; heed my summons.  I have need of your services, &lt;name&gt;, and fear they will take you down a dangerous path...\n\nA path into Dire Maul.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7493] = {title = "The Journey Has Just Begun", objective = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nPattern: Onyxia Scale Cloak"}
MultiLanguageQuestData['en'][7494] = {title = "Feathermoon Stronghold", objective = "Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas.", description = "<name>!  Your aid is needed in Feralas!\n\nAn outlaw mage, Lethtendris, has fled to the ancient elven ruins Eldre'thalas, now called Dire Maul.  It is believed she has an item of dangerous magical energy which must be recovered.\n\nLatronicus Moonspear requests agents to enter Dire Maul and retrieve the item from Lethtendris.\n\nServe the Alliance!  Seek out Latronicus at the Feathermoon Stronghold in Feralas.", progress = nil, completion = "Hail, &lt;name&gt;.  I am pleased to see you, but regret that our meeting is not under more pleasant conditions.\n\nListen close, for I have a vital task for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7495] = {title = "Victory for the Alliance", objective = "Take the Head of Onyxia to Highlord Bolvar Fordragon in Stormwind.", description = "You have accomplished the impossible. The brood mother of the Black Dragonflight lies dead at your feet. Take her head and present it to the Highlord.", progress = "By Uther's beard!", completion = "For so many years I was held under her captivating gaze. Finally, to see justice meted and the honor of Stormwind restored! Today, we celebrate this glorious victory!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7496] = {title = "Celebrating Good Times", objective = "Seek out Major Mattingly in the Valley of Heroes.", description = "Seek out Major Mattingly in the Valley of Heroes, <name>. He will be expecting you...", progress = nil, completion = "Few are graced with such ceremony, &lt;name&gt;. Please, choose your reward so that we may begin the celebration.", rewards = "You will be able to choose one of these rewards:\n\nOnyxia Blood TalismanDragonslayer's SignetOnyxia Tooth Pendant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7497] = {title = "The Journey Has Just Begun", objective = "A dragon slayer and a seasoned leatherworker? You do not cease to astonish, hero. I am humbled.\n\nPlease accept what I am about to teach you. This knowledge will prove to be invaluable if you are to destroy what remains of the Black Dragonflight.\n\nCreate the cloak from the scales of the brood mother. It will protect you and your allies against the incendiary breath of the Lord of Blackrock... Nefarian.", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nPattern: Onyxia Scale Cloak"}
MultiLanguageQuestData['en'][7498] = {title = "Garona: A Study on Stealth and Treachery", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7499] = {title = "Codex of Defense", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7500] = {title = "The Arcanist's Cookbook", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7501] = {title = "The Light and How To Swing It", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7502] = {title = "Harnessing Shadows", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7503] = {title = "The Greatest Race of Hunters", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7504] = {title = "Holy Bologna: What the Light Won't Tell You", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7505] = {title = "Frost Shock and You", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7506] = {title = "The Emerald Dream...", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Excellent work, &lt;race&gt;. Should you find any more tomes, do not hesitate to return them to us.\n\nAs time passes, we tend to change around and even add new rewards for the return of missing tomes.", rewards = "You will receive:\n\nRoyal Seal of Eldre'Thalas"}
MultiLanguageQuestData['en'][7507] = {title = "Nostro's Compendium", objective = "Return Nostro's Compendium of Dragon Slaying to the Athenaeum.", description = "You have uncovered something of great importance. This book is unlike any that you have seen.\n\nIt would appear as if someone or something has managed to shatter the seal of Athenaeum. The text within is garbled and barely legible.", progress = "Ah, one of our greatest compilations. This one has been missing for ages.", completion = "You could have gotten quite a lot of gold for this book on the black market, &lt;name&gt;. Especially since the protective seal has been broken, leaving the secrets of dragon slaying viewable to any with the requisite intellect to consume the knowledge held within the sacred pages.\n\nPerhaps a grand reward is in order... Well, a reward that will require enormous effort to obtain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7508] = {title = "The Forging of Quel'Serrar", objective = "Give the Dull and Flat Elven Blade to Lorekeeper Lydros.", description = "If you wish to take on this task, present Lydros with the dull blade.", progress = "Excellent, let us begin...", completion = "If you manage to enter the lair of the dragon, heat the blade under her fiery breath, and ultimately temper it in her blood, I shall bind the blade for your use.", rewards = nil}
MultiLanguageQuestData['en'][7509] = {title = "The Forging of Quel'Serrar", objective = "You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.\n\nThe last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.\n\nDo this and Quel'Serrar will be yours.", description = "Take the unfired ancient blade to the lair of Onyxia and engage her in battle.\n\nSome trickery must be utilized for the heating of the blade. While in combat, she will surely try to incinerate you with her fiery breath. You must plant the unfired ancient blade nearby and hope that the fiery breath heats the blade. If you live beyond this, pick up the now heated ancient blade and finish off the dragon.\n\nPlunge the heated ancient blade into her smoldering corpse to fashion the treated ancient blade.", progress = "Perhaps one day, another will wield the prismatic blade.", completion = "&lt;Lydros murmurs something unintelligible.&gt;\n\nAs promised, &lt;class&gt;, the blade of Quel'Serrar.", rewards = "You will receive:\n\nQuel'Serrar"}
MultiLanguageQuestData['en'][7541] = {title = "Service to the Horde", objective = "It will take time for our scholars to study the pendant you brought us.  But for your service to the Horde I would like to offer you a small token.\n\nThank you, <name>.  Your acts bring honor to you, and to us.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nBand of AllegianceLonetree's Circle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7562] = {title = "Mor'zul Bloodbringer", objective = "Speak with Mor'zul Bloodbringer in the Burning Steppes.", description = "<name>, your delvings into the dark arts are deep.  Your mastery over otherworldly denizens has grown so strong... perhaps you are ready to bind to you one of the infamous dreadsteeds.\n\nThe ritual to summon the beast from its home requires great power and resources, but if you desire to dominate that epic mount, then speak with Mor'zul Bloodbringer.  He is camped near the Altar of Storms in the Burning Steppes.\n\nGo, <name>.  This quest will be perilous, but a Warlock of your stature does not shy from danger!", progress = nil, completion = "Greetings, &lt;name&gt;, and welcome.  Are you here to study near the Altar of Storms as I am, perhaps to harness its energy for some hidden purpose...\n\nOr... are you here to speak with me?  Yes, I believe you are.\n\nYou want to master a dreadsteed?  Such is no easy task.  It will cost you no small amounts of blood, sweat... and of course gold.  But a dreadsteed of Xoroth is a prize well worth winning so if interested, listen on...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7563] = {title = "Rage of Blood", objective = "Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes.", description = "The dreadsteeds dwell on another world, on the fiery Plains of Xoroth, and to bind one of those famed beasts you must invoke powerful glyphs.  I can scribe the glyphs on a parchment for you, but first I will need a special ink.\n\nIn distant Winterspring there dwells a race of owl beasts.  Once pure creatures, they were turned mad by the demonic emanations of the Darkwhisper Gorge and now roam the snows in a frenzy.\n\nTheir blood is what I need to ink your parchment.  Bring it to me.", progress = "Have you seen the raging owl beasts, <name>?  The magic of those creatures is strong, and it concentrates in the blood that flows through their torturted forms.", completion = "Ah, very good.  I will have this blood distilled into an ink and use it for the parchment I promised you.  And perhaps I will save just a little for myself, as I hear its taste is quite euphoric...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7564] = {title = "Wildeyes", objective = "Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes.", description = "My servant, Gorzeeki, is an alchemist of some skill.  He can prepare the ink I will need for your parchment.  I gathered together the blood you acquired; take it to Gorzeeki so that he can begin his work.", progress = "You have something for me?  It's not a big, juicy spider, is it?  Or maybe a roach?  I hope it's still alive... I so love chewing on them when they're still alive...", completion = "Oh, it's blood.  It must be from master Mor'zul then.  He is so enamored with the stuff, and loves to see it spilled.  I, however, prefer it coursing through the veins of a small rodent.  It stays warm that way... until you want it.\n\nThis is powerful blood.  Mor'zul must be making another parchment to summon a dreadsteed!  How exciting!\n\nIf that's true, and you're going to perform the ritual, then... you're going to need a lot more than blood, my friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7581] = {title = "The Prison's Bindings", objective = "Travel to Dire Maul in Feralas and recover 15 Satyr Blood from the Wildspawn Satyr that inhabit the Warpwood Quarter. Return to Daio in the Tainted Scar when this is done.", description = "You must retrieve bindings for the prison of the Doomguard from lesser demons.\n\nThe blood of the Wildspawn satyr that occupy Dire Maul should do nicely. The coagulated blood will bond the Hederine shards and power the crystal prison.", progress = "Only the blood of Wildspawn satyr will suffice.", completion = "Ah, a most excellent recovery. The blood will suppress the Doomguard's magical defenses.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7582] = {title = "The Prison's Casing", objective = "Travel to Darkwhisper Gorge in Winterspring and recover 5 Tears of the Hederine from the Hederine demons that occupy the gorge. Return to Daio in the Tainted Scar when you have completed this task.", description = "The Hederine demons that occupy the foothills of Mount Hyjal secrete powerful fel poisons, which if left to mature, harden into a dense anti-magic crystal. These crystals have come to be known as Tears of the Hederine.\n\nNot even the immense power of a Doomguard could break the walls of a prison constructed from this material.\n\nTravel to Darkwhisper Gorge in Winterspring and recover the Tears.", progress = "The Hederine will not give up their precious gems without a fight, <name>.", completion = "I merely need to combine the blood of the Wildspawn with these crystals and the prison shall be ready for use.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7583] = {title = "Suppression", objective = "Venture forth into the Tainted Scar and locate a Doomguard Commander.\n\nUse the Glowing Crystal Prison on the Doomguard Commander. Be prepared for a ferocious onslaught of attacks, as the demon attempts to escape capture.\n\nShould you succeed, return the Imprisoned Doomguard to Daio in the Tainted Scar.", description = "The prison is ready. Now for the most difficult portion of this task.\n\nYou must find and capture a Doomguard Commander within the Tainted Scar using this crystal prison.\n\nBe warned! A Doomguard is a cunning and lethal adversary and will seek to destroy you as you begin the ritual of imprisonment. It will flail wildly in its attempts to escape imprisonment.\n\nIt will focus on nothing but you, <name>. Because of this, I must recommend that you take companions capable of keeping you alive!", progress = "Hrm? Well?", completion = "You have done as I have asked. You are ready to be given the knowledge to conjure and control the beast.", rewards = "You will learn:\n\nRitual of Doom\n\nThe following spell will be cast on you:\n\nRitual of Doom\n\nYou will also receive:\n\nTome of Sacrifice"}
MultiLanguageQuestData['en'][7601] = {title = "What Niby Commands", objective = "Speak with Impsy in Felwood.", description = "If I am to teach you the secrets of summoning an infernal servant, you must destroy Kroshius and bring me the infernal core from his burning remains. This, however, is not as easy as it sounds. Kroshius has all but burned out completely. You must reignite his corpse and raise him from the rubble. To do this, however, you must gather some components from other demonic entities.\n\nMy imp, Impsy, shall set you on your way.", progress = nil, completion = "Oh boy, here we go again.", rewards = nil}
MultiLanguageQuestData['en'][7602] = {title = "Flawless Fel Essence", objective = "Impsy in Felwood has asked that you bring him three Flawless Fel Essences originating from three distinct locations.\n\nThe Legashi Satyrs of Azshara hold the Flawless Fel Essence of their region. The Jaedenar Legionnaires of Jaedenar hold the Flawless Fel Essence of their region. The Felguard Sentries of the Blasted Lands hold the Flawless Fel Essence of their region.\n\nRecover the Flawless Fel Essences and return  to Impsy in Felwood.", description = "If you're going to reanimate Kroshius, you're going to need Fel fire. I can make Fel fire but it's going to require some components.\n\nYou need to bring me flawless Fel essences from three distinct regions of the world.\n\nThe Legashi Satyrs of Azshara will have the first essence type; the Jaedenar legionnaires of Jaedenar the second type and the felguard sentries of the Blasted Lands the third.\n\nBring me back one of each essence type and I will create the Fel fire, allowing you to reanimate Kroshius.", progress = "Don't tell anyone this but Niby is daft.", completion = "Give me a minute and I'll combine the essences into Fel fire.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7603] = {title = "Kroshius' Infernal Core", objective = "Search Shatter Scar Vale in Felwood for the remains of Kroshius. When you locate the remains, use the Fel Fire near them and await Kroshius' return. When the infernal has awoken, slay him and take from his corpse Kroshius' Infernal Core.\n\nReturn Kroshius' Infernal Core to Niby the Almighty in Felwood.", description = "Kroshius lays in a heap to the northeast, in the Shatter Scar Vale. Take this Fel fire and use it on his remains. The fire should reanimate the fallen infernal.\n\nAt this point, I fully expect him to kill you and your minion.\n\nIf by some miracle you happen to kill Kroshius, take his infernal core and return it to Niby.", progress = "Did you get lost?", completion = "A deal is a deal! Quickly, take this and write this down. I don't have time! My greatest conjuration is upon us!", rewards = "You will learn:\n\nInferno\n\nThe following spell will be cast on you:\n\nInferno\n\nYou will also receive:\n\nShard of the Green Flame"}
MultiLanguageQuestData['en'][7604] = {title = "A Binding Contract", objective = "Turn the Thorium Brotherhood Contract in to Lokhtos Darkbargainer if you would like to receive the plans for Sulfuron.", description = "The undersigned hereby declares that the Sulfuron ingot they are delivering to the Thorium Brotherhood (TB Ltd.) is genuine and not a facsimile thereof. The undersigned also acknowledges that any harm that should come to <him/her> as a result of attempting to build, forge, find, create, sell, or eat Sulfuras, is not the responsibility or fault of TB Ltd.\n\nBy signing this contract, you are agreeing to all terms listed herein.\n\n_________________\n\nSignature", progress = "Do we have a deal?", completion = "It has been a pleasure doing business with you, &lt;name&gt;!\n\nOn behalf of TB Ltd., I wish you luck in your search for Sulfuras!", rewards = "You will receive:\n\nPlans: Sulfuron Hammer"}
MultiLanguageQuestData['en'][7621] = {title = "A Warning", objective = "<class>, you are about to undergo a rigorous series of events which shall test all of your abilities.\n\nI suggest that you listen to the story that I have to tell.\n\nBe warned, you must complete this task alone. It is recommended that your allies remain at a distance. Interference by outside agents will result in a most severe punishment.\n\nDestiny has led you and you alone here. Battle with honor. Harness the Light.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][7622] = {title = "The Balance of Light and Shadow", objective = "Save 50 Peasants before 15 are slain. Speak with Eris Havenfire should you accomplish this task.\n\nYou may view the Death Post to view how many Peasants have been slain.", description = "You must do what I could not: Save the peasants that were cut down while fleeing from Stratholme.\n\nThey will walk towards the light, you must ensure their survival. Should too many fall, our cursed existence shall continue - you will have failed.\n\nEvery ability, prayer, and spell that you have learned will be tested. May the Light protect you, <name>.", progress = nil, completion = "Your tenacity and courage are astounding, &lt;class&gt;. You have earned the right to hold the Splinter of Nordrassil. Only one task remains: The Eye of Shadow must be recovered. Scour the world.", rewards = "You will receive:\n\nSplinter of Nordrassil"}
MultiLanguageQuestData['en'][7623] = {title = "Lord Banehollow", objective = "Purchase Shadowy Potions from Gorzeeki in the Burning Steppes.\n\nUse the potions to travel through Jaedenar, and speak with Lord Banehollow.", description = "Mor'zul says that you want to open a portal to Xoroth.  To do that, you'll need Xorothian stardust.  That's not easy to find on Azeroth!\n\nThere is one being who might have some: Lord Banehollow in Jaedenar, the seat of the Shadow Council!  Speak with him and he might part with the stardust.\n\nBut if you're going to Jaedenar, then you'll need to cloak yourself in the Shadow Council's own flavor of evil.  That will require some of my shadowy potions, and that will cost you...", progress = nil, completion = "My patience spans the millenia, &lt;class&gt;.  But do not think that allows you more than an instant of my time...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7624] = {title = "Ulathek the Traitor", objective = "Confront Ulathek, then bring The Traitor's Heart to Lord Banehollow in Jaedenar.", description = "You wish to enter my good graces?  Then kill for me.\n\nMy servant, Ulathek, is pathetic how he grovels before me, all the while plotting with Lord Hel'nurath on Xoroth.  Hel'nurath plans to usurp my power here, and Ulathek is his spy...\n\nProve that you serve me and not my rivals.  Confront Ulathek in his quarters, in the Shadow Hold to the west.  Tell him that I know his secret and watch as fear grips him.  Then, bring me the traitor's heart!", progress = "I can already taste the heart of Ulathek on my lips.  So sweet is the flesh of a traitor...", completion = "Ah, how splendid!  After rotting a week, this heart will prove a succulent treat!  Perhaps I will send for Ulathek's head and place it before me as I eat...\n\nYou have done me a service, &lt;class&gt;, and so my patience for you has grown.  Marginally.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7625] = {title = "Xorothian Stardust", objective = "Purchase Xorothian Stardust from Ur'dan. Bring it to Gorzeeki Wildeyes in the Burning Steppes.", description = "So you come to me seeking Xorothian stardust?  You wish to open a portal to Xoroth, the domain of Hel'nurath my rival?  Perhaps you plan to steal from him one of his precious dreadsteeds?\n\nVery well.  My servant Ur'dan has a supply of Xorothian stardust.  You may obtain it from him... if you can pay the price.", progress = "Have you been to Jaedenar, <name>?  Did you get the stardust from Lord Banehollow?", completion = "There it is!  I can hardly believe you got it!  You must have struck a big deal with that Dreadlord or else paid a large sum, or both!\n\nMor'zul will have his ink very soon and then he can finally make the glyph parchment, so you can open a portal to Xoroth and pull through it one of the famed dreadsteeds!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7626] = {title = "Bell of Dethmoora", objective = "Bring 2 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes.", description = "A Bell of Dethmoora, named after the late warlock Dethmoora Darkeyes, is one of the three tools needed to create a Circle of Greater Summoning.  When properly atuned with the Wheel and the Candle, these items conduct vast stores of arcane power.\n\nMy servant Gorzeeki can construct such a bell, but to do so he will need a large supply of elixirs of shadow power.  Procure the elixirs from an alchemist and bring them to Gorzeeki.", progress = "You have those elixirs, <name>?  Mor'zul told me you need a Bell of Dethmoora, and making one of those takes a lot of shadow power!", completion = "Very good!  I hope these elixirs weren't too hard to get.  Sometimes alchemists can be so miserly with their creations...\n\nI'll make the bell and keep it until you're ready for your ritual.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7627] = {title = "Wheel of the Black March", objective = "Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes.", description = "A Wheel of the Black March contains and directs the violent energies required for the Circle of Greater Summoning.  For Gozeeki to construct a wheel, he will need both large brilliant shards from an enchanter, and dark iron ore from a master miner.\n\nAcquire these and bring them to my servant.", progress = "The Wheel of the Black March isn't easy to make, and takes a lot of materials.  Have you gathered them yet?", completion = "There they are!  I hear that dark iron ore is only found in the depths of Blackrock, and I'm sure these shards weren't easy to find either.  I am often awed at the dedication you warlocks have.  If you instead bent all that energy into the art of bug catching, oh... such a feast you would enjoy!\n\nSorry, a small digression.  I'll create the wheel and keep it for you until you're ready for your ritual.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7628] = {title = "Doomsday Candle", objective = "Bring 3 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes.", description = "A Doomsday Candle stores fire and directs it at those who would disrupt your ritual.  When creating your Circle of Greater Summoning, if your candle is lit then any wayward demons will be burned by its flames!\n\nContaining that fire is not easy, and requires the essence within the scales of a black dragon.  Acquire those scales from a skinner and bring them to Gorzeeki Wildeyes.", progress = "Did you bring the dragonscales, <name>?  I don't want to start on the candle until I have them... or I might blow up the whole camp!", completion = "Ah, very good.  I'll need these to contain the fires of the candle.  Now that I have the scales, I'll make the candle and hold onto it until you're ready to begin your ritual for the Circle of Greater Summoning.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7629] = {title = "Imp Delivery", objective = "Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes.", description = "There is one more process required for Mor'zul's parchment; I need paper infused with Xorothian stardust.  And... I'm afraid I can't do that here.  I don't have the equipment!\n\nThere is an alchemy lab, however, with everything needed.  It's in the Scholomance, on the isle of Caer Darrow in the Plaguelands.\n\nI can't make the trip, but here - take this jar.  There's an imp inside who is quite clever.  Let him out at the alchemy lab and he'll infuse the parchment.", progress = "Have you been to the Scholomance, <name>?  Has the imp yet infused the parchment with the stardust?", completion = "Ah, good.  J'eevee created the parchment.  How was the Scholomance?  Charming, don't you think?  And the bugs there... I hear they're delicious!\n\nWell done, &lt;name&gt;, and thank you for returning my jar.  I've had it for a long time... and it's not for sale!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7630] = {title = "Arcanite", objective = "Bring 1 Arcanite Bar to Gorzeeki in the Burning Steppes.", description = "Now that the Bell, Wheel and Candle are made, I should make a black lodestone.  During your ritual, you'll need that lodestone to maintain the other ritual objects if they should fail.\n\nTo make the lodestone, I require arcanite.  Do you have any?  If not, then... you'll have to get the arcanite from an alchemist.\n\nReturn to me when you have the arcanite, and then I'll make the black lodestone.", progress = "Do you have the arcanite, <name>?  Once I have it I can make you the black lodestone.", completion = "You got it!  Nicely done!  Now I can create the lodestone.  When you're finally ready for your ritual to create the Circle of Greater Summoning, you'll want  a lodestone to make sure the ritual doesn't fizzle out!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7631] = {title = "Dreadsteed of Xoroth", objective = "Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you.\n\nProvided item: \n", description = "All the preparations are made.  Now, you must perform the ritual to create a Circle of Greater Summoning, then use the parchment infused with Xorothian stardust... to open a portal to Xoroth.\n\nI have written the instructions for the ritual onto a scroll.  Study it closely, for you must perform each step exactly if you wish to succeed.\n\nFortune to you, <name>.  And may the souls of your enemies swiftly find their way into your shard pouch.", progress = nil, completion = "The Xorothian Dreadsteed's spirit is beaten.  Although rage pulses through its ghostly flanks, you know that the beast's soul is yours...\n\nIt whispers dark magic into your mind and instills within you the knowledge to summon a dreadsteed.", rewards = "You will learn:\n\nSummon Dreadsteed\n\nThe following spell will be cast on you:\n\nTeach Summon Dreadsteed\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7632] = {title = "The Ancient Leaf", objective = "Find the owner of the Ancient Petrified Leaf. Good luck, <name>; It's a big world.", description = "The epidermis of the leaf glows a bright green. The surface is extremely rugose, exposing several veins and wrinkles.\n\nIf you had to take a guess, you would say this leaf came from something ancient and powerful.\n\nMaybe you should find the original owner of this leaf?", progress = "<Vartrus groans.>", completion = "Of course I recognize my own leaves. Look at that! It's in perfect condition.\n\nHow good of you to return it, &lt;class&gt;.\n\nPerhaps you could be of service to us and we to you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7633] = {title = "An Introduction", objective = "Your diligence and integrity has been noted, <class>.\n\nWe are Ancients: Protectors of this once great forest. Our physical forms were destroyed 10,000 years ago when Archimonde and the Burning Legion marched upon Hyjal. Our spirits, however, remain intact.\n\nThere are tasks that we can offer. Tasks that if completed will open up the secrets of the Ancients to you.\n\nKnow this, should you complete these tasks, merely return to this rock and we shall answer the calling.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][7634] = {title = "Ancient Sinew Wrapped Lamina", objective = "Hastat the Ancient has asked that you bring him a Mature Blue Dragon Sinew. Should you find this sinew, return it to Hastat in Felwood.", description = "Greetings, <class>. I am Hastat, Ancient of Lore. I hold knowledge lost eons ago.\n\nWith the proper binding, one of my leaves can serve as a quiver the likes of which has not been seen in 10,000 years. A quiver that when accompanied by a bow of Ancients, could grant untold powers.\n\nReturn here with sinew from an adult blue dragon and this quiver shall be yours.", progress = "Welcome back, young <class>.", completion = "May my leaves provide your arrows protection from harm. May your arrows strike true. May the enemies of our world be smitten.", rewards = "You will receive:\n\nAncient Sinew Wrapped Lamina"}
MultiLanguageQuestData['en'][7635] = {title = "A Proper String", objective = "Stoma the Ancient has asked that you bring him a Mature Black Dragon Sinew. Should you find this sinew, return it to Stoma in Felwood.", description = "Vartrus may offer you the stave to create a bow of Ancients but only I can enchant the string required to complete the bow.\n\nIt is a simple task, puny one. Slay a mature black dragon and remove the sinew from its bones. Return that sinew to me and I shall enchant the material into an almost indestructible bow string.", progress = "I am certain that you will have little difficulty in finding and slaying a black dragon, <name>. Do not waste my time with idle chatter.", completion = "A most foul dragon this one was. The sinew reeks of evil.\n\nGive me a moment to cleanse the filth from this flesh and apply the proper enchantments.", rewards = "You will receive:\n\nEnchanted Black Dragon Sinew"}
MultiLanguageQuestData['en'][7636] = {title = "Stave of the Ancients", objective = "You must find and destroy these four demonic corrupters:\n\nSimone the Seductress.\n\nKlinfran the Crazed.\n\nSolenor the Slayer.\n\nArtorius the Doombringer.\n\nDestroy these creatures and return to Vartrus the Ancient in Felwood with their heads.\n\nRefer to the Petrified Bark in your inventory for clues as to their whereabouts.\n\nYou MUST complete this task by yourself.", description = "Agents of the Burning Legion are still active in our world, <class>. These agents corrupt all that they touch. Nature wilts and weeps in their presence.\n\nYou must track down these demonic corrupters and destroy them, <name>. Be warned, you must engage them by yourself or they will flee. As long as you are alone, they will try and destroy you. You must strike at them, turning their arrogance into misery.\n\nI grant you a piece of my bark, the inscriptions shall lead you to your targets. Retrieve their heads.", progress = "Do not be fooled by their disguises!", completion = "You have served us well, &lt;name&gt;! Take this stave and combine it with the bow string that Stoma is able to create. Together, they form a most formidable weapon.", rewards = "You will receive:\n\nAncient Rune Etched Stave"}
MultiLanguageQuestData['en'][7637] = {title = "Emphasis on Sacrifice", objective = "Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it.", description = "In order to prepare yourself for this task, you must first show due sacrifice and judgment... with an emphasis on sacrifice.\n\nYou must acquire High Priest Rohan's exorcism censer for your task.  Even though its use will be for good and just reasons, due compensation must be given for it.\n\nProceed to Ironforge and speak with the High Priest.  By bringing ample coin with you to help offset the loss of his censer, it will show your due sacrifice.\n\nGo now <name>, time is of the essence.", progress = "Greetings, noble <class>!  I have prepared my trusted censer with the freshest of incense and blessed it thrice for your use.  Your donation will help us in Ironforge not only to create a new censer, but also to bolster sagging reserves of food for our needy.", completion = "Blessings onto you, friend &lt;class&gt;!  Your donation goes far beyond what was needed.  Your sacrifice will not only help us recover what we have lost, but also help us to help those most in need here in Ironforge.\n\nNow, let me make sure I've suitably prepared this censer for your future needs...", rewards = nil}
MultiLanguageQuestData['en'][7638] = {title = "Lord Grayson Shadowbreaker", objective = "Speak with Lord Grayson Shadowbreaker in Stormwind's Cathedral District.", description = "The time has come, <name>, for you to learn about what it will take for you to acquire something you have no doubt waited on for some time... your charger.\n\nSpeak with Lord Grayson Shadowbreaker here in Stormwind's Cathedral District.  It is he who will guide you not only though the legerdemain of a Paladin's most trusted mount, but the tasks before you to acquire one of your own.\n\nI wish you the best in this trial.  For the Light, noble <brother/sister>!", progress = nil, completion = "I am glad to see you &lt;name&gt;.  I know that you have awaited word as to how to acquire your charger, and now that time has come.\n\nYou will be surely tested in many different ways, but most importantly in your willingness to rise above numerous obstacles thrust before you.  These are not done as a learning exercise - your stature is beyond simple educational tests.  You must save your future companion from the clutches of the evil you have spent your life fighting.\n\nTake heed, your time has come!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7639] = {title = "To Show Due Judgment", objective = "Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", description = "With my blessings, take the censer.  I myself have used it in several exorcisms, and it should serve you well for the arduous tasks that lie ahead.\n\nReturn now to Lord Grayson Shadowbreaker in Stormwind, <name>.  Your quest continues with him.", progress = "Welcome back, <name>.  Have you acquired the exorcism censer?", completion = "Yes, this will do.  You will be called upon more than once during this process to make acts of sacrifice; I am glad to see that you are willing to do just that.  Sacrifice is a key component in what it takes to uphold the duties of being a &lt;class&gt;... but I don't have to lecture you on that.\n\nNow &lt;name&gt;, you will need to show due judgment in your actions.  To that end, this censer will act as your vessel to dispense such judgment on tortured spirits of lands lost to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7640] = {title = "Exorcising Terrordale", objective = "Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", description = "I have added a pinch of dirt from the tainted ground of Terrordale in the Eastern Plaguelands to the censer.  You will now use this censer to find areas there that show signs of spiritual turmoil and disturbance.  Look for green auras that permeate the ground as the physical world buckles under the torment of the spirit realm and use the censer to drive out the evil spirits.\n\nWhen you have passed sufficient judgment on the spirits there, you will be ready to proceed.", progress = "It is good to see you again <name>.  Is your work done in Terrordale?", completion = "Well done, &lt;name&gt;.  To render the judgment of the Light on those that dwell in darkness is a task we must approach with vim and zeal; you have done just that with your sacrifice in Ironforge and your judgments of the spirits in Terrordale.\n\nYour next steps will call on both sacrifice and judgment again as you now strive to reclaim the spirit of a fallen charger who now serves a Death Knight known as Darkreaver.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7641] = {title = "The Work of Grimand Elmore", objective = "Speak with Grimand Elmore in Stormwind's Dwarven District.", description = "A paladin's charger is nothing more than a pack animal without proper barding for it.  The barding used by your charger not only needs to be of the finest materials possible, but because of the circumstances involved it must also be sufficiently attuned to the spirit realm.\n\nFirst things first, <name> - let's get your barding made.  In Stormwind's Dwarven District is one of the finest craftsmen living today, Grimand Elmore.  His work will not be cheap, but his quality is what we seek.  Speak with him.", progress = nil, completion = "Hello there lad - Lord Shadowbreaker sent me word ahead of time that you'd be coming around this way to see me.  I'm willing to make the barding you need, but it won't be either cheap or easy; let's get that out in the open first and foremost.\n\nI will say this much, and Grayson will back me up when I make this claim... you'll not find better barding made anywhere in all of Azeroth than right here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7642] = {title = "Collection of Goods", objective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind.", description = "You'll need four things for the barding - runecloth for the lining, arcanite bars for the plating, Arthas' Tears for the spiritual attunement, and Stratholme holy water for the spiritual imbuement.  Actually, you need five things... gold for my fee.  That fee includes all labor as well as a handcrafted saddle and stirrups.\n\nOnce you've got all that, I'll be able to finish your barding.  Until then, there are some things I can get started on for you while you assemble your collection of goods.", progress = "Ah, <name>.  I won't be able to finish your barding without the things I mentioned.  Have you gotten everything together?", completion = "This... well, this is exactly what I needed.  You're quite the resourceful &lt;class&gt;, aren't you?\n\nAll right then, let's get this barding finished up for you!", rewards = nil}
MultiLanguageQuestData['en'][7643] = {title = "Ancient Equine Spirit", objective = "Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food.\n\nTravel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it.", description = "Your barding needs a special form of blessing, one from an appropriate spirit.  In Dire Maul is such a spirit, the Ancient Equine Spirit.  It is currently held by a corrupt treant, Tendris Warpwood.  Pass judgment upon this foul beast, <name>.\n\nKnow this - freedom alone is not enough.  You must soothe the spirit before receiving its blessing.  For that, special horse feed is needed.  Travel to Southshore first and speak with Merideth Carlson on this... and prepare for more sacrifice.", progress = "The Ancient Equine Spirit looks at you expectantly, as though it wants something from you.", completion = "The Ancient Equine Spirit accepts the offering of the Manna-Enriched Horse Feed, nuzzling the container as it helps itself to the special oats and grains.  After it has eaten a little, it looks at the barding you possess and positions itself as though it wants you to place it upon its back...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7644] = {title = "Blessed Arcanite Barding", objective = "Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", description = "As the barding rests on the back of the Ancient Equine Spirit, it glows ever so slightly.  The air is thick with power for a brief moment, and then the barding disappears from the back of the horse and is now secure in your backpack.\n\nIt would seem that the barding has been blessed.  As per Lord Shadowbreaker's instructions, you should now return with it to him in Stormwind.", progress = "<name>, you're back!  Were you able to successfully deal with Merideth Carlson and Tendris Warpwood?  Honestly, I'm not sure which one is a greater threat at times...", completion = "You've come far, my friend.  Your barding is now suitably prepared for the last task at hand.\n\nYou will be using this barding to harness your charger once the task of redemption is complete.  Before that, however, you will have a monumental struggle to overcome.  Your time draws near - huzzah!\n\nThere is one last item that needs to be made before we begin this, &lt;name&gt;.  Hopefully your resourcefulness has not departed you since you had your barding made...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7645] = {title = "Manna-Enriched Horse Feed", objective = "Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits.\n\nYou also need to give her 50 gold to soothe her ruffled sensibilities.", description = "The Silver Hand thought me MAD when I told them that I could make a special horse feed that could nourish spiritual horses.  EVERYONE thought I was mad!  Well, now it's payback time!\n\nI'll make what you need, PALADIN... so-called CHAMPION... but it will cost you.  I need special biscuits - Enriched Manna Biscuits sold only by the Argent Dawn - for this blend.  I also demand, yes DEMAND gold as compensation for the misery I have endured!\n\nShow me the sacrifice you tout so much, PALADIN.", progress = "Yes, I've proved you wrong now, haven't I?  I've proved them all wrong!  I WAS RIGHT ALL ALONG!!!", completion = "YES, NOW WHO - wait - you're giving me the gold too?  You weren't the one who called me mad (actually they called me a fruitcake nut-job)... still, you're willing to show sacrifice even for wrongs you've not committed?\n\nI... I misjudged you, &lt;name&gt;.  Should you need more horse feed, come see me.  I will give it to you free of charge.  Thank you... noble &lt;class&gt;.\n\nI am going to keep the money though - I'm not that much of a nut-job as to give up a fortune.", rewards = "You will receive:\n\nManna-Enriched Horse Feed"}
MultiLanguageQuestData['en'][7646] = {title = "The Divination Scryer", objective = "Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind.", description = "We now must assemble a Divination Scryer - this will begin the trial that will allow you to redeem the fallen charger.  Your scryer, actually, is almost done.  The exorcism censer used in Terrordale is the catalyst for it, and I will fashion a suitable housing for the device.\n\nThe last components needed, though, are two diamonds.  They must be as juxtaposed in brilliance as they are in purpose - an Azerothian and a Pristine Black.  These two will be the beacon by which the scryer will pierce the shadows!", progress = "You have come so very far, <name>.  Your final act of worldly-item sacrifice will be the genesis for one of your greatest accomplishments.  I can feel it in the very fiber of my being!", completion = "These are fine specimens, &lt;name&gt; - the final pieces are now in place.  At long last, your time has come!\n\nIn the depths of the Great Ossuary of Scholomance are the skeletal remains of many beings.  Amongst them is a once-noble charger.  The hollowed soul of this charger now serves as the steed for Death Knight Darkreaver.  It is he whom you will face, and it is this steed that you will pass judgment upon.  Only you, &lt;name&gt;, can redeem its soul and save it from the torment of its servitude.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7647] = {title = "Judgment and Redemption", objective = "Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger.\n\nGive the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger.", description = "Take this satchel - in it are the items you will need for your task.\n\nUse the divination scryer in the heart of the Great Ossuary's basement to bring forth accursed spirits that must be judged.  Use your judgments wisely during this trial - they will prove more potent than you realize.  After the spirits, the death knight will appear; defeat him and reclaim the lost soul of the charger.  Only then <name>, will you be able to redeem it and place your barding upon your new steed!\n\nGood luck!", progress = "The spirit of the fallen charger looks upon you with a mournful gaze.  Sad, almost hollow eyes look at you as though all hope was lost to it.", completion = "A glimmer of life - long vacant from the poor beast - shines in its eyes as you hand its judged soul back to it.  You feel a holy rush of power surge around you as you place the barding on its back, having judged the charger redeemed.  The charger nuzzles your hand as the burdens of the past are lifted from the beast.  You now feel as though you could call upon this beast to serve as your steed, should the need arise.\n\nYou have claimed your epic charger, &lt;class&gt;!  Congratulations!", rewards = "The following spell will be cast on you:\n\nSummon Charger\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][7648] = {title = "Grimand's Finest Work", objective = "Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection.", description = "<Grimand wipes sweat from his brow, beaming with a sense of pride.>\n\nThere you are, my friend.  This is some of my finest work - as good as the barding I personally made for Lord Shadowbreaker when he went for his own charger.  I thank you for your trust in me to provide for you the best.\n\nNo doubt Grayson will want to see the work for himself as well.  Take your barding to him, and give him my thanks for his honorable business.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7649] = {title = "Enchanted Thorium Platemail: Volume I", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n&lt;Lorekeeper Lydros tears out a page from the book.&gt;\n\nI am sure you can make use of this recipe.", rewards = "You will receive:\n\nPlans: Enchanted Thorium Breastplate"}
MultiLanguageQuestData['en'][7650] = {title = "Enchanted Thorium Platemail: Volume II", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n&lt;Lorekeeper Lydros tears out a page from the book.&gt;\n\nI am sure you can make use of this recipe.", rewards = "You will receive:\n\nPlans: Enchanted Thorium Leggings"}
MultiLanguageQuestData['en'][7651] = {title = "Enchanted Thorium Platemail: Volume III", objective = "Return the book to its rightful owners.", description = "The tome carries the mark of the Athenaeum.", progress = "You have recovered a tome!", completion = "Well done, my boy.\n\n&lt;Lorekeeper Lydros tears out a page from the book.&gt;\n\nI am sure you can make use of this recipe.", rewards = "You will receive:\n\nPlans: Enchanted Thorium Helm"}
MultiLanguageQuestData['en'][7652] = {title = "A Blue Light Bargain", objective = "Aright, mister, I got a hot deal for ya.\n\nI'm lookin' to offload some of these here Imperial plate armor recipes and need someone willing to take on the burden. All I want in exchange is some thorium bars. Sound good?", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][7653] = {title = "Imperial Plate Belt", objective = "For the belt plans, I'll be needin' 20 thorium bars.", description = nil, progress = "For the belt plans, I'll be needin' 20 thorium bars.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Belt"}
MultiLanguageQuestData['en'][7654] = {title = "Imperial Plate Boots", objective = "For the boot plans, I'll be needin' 40 thorium bars. Yep, 40. Are you gonna cry? Would you like a hanky?\n\n<Derotain laughs.>", description = nil, progress = "For the boot plans, I'll be needin' 40 thorium bars. Yep, 40. Are you gonna cry? Would you like a hanky?\n\n<Derotain laughs.>", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Boots"}
MultiLanguageQuestData['en'][7655] = {title = "Imperial Plate Bracer", objective = "For the bracer plans, I'll be needin' 20 thorium bars.\n\nAre you alright, sonny? Yer getting' all red.", description = nil, progress = "For the bracer plans, I'll be needin' 20 thorium bars.\n\nAre you alright, sonny? Yer getting' all red.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Bracers"}
MultiLanguageQuestData['en'][7656] = {title = "Imperial Plate Chest", objective = "For the chest piece plans, I'll be needin' 60 thorium bars.\n\nOh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life's fair.", description = nil, progress = "For the chest piece plans, I'll be needin' 60 thorium bars.\n\nOh boy, there you go again. Are you gonna be runnin' to yer blue Gods, askin' why they have forsaken you?!? Toughen up, Nancy! Nobody ever said life's fair.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Chest"}
MultiLanguageQuestData['en'][7657] = {title = "Imperial Plate Helm", objective = "Just hand over 50 thorium bars and the helm plans are yers.", description = nil, progress = "Just hand over 50 thorium bars and the helm plans are yers.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Helm"}
MultiLanguageQuestData['en'][7658] = {title = "Imperial Plate Leggings", objective = "Just hand over 60 thorium bars and the leg plans are yers.\n\nI know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.", description = nil, progress = "Just hand over 60 thorium bars and the leg plans are yers.\n\nI know, I'm driving you into bankruptcy! I've heard it all before so you can save your sob story, weakling.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Leggings"}
MultiLanguageQuestData['en'][7659] = {title = "Imperial Plate Shoulders", objective = "For the shoulder plans, I'll be needin' 20 thorium bars.", description = nil, progress = "For the shoulder plans, I'll be needin' 20 thorium bars.", completion = "A pleasure doin' business with ya.\n\nAnd &lt;name&gt;, wipe that look of disgust off yer face.", rewards = "You will receive:\n\nPlans: Imperial Plate Shoulders"}
