MultiLanguageQuestData['en'][7810] = {title = "Arena Master", objective = "Speak with Short John Mithril in the Stranglethorn Arena.\n\nProvided item: \n", description = "There must be more to being a master of the arena than this!   Perhaps the Pirate who runs the event at Gurubashi will know!", progress = nil, completion = "Arr Me Hearty!   Gaining one Trinket be not enough to make ye master of the Arena!    Now tis the time to truly prove your steel.", rewards = "You will receive:\n\n"}
