MultiLanguageQuestData['en'][7813] = {title = "A Donation of Wool", objective = "We are currently accepting donations for wool cloth.  A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions.  Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", description = nil, progress = "We are currently accepting donations for wool cloth.  A donation of sixty pieces of wool cloth will net you full recognition by the Undercity for your generous actions.  Our stores are such on wool that we would only need sixty pieces from you total; we should be able to acquire enough from others in the realm to support our drive.\n\nIf you have the sixty pieces of wool cloth on you and are ready to donate them, I'm able to take them from you now.", completion = "Wonderful!  We thank you for your generous donation, &lt;name&gt;!", rewards = "You will receive:\n\n"}
