MultiLanguageQuestData['en'][7838] = {title = "Arena Grandmaster", objective = "Avast Lubber!   Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!   Arrrr!", description = nil, progress = "Avast Lubber!   Bring me 12 trinkets of the Arena Master and then ye shall be a Grandmaster of the Gurubashi Arena!   Arrrr!", completion = "Much blood have you spilt on the Arena floor and I be glad to name you Grandmaster of the Arena!", rewards = "You will receive:\n\nArena Grand Master"}
MultiLanguageQuestData['en'][7839] = {title = "Vilebranch Hooligans", objective = "Smith Slagtree at Revantusk Village in the Hinterlands wants you to find Slagtree's Lost Tools. Return to him once this task is complete.\n\nYou recall Smith Slagtree mentioning that the tools might be at one of the Vilebranch temples in the northeastern region of the Hinterlands. You should also check Skulk Rock.", description = "Vilebranch scum invaded our village and stole my tools! I have backup tools but the set they stole was a gift given to me by a kind hearted gnome that saved my life when I was a young orc.\n\nI want those tools back, <name> - they mean the world to me.\n\nMarkhor reported that the tools were spotted near the Agol'watha and Shaol'watha temples.\n\nThose temples are in the northeastern region of the Hinterlands.\n\nRecover my tools!", progress = "Watch out for the Vilebranch trolls of the region, <name>. They are ruthless, murderous filth.", completion = "My tools! You found them! Oh glorious day! Thank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7840] = {title = "Lard Lost His Lunch", objective = "Lard at Revantusk Village in the Hinterlands wants you to find Lard's Lunch. Return to him when this task is complete.\n\nLard mentioned that he left it on the island to the north. Watch out for Vilebranch trolls.", description = "Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.", progress = "<Lard rubs his enormous belly.>\n\nLard so hungry.", completion = "&lt;Lard takes the huge haunch of meat from you and stuffs it in his face.&gt;\n\nDis hit da spot! Tanks little one.\n\nLard make you special picnic basket for help Lard.", rewards = "You will receive:\n\nLard's Special Picnic Basket"}
MultiLanguageQuestData['en'][7841] = {title = "Message to the Wildhammer", objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to slaughter 15 Highvale Outrunners, 15 Highvale Scouts, 15 Highvale Marksman and 15 Highvale Rangers. Return to him when this task is complete.\n\nYou can find the Highvale high elves at the Quel'Danil Lodge in the northwestern region of the Hinterlands.", description = "The Wildhammer be striking up deals with our enemies, forgin' new alliances. This time, they be workin' with the high elves, mon.\n\n<Otho spits.>\n\nWe be needin' to send those Wildhammer dwarves a message - a message in the blood of our enemies. Slaughter every Highvale high elf that you come across, leave their bodies as a warnin'.\n\nNever mess with trolls!", progress = "You be too clean, mon. You gotta mix it up - get down and dirty with the enemy.", completion = "It be lookin' like the Revantusk are forgin' new alliances as well, mon! You done good.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7842] = {title = "Another Message to the Wildhammer", objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to bring him 10 Long Elegant Feathers from the gryphons that inhabit the Hinterlands. Return to him once this task is complete.\n\nGryphons are known to inhabit every region of the Hinterlands.", description = "They say the Wildhammer and gryphon are as close to each other as troll and mate. Disgusting, but we be able to use this to our advantage, mon. We send them another message.\n\nKill all the gryphons you see in the Hinterlands, collect their feathers. From this we make the final message.", progress = "The last message gonna scare them off for sure. Either that or make them very, very angry.", completion = "Oh, mon, this gonna be good. One more step to go and Wildhammer see that they can't mess with troll!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7843] = {title = "The Final Message to the Wildhammer", objective = "Otho Moji'ko at Revantusk Village in the Hinterlands wants you to travel to Aerie Peak in the western region of the Hinterlands and place the Final Message to the Wildhammer by the well in the center of town. Return to him once this task is complete.\n\nBeware of angry Wildhammer dwarves and unruly members of the Alliance.", description = "<Otho hands you a long, blood drenched spear, wrapped in several gryphon feathers.>\n\nYou take this, mon. You take this to Aerie Peak, dead center of town by the well. You plant it! Drive it right into the ground! Show those dwarves that troll mean business! Come back when you do this. Hopefully you come back alive.", progress = "What's the hold up, mon?", completion = "I wish I coulda been there to see the look on their faces, mon. Are they packing up their bags? Leavin' town?\n\nYou done good, &lt;name&gt;. Real good. Otho reward you with the big mojo.", rewards = "You will receive:\n\nOwlbeast Hide Gloves"}
MultiLanguageQuestData['en'][7844] = {title = "Cannibalistic Cousins", objective = "Mystic Yayo'jin at Revantusk Village in the Hinterlands wants you to kill 15 Vilebranch Scalpers and 10 Vilebranch Soothsayers. Return to her when this task is complete.\n\nYayo'jin indicated that these trolls could be found near the Shaol'watha and Agol'watha temples in the north by northeastern region of the Hinterlands.", description = "Three different tribes of trolls inhabit the Hinterlands, <name>. That is about as far as the similarities between the tribes extends: We are all trolls and we live in the Hinterlands.\n\nThe Vilebranch - aptly named - are a depraved lot; feeding on other trolls and humanoids.\n\nIf Zul'jin were here, he would have destroyed the whole lot of them with a flick of his wrist - alas, Zul'jin has not yet returned and we are left to our own devices.\n\nIt is up to you to destroy the filth of the region!", progress = nil, completion = "Well done, &lt;class&gt;. Zul'jin himself could not have done a better job!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7845] = {title = "Kidnapped Elder Torntusk!", objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to rescue her mate, Elder Torntusk, from Jintha'alor.\n\nYou have been told that he is being held prisoner atop Jintha'alor, the Vilebranch capital city located in the southern region of the Hinterlands.", description = "My mate was taken by Vilebranch savages in a bold midnight raid on our village. Our spies have told me that he is still alive and being held prisoner atop Jintha'alor. The Vile Priestess Hexx is said to be preparing him for a sacrifice to the faceless blood God, Hakkar.\n\nYou must save him, <name>! Our village could not stand a loss this great.", progress = nil, completion = "You must act quickly, &lt;name&gt;. Surely the guards have been alerted to your presence.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7846] = {title = "Recover the Key!", objective = "Elder Torntusk at Jintha'alor wants you to kill Hitah'ya the Keeper to get the Shackle Key to his bindings. Return to Elder Torntusk when you have recovered the key.", description = "The key to my bindings is held by Hitah'ya the Keeper. She is in the nearby cave. Be careful, <class>, for she is guarded well.\n\nKill her and bring the key back to loosen my shackles. Only then will I be free to return home.", progress = "You must hurry!", completion = "Freedom at last! Thank you, &lt;name&gt;. Revantusk will know your deeds!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][7847] = {title = "Return to Primal Torntusk", objective = "Elder Torntusk at Jintha'alor wants you to return to Primal Torntusk at Revantusk Village with news of his rescue.", description = "Return to my mate, Primal Torntusk at Revantusk Village. Tell her that I am coming home! She is sure to reward you.", progress = nil, completion = "You have done the Revantusk a great service, &lt;name&gt;! We owe you a great debt of gratitude.", rewards = "You will be able to choose one of these rewards:\n\nHighland BowFlask of Forest Mojo\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7848] = {title = "Attunement to the Core", objective = "Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment.", description = "Rifts stir, tear, and collapse all around us, <race>. Not two paces from where I stand is a tear leading through the depths of Blackrock Mountain, into the maw of the Firelord.\n\nSurprised? Pity... The mortal races cannot comprehend that which they cannot see, touch, or feel.\n\nI assure you, the portal is there and access is possible.\n\nI've piqued your interest? Attunement is simple. Venture into Blackrock Depths and retrieve a core fragment. Return it to me and I shall attune your essence with the portal.", progress = "You must attune your soul with the Molten Core before access is granted.", completion = "I am now able to transport you to the Molten Core. Ask and it shall be done.", rewards = "The following spell will be cast on you:\n\nAttunement to the Core\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][7849] = {title = "Separation Anxiety", objective = "Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.\n\nMarkhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple.", description = "Like many in our village, I too have lost a loved one to the wilds. Alas, it was my twin brother Malkhor - taken in the same raid as Torntusk's mate by the Vilebranch.\n\nSadly, he was not fated to live and was given a swift, brutal execution; his remains fed to the oozes and wolves of the Vilebranch.\n\nIt is too late to save his life but not too late to save his soul. Recover his remains, <name>.", progress = "When I have his remains, I shall take them to Yayo'jin and have them prepared for a proper burial.", completion = "My dearest brother, how I will miss you...\n\nThank you for your assistance, &lt;name&gt;. You are truly a hero in my eyes.", rewards = "You will be able to choose one of these rewards:\n\nLaquered Wooden Plate LegplatesGreenleaf Handwraps\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7850] = {title = "Dark Vessels", objective = "Primal Torntusk at Revantusk Village in the Hinterlands wants you to recover 10 Vessels of Tainted Blood from Jintha'alor. Return to Primal Torntusk when this task is complete.", description = "The Vilebranch fight with supernatural ferocity. This is due to the foul magical weavings of the Vile Priestess Hexx.\n\nThroughout Jintha'alor you will find dark vessels of tainted blood. The vessels radiate the foul magic of the faceless blood God, empowering the Vilebranch and also driving them to madness.\n\nSteal those vessels and return them to me so that I may remove the taint and ultimately loosen the grip of the blood God.", progress = "Be cautious in battling the Vilebranch, <name>. Their minds are clouded - they fight to the death.", completion = "The dark energy that compels the Vilebranch has been lifted - for now. We must remain ever vigilant in our battle against evil, as even if the Vile Priestess is destroyed, another soon takes her place.", rewards = "You will receive:\n\nNature's Breath"}
MultiLanguageQuestData['en'][7861] = {title = "Wanted: Vile Priestess Hexx and Her Minions", objective = "You have been ordered to slay Vile Priestess Hexx and 10 Vilebranch Aman'zasi Guards. See Primal Torntusk at Revantusk Village in the Hinterlands once this task is complete.\n\nVile Priestess Hexx and the Aman'zasi Guards can be found atop Jintha'alor in the Hinterlands.", description = "By order of Primal Torntusk, Vile Priestess Hexx and her minions are to be brought to justice!\n\nA grand reward is offered for any that slay the Vile Priestess Hexx and all of her Aman'zasi elite guard.", progress = nil, completion = "A crippling blow to the Vilebranch, indeed. You shall be richly rewarded, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nWoven Ivy NecklaceDeep Woodlands Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][7862] = {title = "Job Opening: Guard Captain of Revantusk Village", objective = "You have been tasked with the decimation of 10 Vilebranch Berserkers, 5 Vilebranch Shadow Hunters, 5 Vilebranch Blood Drinkers, and 5 Vilebranch Soul Eaters.\n\nShould you complete this task, return to Primal Torntusk at Revantusk Village in the Hinterlands.", description = "With the loss of Guard Captain Malkhor, the position of Guard Captain of Revantusk is once again open. If you are interested in becoming Captain of the Guard for Revantusk, complete the following tasks and submit your application to Primal Torntusk:\n\nExterminate Vilebranch Berserkers.\n\nExterminate Vilebranch Shadow Hunters.\n\nExterminate Vilebranch Blood Drinkers.\n\nExterminate Vilebranch Soul Eaters.", progress = "Are you here about the job opening?", completion = "You are indeed a worthy candidate for the new position, &lt;name&gt;. Accept this trinket as a token of our appreciation for your hard work. I will be reviewing all applications next year.", rewards = "You will receive:\n\nRune of the Guard Captain"}
MultiLanguageQuestData['en'][7863] = {title = "Sentinel Basic Care Package", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSentinel Basic Care Package"}
MultiLanguageQuestData['en'][7864] = {title = "Sentinel Standard Care Package", objective = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Warsong Gulch.\n\nAs you continue to prove yourself inside the Gulch, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSentinel Standard Care Package"}
MultiLanguageQuestData['en'][7865] = {title = "Sentinel Advanced Care Package", objective = "You've certainly begun to prove yourself to us, <name>.  As a reward, please take this care package!  Inside it you'll find rations and bandages that are usable only inside Warsong Gulch.\n\nAs you continue to prove yourself inside the Gulch, you'll find that these items will become available to you for purchase.  Rations become available when you are Friendly with us, and bandages when you are Honored.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nSentinel Advanced Care Package"}
