MultiLanguageQuestData['en'][7937] = {title = "Your Fortune Awaits You...", objective = "Travel to the Eastvale Logging Camp in Elwynn Forest and seek out your fortune.", description = "\"Your fortune awaits you in Eastvale.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Eastvale Logging Camp in Elwynn Forest.  Focusing closer in on the image, you see a haystack that sits next to a stable.", progress = "This haystack looks like the one from your vision.", completion = "A quick search of the haystack reveals a lockbox from within it!  It would seem that you have found your fortune!", rewards = "You will receive:\n\nMysterious Lockbox"}
MultiLanguageQuestData['en'][7938] = {title = "Your Fortune Awaits You...", objective = "Travel to the Deadmines in Westfall and seek out your fortune.", description = "\"Your fortune awaits you inside the Deadmines.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Deadmines inside Westfall's ruined hamlet of Moonbrook.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the mines itself.  Stepping through it, a strange chest appears out from nowhere.", progress = "This chest looks like the one from your vision...", completion = "A quick search of the chest reveals a lockbox from within it!  It would seem that you have found your fortune!", rewards = "You will receive:\n\nMysterious Lockbox"}
MultiLanguageQuestData['en'][7939] = {title = "More Dense Grinding Stones", objective = "<name>, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", description = nil, progress = "<name>, thank you for all the help you've given me.  I really can't thank you enough!\n\nAlthough my need is no longer great... if you bring me more dense grinding stones, I still have more Darkmoon Faire tickets for you.", completion = "Again, thank you &lt;name&gt;.  Please enjoy these tickets, and tell your friends about the Darkmoon Faire!", rewards = "You will receive:\n\nDarkmoon Faire Prize Ticket"}
MultiLanguageQuestData['en'][7940] = {title = "1200 Tickets - Orb of the Darkmoon", objective = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", description = nil, progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets.", rewards = "You will receive:\n\nOrb of the Darkmoon"}
MultiLanguageQuestData['en'][7941] = {title = "More Armor Kits", objective = "<name>, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", description = nil, progress = "<name>, I must thank you for all your help.  I have plenty of supplies, through no small efforts on your part, but if you wish to bring me more armor kits, then I will gladly trade them for Darkmoon Faire tickets.", completion = "There you are, &lt;name&gt;.  A fair trade.  Enjoy.", rewards = "You will receive:\n\nDarkmoon Faire Prize Ticket"}
MultiLanguageQuestData['en'][7942] = {title = "More Thorium Widgets", objective = "<name>, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", description = nil, progress = "<name>, you have been so good to us, bringing me goods without tiring.  You have my eternal thanks!\n\nAlthough our need for Thorium widgets is not as great as it was, you may still bring them to me and I will gladly trade them for Darkmoon Faire tickets.", completion = "Here you are, &lt;name&gt;.  Here are Darkmoon Faire tickets for your enjoyment.  Do not, as they say, spend them all in one place!", rewards = "You will receive:\n\nDarkmoon Faire Prize Ticket"}
MultiLanguageQuestData['en'][7943] = {title = "More Bat Eyes", objective = "<name>, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", description = nil, progress = "<name>, the attraction I'm designing will be the scariest event since Gnomeregan was overrun!  And it's largely thanks to you and all the baubles you've brought me.  Many, many thanks!\n\nI don't need much else, but... if you bring me more evil bat eyes from the bats of the Eastern Plaguelands... I might have more Darkmoon Faire tickets for you.", completion = "Thanks again, &lt;name&gt;.  Here are your tickets!", rewards = "You will receive:\n\nDarkmoon Faire Prize Ticket"}
MultiLanguageQuestData['en'][7944] = {title = "Your Fortune Awaits You...", objective = "Travel to the Wailing Caverns in the Barrens and seek out your fortune.", description = "\"Your fortune awaits you inside Wailing Caverns.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of a cave to the southwest of the Crossroads in the Barrens.  Focusing closer in on the image, you wind about twisty passages until you reach a shimmering portal... one that leads into the heart of the caverns itself.  Stepping through it, a strange chest appears out from nowhere.", progress = "This chest looks like the one from your vision...", completion = "A quick search of the chest reveals a lockbox from within it!  It would seem that you have found your fortune!", rewards = "You will receive:\n\nMysterious Lockbox"}
MultiLanguageQuestData['en'][7945] = {title = "Your Fortune Awaits You...", objective = "Travel to Palemane Rock in Mulgore and seek out your fortune.", description = "\"Your fortune awaits you outside Palemane Rock.\"\n\nThe fortune Sayge handed you feels slightly warm to the touch.  Grasping it firmly, you see an image of the Palemane Rock of Mulgore.  Focusing closer in on the image, you see a tree stump that sits close to the cave entrance.", progress = "This tree stump looks like the one from your vision.", completion = "A quick search of the tree stump reveals a lockbox from within it!  It would seem that you have found your fortune!", rewards = "You will receive:\n\nMysterious Lockbox"}
MultiLanguageQuestData['en'][7946] = {title = "Spawn of Jubjub", objective = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", description = nil, progress = "I'm so happy Jubjub is no longer lost.  She loves Dark Iron ale so much that when I ran out... she ran away to find more!\n\nNow that Jubjub's back, I want as much ale as I can get!  I won't want her to run away again!\n\nDo you have any Dark Iron Ale?  If you do, then I'll trade you one of Jubjub's frog eggs for a mug...", completion = "Thank you, &lt;name&gt;.  Here is your egg!  It won't be ready to hatch for a little while, but when it does you'll have a great pet!", rewards = "The following spell will be cast on you:\n\nJubling Cooldown\n\nYou will receive:\n\nUnhatched Jubling Egg"}
MultiLanguageQuestData['en'][7961] = {title = "Waskily Wabbits!", objective = "Kill 5 rabbits and return to Jon LeCraft by the forge on Designer Island.These rabbits are breeding uncontrollably. Something must be done!\n\nHelp us <name>, you're our only hope.You will learn:\n\n", description = "These rabbits are breeding uncontrollably.  Something must be done!\n\nHelp us <name>, you're our only hope.You will learn:\n\n", progress = nil, completion = nil, rewards = "You will learn:\n\nTaming Lesson\n\nThe following spell will be cast on you:\n\nTame Beast"}
MultiLanguageQuestData['en'][7962] = {title = "Wabbit Pelts", objective = "Bring 3 LeCrafty Rabbit Pelts to Jon LeCraft.", description = "I want LeCrafty rabbit pelts.  Get me some from LeCrafty Rabbits.\n\nThis is important!The following spell will be cast on you:\n\n", progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nMark of the Wild\n\nYou will receive:\n\n22 Pound Lobster"}
MultiLanguageQuestData['en'][7981] = {title = "1200 Tickets - Amulet of the Darkmoon", objective = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", description = nil, progress = "Step right up, step right up!  If you have tickets from the Darkmoon Faire you'd like redeemed, then just say so!  You can redeem tickets in various denominations for wondrous and fantastic prizes.  Don't be shy, give it a try!", completion = "Here you go, here you go!  A prize fit for a king!  Congratulations to you, my friend!\n\nIf you have more tickets you'd like to turn in, then please let me know!  For as long as the Darkmoon Faire is here, I'll redeem your tickets.", rewards = "You will receive:\n\nAmulet of the Darkmoon"}
MultiLanguageQuestData['en'][8021] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8022] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8023] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8024] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8025] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8026] = {title = "Redeem iCoke Prize Voucher", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWhite Murloc Egg"}
MultiLanguageQuestData['en'][8041] = {title = "Strength of Mount Mugamba", objective = "Hail, <class>. I am Jin'rokh the Breaker, troll of Mugamba. We of the Zandalar tribe recognize your accomplishments. We salute your tenacity and strength of will.\n\nWear this talisman around your neck, <class>. Let the strength of Mount Mugamba flow through your being. Be empowered as you strike down our enemies!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nStrength of Mugamba"}
MultiLanguageQuestData['en'][8042] = {title = "Strength of Mount Mugamba", objective = "It is good to see you in good health, <name>. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", description = nil, progress = "It is good to see you in good health, <name>. The glorious battles you have undertaken affect all life on this planet. Hakkar must never leave the confines of Zul'Gurub as the world will surely collapse beneath his immense hunger.\n\nGive me your talisman and I shall amplify its strength. Use the Strength of Mugamba to punish our enemies!", completion = "Our paths will cross again, &lt;class&gt;.", rewards = "You will receive:\n\nStrength of Mugamba"}
MultiLanguageQuestData['en'][8043] = {title = "Strength of Mount Mugamba", objective = "Master <name>, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary <class> - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", description = nil, progress = "Master <name>, you return! Molthor has sent word of your deeds to the King. Your name is known even in the South Seas. Perhaps one day you will be a legendary <class> - a story for the ages.\n\nGive me your talisman so that I may once more amplify its power.", completion = "Use your newfound strength to destroy the Gurubashi!", rewards = "You will receive:\n\nStrength of Mugamba"}
MultiLanguageQuestData['en'][8044] = {title = "The Rage of Mugamba", objective = "King Rastakhan sends his regards, Master <name>. Such an honor has never been given to one outside the Zandalar tribe.\n\n\n\nGive me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", description = nil, progress = "King Rastakhan sends his regards, Master <name>. Such an honor has never been given to one outside the Zandalar tribe.\n\n\n\nGive me your talisman so that I may enhance it once more. Know that the Rage of Mugamba is now intrinsically connected to your very soul.", completion = "Zul'jin would be envious, &lt;class&gt;. Go forth and conquer!", rewards = "You will receive:\n\nRage of Mugamba"}
MultiLanguageQuestData['en'][8045] = {title = "The Heathen's Brand", objective = "Know this, heathen: A catastrophe has brought us together. Your pagan ways are neither understood nor appreciated by Zandalar but we are a fair people. Wear this brand around your neck. It shall serve as both a warning to our enemies and a symbol of your friendship to Zandalar.\n\nContinue to serve our people and I will amplify the power of the brand.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nHeathen's Brand"}
MultiLanguageQuestData['en'][8046] = {title = "The Heathen's Brand", objective = "I may have been too hasty in my judgement, <class>. It seems as if your blind faith in this Light has some value after all.\n\nGive me your brand and I shall amplify its power.", description = nil, progress = "I may have been too hasty in my judgement, <class>. It seems as if your blind faith in this Light has some value after all.\n\nGive me your brand and I shall amplify its power.", completion = "Do what you must to defeat our enemies, &lt;class&gt;. Even if it means channeling the Light.", rewards = "You will receive:\n\nHeathen's Brand"}
MultiLanguageQuestData['en'][8047] = {title = "The Heathen's Brand", objective = "I must confess, I did not think you had the resolution to see this cause through, <class>. Zandalar now considers you an invaluable ally. Well done, indeed.\n\nGive me your brand and I shall once more amplify its power.", description = nil, progress = "I must confess, I did not think you had the resolution to see this cause through, <class>. Zandalar now considers you an invaluable ally. Well done, indeed.\n\nGive me your brand and I shall once more amplify its power.", completion = "Our beliefs differ but our cause is righteous. Strike down our foes, noble &lt;class&gt;.", rewards = "You will receive:\n\nHeathen's Brand"}
MultiLanguageQuestData['en'][8048] = {title = "The Hero's Brand", objective = "The King has acknowledged your existence, <class>. You are the first of your kind to be accepted by Rastakhan as a true ally of Zandalar.\n\nYou will be rewarded greatly for your efforts. Present your brand and I shall apply the final amplification.", description = nil, progress = "The King has acknowledged your existence, <class>. You are the first of your kind to be accepted by Rastakhan as a true ally of Zandalar.\n\nYou will be rewarded greatly for your efforts. Present your brand and I shall apply the final amplification.", completion = "Vigilance, honor, loyalty, bravery... You embody all of these traits and so shall your brand.", rewards = "You will receive:\n\nHero's Brand"}
MultiLanguageQuestData['en'][8049] = {title = "The Eye of Zuldazar", objective = "Accept this talisman as a token of our appreciation, <class>.\n\nThe Eye of Zuldazar will grow in power as your bond with the trolls of Zandalar strengthens. Return to me periodically and I shall imbue the jewel.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nThe Eye of Zuldazar"}
MultiLanguageQuestData['en'][8050] = {title = "The Eye of Zuldazar", objective = "Welcome <class>. The Eye of Zuldazar pulses with energy. You are ready to take the next step. Hand me the talisman and I shall perform the imbue.", description = nil, progress = "Welcome <class>. The Eye of Zuldazar pulses with energy. You are ready to take the next step. Hand me the talisman and I shall perform the imbue.", completion = "Continue in your battle against the Soulflayer and his minions, &lt;name&gt;. He must never be permitted to leave the confines of Zul'Gurub.", rewards = "You will receive:\n\nThe Eye of Zuldazar"}
MultiLanguageQuestData['en'][8051] = {title = "The Eye of Zuldazar", objective = "Tales of your battles against the Gurubashi are whispered in the winds, <class>. Even royalty is beginning to talk of your deeds. It is rumored that King Rastakhan even mentioned you by name.\n\nThe time has come to imbue the Eye. Hand me the talisman and I shall perform the service.", description = nil, progress = "Tales of your battles against the Gurubashi are whispered in the winds, <class>. Even royalty is beginning to talk of your deeds. It is rumored that King Rastakhan even mentioned you by name.\n\nThe time has come to imbue the Eye. Hand me the talisman and I shall perform the service.", completion = "Be resolute in your endeavors, &lt;name&gt;. The Soulflayer will attempt to siphon your will to live.", rewards = "You will receive:\n\nThe Eye of Zuldazar"}
MultiLanguageQuestData['en'][8052] = {title = "The All-Seeing Eye of Zuldazar", objective = "If only we had ten-thousand more like you, <name>. The armies of Hakkar would be scattered to the wind in the blink of an eye.\n\n\n\nAlas, the Eye is ready to realize its full potential. Give it to me.", description = nil, progress = "If only we had ten-thousand more like you, <name>. The armies of Hakkar would be scattered to the wind in the blink of an eye.\n\n\n\nAlas, the Eye is ready to realize its full potential. Give it to me.", completion = "Smite them all and let Hakkar sort them out...", rewards = "You will receive:\n\nThe All-Seeing Eye of Zuldazar"}
MultiLanguageQuestData['en'][8053] = {title = "Paragons of Power: The Freethinker's Armguards", objective = "Bring Jin'rokh the BreakerPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "You are a heathen.  Heathens have a place in the tribe.  Heathens are freethinkers of Zandalar.  Freethinkers do not fear oppression.  Freethinkers die for what they believe in.  We know you would die for what you believe in.  This earns our acknowledgement.  This earns you a chance to prove yourself further.\n\nWe must have the Paragons of Power.  Go to Zul'Gurub.  Kill the minions of Hakkar.  Return when you have what I seek.  Claim the first battle gear of a Zandalar freethinker.\n\nGo.", progress = "You have returned?  Do you have the Paragons of Power?  Are you wasting my time?\n\nI hope not, heathen.", completion = "You do much to honor us.  Your hands drip with the blood of Hakkar's minions.  You are a friend to the tribe.\n\nWear these bracers.  They are the freethinker's armguards.  This is what I mean about real power.", rewards = "You will receive:\n\nZandalar Freethinker's Armguards"}
MultiLanguageQuestData['en'][8054] = {title = "Paragons of Power: The Freethinker's Belt", objective = "Bring Jin'rokh the Breaker a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "Your beliefs are alien to us, heathen.  Ancient Zandalar were once branded as heretics.  This was when the Gurubashi Empire was strong.  Heathens dared to challenge the priest of Hakkar.  Heathens then were hunted and killed as vermin.  Those heathens never wavered in their fight against the Blood God.  We honor the price they paid.  They are the freethinkers.\n\nDestroy the minions of Hakkar in Zul'Gurub.  Bring me the Paragons of Power I seek.  Success will be greatly rewarded.\n\nGo.", progress = "Your presence means victory?  Do you have the Paragons?  Are you dripping in the remains of your enemies?", completion = "Your honor is assured in the tribe.  You claim many deaths in Zul'Gurub.  Enemies fall before your convictions.  Enemies fall before your power.\n\nThis is the freethinker's belt.  It is a symbol of honor.  It is powerful mojo.  It is now yours.", rewards = "You will receive:\n\nZandalar Freethinker's Belt"}
MultiLanguageQuestData['en'][8055] = {title = "Paragons of Power: The Freethinker's Breastplate", objective = "Bring Jin'rokh the Breaker a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "Battle gear gives you power in the tribe.  The freethinkers are honored in this way.  They are zealots.  They imbue their breastplates with powerful mojo.  If their beliefs falter in the face of the enemy, their breastplate will not.\n\nYou must be revered amongst us to possess such a breastplate.  Go to Zul'Gurub.  Take the Paragons of Power I need.  Take the Paragons most painfully from the fools inside.  Bring them to me.  Prove your worth as a freethinker once and for all.", progress = "Do you have the Paragons?  They have mojo inside them.  We must have them.  You will aid us.", completion = "You have done what few ever could.  You have brought the minions of Hakkar to their knees.  You have shown them what a freethinker can do.  You have shown us how a heretic could be revered in the tribe.  You have more than real power.  You ARE real power.\n\nTake the breastplate, freethinker.  Crush those who oppose you.", rewards = "You will receive:\n\nZandalar Freethinker's Breastplate"}
MultiLanguageQuestData['en'][8056] = {title = "Paragons of Power: The Augur's Bracers", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", description = "The augurs of our tribe are revered for their gifts of the divine sight, ya mon.  They ain't a witch doctor; they spend their time castin' bones or readin' the leaves for insight - not hexin' people.  As a shaman, you already know somethin' about the power of augury; we Zandalar prize the insight they give to the tribe.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this for us, and I'll give ya some bracers that our augurs prize above all others!", progress = "Got the Paragons of Power from Zul'Gurub that I need?  These bracers are well worth any effort ya be needin' to make!", completion = "It seems ya got a bit of the Zandalar augur in ya.  We know about the deeds you've been doin' in Zul'Gurub on our behalf mon.  These Paragons of Power will go a long way to helpin' out the Zandalar tribe - a tribe, I might add, ya can call upon as friends.  Take these bracers, &lt;name&gt;; ya earned them and then some!", rewards = "You will receive:\n\nZandalar Augur's Bracers"}
MultiLanguageQuestData['en'][8057] = {title = "Paragons of Power: The Haruspex's Bracers", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", description = "A haruspex is a key member of our tribe; you'll be wise to listen to their portents.  By communion with animals and givin' them up to the spirits when needed, they give us divine guidance.  In times past, the haruspex's insight and wisdom gave us an edge in the wars against the splintered tribes of the Gurubashi.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and I'll give ya bracers that any haruspex of the Zandalar would want.", progress = "Have ya got the Paragons of Power from Zul'Gurub?  These bracers are worth the effort, <name>.  Trust me mon!", completion = "Ah, I can sense the power comin' from these Paragons of Power, &lt;name&gt;.  Ya proved to be someone we in the tribe can call \"friend.\"  A deal is a deal, &lt;name&gt;... behold the power of the haruspex's bracers!", rewards = "You will receive:\n\nZandalar Haruspex's Bracers"}
MultiLanguageQuestData['en'][8058] = {title = "Paragons of Power: The Vindicator's Armguards", objective = "Bring Jin'rokh the Breaker a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "Vengeance is power.  The Zandalar vindicator is such power.  The tribe has many enemies.  The vindicator exacts retribution on them.  No crime against us is unpunished.  The vindicator delivers this punishment.  Our enemies fear our vengeance.  They should.  They forever will.\n\nBecome one of our vindicators.  Seek the Paragons of Power inside Zul'Gurub.  Slay the minions of Hakkar and claim vengeance in the tribe's name.  You will be rewarded.", progress = "Have you brought the Paragons of Power?  Has vengeance been claimed in the name of the Zandalar?", completion = "You have wrought much vengeance today.  You have taken on the visage of the vindicator.  You have brought the Blood God's minions to their knees.\n\nTake this.  It will fuel your vengeance for the future.  You are a friend to the Zandalar now.", rewards = "You will receive:\n\nZandalar Vindicator's Armguards"}
MultiLanguageQuestData['en'][8059] = {title = "Paragons of Power: The Demoniac's Wraps", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "Warlocks tread dangerous ground in dealing with demons, but our demoniacs take this one step further.  Through an ancient and arcane ritual, they allow a demon to enter their being.  Rather than let it possess them though, they enslave the demon from the inside, absorbing the power of the beast for their own command.  It is a feat few are ever able to master.\n\nFor you to learn of the power of the demoniac, I must have Paragons of Power from Zul'Gurub.  Go there and retrieve that which we seek.", progress = "Have you returned with the Paragons of Power?  By defeating the diabolic minions of the Hakkar, you will not only prove yourself to us, but also your willingness to learn the ways of the demoniac.", completion = "Well done... no doubt they were made to pay in excruciating ways before they gave up the Paragons of Power.  Take this - the demoniac's wraps.  Made from powerful mojo used in summoning the demoniac's prey, it is a powerful tool in your acquisition of power.", rewards = "You will receive:\n\nZandalar Demoniac's Wraps"}
MultiLanguageQuestData['en'][8060] = {title = "Paragons of Power: The Illusionist's Wraps", objective = "Bring Al'tabim the All-SeeingPrimal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "Mages in our tribe are known as illusionists.  They employ powerful mojo in their incantations, often befuddling and confusing the tribe's enemies!\n\n<Al'tabim laughs wickedly.>\n\nIt is quite the sight to see a powerful illusionist at work, bringing our enemies to their knees from their own madness!\n\nFor you to know the way of our illusionists, go to Zul'Gurub and bring back to me selected Paragons of Power.  For this, I will give you arm wraps our illusionists use to weave their spells.", progress = "<name> - you've returned already?  Were you able to get the Paragons of Power I need?", completion = "Impressive... could you feel the mojo flowing through them?  The Paragons of Power were used as currency of sorts back when the Gurubashi Empire ruled these lands.  Now we Zandalar will use the latent mojo inside of them to fight the second rise of the Blood God Hakkar!\n\nYou've done well today - consider yourself to have a friend in the Zandalar.  For that, here are the illusionist's wraps I promised!", rewards = "You will receive:\n\nZandalar Illusionist's Wraps"}
MultiLanguageQuestData['en'][8061] = {title = "Paragons of Power: The Confessor's Wraps", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Stanchion. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "We Zandalar invest power in those who speak with the authority of divinity.  Our priests are more than just healers - they are our confessors.  Evil comes both from outside threats - such as Hakkar - and from within the tribe.  Our confessors act as the judges amongst us, preserving us from the same evil that devoured the Gurubashi from inside itself.\n\nGo to Zul'Gurub and bring back the Paragons of Power from the Gurubashi.  Learn what it means to be the confessor, and preserve us from evil.", progress = "Back from Zul'Gurub, are you?  Have you succeeded in retrieving the Paragons of Power from the minions of Hakkar?", completion = "Outstanding, &lt;name&gt;!  This was no small feat bringing these to me.  No doubt you've acted as our tribe's confessor today in preserving ourselves against the threat of Hakkar.  These wraps are befitting a friend of the tribe such as you!", rewards = "You will receive:\n\nZandalar Confessor's Wraps"}
MultiLanguageQuestData['en'][8062] = {title = "Paragons of Power: The Predator's Bracers", objective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Bindings. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "In the dark times after the fall of the Gurubashi Empire, Zandalar predators used their prowess to provide sustenance for the tribe.  Hunters claim to be much like our tribe's predators - to seek the hunt is to embody the essence of the predator, yes.  Your hunt in Zul'Gurub, however, will show us how you truly rate amongst our finest predators.\n\nBring to me a sampling of the Paragons of Power from within Zul'Gurub.  Do so, and you'll take first steps in becoming the penultimate predator.", progress = "Hunt those in Zul'Gurub that would possess the Paragons of Power, <name>.  They are your prey; they possess that which we both must have.", completion = "Yes... I need no vision to sense the presence of the Paragons of Power.  Your success in Zul'Gurub has impressed many among the tribe.  We not only consider you to be a friend of the Zandalar, but also consider you worthy enough to possess the predator's bracers - powerful items, and a symbol of what it means to be a predator.  Well done, &lt;name&gt;.", rewards = "You will receive:\n\nZandalar Predator's Bracers"}
MultiLanguageQuestData['en'][8063] = {title = "Paragons of Power: The Madcap's Bracers", objective = "Bring Falthir the Sightless a Primal Hakkari Armsplint. You must also have a reputation equal to or greater than Friendly with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "The madcaps of Zandalar are similar to rogues, but above all else they embrace madness... chaos... the unpredictability of existence.  A terror to behold on the battlefield, they sowed the seeds of confusion and mayhem amongst our enemies in the savage times after the tribes splintered.  We would not be here today without them.\n\nBring to me the Paragons of Power from Zul'Gurub that I seek, and I will grant you the first of the madcap's prized armors.  Embrace the madness!", progress = "Seek the madness from within Zul'Gurub and overshadow it with your own, <name>!  To do so means success, and success means reward!  Let not the Blood God reign supreme again!", completion = "Well done, &lt;name&gt;... your accomplishments in Zul'Gurub have earned you the right to call the Zandalar tribe as a friend.  I will see to the disposition of the Paragons; for your effort please accept this reward!", rewards = "You will receive:\n\nZandalar Madcap's Bracers"}
MultiLanguageQuestData['en'][8064] = {title = "Paragons of Power: The Haruspex's Belt", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Sash. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Honored with Zandalar.", description = "We Zandalar know not of druidic ways; nature is to be shaped by our need, not the other way around.  Still, a haruspex is the one of us most in tune with nature, and rightly so.  To give up the ghost of a beastie is to know what it is to be one of them.  That is the real power of nature.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub, proving yourself to us.  Do this, and I'll give ya a powerful item - a belt used by many of the Zandalar's haruspices.\n\nStrong mojo, ya mon!", progress = "Got the Paragons of Power from Zul'Gurub I need?  The haruspex's belt will be yours if ya have them.", completion = "I thank you - the latent power in these items will be treasures unto themselves, you betcha.  Not only have ya done as I've asked of ya, but you've also proven to be honorable to us here in the tribe.  As promised, here is your reward!", rewards = "You will receive:\n\nZandalar Haruspex's Belt"}
MultiLanguageQuestData['en'][8065] = {title = "Paragons of Power: The Haruspex's Tunic", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. Maywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale. You must also be Revered with Zandalar.", description = "The ultimate symbol of a haruspex's power is what they wear, <name>.  Of these, the tunic symbolizes the connection between themselves and the divine wisdom they seek.  It often weaves parts of the beasties they sacrifice into the tunic; this reminds them of the connection they have to their gifts.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do this, and a tunic seeping with the true power of a haruspex is yours.", progress = "Got the necessary Paragons of Power from Zul'Gurub?  The haruspex's tunic is well worth any effort ya be needin' to make.", completion = "Impressive... you've successfully collected the required Paragons of Power, &lt;name&gt;.  Your accomplishments in Zul'Gurub for the Zandalar are legendary; hence forth, you'll be revered amongst the tribe.  Here is your tunic, mighty &lt;class&gt;!", rewards = "You will receive:\n\nZandalar Haruspex's Tunic"}
MultiLanguageQuestData['en'][8066] = {title = "Paragons of Power: The Predator's Belt", objective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "A predator knows how to stalk their prey, but a successful one knows how to strike at it once they have closed ranks.  You must master both to have any chance of success in Zul'Gurub... and any chance of being like the Zandalar predators.\n\nBring me choice parts of the Paragons of Power from within Zul'Gurub.  My reward will be the power that the trinkets yield, while yours will be the Zandalar predator's belt - equipment well worth the trade.", progress = "Strike at the insane minions of Hakkar in Zul'Gurub - they are the ones that hold the Paragons of Power, <name>.  Prove your success to them - and to the tribe - as an aspirant to the predator.", completion = "I sensed your arrival moments before, &lt;name&gt;, but none too easily.  What revealed yourself to me were the Paragons of Power you brought.  I can feel the power without needing to see the trinkets; their latent mojo - raw magic, if you will - will continue to fuel our efforts of vanquishing the diabolic schemes of the Blood God Hakkar.\n\nYou are to be commended - and rewarded - for your success.  You are honored amongst the tribe, and you are worthy to wear the predator's belt.", rewards = "You will receive:\n\nZandalar Predator's Belt"}
MultiLanguageQuestData['en'][8067] = {title = "Paragons of Power: The Predator's Mantle", objective = "Bring the following Paragons of Power from Zul'Gurub to Falthir the Sightless: A Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "We Zandalar prize what we wear as a symbol of accomplishment.  You don't need to be able to see what one wears to be able to sense what emanates from it - power transcends sight.  The garments of the Zandalar predator are like this, and most cherished by them is the mantle they wear.  It helps to obfuscate them from view... and to make their presence known when they wish it.\n\nThe Paragons of Power await your retrieval in Zul'Gurub.  Bring me what I seek, and the predator's mantle shall be yours.", progress = "Have your strikes into Zul'Gurub yielded success, <name>?  Only when you've brought me what I seek - and proven yourself fully to the tribe - will you earn a mantle second to none amongst the Zandalar.", completion = "Success... you are to be revered amongst the tribe, &lt;name&gt;.  It was no small feat acquiring the Paragons of Power needed for the mantle, but you handled it in the fashion of the deadliest of our predators.  You've earned your place amongst them, and you've certainly earned the right to wear their mantle.", rewards = "You will receive:\n\nZandalar Predator's Mantle"}
MultiLanguageQuestData['en'][8068] = {title = "Paragons of Power: The Illusionist's Mantle", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Shawl. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "Magic is a raw, primal force to be shaped by those strong enough to do it.  Mojo is our extension of this power; one such potent manipulation of it is in the form of illusion.  How can one truly hope to win against a foe that is not even really there?  We Zandalar know the power of this, and as such illusionists hold a honored place within the tribe.\n\nTake the needed Paragons of Power from Zul'Gurub - for this, honor from the tribe and a powerful mantle used by our best illusionists will be yours!", progress = "How was your foray into Zul'Gurub?  Did you drive your enemies mad through the power of illusion?  Illusion or not, their deaths - and the Paragons of Power taken from them - will help thwart the rise of Hakkar.", completion = "Success!  You shall be honored in the tribe from here on!  Zul'Gurub has certainly tasted the might of the Zandalar today, thanks to you &lt;name&gt;.\n\nWith the tribe's blessing, take the Zandalar illusionist's mantle.  May it serve you well.", rewards = "You will receive:\n\nZandalar Illusionist's Mantle"}
MultiLanguageQuestData['en'][8069] = {title = "Paragons of Power: The Illusionist's Robes", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "The tribe acknowledges station and power through what we wear.  Our vestments are made from the finest of materials, and interwoven with the mojo we use to make us powerful.  Illusionists are no exception; their robes are said to embody the essence of illusion in their look.  Legend states that their ancient robes never looked the same twice.\n\nI will give you an illusionist's robe, <name>... but earn your place of reverence among the tribe first!  Bring me the Paragons of Power from Zul'Gurub!", progress = "Have you returned with the Paragons of Power we need?  I know it will not be easy... but I have long predicted an outsider would come to aid us in our fight against Hakkar.  Let it be you, I say!", completion = "At last, someone worthy to wear the illusionist's robe!  Your success in Zul'Gurub has assured your reverences amongst the tribe for ages to come.  Wear it with pride, &lt;name&gt;!", rewards = "You will receive:\n\nZandalar Illusionist's Robe"}
MultiLanguageQuestData['en'][8070] = {title = "Paragons of Power: The Confessor's Bindings", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "Shortly after the fall of the Gurubashi, we Zandalar almost succumbed to a final defeat from evil within our own tribe.  It was then that the confessors amongst us arose, preserving the tribe by banishing out those who would destroy their own kind.  They not only keep us in tune with the spirits, but they also preserve the flesh.\n\nGo forth into Zul'Gurub and witness first hand the depravity of Hakkar and the Gurubashi.  Wrest the Paragons of Power that we seek from them; success will be rewarded!", progress = "The Paragons of Power... do you have them?  Only when we have them will we be able to make use of the latent power stored inside them.  It will be good to turn the tables on the minions of the Blood God...", completion = "Success!  These will go a long way to building up our power against the rise of Hakkar.  With your help, we've taken a significant step in ensuring that the Blood God will not destroy us all.\n\nYou've earned honor with the tribe today, &lt;name&gt;.  Take this - the confessor's bindings - as a symbol of our thanks.", rewards = "You will receive:\n\nZandalar Confessor's Bindings"}
MultiLanguageQuestData['en'][8071] = {title = "Paragons of Power: The Confessor's Mantle", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "The confessors of the Zandalar all wear a distinctive mantle, marking them as the preservers of the tribe.  These mantles are woven with powerful mojo that aids them in judging those who would threaten our tribe.  As a priest, you too must spend your time judging those worthy and not; such a mantle would definitely be a blessing to you.\n\nIn exchange for fighting Hakkar's minions in Zul'Gurub and bringing me the Paragons of Power I seek, I will give you a mantle worthy of our finest confessors.", progress = "Do you have the Paragons of Power from Zul'Gurub?", completion = "Well done, &lt;name&gt; - the minions of Hakkar have surely felt the retribution of the Zandalar today, thanks to you.  Your actions have given you a permanent place of reverence within the tribe.  With our blessing, please take this confessor's mantle as your own!", rewards = "You will receive:\n\nZandalar Confessor's Mantle"}
MultiLanguageQuestData['en'][8072] = {title = "Paragons of Power: The Madcap's Mantle", objective = "Bring Falthir the Sightless a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "One of Zandalar's legendary madcaps was Khar'vaxal the Cracked.  Legend states that when facing the enemies of the tribe for the first time, Kar'xavan used his mantle specifically woven with \"the weave of madness\".  His form was shrouded not only by the mantle, but also with the blinding speed of his twin daggers.  Madcaps today cherish their mantle as a sign of their place in the tribe.\n\nBring to me the Paragons of Power I seek, and such a mantle will be yours to weave madness unto your own enemies.", progress = "You've returned - do you have the Paragons of Power I need?\n\nThe legend of Khar'vaxal the Cracked serves us today as a reminder that no foe - no matter how great a threat they may be - is impossible to overcome.  Chaos will bring everyone to their knees, that much is certain... and perhaps the most non-chaotic elements of chaos.", completion = "Victory is ours this day, thanks to the madness you have sowed upon our mutual enemies!  You are to be honored amongst the Zandalar, and there is no better way of showing gratitude for your deeds than by offering you the madcap's mantle!", rewards = "You will receive:\n\nZandalar Madcap's Mantle"}
MultiLanguageQuestData['en'][8073] = {title = "Paragons of Power: The Madcap's Tunic", objective = "Bring Falthir the Sightless a Primal Hakkari Aegis. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nFalthir the Sightless is located on Yojamba Isle, Stranglethorn Vale.", description = "My eyes failed me long ago, but I do not miss them.  Even in a tribe such as ours - where one's vestments convey station and purpose - the most potent of garb exudes power that simple eyes cannot see.  The prized tunic of the Zandalar madcap is no exception, exuding the raw power of chaos and madness that they are able to channel.\n\nThe Paragons of Power I need lie in Zul'Gurub; bring me what I seek, and I will reward you with your own legendary tunic... one befitting a weaver of madness.", progress = "Welcome back to the Isle, <name>... have you returned triumphantly with the Paragons of Power in tow?", completion = "Impressive... you have accomplished today what few thought was possible.  Your reverence in the tribe is assured for a lifetime, &lt;name&gt;.  You have earned the right to don the madcap's tunic - do so with our blessing.", rewards = "You will receive:\n\nZandalar Madcap's Tunic"}
MultiLanguageQuestData['en'][8074] = {title = "Paragons of Power: The Augur's Belt", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", description = "Augurs know the mojo of the elements, mon.  They use it as a means to guide the tribe to glory.  In the dark days after the Gurubashi Empire ripped itself up, our augurs led us to our safe haven in the South Seas.  They've also led us back here to the Vale, right back to the heart of evil brewin' in Zul'Gurub.\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya a belt that our augurs use - one with powerful mojo inside it!", progress = "The Paragons of Power are what I need mon - we'll tap the power right out of them in our fight against the evil from Zul'Gurub.  Do ya have them for me?", completion = "I can smell the scent of vanquished evil on ya, &lt;name&gt;.  It's a sweet smell mon... one I think you know quite well.\n\nI know it's no small feat to have brought me the Paragons of Power required for the belt.  Your deeds have not only honored the tribe, but also honored yourself amongst my tribe.  Here ya are - take the augur's belt and don it as your own!", rewards = "You will receive:\n\nZandalar Augur's Belt"}
MultiLanguageQuestData['en'][8075] = {title = "Paragons of Power: The Augur's Hauberk", objective = "Bring Maywiki of Zuldazar a Primal Hakkari Tabard. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nMaywiki of Zuldazar is located on Yojamba Isle, Stranglethorn Vale.", description = "The augurs of the Zandalar all wear a distinctive chest piece called a hauberk.  It's fitted with the finest of silks and cloths, interwoven with strong chain.  It's a symbol of not only their divinity, but also of their authority, mon.  It's never wise to cross one whose life is devoted to speakin' with the spirits...\n\nBring me an offerin' of the Paragons of Power from inside Zul'Gurub and prove your worth to us.  Do it and I'll give ya one of the finest hauberks our augurs would ever hope to wear!", progress = "The Paragons of Power are a key source of magic power - the same kind of power that goes into makin' the augur's hauberk.  Bring me what I need, and I'll be able to share the finest of vestments any Zandalar augur would be wantin' as their own.", completion = "I know what ya had to go through to bring me the Paragons of Power, &lt;name&gt;.  It wasn't easy, mon - defeatin' the evil that seeps out of Zul'Gurub like a foul ooze - but now that it is all said and done, I can easily say that you'll be revered amongst the Zandalar for ages to come!\n\nHere - take the augur's hauberk and wear it with pride!", rewards = "You will receive:\n\nZandalar Augur's Hauberk"}
MultiLanguageQuestData['en'][8076] = {title = "Paragons of Power: The Demoniac's Mantle", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Sash. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "The demoniac seeks to embody power outright, not just possess it.  More than one of our demoniacs has lost a fight with a demon; with our enemies threatening us - especially in Zul'Gurub - the power that a demoniac is able to unleash on our foes is worth the sacrifice.  Our survival depends on crushing those who would destroy us; the fall of the Gurubashi Empire taught us this.\n\nTravel to Zul'Gurub and gain the Paragons of Power we need.  Do this, and a valuable demoniac item shall be yours.", progress = "Retrieved the Paragons of Power from Zul'Gurub?  While we will take the latent power from these items and make them our own, we will give you your own reward of power should you be successful...", completion = "Well done, &lt;name&gt;.  The Paragons of Power from Zul'Gurub should act as a reminder of wasted power.  The Gurubashi were strong at their height, but they allowed themselves to be consumed by it.  A demoniac knows that the game they play is much similar, but the power unleashed is often the very thing needed for survival.\n\nUse this mantle as an honored ally of the Zandalar... it will serve you well.", rewards = "You will receive:\n\nZandalar Demoniac's Mantle"}
MultiLanguageQuestData['en'][8077] = {title = "Paragons of Power: The Demoniac's Robes", objective = "Bring Al'tabim the All-Seeing a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nAl'tabim the All-Seeing is located on Yojamba Isle, Stranglethorn Vale.", description = "The ultimate symbol of power amongst the tribe is the garb we wear in battle.  A demoniac's robes have fused fine runecloth and devastatingly powerful mojo into a single fabric.  The visage of the robe is said to instill fear into the minds of all who see it... especially the demons that the demoniac will eventually dominate.\n\nFrom Zul'Gurub, you must bring me a very specific set of the Paragons of Power.  It will be difficult... but your success will assure you of acquiring a robe for yourself.", progress = "The Paragons of Power... you have returned with them?  Only once we have them will we share the ultimate symbol of demoniac power with you, <name>.", completion = "Impressive - your victory in Zul'Gurub has assured us - nay, the world - that Hakkar will not prevail.  The time may come when you face the Blood God directly... and should this come to pass know that your reverence is assured amongst the Zandalar tribe.\n\nOh, and this simple robe should help out too I think.\n\n&lt;Al'tabim winks knowingly at you.&gt;", rewards = "You will receive:\n\nZandalar Demoniac's Robe"}
MultiLanguageQuestData['en'][8078] = {title = "Paragons of Power: The Vindicator's Belt", objective = "Bring Jin'rokh the Breaker a Primal Hakkari Girdle. You must also have a reputation equal to or greater than Honored with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "The ultimate vengeance waits within Zul'Gurub.  Hakkar must not rise again.  Hakkar destroyed the Gurubashi Empire from within.  No sacrifice was enough.  The trolls are a shadow of former glories.  I know this is because of Hakkar.\n\nBecome the vindicator you were meant to be.  Wreak havoc on the minions of evil.  Zul'Gurub must taste Zandalar vengeance.  Bring me proof in the Paragons of Power.  You will receive the vindicator's belt.  You will receive real power.\n\nGo.", progress = "Have you brought the Paragons of Power?  Have you struck down the enemies of the tribe?  Hakkar must know the wrath of the vindicator!", completion = "The way of the vindicator is now known to you.  You have brought honor to the tribe.  You have brought honor to yourself.  You have brought pain to our enemies.\n\nThe vindicator's belt is yours.  You are surely becoming one with the way of the vindicator.", rewards = "You will receive:\n\nZandalar Vindicator's Belt"}
MultiLanguageQuestData['en'][8079] = {title = "Paragons of Power: The Vindicator's Breastplate", objective = "Bring Jin'rokh the Breaker a Primal Hakkari Kossack. You must also have a reputation equal to or greater than Revered with the Zandalar Tribe.\n\nJin'rokh the Breaker is located on Yojamba Isle, Stranglethorn Vale.", description = "The vindicator's symbol of power is the breastplate.  It is forged with powerful mojo.  It is trusted only to those we revere.  It is the Zandalar symbol of vengeance.\n\nTo become a vindicator is to become vengeance.  Take the Paragons of Power we need from Zul'Gurub.  Bring them to us.  We will take the mojo stolen from us.  We will make the minions of Hakkar pay.  We will reward you with the vindicator's breastplate.\n\nGo.  Be our vengeance, <name>.", progress = "Your presence means victory?  Do you have the Paragons of Power?  Tell me of the vengeance you have wrought today!", completion = "You are to be revered for your deeds.  The tribe rewards its heroes.  Zul'Gurub has tasted Zandalar vengeance like never before.\n\nYour deeds will herald the deeds of others to come.  They will look upon you as a sign of real power.  They will look upon you as vengeance personified!", rewards = "You will receive:\n\nZandalar Vindicator's Breastplate"}
MultiLanguageQuestData['en'][8080] = {title = "Arathi Basin Resources!", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8101] = {title = "The Pebble of Kajaro", objective = "<race>, the pebble held within the frame of this talisman comes from Mount Kajaro in the South Seas. Mount Kajaro is an area plagued by volatility - marked by violent and oftentimes magical volcanic eruptions.\n\nAs your bond with the trolls of Zandalar grows, so too shall the power of this pebble. Harness the power of the pebble to strike down our enemies. Be like the mountain: Quick, explosive, deadly...", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nPebble of Kajaro"}
MultiLanguageQuestData['en'][8102] = {title = "The Pebble of Kajaro", objective = "Welcome back, <class>. I can see that the pebble has seen much use. Many of our foes have fallen to your otherworldly abilities. Their suffering has been great. It is time that I enhance the power of the pebble. Give it to me.", description = nil, progress = "Welcome back, <class>. I can see that the pebble has seen much use. Many of our foes have fallen to your otherworldly abilities. Their suffering has been great. It is time that I enhance the power of the pebble. Give it to me.", completion = "Be unstoppable, like the molten fronts of Kajaro.", rewards = "You will receive:\n\nPebble of Kajaro"}
MultiLanguageQuestData['en'][8103] = {title = "The Pebble of Kajaro", objective = "Hakkari fear you, <name>. They speak of horrors they believed that only their faceless God could perpetrate. You have burned them with the force of Kajaro. They now know fear in two places.\n\nIt is time to further strengthen the pebble. Hand me the talisman.", description = nil, progress = "Hakkari fear you, <name>. They speak of horrors they believed that only their faceless God could perpetrate. You have burned them with the force of Kajaro. They now know fear in two places.\n\nIt is time to further strengthen the pebble. Hand me the talisman.", completion = "Continue in your decimation of the trolls of Zul'Gurub. Hakkar must see that the world will not buckle beneath his indomitable will.", rewards = "You will receive:\n\nPebble of Kajaro"}
MultiLanguageQuestData['en'][8104] = {title = "The Jewel of Kajaro", objective = "Give me the talisman, <name>. I must show you something.", description = nil, progress = "Give me the talisman, <name>. I must show you something.", completion = "&lt;Al'tabim shatters the pebble with a powerful unseen force.&gt;\n\nDo you see? The pebble is what we call a geode. Inside the pebble are powerful crystals that have been soaking in the latent energies from our world. By cutting the pebble in half, I have finally allowed its full potential to be realized. Use it to lay waste to our enemies.", rewards = "You will receive:\n\nJewel of Kajaro"}
MultiLanguageQuestData['en'][8105] = {title = "The Battle for Arathi Basin!", objective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", description = "<name>, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.", progress = nil, completion = "I received reports of your exploits in Arathi Basin, &lt;name&gt;.  Well done!  With those like you joining the struggles here, I have faith that we will one day retake our homelands.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8106] = {title = "Kezan's Taint", objective = "Accept this talisman, <class>. Accept it and use its power to strike down our mutual enemies.\n\nKnow that around your neck you carry a piece of history. Kezan was once a grand territory of the Zandalar Empire. Alas, the taint of goblin trade princes would force out my proud brothers and sisters.\n\nKezan is now home to the goblin capital of the Undermine; but know that before the taint, it held greatness. Still to this day Kezan is considered sacred land to my people.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nKezan's Taint"}
MultiLanguageQuestData['en'][8107] = {title = "Kezan's Taint", objective = "Honor is earned amongst the Zandalar trolls, <name>. With honor comes reward - friendship, alliance...\n\nHand me the talisman so that I may enhance its power.", description = nil, progress = "Honor is earned amongst the Zandalar trolls, <name>. With honor comes reward - friendship, alliance...\n\nHand me the talisman so that I may enhance its power.", completion = "Draw from the darkness, &lt;class&gt;. Embrace the shadows. Let Kezan's Taint supplement your dark meddling.", rewards = "You will receive:\n\nKezan's Taint"}
MultiLanguageQuestData['en'][8108] = {title = "Kezan's Taint", objective = "I am ready for you, <class>. Once more I will enhance your talisman. I only ask that you continue in your destruction of Hakkar and his minions.\n\nGive me the talisman.", description = nil, progress = "I am ready for you, <class>. Once more I will enhance your talisman. I only ask that you continue in your destruction of Hakkar and his minions.\n\nGive me the talisman.", completion = "It is only through our combined efforts that we will stop the Soulflayer.", rewards = "You will receive:\n\nKezan's Taint"}
MultiLanguageQuestData['en'][8109] = {title = "Kezan's Unstoppable Taint", objective = "Call forth your demons, <class>. Let them bask in the energy of Kezan's Taint. Command them on the field of battle! Decimate the enemy!\n\nYes... The time has come to apply the final enhancement to Kezan's Taint. Give me the talisman.", description = nil, progress = "Call forth your demons, <class>. Let them bask in the energy of Kezan's Taint. Command them on the field of battle! Decimate the enemy!\n\nYes... The time has come to apply the final enhancement to Kezan's Taint. Give me the talisman.", completion = "Flay the flesh from their corpses. Watch as the shadows consume the Hakkari. Draw power from their fear, &lt;class&gt;. Let Kezan's Taint augment this power...", rewards = "You will receive:\n\nKezan's Unstoppable Taint"}
MultiLanguageQuestData['en'][8110] = {title = "Enchanted South Seas Kelp", objective = "See this here seaweed, mon? It be from the South Seas. We just add a little mojo and a little magic and it takes on the properties most suited to its owner.\n\nYou a <class> so it be easy, mon. Just wrap it around your neck and think of nature or squirrels or whatever it be that you people like.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nEnchanted South Seas Kelp"}
MultiLanguageQuestData['en'][8111] = {title = "Enchanted South Seas Kelp", objective = "Hey mon! It be good to see you again. The tribe be talking about your killin' of the Hakkari and all that. Molthor gave me the word to be adding more mojo to your talisman. Just give it here and Maywiki make it better.", description = nil, progress = "Hey mon! It be good to see you again. The tribe be talking about your killin' of the Hakkari and all that. Molthor gave me the word to be adding more mojo to your talisman. Just give it here and Maywiki make it better.", completion = "The neck piece not be for smokin', mon! You got to use it to fight evil.", rewards = "You will receive:\n\nEnchanted South Seas Kelp"}
MultiLanguageQuestData['en'][8112] = {title = "Enchanted South Seas Kelp", objective = "How be that talisman, mon? It look like it be time to add a little more magic and mojo to its leaves. It need a little bloom in its wilt. Give it here and Maywiki fix it right up.", description = nil, progress = "How be that talisman, mon? It look like it be time to add a little more magic and mojo to its leaves. It need a little bloom in its wilt. Give it here and Maywiki fix it right up.", completion = "Now you take the evil trolls in Zul'Gurub and show them what your nature powers can do, mon!", rewards = "You will receive:\n\nEnchanted South Seas Kelp"}
MultiLanguageQuestData['en'][8113] = {title = "Pristine Enchanted South Seas Kelp", objective = "<name>! It been a long time since I seen you. Did you know that King Rastakhan himself be givin' me the order to add the final bit of mojo and magic to your talisman? It be true, mon! I wouldn't have believed it had I not seen it with me own eyes. Give it here.", description = nil, progress = "<name>! It been a long time since I seen you. Did you know that King Rastakhan himself be givin' me the order to add the final bit of mojo and magic to your talisman? It be true, mon! I wouldn't have believed it had I not seen it with me own eyes. Give it here.", completion = "&lt;name&gt; mon, it been a good journey. Keep on with the killing and suppressing of Hakkar and he minions.", rewards = "You will receive:\n\nPristine Enchanted South Seas Kelp"}
MultiLanguageQuestData['en'][8114] = {title = "Control Four Bases", objective = "Enter Arathi Basin, capture and control four bases at the same time, and then return to Field Marshal Oslight at Refuge Pointe.", description = "<name>, you have taken the battle of Arathi Basin to our enemies and earned great honors in that field of battle.  You have shown us your worth as a <class>, and you have shown our enemies that we will not submit to their villainy!\n\nBecause of your proven value to us, I have a difficult task for you.  I want you to take and hold at least four of the bases in Arathi Basin.  If you can do that, then we will not only secure critical resources, we will show the Horde our dominance!\n\nGo, <name>, and good fortune.", progress = "You have not yet taken four bases, <name>.  Return to Arathi Basin and do as you have been tasked!", completion = "Very good work, &lt;name&gt;!  An excited scout came to me with a report of your exploits.  We in the League of Arathor are very pleased!\n\nYou are swiftly becoming a local hero among the soldiers in the League, and today's deed once again proves your sterling reputation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8115] = {title = "Control Five Bases", objective = "Control 5 bases in Arathi Basin at the same time, then return to Field Marshal Oslight at Refuge Pointe.", description = "<name>, battling for the resources of Arathi Basin is a bloody undertaking.  Your services to the League of Arathor are as needed as they are appreciated.\n\nAnd we have one more task for you.\n\nThe League wishes to make one strong push against the Defilers' occupation of Arathi Basin.  We want them driven out of every strategic point on the battlefield!\n\nIt will not be easy, but if anyone can get it done, it is you.", progress = "You have not yet completed your mission, <name>.  It is difficult, but my faith in you is strong.", completion = "You did it!  You took all of the bases!  Well done, &lt;name&gt;!\n\nThere were those who doubted your chances, but I knew you could do it.  Thank you, and know that the League of Arathor holds you in high regard, just as the Defilers of the Forsaken must fear the very mention of your name!", rewards = "You will receive:\n\nArathor Battle Tabard"}
MultiLanguageQuestData['en'][8116] = {title = "Vision of Voodress", objective = "You and Maywiki have something in common, mon. We both be <class>! Although, Maywiki is more of a mystic and you be more of a scrub. Still, we both know what the great spirits bring.\n\nAs a gift I give to you this orb to wear around your neck. Look deep inside and see the village of Voodress in the South Seas! Let it lift your spirits!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nVision of Voodress"}
MultiLanguageQuestData['en'][8117] = {title = "Vision of Voodress", objective = "Sha-mon! Maywiki make a joke!\n\n<Maywiki laughs.>\n\nSo, you been using the spirits and elements against our enemies in Zul'Gurub, eh? Spirits be praised!\n\nMaywiki gonna brighten your orb. Give it here, <name>.", description = nil, progress = "Sha-mon! Maywiki make a joke!\n\n<Maywiki laughs.>\n\nSo, you been using the spirits and elements against our enemies in Zul'Gurub, eh? Spirits be praised!\n\nMaywiki gonna brighten your orb. Give it here, <name>.", completion = "Take a look at it now, &lt;name&gt;. Voodress come in even clearer now, yea? Let the primal power flow through you, mon.", rewards = "You will receive:\n\nVision of Voodress"}
MultiLanguageQuestData['en'][8118] = {title = "Vision of Voodress", objective = "Good news, <name>. Molthor be singin' your praises lately. He say how you be turnin' into a real hero of Zandalar.\n\nHe also say for Maywiki to polish your orb some more! Give it here so Maywiki can brighten the vision.", description = nil, progress = "Good news, <name>. Molthor be singin' your praises lately. He say how you be turnin' into a real hero of Zandalar.\n\nHe also say for Maywiki to polish your orb some more! Give it here so Maywiki can brighten the vision.", completion = "Beware the evil Hakkari spirits, mon. Honestly, they be spooky.", rewards = "You will receive:\n\nVision of Voodress"}
MultiLanguageQuestData['en'][8119] = {title = "The Unmarred Vision of Voodress", objective = "<Maywiki points to your talisman.>\n\nLook at it, <name>! It's come alive. The spirits dance around the orb.\n\nGive it to Maywiki so she can make one last adjustment.", description = nil, progress = "<Maywiki points to your talisman.>\n\nLook at it, <name>! It's come alive. The spirits dance around the orb.\n\nGive it to Maywiki so she can make one last adjustment.", completion = "One day, &lt;name&gt;, you will be able to use this orb to communicate directly with me. Whenever this battle with Hakkar be over and Maywiki go home. Let us call to the spirits and ask them for that day to come soon.", rewards = "You will receive:\n\nUnmarred Vision of Voodress"}
MultiLanguageQuestData['en'][8120] = {title = "The Battle for Arathi Basin!", objective = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.", description = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, <name>.  Report back to me when this task is complete.", progress = nil, completion = "A Defiler scout came to me with a report of your success, &lt;name&gt;.  Well done.\n\nAs you will learn, to win the battle for Arathi Basin, we must be ever vigilant and crush any attempts at Alliance expansion.  Do this, and our victory here is ensured.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8121] = {title = "Take Four Bases", objective = "Hold four bases at the same time in Arathi Basin, and then return to Deathmaster Dwire in Hammerfall.", description = "<name>, as the battles over Arathi Basin rage, news of your actions have reached many ears.  You are highly regarded among us, which gives me confidence that you will accomplish the mission I now have for you.\n\nIt is time to send a message to the League of Arathor.  We must show them that their holdings in Arathi Basin are tenuous and quickly lost.  We will show them this by holding, all at once, four strategic points in Arathi Basin.\n\nSucceed in this, <name>, and earn great respect among the Defilers.", progress = nil, completion = "Good work, &lt;name&gt;!  Your latest actions in Arathi Basin were quite difficult, and so their successes are quite praiseworthy.  The League of Arathor must be reeling from the last skirmishes in the basin, licking their wounds and, let us hope, rethinking their choice to fight here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8122] = {title = "Take Five Bases", objective = "Hold five bases in Arathi Basin at the same time, then return to Deathmaster Dwire in Hammerfall.", description = "It is difficult to see, so deep we are in the conflict, but our spies report a weakening in the League of Arathor's resolve.  We must use this window and strike a brutal blow against them!  Return to Arathi Basin and throw yourself against our foes.  Curse them and kill them and control all five strategic bases!  Send their soldiers screaming and bleeding from the front lines, with stories of your cruelty on their mewling lips.\n\nDo this, and score a great victory for the Defilers.", progress = nil, completion = "The cries of the Alliance as you and your compatriots attacked them could be heard even from here, &lt;name&gt;.  I can almost pity them for the pain and fear you delivered to their ranks.  Almost, but not quite.\n\nYour value to the Defilers is without question.  Your deeds in Arathi Basin have been most impressive, and have echoed among the chambers of Varimathras... and the Dark Lady herself.", rewards = "You will receive:\n\nBattle Tabard of the Defilers"}
MultiLanguageQuestData['en'][8123] = {title = "Cut Arathor Supply Lines", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8141] = {title = "Zandalarian Shadow Talisman", objective = "You progress swiftly, young <class>. Perhaps it is time to initiate you into the Shera Ali'kh - Zandalari for Death's Hand. For thousands of years we have played the role of assassin for the Zandalar Empire. For too long we have sat idly, allowing the Hakkari to grow in strength. Once more we face Hakkar, but this time without the support of a united troll front. It is you and your allies who must assist in vanquishing the Blood God and his minions!\n\nWear this talisman and let it assist you in your journeys.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nZandalarian Shadow Talisman"}
MultiLanguageQuestData['en'][8142] = {title = "Zandalarian Shadow Talisman", objective = "I sense that you have dealt countless fatalities to the Hakkari, <name>. You carry the stink of their mojo.\n\nI assume the Shadow talisman has assisted in the culling? Give it to me and allow me to enhance its power.", description = nil, progress = "I sense that you have dealt countless fatalities to the Hakkari, <name>. You carry the stink of their mojo.\n\nI assume the Shadow talisman has assisted in the culling? Give it to me and allow me to enhance its power.", completion = "An assassin of your caliber should be given a wide berth. Your foes must learn respect! You will get just that when the enemy sees the glint of Death's Hand - all too late...", rewards = "You will receive:\n\nZandalarian Shadow Talisman"}
MultiLanguageQuestData['en'][8143] = {title = "Zandalarian Shadow Talisman", objective = "Impressive, <name>. You have a gift for killing that I have not sensed in another in many years. Even Molthor is aware of the work that you have done for Zandalar. It is time to enhance your talisman further. Give it to me.", description = nil, progress = "Impressive, <name>. You have a gift for killing that I have not sensed in another in many years. Even Molthor is aware of the work that you have done for Zandalar. It is time to enhance your talisman further. Give it to me.", completion = "There is only one enhancement left that can be placed on the talisman, &lt;class&gt;. When the time is right, I shall apply that enhancement.", rewards = "You will receive:\n\nZandalarian Shadow Talisman"}
MultiLanguageQuestData['en'][8144] = {title = "Zandalarian Shadow Mastery Talisman", objective = "It yearns to grow, <name>. The talisman has soaked in all that you have done. The thousands of troll corpses littering Zul'Gurub have fueled its power. Hand it to me and I shall make the final enhancement.", description = nil, progress = "It yearns to grow, <name>. The talisman has soaked in all that you have done. The thousands of troll corpses littering Zul'Gurub have fueled its power. Hand it to me and I shall make the final enhancement.", completion = "This is the last time we will speak under the auspices of Shera Ali'kh. You know all that you must. Take the talisman and continue in your slaying. Hakkar must never be allowed to leave Zul'Gurub.", rewards = "You will receive:\n\nZandalarian Shadow Mastery Talisman"}
MultiLanguageQuestData['en'][8145] = {title = "The Maelstrom's Tendril", objective = "Amongst the Zandalarians, the profession of <class> is revered. Our greatest hunters travel to the edge of the Maelstrom to prove their resolution.\n\nFrom the heart of the sea they pull strands of kelp known as Maelstrom Tendrils. The kelp is then woven into a talisman that is enchanted to improve their accuracy and power.\n\nI now grant you a single weaving of the Maelstrom's Tendril. As your bond with Zandalar grows, I shall weave more power into the talisman.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nMaelstrom's Tendril"}
MultiLanguageQuestData['en'][8146] = {title = "The Maelstrom's Tendril", objective = "Ah, <name>, it is good to smell you again.\n\n\n\nYou'll have to excuse my sense of humor. It can be most foul at times.\n\nI sense that you have caused great anguish to our enemies. The forces of Hakkar cry out your name in anger. This is most excellent.\n\nYou have earned another weave on your talisman. Hand it to me.", description = nil, progress = "Ah, <name>, it is good to smell you again.\n\n\n\nYou'll have to excuse my sense of humor. It can be most foul at times.\n\nI sense that you have caused great anguish to our enemies. The forces of Hakkar cry out your name in anger. This is most excellent.\n\nYou have earned another weave on your talisman. Hand it to me.", completion = "Let them seek atonement at the end of your munitions.", rewards = "You will receive:\n\nMaelstrom's Tendril"}
MultiLanguageQuestData['en'][8147] = {title = "The Maelstrom's Tendril", objective = "Even from here I can hear the sound of your volleys laying waste to our enemies. Their cries echo in agony.\n\nYou have made quite a name for yourself among the trolls of Zandalar, <name>. We are grateful for all that you have done.\n\nHand me your talisman so that I may add another weave.", description = nil, progress = "Even from here I can hear the sound of your volleys laying waste to our enemies. Their cries echo in agony.\n\nYou have made quite a name for yourself among the trolls of Zandalar, <name>. We are grateful for all that you have done.\n\nHand me your talisman so that I may add another weave.", completion = "There is only one more weave that I will be able to add to your talisman, &lt;class&gt;.", rewards = "You will receive:\n\nMaelstrom's Tendril"}
MultiLanguageQuestData['en'][8148] = {title = "Maelstrom's Wrath", objective = "Molthor delivers word from King Rastakhan, <name>. The royal court is most impressed with your decimation of the Hakkari forces. I am to award you with the final weave in your talisman. Hand it to me.", description = nil, progress = "Molthor delivers word from King Rastakhan, <name>. The royal court is most impressed with your decimation of the Hakkari forces. I am to award you with the final weave in your talisman. Hand it to me.", completion = "Your journey has only just begun, young &lt;class&gt;. Perhaps one day you will visit the Maelstrom and glance into the heart of the world.\n\nI wish you power and fortitude!", rewards = "You will receive:\n\nMaelstrom's Wrath"}
MultiLanguageQuestData['en'][8149] = {title = "Honoring a Hero", objective = "Travel to Uther's Tomb in Western Plaguelands and use Uther's Tribute at his statue, and then return to Wagner Hammerstrike outside Ironforge before the Harvest Festival is over.\n\nProvided item: \n", description = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Alliance acknowledges many heroes, but none weave a more tragic tale than that of Uther Lightbringer.\n\nHelp us honor Uther by taking this offering to his tomb in the Western Plaguelands.  Place it at his statue, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Uther his tribute.", progress = "Have you made the journey to Uther's Tomb and placed the tribute there?\n\nIt can be a dangerous trip for less experienced adventurers; a safer way of traveling there, relatively speaking, may be to travel north from the river that runs through Hillsbrad into the Plaguelands.  It flows from a lake that is adjacent to Sorrow Hill; travel west up through the hills, steering clear of the adjacent tomb... one that is infested with the Scourge.", completion = "He was a hero among heroes, Uther was.  I can't even begin to imagine the anguish of what he felt when Arthas - his greatest student and someone whom Uther loved like his own son - betrayed all of humanity.  Still, he rose to try and stop Arthas, and for that he will be forever remembered as a true paladin.  His fight was to the end, thinking only of those he might save.\n\nThank you, &lt;name&gt;.  You've paid tribute to a great hero today, honoring his spirit and the spirit of the Harvest Festival.", rewards = "You will receive:\n\nFor the Light!"}
MultiLanguageQuestData['en'][8150] = {title = "Honoring a Hero", objective = "Travel to Grom's Monument in the Demon Fall Canyon of Ashenvale and use Grom's Tribute at the base of the monument. Return to Javnir Nashak outside Orgrimmar before the Harvest Festival is over.\n\nProvided item: \n", description = "During the Harvest Festival of Azeroth, we give thanks to heroes for the sacrifices - in some cases ultimate sacrifices - they have given on our behalf.  The Horde acknowledges many heroes, but none exemplify strength and sacrifice more than Grom Hellscream.\n\nHelp us honor Grom by taking this offering to his monument in the Demon Fall Canyon of Ashenvale.  Place it at the base, and then return to me.  I'll only be here through the end of the festival, so waste no time in giving Grom his tribute.", progress = "Have you made the journey to Grom's Monument and placed his tribute there?\n\nThe site where the monument is still touched by the taint of the Burning Legion.  Should you be less experienced in the ways of adventuring, be on your toes when approaching the monument.", completion = "Grom's full name - Grommash - means \"The Giant's Heart\"; it took that and more to stand alone against Mannoroth.  I think the Warchief said it best when the curse of the orcs began and ended with Grom.  Fitting that Grom's sacrifice - and perhaps redemption - would be the wellspring from which the Horde flows today.\n\nThank you, &lt;name&gt;.  You've paid tribute to a great hero today, honoring his spirit and the spirit of the Harvest Festival.", rewards = "You will receive:\n\nThe Horde's Hellscream"}
MultiLanguageQuestData['en'][8151] = {title = "The Hunter's Charm", objective = "Speak to Ogtinc in Azshara.", description = "Ogtinc of Azshara has sent out a call for seasoned hunters such as yourself.  He is a furbolg hunter who has left his tribe to aid the Cenarion Circle.  His teachings are meant to enrich the wisdom of others who share his craft, and guide them toward maintaining a balance.  You would do well to speak with him.\n\nOgtinc resides atop the cliffs of Azshara, northeast from the Ruins of Eldarath.", progress = nil, completion = "It is no longer my purpose to hunt, but to teach the &lt;class&gt;.  That is what fate has handed to me.\n\nCraft with me a &lt;class&gt;'s charm -- a collection of trophies from fallen prey that will remind you of your past trials and triumphs.  In the end I will keep the charm, but reward you with something else.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8153] = {title = "Courser Antlers", objective = "Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath.", description = "The courser wears the mightiest antlers in the known lands.  Such antlers are used to defend the courser, goring an attacker and often damaging the points.  Perfect, natural antlers are the sign of an animal spirit with supreme confidence.\n\nTo hold such antlers will bestow the same confidence in you.\n\nHunt the mosshoof courser, find the perfect antlers and bring them to me.", progress = "Have you found the antlers?", completion = "You must possess keen sight and great patience to have obtained these.  Well done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8154] = {title = "Arathi Basin Resources!", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8155] = {title = "Arathi Basin Resources!", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8156] = {title = "Arathi Basin Resources!", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8160] = {title = "Cut Arathor Supply Lines", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8161] = {title = "Cut Arathor Supply Lines", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8162] = {title = "Cut Arathor Supply Lines", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8166] = {title = "The Battle for Arathi Basin!", objective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", description = "<name>, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8167] = {title = "The Battle for Arathi Basin!", objective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", description = "<name>, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.", progress = nil, completion = "I received reports of your exploits in Arathi Basin, &lt;name&gt;.  Well done!  With those like you joining the struggles here, I have faith that we will one day retake our homelands.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8168] = {title = "The Battle for Arathi Basin!", objective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", description = "<name>, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8169] = {title = "The Battle for Arathi Basin!", objective = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.", description = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, <name>.  Report back to me when this task is complete.", progress = nil, completion = "A Defiler scout came to me with a report of your success, &lt;name&gt;.  Well done.\n\nAs you will learn, to win the battle for Arathi Basin, we must be ever vigilant and crush any attempts at Alliance expansion.  Do this, and our victory here is ensured.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8170] = {title = "The Battle for Arathi Basin!", objective = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.", description = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, <name>.  Report back to me when this task is complete.", progress = nil, completion = "A Defiler scout came to me with a report of your success, &lt;name&gt;.  Well done.\n\nAs you will learn, to win the battle for Arathi Basin, we must be ever vigilant and crush any attempts at Alliance expansion.  Do this, and our victory here is ensured.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8171] = {title = "The Battle for Arathi Basin!", objective = "Assault the Arathi Basin mine, lumber mill, blacksmith and stable, and then return to Deathmaster Dwire in Hammerfall.", description = "As you no doubt have heard, the League of Arathor is sending large numbers of troops into Arathi Basin.  Eager for food and supplies, these Alliance fools are intent to take and control the rich resources there.  We must show them that Arathi will never again be a home for humans!\n\nGo to Arathi Basin and assault the mine, the lumber mill, the blacksmith and the stables.  Pull down the enemies' banners, declaring those territories for the Horde.\n\nGo, <name>.  Report back to me when this task is complete.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8181] = {title = "Confront Yeh'kinya", objective = "Speak with Yeh'kinya.", description = "My delvings into the Mosh'aru Tablets bear grim news, <name>.  Hakkar's true form, the god himself, can be born again through the very egg into which you captured him.  Yeh'kinya told you it was to contain his evil, but it is to recreate it!  The troll has led you astray!\n\nGo to Yeh'kinya and demand the egg from him.  Pray that it is not too late to stop Hakkar's return!", progress = nil, completion = "So, you have been speaking with that old dwarf Ironboot and uncovered the lost Mosh'aru Tablets, have you?  That meddling prospector...\n\nNo matter.  It is too late to save this world.  Hakkar has been reborn, and even now grows in power... deep in the ancient troll kingdom of Zul'Gurub!  He has come!  And he will rule in blood and terror!\n\nThank you, &lt;name&gt;.  Your help has sped the return of the Soulflayer!", rewards = "You will be able to choose one of these rewards:\n\nFaded Hakkari CloakTattered Hakkari Cape\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8182] = {title = "The Hand of Rastakhan", objective = "Speak with Molthor in Stranglethorn.", description = "<name>, our worst fears have come.  Legend speaks of the Soulflayer ruling the ancient troll world through evil and terror, and his power was absolute.  If he cannot be stopped now, then his new reign may spread across all of Azeroth!\n\nThere is a contingent of Zandalarian trolls who may help us stem this tide of darkness.  They have camped on Yojamba Isle, off the coast of Stranglethorn, west of the ruins of Zul'Kunda.  Speak with their leader, Molthor, and pray he knows how to defeat Hakkar.", progress = nil, completion = "You were sent by the prospector, Ironboot?  His kind are wise, and wiser still to bring you to me, for I and the Zandalarian trolls may know a way to defeat the Soulflayer.\n\nSpeak with the trolls of this isle, heed their words, and prepare yourself, &lt;name&gt;, for the task before you is soaked in blood.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8183] = {title = "The Heart of Hakkar", objective = "Bring the Heart of Hakkar to Molthor on Yojamba Isle.", description = "The Heart of Hakkar burns from within.  Although the Soulflayer is defeated, the kernel of his power yet remains in this cursed organ.", progress = "<name>, the reek of an evil soul surrounds you.  Have you been cursed by the Soulflayer?", completion = "Ah, the Heart of Hakkar.  So the Soulflayer has been slain!  Our world is saved!\n\n&lt;name&gt;, your service to us cannot be overstated.  You truly are a hero of this realm!", rewards = "You will be able to choose one of these rewards:\n\nZandalarian Hero BadgeZandalarian Hero CharmZandalarian Hero Medallion\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8184] = {title = "Presence of Might", objective = "Zanza can create the ancient troll enchantments with the right components.\n\nThe first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo piles.\n\nBring me these things and I will create a powerful enchantment for you!", description = nil, progress = "Zanza can create the ancient troll enchantments with the right components.\n\nThe first is a primal Hakkari idol that must be taken from the most powerful of the Hakkari lieutenants: Jin'do and the Bloodlord.\n\nThe second is a punctured voodoo doll. These can be found in the piles of refuse that litter this foul place. Look inside the jinxed hoodoo piles.\n\nBring me these things and I will create a powerful enchantment for you!", completion = "Use it well, &lt;class&gt;. Show the Hakkari no mercy!", rewards = "You will receive:\n\nPresence of Might"}
