MultiLanguageQuestData['en'][8382] = {title = "Armaments of War", objective = "War comes, <name>, and with it comes untold horrors. You have done all that could be asked of you and for that you should be rewarded.\n\nShould this... this prophecy ever come to pass...\n\n\n\nThe future of us all could be at an end.\n\nThese armaments will prove invaluable to your campaign in this desert.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nCenarion Reservist's LeggingsSandstorm Boots"}
MultiLanguageQuestData['en'][8383] = {title = "Remember Alterac Valley!", objective = "The Battle in Alterac Valley rages on, <name>!  Have you done your part as of late, <name>?", description = nil, progress = "The Battle in Alterac Valley rages on, <name>!  Have you done your part as of late, <name>?", completion = "You continue to honor the Alliance, &lt;name&gt;.  The Horde will be crushed before long if we keep our efforts up.", rewards = "The following spell will be cast on you:\n\nHonor Points +398"}
MultiLanguageQuestData['en'][8384] = {title = "Claiming Arathi Basin", objective = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", description = nil, progress = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, &lt;class&gt;!  Your efforts will help to provide the Alliance with the resources it needs.", rewards = "The following spell will be cast on you:\n\nHonor Points +82"}
MultiLanguageQuestData['en'][8385] = {title = "Concerted Efforts", objective = "Ah, <name>.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", description = nil, progress = "Ah, <name>.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", completion = "You live up to yer reputation, &lt;name&gt;.  Without people like you, the Alliance wouldn't stand a chance against the savage forces of the Horde.", rewards = nil}
MultiLanguageQuestData['en'][8386] = {title = "Fight for Warsong Gulch", objective = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", description = nil, progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", completion = "Good work, &lt;name&gt;.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.", rewards = "The following spell will be cast on you:\n\nHonor Points +50"}
MultiLanguageQuestData['en'][8387] = {title = "Invaders of Alterac Valley", objective = "The battle for Alterac rages on!  You must return to Alterac Valley and once more drive the invaders out of Frostwolf territory, <name>!", description = nil, progress = "The battle for Alterac rages on!  You must return to Alterac Valley and once more drive the invaders out of Frostwolf territory, <name>!", completion = "Good work, &lt;name&gt;!  You should be proud of yourself.  The Alliance invaders must be expelled from Alterac!", rewards = "The following spell will be cast on you:\n\nHonor Points +398"}
MultiLanguageQuestData['en'][8388] = {title = "For Great Honor", objective = "Many brave fighters look up to you, <name>.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", description = nil, progress = "Many brave fighters look up to you, <name>.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", completion = "You continue to honor the Horde, &lt;name&gt;.  I'm glad to see you haven't turned soft.", rewards = nil}
MultiLanguageQuestData['en'][8389] = {title = "Battle of Warsong Gulch", objective = "The battle in Warsong Gulch rages on, <name>.  Do your part to drive the Silverwing Sentinels out of our lands!", description = nil, progress = "The battle in Warsong Gulch rages on, <name>.  Do your part to drive the Silverwing Sentinels out of our lands!", completion = "Well done, &lt;class&gt;!  You've helped ensure the Horde's ownership over Warsong Gulch!", rewards = "The following spell will be cast on you:\n\nHonor Points +50"}
MultiLanguageQuestData['en'][8390] = {title = "Conquering Arathi Basin", objective = "The war against the Alliance scum demands resources, <name>! We cannot allow our stockpiles to run dry in the middle of a battle.  Continue to ensure Arathi Basin remains in our hands!", description = nil, progress = "The war against the Alliance scum demands resources, <name>! We cannot allow our stockpiles to run dry in the middle of a battle.  Continue to ensure Arathi Basin remains in our hands!", completion = "Excellent work, &lt;name&gt;!  As long as Arathi Basin stays under our control our supplies will be well stocked.", rewards = nil}
MultiLanguageQuestData['en'][8391] = {title = "Claiming Arathi Basin", objective = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", description = nil, progress = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, &lt;class&gt;!  Your efforts will help provide the Alliance with the resources it needs.", rewards = "The following spell will be cast on you:\n\nHonor Points +138"}
MultiLanguageQuestData['en'][8392] = {title = "Claiming Arathi Basin", objective = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", description = nil, progress = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, &lt;class&gt;!  Your efforts will help provide the Alliance with the resources it needs.", rewards = nil}
MultiLanguageQuestData['en'][8393] = {title = "Claiming Arathi Basin", objective = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, <name>.", progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.", rewards = "The following spell will be cast on you:\n\nHonor Points +138\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8394] = {title = "Claiming Arathi Basin", objective = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, <name>.", progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.", rewards = "The following spell will be cast on you:\n\nHonor Points +228\n\nYou will receive:\n\n"}
