MultiLanguageQuestData['en'][8396] = {title = "Claiming Arathi Basin", objective = "Bring 3 Arathi Basin Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "Winning a war is about more than just outsmarting and outfighting your opponent.  Victory often comes down to simply producing more than your enemy.\n\nWhat we have in Arathi Basin is a sizeable supply of resources for whichever side manages to claim it first.\n\nIf the Alliance comes out victorious, it'll mean more swords and pikes for our troops.  If the Horde were to win, those swords and pikes would still get made, they'd just be pointed at us!  Now is the time to help the Alliance in Arathi Basin, <name>.", progress = "Tell me, what are the news from the front?", completion = "Good work, soldier!  Keep it up and we'll have the Horde running all the way back to Orgrimmar.", rewards = "The following spell will be cast on you:\n\nHonor Points +398\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8397] = {title = "Claiming Arathi Basin", objective = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", description = nil, progress = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, &lt;class&gt;!  Your efforts will help provide the Alliance with the resources it needs.", rewards = "The following spell will be cast on you:\n\nHonor Points +378"}
MultiLanguageQuestData['en'][8398] = {title = "Claiming Arathi Basin", objective = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", description = nil, progress = "The war against the Horde is quickly depleting our supplies, <name>.  It is vital to maintain control of Arathi Basin to keep the stream of resources flowing!  Have you lent a hand in Arathi yet?", completion = "Excellent work, &lt;class&gt;!  Your efforts will help provide the Alliance with the resources it needs.", rewards = "The following spell will be cast on you:\n\nHonor Points +398"}
MultiLanguageQuestData['en'][8399] = {title = "Fight for Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, <name>!  For the Alliance!", progress = "You've come back with news from the front, <name>?", completion = "Good work, &lt;name&gt;.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.", rewards = "The following spell will be cast on you:\n\nHonor Points +82\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8400] = {title = "Fight for Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, <name>!  For the Alliance!", progress = "You've come back with news from the front, <name>?", completion = "Well done, &lt;name&gt;!  You've served the Alliance well.", rewards = "The following spell will be cast on you:\n\nHonor Points +138\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8401] = {title = "Fight for Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than the preservationist philosophy the Silverwings espouse.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.  Do your part in fighting the Warsong Outriders!  For the Alliance!", progress = "You've come back with news from the front, <name>?", completion = "Well done, &lt;name&gt;!  You've served the Alliance well.", rewards = "The following spell will be cast on you:\n\nHonor Points +228\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8402] = {title = "Fight for Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, <name>!  For the Alliance!", progress = "You've come back with news from the front, <name>?", completion = "Well done, &lt;name&gt;!  You've served the Alliance well.", rewards = "The following spell will be cast on you:\n\nHonor Points +378\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8403] = {title = "Fight for Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to an Alliance Brigadier General outside the battlegrounds.", description = "The Silverwing Sentinels are at war with the Warsong Outriders due to the destruction the Orcs are causing to the forest.  There are, however, more reasons to defend this particular forest than plain love for nature.\n\nThe forest forms a strategic barrier that makes Ashenvale defendable against a large-scale attack.  Without it, Astranaar would last a day or two before being annexed to the Barrens.\n\nDo your part in fighting the Warsong Outriders, <name>!  For the Alliance!", progress = "You've come back with news from the front, <name>?", completion = "Well done, &lt;name&gt;!  You've served the Alliance well.", rewards = "The following spell will be cast on you:\n\nHonor Points +398\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8404] = {title = "Fight for Warsong Gulch", objective = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", description = nil, progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", completion = "Good work, &lt;name&gt;.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.", rewards = "The following spell will be cast on you:\n\nHonor Points +82"}
MultiLanguageQuestData['en'][8405] = {title = "Fight for Warsong Gulch", objective = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", description = nil, progress = "Don't forget the fight for Warsong Gulch is about more than just protecting trees.  It's about keeping a natural barrier between Ashenvale and the Barrens.  Do you bring any news from the battlefield, <name>?", completion = "Good work, &lt;name&gt;.  Thanks to you, our natural defenses in Ashenvale will remain intact for another day.", rewards = "The following spell will be cast on you:\n\nHonor Points +138"}
