MultiLanguageQuestData['en'][8409] = {title = "Ruined Kegs", objective = "Return to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade.", description = "The rotten eggs have been successfully placed inside the keg.  Future batches of ale from the Southshore Inn are sure to be ruined!\n\nYou should now report back to Darkcaller Yanka at the Wickerman Festival in Tirisfal Glade and report your success.", progress = nil, completion = "Ah, success!  You've shown true Hallow's End spirit - FORSAKEN spirit, I should say!\n\n&lt;Darkcaller Yanka laughs and rubs her hands together.&gt;\n\nI revel in the fact that Southshore must now feast on bad ale or go without!  As for you, take these treats.  I believe you will find good use for them!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][8410] = {title = "Elemental Mastery", objective = "Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher.", description = "Bath'rah the Windwatcher has sent out a summons for a shaman of your wisdom.  He requests you bring a sample of each of the elements to show you are ready.\n\nTo find Bath'rah, go to the river east of Tarren Mill.  Follow the river north until you come across the ruins where Bath'rah resides.", progress = "What you got for me, <class>?", completion = "Excellent, mon.  Now we be talkin'.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8411] = {title = "Mastering the Elements", objective = "Bring the elements earth, air, fire and water to Bath'rah the Windwatcher.", description = "Welcome, <class>.  You bring me the elements and then we do the talkin'.\n\nThe fire, the air, the water, and the earth I be needin' before I trust ya, mon.  I gots to know you be knowledgeable.", progress = "Where's the elements, mon?", completion = "These be the elements I need.  Now we talk.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8412] = {title = "Spirit Totem", objective = "Bring the pieces for the spirit totem to Bath'rah the Windwatcher.", description = "The elemental spirits of this place don't be likin' me any more.\n\nYou know about the totems more than any, and I be needin' a spirit totem to protect me.  We already got the elements, now we need somethin' more with more nature.  More primal.\n\nIn the Western Plaguelands you can kill bears for claws and spiders for their eyes.  The carrion birds eat everything, so they might have either one.", progress = "The spirits know what we're up to, and they been tryin' to kill me!  I hope you got the parts.", completion = "Great, mon!  Let's try it out....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8413] = {title = "Da Voodoo", objective = "Bring the voodoo feathers to Bath'rah the Windwatcher.", description = "The spirit totem just isn't enough.  We be needin' some voodoo magic to make it work jus' right.\n\nThe trolls in the sunken temple have feathers strong with voodoo magics.  Go there and kill Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Then we have magic enough for a real spirit totem.", progress = "Where's the feathers, mon?", completion = "It's about time this troll got a full night's rest!  The spirit totem will watch over me.\n\nI been a long time collectin' things, maybe you want somethin' for all your trouble?", rewards = "You will be able to choose one of these rewards:\n\nAzurite FistsEnamored Water SpiritWildstaff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8414] = {title = "Dispelling Evil", objective = "Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands.", description = "Greetings, <class>.  Crusaders like you are a welcome sight in these desolate reaches.\n\nYour holy strength is needed to help fight the endless undead here.  We need you to collect a large number of scourgestones and bring them to High Priest Thel'danis.  The high priest can be found guarding Uther's Tomb in Sorrow Hill, not far from here.\n\nOnly one with an Argent Dawn Commission can hope to find scourgestones, so speak to Officer Pureheart if you haven't already.", progress = "What evil have you brought me?", completion = "There is risk in dispelling the evil from a scourgestone, for it attracts the attention of undead for countless miles.  But you are strong in the Light, &lt;name&gt;, and I do not fear for you...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8415] = {title = "Chillwind Camp", objective = "Speak to Commander Ashlam Valorfist at Chillwind Camp.", description = "Commander Ashlam Valorfist has sent out a call for a paladin of your purity and valor, <name>.  You can find him at Chillwind Camp in the southern part of the Western Plaguelands.  Seek him and aid in his cause for the Light!", progress = nil, completion = "Very well, &lt;class&gt;!  Let's see what you're made of.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8416] = {title = "Inert Scourgestones", objective = "Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point.", description = "The evil has been purged from the stones, <name>.\n\nI am aware of Commander Ashlam's plans, and he will require only a single inert stone.  Bring it to him so we may bathe the Scourge in righteous fire.", progress = "Was Thal'danis able to cleanse the scourgestones?", completion = "You have done as I asked without question, &lt;name&gt;.\n\nTrust is achieved, it seems.  Perhaps I can reveal our plan in more detail to you now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8417] = {title = "A Troubled Spirit", objective = "Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands.", description = "In the Blasted Lands, there is a troubled spirit who was once a great hero of the horde.  A warrior's honor does not die with the body, and it would serve you well to speak with him.", progress = nil, completion = "So, you have come to alleviate my pain.  I wish you could simply strike me down, but it is not that simple...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8418] = {title = "Forging the Mightstone", objective = "Bring the voodoo feathers to Ashlam Valorfist.", description = "Now we must combine the inert scourgestones and create a weapon to shatter the ranks of undead.  This is no trivial task, <name>.  Only the trolls of the sunken temple carry the kind of rare magic able to turn the evil of something against itself.\n\nIn the temple, the trolls are known as Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Do not feel remorse for their corrupt souls... they are not without evil.", progress = "Have you slain the wretched trolls?", completion = "This is excellent, &lt;name&gt;.  I would say I am surprised, but I knew without question that you wouldn't let us down.\n\nIt is my honor to bestow one of the Holy Mightstones to you.  Use it well.", rewards = "You will be able to choose one of these rewards:\n\nLightforged BladeSanctified OrbChivalrous Signet\n\nYou will also receive:\n\nHoly Mightstone"}
MultiLanguageQuestData['en'][8419] = {title = "An Imp's Request", objective = "Bring a piece of felcloth to Impsy in Felwood.", description = "<name>, an imp in Felwood by the name of Impsy has requested your presence.  It is somewhat strange, as he has asked that you bring a piece of felcloth as a sign of good faith.  Considering the power you already wield as a warlock, I can only assume you know the satyrs of Felwood carry this felcloth.\n\nYou can find Impsy just north of the Bloodvenom Falls, which I've heard is quite lovely this time of year.", progress = "Do you have my felcloth?", completion = "What a splendid &lt;class&gt; you are!\n\n\n\nOh how I love the feel of it, the way it burns your skin and weaves evil thoughts through the mind...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8420] = {title = "Hot and Itchy", objective = "Bring a piece of felcloth to Impsy in Felwood.", description = "Maybe this sounds strange coming from an imp, but I'd like a pet of my own.  I really would.  It's just not fair that Niby gets me and I get nothing!\n\nIn fact, it doesn't even need to be a living pet.  I'd need something to start making it with, like some felcloth.  The satyrs here in Felwood sometimes have felcloth, so you'd just have to kill enough of them until you find some.  That doesn't sound so bad, does it?", progress = "Do you have my felcloth?", completion = "Wow!  You are too kind.  Especially for a &lt;class&gt;!\n\n\n\nOh how I love the feel of it, the way it burns your skin and weaves evil thoughts through the mind...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8421] = {title = "The Wrong Stuff", objective = "Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood.", description = "Now that I have my felcloth, I can really begin making *my* pet.\n\nIt's going to need some eyes though.  Perhaps you could rip some rotting wood from the irontree folk for me, so I can carve out some lovely eyes.  They're up north in the Irontree Woods.\n\nI'll also need some bloodvenom essence to give it that new demon smell.  The tainted oozes carry the essence, and they hang out right here near Niby and me.", progress = "Do you have the goods?", completion = "This will work so very well.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8422] = {title = "Trolls of a Feather", objective = "Bring a total of 6 Voodoo Feathers from the trolls in sunken temple.", description = "My pet is almost done.  Now I just need something to stuff it with.\n\nOnly the voodoo feathers from the trolls in the sunken temple will do.  They go by the names Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  Kill them.  Kill them all.\n\nThis is no trivial task <name>, so I'll make it worth your while by giving you something of Niby's -- he probably doesn't need it anyhow.", progress = "Did you bring the feathers?  This doll needs stuffed!", completion = "Wonderful, now my pet is complete!\n\n&lt;Impsy quickly stuffs the doll and gives it a demonic hug.&gt;\n\nOh, what an odd side effect these voodoo feathers have...", rewards = "You will be able to choose one of these rewards:\n\nSoul HarvesterAbyss ShardRobes of Servitude\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8423] = {title = "Warrior Kinship", objective = "Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde.", description = "<The Hero looks you over.>\n\nYou are a <class>, no doubt.  I would ask an honorable task of you, but I must test your strength.\n\nIt is said that Rexxar would measure the sharpness of his blades by killing a helboar with a single, swift strike.  Now I will measure your strength by killing them.", progress = "The burning spines of the helboar leave horrific scars.  Do not fear the pain and disfigurement, <class>, they are nothing compared to the prison to which I am bound.", completion = "I need no proof to know what you have done, &lt;class&gt;.  I can see the determination etched in your expression.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8424] = {title = "War on the Shadowsworn", objective = "Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde.", description = "The continued presence of the shadowsworn in the Blasted Lands bring great pain to me.  Their dark rituals and spells cause agony unlike any I felt while alive.\n\nThrough you I can deliver my own message of pain.  Go forth and deliver my wrath.", progress = "The shadowsworn are not easily defeated, are they?  But you are a <class>, and you will triumph or perish trying.", completion = "Already you have subdued my pain and honored me.  Thank you, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8425] = {title = "Voodoo Feathers", objective = "Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde.", description = "Your honor has brought some peace to me.  It is only right that I offer you something in return.\n\nMy weapons and armor were splendid in life, and yet they are of no use to me now.  They would be better served in your possession.\n\nTravel to the sunken temple and destroy the troll guardians Gasher, Mijan, Zolo, Hukku, Zul'lor, and Loro.  They carry magic feathers that can reform my physical body long enough to grant you a reward.", progress = "Are you back so soon?  Time is not the same to me any more, perhaps it has indeed been a long journey for you...", completion = "At last I can feel the cold touch of steel again, even if only for a moment.", rewards = "You will be able to choose one of these rewards:\n\nFury VisorDiamond FlaskRazorsteel Shoulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8426] = {title = "Battle of Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!", progress = "Do you bear news from Warsong Gulch, <name>?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", rewards = "The following spell will be cast on you:\n\nHonor Points +82\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8427] = {title = "Battle of Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!", progress = "Do you bear news from Warsong Gulch, <name>?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", rewards = "The following spell will be cast on you:\n\nHonor Points +138\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8428] = {title = "Battle of Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!", progress = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", rewards = "The following spell will be cast on you:\n\nHonor Points +228\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8429] = {title = "Battle of Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!", progress = "Do you bear news from Warsong Gulch, <name>?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", rewards = "The following spell will be cast on you:\n\nHonor Points +378\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8430] = {title = "Battle of Warsong Gulch", objective = "Bring 3 Warsong Gulch Marks of Honor to a Horde Warbringer outside the battlegrounds.", description = "The battle in Warsong Gulch against the Silverwing Sentinels is of great importance.  Under the guise of protecting a forest that doesn't belong to them, the Alliance seeks to deny the Horde one of our largest sources for lumber.\n\nDo not let this happen, <name>!  Come back to me with proof of serving the Horde in a worthy manner!", progress = "Do you bear news from Warsong Gulch, <name>?", completion = "Excellent!  You've shown your worth by defending our operations in Warsong Gulch!  May word of your honor spread far and wide across our lands.", rewards = "The following spell will be cast on you:\n\nHonor Points +398\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8431] = {title = "Battle of Warsong Gulch", objective = "The battle in Warsong Gulch rages on, <name>.  Do your part to drive the Silverwing Sentinels out of our lands!", description = nil, progress = "The battle in Warsong Gulch rages on, <name>.  Do your part to drive the Silverwing Sentinels out of our lands!", completion = "Well done, &lt;class&gt;!  You've helped ensure the Horde's ownership over Warsong Gulch!", rewards = "The following spell will be cast on you:\n\nHonor Points +82"}
