MultiLanguageQuestData['en'][8687] = {title = "Target: Hive'Zora Tunnelers", objective = "Slay 30 Hive'Zora Tunnelers and report back to Commander Mar'alith at Cenarion Hold in Silithus. You must also bring Combat Task Briefing VII in order to complete this quest.", description = "Reinforcements have been called on to join the assault on Hive'Zora.  You have been selected to target Hive'Zora tunnelers.  Report back to Commander Mar'alith after completing your task.", progress = "You have something to tell me, <class>?", completion = "Excellent work, &lt;name&gt;.  Without their tunnelers, the silithid will have a hard time repairing any damage inflicted to their hive's structure.  I assume you'll want a new task.", rewards = "You will receive:\n\nCenarion Combat Badge"}
MultiLanguageQuestData['en'][8688] = {title = "Windrun the Elder", objective = "The heavens, in their countless stars, hold answers to earthly mysteries, <name>.  Might, then, the wise, and the lucky, gaze up and find truth?", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nForce Self - Bow\n\nYou will receive:\n\nCoin of Ancestry"}
MultiLanguageQuestData['en'][8689] = {title = "Shroud of Infinite Wisdom", objective = "Bring 1 Qiraji Martial Drape, 2 Jasper Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nShroud of Infinite Wisdom"}
MultiLanguageQuestData['en'][8690] = {title = "Cloak of the Gathering Storm", objective = "Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Clay Scarabs and 5 Gold Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nCloak of the Gathering Storm"}
MultiLanguageQuestData['en'][8691] = {title = "Drape of Vaulted Secrets", objective = "Bring 1 Qiraji Martial Drape, 2 Alabaster Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nDrape of Vaulted Secrets"}
MultiLanguageQuestData['en'][8692] = {title = "Cloak of Unending Life", objective = "Bring 1 Qiraji Regal Drape, 2 Vermillion Idols, 5 Silver Scarabs and 5 Bone Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nCloak of Unending Life"}
MultiLanguageQuestData['en'][8693] = {title = "Cloak of Veiled Shadows", objective = "Bring 1 Qiraji Martial Drape, 2 Azure Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nCloak of Veiled Shadows"}
MultiLanguageQuestData['en'][8694] = {title = "Shroud of Unspoken Names", objective = "Bring 1 Qiraji Regal Drape, 2 Amber Idols, 5 Ivory Scarabs and 5 Bronze Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nShroud of Unspoken Names"}
MultiLanguageQuestData['en'][8695] = {title = "Cape of Eternal Justice", objective = "Bring 1 Qiraji Regal Drape, 2 Obsidian Idols, 5 Gold Scarabs and 5 Clay Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cape, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nCape of Eternal Justice"}
MultiLanguageQuestData['en'][8696] = {title = "Cloak of the Unseen Path", objective = "Bring 1 Qiraji Regal Drape, 2 Lambent Idols, 5 Stone Scarabs and 5 Crystal Scarabs to Keyl Swiftclaw in Silithus. You must also obtain Revered reputation with Cenarion Circle to complete this quest.", description = "I'm glad to hear you're aiding us in our attack on Ahn'Qiraj, <name>.  I can make you a protective item that'll be of assistance in the fight against our enemy, <class>.\n\nI shall need a Qiraji drape, which I'll resize for you of course.  I'll also need idols and scarabs which I'll use to create a suitable clasp.\n\nI promise you won't be disappointed.", progress = "Did you bring the materials for the cloak, <name>?", completion = "Ah yes... this drape is immaculate.\n\nTake this cloak, &lt;name&gt;.  May it protect you from the foul magic of the Qiraji.", rewards = "You will receive:\n\nCloak of the Unseen Path"}
MultiLanguageQuestData['en'][8697] = {title = "Ring of Infinite Wisdom", objective = "Bring 1 Qiraji Ceremonial Ring, 2 Obsidian Idols, 5 Silver Scarabs and 5 Bone Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest.", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, <class>.", progress = "Did you bring me the ring and materials, <name>?", completion = "I will swap the gem on the ring for you.  You'll find the effect is much more... agreeable.", rewards = "You will receive:\n\nRing of Infinite Wisdom"}
