MultiLanguageQuestData['en'][8704] = {title = "Signet of the Unseen Path", objective = "Bring 1 Qiraji Ceremonial Ring, 2 Amber Idols, 5 Gold Scarabs and 5 Clay Scarabs to Windcaller Yessendra in Silithus. You must also attain Honored reputation with Cenarion Circle to complete this quest.", description = "The rings worn by the Qiraji lieutenants are rumored to grant them formidable abilities.  The corrupted gems that adorn them could, in theory, be swapped out with more pure materials to create uncorrupted versions of the rings.\n\nThe gems that adorn Qiraji idols would work quite well, as their quality is superior.\n\nBring me the ring and idols and I'll create a powerful ring for you, <class>.", progress = "Did you bring me the ring and materials, <name>?", completion = "I will swap the gem on the ring for you.  You'll find the effect is much more... agreeable.", rewards = "You will receive:\n\nSignet of the Unseen Path"}
MultiLanguageQuestData['en'][8705] = {title = "Gavel of Infinite Wisdom", objective = "Bring 1 Qiraji Ornate Hilt, 2  Lambent Idols, 5 Bronze Scarabs and 5 Ivory Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest.", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.", progress = "Did you bring me the components I require, <name>?", completion = "You've done well, &lt;class&gt;.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, &lt;name&gt;.  Wield it with great confidence and vanquish our enemies!", rewards = "You will receive:\n\nGavel of Infinite Wisdom"}
MultiLanguageQuestData['en'][8706] = {title = "Hammer of the Gathering Storm", objective = "Bring 1 Qiraji Spiked Hilt, 2  Amber Idols, 5 Ivory Scarabs and 5 Bronze Scarabs to Warden Haro in Silithus. You must also attain Exalted reputation with Cenarion Circle to complete this quest.", description = "The Qiraji and their servants wield items made with the rarest and finest materials: bones from gargantuan ancient creatures, gems from the depths of the earth, metals pure and strong.\n\nJust the sight of Qiraji artifacts fills me with an urge to practice my craft with their shattered and smelted pieces.  Prove your allegiance to the Circle, <name>, and I will make you a powerful weapon from the finest Qiraji materials.", progress = "Did you bring me the components I require, <name>?", completion = "You've done well, &lt;class&gt;.  This is a masterwork hilt... the balance is perfect.\n\nTake your weapon, &lt;name&gt;.  Wield it with great confidence and vanquish our enemies!", rewards = "You will receive:\n\nHammer of the Gathering Storm"}
