MultiLanguageQuestData['en'][8827] = {title = "Winter's Presents", objective = "Speak with Greatfather Winter. He is located near the Smokywood Pastures vendor area in Ironforge.", description = "I hear Greatfather Winter - with the generous support of Smokeywood Pastures - has put presents for everyone under the tree in Ironforge. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Greatfather Winter has some presents with your name on them.", progress = nil, completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Greatfather Winter hasn't forgotten about his favorite &lt;race&gt; &lt;class&gt;. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokeywood Pasture's excellent products?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8828] = {title = "Winter's Presents", objective = "Speak with Great-father Winter. He is located near the Smokywood Pastures vendor area in Orgrimmar.", description = "I hear Great-father Winter - with the generous support of Smokeywood Pastures - has put presents for everyone under the tree in Orgrimmar. I wish I could go, but I've got to look after the PX-238 Winter Wondervolt.\n\nBut you should definitely check it out. I'm sure Great-father Winter has some presents with your name on them.", progress = nil, completion = "Oh, ho hello there! You can only be here for one reason: to open your Winter Veil presents.\n\nNow, don't you worry, Great-father Winter hasn't forgotten about his favorite &lt;race&gt; &lt;class&gt;. Look under the tree and you'll find your gifts.\n\nDuring this season of giving, perhaps your friends would also enjoy receiving some of Smokeywood Pasture's excellent products?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8829] = {title = "The Ultimate Deception", objective = "Bring a Skin of Shadow, 3 Frayed Abomination Stitchings and 1 Twilight Cultist Robe to Aurel Goldleaf at Cenarion Hold in Silithus. You must also bring Logistics Task Briefing XI in order to complete this quest.", description = "The Twilight's Hammer operates through innumerable layers of secrecy and deceit.  While their actions are carried out in our world, they are planned in a place we have not yet been able to reach.\n\nWe've come to believe that the stones the Twilight's Hammer uses to summon their superiors allow for two-way transportation.  To attempt to use them in this manner, we must replicate - to every last detail - a twilight emissary's robe.\n\nGather the necessary materials and bring them to Aurel Goldleaf, <name>.", progress = "You have something for me?", completion = "Yes, I believe these shall suffice.  I shall craft these into the colors worn by the Twilight Hammer's emissaries.  I pray to Elune that my skills will be able to fool our enemies once more.\n\nBut do not be concerned with that, you've done your part and for that you will be appropriately rewarded.  You are a loyal and worthy ally, &lt;name&gt;.", rewards = "You will receive:\n\nMark of Remulos"}
MultiLanguageQuestData['en'][8830] = {title = "One Commendation Signet", objective = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with Darnassus.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", description = nil, progress = "For those adventurers who have but a single commendation signet, I'll exchange it for a small amount of recognition with Darnassus.\n\nPlease bear in mind that it is better to hand over a stack of ten signets at once; your efforts will receive greater recognition in doing so.  We offer a single signet exchange as a service for those who don't have enough for a full stack of ten.\n\nWith that being said, I stand ready to assist you if you still wish to hand in a single signet.", completion = "Very well - your deeds have been entered into the records, and you are duly recognized for your efforts.  Keep up the good work, &lt;class&gt;.\n\nIf you have any more signets to hand in, then I am able to assist you further in that regard.", rewards = nil}
MultiLanguageQuestData['en'][8831] = {title = "Ten Commendation Signets", objective = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with Darnassus.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", description = nil, progress = "I accept commendation signets from adventurers who have received them in the line of duty.  For each set of ten that you hand to me, I'll make sure that you receive a significant acknowledgement of your deeds with Darnassus.  I also accept single tokens, but at a much reduced rate of recognition.  We are much more interested in greater feats of duty, though no feat will be ignored.\n\nWith that said, I'll gladly take your signets if you are ready to hand in a set.", completion = "Excellent!  It is no small sacrifice that you've made to earn these signets, and you will be acknowledged for your service appropriately.  It's adventurers like you, &lt;name&gt;, that truly make a difference.\n\nLet me know if you have additional signets to hand in; I'll gladly help you out with whatever ones you need exchanged.", rewards = nil}
