MultiLanguageQuestData['en'][8856] = {title = "Desert Survival Kits", objective = "Bring 4 Globes of Water, 4 Powerful Anti-Venom and 4 Baked Salmon to Calandrath at the inn in Cenarion Hold in Silithus.", description = "With the arrival of fresh recruits to Cenarion Hold comes the problem of keeping them alive in the desert.  Dehydration as well as numerous poisonous creatures present a serious threat to inexperienced volunteers.  Gather the supplies necessary for a desert survival kit and bring them to Calandrath in Cenarion Hold.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nCenarion Logistics BadgeFollowup Logistics Assignment"}
MultiLanguageQuestData['en'][8857] = {title = "Secrets of the Colossus - Ashi", objective = "Take the Colossus of Ashi's Husk to Oglethorpe Obnoticus in Booty Bay.", description = "I'm looking for battle hardened adventurers willing and able to get a fresh husk sample from the fallen Colossus of Ashi to Oglethorpe in Booty Bay. No, no, I wouldn't want you to go anywhere near that thing's corpse. Just take one of my samples and make it snappy. These things are no good to him rotten!", progress = "Yes? What have you got there?", completion = "Oh the chickens I will craft from this wondrous husk! Well done, my boy!", rewards = "You will receive:\n\nColossal Bag of Loot"}
MultiLanguageQuestData['en'][8858] = {title = "Secrets of the Colossus - Regal", objective = "Take the Colossus of Regal's Husk to Overseer Oilfist in Searing Gorge.", description = "There ain't nothin' I'd like more than to stuff this bug husk down Oilfist's fat face... Cept, I'm stuck here collectin' samples from that overgrown cockroach. I'll be here 'till the wee mornin' hours given the size o' that thing.\n\nTake this here sample to Oilfist fer me and do it fast, <class>. He's payin' BIG!\n\nYar, Thorium Point - it be in the Searin' Gorge.", progress = "Hmmm...", completion = "Excellent. We could surely devise some incredibly powerful armor from this chitin. Here's the riches you were promised.", rewards = "You will receive:\n\nColossal Bag of Loot"}
MultiLanguageQuestData['en'][8859] = {title = "Secrets of the Colossus - Zora", objective = "Take the Colossus of Zora's Husk to Lord Maxwell Tyrosus at Light's Hope Chapel in the Eastern Plaguelands.", description = "My servants were nearly killed in their efforts to recover this sample. You absolutely must hurry! Lord Maxwell Tyrosus eagerly awaits a fresh husk sample. He believes that the secrets of this Colossus could help us in the war against the Scourge!\n\nWhy are you still here!? To Light's Hope! Yes, you will be rewarded handsomely for your efforts...", progress = "You look a bit heavy in the boots, friend.", completion = "Excellent and timely! Well done, lad.", rewards = "You will receive:\n\nColossal Bag of Loot"}
MultiLanguageQuestData['en'][8860] = {title = "New Year Celebrations!", objective = "Bring the Smokywood Supplies to Innkeeper Allison in Stormwind.", description = "Stormwind is holding a celebration for the new year!  All day long today you can get free booze, and at night they'll put on a firework show!  It should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Allison in Stormwind needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, <name>!  Innkeeper Allison is in the Gilded Rose, in the Trade District of Stormwind.", progress = "Greetings!  Are you here for the party!  Or perhaps you just need to rest those weary feet of yours...", completion = "Oh, my Smokywood supplies!  Splendid!  I'll need these to feed all the people in town for the celebration!\n\nThank you, &lt;name&gt;.  Please take this as payment, and don't forget to drink and dance with the revelers outside!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8861] = {title = "New Year Celebrations!", objective = "Bring the Smokywood Supplies to Innkeeper Pala in Thunder Bluff.", description = "Thunder Bluff is holding a celebration for the new year!  All day you'll find free booze there, and at night they'll put on a firework show!\n\nIt should be pretty nice... but Booty Bay is also having a party today; I bet it'll be even better!\n\nWell anyway, Innkeeper Pala in Thunder Bluff needs a supply of Smoky Wood Pasture fare to help feed all the party goers.  Can you do me a favor and deliver it!\n\nThanks, <name>!  Innkeeper Pala is in the inn near the bridge to Hunter's Rise.", progress = "Good day, <class>!  Did you come to Thunder Bluff for our celebrations?  Or are you here to rest a weary hoof between hunts?", completion = "Oh, very good!  These supplies will help feed all our people, here to celebrate the new year!\n\nI thank you, &lt;name&gt;.  You are in my debt.  Please, take these coins... and heed my advice - drink heartily from the kegs outside, and join our revelers in a dance of celebration!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8862] = {title = "Elune's Candle", objective = "Elune's candle is an artifact of great reverence to the disciples of the Lunar Festival.  Stored within the candle is true moonlight, ready to be unleashed!\n\nThis light is harmless to most creatures, but you will find that Omen and his minions are burned and dazzled by it.", description = nil, progress = "Elune's candle is an artifact of great reverence to the disciples of the Lunar Festival.  Stored within the candle is true moonlight, ready to be unleashed!\n\nThis light is harmless to most creatures, but you will find that Omen and his minions are burned and dazzled by it.", completion = "Very well then - I accept these coins of ancestry.  Please take Elune's candle with my blessing.  Also, please enjoy these complimentary fireworks.\n\nMay your Lunar Festival be joyous and filled with merriment, &lt;name&gt;.\n\nAnd if you choose to face Omen and his minions, you will find Elune's candle quite useful...", rewards = "You will receive:\n\nElune's CandleLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8863] = {title = "Festival Dumplings", objective = "If you are hungry, then you have come to the right place my friend!\n\nDumplings are the traditional food of the Lunar Festival; it has been served since the time of the first Lunar Festival, and I am pleased to be able to offer it at this one.  In exchange for just a single coin of ancestry, I will share with you a sampling of one of the tastiest dishes you will ever enjoy!", description = nil, progress = "If you are hungry, then you have come to the right place my friend!\n\nDumplings are the traditional food of the Lunar Festival; it has been served since the time of the first Lunar Festival, and I am pleased to be able to offer it at this one.  In exchange for just a single coin of ancestry, I will share with you a sampling of one of the tastiest dishes you will ever enjoy!", completion = "Excellent - please enjoy these dumplings with my compliments.  While they are but a small token of appreciation for the honor you have brought upon yourself through your actions, I think you will enjoy them all the same.\n\nShould you have any more coins of ancestry, I stand ready to offer you a wide array of items in exchange.", rewards = "You will receive:\n\nFestival Dumplings"}
MultiLanguageQuestData['en'][8864] = {title = "Festive Lunar Dresses", objective = "I have a selection of dresses that may be of interest to you.  Such dresses have been worn in times past during the Lunar Festival, and the selection I have today is perhaps the finest I have ever seen.  Each is hand-crafted with only the finest and softest of components.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", description = nil, progress = "I have a selection of dresses that may be of interest to you.  Such dresses have been worn in times past during the Lunar Festival, and the selection I have today is perhaps the finest I have ever seen.  Each is hand-crafted with only the finest and softest of components.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", completion = "Very well then - I accept these coins of ancestry.  Please take your dress with my blessing.  Also, please enjoy these complimentary fireworks.\n\nAs you have honored your elders, you honor me with your mere presence.  Thank you, and may your Lunar Festival be joyous.", rewards = "You will be able to choose one of these rewards:\n\nFestive Green DressFestive Pink DressFestive Purple Dress\n\nYou will also receive:\n\nLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8865] = {title = "Festive Lunar Pant Suits", objective = "I am please to inform you that I have a fine selection of festive pant suits available for you to own... but only in trade for coins of ancestry.  If fashion is important to you, then these are what you're looking for!  I assure you that you will not find pant suits like these anywhere else.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", description = nil, progress = "I am please to inform you that I have a fine selection of festive pant suits available for you to own... but only in trade for coins of ancestry.  If fashion is important to you, then these are what you're looking for!  I assure you that you will not find pant suits like these anywhere else.\n\nIn exchange for some coins of ancestry, I will let you choose one of the three styles I have to keep as your own.  Is this acceptable to you?", completion = "Very well then - I accept these coins of ancestry.  Please take your pant suit with my blessing.  Also, please enjoy these complimentary fireworks.\n\nShould you have more coins of ancestry to trade, then speak with me again.  I will be offering various items throughout the entirety of the Lunar Festival.", rewards = "You will be able to choose one of these rewards:\n\nFestive Black Pant SuitFestive Blue Pant SuitFestive Teal Pant Suit\n\nYou will also receive:\n\nLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8866] = {title = "Bronzebeard the Elder", objective = "It is good to know the people of this land still pay homage to the olden races.  I bid you well, <name>, and offer you this token...", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nForce Self - Bow\n\nYou will receive:\n\nCoin of Ancestry"}
MultiLanguageQuestData['en'][8867] = {title = "Lunar Fireworks", objective = "Launch 8 Lunar Fireworks and 2 Cluster Fireworks and return to a Lunar Festival Harbinger at any capital city.", description = "Every year the druids of Moonglade hold a celebration of our city's great triumph over an ancient evil.\n\nWe celebrate the wisdom of our elders, share in magnificent feasts and of course... shoot fireworks!\n\nFor a small donation you can purchase colorful rockets from our vendor.  Try using some of the launchers around here, <name>.", progress = "Did you find the launchers, <name>?", completion = "Well done, &lt;name&gt;.\n\nNow that you're in the spirit of things, why don't you take this invitation to the festival in Moonglade.\n\nIt's quite an enjoyable celebration, if you have the time to spare.  We share food, drink, stories and of course... more fireworks!\n\nOpen the invitation while standing inside the circle of greater moonlight and you'll be transported to Moonglade.", rewards = "You will receive:\n\nLunar Festival Invitation"}
MultiLanguageQuestData['en'][8868] = {title = "Elune's Blessing", objective = "Summon Omen, defeat him and gain Elune's Blessing. Return to Valadar Starsong in Nighthaven", description = "The beast Omen was once a hero of this world.  A wolf of great strength and fortune, Omen fought beside the heroes of the War of the Ancients until he succumbed to demonic magics.  Turning against his allies, he raged across Azeroth and carried death and terror in his wake.\n\nFinally defeated here, in Moonglade, Omen now sleeps among the silt of Lake Elune'ara.  But each new year, during the festival, he stirs...\n\nGather cohorts, <name>, and summon and defeat the beast Omen.  Earn the blessing of Elune!", progress = "Omen yet stirs below below Lake Elune'ara, <name>...", completion = "Very well done, &lt;name&gt;.  Defeating Omen sent his spirit back to the waters of Elune'ara.  Although the beast himself is blessed by Elune and so cannot die, his anger will subside for another year.\n\nYour victory is a celebration, &lt;name&gt;--a celebration of the might of Omen, of you and your allies, and of the peace you have given this tragic hero of our past.", rewards = "You will receive:\n\nElune's LanternLunar Festival Fireworks PackSolid Stone"}
MultiLanguageQuestData['en'][8869] = {title = "Sweet Serenity", objective = "Travel to Stratholme and kill the Crimson Hammersmith. Recover the Crimson Hammersmith's Apron and return to Lilith.", description = "Within the confines of the Scarlet Bastion lies sweet Serenity. The Crimson Hammersmith guards the recipe with his life. Defeat him and bring me his apron. For that, I shall train you to become a hammersmith.\n\nUnderstand this: Once you have chosen the path of the hammersmith, the paths of the swordsmith and axesmith will no longer be available.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nPlans: Enchanted Battlehammer"}
MultiLanguageQuestData['en'][8870] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger in the Mystic Ward of Ironforge. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  You're here to join us in our celebration?", rewards = nil}
MultiLanguageQuestData['en'][8871] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger in the Park District in Stormwind. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  Are you here to join in the festivities?", rewards = nil}
MultiLanguageQuestData['en'][8872] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger at the Cenarion Enclave in Darnassus. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  Are you here to join in the festivities?", rewards = nil}
MultiLanguageQuestData['en'][8873] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger in the Valley of Wisdom in Orgrimmar. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  Are you here to join in the festivities?", rewards = nil}
MultiLanguageQuestData['en'][8874] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger in the entrance to the Undercity. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  Are you here to join in the festivities?", rewards = nil}
MultiLanguageQuestData['en'][8875] = {title = "The Lunar Festival", objective = "Talk to the Lunar Festival Harbinger at the Elder Rise in Thunder Bluff. You can also talk to Lunar Festival Harbingers in other capital cities.", description = "It's that time of the year, <name>!  The Cenarion Circle invites all denizens of Azeroth to partake in our celebration of the Lunar Festival.  You will find the Lunar Festival Harbinger in this very city at a location marked by a blessed circle of moonlight.  She can tell you more about the holiday.", progress = nil, completion = "Welcome, &lt;name&gt;.  Are you here to join in the festivities?", rewards = nil}
MultiLanguageQuestData['en'][8876] = {title = "Small Rockets", objective = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", description = nil, progress = "I hold the secrets to creating Lunar Festival rockets, and I am happy to share my knowledge with the honored.\n\nIn exchange for coins of ancestry, I can offer you the recipe to make a small rocket...", completion = "Ah, very well.  Here are your recipes, &lt;name&gt;, and my Elune bless you.", rewards = "You will receive:\n\nSmall Rocket RecipesLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8877] = {title = "Firework Launcher", objective = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", description = nil, progress = "Although rockets are a wonderful way to celebrate, in order to see their glory... they must be fired from a launcher.\n\nBring me coins of ancestry and I can offer you the knowledge to create rocket launchers like the ones you see in Moonglade.", completion = "Here you are, &lt;name&gt;.  Here is the schematic to create a firework launcher.  Place launchers where you wish to celebrate, and then welcome your friends to join you!", rewards = "You will receive:\n\nSchematic: Firework LauncherLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8878] = {title = "Festive Recipes", objective = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, <name>, then I will give you the pattern to create traditional red dresses or suits.", description = nil, progress = "The dresses and pant suits you see are traditional clothes from many years past.  They are worn in honor of old ways and loved ones gone.\n\nIf you bring me coins of ancestry, <name>, then I will give you the pattern to create traditional red dresses or suits.", completion = "Here are the patterns, &lt;name&gt;.  I am sure you will find the product of this knowledge quite beautiful.", rewards = "You will be able to choose one of these rewards:\n\nPattern: Festival DressPattern: Festival Suit\n\nYou will also receive:\n\nLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8879] = {title = "Large Rockets", objective = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, <name>, and I shall share the knowledge of their creation.", description = nil, progress = "Large Festival rockets light up the sky brilliantly - only the cluster rockets rival their magnificence!\n\nBring me coins of ancestry, <name>, and I shall share the knowledge of their creation.", completion = "Very well - I accept these coins of ancestry.  Here are your recipes, &lt;name&gt;.  May you use them to spread Elune's glory!", rewards = "You will receive:\n\nLarge Rocket RecipesLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8880] = {title = "Cluster Rockets", objective = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", description = nil, progress = "Cluster rockets are a collection of individual rockets, and their beauty is awesome!  Bring me coins of ancestry and I will share the knowledge of their creation to you...", completion = "Here you are, &lt;name&gt;.  Take these recipes and learn their secrets.  I bid you fortune, and I look forward to seeing your magnificent creations.", rewards = "You will receive:\n\nCluster Rocket RecipesLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8881] = {title = "Large Cluster Rockets", objective = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", description = nil, progress = "Large cluster rockets require vast resources and skill to create, but their brilliance and beauty is worth that effort!  Bring me coins of ancestry and I will grant you the knowledge of their crafting.", completion = "Thank you, &lt;name&gt;.  Here is the recipe for large cluster rockets.  May your products bring joy and luck to all those who gaze up them.", rewards = "You will receive:\n\nLarge Cluster Rocket RecipesLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8882] = {title = "Cluster Launcher", objective = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", description = nil, progress = "The most splendid fireworks shows must include cluster rockets, and those cluster rockets must be fired from cluster launchers!  Is it not then logical for you to learn the secrets of making cluster launchers?  Bring me coins of ancestry and I will give this knowledge to you.", completion = "Here is your schematic.  Study it closely, and learn...\n\nGood luck, &lt;name&gt;.  May your celebrations rival that of the Lunar Festival itself!", rewards = "You will receive:\n\nSchematic: Cluster LauncherLunar Festival Fireworks Pack"}
MultiLanguageQuestData['en'][8883] = {title = "Valadar Starsong", objective = "Use your Lunar Festival Invitation in the moonlight to travel to Moonglade. Speak with Valadar Starsong in Nighthaven when you arrive.", description = "Now that you have your Lunar Festival invitation, you may travel to Moonglade!  There you will find many revelers, and in the village of Nighthaven Valadar Starsong and his sister Fariel await those eager to participate in the celebration.\n\nTravel to Moonglade through the greater moonlight and speak with Valadar Starsong; see what prizes you might gain during the festival!", progress = nil, completion = "&lt;name&gt;, welcome to Nighthaven, host of the Lunar Festival!  Although our village is normally remote and sequestered from the peoples of Azeroth, during this time of celebration we open our arms and hearts to all.\n\nEnjoy your visit, &lt;name&gt;, and speak with me or my sister again when ready.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8884] = {title = "Fish Heads, Fish Heads...", objective = "Collect 8 Grimscale Murloc Heads. Return them to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", description = "Greetings, <class>.  Take a look toward the shore; what do you see?  That's right, our beach... our Tranquil Shore, has been infested with the malignancy known as the murloc.\n\nThis blight will not stand!\n\nI have a task for you.  If you feel that you're up to it, I would have their heads!  Let us see if we can put a dent in their numbers so large that, if they have any sense at all, they will return to the murky depths from which they sprang!", progress = "We rangers of the Farstrider Retreat are dedicated to setting right the damage that has been wreaked upon our fair lands.  We will go to any length to do so.\n\nI trust that you have returned with the murloc heads I tasked you to gather?", completion = "A job well done, &lt;class&gt;.  By the smell of it, I'd say you returned all that I asked for, and possibly more.  I'm sure we can find some use for these, in a stew, or somesuch.\n\nAlas, it does not appear that your efforts have done the trick; the murlocs are not in retreat.  This calls for more direct action!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8885] = {title = "The Ring of Mmmrrrggglll", objective = "Retrieve the Ring of Mmmrrrggglll from the Grimscale chieftain's dead clutches. Return it to Hathvelion Sungaze in the Eversong Woods on the bluff overlooking the Tranquil Shore.", description = "The Grimscale murlocs have not been scared off by your efforts. But, I think I know what will send them packing, as well as get me some personal retribution.\n\nThey have a murloc chieftain that calls itself Mmmrrrggglll. It wanders the Golden Strand south of the river inlet. The beast once slew a compatriot of mine, and now wears his ring in open defiance and mockery.\n\nSlay Mmmrrrggglll, and bring back my friend's ring. Then we shall see these monsters cowed!", progress = "You are the instrument of my success and revenge, <class>. Have you the ring?", completion = "At last! Though the Grimscale did not route, as hoped, it was entertaining to watch them panic in confusion when you laid low their so-called chieftain. You have my thanks, and the gratitude of the sin'dorei of Silvermoon City!\n\nPlease, take one of these in thanks for the service that you have rendered.", rewards = "You will be able to choose one of these rewards:\n\nWorn Ranger's BowFarstrider's BucklerSatin Lined GlovesSlightly Used Ranger's Blade\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8886] = {title = "Grimscale Pirates!", objective = "Retrieve 6 of Captain Kelisendra's Cargo and return them to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", description = "Thank goodness for you, <class>! Those slimy Grimscale murlocs have pirated away my cargo! It's bad enough that the Wretched have stolen what little magical goods I had, but the murlocs took the rest! What has this land come to?\n\nCould you retrieve my cargo? I can't expect that you'd be able to get all of it back, but I'll be grateful for any of it at this point. It was the Grimscale murlocs in the huts, just to the west and south of the anchorage on the Golden Strand, I'm sure of it!", progress = "I am grateful for the assistance of someone like you, <name>. It almost puts a smile on my face. But then I realize what these monsters have done to my ship and what's happening to Quel'Thalas.\n\nHave you managed to retrieve any of my cargo?", completion = "You did it! You've saved me from ruin and delivered my revenge upon those disgusting creatures!\n\nNow if I can just get these pretty rangers here to help me with this cargo, I'll finally get out of here! I'll have to come back when Velendris has retaken the shipyard.\n\nHere, take this coin. It's what little I can afford, and the least that I can do to reward your efforts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8887] = {title = "Captain Kelisendra's Lost Rutters", objective = "Return Captain Kelisendra's Lost Rutters to Captain Kelisendra at the defended camp just to the east of the Sunsail Anchorage in Eversong Woods.", description = "Interesting... what you have found here is a water-proofed, leather tube containing a number of sheets of parchment. By the markings upon them, the pages are clearly navigation rutters, and each bears the signature of one Captain Kelisendra.\n\nYou've heard of a small, defended camp just east of the nearby Sunsail Anchorage. Maybe the captain is there?", progress = "Hello, <class>, you're a sight for sore eyes. I know, it's crazy for me to be here, what with the anchorage overrun by the Wretched. Velendris and his rangers have sworn to protect me on the condition that I get out of here as soon as I've recovered my cargo.\n\nWhat's that you have there... it looks vaguely familiar?", completion = "Oh you sweet, sweet &lt;class&gt;! I had no idea that those disgusting Grimscale murlocs had also pirated away with my navigation rutters! Without them, I would have no chance of navigating the seas again once we retake the anchorage and repair the ship.\n\nThank you very much! Here, take this coin as a sign of my appreciation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8888] = {title = "The Magister's Apprentice", objective = "Speak with Apprentice Loralthalis near Duskwither Spire in Eversong Woods.", description = "<class>, hear my request. For reasons that I cannot go into now, I decided to shut down my nearby school. A few days ago, I sent one of my pupils, Apprentice Loralthalis, there with this very task. I have not heard back from her since.\n\nWill you go to Duskwither Spire and check in on her, to make sure that she is well? You'll find it by heading north on the path out of Farstrider Retreat, then go to the right when the road branches.", progress = nil, completion = "The magister was concerned for my wellbeing? How sweet; I wish that he had shown such an interest before, when we were at the Spire.\n\nThat doesn't matter now. Please listen carefully, &lt;class&gt;, as I have a favor to ask of you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8889] = {title = "Deactivating the Spire", objective = "Deactivate the 3 Duskwither Spire Power Sources inside Duskwither Spire. Then return the Deactivating Jewel to Apprentice Loralthalis in Eversong Woods.", description = "As you may know, Magister Duskwither sent me back here to shut down the power sources that feed the Spire. There are three of them, each located in a different place inside.\n\nUnfortunately, I appear to be too late, and Duskwither Spire has been overrun with strange, magical creatures. While I haven't the expertise to accomplish this task, surely a <class>, such as yourself, could do so easily?", progress = "I can't be certain from this distance... have you already shut down the power to Duskwither Spire?", completion = "I am grateful to you for your assistance, but saddened to hear that some of my fellow apprentices have fallen to their addiction.\n\nWith the power to the Spire cut off, I think I'll stay here a while and see if things calm down long enough for me to sneak in and retrieve their remains.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8890] = {title = "Word from the Spire", objective = "Return to Magister Duskwither at the Farstrider Retreat in Eversong Woods.", description = "<name>, I have one last favor to ask of you. Would you please relay what's transpired here to Magister Duskwither, back at the Farstrider Retreat? Let him know that I am well, but make certain that he is aware that some of the apprentices have become Wretched.\n\nThank you for your help!", progress = nil, completion = "No! I was too late. It is all my fault.\n\nMy investigation into purifying alternative magical sources got out of hand before I could put a stop to it. If only I had gone myself... or that they had listened to me, and heeded my warnings!\n\nI have blood on my hands, &lt;class&gt;. I thank you, though, for putting to rest the tortured souls of my former apprentices. It is some small consolation that they will not linger in that state where a &lt;race&gt; is better off dead.", rewards = "You will receive:\n\nFallen Apprentice's Robe"}
MultiLanguageQuestData['en'][8891] = {title = "Abandoned Investigations", objective = "Return Magister Duskwither's Journal to Magister Duskwither at the Farstrider Retreat in Eversong Woods.", description = "You have discovered what appears to be an investigative journal left behind by Magister Duskwither. A brief scan of its contents reveal some shocking attempts at filtering corrupted magical flows, which might explain what has happened here at Duskwither Spire. The magister is sure to want this brought back to him.", progress = "What's this? It looks familiar. Oh no, this journal... my investigations... this is what caused all of this in the first place.", completion = "Here it is, &lt;name&gt;, the proof of my crime. This journal contains all of my ill-conceived studies.\n\nHeedless of the warnings, I continued my research, until it was almost too late. Then, when I grasped my error, I did what I could. But by then, some of my pupils had already gone too far. I evacuated the Spire to get them away from the corruption, but in my haste, forgot to shutdown the power sources.\n\nI will burn this tome so that no one else falls prey to its contents. I only wanted to help the sin'dorei.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8892] = {title = "Situation at Sunsail Anchorage", objective = "Kill 5 Wretched Thugs and 5 Wretched Hooligans and report to Ranger Degolien in Eversong Woods.", description = "Sunsail Anchorage has been overrun by Wretched scum.  As soon as we manage to get reinforcements to the area we'll show those thugs who's boss, <name>.\n\nIn the meantime you can help by showing them a bit of discipline.  Go in there and show them we are not to be trifled with.  You will find Sunsail Anchorage just to the west of Fairbreeze Village.", progress = "Did you teach those Wretched a lesson?", completion = "That'll teach them not to mess with us.  Good work, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8893] = {title = "The Super Egg-O-Matic", objective = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", description = nil, progress = "The Super Egg-O-Matic is the latest of Curgle Cranklehop's inventions. It is quite an impressive piece of machinery.\n\nThe Super Egg-O-Matic sputters wildly as you approach the control panel.", completion = "You place the hippogryph egg into the machine. A series of beeps follows along with some strange mechanical sounds.\n\nIt appears that the Eggometer has weighed, measured, and packaged your egg. Now that's speedy service!", rewards = "You will receive:\n\nEgg Crate"}
MultiLanguageQuestData['en'][8894] = {title = "Cleaning up the Grounds", objective = "Kill 6 Mana Serpents and 6 Ether Fiends and return to Groundskeeper Wyllithen at Duskwither Grounds in Eversong Woods.", description = "It's horrible, I tell you! Strange things happening in the spire, the magister and his apprentices run off, and then the next thing that you know, the whole grounds are overrun with these magical beasties! And who told Wyllithen? No one, that's who!\n\n<class>, you've got to help me clear some of these things out... I cannot maintain the grounds while these 'anomalies' are running amok!", progress = nil, completion = "Well, I suppose that will have to do, now won't it? Thanks for the help, &lt;class&gt;. I can only hope to get this mess completely cleaned up before the Magister returns to Duskwither Spire.\n\nTake this pocket change; it's not much but it's all that I have at the moment. Feel free to dispatch a few more of the beasties on your way out, if you'd be so kind.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8895] = {title = "Delivery to the North Sanctum", objective = "Deliver the Unmarked Letter to Ley-Keeper Caidanis at the North Sanctum in Eversong Woods.", description = "I'm pleased to discover that you're at least somewhat competent, <name>.  I'll give you another task since you seem so eager to prove yourself.\n\nThis is a letter to Ley-Keeper Caidanis, the arcanist in charge of the upkeep of the North Sanctum.  Go southwest of Falconwing Square  and you will find him.  He is a very important person, so I hope you don't bother him too much with trivial chatter.", progress = "Yes, <class>?", completion = "Thank you, &lt;name&gt;.  I've been expecting this letter.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8896] = {title = "The Dwarven Spy", objective = "Find and kill Prospector Anvilward in the North Sanctum and report back to Aeldon Sunbrand in Eversong Woods.Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission. I should've known his interest in our Arcane Sanctums was a bit excessive. <name>, find the dwarf in the North Sanctum and take care of him. Oh, and be discrete about it.", description = "Are you sure you found these notes on a Night Elf, then?  Most of them are written in the Dwarven...\n\nProspector Anvilward!  He was sent here from Ironforge on a diplomatic mission.  I should've known his interest in our Arcane Sanctums was a bit excessive.  <name>, find the dwarf in the North Sanctum and take care of him.  Oh, and be discrete about it.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][8897] = {title = "Dearest Colara,", objective = "Deliver Lieutenant Heldric's Carefully Penned Note to Colara Dean outside the bank in Stormwind.", description = "I've got to keep watch here at the gate, but I'm always worrying about my sweetheart, Colara. I only get to see her for a few hours, if I'm lucky, and well, just look at me. I've got a minor officer's pay and I could be called to the front any day now.\n\nWould she just forget about me? There are a lot of men in the city. A lot of rich ones.\n\nAnyways, I've scribbled some things down... nothing much, but if you could take it to her for me, that'd be great.", progress = "Hello there, handsome. Something I can help you with?", completion = "Oh, isn't that sweet! This is the first time he's ever sent me something. Do you suppose he's getting serious?\n\nColara Heldric? I suppose it has a ring to it. Oh, but I'm getting ahead of myself. Thank you.", rewards = nil}
MultiLanguageQuestData['en'][8898] = {title = "Dearest Colara,", objective = "Deliver the Creased Letter to Colara Dean outside the bank in Stormwind.", description = "I met a lass in Stormwind when I was last there on the bank's business. She stole my heart away. Now, I can't stop thinking about her! I'd like to send her this message - I've rewritten it twelve times!\n\nThe mail is so full now, and I want to make sure it gets there.\n\nIf you're heading that way, could you help me?", progress = "Hello there, handsome. Something I can help you with?", completion = "Tormek? Oh yes, I do remember him. He had quite a nice beard and smile underneath.\n\nAh, I can't believe he remembered me!", rewards = nil}
MultiLanguageQuestData['en'][8899] = {title = "Dearest Colara,", objective = "Deliver the Immaculate Letter to Colara Dean outside the bank in Stormwind.", description = "How to describe her beauty? Thousands of years of words and I am at a loss.\n\nThese mortals confound the mind and leave us babbling fools.\n\nI've stared at these words too long. No more eloquent meaning can I squeeze from them. No, she must have it now, or some other suitor will surely steal her eye.", progress = "Hello there, handsome. Something I can help you with?", completion = "I've never received something like this before. How lovely!", rewards = nil}
MultiLanguageQuestData['en'][8900] = {title = "Dearest Elenia,", objective = "Deliver the Slightly Creased Note to Elenia Haydon near the bank in the Undercity.", description = "She was so sad. I could see that, once I saw past her state. I mean, she seemed sad - wouldn't you?\n\nBut after talking to her, there was a connection. I didn't think anyone could understand what I was thinking, but she could.\n\nWhen I told the others, they laughed at me, so I never spoke with her again. But I miss her. Can you take this letter to her for me? I want to be sure it finds her hands.", progress = "Oh, and to what do I owe this pleasure?", completion = "You wouldn't expect an orc to be so eloquent. Of course, we never really had a chance to know them before now. Thank you for bringing this to me.", rewards = nil}
MultiLanguageQuestData['en'][8901] = {title = "Dearest Elenia,", objective = "Deliver the Carefully Written Letter to Elenia Haydon near the bank in the Undercity.", description = "Have you ever known love, young one? It was a thing foreign to me until lately, when I met a girl from the Undercity, Elenia. It is rare enough for one of my kind to look outside our own, let alone one of the Forsaken.\n\nBut now thoughts of her occupy my mind both days and nights.\n\nIf you can, could you take this letter to her? I want her to come here to Mulgore. I hope that she will say yes.", progress = "Oh, and to what do I owe this pleasure?", completion = "What kind words Temma writes for me. But, as much as his words move me, I cannot consider the love of a tauren. In thoughts, body and mind we are too different.\n\nIt is good I do not have to receive these thoughts of his in person. I could not bear to break his heart.", rewards = nil}
MultiLanguageQuestData['en'][8902] = {title = "Dearest Elenia,", objective = "Deliver the Lovingly Composed Letter to Elenia Haydon near the bank in the Undercity.", description = "A lifetime ago, I was betrothed to marry Elenia, my childhood sweetheart. It's been years since I thought about her last, but of late, she frequently occupies my thoughts.\n\nPerhaps, even with everything that has passed, there can be some room in each other's lives for our love.\n\nI'm sure she has changed, also. Can you deliver this letter to her for me? I am too nervous to give it in person.", progress = "Oh, and to what do I owe this pleasure?", completion = "This brings back memories from a lifetime ago, &lt;name&gt;. Elenia Tor. That was going to be my name, you know. We would have a beautiful ceremony out on the shores of the lake. When he retired, we'd find a farm to retire to.\n\nSimple dreams, then.\n\nBut if he saw me now, I doubt he'd even see Elenia in me. Only cold flesh and a dead heart...", rewards = nil}
MultiLanguageQuestData['en'][8903] = {title = "Dangerous Love", objective = "Get a Stormwind Guard's Card and return it to Aristan Mottar in Stormwind.", description = "There's something unnatural about this epidemic of love. It's not proper, it's an eyesore, and at worst, it could be a threat to the the safety of the Alliance itself.\n\nJust think: what if the guards have been taken in by this strange affliction? Something must be done.\n\nGo to one of the guards here in Stormwind and see if they've been caught up in this foolishness.", progress = "Was I right to worry? Are the guards afflicted with this lovesickness?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", rewards = nil}
MultiLanguageQuestData['en'][8904] = {title = "Dangerous Love", objective = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", rewards = nil}
MultiLanguageQuestData['en'][8905] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Wildheart Bracers to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nFeralheart Bracers"}
MultiLanguageQuestData['en'][8906] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Beaststalker's Bindings to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nBeastmaster's Bindings"}
MultiLanguageQuestData['en'][8907] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Magister's Bindings to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nSorcerer's Bindings"}
MultiLanguageQuestData['en'][8908] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Lightforge Bracers to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nSoulforge Bracers"}
MultiLanguageQuestData['en'][8909] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with 1 set of Devout Bracers to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nVirtuous Bracers"}
