MultiLanguageQuestData['en'][8941] = {title = "Just Compensation", objective = "Bring a Shadowcraft Belt and a set of Shadowcraft Gloves to Mokvar in Orgrimmar.", description = "You've proven to be a very reliable individual, <name>.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", rewards = "You will receive:\n\nDarkmantle GlovesDarkmantle Belt"}
MultiLanguageQuestData['en'][8942] = {title = "Just Compensation", objective = "Bring a Cord of Elements and a set of Gauntlets of Elements to Mokvar in Orgrimmar.", description = "You've proven to be a very reliable individual, <name>.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gauntlets.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", rewards = "You will receive:\n\nCord of The Five ThundersGauntlets of The Five Thunders"}
MultiLanguageQuestData['en'][8943] = {title = "Just Compensation", objective = "Bring a Dreadmist Belt and a set of Dreadmist Wraps to Mokvar in Orgrimmar.", description = "You've proven to be a very reliable individual, <name>.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", rewards = "You will receive:\n\nDeathmist BeltDeathmist Wraps"}
MultiLanguageQuestData['en'][8944] = {title = "Just Compensation", objective = "Bring a Belt of Valor and a set of Gauntlets of Valor to Mokvar in Orgrimmar.", description = "You've proven to be a very reliable individual, <name>.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gauntlets.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", rewards = "You will receive:\n\nBelt of HeroismGauntlets of Heroism"}
MultiLanguageQuestData['en'][8945] = {title = "Dead Man's Plea", objective = "Go into Stratholme and rescue Ysida Harmon from Baron Rivendare.", description = "I'll provide you the information you ask for, <name>.  But more pressing matters are at hand.\n\nMy beloved wife has been taken prisoner by Rivendare's undead scum.\n\nI strongly objected to her joining the Argent Dawn's foolish crusade, yet that's not of importance anymore.  You must finish what I attempted to do, you must rescue Ysida from the clutches of the Baron!", progress = "Tell me, is Ysida alive?", completion = "Thank you for rescuing me... I feared for my life.  Please accept this as a small token of my gratitude.\n\nAnthion is... no... he can't be...", rewards = "You will receive:\n\nYsida's Satchel"}
MultiLanguageQuestData['en'][8946] = {title = "Proof of Life", objective = "Bring Ysida's Locket to Anthion Harmon in Eastern Plaguelands.", description = "It is the cruelest of fates that my beloved has perished while trying to rescue me.  Yet, you claim to possess the ability to converse with him.\n\nBring him this locket as proof that I am well.  He must not linger in this world; my heart would not be able to bear it.\n\nFarewell, <name>.  I shall be in your debt always.", progress = "Ysida... is she alive?", completion = "That locket... you found her!  I can rest in peace at long last.\n\nI shall now answer any questions you might have, &lt;name&gt;.  But make haste, my time in this world is not long.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8947] = {title = "Anthion's Strange Request", objective = "Bring 3 Dark Iron Bars, 20 Enchanted Leather, 3 Mooncloth and 4 Cured Rugged Hides to Anthion Harmon in the Eastern Plaguelands.", description = "We didn't realize the importance of Valthalak's medallion, so it was divided along with the rest of the spoils.  The first piece was taken by a dwarf named Theldren.  I tried to retrieve it from him and he beat me within an inch of my life.  You shall have to take the fragment by force.\n\nLast I heard of him, he'd become a gladiator for the Dark Iron dwarves.  Getting him to fight you is going to present a bit of a challenge, though.\n\nGather the following materials for me.  You're going to need them.", progress = "Did you obtain the materials I asked for, <name>?", completion = "Excellent.  I shall transmute these into something more suitable to our needs.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8948] = {title = "Anthion's Old Friend", objective = "Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul.", description = "Theldren is not one to willingly participate in a fair fight.  I've shaped this banner to display his family colors.\n\nWith some additional sorcery, this banner shall provoke him in a way he won't be able to resist.\n\nAn old acquaintance of mine named Falrin knows the exact procedure required.  He has a particular way of... aggravating people.  You shall find him at the library in Dire Maul.", progress = "Speak up stranger, can't you see I'm busy?", completion = "Anthion sent you, you say?  I thought he was dead.  I guess I've heard stranger things in my life.\n\nVery well, then.  What is it you want me to do with this banner?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8949] = {title = "Falrin's Vendetta", objective = "Collect 25 Ogre Warbeads from Ogres inside Dire Maul or Blackrock Spire and return to Falrin Treeshaper inside the Athenaeum in Dire Maul.", description = "Yes, it is true that I am familiar with this enchantment you require, <class>.  Yet I'm not one to give out favors freely, even if you were sent here by an old friend.\n\nI hold nothing but hatred and contempt for our brutish ogre neighbors.  And not only them, I hate the followers of Omokk just as much as I hate those that follow King Gordok.\n\nI want you to kill them.  Kill lots of them!  Bring me the beads they carry around their neck as proof of your work.  Do this and we shall talk about your request.", progress = "Have you performed the favor I asked of you, <name>?", completion = "Hmmm... strangely enough I don't feel any better about my brother's death at the hands of those brutes.\n\nWell, you held your end of the bargain.  Let's see what I can do for you.", rewards = "You will be able to choose one of these rewards:\n\nBeads of Ogre MightBeads of Ogre Mojo\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8950] = {title = "The Instigator's Enchantment", objective = "Bring the following to Falrin Treeshaper inside Dire Maul: 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards.", description = "I can place the enchantment you require on the banner quite easily, <name>.  Unfortunately I don't have the materials I need as it is very rarely that someone asks for this sort of charm.\n\nI will require the essence of one of the Eldreth ghosts that haunt these halls, a handful of Scholomance dark runes and some large brilliant shards.  Bring me these reagents and I shall perform this task for you.", progress = "Have you gathered the materials I require, <name>?", completion = "Yes, these will do just fine.  After I'm done, no force in the world will be able to stop your victim from accepting your challenge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8951] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Wildheart Boots, a Wildheart Kilt and Wildheart Spaulders.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You're back, <name>.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", rewards = "You will receive:\n\nFeralheart BootsFeralheart KiltFeralheart Spaulders"}
MultiLanguageQuestData['en'][8952] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Beaststalker's Boots, Beaststalker's Pants and Beaststalker's Mantle.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You're back, <name>.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", rewards = "You will receive:\n\nBeastmaster's BootsBeastmaster's PantsBeastmaster's Mantle"}
