MultiLanguageQuestData['en'][8955] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Devout Sandals, Devout Skirt and Devout Mantle.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nVirtuous SandalsVirtuous SkirtVirtuous Mantle"}
MultiLanguageQuestData['en'][8956] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Shadowcraft Boots, Shadowcraft Pants and Shadowcraft Spaulders.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You're back, <name>.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", rewards = "You will receive:\n\nDarkmantle BootsDarkmantle PantsDarkmantle Spaulders"}
MultiLanguageQuestData['en'][8957] = {title = "Anthion's Parting Words", objective = "Return to Mokvar in Orgimmar with a set of Boots of Elements, Kilt of Elements and Pauldrons of Elements.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You've returned and I see in your eyes that you've much to tell me, <name>.  Let us take care of your reward first.", completion = "This curse was bestowed upon us but for a mere medallion.  Lord Valthalak certainly knows how to hold a grudge.\n\nWe'll endeavor to find the remaining pieces - hopefully before I meet an untimely demise.  But before that, let us see about your reward.", rewards = "You will receive:\n\nBoots of The Five ThundersKilt of The Five ThundersPauldrons of The Five Thunders"}
MultiLanguageQuestData['en'][8958] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Dreadmist Sandals, Dreadmist Leggings and Dreadmist Mantle.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You're back, <name>.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", rewards = "You will receive:\n\nDeathmist SandalsDeathmist LeggingsDeathmist Mantle"}
MultiLanguageQuestData['en'][8959] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Boots of Valor, Legplates of Valor and Spaulders of Valor.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!", progress = "You're back, <name>.  You must tell me all about what you've found out.  But first let us arrange for your reward.", completion = "I can't believe our lives are all but forfeit all because of a stupid medallion!  And you're sure Anthion mentioned Bodley?\n\nWell, you've done your job so let's get your reward out of the way.", rewards = "You will receive:\n\nBoots of HeroismLegplates of HeroismSpaulders of Heroism"}
MultiLanguageQuestData['en'][8960] = {title = "Bodley's Unfortunate Fate", objective = "Travel to Blackrock Mountain and use the Extra-Dimensional Ghost Revealer to find Bodley near Blackrock Spire.", description = "So we need to recover the rest of the medallion?  Finding Bodley's going to be a bit of a headache.  He went back to Blackrock Mountain to attempt to re-enter Blackrock Spire and never came back.\n\nI'd suggest taking the goblin's ghost revealing device with you, as I fear the worst might have happened.", progress = nil, completion = "I am so glad that you can see me. Finally someone to talk to!\n\nWill you help us, &lt;name&gt;? Help to undo the wrong that we perpetrated and put things to right? If it's true that you already have the Top Piece of Lord Valthalak's Amulet, then I think I can point you in the right direction to acquire the other two parts, reunite them and put an end to all of this.\n\nOh, by the way, hello, my name is Bodley. Nice to meet you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8961] = {title = "Three Kings of Flame", objective = "Gather the Incendicite of Incendius, the Ember of Emberseer and the Cinder of Cynders, along with a Hallowed Brazier, and return them to Bodley inside Blackrock Mountain.", description = "In order to summon Lord Valthalak we're first going to need to gather the other two-thirds of the amulet. To do that we need to get a brazier and some special coals to burn in it.\n\nThere are three nobles of fire, Lord Incedius in Blackrock Depths, Pyroguard Emberseer in Blackrock Spire and The Duke of Cynders in Silithus, with what we need. Collect from each a piece of their remains, and then return to me with a Hallowed Brazier, which can be purchased from the Argent Dawn if you are honored by them.", progress = "It was our folly... our doom that we took that last job. If only we hadn't inadvertently stolen Lord Valthalak's spirit, which was contained in the amulet; if only there weren't those in our mercenary group that had been so greedy and divided it up amongst themselves. I'd be alive today, maybe tossing back a beer, or tossing one of my kids into the air.\n\n<name>, don't let the avarice of the ignoble in our old mercenary company be your doom as well.", completion = "I'm impressed, &lt;class&gt;, but there's no time to lose. I will give you your next task, because you will still need to acquire a few more important components before we can proceed.\n\nSpeak to me again when you feel that you are ready for the challenge that lies ahead.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8962] = {title = "Components of Importance", objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the remains into the brazier.\n\nNow all that is left is to go to the lower portion of Blackrock Spire, to the chamber where War Master Voone resides in Tazz'Alaor, and use the brazier to summon forth the corrupted spirit of my former cohort, Mor Grayhoof. He cannot rest until the amulet piece is taken from him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8963] = {title = "Components of Importance", objective = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the relic into the brazier.\n\nNow all that is left is to go to the Shrine of Eldretharr in the east wing of Dire Maul, and use the brazier to summon forth the spirit of my former cohort, Isalien. Her spirit has been corrupted by her possession of the piece of Valthalak's amulet, and the portion of his soul within it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8964] = {title = "Components of Importance", objective = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the sword into the brazier.\n\nNow all that is left is to get into The Crimson Throne inside The Scarlet Bastion at Stratholme, and use the brazier to summon forth the remains of my former cohorts, Jarien and Sothos. Their souls have been twisted further by their possession of Valthalak's amulet piece and his spirit within.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8965] = {title = "Components of Importance", objective = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the brazier, and the means to light it, we still need another component to suffuse it with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the ashes into the brazier.\n\nNow all that is left is to get into Scholomance, to Ras Frostwhisper's chamber, and use the brazier to summon forth the spirit of my former cohort, Kormok. The amulet piece, and Valthalak's spirit within, has corrupted him even further, and he will not rest until you forcibly take it from him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8966] = {title = "The Left Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", progress = "Then it is done? You have retrieved the Left Piece of Lord Valthalak's Amulet and finally put to rest the spirit of my old companion, Mor Grayhoof?", completion = "You have done a great thing, &lt;name&gt;. One spirit rests in peace, but there is still much work to be done before we can put all of this behind us.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8967] = {title = "The Left Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", progress = "Surely you haven't already dealt with the salvation of Isalien's spirit and the retrieval of the Left Piece of Lord Valthalak's Amulet, <name>?", completion = "Thank you, &lt;name&gt;, for putting Isalien's spirit to rest. Now, perhaps, she will find peace with her goddess. But, there is still a great deal of work ahead of us if we are to get out of this fine pickle we find ourselves in.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8968] = {title = "The Left Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the left piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", progress = "Does this mean then, <class>, that you've already put the souls of those two fools to rest and retrieved the Left Piece of Lord Valthalak's Amulet?", completion = "I suppose it's for the best that the souls of those two have finally been put to rest, even if I didn't like them while they were alive. In any case, we have what we were after, and that is definitely a good thing!\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8969] = {title = "The Left Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the Left Piece of Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", progress = "I commend you, <name>, if you have returned with the left piece of the amulet. If not, however, please take care of that as there is no time to waste, I assure you!", completion = "Good work, &lt;name&gt;! Kormok wasn't all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. But, there is more work ahead of us.\n\nUnfortunately, I do not know the location of the one who died with the right piece of the amulet in their possession. But do not fear; in life I was a dabbler in the art of divination, so I have another task for you, which is going to enable us to ferret out the final piece.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8970] = {title = "I See Alcaz Island In Your Future...", objective = "Gather 20 Bloodkelp from the Strashaz naga and then return to Bodley inside Blackrock Mountain.", description = "As I was saying, <class>, in my living years I flirted with becoming a diviner. But, there really wasn't as much profit in it as you might imagine, mostly because it's dangerous and the reagents are rare and expensive. However, I do know enough to be able to pinpoint the final piece of the amulet, and the spirit of my former comrade along with it.\n\nThis is where you come in, <name>. I need you to go to Alcaz Island off the coast of Dustwallow Marsh and collect Bloodkelp from the Strashaz naga that live there.", progress = "Bloodkelp, <name>, a big stack of it, that's what I need to power my divinatory spells. You're likely to need to take at least a couple of friends along with you to Alcaz Island to gather it up... those Strashaz are a nasty lot!", completion = "To be honest, &lt;name&gt;, I'm surprised you made it back in one piece. Then again, I guess Alcaz Island is the least of your worries right now.\n\nOk, give me a moment here... divination isn't something that you can just snap your fingers and expect accurate answers from.", rewards = "The following spell will be cast on you:\n\nDivining Trance\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][8971] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nStormwind Gift Collection"}
MultiLanguageQuestData['en'][8972] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nOrgrimmar Gift Collection"}
MultiLanguageQuestData['en'][8973] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nDarnassus Gift Collection"}
MultiLanguageQuestData['en'][8974] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUndercity Gift Collection"}
MultiLanguageQuestData['en'][8975] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nThunder Bluff Gift Collection"}
MultiLanguageQuestData['en'][8976] = {title = "REUSE", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nIronforge Gift Collection"}
MultiLanguageQuestData['en'][8977] = {title = "Return to Deliana", objective = "Bring the Extra-Dimensional Ghost Revealer  to Deliana in Ironforge.", description = "It's been great working with you, <name>.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", progress = "You've returned?", completion = "Excellent!  You've done well, &lt;name&gt;.  I'm not sure I trust the goblin's craftsmanship, but I'm left with no other choice.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8978] = {title = "Return to Mokvar", objective = "Return to Mokvar in Orgrimmar with the Extra-Dimensional Ghost Revealer.", description = "It's been great working with you, <name>.  Here is the finished product.\n\nI hope it helps you in your current endeavors.  And hey, if you don't mind, help spread the word.  I wouldn't mind having more customers!", progress = "You've returned with the device?", completion = "You've returned with the device!  I'm impressed by your dedication, &lt;name&gt;.  Excellent work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8979] = {title = "Fenstad's Hunch", objective = "Bring 1 Cologne Bottle and 1 Perfume Bottle to Apothecary Zinge in the Undercity's Apothecarium.", description = "I believe I know the cause of this recent behavior. Have you smelled the new fragrance on the wind, over the stink of the canals? The new colognes and perfumes that have come into fashion?\n\nOur thinking has been clouded by some foul alchemy.\n\nThere is only one way to be sure - bring a bottle of cologne and perfume to my friend, Apothecary Zinge. The Royal Apothecary Society will find the truth.\n\n I will reimburse you for their purchase when you return.", progress = "How may I serve you?", completion = "Another one of Fenstad's obsessions, I see. Does he think that the Royal Apothecary Society has nothing better to do than to perform his little investigations?\n\nVery well, I will humor him once again.", rewards = nil}
MultiLanguageQuestData['en'][8980] = {title = "Zinge's Assessment", objective = "Return to Fenstad Argyle outside the bank in the Undercity.", description = "This is unexpected. It looks like Fenstad might be on to something after all. I found traces of substances used in mind control potions.\n\nIt isn't unheard of for perfumes to have some of this, but a few of the ingredients I detected... This is serious alchemy, along the abilities of a member of the Royal Apothecary Society.", progress = nil, completion = "So, I was right. We must waste no time. We must determine the source of these tainted fragrances.\n\nHere, to repay you for the purchase of the cologne and perfume.", rewards = "You will receive:\n\nBox of ChocolatesHandful of Rose PetalsLove Rocket"}
MultiLanguageQuestData['en'][8981] = {title = "Gift Giving", objective = "Have you come to deliver a present of love and adoration to your favorite leader?", description = nil, progress = "Have you come to deliver a present of love and adoration to your favorite leader?", completion = "Wonderful! Wonderful! I will add this to the pile of other gifts.\n\nI didn't expect so many! You must truly love your leaders.\n\nNow, let me just add one more to the count...", rewards = "You will be able to choose one of these rewards:\n\nHandful of Rose PetalsSilver Shafted ArrowLove Rocket\n\nThe following spell will be cast on you:\n\nHoliday - Valentine, gift given\n\nYou will also receive:\n\nBox of Chocolates"}
MultiLanguageQuestData['en'][8982] = {title = "Tracing the Source", objective = "Speak with Innkeeper Norman in the Undercity.", description = "We must find who the supplier is. I noticed Apothecary Katrina with a bottle of the perfume tucked in her pack. She told me that she purchased it from Norman, the innkeeper.", progress = nil, completion = "Ah yes, I just recently received stock of the perfume and cologne. I don't know how long I can keep it on the shelves - seems like no one can get enough of it.\n\nIf you ask me, I don't see what the big deal is.", rewards = nil}
MultiLanguageQuestData['en'][8983] = {title = "Tracing the Source", objective = "Speak with Mara Rennick at the tailor's shop in the Undercity's Mage Quarter.", description = "Something's wrong with my product? Well, I've never seen so many people wanting something so badly.\n\nI bought my supply from a merchant named Mara Rennick. She's new in town.\n\nShe mentioned she had some goods she had to deliver to the tailor in the Mage Quarter.", progress = nil, completion = "I'm afraid I sold my entire supply of perfume and cologne to Norman, the innkeeper. If you'd like some, you should speak with him - assuming he has any left.\n\nYou shouldn't waste any time, though. I think you'll find the cologne  irresistible.", rewards = nil}
MultiLanguageQuestData['en'][8984] = {title = "The Source Revealed", objective = "Find Apothecary Staffron Lerent in the Hillsbrad Foothills past Ravenholdt Manor.", description = "Look, the actions of a rogue apothecary are not my concern. If he's undermining our efforts, then let me be the first to point you in the right direction\n\nIf he's innocent, then he's got nothing to hide, right?\n\nI purchased the goods from Apothecary Staffron Lerent. He's working in a secluded area past Ravenholdt Manor in the hills over Hillsbrad. To be honest with you, I thought he was a little odd.", progress = nil, completion = "Yes, I made those fragrances. Wonderful smell, isn't it? Irresistible.\n\nOnce the warriors of Alliance and Horde alike are smitten with these feelings of love, they will be powerless to stop the rise of the Shadow Council.\n\nThey will be weakened, unprepared. As they worry for their loved ones, they will lose their edge.\n\nThe solution was so simple. Why did it take me so long to come upon it? The weakness of all is through the heart. And there is nothing you can do to stop the inevitable.", rewards = nil}
MultiLanguageQuestData['en'][8985] = {title = "More Components of Importance", objective = "Acquire a Starbreeze Village Relic and return it to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nIsalien, our priestess, grew up in Winterspring at Starbreeze Village. I need you to gather a Starbreeze Village Relic from the Frostmaul giants of Frostwhisper Gorge in southern Winterspring, who are known for raiding to the north from time to time.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the relic into the brazier.\n\nNow all that is left is to go to the Shrine of Eldretharr in the east wing of Dire Maul, and use the brazier to summon forth the spirit of my former cohort, Isalien. Her spirit has been corrupted by her possession of the piece of Valthalak's amulet, and the portion of his soul within it.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", rewards = "You will be able to choose one of these rewards:\n\nBloodkelp Elixir of DodgingBloodkelp Elixir of Resistance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8986] = {title = "More Components of Importance", objective = "Acquire Druidical Remains and return them to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nMor Grayhoof, our most prominent druid, had many close friends amongst the Cenarion Circle, some of which have fallen to the silithid. I need you to retrieve some Druidical Remains from the silithid that inhabit the environs of Hive'Regal in southeastern Silithus.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the remains into the brazier.\n\nNow all that is left is to go to the lower portion of Blackrock Spire, to the chamber where War Master Voone resides in Tazz'Alaor, and use the brazier to summon forth the corrupted spirit of my former cohort, Mor Grayhoof. He cannot rest until the amulet piece is taken from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", rewards = "You will be able to choose one of these rewards:\n\nBloodkelp Elixir of DodgingBloodkelp Elixir of Resistance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8987] = {title = "More Components of Importance", objective = "Retrieve a Brilliant Sword of Zealotry and return it to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to summon the remains of my deceased, former comrades.\n\nThe siblings, Jarien and Sothos, were believers in the way of the Scarlet Crusade. They aspired to knighthood within that vile organization. Go to Tyr's Hand in Eastern Plaguelands and retrieve a Brilliant Sword of Zealotry from the praetorians there.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the sword into the brazier.\n\nNow all that is left is to get into The Crimson Throne inside The Scarlet Bastion at Stratholme, and use the brazier to summon forth the remains of my former cohorts, Jarien and Sothos. Their souls have been twisted further by their possession of Valthalak's amulet piece and his spirit within.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", rewards = "You will be able to choose one of these rewards:\n\nBloodkelp Elixir of DodgingBloodkelp Elixir of Resistance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8988] = {title = "More Components of Importance", objective = "Obtain Soul Ashes of the Banished and return them to Bodley inside Blackrock Mountain.", description = "<class>, listen closely. Now that we have the location of the last amulet piece, we still need another component to suffuse the brazier with; something that will provide a focus strong enough to entice the spirit of my deceased, former comrade.\n\nAn ogre necromancer that traveled with us, Kormok, delighted in summoning forth the souls of the banished dead of Purgation Isle, off the south coast of the Hillsbrad Foothills. Go there and retrieve some Soul Ashes of the Banished from their remains.", progress = "Have you returned already then, <class>, with what I sent you out to gather?", completion = "A job well done, &lt;name&gt;. I will imbue the essence of the ashes into the brazier.\n\nNow all that is left is to get into Scholomance, to Ras Frostwhisper's chamber, and use the brazier to summon forth the spirit of my former cohort, Kormok. The amulet piece, and Valthalak's spirit within, has corrupted him even further, and he will not rest until you forcibly take it from him.\n\nOh, by the way, I had some leftover bloodkelp from your trip to Alcaz Isle, so I made it into some potions for you. Take your pick!", rewards = "You will be able to choose one of these rewards:\n\nBloodkelp Elixir of DodgingBloodkelp Elixir of Resistance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][8989] = {title = "The Right Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Mor Grayhoof and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "My friend, Mor Grayhoof, was the first to fall victim to possession of a piece of Lord Valthalak's amulet, and the corrupting spirit fragment that it contains. After stealing Valthalak's spellbook and amulet, we fled for our lives from the upper portion of Blackrock Spire. Along the way, Mor fell into the lower portion of the spire.\n\nLater, we discovered that he survived the fall, only to be captured and tortured by War Master Voone. A few spectral assassins snuck in and slew him right in front of Voone.", progress = "Then it is done? You have retrieved the Right Piece of Lord Valthalak's Amulet, recombined the amulet into one whole, and finally put to rest the spirit of my old companion, Mor Grayhoof?", completion = "Thank you for helping Mor Grayhoof, &lt;name&gt;. Another spirit rests in peace, and we now have the reassembled amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8990] = {title = "The Right Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Isalien and slay her. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "It became known to us in later days, as we were doing what we could ourselves to survive, that Isalien, a night elf priestess of our company, had gone to the night elvic ancestral city, now known as Dire Maul. From what we gathered, she went there both for personal reasons and also to unlock the secrets of the piece of the amulet that she had in her possession.\n\nShe didn't quite make it, though. Word got back to us that she was ambushed at the Shrine of Eldretharr by Alzzin the Wildshaper and his forces.", progress = "Surely you haven't already dealt with the salvation of Isalien's spirit and the retrieval of the Right Piece of Lord Valthalak's Amulet, <name>? Be sure to recombine the pieces of the amulet before handing it to me.", completion = "Thank you, &lt;name&gt;, for putting Isalien's spirit to rest. Now, perhaps, she will find peace with her goddess. And, we have the reassembled amulet, as well! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8991] = {title = "The Right Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth Jarien and Sothos and slay them. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "The siblings, Jarien and Sothos, decided to join the Scarlet Crusade upon the disbanding of our mercenary company. They took the right piece of Lord Valthalak's amulet with them. Good riddance, I say, but we need that piece back.\n\nFrom what we could gather, they were actually slain by Grand Crusader Dathrohan himself for failing the initiation rites inside his chamber in the Scarlet Bastion.\n\nIn any case, we... meaning you, are still going to need to retrieve that piece of the amulet.", progress = "Does this mean then, <class>, that you've already put the souls of those two fools to rest and recombined the pieces of Lord Valthalak's Amulet?", completion = "I suppose it's for the best that the souls of those two have finally been put to rest, even if I didn't like them while they were alive. In any case, we have what we were after, and now the amulet is reassembled! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8992] = {title = "The Right Piece of Lord Valthalak's Amulet", objective = "Use the Brazier of Beckoning to summon forth the spirit of Kormok and slay him. Return to Bodley inside Blackrock Mountain with the recombined Lord Valthalak's Amulet and the Brazier of Beckoning.", description = "Now we have what we need, so it's time to discuss who it is that you'll be summoning next.\n\nKormok was ok for an ogre, right up until he turned to necromancy. After that, things got creepy for just about everyone in the outfit. It was no surprise then when he took his piece of the amulet and returned to his new home, Scholomance.\n\nBut even there, or perhaps especially there, he was not safe from the spectral assassins. They slew him right in front of his master, Ras Frostwhisper.", progress = "I commend you, <name>, if you have returned with the completed amulet. If not, however, please take care of that as there is no time to waste, I assure you!", completion = "Good work, &lt;name&gt;! Kormok wasn't all that bad for an ogre, at least not while he was still alive, so I hope he gets the rest that he deserves. And now we have the completed amulet! But we still have the hardest test ahead of us.\n\nIn order for the brazier to be attuned to calling forth Lord Valthalak, there are a few more items that need to be gathered and brought back to me here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8993] = {title = "Gift Giving", objective = "Have you come to deliver a present of love and adoration to your favorite leader?", description = nil, progress = "Have you come to deliver a present of love and adoration to your favorite leader?", completion = "Wonderful! Wonderful! I will add this to the pile of other gifts.\n\nI didn't expect so many! You must truly love your leaders.\n\nNow, let me just add one more to the count...", rewards = "You will be able to choose one of these rewards:\n\nHandful of Rose PetalsSilver Shafted ArrowLove Rocket\n\nThe following spell will be cast on you:\n\nHoliday - Valentine, gift given\n\nYou will also receive:\n\nBox of Chocolates"}
MultiLanguageQuestData['en'][8994] = {title = "Final Preparations", objective = "Gather 40 Blackrock Bracers and acquire a Flask of Supreme Power. Return them to Bodley inside Blackrock Mountain.", description = "We're nearly there, <class>. All that is left is to retrieve a few more components so that I can attune the brazier and enable it to beckon forth Lord Valthalak.\n\nTo begin I must ask you to journey forth into Blackrock Spire and slay the orcs therein. They wear bracers that contain trace metals that I will need, so I'll need more than a few to extract the right amount out of them. Then, to complete the imbuing process, you'll need to bring me a Flask of Supreme Power.\n\nGood luck, <name>!", progress = "We've come a long way, <name>, and I just wanted to say that no matter what happens, thank you! You've put yourself in mortal danger to try to help the surviving members of our mercenary company, The Veiled Blade, and as far as I'm concerned, you're one of us now.", completion = "That's it then. I'll extract the metal from the bracers and imbue the brazier with these final components. Then it will be ready for you to summon Lord Valthalak, and finally return his spirit amulet to him.\n\nYou've come quite a distance, &lt;name&gt;, don't falter now that the end is in sight!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8995] = {title = "Mea Culpa, Lord Valthalak", objective = "Use the Brazier of Beckoning to summon Lord Valthalak. Dispatch him, and use Lord Valthalak's Amulet on the corpse. Then, return Lord Valthalak's Amulet to the Spirit of Lord Valthalak.", description = "All is now ready, <name>.\n\nWhen alive, Lord Valthalak used to inhabit what is now The Beast's chamber. Go there and use the Brazier of Beckoning to summon forth Lord Valthalak. It will reincorporate him, so he'll have to be killed again. I'd take care of The Beast first, and be sure take enough friends along to survive the upper portion of Blackrock Spire.\n\nOnce you've dispatched Valthalak, use the amulet on his corpse. With his spirit reunified, he'll likely want his amulet back, as well.\n\nGood luck!", progress = "<class>, you dare disturb my rest!", completion = "How fortunate for you that I know you're not part of the original group that stole this from me.\n\nI'll take back what is mine now, mortal! Give the amulet to me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8996] = {title = "Return to Bodley", objective = "Return to Bodley inside Blackrock Mountain and give him the Brazier of Beckoning.", description = "I will ignore your impertinence this time, <class>, because you have done a noble thing today; returning the rest of my stolen spirit to me. Despite your obviously weak nature, <race>, you have shown courage where those that stole from me did not, and probably never could!\n\nReturn to them, before I change my mind and slay you where you stand. Go back and tell them that they are safe... for now.", progress = "<name>, you're back and still alive! Well, at least that makes one of us.\n\nYou're going to have to tell me all about it!", completion = "He really said all of that? Wow, I can't believe he's going to call off the spectral assassins and stalkers, even if he did hint at causing my living companions further harm in the future.\n\nThis is a great day, &lt;name&gt;! You've accomplished what few ever could, and absolved us, at least in part, of some of our past sins.\n\nThank you! As a sign of appreciation, I'd like to give you this. You can use it to summon forth spirits at the same haunted locations that you already have, and a few others, too.", rewards = "You will receive:\n\nBrazier of InvocationBrazier of Invocation: User's Manual"}
MultiLanguageQuestData['en'][8997] = {title = "Back to the Beginning", objective = "Speak with Deliana at The High Seat in Ironforge.", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Deliana in Ironforge and tell her what's happened.", progress = nil, completion = "I am very happy to see you return to me safely, &lt;name&gt;. You look well, if not a bit worse for the wear.\n\nCome, tell me of all that has transpired.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8998] = {title = "Back to the Beginning", objective = "Speak with Mokvar at Grommash Hold in Orgrimmar's Valley of Wisdom.", description = "I suppose that this is goodbye then, my friend. But, I'll always be here if you want to come back and talk with me from time to time. Probably while you're loitering around waiting for your buddies to join you for a raid on Blackrock Spire.\n\nGo, before I start to cry. Go back to Mokvar in Orgrimmar and tell him what's happened.", progress = nil, completion = "I am pleased to see that you have survived, &lt;name&gt;. You look well, if not a bit more seasoned.\n\nCome, tell me of all that has transpired.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][8999] = {title = "Saving the Best for Last", objective = "Give Deliana your Wildheart Cowl and Wildheart Vest.", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", progress = "As per our deal, are you ready to hand over your Wildheart pieces in exchange for your new Feralheart Cowl and Vest?", completion = "I'm going to miss you, &lt;name&gt;. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.", rewards = "You will receive:\n\nFeralheart CowlFeralheart Vest"}
MultiLanguageQuestData['en'][9000] = {title = "Saving the Best for Last", objective = "Give Deliana your Beaststalker's Cap and Beaststalker's Tunic.", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBeastmaster's CapBeastmaster's Tunic"}
