MultiLanguageQuestData['en'][9006] = {title = "Saving the Best for Last", objective = "Give Deliana your Helm of Valor and Breastplate of Valor.", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.", progress = "As per our deal, are you ready to hand over your Valor pieces in exchange for your new Helm and Breastplate of Heroism?", completion = "I'm going to miss you, &lt;name&gt;. I owe you such a debt of gratitude; I think I'll never be able to repay it.\n\nI hope that you enjoy your new head and chest armor, and that it protects you for a long time to come.", rewards = "You will receive:\n\nHelm of HeroismBreastplate of Heroism"}
MultiLanguageQuestData['en'][9007] = {title = "Saving the Best for Last", objective = "Give Mokvar your Wildheart Cowl and Wildheart Vest.", description = "A truly amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.", progress = "Are you ready to give me your Wildheart pieces in exchange for your new Feralheart Cowl and Vest?", completion = "I will truly miss you, &lt;name&gt;. There is a debt that I owe you, which I may never be able to repay.\n\nEnjoy your new head and chest armor. May it protect you for a long time to come, and help you to achieve even greater honor!", rewards = "You will receive:\n\nFeralheart CowlFeralheart Vest"}
