MultiLanguageQuestData['en'][9093] = {title = "Dreamwalker Wristguards", objective = "Rayne at Light's Hope Chapel in the Eastern Plaguelands will make Dreamwalker Wristguards if you bring her the following: 1 Desecrated Wristguards, 6 Wartorn Leather Scraps, 1 Arcane Crystal and 2 Cured Rugged Hides.", description = "Many heroes fell in the last war and many continue to perish at the hands of the Scourge to this day. From the corpses of the fallen, the armor is stripped and taken back to Naxxramas to be used for unknown purposes.\n\nRecover the desecrated armor and wartorn armor scraps and supply to me the other material components I require and I will craft Dreamwalker armor.", progress = "The material cost is high, but soon forgotten.", completion = "Your Dreamwalker wristguards are ready, &lt;name&gt;.", rewards = "You will receive:\n\nDreamwalker Wristguards"}
MultiLanguageQuestData['en'][9094] = {title = "Argent Dawn Gloves", objective = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", description = nil, progress = "If you bring me thirty necrotic runes, I will give you your choice of hand protection in return. These should prove valuable in our fight against the undead Scourge.", completion = "You've done well, &lt;name&gt;. Take your pick of hand protection in thanks for your efforts.", rewards = "You will be able to choose one of these rewards:\n\nGloves of Undead CleansingHandwraps of Undead SlayingHandguards of Undead SlayingGauntlets of Undead Slaying"}
MultiLanguageQuestData['en'][9095] = {title = "Frostfire Robe", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Robe if you bring her the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Robe"}
MultiLanguageQuestData['en'][9096] = {title = "Frostfire Leggings", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Leggings if you bring her the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Leggings"}
MultiLanguageQuestData['en'][9097] = {title = "Frostfire Circlet", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Circlet if you bring her the following: 1 Desecrated Circlet, 15 Wartorn Cloth Scraps, 3 Mooncloth and 3 Nexus Crystals.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Circlet"}
