MultiLanguageQuestData['en'][9100] = {title = "Frostfire Gloves", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Gloves if you bring her the following: 1 Desecrated Gloves, 8 Wartorn Cloth Scraps and 4 Mooncloth.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Gloves"}
MultiLanguageQuestData['en'][9101] = {title = "Frostfire Belt", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make a Frostfire Belt if you bring her the following: 1 Desecrated Belt, 8 Wartorn Cloth Scraps, 2 Arcane Crystals and 2 Mooncloth.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Belt"}
MultiLanguageQuestData['en'][9102] = {title = "Frostfire Bindings", objective = "Archmage Angela Dosantos at Light's Hope Chapel in the Eastern Plaguelands will make Frostfire Bindings if you bring her the following: 1 Desecrated Bindings, 6 Wartorn Cloth Scraps, 1 Arcane Crystal and 1 Nexus Crystal.", description = "As a Watcher, I was allowed access to many of Medivh's personal effects. Among those items, I found the tomes most enlightening. While the majority of the books were filled with - to put it bluntly - tripe, there were some gems. One of those tomes documented the creation of a set of armor fit for an archmage: Frostfire.\n\n<Angela points to her head.>\n\nIt's all in here and I am willing to share the fruits of that knowledge with you as long as you are able to provide me with the necessary materials.", progress = "With the proper materials and reagents, I am able to reform the mythical Frostfire armor.", completion = "Do not forget that power left unchecked is as destructive as power left unused, &lt;class&gt;. Use discretion when donning Frostfire.", rewards = "You will receive:\n\nFrostfire Bindings"}
MultiLanguageQuestData['en'][9103] = {title = "Plagueheart Robe", objective = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands will make a Plagueheart Robe if you bring him the following: 1 Desecrated Robe, 25 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", description = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.\n\nAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die; but I've already explained this...", progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n&lt;Mataus shakes his head disapprovingly.&gt;\n\nNow take it and get out of my sight.", rewards = "You will receive:\n\nPlagueheart Robe"}
MultiLanguageQuestData['en'][9104] = {title = "Plagueheart Leggings", objective = "Mataus the Wrathcaster at Light's Hope Chapel in the Eastern Plaguelands will make Plagueheart Leggings if you bring him the following: 1 Desecrated Leggings, 20 Wartorn Cloth Scraps, 4 Mooncloth and 2 Nexus Crystals.", description = "I make no pretenses, maggot. The darkness Plagueheart items hold could very well destroy the both of us. That is why the price is so high. If I'm going to die, it's going to be as a rich man.\n\nAnd I don't give an ounce of gnoll spit how you die, only that you do as I ask. Bring me what I require and we will both benefit - or die; but I've already explained this...", progress = "The prodigal rodent returns! Have you what I require?", completion = "Do you see? Do you now understand the power? Purification... What fools...\n\n&lt;Mataus shakes his head disapprovingly.&gt;\n\nNow take it and get out of my sight.", rewards = "You will receive:\n\nPlagueheart Leggings"}
