MultiLanguageQuestData['en'][10464] = {title = "Sage's Vow", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", description = "You've made your pledge, <class>.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.\n\nFail and the timeline as we know it will be unravelled!", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, &lt;race&gt;.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10465] = {title = "Restorer's Vow", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", description = "You've made your pledge, <class>.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, &lt;race&gt;.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10466] = {title = "Champion's Vow", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", description = "You've made your pledge, <class>.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, &lt;race&gt;.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained easily.", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10467] = {title = "Defender's Vow", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Honored reputation with the Scale of the Sands.", description = "You've made your pledge, <class>.  Now it is up to you to see it through.\n\nServe the Scale of the Sands well and you will be rewarded.  Fail and the timeline as we know it will be unravelled!", progress = "You continue to serve us well, <name>.", completion = "You've proved your worth, &lt;race&gt;.  Up to a certain point, at least.\n\nThe favor of Nozdormu's prime mate is not obtained quickly.", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10468] = {title = "Sage's Oath", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", description = "You've carried out the promise you made to us, <name>.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10469] = {title = "Restorer's Oath", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", description = "You've carried out the promise you made to us, <name>.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10470] = {title = "Champion's Oath", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", description = "You've carried out the promise you made to us, <name>.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10471] = {title = "Defender's Oath", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Revered reputation with the Scale of the Sands.", description = "You've carried out the promise you made to us, <name>.  And for that you've gained the recognition you deserve.\n\nAs you continue to become attuned with past events surrounding mount Hyjal, I can continue to tap into the power contained in your ring.  It won't be long until it has reached its full potential.", progress = "You've returned.  You wish to speak to me?", completion = "You are a worthy ally indeed.  As you grow in power so does the band of eternity!", rewards = "You will receive:\n\nBand of Eternity"}
MultiLanguageQuestData['en'][10472] = {title = "Sage's Covenant", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", progress = "May time always be on your side, <name>.", completion = "You are one with time, &lt;name&gt;.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", rewards = "You will receive:\n\nBand of the Eternal Sage"}
MultiLanguageQuestData['en'][10473] = {title = "Restorer's Covenant", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", progress = "May time always be on your side, <name>.", completion = "You are one with time, &lt;name&gt;.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", rewards = "You will receive:\n\nBand of the Eternal Restorer"}
MultiLanguageQuestData['en'][10474] = {title = "Champion's Covenant", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", progress = "May time always be on your side, <name>.", completion = "You are one with time, &lt;name&gt;.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", rewards = "You will receive:\n\nBand of the Eternal Champion"}
MultiLanguageQuestData['en'][10475] = {title = "Defender's Covenant", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.", progress = "May time always be on your side, <name>.", completion = "You are one with time, &lt;name&gt;.  You are one with us.\n\nBehold!  Power beyond mortal understanding is unleashed from even that small remnant of the Well of Eternity.\n\nAccept this gift so that all may know of your covenant with the Scale of the Sands.... so that all may know of your covenant with time itself!", rewards = "You will receive:\n\nBand of the Eternal Defender"}
MultiLanguageQuestData['en'][10476] = {title = "Fierce Enemies", objective = "Warden Moi'bff Jill at Telaar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", description = "If you seek to prove your loyalty to us, there is no better way than to fight against our enemies.\n\nOf these, there are none that can match the ogres in strength and fierceness.  Bring me the warbeads they wear around their necks as proof of their demise and I'll let the others know of your prowess.", progress = "Well, <name>?  Are you all talk or do you have something to show me?", completion = "You're starting to prove your worth as an ally and combatant.  Keep up the good work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10477] = {title = "More Warbeads", objective = "Do you bear any additional obsidian warbeads, <name>?", description = nil, progress = "Do you bear any additional obsidian warbeads, <name>?", completion = "You continue to prove your worth to us, &lt;name&gt;.  May your strength never fail you.", rewards = nil}
MultiLanguageQuestData['en'][10478] = {title = "More Warbeads!", objective = "Have you obtained more warbeads, <name>?", description = nil, progress = "Have you obtained more warbeads, <name>?", completion = "You continue to prove your strength and honor, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['en'][10479] = {title = "Proving Your Strength", objective = "Warden Bullrok at Garadar wants you to obtain 10 Obsidian Warbeads from the various ogres that inhabit Nagrand.", description = "Though we seek a peaceful life, our enemies are many.  Of these, none match the ogres in sheer brute power.\n\nIf you seek to prove your prowess to us, bring me the warbeads they wear around their necks.  I will tell others of your accomplishments.", progress = "You have something to show me, <name>?", completion = "You are a strong ally indeed, &lt;name&gt;.  Going head to head against the ogres of Outland is not something that just anyone can do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10480] = {title = "Enraged Spirits of Water", objective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 5 Watery Souls.", description = "The Illidari naga of the region have taken control of the only clean water supply that exists in Shadowmoon Valley.\n\nDirectly north of here you will find the lair of the naga: Coilskar. Around Coilskar are pockets of agitated water that howl to the land in anguish. It is at those pockets that the enraged spirits of water now wander.\n\nTravel to Coilskar and use the totem of spirits to capture watery souls. You will find the largest concentration of these spirits near Coilskar Cistern.", progress = "Wherever you find naga you will almost certainly find tortured water spirits.", completion = "Only air remains, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10481] = {title = "Enraged Spirits of Air", objective = "Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley wants you to use the Totem of Spirits to capture 10 Airy Souls.", description = "Venture southeast, hero. When you see fields of gigantic blue crystals jutting out from the land, you will have reached your destination. It is there, at the Netherwing Fields, that you will find the enraged spirits of air. They roam the cliffs and mountain bases that surround the fields.\n\nDestroy their tortured forms and capture their souls with the totem of spirits. Return to me when this is done.", progress = "Soon, we will speak with the spirits.", completion = "Allow me to reward you for undertaking such an arduous task, hero.\n\nNow, we must get to work! Please stand back so that I may place the totem and unleash the souls.", rewards = "You will be able to choose one of these rewards:\n\nBoots of the SkybreakerGrips of the VoidManimal's CinchSkybreaker's Pauldrons\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10482] = {title = "Fel Orc Scavengers", objective = "Kill 20 Bonechewer Orcs and return to Amadi in Honor Hold.", description = "Scavengers, orcs of the Bonechewer clan, skulk about the ruined battlements overlooking the Path of Glory.  We must assume that these fel orcs are gathering war machine parts for their masters within Hellfire Citadel -- they must be stopped!\n\nFind Bonechewer orcs to the north, <name>.  Find them and slay them!  But use caution, for although these orcs are the lesser of the fel orc clans, their strength is the match of any green-skinned orc we've faced thus far...", progress = "The Bonechewers appear in large numbers, <name>.  Slay them or the fel orcs may overrun us!", completion = "Very good.  I'm sure their loss will be felt in Hellfire Citadel.  Although that dark bastion looms over us and seems nigh insurmountable, it is only with bold moves like you have made that we will find victory over the fel orcs!", rewards = "You will be able to choose one of these rewards:\n\nDesolation RodAdamantine Kite ShieldLandslide BucklerHellfire SkiverIronstar Repeater\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10483] = {title = "Ill Omens", objective = "Lieutenant Amadi in Honor Hold wants you to bring 1 Cursed Talisman to Corporal Ironridge at Expedition Point.", description = "<name>, in our battles with the Bleeding Hollow clan of fel orcs, we have found upon them foreboding trinkets.  These orcs have collected the insignias of fallen Honor Hold soldiers and created cursed talismans from them.  We fear the dark magic of the Bleeding Hollow orcs have transformed our insignias into evil charms with powers against us!\n\nFind such a talisman from the Bleeding Hollow orcs of Zeth'Gor, to the east, and bring it to Corporal Ironridge at Expedition Point, northeast of Zeth'Gor.", progress = "Reporting from Honor Hold, <name>?  That's good -- our campaign against the demons and the fel orcs is running thin on able bodies!", completion = "Ah, you recovered an insignia from the Bleeding Hollow orcs?  Good -- it is outrageous that they use our own symbols against us, and mock our comrades who've fallen to those red-skinned beasts!", rewards = "The following spell will be cast on you:\n\nSet Rails Flag\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][10484] = {title = "Cursed Talismans", objective = "Bring 12 Cursed Talismans to Corporal Ironridge at Expedition Point.", description = "<name>, we cannot allow the Bleeding Hollow orcs to possess their cursed talismans!  You must acquire them for us so they may be disposed of, and so the soldiers who owned them may be honored for their sacrifices.\n\nGo to Zeth'Gor, the cursed abode of the Bleeding Hollow, and perform your grim task... return to me when you have collected the talismans.", progress = "Do you have the talismans, <name>?  It pains me to know that those cursed orcs possess our soldiers insignias...", completion = "Thank you, &lt;name&gt;.  My heart is saddened to see these talismans -- they underline the great losses we of Honor Hold have suffered against the fel orcs.  But I am heartened to see you successful against them.  If we can kill enough, perhaps we might emerge from this war victorious.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10485] = {title = "Warlord of the Bleeding Hollow", objective = "Bring Warlord Morkh's Shattered Armor to Corporal Ironridge in Expedition Point.", description = "You have shown great strength and fortune, for you have delved into Zeth'Gor and lived!  Now, let us hope your fortune holds, for I have a dire task to ask of you...\n\nWarlord Morkh sits within the barracks of Zeth'Gor, commanding his fel troops against us.  His tactics are as clever as they are cruel, and I must admit that his successes against us have cut deep.  And so, <name>, I ask you to remove Morkh from his seat.  Bring me his armor so that we might display it for our soldiers and bolster them.", progress = "Do you have Morkh's shattered armor?  Have you braved Zeth'Gor again?", completion = "You've done it!  Morkh is slain!  Now, we have a fighting chance against the fel orc beasts!\n\nThank you, &lt;name&gt;.  Your aid to the war effort here is beyond measure.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10486] = {title = "The Encroaching Wilderness", objective = "Gor'drek has asked you to slay 12 Bladewing Bloodletters. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once you have accomplished that.", description = "The Thunderlord were once a proud orc clan before they were transformed into fel orcs through the blood of Mannoroth.\n\nRecently we recovered this orc stronghold from the ogres that infest the ravine below.  They had moved in when the Thunderlord clan abandoned it.\n\nWe will keep this place and I will have your help doing so.\n\nIn the Jagged Ridge to the south and the west, there are bloodletters that have become like a plague upon us.  They eat and breed incessantly.\n\nKill them and then return to me.", progress = nil, completion = "That didn't take as long as I thought it would.  Are you sure that you dealt with as many as was necessary?\n\nVery well, there's something else that I want you to help us with.  Something far more important.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10487] = {title = "Dust from the Drakes", objective = "Gor'drek wants you to gather 4 Dusts of the Fey Drake. After doing so, return to him at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "The Alliance has recently moved in to the west, using their elven magics to grow a town and grove in a short matter of time.  We must keep their defenses weak so that they do not also grow a spine.\n\nI have a plan that will do that and more.  I want you to traverse the bridge to the southwest, which crosses over Bloodmaul Ravine and leads into the Living Grove.\n\nAttack their fey drake defenses in the Living Grove and bring back the magical dust that sometimes can be found upon their wings.", progress = "It would seem that the Alliance is determined to follow us wherever we go.  Let us teach them that we are not intimidated by their presence.\n\nDo you have that which I have requested?", completion = "Not only have you weakened their defenses, but we're going to put this dust to use in bolstering our own defenses against the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10488] = {title = "Protecting Our Own", objective = "Use Gor'drek's Ointment on 5 of the Thunderlord Dire Wolves to strengthen them and the defense of the Jagged Ridge. Then return to Gor'drek at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "With the magical dust you recovered, I have fashioned a magic ointment that will aid in our own defenses.\n\nOur dire wolves are the perfect combination of mount, sentry and friend, but the Alliance scum have been poaching them in the Jagged Ridge.\n\n<name>, I want you to take this ointment and apply it to our dire wolf friends.  The Alliance will get a rude surprise the next time that they send one of their hunting parties.\n\nBe aware though that some of the wolves may not like this, and will turn on you.", progress = "How fares the bolstering of our Thunderlord dire wolves' defenses?", completion = "Now that you have strengthened the wolves, and the Jagged Ridge's defenses, perhaps we can refocus our attentions on more deadly matters, such as the ogres?\n\nYou have done a good job in aiding us here.  We could use the help of someone capable, such as yourself, should you decide to stay.\n\nWhatever you do, you have earned my respect and appreciation.", rewards = "You will be able to choose one of these rewards:\n\nThunderlord ArmbandsDire Wolf Handler GlovesGor'drek's PauldronsWolf Chaps\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10489] = {title = "Felling an Ancient Tree", objective = "Acquire Stronglimb Deeproot's Trunk and deliver it to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "WANTED!\n\nStronglimb Deeproot, ancient of war and chief defender of the Living Grove south of Sylvanaar.\n\nFind him by heading west across the bridge that traverses the Bloodmaul Ravine.\n\nReturn his hewn trunk to Tor'chunk Twoclaws inside the Thunderlord Stronghold inn.", progress = "What's that you have there?  You're a strong one!", completion = "Stronglimb Deeproot's Trunk!  Did you chop him down by yourself?\n\nI bet you did.  You know, Rexxar and I are looking for a young, strong &lt;class&gt;, such as yourself, to help out around here, especially with the problems we continually have with the ogres.  Make sure that you follow-up with me on that possibility.\n\nWell that trunk's definitely proof, which means you're here to collect the bounty and not to listen to me talk.  Go ahead, take your pick.", rewards = "You will be able to choose one of these rewards:\n\nBear-Strength HarnessWild Horned HelmBoots of the Ancient-KillerDark Deed Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10490] = {title = "Call of Water", objective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", description = "I'm sensing that it's been a while since last you were tested.  This is because Farseer Nobundo has been asking for you.\n\nYou must have grown greatly in wisdom because you are being called to learn the mysteries of the element of water.\n\nI trust that you remember how to take the boat from Auberdine in Darkshore on Kalimdor back to the Exodar?  And that you remember where to find the farseer at the Crystal Hall inside the Exodar, yes?", progress = nil, completion = "We meet again.  I have been watching your progress from afar, &lt;class&gt;, and I am pleased.\n\nThe time has come for you to commune with the element of water, to learn its mysteries and give yourself over to the water so that you might in turn learn to master it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10491] = {title = "Call of Air", objective = "Speak with Farseer Nobundo at the Crystal Hall inside the Exodar on Azuremyst Isle.", description = "<name>, once again Farseer Nobundo has been asking for you.  It must be time for you to learn the secrets of air, the last of the elements!\n\nI want you to know that I'm very proud of all that you have accomplished thus far.  I know that you have great things ahead of you.\n\nTake the boat from Auberdine in Darkshore on Kalimdor.  Cross the Veiled Sea and seek out the farseer inside the Crystal Hall of the Exodar on Azuremyst Isle.", progress = nil, completion = "And finally we come to it, the last of the four great elements: air.  Do you think yourself wise enough to continue, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10492] = {title = "An Earnest Proposition", objective = "Acquire 15 Winterspring Blood Samples and 20 gold and bring them along with a set of Bindings of Elements to Deliana in Ironforge.", description = "Well met, <class>.  I've something that might interest you.\n\nI have in my possession a set of armor much like the one worn by those of your profession, but of much higher quality.  I'd be willing to trade the bracers for ordinary ones in exchange for a small favor.\n\nThe blood of the frostsabers and bears that inhabit Winterspring has properties I'm in need of at the moment.  Bring me a sizeable sample of it along with the bracers and a small amount of gold.  You shall find the effort worth your while.", progress = "Have you brought me what I requested of you, <name>?", completion = "Excellent!  Let's perform the trade then.  It's hard to part with this excellent armor, but I'm afraid I won't be needing it any time soon.\n\nIf you're interested in performing more work for me, I might be willing to give up the rest of the pieces.", rewards = "You will receive:\n\nBindings of The Five Thunders"}
MultiLanguageQuestData['en'][10493] = {title = "An Earnest Proposition", objective = "Acquire 15 Silithus Venom Samples and 20 gold and bring them along with a set of Lightforge Bracers to Mokvar in Orgrimmar.", description = "Hail, <class>!  I can tell by your demeanor that you've seen and done much in this world.  Yet I'm willing to wager you haven't seen a piece of armor like this.\n\nPerform a small favor for me and I'll be willing to trade it to you for an ordinary set of bracers.\n\nI'm in need of a sizeable sample of venom drawn from the spiders and scorpions that inhabit Silithus.  Bring this to me along with a few gold coins and I'll perform the exchange.", progress = "Have you obtained the items I require, <name>?", completion = "Ah, yes.  Mux will be quite happy with this.\n\nThose bracers were part of a larger armor set.  If you're interested in providing me with further assistance,  I'd be willing to consider parting with the rest of it.", rewards = "You will receive:\n\nSoulforge Bracers"}
MultiLanguageQuestData['en'][10494] = {title = "Just Compensation", objective = "Bring a Cord of Elements and a set of Gauntlets of Elements to Deliana in Ironforge.", description = "You kept your word and brought the device built by Mux.  I believe a reward is in order if I'm to keep you interested in saving my skin.  Bring me the belt and set of gloves that you wish to upgrade.  I promise the ones I give you in return will be far superior.", progress = "You're ready to perform the trade?", completion = "You've kept your end of the bargain, I shall keep mine.\n\nJust remember that I'm holding on to the best pieces until your work is finished.", rewards = "You will receive:\n\nCord of The Five ThundersGauntlets of The Five Thunders"}
MultiLanguageQuestData['en'][10495] = {title = "Just Compensation", objective = "Bring a Lightforge Belt and a set of Lightforge Gauntlets to Mokvar in Orgrimmar.", description = "You've proven to be a very reliable individual, <name>.  As much as I trust that you'll help me through this predicament, it would be wise of me to reward you according to your performance.\n\nFor now I will exchange your belt and gloves.  If we both see this through I shall make the rest of the pieces available to you.", progress = "You're ready to perform the exchange?", completion = "Our agreement remains in place.  Just remember, this is but a taste of what awaits you.  Free me of this cursed fate and I will reward you with items of truly great power.", rewards = "You will receive:\n\nSoulforge BeltSoulforge Gauntlets"}
MultiLanguageQuestData['en'][10496] = {title = "Anthion's Parting Words", objective = "Return to Deliana in Ironforge with a set of Boots of Elements, a Kilt of Elements and Pauldrons of Elements.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the medallion back together.  Return to Deliana and tell her that Bodley is her only hope for finding the remaining pieces.  Speak to her about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBoots of The Five ThundersKilt of The Five ThundersPauldrons of The Five Thunders"}
MultiLanguageQuestData['en'][10497] = {title = "Anthion's Parting Words", objective = "Return to Mokvar in Orgimmar with a set of Lightforge Boots, Lightforge Legplates and Lightforge Spaulders.", description = "Valthalak's soul was stored in this amulet.  In our greed we foolishly split it into three parts, not knowing the curse that would await us.\n\nThe only way to stop Valthalak's spell is to put the amulet back together.  Return to Mokvar and tell him that Bodley is his only hope for finding the remaining pieces.  Speak to him about any rewards you've arranged for.\n\nI, for once, shall rest in peace.  I wish you the best of luck; you shall need every bit of it!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nSoulforge BootsSoulforge LegplatesSoulforge Spaulders"}
MultiLanguageQuestData['en'][10498] = {title = "Saving the Best for Last", objective = "Give Deliana your Coif of Elements and Vest of Elements.", description = "That's an amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved. Now maybe I'll be able to sleep at night with both eyes shut.\n\nAs to your reward, I believe I have a few things that you'll really enjoy.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nCoif of The Five ThundersVest of The Five Thunders"}
MultiLanguageQuestData['en'][10499] = {title = "Saving the Best for Last", objective = "Give Mokvar your Lightforge Helm and Lightforge Breastplate.", description = "A truly amazing story, <name>! You have my thanks, and the heartfelt gratitude of all who were involved, I can assure you. Through your efforts we are delivered from the mistakes of our past.\n\nAs to your reward, I believe I have a few things that you have definitely earned and will truly enjoy.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nSoulforge HelmSoulforge Breastplate"}
MultiLanguageQuestData['en'][10500] = {title = "The Horde Needs Your Help!", objective = "Speak with Warlord Gorchuk in Orgrimmar's Valley of Spirits.Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, <class>? Will you help out with the vital preparations?You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Hello, I'm glad that you've decided to hear me out. The Horde needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Warlord Gorchuk. What do you say, <class>? Will you help out with the vital preparations?You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10501] = {title = "The Alliance Needs Your Help!", objective = "Speak with Field Marshal Snowfall in Ironforge's Military Ward.Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, <class>? Will you help out with the vital preparations?You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Hello, I'm glad that you've decided to hear me out. The Alliance needs all of the help that it can get to prepare for the Ahn'Qiraj War, and that means that we need you! Even now as we speak, official collectors are gathering the necessary material needed for the upcoming war, but we won't be able to meet our goals without your assistance, <name>!\n\nYou should go speak with the guy in charge, Field Marshal Snowfall. What do you say, <class>? Will you help out with the vital preparations?You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10502] = {title = "The Bloodmaul Ogres", objective = "Commander Skyshadow has tasked you with the destruction of any 30 Bloodmaul Ogres at Bloodmaul Outpost. Return to him at Sylvanaar in the Blade's Edge Mountains once your gruesome task is completed.", description = "There is a threat to Sylvanaar far deadlier than the Horde at Thunderlord Stronghold.\n\nI'm speaking of the native ogres of these mountains.  Just to the south and east, down in the ravine, lives the Bloodmaul clan.  While they aren't the only group of ogres that threaten us here, they are the closest.\n\nI would have you head south through the Living Grove, and then go down the path to the east, which leads to their outpost.  Slay as many of the Bloodmaul ogres at Bloodmaul Outpost as you can.", progress = "Our scouts have reported that the Bloodmaul ogres have begun to creep up the switchback, which leads up to the Living Grove from their hold.\n\nIt is unfortunate that we cannot find a way to live together in peace with the ogres, but then, when have we ever been able to do so?", completion = "This is a good first step toward securing Sylvanaar and the grove.\n\nWith their ogres not so numerous, the Bloodmaul will think twice about attacking us here.\n\nNow, if only they were the only clan of ogres that we have to worry about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10503] = {title = "The Bladespire Threat", objective = "Tor'chunk Twoclaws has tasked you with the destruction of any 30 Bladespire Ogres and 10 Bladespire Raptors at Bladespire Hold and the Bladespire Grounds. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once your task is completed.", description = "There is a threat to Thunderlord Stronghold worse than the Alliance at Sylvanaar.\n\nI speak of the ogres of these mountains.  Just to the west, down in the ravine, lies the Bladespire clan.  While they aren't the only ogres, they are the closest and they're the ones that we defeated to take this place.\n\nHead north through the Jagged Ridge, and then down the path, which leads to their hold.  Slay as many of the Bladespire ogres and their raptors as you can at Bladespire Hold and the Bladespire Grounds.", progress = nil, completion = "This is a good first step toward securing our position here against the ogres.\n\nWith their numbers decimated, the Bladespire will think twice about attempting to retake Thunderlord Stronghold.\n\nNow, if they were the only clan of ogres that we have to worry about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10504] = {title = "The Bladespire Ogres", objective = "You have been asked by Commander Skyshadow to kill any 30 Bladespire Ogres in Bladespire Hold and the Bladespire Grounds. Return to him at Sylvanaar in the Blade's Edge Mountains once you have done so.", description = "To the north of the Bloodmaul clan lies a threat more grave:  Bladespire Hold.\n\nThe Bladespire ogres are the strongest clan in the mountains, having the favor of the gronn known as Gruul the Dragonkiller, and his seven sons.\n\nNow that we've dealt with winnowing the Bloodmaul, it is time to turn our eye upon their rivals.\n\nFrom Bloodmaul Hold head north through the ravine until you come to Bladespire Hold and the Bladespire Grounds.  Slay as many of the Bladespire ogres therein as you can.", progress = nil, completion = "Your actions against both the Bloodmaul and the Bladespire ogre clans have gone a long way to securing Sylvanaar's future.  While we do not seek to expand past this patch of land, which we initially found empty, we will also not suffer those that would destroy us.\n\nAs you have done us good service, I would reward that service with the appreciation of the Alliance.", rewards = "You will be able to choose one of these rewards:\n\nOgre Vanquisher's BeltAgile Mountain BracersSylvanaar Defender's PauldronsCommander Skyshadow's Gloves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10505] = {title = "The Bloodmaul Ogres", objective = "You have been asked by Tor'chunk Twoclaws to kill any 30 Bloodmaul Ogres at Bloodmaul Outpost. Return to him at Thunderlord Stronghold in the Blade's Edge Mountains once you have done so.", description = "To the south of the Bladespire clan lies yet another threat:  Bloodmaul Outpost.\n\nWhile the Bloodmaul ogres are not the strongest clan in the mountains, not having the favor of the gronn known as Gruul the Dragonkiller, they run a close second.\n\nNow that we've dealt with winnowing the Bladespire, it is time to turn our eye upon their rivals.\n\nFrom Bladespire Hold head south through the ravine until you come to Bloodmaul Outpost.  Slay as many of the Bloodmaul ogres in the vicinity as you can.", progress = nil, completion = "Your actions against both the Bladespire and the Bloodmaul ogre clans have gone a long way to securing Thunderlord Stronghold's future.  We will not suffer those that would get in the way of our destiny here.\n\nAs you have done good work in destroying these ogres, I intend to reward you with the appreciation of the Horde.", rewards = "You will be able to choose one of these rewards:\n\nRed Hands of the ThunderlordRugged Mountain BracersTor'chunk's Foot CoversOgre Beater's Belt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10506] = {title = "A Dire Situation", objective = "Rina Moonspring wants you to take her Diminution Powder and apply it to 5 of the Bloodmaul Dire Wolves, which can be found at Bloodmaul Outpost and in Bloodmaul Ravine. After doing so, return to her at Sylvanaar in the Blade's Edge Mountains.", description = "With their wolf pack reduced, the Horde is looking for replacements.  Unfortunately there's another source nearby.\n\nThe Bloodmaul ogres in the ravine below to the east keep a strong pack as their own sentries.  I hated sending you to kill the Thunderlord wolves, so why don't we do something different this time?\n\nI've derived a magic powder from the dust that naturally falls off the wings of our fey drakes.  Sprinkle it on the Bloodmaul dire wolves to make them undesirable to the Horde.", progress = "Any luck out there?  I know that it's dangerous work to be doing this amongst the Bloodmaul ogres, but if we can avoid the killing of any more animals, I'll be happy.", completion = "I'm glad to hear that it worked.  The fewer the number of Nature's creatures that have to die, the better.\n\nWith all that you've done for us already, I must say that I'm beginning to grow very fond of your company.\n\nTake care, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10507] = {title = "Turning Point", objective = "\nUse Socrethar's Teleportation's Stone at Invasion Point: Overlord, north of Forge Base: Oblivion to transport your party to Socrethar's Landing. Once there, use Voren'thal's Presence to defeat Socrethar.\n\nPerforming quests for the Scryers will cause your Aldor reputation to decrease.", description = "This is the chance we've been waiting for, <name>.  Not only have we uncovered the evidence we need to show our people who Kael'thas is really working for, but we can prove our strength by defeating his new masters.\n\nMy frail health prevents me from aiding you in person with this endeavor, but I will offer you an object that will allow me to project my powers across the continent.", progress = "Is it done, <name>?", completion = "You are an individual of formidable power, &lt;name&gt;.  The Scryers are fortunate to count you as an ally.\n\nAs word of Kael's new allegiance spreads, more people will see things our way.  The fact that we can claim such a decisive victory against Kael'thas' new overlords puts us in a most favorable situation.\n\nI will not forget your deeds.", rewards = "You will be able to choose one of these rewards:\n\nGauntlets of the VanquisherSocrethar's GirdleNetherfused PauldronsGreaves of SpellpowerWand of the Seer\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10508] = {title = "A Gift for Voren'thal", objective = "Spymaster Thalodien at Area 52 wants you to obtain the First Half of Socrethar's Stone from Forgemaster Morug at Forge Base: Oblivion and the Second Half of Socrethar's Stone from Silroth at Forge Base: Gehenna.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", description = "I don't want to send you to Voren'thal empty-handed.  It's not in my style to be underwhelming.\n\nTo gain access to Socrethar's Seat in the north, we'll need to use his own teleporters - locked by Socrethar's teleportation stone.  The first half of the stone is in the possession of Forgemaster Morug at Forge Base Oblivion.  The second half is held by the demon Silroth at Forge Base: Gehenna.\n\nObtain these and Voren'thal will be impressed beyond words.", progress = "Have you obtained Socrethar's teleportation stone, <name>?", completion = "You do not cease to amaze me, &lt;name&gt;!  Good thing you're on our side.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10509] = {title = "Bound for Glory", objective = "Bring Socrethar's Teleportation Stone to Voren'thal the Seer at the Scryer's Tier in Shattrath City.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", description = "Now I can properly send you back to Shattrath City.  You've uncovered evidence of Kael'thas making pacts with the Burning Legion and you've got the key to the overlord's back door.\n\nMake sure Voren'thal doesn't topple over with excitement from the news - the old man's getting a bit fragile, if you know what I mean.  You'll find him inside the Seer's Library at the Scryer's Tier.", progress = nil, completion = "You have no idea what this will mean for the Scryers, &lt;name&gt;.  You will have to excuse me while I catch my breath and assess the situation.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10510] = {title = "Into the Draenethyst Mine", objective = "Bronwyn Stouthammer has asked you to collect 5 Draenethyst Mine Crystals and then return to her at Sylvanaar in the Blade's Edge Mountains.", description = "Well it's good to see someone who's willing to help out around here!\n\nBorgrim and I are part of the Explorers' League, and we're here to learn what we can of these mountains.  We've heard all sorts of tales, and I can't wait to get settled in and started.\n\nOne thing in particular has caught my attention.  The night elves speak of a place down in the ravine to the east known as the Draenethyst Mine.  It's at the south end of Bloodmaul Outpost.  I'd like some of the crystals that grow naturally therein.", progress = "Isn't this exciting?  After all of the dirt and insects of Silithus, this place is like a paradise.", completion = "Ooh, by the looks of those, they're fine specimens.  I can't wait to get my examination tools unpacked and have a real look at them!\n\nThank you!", rewards = "You will be able to choose one of these rewards:\n\nSpelunker's MantleAll-Weather ArmguardsMiner's GlovesExplorer's Boots\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10511] = {title = "Strange Brew", objective = "Borgrim Stouthammer wants you to procure 11 Bloodmaul Brutebane Brew for him. Once you've done that, return it to him at Sylvanaar in the Blade's Edge Mountains.", description = "If I'm going to start this vacation out right, then I'm going to need more brew.  Unfortunately, the elves know nothing of the fine art of fermentation.\n\nI overheard that the Bloodmaul ogres down in the ravine have plenty.  I'm willing to give it a try.\n\nDo me a favor?  Head south through the Living Grove and then down the ramp to the east into Bloodmaul Outpost and procure me some?  I hear they have big barrels of it laying around and that their brewmasters carry it around to all the other ogres.", progress = "It's getting pretty dry around here.  How am I supposed to enjoy my vacation without something to drink?", completion = "What is that smell?  Oh no, don't tell me that's the ogre brew?!\n\nI'm almost afraid to try this stuff out.  Oh well, what the hell?  Bottoms up!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10512] = {title = "Getting the Bladespire Tanked", objective = "Take the Bloodmaul Brutebane Keg and use it in an attempt to get 5 Bladespire Ogres drunk. If you're successful, return to Borgrim at Sylvanaar in the Blade's Edge Mountains.", description = "I'll not take another sip of that ill-smelling muck!  But it does give me an idea.\n\n<Borgrim gets a twinkle in his eye.>\n\nSo here's the plan.  We know that the Bloodmaul practically live off of this swill.  But I wonder what their enemies, the Bladespire ogres, think of it?\n\n<name>, I want you to take the rest of this rubbish and see if you can get the Bladespire ogres tanked.  You can find them by heading north from Bloodmaul Outpost through the ravine.", progress = "What's the word?  Are the Bladespire ogres as indiscriminate as the Bloodmaul, or did it nearly kill them like it did me?", completion = "Ah, hahaha!  That's what I thought.  I guess ogre's will drink anything.\n\nStupid, the lot of 'em!\n\nWell, I must say even though I didn't get my brew, you have given me a great start to my vacation.\n\nTell you what... we have all sorts of stuff here we don't really need.  Can I offer you something?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10513] = {title = "Oronok Torn-heart", objective = "Seek out Oronok Torn-heart on the Shattered Shelf - north of Coilskar Cistern.", description = "I do not know how we can acquire the spell that the spirits mentioned, <name>. Truth be told, I don't even know where we would start such a search.\n\n<Torlok stares off in the distance, lost in thought.>\n\nHrm... It is a long shot but it might be our only chance. There is an orc that I have seen visit this area before. I spoke to him briefly once. He is a hermit that claims to live above Coilskar Cistern to the northeast. Seek out this orc, Oronok Torn-heart.\n\nAs I said, it is a long shot.", progress = nil, completion = "Words of damnation? Never heard of 'em. Take my advice: Let the dead rest.\n\nBut since you've already come all this way, I could use some help with a few other matters. What do you say?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10514] = {title = "I Was A Lot Of Things...", objective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to recover 10 Shadowmoon Tubers from the Shattered Plains.\n\nHe also wants Oronok's Boar Whistle back when you're done.", description = "I've been a lot of things, stranger, but what I once was isn't what's important. What I am now is what matters and what I am now is a farmer.\n\nI use trained felboars to dig up tubers from the hardened earth of the Shattered Plains. Recently, though, flayers from a nest to the northeast have been attacking my animals, preventing me from gathering tubers.\n\nWould you go to the area north of here and gather tubers for me? Use this whistle while standing on a tuber mound and a boar will come dig one up!", progress = "Get me those tubers!", completion = "You say there were a lot more of those flayers than you expected? Looks like it's time to take out the trash.", rewards = "You will be able to choose one of these rewards:\n\nOronok's Tuber of HealingOronok's Tuber of AgilityOronok's Tuber of StrengthOronok's Tuber of Spell Power\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10515] = {title = "A Lesson Learned", objective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to destroy 10 Ravenous Flayer Eggs on the Shattered Plains.", description = "We need to show those flayers what happens when you mess with Oronok's business!\n\nI want you to go back to the Shattered Plains and destroy every flayer egg that you see. They'll be deep in flayer territory so keep your guard up.", progress = "No mercy!", completion = "That'll teach those damned, filthy animals not to kill my boars! Well done, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10516] = {title = "The Trappings of a Vindicator", objective = "Retrieve Vindicator Vuuleen's Blade and Vindicator Vuuleen's Shield. Then return them to Vindicator Vuuleen at Bladespire Hold in the Blade's Edge Mountains.", description = "I know it's strange, but I do want to stay in this cage.  It gives me the perfect opportunity to do what I came here for; to gather information on the Bladespire.\n\nI can leave at any time, but I would like to have my sword and shield back.\n\nTwo of their leaders have my trappings.  Droggam has my sword and Mugdorg has my shield.\n\nIf you have need, obtain and use the brew from Bloodmaul Outpost to the south to thin out their help and entice those two, but beware their sober guards who don't drink!", progress = "<class>, do you have my sword and shield?\n\nWhile I could leave at any time, it would be embarrassing for me to return to Sylvanaar without my trappings.", completion = "And now I owe you a great debt, for you have helped me to restore my honor.  But our work here is not yet over.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10517] = {title = "Gorr'Dim, Your Time Has Come...", objective = "Vindicator Vuuleen has asked you to kill Gorr'Dim, leader of the Bladespire Hold ogres. Once you have done so, return to her at Bladespire Hold in the Blade's Edge Mountains.", description = "The leader of Bladespire Hold is known as Gorr'Dim.  Trust me... the name is appropriate.\n\nStill, I wouldn't underestimate him.  He's crafty enough to have elevated his clan to be the favorite of Gruul the Dragonkiller and they now dominate these mountains.  And Gorr'Dim keeps an entourage about him at all times, including defenders who are sworn not to drink the Bloodmaul brew.\n\nFor the safety of Sylvanaar, I'm asking that you go back in there and deal with him.", progress = "What was all of that noise?  Was that you dealing with Gorr'Dim?", completion = "Very well.  You're a very resourceful &lt;class&gt;, that's for certain.\n\nI wonder then if there's one more thing that you can do for myself and Sylvanaar?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10518] = {title = "Planting the Banner", objective = "Use the Bladespire Banner atop the Northmaul Tower to lure Gurn Grubnosh. Deliver the banner and the Helm of Gurn Grubnosh to Commander Skyshadow at Sylvanaar in the Blade's Edge Mountains.", description = "I want you to steal the Bladespire banner from one of their champions and take it south to Bloodmaul Outpost.  Plant it atop their Northmaul Tower.\n\nThis will infuriate the Bloodmaul and they will attack you relentlessly.  But it will also keep their hatred focused on Bladespire Hold, and away from Sylvanaar.\n\nYou will know you have accomplished the deed when you have defeated Gurn Grubnosh and taken his helm.  Return it to Sylvanaar.\n\n<name>, this isn't going to be easy.  Take a  friend or two with you.", progress = "What brings you to me?  Surely not more trouble with the Bloodmaul ogre clan?", completion = "Gurn Grubnosh's helm and a Bladespire banner?\n\nQuite clever of you and the vindicator to come up with that plan.\n\nBy keeping the attention of the Bloodmaul clan on Bladespire Hold, you've relieved the pressure that they were beginning to assert upon us here.\n\nPlease, &lt;name&gt;, accept a humble gift from Sylvanaar.", rewards = "You will be able to choose one of these rewards:\n\nSylvanaar Elite Caster's ArmorOgre Assassin's BritchesGurn's Horned HelmetSylvanaar Champion's Shoulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10519] = {title = "The Cipher of Damnation - Truth and History", objective = "Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley wants you to listen to his story. Speak to Oronok to begin hearing his story.", description = "<Oronok adjusts his posture and stands to his full height.>\n\nI had to be sure, <name>. And to be sure, I had to test you. Please excuse the little masquerade. I am as much a farmer as you are <female/male>. Which is to say, not at all.\n\nIf you are to recover the Cipher of Damnation, you will need to listen to what I have to tell you. When you are ready, let me know and I will tell you the story.", progress = "Be patient and listen, <name>.", completion = "Do you understand what must be done? Find the sons of Oronok. Find my boys...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10520] = {title = "Assisting Arch Druid Staghelm", objective = "Speak with Arch Druid Fandral Staghelm in Darnassus.", description = "Excuse me <class>, but I'd like just a moment of your time if possible.\n\nThe Cenarion Circle in Darnassus is looking for seasoned adventurers such as yourself to lend them aid in a vital research project.  While I do not know the specifics, I can inform you that none other than Arch Druid Fandral Staghelm is spearheading this research.\n\nPlease - if you are interested, speak with him directly in the Cenarion Enclave within Darnassus proper.", progress = nil, completion = "Well now, &lt;class&gt;... since you were informed that I was leading this research myself, you obviously came as quickly as you could.\n\nNow that you are here, be sure to pay attention the first time I tell you the details; I have no desire to repeat myself.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10521] = {title = "Grom'tor, Son of Oronok", objective = "Find Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley.", description = "My first born, Grom'tor, left to search Coilskar Point - directly southwest of here.\n\nHe's the warrior in the family - ill-tempered and blood-thirsty... Traits he inherited from his mother. Search along the outskirts of Coilskar Point. If you see naga corpses, Grom'tor is sure to be close.\n\nWhen you find him, tell him this: \"We spill blood for just cause.\" It will let him know that you are a friend to Torn-heart and prevent your premature death.", progress = nil, completion = "&lt;Grom'tor grunts.&gt;\n\nIt's good you came. This maggot just spilled its guts. We've got them now!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10522] = {title = "The Cipher of Damnation - Grom'tor's Charge", objective = "Grom'tor, Son of Oronok at Coilskar Point in Shadowmoon Valley wants you to recover the First Fragment of the Cipher of Damnation.", description = "This naga filth is the sixth one I've interrogated today. He's got the fancy armor so I figured he knew something. Those other ones were useless.\n\n<Grom'tor points to the corpses of the naga around him.>\n\nI only had to beat him once and he told me everything.\n\nThe first part of the cipher is hidden in a naga chest at Coilskar Point or Coilskar Cistern, east of here. He says naga carry the keys. Kill 'em, take their keys and use them to open the Coilskar chests. Return to me when you find the cipher.", progress = "Any luck?", completion = "This must be taken back to father at once.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10523] = {title = "The Cipher of Damnation - The First Fragment Recovered", objective = "Take Grom'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", description = "<Grom'tor wraps the documents up and places them in a lockbox.>\n\nTake this box to father. He awaits your return at the farm, northeast of here.\n\nTell him that I will be home soon. As soon as I am done having my fun...", progress = "You have succeeded?", completion = "When the Cipher of Damnation is reformed, we shall end this curse!", rewards = "You will be able to choose one of these rewards:\n\nGrom'tor's Friend's Cousin's TunicGrom'tor's Bloodied BandageGrom'tor's Pendant of ConquestOronok's Old Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10524] = {title = "Thunderlord Clan Artifacts", objective = "Retrieve the Thunderlord Clan Drum, Thunderlord Clan Arrow and the Thunderlord Clan Tablet. Return them, along with the Thunderlord Clan Artifact, to Rokgah Bloodgrip at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "The artifact bears markings that indicate its origins as being created by the Thunderlord clan orcs.  These orcs used to live at Thunderlord Stronghold before they were changed into fel orcs.\n\nFor a time the Bladespire ogres inhabited the stronghold until recently when the Horde pushed them out.\n\nYou've heard of other artifacts that were lost.  A drum, an arrow and a tablet come to mind as objects that you know are being sought after.\n\nFind them in Bladespire Hold and return them to Rokgar Bloodgrip.", progress = "Do I know you?", completion = "I do not believe my eyes!  If this is some sort of trick, I will flay the flesh from your bones, &lt;class&gt;!\n\nQuickly, let me examine these priceless artifacts before you break them with your clumsy hands.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10525] = {title = "Vision Guide", objective = "Use the Fiery Soul Fragment to transform your spirit into a vision guide. Speak with Rokgah Bloodgrip at Thunderlord Stronghold after your vision has guided you to the location of the final Thunderlord relic.", description = "<race> fool.  You almost destroyed the drum!\n\nI've worked too hard to get here, and my hands have been empty up until now.  At least you were able to succeed where the others only met with failure, or worse.\n\nIt is time to evoke a vision that will lead you to the last relic that I have been seeking.\n\nTake this fiery fragment of my soul.  Use it to transform your body into flame and denature your spirit into a vision guide that will shoot forth to reveal the location of the final Thunderlord relic.", progress = "What did you see?  Tell me, I must know where it is!", completion = "The back of the Draenethyst Mine?  The Bloodmaul clan must have stolen it from the Bladespire ogres.\n\nBah!  That is too far away... too deep into Bloodmaul territory for me to travel.\n\nBut you.  You know the path.  You will go there in my stead!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10526] = {title = "The Thunderspike", objective = "Rokgah Bloodgrip has tasked you with the retrieval of the Thunderspike. Return it to her at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "If the vision that I granted you is true, then you must travel down into the ravine and to the south end of Bloodmaul Ravine.  There you will find the Draenethyst Mine.\n\nJourney to the back of the mine, and retrieve the Thunderspike.  Ignore everything else!  I have no interest in the crystals of the mine, nor the ogres therein.\n\nAs soon as you have the spear return it to me here!\n\nAnd, <name>, be very careful with it... I would hate to think what would happen to you should you break it.", progress = "The significance of these artifacts eludes you, I am sure.\n\nWhen we have all five, our right to the ownership of Thunderlord Stronghold will be secured through the appeasement of its dead spirits.\n\nDo you begin to grasp now why this is so important?  Do you understand why I have little patience for niceties?", completion = "Now I am impressed!  Do you have any idea how many others died attempting to retrieve all of these relics?\n\nWe are fortunate to have you working with us here, &lt;name&gt;.  Even if you are a bit slow.\n\nYou must allow me to reward your dedication to our cause.  Choose, but choose wisely.  When you are done, I will hand over the artifacts to appease the ghosts of Thunderlord Stronghold.", rewards = "You will be able to choose one of these rewards:\n\nThunderlord ScalpelSlow Death DirkWand of the Ancestors\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10527] = {title = "Ar'tor, Son of Oronok", objective = "Find Ar'tor, Son of Oronok at Illidari Point in Shadowmoon Valley.", description = "My youngest son, Ar'tor, left to search Illidari Point - far to the southwest, nestled between Legion Hold and Wildhammer Stronghold.\n\nWhile Ar'tor is a hunter of remarkable skill and an expert tracker, I fear that he may be in over his head this time. Illidari Point is the proving grounds for Illidan's demons. These are demons that left the Burning Legion to join the Betrayer!\n\nTravel to Illidari Point and find Ar'tor, <name>.", progress = nil, completion = "Ar'tor's body lies limp, suspended in mid-air. You have no idea how long he has been dead but your heart aches for Oronok.\n\nPerhaps you should try and get him down and take his corpse back to his father.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10528] = {title = "Demonic Crystal Prisons", objective = "Seek out and slay Painmistress Gabrissa at Illidari Point and return to the corpse of Ar'tor, Son of Oronok with the Crystalline Key.", description = "From assessing the scene, you note that Ar'tor is being held in place by energy beams emanating from the crystals hovering around the rune. Try as you might, Ar'tor is unmovable.\n\nYou note that the crystals have an empty slot at their base - perhaps for a key. It also seems as if succubi periodically perform some sort of ritual at the site.\n\nSearch Illidari Point for their leader. Perhaps she holds the key to releasing Ar'tor.", progress = "Ar'tor hovers lifelessly before you.", completion = "You slide the crystalline key into the slots at the base of each of the demonic crystals.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10529] = {title = "The Hunter's Path", objective = "Speak with Lieutenant Dawnrunner at Farstrider Retreat.Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters. It would greatly benefit you to seek her out, <name>. She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, <name>.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10530] = {title = "The Hunter's Path", objective = "Speak with Lieutenant Dawnrunner at Farstrider Retreat.Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters. It would greatly benefit you to seek her out, <name>. She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Lieutenant Dawnrunner at Farstrider Retreat has requested an audience with all able hunters.  It would greatly benefit you to seek her out, <name>.  She is a beacon of wisdom for those of our calling.\n\nFarstrider Retreat lies south of Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10531] = {title = "The Battle for Arathi Basin!", objective = "Assault the mine, the lumber mill, the blacksmith and the farm, then return to Field Marshal Oslight in Refuge Pointe.", description = "<name>, the battle for Arathi Basin is a battle for resources and territory.  Key points in the area must be held and operated in order to supply our forces with much needed raw materials and supplies.  I charge you to assault the points farthest from our Arathi Basin base.\n\nAssault the farm, the mine, the lumber mill and the blacksmith when they are controlled by the enemy.  Find the enemy's banner and rip it from its flag post!\n\nWhen you have done this to all four points, return to me.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10532] = {title = "Cut Arathor Supply Lines", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Deathstalker Mortis at Hammerfall.", description = "The League of Arathor is sparing no expense in their move to retake Arathi.  They, and all the races of the Alliance, now stream to this distant region, intent on expanding their hold from Refuge Pointe.  We must stop them, and the best means to stop them is to take their supplies.\n\nYou can help us, <name>.  Enter Arathi Basin, known for its rich mines, fertile land and skilled craftsman.  Capture and control every base you can, win the battle, and return to me with the resources you gain.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10534] = {title = "Returning Home", objective = "Caedmos at the Exodar has requested you come see him.A <race> <class>...\n\nYes, there was a priest of your order here recently, <name>. He told me it was time you returned to the Exodar met with Caedmos. There was a sense of urgency in his request, so I wouldn't take too long to see him.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "A <race> <class>...\n\nYes, there was a priest of your order here recently, <name>.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10535] = {title = "Arathi Basin Resources!", objective = "Win the battle for Arathi Basin, get an Arathi Resource Crate, and return it to Sergeant Maclear at Refuge Pointe.", description = "War must be fought with soldiers, any soldier will tell you.  They'll also say that a battle fought with poor gear or on an empty stomach is lost before it starts!\n\nThat is why Arathi Basin is important.  There are key areas in the basin that hold essential resources.  Metals, weapons, food, lumber - all are needed, and all can be gained there.\n\nThat is what I want from you, <name>.  Enter Arathi Basin, win the battle by holding more bases than the enemy, and return to me with a crate of resources.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10537] = {title = "Lohn'goron, Bow of the Torn-heart", objective = "The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover Lohn'goron, Bow of the Torn-heart from the demons of the area.", description = "It is a sign, <name>. Even in death, I cannot be stopped. Recovering a part of the Cipher of Damnation is my destiny. With your help, that destiny will be fulfilled.\n\nBefore we embark on that journey, I must have my longbow, Lohn'goron. It is a family heirloom that has been handed down from Torn-heart to Torn-heart for generations.\n\nMy instinct tells me that a demon stole it from my corpse. Kill the demons here until you find my bow.", progress = "Fear not, hero. When the time is right, I will assist you...", completion = "It means \"hero's sojourn\" in my native tongue. It rings true even now - in this era where our heroes have all died...\n\nIt seems as though one always rises.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10538] = {title = "Boiling Blood", objective = "Use Bleeding Hollow Blood at the Cursed Cauldron to make Boiled Blood. Bring 12 Boiled Blood to Apothecary Albreck at Spinebreaker Post.", description = "That last experiment was not a complete loss -- I did save a small bit of the blood you brought me.  Now boiled down, it should be free of whatever curses the Bleeding Hollow witches placed on their people's blood.\n\nI need more for study.  Go gather Bleeding Hollow blood from the orcs in Zeth'Gor.  When you've gathered the blood, bring it to their cursed cauldron and boil it.  Bring me the boiled blood.", progress = "Do you have the boiled blood, <name>?  I am eager to study it without an interruption this time...", completion = "Very good.  Now I can more easily perform my tests...\n\nThank you, &lt;name&gt;.  Your talents are considerable.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10539] = {title = "Returning Home", objective = "Caedmos at the Exodar has requested you come see him.A <race> <class>...\n\nYes, there was a priest of your order here recently, <name>. He told me it was time you returned to the Exodar met with Caedmos. There was a sense of urgency in his request, so I wouldn't take too long to see him.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "A <race> <class>...\n\nYes, there was a priest of your order here recently, <name>.  He told me it was time you returned to the Exodar met with Caedmos.  There was a sense of urgency in his request, so I wouldn't take too long to see him.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10540] = {title = "The Cipher of Damnation - Ar'tor's Charge", objective = "The Spirit of Ar'tor at Illidari Point in Shadowmoon Valley wants you to recover the Second Fragment of the Cipher of Damnation from Veneratus the Many.\n\nCreatures attacked or damaged by the Spirit Hunter will not yield loot or experience.", description = "At last, we are ready. I will bestow a piece of my spirit upon you, hero. It will guard you and help you in your battle against evil.\n\nYou must then travel south of here towards the back of Illidari Point. Hidden in the ether is a vile creature known as Veneratus the Many. My spirit hunter will call him out when he is near.\n\nDestroy Veneratus and take from his corpse the second part of the Cipher of Damnation.", progress = "The cipher must be recovered!", completion = "&lt;Ar'tor fades in and out of existence.&gt;\n\nIt would seem that my time is nearly at an end, hero.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10541] = {title = "The Cipher of Damnation - The Second Fragment Recovered", objective = "Take Ar'tor's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", description = "I thank you, hero. For without you, my spirit would forever remain in this cursed place.\n\n<Ar'tor hands you a spectral lockbox.>\n\nTake it and deliver it to my father at the farm, far to the northeast, above Coilskar Cistern... Inside are Lohn'goron and the second part of the cipher.\n\nHe will be sad to hear news of my death. Promise me that you will assure him that I died a free soul. Tell him that I see the hunting grounds and they are glorious. Tell him that I wait for him there...", progress = "<A single tear rolls down Oronok's cheek.>", completion = "&lt;Oronok wipes the tear away and smiles at you.&gt;\n\nThank you. I promise you, hero, a song of honor will be written in your name.", rewards = "You will be able to choose one of these rewards:\n\nEva's StrapGhostly HeadwrapOronok's Old LeggingsTorn-heart CloakTorn-heart Family Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10542] = {title = "They Stole Me Hookah and Me Brews!", objective = "Retrieve T'chali's Hookah and 10 Bloodmaul Brutebane Brews. Bring them back to T'chali the Witch Doctor at Bloodmaul Ravine in the Blade's Edge Mountains.", description = "T'chali used to be a pretty friendly troll.  Me come down here to teach the Bloodmaul how to brew their beer.  But once me do that, the Bloodmaul bury T'chali and leave him here to rot!\n\nThe worst part of it was that they stole me hookah!\n\nSo, you want to help T'chali?  You bring me hookah back.  T'chali think the ogres that stole it headed southwest over by the mine.\n\nAnd while you're in there, pick up some brews, too!", progress = "Hey, you got me hookah and those brews yet?", completion = "Yes, that is what T'chali is talking about!  Though me not sure what those ogres put in there; that not T'chali's brand of tobacco that me smell in the hookah.\n\nNo matter, T'chali is happy.  Happy enough, in fact, to ask you to do something else.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10543] = {title = "Grimnok and Korgaah, I Am For You!", objective = "T'chali the Witch Doctor has asked you to kill his chief tormentors, Grimnok Battleborn and Korgaah. After you have done so, return to him at Bloodmaul Ravine in the Blade's Edge Mountains.", description = "T'chali has been waiting for his revenge!\n\nThe day they bury T'chali and leave him to die, it was Grimnok Battleborn that led them.  And the next day it was Korgaah that come south to raid and kick T'chali in the head.\n\nI want them dead!\n\nYou will find Grimnok atop the Southmaul Tower in Bloodmaul Outpost.  You will find Korgaah in the top of a building at the north end of Bladespire Hold.  Korgaah has sober defenders, so use the brew to distract him away from them, because they won't drink.", progress = "You think T'chali likes being this way?  No!\n\nSo, have you exacted me revenge yet?  Are Grimnok and Korgaah dead?", completion = "T'chali is pleased that Korgaah and Grimnok Battleborn are pushing up daisies just like him.\n\nBut T'chali's thirst for revenge is not quenched.  There's one more thing that you must do!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10544] = {title = "A Curse Upon Both of Your Clans!", objective = "Use the Wicked Strong Fetish to curse 5 buildings or towers in Bladespire Hold and 2 in Bloodmaul Outpost. Return to T'chali the Witch Doctor at Bloodmaul Ravine in the Blade's Edge Mountains after you have done so.", description = "T'chali wants revenge on all of the ogres!\n\nT'chali was a powerful witch doctor in life.  If you reach into me grave you will find a wicked strong fetish.\n\nInvoke the fetish's magic at the entrances to the buildings and towers of both Bladespire Hold and Bloodmaul Outpost.  The voodoo you work will summon an evil spirit that you must defeat.  This in turn will curse that building.\n\nBeware, if you attempt to curse a building that is already cursed, you will call down another cursed spirit!", progress = "T'chali does not want to speak again until <name> has used the fetish to curse the buildings and towers of both the Bladespire and Bloodmaul clans!", completion = "Hahaha, revenge is sweet!\n\nBut, T'chali can see you be interested in moving on now that you help him get his revenge.  I hear you, mon... life is for the living.\n\nTell you what, T'chali got lots of goodies still left here in his grave.  You pick the one you like best!", rewards = "You will be able to choose one of these rewards:\n\nWitch Doctor's BeadsT'chali's KiltHexxer's BeltOgre Defiler's Handguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10545] = {title = "Bladespire Kegger", objective = "T'chali has asked you to take the Bloodmaul Brutebane Keg and use it in an attempt to get 5 Bladespire Ogres drunk. If successful, return to T'chali the Witch Doctor at Bloodmaul Ravine in the Blade's Edge Mountains.", description = "As T'chali was saying, he helped out his Bloodmaul friends to make their brew.  But what T'chali did not say was why.\n\nThe Bloodmaul are in dire straits.  The Bladespire clan be crushing them, and they needed a new weapon to help out with their fight.\n\nThat's when T'chali came up with a great idea.  Why not make the perfect brew, one that strengthens you and weakens your enemy?  Only thing is, T'chali does not know if it works.\n\nSo, you gonna take this brew up to Bladespire Hold and see if it works!", progress = "Tell T'chali... did the brew work?  Did the Bladespire ogres like it?", completion = "That's good news!  That brew is gonna come in handy with what T'chali is gonna ask you to do next.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10546] = {title = "Borak, Son of Oronok", objective = "Find Borak, Son of Oronok near Eclipse Point in Shadowmoon Valley.", description = "While Ar'tor was off hunting and Grom'tor was off fighting, Borak studied. Eventually he took up a vocation as a scholar and left for the wilds of Draenor. He returned home a few years ago a changed orc.\n\nHis heightened sense of awareness and mental acuity had forged a silent assassin.\n\nNow a confident and powerful orc, he has taken to recovering the most guarded piece of the cipher.\n\nFind Borak hiding near Eclipse Point, far to the south. He watches from the shadows of the bridge.", progress = nil, completion = "&lt;Borak is silent for a moment.&gt;\n\nI've been watching these blood elves for weeks now, trying to get a lock on where they've hidden the third part of the Cipher of Damnation.\n\nThus far, I've been unsuccessful in gathering any clues. The only thing I do know is that Illidan sends an envoy from the Black Temple here once a day.\n\nThis envoy is untouchable. I've shadowed him for a week, trying to figure out how to separate him from his bodyguard. Unfortunately, the bodyguard never leaves his side.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10547] = {title = "Of Thistleheads and Eggs...", objective = "Borak, Son of Oronok at the bridge north of Eclipse Point wants you to find a Rotten Arakkoa Egg and deliver it to Tobias the Filth Gorger in Shattrath City, located in northwest Terokkar Forest.", description = "I'd have given up had I not noticed... He's a Thistlehead. I couldn't place it at first but the signs are all there...\n\nNow if we could get our hands on some bloodthistle, we'd be in business.\n\nIn my travels, I met a shady Broken in Shattrath named Tobias.\n\nTobias made a business of trading bloodthistle to blood elves for rotten arakkoa eggs.\n\nDirectly west of here are arakkoa ruins. Search them for an egg and head to the lower city of Shattrath. That's where you'll find Tobias.", progress = "<Tobias raises an eyebrow.>\n\nBloodthistle? Never heard of it... Are you a peacekeeper? You know you'd have to tell me if you were... I've got rights!", completion = "You've got a rotten arakkoa egg? Well why didn't you say so! I think we can do business.\n\n&lt;Tobias smiles, exposing a mouthful of decay and filth.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10548] = {title = "The Sad Truth", objective = "Eralan in Tranquillien wants you to retrieve the Archeologist's Shrunken Head from one of the chests in Zeb'Tela or Zeb'Nowa.", description = "Remember how I told you about the fat merchant who was looking for that ring?  As it turns out, he had his archeologist son looking for the thing and it didn't turn out so well.  By not so well I mean they killed him and shrunk his head.\n\nNow this might seem cold, calculating, and exceptionally callous, but he'd pay a lot to get his son's head back.  Sounds like the perfect job for you!\n\nGo east until you find the troll ruins of Zeb'Tela and Zeb'Nowa.  You're bound to find it one of the chests there.", progress = "How's the head hunting?", completion = "Oh, wow.  That is not pretty.  I'm sure the merchant will appreciate it more than me.\n\nAs payment, the merchant offered to buy one of my special stock items for you, so take your pick handsome!", rewards = "You will be able to choose one of these rewards:\n\nLeafblade DaggerGhostclaw Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10550] = {title = "The Bundle of Bloodthistle", objective = "Take the Bundle of Bloodthistle back to Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley.", description = "I wasn't lying. That egg was incredible. Where did you get it from?\n\nWell, if you ever need more bloodthistle, you know where I am and what I need.\n\nHere's a bundle of the stuff. Take it back to your benefactor.", progress = "Do you have the bloodthistle?", completion = "Now to set the trap!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10551] = {title = "Allegiance to the Aldor", objective = "Are you certain of your choice, <name>?  The Aldor will welcome you as an ally, but the Scryers will not easily forgive your decision.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10552] = {title = "Allegiance to the Scryers", objective = "Are you certain of your choice, <name>?  The Scryers will welcome you as an ally, but the Aldor will not easily forgive your decision.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10553] = {title = "Voren'thal the Seer", objective = "Speak to Voren'thal the Seer inside the Seer's Library at the Scryer's Tier in Shattrath City.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", description = "Now that you've chosen a side, <name>, you should meet the Scryers' leader.\n\nYou will find Voren'thal the Seer inside the Seer's Library at the Scryer's Tier.\n\nSee if you can be of assistance to him.  He will be glad to hear you've decided to lend them a hand.", progress = nil, completion = "Khadgar sends a new recruit?  Let us put you to work, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10554] = {title = "Ishanah", objective = "Speak to Ishanah inside the Shrine of Unending Light at the Aldor Rise in Shattrath City.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", description = "Now that you've decided to side with the Aldor, you'd do well to introduce yourself to their leader.  You will find High Priestess Ishanah inside the Shrine of Unending Light.", progress = nil, completion = "Welcome, &lt;name&gt;.  I'm glad to hear you've decided to join us in our mission.  May the Light always protect you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10555] = {title = "Malaise", objective = "Collect 18 Plucked Lashh'an Feathers, then read the Lashh'an Tome in the treetops of Veil Lashh.", description = "The magic practiced by the Lashh'an arakkoa is unnatural. They rip out handfuls-clawfuls?-of their own feathers as reagents!\n\nThat doesn't sound like good magic to me. I've come here to learn more about their spells. Unfortunately getting close is too much for me.\n\nYou could succeed: cast one of their spells on yourself, then return to me. You'll have to find one of their spellbooks, high up in the trees of Veil Lashh.\n\nAnd unless you've grown feathers I can't see, you'll need to get some of those.", progress = "From the crude pictographs on the pages of the aged tome, you discern that a large number of Lashh'an feathers will be needed when casting the spells contained within.", completion = "Flipping through the pages of the scratched notes and spindly script of the Lashh'an arakkoa, you find a page with a pictogram of the circles of power you have seen in Veil Lashh.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10556] = {title = "Scratches", objective = "Use the Fistful of Feathers on the Lashh'an Spell Circle, then return to Daranelle at Sylvanaar before the kaliri spirit fades.", description = "The pictograms indicate using feathers to cast the spell at one of the circles of power in Veil Lashh.\n\nConfusing iconography seems to show an arakkoa being suffused with the spirit of a kaliri.", progress = "This is exciting! I can't wait to examine the workings of the spell.", completion = "I don't know what to say. This spell is very strange. It is not a simple conjuration or enchantment, but some sort of communion or communication spell.\n\nI'm not sure what to make of it, &lt;name&gt;. I'll have to think about it some more.\n\nBut thanks for your help, anyways! I'm sure I'll think through this sooner or later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10557] = {title = "Test Flight: The Zephyrium Capacitorium", objective = "Speak with Rally Zapnabber and use the Zephyrium Capacitorium. Return to Tally Zapnabber at Toshley's Station.", description = "I built an amazing device, the Zephyrium Capacitorium, and I'm sure it'll work perfectly, but... do you want to help me test it?\n\nThere's plenty of hazard pay!\n\nSpeak with my twin over there, Rally. Good luck, <name>. Come back after your experiment.  Or... if that's not possible due to sustained injuries, your next of kin can report to collect your pay.", progress = "Don't be afraid!  This is for science, and science is painful!", completion = "Wow, you made it!  And not a single bruise or compound fracture!  See, I told you everything would work out!\n\nHere's your pay, &lt;name&gt;, though I factored in medical expenses and you don't need those... so that's a bonus for you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10558] = {title = "Revered Among Honor Hold", objective = "Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula wants you to become revered with Honor Hold by fighting Fel Orcs inside the Shattered Halls of Hellfire Citadel.", description = "You've proven your worth to our cause, <name>.  One such as yourself could one day become a great leader.\n\nContinue to fight our enemies in the Shattered Halls and gain renown among my men.  If you live up to my expectations I will have greater tasks to ask of you.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10559] = {title = "Revered Among Thrallmar", objective = "Nazgrel at Thrallmar in Hellfire Peninsula wants you to become revered with Thrallmar by fighting the Fel Orcs inside the Shattered Halls of Hellfire Citadel.", description = "You've proven yourself time and again, <class>.  Yet more trials await you.\n\nContinue to fight the Fel Horde inside the Shattered Halls of Hellfire Citadel and your name will be known to all of Thrall's followers in this land.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10560] = {title = "Revered Among the Sha'tar", objective = "A'dal in Shattrath City wants you to become revered with the Sha'tar by defeating the forces of Kael'thas inside Tempest Keep.", description = "<The calming melodic tones projected by A'dal become more hushed and somber.>\n\n<You are shown the large naaru structure known as Tempest Keep.  It is now inhabited by the forces of Kael'thas and its power used for nefarious ends.  A'dal promises you greater tasks once you've done your part to take back Tempest Keep.>You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10561] = {title = "Revered Among the Keepers of Time", objective = "Andormu inside the Caverns of Time in Tanaris wants you to become revered with the Keepers of Time by continuing to defend the events of Old Hillsbrad and the Black Morass inside the Caverns of Time.", description = "You've proven yourself to us, <race>.  The timeline is not yet safe, however.\n\nWe're in need of true champions and you may prove to be one.\n\nContinue to defend the events of the past from intruders and you'll get the renown you deserve.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10562] = {title = "Besieged!", objective = "Wing Commander Nuainn, outside of Wildhammer Stronghold, wants you to kill 10 Infernal Attackers.", description = "Don't let your guard down, <race>. We're under constant assault from the Burning Legion.\n\nFrom their base of Legion Hold to the northwest, the demons rain down a ceaseless stream of infernals. As quickly as we can kill them, the new meteors impact and begin a new wave of attacks.\n\nMy men are ragged and exhausted. I don't know how much longer they'll hold out. Please, <name>, lend your help to our defenses. Take your place on the line and halt the advance of the infernals!", progress = "Have you tired already, <class>?", completion = "Thank you for relieving my men, &lt;name&gt;. With your help, and that of others, we may yet hold out. Unfortunately, merely holding out is not enough. We must go on the offensive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10563] = {title = "To Legion Hold", objective = "Make your way to Legion Hold and locate the Legion Communication Device. While standing near the communication device, use your disguise and learn about the Legion's plans. Return to Wing Commander Nuainn at Wildhammer Stronghold when you've completed your mission.", description = "The fortress of Legion Hold is nigh impregnable, and to be completely honest, I can't spare the forces for an assault. Our hopes are riding on you, <name>.\n\nWhat little information we've been able to gather indicates that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and learn about the their plans. Your best hope is to intercept or overhear communication between their commanders. Good luck, <name>.", progress = "What did you discover?", completion = "&lt;Wing Commander Nuainn listens to your report, growing more alarmed with each sentence.&gt;\n\nSo you're saying they have more than enough infernals to intensify the bombardment? If we don't stop them before they can put the next phase of their plan into motion, Wildhammer Stronghold is finished.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10564] = {title = "Blast the Infernals!", objective = "Use the Fel Bomb while standing on the green glyph in Legion Hold, then report to Wing Commander Nuainn at Wildhammer Stronghold.", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", progress = "Have you found a way to destroy the Legion's infernal stockpile?", completion = "Well done, &lt;name&gt;! I wish I could say that the Legion would give up after a setback like this, but you and I know better than that. The Deathforge that you learned about during your reconnaissance mission will be our next target.", rewards = "You will be able to choose one of these rewards:\n\nBloodforged GuardCrimson Mail HauberkMooncrest HeaddressSoothsayer's Kilt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10565] = {title = "The Stones of Vekh'nir", objective = "Collect and use a Vekh'nir Crystal at the Vekh'nir Spell Circle, then return the Charged Vekh'nir Crystal to Dertrok at the Mok'Nathal Village.", description = "The arakkoa of Vekh'nir have been a thorn in our sides for many years. Some strange religion guides them, a religion which has the arakkoa in a frenzy of activity. They carry these crystals with them now, which they have turned to some dark purpose.\n\nI know something of their rituals. They take the crystals to their spell circles to infuse them. We at the village would like to know more. Waylay a few of the arakkoa until you find a crystal, charge it, then return it to me.", progress = "The Vekh'nir arakkoa have been benign for many years, but now something has stirred them.", completion = "Ah, look how it glows! I must try this at once.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10566] = {title = "Trial and Error", objective = "Try out each of Dertrok's wands on an Arakkoa Ogre Slave, then return to Dertrok. Each wand will require an Infused Vekh'nir Crystal to use.", description = "I've fashioned four wands that I believe will enhance the power of the arakkoa's crystals. Take these wands to Trogma's Claim, and try them on the ogre slaves.\n\nYou'll need to find an infused crystal off of the arakkoa in the area.\n\nWhen you figure out which is best, come back to me.", progress = "I eagerly await your results, <name>.", completion = "This information will be very helpful, &lt;name&gt;. I will further refine that design and see if we can't expand its utility.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10567] = {title = "Creating the Pendant", objective = "Find 6 Ruuan'ok Claws and use them at the Ruaan'ok Oracle Circle to summon a Harbinger of the Raven. Kill it and return its Harbinger's Pendant to Timeon at Ruuan Weald.", description = "The arakkoa of Ruaan Weald elevate from their flock the Harbingers of the Raven, the heralds of their god.\n\nThey believe that the Harbingers watch over them from the sky, where they receive the teachings of the Raven, and descend to pass this message along.\n\nThe Harbingers hold a powerful sway over the souls of the arakkoa. They use magical pendants, which we need.\n\nAttract one of the Harbingers by slaying its flock and taking their claws. Place the claws upon the altar to get his attention.", progress = "Once the Harbinger is aware of your attack upon his flock, he will be quick to respond.", completion = "You have it!\n\nWith this pendant, I will be able to attune you to the arakkoa of Grishnath in such a way that will enable you to comprehend their speech.\n\nWith this, we may gain further understanding of the arakkoa, and the nature of the Raven. I will need your help to do this.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10568] = {title = "Tablets of Baa'ri", objective = "Anchorite Ceyla at the Altar of Sha'tar wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.\n\nCompleting quests with the Aldor will cause your Scryers reputation level to decrease.", description = "Years ago, the dreaded warlock known as Gul'dan raised the volcano in the middle of Shadowmoon.  The draenei village of Baa'ri, to the southwest, was buried under the lava along with its inhabitants and artifacts of religious importance.\n\nThe treacherous tribe of Broken known as the Ashtongue has been ordered by Illidan to excavate the area.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor, now known as the Black Temple.", progress = "Have you found the tablets yet, <name>?", completion = "The Baa'ri tablets!  Yes, this might provide us with very useful information.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10569] = {title = "The Sketh'lon Wreckage", objective = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Gryphonrider Kieran.", description = "Our scouts have brought back disturbing reports from the ruined arakkoa encampments in the area.\n\nThe ghosts of powerful arakkoa magicians wield powers we never thought they possessed. They seem to be organizing, as though preparing for something, but our knowledge is limited. We cannot afford to remain ignorant!\n\nTravel north to the Sketh'lon Wreckage, to the northwest of the Deathforge and search for signs of their motives.", progress = "What have you discovered?", completion = "&lt;Kieran leafs through the journal pages.&gt;\n\nMuch of this is unintelligible, but I can make out bits here and there about preparations for a spell gone awry, casualties, and a deteriorating situation. There's also a curious note here about a 'deserter.'", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10570] = {title = "To Catch A Thistlehead", objective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Stormrage Missive.", description = "<Borak takes the bundle of bloodthistle from you and places it to his nose.>\n\nPungent...\n\nNow, take this bundle and place it at the other end of this bridge. When the envoy makes his daily rounds, he will be compelled to pick it up - without his bodyguard. You see, blood elves look down upon bloodthistle addicts. If any of his compatriots ever found out...\n\nAll you need to do is lie in wait for him to dismiss his bodyguard. When he is alone, make your strike! Kill him and take the missive.", progress = "Be quick about it, boy.", completion = "&lt;Borak takes the missive from you and begins to read.&gt;\n\nClever bastards! This is a directive from Illidan that dictates where the cipher is to be hidden next. Apparently, they keep it moving. It does not tell us where it currently rests... If only we could deliver the missive now that we know the next location.\n\nToo bad the seal on the missive is broken, rendering it unusable.\n\nHrm... Yet...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10571] = {title = "Oronu the Elder", objective = "Anchorite Ceyla at the Altar of Sha'tar wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", progress = "Any news yet, <name>?  Time is not on our side.", completion = "Akama's very own handwriting.  It is truly sad to think of what became of one as wise and beloved as he.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10572] = {title = "Setting Up the Bomb", objective = "Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate and bring them to Wing Commander Nuainn at Wildhammer Stronghold.", description = "We cannot permit the Legion to carry out its plan to destroy Wildhammer Stronghold on their march to the Black Temple.\n\nThere's only one way to stop them, <name>. You must create an explosive large enough to destroy the Legion's entire stockpile of infernals at the hold.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the base of your device. Search the other wreckage near the fel reaver for armor plating we might be able to make a casing from.", progress = "<You hand the materials to the wing commander.>", completion = "&lt;The wing commander inserts the power core into the armor plates and seals the device shut, nodding.&gt;\n\nThis should do the trick. Should make quite an explosion too, if I do say so m'self.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10573] = {title = "The Deathforge", objective = "Report to Stormer Ewan Wildwing at the Deathforge Tower.", description = "From your findings at Legion Hold, we know that the Legion's Shadow Council allies are producing infernals in the Deathforge. I've dispatched a small scouting party to keep watch over the area, but they're not able to accomplish everything we need.\n\nIf the Deathforge is left alone to operate, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nI want you to meet up with Stormer Ewan Wildwing, at the Deathforge Tower, to the northwest, overlooking the Deathforge itself.", progress = nil, completion = "&lt;The dwarf nods.&gt;\n\nIt'll be good to have the backup. We've gathered some preliminary information on what the Shadow Council is up to in there, but I'll feel better once we're able to start taking action against them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10574] = {title = "The Ashtongue Corruptors", objective = "Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Anchorite Ceyla at the Altar of Sha'tar in Shadowmoon Valley.\n\nPerforming quests for the Aldor will cause your Scryers reputation level to decrease.", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", progress = "Have you obtained the four medallion fragments, <name>?", completion = "Yes!  The four fragments of the medallion.  Now to put them together...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10575] = {title = "The Warden's Cage", objective = "Anchorite Ceyla wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", progress = nil, completion = "We've been expecting you, &lt;name&gt;.  Akama said you would arrive sooner or later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10576] = {title = "The Shadowmoon Shuffle", objective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover 6 pieces of Eclipsion Armor.", description = "<Borak looks you up and down.>\n\nThis is going to be tricky, but I think I can make it work.\n\nI can disguise you as one of these Illidari blood elves, <name>. What I need first, though, are several pieces of their armor. It is imperative that the armor be clean. No blood stains! We want to avoid suspicion.\n\nBring me the gear and I'll take care of the rest of the disguise.\n\nOnce the disguise is assembled, you're going to deliver the message to the Grand Commander - in person.", progress = "It's far too complicated, <race>. You wouldn't understand.", completion = "Well done, &lt;name&gt;. I hope you are a good actor. The next step in my grand plan is going to require some theatrics!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10577] = {title = "What Illidan Wants, Illidan Gets...", objective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to Deliver Illidan's Message to Grand Commander Ruusk at Eclipse Point.", description = "Take this disguise and enter Eclipse Point. Once inside, use the disguise to cloak yourself. The Eclipsion blood elves will be unable to see through the disguise, thereby granting you safe passage to Grand Commander Ruusk.\n\nOnce you find Ruusk, tell him where next to move the cipher. You're going to have to act your heart out, <name>. Play it off as if you are his superior, delivering a message from his lord. That should do it!\n\nOh - watch out for the dragonhawks as they see through the disguise.", progress = "The disguise is delicate. Almost any action, aside from walking, will disrupt the magic holding it together.", completion = "Now all you need to do is go get the cipher. Easy, right?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10578] = {title = "The Cipher of Damnation - Borak's Charge", objective = "Borak, Son of Oronok at the bridge near Eclipse Point in Shadowmoon Valley wants you to recover the Third Part of the Cipher of Damnation from Ruul the Darkener.\n\nThis mission will require a group.", description = "That Cipher fragment will never reach Zuluhed. You're going to ambush Ruul the Darkener and his transport before it has a chance to make the delivery.\n\nThe Dragonmaw Fortress is directly east of here, across the Netherwing Fields. Somewhere between Dragonmaw Fortress and the Sanctum of the Stars is where you'll find Ruul. Strike hard and strike fast! And <name>, from the sound of it, this Ruul is going to be tough. Keep your guard up.\n\nReturn the Cipher to me should you succeed.", progress = "You must act quickly!", completion = "Finally! The cipher fragment is ours!\n\n&lt;Borak places the fragment into a box.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10579] = {title = "The Cipher of Damnation - The Third Fragment Recovered", objective = "Take Borak's Lockbox to Oronok Torn-heart at Oronok's Farm in Shadowmoon Valley.", description = "Take this box to my father. He still resides at Oronok's Farm, far to the north, above Coilskar Cistern. When all three fragments are pieced together, the ancient words will be known once more.\n\nGood luck, <name>. Tell my father that I will be home soon.", progress = "<name>!", completion = "As soon as all three of the fragments of the cipher are together, the ancient words will be known.\n\nRecovery of this fragment was no doubt challenging. You must be rewarded for such heroism.", rewards = "You will be able to choose one of these rewards:\n\nAr'tor's MainstayBorak's Belt of BraveryFelboar Hide ShoesSpaulders of the Torn-heartThe Hands of FateUmberhowl's Collar\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10580] = {title = "Where Did Those Darn Gnomes Go?", objective = "Commander Skyshadow has asked you to look in the southern area of the Jagged Ridge of the Blade's Edge Mountains for a clue as to the whereabouts of Toshley and the other gnomes.", description = "Despite the good that we've done here, I feel bad about one thing: driving Toshley and his gnome friends away.\n\nWe had no choice; they were making a mess of our efforts in the grove with all of their technology and experimentation.\n\nI would appreciate it if you would find out what became of them.  Last we heard, they headed east across the bridge.  I'm certain that they must have turned south, away from Thunderlord Stronghold.\n\nLook for a clue as to their whereabouts in the southern Jagged Ridge.", progress = nil, completion = "SYLVANAAR?  COMMANDER SKYSHADOW?\n\nTHIS DOES NOT COMPUTE!\n\nBACK AWAY BEFORE I AM FORCED TO PLAY LOUD SOUNDS AT YOU!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10581] = {title = "Follow the Breadcrumbs", objective = "In a round-about way, R-3D0 has informed you that if you follow the trail of spare parts up the ramp here to the Razor Ridge, you will find the gnomes at a place named Toshley's Station.\n\nIf you find him, speak with Toshley.", description = "VERY WELL, I AM HEREBY WARNING YOU THAT YOU WILL FIND NOTHING UP ON THE RIDGE.\n\nDO NOT FOLLOW THE TRAIL OF SPARE PARTS THAT LEAD TO TOSHLEY'S STATION!  YOU WILL NOT FIND TOSHLEY, NOR ANY OTHER GNOME THERE.", progress = nil, completion = "Alright, you want to make yourself useful?  Good, I have just the thing that you can prove yourself with.\n\nI think you'll like it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10582] = {title = "Minions of the Shadow Council", objective = "Stormer Ewan Wildwing at the Deathforge Tower wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners.", description = "<Ewan listens to you recount the events at Legion Hold, nodding.>\n\nThat puts our observations into perspective. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the Deathforge sealed tighter than a new keg o' thunderbrew. The first thing you'll need to do is crack some skulls so you can get in there and poke around. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", progress = "Have you cleared a way into the Deathforge yet?", completion = "I wish I could've been out there with you! I've been itching to put my hammer to use, but my mission is to observe, not to kill.\n\nNow that you've punched a hole in their defenses, let's get to work on shutting down production in the Deathforge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10583] = {title = "The Fate of Flanis", objective = "Stormer Ewan Wildwing at Deathforge Tower wants you to search the Deathforge for Flanis Swiftwing and recover Flanis's Pack.", description = "Wing Commander Nuainn originally sent three of us out here to keep watch over the Deathforge and to gather information. Flanis Swiftwing volunteered to try to infiltrate the Deathforge, but we haven't heard anything from him in days.\n\nI fear the worst, <name>. Flanis is a skilled scout, but if he's gotten in over his head, we have no way of knowing. Search the Deathforge for him and recover any information or items he might have collected.", progress = "Did you find any sign of Flanis in the Deathforge?", completion = "&lt;Ewan shakes his head as he accepts the pack from you&gt;\n\nI don't think Flanis realized how heavily guarded the Deathforge would be. Now that we know what's really going on there, I don't blame them. I just wish Flanis had known that when he went in.\n\nI can only hope there's something here that will help us shut down the Deathforge once and for all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10584] = {title = "Picking Up Some Power Converters", objective = "Toshley has asked you to take the Protovoltaic Magneto Collector and gather up 5 Electromentals. Return to him at Toshley's Station in the Blade's Edge Mountains after you have done so.", description = "Those dumb ogres at the Bladespire Outpost to the north have been raiding our power converters!  And you're going to get them back for me, sort of.\n\nNo doubt, with their big, clumsy hands, the ogres have damaged the converters.  So, what I want you to do is release the energy from them and then use this protovoltaic magneto collector on the resultant electromental to encase it.\n\nIt'll likely be sore with you, so you'll need to 'kill' it while it's contained in the magneto sphere.", progress = "This line of research we have going with the electromentals is exciting!  Just think of it... intelligent electrical creatures that we can create at will and that will follow our every instruction!\n\nWhat could possibly go wrong?", completion = "Excellent!  With all of this power that you've recovered we'll be able to keep the machinery running for a little while, anyway.\n\nThe Zephyrium Capacitorium is a real pig when it comes to power consumption!\n\nI hope dealing with those electromentals wasn't too difficult.  I have something else in mind for you to do, and I have a feeling that it's going to be a little more dangerous.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10585] = {title = "The Summoning Chamber", objective = "Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning  chamber. Report to Stormer Ewan Wildwing at the Deathforge Tower when you've completed your task.", description = "In order for the Shadow Council to construct infernals as quickly as they're being used, they must have an area dedicated to summoning the corrupted elementals that serve as the souls of the creatures.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", progress = "We cannot afford to let their production continue. Have you put an end to the summoning ritual?", completion = "Well done, &lt;name&gt;. Disrupting the Shadow Council's summoning puts us one step closer to shutting down the Deathforge.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10586] = {title = "Bring Down the Warbringer!", objective = "Defeat Warbringer Razuun, recover Razuun's Orders, and report to Wing Commander Nuainn at Wildhammer Stronghold.", description = "We've made a lot of progress against the Shadow Council's operations at the Deathforge, but if we're to truly be triumphant, we'll need to defeat the Legion's overseer there.\n\nI found a key among the items in Flanis's pack. I'm certain it will prove useful in tracking down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Wing Commander Nuainn. He'll want to know immediately!", progress = "What news do you bring from the Deathforge?", completion = "&lt;You make your report to the wing commander and hand over the captured orders.&gt;\n\nDefeating Warbringer Razuun should've meant the end of our troubles with the Legion, but these orders outline a much larger plan that I had anticipated. I fear that more remains to be done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10587] = {title = "Karabor Training Grounds", objective = "Exarch Onaala at the Altar of Sha'tar wants you to obtain 8 Sunfury Glaives from Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, southeast of the Altar of Sha'tar.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", progress = "Have you completed the task I asked of you, <name>?", completion = "Let's take a closer look at these weapons, &lt;name&gt;.  Hmmm... this is rather unsettling.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10588] = {title = "The Cipher of Damnation", objective = "Use the Cipher of Damnation at the Altar of Damnation to summon Cyrukh the Firelord.\n\nDestroy Cyrukh the Firelord and then speak with Earthmender Torlok, also found at the Altar of Damnation.", description = "How many times has this spell has been used in the history of our worlds? Undoubtedly, its power for destruction is unparalleled.\n\nWhat you must do now is take the cipher, now made whole, and read from it at the Altar of Damnation - where the memory of Gul'dan stands.\n\nWhat you will see once the words are uttered are the memories left imprinted upon the land. Stand your ground and await the coming of Cyrukh.\n\nYou must be victorious, <name>. This land can not withstand another shattering.", progress = "Is it done?", completion = "&lt;Earthmender Torlok takes the Cipher of Damnation from you.&gt;\n\nYou have done as the elements asked. For that, we are grateful. While you will be rewarded, trouble still looms. The spirits of fire are in turmoil. A claim has been made. the Cipher of Damnation is known by another.\n\nIt is cryptic, I know, but that is all that the spirits would have me know. That and this symbol...\n\n&lt;Earthmender Torlok turns around and points to the sky.&gt;\n\nWhat could it mean?", rewards = "You will be able to choose one of these rewards:\n\nOronok's Ancient ScepterStaff of the RedeemerTorn-heart Axe of BattleGrom'tor's ChargeLohn'goron, Bow of the Torn-heartBorak's Reminder\n\nYou will also receive:\n\nAmulet of the Torn-heart"}
MultiLanguageQuestData['en'][10589] = {title = "Gaining Access", objective = "Bring a Legion Teleporter Control to Wing Commander Nuainn at Wildhammer Stronghold. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices.", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's nestled in the northern mountains. The only way to reach it is by using a teleporter located at Legion Hold.\n\nCertain members of the Legion host carry devices allowing them to activate the teleporters. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed.", progress = "We must find a way to destroy the rest of those infernals, <name>. We've come far, but failure could still cost us everything.", completion = "Let me see if I can find out how this works...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10590] = {title = "Prove Your Hatred", objective = "Mehlar Dawnblade at the Bulwark wants you to bring him 20 Minion's Scourgestones.", description = "It is time you remembered history that should not be forgotten... the slaughter of our people by Arthas and his Scourge army.\n\nVengeance on the Scourge is the only way to ease your pain.  It is unfortunate they are not susceptible to fear and pain.  Only their utter destruction will bring you even a shred of satisfaction.\n\nSpeak with Argent Officer Garush for knowledge of scourgestones and how to obtain them -- I will need to see many of them as proof of your commitment before we speak again.", progress = "Have the Scourge crumbled beneath your weapon?", completion = "Very good, &lt;name&gt;.  Perhaps you have a taste for revenge after all.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10592] = {title = "Wisdom of the Banshee Queen", objective = "Bring the Scourgestone Fragments to Lady Sylvanas Windrunner in Undercity.", description = "The scourgestones are weak when separated from the skeletal grasp that once held them.  Simply holding them in my hands has caused them to fracture and break.\n\n<Mehlar crushes the scourgestones into a pile of rubble.>\n\nTake these fragments to the Banshee Queen, Lady Sylvanas Windrunner, at her throne in Undercity.  With her lies the knowledge to turn these remains into a weapon against the Scourge.", progress = "Do you have something for me, <race>?", completion = "These stones carry a taint I do not wish to remember, but one I cannot forget.  You try my patience dangerously by bringing these to me.\n\nHowever, it is clear your heart seeks the same vengeance as I, and I will aid you with instruction.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10593] = {title = "Ancient Evil", objective = "Unlock the secrets of the Temple of Atal'Hakkar to release Atal'alarion and recover the Putrid Vine from his flesh. Return to Mehlar at the Bulwark when you have done this.", description = "If you wish to turn these stones into a weapon to fight the Scourge, you must acquire something equally vile to fortify them.\n\nAn ancient evil lies hidden at the bottom of the Temple of Atal'Hakkar in the Swamp of Sorrows.  Release the creature there and destroy him, taking only a small part of his body back to Mehlar Dawnblade.  My guards will deliver the scourgestone fragments to Mehlar.", progress = "Given that you are alive, I can only surmise you were lucky enough to receive wisdom rather than death from Lady Sylvanas.", completion = "The Banshee Queen has guided you well.  This is precisely what I need to combine the fragments.\n\n&lt;Mehlar watches as the vine interweaves through the fragments, binding them together.&gt;\n\nThere!  Scourgebane, I shall call it.  Be wary when you use it, for it serves you against its will.", rewards = "You will receive:\n\nScourgebane"}
MultiLanguageQuestData['en'][10594] = {title = "Gauging the Resonant Frequency", objective = "Nickwinkle the Metro-Gnome wants you to place the Oscillating Frequency Scanners in such a way that when you stand amongst them, you are hit by five overlapping Oscillation fields.\n\nReturn to him at Toshley's Station in the Blade's Edge Mountains after you have done so.", description = "Take these scanners to the Singing Ridge.  By dropping them in a pattern on the ground, you will create overlapping fields that will read the amplitude of the crystals.  Stand amidst them in such a way that you're in five oscillation fields and I'll have the information that I need!\n\nYour scanners will even work with those that others drop.\n\nOh, and it's likely that a rift will be formed!  I have no idea what, if anything, will come out of it, but be prepared for the worst.", progress = "Well, do you have the measurements from the singing crystals that I asked for?", completion = "Oh, this is extraordinary!  I had no idea... it's almost as if those crystals are alive.\n\nI wonder if there's some sort of symbiotic relationship between them and the nether drakes?\n\nThank you, thank you!  You must accept a little something from my collection of odds and ends that I wouldn't be caught dead wearing.\n\nOne of them might look good on you, though.", rewards = "You will be able to choose one of these rewards:\n\nParty Hat MistakeNickwinkle's Harness ExperimentLast Year's \"In\" BeltMetro's Slimming Legs\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10595] = {title = "Besieged!", objective = "Blood Guard Gulmok outside of Shadowmoon Village, wants you to kill 10 Infernal Attackers.", description = "<Gulmok looks to the sky.>\n\nOur scouts are putting up a good fight, but the infernals keep coming!\n\nFrom their base of Legion Hold to the southwest, the demons bombard us with impunity! Even the elite Kor'kron guard cannot hold them off forever.\n\nI'm drafting every able-bodied <race> to do their part in defense of Shadowmoon Village. This is no game, <class>. The survival of the village is at stake. Do your duty to the Horde, and join the fray!", progress = nil, completion = "I'm impressed that you managed to survive the carnage. You just might be the person we need for a dangerous mission.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10596] = {title = "To Legion Hold", objective = "Make your way to Legion Hold, locate the Legion Communication Device, and learn about the Legion's plans while in disguise. Return to Blood Guard Gulmok at Shadowmoon Village when you've completed your mission.", description = "The fortress of Legion Hold is your target. You'll have no reinforcements, so a frontal attack is out of the question.\n\nWhat little information we have shows that the Legion stocks and prepares its infernals at the hold. With the help of a disguise I'll give you, you must sneak into Legion Hold and discover their plans.\n\nYour best hope is to intercept or overhear communication between their commanders.", progress = "What did you discover?", completion = "&lt;Blood Guard Gulmok listens to your report, growing more alarmed with each sentence.&gt;\n\nWhat do you mean they're going to step up the bombardment? We can't allow that to happen. Get back out there and take care of it while there's something left of Shadowmoon Village!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10597] = {title = "Setting Up the Bomb", objective = "Obtain a Fel Reaver Power Core and a Fel Reaver Armor Plate, then bring them to Blood Guard Gulmok at Shadowmoon Village.", description = "We can't allow the Legion to trample us on their march to Black Temple.\n\nFind a way to destroy the infernals they intend to use against us. That's not a request, <name>; it's an order.\n\nThe Fetid Pool near Legion Hold holds an old fel reaver power core you could use as the basis for a kind of fel bomb. Search the other wreckage near the fel reaver for a section of armor plating. You should be able to make a bomb powerful enough to take out those infernals and give the hold a nice shake!", progress = "<You hand the materials to Gulmok.>", completion = "&lt;Gulmok slips the power core inside of the casing, then seals it.&gt;\n\nThat should do the trick. I wouldn't want to be in the hold when that thing goes off.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10598] = {title = "Blast the Infernals!", objective = "Use the Fel Bomb while standing on the green glyph in Legion Hold to destroy the infernals, then report to Blood Guard Gulmok at Shadowmoon Village.", description = "The device we've assembled won't win any beauty contests, but it should be capable of destroying the infernals amassed at Legion Hold. Judging from what the fel reaver power core's energy did to the Fetid Pool, it holds a respectable amount of explosive power.\n\nIf you set the device off in the middle of the green glyph at the hold, it should be in range to hit all of the infernals.", progress = "Have you found a way to destroy the Legion's infernal stockpile?", completion = "&lt;Gulmok nods grimly.&gt;\n\nThis is no time for celebration, &lt;name&gt;. We're not out of the fire yet. I've got new orders for you.", rewards = "You will be able to choose one of these rewards:\n\nBloodforged GuardCrimson Mail HauberkMooncrest HeaddressSoothsayer's Kilt\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10599] = {title = "The Deathforge", objective = "Report to Scout Zagran at Slag Watch.", description = "While you were taking care of the infernals at Legion Hold, I've been going over your reports. We've got no reason to believe the Legion lied about what's going on at the Deathforge. They're really cranking out infernals down there, so I've dispatched a scouting party to keep watch over it.\n\nIf we don't shut down the Deathforge, they'll rebuild the infernal stockpile that you destroyed at Legion Hold.\n\nReport to Scout Zagran atop Slag Watch, to the southeast of here and overlooking the Deathforge.", progress = nil, completion = "&lt;The orc nods.&gt;\n\nIt'll be good to have the backup. We've gathered some preliminary information on what the Shadow Council is up to in there, but it's time for the hammer to fall.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10600] = {title = "Minions of the Shadow Council", objective = "Scout Zagran at Slag Watch wants you to kill 10 Deathforge Guardians and 5 Deathforge Summoners.", description = "<Zagran listens to you recount the events at Legion Hold, nodding.>\n\nThat fills in the gaps we've seen. We've caught glimpses of them launching infernals in the direction of the hold, but haven't been able to find much more than that.\n\nThe Shadow Council has the forge pretty much locked down. Looks like you're going to need to fight your way in. Start eliminating the Shadow Council guarding the entrance to the Deathforge!", progress = nil, completion = "I'd've been down there cracking skulls myself, but I'm under strict orders not to engage the enemy.\n\n&lt;The scout grumbles, doing a fair imitation of Blood Guard Gulmok's voice.&gt;\n\nLet's get to work on shutting down production in there.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10601] = {title = "The Fate of Kagrosh", objective = "Scout Zagran at Slag Watch wants you to search the Deathforge for Kagrosh and recover Kagrosh's Pack.", description = "The scouting party originally had three members. Unfortunately, Kagrosh decided he wanted to be a hero.\n\nHe descended into the Deathforge and we haven't heard from him since.\n\nIn all likelihood, the fool's gone and gotten himself killed. The Shadow Council members aren't idiots and Kagrosh wasn't exactly strong in the subtlety department, if you know what I mean. Keep an eye out for him in the Deathforge and recover any information or items he might have collected.", progress = "Did you find any sign of Kagrosh in the Deathforge?", completion = "&lt;Zagran shakes his head as he accepts the pack from you&gt;\n\nI told you he was a fool. I hope there's something in here that justifies the time you spent searching for him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10602] = {title = "The Summoning Chamber", objective = "Obtain an Elemental Displacer from a Deathforge Smith or Deathforge Tinkerer and use it to disrupt the ritual in the summoning chamber. Report to Scout Zagran at Slag Watch when you've completed your task.", description = "In order to churn out infernals as quickly as the Deathforge seems to, they must have an area dedicated to summoning the elementals that form the core of the infernals.\n\nThe summoning chamber is likely to be found below ground, near a pool of fouled water or lava. Locate the summoning chamber within the Deathforge and find a way to end their summoning ritual. The mo'arg involved in making the infernals may carry a tool that will help disrupt the summoner's magics.", progress = "We cannot afford to let their production continue. Have you put an end to the summoning ritual?", completion = "Good, we're making progress. That puts us one step closer to shutting down this facility and returning safely to Shadowmoon Village.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10603] = {title = "Bring Down the Warbringer!", objective = "Defeat Warbringer Razuun, recover Razuun's Orders, and report to Blood Guard Gulmok at Shadowmoon Village.", description = "We've made a lot of progress against the Shadow Council here at the Deathforge, but now it's time to finish the job.\n\nI found a key among the items in Kagrosh's pack. At least he accomplished something before they got to him.\n\nThe key should help you to track down this Warbringer Razuun you observed at Legion Hold.\n\nAfter you've hunted down and dealt with Warbringer Razuun, report directly to Blood Guard Gulmok. We must not keep him waiting.", progress = "What news do you bring from the Deathforge?", completion = "&lt;You make your report to the blood guard and hand over the captured orders.&gt;\n\nGood work, &lt;name&gt;, but don't go thinking you'll be getting any ribbons for it. Let the night elves decorate their pretty little uniforms if they wish. Real warriors share tales of battle over a mug of ale.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10604] = {title = "Gaining Access", objective = "Bring a Legion Teleporter Control to Blood Guard Gulmok at Shadowmoon Village. The Mo'arg Weaponsmiths at Legion Hold are known to carry the devices.", description = "According to Razuun's orders, the massive infernal staging area is called Invasion Point: Cataclysm and it's located in the mountains behind our village! The only way to reach it is by using a teleporter at Legion Hold.\n\nCertain Legion minions carry a device allowing them to use the teleporter. You must capture one of these devices to win access to the teleporter. Slaughter all of the demons if you must, but you can't afford to return empty-handed. Do not delay; the enemy is perilously close.", progress = "A Legion presence in our midst is intolerable! We must find a way to deal with it before they can renew their assault.", completion = "At last, we have a means with which to drive the Legion from Shadowmoon!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10605] = {title = "Carendin Summons", objective = "Speak with Carendin Halgar in Undercity.", description = "You have a hungry look about you, <name>.  Perhaps it is time you advanced your training.\n\nTravel to Undercity and speak with Carendin Halgar, the old bag of bones knows a trick or two you might find useful.", progress = nil, completion = "Ah, yet another power hungry initiate.  Wonderful!\n\nWouldn't be much of a &lt;class&gt; if you didn't thirst for power, now would you boy?  Let's get on with it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10606] = {title = "The Art of Fel Reaver Maintenance", objective = "Kill Doctor Gutrick and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Plexi at Invasion Point: Cataclysm.", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Gutrick keeps locked in a chest at the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest!", progress = "Did you get that manual?", completion = "Ah, this is exactly what we'll need. I'd never accuse the Legion of producing anything resembling literature, but it gets the job done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10607] = {title = "Whispers of the Raven God", objective = "Kill Grishna arakkoa to gain Understanding Ravenspeech for 2 minutes. While under the effects of the spell, you can find and receive the prophecy from the four shrines. Return when you have visited all four.", description = "At Grishnath, totems left by the Oracles of the Raven enable the arakkoa to hear the Word of the Raven. Unfortunately, the language of the arakkoa is indecipherable to us.\n\nUsing the Harbinger's pendant, we can understand it. You will be able to take the souls of the arakkoa to understand their language. While you are suffused with the arakkoa's spirit, you can visit the totems and understand their message.\n\nDiscover this for us, <name>.", progress = nil, completion = "This is truly disturbing. The arakkoa were peaceful for a long time. This cult of the Raven was nothing more than a gathering of misfits and madmen.\n\nBut their power has grown, that we cannot discount. Perhaps there is more to this Raven than we know.", rewards = "You will be able to choose one of these rewards:\n\nWraithcloth BindingsSupple Leather BootsDiluvian SpauldersWhiteknuckle Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10608] = {title = "Crystal Clear", objective = "Nickwinkle the Metro-Gnome wants you to slay 10 Crystal Flayers and then return to him at Toshley's Station in the Blade's Edge Mountains.", description = "The damned rock flayers are keeping me from my research down in the Singing Ridge!  By digging at the crystals there, with every scratch they are ruining my chances of studying the harmonics of the singing crystals.\n\nYou look like someone who can help me deal with this problem.  Head south and clear those crystal flayers out.", progress = "Have you cleared those crystal flayers out of the Singing Ridge yet?  We can't get started on my research until you do.", completion = "Good riddance to them; that's what I say.  Filthy creatures!\n\nSo, if you're certain that you eliminated those pests, then I have a little research project for you.  I think you'll like it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10609] = {title = "What Came First, the Drake or the Egg?", objective = "Collect 3 Proto-Nether Drake Essences, 3 Adolescent Drake Essences and 3 Mature Drake Essences. Return with them to Fizit \"Doc\" Clocktock at Toshley's Station in the Blade's Edge Mountains.", description = "I'm researching the applications of drake essences to my work as a physician.  I think they could be a panacea for a host of maladies!\n\nI need someone to go south to the Singing Ridge and get me some.\n\nWilling to take my temporal phase modulator and use it on the nether whelps that hatch from the nether drake eggs?  Retrieve the essences from whatever they turn into.\n\nWhich, I might add, I'm not certain of what that will be as we're using some pretty dicey, time  and space modifying tech here.", progress = "You have them?  You have the three drake essences that I so dearly need to continue my research?\n\nYou know that those nether drake eggs used to be black dragon eggs?  It's a fact!  But when Draenor blew apart, the resultant nether that raced across what was left mutated the eggs.", completion = "You've no idea how important this research could be.  Thank you!\n\nIt'll be interesting to delve into these essences.  I'm particularly curious to see if the nether effect that changed the black dragon eggs into nether dragon eggs resulted in any potential extra blessings for my studies.\n\nI'm thinking, in fact, that you should be the first person to test out the benefits of my little concoction.  Here, take these preliminary samples and use them when you find the need.", rewards = "You will be able to choose one of these rewards:\n\nFizit's Mantle of Drake HuntingPrecise Gloves of AlacrityDevolved Drake GirdleClocktock's Jumpers\n\nYou will also receive:\n\nMedicinal Drake Essence"}
MultiLanguageQuestData['en'][10611] = {title = "The Art of Fel Reaver Maintenance", objective = "Kill Doctor Maleficus and obtain the Doctor's Key. Use the key to open the Doctor's Strongbox to retrieve The Art of Fel Reaver Maintenance and deliver the book to Nakansi at Invasion Point Cataclysm.", description = "The best way to destroy the rest of the Legion's supplies is to use their own weapons against them. I've been working on a rig that will let you take control of one of those Fel Reaver Sentinels below.\n\nThere are a couple things I need to work out, yet. For that, I'll need the manual that Doctor Maleficus keeps locked in a chest near the bottom of the ramp. He probably won't give up the key without a fight, so you'll need to capture it. Bring the fel reaver manual back to me and I'll do the rest.", progress = "Did you get that manual?", completion = "This has the information I'm looking for. Just a couple more tweaks, and we'll have you taking control of a fel reaver in no time.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10612] = {title = "The Fel and the Furious", objective = "Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Plexi at Invasion Point: Cataclysm.", description = "<Plexi leafs through the manual.>\n\nWell, this has everything we need, but there's just one problem. Fel Reavers aren't really built to respond to remote control.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion's lackeys, either. Keep an eye out, and whatever you do, don't forget to destroy as much as you can!", progress = "You're back, so I'll assume the operation went well. What've you got to report?", completion = "Amazing! You've managed to do what all the gryphonriders in Wildhammer Stronghold couldn't! You've broken the back of the Burning Legion's advance and spared us from annihilation at the hands of their infernals. You have our deepest gratitude for your service, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10613] = {title = "The Fel and the Furious", objective = "Use a Fel Reaver Control Console to take control of a Fel Reaver Sentinel. Destroy 60 Deathforged Infernals before your fel reaver fails. When your mission is complete, report to Nakansi at Invasion Point: Cataclysm.", description = "<Nakansi leafs through the manual.>\n\nAll the information is here, but be warned. These things weren't built to be controlled remotely.\n\nWe can modify one for you to use for a short time, but you'll have to work fast, or there's no telling what might happen! I wouldn't be surprised if your little stunt with the fel reaver catches the attention of the Legion scum, either. Try to keep yourself safe, but remember, the mission and the safety of Shadowmoon Village come first!", progress = "You're back, so I'll assume the operation went well. What've you got to report?", completion = "I'll admit it, &lt;name&gt;. I'm impressed by all you've managed to accomplish. Destroying the Legion's ability to make war in Shadowmoon will give us the opportunity to turn the tide elsewhere.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10614] = {title = "Whispers on the Wind", objective = "Search out Leoroxx at the Mok'Nathal Village in the Blade's Edge Mountains.", description = "I have chased rumors of the Mok'Nathal across Outland with nothing to show for it. Finally, we may have found their home.\n\nBut now that the moment is here, I am filled with unease. Unease that has kept me awake deep into the nights during my search. Will they accept me?\n\nI... know their leader's name: Leoroxx. Seek him out. You must be my eyes in this.", progress = nil, completion = "What brings you to our village?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10615] = {title = "Ruuan Weald", objective = "Speak with Timeon at Evergrove, which is in the Ruuan Weald in the Blade's Edge Mountains.", description = "The information you have helped me reveal about the nature of the arakkoa here will be of great interest to another.\n\nWe were visited by members of the Cenarion Expedition, who have also become concerned with the arakkoa's intentions here in the Blade's Edge Mountains.\n\nYou should seek him out. His name is Timeon, and you will find him at Evergrove in Ruuan Weald. Follow the road west from here, then north when it forks in Razor Ridge. Finally, follow the road west when it splits in the Bladed Gulch.", progress = nil, completion = "Ah, yes, Dertrok. We spoke briefly about the arakkoa. I must say that our... interests in them vary quite significantly.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10617] = {title = "Silkwing Cocoons", objective = "Taerek at Mok'Nathal Village wants you to collect 8 Silkwing Cocoons from Silkwing Larva.\n\nKill the Larva quickly or they will turn into Silkwings, ruining their cocoons.", description = "The silk from the cocoons of the silkwings are used for all manner of things in the village. We can never get enough, and we never have enough.\n\nIt is difficult to harvest the cocoons from the larva once they begin the process of metamorphosis.\n\nOur warriors are occupied with the assault on our village. If you could gather these for us, that would be helpful.", progress = "A swift and sure hand is needed for the harvesting. I hope you will be successful.", completion = "Good quality cocoons, these. I can see you've gotten the hang of harvesting them.\n\nWe have experimented with trying to raise our own silkwing larva, but unfortunately the small ones do not produce enough silk to be of use to us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10618] = {title = "The Softest Wings", objective = "Silmara at Mok'Nathal Village wants you to collect 12 Iridescent Wings.", description = "Hunting silkwing larva is a difficult challenge for our young warriors, but luckily, even if they fail to harvest the cocoon from the larva, we can still use the wings of hatched silkwings.\n\nIn fact, we use the wings for much more than the cocoons, and we can never have too many.\n\nIf you'll be out there, it would be a great help if you could bring me some.", progress = "The wings are quite delicate, but can be inlaid as a decorative element in many of our designs.", completion = "Thank you, &lt;name&gt;. We will use these sooner than you might think.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10619] = {title = "The Ashtongue Tribe", objective = "Vindicator Aluumen wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, southwest of here.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", progress = nil, completion = "Glory to the naaru, &lt;name&gt;.  You've done the Light's bidding by defeating those who follow Illidan.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10620] = {title = "Ridgespine Menace", objective = "Dizzy Dina wants you to kill 10 Ridgespine Stalkers. After you have done so, return to her at Toshley's Station in the Blade's Edge Mountains.", description = "We hired on to help Toshley when he decided to move to Outland, and we've been on the move ever since.\n\nNow it looks like we've finally put down some roots.  All of the crazy scientists have their projects going, and us Roughriders are here to protect them.\n\nWhat we need right now is for you to go north into Razor Ridge, or east to the Scalewing Shelf, and keep them clear by killing the stalkers.  They're stealthy spiders that live amongst the rock outcroppings, and jump unsuspecting passersby.", progress = nil, completion = "Pretty good for a rookie.  As it turns out, we've got a small group of eggheads that want to go 'observe' the ethereals and their technology up north.  They'll be thrilled to know that you cleared the way for them.\n\nHere, take some of these.  We don't have many, but maybe they'll help you out in the future.", rewards = "You will be able to choose one of these rewards:\n\nDistilled Stalker SightStealth of the Stalker\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10621] = {title = "Illidari-Bane Shard", objective = "Bring the Illidari-Bane Shard to Ordinn Thunderfist at Wildhammer Stronghold.", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Wildhammer Stronghold might be able to tell you more about it.", progress = "What have you got there?", completion = "&lt;Ordinn accepts the weapon fragment from you.&gt;\n\nI haven't seen something like this in a long time. Sure, it's made from a rare ore, but this is destined for no mundane weapon, &lt;name&gt;. It's infused with a magic intended to destroy demons. If you obtained this from the Legion, it must be some kind of 'secret weapon' they're planning to deploy against Illidan. What a find!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10622] = {title = "Proof of Allegiance", objective = "Slay Zandras at the Warden's Cage in Shadowmoon Valley and return to Sanoru.", description = "Akama has been tracking your progress quite closely, <name>.\n\nThe Ashtongue you've slain at the Ruins of Baa'ri are amongst the most evil Broken known among us... carefully hand-picked by Akama himself to maintain the facade we need to present to Illidan.  The Deathsworn, however, know of Akama's true intentions.\n\nFirst things first.  We need to know that you are not with Illidan.  A Satyr known as Zandras watches over us from above the prison walls on his behalf.  Slay him as proof of your allegiance.", progress = "Have you done what I asked of you, <name>?  Trust is not easily found around these parts.", completion = "Very well, &lt;name&gt;.  Your allegiance is no longer in question.  You may see Akama now.", rewards = nil}
MultiLanguageQuestData['en'][10623] = {title = "Illidari-Bane Shard", objective = "Bring the Illidari-Bane Shard to Grokom Deatheye at Shadowmoon Village.", description = "The shard appears to be a piece of a larger weapon. Sharp-looking runes etched into the metal glow with a menacing light.\n\nThe weapon's intended purpose isn't clear to you, but it's hard to ignore. Most of the mo'arg at Legion Hold seem to be working with fragments of the same metal you hold in your hand. Perhaps one of the weaponsmiths at Shadowmoon Village might be able to tell you more about it.", progress = "What have you got there?", completion = "&lt;Grokom accepts the weapon fragment from you.&gt;\n\nI haven't seen this in years. Not only is it made from a rare ore, but it's not about to be used in an ordinary weapon, &lt;name&gt;.\n\nThese runes imbue the blade with the power to obliterate demons. This shows how much the Legion hates Illidan, if they're willing to arm their own troops with demon-destroying weapons. We could use this to our advantage.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10624] = {title = "A Haunted History", objective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to bring her 15 Ever-burning Ash samples.", description = "Have you felt the cold chill? Perhaps what you thought was a hand on your shoulder? That was not your mind playing tricks on you, <race>. The land is haunted. Ghosts litter the landscape, stuck here for all eternity.\n\nWould you like to see them? Are you sure about that? These types of things tend to change a person - and not for the better.\n\nVery well, I will need you to collect for me the ever-burning ash that is found near any of the fel lava pools of western Shadowmoon. Anywhere near green lava...", progress = "What do you mean? I'm going to make something out of the ash - obviously.", completion = "Your world is about to change, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10625] = {title = "Spectrecles", objective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to slay 12 Shadowmoon Zealots.", description = "I call them \"Spectrecles.\" Clever, no? When you equip these goggles, you will be able to see the spirits of Shadowmoon Valley.\n\nBefore I let you have them, though, you must promise me that you will help us clear out the ghosts at the village.\n\nTake the goggles and destroy any and all spirits that you see wandering about Shadowmoon Village. Hopefully, destroying these spirits will force any that remain to move elsewhere.", progress = "If you lose your goggles, let me know and I will craft another pair.", completion = "Gorefiend? T... Teron Gorefiend? But... How?\n\nHow could Gorefiend be here? This is impossible!\n\nThe legend of Teron Gorefiend is one that causes even the Forsaken to tremble in fear. By all accounts, Gorefiend was a warlock of Gul'dan - extremely powerful in his own right. When Gorefiend was slain by Orgrim Doomhammer, Gul'dan took the soul of the fallen warlock and placed it inside the broken shell of a slain knight of Stormwind. And so was born the first death knight of the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10626] = {title = "Capture the Weapons", objective = "Ordinn Thunderfist at Wildhammer Stronghold wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.", description = "With a larger supply of this material, we might be able to forge a weapon for you to use.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. We have no way of knowing how many more the Legion intends to produce, but if we can capture these prototypes, there should be enough for our project.\n\n<Ordinn grins.>\n\nThere's a certain amount of satisfaction in using the Legion's own 'secret weapons' against them, don't you think?", progress = "Did you capture those prototypes?", completion = "These should work nicely. Now, let's forge them into a more useful form.", rewards = "You will be able to choose one of these rewards:\n\nAshwalker's FootwrapsAzurestrike ShouldersDarkhunter's CinchSinged Vambraces\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10627] = {title = "Capture the Weapons", objective = "Grokom Deatheye at Shadowmoon Village wants you to bring him Mazakradon's Glaive and Morgroron's Glaive.", description = "With a larger supply of this material, I can forge a weapon suitable for you.\n\nThe two pit lords at Legion Hold, Makazradon and Morgroron, have already been equipped with these anti-demon weapons. Capturing those two weapons should provide us with enough material to make your weapon, and then some.\n\nI can't wait to bring the battle to the enemy using these weapons. That'll teach the Legion to trifle with anti-demon magics.", progress = "Did you capture those prototypes?", completion = "These should work nicely. Now, let's forge them into a more useful form.", rewards = "You will be able to choose one of these rewards:\n\nAshwalker's FootwrapsAzurestrike ShouldersDarkhunter's CinchSinged Vambraces\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10628] = {title = "Akama", objective = "Speak to Akama inside the hidden chamber in the Warden's Cage.", description = "You've proven what side you're on.  I will reveal to you our leader's hideout.\n\nFollow the halls beyond; there will be an underground passage hidden by stagnant water on your right.\n\nI must warn you, <name>.  You are not to speak to anyone of what you see there.", progress = nil, completion = "Hail, &lt;name&gt;.  There is much we need to talk about.\n\nI hope your mind is an open one.  The decisions I make are not understood by many.  Only my closest collaborators have understanding of the portents I see and the signs I await.\n\nWhen I joined forces with Illidan it was based on visions foretelling that otherwise my race would have been destroyed.  I've waited patiently for other signs and visions to come to pass... Velen's exodus... the opening of the Dark Portal... and now... your arrival.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10629] = {title = "Shizz Work", objective = "Use the Felhound Whistle to summon a Fel Guard Hound. Take the Fel Guard Hound for a walk and kill some Deranged Helboars. Search for the Shredder Keys in the Fel Guard Hound's \"leavings.\"  Return the Shredder Keys to Foreman Razelcraz by the mine northwest of Thrallmar.", description = "I finally got my shredder working but I seem to have lost the keys.  I keep a pack of felhounds to protect my camp.  They don't do a very good job and they like to bite me a lot.  They also like shiny things.  I think this one felhound I have may have eaten my shredder keys.  I'll pay you if you'll take my felhound on a walk.  Kill some helboars and let him eat.  He'll do his business.  When he's done, see if you can't find the keys in his \"leavings.\"", progress = "Did you manage to find my keys?  I'm sure one of my felhounds ate them.  It's probably the one I sent with you.  Probably.", completion = "You smell terrible.  But you found my keys!  Thank you so much.  Now I can get my shredder started and make some money.  Pretty soon I will have enough money to leave Outland.  I don't know why you stay; I hate this place.  Wouldn't you rather be back in Booty Bay?  \n\nMaybe do some fishing?", rewards = "You will receive:\n\nEz-Thro Dynamite II"}
MultiLanguageQuestData['en'][10630] = {title = "Beneath Thrallmar", objective = "Kill Urga'zz and return to Foreman Razelcraz by the mine northwest of Thrallmar.", description = "I'm almost back in business.  Problem is all these gan'arg are in my mine.  I can't send my peons in and even once I fix this shredder I wouldn't want to risk it in combat. Deep down in the mine the gan'arg have a leader.  If you kill him maybe the gan'arg will leave.  Then I could make some money and buy my way out of here.", progress = "Is he dead yet?  I'm too scared to look.", completion = "All those gan'arg are sure to clear out now.  I'll be back in Booty Bay within a week.  I can't wait to go fishing again.  Coming to Outland was a mistake.  If you'll take my advice, you'll head back the way you came.  Spend some time in Stranglethorn, or maybe, if you feel adventurous, head to Un'Goro Crater.  Just don't stay here.", rewards = "You will be able to choose one of these rewards:\n\nUnderworld HelmShatterstone PickDeep Core Lantern\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10631] = {title = "Back In Business", objective = "Get some ore.", description = "Take my shredder.  Go into the mine and get some ore.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10632] = {title = "Cutting Your Teeth", objective = "Razak Ironsides has asked you to gather up 5 Extra Sharp Daggermaw Teeth. Return them to him at Toshley's Station in the Blade's Edge Mountains.", description = "It's nice that you've been helping out Toshley and his scientists.  I, however, do not have the luxury of indulging in my 'personal' interests.\n\nIf you want to make a difference around here, you'll do what I ask of you, and right now, I need weapons.\n\nOur guns are effective at range, but when the bugs get in close, we need to have powerful melee weapons as a backup.\n\nThe teeth of the daggermaw lashtails in the northern part of the Razor Ridge make for great vibro-weapon blades.  Scare me up some.", progress = "How's that collection of teeth coming along?\n\nI'm sure that you're going to do a fine job of getting them for us.  While you're doing that, we'll just hold down the outpost here.", completion = "Good work, kid.  All of the pain is worth it if even one of my soldiers' lives is saved by your efforts.\n\nI think you should benefit from your sweat and tears, too.  Since we're going to have a new batch of weapons soon, why don't you take one of mine?", rewards = "You will be able to choose one of these rewards:\n\nVibro ShankerVibro DaggerVibro Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10633] = {title = "Teron Gorefiend - Lore and Legend", objective = "Chief Apothecary Hildagard at Shadowmoon Village in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.\n\nIf you lose your Spectrecles, Chief Apothecary Hildagard can make you a new pair.\n\nProvided item: \n", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the southeast, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", progress = nil, completion = "Gorefiend? Why, I have not heard that name in ages!\n\nAfter the Second War, Gorefiend returned here, along with his death knights. Unable to cope with the terrible nature of his new form and without the support of his beloved leader, Gul'dan, Gorefiend killed himself.\n\nIf he walks these lands now as a spirit, it is news to me. Yet, perhaps I can divine such knowledge with your assistance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10634] = {title = "Divination: Gorefiend's Armor", objective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Armor.", description = "In life, Gorefiend was a bastard, but in death, Gorefiend was an unmitigated terror.\n\nTo the southeast you will find Netherwing Ledge. What was once part of the mainland of Shadowmoon is now a floating island in the sky.\n\nVhel'kur, spawn of Deathwing, once called it his home, but now knows it as his grave. He flies an endless circle above the island, seething at his defeat to Gorefiend.\n\nIf you are to recover the Gorefiend's armor, it is Vhel'kur that you must defeat.", progress = "Fly to Netherwing Ledge to recover the piece.", completion = "I must have all of the pieces before I am able to divine the fate of Gorefiend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10635] = {title = "Divination: Gorefiend's Cloak", objective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Cloak.", description = "Many a cruel act he committed but none so cold as the slaughter of the clerics of Karabor.\n\nAfter Gul'dan's Horde defeated the draenei of Karabor, the surviving clerics of Karabor were marched out, told that they were to be taken to Hellfire Citadel as prisoners of war.\n\nGorefiend, not yet a death knight, murdered each and every last one of them in cold blood. They now roam in front of the Black Temple with vengeance in their hearts.\n\nIt is the clerics of Karabor that hold the cloak of Gorefiend.", progress = "You must use the Spectrecles if you wish to see the spirits of Shadowmoon.", completion = "When I have all three of the pieces in my possession, I will be able to divine the whereabouts of Gorefiend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10636] = {title = "Divination: Gorefiend's Truncheon", objective = "The Ancient Shadowmoon Spirit at the Altar of Shadows in southeast Shadowmoon Valley wants you to recover Gorefiend's Truncheon.", description = "One by one they knelt before him, offering their lives as a show of allegiance. Gorefiend hoisted his sickle and cut clean their heads. Shortly after this slaughter, Gorefiend took his own life.\n\nBut this was no act of contrition! No, Gorefiend sought immortality! From the corpses of the fallen death knights rose the Ghostriders of Karabor.\n\nThey now ride the roads encircling the Hand of Guldan, awaiting the day that their master returns. It is they who hold the truncheon of Gorefiend. Retrieve it...", progress = "You must use the Spectrecles if you wish to see the spirits of Shadowmoon.", completion = "Only with all three united may I divine the secrets you so desperately seek!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10637] = {title = "A Necessary Distraction", objective = "Exarch Onaala wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, <name>, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", progress = "Have you completed the task I asked of you?", completion = "Let us hope that distraction bought us the time we need to fully learn what we need of the training grounds at Karabor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10638] = {title = "NOT A QUEST", objective = "Seek <NAME> in the <DISTRICT> of Silvermoon City.Seek your trainer in Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Seek your trainer in Silvermoon City.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10639] = {title = "Teron Gorefiend, I am...", objective = "\nThe Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.\n\nIf you succeed, return to Chief Apothecary Hildagard at Shadowmoon Village.", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", progress = nil, completion = "You did what? FOOL!\n\nYou must right this wrong. After all, it is your fault. Take one of these helmets. They are each infused with the ever-burning ash that you retrieved for me. More importantly, they will allow you to see the ghosts of Shadowmoon, including Teron Gorefiend.\n\nShould you ever find Teron Gorefiend, destroy him.", rewards = "You will be able to choose one of these rewards:\n\nEvoker's Helmet of Second SightOverlord's Helmet of Second SightStalker's Helmet of Second SightShamanistic Helmet of Second SightStealther's Helmet of Second SightDruidic Helmet of Second Sight"}
MultiLanguageQuestData['en'][10640] = {title = "Altruis", objective = "Travel to western Nagrand and find Altruis the Sufferer.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "It is rare in this day and age to hear of those who follow the path of the demon hunter.  It is rarer still to find someone who does and has no allegiance to Illidan.\n\nThere are rumors of one such individual here in Outland.  One name is said to be feared in the Legion fields of Nagrand more than any army of Aldor vindicators.  That name is Altruis.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", progress = nil, completion = "You've come a long way, stranger.  I'm surprised whoever sent you has heard of me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10641] = {title = "Against the Legion", objective = "Altruis the Sufferer wants you to obtain Freshly Drawn Blood from a Wrath Priestess at Forge Base: Gehenna in Netherstorm. Spill it on the ground and slay the Avatar of Sathal. Return to Altruis when you've completed this task.", description = "The Burning Legion has proven its capacity to corrupt mortal souls time and again.  If I'm to entrust you with the knowledge you seek, I must have proof of your allegiance.\n\nA demoness known as Sathal has eluded me for a long time as she's gifted with an incorporeal form.\n\nShe watches over the wrath priestesses as they do her bidding at Forge Base: Gehenna.  Slay one of her minions and spill her blood on the ground.  This affront should cause Sathal to materialize temporarily.  Slay her while you can.", progress = "Have you slain the demoness?", completion = "You've proven you're not tainted by the Legion's touch and the enemy of my enemy is my friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10642] = {title = "A Ghost in the Machine", objective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to bring him 15 Ever-burning Ash samples.", description = "I fear that these dwarves do not understand what they have built upon. This area was once the ancestral grounds for the Shadowmoon orcs. I speak of spirits, <race>.\n\nFor nearly twenty years they have laid dormant beneath the Wildhammer Stronghold, but recently, something has riled them up.\n\nVenture beyond the gates of Wildhammer and seek out the pools and rivers of fel lava found across this land. Near the lava will be ever-burning ash. Bring me this ash so that I may craft something that will help us.", progress = "Aye, a duality exists... I can feel it.", completion = "&lt;Zorus begins to craft something out of the ash samples.&gt;\n\nIt is done. Behold, Spectrecles!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10643] = {title = "Harbingers of Shadowmoon", objective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to slay 12 Shadowmoon Harbingers.", description = "Let it be known that Zorus does have a sense of humor.\n\nEnough small talk. Don the Spectrecles so that you are able to see the Shadowmoon orc spirits that wander this stronghold. Do not be frightened as we are truly the invaders here. Alas, they must be destroyed, for their time has long since passed.\n\nDestroy the Shadowmoon harbingers infesting Wildhammer Stronghold and return to me.", progress = "If you lose your goggles, let me know and I will craft another pair.", completion = "You claim to have heard the ghosts whisper to you? And they mentioned Teron Gorefiend?\n\n&lt;Zorus shudders.&gt;\n\nYes... I know Teron Gorefiend. Rather, I knew of him. He has long been thought dead. What could these ghosts be speaking of?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10644] = {title = "Teron Gorefiend - Lore and Legend", objective = "Zorus the Judicator at Wildhammer Stronghold in Shadowmoon Valley wants you to find the Ancient Shadowmoon Spirit.\n\nIf you lose your Spectrecles, Zorus the Judicator can make you a new pair.\n\nProvided item: \n", description = "Stories abound about the life of Teron Gorefiend, but most are just that - stories. We do not know what happened to Gorefiend after he returned to Draenor.\n\nThe only thing we are certain of is that he has already died once.\n\nI have heard the scouts here speaking of an ancient orc spirit that resides at the Altar of Shadows, far to the east, across the Netherwing Fields and through Netherwing Pass. Take the Spectrecles and track this orc down. He will surely have more information on Gorefiend.", progress = nil, completion = "Gorefiend? Why, I have not heard that name in ages!\n\nAfter the Second War, Gorefiend returned here, along with his death knights. Unable to cope with the terrible nature of his new form and without the support of his beloved leader, Gul'dan, Gorefiend killed himself.\n\nIf he walks these lands now as a spirit, it is news to me. Yet, perhaps I can divine such knowledge with your assistance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10645] = {title = "Teron Gorefiend, I am...", objective = "\nThe Ancient Shadowmoon Spirit has used you as a pawn! Now that you have collected the items he required, he has revealed himself to be Teron Gorefiend. To break free of his possession, you must do his bidding and slay Karsius the Ancient Watcher.\n\nIf you succeed, return to Zorus the Judicator at Wildhammer Stronghold.", description = "With Gorefiend's items restored, there is but one last piece to this puzzle: A host.\n\n<The ancient shadowmoon spirit's lips curl up  to form a wicked grin.>\n\nSurely you did not believe the fairy tale that I told you. The Altar of Shadows is my prison. Without your help, I would have been stuck here for all eternity. Now, I will take over your body and you will destroy my captors and break these bonds. Refuse and we will both be stuck here forever.\n\nTeron Gorefiend will be free!", progress = nil, completion = "You did what? FOOL!\n\nYou must right this wrong. After all, it is your fault. Take one of these helmets. They are each infused with the ever-burning ash that you retrieved for me. More importantly, they will allow you to see the ghosts of Shadowmoon, including Teron Gorefiend.\n\nShould you ever find Teron Gorefiend, destroy him.", rewards = "You will be able to choose one of these rewards:\n\nEvoker's Helmet of Second SightOverlord's Helmet of Second SightStalker's Helmet of Second SightShamanistic Helmet of Second SightStealther's Helmet of Second SightDruidic Helmet of Second Sight"}
MultiLanguageQuestData['en'][10646] = {title = "Illidan's Pupil", objective = "Listen to Altruis's story.", description = "You've proven your allegiance, <name>.  You must forgive my caution, but in this world things are not what they appear.\n\nI will tell you about Varedis when you're ready.", progress = "Varedis is powerful, yes.  There is a way he can be defeated, however.", completion = "You know the story now.  Only one thing remains to be done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10647] = {title = "Wanted: Uvuros, Scourge of Shadowmoon", objective = "Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Sardon Truslice at Shadowmoon Village in Shadowmoon Valley.", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Overlord Or'barokh, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Sardon Truslice should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - east of Shadowmoon Village.", progress = "Here ta collect a reward, mon?", completion = "Quite da haul you got der, mon. Well done! An' ya be getting' yer reward. Don't ya worry!", rewards = "You will be able to choose one of these rewards:\n\nUvuros Hide BootsUvuros Hide CinchUvuros Hide GlovesUvuros Plated Spaulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10648] = {title = "Wanted: Uvuros, Scourge of Shadowmoon", objective = "Slay Uvuros and recover Uvuros's Fiery Mane. Return it to Warcaller Beersnout at Wildhammer Stronghold in Shadowmoon Valley.", description = "Wanted - DEAD:\n\nUvuros, scourge of Shadowmoon Valley.\n\nBy order of Thane Yoregar, the fel beast, Uvuros, is to be killed on sight and his mane stripped from his carcass as proof of deed. Return the fiery mane of the beast to Warcaller Beersnout should you succeed.\n\nUvuros was last seen at the Hand of Gul'dan, located in the heart of Shadowmoon Valley - northeast of Wildhammer Stronghold.", progress = "I hope you've done somethin' special, lad. Otherwise, buzz off!", completion = "Yep, here's your reward. Don't go spendin' it all in once place.", rewards = "You will be able to choose one of these rewards:\n\nUvuros Hide BootsUvuros Hide CinchUvuros Hide GlovesUvuros Plated Spaulders\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10649] = {title = "The Book of Fel Names", objective = "Venture inside the Shadow Labyrinth in Auchindoun and obtain the Book of Fel Names from Blackheart the Inciter. Return to Altruis in Nagrand once you've completed this task.", description = "I sympathize with your intentions of stopping Varedis and his followers, but you won't stand a chance against him.  That is, unless you find the artifact that gave him his power.\n\nThe Book of Fel Names is rumored to be in the possession of Blackheart the Inciter inside the Shadow Labyrinth in Auchindoun.  Obtaining it will be your only hope against Varedis.", progress = "Have you obtained the book, <name>?", completion = "I was able to sense the book's power from yards away.  The temptation to keep it is... very strong.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10650] = {title = "Return to the Aldor", objective = "Speak with Exarch Onaala at the Altar of Sha'tar in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, <name>.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", progress = nil, completion = "You bring this abomination of a book to this holy site?  You'd better have a very good explanation, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10651] = {title = "Varedis Must Be Stopped", objective = "Exarch Onaala wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis. Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him. Return to Exarch Onaala with the Book of Fel Names after you've completed this task.\n\nCompleting quests for the Aldor will cause your Scryers reputation to decrease.", description = "We must dispose of this foul artifact, but not before we use it to dispose of Varedis's powers.\n\nWe need to permanently shut down the Ruins of Karabor training grounds, which will mean killing not only Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  For all of our sakes, I hope they work.", progress = "Have you completed what I asked of you, <name>?", completion = "Excellent work, &lt;name&gt;!  Your victory over Varedis will have a tremendous impact on our war against Illidan.\n\nYou've proven yourself not just to the Aldor but to all of Outland.  Allow me to destroy what remains of that horrible book.", rewards = "You will be able to choose one of these rewards:\n\nCeremonial KrisHauberk of KaraborSlayer's AxeSummoner's BladeSunfury LegguardsWildcaller\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10652] = {title = "Behind Enemy Lines", objective = "Speak to Veronia when you're ready to depart to Manaforge Coruu. Once there, speak to Caledis Brightdawn.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "All arrangements have been made to take you to where our spies are hiding.  Just come see me when you're ready and we'll get you on your way.", progress = nil, completion = "Welcome, &lt;class&gt;.  Try not to give our position away.\n\nWe wouldn't last long if Kael's cronies sniff us out.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10653] = {title = "Marks of Sargeras", objective = "Bring 10 Marks of Sargeras to Adyen the Lightwarden in Shattrath City.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  The highest-ranking Legion can be found in Netherstorm and Shadowmoon Valley.", progress = "Do you bear any of our enemies' insignias, <name>?", completion = "Facing the demons of the Burning Legion and the mad cultists that worship them is no small feat, &lt;name&gt;.  You've shown great dedication and courage.  Keep it up and your renown among the Aldor will continue to grow.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10654] = {title = "More Marks of Sargeras", objective = "Do you bear more of our enemies' insignias, <class>?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", description = nil, progress = "Do you bear more of our enemies' insignias, <class>?  The Burning Legion continues to be a threat and we continue to pursue them anywhere that we find them.", completion = "You continue to prove your worth, &lt;name&gt;.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded.", rewards = nil}
MultiLanguageQuestData['en'][10655] = {title = "Single Mark of Sargeras", objective = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", description = nil, progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, &lt;name&gt;.  Fight the enemies of the Light wherever you may find them; your actions will be well-rewarded.", rewards = nil}
MultiLanguageQuestData['en'][10656] = {title = "Sunfury Signets", objective = "Magistrix Fyalenn in Shattrath City wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", description = "As you might know, the Scryers and the armies of Kael'thas are at war.  Kael sees us as a threat to his influence over other blood elves and has tried to crush us time and again.\n\nIf you wish to aid us in our battle against Kael'thas, there are plenty of targets for you to go after.  Kael's highest ranking soldiers wear Sunfury signets to mark their ranks.  You will find them all over Netherstorm and Shadowmoon Valley.", progress = "Go on, <name>.  Speak.", completion = "Kael's Sunfury army is extremely well-trained.  Very impressive job, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10657] = {title = "Ride the Lightning", objective = "Toshley wants you to use the Repolarized Magneto Sphere to absorb 25 lightning strikes from the Scalewing Serpents. As well, collect 5 Scalewing Lightning Glands. Then, deliver them back to him at Toshley's Station in the Blade's Edge Mountains.", description = "We haven't kept the use of the Zephyrium Capacitorium under budget.  But, it occurs to me that the serpents of the Scalewing Shelf to the east have a lightning breath and glands that we can make use of.\n\nI've repolarized the magneto collector to absorb lightning strikes and I want you to head up there, activate it on yourself, and get us some cheap fuel from those serpents.", progress = "The trick to using the repolarized magneto sphere is to know when to turn it off before you end up getting truly fried.\n\nOf course, you need to balance that against how many of those flying serpents you want to have to face.\n\nSpeaking of which, have you managed to charge up the sphere?", completion = "Woo hoo, it worked!  To be honest I wasn't sure... I calculated a twenty-three point seven two chance that you'd implode by the third strike.\n\n&lt;Toshley grins innocently.&gt;\n\nSo, now we know that the sphere works, we should have no problem meeting our energy needs for the Zephyrium Capacitorium.  Well, that is if we can find more volunteers to go out there and get zapped.\n\nStill, you've pioneered our efforts and deserve something in return!", rewards = "You will be able to choose one of these rewards:\n\nEnergized WristwrapsCharged FootwearScalewing GlovesMuscle Toning Belt\n\nYou will also receive:\n\nPure Energy"}
MultiLanguageQuestData['en'][10658] = {title = "More Sunfury Signets", objective = "What have you done for us lately, <name>?  The war against Kael'thas is not going to fight itself, you know?", description = nil, progress = "What have you done for us lately, <name>?  The war against Kael'thas is not going to fight itself, you know?", completion = "Excellent!  That'll show Kael'thas not to underestimate our power.", rewards = nil}
MultiLanguageQuestData['en'][10659] = {title = "Single Sunfury Signet", objective = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", description = nil, progress = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", completion = "Kael's army will soon fall.", rewards = nil}
MultiLanguageQuestData['en'][10660] = {title = "What Strange Creatures...", objective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to recover 8 Felfire Spleens.", description = "I am interested in learning more about the strange reptiles that mill about the lava flows of Shadowmoon Valley. Never have I seen beasts able to withstand the searing heat of molten lava!\n\nOutside of Shadowmoon Village, where the ground has ruptured and lava flows through the cracks, you will find felfire diemetradons. Slay them and bring me their spleens. From their spleens I will be able to begin preliminary analysis of their resistance to heat.\n\nBegin your search to the southeast.", progress = "Spleens! I need spleens!", completion = "&lt;Researcher Tiorus takes the spleens and starts his examination.&gt;\n\nThis may take a while. Take these coins for your hard work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10661] = {title = "Spleendid!", objective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 8 Felfire Spleens.", description = "Have you ever heard of food that cooks itself and stays hot forever? Dare to dream, I say!\n\nBut maybe it's not a dream at all! Outside the fortress, near the lava pools and streams, you can find beasts that thrive in the sizzling heat. They're called felfire diemetradons.\n\nThe dwarves around here tell me that those diemetradons have the tastiest spleens ever and that the spleens practically come pre-cooked! Bring me those spleens and I'll give you some coin.\n\nStart your search directly east of here.", progress = "Spleens! I need spleens!", completion = "&lt;Gnomus hungrily grabs at the spleens.&gt;\n\nHere's your coin as promised. I'll call for you if I need more spleens.\n\nSo delicious... I dare say that they are 'spleendid!'", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10662] = {title = "The Hermit Smith", objective = "Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest.", description = "<Ordinn examines the results from his attempt at smithing the metal and shakes his head.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated for your use.\n\nThere was a talented smith who accompanied the Sons of Lothar to Draenor, David Wayne. He was a remarkable blacksmith, but chose to leave the expedition. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you with the weapon.", progress = "What brings you here, <class>? I don't get many visitors.", completion = "Ordinn sent you with these?\n\n&lt;The smith examines the ingots.&gt;\n\nHe was right. Most of the magic is gone, but I can still sense traces of it. With some work and a few 'exotic' resources, I can forge you a powerful anti-demon sword from this metal.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10663] = {title = "The Hermit Smith", objective = "Bring the Box of Ingots to David Wayne at Wayne's Refuge in Terokkar Forest.", description = "<The orc shakes his head at his failure.>\n\nThis is beyond my ability, but that's not to say the weapon can't be recreated.\n\nIt pains me to suggest this, but your only hope may be a human smith by the name of David Wayne. It's true he was once a member of the Alliance's expedition, but that was a long time ago and he has since left the Sons of Lothar. These days, he lives in a small camp on a peninsula east of Firewing Point in Terokkar Forest. Take the ingots to him and see if he can help you.", progress = "What brings you here, <class>? I don't get many visitors.", completion = "&lt;The smith frowns and examines the ingots.&gt;\n\nI'll be frank with you, &lt;class&gt;. I'm a relic of an age when cooperation with the Horde was unthinkable.\n\nI am not so blind as to see that we do not have common enemies. I will help you to reforge the anti-demon weapon but it's going to take a lot of hard work and a few 'exotic' resources.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10664] = {title = "Additional Materials", objective = "David Wayne at Wayne's Refuge wants you to bring him an Adamantite Frame, 4 Heavy Knothide Leather, and a Demon Warding Totem.", description = "The ingots that you brought contain most of the metal I'll need to forge the sword's blade, but I'll need a variety of things to create other parts of the weapon.\n\nLet's see, among the things I don't have here are an adamantite frame, some heavy knothide leather, and a demon warding totem. Skilled crafters should be able to produce the first two, but the third is only sold by the reagent vendor in Shattrath's Lower City, Fantei. You'll find him with the other tradesmen.", progress = "Did you get those materials?", completion = "&lt;The smith accepts the materials, nodding approvingly.&gt;\n\nThese will suffice. The remainder of the materials I'll need won't be quite so easy to come by.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10665] = {title = "Fresh from the Mechanar", objective = "David Wayne at Wayne's Retreat wants you to bring him an Overcharged Manacell.", description = "Working with the ingots you brought is going to require a lot of heat -- rather more than a conventional forge can supply.\n\nI'm going to need a supplemental heat source for the forge and there are very few things in Outland that can supply that kind of power.\n\nThe Mechanar area of Tempest Keep turns out manacells containing an incredible amount of power. Find one of the overcharged manacells from the stacks around Mechano-Lord Capacitus and bring it back here.", progress = "Were you able to smuggle a manacell out of the Mechanar.", completion = "This is even more potent than I expected! With this much power, I could forge a dozen blades!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10666] = {title = "The Lexicon Demonica", objective = "Obtain the Lexicon Demonica from Grandmaster Vorpil and bring it to David Wayne at Wayne's Refuge.", description = "Recreating the enchantments on the blade requires several spells to be spoken in demonic.\n\nIt's not something I was taught during my training as an apprentice, but there's no way around it. There's a book, called the Lexicon Demonica, that will provide most of the words I need, but it's in the hands of a powerful Shadow Council warlock.\n\nDeep in the halls of Auchindoun's Shadow Labyrinth, it is held by Grandmaster Vorpil. Do whatever you must to secure the book and bring it to me.", progress = "Have you retrieved the book?", completion = "&lt;David leafs through the book's pages, shuddering.&gt;\n\nThis is not something to be trifled with, &lt;name&gt;. After the weapon is created, I will destroy it. There is enough demonic power about in the world without this text out in the open.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10667] = {title = "Underworld Loam", objective = "Get a Vial of Underworld Loam from Hydromancer Thespia and bring it to David Wayne at Wayne's Refuge.", description = "The frame that you brought me earlier will not be sufficient to hold molten metal without reinforcement. A rare kind of earth can be used to cool and imbue the frame, giving the adamantite an unnatural strength.\n\nUnderwold loam, as the earth is known, is accorded great value among the naga. Few enough of them possess it, and in Outland, I know of only one naga who uses it -- Hydromancer Thespia, who resides in the Steamvault of Coilfang Reservoir.", progress = "Have you secured the underworld loam?", completion = "This should do the trick. I'd hoped for a bit more, but to be honest, we were lucky to get our hands on any at all out here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10668] = {title = "Against the Illidari", objective = "Altruis the Sufferer wants you to slay Lothros at Illidari Point in Shadowmoon Valley.", description = "I still have respect for Illidan.  Without him I would not have found my path.\n\nHe is not who he once was, however.  His soul has been corrupted by power, his mind has been twisted by defeat.  He has become what I am sworn to destroy and his pet servants, the Illidari, are as much of an abomination as any demon of the Burning Legion.\n\nHis grasp on Outland is slipping yet his reach is still vast.  Prove you're not with him by slaying his lieutenant Lothros at Illidari Point in Shadowmoon Valley.", progress = nil, completion = "So you're not with Illidan.  You're one step closer to gaining my full trust.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10669] = {title = "Against All Odds", objective = "Altruis the Sufferer wants you to take the Imbued Silver Spear and use it at Portal Clearing near Marshlight Lake in Zangarmarsh to awake Xeleth. Return to Altruis after you've slain the demon.", description = "Some demons pledge allegiance to no one but themselves.  A true enemy of demons finds and destroys his prey regardless of affiliation, however.\n\nThe demon Xeleth - a Legion defector - was once worshipped as a god by primitive swamp creatures in Zangarmarsh.  When Draenor was nearly destroyed, he retreated into a slumber deep beneath Marshlight Lake.  Find the portal at the lake and plant this spear into the ground.\n\nXeleth will awake - be ready to slay him and prove you're an enemy to all demons.", progress = "You've returned.  Has Xeleth been slain?", completion = "Well done, &lt;name&gt;.  He still remembered the day I drove this spear into him?  That was so long ago...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10670] = {title = "Tear of the Earthmother", objective = "Recover the Tear of the Earthmother from Warbringer O'mrogg and return it to David Wayne at Wayne's Refuge.", description = "The sword's enchantments must be contained within a powerful focus, such as a gem. I know of a gem that we can use for this purpose, for there are few that can play host to such powerful magics without shattering.\n\nThe gem we need is called the tear of the earthmother. It's a powerful artifact in the hands of the ogres who created it, and Warbringer O'mrogg, who currently holds the gem, has many powerful allies in Hellfire Citadel's Shattered Halls. Take care in retrieving the tear, <name>.", progress = "Were you able to wrest the gem from the grip of O'mrogg?", completion = "&lt;David Wayne holds the gem up, to the light, admiring it.&gt;\n\nIt's aboslutely flawless, and that's exactly what we'll need. A flawed gem would endanger the weapon's wielder, twisting the magic against them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10671] = {title = "More than a Pound of Flesh", objective = "Dizzy Dina has asked you to acquire 5 Ether-Energized Flesh and return them to her at Toshley's Station in the Blade's Edge Mountains.", description = "<name>, I've got something else for you to do.  One of the eggheads wants to study the fiendling flesh beasts that can be found at Razaan's Landing, north of the Razor Ridge.\n\nMore to the point, they want to study the flesh of the flesh beasts that are there.\n\n<Dizzy makes a disgusted face.>\n\nBut, of course, they aren't willing to get their hands dirty, and they only want the ether-energized flesh, which it's not likely that all of them have.\n\nI say, beggars can't be choosers, but what can you do?", progress = "You have my pound of flesh?  What, you didn't think that was funny?", completion = "These ought to do nicely.  Don't they stink, though?\n\nI hope that this is worth your troubles... I'm just glad that it was you collecting this stuff instead of me!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10672] = {title = "Frankly, It Makes No Sense...", objective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to travel to the lava flow near the Ruins of Baa'ri and use the Arcano Control Unit to control an Arcano-Scorp, swim in the lava with the Arcano-Scorp, and tag 8 Greater Felfire Diemetradons.", description = "We must study these creatures further.\n\nFar to the east - near the huge lava flow beneath the ruins of Baa'ri - you will find arcano control units. These controllers were crafted by a genius named Gnomus for the sole purpose of exploring lava via mechanical scorpion.\n\nHe has long since lost his mind and is now only interested in eating the hottest food known to gnome-kind.\n\n<Tiorus gives you a funny look.>\n\nI want you to use the control and tag the diemetradons of the lava flow for further study.", progress = nil, completion = "Listen, there is no time to spare. I've been watching the tagged diemetradons and have discovered that they all report to a gigantic, nay, ENORMOUS, diemetradon named Felspine the Greater.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10673] = {title = "Felspine the Greater", objective = "Researcher Tiorus at Shadowmoon Village in Shadowmoon Valley wants you to kill Felspine the Greater and recover Felspine's Hide.", description = "Gnomus knows about the massive diemetradon and plans to eat it! He must have been able to see what I could see through the eyes of his arcano-scorp. Look, there's no time to explain. He's crazy and that craziness is going to cost us the closest thing we've got to a fireproof jumpsuit.\n\nGet back to the lava flow near Baa'ri and track down Felspine the Greater. Once you find it, kill it and bring me back its hide.\n\nDon't try and reason with me, <name>. I'm well past that point.", progress = "Snap to it! That gnome's appetite knows no limit!", completion = "At last! Total protection against lava is mine! Of course you get a cut of this technology too, &lt;name&gt;. You've earned it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10674] = {title = "Trapping the Light Fantastic", objective = "Toshley would like you to use the Light Trap to catch 15 Razaani Light Orbs. Return to him at Toshley's Station in the Blade's Edge Mountains after you have done so.", description = "The Razaani ethereals have been playing with some interesting technology at Razaan's Landing to the north.\n\nI'm sure they won't mind if you use this trap to take a few samples of their little pink floating light orbs?  They're probably only for decoration anyway.\n\nThe trap has a special property to it that when opened should attract one of the floating balls towards it.  Of course, it'll probably also alert the Razaani to your presence.", progress = "I take it that since we're speaking, you have the light orbs from the Razaan's Landing?  It'll be interesting to take a look at them and see what the ethereal are up to.", completion = "Hey!  Wait just one damned minute!!\n\nThis doesn't look good...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10675] = {title = "Show Them Gnome Mercy!", objective = "Toshley wants you to retrieve the Collection of Souls and return it to him at Toshley's Station in the Blade's Edge Mountains.", description = "<The blood drains out of Toshley's face.>\n\nThese orbs are made up of both nether energy and souls, some of them gnome souls!\n\nHow dare they!  Were they the ones killing our people that traveled north?!\n\n<name>, you must put a stop to this, and the only way to do that is to finish off their leader, Nexus-Prince Razaan.\n\nYou'll have to coax him out of hiding though.  I'm guessing that you can do that by killing a lot of his Razaani ethereal.\n\nBring me the collection of souls that he no doubt has.", progress = "Have you dealt with that soul-stealing bastard, Razaan yet?", completion = "Good riddance to him!  Thank you for putting an end to their macabre twisting of magic and technology.\n\nAs a true hero of gnomes everywhere, I hereby bequeath unto you our highest honor... some power converters and your pick of any of these.\n\nI know that you'll put them to good use!", rewards = "You will be able to choose one of these rewards:\n\nGnomish Casting BootsToshley's Station Hero's HatRazaani-Buster LeggingsSoul Saver's Chest Plate\n\nYou will also receive:\n\nPower Converter"}
MultiLanguageQuestData['en'][10676] = {title = "Bane of the Illidari", objective = "Wait for David Wayne to finish forging a sword for you.", description = "<David gathers his smithing supplies.>\n\nYou've done well in getting everything we'll need to reforge the anti-demon blade. Your hard work and dedication is about to be repaid.\n\nThe time has come to forge the sword.", progress = nil, completion = "&lt;David mops sweat from his brow.&gt;\n\nThe bulk of the work is done, but to set the magics, the blade must now be quenched.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10677] = {title = "The Second Course...", objective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover 1 Overdeveloped Felfire Gizzard.", description = "I remember seeing larger diemetradons east of the Hand of Gul'dan, near the lava flows around the Ruins of Baa'ri. What I want you to get for me now is one overdeveloped felfire gizzard from the beasts around that area. You might have to kill several to find a gizzard like the one I described. Keep at it! One of them is bound to have my next meal.", progress = "Special of the day: Gizzard.", completion = "This is fantastic but I just received some incredible news!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10678] = {title = "The Main Course!", objective = "Gnomus at Wildhammer Stronghold in Shadowmoon Valley wants you to recover Felspine's Hide.", description = "Long story short, I used to work with a blood elf named Tiorus. My partnership with Tiorus dissolved once I got into gourmet living. He decided to take it upon himself to continue our research using MY inventions. Anyhow, he had some of his Horde goons using my arcano-scorp probes at the Ruins of Baa'ri lava flow and discovered the mother of all diemetradons!\n\nI need you to get there before he does and kill the diemetradon, Felspine, and bring his hide back to me.\n\nHurry up!", progress = "Special of the day: Felspine's hide.", completion = "I'll need some alone time now, &lt;name&gt;. Thanks for all the help!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10679] = {title = "Quenching the Blade", objective = "Travel to the Scalding Pools located near the top of the Hand of Gul'dan and use the Forged Illidari-Bane Blade to quench it in the lava pools. Once you have the Quenched Illidari-Bane Blade, return to David Wayne at Wayne's Refuge.", description = "The blade is nearly finished!\n\nYou can almost feel the magic beginning to coalesce inside the steel, but one thing remains to be done.\n\nYou must take the forged blade to the Scalding Pools near the top of the Hand of Gul'dan in Shadowmoon Valley and plunge it into the lava pools to quench the sword. When you have quenched the sword, return.", progress = "Have you quenched the sword in the lava of the Hand of Gul'dan?", completion = "Well done!\n\n&lt;The smith examines the blade closely.&gt;\n\nI'd say it's a fair improvement over the crude Legion weapons you started with. Not only will this blade cut down Illidari demons, but it will work against the Legion's minions as well.", rewards = "You will be able to choose one of these rewards:\n\nIllidari-Bane BroadswordIllidari-Bane ClaymoreIllidari-Bane MagebladeIllidari-Bane Dagger\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10680] = {title = "The Hand of Gul'dan", objective = "Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley.", description = "The elements need your help, <race>! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nDirectly northeast of Wildhammer Stronghold you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", progress = nil, completion = "It is good that you came, &lt;race&gt;. We have much work to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10681] = {title = "The Hand of Gul'dan", objective = "Speak with Earthmender Torlok at the Altar of Damnation in Shadowmoon Valley.", description = "The elements need your help, <race>! Shadowmoon Valley has been subject to unspeakable evils. The spirits remain tortured to this day. Many are enraged and unwilling to commune with the Earthen Ring.\n\nHelp this world heal, friend.\n\nSoutheast of Shadowmoon Village - in the heart of Shadowmoon Valley - you will find an area known as the Altar of Damnation. Make your way there and speak with Earthmender Torlok.", progress = nil, completion = "It is good that you came, &lt;race&gt;. We have much work to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10682] = {title = "A Time for Negotiation...", objective = "Tree Warden Chawn has asked you to negotiate with Overseer Nuaar. Return to the tree warden at Evergrove in the Blade's Edge Mountains afterward.", description = "When we arrived in the Ruuan Weald, the wyrm cultists were keeping themselves to Blackwing Coven, through the tunnel to the west.  But now, they are encroaching upon us here.\n\nI need you to find the wyrmcultists' overseer.  He's known to make a regular patrol between their various camps in the Ruuan Weald.\n\nNegotiate with him.  Let him know that there's room for compromise, but that we will not condone or allow the wholesale slaughter of the wildlife, nor the felling of all of the trees.", progress = "Is everything okay?", completion = "WHAT?!  They dismissed you and our proposals out of hand?\n\nThis is outrageous!  We go to them in good faith, and they turn you away without even trying to come to a compromise?\n\nWell, we'll see about that!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10683] = {title = "Tablets of Baa'ri", objective = "Arcanist Thelis at the Sanctum of the Stars wants you to collect 12 Baa'ri Tablets from the ground and from Ashtongue Workers at the Ruins of Baa'ri.\n\nCompleting quests with the Scryers will cause your Aldor reputation level to decrease.", description = "The Ashtongue Broken have been ordered by Illidan to excavate the Ruins of Baa'ri, to the far north.  They're in search of draenei artifacts, no doubt - Baa'ri was home to many Baa'ri relics before Gul'dan buried the town under a volcanic explosion.  We must use this opportunity to recover the Tablets of Baa'ri, an ancient text rumored to hold the secrets of the Temple of Karabor... a place you might know as the Black Temple.", progress = "Have you found the tablets yet, <name>?", completion = "The Baa'ri tablets!  Yes, this might provide us with very useful information.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10684] = {title = "Oronu the Elder", objective = "Arcanist Thelis at the Sanctum of the Stars wants you to obtain the Orders from Akama from Oronu the Elder at the Ruins of Baa'ri.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "According to the tablets, an artifact known as a Medallion of Karabor was kept at Baa'ri.  Only the highest-ranking draenei priests were granted these, as they allowed unfettered access into the Temple of Karabor.\n\nWe must find out whether the Ashtongue have recovered the medallion that was kept at Baa'ri yet.  Its power would provide great aid in our fight against Illidan.\n\nAkama's lieutenant at Baa'ri, Oronu the Elder, receives written orders from him daily.  Obtain them and bring them to me.", progress = "Any news yet, <name>?  Time is not on our side.", completion = "It matches Akama's handwriting... let us see what we can learn.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10685] = {title = "The Ashtongue Corruptors", objective = "Obtain the four medallion fragments from Haalum, Eykenen, Lakaan and Uylaru and return to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.\n\nPerforming quests for the Scryers will cause your Aldor reputation level to decrease.", description = "According to Akama's letter, four fragments of the medallion were unearthed and given to the Ashtongue Corruptors.  These dreaded Broken were once powerful shaman who now defile the very elements they revered.\n\nHaalum, Corruptor of Air, can be found at Netherwing Pass.  Eykenen and Uylaru, Corruptors of Earth and Fire, were last seen at the Fel Pits near the Hand of Gul'dan.  Lakaan, Corruptor of Water, is rumored to be near Coilskar Point.\n\nFind them and obtain the medallion fragments.", progress = "Have you obtained the four medallion fragments, <name>?", completion = "Yes!  The four fragments of the medallion.  Now to put them together...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10686] = {title = "The Warden's Cage", objective = "Arcanist Thelis wants you to enter the Warden's Cage, south of the Ruins of Baa'ri and interrogate Sanoru on Akama's whereabouts.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", description = "The fragments you obtained are only half of the medallion.  The Ashtongue leader, Akama, must have kept the other half.\n\nI dread to ask this of you, as Akama is both evil and cunning.\n\nHe and the Ashtongue Deathsworn - the vilest and most brutal of the tribe - are rumored to run a torture chamber inside the Warden's Cage.\n\nI want you to find that dreaded prison,  and find the whereabouts of Akama.  His second in command at the location is a Broken known as Sanoru - interrogate him if you have to.", progress = nil, completion = "We've been expecting you, &lt;name&gt;.  Akama said you would arrive sooner or later.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10687] = {title = "Karabor Training Grounds", objective = "Larissa Sunstrike at the Sanctum of the Stars wants you to obtain 8 Sunfury Glaives from the Demon Hunter Supplicants and Demon Hunter Initiates at the Ruins of Karabor, northeast of the Sanctum of the Stars.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "Our scouts have reported a massive influx of Sunfury blood elf recruits heading to the Ruins of Karabor.  Normally this would represent a purely military threat, however we believe something else is amiss.\n\nDescriptions of their attire and fighting style are suspiciously close to that of Illidan himself.  I do not want to become alarmed without good reason, so I would like you to go there and bring me back their weapons.  We will then determine whether my fears are unfounded or not.", progress = "Have you completed the task I asked of you, <name>?", completion = "Let's take a closer look at these weapons, &lt;name&gt;.  Hmmm... this is rather unsettling.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10688] = {title = "A Necessary Distraction", objective = "Larissa Sunstrike wants you to return to the Ruins of Karabor and find a way to unleash Azaloth on his captors.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "The weapons are authentic, as we feared.  Illidan is training demon hunters at the Ruins of Karabor and we must put an end to it.\n\nDo not be fooled by their name, <name>, their power will be used against us as often as against any demon.\n\nTheir warlocks summon and subdue demons to be used as part of the initiates' training.  A pit lord named Azaloth has proven too strong to be used in training and is kept banished.  Find a way to let him loose on his captors.  That should buy us the time we need.", progress = nil, completion = "That should buy us some time... hopefully it will be enough for us to obtain more information.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10689] = {title = "Altruis", objective = "Travel to western Nagrand and find Altruis the Sufferer.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "You don't see many demon hunters nowawdays.  They're viewed with suspicion by their own people and it's very rare to find one that doesn't have some sort of allegiance to Illidan.\n\nThere are rumors of one such demon hunter out in Nagrand.  His name is Altruis.  He hates all demons with a passion and will help us if you can convince him that you share his goals.\n\nGo to western Nagrand and find him.  He might be willing to shed some light on these new demon hunter training grounds.", progress = nil, completion = "You've come a long way, stranger.  I'm surprised whoever sent you has heard of me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10690] = {title = "The Den Mother", objective = "Kill Rema and then inform Commander Skyshadow at Sylvanaar in the Blade's Edge Mountains.", description = "WANTED!\n\nRema, the den mother and primary defender of the Jagged Ridge south of Thunderlord Stronghold.\n\nFind her by heading east out of town and across the bridge that traverses the Bloodmaul Ravine.  She keeps herself secluded in the tunnel at the southern edge of the ridge.\n\nReturn with news of her demise to Commander Skyshadow of Sylvanaar.", progress = "What can I do for you today?", completion = "Unbelievable.  Did you slay Rema all by yourself?\n\nBy the looks of you, I'd say that you could.  You know, we're looking for a young, strong &lt;class&gt;, such as yourself, to help out around here, especially with the problems we continually have with the ogres.  Make sure that you follow-up with me on that possibility.\n\nWell, you've definitely earned the bounty that I put on that wanted poster.\n\nPlease, take your pick.", rewards = "You will be able to choose one of these rewards:\n\nWolf Hewer's AxeHeavy Elven DirkArcane Wand of Sylvanaar\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10691] = {title = "Return to the Scryers", objective = "\nSpeak with Larissa Sunstrike at the Sanctum of the Stars in Shadowmoon Valley.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "This book... I could use it to increase my power tenfold...  No!  It would end up corrupting my very soul, this I am sure of.  Return to those who sent you here, <name>.\n\nYou now have the means to stop Varedis.  Wait until he manifests his demonic form through metamorphosis, at that point you will need to burn the book in his presence.  That will be the only way you can deprive him of his power.", progress = nil, completion = "Many would pay a great price for the book you carry with you.  It is a shame we'll have to destroy it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10692] = {title = "Varedis Must Be Stopped", objective = "Larissa Sunstrike wants you to go to the ruins of Karabor and slay Alandien, Theras, Netharel and Varedis. Use the Book of Fel Names when Varedis uses Metamorphosis to weaken him. Return to Larissa Sunstrike with the Book of Fel Names after completing this task.\n\nCompleting quests for the Scryers will cause your Aldor reputation to decrease.", description = "Of course we must destroy this book, but not before we use it to destroy Varedis.\n\nIf we're to shut down this academy of Illidan imitators, we'll have to deal not just with Varedis but also the three night elf masters that assist him: Alandien, Theras and Netharel.\n\nGather a suitable force and return to the Ruins of Karabor.  Follow Altruis's instructions for defeating Varedis.  Hopefully his plan will work - otherwise... it'll have been a pleasure working with you.", progress = "Have you completed what I asked of you, <name>?", completion = "You've done well, &lt;name&gt;.  By slaying Varedis you've put an end to one of Illidan's most dangerous projects.\n\nYour name will definitely get around after this.\n\nAllow me to take what remains of the Book of Fel Names.  I will make sure it's properly... disposed of.", rewards = "You will be able to choose one of these rewards:\n\nCeremonial KrisHauberk of KaraborSlayer's AxeSummoner's BladeSunfury LegguardsWildcaller\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10693] = {title = "One Commendation Signet", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
