MultiLanguageQuestData['en'][10732] = {title = "Path of the Violet Protector", objective = "Are you certain of your choice, <name>?  This is not a decision you ought to take lightly.\n\nThe Violet Signet will grow in power as you continue to prove yourself to the Violet Eye.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10733] = {title = "Down the Violet Path", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;.  Behold as I unleash the power contained in your signet!", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10734] = {title = "Down the Violet Path", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;.  Behold as I unleash the power contained in your signet!", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10735] = {title = "Down the Violet Path", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;.  Behold as I unleash the power contained in your signet!", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10736] = {title = "Down the Violet Path", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Honored reputation with the Violet Eye.", description = "You've chosen your path, <class>.  Now it is up to you to travel the path to wherever it may lead.\n\nYou will find that having friends among the Archmages of Dalaran has its advantages.  Serve us well and your deeds will not go unrewarded.", progress = "It is good to see you again, <name>.", completion = "You honor us with your service, &lt;name&gt;.  Behold as I unleash the power contained in your signet!", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10737] = {title = "The Master's Touch", objective = "Go into the Caverns of Time and convince Medivh to enable your Restored Apprentice's Key.", description = "I've put together the very key I used as an apprentice.  It looks completely functional as far as keys go.  In regards to opening Karazhan, however, this might as well be a piece of scrap metal.\n\nWithout Medivh's consent, the key is worthless.  Yes, of course I know Medivh is dead.  This merely makes things difficult, not impossible\n\nThere is a place in Azeroth called the Caverns of Time, guarded by the bronze dragonflight.  Find a way inside, travel back in time and get Medivh to enable the key.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10738] = {title = "Distinguished Service", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, &lt;name&gt;.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10739] = {title = "Distinguished Service", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, &lt;name&gt;.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10740] = {title = "Distinguished Service", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, &lt;name&gt;.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10741] = {title = "Distinguished Service", objective = "Bring your Violet Signet to Archmage Leryda at Deadwind Pass after obtaining Revered reputation with the Violet Eye.", description = "You have not disappointed us, <name>.  We continue to have very high hopes for you, however.\n\nContinue to serve the Violet Eye and you will be appropriately rewarded.", progress = "You're welcome among us, as always.  What brings you to us?", completion = "Your services have not gone unnoticed, &lt;name&gt;.  Your signet may look the same, but its powers grow as you continue to prove your loyalty.", rewards = "You will receive:\n\nViolet Signet"}
MultiLanguageQuestData['en'][10742] = {title = "Showdown", objective = "Use Rexxar's Battle Horn at the Altar of Goc, then kill Goc. Return to Rexxar at Thunderlord Village in the Blade's Edge Mountains when this is done.", description = "Now it comes to this. We will bring Goc forth from his lair, and we will destroy him. With Goc dead, the Bladespire ogres will threaten the Mok'Nathal no longer. Go to Goc's altar outside Gruul's Lair, then blow my horn. I will come, and we will face the son of Gruul together.", progress = "Only through the deaths of Goc and Gorgrom the Dragon-Eater will we free the Mok'Nathal.", completion = "The battle was hard and you fought well, &lt;name&gt;. I am honored to have stood by your side in the battle against Goc. I am thankful beyond words.\n\nThe Mok'Nathal should know of these great defeats, but I am not ready to face them yet. I know my father's mind, and I know my heart. There is still much I can learn and do to become stronger, to show to him that I am his true son.", rewards = "You will be able to choose one of these rewards:\n\nTourmaline CrownClefthoof Hide LeggingsOilcloth BreechesMalefactor's EyepatchLeonine BreastplateBlackened Chestplate\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10743] = {title = "txt>Hero of the Mok'Nathal", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10744] = {title = "News of Victory", objective = "Return to Wildhammer Stronghold and speak with Kurdran Wildhammer.", description = "You must bring word of our success to Kurdran Wildhammer immediately! His men, under Wing Commander Nuainn, have fought nonstop to keep Wildhammer Stronghold safe and your return will surely bolster their spirits. With the threat from the Legion out of the way, Kurdran can finally turn his attention to dealing with the forces of Illidan. Our place here is far from secure, but we've won a major victory this day.", progress = nil, completion = "&lt;Kurdran listens to your report.&gt;\n\nThat is good news, indeed! Mere days ago, I wouldn't have dreamt that we could break the Legion's siege on the stronghold.\n\nNot only have you halted their offensive, but you've broken the back of their war machine as well! You have the gratitude of the Wildhammer clan for your valor, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nBand of AnguishGloves of the High MagusIdol of the AvengerLibram of Righteous PowerStormfury Totem\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10745] = {title = "News of Victory", objective = "Return to Shadowmoon Village and speak with Overlord Or'barokh.", description = "You must bring word of our success to Overlord Or'barokh immediately! Now that we've crushed the Legion and obliterated their presence in Shadowmoon Valley, the overlord can turn his attention to our other foes.\n\nAlthough the Kor'kron guard will never admit it, they'll be glad we're no longer fighting on two fronts.", progress = nil, completion = "&lt;The overlord listens to your report.&gt;\n\nExcellent news! Holding the line against the Legion's infernals was taking too many resources. Not that I expected my men to break, but they were greatly strained.\n\nYou have proven your worth to the Horde this day. The Kor'kron guard would be honored to fight by your side anytime.", rewards = "You will be able to choose one of these rewards:\n\nBand of AnguishGloves of the High MagusIdol of the AvengerLibram of Righteous PowerStormfury Totem\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10746] = {title = "DEPRECATED Karazhan: LAB - E - Exalted Ring - Caster", objective = "Bring your Band of Eternity to Soridormi at the Caverns of Time after obtaining Exalted reputation with the Scale of the Sands.", description = "Your accomplishments have gone beyond my greatest expectations, <name>.\n\nYou step in and out of time as comfortably as any bronze dragon I've known.  You are destined for great power and I am more than pleased to help you on your way there.\n\nContinue to serve the Scale of the Sands and I will unleash your gift's full potential.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBand of the Eternal Sage"}
MultiLanguageQuestData['en'][10747] = {title = "Whelps of the Wyrmcult", objective = "Samia Inkling has asked you to use the Blackwhelp Net to capture 10 Wyrmcult Blackwhelps. Return them to her at Evergrove in the Blade's Edge Mountains.", description = "I need to examine the whelps that they are raising at the Blackwing Coven.\n\nThere should be an abundance of them flying around inside their cavernous base, as well as a number of eggs, which if you get close to them will likely hatch.\n\nPlease, <name>, take the net and capture a handful of them alive for me.\n\nFind them by heading west across the Wyrmskull Bridge and heading through the Wyrmskull Tunnel.  Follow the path to its end past Grishnath and the Raven's Wood.", progress = "Did you run into much trouble snatching the whelps?  I hope you didn't get singed!", completion = "Oh my goodness, these are more than I'd hoped for!  You are certainly to be lauded for your heroics!\n\nThis looks like a fine brood of blackwhelps to make a start with.  Examining them, that is.\n\nPlease, accept this as payment.  I insist!", rewards = "You will be able to choose one of these rewards:\n\nWyrmcultist's HoodBlackwhelp BeltWhelpscale GauntletsInkling's Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10748] = {title = "Maxnar Must Die!", objective = "On behalf of the Cenarion Expedition druids of Evergrove, and the indigenous life of the Ruuan Weald, Tree Warden Chawn has asked you to slay Maxnar the Ashmaw. Return to him at Evergrove in the Blade's Edge Mountains after you have done so.", description = "They've left us no choice, <name>.  It's time to put an end to the threat from the Blackwing Coven by taking out their leader, Maxnar the Ashmaw.\n\nI don't know if you caught a glimpse of him while you were in there, but he's one of the dragonkin, half-man, half-dragon.  And he's tough, so don't underestimate him!\n\nFinish it quickly and with any luck you'll secure the safety of Evergrove and the Ruuan Weald.", progress = "You've dealt with Maxnar the Ashmaw already?\n\nAre you having trouble finding him?  As I understand it if you head to the right once you enter their caverns, it will eventually curve around and lead you to him.", completion = "Now we can breathe more easily knowing that the leader of our enemy has been dealt with.  Not only that, but you've saved the entire mountain range from their depredations.\n\nWhatever their ultimate goals, you've foiled them!\n\nYou have our gratitude, &lt;name&gt;.  Please accept this token of our esteem, as well as our unending hospitality.", rewards = "You will be able to choose one of these rewards:\n\nCoven BritchesChest of the WyrmcultDragonkin ShirtBlackwing Helm\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10749] = {title = "Baron Sablemane's Poison", objective = "Deliver Baron Sablemane's Poison to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "Here, take this to your master. I'm sure that whatever the reason, Rexxar will put it to good use.\n\nOh, and do be certain to remind him that he owes me.\n\nHe knows what I want, and I'm certain that however he intends to obtain it for me, I'll be seeing you again sooner than you think.\n\nNow, do be a good little <boy/girl> and run this up to Rexxar.", progress = "<class>, you are back so soon? Do you have the poison?", completion = "This is unsavory business, this use of poisons. But it will do what we want.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10750] = {title = "The Path of Conquest", objective = "Travel to the Path of Conquest in Shadowmoon Valley. Once you have done a preliminary assessment of the area, use the Kor'kron Flare Gun to signal a Kor'kron Wind Rider.\n\nSpeak with Overlord Or'barokh should you lose your Kor'kron Flare Gun and require a replacement.", description = "Word has come from my wind riders, <name>. The Eclipsion blood elves are planning something big. They have begun forming their armies at the Path of Conquest, far to the southeast - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you have done so, use this flare gun to signal a wind rider. One will swoop down from the sky to meet you. Inform them of what you have discovered and they will give you your next set of orders.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10751] = {title = "Breaching the Path", objective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 10 Eclipsion Spellbinders and then use the Kor'kron Flare Gun to signal another Kor'kron Wind Rider to report your task complete.\n\nSpeak with Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley should you lose your Kor'kron Flare Gun and require a replacement.", description = "We're going to need more time, <race>. I'm going to fly further ahead with some of the other wind riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a wind rider with the Kor'kron flare gun once you have thinned their numbers.", progress = "What have you to report, soldier?", completion = "You won't believe this, grunt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10752] = {title = "Onward to Ashenvale", objective = "Speak with Raene Wolfrunner in Astranaar.", description = "Recently Raene Wolfrunner came through Auberdine from Darnassus and was heading to Ashenvale; she said something about the Furbolgs. I wasn't given an opportunity to ask more about her situation but perhaps you can seek her out and lend her your aid <class>. Take the southern road out of Auberdine. Once you reach Ashenvale border continue your path down the road. There you will find Astranaar and Raene Wolfrunner.", progress = nil, completion = "So Thundris Windweaver still thinks I need looking after? I'll need to remind him who saved whom; he seems to forget it was I that pulled him from harm's way.\n\nWell now that you're here, &lt;race&gt;, perhaps I can find something for you to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10753] = {title = "Culling the Wild", objective = "Kill 4 Felsworn Scalewing, 4 Felsworn Daggermaw, and 2 Fel Corrupters.", description = "The number of atrocities committed by the Burning Legion is countless. Even as we speak, they send their legion forces against the creatures of this land. Helpless to defend against their power, they fall one by one. <name>, help me stop these crimes of nature destroy all which they corrupt. \n\nOver the hill, east of here, you will see the corruption spreading across Bladed Gulch. Kill the ones causing the crime, the Fel Corrupters, and as many Felsworn as you can.", progress = nil, completion = "I do not pride myself knowing we destroyed what Elune has created, but the corruption needed to be stopped. You have done well &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10754] = {title = "Entry Into the Citadel", objective = "\nBring the Primed Key Mold to Force Commander Danath at Honor Hold in Hellfire Peninsula.", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Danath, the force commander at Honor Hold.", progress = "You've something to show me, <name>?", completion = "Could this be?  Let me take a closer look at that mold.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10755] = {title = "Entry Into the Citadel", objective = "\nBring the Primed Key Mold to Nazgrel at Thrallmar in Hellfire Peninsula.", description = "This freshly cast mold was to be used to create a key of some sort.  From the image engraved on its back, it appears to be related to Hellfire Citadel.\n\nMaybe this could prove to interest to Nazgrel, the leader of the Horde's forces in Thrallmar.", progress = "You've something to show me, <name>?", completion = "A key mold?  Could this be what grants us access to the Shattered Halls?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10756] = {title = "Grand Master Rohok", objective = "Bring the Primed Key Mold to Rohok in Thrallmar.", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it as the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Rohok, our resident blacksmith.  If anyone can forge this key it is he.", progress = "What is this?", completion = "Nazgrel wants me to work on a key?  Does he forget we're in a battlefield?  There are blades and spears to forge!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10757] = {title = "Rohok's Request", objective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Rohok at Thrallmar in Hellfire Peninsula.", description = "Fel orc blacksmiths may not be the most skilled in the world, but there is some craftsmanship to their trade.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", progress = "Have you obtained the materials I requested?", completion = "Excellent.  Let's give it a shot.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10758] = {title = "Hotter than Hell", objective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Rohok in Thrallmar.", description = "It's no good, <name>!  No matter how many coals I put to the fire, it's just not enough heat.\n\nThere's only one thing I can think of that is hot enough to temper this key and it is the insides of the Legion's fel reavers.\n\nI've only ever seen one downed once.  I remember seeing its insides fuming, shooting fire and steam as it fell.  Take this mold and plunge it into a fallen fel reaver.  I recommend you get yourself some friends if you plan to take one down.", progress = "Did you do what I asked of you, <class>?", completion = "You've succeeded!  Only thing left for you to do is try it out.", rewards = "You will receive:\n\nShattered Halls Key"}
MultiLanguageQuestData['en'][10759] = {title = "Find the Deserter", objective = "Locate Parshah in the Magma Fields and speak to him.", description = "I get the feeling that all the pieces are here, but I just can't put them together in a way that makes sense.\n\nI think our best lead is to attempt to locate this deserter. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him along the road in Magma Fields to the northwest. It seems a likely place for him to take refuge.", progress = nil, completion = "&lt;The arakkoa cackles.&gt;\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10760] = {title = "The Sketh'lon Wreckage", objective = "Recover the Skethlon Commander's Journal Page 1, Skethlon Commander's Journal Page 2, and Skethlon Commander's Journal Page 3 from the Dark Conclave arakkoa at the Sketh'lon Wreckage to Sergeant Kargrul at Shadowmoon Village.", description = "The Sketh'lon Wreckage, just to the east, is an eerie place. The peons are convinced that it's cursed.\n\nThere are few trees here, so the peons have no choice but to venture into the arakkoa ruins to chop wood. The arakkoa spirits prey on the work groups, draining their life and using it to fuel their foul magics.\n\nWe must find out what is driving the dark conclave and stop them before their influence expands. Search the Sketh'lon Wreckage for evidence of their plans.", progress = "What have you discovered?", completion = "&lt;The sergeant examines the journal pages.&gt;\n\nI don't see much of use here, but there are a couple of entries that could prove useful. It looks as though these arakkoa were preparing some kind of elaborate magical ritual up until the time of their deaths, but why? There's also a curious note here about a 'deserter.'", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10761] = {title = "Find the Deserter", objective = "Locate Parshah in the Magma Fields and speak to him.", description = "There's nothing here that would explain why the spirits of these arakkoa have remained in this world or how they came into thirst for the blood of orcs.\n\nI think our best lead is to try to find the deserter mentioned in the journal. If he left his comrades at the camp, there's a chance you might be able to persuade him to help us understand what the dark conclave arakkoa are planning.\n\nStart your search for him on the road through the Magma Fields to the southeast.", progress = nil, completion = "&lt;The arakkoa cackles.&gt;\n\nYes, I am the deserter mentioned in the commander's journal. I have been waiting for the day when others might recognize the threat posed by those I once called brothers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10762] = {title = "Grand Master Dumphry", objective = "Bring the Primed Key Mold to Dumphry in Honor Hold.", description = "The symbol on the key's handle... it is hard to make it out inside the mold, but I recognize it at the Shattered Hand's own.\n\nThere is a good chance this key will allow you to enter the Shattered Halls.\n\nSpeak to Dumphry.  He is a master of his craft.  If he can't craft this key for you, no one can.", progress = "What is this?", completion = "A key?  Danath should have us working on siege engines!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10763] = {title = "Dumphry's Request", objective = "Bring 4 Fel Iron Bars, 2 Arcane Dust and 4 Motes of Fire to Dumphry at Honor Hold in Hellfire Peninsula.", description = "Fel orcs might be complete barbarians but their smithing is not as primitive as you might think.  Only fel iron can be used with this mold if we want to end up with a working key - anything else would probably end up breaking it.\n\nBring me some fel iron bars, a bit of arcane dust and motes of fire.  I'll try my hand at it, but I make no promises.", progress = "Have you obtained the materials I requested?", completion = "Let's try it then.  Let's see what fel orc crafting is all about.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10764] = {title = "Hotter than Hell", objective = "Destroy a Fel Reaver in Hellfire Peninsula and plunge the Unfired Key Mold into its remains. Bring the Charred Key Mold to Dumphry in Honor Hold.", description = "It's not working, <lad/lass>.  I cannot give it enough heat... the materials will not be properly tempered.\n\nYou know, the Fel Reavers used by the Burning Legion are powered by a scalding core of fel fire - it burns much hotter than normal fire.\n\nIf you could find enough people to take one down, you could heat the mold in the insides of the fallen reaver.  Beware, <class>, those fel reavers pack quite a punch.", progress = "Did you do what I asked of you, <class>?", completion = "You've done it, laddie!  Only thing left to do is for you to take it to Hellfire Citadel and kill yourself some orcs!", rewards = "You will receive:\n\nShattered Halls Key"}
MultiLanguageQuestData['en'][10765] = {title = "When Worlds Collide...", objective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command. Use the Kor'kron Flare Gun to signal another Kor'kron Wind Rider once you have accomplished this task.\n\nSpeak with Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley should you lose your Kor'kron Flare Gun and require a replacement.", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. You've probably already noticed the smaller giants on the path as well. Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that promises to sever this unholy union.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10766] = {title = "Invasion Point: Cataclysm", objective = "Report to Plexi at Invasion Point: Cataclysm.", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Wildhammer Stronghold won't be safe until the Legion's presence is erased from Shadowmoon Valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Plexi will meet you at your destination.", progress = nil, completion = "Pleased to meet you, &lt;name&gt;. Name's Plexi.\n\nI won't bore you with formalities. We both know why we're here. Now, let's get to work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10767] = {title = "Invasion Point: Cataclysm", objective = "Report to Nakansi at Invasion Point: Cataclysm.", description = "Now that we have access to the Legion's base at Invasion Point: Cataclysm, we need to figure out a way to shut down their operations there. Shadowmoon Village won't be safe until the Legion's presence is erased from the valley.\n\nI've sent an advance party up to the invasion point to help you formulate a plan to destroy the Legion's supplies. Go back to Legion Hold and step into the teleporter with the green crystals above it. Nakansi will meet you at your destination.", progress = nil, completion = "You must be the &lt;race&gt; Blood Guard Gulmok told me to expect. I have a plan in mind, but I'll need your help to complete the preparations.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10768] = {title = "Tabards of the Illidari", objective = "Collect 10 Illidari Tabards and then use the Kor'kron Flare Gun to signal another Kor'kron Wind Rider.\n\nSpeak with Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley should you lose your Kor'kron Flare Gun and require a replacement.", description = "The wind riders must return to Shadowmoon Village to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a wind rider using the Kor'kron flare gun. Prepare yourself for a bit of espionage, <race>!", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10769] = {title = "Dissension Amongst the Ranks...", objective = "\nSlay 5 Crazed Colossus while in disguise as an Illidari blood elf and return to Overlord Or'barokh at Shadowmoon Village in Shadowmoon Valley. He will also want his Kor'kron Flare Gun returned.", description = "Researcher Tiorus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", progress = "You have returned!", completion = "Well, well, well... If it isn't the grunt I sent out into the field. You're back and in one piece.\n\n&lt;Or'barokh nods.&gt;\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", rewards = "You will be able to choose one of these rewards:\n\nEvoker's Mark of the RedemptionSlayer's Mark of the RedemptionSpellsword's Mark of the RedemptionProtector's Mark of the Redemption\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10770] = {title = "Little Embers", objective = "Mosswood the Ancient wants you to kill 8 Scorch Imps and then return to him in Ruuan Weald.", description = "Northeast of here, on the plateau above us lies the burnt ashes of my ancient home. A great wood flourished there before the Burning Legion sent their imps to burn us away. So many died that even centuries later my tired old heart hungers for revenge. There are too many of them for us to ever reclaim the land, but you could make them afraid.\n\nSurely you will help me?", progress = "Soon I will sleep the deep sleep of the forest. Before I dig my roots deep and close these old eyes forever, I hope to know that those wretched imps suffered and perished.", completion = "There are so many that we could never kill them all, but you have given me hope. Perhaps I shall try harder for the next few centuries to revive my beloved wood.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10771] = {title = "From the Ashes", objective = "Mosswood the Ancient wants you to journey to Skald and plant Ironroot Seeds in three different mounds of Fertile Volcanic Soil and then return to him in Ruuan Weald.", description = "If you follow the road east and up the side of the mountain, then turn north, you will come to my long lost home.\n\nOnce there was a wood there. Its name is forgotten. Long ago the Burning Legion summoned scorched imps and other creatures of flame. My home was destroyed and my people fled. Now only I remain. \n\nI have saved some ironroot seeds that could be planted in fertile volcanic soil. Their magic is strong. Do this for me and I will share with you the treasures of a forgotten age.", progress = "Is it done?  Did you return some life to my ancient home?", completion = "You destroyed many of those foul little creatures.  I can rest easier in that knowledge.", rewards = "You will be able to choose one of these rewards:\n\nWild Wood StaffScorch Wood BowIron Oak Shield\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10772] = {title = "The Path of Conquest", objective = "Travel to the Path of Conquest in Shadowmoon Valley. Once you have done a preliminary assessment of the area, use the Wildhammer Flare Gun to signal a Wildhammer Gryphon Rider.\n\nSpeak with Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley should you lose your Wildhammer Flare Gun and require a replacement.", description = "My gryphon riders have come back with a bit of news! The Eclipsion blood elves are planning something big. They've begun forming their armies at the Path of Conquest, located east of here - adjacent to Eclipse Point.\n\nI want you to travel to the Path of Conquest and assess the situation. Once you've done so, use this flare gun to signal a gryphon rider. One will swoop down from the sky to meet you. Tell 'em what you've discovered and they'll give you the next set of orders.", progress = "What have you to report, soldier?", completion = "Indeed, these troublesome whelps are up to something insidious. We must investigate further...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10773] = {title = "Breaching the Path", objective = "Slay 20 Eclipsion Soldiers, 10 Eclipsion Cavaliers, and 5 Sons of Corok and then use the Wildhammer Flare Gun to signal another Wildhammer Gryphon Rider to report your task complete.\n\nSpeak with Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley should you lose your Wildhammer Flare Gun and require a replacement.", description = "We're going to need more time, <race>. I'm going to fly further ahead with some of the other gryphon riders. Hopefully, we can gather some more information. What I need from you now is to clear a path and more importantly, keep their arrows pointed away from us!\n\nCall for a gryphon rider with the Wildhammer flare gun once you have thinned their numbers.", progress = "What have you to report, soldier?", completion = "You won't believe this, soldier!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10774] = {title = "Blood Elf + Giant = ???", objective = "Slay Chancellor Bloodleaf and Corok the Mighty and recover Illidan's Command. Use the Wildhammer Flare Gun to signal another Wildhammer Gryphon Rider once you have accomplished this task.\n\nSpeak with Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley should you lose your Wildhammer Flare Gun and require a replacement.", description = "At the southern end of the Path of Conquest, near a stationary caravan, I discovered what looked like a meeting between a giant and a blood elf chancellor. What are giants even doing here? Something is just not right about all of this, grunt.\n\nI want you to fight your way to this meeting and break up the party. Recover whatever you can from the scene and then call for one of us with the flare gun.", progress = "What have you to report, soldier?", completion = "So they are attempting to gain the favor of the giants, eh? I have a plan that could serve to sever this unholy union.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10775] = {title = "Tabards of the Illidari", objective = "Collect 10 Illidari Tabards and then use the Wildhammer Flare Gun to signal another Wildhammer Gryphon Rider.\n\nSpeak with Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley should you lose your Wildhammer Flare Gun and require a replacement.", description = "The gryphon riders must return to Wildhammer Stronghold to prepare for the next phase of our assault. What I need from you now are the tabards that these blood elves wear.\n\nWhen you have collected enough tabards, call for a gryphon rider using the Wildhammer flare gun. Prepare yourself for a bit of espionage, <race>!", progress = "What have you to report, soldier?", completion = "Ah-ha! These will do quite nicely.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10776] = {title = "Dissension Amongst the Ranks...", objective = "\nSlay 5 Crazed Colossus while in disguise as an agent of Illidan and return to Thane Yoregar at Wildhammer Stronghold in Shadowmoon Valley. He will also want his Wildhammer Flare Gun returned.", description = "Gnomus was kind enough to put this concoction together for the final strike. I merely pour it upon this tabard that you have provided for me and the item is imbued with the essence of the Illidari filth.\n\nTake the enchanted tabard and travel to the Eclipsion Fields, southwest of Eclipse Point. Once there, use the tabard to transform into an agent of Illidan. While in disguise, slay the crazed colossi that wander the field. They will think it an attack by the Eclipsion and sever all ties!", progress = "You have returned!", completion = "Well, well, well... If it isn't the soldier I sent out into the field. You're back and in one piece.\n\n&lt;Yoregar nods.&gt;\n\nI knew you wouldn't let me down, soldier. You've stopped a major Illidari advance and, in doing so, earned yourself a little reward.", rewards = "You will be able to choose one of these rewards:\n\nEvoker's Mark of the RedemptionSlayer's Mark of the RedemptionSpellsword's Mark of the RedemptionProtector's Mark of the Redemption\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10777] = {title = "Asghar's Totem", objective = "Bring the Sketh'lon War Totem to Parshah in the Magma Fields.", description = "What you read in the commander's journal is true. While the orcish Horde massed under Gul'dan, my people sought to defend ourselves from the threat by striking against him. Gul'dan learned of their intentions and cast a mighty spell that destroyed our camps and twisted the spirits of my brothers.\n\nThey must be stopped before they unleash a greater evil. In the Sketh'lon Wreckage to the north, seek out Asghar and bring me the totem he carries. With it, we can begin to thwart the dark conclave's plans.", progress = "Have you recovered the totem from Asghar?", completion = "&lt;Parshah examines the totem.&gt;\n\nGood. This old totem hasn't lost its power over the years, but it alone is not enough to stop the dark conclave.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10778] = {title = "The Rod of Lianthe", objective = "Obtain Lianthe's Key from any of the blood elves at Eclipse Point and use it to open Lianthe's Strongbox and claim the Rod of Lianthe. Return the rod to Parshah in the Magma Fields.", description = "The totem alone is not strong enough to counteract the sinister magics of the dark conclave.\n\nWe can combine it with other objects of power, forming a staff to focus the energies. We cannot rescue my brethren from the depths of their depravity, but we can stop them.\n\nOne of the items I need for the staff is the Rod of Lianthe, held by the blood elves at Eclipse Point to the southeast. It is kept in a pavilion on the top tier of the ruins and will be heavily guarded. Use caution, <name>.", progress = "Did you manage to get the rod?", completion = "Well done. Such a treasure deserves better than to be shut away in a dark chest. We shall see it used for a worthy purpose.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10779] = {title = "The Hunter's Path", objective = "Speak with Huntress Kella Nightbow at LOCATION.Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Hello, young hunter. You look to me like you are skilled enough to handle a beast and train it as your companion.\n\nYou must see Huntress Kella Nightbow at LOCATION. She can put you on the path to earning a pet of your own.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10780] = {title = "Sketh'lon Feathers", objective = "Gather 8 Sketh'lon Feathers and bring them to Parshah in the Magma Fields.", description = "There is one last element missing from the staff. We must direct the staff's power toward the Dark Conclave spirits.\n\nWe can do that by gathering feathers scattered on the ground at the Sketh'lon Base Camp and using them in the staff. The base camp is to the south, east of Wildhammer Stronghold.\n\nGul'dan's magic utterly destroyed my brethren, leaving only their spirits, but it did not stop there. The magic fed on the spell the arakkoa were preparing, forging a sinister force that engulfed the spirits.", progress = "Have you gathered the feathers for the staff?", completion = "&lt;Parshah accepts the ash-dusted feathers, shaking his head.&gt;\n\nIt would've been better if they had died that day, but nothing is ever that simple. That Gul'dan's magic would turn them into the kind of threat they tried to stop is a particularly cruel twist of fate.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10781] = {title = "Battle of the Crimson Watch", objective = "Battle the forces of Illidan at Crimson Watch and survive!\n\nReturn to A'dal at Shattrath City should you emerge the victor.", description = "They are probably searching for you on the Path of Conquest as we speak. You must make your escape, <race>!\n\nLeave me, I'm done for... They... I think I hear them coming. It's now or never! Get out! If you choose to stay, you will have to fight!\n\nIf you fight and somehow manage to survive, take what you have learned here and deliver that knowledge to A'dal in Shattrath City.", progress = "<A'dal greets you.>", completion = "This Crimson Sigil will be investigated. They pose a threat to all life on Draenor. I foresee a day when their dark master has to answer for his crimes. Perhaps it will be you who brings him to justice, hero.", rewards = "You will be able to choose one of these rewards:\n\nAcrobat's Mark of the Sha'tarAggressor's Mark of the Sha'tarMage's Mark of the Sha'tarSpiritualist's Mark of the Sha'tar\n\nYou will also receive:\n\nOffering of the Sha'tar"}
MultiLanguageQuestData['en'][10782] = {title = "Imbuing the Headpiece", objective = "Equip the Unfinished Headpiece, travel to the Altar of Damnation, and use it while standing near Gul'dan. When the headpiece is energized, return to Parshah in the Magma Fields.", description = "The staff is nearly finished!\n\nAll that remains is to imbue the headpiece with power flowing from the echoes of Gul'dan in this accursed place. To the east, near the Fel Pits and south of the Deathforge, is the Altar of Damnation.\n\nThere, fragments of Gul'dan's past are trapped. When you carry the unfinished headpiece of the staff into the area around the altar, don't be surprised if some of the entities react to it. You will be carrying a dangerous object with strong connections to the cataclysm.", progress = "Have you returned with the imbued headpiece?", completion = "&lt;Parshah accepts the headpiece, handing it gingerly.&gt;\n\nThis holds the power that we'll need to disrupt the dark conclave's efforts in the Sketh'lon Base Camp.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10783] = {title = "Baron Sablemane", objective = "Speak with Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains.", description = "Here is my plan. We will poison the ogres and then destroy their gronn master.\n\nDuring my travels in these mountains, I met a man named Baron Sablemane. He is a master of the alchemical arts, and may be convinced to assist us.\n\nYou will find him at the Circle of Blood, down in the canyon to the north of here. Whatever price he requires, I will leave it to your discretion to accept.", progress = nil, completion = "Hello, &lt;race&gt;. I am Baron Sablemane. A friend of Rexxar's is a friend of mine.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10784] = {title = "Crush the Bloodmaul Camp", objective = "Tor'chunk Twoclaws has asked you to slay 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks. Afterward, return to him at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "<Tor'chunk leans in close to whisper.>\n\n<name>, you've done us more than proud in the fight against the ogres so far.  And while I have every confidence in what Rexxar has planned, I would still ask that you crush the ogres at Bloodmaul Camp before returning.\n\nThat way we'll be doubly certain of the outcome.\n\nTo get there, head north down the ramp out of Thunderlord.  Then, at the base of the ramp, head west across Dragons' End and north through the Churning Gulch and Daggermaw Canyon.", progress = nil, completion = "&lt;Tor'chunk nods his head in obvious approval of your killing prowess.&gt;\n\nYou continue to impress me, &lt;name&gt;.  Every time one of those stinking ogres is felled, we come one step closer to ridding ourselves of an unworthy foe.", rewards = "You will be able to choose one of these rewards:\n\nDarktread BootsTwin Moon ShoulderguardsChaintwine CinchFairweather's Wristguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10785] = {title = "It's a Trap!", objective = "Deliver the Dragonfire Trap to Rexxar at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "There's is no cause of fury greater in this world than that of Gruul and his sons. They slaughtered my people - my children - and now I will have revenge.\n\nI have fashioned a trap from dragon fire, and if you're clever enough, you can use it to kill even a gronn.\n\nJust hurry, take the trap to Rexxar. My thirst for revenge must be quenched.", progress = "Did you recover whatever was in that gronn's sack for Sablemane? What has he given us?", completion = "Hmm, a trap fashioned from the essence of dragon fire? I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter. What does matter is that we are going to use it to slay a son of Gruul.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10786] = {title = "Slaughter at Boulder'mok", objective = "Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Tor'chunk Twoclaws at Thunderlord Stronghold in the Blade's Edge Mountains.", description = "I know that Rexxar has plans for you to head to Boulder'mok.  I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies far to the northwest.  Travel north to Ruuan Weald, and from there head west through the tunnel and past the Raven's Wood.\n\n<name>, I want you to kill the Bladespire ogres of Boulder'mok.  Wipe them out!", progress = nil, completion = "&lt;Tor'chunk grins at the story that you tell him about your adventures at Boulder'mok.&gt;\n\nAh, I wish that I could have been there with you.  Let me tell you something, &lt;name&gt;: never accept any duty that keeps you from the glory of battle!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10788] = {title = "Return to Talionia", objective = "Speak with Talionia in Silvermoon City.", description = "One of your masters, Talionia, in Silvermoon City has sent a summons for you, <name>.  I'm certain it is time you learned to summon and control a more powerful demon, so I suggest you see her at once.  I understand Talionia is found in The Sanctum, a cozy little den of evil found along Murder Row.", progress = nil, completion = "So the world traveler returns...\n\nI hope my sarcasm is evident, &lt;name&gt;, for you have inconvenienced me greatly by forcing me to send out a summons.  Consider that you are but a felguard's hair away from incineration, and they don't have any hair.\n\nPay attention closely, this is not a lesson you'll get twice.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10789] = {title = "Return to Carendin Halgar", objective = "Speak with Carendin Halgar in Undercity.", description = "Ah, so there you are, <name>.\n\nCarendin Halgar has sent out word for you to come see him in the Magic Quarter of Undercity.  He is not known for his patience, so I would not wait long.", progress = nil, completion = "Yes, I can see it in your eye sockets.  You are eager to learn more.\n\nVery well, this is a lesson we'll both enjoy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10790] = {title = "Return to Gan'rul Bloodeye", objective = "Speak with Gan'rul Bloodeye in Orgrimmar.", description = "You are a long way from home, <race>.  Perhaps it is time you returned to learn from your master, Gan'rul Bloodeye.  His knowledge is known to all of our craft, even those of us here.\n\nGan'rul dwells in the Cleft of Shadow in Orgrimmar.", progress = nil, completion = "It is the forbidden knowledge you hunger for, is it?  I can give you that...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10791] = {title = "Welcoming the Wolf Spirit", objective = "Use the Ceremonial Incense near the candles in Malukaz's hut and observe the ceremony. When the ceremony is complete, speak with Malukaz again.", description = "I've nearly completed the vestments that I'll wear during the ceremony. As I add the finishing touches, I'd like you to set this incense by the candles near the runestone to my left.\n\nI believe it will help us to attract the wolf spirit's attention, since it was made in the days of the orcish clans. I can almost imagine my ancestors using it in a ceremony paying tribute to the wolf spirit after a successful hunt.\n\nOnce you've placed the incense, I'll begin the ceremony.", progress = "Reestablishing ties with the wolf spirit is just the beginning of my journey, not the end.", completion = "This is incredible! I set out on this journey unsure of whether the wolf spirit would answer our summons and now it feels as though he's always been here. Perhaps he was, &lt;name&gt;.\n\nPerhaps he was waiting for the orcs to realize what their choices had wrought.", rewards = "You will be able to choose one of these rewards:\n\nHelm of Lupine CunningHelm of Lupine FerocityHelm of Lupine GraceWolf Hunter's Guise\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10792] = {title = "Zeth'Gor Must Burn!", objective = "Kill Bleeding Hollow Peons for their torches, ignite them at Zeth'Gor's forge then throw the burning torches at Zeth'Gor Buildings.", description = "The Bleeding Hollow clan have betrayed their noble heritage!  We, the orcs who fought and died to save ourselves from the fel taint of Mannoroth, look upon our vile cousins and see only weakness and ignobility... and for that, they must burn!\n\nEnter Zeth'Gor, their bastion to the east, and burn their buildings.  Kill peons for their torches, ignite them at their forge, and hurl the burning torches at their hovels, their stable and their barracks.  Burn them all, and then return to me!\n\nFor the Horde!", progress = "Zeth'Gor must burn, <name>!  Speak with me again when your task is complete.", completion = "Hah!  I could see the smoke and flames of Zeth'Gor from here!  May the Bleeding Hollow fiends burn to ash and drift far from the sight of any true orc!\n\nThank you, &lt;name&gt;.  You helped burn away an afront to every orc's spirit.", rewards = "You will be able to choose one of these rewards:\n\nInfiltrator's CloakVindicator's Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10793] = {title = "The Journal of Val'zareq: Portends of War", objective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.\n\nLook for him inside a crystalline prison.", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.", progress = "<General Auralion is floating in the middle of the crystal.>\n\nWha... What are you doing here?", completion = "You slew their conqueror? Then we haven't much time...\n\nThe Crimson Sigil is a group comprised of Illidan's elite minions. They are at the top of the chain of command for all Illidari forces outside of the Black Temple. These soldiers communicate directly with the Betrayer here, carrying out his orders without question.\n\nThey are the fiends that will undoubtedly lead an assault on this world, trampling under foot all that would stand in their way.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10794] = {title = "Rogues of the Shattered Hand", objective = "Speak with Shenthul in Orgrimmar.", description = "<name>, there are secrets in the world that we do not yet possess.  The Shattered Hand in Orgrimmar can lead you to one of these secrets: the method for brewing deadly poisons.  Do as they ask and you will gain their trust.\n\nTo reach Orgrimmar, take the portal in Silvermoon City to Undercity.  Then, travel outside the city and find the nearby tower where the goblin Zepplins pick up their passengers.  From there, fly to the city of Orgrimmar where you can find Shenthul in the Cleft of Shadow.", progress = nil, completion = "So, you want to work for the Shattered Hand?  Seems like we're getting someone new every day.\n\nPay close attention and I'll explain what you have to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10795] = {title = "A Date with Dorgok", objective = "Commander Haephus Stonewall has asked you to kill Dorgok at Bloodmaul Camp. Return to him at Evergrove in the Blade's Edge Mountains after you have done the deed.", description = "Good, I've seen you around and I've been meaning to speak to you about a matter of some importance.\n\nThere are reports coming in that for some reason the Bloodmaul ogres are planning an offensive against Sylvanaar and Ruuan Weald.  We don't know who or what is pushing them to do this, but I intend to nip their plan in the bud!\n\nBloodmaul Camp is where the attacks are to be staged from.  Head northwest down the ramp out of the Ruuan Weald and you will find it.  I want you to kill their leader, Dorgok!", progress = nil, completion = "With Dorgok dead, the Bloodmaul ogres are without leadership, and should be in disarray until another leader arises from within their ranks.\n\nThank you, &lt;class&gt;, I think we can breathe a little easier now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10796] = {title = "Crush the Bloodmaul Camp!", objective = "Lieutenant Fairweather has tasked you with slaying 10 Bloodmaul Maulers and 5 Bloodmaul Warlocks. Afterward, return to her at Evergrove in the Blade's Edge Mountains.", description = "I've heard that you've done us more than proud in the fight against the ogres thus far.  Now, I would ask that you face them again.  I want you to crush the ogres at Bloodmaul Camp!\n\nTo get down there, head northwest down the ramp out of the Ruuan Weald.  You'll find them at the base of the ramp.\n\nGood luck, <class>!", progress = nil, completion = "&lt;The lieutenant nods her head in obvious approval of your killing prowess.&gt;\n\nI am impressed, &lt;name&gt;.  Your reputation seems to be well-deserved.\n\nEvery time one of the ogres is felled, we come one step closer to ridding ourselves of a danger that has no intention of leaving us in peace.", rewards = "You will be able to choose one of these rewards:\n\nDarktread BootsTwin Moon ShoulderguardsChaintwine CinchFairweather's Wristguards\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10797] = {title = "Favor of the Gronn", objective = "Deliver Gorgrom's Favor to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", description = "A token in the form of a small statuette falls from Dorgok's dead clutch.  It bears a striking resemblance to one of the gronn.\n\nSurely, Commander Haephus Stonewall at Evergrove in the Ruuan Weald, up the ramp to the east, would be interested in this!", progress = "Hello, lad, what news do you bring?", completion = "Oh, now that's pretty.  Looks a lot like those gronn that are always bossing the Bladespire ogres around.\n\nOdd that you should find it in the hands of one of the Bloodmaul leaders.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10798] = {title = "Pay the Baron a Visit", objective = "Speak with Baron Sablemane about fashioning a trap. He is located at the Circle of Blood in the Blade's Edge Mountains.", description = "This is bad news.  Gorgrom the Dragon-Eater is behind the recent Bloodmaul plans against Sylvanaar!\n\nWhy he's manipulating them, and not just using the Bladespire, I don't know.  But if we're to deal with a gronn, we're going to need help.\n\nI know a man who is wise in the ways of all sorts of exotic magics.  Baron Sablemane is his name, and you can find him at the Circle of Blood, back down the ramp to the northwest, and then southwest through the canyon.\n\nAsk him to fashion us a trap for the gronn.", progress = nil, completion = "Ah, an envoy from the vaunted Alliance.  Tell me, lackey, why is it that you are here, begging me for this thing, instead of your illustrious commander?\n\nCould it be that he is afraid of me?  It says something about you that you are not, but I haven't quite decided yet what that is.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10799] = {title = "Into the Churning Gulch", objective = "Baron Sablemane has told you to bring him 7 Crust Burster Venom Glands. Return to him at the Circle of Blood in the Blade's Edge Mountains once you have procured them.", description = "Very well, I'll create this trap, but first I want something in return.\n\nThere happens to be a nearby gronn that is in possession of an item that I want, but you can't face him, not yet anyway.\n\nSo, you and I are going to fashion a sleeping powder from the poison of the nearby crust bursters.\n\nYou'll find them in the Churning Gulch to the southwest.  Bring me a number of their glands, and be quick about it!", progress = "You have all of the venom glands?  If not, begone and waste no more of my time until you do!", completion = "Very well.  A simple, if mundane, task has been completed.  Now, hand me the glands and I will perform the difficult part.", rewards = "You will receive:\n\nBloodboil Poison"}
MultiLanguageQuestData['en'][10800] = {title = "Goodnight, Gronn", objective = "Baron Sablemane wants you to steal Grulloc's Sack, and then return it to him at the Circle of Blood in the Blade's Edge Mountains.", description = "I've outdone myself again.  I've fashioned a sleeping powder for you to use on Grulloc, the gronn I spoke of who is guarding what I want.\n\nGrulloc keeps himself at the Cursed Hollow, an area at the eastern edge of Dragons' End on the other side of the Circle of Blood.\n\nIf I were you, I wouldn't tarry long once you have his sack.  The effects of the dust won't last long.", progress = "You are before me again, <class>.  This must mean that you've procured the sack out from underneath Grulloc's nose.", completion = "&lt;Baron Sablemane peers inside the gronn's sack and seems satisfied.&gt;\n\nVery well, you have upheld your end of the bargain.  And now, I will gift your Commander Stonewall with the trap.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10801] = {title = "It's a Trap!", objective = "Deliver the Dragonfire Trap to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", description = "There's nothing more that I hate in this world than the sons of Gruul and their father!  They slaughtered my people, and my children, and now I will have a taste of revenge!\n\nI have fashioned a trap from some dragon fire, and if you're clever enough, you might just be able to use it to kill a gronn.\n\nI'm sure that you have a particular gronn in mind; it matters not to me which one you kill.  Just hurry, take the trap to your Commander Stonewall.\n\nMy thirst for revenge must be quenched!", progress = "Did the baron fashion us a trap?  One powerful enough to kill a gronn?", completion = "Hmm, a trap fashioned from the essence of dragon flame?  I wonder how Sablemane comes by such rarified substances?\n\nIt does not matter.  What does matter is that we are going to use it to slay a son of Gruul!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10802] = {title = "Gorgrom the Dragon-Eater", objective = "Go to Boulder'mok and collect 3 Grisly Totems from the Boulder'mok ogres. Use Sablemane's Trap at Gorgrom's Altar to summon and kill Gorgrom the Dragon-Eater.\n\nWhen Gorgrom is dead, place the 3 Grisly Totems near his corpse, then return to Commander Haephus Stonewall at Evergrove in the Blade's Edge Mountains.", description = "We must show the ogres that we are not to be trifled with. We must send a message.\n\nTravel to Boulder'mok and kill the ogres there. Make sure you keep their heads.\n\nThen go to Gorgrom's altar and place the trap there for him. Gorgrom will appear, and you must lure him into the trap. When he is dead, mount your grisly totems near his corpse, so that the ogres may look at their fallen master and their fallen brothers, and know the price for seeking to destroy us.", progress = "Has the message been delivered?", completion = "Well done, &lt;name&gt;. Well done!\n\nI suspect we will hear little more from the ogres and their master.", rewards = "You will be able to choose one of these rewards:\n\nFanged AxeWhistling SwordAdjudicator's Staff\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10803] = {title = "Slaughter at Boulder'mok", objective = "Slaughter 5 Boulder'mok Brutes and 3 Boulder'mok Shaman, and then return to Lieutenant Fairweather at Evergrove in the Blade's Edge Mountains.", description = "I know that we have plans for you to head to Boulder'mok. I have something that I want you to do while you are there.\n\nWe must take any chance we can get to strike down the ogres of these mountains, or they will overrun us, and all that we have bled and died for will be for nothing!\n\nBoulder'mok lies to the west. Travel southwest, cross the bridge and head through the tunnel. On the west side of the Raven's Wood you will find them.\n\n<name>, I want you to wipe out the Bladespire ogres of Boulder'mok.", progress = nil, completion = "&lt;Lieutenant Fairweather grins at the story that you tell her about your adventures at Boulder'mok.&gt;\n\nAh, I wish that I could have been there with you.  Let me tell you something, &lt;name&gt;: never accept any duty that keeps you from the glory of the battlefield!\n\nHah!  After all of the ogre killing that you've done, are there any still left in these mountains for me?!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10804] = {title = "Kindness", objective = "Mordenai at Netherwing Fields in Shadowmoon Valley wants you to feed 8 Mature Netherwing Drakes.", description = "Something has them spooked, <race>.\n\n<Mordenai points to the nether drakes flying overhead.>\n\nThey won't even come down to feed. I have seen several fall to the earth, dead from exhaustion before their bodies hit the ground.\n\nWe must save them! The Rocknail flayers that are found near the crystals are their natural prey. Kill flayers and take their carcasses. Place a carcass in the field and stand extremely still. As long as you do not make any aggressive motions, they will not attack you.", progress = "I cannot save them by myself, <name>!", completion = "You are a kind and compassionate &lt;race&gt;, friend.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10805] = {title = "Massacre at Gruul's Lair", objective = "Baron Sablemane has tasked you and your friends with the deaths of 10 Bladespire Enforcers, 5 Bladespire Battlemages, 5 Bladespire Ravagers and their leader, Fingrom. When you have managed this feat, return to him at the Circle of Blood in the Blade's Edge Mountains.", description = "You've proven yourself resourceful, and now I think I'm going to put you to personal use in my own fight against Gruul and his sons.\n\nThe Bladespire clan are the favored of the gronn, and while you may have thinned out their numbers elsewhere, you haven't yet dealt with their strongest.\n\nGruul protects the exterior of his lair with only the toughest of ogres, and it is those that you must kill.  Head north through the Daggermaw Canyon and you will find Gruul's Lair at the end.", progress = nil, completion = "Very well, I chose wisely when I selected you to spearhead my fight.  Time to ramp things up to a whole new level, I think.\n\nYou remember that little goodie that you stole for me out from underneath Grulloc's nose?  You're going to get a chance to put it to good use.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10806] = {title = "Showdown", objective = "Use Sablemane's Signet at the Altar of Goc, then kill Goc. Return to Baron Sablemane at the Circle of Blood in the Blade's Edge Mountains when this is done.", description = "The time has come for us to face Goc, the master of the Bladespire ogres. It is also time that I take a hand in events, to see the last of the gronn's life.\n\nTake my signet ring. When you come to the Altar of Goc, use it, and I will come to join you.\n\nTogether we will destroy Goc.", progress = "In time, all the sons of Gruul will be destroyed.", completion = "You fought surprisingly well for a &lt;race&gt;, and it was an honor to have you at my side.  My transformation must have been quite a surprise for you.  I trust it was not too startling?\n\nLet us keep my true identity between the two of us for now, shall we?  In return, and for your adept service, I grant you your choice of any of these baubles.", rewards = "You will be able to choose one of these rewards:\n\nTourmaline CrownClefthoof Hide LeggingsOilcloth BreechesMalefactor's EyepatchLeonine BreastplateBlackened Chestplate\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10807] = {title = "The Ashtongue Broken", objective = "Varen the Reclaimer wants you to go to the Ruins of Baa'ri and slay 3 Ashtongue Handlers, 4 Ashtongue Warriors and 6 Ashtongue Shaman.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "The Ashtongue tribe is feared among all Broken.  It consists of the most vicious and bloodthirsty individuals, handpicked by Akama himself.  They are as fierce and ruthless as any naga, demon or blood elf in Illidan's army and they have been deployed in large numbers at the Ruins of Baa'ri, to the north.  Go there and put a dent in their numbers before they get a chance to mount an attack on us.", progress = nil, completion = "Glory to the Scryers, &lt;name&gt;.  You've done the Seer's bidding by defeating those who follow Illidan.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10808] = {title = "Thwart the Dark Conclave", objective = "Slay the Dark Conclave Ritualists and use the Staff of Parshah to end the Dark Conclave's summoning ritual, then return to Parshah in the Magma Fields.", description = "The spirits of the dark conclave seek to summon an ancient and powerful evil through a ritual conducted at the lava pits to the south of the Sketh'lon Base Camp.\n\nGul'dan's magic mingled with their own, empowering them to aid this creature in manifesting in our world! We must not allow this to happen, <name>. The death and destruction it would bring are unimaginable!\n\nCarry the staff with you to the site of the summoning and use its magics to stop the dark conclave once and for all!", progress = "Is it done, <name>? Have you stopped the dark conclave from completing their ritual?", completion = "I have sought a way to stop the dark conclave for years, and you have succeeded where I failed. The conclave's dark rituals will threaten us no more.\n\nI often feel guilty for abandoning my fellows all those years ago, but now I finally know that I made the right decision. If not for my wavering conscience then, I might have ended up as a shade among them.", rewards = "You will be able to choose one of these rewards:\n\nAsh Tempered LegguardsCrown of CindersRuned Sketh'lon LegplatesSketh'lon Survivor's Tunic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10809] = {title = "Wanted: Worg Master Kruush", objective = "Kill Worg Master Kruush and bring his head to Captain Darkhowl in Spinebreaker Post.", description = "The poster reads:\n\n\"Worg Master Kruush leads the worg riders of the Bleeding Hollow clan.  A price has been placed on his head, for his riders exact heavy tolls on supply trains to Spinebreaker Post.\"\n\n\"Scouts report him within Zeth'Gor, and the hero able to bring the severed head of this villain to me will earn the thanks of the Horde, and a large bounty.\"\n\n\"-Captain Darkhowl\"", progress = "Report, <name>.  Is that Bleeding Hollow blood I see on your sleeve?  I hope so!", completion = "Ah, so you slew that villain, Kruush!  Well done, &lt;name&gt;!  Well done!  His death will defang those cursed worg riders.  In fact, I hope you took a few of them out during your foray into Zeth'Gor!\n\nHere's your reward.  You earned every piece of it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10810] = {title = "Damaged Mask", objective = "Bring the Damaged Mask to O'Mally Zapnabber in Ruuan Weald.", description = "As you examine the damaged mask, you hear strange sounds coming from within. If the mask wasn't damaged you might be able to hear the sounds more clearly.\n\nO'Mally Zapnabber in Ruuan Weald might be able to fix the mask.", progress = "Don't be bothering me! Can't you see I'm trying to unlock mysterious powers?", completion = "Ah, what's that you have? Let me take a closer look, &lt;class&gt;. Yes, yes... it's just what I thought it was. Here, let me fix this mask for you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10811] = {title = "Seek Out Neltharaku", objective = "Seek out Neltharaku, patron of the Netherwing Dragonflight.", description = "Their patron soars high above, <name>. Perhaps the kindness that you showed his children has moved his heart. Seek Neltharaku out and enlist his aid. Together, you may be able to solve the plight of the Netherwing drakes.\n\n<Mordenai points to the sky.>\n\nFly high, friend...", progress = nil, completion = "My children have told me of your heroic deeds, &lt;race&gt;. There is more that you can do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10812] = {title = "Mystery Mask", objective = "Bring the Mystery Mask to Wildlord Antelarion in Ruuan Weald.", description = "Ok, it should work now. What is it, you ask? Why, it's a communication device - it allows those blockheads to communicate with each other. You know, the Burning Legion! I would suggest that you hand this mask to Wildlord Antelarion. He's over there pacing around. Always moving, he is.\n\nWell get moving, he's been trying to get his hands on one of these for sometime now.", progress = "I cannot believe my eyes.", completion = "That mask you hold in your hands is a Felsworn gas mask and by the appearance, it's not damaged. The trouble we can cause Forge Camp: Anger is boundless. Are you interested in helping us out, &lt;name&gt;?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10813] = {title = "The Eyes of Grillok", objective = "Use Zezzak's Shard to capture an Eye of Grillok, then approach Zezzak's cauldron to extract it. After it is removed, return Zezzak's Shard to him.", description = "<name>, you have braved the lair of the Bleeding Hollow orcs, dreaded Zeth'Gor, and survived!  Perhaps you have the strength to aid me, for I aim to gaze into the mind of its darkest witch, Grillok!\n\nTake this shard.  Use it to ensorcel an Eye of Grillok and bind it to yourself.  Return here and approach my cauldron... and it will pull the eye from you.\n\nGo, <name>.  And use care -- An Eye of Grillok will betray you to our enemies if given the slightest opening!", progress = "The orcs of the Bleeding Hollow Clan were dark allies long ago... and even darker enemies now.", completion = "I am indebted to you, &lt;name&gt;.  You have again braved Zeth'Gor and held its darkness close to your heart.  I will study the eye and perhaps pierce the secrets of its master, Grillok.\n\nLet us hope that he can no longer use its magic!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10814] = {title = "Neltharaku's Tale", objective = "Speak with Neltharaku and listen to his story.", description = "I have information that you may find useful. Please listen to what I have to tell you, <race>.", progress = "Allow me to finish telling you my tale.", completion = "So you will help us?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10815] = {title = "The Journal of Val'zareq: Portends of War", objective = "Locate Marcus Auralion, High General of the Sha'tar, at Crimson Watch.", description = "This journal documents the recent activities of Illidan's armies. It also explains why Val'zareq was parading around the Path of Conquest. He was personally responsible for the capture of a high general of the Sha'tar.\n\nThis general is being held at a post known as Crimson Watch, located at the southern end of the Path of Conquest. A mysterious faction, calling itself the Crimson Sigil, is charged with his incarceration. If you choose to investigate, it would be wise to bring allies.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10816] = {title = "Reclaiming Holy Grounds", objective = "Vindicator Aluumen wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "You did well against the Broken in Baa'ri, <name>.  Let's see how well you do against Illidan's most feared army.\n\nThe fel orcs of the Shadowmoon Clan occupy the Ata'mal Terrace, once a very holy site where ata'mal crystals were used in spiritual ceremonies.\n\nWe had reason to believe they were hiding an actual ata'mal crystal in the vicinity, but our scrying has revealed nothing.  Nevertheless, the fel orcs are on draenei holy ground and their presence must be dealt with.", progress = nil, completion = "Excellent work, &lt;class&gt;.  May the Light continue to protect you.", rewards = "You will be able to choose one of these rewards:\n\nAged Leather BindingsAsh-Covered HelmAta'mal CrownBlackened Chain Greaves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10817] = {title = "The Great Retribution", objective = "Varen the Reclaimer wants you to slay 8 Shadowmoon Slayers, 8 Shadowmoon Chosen and 4 Shadowmoon Darkweavers.\n\nCompleting quests for the Scryers will cause your Aldor reputation level to decrease.", description = "You did well against the Ashtongue Broken, <name>.  I have another challenge for you, should you be up to it.\n\nNot too long ago, the Sanctum of the Stars suffered a tremendous attack by Illidan's fel orcs.\n\nWe've determined it was perpetrated by the Shadowmoon orcs who occupy the Ata'mal Terrace.\n\nShow them that the Scryers are not to be trifled with.", progress = nil, completion = "You've gained my utmost respect today, &lt;name&gt;.\n\nSlaying one fel orc is not an easy task.  Massacring a score of them is, well... heroic.", rewards = "You will be able to choose one of these rewards:\n\nAged Leather BindingsAsh-Covered HelmAta'mal CrownBlackened Chain Greaves\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10818] = {title = "Baron Sablemane Has Requested Your Presence", objective = "You have received an invitation to speak again with Baron Sablemane on some matter of import. Go to him at the Circle of Blood in the Blade's Edge Mountains.", description = "<name>, while you were out being one hell of a <class>, Baron Sablemane sent his pet dragon up here with a message.\n\nHe's asked for you personally.  From what I understand, he wants you to head up his own fight against the gronn.\n\nI guess you're the most qualified person in all of Outland to help him, but if I were you, I'd get in contact with a couple of friends first and ask them to join you at the Circle of Blood.", progress = nil, completion = "Ah, I see that you decided to take your sweet time answering my summons.\n\nNo matter, I have plenty of time to exact my revenge, and I intend for you to be my proxy in the coming battle!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10819] = {title = "Felsworn Gas Mask", objective = "Wear the Felsworn Gas Mask and use the Legion Communicator at Forge Camp: Anger.\n\nProvided item: \n", description = "I have a very special mission for you, <name>. I need you to infiltrate Forge Camp: Anger east of here. When you enter the camp you will need to wear the Felsworn gas mask and locate the Legion communicator. Once you have located the communication device speak with whomever is on the other side of the device.\n\nIf all works out you can trick the demon into something devious! Try telling the demon that camp anger has revolted.\n\nGood luck to you <class>.", progress = nil, completion = "What's the meaning of this! No one summons me! Speak, or I will silence you forever!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10820] = {title = "Deceive thy Enemy", objective = "Kill 4 Doomforge Attendants and 4 Doomforge Engineers.", description = "For every moment I hear silence, you draw closer to your death! SPEAK!\n\nWhat? The camp has revolted? This cannot possibly be true! My minions would not dare undermine my authority.\n\nWell then, every last one of them will pay for this treachery, they will pay dearly. Silence them all and be done with it! Report back to me once you have carried out my order or you shall be dealt with.", progress = "My patience is tiring, why have you not finished them?", completion = "That will surely teach those that don't do as I say...\n\nBy the way... where is Doomcryer? Why have you reported this revolt to me and not she?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10821] = {title = "You're Fired!", objective = "Kill Doomcryer and report back to Wildlord Antelarion in Evergrove.", description = "Doomcryer did nothing to stop the revolt? How dare she! She has been trying to undermine my authority for some time. However, this time will be her last. You must summon her and deal with her personally.\n\nHer anger guards hold the keys that summon her to Forge Camp: Anger. Retrieve the five keys and activate the five Legion obelisks. The obelisks have a short duration, so make sure they are all activated at the same time. Remember, the anger guards carry more keys.", progress = "Are you looking to join my list of those expendable? Get those keys and silence Doomcryer!", completion = "That is great news, great news indeed, &lt;name&gt;. I could not have asked for a better outcome. Your service to our people is most greatly appreciated; choose one of the following heroic items.\n\nYour name will forever be remembered in our peoples' hearts.", rewards = "You will be able to choose one of these rewards:\n\nRuuan Weald WristguardsEvergrove Ranger's CloakExpedition PendantWildlord's Band\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10822] = {title = "Single Sunfury Signet", objective = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", description = nil, progress = "Even the smallest contribution to our cause is noted, <name>.  Our enemies are many, but we shall prevail!", completion = "Victory to the Scryers!  Kael's forces will soon crumble.", rewards = nil}
MultiLanguageQuestData['en'][10823] = {title = "More Sunfury Signets", objective = "How fares the battle against Kael's forces?", description = nil, progress = "How fares the battle against Kael's forces?", completion = "You're making a name for yourself, &lt;name&gt;.  Keep it up.", rewards = nil}
MultiLanguageQuestData['en'][10824] = {title = "Sunfury Signets", objective = "Battlemage Vyara at the Sanctum of the Stars wants you to bring her 10 Sunfury Signets.\n\nPerforming quests for the Scryers will cause you Aldor reputation level to decrease.", description = "The survival of the Scryers hinges on outrecruiting Kael'thas.  Every pilgrim from Quel'Thalas that joins his side brings him closer to victory.  The opposite is true for us.\n\nSoon, however, we will run out of recruits and it will come down to what side can kill the other quicker.  Prove your worth to the Scryers by bringing me Sunfury signets worn by  high-ranking blood elves allied with Kael'thas and Illidan.  You'll find them at Eclipse Point to the west and the Ruins of Karabor, to the northeast.", progress = "Go on, <name>.  Speak.", completion = "Kael's elves are extremely well-trained.  Excellent job.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10825] = {title = "The Truth Unorbed", objective = "Deliver the Orb of the Grishna to Tree Warden Chawn at Ruuan Weald in the Blade's Edge Mountains.", description = "This strange, magical orb drops from beneath the contour feathers of the arakkoa.\n\nSuffused with an eerie, purple glow, the orb pulses to an unheard beat.  Holding it makes you mildly uncomfortable, and so you quickly place it within your pack.\n\nPerhaps Tree Warden Chawn at Ruuan Weald to the west, through the tunnel and across the Wyrmskull Bridge, would be interested in examining it?", progress = "<class>, do you feel that?  I sense something unnatural and evil nearby.", completion = "Yes, it's that orb you have there!  Odd, it appears to be of arakkoan design.  Were you recently at Grishnath?\n\nAll right, that explains that, but I wonder what diabolical purpose this object serves.  Though it radiates evil, it also somehow feels as if it were connected to the natural world.\n\nHere, allow me to try activate it.  The evil is so strong within it, there's some sort of residual memory here....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10826] = {title = "Marks of Sargeras", objective = "Bring 10 Marks of Sargeras to Harbinger Saronen in Shadowmoon Valley.\n\nCompleting quests for the Aldor will cause your Scryers reputation level to decrease.", description = "By now it should be clear to you why we oppose the Burning Legion and those who serve them.\n\nIf you wish to prove yourself to the Aldor, bring me the insignias of high-ranking Legion and their Shadow Council followers.  Here in Shadowmoon you will find a strong Legion presence to the far west in Legion Hold and the Deathforge.", progress = "Do you bear any of our enemies' insignias, <name>?", completion = "Your courage is strong, friend.  Let it be known to all that you are a true ally of the priesthood!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10827] = {title = "More Marks of Sargeras", objective = "Do you bear more of our enemies' insignias, <class>?  We will fight the Legion until the Light prevails.", description = nil, progress = "Do you bear more of our enemies' insignias, <class>?  We will fight the Legion until the Light prevails.", completion = "Destroy the enemies of the Light wherever you find them, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['en'][10828] = {title = "Single Mark of Sargeras", objective = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", description = nil, progress = "I'll take any leftover marks you might have.  Do not worry; your actions will be duly noted.", completion = "You continue to prove your worth, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['en'][10829] = {title = "Treebole Must Know", objective = "Tree Warden Chawn has asked you to seek out and speak with Treebole, an ancient of lore who lives in the Raven's Wood of the Blade's Edge Mountains.", description = "This is troubling!  The arakkoa are causing the ancients and protectors to become possessed by evil spirits!\n\nBut, there is one ancient that could not possibly have been affected.  His name is Treebole, and you must go to him at once if we're to save the trees of the Raven's Wood!\n\nGo back to the Raven's Wood.  You will find him at the fork in the path just past Grishnath.", progress = nil, completion = "Greetings, tiny &lt;race&gt;.  The birds in my boughs whispered to me that you were to be expected.\n\nYou are here to help free the trees of the woods from their possession?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10830] = {title = "Exorcising the Trees", objective = "Collect 5 Grishnath Orbs and 5 Dire Pinfeathers and then combine them into Exorcism Feathers. Use these feathers to exorcise and slay 5 Koi-Koi Spirits from the Raven's Wood Leafbeards. Once you've done this, return to Treebole in the Raven's Wood of the Blade's Edge Mountains.", description = "The Grishna have caused the leafbeards and stonebarks to be inhabited by evil koi-koi spirits.\n\nWe must save the trees or soon all of the Raven's Wood will be lost forever!\n\nCombine the magic of a Grishnath orb, found throughout Grishnath, with a dire pinfeather from a dire raven.\n\nUse the resultant exorcism feather to draw out and slay the koi-koi spirit as quickly as possible.  The stonebarks are too powerful for this ritual, but if enough leafbeards are saved, they will be freed as well.", progress = "The evil that is inhabiting the trees is beginning to seep into every natural thing in the woods.\n\nYou must act quickly, <name>, before all is lost!", completion = "The evil is lifting from the Raven's Wood!  Can you feel it, &lt;name&gt;?\n\nYou have saved us, and all of the surrounding wildlife, from certain destruction, little one!\n\nI keep stashed four magic rings amongst my boughs for such occasions as this, when a hero arises to do some great deed.\n\nYou are one such hero!  On behalf of all of the Raven's Wood, we give you thanks.", rewards = "You will be able to choose one of these rewards:\n\nRaven's Wood Exorciser's BandLeafbeard RingTreebole's HoopRing of the Stonebark\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10831] = {title = "Becoming a Mooncloth Tailor", objective = "Use the Square of Imbued Netherweave while standing in Cenarion Refuge's moonwell to create a Sample of Primal Mooncloth. Bring the completed sample back to Nasmara Moonsong in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", description = "I can teach you the ways of mooncloth tailoring, if you are interested.. By specializing in mooncloth tailoring, creating primal mooncloth will yield twice the normal amount and you will have access to several exclusive patterns. All that is required is that you pass a simple test.\n\nAs to the test, your task is to create a small sample of primal mooncloth in the moonwell at Cenarion Refuge. I will provide all the materials you'll need. When you've created the sample, bring it back to me for examination.", progress = "Have you created the primal mooncloth sample?", completion = "&lt;Nasmara examines the cloth, turning it over in her hands.&gt;\n\nThis is an exceedingly fine sample, &lt;name&gt;. You will make an excellent mooncloth tailor.", rewards = "You will learn:\n\nMooncloth Tailoring\n\nThe following spell will be cast on you:\n\nMooncloth Tailoring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10832] = {title = "Becoming a Spellfire Tailor", objective = "Bring a sample of Nether-wraith Essence to Gidge Spellweaver in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", description = "I can teach you the ways of spellfire tailoring if you wish, but be warned, it's a dangerous pursuit.\n\nCreating spellcloth in Netherstorm attracts powerful nether-wraiths. I'm searching for a way to lessen backlash, but I need more nether-wraith essence for my research.\n\nTake this beacon with you to Netherstorm and use it to summon a nether-wraith. Bring back its essence and I'll agree to teach you. As a spellfire tailor, you'll receive twice as much cloth and have access to exclusive patterns.", progress = "Did you get the nether-wraith sample?", completion = "&lt;Gidge examines the nether-wraith essence.&gt;\n\nEven this small a sample of the creature's essence radiates power. Perhaps I misunderstood what's happening. We're not angering the wraiths by taking energy from the environment. Rather, the wraiths and the environment are the same thing!\n\nDon't hesitate to let me know if you make any further discoveries, now that you've become a spellfire tailor.", rewards = "You will learn:\n\nSpellfire Tailoring\n\nThe following spell will be cast on you:\n\nSpellfire Tailoring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10833] = {title = "Becoming a Shadoweave Tailor", objective = "Use the Crystal of Deep Shadows near the Altar of Shadows to deepen your attunement to the altar, then return to Andrion Darkspinner in Shattrath's Lower City.\n\n*WARNING!* You can only select one tailoring specialization.", description = "If you become a shadoweave specialist, you will make twice as much shadowcloth as an average tailor and have access to several exclusive patterns.\n\nOf course, any tailor can use the Altar of Shadows, but a shadoweave tailor possesses a deeper attunement to the altar, unlocking powers that few can fathom.\n\nTake this crystal to eastern Shadowmoon Valley, and find Netherwing Pass leading south from the Netherwing Fields. Near the world's edge, you will find the Altar of Shadows. Use the crystal there.", progress = "Have you used the crystal's power to deepen your attunement to the Altar of Shadows?", completion = "I can see that your visit to the altar was a success. There is a subtle difference about you that few will see, but there's no doubt it's there.", rewards = "You will learn:\n\nShadoweave Tailoring\n\nThe following spell will be cast on you:\n\nShadoweave Tailoring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10834] = {title = "Grillok \"Darkeye\"", objective = "Kill Grillok Darkeye and bring Grillok's Eyepatch to Zezzak in Spinebreaker Post.", description = "Grillok Darkeye has wagered a piece of himself to dark powers, and gained great magic for it.  His lost eye burns deep in some hellish pit, now a demon's trinket... and the patch that covers his betrayal holds its own dark secrets.\n\nBring me Grillok's eyepatch, <name>, and I will reward you greatly for your service...", progress = "The evils of the Bleeding Hollow orcs know no bounds, and are rivaled by only their Shattered Hand cousins.", completion = "Ah, yes.  Just as some who lost a hand or a leg in battle will oftentimes feel their severed limb, I wonder if Grillok still clutched at his lost eye in his dark, dark dreams...\n\nI too will dream on this, and if fortune is with us then perhaps I will learn what drew Grillok and the Bleeding Hollow orcs to succumb to demons.", rewards = "You will be able to choose one of these rewards:\n\nBonechewer Berserker's VestGoldweave TunicSacred Feather VestGilded Crimson ChestplateJerkin of the Untamed Spirit\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10835] = {title = "Apothecary Antonivich", objective = "Bring Albreck's Findings to Apothecary Antonivich in Thrallmar.", description = "<name>, I have prepared a preliminary report of my findings regarding the Bleeding Hollow orcs.  My colleague in Thrallmar, Apothecary Antonivich, will be happy to receive them.  He too studies the phenomenon of fel orcs... in hopes of preventing such a tragedy from again befalling our orcish allies.\n\nTake him this report, and I will continue my study of the blood you brought me.  If fortune is with us, we will isolate the cause of the fel orc affliction.", progress = "Good day, <name>.  And how is your stay in Hellfire Peninsula?  I trust it has been fruitful...", completion = "Ah, a report from Albreck?  Very good.  The Royal Apothecary Society works feverishly to determine how the orcs of Hellfire Peninsula became fel orcs.  Their betrayal is unforgivable... and we must ensure that our orc friends are forever safe from future corruption.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10836] = {title = "Infiltrating Dragonmaw Fortress", objective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to slay 15 Dragonmaw Orcs.\n\nAny Dragonmaw Orc in Dragonmaw Fortress will suffice.", description = "I require time so that I may devise a plan to save my children and mate. You will buy me this time, mortal.\n\nVenture into Dragonmaw Fortress, located on the eastern edge of the Netherwing Fields, and lay waste to all Dragonmaw orcs that you find. The ensuing chaos and confusion should have a considerable impact on their plans.\n\nBe warned, some of my kin are too far gone - their minds corrupted by the Dragonmaw. For them, the only resolution is death. You have my permission to end their lives as well.", progress = "Is it done? I can only hope that it is not too late...", completion = "Well done, &lt;name&gt;. I have discovered a way in which we can free the enslaved drakes that are being held at Dragonmaw Fortress.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10837] = {title = "To Netherwing Ledge!", objective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to collect 12 Nethervine Crystals from Netherwing Ledge.", description = "I believe that I can imbue nethervine crystals with my own essence. The power contained within these imbued crystals should be sufficient to free enslaved drakes of their masters' grasps.\n\nTravel to Netherwing Ledge, an island located off the broken shelf of Shadowmoon Valley, to the southeast. It is on Netherwing Ledge that you will find nethervine crystals. Return to me when you have collected enough crystals to fill your packs.\n\nAnd <name>, Beware the Dragonmaw that now inhabit the island.", progress = "I require nethervine crystals.", completion = "&lt;Neltharaku takes the crystals from you.&gt;\n\nI will prepare the crystals for you now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10838] = {title = "The Demoniac Scryer", objective = "Use the Demoniac Scryer in Hellfire Basin, wait for it to attune, and then take a reading.\n\nReturn the Demoniac Scryer and the Demoniac Scryer Reading to Apothecary Antonivich in Thrallmar.", description = "The Demoniac Scryer is now ready.  Take it behind Hellfire Citadel, to Hellfire Basin, and summon it upon the ground.  It will then begin to attune itself to Hellfire Citadel.  After its attunement, speak to the Scryer and transcribe what it tells you.  Bring that transcription to me...\n\nGo, <name>, but only when you are ready.  There is no doubt that Hellfire Citadel will detect the Scryer and send wardens to destroy it!", progress = "Do you have the reading?  Has your mission with the Demoniac Scryer been successful?", completion = "You obtained the reading?  Excellent -- I am sure this data will prove invaluable to our research.  I will disseminate it to Apothecaries Zelana and Albreck.\n\nYou should be proud, &lt;name&gt;.  Your strength and bravery is unquestionable... as is your service to the Horde.", rewards = "You will receive:\n\nDemoniac Soul Prison"}
MultiLanguageQuestData['en'][10839] = {title = "Veil Skith: Darkstone of Terokk", objective = "Use the Rod of Purification on the Darkstone of Terokk in Veil Skith and return to Kirrik at the Refugee Caravan in Bone Wastes.", description = "Veil Skith lies to the northwest of the caravan and to the south of Shattrath in a secluded grove of the forest. It is rumored that the colony of Skettis has constructed a maligned altar of worship. This Darkstone of Terokk must be purified if the arakkoa of Skith are ever to be redeemed.\n\nTake this Rod of Purification and cast it upon the Darkstone. Blessed by A'dal, the rod's purity might be enough to bring clarity to the Darkstone. Go now and may the light shine upon thee.", progress = "Darkness surrounds us. What have you to say about Veil Skith?", completion = "I heard the explosion from here. Not with my ears, but with my heart.\n\nIf the touch of the blessed Naaru, A'dal, is not enough to bring the arakkoa to redemption, nothing will be. Those who have not given themselves over to the Light are mere servants of evil.\n\nThey must be destroyed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10840] = {title = "The Tomb of Lights", objective = "High Priest Orglum wants you to journey to the Tomb of Lights and kill 10 Ethereal Nethermancers and 10 Ethereal Plunderers and then return to him by the Refugee Caravan.", description = "To the east, buried under the charred sand, is the Tomb of Lights, a lost resting place of the dead.  Before our caravan was ambushed I was going to journey to the tomb and cleanse it of evil spirits.  \n\nLittle did I know it was already infested with another kind of evil.  Even now the ethereals plunder the bodies of the fallen for trinkets and keepsakes that were given to the dead centuries ago.  \n\nThere is little I can do while our caravan struggles to survive.", progress = "How many ethereals have you destroyed?  I hope it will be enough to drive them from the Tomb of Lights.", completion = "Out here in the wilds of Outland we are weak with few heroes to defend our rights, but you have given them something to fear &lt;class&gt;.  I do not think the ethereals will soon forget the strong right arm of &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10841] = {title = "The Vengeful Harbinger", objective = "[PH]  Activate the thingy.", description = "[PH]  Go into the Tomb of Light and activate the thingy.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10842] = {title = "The Vengeful Harbinger", objective = "High Priest Orglum wants you to journey into the Tomb of Lights and use the Draenei Tomb Relic near the Ancient Draenei Altar.\n\nDefend the Tomb Guardian and defeat the Vengeful Harbinger. When the ritual is complete, speak with the Draenei Ascendant at the Ancient Draenei Altar.", description = "The Tomb of Lights has become corrupted by the Shadow Council and the draenei dead have become cursed spirits, angry and confused with a burning hatred for the living.  \n\nBefore I left Shattrath I was given a draenei tomb relic.  It can be used near the Ancient Draenei Altar deep within the Tomb of Lights to summon a tomb guardian.  This creature will activate the altar and will begin to purge the tomb of corrupt spirits, freeing them to ascend.  Protect the tomb guardian until the ritual is complete.", progress = "You have saved us all.  What can we do to thank you?", completion = "You cannot know what you have done here &lt;name&gt;.  You have saved so many of us from an eternity of darkness.  There is little that I can do for the living and nothing that I could give that would thank you enough.  Take what seems useful to you.", rewards = "You will be able to choose one of these rewards:\n\nAncient Draenei War TalismanAncient Draenei Arcane Relic\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10843] = {title = "Since Time Forgotten...", objective = "In order to prove yourself to the Mok'Nathal, Leoroxx has ordered you to slay Gnosh Brognat, leader of the ogres at the Bladespire Outpost. Return to Leoroxx at Mok'Nathal Village in the Blade's Edge Mountains after you have done so, or do not return at all.", description = "Since time forgotten we have fought with the Bladespire ogres.\n\nWe have managed to push them back so that now they only hold a tenuous grip at Bladespire Outpost.  It's back the way that you came, on the southwestern edge of the Razor Ridge.\n\nProve your worth to me by killing their leader, Gnosh Brognat.\n\nLet us see what stuff you are made of when fighting the ogres.", progress = nil, completion = "&lt;Leoroxx appraises you with a keen eye, seemingly trying to take your measure.&gt;\n\nThe death of Gnosh Brognat is a boon to all of the Mok'Nathal.  This is a good thing for you.\n\nLet us see if we can push the boundaries of your prowess just a bit more.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10844] = {title = "Forge Camp: Anger", objective = "You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10845] = {title = "Slay the Brood Mother", objective = "Leoroxx has challenged you to slay Dreadwing. Return to him at Mok'Nathal Village once you have managed to kill her.", description = "My hunters have just returned from a scouting mission to the Singing Ridge.  It seems that the nether drakes, which infest the crystals there, have increased greatly in number, and threaten to spill out into our laps.\n\nSince you have proven yourself a competent slayer, let us see if your <class> skills are the match of an adult drake.\n\nFind the Singing Ridge by heading south through the Scalewing Shelf.  Enter and slay their brood mother, Dreadwing.", progress = "Though you will not further yourself in my eyes, there is no shame in admitting that you aren't up to the challenge of slaying the mother of the Singing Ridge nether drakes.\n\nIs that what you are here to tell me?", completion = "No?  You slew Dreadwing?  Perhaps I was wrong about you, &lt;class&gt;.\n\nPerhaps.\n\nStill, you have slain the chiefs of the three greatest threats that we face.  That is something to be proud of.\n\nI offer you a token of my appreciation, but don't let it go to your head.  You still do not fully understand what it is to be Mok'Nathal, and we may still have need to call upon your skills.", rewards = "You will be able to choose one of these rewards:\n\nDreadwing Skin BeltBrood Mother LeggingsNetherhide GlovesNether Protector's Chest\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10846] = {title = "Understanding the Mok'Nathal", objective = "To begin your understanding of the Mok'Nathal, slay Vekh, leader of the Vekh'nir arakkoa. Then, return to Leoroxx at Mok'Nathal Village in the Blade's Edge Mountains.", description = "<Leoroxx looks you in the eye with the kind of stare that chills your soul.>\n\nYou come to the Mok'Nathal, but you do not understand us.  You do not understand our struggle to survive.\n\nIf you would understand us, then you will have to endure a taste of that struggle.\n\nTo the south are the Vekh'nir arakkoa.  They have enslaved a group of ogres in the caverns known as Trogma's Claim and their leader, Vekh is in there.\n\nSlay him!", progress = "We have many enemies.  Some we have chosen, and some, such as the Vehk'nir, we have not.\n\nRegardless, we shall slay all of their chieftains until none stand before us.", completion = "The Vekh'nir are the least of our adversaries.\n\nSo, you know how to slay an overgrown bird.  This does not make you a true warrior.  This does not give you a full understanding of our ways.\n\nBut it's a start.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10847] = {title = "The Eyes of Skettis", objective = "Bring the Eye of Reskk and the Eye of Shienor to Rilak the Redeemed in the Lower City district of Shattrath.", description = "Doom harkens from the cliffs of Skettis.\n\nMy people, the arakkoa, face a fate shrouded in unspeakable evil. Too often have we abused dark magic for wrongdoing. Through A'dal I have learned of the Light and of redemption.\n\nTerokk watches his colonies from Skettis through orbs enchanted by the black art. Steal these Eyes from Veil Reskk and Veil Shienor in northern Terokkar. Let me see what Terokk sees. Let me look through the eyes of Skettis.", progress = "You have returned, <class>. What news do you bring?", completion = "Your bravery should be commended. The guardians of Skettis do not part with their belongings willingly.\n\nBut heroics of the past are of little consequence now. We shall see if such bravery continues to persist in the future, for Terokk's gaze fixates on the south.\n\nThese Eyes are all seeing.", rewards = "You will be able to choose one of these rewards:\n\nSuper Healing PotionSuper Mana Potion\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10848] = {title = "Veil Rhaze: Unliving Evil", objective = "Kill 4 Deathtalon Spirits, 4 Screeching Spirits and 2 Spirit Ravens and return to Kirrik at the Refugee Caravan.", description = "Veil Rhaze was a particularly wicked colony of Skettis.\n\nDespite the village's eradication by the Auchindoun disaster, Terokk's influence remained in the maligned spirits there. Travel west to Veil Rhaze and slay those murderous wretches. You'll find them to the west of the Shadow Tomb, on the border of Bone Wastes and Terokkar Forest.\n\nThis will be our first blow against Terokk and the guardians of Skettis.", progress = "Evil grows in Veil Rhaze. Put it down, <race>.", completion = "Those foul spirits deserved to die. The death they would have wrought on others is reason enough.\n\nWe cannot hope to redeem those in Terokk's grasp. But we shall deliver them a devastating blow in the name of the Light.", rewards = "You will be able to choose one of these rewards:\n\nTalonbranch WandFeather-Wrapped Bow\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10849] = {title = "Seek Out Kirrik", objective = "Take Rilak's Missive to Kirrik at the Refugee Caravan in the Bone Wastes.", description = "Other arakkoa took part in the betrayal of Terokk.\n\nKirrik recognized Terokk as a charlatan, not a prophet. The only prophecy Terokk envisioned was the doom borne of his own bidding.\n\nIt was Kirrik who led us bravely from Skettis. After our pilgrimage to Shattrath, Kirrik traveled to the colonies in search of others.\n\nThis missive tells of what the Eyes have seen. Kirrik must be told! Follow the road south out of Shattrath to the Bone Wastes and look for the caravan.", progress = "You have traveled far and bear news for me.", completion = "Rilak's tale is grim, traveler. As you can see from the state of the caravan, there is much sorrow and darkness in the forest of Terokk these days.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10850] = {title = "Nether Gas In a Fel Fire Engine", objective = "You uncover an opening through which fuel is loaded into the fel reaver.", description = nil, progress = "You uncover an opening through which fuel is loaded into the fel reaver.", completion = "The fel reaver's engine begins to rumble and sputter as you supply it with the incorrect fuel.", rewards = nil}
MultiLanguageQuestData['en'][10851] = {title = "The Totems of My Enemy", objective = "Collect 5 Bladespire Totems for Spiritcaller Dohgar at Mok'Nathal Village in the Blade's Edge Mountains.", description = "There is the right way to honor one's ancestors, and there is the wrong way.\n\nThe Bladespire ogres carry totems with them, but they do not use them to show their respect.  Instead, they seek to use them to manipulate and control.\n\nWe should steal their totems because they are unworthy!  We will then put them to better use.\n\nGo to the Bladespire Outpost to the west, just southwest of the Razor Ridge.  Slay the Bladespire mystics and crushers, and take their totems from them!", progress = "Have you gone to Bladespire Outpost and taken their totems from them?", completion = "This looks like a good assortment.  We should be able to find a respectful use for one or two of them.\n\nIn fact, I have an idea for how to do just that!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10852] = {title = "Missing Friends", objective = "Ethan wants you to find 12 of his missing friends in Veil Skith and then return to him at the Refugee Caravan.", description = "We broke down here because some guys came in the night and made a lot of noise.  It was scary.  I don't know when we are going to get moving again.  \n\nSome of my friends are missing though.  I don't know where they are.  I think those scary bird men took them away to the northwest.  They probably are all locked up in cages and stuff.  If you find them that would be great.  I'm kind of worried about them.", progress = "I'm bored, there's nobody to play with.  Have you found my friends?", completion = "You found all my friends!  Now I have someone to play with.  Thank you, Mister &lt;name&gt;.  \n\nSince I have kids to play with maybe you would like one of my toys?  That way you have something to play with too.", rewards = "You will receive:\n\nBattered Steam Tonk Controller"}
MultiLanguageQuestData['en'][10853] = {title = "Spirit Calling", objective = "Spiritcaller Dohgar has asked you to use the Spirit Calling Totems to collect 8 Lesser Nether Drake Spirits and return them to him at Mok'Nathal Village in the Blade's Edge Mountains.", description = "The spirits of the nether drakes in the Singing Ridge are in need of liberation.\n\nThe nether drakes were not always nether drakes.  They used to be black drakes.\n\nBut then, with the destruction of this world, a wave of nether energy washed over everything and had the side-effect of changing the drakeling eggs.\n\nNow they are all twisted versions of their former selves.  We must help them to find peace.\n\nDo this by slaying a drake near to the spirit calling totem, and then take its spirit from it.", progress = "The drakes of the Singing Ridge may pose a threat to us, but I think they are majestic creatures.\n\nOr, at least they were.  I hope that you will be able to save their spirits.\n\nAnd if you are in need of more totems, I have a few to spare.", completion = "You have done a good thing this day, &lt;class&gt;.  The spirits of the drakes will truly sing again now that they have been freed.  And the residual part of their spirits that they leave behind are powerful medicine, too.\n\nI wonder, are you up for a journey to the north?  There is something that I am curious about concerning the activities of the ethereal.\n\nI sense a great deal of pain coming from their direction.", rewards = "You will be able to choose one of these rewards:\n\nNether-Empowered FootgearRitualist's HelmMok'Nathal Champion's ShoulderguardsNether Drake Wristguards\n\nYou will also receive:\n\nMedicinal Drake Essence"}
MultiLanguageQuestData['en'][10854] = {title = "The Force of Neltharaku", objective = "Neltharaku, flying high above Netherwing Fields in Shadowmoon Valley, wants you to free 5 Enslaved Netherwing Drakes.", description = "Take this enchanted nethervine crystal and make your way back to Dragonmaw Fortress. Once there, seek out the enslaved drakes and invoke the magic of the nethervine crystal. My own energies will pour forth, causing the drakes to break free from the bond of their captors. When you see that the drake has broken free, help it defeat its captor! It will most assuredly be weak from the imprisonment.\n\nRelease all that you can find and return to me, <name>.", progress = "Waste no time, we have much work to do!", completion = "&lt;Neltharaku laughs.&gt;\n\nThe orcs must have been shocked to see the drakes turn on them in such a manner. Well done, &lt;name&gt;. Perhaps you truly are the hero of our flight.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10855] = {title = "Fel Reavers, No Thanks!", objective = "Obtain 5 Condensed Nether Gas from Gan'arg Mekgineers at Forge Base: Oblivion, northwest of the Stormspire, and load them into a nearby Inactive Fel Reaver. Return to Nether-Stalker Nauthis after you've completed this task.", description = "Ah, yes - the fel reaver!  Certainly the Legion's most terrible mechanical creation.  There are no less than three of these abominations aimed at the Stormspire.\n\nFortunately for us, they are not active yet.  This affords us the possibility of dealing with them through sabotage instead of brute force.\n\nObtain condensed nether gas from the gan'arg at Forge Base: Oblivion and fill a nearby fel reaver's fuel tank with it.  I've a feeling its engine won't handle it too well.", progress = nil, completion = "That is excellent news, &lt;name&gt;.  Now that we know how to deal with these, I can have hirelings sabotage any remaining reavers.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10856] = {title = "The Best Defense", objective = "Nether-Stalker Nauthis wants you to slay 12 Wrathbringers at Forge Base: Gehenna, north of the Stormspire.", description = "Brave acts of industrial sabotage will only get us so far, <name>.  Just as Forge Base: Oblivion serves as an assembly site for Fel Reavers, Forge Base: Gehenna serves as a staging ground for their army as it is where the majority of the Legion's teleportation devices are located.\n\nI want you to go in there and put a dent in their numbers.  They must have a full regiment of wrathbringers by now and we just can't allow that.", progress = "How goes it?  Did you get a chance to show the Legion a lesson or two?", completion = "Nice work, &lt;name&gt;.  Keep it up and I'll put in a good word with the Nexus-Prince.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10857] = {title = "Teleport This!", objective = "Nether-Stalker Nauthis wants you to use the Mental Interference Rod on the Mo'arg at Forge Base: Gehenna and use their Detonate Teleporter ability on the three teleporters in the forge camp.", description = "As fun as killing demons might be, it does us little good when the Legion can keep using its teleporters to replace anything we kill.\n\nUnfortunately, I don't have any high-powered explosives handy... but the mo'arg that maintain the teleporters do.\n\nTake this rod... I've tuned its powers to interfere with mo'arg brain frequencies.  Return to Forge Base: Gehenna and use it on any mo'arg you see.  You won't have long, but you'll be able to use their demolition charges on the nearby teleporters.", progress = "Is it done then?  Are the teleporters shut down?", completion = "Thanks to you, &lt;name&gt;, I'll breathe a little easier.  Figure of speech, of course!\n\nI suppose you'll want some form of reward now.", rewards = "You will be able to choose one of these rewards:\n\nSaboteur's AxeRuned Silver StaffNether-Stalker's BladeImbued Draenethyst Crystal\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10858] = {title = "Karynaku", objective = "Seek out Karynaku at Dragonmaw Fortress.", description = "It shames me to ask for your assistance once more, <name>, but you are my flight's only hope. Without my mate, the netherwing brood may die out completely.\n\nMake your way to the top of Dragonmaw Fortress and find Karynaku.\n\nWe will be flying overhead. Should a break appear in their defenses, the might of the netherwing will swoop down to assist you.", progress = nil, completion = "It is the chains. They sap my power. The only way is to get the key from Zuluhed and unbind me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10859] = {title = "Gather the Orbs", objective = "Spiritcaller Dohgar has asked you to use the Orb Collecting Totem to collect 15 Razaani Light Orbs. Return to him at Mok'Nathal Village in the Blade's Edge Mountains after you have done so.", description = "The Razaani ethereals have strange devices that emit small, pink floating light orbs.  They remind me of souls.\n\nThey are not to be confused with the large yellow balls that break free of the ethereal when they die, these are something else entirely.\n\nI'd like for you to head north to Razaan's Landing and drop some totems, which will attact the pink light orbs.\n\nBring them back to me so that I might determine exactly what they are.", progress = "Have you collected all of the Razaani Light Orbs that are needed?", completion = "Something does not feel right.\n\nPlease, &lt;name&gt;, hand me the totem.  I must examine those orbs!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10860] = {title = "Mok'Nathal Treats", objective = "Matron Varah has given you a list of ingredients for the making of her two favorite dishes, which includes the collection of 3 Raptor Ribs and 3 Serpent Flesh. Bring them to her at Mok'Nathal Village in the Blade's Edge Mountains.", description = "Hungry, <race>?  The Great Spirit helps those that help themselves.  If you want to earn a meal, I suggest that you listen up, because Braagor there isn't going to give you anything for free, nor as tasty!\n\nThe raptors and scalewings of Razor Ridge and the Scalewing Shelf have everything that's needed for two of the most delicious dishes you'll ever taste.  Bring me their raptor ribs and serpent flesh, and I'll make some of each for you.\n\nI may even teach you how to cook them up for yourself, if you hurry.", progress = "Have all of the ingredients yet?  Talking about it with you has made my mouth water!", completion = "Mmm, I can taste them already.  Quickly, hand over those parts... I'm going to get them diced up and onto the fire!\n\nLuckily for you, this stuff keeps, and I mean for a long time!  So, take these, and I suppose you can have the recipes as well for being so kind as to restock my larder.", rewards = "You will receive:\n\nMok'Nathal ShortribsCrunchy SerpentRecipe: Mok'Nathal ShortribsRecipe: Crunchy Serpent"}
MultiLanguageQuestData['en'][10861] = {title = "Veil Lithic: Preemptive Strike", objective = "Break the cursed eggs in Veil Lithic. Redeem 3 Hatchlings and slay 3 Malevolent Hatchlings before returning to Kirrik at the Refugee Caravan.", description = "In the wretched colony to the southwest known as Veil Lithic, Terokk's minions are attempting to befoul their avian brethren before they hatch. The dark sorcerers of Lithic encase eggs in a shadowy curse. When the hatchlings emerge, they mindlessly serve Terrok.\n\nTravel to Veil Lithic and prematurely break the eggs before the curse has time to seep in. Even if you are too late, you can put down the tainted ones.\n\nRemember, the Light shines brightest in the darkness.", progress = "Have you done your bidding? Quash the evil before it is too late!", completion = "It is grim work toiling with someone's hatchlings, yet ignoring the brewing evil would be a bleak proposition as well. You have done well.  A'dal's favor shines upon your heart.", rewards = "You will be able to choose one of these rewards:\n\nFeathered ArmbandsFeathered Wrist CuffsEagle Engraved BracersTalonstalker Bracers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10862] = {title = "Surrender to the Horde", objective = "Rokag wants you to seek out Rilak the Redeemed in Shattrath and demand that he and his people surrender to the Horde.", description = "The cowardly arakkoa attack us daily.  They ambush our hunters and sometimes even raid inside our walls.  We kill them when we can, but their magic is strong and they often escape our warbands.  \n\nI have learned that some arakkoa claim to be friendly with the Horde.  They live in Shattrath City to the northwest.  Rilak the Redeemed is their leader.  Search for him in the Lower City, and when you find him, demand his surrender.", progress = nil, completion = "Your people are angry but there is little I can do.  Some of us have been touched by the power of the naaru and we are forever changed.  Those of us who remain in the wild are as we have always been.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10863] = {title = "Secrets of the Arakkoa", objective = "Lady Dena Kennedy wants you to seek out Rilak the Redeemed in Shattrath and find out what secrets he will share of the Arakkoa.", description = "Out here on the frontier we have to deal with the arakkoa every day.  They strike at us when they please, raiding our supply lines and killing our scouts.  \n\nYet we know very little about these enigmatic creatures.  I have received news that northwest of here in Shattrath City there are arakkoa who are not hostile.  They might be willing to share the secrets of their race.  \n\nRilak the Redeemed is their leader.  He resides in the northern part of the Lower City.", progress = nil, completion = "You are wise to find me.  There is much that I can show you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10864] = {title = "A Burden of Souls", objective = "Kill 20 Shattered Hand orcs, then return to Apothecary Antonivich in Thrallmar.", description = "I have a device, the Demoniac Scryer, that can analyze fel magic.  I would have you use the Scryer, but first... you must appease it.  The Scryer, you see, has trapped within it a creature of vast intelligence and its needs are, shall we say, quite eccentric.\n\nTo appease the Scryer, you must kill orcs.  Specifically, they must be Shattered Hand orcs -- the Scryer demands their souls.\n\nReturn to me when the souls are reaped.  You will find the orcs north, and south, and surrounding... Hellfire Citadel.", progress = "The Demoniac Scryer is not yet appeased, <name>.  Return to me after you have reaped the souls of Shattered Hand orcs.", completion = "Well done, &lt;name&gt;.  Your soul is burdened with many deaths... and the Demonaic Scryer will now perform its duties for you.\n\nLet us hope you are ready for the coming trial...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10865] = {title = "Inform Leoroxx!", objective = "Spiritcaller Dohgar has implored you to inform Leoroxx about what the Razaani ethereal are up to. He can be found at Mok'Nathal Village in the Blade's Edge Mountains.", description = "Quickly, you must inform Leoroxx of what is transpiring up at Razaan's Landing!\n\nThose orbs were comprised of souls, some of them Mok'Nathal!", progress = nil, completion = "What you say, is it even possible?  What am I saying?  Of course it is, if the spiritcallers say so.\n\nRemember before when I said that we might need your further assistance?  It would seem that I can tell the future.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10866] = {title = "Zuluhed the Whacked", objective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10867] = {title = "There Can Be Only One Response", objective = "Leoroxx has beseeched you to retrieve the Collection of Souls and return them to Spiritcaller Dohgar at Mok'Nathal Village in the Blade's Edge Mountains.", description = "There can be only one response to this... this, DEFILEMENT of the souls of our ancestors!\n\n<name>, if you would aid us to restore the souls of our honored dead to their rightful place, go back to Razaan's Landing.\n\nGo back up there and kill the razaani until their leader, Nexus-Prince Razaan shows his cowardly face.  Kill him and get those souls back, and then give them over to Spiritcaller Dohgar!", progress = "Have you done it?  Are the souls of our ancestors safely recovered from the evil of the ethereals?", completion = "Good that the ethereal filth and their leader are dead.  I wish a thousand plagues upon their brethren!\n\nYou are to be rewarded for you actions on behalf of all of the Mok'Nathal, &lt;name&gt;!  You are truly one of our heroes.\n\nLet us now release the souls of our ancestors to the cleansing fire.", rewards = "You will be able to choose one of these rewards:\n\nMok'Nathal MantleSpiritcaller's MaskMok'Nathal Hero's PantaloonsBelt of the Soul Saver\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10868] = {title = "Arakkoa War Path", objective = "Advisor Faila asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to her in Stonebreaker Hold.", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could charge out to meet them in numbers.  They use their summoning circles to rescue their warriors from certain death but they cannot run from us if we attack their homes.  Veil Reskk and Veil Shienor lie to the north and northeast.  \n\nFind these arakkoa nests and kill as many as you can.", progress = nil, completion = "Well done &lt;class&gt;.  The arakkoa have learned to fear the might of the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10869] = {title = "Thin the Flock", objective = "Lieutenant Gravelhammer asks that you kill 14 Shienor Talonites and 6 Shienor Sorcerers and then return to him in Allerian Stronghold.", description = "The arakkoa have attacked us again, this time striking in the night and then using their dark magic to escape before we could marshal our soldiers.  \n\nVeil Reskk and Veil Shienor lie to the north and northwest.  Find these arakkoa nests and kill as many as you can.  They may not fear us, but at least we can thin their numbers.", progress = nil, completion = "Well done &lt;class&gt;.  The arakkoa have learned to fear the might of the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10870] = {title = "Ally of the Netherwing", objective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", progress = nil, completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", rewards = "You will be able to choose one of these rewards:\n\nNetherwing Protector's ShieldNetherwing Defender's ShieldClaw of the Netherwing FlightNetherwing Spiritualist's CharmNetherwing Sorceror's Charm\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10871] = {title = "Ally of the Netherwing", objective = "Let Karynaku return you to Mordenai in the Netherwing Fields.", description = "Allow me to return you to Mordenai. I am certain that he wishes to see you once more.", progress = nil, completion = "You have proven yourself as an ally of the Netherwing. My mother is free and my brothers and sisters are saved!\n\nPerhaps someday, we will call for you again. When that day comes, know that you will be welcomed with open arms - a brother to the Netherwing Dragonflight.", rewards = "You will be able to choose one of these rewards:\n\nNetherwing Protector's ShieldNetherwing Defender's ShieldClaw of the Netherwing FlightNetherwing Spiritualist's CharmNetherwing Sorceror's Charm\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10872] = {title = "Zuluhed the Whacked", objective = "Kill Zuluhed the Whacked and recover Zuluhed's Key. Use Zuluhed's Key on Zuluhed's Chains to free Karynaku.", description = "He hides in my thoughts, mortal. He waits for me to break... for me to bend to his will.\n\nAnd this will be his undoing. I will call for him. I will tell him that I will do as he asks. When he appears, kill him and take the key!\n\nKnow this: Zuluhed is an ancient orc with unknown powers. He has surely been empowered further by Illidan. You risk your life for me in doing as I ask. Are you certain you wish to make such a sacrifice?", progress = "<Karynaku groans.>", completion = "I am free! You have saved us, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10873] = {title = "Taken in the Night", objective = "Scout Navrin wants you to travel to the Netherweb Ridge and free 6 Webbed Sha'tar Warriors and then return to him at Sha'tar Outpost.", description = "Our small outpost is under constant attack. Several nights ago, we were raided by the spiders of Netherweb Ridge, on the southeastern edge of the Bone Wastes. They poisoned many of our people, wrapped them in webs and carried them away. Some of our warriors took up arms and with little preparation pursued the spiders.\n\nWe have not seen the captives or our hunting parties since. We hope that some may still be alive, perhaps imprisoned by the spiders.  Our numbers are few. Will you search for our people?", progress = "Did you find our missing people?", completion = "You saved so many.  I didn't think we would ever see them again.  We cannot thank you enough, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10874] = {title = "Veil Shalas: Signal Fires", objective = "Kirrik at the Refugee Caravan wants you to extinguish the four signal fires of Veil Shalas.", description = "Terokk's perch, Skettis, looms above the Bone Wastes to the east. At the base of Skettis lies Veil Shalas, the most formidable of Terokk's colonies. It is through the stronghold of Veil Shalas that Terokk's forward sages wage war against the Light.\n\nThe evil-doers of Shalas communicate with their master using a complex system of magical signal fires. Travel to the east, <race>, and extinguish the fires. Once Veil Shalas is silenced, we can begin to plot the fall of Skettis.\n\nBut I get ahead of myself.", progress = "Veil Shalas must be silenced!", completion = "We witnessed the cursed smoke rise from here. You are most brave, &lt;class&gt;.", rewards = "You will be able to choose one of these rewards:\n\nArakkoa Sage's ShawlCloak of Grasping TalonsKokorek's Signet\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10875] = {title = "Report to Nazgrel", objective = "Speak with Nazgrel in Thrallmar.", description = "<name>, during your foray with the Demoniac Scryer, I sent word of your exploits against the fel orcs.  Nazgrel, our illustrious leader in Thrallmar, wishes to speak with you.  I believe he has a bloody mission in mind...", progress = nil, completion = "It is good to hear of all your moves against the fel orcs, &lt;name&gt;.  The apothecaries have spent much time and resources studying the cause of their corruption, and although such information in invaluable... my orc blood burns to strike a severe blow against these betrayers!\n\nListen close, and I will explain my task...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10876] = {title = "The Foot of the Citadel", objective = "Kill Force Commander Gorax, place the Challenge From the Horde upon his corpse, kill The Hand of Kargath, and then bring the Head of the Hand of Kargath to Nazgrel in Thrallmar.", description = "Force Commander Gorax is training Shattered Hand captains at the base of Hellfire Citadel, honing them to a bloody razor's edge.  You must kill him, <name>, for his loss would be a mighty blow to the fel orcs.\n\nHowever, that is not all you must do.\n\nTake this banner.  Place it atop Gorax's corpse.  Gorax's commander, the Hand of Kargath, must answer your challenge if he has even a drop of true orc blood within him!\n\nHis head, the head of the hand of Kargath, is what I seek.", progress = "Have you faced the Hand of Kargath, <name>?", completion = "You have done a great deed, &lt;name&gt;.  The fel orcs are a shame to all true orcs.  If we have one fear, it is the fear of  succumbing to demonic corruption once again.  So you see, our war against the fel orcs is more than merely a battle with fierce foes -- it is also a battle within ourselves.\n\nAnd with strength, strength you have shown time again, it is a battle we will win.", rewards = "You will be able to choose one of these rewards:\n\nStormstrike VestShadowcast TunicDarkstorm TunicBattlemaster's Breastplate\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10877] = {title = "The Dread Relic", objective = "Oakun wants you to travel east to the Derelict Caravan to recover the Dread Relic. Return to Oakun when the task is complete.", description = "Long ago a caravan went to Auchindoun with a mission to take a Dread Relic from the ancient tombs beneath the necropolis. They fled, but the relic was their undoing.  The relic is evil and it summons evil when touched.   Their caravan was destroyed somewhere to the east. \n\nThis dark artifact is the key to a terrible plan to defeat Teribus the Cursed, a creature that flies over the Bone Wastes.  Help me if you wish, but your life and even your soul will be at risk.", progress = "Do you have the Dread Relic?  We must have it.", completion = "It is incredible that you succeeded.  The Dread Relic is far more powerful than I feared. Only a mighty hero could have survived the long journey back carrying such blasphemous evil.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10878] = {title = "Before Darkness Falls", objective = "Mekeda at the Refugee Caravan in Terokkar Forest wants you to kill 8 Cabal Skirmishers, 4 Cabal Spell-Weavers and 2 Cabal Initiates.", description = "After our caravan fell prey to an attack by Shadow Council cabal cultists, scouts were sent to Shattrath to call for help.  The guards think we're safe for now, but they underestimate these madmen.\n\nI, for one, am not looking forward to having my throat slit by some cabal initiate in the middle of the night.  Do us all a favor and take the fight to them, before they come to us.\n\nYou will find our attackers south of here, at Auchindoun's northern entrance.", progress = "Have you done what I asked of you, <name>?  I fear for our lives.", completion = "I can breath a sigh of relief for now, &lt;name&gt;.  The Shadow Council will be held off for the time being.\n\nThey are murderers and cowards and your display of courage will keep them at bay.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10879] = {title = "The Skettis Offensive", objective = "Hold off the attackers and speak with Rilak.", description = "Skettis has waged war on us! Have you gathered enough to help with Shattrath's defense?\n\nHold off the attackers!", progress = "This is no time for idle chatter, <name>. We're under attack! Hold off the invaders!", completion = "I applaud your prowess in combat, &lt;class&gt;. You have proven yourself to be a true defender of the Light. May A'dal's blessing shine upon your darkest hours.\n\nBut look far into the horizon. Dark skies loom above Skettis. Terokk is undoubtedly plotting his next move. Shattrath is safe for now. But only tomorrow knows what terror will descend upon us.", rewards = "You will be able to choose one of these rewards:\n\nChoker of Bloodied FeathersNecklace of Bloodied Feathers\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10880] = {title = "Cabal Orders", objective = "Bring the Cabal Orders to Mekeda at the Refugee Caravan in Terokkar Forest.", description = "This message bears a dark seal and though the language seems somewhat familiar, it appears to be encoded.\n\nPerhaps someone at the Refugee Caravan will know something about it.", progress = "You wish to show me something, <name>?", completion = "Ah, yes... this was written in a basic form of the shadow cypher.  My knowledge of it is not perfect but it should suffice to translate this.\n\nYou learn much about unsavory subjects when you live among outcasts and refugees in the Lower City.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10881] = {title = "The Shadow Tomb", objective = "Go into the Shadow Tomb, west of the Refugee Caravan and retrieve the Drape of Arunen, the Gavel of K'alen and the Scroll of Atalor. Return to Mekeda at the Refugee Caravan after you've completed this task.", description = "Many believe it was the Shadow Council that caused the explosion that tore Auchindoun apart.  It is rumored they awoke a great evil inside.\n\nIf that is true, then that evil must have turned against them.  According to these orders, part of the Shadow Council is fleeing Auchindoun.  They are using the Shadow Tomb to store powerful artifacts from Auchindoun.\n\nThree of these are sacred, for they belonged to the powerful patriarchs Arunen, K'alen and Atalor.  I must ask you to retrieve them.", progress = "Have you retrieved the relics, <name>?  We cannot allow the Shadow Council to use their power for dark purposes.", completion = "The Light might have forgotten me, but I have not forgotten the Light.  These relics were once very sacred to my people.\n\nAllowing the Shadow Council to use their power for evil is... unthinkable!", rewards = "You will be able to choose one of these rewards:\n\nHeirloom Signet of ConvalescenceHeirloom Signet of ValorHeirloom Signet of Willpower\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10882] = {title = "Harbinger of Doom", objective = "You have been tasked to go to Tempest Keep's Arcatraz satellite and slay Harbinger Skyriss. Return to A'dal at the Terrace of Light in Shattrath City after you have done so.", description = "<A discordant note can be detected in A'dal's 'voice'.>\n\nPrince Kael'thas has chosen his warden poorly, and now the entities that we kept locked up within the Arcatraz are breaking free.\n\nOne in particular, a servant of the Old Gods known as Harbinger Skyriss, seeks to usher in his masters' vision of conquering all of the worlds in the universe.\n\n<name>, you must not allow him to escape.  Return to Tempest Keep, enter the Arcatraz, and slay Harbinger Skyriss before it is too late!", progress = "<A'dal focuses his attention upon you, his gaze almost unbearable.>\n\n<name>, perhaps you do not understand the magnitude of your mission?  There is no time to waste... gather yourself a group of compatriots and enter the Arcatraz.\n\nPut an end to Harbinger Skyriss.", completion = "&lt;The crystalline timber of A'dal's voice carries a more tranquil melody within your mind than the last time the two of you spoke.&gt;\n\nOnce again you have proven your mettle.  Had Harbinger Skyriss broken free, countless thousands would have perished in the ensuing conflict, just as happened with another servant of the Old Gods, Skeram, on your world of Azeroth.\n\n&lt;name&gt;, what I have to offer in return may seem a pittance in comparison, but know that it comes with the everlasting gratitude of the Sha'tar.", rewards = "You will be able to choose one of these rewards:\n\nPotent Sha'tari PendantA'dal's Recovery NecklaceShattrath Choker of Power\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10883] = {title = "The Tempest Key", objective = "Speak with A'dal in Shattrath City.", description = "You have proven yourself capable of great feats, <name>. Your discovery of the Cipher of Damnation and Kael'Thas' involvement is most important to our cause. Should Kael use the cipher, what little is left of this world may collapse.\n\nA'dal is convinced that Kael must be stopped and now seeks adventurers willing to undergo trials. Those that prove their strength will be granted favor by the naaru.\n\n<Khadgar nods.>\n\nA'dal awaits...", progress = nil, completion = "Tempest Keep is a naaru creation, mortal. Access to the vessel has always been within our power to grant. A return to Tempest Keep, though, had been deemed unnecessary. A point of pride for a mortal race, perhaps, but naaru invest little in such things.\n\nWe go now because we must. Kael'thas cannot be allowed to utter the words of damnation.\n\nWhile the way is open, only a fool would enter unproven. Do not underestimate the purpose of the trials, mortal.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10884] = {title = "Trial of the Naaru: Mercy", objective = "A'dal in Shattrath City wants you to recover the Unused Axe of the Executioner from the Shattered Halls of Hellfire Citadel.\n\nThis quest must be completed in Heroic dungeon difficulty.", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nWithin the Shattered Halls of Hellfire Citadel are three of your people. They are held there by the merciless one, Kargath Bladefist. He seeks to execute them as a sign of his virility and power. You must save these prisoners before such an atrocity can come to pass. As proof of deed, bring me the unused axe of the executioner. It must not have a drop of blood on its blade!", progress = "<A'dal greets you.>", completion = "Well done, &lt;name&gt;. You have passed the trial of mercy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10885] = {title = "Trial of the Naaru: Strength", objective = "A'dal in Shattrath City wants you to recover Kalithresh's Trident and Murmur's Essence.\n\nThis quest must be completed in Heroic dungeon difficulty.", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nThe trial of strength is divided in two. You must destroy the leader of the Coilfang Steamvaults, Warlord Kalithresh, and bring me his trident. Slay the extra-planar being known as Murmur, in the Shadow Labyrinth of Auchindoun, and bring me his essence.\n\nDo this and you will have passed the trial of strength.", progress = "<A'dal greets you.>", completion = "Well done, &lt;name&gt;. You have passed the trial of strength.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10886] = {title = "Trial of the Naaru: Tenacity", objective = "A'dal in Shattrath City wants you to rescue Millhouse Manastorm from the Arcatraz of Tempest Keep.\n\nThis quest must be completed in Heroic dungeon difficulty.", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nIn our travels we have encountered many dangerous beings. Some of these beings we incarcerated and placed in what is now known as the Arcatraz of Tempest Keep.\n\nThere is one prisoner, however, that is a victim of circumstance. A stowaway who was in the wrong naaru vessel at the wrong time.\n\nVenture to the Arcatraz and rescue the gnome, Millhouse Manastorm. Ensure his survival.", progress = "<A'dal greets you.>", completion = "Well done, &lt;name&gt;. You have passed the trial of tenacity.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10887] = {title = "Escaping the Tomb", objective = "Help Akuno find his way to the Refugee Caravan in Terokkar Forest. Speak to Mekeda after you've completed this quest.", description = "I appreciate your help, <name>.  I was certain I was going to be killed.\n\nLet's get out of here with a hurry.  It won't be long before more cultists come after us.", progress = nil, completion = "You rescued Akuno, a dear friend of mine.  For this I am in your debt, &lt;name&gt;.", rewards = "You will be able to choose one of these rewards:\n\nAkuno's BladeAncient Draenei CrestMekeda's GiftUnearthed Orb\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10888] = {title = "Trial of the Naaru: Magtheridon", objective = "A'dal in Shattrath City wants you to slay Magtheridon.", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", progress = "<A'dal greets you.>", completion = "You have proven yourself as a being of great power. The naaru approve...", rewards = "The following spell will be cast on you:\n\nCreate Tempest Key\n\nYou will receive:\n\nPhoenix-fire Band"}
MultiLanguageQuestData['en'][10889] = {title = "Return to Shattrath", objective = "Travel to Shattrath City and speak with Rilak.", description = "Your actions, while brave, will surely rouse a vindictive response from Terokk.\n\nHurry to Shattrath. Send word to Rilak!", progress = nil, completion = "The guardians of Skettis grow restless from their perch. Shattrath is in trouble. We will surely feel the brunt of Terokk's revenge.\n\nMuster a defense party quickly! Speak with Defender Grashna and let him know you are ready to bear arms against our attackers!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10891] = {title = "Imperial Plate Armor", objective = "Speak with Derotain Mudsipper in Gadgetzan.", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", progress = nil, completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10892] = {title = "Imperial Plate Armor", objective = "Speak with Derotain Mudsipper in Gadgetzan.", description = "There's a dwarf in Gadgetzan by the name of Derotain Mudsipper who'll teach you how to make imperial plate armor. All you gotta do is get to the Tanaris desert and find him. Interested?", progress = nil, completion = "Of course I'll teach you how to make imperial plate armor! It might cost you a bit of gold... in the form of thorium bars!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10893] = {title = "Longtail is the Lynchpin", objective = "Eliminate Draaca Longtail, the leader of the wyrmcultists in Wyrmskull Tunnel. Report back to Watcher Moonshade at the Wyrmskull Tunnel in the Blade's Edge Mountains once you have done so.", description = "With the Blackwing wyrmcultists massing in the tunnel, we're hard pressed to deal with the situation.  Quite frankly, they have the numbers.\n\nAnd while we've been able to take care of any of their people that get too close, the fact remains that if they attack in earnest, we're going to be overrun.\n\nThe situation calls for someone to get through to the other end of the tunnel, and take out their leader, Draaca Longtail.  Up for some fun?", progress = "Is she dead?\n\n<name>, if we're to have a fighting chance here, we need you to sow confusion into their ranks by killing Draaca Longtail!", completion = "With Draaca out of the picture, we should be able to take advantage of the situation.  They'll be in-fighting over who should be in charge, and that will relieve some of the pressure.\n\nThat is, unless the overseer mentioned in that note you gave me comes to take her place.\n\nLet's see if you can do something to make sure that never happens!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10894] = {title = "Wyrmskull Watcher", objective = "Deliver the Meeting Note to Watcher Moonshade at the entrance of the Wyrmskull Tunnel in the Blade's Edge Mountains.", description = "Hmm, I'm not certain what we should do.  I'm not much of a military planner.\n\nWatcher Moonshade will know what to do.  He's heading up our defensive efforts at the Wyrmskull Tunnel to the west at the end of Wyrmskull Bridge.  We have a force out there just in case the cultists try anything funny.\n\nPlease, take the note to him with all due haste.", progress = "How can I help you?  You bring news from Evergrove?", completion = "It's as I thought, and that's not good!\n\nI've got an idea for how to help you, but first, I was wondering if you might help us out?\n\nYou scratch my back, I'll scratch yours.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10895] = {title = "Zeth'Gor Must Burn!", objective = "Use the smoke beacon at each of Zeth'Gor's towers, and then return to Wing Commander Dabir'ee at Expedition Point.", description = "It's time to strike Zeth'Gor from the air!  Our gryphon riders are ready for a sortie, <name>.  But they need someone on the ground to direct their fire.  Are you ready for a covert mission?\n\nTake these smoke beacons into Zeth'Gor, the Bleeding Hollow stronghold to the west.  They have four guard towers: one near their northern wall, one near their southern wall, one near their forge and another nestled in their foothills.  Place a beacon underneath each of the towers and we'll fly in and bomb them!", progress = "Time is crucial, <name>.  We need those guard towers burned!", completion = "I could see the smoke and flames from here!  Good job, &lt;name&gt;!  You received more than a few words of praise from our gryphon riders -- what you just did took a lot of guts...", rewards = "You will be able to choose one of these rewards:\n\nBonechewer Berserker's VestGoldweave TunicSacred Feather VestGilded Crimson ChestplateJerkin of the Untamed Spirit\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10896] = {title = "The Infested Protectors", objective = "Lakotae wants you to kill 25 Wood Mites and then return to him at the Refugee Caravan. The mites can be found living inside the bodies of Rotting Forest-Ragers and Infested Root-Walkers.", description = "The trees of this land are ravaged by the power that was unleashed from Auchindoun.  The foul magic that was unleashed blasted the land into the wastes you see all around.  The trees that survived are now infested with wretched wood mites that crawl under their bark and gnaw at their flesh.  \n\nRotting forest-rages and infested root-walkers are breeding grounds for the mites.  They are found along the edge of the wood to the east.  Destroy these creatures and then kill the mites that flee their husks.", progress = "Have you destroyed the worst of the infestations?", completion = "You have done much to help Terokkar Forest, &lt;name&gt;.  With the worst of the mite colonies destroyed we may yet be able to reclaim this wasted land.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10897] = {title = "Master of Potions", objective = "Lauranna Thar'well wants you to go to the Botanica in Tempest Keep and retrieve the Botanist's Field Guide from High Botanist Freywinn. In addition she also wants you to bring her 5 Super Healing Potions, 5 Super Mana Potions and 5 Major Dreamless Sleep Potions.\n\n*WARNING!* You can only select one alchemy specialization.", description = "As you know, plants have properties that allow alchemists to re-energize and reinvigorate others through potions.\n\nMy familiarity with the plants of Outland allows me to teach alchemists how to make the most out of them.  If you're interested in expanding your knowledge of potions, I have but one task to ask of you.\n\nHigh Botanist Freywinn in Tempest Keep is rumored to have written a comprehensive botany guide.  Bring it to me along with samples of your work and I'll teach you the knowledge you seek.", progress = "Are you sure about this, <name>?  Specializing in potions will prevent you from pursuing other specializations.", completion = "Excellent!  It looks like you're eager to learn, so let's get to it.  I will teach you how to make the most out of the plants you use in your alchemical potions.\n\nYou will find that you can make herbs go a really long way if you know what you're doing.  Sometimes you will be able to make two potion with materials you initially judged necessary for just one.", rewards = "You will learn:\n\nPotion Master\n\nThe following spell will be cast on you:\n\nPotion Master\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10898] = {title = "Skywing", objective = "Escort Skywing and report to Rilak the Redeemed in Shattrath City.", description = "Skywing flutters around you.\n\nYou get the feeling he wants you to follow him.", progress = nil, completion = "Alas, poor Skywing was under the dreaded curse of Luanga the Imprisoner!\n\nSkywing traveled to Veil Shalas to attempt to sway others in seeing the way of the Light. They didn't take lightly to his actions, especially sitting on the doorstep of Skettis.\n\nLuanga was one of Terokk's most feared agents. You have done well by freeing Skywing! I thank you.", rewards = "You will be able to choose one of these rewards:\n\nSkywitch HatRedeemer's PlateStillfire Leggings\n\nYou will also receive:\n\nMiniwing"}
MultiLanguageQuestData['en'][10899] = {title = "Master of Transmutation", objective = "Zarevhi at the Stormspire in Netherstorm wants you to bring him 4 Primal Mights.\n\n*WARNING!* You can only select one alchemy specialization.", description = "Any alchemist will tell you that matter is malleable, any substance can be transformed into another - but nothing is really created or destroyed.\n\nA true master of transmutation can learn to overcome this limitation - and I can teach you how to obtain this mastery!\n\nAs a prospective transmuter you're undoubtedly familiar with primal might - the combination of the material representation of all primal forces.  Show me proof of your transmuting prowess and I will share my knowledge with you.", progress = "Are you sure you want to become a master transmuter?  If you specialize in this field you will find it impossible to specialize in potions or elixirs.", completion = "Excellent work, &lt;name&gt;!  These transmutations are perfect in every way!\n\nI will now teach you the manner in which the alchemical transmutation process can conjure matter out of thin air!  Make good use of your knowledge, master transmuter.\n\nNow, if you'll excuse me, I have to go see a buyer interested in primal might.", rewards = "You will learn:\n\nTransmutation Master\n\nThe following spell will be cast on you:\n\nTransmutation Master\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10900] = {title = "The Mark of Vashj", objective = "Burn it down, <race>. Burn it all down! They deserve nothing! Do you hear me! NOTHING! They must pay for what they have done. For what they continue to do.\n\nI would kill Vashj myself if I could break free of these damned bindings.\n\nOr maybe you seek to do the work of Neptulon? Her death serves both of us, soft-skin. Will you assist me in forming the sacred cudgel.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10901] = {title = "The Cudgel of Kar'desh", objective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10902] = {title = "Master of Elixirs", objective = "Go to the Black Morass in the Caverns of Time and obtain 10 Essences of Infinity from Rift Lords and Rift Keepers. Bring these along with  5 Elixirs of Major Defense, 5 Elixirs of Mastery and 5 Elixirs of Major Agility to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", description = "I've devoted my life to perfecting my elixirs.  Despite my success, I haven't been able to create an elixir of eternal life.\n\nI think I know the reagent I'm missing.  I've heard of a place called the Caverns of Time in Azeroth where intruders known as rift lords and rift keepers phase in and out of the timeline.\n\nThis intrusive time-shifting creates tears in time itself, twisting it infinitely into crystallized essences.  Bring these to me along with samples of your work and I'll teach you all I know.", progress = "The essences!  Do you have them?", completion = "You are very good with elixirs, if these are any indication.  You will make a fine student.\n\nThese essences will provide me enough materials to formulate my recipe.  I will be known among all alchemists for this discovery!\n\nNow, if you're willing to learn, I am willing to teach.", rewards = "You will learn:\n\nElixir Master\n\nThe following spell will be cast on you:\n\nElixir Master\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10903] = {title = "Return to Honor Hold", objective = "Speak with Assistant Klatu, at Honor Hold's inn.", description = "<name>, while you were on your mission in Zeth'Gor, I received news of my commanding officer, Colonel Jules.  He was stricken with a demonic corruption while fighting near the Gor'gaz Outpost, and his situation has grown very bad.\n\nYou have made such great gains for us against the fel orcs.  Your strength in battle is without question... is your spirit just as strong?\n\nPlease, return to Honor Hold and speak with Klatu, in an upper room at the Honor Hold inn.", progress = nil, completion = "Yes, it is true.  Colonel Jules' situation has grown much worse these past days.  Anchorite Barada is busy praying for him... let us hope he may be cured.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10904] = {title = "Harvesting the Fel Ammunition", objective = "The Evergrove Druid has asked you to collect 5 Fel Cannonballs. Once you have done so, use the Druid Signal to call to the Evergrove Druid inside of Death's Door at the Blade's Edge Mountains.", description = "We must shut down the Burning Legion's access to Death's Door, but first you're going to destroy their two warp-gates!\n\nThe problem is, we can't even scratch one of those things, so you're going to need to use their own weapons against them.\n\nThe death's might, death's watch, deathforge over-smiths and deathforge technicians carry the ammunition for the fel cannons.\n\nNormally it wouldn't affect any of them, but if you bring the cannonballs to me, I will imbue them with Nature's unbridled wrath!", progress = "Do you have the cannonballs yet?", completion = "Those things stink more than I thought they would!\n\nQuickly, hand them over to me and I will imbue them with Nature's force such that they will prove extremely deadly to their fel masters and their unnatural creations.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10905] = {title = "Master of Potions", objective = "Speak to Lauranna Thar'well at Cenarion Refuge in Zangarmarsh.\n\n*WARNING!* You can only select one alchemy specialization.", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in potion creation, I would recommend that you seek the help of Lauranna Thar'well of the Cenarion Expedition.\n\nHer knowledge of plants will allow you to make the most of your raw materials.  Look for her in Zangarmarsh and tell her I sent you to her.", progress = nil, completion = "You want me to help you with your study of potions?  Very well, &lt;name&gt;.  Let's see what we can do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10906] = {title = "Master of Elixirs", objective = "Speak to Lorokeem in Shattrath's Lower City.\n\n*WARNING!* You can only select one alchemy specialization.", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in elixir creation, I would recommend that you seek the help of the arakkoa known as Lorokeem.\n\nHis knowledge of elixirs is unmatched, yet he  squanders his skill pursuing an elixir of eternal life.  Find him and see what he can teach you.", progress = nil, completion = "You want to learn from me?  Hmmm, yes.  Perhaps you'll be a suitable student.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10907] = {title = "Master of Transmutation", objective = "Speak to Zarevhi at the Stormspire in Netherstorm.\n\n*WARNING!* You can only select one alchemy specialization.", description = "My knowledge of alchemy is vast.  It is, however, general in nature.  If you wish to specialize, you will have to find others who have narrower fields of study.\n\nIf you wish to specialize in transmutation, I would recommend that you seek the help of the ethereal known as Zarevhi.  He resides in the Stormspire in Netherstorm.\n\nHis mastery of transmutation is... well, outlandish!  See what you can learn from him, but beware - ethereals drive a hard bargain.", progress = nil, completion = "You want me to help you with your study of transmutations?  Very well, &lt;name&gt;.  Let's see what we can do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10908] = {title = "Speak with Rilak the Redeemed", objective = "Kirrik the Awakened wants you to speak with Rilak the Redeemed in the Lower City district of Shattrath.", description = "You look surprised to be talking to me. I do not blame you. My people, the arakkoa, deserve to be feared.\n\nSpeak with Rilak the Redeemed in Shattrath City if you wish to know more. He can be found in the northern part of the Lower City, with the other outcasts of Skettis.\n\nAnd, <name>, we will speak again.", progress = nil, completion = "So we meet, &lt;name&gt;. You must forgive the lack of formalities for time is of the essence.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10909] = {title = "Fel Spirits", objective = "Klatu in Honor Hold wants you to use the Anchorite Relic at Gor'gaz Outpost southwest of Honor Hold, slay Shattered Hand Berserkers near the relic, and then slay 10 released Fel Spirits to avenge Colonel Jules.", description = "Colonel Jules was cursed in a battle near the Gor'gaz Outpost, a haunt for Shattered Hand fel orcs.  My master, Barada, works feverishly to cure the poor human, but he needs help.  The Colonel's tormented spirit seeks peace, and his path to peace is, I fear, a path of vengeance.\n\nTake this anchorite relic to Gor'gaz Outpost.  Place it upon the ground near Shattered Hand orcs and defeat them.  This will release their fel spirits -- you must slay those fel spirits for Jules' own spirit's recovery.", progress = "The fel spirits of the Shattered Hand orcs are a blight to poor Jules' soul.  Tell me, <name>... has he been appeased?", completion = "The Shattered Hand orcs are foul and beyond hope, but my heart is saddened that the road to salvation for Colonel Jules holds such bloodshed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10910] = {title = "Death's Door", objective = "Wildlord Antelarion has implored you to travel to Death's Door. Once you arrive there, use the Druid Signal to call down an Evergrove Druid so that you can speak with them.\n\nProvided item: \n", description = "Now there is an even greater threat from the Burning Legion.  To the south is a portal known as Death's Door, which opens upon the horrific world where the Legion breeds its deadly hounds.\n\nTo get there, exit Evergrove by heading east up the ramp.  Follow the path south, through the Bladed Gulch, Razaan's Landing, Razor Ridge and the Scalewing Shelf.  Then, take the ramp down into the Vekhaar Stand and enter Death's Door through the tunnel, south of Mok'Nathal.\n\nOnce there, use this druid signal.", progress = nil, completion = "It is a relief that Wildlord Antelarion has sent you to us.  The problem is much worse than first we feared!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10911] = {title = "Fire At Will!", objective = "Use the Naturalized Ammunition to take control of the Death's Door Fel Cannons. Use them to destroy both the South Warp-Gate and the North Warp-Gate. Then, use the Druid Signal to call out to an Evergrove Druid to report your success.", description = "Now that the ammunition can affect the Burning Legion, it's time for you to use it.\n\nThere are two warp-gates, which are used for teleportation and enhancement of the void terrors.  One is in the south and the other in the north, and each is within range of a fel cannon.\n\nUse the naturalized ammunition to take control of each fel cannon and destroy the warp-gates.\n\nAttack the gate with artillery to begin, and be prepared to kill its defenders to keep the cannon alive if necessary.", progress = "Have you destroyed both of the warp-gates yet?", completion = "Your prowess is staggering!\n\nVery well, with the warp-gates out of the picture, there's only one thing left to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10912] = {title = "The Hound-Master", objective = "The Evergrove Druid has told you that the final thing you must do is to slay Baelmon the Hound-Master. Afterward, return to Evergrove in the Blade's Edge Mountains, and inform Wildlord Antelarion of your success.", description = "Baelmon the Hound-Master must die!  He maintains the ritual that keeps the portal functioning.\n\nThe Death's Door portal is located at the north end of the canyon.  When you find it, you will find Baelmon.\n\nYou're going to need help on this one, so take this wand.  When you battle the Hound-Master, use it and a couple of my friends will come to your aid.\n\nAfter you have defeated Baelmon, return to Wildlord Antelarion.\n\nAnd, <name>, thank you for all that you've gone through for us here.", progress = "It is over then?  Has the danger at Death's Door been averted?", completion = "You are truly an amazing &lt;race&gt;!  If I thought that we were indebted to you before, then now there is simply no way in which we could ever repay you.\n\nBut we'll give it a try.  Thank you, hero of Evergrove!", rewards = "You will be able to choose one of these rewards:\n\nNatasha's Arcane FilamentNatasha's Battle ChainNatasha's ChokerNatasha's Ember NecklaceNatasha's Guardian CordNatasha's Pack Collar\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10913] = {title = "An Improper Burial", objective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to burn 8 Slain Auchenai Warriors and 8 Slain Sha'tar Vindicators.", description = "Is there nothing that can be done to stem the tide of corruption? My soldiers have been battling the Auchenai for days now with no end in sight. Each casualty, whether Auchenai or Sha'tar, is snatched from the battlefield - their souls lifted and taken to parts unknown.\n\nI will not have it! A proper burial is out of the question but those fiends will not have their souls! Take this torch and travel to the field of battle, directly east of here. Burn every corpse you see! We will not fuel their rituals.", progress = "It's a terrible thing to ask, I know...", completion = "&lt;Commander Ra'vaj holds his head in his hands.&gt;\n\nIt's not enough... It's just not enough.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10914] = {title = "A Hero Is Needed", objective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to slay 12 Auchenai Initiates and 5 Auchenai Doomsayers.", description = "It is not enough. A hero is needed. Our forces are overwhelmed as the Auchenai continue to grow in number.\n\n<Commander Ra'vaj looks at you.>\n\nWill you be the hero? Return to the field of battle and strike at their soldiers. Keep them occupied so that my scouts can get behind their lines and see what they are creating.", progress = "Take no prisoners!", completion = "You've done it, &lt;name&gt;! Because of you, we have made a new discovery...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10915] = {title = "The Fallen Exarch", objective = "Commander Ra'vaj at the Sha'tari Outpost in the Bone Wastes of Terokkar Forest wants you to destroy the contents of the Auchenai Coffin.", description = "They are feeding the souls they steal to a coffin that they have dragged out from the Auchenai Crypts. My scouts believe the contents of the coffin to contain the first exarch of the crypts. They seek to resurrect the ancient one!\n\nYou must battle your way to the western side of Auchindoun and disturb the contents of that coffin before they feed it enough souls. Should you lose your way, follow the walking souls.\n\nDestroy whatever is inside that coffin!", progress = "You must destroy the ancient evil before it has regained its powers.", completion = "Victory is ours! This defeat will set the Auchenai back several weeks.", rewards = "You will be able to choose one of these rewards:\n\nDeath-Speaker's TunicElekk Hide SpauldersSha'tari Marksman's GlovesSha'tari Vindicator's Legplates\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10916] = {title = "Digging for Prayer Beads", objective = "Recover the Draenei Prayer Beads and bring them to Assistant Klatu in Honor Hold.", description = "Anchorite Barada plans to exorcise the corruption from Colonel Jules, and will require an assistant for the task.  Such an assistant must be prepared...\n\nI am ashamed to admit that my prayer beads were lost in Honor Hold's courtyard.  I believe the dog Fei Fei stole them and buried them, but I do not know where.  If you speak with his master, Warrant Officer Tracy Proudwell, perhaps she will know where Fei Fei hides his stolen treasures.", progress = "Have you found the prayer beads, <name>?  Their powers are crucial to many holy rites... including the rite of exorcism.", completion = "You found the prayer beads!  Well done, &lt;name&gt;.  You are a wonder, indeed -- you slay the horrors of Hellfire Peninsula one moment and find lost treasures the next.  Your people truly inspire!\n\nIt is good that you recovered these beads... for they will be invaluable in the exorcism ritual to come.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10917] = {title = "The Outcast's Plight", objective = "Bring 30 Arakkoa Feathers to Vekax in Shattrath's Lower City.", description = "As an outcast, I am marked by death by arakkoa loyal to the city of Skettis.  I cannot leave these walls for fear of my life, but that doesn't mean I cannot strike at them in retaliation.\n\nI have a small cache of treasure that I'm willing to part with, should you help me strike back at my would-be assassins.  Bring me feathers from the denizens of the various Veils of Terokkar as proof of their demise.", progress = "Do you bring the feathers I asked for, <name>?", completion = "&lt;Vekax squawks in glee as you present him with proof of his enemies' demise.&gt;\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.", rewards = "You will receive:\n\nOutcast's Cache"}
MultiLanguageQuestData['en'][10918] = {title = "More Feathers", objective = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", description = nil, progress = "Skettis's lapdogs still keeps a close watch over us, outcasts.  The moment any of us sets foot outside Shattrath we'll be as good as dead.\n\nBring me more feathers as proof of your victory over them.", completion = "&lt;Vekax squawks in glee as you present him with proof of his enemies' demise.&gt;\n\nYes, that will show Skettis that we Outcasts will not take their punishment lying down.  Here is the reward I promised you.  I can arrange for more, should you provide me with additional feathers.\n\n&lt;This quest can be repeated up to Honored reputation.&gt;", rewards = "You will receive:\n\nOutcast's Cache"}
MultiLanguageQuestData['en'][10919] = {title = "Fei Fei's Treat", objective = "Fei Fei looks at you expectantly...", description = nil, progress = "Fei Fei looks at you expectantly...", completion = "&lt;Fei Fei barks happily and grabs the doggy treat.  He looks left and right... deciding where he should hide this new treasure...&gt;", rewards = nil}
MultiLanguageQuestData['en'][10920] = {title = "For the Fallen", objective = "Vindicator Haylen wants you to slay 20 Dreadfang Widows and then return to him just west of Netherweb Ridge.", description = "When the dreadfang widows attacked our outpost we heard the voice of the naaru calling us to battle.  We pursued the creatures into the night.  Some of our people we found dead in the dark, others we could hear struggling against their captors. \n\nBy morning we had come to this place and we fought a fierce battle but we were beaten.  Dreadfang poison will soon take my companions and I cannot last long.  Before I die I must know that the dreadfang widows were beaten.", progress = "I can feel the poison flowing through my veins.  The naaru call to me, I can see the light.  Are the dreadfang widows defeated?", completion = "I heard the sounds of your battle from here, &lt;class&gt;.  The sounds of your victory filled my heart with hope.  If you can win against such terrible odds, perhaps I can find the strength to drag my companions from this terrible place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10921] = {title = "Terokkarantula", objective = "Vindicator Haylen wants you to kill the Terokkarantula and then return to him west of Netherweb Ridge.", description = "You have slain many of the dreadfang widows but they will continue to spawn and soon they will strike at us again.  Deep within Netherweb Ridge is the lair of the Terokkarantula, the brood-mother of these gruesome creatures.  If we are to be safe, she must die.", progress = "Has Terokkarantula been slain?", completion = "The dreadfangs are beaten.  You have killed many and even their foul mother has fallen before you.  I am too poisoned to fight my way to freedom.  \n\nPlease, take some of my equipment.  It will lighten my load and give you the tools you need to make the journey back to Sha'tar Outpost.", rewards = "You will be able to choose one of these rewards:\n\nBlade of RetributionBlessed Signet RingNoble Plate PauldronsBook of Many Blessings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10922] = {title = "Digging Through Bones", objective = "Escort Letoll and his crew and protect them while they make their dig. Return to Dwarfowitz at the Sha'tari Outpost if you succeed.", description = "Oy! You look like you can take care of yerself, <race>. Me and the crew here are looking for a bodyguard to watch over us while we hit a dig site to the north. The pay is pretty good and all you gotta do is make sure no nasty creatures kill me or any of my employees.\n\nIf you successfully make it back without any casualties, Dwarfowitz over there will pay ya.", progress = "You get paid when the job is done, sonny.", completion = "A bone wurm! Fantastic! This may actually be the first time in recorded history that Letoll has actually made a discovery.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10923] = {title = "Evil Draws Near", objective = "Oakun wants you to take the Dread Relic to the Writhing Mound. Once there, kill Auchenai Death-Speakers and Auchenai Doomsayers to collect 20 Doom Skulls. Then find the Writhing Mound Summoning Circle and use the Dread Relic to summon and destroy Teribus the Cursed. Return to Oakun when the deed is done.", description = "Now you must use the Dread Relic in a foul necromantic ritual if you wish to challenge Teribus the Cursed.  To the northeast, beyond Auchindoun, is the Writhing Mound, a place where necromancers gather.  \n\nThe auchenai death-speakers and doomsayers carry doom skulls that are laced with powerful necro-enchantments.  If you collect enough skulls you can use their power along with the power of the Dread Relic to command Teribus to face you.", progress = "Has Teribus the Cursed been purged from the skies of Terokkar?", completion = "A great evil has been cleansed from Terokkar.  The Sha'tar are in your debt.", rewards = "You will be able to choose one of these rewards:\n\nDragonbone GreatswordDragonbone ShouldersDragonbone Talisman\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10924] = {title = "Bloody Imp-ossible!", objective = "Bring 8 vials of Warp Chaser Blood to Sab'aoth at Cosmowrench.", description = "The blood of the warp chasers in this area is a powerful and rare reagent. It's one of my biggest sellers.\n\nNormally, I take my imp, Zeppit, out to help me gather it. Warp chaser blood is simply too caustic to be handled safely by you or I, but it doesn't bother Zeppit.\n\nThings are getting busier here at the shop, so if I send Zeppit with you, will you help gather the blood? Zeppit's attention tends to wander, so you'll need to be close to the chaser when it dies for Zeppit to do his work.", progress = "Did Zeppit cooperate enough for you to get all the blood I'll need?", completion = "This should prove a large enough supply for my needs.\n\nI hope the imp didn't give you too much trouble. He has a bit of a nasty mouth on him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10925] = {title = "Evil Draws Near", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10926] = {title = "Return to Sha'tari Base Camp", objective = "Vindicator Haylen wants you to return to Sha'tari Base Camp and speak with Scout Navrin.", description = "We will not make it back on our own.  The dreadfang poison is too strong. You must return to Sha'tari Base Camp for us.  Scout Navrin will send a rescue party out to find us.", progress = nil, completion = "It is good to know that some of our warriors fought well against the dreadfang widows.  We will send a rescue party immediately.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10927] = {title = "Killing the Crawlers", objective = "Sentinel Moonwhisper at the tunnel between Zangarmarsh and Blade's Edge Mountains wants you to kill 6 Cavern Crawlers and report to Commander Skyshadow in Sylvanaar.", description = "Commander Skyshadow wants this tunnel cleared out so we can expedite trade with the Harborage. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Commander Skyshadow at once!", progress = nil, completion = "Good work, &lt;class&gt;. That tunnel is our lifeline to the swamp.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10928] = {title = "Killing the Crawlers", objective = "Grunt Grahk at the tunnel between Zangarmarsh and Blade's Edge Mountains wants you to kill 6 Cavern Crawlers and report to Tor'chunk Two-claws in Thunderlord Stronghold.", description = "Tor'chunk Twoclaws wants this tunnel cleared out so we can expedite trade with Swamp Rat. I must not leave my post here so I am leaving the task in your hands. Clear the tunnel and report to Tor'chunk Twoclaws at once!", progress = nil, completion = "Good work, &lt;class&gt;. That tunnel is our lifeline to the swamp.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10929] = {title = "Fumping", objective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to bring him 8 Mature Bone Sifter Carcasses.", description = "How would you like to do a little more work for the Explorers' League? These bone worms have us all quite intrigued.\n\nI've got a drum right here that you can use out in the Bone Wastes. Just bang on the damned thing and see what you get. If it's a worm, kill it and bring back the carcass for us to study. We'll need a good lot of carcasses to get a valid testing sample.", progress = "We think the one that popped up at the dig was actually a baby worm!", completion = "Sand gnomes? Yea, sure... The desert can do strange things to a person.\n\nI think we're about to make a breakthrough here with these worms!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10930] = {title = "The Big Bone Worm", objective = "Dwarfowitz at the Sha'tari Base Camp in the Bone Wastes wants you to recover Enormous Bone Worm Organs.\n\nHe wants his Fumper back too.", description = "I was right! These carcasses you brought me belong to the baby bone worms. Do you know what that means? It means that somewhere out there is a big one! I think we can get it to come out if we can provide the right kind of food. Let's see... something big! Yes!\n\nI remember seeing clefthooves east of here on the other side of the Bone Wastes. Get out there and kill a clefthoof. Once it's dead, use the drums. Hopefully the big one will come up to feed. If you manage to kill it, bring me its organs!", progress = "Take a friend with you!", completion = "Amazing! Look at this stuff! The thing-a-ma-whatever has some sort of dust inside its whatcha-ma-bobber. Bah! I won't bore you with all this scientific jargon. I did manage to pull a few teeth from the little ones to make these incredibly sharp knives. Want one?", rewards = "You will be able to choose one of these rewards:\n\nDib'Muad's CrysknifeRevered Mother's CrysknifeShani's Crysknife\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10931] = {title = "Return to the Exodar", objective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10932] = {title = "Return to the Exodar", objective = "Speak with Caedmos at the Exodar.Your master Caedmos of the Exodar has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", description = "Your master Caedmos of the Exodar has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10933] = {title = "Return to Silvermoon", objective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10934] = {title = "Return to Silvermoon", objective = "Speak with Aldrae in Silvermoon City.Your master Aldrae in Silvermoon City has requested to see you. It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", description = "Your master Aldrae in Silvermoon City has requested to see you.  It concerns your training, but I don't really know anything beyond that.Upon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][10935] = {title = "The Exorcism of Colonel Jules", objective = "Speak with Anchorite Barada. Use the prayer beads to help with the ritual, and then speak with Colonel Jules when he is saved. Finally, return to Assistant Klatu.", description = "<name>, it is time to save Colonel Jules.  His condition has worsened and Barada fears that, if we do not cleanse him of his corruption,  he will be lost to us.\n\nTake the prayer beads you found and speak with Anchorite Barada to begin the ritual.  Let no disruptions stop the ritual... and if all goes well, Colonel Jules will be saved.  Speak with Jules when he is saved, then return to me.", progress = "Go to Anchorite Barada, <name>.  He must succeed with his ritual if the colonel is to be saved.", completion = "You have done it, &lt;name&gt;.  You have saved Colonel Jules' soul and cast the darkness within him back to where it came.  A great, noble deed this is!  A hero's day!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10936] = {title = "Trollbane is Looking for You", objective = "Assistant Klatu has informed you that Force Commander Danath Trollbane has been seeking you. Speak to him in the barracks at Honor Hold in Hellfire Peninsula.", description = "While we were busy, a messenger was waiting out in the hall.  I suppose he grew tired, or perhaps he simply ran away at the sight of Jules floating around the room.\n\nEither way, Force Commander Danath is looking for you.  I suggest that you seek an audience with him inside the barracks as quickly as possible!", progress = nil, completion = "It's about time!  I heard all about what you've been up to with that draenei priest. You totally freaked my messenger out!\n\nNow that you're done with that, I have a little mission planned for you to Hellfire Citadel.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10937] = {title = "Drill the Drillmaster", objective = "Force Commander Danath Trollbane has ordered you to kill Drillmaster Zurok with all due haste. Return to the force commander at Honor Hold in the Hellfire Peninsula once the drillmaster is dead.", description = "I'm receiving reports that the Shattered Hand fel orcs, out in front of Hellfire Citadel, are organizing for what looks like an all-out assault.  No doubt, they're not happy about your successes against all of the clans.\n\nGet to the base of the citadel, where the Path of Glory ends.  You'll find the fel orcs busy with their preparations, but you're going to catch them with their pants down.\n\nEliminate the one that's in charge of that force.  Kill Drillmaster Zurok!", progress = "Is the drillmaster dead?  Hmm, maybe my scouts are wrong?", completion = "I wasn't going to believe it until I heard it from you, personally.  Already our scouts are trickling in with information that the Shattered Hand are in disarray without their precious drillmaster to tell them what to do.\n\nYou've traveled a long road, &lt;name&gt;.  I trust that you will accept this armor along with my thanks.  Wear it proudly, you've earned it!", rewards = "You will be able to choose one of these rewards:\n\nStormstrike VestDarkstorm TunicShadowcast TunicBattlemaster's Breastplate\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10938] = {title = "Darkmoon Blessings Deck", objective = "Return the Blessings Deck to the Darkmoon Faire when it comes to town.", description = "Now that you have gathered all of the Blessings cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", progress = "I see that you have managed to complete a deck of Blessings!   Congratulations!", completion = "So you have put together a deck of Blessings.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", rewards = "You will receive:\n\nDarkmoon Card: Crusade"}
MultiLanguageQuestData['en'][10939] = {title = "Darkmoon Storms Deck", objective = "Return the Storms Deck to the Darkmoon Faire when it comes to town.", description = "Now that you have gathered all of the Storms cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", progress = "I see that you have managed to complete a deck of Storms!   Congratulations!", completion = "So you have put together a deck of Storms.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", rewards = "You will receive:\n\nDarkmoon Card: Wrath"}
MultiLanguageQuestData['en'][10940] = {title = "Darkmoon Furies Deck", objective = "Return the Furies Deck to the Darkmoon Faire when it comes to town.", description = "Now that you have gathered all of the Furies cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", progress = "I see that you have managed to complete a deck of Furies!   Congratulations!", completion = "So you have put together a deck of Furies.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", rewards = "You will receive:\n\nDarkmoon Card: Vengeance"}
MultiLanguageQuestData['en'][10941] = {title = "Darkmoon Lunacy Deck", objective = "Return the Lunacy Deck to the Darkmoon Faire when it comes to town.", description = "Now that you have gathered all of the Lunacy cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"   You have heard that this faire alternately stops at Mulgore and Goldshire every few months, so you will have to wait until they are here next.", progress = "I see that you have managed to complete a deck of Lunacy!   Congratulations!", completion = "So you have put together a deck of Lunacy.   Your gesture of returning it to us will create a tie between you and the Darkmoon that will not soon be forgotten.   Allow me to present you with one of the greater Darkmoon cards as a small token of our appreciation.", rewards = "You will receive:\n\nDarkmoon Card: Madness"}
MultiLanguageQuestData['en'][10942] = {title = "Children's Week", objective = "Use the Blood Elf Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item: \n", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, <name>, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", progress = nil, completion = "Hmph, you're my sponsor?  I'm Salandria!  I've been here ever since I was a little baby.  My parents were taken by the war, so I have to live here at the orphanage.\n\nIt's not that bad, but I always wanted to go places -- I haven't ever stepped foot outside of the city.  I've already made a list of all the cool places that I want to go, and the awesome things that I want to do.\n\nI'm ready to go when you are!", rewards = nil}
MultiLanguageQuestData['en'][10943] = {title = "Children's Week", objective = "Use the Draenei Orphan Whistle to call for the ward that you will be looking after during Children's Week.\n\nProvided item: \n", description = "One special little girl is going to be very happy to have you as a friend, even if it is for a short while.\n\nTake this whistle.  With it, you will be able to call for the child that you have agreed to sponsor.  It will only last for a limited time - not much longer than Children's Week itself, in fact.\n\nPlease, <name>, call upon your orphan.  I know that she will be more than excited to meet you and have the opportunity to venture out of the city!", progress = nil, completion = "You must be the adventurer who's going to be my big brother for Children's Week!  I'm Dornaa, pleased to meet you.\n\n&lt;She looks sad for a moment.&gt;\n\nMother and father were killed in the war, and I've lived in the orphanage all my life.  It's nice, actually, but I've always wanted to go places and see things.\n\nI've already made a list of places we could visit, if that's okay?  I just know that we're going to have a great time together!\n\nI'm ready to go when you are!", rewards = nil}
MultiLanguageQuestData['en'][10944] = {title = "The Secret Compromised", objective = "Travel to the Warden's Cage in Shadowmoon Valley and speak to Akama.", description = "Thanks again, <name>.  I recognize your name.  Akama has entrusted you with his plans and so I will trust you as well.\n\nThe naga discovered I was working against Illidan and tried to get me to speak by torturing me.  I did not tell them a thing - Akama himself taught me to master pain through meditation.\n\nIllidan asked the naga to bring me to him.  He would have seen right through my flesh and into my soul's deepest secrets.\n\nAkama must be warned.  Our plans are in jeopardy!", progress = nil, completion = "I thank you, &lt;name&gt;.  Olum is one of my dearest friends and most trusted followers.  His contributions have been of vital importance to our plans.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10945] = {title = "Hch'uu and the Mushroom People", objective = "Take your orphan, Salandria, to Sporeggar in Zangarmarsh. Make sure to call for her if she is not present when you arrive. Then, speak with Hch'uu.", description = "I had a friend named Hch'uu.  She told me that she ended up in the orphanage because she had to run away from an evil fungal giant and got lost.\n\nWe had great fun until her people came and took her away last year.  I think she said she was going to live at a place called Sporeggar.\n\nI'd like to go to see her and have a look at her mushroom village.  The orphan matron told me that it is on the west side of Zangarmarsh, between the Sporewind and Marshlight lakes.\n\nCan we go?  Can we go?  Please?!", progress = "You're the adventurer that brought her here?", completion = "Thank you for this chance to once again see Salandria.  I have missed her so much this past year, but we are still good friends.\n\nWe agreed that when we grow up, we're both going to be brave adventurers, just like you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10946] = {title = "Ruse of the Ashtongue", objective = "Travel into Tempest Keep and slay Al'ar while wearing the Ashtongue Cowl. Return to Akama in Shadowmoon Valley once you've completed this task.", description = "Olum's sacrifice was tremendous.  I would never have asked him to give up his life myself.  But it is done.\n\nIf we're to lure Illidan back into a false sense of security, we need to do his bidding - at least for now.\n\nI command a vast army of Ashtongue, but - aside from the Deathsworn - none can be trusted.\n\nYou are to perform the deed that Illidan demands.  Take this cowl; it is magical in nature.  You will appear to be one of my men to any who see you slaying Kael's phoenix, Al'ar.", progress = "Is the deed done, <name>?  Illidan is not a patient master!", completion = "You've done well, &lt;name&gt;.  This will bring us a step closer to shifting Illidan's focus away from us and from...\n\n\n\nMore work remains to be done, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10947] = {title = "An Artifact From the Past", objective = "Go to the Caverns of Time in Tanaris and gain access to the Battle of Mount Hyjal. Once inside, defeat Rage Winterchill and bring the Time-Phased Phylactery to Akama in Shadowmoon Valley.", description = "Illidan's attention is now on Kael'thas, thanks to you.  The time has come to make our move.\n\nI've had a vision of an artifact that will aid us in our final struggle - the phylactery of a lich known as Winterchill.  Unfortunately its power was lost forever after his defeat in the Battle of Mount Hyjal.\n\nThere might be a way to retrieve this artifact, however.  Legend speaks of a place in Azeroth guarded by bronze dragons...  a place where past and present meet.  It is there you will find what we seek.", progress = "Have you retrieved the phylactery yet, <name>?", completion = "My vision... it all becomes clear now.  The powers this artifact has over a soul.... to contain it... to siphon it into itself... I will use those powers to reclaim what belongs to me!  The time has arrived for us to take the fight to Illidan!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10948] = {title = "The Hostage Soul", objective = "Travel to Shattrath City to tell A'dal about Akama's request.", description = "You might wonder why I go to such lengths to hide my intentions.  Why not throw my lot in openly with the naaru?\n\nMy very essence - my soul - is held prisoner inside the Black Temple.  Illidan could destroy me any moment... until now!  This phylactery will allow me to regain control of my soul.\n\nThe time has come, <name>.  I'll lead Maiev and my Deathsworn to Illidan's doorstep.\n\nSpeak to A'dal and and tell him of our plan.  If we strike together we'll break through Illidan's defenses.", progress = nil, completion = "&lt;A'dal's light surrounds you as he welcomes you back.  You have a feeling he knows what you're about to ask of him.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10949] = {title = "Entry Into the Black Temple", objective = "Travel to the entrance to the Black Temple in Shadowmoon Valley and speak to Xi'ri.", description = "<A'dal shows you an image of a naaru outside of the Black Temple, fighting alongside draenei vindicators and blood elf magisters.  You immediately understand that this is the distraction Akama is waiting for.>", progress = nil, completion = "&lt;Xi'ri appears to acknowledge your presence.  He seems to be focused on the battle in the surrounding area.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10950] = {title = "Auchindoun and the Ring of Observance", objective = "Take your orphan, Dornaa, to the Meeting Stone at the Ring of Observance in the middle of Auchindoun. Auchindoun, in turn, is in the middle of Terokkar Forest's Bone Wastes. Make sure to call for her if she is not present when you arrive.", description = "One of the priests that comes to visit told a story about a place nearby.  It's called Auchindoun, and it's supposed to be very important to the draenei.\n\nHe said it used to be the place where the bodies of the draenei were taken when they died.  But some time ago, something bad blew it up.\n\nI'd like to see its Ring of Observance.  The orphan matron told me that it is in the middle of the Bone Wastes, on the south side of the Terokkar Forest.\n\nPlease, <Mr./Miss> <name>, can we go?", progress = "Are we there yet?  Just protect me from all the spooky ghosts, okay?", completion = "Oh, it's just wonderful!  I mean, it looks pretty old... and yeah, someone sure did blow it up.  But just look at it!\n\nOoh, and did you look up at the sky?\n\nNeato!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10951] = {title = "A Trip to the Dark Portal", objective = "Take your orphan, Salandria, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", description = "How can we look at all of these interesting places and not see the Dark Portal?!\n\nThe grown-ups are always trying to tell us scary stories about it and how it's so dangerous, with lots of demons, and stuff.\n\n<Salandria rolls her eyes.>\n\nBut you're here, so it can't be too bad, right?\n\nI want to see for myself.  You remember where it is on the east edge of Hellfire Peninsula?", progress = "This is soooo exciting!", completion = "The stories don't even come close to how cool this place is.  It's amazing!\n\nIs it true that a powerful wizard named Medivh created it?\n\nI wonder what's on the other side?  You've been there, right?  Hmm, we should definitely go someplace on the other side of the Dark Portal!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10952] = {title = "A Trip to the Dark Portal", objective = "Take your orphan, Dornaa, up the steps of the Stair of Destiny to stand before the Dark Portal in Hellfire Peninsula. Make sure to call for her if she is not present when you arrive.", description = "There's one place that if we don't go anywhere else, we have to go to: the Dark Portal!\n\nThe orphan matrons are always trying to scare us with stories about how dangerous it is, with lots of demons, and people like you coming through it.\n\n<Dornaa rolls her eyes.>\n\nBut you're here, and nice, so it can't be too bad, right?\n\nI want to see it for myself.  You remember where it is on the eastern edge of Hellfire Peninsula?", progress = "What do you know about the Dark Portal?", completion = "The orphan matron's stories don't even come close to how cool this place is.  It's amazing!  She said that it was created by a powerful wizard named Medivh.\n\nWhat's on the other side of it?  You've been there, right?  We should most definitely go someplace on the other side of the Dark Portal!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10953] = {title = "Visit the Throne of the Elements", objective = "Take your orphan, Salandria, to the Throne of the Elements in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Elementalist Sharvak.", description = "Have you heard of the Throne of the Elements?  It's supposed to be this place in Nagrand where there are these powerful elementals.\n\nOne day soon, I'm going to be a powerful mage, or maybe a warlock.  I'm gonna have to learn about some of the elemental forces!\n\nDo you think maybe that we could go there?\n\n<Salandria looks at you slyly.>\n\nYa know, it would be educational to go there.  It's supposedly just north of Garadar, on the other side of Skysong Lake.", progress = "The Earthen Ring sees you, <class>.", completion = "You bring a child here?  Foolhardy, but I promise that she will come to no harm, at least as long as she doesn't get too close to Incineratus.\n\nHmm, unfortunate that she's a blood elf.  Were she capable of a deep connection to the world, we could teach her some things so that she might aid us to heal its wounds.  But, perhaps her exposure to the elements here will give her some insight into their workings.\n\nGo in peace and see to it that you take good care of her.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10954] = {title = "Jheel is at Aeris Landing!", objective = "Take your orphan, Dornaa, to Aeris Landing in Nagrand. Make sure to call for her if she is not present when you arrive. Then, speak with Jheel.", description = "I miss my brother, Jheel.  He's a couple of years older than me, so they let him start an apprenticeship with the ethereal in Nagrand.\n\nIt sure would be nice to go visit him.  He loves geology and stuff, so I bet he's having a great time.\n\nThe orphan matron told me that he's training at a place called Aeris Landing in Nagrand.  It's supposed to be along the road, far to the west of Telaar, and northwest of the great mountain, Oshu'gun.", progress = "Did you bring her here?", completion = "Oh, I've missed Dornaa so much.  Thank you for bringing her to visit.  It gets lonely here with only the ethereal around.  And they're so serious all the time with this Oshu'gun business.\n\nBut I get to go back and visit the orphanage after I pass my gemcutting exams.  I almost passed them last week, but I'm sure that I'll do better on the test tomorrow!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10955] = {title = "Morthis Whisperwing", objective = "Seek out Morthis Whisperwing at the Cenarion Refuge in Zangarmarsh.", description = "Before all of the druidic orders coalesced into the Cenarion Circle, the Druids of the Talon were responsible for teaching promising young druids the mysteries of flight. With the dissolution of the order, former members teach the skill sparingly.\n\nEven now, Morthis Whisperwing continues his search for a suitable apprentice. Few druids have truly mastered all the forms available to them, but you show the promise Morthis requires of his students. Seek him out at the Cenarion Refuge in Zangarmarsh.", progress = nil, completion = "&lt;Morthis considers you somewhat skeptically.&gt;\n\nI have long searched for an apprentice to pass my knowledge to. Though the Druids of the Talon are no longer a formal group, I shall remain one to the last of my days.\n\nI accept you as my apprentice from this moment forward. For my part, I will teach you the secrets of the stormcrow. For your part, you must be prepared to do all I ask. Do you understand?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10956] = {title = "The Seat of the Naaru", objective = "Take your orphan, Dornaa, to stand before O'ros at the bottom of the Seat of the Naaru inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", description = "Do you know anything about the naaru?  They're these angelic beings that have been helping the draenei for a really long time.  I've seen a bunch around Shattrath.\n\nThey say that one naaru, O'ros, was with the Exodar when it traveled to your homeworld.  I should like to see for myself.\n\nCan you take me there?  I bet we could get there fast by using one of the portals inside the Terrace of Light at Shattrath City!  When we get there, if you get lost, we could always just look at your map.", progress = "I have been expecting you.", completion = "&lt;You feel, more than hear, the musical voice of O'ros chiming in your mind.&gt;\n\nThank you for bringing this child to me, &lt;name&gt;.  She is very special indeed, and will grow up one day to be an important figure amongst the draenei.  This is in no small part due to the kindness that you have shown her, and the impression that you have made.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10957] = {title = "Redemption of the Ashtongue", objective = "Help Akama wrest control back of his soul by defeating the Shade of Akama inside the Black Temple. Return to Seer Kanai when you've completed this task.", description = "When Illidan obtained the Broken's allegiance, Akama was our wisest.  He knew that openly opposing the Betrayer would lead to the extinction of our race.\n\nInstead he has plotted and schemed for this very moment under utmost secrecy.  Failure would be catastrophic... not just for Akama, not just for the Broken, but for all of Outland.  No one this close to Illidan has ever been able to deliver such a terrible blow to him.\n\nHelp Akama free his soul and he will grant you access to Illidan's sanctum.", progress = "Yes, <name>?", completion = "It is done, &lt;name&gt;.  The time to strike at Illidan has come.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10958] = {title = "Seek Out the Ashtongue", objective = "Find Akama's Deathsworn inside the Black Temple.", description = "<As you look up at Xi'ri, your mind becomes focused and your will determined.  Your work here is not done; you must go inside the Black Temple and find Akama's followers.>\n\n<Much depends on Akama's success.>", progress = nil, completion = "We've been expecting you, &lt;name&gt;.  Akama is in great need of your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10959] = {title = "The Fall of the Betrayer", objective = "Seer Kanai wants you to defeat Illidan inside the Black Temple.", description = "With Illidan's lieutenants defeated, Akama will be able to force open the doors to Illidan's sanctum.  Be ready to bring your force inside as soon as Akama does.\n\nWe still do not know what has become of Maiev, but we must make our move without her.\n\nI hope your force is up to the task.  Illidan will not be pleased to see Akama.", progress = "Yes, <name>?", completion = "It is as it was foretold, &lt;name&gt;.  One by one, Illidan's lieutenants have fallen... and now the Betrayer himself has met his demise!\n\nKnow this, &lt;name&gt;: every decision Akama made and every moment of his life since Illidan arrived, Akama planned for this moment.  Illidan is finally dead and our people... are free!", rewards = "You will receive:\n\nBlessed Medallion of Karabor"}
MultiLanguageQuestData['en'][10960] = {title = "When I Grow Up...", objective = "Take your orphan, Salandria, to the paladin trainers in Silvermoon City's Farstriders' Square. Make sure to call for her if she is not present when you arrive. Then, speak with Lady Liadrin, the Blood Knight Matriarch.\n\nRemember that you can use your map inside the city, and speak to the guards to find the paladin trainers.", description = "When you were my age did you know that you wanted to be a <class> when you grew up?\n\nI'm not sure what I want to be.  Maybe a mage or a warlock, like I said before?  Or maybe a paladin Blood Knight?  Yeah, definitely a Blood Knight!\n\nThey say that the true ones are trained in Silvermoon City on your world.  Could you take me there?  The stories that I've heard say that the paladin trainers reside in the Farstriders' Square in that city.\n\nPlease take me there.  Please!You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10961] = {title = "The Ward of Wakening", objective = "Bring 10 Bogblossoms, 10 Ancient Lichen, and 10 Dreaming Glory to Morthis Whisperwing at the Cenarion Refuge.", description = "Long ago, the relics used to teach the ways of the stormcrow were entrusted to an ancient druid.\n\nYour training requires these relics, so we must wake their guardian from his slumber.\n\nI will prepare a potion you can use to ease the process. The mixture requires common herbs, as well as bogblossom, which usually grows atop the tallest mushrooms in the marsh. Fly up there and pursue them but take care, as they're quite fragile and may explode violently if mishandled.", progress = "Have you brought the ingredients for the draught? Take care not to get pollen on me, please. I sneeze uncontrollably in its presence.\n\n<Morthis sniffs at the indignity represented by a sneeze.>", completion = "&lt;Morthis accepts the herbs from you, inspecting them. Producing a vial, he begins mixing the potion.&gt;\n\nThis will only take a moment, &lt;name&gt;. Then, you must travel to Moonglade.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10962] = {title = "Time to Visit the Caverns", objective = "Take your orphan, Dornaa, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", description = "In the orphanage, the old priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nDo you think that we could go there?  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nMaybe you could buy me a souvenir while we're there?", progress = "You think it's true what they say about the Caverns of Time?", completion = "Neato!  A dragon of my very own!  One day I hope that I'm lucky enough to have a dragon as a friend.\n\n&lt;Dornaa bounces up and down with joy, fiercely hugging her new toy.&gt;\n\nThis has been the best trip ever!  I hope it never ends.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10963] = {title = "Time to Visit the Caverns", objective = "Take your orphan, Salandria, to stand before Zaladormu, the dragon on the dais in the middle of the Caverns of Time. Make sure to call for her if she is not present when you arrive.\n\nThen, purchase a Toy Dragon for her from the Keepers of Time Quartermaster, Alurmi, near the bottom of the entrance tunnel.", description = "In the orphanage, the old stinky priest that comes by told us stories about the Caverns of Time.  He said that it sits in the middle of time, and is really important for keeping things straight.\n\nI don't know what that means, but he said that there were dragons there that were helping to save the world!  I want to see a dragon!\n\nI think we should go there.  He said that the entrance was on the eastern edge of a great desert named Tanaris.\n\nYou could buy me a souvenir while we're there!", progress = "If what they say about the Caverns of Time is true, then it must be a place of great power.", completion = "Awesome!  A dragon of my very own!  Someday I plan to own a real one.\n\n&lt;Salandria slyly eyes her new toy, the gears within her mind turning.&gt;\n\nThis has been the best trip ever!  I hope it never ends.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10964] = {title = "Waking the Sleeper", objective = "Use the Ward of Waking to help Clintar Dreamwalker emerge from the Emerald Dream. When he is conscious, speak to him.", description = "Take the ward with you and travel to Moonglade, to the Stormrage Barrow Dens. Within the southernmost of the Stormrage Barrow Dens, watched over by the dreamwardens, you will find Clintar Dreamwalker.\n\nAdminister the potion and watch over him while he wakes. He'll be extremely vulnerable as his spirit reunites with his body and he certainly won't recognize you. Declare yourself to him as soon as he comes around, <name>. He will need your help to gather the relics for the ceremony.", progress = "<You prepare to administer the potion to the sleeping <class>.>", completion = "&lt;The &lt;class&gt; emerges from his sleep, groggy and haggard looking. His gaze darts around the room in search of unseen pursuers.&gt;\n\nMorthis?\n\nNo, you're not Morthis... Who are you, &lt;race&gt;, and why have you disturbed my rest?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10965] = {title = "No Mere Dream", objective = "Protect Clintar Dreamwalker's Spirit while it gathers the relics of Aviana, then speak to Dreamwarden Lurosa.", description = "<Clintar listens as you relay Morthis' instructions, nodding, but clearly fearful.>\n\nI cannot extricate myself fully from the Emerald Dream to help you, but a fragment of my spirit will guide you in your search for the relics. Guard it well, <race>, for it is a fragile thing.\n\nThe Emerald Dream itself has become an alien, dangerous place. Its grasp on me is strong, and I will not be whole until the Emerald Dream returns to normalcy. What you see around you is but an echo of the reality inside the dream!", progress = "Be quick, <race>. If these creatures escape the barrow, Clintar Dreamwalker will not be the only one in danger.", completion = "You are fortunate that Clintar was strong enough to maintain the split in his essence for so long, &lt;name&gt;. Few druids can manage that kind of feat while under attack in Emerald Dream. Guard the relics well!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10966] = {title = "Back to the Orphanage", objective = "Return your ward to the Shattrath City orphanage by handing in the Draenei Orphan Whistle to Orphan Matron Mercy in the Lower City.", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, <name>!  You're my big <brother/sister> now!\n\n<Dornaa's eyes begin to well up with tears.>\n\nI'm going to miss you so much!  When I grow up, I'm going to be just like you!!!", progress = "It is good to see you again, <class>.  I trust that you and young Dornaa had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Dornaa has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", rewards = "You will be able to choose one of these rewards:\n\nElekk Training CollarEgbert's EggSleepy Willy\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10967] = {title = "Back to the Orphanage", objective = "Return your ward to the Shattrath City orphanage by handing in the Blood Elf Orphan Whistle to Orphan Matron Mercy in the Lower City.", description = "Darn it all!  I guess it's time to go back to the orphanage at Shattrath City.\n\nI've had such a great time.  You're the best person in all of the worlds, <name>!  You're my big <brother/sister> now!\n\n<Salandria's eyes begin to well up with tears.>\n\nI'm going to miss you so much!!!", progress = "It is good to see you again, <class>.  I trust that you and young Salandria had a wonderful time together?", completion = "It is good for the soul to know that there are heroes such as yourself that are willing to give of their time so selflessly.\n\nI can tell already that your time together with Salandria has made a huge impression.  It's good for the children to have a chance to get out and see the world.\n\nHere, she told me that she wanted you to take care of one of her favorite pets, just like you took care of her.  Something to remember her by.\n\nDon't be a stranger.", rewards = "You will be able to choose one of these rewards:\n\nEgbert's EggElekk Training CollarSleepy Willy\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][10968] = {title = "Call on the Farseer", objective = "Take your orphan, Dornaa, to visit Farseer Nobundo at the Crystal Hall inside of the Exodar, which is on Azuremyst Isle. Make sure to call for her if she is not present when you arrive.\n\nRemember that you can use your map inside the city.", description = "I am sensing something very special about this child indeed.\n\nYou should take her to visit Farseer Nobundo, here in the Exodar.  I believe that he has been expecting the two of you.\n\nLook for Nobundo upon the highest terrace in the Crystal Hall.", progress = "Remarkable.", completion = "I had hoped, but despaired she was only a figment of my imagination.  The child is amazing!\n\nIt's unheard of in this day and age that one of the draenei should exhibit such ability with the elements without any training.  She must have inherited this power from an ancient ancestor.\n\nI will send a missive to the orphan matron in Shattrath City requesting that the child be allowed to come stay with us.\n\nPlease, keep her safe until then.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10969] = {title = "Seek Out Ameer", objective = "Seek out Commander Ameer at the Protectorate Watch Post.", description = "It would seem that an outside force has taken an interest in the business practices of the Consortium. Five Consortium dealers have gone missing in the past two days. We have reason to believe the Ethereum are involved. If you are interested in assisting, seek out Commander Ameer at the Protectorate Watch Post.\n\nYou will find the Protectorate Watch Post directly east of here on the next island.", progress = nil, completion = "Aye, it is true, but the Consortium are not the only group claiming losses.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10970] = {title = "A Mission of Mercy", objective = "Recover the Salvaged Ethereum Prison Key for Commander Ameer at the Protectorate Watch Post in Netherstorm.", description = "We salvaged this prison orb on our last scouting mission into Ethereum territory. We'd have never found it had it not been for the distress signal that it was faintly emitting.\n\nWe think one of our own might be locked up in there but we have no way of opening the orb up without harming whatever is inside.\n\nWhat we know about the Ethereum is that any of their members could - at any given time - be carrying a key to unlock an orb. Retrieve one and return so that we may uncover the mysteries of this orb.", progress = "Any luck?", completion = "Stand back, &lt;name&gt;. This could very well be an Ethereum trap.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10971] = {title = "Ethereum Secrets", objective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him an Ethereum Prisoner I.D. Tag.", description = "<Ameer holds up a tag.>\n\nI found this prisoner I.D. tag with the remains of the fallen vanguard. I can only assume that all of their prisoners are tagged in the same manner.\n\nI'm going to start cataloguing the tags in hopes of making sense of their penal system. If in your adventures you find more Ethereum prison keys, you can use them to open the Ethereum prisons at the Ethereum Staging Grounds - directly south of here. Bring me back any and all I.D. tags that you find.", progress = "Have you recovered any I.D tags?", completion = "It seems to be more than just an identifier. There is some sort of code written on these tags. I'm on the verge of breaking it wide open. Perhaps if I had a few more pieces.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10972] = {title = "Ethereum Prisoner I.D. Catalogue", objective = "I am in need of more I.D. tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", description = "I am in need of more I.D tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", progress = "I am in need of more I.D. tags, <name>. What I've discovered thus far is that this is not just a way to catalogue prisoners but it also documents locations!\n\nOnce this code is broken we'll be able to pinpoint exactly where all of our allies are held and free them with minimal hostile action received.", completion = "We are close to the truth, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['en'][10973] = {title = "A Thousand Worlds", objective = "Commander Ameer at the Protectorate Watch Post in Netherstorm wants you to bring him 5 Ethereum Prison Keys.", description = "I have cracked the code! Each tag is broken up into several segments. The front side of the tag is always the same and states: \"A Thousand Worlds...\" I am unsure as to the meaning of this phrase but it sounds insidious.\n\nOn the back side of the tag are the vital statistics. The first set of runes indicates location and the second indicates prisoner type. Furthermore, it would seem that the keys can be combined to form a special key that accesses another prison type. Now I just need more keys...", progress = "I know it's asking a lot but think of the lives that could be saved!", completion = "&lt;Ameer deftly combines the keys and begins to read the markings on the newly formed key tablet.&gt;\n\n\"A thousand worlds shattered, a thousand worlds more to overcome... Such is the will of the Nexus-King.\"\n\n&lt;Ameer turns the tablet over and begins to read from the back-side.&gt;\n\nStasis chambers of Bash'ir?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10974] = {title = "Stasis Chambers of Bash'ir", objective = "Use the Ethereum Key Tablet - Alpha to open Stasis Chamber Alpha at Bash'ir's Landing in Blade's Edge Mountains.\n\nReturn Evidence from Alpha to the Image of Commander Ameer at Bash'ir's Landing.", description = "The Ethereum have a settlement on the northernmost shelf of Blade's Edge Mountains known as Bash'ir's Landing. According to the key tablet, much larger versions of the prisons are kept at Bash'ir's. It should also be noted that the Ethereum refer to those prisons as stasis chambers.\n\nThe key tablet grants access to a very specific stasis chamber at the landing known as Stasis Chamber Alpha. Take the key and investigate.\n\nMy image will be awaiting your return at Bash'ir's Landing. Speak to me there.", progress = "You made it! Any luck?", completion = "&lt;The image of Commander Ameer rummages through the evidence.&gt;\n\nIt is worse than I thought... These chambers hold ferocious beasts and creatures from many, many different worlds. They hope to one day command the beasts to do their bidding. We must destroy them all!", rewards = "You will receive:\n\nProtectorate Treasure Cache"}
MultiLanguageQuestData['en'][10975] = {title = "Purging the Chambers of Bash'ir", objective = "We're at an impasse here, <name>. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", description = nil, progress = "We're at an impasse here, <name>. The data you've collected has given us enough information to save our allies being held at the smaller prisons of Netherstorm but we must press forward and eradicate the larger Ethereum threats here at Bash'ir's Landing.\n\nJoin the battle against the Ethereum! Bring Ethereum prison keys to me and I shall forge Ethereum stasis chamber keys for you to use on the stasis chambers of Bash'ir.", completion = "There is always more work that must be done, &lt;name&gt;. Now seek out a stasis chamber and destroy whatever evil lurks within!", rewards = "You will receive:\n\nEthereum Stasis Chamber Key"}
MultiLanguageQuestData['en'][10976] = {title = "The Mark of the Nexus-King", objective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to bring him a Mark of the Nexus-King.", description = "What I must now know is what the Ethereum have held inside the Mana-Tombs of Auchindoun.\n\nIn your battles against the beasts of the stasis chambers of Bash'ir you may run across an item known as the Mark of the Nexus-King. Should you find such an item, return it to me immediately! It is the final piece in crafting a key that will allow access to the stasis chamber inside the Mana-Tombs.", progress = "This will be your most daunting task, <name>.", completion = "At last!\n\n&lt;Commander Ameer reads from the Mark of the Nexus-King.&gt;\n\nTwo final prisons? I shudder to think what horrors lie in wait...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10977] = {title = "Stasis Chambers of the Mana-Tombs", objective = "The Image of Commander Ameer at Bash'ir's Landing in the Blade's Edge Mountains wants you to use the Mana-Tombs Stasis Chamber Key on the Stasis Chamber inside the Mana-Tombs of Auchindoun.\n\nThis quest may only be completed on Heroic difficulty.", description = "The Mark of the Nexus-King that you recovered has allowed me to forge a new key for the stasis chambers found inside the Mana-Tombs.\n\nAccording to the glyphs on the mark, two exist: one near the front and one near Nexus-Prince Shaffar. This key that I am about to give you will open the stasis chamber near the front.\n\nI want you to go to the Mana-Tombs of Auchindoun and open the Mana-Tombs Stasis Chamber.", progress = "I would understand if you chose not to continue, <name>.", completion = "Word has gotten back of your heroics, &lt;name&gt;. Haramad and I both agree that what you've done deserves a great reward.\n\nThough... Nevermind, you've done enough. I cannot in good conscience ask anything more from you.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][10978] = {title = "Return to Morthis Whisperwing", objective = "Bring the Relics of Aviana to Morthis Whisperwing at Cenarion Refuge in Zangarmarsh.", description = "Now that the relics have been recovered, you must leave this place with all haste. Clintar risked his safety and that of the dreamwardens to help you, <name>, but now he must fully devote his attention to fighting the force that has invaded the Emerald Dream.\n\nTake the relics back to Morthis Whisperwing, along with word of what you've seen here. He may be able to help us identify just what Clintar is struggling against.", progress = "Did Clintar help you recover the relics?", completion = "&lt;Morthis accepts the relics from you as you describe your experiences in the barrow dens.&gt;\n\nThis is most troubling news, &lt;name&gt;. There have been any number of strange disturbances in the Emerald Dream, but I can't remember any mention of outside forces tampering with it. Are you certain that's what Clintar believes?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10979] = {title = "To the Evergrove", objective = "Speak with Arthorn Windsong at the Evergrove in Blade's Edge Mountains.", description = "Are you certain you saw a raven in the barrow den?\n\nThis is a troubling development. There's little we can do to help Clintar and the dreamwardens directly, but if we can learn more about what's threatening the Emerald Dream, we may be able to stop it.\n\nWe've been learning about the resurgence in an ancient arakkoa cult in Blade's Edge -- one that venerates a raven god. Go to the Evergrove and find Arthorn Windsong. There may be a connection between what's happening there and in the Emerald Dream!", progress = nil, completion = "&lt;Arthorn listens as you explain that Morthis Whisperwing sent you to investigate a connection between the cult of the raven god and strange happenings in Moonglade. Though shocked at the news, she seems more disappointed at the message's nature.&gt;\n\nOh my...\n\nI've been helping Timeon with his research on the raven cult, but we never imagined its patron had any reach beyond Blade's Edge!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10980] = {title = "The Book of the Raven", objective = "Use an Aether Ray Eye with your Seer's Stone to reveal the raven cult ghosts. Search the Vortex Pinnacle for the spirit of Sai'kkal the Elder and question him about the book of the raven, then return to Arthorn Windsong.", description = "From what you've told me, Morthis's suspicions seem plausible, but we need confirmation.\n\nIn his research, Timeon has uncovered clues that a \"book of the raven\" served as an ancient scripture to the cult.\n\nThe arakkoa spirits will not reveal themselves to your eyes. Take this stone with you to the high peaks in the western part of Blade's Edge, to the south of Raven's Wood, obtain an aether ray eye, and combine them to augment your sight. Search for the ghost Timeon identified as Sai'kkal the Elder.", progress = "<Arthorn looks at you hopefully.>\n\nWere you able to track down any information about the book?", completion = "Isn't it amazing that even among arakkoa, the cultists were considered heretics? That the traditional priests hated them enough to destroy their holy text is incredible! We must get our hands on that book, &lt;name&gt;.\n\nIt's the key to unraveling the mystery of the raven god and preventing him from taking over the Emerald Dream.\n\nPerhaps Morthis will finally agree to take me as a student if we succeed!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10981] = {title = "Nexus-Prince Shaffar's Personal Chamber", objective = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, <name>. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", description = nil, progress = "Only the most steadfast and battle-hardened of adventurers will take me up on this offer, <name>. Should you wish to face the horrors of the second stasis chamber in the Mana-Tombs, I am able to synthesize a key. Bring me a mark of the Nexus-King and I will make it so.", completion = "As promised, here is the key to Shaffar's personal stasis chamber.", rewards = "You will receive:\n\nShaffar's Stasis Chamber Key"}
MultiLanguageQuestData['en'][10982] = {title = "The Eye of Haramad", objective = "You have done much for the Protectorate and the Consortium, <name>. It is only fitting, then, that the first of our new keys goes to you. With this key you will be able to open Shaffar's personal stasis chamber at any time without having expended the key itself.\n\n\n\nIt is permanent and will be with you forever.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nThe Eye of Haramad"}
MultiLanguageQuestData['en'][10983] = {title = "Mog'dorg the Wizened", objective = "Visit Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", description = "Mog'dorg wise!  Him send Grok to city, look for help.  Bloodmaul clan need help.\n\nMog'dorg say, send powerful little ones to him at Blade's Edge Mountains.  Him stand on tower at Circle of Blood.  Mog'dorg wise!", progress = nil, completion = "Grok said that I am wise?  I don't know about that.\n\nPerhaps it is because I am the only one in my clan that is truly trying to save us from annihilation by the Bladespire clan, and Gruul and his sons, who are backing them.\n\nI hope that you have come to deliver us from certain doom, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10984] = {title = "Speak with the Ogre", objective = "Speak with the Ogre, Grok, in the Lower City section of Shattrath City.", description = "<V'eru's voice fills your mind with crystalline tone and clarity.>\n\nThere is an ogre down in the Lower City, pleading for the assistance of passersby.  They have all turned a deaf ear upon his plight.\n\nDo you think you might aid him?\n\nHis name is Grok, and he is sitting near the merchants to the southeast.\n\nThank you, <name>.", progress = nil, completion = "You help Grok?  Grok need help!  Bloodmaul clan need help!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10985] = {title = "A Distraction for Akama", objective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", progress = "<Xi'ri acknowledges your presence.>", completion = "&lt;Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.&gt;", rewards = "You will receive:\n\nMedallion of Karabor"}
MultiLanguageQuestData['en'][10986] = {title = "Eyes in the Sky", objective = "Speak with Watcher Elaira at the Twilight Ridge in Nagrand.", description = "Locating the pieces of the Book of the Raven, if they survive at all, is going to be difficult. Our best hope is to use a keener pair of eyes than your own.\n\nDown in western Nagrand, on the eastern lip of the Twilight Ridge, Watcher Elaira studies the various bird species that make their home there. Visit her and see if she can help you harness avian sight to gather the pieces of the Book of the Raven.", progress = nil, completion = "&lt;Elaira listens as you describe your search for the Book of the Raven and Arthorn's suggestion to use birds to locate the missing pieces of the tablet.&gt;\n\nIt's an excellent idea and Nagrand is teeming with candidates, but which one to use?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10987] = {title = "To Catch A Sparrowhawk", objective = "Use the Sparrowhawk Net to capture a Wild Sparrowhawk and bring it to Watcher Elaira on the Twilight Ridge.", description = "The wild sparrowhawks of Nagrand have the keenest sight of all the predatory birds here. But, because of their size, they've been pushed out of most areas by the larger windrocs.\n\nMost of the sparrowhawks nest here, on the Twilight Ridge. If you can catch one, I'll train it to spot the pieces of your buried tablet.\n\nIt's going to be difficult, though. The sparrowhawks are very skittish and will flee at your approach. I'd suggest cornering one or prowling to get close enough to cast your net.", progress = "Did you catch one of the sparrowhawks?", completion = "Well done! I'm still in the process of getting the hawks to trust me, but I know enough about them to train this one for your needs.", rewards = nil}
MultiLanguageQuestData['en'][10988] = {title = "The Raven Stones", objective = "Gather 8 Raven Stones from Skettis and bring them to Arthorn Windsong at Evergrove in Blade's Edge Mountains.", description = "I've trained your sparrowhawk to respond to a specific whistle. When it hears the sound, the bird will fly to you and guide you to the location of the nearest tablet fragment. Arthorn sent word that the fragments you're looking for are buried in the Skettis area of southeastern Terokkar Forest, so the bird will wait for you there.\n\nWhen you've gathered all the stones, return the whistle to Arthorn and she will see to the animal's care and release.\n\nConvey my greetings to Arthorn when you see her.", progress = "Did you recover enough of the Book of the Raven for me to reconstruct it?", completion = "&lt;Arthorn accepts the fragments of the Book of the Raven from you and begins piecing them together.&gt;\n\nSome of the characters have been worn away, but I should be able to make out most of this...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10989] = {title = "Mog'dorg the Wizened", objective = "Visit Mog'dorg the Wizened atop the tower where Chort is standing, just outside the Circle of Blood in the Blade's Edge Mountains.", description = "Mog'dorg the Wizened waits for you at top of da tower.  He tells me to look for a <race> <class> just like you.  You go speak with him about smart things.\n\nGo now, but don't tell no one.  It's a secret!", progress = nil, completion = "Finally, Chort has sent me someone who looks like they might be able to help.  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10990] = {title = "The Eagle's Essence", objective = "Defeat the Guardian of the Eagle and obtain the Essence of the Eagle. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", description = "The Book of the Raven tells us the raven's followers captured and bound the spirits of his rivals within stone shrines. A guardian was set to watch over each, lest the raven's enemies attempt to free them.\n\nThe first of the shrines is the eagle's, found in the hills to the south of Lake Jorune and west of Stonebreaker Hold in Terokkar Forest.\n\nThe tablet says that the eagle fought valiantly, but was overcome by a swarm of enemies. The armor and endurance of your bear form is well-suited to this fight.", progress = "<The sparrowhawk seems to speak with Arthorn's voice.>\n\nDid you succeed in freeing the essence of the eagle spirit?", completion = "&lt;Arthorn seems to feel the power in the recovered essence through the sparrowhawk's senses.&gt;\n\nEven after thousands of years of captivity, the eagle's power remains strong. If the other essences are as strong as the eagle's, the raven god will be right to fear you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10991] = {title = "The Falcon's Essence", objective = "Defeat the Guardian of the Falcon, obtain the Essence of the Falcon. Use Arthorn's Sparrowhawk Whistle to call Arthorn's Sparrowhawk to relay news of your success.\n\nIf you lose Arthorn's Sparrowhawk Whistle, return to Arthorn Windsong at the Evergrove for a replacement.", description = "<The bird speaks with Arthorn's voice.>\n\nThe second spirit bound by the raven's followers was the falcon.\n\nIt was subdued and imprisoned close to Skettis as a reminder to the raven-priests when they held power.\n\nOn the shores of Lake Ere'Noru, to the northwest of Skettis, you'll find the falcon's shrine.\n\nTo overcome the falcon's guardian, you'll need to use the falcon's strengths to your advantage. Use the speed and grace of your cat form to defeat the guardian before it reaches full strength!", progress = "<Once again, Arthorn's voice issues from the sparrowhawk.>\n\nDo you have the falcon's essence?", completion = "&lt;The sparrowhawk dutifully conveys Arthorn's words.&gt;\n\nWell done, &lt;name&gt;. I'd feared that the falcon's prison had been destroyed in the explosion of Auchindoun. We're almost prepared to confront Anzu, &lt;name&gt;. I'd love to go with you, to be there when this self-styled \"god\" is cast back into the pit that spawned him!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10992] = {title = "The Hawk's Essence", objective = "Defeat the Guardian of the Hawk and bring the Essence of the Hawk to Arthorn Windsong at the Evergrove.", description = "<Arthorn's voice addresses you.>\n\nThe last, and strongest, of the spirits spoken of in the Book of the Raven is that of the hawk. It was imprisoned far from Skettis, in a shrine on a remote island southeast of Auchindoun.\n\nI believe this description best matches the island we know as Sorrow Wing Point.\n\nThe tablet describes the hawk's guardian as nearly invulnerable to the bird's claws. Forsake physical attacks and call down the fury of the stars to defeat this foe. Do not repeat the hawk's mistake.", progress = "Did you overcome the hawk's guardian and win its essence?", completion = "Now that we have all the essences, Morthis Whisperwing must find a way to combine them into an amulet that you'll be able to use to challenge the raven god, draw him out of the Emerald Dream and defeat him. I'll be sending him my notes on the spirits with the hope that he'll realize the value of my insight.\n\nEach of the spirits has blessed a charm I've prepared for you.", rewards = "You will receive:\n\nCharm of Swift Flight"}
MultiLanguageQuestData['en'][10993] = {title = "Return to Cenarion Refuge", objective = "Bring Arthorn's Package to Morthis Whisperwing at Cenarion Refuge.", description = "Bring the essences to Morthis Whisperwing, along with word of our findings about the raven god.\n\nMorthis will know best how to use the essences and information in drawing Anzu out into the open. Make your way to him quickly, for there's no telling how long Clintar and the dreamwardens can withstand the raven's assault!\n\n<Arthorn grabs your arm before you turn to leave>.\n\nPlease, <name>, tell Morthis how much of a help I've been to you. I fear he will not see my hand in this work!", progress = "I've been waiting for word from Arthorn. What have you discovered?", completion = "&lt;Morthis accepts the package, opens it to discover Arthorn's notes, and reads over them without commenting on the author.&gt;\n\nOn one level, I'm relieved to finally know the identity of our enemy, but this Anzu is a being of considerable power. Knowing the nature and the name of your adversary is vital, but we are not yet ready to face him.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10994] = {title = "Chasing the Moonstone", objective = "Bring a Southfury Moonstone to Morthis Whisperwing at the Cenarion Refuge.", description = "If the essences are combined within a rare gemstone such as a Southfury moonstone, you'll be able to release them when you're prepared to challenge Anzu.\n\nThe only problem is that Southfury moonstones are only found on the Azshara side of the river, on the cliffs near the river's source.\n\nTragedy befell the last night elf party that sought the stone. Their boat is still anchored in the river near where they sighted the moonstone. Keep your eyes open and approach the site by land from the Azshara side.", progress = "You look like you've been through quite an ordeal. Was the moonstone really that hard to find?", completion = "&lt;Morthis seems torn, at once desiring to laugh at your story, and mindful of how close you came to losing the moonstone. He settles for staring at the glowing stone.&gt;\n\nI'll get to work on infusing it with the bird spirit essences. Soon, you'll be prepared to challenge our enemy.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10995] = {title = "Grulloc Has Two Skulls", objective = "Retrieve Grulloc's Dragon Skull and deliver it to Mog'dorg the Wizened atop the tower at the Circle of Blood in the Blade's Edge Mountains.", description = "To the east, at the terminus of Dragons' End, is the Cursed Hollow.  Therein, Grulloc, son of Gruul, plots his dimwitted schemes.\n\nI heard that one of his possessions was stolen from him through trickery.  Was that you?  Unfortunate that he was not slain in the process.\n\nIf we are to regain our freedom, I would have you take his most prized possession, a dragon skull from when he rejoiced in his father's slaying of the Black Dragonflight.  The only way you'll get the skull is to vanquish him.", progress = "Is Grulloc no more?", completion = "Indeed, it must have been a difficult struggle, &lt;class&gt;.  I feel greatly relieved now that he will not be breathing down our necks here.\n\nI will send this skull down to Chort for safekeeping.  I'm beginning to think that with your help, we might just pull this off.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10996] = {title = "Maggoc's Treasure Chest", objective = "Retrieve Maggoc's Treasure Chest and deliver it to Mog'dorg the Wizened atop the tower at the Circle of Blood in the Blade's Edge Mountains.", description = "On the Razor Ridge, above and to the southeast, Maggoc patrols.  His father assigned him as the warden of the eastern mountain range, and he revels in terrorizing any creature that gets in his way.\n\nAs a son of Gruul, he must be done away with if my clan is to survive.  That's where you come in.\n\nMaggoc carries a treasure chest with him at all times.  Prove to me that he has been slain by bringing me his precious chest.  Feel free to keep whatever you find within it.", progress = "Do you have the chest?", completion = "You say it was empty?  Unfortunate, but you can see the mindless brutality that we're up against.\n\nWith the fall of Maggoc, we are one step closer to realizing my dream of a home for the ogres where we can determine our own destiny.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10997] = {title = "Even Gronn Have Standards", objective = "Retrieve Slaag's Standard and deliver it to Mog'dorg the Wizened atop the tower at the Circle of Blood in the Blade's Edge Mountains.", description = "Are you familiar with Shattrath City, <class>?  Above it to the northwest is a place called the Barrier Hills, which you can only get to upon a flying mount.\n\nOne of Gruul's sons, Slaag, exiled himself and took control of the Gordunni ogres that reside there.  Even at such a distance, we cannot afford to leave him in peace, lest he return when the rest of his brothers have been slain.\n\n<name>, you must travel there, and bring back his standard as proof that he has been dealt with.", progress = "Do you return with Slaag's standard in hand?", completion = "What a relief that Slaag is gone.  No longer will we be threatened by the looming specter of his return!\n\nIf you do not mind, I will take the standard as a symbol of hope for all of the ogres of the mountains.\n\nThank you, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10998] = {title = "Grim(oire) Business", objective = "You must retrieve Vim'gol's Vile Grimoire. Deliver it to Mog'dorg the Wizened atop the tower at the Circle of Blood in the Blade's Edge Mountains.", description = "There is one more gronn to be slain: Skulloc Soulgrinder.  He keeps himself hidden away, but there is a way to coax him forth.\n\nHe was trained by an ogre warlock known as Vim'gol the Vile, whose grimoire you must retrieve!\n\nVim'gol must be summoned by yourself, and four others, each standing within a different fire ring at his circle.  Find Vim'gol's Circle in the mountains, to the northeast, near the Broken Wilds.\n\nAnd, <name>, if you hear Vim'gol talk about growing bigger, get back to the fire rings!", progress = "Have you summoned forth Vim'gol the Vile and taken the grimoire from his dead clutches?", completion = "I hesitate to even touch such a tainted thing of evil.  Yet read it we must if we are to glean what knowledge it contains and bring forth Skulloc from his hiding place.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][10999] = {title = "One Shot, One Kill", objective = "Bring me 8 trogg stone teeth.", description = "Bring me 8 trogg stone teeth.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11000] = {title = "Into the Soulgrinder", objective = "Retrieve Skulloc's Soul and deliver it to Mog'dorg the Wizened atop the tower at the Circle of Blood in the Blade's Edge Mountains.", description = "The grimoire is the key to Skulloc's downfall.\n\nRead aloud from the book at Soulgrinder's Barrow to initiate the ritual.  An object known as the Soulgrinder will appear, as well as Skulloc's ghostly victims, who will try to destroy it.  You must keep them from doing so long enough to force Skulloc fully into the world.\n\nFind the barrow by heading north through the Daggermaw Canyon on the other side of the Circle of Blood.  It is on the right side before Gruul's Lair.\n\nBring back Skulloc's soul.", progress = "Have you taken Skulloc's soul yet?", completion = "It is over then.  You have freed us from the shackles of our enslavement to the Sons of Gruul.  You have given the Bloodmaul Clan a reprieve from certain extinction.\n\nWords cannot describe the extent of the debt that ALL of the ogres of the Blade's Edge Mountains, Bloodmaul and Bladespire alike, owe you, &lt;name&gt;.\n\nLook down, even now the ogres gather to pay you tribute.  Let Gruul and his puppet, the old king, Maulgar, cower within their lair.  Go to the ogres below as our new king!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11001] = {title = "Vanquish the Raven God", objective = "Slay the Raven God and return to Morthis Whisperwing at Cenarion Refuge.\n\nThis quest must be completed in Heroic dungeon difficulty.", description = "We must waste no time in dealing with the raven god. You must take the essence-infused moonstone to a place of great power in order to lure the god from the relative safety of the Emerald Dream.\n\nDescend into the Sethekk Halls and set the moonstone in the clutches of the raven's claw. You'll find it in the chamber before the talon king's hall.\n\nAnzu must be made believe that his followers have gathered to welcome him back into the world. Once he has manifested, show him no mercy!", progress = "What news from Sethekk Halls? Have you defeated Anzu?", completion = "It's good to see you again, &lt;name&gt;. Your triumph over the raven god counts for far more than any test or rite of passage that I might set for you.\n\nYou have truly proven yourself worthy of the knowledge guarded by the Druids of the Talon for countless generations.", rewards = "You will learn:\n\nSwift Flight Form\n\nThe following spell will be cast on you:\n\nSwift Flight Form\n\nYou will also receive:\n\nIdol of the Raven Goddess"}
MultiLanguageQuestData['en'][11002] = {title = "The Fall of Magtheridon", objective = "Return Magtheridon's Head to Force Commander Danath Trollbane at Honor Hold in Hellfire Peninsula.", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Alliance.\n\nReturn Magtheridon's head to Danath Trollbane at Honor Hold.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, &lt;name&gt;. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", rewards = "You will be able to choose one of these rewards:\n\nA'dal's Signet of DefenseBand of Crimson FuryNaaru Lightwarden's BandRing of the Recalcitrant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11003] = {title = "The Fall of Magtheridon", objective = "Return Magtheridon's Head to Nazgrel at Thrallmar in Hellfire Peninsula.", description = "The source of Illidan Stormrage's fel orc army has been vanquished. The manufactory halts production of its grim product - at least for now. All that remains are a few trinkets and this severed head - a fitting trophy for a hero of the Horde.\n\nReturn Magtheridon's head to Nazgrel at Thrallmar.", progress = "For the first time - in as long as I can remember - there is silence.", completion = "This defeat is not only a blow to Illidan, &lt;name&gt;. The Legion too reels... A pit lord commander has been defeated. The siege of Hellfire Citadel now holds no purpose for the Burning Legion. All of their efforts will undoubtedly be turned upon the Black Temple.\n\nRedemption comes for Illidan... and soon.", rewards = "You will be able to choose one of these rewards:\n\nA'dal's Signet of DefenseBand of Crimson FuryNaaru Lightwarden's BandRing of the Recalcitrant\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11004] = {title = "World of Shadows", objective = "Severin wants you to venture into Skettis and retrieve 6 Shadow Dusts from the arakkoa that dwell there.", description = "Sky Commander Adaris was seriously injured during a Skettis incursion.  He's been in and out of consciousness since.\n\nI fear he has succumbed to a feverish delirium.  During brief lucid moments he demands that I prepare an elixir made from shadow dust carried by the arakkoa.  He seems to believe it will allow him to see into a \"world of shadows\" where the arakkoa's true leaders dwell.\n\nI do not believe this nonsense for a second, but I fear he won't rest until I obtain such an elixir.  Will you help?", progress = "Have you obtained the dust, <name>?", completion = "I thank you, &lt;name&gt;.  I will administer a small amount to the commander... to humor him.  You can keep the rest, perhaps you'll find a use for it.", rewards = "You will receive:\n\nElixir of Shadows"}
MultiLanguageQuestData['en'][11005] = {title = "Secrets of the Talonpriests", objective = "Obtain an Elixir of Shadows from Severin and use it to find and slay Talonpriest Ishaal, Talonpriest Skizzik and Talonpriest Zellek in Skettis. Return to Commander Adaris after completing this task.", description = "Thank you for paying heed to my fevered rants.  All along we had been trying to identify and destroy the Skettis chain of command; we had learned of three clerics known as the talonpriests, but we'd never seen them with our own two eyes.  Now we know why.\n\nTalk to Severin to obtain more of the elixir he discovered.  Use the elixir to find and kill the three talonpriests: Ishaal, Skizzik and Zellek.  They're rumored to dwell in Veil Ala'rak, near the eastern shore of Blackwind Lake.", progress = "Is the deed done, <name>?  I'd kill those blasted birdmen myself if it weren't for my injuries.", completion = "You've done well, &lt;name&gt;.  You've dealt a tremendous blow to the enemy by slaying the talonpriests.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11006] = {title = "More Shadow Dust", objective = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", description = nil, progress = "It looks like the commander was not delirious after all.  Bring me more dust and I'll prepare another elixir for you.", completion = "Keep bringing the dust to me.  I'll prepare as many elixirs as you need.\n\nCommander's orders.", rewards = "You will receive:\n\nElixir of Shadows"}
MultiLanguageQuestData['en'][11007] = {title = "Kael'thas and the Verdant Sphere", objective = "Take the Verdant Sphere to A'dal in Shattrath City.", description = "The air around you hums - a gentle hum. The naaru are aware of your victory. Perhaps they are the reason you were compelled to pick up this sphere from the still-twitching remains of Kael'thas Sunstrider. What secrets could it hold?\n\nPerhaps A'dal in Shattrath City could make sense of the item.", progress = "You heard my call? Yes...", completion = "&lt;A'dal's thoughts intermingle with your own.&gt;\n\nThe sphere... Strange. Did you know that he lived? Yes. It is here - in the sphere itself. Maimed for certain. He calls to a higher power now. No, not Illidan.\n\nHigher.\n\nKil'jaeden the Deceiver comes...\n\nNot here...\n\n&lt;A'dal points your mind elsewhere.&gt;\n\nAzeroth. Unknown.\n\nRest. Your brothers and sisters will retake Tempest Keep now.\n\n&lt;A'dal hums a song of battle.&gt;", rewards = "You will be able to choose one of these rewards:\n\nThe Darkener's GraspThe Sun King's TalismanTelonicus's Pendant of MayhemLord Sanguinar's Claim\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11008] = {title = "Fires Over Skettis", objective = "Seek out Monstrous Kaliri Eggs on the tops of Skettis dwellings and use the Skyguard Blasting Charges on them. Return to Sky Sergeant Doryn.", description = "You think you have what it takes to be part of the Skyguard?  We'll have to see how you handle yerself in the air.\n\nThe arakkoa are breeding a gargantuan variety of their attack pets and are using it against our scouts.  I want you to take these blasting charges and use them to destroy hatcheries above the arakkoa's dwellings.  Avoid the monstrous kaliri guarding the hatcheries.  They'll knock you off your mount before you know what hit you.", progress = "Did you finish your assignment yet?", completion = "Excellent job, &lt;name&gt;!  That'll show those bird men the meaning of air superiority!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11009] = {title = "Ogre Heaven", objective = "Mog'dorg the Wizened has asked you to speak with Chu'a'lor at Ogri'la in the Blade's Edge Mountains.", description = "Now that you have delivered us from bondage, we can begin the process of reunifying the clans.  This will take some time; old grudges are difficult to overcome.\n\nBut more pressing, you must go to Ogri'la in the heavens above to the west.  You must defend it, and us, from those forces above that the gronn used to protect us from: ethereals, demons, and worst of all, the black dragonflight.\n\nWhen you find ogre heaven, seek out the wisdom of Chu'a'lor on how best to proceed.", progress = nil, completion = "Mog'dorg sent a message ahead, saying that I should expect you.  I am glad that you came.\n\nWith the Sons of Gruul destroyed, it is only a matter of time - a short amount at that - before the various inhabitants of this mountain terrace, and the one to the north, decide to prey upon our ogre brothers down below.\n\nI trust that you will help us to prevent that, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11010] = {title = "Bombing Run", objective = "Sky Sergeant Vanderlip has tasked you with the bombing of 15 Fel Cannonball Stacks. Return to her at the Skyguard Outpost atop the Blade's Edge Mountains once you have done so.", description = "You have a flying mount... so what!  You think you have what it takes to use it properly?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nYou want to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n&lt;Sky Sergeant Vanderlip smirks.&gt;", rewards = "The following spell will be cast on you:\n\nBombing Run: On Quest Complete\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11011] = {title = "Eternal Vigilance", objective = "Speak with Morthis Whisperwing to receive an Essence-Infused Moonstone.", description = "Your defeat of Anzu, the raven god, is truly a remarkable accomplishment. He may not abandon his quest to return to Outland, I fear.\n\nAs long as he has followers here, he will attempt to rise again. Keep the essence-infused moonstone with you in case we have not heard the last of Anzu.", progress = nil, completion = "Keep the moonstone with you, &lt;name&gt;. If you suspect that Anzu is gathering his strength to attempt another return to this world, use it to defeat him once again.", rewards = "You will receive:\n\nEssence-Infused Moonstone"}
MultiLanguageQuestData['en'][11012] = {title = "Blood Oath of the Netherwing", objective = "Our lands are lost. Our children stolen in the night, forced into slavery - or worse...\n\n<Mordenai's voice tenses.>\n\nThe time is now, my ally. The time to retake what was once ours has come! You have proven yourself a capable combatant and compassionate soul.\n\nWill you swear to assist the Netherwing Dragonflight in retaking our lands and rebuilding our homes? Will you swear to watch over the flight and allow the bloodline to be born anew? Swear this and let us battle for our home and our loved ones!", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][11013] = {title = "In Service of the Illidari", objective = "\nTravel to Netherwing Ledge and deliver the Illidari Service Papers to Overlord Mor'ghor at Dragonmaw Base Camp.", description = "Netherwing Ledge... What was once a bastion of sanctuary for the Netherwing is now home to the Dragonmaw. While the orcs may have control of our territory, our magic there is still strong. Strong enough to cloak your true identity and allow you to infiltrate the ranks of Dragonmaw.\n\nI have prepared this letter for you to present to their leader, Overlord Mor'ghor. Fly headlong into the maw of our enemy and seek out Dragonmaw Base Camp to start your new life as a fel orc of Illidan Stormrage.", progress = "<Mor'ghor grunts.>\n\nYou're late...", completion = "&lt;Mor'ghor reads the letter and laughs.&gt;\n\nA death knight? You couldn't shine the boots of a death knight, maggot.\n\n&lt;Mor'ghor looks you over.&gt;\n\nBut yes... You might be able to work your way up to peon. At the worst, I'll toss you into the pit and leave you to die...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11014] = {title = "Enter the Taskmaster", objective = "Speak with Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp.", description = "<Mor'ghor crumples up the service letter and tosses it aside.>\n\nAlright grunt, first things first. If you're gonna join my beloved Dragonmaw army, you'll need to work. Everyone works up here on the ledge. Get a job and don't screw it up and I'll see if there might be something more interesting for you to do later.\n\nGo talk to Taskmaster Varkule Dragonbreath. He's standin' in the middle of town. He'll assess your skills and assign work as he sees fit.\n\nNow get out of my face!", progress = nil, completion = "Varkule gonna set you up right, grunt. You get your choice of one job best suited to your skills and Netherwing crystal collection. You'll be required to fill your work orders once per day.\n\nYeah, it's a bunch of crap jobs but even the ascendants started out as peons.", rewards = nil}
MultiLanguageQuestData['en'][11015] = {title = "Netherwing Crystals", objective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 30 Netherwing Crystals.", description = "No good at nothin'? That's fine. Even lunkheads like you can be used around here. Just find creatures on the ledge and kill 'em. Sometimes they'll have nether crystals on their carcasses. Gather those and bring 'em back to me and I'll consider your work order for the day complete.", progress = "Nether crystals are used for lots of things. Mainly makin' weapons and armor...", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11016] = {title = "Nethermine Flayer Hide", objective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 35 Nethermine Flayer Hides.", description = "A skinner, eh? Well you'll find plenty to skin here! You gotta search for flayers around crystal formations. Take 'em down and take their hides. Sometimes they'll have a hide worth keepin'. Bring those to me.", progress = "We use the flayer hides for armor lining and structural tarps.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11017] = {title = "Netherdust Pollen", objective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Netherdust Pollen.", description = "A flower picker?! Hilarious... Unfortunately, our mages and shaman need your services. The netherdust bushes that grow on this ledge have special pollen that is apparently very useful in their magical dealings. Bring me that stuff and I'll consider your work order complete.", progress = "Like I said, netherdust pollen is used by our spell casters.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11018] = {title = "Nethercite Ore", objective = "Taskmaster Varkule Dragonbreath at Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 40 Nethercite Ore.", description = "A miner!\n\n<Varkule salutes.>\n\nAn orc after my own heart! That's how Varkule got his start - minin'! There ain't nothin' better than getting down and dirty in the mines, is there?\n\nNow get out there and find those nethercite deposits. Strip 'em for all their worth and bring me back the ore.", progress = "Gug over there is gonna use the ore to reinforce our weapons and armor.", completion = "You're done for today, kid. Come back tomorrow if you're still alive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11019] = {title = "Your Friend On The Inside", objective = "Didn't think we'd leave you to face the fel orc army by yourself, did you?\n\n<Yarzill's eyes flicker a translucent blue.>\n\nAye, we are here with you, <name>. For every service you perform for the fel orcs in your quest to reclaim Netherwing lands, we'll be at your side to make sure that they suffer a sufficient setback.\n\nYou'll need to keep a low profile so as not to draw any unwanted attention to yourself during your sabotage missions.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][11020] = {title = "A Slow Death", objective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to use Yarzill's Mutton in conjunction with Fel Glands to poison 12 Dragonmaw Peon Camps.", description = "The Dragonmaw have peons stationed at nearly every crystal formation up here. While the outright slaying of them would draw far too much unwanted attention to you, there is a way that we can thin their numbers and remain below the suspicious eyes of Mor'ghor.\n\nVenture into the wilds of Shadowmoon Valley and slay the tainted wildlife. Take from them their corrupt fel glands. Use those fel glands with this mutton that I'll give you near the peons. They'll take one bite and fall deathly ill!", progress = "It is dirty work, <name>.", completion = "&lt;Yarzill speaks in a low whisper.&gt;\n\nExcellent work, &lt;name&gt;. Lay low for now. Come back to me tomorrow and we can do it again.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11021] = {title = "Ishaal's Almanac", objective = "Bring Ishaal's Almanac to Sky Commander Adaris north of Skettis.", description = "This mysterious tome was on Talonpriest Ishaal's body.  It contains arcane symbols and charts of celestial bodies beyond your comprehension.\n\nAll writing is in a language you don't understand; likely an ancient version of the arakkoa written tongue.  Perhaps you should bring this to Sky Commander Adaris.", progress = "You've something to show me?", completion = "What have you brought to me?  I can't make out the writing on this tome, &lt;name&gt;... my loss of blood... must've blurred my vision.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11022] = {title = "Speak with Mog'dorg", objective = "Speak with Mog'dorg the Wizened. He stands atop the tower on the east side of the Circle of Blood in the Blade's Edge Mountains.", description = "<King/Queen> <name>!  You speak with Mog'dorg the Wizened before you leave and go to Ogri'la!", progress = nil, completion = "My good man, I am glad that you have decided to speak to me again before leaving.", rewards = nil}
MultiLanguageQuestData['en'][11023] = {title = "Bomb Them Again!", objective = "Sky Sergeant Vanderlip has tasked you with the bombing of 15 Fel Cannonball Stacks. Return to her at the Skyguard Outpost atop the Blade's Edge Mountains once you have done so.", description = "We're still having problems with those flak cannons, <name>.\n\nDon't get me wrong -- I think that you did an outstanding job the last time out -- but, that doesn't change the fact that those damned demons seem to be replenishing their ammo supplies faster than we can knock them out.  And that means we're having a hell of a time getting our people through there, not to mention the risk those demons pose to Ogri'la.\n\nWhat do you say?  Want to take another shot at it?", progress = "How goes the bombing run?", completion = "Outstanding work, &lt;name&gt;!  I'd have you back up in the air and bombing them again, but policy around here is to make sure that our pilots get plenty of R&amp;R.  Sorry, I don't make the rules, but I sure as hell enforce them!\n\nSee you again tomorrow, Ace!", rewards = "The following spell will be cast on you:\n\nBombing Run: On Quest Complete\n\nYou will receive:\n\nApexis Shard"}
MultiLanguageQuestData['en'][11024] = {title = "An Ally in Lower City", objective = "Bring Ishaal's Almanac to Rilak the Redeemed in Lower City inside Shattrath.", description = "There is an arakkoa in Lower City by the name of Rilak...  He can be trusted.  Take the book... to him.\n\n<Adaris drifts into unconsciousness as he returns the book to you.>", progress = "You have the smell of Skettis on you!  Explain yourself!", completion = "This cannot be... this belonged to a talonpriest once.  How did you ever come across it?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11025] = {title = "The Crystals", objective = "Chu'a'lor has tasked you with gathering 5 Apexis Shards. Bring them to him at Ogri'la atop the Blade's Edge Mountains.", description = "When prepared correctly, the crystals of the mountains exhibit strange powers, such as the clarity of mind that we have found here in Ogri'la.\n\nAll of the creatures atop the mountains covet the crystal shards and use them to further their own goals.  An economy has even sprung up around them.\n\nTo assist us, you must first learn about the Apexis shards.  Bring me some.  In addition to the creatures here having them, they can sometimes be found where the flayers dig at the larger crystals.", progress = "As you come to understand the shards and crystals, you will be better able to assist us in protecting ourselves and our ogre brethren below.\n\nThe shards themselves get their name from an ancient and now-extinct arakkoan civilization, which used to live atop the mountains here.\n\nDo you have the shards with you?", completion = "&lt;Chu'a'lor's left head begins to speak.&gt;\n\nThese will do fine.\n\nRemember, &lt;name&gt;, the value of the shard is not in what it can purchase for you.  It is not even in what it can potentially do for you when properly forged, though there is some debate over that.\n\n\n\nThe true value is in the journey to attain the shard.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11026] = {title = "Banish the Demons", objective = "Kronk has asked you to use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror atop the Blade's Edge Mountains. Return it to him once you have done so.", description = "You've arrived at the perfect time, friend!  We are in need of assistance.  In return, you will receive something very rare, which will help us both in the end.\n\nWe're not a violent ogre any longer, but the demons nearby threaten to overrun us and the Skyguard.  The problem with demons is that, once killed, they come right back in new bodies!\n\nBut, if you use this crystal to summon a banishing portal, when they die near it, their essences will be drawn in and banished back from whence they came!", progress = "We trust that you've used the banishing crystal to send a whole slew of those Burning Legion things packing?!", completion = "That'll teach them!  And, of course, now for your reward.\n\nThe demons of Forge Camp: Wrath, to the north, have created a special transporter on their southern border.   This experimental gate is being used to expand the forge camp, and we don't think we need to tell you how that will effect us if they expand too far.\n\nHowever, if we were you, we'd take this darkrune over to Gahk, and ask him how you can help.  Just take it easy on him, &lt;name&gt;.  Like you, he's new here.", rewards = "You will receive:\n\nDarkrune"}
MultiLanguageQuestData['en'][11027] = {title = "Yous Have Da Darkrune?", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nCrystalforged Darkrune"}
MultiLanguageQuestData['en'][11028] = {title = "Countdown to Doom", objective = "Return to Sky Commander Adaris with the news about Terokk's return.", description = "This almanac presages the return of Terokk, the most powerful and terrible Skettis king in arakkoa history.\n\nI always believed this to be the mere legend, <name>.  The return of the talonpriests and your recovery of this tome indicate otherwise.\n\nWith each day, Terokk comes closer to returning to full strength.  Your only chance is to bring him to our world prematurely.  Return to Skettis and speak to Adaris about this.  Let us hope he has the wisdom to do the right thing.", progress = nil, completion = "The arakkoa seek to bring Terokk back beyond the veil of time and Rilak... wants to find a way to accelerate the process?  Is he out of his mind?\n\n&lt;Adaris lays back down as his strength fades.&gt;\n\nYou've done your duty, &lt;name&gt;.  It is time you let my men take over from here.  This has become a purely military matter.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11029] = {title = "A Shabby Disguise", objective = "Use the Shabby Arakkoa Disguise to obtain the Adversarial Bloodlines from Sahaak and return to Hazzik.", description = "Open the package, <name>.  It is a disguise.  It doesn't look very convincing, does it?\n\nI craft them for ethereal smugglers in search of rare books.  There is an arakkoa scribe who dwells in the central island in Skettis, Terokk's Rest; his name is Sahaak.  He is old and nearly blind.\n\nUse the disguise to speak with him and obtain the book known as the Adversarial Bloodlines.  Be careful, <name>.  The disguise won't fool the other arakkoa.", progress = "The book, <name>.  Have you obtained it?", completion = "Excellent!  This book catalogs the descendants of Terokk's ancient enemies.  It is prophesied that their demise will be followed by Terokk's return.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11030] = {title = "Our Boy Wants To Be A Skyguard Ranger", objective = "Torkus has asked you to obtain an Unstable Flask of the Beast for him. Return with it to him at Ogri'la atop the Blade's Edge Mountains.", description = "<class>, we've got a problem -- we have lots of sons.  And ever since the Skyguard moved in nearby, all our sons ever talk about is joining their ranks.\n\nAs a proud father, we want them to have every advantage for when they apply.  So, would you go to the fel crystalforge at either forge camp to the north or south, and procure a magic flask for our sons?  You can't miss their green smoke.\n\nWe think that they take ten apexis shards to make.  We'd give you the shards, but we don't have any at the moment.", progress = "You have that magic flask, yet?  It will mean the world to little Torkus Jr.", completion = "You're a lifesaver, &lt;name&gt;.  Our boys are going to be so excited to hear the news!\n\nOK, so one down and one to go.  We did tell you about the other magical flask that they're going to need, didn't we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11031] = {title = "Archmage No More", objective = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", description = nil, progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits.", rewards = "You will be able to choose one of these rewards:\n\nViolet Signet of the Grand RestorerViolet Signet of the Great ProtectorViolet Signet of the Master Assassin"}
MultiLanguageQuestData['en'][11032] = {title = "Protector No More", objective = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", description = nil, progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits.", rewards = "You will be able to choose one of these rewards:\n\nViolet Signet of the Grand RestorerViolet Signet of the ArchmageViolet Signet of the Master Assassin"}
MultiLanguageQuestData['en'][11033] = {title = "Assassin No More", objective = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", description = nil, progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits.", rewards = "You will be able to choose one of these rewards:\n\nViolet Signet of the Grand RestorerViolet Signet of the Great ProtectorViolet Signet of the Archmage"}
MultiLanguageQuestData['en'][11034] = {title = "Restorer No More", objective = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", description = nil, progress = "You've decided against your previous choice?  I suppose I can help you reverse it.  In the end Dalaran cares more about your loyalty than how you choose to show it.\n\nIt won't be cheap.  And of course, I will need your old ring back.", completion = "Make this next decision carefully.  We do our best to accommodate our allies, but even Dalaran's resources have their limits.", rewards = "You will be able to choose one of these rewards:\n\nViolet Signet of the Master AssassinViolet Signet of the Great ProtectorViolet Signet of the Archmage"}
MultiLanguageQuestData['en'][11035] = {title = "The Not-So-Friendly Skies...", objective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover 10 Netherwing Relics.", description = "On the northeast edge of this island exists a dock used for the packaging and transport of Netherwing crystals and relics. Dragonmaw Transporters transport the goods from the dock to Dragonmaw Fortress while Dragonmaw Ascendants guard the ground from any would-be attackers.\n\nThis leaves one opening for you to make a strike at the Dragonmaw: The Dragonmaw Skyway.\n\nFly to the shattered islands of the Dragonmaw Skyway and ambush the transporters that use the route. Recover our stolen relics!", progress = "Dead orcs tell no tales, <name>. Make sure those Dragonmaw transporters do not escape.", completion = "&lt;Yarzill whispers.&gt;\n\nYou are doing the Netherwing a great service, &lt;name&gt;. Slowly, we will topple the Dragonmaw. From the inside a disease now grows - a disease with no cure...\n\nReturn to me tomorrow if you are interested in more work at the Dragonmaw Skyway.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11036] = {title = "Out of This World Produce!", objective = "Bring the Preserved Fruit to Rocket-Chief Fuselage at Area 52.", description = "I'll be the first to admit I'm not quite sure what this order is for, but Rocket-Chief Fuselage's instructions were very specific -- only the very best fruit, preserved to survive a long voyage and sealed against the elements.\n\nThere were other specifications, zero-gravity this and low pressure that. I don't pretend to understand it, but the price is right, so he'll get his superfood. Bring this crate to him up at Area 52. After crossing into Netherstorm, keep following the road until you see the town.", progress = "Is that the delivery from Old Orok?", completion = "&lt;The chief inspects the crate's contents.&gt;\n\nEverything looks good here. That's one more thing to cross off the list. Now all we need to do is get the rocket off the ground!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11037] = {title = "A Strange Vision", objective = "Speak with Rocket-Chief Fuselage at Area 52.", description = "I've had a most unusual vision, <name>, and I don't know quite what to make of it. I've seen an arrow, an immense arrow, riding into the sky on a trail of fire. Such a feat is trivial for a skilled mage, but somehow I know the arrow I saw is not the product of magic.\n\nIt will be unlike anything the people of Azeroth have ever achieved. You must seek out the people working on this, <name>. Lend them your help, for without it, their efforts may yet fail.", progress = nil, completion = "&lt;The chief listens as you describe the seer's vision.&gt;\n\nWell, I don't know about any of that, but we could certainly use your help around here. Behold the rocket behind me! That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11038] = {title = "Assist Exarch Orelis", objective = "\nSpeak with Exarch Orelis at Area 52.", description = "Not long ago, High Priestess Ishanah sent a small group of anchorites to Netherstorm, under the command of Exarch Orelis. They were to investigate the activities of Kael'thas and his minions, but we haven't received any reports of their findings yet.\n\nI worry that our presence in the area might not be strong enough to carry out the mission. I'm certain that the exarch could benefit from your knowledge and experience. Are you willing to travel to Area 52 and assist him?", progress = nil, completion = "So you're here to help us determine exactly what Kael'thas is planning? Your help is most welcome. Netherstorm is crawling with blood elf agents whose activities threaten to tear the land asunder.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11039] = {title = "Report to Spymaster Thalodien", objective = "Report to Spymaster Thalodien at Area 52.", description = "Some time ago, Voren'thal dispatched a small team to Netherstorm to investigate the activities of Kael'thas. Our leader has the utmost confidence in Spymaster Thalodien and his compatriots, and has decided to honor his request for reinforcements.\n\nThalodien's report was brief, but clear that he's encountered something of great importance. Report to him at Area 52 and assist him in any way possible, <name>.", progress = nil, completion = "&lt;A brief look of disappointment crosses the spymaster's face.&gt;\n\nI was hoping for at least a squad, but if Voren'thal saw fit to send only you, then I will adjust my plans accordingly.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11040] = {title = "Parts for the Rocket-Chief", objective = "Bring Bossi's Spare Parts to Rocket-Chief Fuselage at Area 52.", description = "You can count on one hand the number of times I've collaborated with a goblin. We're far more likely to be in competition with them, but when I received Rocket-Chief Fuselage's request, I just couldn't refuse him.\n\nThis crate is full of parts I'm not using here, but that the rocket-chief might be able to put to use on his project. Would you be kind enough to deliver them if you're on your way to Area 52?\n\nWho knows, maybe some fine gnomish parts could keep his creation from exploding!", progress = "That crate has the look of a master gnomish engineer about it. Did Bossi send you?", completion = "I don't even know what some of these parts do! I'm certain I'll find a use for some of them, but I never suspected I'd have to learn to think like a gnome!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11041] = {title = "A Job Unfinished...", objective = "Slay 10 Overmine Flayers and Barash the Den Mother. Return to Overlord Mor'ghor at the Dragonmaw Base Camp should you succeed.", description = "In the name of our great master... For the glory of Illidan!\n\nBy order of Overlord Mor'ghor, the great plateau of Netherwing Ledge is to be secured. With all Netherwing drakes captured or forced off of the land, rock flayers are running rampant and threatening crystal harvesting operations.\n\nDestroy them all, their den mother and her consort, Arvoar.\n\nMor'ghor commands it!\n\n<It would appear that this orc failed to take the plateau. It is time to prove your worth to Mor'ghor!>", progress = "Who dares approach Mor'ghor? This had better be important.", completion = "So from the remains of one of my own overseers you recovered the command and took matters into your own hands? You have managed to impress Mor'ghor. Well done...", rewards = "You will be able to choose one of these rewards:\n\nAscendant's BootsDragonmaw Augur's CinchDrake Tamer's GlovesSkybreaker's Mantle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11042] = {title = "A Mystifying Vision", objective = "Speak with Rocket-Chief Fuselage at Area 52.", description = "A strange vision haunts me, <name>. I see a continuous cloud of smoke ascending toward the sky, left in the wake of a giant fire moving ever faster away. It is not a natural phenomenon, nor a creation of evil; that much I know.\n\nI have no knowledge of what it looks like, save that it is the product of the labor of many. Yet, without more hands, it may never come to be.\n\nTravel to Netherstorm, <class>. Locate those responsible for this creation and offer them your aid.", progress = nil, completion = "&lt;The chief listens as you describe the seer's vision.&gt;\n\nWell, I don't know about any of that, but we could certainly use your help around here. Look at the behemoth behind me. That's the X-52...\n\nIsn't it the most beautiful thing you've ever seen?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11043] = {title = "Building a Better Gryphon", objective = "Speak with Brunn Flamebeard at Wildhammer Stronghold.", description = "I've heard that the Wildhammer dwarves maintain a gryphon roost at their fortress down in southern Shadowmoon Valley. If you're going down there, would you speak to them on my behalf? I have some ideas on how to improve their gryphons!\n\nWhy stop at armoring them when you could attach an altimeter, a rear view mirror, and rocket? Imagine how fast you could go with one of those babies strapped to your gryphon's back! I'll call it the TurboGryphon 8000!", progress = nil, completion = "&lt;Brunn's face reddens until its color is indistinguishable from his beard.&gt;\n\nHe wants to do WHAT to my gryphons?\n\nIf that little pipsqueak puts anything other than a saddle on them, I'll personally travel up to Blade's Edge and stuff that rocket o' his down his throat!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11044] = {title = "Visions of Destruction", objective = "Speak with Wing Commander Nuainn at Wildhammer Stronghold.", description = "A vision of cataclysm often disturbs my rest -- a rain of green fire falling to the earth, felling the valiant defenders of a mighty fortress. It has haunted me for weeks now, although I have only recently come to understand its meaning.\n\nTo the far east, in Shadowmoon Valley, the Wildhammer dwarves endure constant attacks from the Burning Legion and numerous other foes. They fight bravely, but without relief, their enemies will triumph. Go to their side, <name>. Help them in their fight.", progress = nil, completion = "A vision, you say? I don't care if he saw it in a vision, read it in a letter, or heard it from the mouth of a pit lord. He was dead on! What matters is that you're here, friend, and we need all the help we can get.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11045] = {title = "Zorus the Judicator", objective = "Speak with Zorus the Judicator at Wildhammer Stronghold.", description = "The history of Shadowmoon Valley is a long and troubled one. Few delve into it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Zorus the Judicator searches for the truth about the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which he would welcome help, I'm sure.\n\nIf you should venture into the valley, look for Zorus at Wildhammer Stronghold, in the central portion of the valley's southern region.", progress = nil, completion = "Fantei speaks the truth and I would welcome your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11046] = {title = "Chief Apothecary Hildagard", objective = "Speak with Chief Apothecary Hildagard at Shadowmoon Village.", description = "The history of Shadowmoon Valley is a long and troubled one. Few study it for fear of breathing new life into the unspeakable atrocities that took place there.\n\nNot all are so timid, though. Chief Apothecary Hildagard's research delves into the ghosts of Shadowmoon's past. It is a staggering undertaking, one with which she would welcome help, I'm sure.\n\nIf your travels bring you there, seek Hildagard at Shadowmoon Village, in the northwestern reaches of the valley.", progress = nil, completion = "Fantei has a good memory. It's been months since I was last in Shattrath to buy reagents. He's right, though. I could use the help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11047] = {title = "The Apprentice's Request", objective = "Speak with Dama Wildmane at Shadowmoon Village.", description = "As an apprentice wind rider master, one of my tasks is to care for the beasts when they're not flying. The problem is that we have so few here, there's very little downtime for any of them.\n\nI'm afraid we'll work them all to death if we don't receive any replacements. There's a large stable down in Shadowmoon Village, in western Shadowmoon Valley. Dama Wildmane oversees the wind rider care and training there.\n\nWould you speak with her on our behalf and let her know about our situation?", progress = nil, completion = "&lt;Dama listens to Agadai's request.&gt;\n\nI can't guarantee that there will be any wind riders available, but I'll see what I can do. As it is, we're having trouble keeping up with the demands of other buyers and outposts.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11048] = {title = "Kroghan's Report", objective = "Speak with Blood Guard Gulmok at Shadowmoon Village.", description = "My original orders were to remain in Garadar for a short time, then continue on and report to Blood Guard Gulmok at Shadowmoon Village. What I've seen in my time here is that Garadar could benefit from a long term Horde liaison.\n\nI know that Blood Guard Gulmok needs all the troops he can get, but I know he'll understand that my mission here isn't yet complete. Travel to Shadowmoon Village, in northwestern Shadowmoon Valley, and inform Blood Guard Gulmok of my delayed arrival.", progress = nil, completion = "&lt;Gulmok grumbles upon hearing of Kroghan's decision.&gt;\n\nI understand his point of view, but we need warm bodies in the trenches here too! The Legion's bombarding us with infernals day and night. If Kroghan's going to be delayed, you can take his place on the field!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11049] = {title = "The Great Netherwing Egg Hunt", objective = "Yarzill the Merc at Dragonmaw Base Camp in Shadowmoon Valley wants you to recover a Netherwing Egg.", description = "Should you discover any Netherwing eggs while exploring, bring them to me.\n\nBe warned, a Netherwing egg is a rare discovery. Do not become frustrated if you cannot locate one. These Dragonmaw have been very thorough in collecting most of them and shipping them off to parts unknown.\n\nEggs might be found on creatures of the island, near crystal formations, in the mines, or even inside a nethercite node or netherdust bush.\n\nKeep a low profile. We don't need Mor'ghor catching wind of your actions.", progress = "How goes the egg hunt?", completion = "Neltharaku will be most pleased, &lt;name&gt;. Well done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11050] = {title = "Accepting All Eggs", objective = "We don't need those eggs to get into the wrong hands, <name>. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", description = nil, progress = "We don't need those eggs to get into the wrong hands, <name>. Bring me any additional eggs that you may find.\n\nJust remember to keep a low profile and avoid raising suspicion!", completion = "You are a true hero, &lt;name&gt;.", rewards = nil}
MultiLanguageQuestData['en'][11051] = {title = "Banish More Demons", objective = "Kronk has asked you to use the Banishing Crystal to banish 15 demons at Forge Camp: Wrath or Forge Camp: Terror atop the Blade's Edge Mountains. Return it to him once you have done so.", description = "If we know the demons, and we do because we've studied them extensively, they're fast at work repairing any damage that has been done to their precious transporter.\n\nSo, if you want a chance at another darkrune, take our banishing crystal back out there and eliminate more demons.  Besides, you want to help us to lessen the threat that the demons pose, yes?\n\nWe said \"chance\" because the process we use yields mixed results.  You might get a darkrune, or you might get something else entirely.", progress = "A seasoned pro such as yourself shouldn't be having any difficulty banishing demons.  You're not having any difficulties, right, <race>?", completion = "We wish the process of creating a darkrune was foolproof, &lt;name&gt;.  Alas, it is not.  Please, take this bag and look in it to see what we've wrought today.  We couldn't bear to look ourselves.\n\nRemember, if you get a darkrune, take it to Gahk to exchange for a crystalforged darkrune.  Then you'll be able to once more bring down Shartuul's transporter.\n\nOh, and &lt;name&gt;, don't forget to come by again tomorrow and pickup the banishing crystal.  There are always more demons to be banished.", rewards = "You will receive:\n\nKronk's Grab BagApexis Shard"}
MultiLanguageQuestData['en'][11052] = {title = "Akama's Promise", objective = "Bring the Medallion of Karabor to A'dal in Shattrath City.", description = "<Akama inserts the crystal into the medallion in his hand.>\n\nI am not as strong as I once was, <name>.  Being so close to evil itself all these years - I do not know if I can trust myself with an artifact as powerful as this.\n\nTake this as my promise to you that when the time comes and you face Illidan, I will be on your side.  Take it to the one being we know we can trust with its power.  Take the medallion to A'dal in Shattrath City.", progress = "<A'dal notices your approach and a warm light embraces you.  A'dal seems to know you have something for him.>", completion = "&lt;As you give the medallion to A'dal, it disappears into his being in a flash of light.&gt;\n\n&lt;You are briefly shown a glimpse of a moment... perhaps in the future.  You see Akama and Maiev coming out of the Warden's Cage, fighting their way to the Dark Temple.  A third figure shrouded in shadows is aiding them.  Upon closer inspection you notice that the figure is you.&gt;", rewards = "You will be able to choose one of these rewards:\n\nAkama's SashAshtongue BladeBloodwarder's RifleVerdant GlovesSpellbreaker's BucklerStaff of the Ashtongue Deathsworn\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11053] = {title = "Rise, Overseer!", objective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", description = "Rare it is that a peon survives for as long as you have. Rarer still is when a peon rises from the dregs to attain a new rank.\n\n<Varkule claps.>\n\nThe Overlord has called for you, grunt. A new rank awaits, no doubt.", progress = nil, completion = "I have been following your activities closely, &lt;name&gt;. You have proven to be an invaluable asset to Dragonmaw. With that said, I am going to promote you to Overseer. With that rank comes new responsibilities that you must fulfill.\n\nRise, Overseer &lt;name&gt;! Rise and seek out those that need your assistance at the base camp.", rewards = "You will receive:\n\nOverseer's Badge"}
MultiLanguageQuestData['en'][11054] = {title = "Overseeing and You: Making the Right Choices", objective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 10 pieces of Knothide Leather and 1 Hardened Hide of Tyrantus.", description = "So you're the new overseer, eh? Well there's one thing any good overseer needs and that's the proper disciplinary weapon. Before you can go out there and knock some sense into these peons you need to have your \"piece.\" Each overseer has to gather the materials required to make their own \"piece\" and you'll be no different.\n\nI'll need knothide leather and the hardened hide of Tyrantus. You'll find Tyrantus in Eco-Dome Farfield, located in the northern reaches of Netherstorm.", progress = "There's peons to be disciplined, <name>! Hurry it up!", completion = "ARRR! You might make it as an overseer after all. That oversized lizard has been the bane of many an orc!\n\n&lt;Chief Overseer Mudlump begins to fashion the weapon.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11055] = {title = "The Booterang: A Cure For The Common Worthless Peon", objective = "Chief Overseer Mudlump at the Dragonmaw Base Camp in Shadowmoon Valley wants you to discipline 20 lazy Dragonmaw Peons. You will also need to return your Booterang.", description = "This is your booterang. There are many like it but this one is yours.\n\nAs an overseer you will use this booterang to sow terror into the hearts of defiant peons. Proper use of the booterang will instill obedience and ensure subservience.\n\nVenture forth to the crystal fields and discipline any peons that you see slacking off. Show them the might of the booterang!", progress = "It's all in the wrist, <name>.", completion = "A hard day's work! It pays off, though, doesn't it? Warms your heart seeing those worthless runts slavering over those crystals... Anyhow, that's all for today. Come back tomorrow for another round of booterang discipline.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11056] = {title = "Hazzik's Bargain", objective = "Obtain Hazzik's Package at his dwelling in eastern Skettis and return to him with it.", description = "Do not draw attention to our conversation.  Adaris would not approve.\n\nI belong to the lowest caste of arakkoa, <name>.  During Terokk's rule I would've been sacrificed to the dark powers worshipped by his talonpriests.  If what you say is true and the talonpriests are seeking Terokk's return, then you must prevent them from succeeding - regardless of what your leader says!\n\nI've something to offer you that you'll find useful.  There is a package at my old dwelling in Upper Veil Shil'ak.  Bring it to me!", progress = "You've returned, <name>.  I was beginning to think you'd given up on me.", completion = "Excellent, &lt;name&gt;.  You will see that I'm true to my word.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11057] = {title = "The Trouble Below", objective = "Chu'a'lor has asked you to speak with Mog'dorg the Wizened atop one of the towers just outside the Circle of Blood in the Blade's Edge Mountains.", description = "We commend your zeal in wanting to help out here in Ogri'la, <class>.  However, we have a favor to ask of you before we can accept your assistance.\n\nDown below our brethren are enslaved to the Sons of Gruul.  Please, speak with Mog'dorg the Wizened, who is leading an ogre resistance against their gronn masters.\n\nSeek him out atop the tower on the eastern side of the Circle of Blood arena.", progress = nil, completion = "You were sent from on high?  Truly my mission is blessed!  I am trying to save the Bloodmaul from annihilation by the Bladespire clan, and Gruul's sons, who are backing them.\n\nI trust that you will be the one to aid our secret society and deliver us into freedom.", rewards = nil}
MultiLanguageQuestData['en'][11058] = {title = "An Apexis Relic", objective = "Chu'a'lor has asked you to return to him at Ogri'la atop the Blade's Edge Mountains after you have gained Apexis Vibrations from an Apexis Relic.", description = "Long ago a now-extinct sect of the arakkoa known as the Apexis lived here.  Remnants of their civilization are still present.  We call them apexis relics.\n\nWhat we know about them is that, when properly used, they grant a boon.  Each relic presents a colored sequence which, when the crystals are pressed in the correct order, leads through a series of levels, each harder than the last.\n\nAn apexis shard is needed to power the relic.  Return when you have attained the insight of the apexis vibration.", progress = "Have you learned how to use the apexis relic yet?  Both we and the Sha'tari Skyguard just to the north are interested in what you learn about them.", completion = "&lt;Chu'a'lor nods his heads at you in satisfaction at your accomplishment.&gt;\n\nYou have a quick mind, &lt;name&gt;.  It took us much longer to successfully make use of the relic.\n\nNow that you know how, you can do so as much as you care to.  Just remember that they require an apexis shard to power them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11059] = {title = "Guardian of the Monument", objective = "Chu'a'lor has asked you to obtain an Apexis Guardian's Head for him as proof. Return with it to him at Ogri'la atop the Blade's Edge Mountains once you have done so.", description = "You've figured out how to use the single-person relics, but as you may have seen, there are bigger ones, which they surround.\n\nThese larger apexis monuments function in much the same way, but they take many more apexis shards to activate and require four persons to operate.\n\nOf greater concern to us are the guardians that are summoned through their use.  These crystal constructs turned on their arakkoan masters long ago, and now endanger Ogri'la.\n\nWe would ask that you destroy one and bring us proof.", progress = "We abhor violence, but at least the construct that we have sent you against isn't a living being.\n\nSpeaking of which, do you have the head?", completion = "&lt;Chu'a'lor beams at you with obvious respect.&gt;\n\nNot only are we impressed with the mental alacrity of you and your friends, but we are indebted to you, as is all of Ogri'la and the Skyguard, for helping to protect our way of life here.\n\nAnd remember, &lt;name&gt;, at any time you can gather others and return to any of those larger apexis monuments to make use of them; as long as you have enough apexis shards to power it that is.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11060] = {title = "A Crystalforged Darkrune", objective = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  <race> give Gahkdarkrune, us give <race> crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", description = nil, progress = "Da demons are making da Forge Camp: Wrath bigger.  Soon, dey be too big and crush us.  You crush dem first!\n\nShartuul's transporter is da key, but it protected by a magic shield and a demon called a degrader.  Us powerful warlock, and make special darkrune dat give you control of da degrader.  <race> give Gahkdarkrune, us give <race> crystalforged darkrune back.\n\nTake control of da degrader and possess as many of da demons dat come through da gate as you can ta stop dem!", completion = "Little &lt;race&gt;, remember, when you control da degrader, you use its hammer ta smash da warp-gate's shield and let loose da demon within.\n\nDen you crush dat demon and control it.  Den another demon come and you control it, until da eredar overseer come.\n\nDen you crush him too!!!", rewards = "You will receive:\n\nCrystalforged Darkrune"}
MultiLanguageQuestData['en'][11061] = {title = "A Father's Duty", objective = "Torkus has asked you to obtain an Unstable Flask of the Sorcerer for him. Return with it to him at Ogri'la atop the Blade's Edge Mountains.", description = "As to that other magical flask, it can only be obtained from one spot: Bash'ir Landing.  It's an ethereal base, and they aren't too friendly with outsiders, so it might be a little dangerous to obtain.\n\nWhere's Bash'ir Landing, you ask?  Well, if you get on your flying steed and head north by northeast, well past Forge Camp: Wrath, you'll eventually spot it.  The Bash'ir crystalforge itself is at the northeast corner of the landing.\n\nThank you for doing this, <name>.  It'll mean the world to our sons!", progress = "That sorcerer's flask is sure to make my boys more intelligent than they already are, and that should help immensely with what they'll need to do once they're in the Sha'tari Skyguard.", completion = "We can't thank you enough, &lt;name&gt;!\n\nNow with these two flasks, unstable though they may be, we'll be able to send one of our boys north to the Skyguard Outpost.\n\nHere, just wait a moment and we'll call for one of them.", rewards = "The following spell will be cast on you:\n\nPeriodic - Summon Torkus Jr.\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11062] = {title = "The Skyguard Outpost", objective = "Chu'a'lor has asked you to speak with Sky Commander Keller at the Skyguard Outpost atop the Blade's Edge Mountains.", description = "<name>, we were wondering if you might be willing to visit our friends just to the north at the Skyguard Outpost?\n\nSky Commander Keller and his Skyguard are here running missions for our mutual protection, and he's asked us to send along anyone that we feel would excel at helping out.\n\nThat would be you!\n\nHead up there as soon as you can, and please, give him our regards.", progress = nil, completion = "Welcome ta the Skyguard Outpost!  I built it with me own hands ya know.\n\nYeah, the whole thing!\n\n&lt;The sky commander looks serious.&gt;\n\nSo, ye must be lookin' ta spoil for a fight if ye're here talkin' ta me.  It was kind of old Chu'a'lor ta send ye along.  We can always use fresh meat for the grinder around here.\n\nIf ye don't mind, I'd like ya ta start by having a talk with my sergeant across the way: Vanderlip.  Don't mind her tongue, though it be sharper than the greatsword she be carrying.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11063] = {title = "Earning Your Wings...", objective = "So you wanna join the Skybreakers, eh? You've certainly proven yourself an able Dragonmaw but that means nothing in the skies of Outland. The question has to be answered: CAN YOU FLY?\n\nAnd I don't just mean being able to mount up on a nether drake and delivering a shipment of crystals to the fort like those transporter scrubs. I'm talking about being the best... The top orc...\n\nOver to the west there are six riders. Defeat them all and I will grant you Skybreaker wings.", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][11064] = {title = "Dragonmaw Race: The Ballad of Oldie McOld", objective = "Follow Murg \"Oldie\" Muckjaw while attempting to stay on your flying mount. Should you defeat Murg \"Oldie\" Muckjaw, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "Don't let the gray hair fool you, grunt. I'm still ten times the rider that you are! And don't go thinking that this old dog doesn't have any tricks up his sleeve.\n\nNow all you gotta do is follow me and try not to get knocked down off your mount. If you can do that, Oldie will admit defeat.\n\nWe'll lift off as soon as you're ready.", progress = nil, completion = "Pumpkins? Oh how the mighty have fallen... I am certain the other riders will prove to be much more challenging.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11065] = {title = "Wrangle Some Aether Rays!", objective = "Skyguard Khatie has asked you to wrangle 5 Aether Rays. After you have done so, return them to her at the Skyguard Outpost atop the Blade's Edge Mountains.", description = "Wanna help the Skyguard and Ogri'la?\n\nJust hear me out before you walk away, <hot stuff/girly>.  We're in need of remounts!  The bombing runs and missions to Bash'ir Landing have taken a toll on our mounts.\n\nThe aether rays that fly around Vortex Pinnacle, and the Crystal Spine to the northeast, look like they'd do just fine.  You don't even have to bring them back here, though that would be nice.  Just break and rope them, and we'll track them down later.\n\nThink you can wrangle me up some?", progress = "You wrangle me some aether rays yet?  You look like you might have some skill with rope, so it shouldn't take you too long.", completion = "Woo hoo!  Nice job, &lt;name&gt;!  Those rays are going to make excellent mounts!\n\nStick around kid... the Sha'tari Skyguard can always use a man of your obvious talents!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11066] = {title = "Wrangle More Aether Rays!", objective = "Skyguard Khatie has asked you to wrangle 5 Aether Rays. After you have done so, return them to her at the Skyguard Outpost atop the Blade's Edge Mountains.", description = "So, I hope that you're up to helping us wrangle up even more aether rays!  From what I can see, you're a natural with the rope!  And it's for a good cause, because not only do we get fresh mounts, but it helps us to protect Ogri'la, which the ogres appreciate.\n\nRemember, the aether rays fly around Vortex Pinnacle, and the Crystal Spine to the northeast.\n\nThink you can wrangle me up some more?", progress = "You're doing great work for us, <name>.  I want you to know that we really appreciate everything that you're doing to keep us stocked up in fresh mounts!", completion = "You continue to amaze me!  Tell you what... why don't you come back tomorrow and we'll let the rope cool off for now?\n\n&lt;Khatie laughs.&gt;\n\nThank you so much, &lt;name&gt;!", rewards = "You will receive:\n\nApexis Shard"}
MultiLanguageQuestData['en'][11067] = {title = "Dragonmaw Race: Trope the Filth-Belcher", objective = "Follow Trope the Filth-Belcher while attempting to stay on your flying mount. Should you defeat Trope the Filth-Belcher, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "Dragonmaw treat you right, <name>. Even a worn out cursed being like me is given a chance. Now if you want to prove your worth to the Skybreakers, you will have to defeat me.\n\nI'm going to shake you off my tail like a bad case of fleas...\n\nWe'll lift off when you are ready.", progress = nil, completion = "Interesting... Your next match will undoubtedly prove much more difficult. Corlok is no slouch.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11068] = {title = "Dragonmaw Race: Corlok the Vet", objective = "Follow Corlok the Vet while attempting to stay on your flying mount. Should you defeat Corlok the Vet, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "You are challenging ME? Don't make me laugh!\n\nYou're serious? Very well then! All you need to do is not die. You can manage to not die, right?? Even if I'm hurling skulls at you and flying circles around your pathetic riding skills?\n\nJust let me know when you're ready and we'll lift off.", progress = nil, completion = "The next two riders were the two top pilots that the dwarves and orcs of Azeroth had to offer. You stand no chance!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11069] = {title = "Dragonmaw Race: Wing Commander Ichman", objective = "Follow Wing Commander Ichman while attempting to stay on your flying mount. Should you defeat Wing Commander Ichman, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "Three years I spent in that hell hole. Three years a prisoner of war to the damnable Frostwolf Clan. Made to sit in their tower and listen to them endlessly whine about the bridge to Dun Baldar. About how it's \"unfair\" that blah, blah, blah, blah... War isn't fair! To hell with 'em all!\n\nThe minute I was freed I left that place forever and came here to start a new life. Now Mulv and I are vying for the top orc spot. If you want it, you're gonna have to go through me, scrub.\n\nWe go when you're ready.", progress = nil, completion = "I don't believe it! Mulverick is your next challenge. There's no way you'll survive that match.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11070] = {title = "Dragonmaw Race: Wing Commander Mulverick", objective = "Follow Wing Commander Mulverick while attempting to stay on your flying mount. Should you defeat Wing Commander Mulverick, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "Three years of blood, sweat and tears. Mostly tears... The amount of crying that a hardened soldier does when it comes down to all-out war is amazing!\n\n\"They're jumping into our tower with their horses!\" \"Why is their base so well defended?\" \"They're taking our relief hut, I'm going A.W.O.L.!\"\n\nWimps...\n\nI took the first train out of \"cry-town\" the minute the Dark Portal opened. Now I'm a top gun for the Dragonmaw. If you want to be top orc, you'll have to defeat me.\n\nWe go when you are ready.", progress = nil, completion = "Well it looks like it's just you and the captain now, grunt. Good luck! You're gonna need it!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11071] = {title = "Dragonmaw Race: Captain Skyshatter", objective = "Follow Captain Skyshatter while attempting to stay on your flying mount. Should you defeat Captain Skyshatter, report your victory to Ja'y Nosliw at the Dragonmaw Base Camp in Shadowmoon Valley.", description = "You dare challenge Skyshatter? The world around you will fall into darkness as the heavens are torn asunder by my meteors.\n\nYou stand no chance, soldier. Yet it is your desire to die...\n\nI will entertain this morbid obsession if only to prove a point to any that might foolishly dream of making the same mistake.\n\nWe ride when you are ready!", progress = nil, completion = "I never dreamed any would be skilled enough to defeat Skyshatter. You do know what this means, right? You are now the top orc! You must defend your title.", rewards = "You will receive:\n\nSkybreaker Whip"}
MultiLanguageQuestData['en'][11072] = {title = "Adversarial Blood", objective = "Find the Skull Piles in the middle of the summoning circles of Skettis. Summon and defeat each of the descendants by using 10 Time-Lost Scrolls at the Skull Pile. Return to Hazzik at Blackwind Landing with a token from each.", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book: Gezzarak the Huntress, Karrog the crystal giant, the heretic known as Darkscreecher Akkarai and Vakkiz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa to call them forth at the summoning circles in Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nTime-Lost Offering"}
MultiLanguageQuestData['en'][11073] = {title = "Terokk's Downfall", objective = "Take the Time-Lost Offering prepared by Hazzik to the Skull Pile at the center of Skettis and summon and defeat Terokk. Return to Sky Commander Adaris when you've completed this task.", description = "I... I've turned a blind eye to your dealings with the arakkoa prisoner, <name>.  It looks like your instincts to cooperate with him were right.\n\nYou must understand... I would've faced a mutiny in my current state if I endorsed your efforts to bring Terokk to this world.\n\nTake the items that Hazzik prepared for you and go ahead with your plan.  I will command my men to back you up when the time comes.  I recommend that you bring a force of your own as well.  I fear you'll only get one chance at this.", progress = "Is it done, <name>?  Has Terokk been defeated?", completion = "You've made us all very proud, &lt;name&gt;.  I'll send word of your deeds back to Shattrath.  The Skyguard will be forever in your debt.", rewards = "You will be able to choose one of these rewards:\n\nJeweled RodScout's Throwing KnivesSeverin's CaneWindcharger's Lance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11074] = {title = "Tokens of the Descendants", objective = "Collect Time-Lost Scrolls from the time-lost arakkoa in Skettis and bring them to a Skull Pile inside a summoning circle in Skettis. Summon and defeat the descendants of Terokk's adversaries and return to Hakkiz with Akkarai's Talon, Garokk's Spine, Vekkaz's Scale and Gezzarak's Claw.", description = "The descendants held prisoner by the Skettis talonpriests are listed in this book.  Gezzarak the Huntress, Garokk the Crystal Giant, the heretic known as Darkscreecher Akkarai and Vekkaz the Windrager.  They will all need to be slain before Terokk returns to this world.\n\nYou will need the scrolls carried by the time-lost arakkoa and burn them at the summoning circles all over Skettis.  Bring me a token from each one.  These are powerful beings you will be facing; you would do well to bring friends.", progress = "I require a token from each of the descendants of Terokk's greatest adversaries.  Only then will we be ready to summon Terokk.", completion = "Excellent!  Take this.  I've prepared this bundle with the items you obtained.  They will allow you to summon Terokk.\n\nBeware, &lt;name&gt;.  He is the most powerful arakkoa to ever exist.  Do not underestimate him!", rewards = "You will receive:\n\nTime-Lost Offering"}
MultiLanguageQuestData['en'][11075] = {title = "The Netherwing Mines", objective = "Seek out the Mistress of the Mines on Netherwing Ledge.", description = "Your help is required at the Netherwing Mines, overseer <name>.\n\nTwo days ago our mining operations came to a grinding halt when we made a grim discovery. A miner was working in the depths of the mine and struck his pick upon an unusual crystal formation. Unfortunately, this crystal formation was attached to a very angry nether dragon. The beast woke from its slumber and annihilated all of our workers.\n\nReport to the Mistress of the Mines. They await you at the mouth of the mines, southwest of here.", progress = nil, completion = "The miners are working hard but none dare step foot further into the mines. They choose death rather than being forced to mine deeper! It is going to be your job to carry out the duties and tasks that they failed to complete.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11076] = {title = "Picking Up The Pieces...", objective = "The Mistress of the Mines at the Netherwing Mines in Shadowmoon Valley wants you to recover 15 Nethermine Cargo crates.", description = "Much of our hard work lies scattered about in these mines. Carts full of cargo are littered across every inch of this mine! We just can't get to any of it with the current infestation.\n\nThat's where you come in, <name>. Your daily duty here at this mine is to collect the cargo left behind by the miners and deep mine workers.\n\nGather the nethermine cargo and return it to me or my sister.", progress = "Have you gathered the cargo?", completion = "Well done, &lt;name&gt;. Return tomorrow for another mission into the depths of the mine.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11077] = {title = "Dragons are the Least of Our Problems", objective = "The Dragonmaw Foreman at the Netherwing Mines in Shadowmoon Valley wants you to kill 15 Nethermine Flayers and 5 Nethermine Ravagers.", description = "That dragon waking up riled up a host of other nasty creatures in these mines. Two types are proving to be a thorn in the side of the Dragonmaw: Nethermine flayers and Nethermine ravagers. You must help us by killing them off. All I ask is your involvement once per day.\n\nGet in there and kill as many as you can!", progress = "How's that flayer infestation problem coming along?", completion = "That'll be enough for today, overseer. Come back tomorrow for another round of clean up.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11078] = {title = "To Rule The Skies", objective = "Sky Commander Keller has asked you to acquire Dragon Teeth and return them to him at the Skyguard Outpost atop the Blade's Edge Mountains.", description = "As ye've flown around, ye must have noticed the dragons above.  I trust ye haven't fallen victim ta their rage.  Help us put an end ta it, <name>!\n\nRivendark and Obsidia lord over this terrace, while Insidion and Furywing rule the skies over yon terrace ta the northeast.  Each has a perch on their respective domains.  I be wondering if ye and yer friends will go ta one, <lad/lass>, break open an egg and attract the dragon down.\n\nBring me some teeth as proof.  Ta rule the skies, it's either them or us.", progress = "How fares yer mission, <name>?  I needn't tell ye how important this be ta our continued ability ta fly around up here.", completion = "Yes!  Those teeth look like they be sharp enough ta cut through just about anything!\n\nAnd let me encourage ye and yer friends ta keep up the good work!  Those dragons be fierce predators that make the skies wholly unsafe.\n\nYe might have noticed, too, the dragon scales.  I hear they be good fer making powerful cloaks if ye get one o' each o' their scales.  And if yer not happy with the cloak ya get, I'll be willing ta trade ye an apexis crystal fer it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11079] = {title = "A Fel Whip For Gahk", objective = "Gahk has asked you to acquire a Fel Whip. Bring it to him at Ogri'la atop the Blade's Edge Mountains.", description = "Gahk think being smart is dumb sometimes.  Gahk not want to think.  Me want little <race> to smash big demons!\n\nDey have some chiefs, and da chiefs all have whips to hurt da little demons.  You bring Gahk a whip!\n\nYou challenge demon chief in forge camps at burning, green, fel crystal prism.  Use many apexis shards to get dem to come.  Dey called Galvanoth, Braxxus, Zarcsin and da Mo'arg Incinerator.", progress = "Yous have da whip?", completion = "Gahk like whip.  Maybe Gahk take whip and beat demons with it!\n\nMe say to &lt;race&gt; that &lt;race&gt; summon demon chiefs anytime &lt;race&gt; have friends and many shards.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11080] = {title = "The Relic's Emanation", objective = "Chu'a'lor has asked you to return to him at Ogri'la atop the Blade's Edge Mountains after you have gained Apexis Emanations from an Apexis Relic.", description = "Now that you have felt the enlightening vibrations of the apexis relics, it is time for you to further your understanding of their workings.  We are very eager to benefit from your observations!\n\nAs you progress in your ability to attune to the relics, you will gain a higher level of knowledge.  This recognition will come in the form of an emanation from the relic.\n\nReturn to us when you have attained such an emanation.", progress = "Do you have the emanation from the apexis relic about you?", completion = "You continue to amaze us with your acumen as concerns the relics, &lt;name&gt;.  May we suggest that you practice with the relics at least once a day to maintain such a sharp edge to your mental acuity?", rewards = "You will receive:\n\nApexis Shard"}
MultiLanguageQuestData['en'][11081] = {title = "The Great Murkblood Revolt", objective = "Take the Murkblood Escape Plans to the Mistress of the Mines.", description = "This document outlines a revolt planned by the Murkblood broken. It seems that the dragon was to be used as a diversion to draw attention away from their escape. Looking at all of the corpses littering the mine, it would be safe to assume that their plans failed.\n\nReturn the escape plans to the Mistress of the Mines.", progress = "What's this?", completion = "Excellent work, overseer. Mor'ghor will hear of your outstanding service to the Dragonmaw.\n\nNow back to these Murkblood dogs. They plan an escape, eh? Dare they defy the one true lord of Outland? Their masters will pay for this!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11082] = {title = "Seeker of Truth", objective = "Find a Murkblood Overseer and interrogate him. Return to the Mistress of the Mines with the Murkblood information and the Hand of the Overseer.", description = "These miners are far too stupid to concoct any type of escape plan. We must find and punish the source. Venture into the depths of the mine and seek out the Murkblood overseers. If they have not been overcome by the denizens of the mine, they will undoubtedly be hiding.\n\nOnce you locate one, interrogate him until he reveals the true mastermind behind the escape. Return to me with the identity of this traitor and the hand of the overseer.", progress = "Well? What's taking so long?", completion = "Nothing to say? Perhaps as he lies bleeding to death on the floor of this cursed mine he will remember... Remember what it means to cross the forces of Illidan!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11083] = {title = "Crazed and Confused", objective = "Ronag the Slave Driver in the Netherwing Mines of Shadowmoon Valley wants you to slay the Crazed Murkblood Foreman and 5 Crazed Murkblood Miners.", description = "Don't worry about this dragon, <name>. We've got plans for it...\n\nDeeper in this mine is a band of crazed Murkblood. After the dragon broke out, they were cut off from the exit. Somehow, after a mere 2 days of isolation, they've lost all sense of decency.\n\nThey've resorted to cannibalism and the promotion of mayhem. We don't need that kind of madness in this place. Find 'em and kill 'em. All of 'em.", progress = "Is the problem \"solved\"?", completion = "Yeah, I don't understand it... You would think that they wouldn't even be that hungry after 2 days. Murkblood...\n\n&lt;Ronag shakes his head.&gt;\n\nDamn they're stupid...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11084] = {title = "Stand Tall, Captain!", objective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", description = "Well, well, well... still alive I see. That's good, because Mor'ghor has requested your presence in his tower at once. Get a move on!", progress = nil, completion = "&lt;Mor'ghor nods.&gt;\n\nThat's right, I said captain. You've earned another promotion, &lt;name&gt;.\n\nYou certainly don't work like any fel orc I've ever seen. Keep this up and you might make overlord some day.\n\nNow get out there and take command. I would suggest you try and earn your Skybreaker wings.", rewards = "You will receive:\n\nCaptain's Badge"}
MultiLanguageQuestData['en'][11085] = {title = "Escape from Skettis", objective = "Escort the Skyguard Prisoner to safety and report to Sky Sergeant Doryn.", description = "Hail, <name>.  I thank you for coming to my aid.\n\nThe arakkoa's monstrous birds knocked me from my nether ray while on a scouting mission.\n\nLet's get out of here, while we can.", progress = "Yes, <name>?", completion = "Thank you for rescuing one of our scouts, &lt;name&gt;.  We lose good people every day and there aren't enough new recruits to replace them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11086] = {title = "Disrupting the Twilight Portal", objective = "Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley wants you to kill 20 Deathshadow Agents.", description = "One of your responsibilities as a captain of Dragonmaw is to snuff out Burning Legion activity in Outland. It is your duty to silence those that defy Lord Illidan!\n\nThe demons foolishly attempt to stabilize the portal found on the Twilight Ridge of western Nagrand. They must pay for their treachery, and you will be the orc that collects on their debt.\n\nTravel to the Twilight Ridge and lay waste to its inhabitants. You will be responsible for making at least one attack per day on their fortifications.", progress = "It was our lord, after all, that banished the demons from Outland and closed their portals. All should bow down to the magnificence of Illidan.", completion = "Excellent work, captain! Lord Illidan will hear of your heroism!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11087] = {title = "HYJAL FLAG", objective = "Soridormi at Caverns of Time wants you to retrieve Vashj's Vial Remnant from Lady Vashj at Coilfang Reservoir and Kael's Vial Remnant from Kael'thas Sunstrider at Tempest Keep.", description = "Seven vials were drawn from the Well of Eternity by Illidan.  He poured three into the lake on top of Mount Hyjal and a second Well of Eternity was created.  For years the rest were believed lost.\n\nWith the opening of the Dark Portal, we've come to know that he gave one each to his lieutenants Kael'thas and Vashj.  Retrieve what remains of them; we will need them as foci to open a gateway to any events tied to Mount Hyjal, recent or ancient.  The outcome of the Battle of Mount Hyjal must be preserved.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11088] = {title = "<DEPRECATED>Unravelling Your Training", objective = "Bring Jonathan LeCraft 10 pieces of Spellfire cloth.", description = "Bring me a lot of Spellfire cloth, and then you can forget everything.You will learn:\n\n", progress = nil, completion = nil, rewards = "You will learn:\n\nUnlearn Spellfire Tailoring"}
MultiLanguageQuestData['en'][11089] = {title = "The Soul Cannon of Reth'hedron", objective = "Illidari Lord Balthas at the Dragonmaw Base Camp in Shadowmoon Valley wants you to bring him 2 Felsteel Bars, 1 Adamantite Frame, 1 Khorium Power Core and 1 Flawless Arcane Essence.", description = "Reth'hedron now lords over the Twilight Ridge of Nagrand. An eredar of such power being loosed upon this world does not bode well for the Illidari. Alas, we do not have the resources required to slay Reth'hedron. Not with the war the bastards have brought to the Black Temple. No... I have a better plan.\n\nYou will subdue Reth'hedron, banishing him back through the Twilight Portal. For this a soul cannon must be fashioned.\n\nReturn to me with the materials on this list.", progress = "Have you gathered the components required to fashion the soul cannon?", completion = "&lt;Balthas deftly combines the components you brought him.&gt;\n\nYou are now ready for the second phase of the plan, captain.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11090] = {title = "Subdue the Subduer", objective = "Illidari Lord Balthas at Dragonmaw Base Camp in Shadowmoon Valley has tasked you with using the Soul Cannon on Reth'hedron the Subduer in Nagrand.\n\nYou must also return the Soul Cannon.", description = "<Balthas holds up an alien looking device.>\n\nThis is a soul cannon. Its effects are devastating when attuned. This one is attuned to my blood. The same blood flowing through the veins of Reth'hedron - my brother. Aye, his misplaced allegiance will be the end of him.\n\nTake the cannon and fly to the Twilight Ridge in western Nagrand. Locate Reth'hedron and fire! You must stay on your mount and within range for the effects to take hold. Stand your ground against him and he will have no choice but to flee!", progress = "Is it done?", completion = "He will be back, but for now the Legion's war against Lord Illidan is weakened. He shall know of your deeds, captain.", rewards = "You will be able to choose one of these rewards:\n\nHorns of the IllidariIllidari Lord's TunicIllidari Rod of DisciplineLegguards of Contemplation\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11091] = {title = "A Special Thank You", objective = "Chu'a'lor suggested that you speak with Jho'nass at Ogri'la atop the Blade's Edge Mountains.", description = "You honor us with your efforts on our behalf.  And now there is someone that we would like for you to meet.\n\nJho'nass is our most trusted quartermaster.  He maintains a stock of goods that we provide for sale to only the most dedicated of friends to Ogri'la.\n\nYou are one such friend, <name>.\n\nWhen you find the time, go and speak with him.  As we understand it, he has prepared a little something for you as a token of our appreciation.", progress = nil, completion = "Hey, man, that's great.  We hear you've been doing good things.  That's cool.  We've got a feeling that you're going to make things right for us here in Ogri'la, and keep us safe, and everything nice and mellow.\n\nHere, take this.  It's nothing much, just a care package that we whipped up as a thanks for your effort.\n\nFeel free to look around at our goods.  We have a lot of really choice stuff that you're gonna want to get.", rewards = "You will receive:\n\nOgri'la Care Package"}
MultiLanguageQuestData['en'][11092] = {title = "Hail, Commander!", objective = "Speak with Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", description = "Captain <name>!\n\n<Taskmaster Varkule salutes you.>\n\nOverlord Mor'ghor has asked to see you in his chambers at once!", progress = nil, completion = "Lord Illidan himself has asked that I promote you to the rank of commander! This is unprecedented. You will be the first Dragonmaw to reach such a rank outside of the Black Temple.", rewards = "You will receive:\n\nCommander's Badge"}
MultiLanguageQuestData['en'][11093] = {title = "Hungry Nether Rays", objective = "Use the Nether Ray Cage in the woods south of Blackwind Landing and slay Blackwind Warp Chasers near the Hungry Nether Ray. Return to Skyguard Handler Deesak when you've completed your task.", description = "Nether rays are surprisingly loyal and obedient once properly trained.  Unfortunately the war on Skettis is taking a toll on them.\n\nWe have dozens of sorties a day - the poor fellows rarely get a break.  And with recent shortages on feed, if those blasted birdmen don't kill them on a mission then starvation will.\n\nIf you can lend a hand, take one of our rays to the woods in the south.  They don't mind warp chaser meat as long as it's a fresh kill.", progress = "You're back!  Did your ray behave well?", completion = "Thanks for taking care of the ray, &lt;name&gt;.  Goodness knows these guys fly much better when they're well-fed.  We don't want our boys getting shot down because their ray was too weak to fly.", rewards = "You will be able to choose one of these rewards:\n\nElixir of Major AgilityAdept's Elixir\n\nThe following spell will be cast on you:\n\nNether Ray Desummoner\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11094] = {title = "Kill Them All!", objective = "Deliver news of your mission along with the Dragonmaw Flare Gun to Arcanist Thelis at the Sanctum of the Stars in Shadowmoon Valley.", description = "Commander <name>, stand at attention! You are to take a battalion of Skybreakers and sack the Scryers' outpost located at the foot of the Netherwing Fields. With the Sanctum of the Stars destroyed, our lines of communication to our posts at Eclipse Point and Illidari Point will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11095] = {title = "Commander Hobb", objective = "Give the Dragonmaw Flare to Commander Hobb at the Sanctum of the Stars in Shadowmoon Valley.", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, <name>.\n\n<Thelis nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Hobb. He is standing guard right outside this building.", progress = "<Hobb nods.>", completion = "&lt;Hobb grins.&gt;\n\nThe deadliest trap ever laid...", rewards = nil}
MultiLanguageQuestData['en'][11096] = {title = "Threat from Above", objective = "Slay any 20 Gordunni Ogres in the Barrier Hills and return to Yuula in Shattrath City.", description = "So you want to join the Skyguard?  Well, I know you can fly... but can you fight?\n\nThe Skyguard is sworn to protect Shattrath from the dangers that loom above us, both near and far.  The Gordunni ogres who dwell in the Barrier Hills to the north are an immediate threat to us.\n\nReaching the ogres has been problematic for Shattrath's ground units.  That's where we come in.  See what you can do to help contain them.", progress = "Have you completed your task, <name>?", completion = "Good job, ace.  I've a feeling you're going to fit in well with us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11097] = {title = "The Deadliest Trap Ever Laid", objective = "Assist Commander Hobb and the Scryers in defending the Sanctum of the Stars. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Scryer Medals.", description = "Take these Scryer medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Scryer soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", progress = "Did you crush them under your boot, commander?", completion = "&lt;Mor'ghor laughs.&gt;\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Sanctum of the Stars at least once per day. They will have no choice but to leave Shadowmoon!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11098] = {title = "To Skettis!", objective = "Take the Explosives Package to Sky Sergeant Doryn at Blackwind Landing outside Skettis.", description = "The Barrier Hills are only one of the fronts where we've been deployed.  A less immediate but far more dangerous threat looms from beyond the Skethyl Mountains, from within the arakkoa city of Skettis.\n\nA few months ago our scouts detected a huge increase in arakkoa activity there.  Several attacks against Shattrath followed.  We've stationed forces outside of their city since.\n\nTake these explosives to Sergeant Doryn at Blackwind Landing, just outside Skettis.  Tell him you're a new recruit.", progress = "You've something for me, lad?", completion = "Thanks for the supplies; we'll put them to good use!  A new recruit?  Well, let's see what you're made of.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11099] = {title = "Kill Them All!", objective = "Deliver news of your mission and the Dragonmaw Flare Gun to Anchorite Ceyla at the Altar of Sha'tar.", description = "Commander <name>, stand at attention! You are to take a battalion of Skybreakers and sack the Aldor outpost located northwest of our beloved Black Temple. With the Altar of Sha'tar destroyed, our lines of communication to our posts at Coilskar will once more be open.\n\nGo now! Use this flare gun to signal the Skybreakers for the attack!", progress = "Settle down, child.", completion = "It is good that you came to us. Perhaps we can use this attack to our advantage and turn the tables on the Dragonmaw.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11100] = {title = "Commander Arcus", objective = "Give the Dragonmaw Flare to Commander Arcus at the Altar of Sha'tar in Shadowmoon Valley.", description = "The Dragonmaw only dare attack us when our guard is down. They would face certain defeat if they were to attack us while we were prepared.\n\nI want you to let them come, <name>.\n\n<Ceyla nods.>\n\nYes... a trap. Take this flare that their overlord gave you and deliver it to Commander Arcus. He is standing guard right outside this building.", progress = "<Arcus nods.>", completion = "&lt;Arcus grins.&gt;\n\nThe deadliest trap ever laid...", rewards = nil}
MultiLanguageQuestData['en'][11101] = {title = "The Deadliest Trap Ever Laid", objective = "Assist Commander Arcus and the Aldor in defending the Altar of Sha'tar. Once all of the Dragonmaw forces have been defeated, return to Overlord Mor'ghor at Dragonmaw Base Camp with the Aldor Medals.", description = "Take these Aldor medals. Mor'ghor will need proof of \"victory\" once this is over. He will recognize them as coming from the corpses of fallen Aldor soldiers.\n\nNow all that remains is to use the signal flare to alert the Dragonmaw raiders. We will crush them when you are ready. Just give me the word.", progress = "Did you crush them under your boot, commander?", completion = "&lt;Mor'ghor laughs.&gt;\n\nHAH! I knew you wouldn't let me down, commander! I want you to lead a raid on the Altar of Sha'tar at least once per day. They will have no choice but to leave Shadowmoon!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11102] = {title = "Bombing Run", objective = "Sky Sergeant Vanderlip has tasked you with the bombing of 15 Fel Cannonball Stacks. Return to her at the Skyguard Outpost atop the Blade's Edge Mountains once you have done so.", description = "You can fly around as a crow... so what!  Ever annihilate something on the ground while you were flying?  Want to?\n\nForge Camp: Wrath and Forge Camp: Terror, to the north and south, are a major pain in my backside, as well as being a threat to peaceful Ogri'la.  With all of those fel cannons shooting down the Skyguard left and right, we can't get through there to take care of business.\n\nWant to prove yourself?  Take these bombs and knock out their ammo stacks.  Just don't let them shoot you down, too!", progress = "You take out their stacks of fel cannonballs yet?", completion = "Well, well, well, I guess you had it in you after all.  Good work.  Maybe Old Man Keller was wrong about you after all.\n\n&lt;Sky Sergeant Vanderlip smirks.&gt;", rewards = "The following spell will be cast on you:\n\nBombing Run: On Quest Complete\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11103] = {title = "Sage No More", objective = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", description = nil, progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty.", rewards = "You will be able to choose one of these rewards:\n\nBand of the Eternal ChampionBand of the Eternal DefenderBand of the Eternal Restorer"}
MultiLanguageQuestData['en'][11104] = {title = "Restorer No More", objective = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", description = nil, progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty.", rewards = "You will be able to choose one of these rewards:\n\nBand of the Eternal ChampionBand of the Eternal DefenderBand of the Eternal Sage"}
MultiLanguageQuestData['en'][11105] = {title = "Champion No More", objective = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", description = nil, progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty.", rewards = "You will be able to choose one of these rewards:\n\nBand of the Eternal SageBand of the Eternal DefenderBand of the Eternal Restorer"}
MultiLanguageQuestData['en'][11106] = {title = "Defender No More", objective = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", description = nil, progress = "The power within your ring is malleable, though reversing your choice is not easy.  Are you sure you want to replace its current form?", completion = "The sands of time flow forwards easily.  They can be made to flow backward, but with great difficulty.", rewards = "You will be able to choose one of these rewards:\n\nBand of the Eternal ChampionBand of the Eternal SageBand of the Eternal Restorer"}
MultiLanguageQuestData['en'][11107] = {title = "Bow to the Highlord", objective = "Speak to Overlord Mor'ghor at Dragonmaw Base Camp in Shadowmoon Valley.", description = "I am unworthy to even carry a message directed at you, sir. Please forgive me for this indulgence. Overlord Mor'ghor has requested your presence in his chambers at once!", progress = nil, completion = "You are the first highlord of the Dragonmaw, &lt;name&gt;. The master himself has chosen to come here to promote you.", rewards = nil}
MultiLanguageQuestData['en'][11108] = {title = "Lord Illidan Stormrage", objective = "Meet Illidan Stormrage. Seek out Barthamus in the Lower City of Shattrath should you survive.", description = "Come, highlord <name>. Illidan himself awaits us!", progress = nil, completion = "I was the first, you know. The abandoned child of a monster...\n\n&lt;Barthamus shakes his head.&gt;\n\nWe owe you everything, &lt;name&gt;. You have single-handedly shattered the Dragonmaw empire and gathered enough information to keep my brethren occupied for ten lifetimes.\n\nIt is not much but there is something that we can offer... My kin have each offered to join you on your mission in Outland. Simply ask and they will bond with you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11109] = {title = "Jorus the Cobalt Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Cobalt Netherwing Drake"}
MultiLanguageQuestData['en'][11110] = {title = "Malfas the Purple Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Purple Netherwing Drake"}
MultiLanguageQuestData['en'][11111] = {title = "Onyxien the Onyx Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Onyx Netherwing Drake"}
MultiLanguageQuestData['en'][11112] = {title = "Suraku the Azure Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Azure Netherwing Drake"}
MultiLanguageQuestData['en'][11113] = {title = "Voranaku the Violet Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Violet Netherwing Drake"}
MultiLanguageQuestData['en'][11114] = {title = "Zoya the Veridian Netherwing Drake", objective = "It is an honor to meet you, <name>. We have all been keeping a close eye on your adventures and are grateful for all that you have done for the Netherwing Dragonflight.\n\nIf you choose me as your compatriot, I will fly you to the ends of this world and back. Whatever it is that you ask of me, I will do my best to comply.\n\nBe warned that you may only select one of us for your journeys in Outland. Once the selection has been made, you cannot change your mind.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReins of the Veridian Netherwing Drake"}
MultiLanguageQuestData['en'][11115] = {title = "The Mark of Vashj (FLAG ONLY)", objective = nil, description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][11116] = {title = "Trial of the Naaru: (QUEST FLAG)", objective = "A'dal in Shattrath City wants you to slay Magtheridon.", description = "Four trials you must pass before you are deemed worthy of the Tempest key.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!\n\nDo this and you will be granted the Tempest key.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nPhoenix-fire Band"}
MultiLanguageQuestData['en'][11117] = {title = "Catch the Wild Wolpertinger!", objective = "Goldark Snipehunter has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated to see them.", description = "Here now. Ye hear that? There be sounds in them hills. Those're the wolpertingers! Wily beasts, they are, attracted by the smells o' Brewfest. I've a mind to catch me some, but I knocked me shin and can't outrun the buggers. Ye can help me, though!\n\nTake this net and cast it over the little blighters. Bring me a good five of 'em and I'll make it worth yer while! Oh, and one more thing - in order to even see these critters, ye need t' be blitzed! Load up on the booze!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nWolpertinger's Tankard"}
MultiLanguageQuestData['en'][11118] = {title = "Pink Elekks On Parade", objective = "Visit the beer gardens outside of Stormwind, Darnassus, and the Exodar, zap three elekks at each location, and return to Goldark Snipehunter. You must be drunk to see the pink elekks.", description = "Getting drunk is a time-honored tradition at Brewfest -- it's damn near required! Thing is, I'm getting reports across Azeroth saying the celebration's plagued by hallucinations!  We can't have that!\n\nThese elekks can't be harmed by normal weapons -- they pass right through 'em -- so take this fabulous piece of gnomish machinery, visit the other beer gardens, and zap 'em to oblivion. Remember, you have to be drunk to see 'em!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11119] = {title = "Assault on Bash'ir Landing!", objective = "Sky Commander Keller has asked you to speak with the Aether-tech Apprentice at the Skyguard Outpost in the Blade's Edge Mountains.", description = "Heya, <boyo/girly>!  Up fer some fun are ye?\n\nEvery couple o' hours, me aether-techs launch an assault on Bash'ir Landing, far ta the northeast in the Blade's Edge Mountains.  They say that they're there 'studying' the Bash'ir crystalforge, but it's an assault; there be no two ways about it.  We use the crystalforge to resupply, and there's always extra to be sold.\n\nGo on down ta the landin' pad and speak with the aether-tech apprentice.  He'll tell ye when the next mission is ta launch.", progress = nil, completion = "Despite how Keller cares to characterize it, I prefer to think of our missions as research-oriented.\n\nBut yes, we do resupply the Skyguard while we're there.  That is if we can stay long enough to do so.\n\nYou look like you'd be willing to keep the ethereals off of our backs.  If you can manage to for long enough, we'll sell you surplus items that we create at the crystalforge, so bring your apexis shards and crystals!\n\nWe leave in 0 |4minute:minutes;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11120] = {title = "Pink Elekks On Parade", objective = "Visit the beer gardens outside of Silvermoon, Thunder Bluff, and the Undercity, zap three elekks at each location, and return to Glodrak Huntsniper. You must be drunk to see the pink elekks.", description = "Look. We're running a business here. People being drunk? It's good business. But I'll tell ya one thing that puts a cramp in the profits - hallucinations. Wouldn't ya know it, the boys are reporting that the sot- er, the loyal customers are seeing pink elekks everywhere.\n\nI don't need my customers unsettled. Look, take this ray and travel to the other beer gardens to take care of 'em for me, would ya? And be sure to get drunk!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11121] = {title = "DAILY TEST QUEST (RAID)", objective = "Speak with <QUESTGIVER> in the <AREA>.<NYI>Seek <QUESTGIVER> in <LOCATION>. S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "<NYI>Seek <QUESTGIVER> in <LOCATION>.  S/he wishes for you to aid them in a difficult task.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11122] = {title = "There and Back Again", objective = "Get a keg from Flynn Firebrew in Kharanos and return it to Pol Amberstill. Do this 3 times before your ram goes away.", description = "So you want to help out at Brewfest?  I've got the perfect task for ya.  I'll put you on one of my racing rams and you head down to Kharanos.  I've got some kegs I need to pick up.  \n\nFlynn Firebrew is waiting on a hill near a stack of kegs.  He'll toss you a keg when you get near, then you run the keg back here and toss the keg to Pol Amberstill.  You can only carry one at a time.  \n\nReady?", progress = "I need those kegs!  So, what are yeh waitin' for!?!", completion = "Thanks a lot for your help!  As long as Brewfest is going and the Dark Iron dwarves are attacking, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nBut enough about that, I need to pay you for the job you just did.  Here are your tokens, have fun at Brewfest!", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11123] = {title = "Inspecting the Ruins", objective = "Speak to Inspector Tarem at the Shady Rest Inn.", description = "Poor James never recovered from the destruction of the Shady Rest and the murder of his family. The boys and I are doing what we can to find the bastards who did this.\n\nI've sent our best investigator, Inspector Tarem, out to the ruins, but this is too big a job for any one man. If you'd lend Tarem a hand, we'd appreciate it. Light knows, we'd all like to be out there helping.\n\nThe main road will lead you to the inn, but take care. Your journey will take you beyond the protection of my soldiers.", progress = nil, completion = "It's good to see that Captain Vimes is finally assigning others to this investigation.\n\nI've used a reflective powder to dust the area. It will reveal suspicious objects and markings, helping you to focus your efforts. Look over anything the dust illuminates.", rewards = "The following spell will be cast on you:\n\nReflective Dust\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11124] = {title = "Inspecting the Ruins", objective = "Speak to Inspector Tarem at the Shady Rest Inn.", description = "If you follow the road south from the village, and then west toward the Barrens, you'll come across the ruins of the Shady Rest Inn.\n\nTheramore has sent an investigator to discover how the inn met its fate. Normally, I'd advise you to steer clear, but we have orders from Orgrimmar to 'assist' in the investigation.\n\nAccept any help the Theramore investigator offers, even feed him a tidbit or two of information if you'd like, but save your real findings for me.", progress = nil, completion = "&lt;The inspector regards you with what can only be distrust.&gt;\n\nI've been told that you're to... aid in this investigation. Very well, then.\n\nI've been using this powder to search the ruins for clues that might help identify the attackers. It will illuminate anything that might have been involved in the attack. Don't hesitate to examine anything that looks suspicious.", rewards = "The following spell will be cast on you:\n\nReflective Dust\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11126] = {title = "Traitors Among Us", objective = "Confront 5 Deserter Agitators and return to Calia Hastings near the docks in Theramore.", description = "It's good to meet you, <class>. I've come to Theramore to help eliminate the problem of the deserters. Not only have some of the men abandoned their posts, but some have filtered back into the town.\n\nThese deserter agents are spreading lies and propaganda, hoping to convince others to join their ranks.\n\nThey're at virtually every guard post throughout the town and the docks. Find them, expose them, and discredit them. At this point, anything more risks inspiring more sympathy for them.", progress = "Have you driven the deserter agents from Theramore?", completion = "Well done, &lt;name&gt;. I think we managed to catch them off guard. Their agents probably thought themselves safe within the city walls.\n\nGiven time, the agitators will return and spread their lies again. We'll use the time you've bought to shut out the deserters further.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11128] = {title = "Propaganda War", objective = "Bring the Deserter Propaganda to Calia Hastings near the docks in Theramore.", description = "The deserter agents were doing far more than just chatting up the guards. We've found a number of leaflets the deserters somehow managed to smuggle in on a ship in the docks.\n\nThe ship used to transport the leaflets is still in Theramore, at the farthest dock. If you can sneak aboard and capture the rest of their propaganda documents, their agents will lose their most powerful tool. Be careful! The ship is manned by seasoned privateers and the cargo is probably being kept in the captain's quarters.", progress = "Did you manage to find and capture the remaining propaganda leaflets?", completion = "&lt;The SI:7 agent nods in approval.&gt;\n\nExcellent. All that remains is to discredit the deserters so that they'll never gain a foothold in Theramore again, and I have just the plan to do it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11129] = {title = "Kyle's Gone Missing!", objective = "Ahab Wheathoof at Bloodhoof Village in Mulgore wants you to feed his prized puppy, Kyle the Frenzied.\n\nFeed Kyle Tender Strider Meat and return to Ahab Wheathoof.", description = "Help, <name>! My prized puppy, Kyle, has run away! I just know he's running around Bloodhoof Village, lost and hungry.\n\nWill you find him and feed him? Once he eats he will settle down and come home.\n\nTo feed him you will need to find food. His favorite meal is tender strider meat. Just venture east and you should find plenty of striders. Hunt one down and take its succulent meat to Kyle. When you see Kyle in town, put the meat down and he is sure to come to you.", progress = "Did you find Kyle?", completion = "Fantastic work, &lt;name&gt;! Kyle came home as soon as he ate and went straight to bed. Thank you for your help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11130] = {title = "Oooh, Shinies!", objective = "Griftah wants you to take Griftah's Note to Budd in the Ghostlands, just outside of Zul'Aman.", description = "Come closer, <man/sweetheart>! Let ol' Griftah look at yer shiny things....\n\nHmm. Yeh, yeh, not bad, but ya can do better. Much, much better.\n\n<Griftah leans in and whispers.>\n\nThere be priceless shinies everywhere, <name>, ya just gotta know where to look! It be yer lucky day; I know a fella who can help ya find more shinies than ya can ever carry.\n\nVisit my ol' friend, Budd, near Zul'Aman and show him this here. Ya be tellin' him ol' Griftah sent ya and he'll let ya in on his new project.", progress = "<Budd eyes the note suspiciously.>\n\nWhat have you there, <class>?", completion = "&lt;Budd reads the note.&gt;\n\nAhh! A friend of Griftah? Welcome!\n\nYou have impeccable timing, friend. As fate would have it, I recently lost my latest partners. Tragic, truly, but great rewards often have a high price. Best not to dwell on the negative!\n\nYou've doubtlessly heard of my countless exploits and discoveries. Well, all of that was nothing compared to this! Truth is, we're close to making history here at Zul'Aman and, by fate's decree, you're in on the ground floor!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11131] = {title = "Stop the Fires!", objective = "The Costumed Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Costumed Orphan Matron.", description = "You must help us!  The Headless Horseman is attacking the village.  Fires are everywhere!  The children aren't safe!\n\nPlease, <name>, join the fire brigade.  Grab a bucket and toss it on the fires, or pass it to a friend who's closer to the blaze.  Put out all the fires and we may yet be saved!", progress = "<name>, you promised to save the children!", completion = "Oh, thank you!  May the Light bless your good works, kind sir.  The shadow of the Dark Horseman yet looms, but at least, for now, the village is safe from his flames.", rewards = "You will receive:\n\nHallow's End Pumpkin TreatWeighted Jack-o'-Lantern"}
MultiLanguageQuestData['en'][11132] = {title = "Promises, Promises...", objective = "Budd Nedreck in Hatchet Hills wants you to retrieve his map from High Priest Nalorakk's terrace in Zul'Aman.", description = "My inscrutable theories confirm rumors of vast treasure in Zul'Aman. There'll be mounts and mansions for everyone! First things first, though. You must earn your share, after all....\n\nOur initial efforts here haven't gone as well as I hoped. In fact, my map, and the recruits I lent it to, have gone missing. They were after a troll-beast named Nalorakk.\n\nForget the crew, I need that map! Succeed, and you'll go down in history as the one who helped Budd Nedreck unlock the secrets of Zul'Aman!", progress = "Ahh yes, <name>, isn't it?\n\nHave you recovered my map yet?", completion = "&lt;Budd looks a bit shocked.&gt;\n\nOh? You've found it?\n\nAhem, I mean, of course you have! Well done, &lt;class&gt;.\n\nLet me see if I can find you a little something nice... ahh yes, this should do.", rewards = "You will receive:\n\nTattered Hexcloth Sack"}
MultiLanguageQuestData['en'][11133] = {title = "Discrediting the Deserters", objective = "Calia Hastings wants you to distribute the Altered Leaflets to 6 Theramore Guards, then report back to her near the docks in Theramore.", description = "I've altered the leaflets you captured from the deserters' mercenary friends at the docks. Now, anyone who reads them will get an entirely different view of the deserters and their aims.\n\nIf we distribute these to enough of the guards, the deserters will be too embarrassed to ever reestablish their presence within our walls.\n\n<Calia hands you a stack of the altered leaflets.>\n\nWhy don't you get started while I plan our next move?", progress = "I thought I heard laughter coming from the barracks. Did you distribute those leaflets I gave you?", completion = "&lt;Calia chuckles as you describe the guards' reactions to the propaganda.&gt;\n\nJust as I'd hoped! I think it's safe to say any deserter agents who try to infiltrate Theramore will be laughed right out of town!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11134] = {title = "The End of the Deserters", objective = "Capture Gavis Greyshield, then report to Calia Hastings near the docks in Theramore.", description = "Now that we've eliminated the deserters from Theramore, it's time to complete this operation. My local contacts have reported that the deserters base their operations in a ship moored on a small island to the southeast of the docks.\n\nArresting their leader, Gavis Greyshield, should cause the others to lose their will to fight. Find him within the ship and convince him to surrender. I wouldn't be surprised if he puts up a bit of a fight for show, but then surrenders when he understands he can't win.", progress = "Have you completed your assault on the deserter base?", completion = "Gavis' request isn't as outlandish as it might sound. With the proper handling, Lady Jaina can return the deserters to the fold, but that is her decision, of course.\n\nIt's been a pleasure working with you, &lt;name&gt;. Without your help, I doubt the operation would've gone so smoothly. When I make my report in Stormwind, it will name you as the &lt;class&gt; who ended the deserter threat.", rewards = "You will be able to choose one of these rewards:\n\nJourneyman's CowlBoots of the SkirmisherMercenary's Crossbow\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11135] = {title = "The Headless Horseman", objective = "Find the Headless Horseman's pumpkin Shrine.", description = "The Headless Horseman is driven away, but he will return as long as Hallow's End looms.  <name>, end our misery, and the insane lament of the Horseman.  Face him when he is joined with his head, and destroy it!\n\nHe rests in the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glade.  Find his pumpkin shrine and say this:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nGo, <name>.  And may the Light go with you.", progress = nil, completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11136] = {title = "A Disturbing Development", objective = "Report to Captain Wymor at Sentry Point.", description = "Reports from our scout patrols have recently taken a disturbing turn. They tell of men wearing red Defias bandanas walking the Dreadmurk Shore north of Theramore's walls.\n\nWreckage in the area suggests they may be survivors of a shipwreck, but our information is limited. Captain Wymor at Sentry Point, a guard tower to the north of the city, is looking for help in following up on the reports.", progress = nil, completion = "&lt;The captain makes no effort to hide that he's assessing your abilities.&gt;\n\nSo you've heard about the recent shipwreck off the coast? Good, I could use some help confirming my suspicions about the survivors. Welcome aboard, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11137] = {title = "Defias in Dustwallow?", objective = "Obtain the Defias Orders from Garn Mathers and bring them to Captain Wymor at Sentry Point.", description = "My scouts have reported a shipwreck just off the beach to the northeast. Shipwrecks aren't all that unusual out here, but the reports also indicated the survivors were all wearing red bandanas!\n\nThe Defias are craftsmen and guildsmen, not sailors. What are they doing at the site of a shipwreck on a continent they've no interest in?\n\nTheir leader is rumored to reside on a large island just off the coast to the northeast of the tower. Kill him and retrieve any documents you find in his possession.", progress = "Were you able to track down their leader?", completion = "&lt;Captain Wymor accepts the orders from you and reads over them.&gt;\n\nWhat in the world could 'precious cargo' refer to? The Defias have done some small time smuggling back in lands of Stormwind, but this seems out of their league. The language of these orders suggests a wealthy or noble patron.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11138] = {title = "Renn McGill", objective = "Bring the Defias Orders to Renn McGill in the waters off the Dreadmurk Shore.", description = "From the wording of the orders you recovered, it looks like the first priority of the Defias will be to locate and secure whatever cargo they possessed.\n\nSI:7 has had a salvage diver named Renn McGill working out of Theramore for some time. When he heard about the shipwreck, Renn went north to dive near the islands the Defias now occupy.\n\nIf we're to beat the Defias to this cargo, we'll need his help. Look for him in the waters northeast of a small island just north of the island you visited earlier.", progress = "Well met, <class>. What brings you out here?", completion = "&lt;Renn looks over the orders.&gt;\n\nSo there was valuable cargo on board! We have to locate it before the Defias recover it. These guys are no divers, but we're going to need some of their gear if you're to help me find the cargo.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11139] = {title = "Secondhand Diving Gear", objective = "Bring the Tool Kit and Damaged Diving Gear to Renn McGill in the Dustwallow Marsh.", description = "There's plenty of wreckage strewn across the bottom of the water from here to Alcaz, and the Defias have already got divers out there looking around. With the help of some of their gear, we can get you suited up and ready to join the hunt, but you'll have to do some creative \"borrowing\" first.\n\nSearch this island for a crate of diving gear and something to repair it with. When you've got them, bring them to me and I'll have your gear ready in no time!", progress = "Let's see what you managed to \"borrow\" from the Defias.", completion = "Wow, this is in worse shape than I'd thought, and these tools...\n\nWell, I said I'd get this back into working condition for you, so I'd better get to work.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11140] = {title = "Recover the Cargo!", objective = "Bring 6 Salvaged Strongboxes to Renn McGill in Dustwallow Marsh.", description = "Well, I was able to make enough repairs to this gear to let you dive for awhile, anyway. I wouldn't count on it holding out for a long time, though.\n\nThe wreckage of the ship is strewn along the bottom from the east coast of this island out toward Alcaz Island. While that helm holds out, locate pieces of the wreckage on the bottom between this island and Alcaz. Use this salvage kit to search the wreckage for pieces of the cargo. Be careful not to venture too close to Alcaz Island. Those hydra are fierce.", progress = "Did your search of the wreckage reveal anything about the Defias cargo?", completion = "&lt;Renn rifles through the contents of the strongboxes you recovered.&gt;\n\nGood work. Now, let's see if our 'precious cargo' is in here....", rewards = "You will be able to choose one of these rewards:\n\nFleshripperCrimson BarbutMariner's Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11141] = {title = "Jaina Must Know", objective = "Speak with Lady Jaina Proudmoore in Theramore.", description = "You must bring news of our findings to Lady Jaina without delay! If the Defias were transporting a prisoner, there's no telling who it might be or if the person is still alive!\n\nOne thing is for certain, <name>. The Defias wouldn't go to all this trouble for some petty grudge. Their prisoner must have been someone of importance. Lady Jaina would know better than anyone else what these findings mean. You'll find her at the top of the mage tower at Theramore's center.", progress = nil, completion = "You and Renn have done excellent work in bringing this information to light and reporting it immediately. There's no denying the Defias have hatched some sinister plan to strike at Stormwind and its allies. There's a level of complexity here that's beyond anything they've ever attempted, which means they must have a wealthy sympathizer somewhere.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11142] = {title = "Survey Alcaz Island", objective = "Speak to Cassa Crimsonwing and use one of her gryphons to survey Alcaz Island. When your survey is complete, speak with Lady Jaina Proudmoore in Theramore.", description = "It looks like Renn's hunch about Alcaz Island was right. We need to survey that island, but it would take a whole brigade of troops to fight our way in there.\n\nTheramore's defenses can't weather such a hit, so I've arranged with Cassa Crimsonwing, the apprentice to Theramore's gryphon master, to allow you to use one of her beasts to survey Alcaz from the air.\n\nAlcaz Island holds the key to the Defias' plans for their prisoner and perhaps the prisoner's identity itself.", progress = "Have you completed your aerial survey of Alcaz Island?", completion = "&lt;Lady Jaina listens intently as you report the results of your aerial survey.&gt;\n\nA rune circle, dragonkin? The Defias certainly have hedge mages among their ranks, but no one powerful enough to make use of such a thing!\n\nAnd why would the black dragonkin be interested in an island full of naga? There are many unanswered questions, but one thing is for certain: the Defias have a powerful ally in upper echelons of the Alliance.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11143] = {title = "A Grim Connection", objective = "Report to Captain Darill at North Point.", description = "I've spoken with Inspector Tarem regarding the evidence you gathered from the ruins of the Shady Rest Inn. He seems certain that the hoofprints and the shield you found there point to the Grimtotem clan of tauren.\n\nWith reports of Grimtotem activity on the rise in the marsh, this has to be more than a mere coincidence. I'm sending you to speak with Captain Darill, who is something of an expert on the Grimtotems. Follow the road north out of town to North Point tower. It's the second outpost on the road.", progress = nil, completion = "Captain Vimes thinks the Grimtotems are behind the destruction of the Shady Rest Inn? They wouldn't have been first on my list of suspects, but if Captain Vimes sent you here to follow up on a lead, he must have his reasons. Regardless, the Grimtotems have been a thorn in our side for some time and we're always glad to have the extra help.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11144] = {title = "Confirming the Suspicion", objective = "Bring the Grimtotem Battle Plan to Captain Darill at North Point Tower.", description = "The Grimtotems may be the most warlike of all the tauren clans, but they're by no means unorganized. If they're the ones who put the torch to the Shady Rest Inn, they'll have had orders from one of their clan elders.\n\nThere's a large Grimtotem settlement called Blackhoof Village to the northwest. They've been using it as a base to attack the tower, but I'll bet that you'll find the orders you're looking for there. Check the village's elders for traces of the orders you seek.", progress = "Were you able to find any trace of the orders?", completion = "&lt;Captain Darill glances at the battle plan.&gt;\n\nI'd say it doesn't get any clearer than this. They've taken it upon themselves to fight back against human settlements in the area and I have little doubt Theramore is next on their list.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11145] = {title = "Prisoners of the Grimtotems", objective = "Sergeant Lukas at North Point Tower wants you to free 5 Theramore Prisoners.", description = "We're doing all we can to keep the Grimtotem raiders at bay, but they keep launching assaults on the tower. Even worse, they've managed to discover and capture the patrols the captain sends out to gather information and safeguard the road.\n\nI suspect the captives are being held in Blackhoof Village, to the northwest. Knowing the Grimtotems, the defenders of the village probably carry the keys to the prisoners' cages with them. I don't care what you have to do, <class>, just bring back my men alive.", progress = "Did you manage to free the captives at Blackhoof Village?", completion = "The freed captives have already begun returning from Blackhoof Village. The information the captain is receiving from the prisoners will give us an advantage in our next battle against the Grimtotems.\n\nYou have my thanks and that of the men.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11146] = {title = "Raptor Captor", objective = "Sergeant Lukas at North Point Tower wants you to capture 6 raptors. You can capture either Bloodfen Raptors or Bloodfen Screechers.", description = "The patch of swamp to the northeast is home to a particularly nasty breed of raptors. We've lost more than one unwary soldier to them, but I think we can turn them against our Grimtotem neighbors.\n\nTake this rope and use it to capture bloodfen raptors or bloodfen screechers that you've subdued. I wouldn't try to capture one of the beasts until you've weakened them quite a bit in combat. It's going to be quite a struggle.", progress = "Did you capture those raptors?", completion = "You look a little scratched up, but nothing major. You're certainly in a lot better shape than the Grimtotems will be when our new raptor friends get done with them.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11147] = {title = "Unleash the Raptors", objective = "Sergeant Lukas at North Point Tower wants you to place the Raptor Bait near the windmill in Blackhoof Village.", description = "Now that we've got our raptors, our next move is to \"encourage\" them to attack the Grimtotems at Blackhoof Village to the northwest.\n\nI've got a leftover haunch of... well, it doesn't really matter what it is. It'll be your bait. Set it down on the ground in Blackhoof Village near the windmill in the center of the settlement. The raptors should take care of the rest, if their training took.", progress = nil, completion = "&lt;The sergeant doesn't bother to hide his grin.&gt;\n\nGood. That ought to forestall a raid or two.", rewards = "You will be able to choose one of these rewards:\n\nBook of the AdeptCrested ShoulderpadsPendant of Ferocity\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11148] = {title = "Arms of the Grimtotems", objective = "Captain Darill at North Point Tower wants you to bring him 7 Blackhoof Armaments.", description = "If the equipment you found at the ruins of the inn belonged to a Grimtotem attack party, there's likely to be more just like it within their camp to the northwest.\n\nWe haven't been able to gather much information about Blackhoof Village, but judging from the size of the raiding parties, there's a substantial force based there.\n\nDo whatever you have to to capture some of their equipment so that we can compare it with your findings from the inn.", progress = "Did you get those weapons from Blackhoof Village?", completion = "&lt;Captain Darill inspects the armaments you've brought from Blackhoof Village.&gt;\n\nThere's no doubt about it. These match the description exactly, but there's just one problem -- these have never been used in battle. Blackhoof Village must not be the only Grimtotem post in the marsh.", rewards = "You will be able to choose one of these rewards:\n\nGlowing Tourmaline RingBone DirkBiting Axe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11149] = {title = "Tabetha's Assistance", objective = "Speak with Tabetha at her farm.", description = "I can't spare any men to help search for a second Grimtotem outpost, but I think I know of someone who might be able to help you.\n\nDeep in the Quagmire, to the south, there is a small farmstead owned by Tabetha. She may seem little more than an old hermit, but the truth is that she's a mage and scryer of some renown. Follow the road south to her farm and seek her help in finding the culprits responsible for the massacre at the Shady Rest Inn.", progress = nil, completion = "So you want me to scry for Grimtotems, eh? And what will you say when I tell you there's no need?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11150] = {title = "Raze Direhorn Post!", objective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", progress = "Have you put that torch to good use?", completion = "I hope the Grimtotems got the message. Any attempt to return will be met with far worse than a mere torch. My apprentices and I will see to that.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11151] = {title = "Justice for the Hyals", objective = "Speak to Captain Garran Vimes at Foothold Citadel in Theramore.", description = "Although these Grimtotems were simply a nuisance to me, Captain Vimes will want to know of your deeds. Bring him the news that you have tracked down and dealt with those responsible for the burning of the Shady Rest Inn.\n\nIt's too late to save Jim Hyal's family, but perhaps the Grimtotems will think twice before attacking anyone connected to Theramore.", progress = nil, completion = "&lt;The captain listens to your report intently.&gt;\n\nWe have avenged James and his family, but not even that can restore what was destroyed.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11152] = {title = "Peace at Last", objective = "Captain Garran Vimes at Foothold Citadel wants you to lay the Wreath at the Hyal Family Monument.", description = "I wish we had a way of letting James Hyal's wife and son know that we have brought their murderers to justice.\n\n<Captain Vimes produces a small wreath decorated with flowers.>\n\nThere are some who say that their spirits will know, even if we cannot reach them. It's not much, but I'd like you to lay this wreath at the Hyal family monument. It's one of the larger stones in the graveyard just north of Theramore's gates.", progress = "Did you lay the wreath?", completion = "&lt;Captain Vimes smiles slightly as you relate the events you witnessed at the Hyal family grave.&gt;\n\nIt's good to know that they understand. You didn't tell them about James, did you?\n\nI'll deliver his wife's message to him, but I doubt he'll understand.", rewards = "You will be able to choose one of these rewards:\n\nLeggings of the Long RoadSkirmisher's CoverSteel-banded Hauberk\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11156] = {title = "Direhorn Raiders", objective = "Kill 12 Direhorn Grimtotems and return to Apprentice Morlann at Tabetha's Farm.", description = "The Grimtotems up at Direhorn Post, just to the north, are getting bolder by the day. At night, you can often hear them chanting about their deeds in battle against people who've tried to settle here.\n\nThey're determined to drive us from Tabetha's farm even though she's trained generations of apprentices here. We've defended the farm as best we can, but Apprentice Garion was wounded in the last attack.\n\nGo to Direhorn Post and kill any Grimtotem you can find! The attacks must stop.", progress = nil, completion = "&lt;Apprentice Morlann nods.&gt;\n\nGood. Can't say I'll miss the company, if you can call it that. You'd think at least in the middle of the swamp you'd get some privacy, you know?", rewards = "You will be able to choose one of these rewards:\n\nGrimtotem Earthbinder's TunicMorlann's SealDestroyer's Cloak\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11158] = {title = "Bloodfen Feathers", objective = "Bring 5 Bloodfen Feathers to Brogg at Mudsprocket.", description = "Are you startled by Brogg's presence here, little <race>? Don't worry. Goblins at Mudsprocket are Brogg's friends and you can be, too.\n\nBrogg left Brackenwall Village when new overlord not take revenge against black dragonkin for destroying old home and killing many of Brogg's old friends. Brogg come here to lay friends spirits to rest and avenge them, but Brogg need help preparing. For ritual, Brogg need feathers with strong magic, like ones worn by raptors at Bloodfen Burrow to the west of town.", progress = "<Brogg looks at you hopefully.>\n\nYou bring Brogg feathers?", completion = "&lt;Brogg accepts the feathers.&gt;\n\nBrogg pleased with these feathers. Very strong magic. Brogg not know what raptors do to give feathers power, but raptor feathers always best for ritual.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11159] = {title = "Spirits of Stonemaul Hold", objective = "Brogg, at Mudsprocket, wants you to put 10 Stonemaul Spirits to rest.", description = "Brogg has completed the totem that will put the spirits of his friends to rest. When the dragonkin came, they killed all Stonemaul who did not flee. Brogg fled with Overlord Mok'Morokk, hoping to lead a counterattack with other Stonemaul survivors.\n\nThe counterattack never came and the spirits of the Stonemaul dead still haunt Brogg and the others. Take this totem north to Stonemaul Ruins and use it near ogre skeletons to draw the spirit to you. Defeat the spirit to give it rest with its bones.", progress = "Brogg must know, have you brought peace to the violent spirits of the Stonemaul?", completion = "Brogg thanks you for your help, although he knows Overlord Mok'Morokk never will. At least surviving Stonemaul can finally focus on problems with the living and leave dead where they belong. Only one thing remains for Brogg to do.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11160] = {title = "Banner of the Stonemaul", objective = "Retrieve the Stonemaul Banner and bring it to Brogg at Mudsprocket.", description = "When the dragons came and took over Brogg's old home, Stonemaul ogres fled and left everything behind, including clan's banner.\n\nBrogg knows banner was kept deep in Stonemaul ogre mound, but these days it's called Den of Flame. Brogg must have clan banner to get his revenge on dragons who killed his friends.\n\nBrogg's clan's old mound, Den of Flame, is northwest of Mudsprocket and crawling with dragonkin. Banner will be deep inside the cave. Be careful, <name>.", progress = "You bring Stonemaul banner?", completion = "You have Brogg's thanks, &lt;name&gt;. Brogg has big plans for clan banner.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11161] = {title = "The Essence of Enmity", objective = "Bring 10 Black Dragonkin Essences to Brogg at Mudsprocket.", description = "To make the totem Brogg will need for his ritual, he must use the essences of the creatures who killed his friends. The hate and anger of Brogg's enemies will fuel the magic of his vengeance.\n\nTrack down Firemane ash tails, scouts, or scalebanes and use Brogg's totem on their corpses. Only when the dragonkin die will they give up their essences.\n\nThe creatures you seek swarm over the Den of Flame to the northwest and the Stonemaul Ruins to the north.", progress = "Do you have the essences? Brogg must have them to avenge his friends!", completion = "You have Brogg's thanks, &lt;name&gt;. Once Brogg adds their magic to the totem, it will be able to redeem the spirits of Brogg's fallen friends.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11162] = {title = "Challenge to the Black Flight", objective = "Plant the Stonemaul Banner near the entrance to Onyxia's Lair, wait for Onyxia's response, then return to Brogg at Mudsprocket.", description = "Brogg relishes the thought of taking his revenge on the black dragonkin of the marsh. <name>, you have been very helpful in preparing for this moment. Will you help?\n\nTake Brogg's clan banner and travel east until you see a cave like a dragon's mouth. At the entrance to that cave, plant Stonemaul banner and issue Brogg's challenge to Onyxia.\n\nBrogg and the Stonemaul will have their lands back!", progress = "Brogg will have his revenge!", completion = "&lt;Brogg listens as you recount your experience at the entrance to Onyxia's lair.&gt;\n\nBrogg suspected Onyxia would be too much of a coward to confront you. Just like black dragonflight to attack when victory is guaranteed.\n\nBrogg is grateful for your help, &lt;name&gt;, and he will never forget what you have done for him. Brogg will never give up his quest to bring Stonemaul back where they belong.", rewards = "You will be able to choose one of these rewards:\n\nOversized Stonemaul HoodBrogg's Battle HarnessRefitted Bruiser Gauntlets\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11163] = {title = "Undercover Sister", objective = "Report to Donna Brascoe to collect a reward for your heroism in Zul'Aman. Donna is currently stationed in the Ghostlands, just outside Zul'aman.", description = "<Donna looks around and then whispers to you.>\n\n<name>, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", progress = nil, completion = "&lt;Donna looks around and then whispers to you.&gt;\n\n&lt;name&gt;, what I'm about to tell you must remain confidential, understood?\n\nI've been sent by the Shattrath Peacekeepers to infiltrate Budd's gang here. Truth be told, since you first arrived you've been a key person of interest in my investigation. \n\nBut your deeds have since cleared you of any suspicion. In fact, for your slaying of the crazed warlord, Zul'Jin, I'm compelled to reward you for your efforts.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11164] = {title = "Tuskin' Raiders", objective = "Prigmon needs you to collect 10 Forest Troll Tusks from the trolls in Zul'Aman. Bring them to him at Budd's camp in the Ghostlands.", description = "'Ey mon! You be new around 'ere, eh? Lemme ask a favor of ya.\n\nBudd's been refinin' his forest troll disguise. Says that he be close now - just be needin' one last touch. Tusks.\n\nMy skinnin' talents be wasted 'ere. Somethin' about yankin' troll tusks be makin me queasy. \n\nBring me back 10 troll tusks, eh mon?", progress = "Hurry, mon!\n\nBudd be sendin' me into Zul'Aman alone to test his mask if I don't be givin' him those tusks soon!", completion = "Ahh yeah, these be just what I be needin'!\n\nHere be the payment I promised ya, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11165] = {title = "A Troll Among Trolls", objective = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'Aman.", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'Aman. He still be alive too - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!", progress = nil, completion = "I be free!\n\nDey took most everyting when dey nabbed me, but here - take the last of my coin fer your troubles.\n\nAnd the least I can be doin' is stickin' around to offer my services....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11166] = {title = "X Marks... Your Doom!", objective = "Enter Zul'Aman and visit Halazzi's Chamber, Jan'alai's Platform, and Akil'zon's Platform. Report the details of those areas to Budd, at his camp in the Ghostlands.", description = "How did those fools fail? I told them to be careful - even gave them disguises to help them blend in. Ahh, well. The bright side of their failure is that this opportunity falls to you.\n\nSucceed, and you'll be well on your way to joining my crew and sharing in the immeasurable fame that will soon be mine. Not that I need any more, mind you.\n\nThere are yet a few portions of my map that require further exploration before our excavation can be initiated....", progress = "I trust that my hand-crafted disguises have given you adequate protection in Zul'aman.\n\nHave you scouted those areas for me? Or shall I begin looking for your replacements?", completion = "&lt;Budd struggles to maintain his composure.&gt;\n\nErr - So, &lt;name&gt; - it's, uhhh,  about time you returned. Yes - in fact you're holding up the entire operation.\n\nNow then, let's get to filling in this map....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11169] = {title = "The Grimtotem Weapon", objective = "Apprentice Garion at Tabetha's Farm wants you to test the Captured Totem on 10 Mottled Drywallow Crocolisks or Drywallow Daggermaws.", description = "During the last Grimtotem attack, I was wounded, but not before I managed to capture a curious totem our enemies were using against us.\n\nIt seemed to be emitting raw bolts of energy during the battle, but in all my experiments, I haven't managed to figure out how it works. I'll loan the totem to you if you agree to help me test it.\n\nThe watery areas surrounding the farm are home to pesky mottled drywallow crocolisks and drywallow daggermaws. Try fighting the crocolisks near the totem.", progress = "Have you had any luck testing the totem?", completion = "&lt;The apprentice listens as you describe your experiment.&gt;\n\nA haze and some lightning? That's it? There's got to be more to the totem than just that! The Grimtotems aren't likely to bring something like this to the battlefield unless it has some kind of utility.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11171] = {title = "Hex Lord? Hah!", objective = "Budd Nedreck in Hatchet Hills wants you to kill Hex Lord Malacrass in Zul'Aman.", description = "Excellent! Everything's nearly ready for my grand entrance into Zul'Aman.\n\nYou've done a fine job, <name>. I've spoken with my crew and they're warming up to you nicely. I'd say you're very close to becoming a permanent member of the team. Only one thing remains for you to do - dispatch that 'Hex Lord' fellow.\n\nNothing to it, really. You stand up to this wretch and he'll likely just turn and run. Weaker, older trolls just add intimidating titles to their name to make up for their deficiencies, you see?", progress = "I hope you appreciate the magnitude of the opportunity I've given you, <name>.\n\nHave you taken care of old Malacrass yet?", completion = "Finally! Now that the light work is done, I can at last make yet another mark on history. But first, there's one small matter to attend to - You....\n\nI'm afraid, &lt;name&gt;, that the time has come for me to let you go. I feel that your potential has been reached here, if not far exceeded.\n\nDon't feel bad, though. After all, it takes an exceptional type of individual to participate in such extraordinary events and not lose their wits. And look here, I have a little something for you to remember me by.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11172] = {title = "The Zeppelin Crash", objective = "Speak with Moxie Steelgrille at Beezil's Wreck.", description = "Not long ago, a goblin zeppelin crashed to the east. A representative of the Steamwheedle Cartel passed through here a few days ago.\n\nShe was looking for information about the zeppelin's cargo and it's pilot, Beezil, but none of us really got a good look at the crash. I doubt she'll be able to clean up after the wreck by herself, much less recover whatever cargo the vessel might have carried.\n\nIf you have time, you may want to check up on her out at Beezil's Wreck, due east of here, near the mountains.", progress = nil, completion = "So those hermit mages sent you? How can I be sure that I can trust you?\n\nI suppose I can use the help. There's not much here a mage would be interested in, anyway.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11173] = {title = "The Reagent Thief", objective = "Bring 6 vials of Marsh Venom to Apprentice Garion at Tabetha's Farm.", description = "If there's one thing you can count on Apprentice Morlann to do, it's whine about reagents.\n\nNormally, I just ignore him, and it never works. This time, I'm going to try something different.\n\nMaybe if I replace the missing reagents before he notices, he'll leave me alone. The most common reagent we both use is marsh venom, which comes from the darkfang creepers and noxious shredders in the marsh north of the farm. If you bring me the venom, I'll replace it before Morlann notices it's gone.", progress = "Did you get that venom? Morlann's going to discover that it's gone any moment now...", completion = "&lt;Apprentice Garion inspects the venom.&gt;\n\nThis is absolutely perfect! He'll never know the difference.", rewards = "You will be able to choose one of these rewards:\n\nSpellbound CloakSeasoned Marshwood BowThe Wanderer's Cover\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11174] = {title = "Corrosion Prevention", objective = "Moxie Steelgrille wants you to dissolve 10 oozes and report back to her at Beezil's Wreck.", description = "Just look at this area! It's swarming with oozes. If I don't find some way to keep them under control, they'll corrode the wreckage and the zeppelin's cargo!\n\nI can't go back empty-handed, <class>! Help me dissolve these oozes before they've digested everything!\n\nThis device, when powered, will concentrate energy on the slimes, causing them to explode. The zeppelin's fragmented power core should power the device. The one near the main crash works all the time, but the others flicker on and off.", progress = "Did you make any progress against those oozes?", completion = "Well, it does look a little cleaner out there...\n\nI suppose it's time to get down to the business of salvaging this wreckage.", rewards = "You will be able to choose one of these rewards:\n\nCobalt-threaded GlovesMarshwarden's TunicRustproof Waistguard\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11177] = {title = "The Hermit of Swamplight Manor", objective = "Speak to \"Swamp Eye\" Jarl at Swamplight Manor.", description = "There's a fellow the locals know as \"Swamp Eye\" Jarl, who lives alone out in the swamp. Sometime ago he \"took over\" Swamplight Manor after the previous owners disappeared under mysterious circumstances.\n\nI like to send someone to check up on him every once in a while. He kind of reminds me of my grandfather, you know? Some say he's not quite right in the head.\n\nIf you're headed northwest on the road out of Theramore, you'll find Swamplight Manor in the Witch Hill area, before the road turns west.", progress = nil, completion = "Get off my lawn... unless, that is, you want to help old \"Swamp Eye\" with a little bit of cooking. Whad'ya say?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11178] = {title = "Blood of the Warlord", objective = "Bring the Blood of Zul'jin to Budd at his camp in the Ghostlands, outside Zul'Aman.", description = "As you examine the pulsating vial, your thoughts turn to the petulant little man outside Zul'Aman.\n\nYou can't wait to see Budd's expression when he sees this!", progress = "<Budd tries to mask his displeasure at your presence.>\n\nYou again....\n\nI don't know how else to say it - I'm simply too busy with my preparations to hold your hand any longer.\n\nTrust me, <name>, it's all for the best. Perhaps, by some miracle, you might eventually build a name for yourself.\n\nIf so, you'll be able to say that you got your start from the incomparable Budd Nedreck!", completion = "Th-the Blood of Zul'jin himself you say?\n\n&lt;Gathering himself, Budd continues&gt;\n\nWell, I appreciate the gesture, &lt;class&gt;, but I could've taken him down with ease. There's no way he was as fearsome as the legends say. These things have a way of being utterly overstated, as you'll learn in time. More likely, the pitiful old cretin was overcome with arthritis!\n\nAnyway, I suppose it was the least you could do as payment for the kindness I've shown you here.\n\nNow off with you - I must dispose of this vial!", rewards = nil}
MultiLanguageQuestData['en'][11180] = {title = "What's Haunting Witch Hill?", objective = "Mordant Grimsby at Swamplight Manor wants you to gather information from 10 Risen Husks or Risen Spirits.", description = "I traveled out here to pay Jarl a visit at his new home and it's been a nonstop horror show ever since! There's something seriously wrong here and I can't be the only one who sees it...\n\nHave you seen the ghosts and corpses shambling about Witch Hill? I've a feeling that if anyone knows what happened here, it is them. Seek out these risen husks and risen spirits in the surrounding area, grant them rest through combat, and see what you can learn from them before this evil consumes Jarl!", progress = "What have you learned from the spirits haunting this place?", completion = "&lt;Mordant produces a small sheet of paper and a pen, beginning to scribble down notes on your findings.&gt;\n\nFrom your findings, the spirits in this place must amount to everyone who ever lived on this land, not just the previous occupants.\n\nSomething has been corrupting and killing them. Those who follow don't learn the truth until it's too late. We have to put an end to this, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11181] = {title = "The Witch's Bane", objective = "Bring 9 sprigs of Witchbane to Mordant Grimsby at Swamplight Manor.", description = "In my years as an herbalist, I've often observed that nature will provide subtle cures to the most vexing of problems. I've read that hedge mages and witch doctors often use the smoke of an herb known as witchbane to draw evil from its hiding places.\n\nIf true, this would mean witchbane should be growing near the shallow waters of Witch Hill. You should be able to identify it by its broad leaves and reddish central stalk. Bring me any of the herb you can find, <name>. It may be our only hope.", progress = "Were you able to gather any of the herb? We must work quickly, before whatever evil is behind this infestation consolidates its hold on this area.", completion = "&lt;Mordant accepts the bunch of herbs from you.&gt;\n\nThese match the description exactly! I prepared the torch while you were out. All that remains is to fasten the herbs to the end here.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11183] = {title = "Cleansing Witch Hill", objective = "Mordant Grimsby at Swamplight Manor wants you to plant the torch at the end of the dock and defeat anything that appears.", description = "The torch is ready. Plant it at the end of the dock and be prepared to face whatever comes forth.\n\nI have no idea what the torch's smoke may reveal... if anything emerges at all. I must say, I have my doubts about this kind of folk magic, but we haven't time for anything else. For your sake and Jarl's, I wish you luck.", progress = "Is it over?", completion = "It worked?\n\n&lt;Mordant clears his throat.&gt;\n\nI mean... it worked! Jarl and I are in your debt, &lt;name&gt;. Now the only remaining problem is my friend's taste in furniture, and I'm afraid that won't be solved as easily.", rewards = "You will be able to choose one of these rewards:\n\nMordant's Travel TunicScaled MarshwalkersGrimsby's Gaudy Girdle\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11184] = {title = "WANTED: Goreclaw the Ravenous", objective = "Kill Goreclaw the Ravenous and report to Drazzit Dripvalve at Mudsprocket.", description = "Travelers and Steamwheedle personnel working in the field are advised to avoid the Bloodfen Burrow to the west of town.\n\nThe area is overrun with raptors lead by the cruel and cunning Goreclaw the Ravenous, who has already killed at least two Steamwheedle engineers.\n\nDrazzit Dripvalve has authorized a generous reward to be paid to the individual who rids Mudsprocket of this menace.", progress = "You look pretty satisfied with yourself. Come to claim the bounty on that monstrous raptor?", completion = "Thank goodness someone's finally taken me up on that offer. I was just thinking that I might need to triple the reward to get that stupid raptor killed, and our budget couldn't afford that!", rewards = "You will be able to choose one of these rewards:\n\nRaptorhide LegguardsRaptor Eye RingProtective Engineer's Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11185] = {title = "The Apothecary's Letter", objective = "Bring the Sealed Letter to Andello Porter at Tabetha's Farm.", description = "Recovered from the body of a Forsaken apothecary, this letter contains alarming evidence of a close alliance between the Grimtotems and the new masters of Lordaeron.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nThis letter should be brought to the attention of the SI:7 agent at Tabetha's Farm, Andello Porter.", progress = "What is that you're carrying, <class>?", completion = "&lt;Andello reads the letter, shocked at its contents.&gt;\n\nWe've long had misgivings about the cooperation between the Horde and the Forsaken, and this only confirms those suspicions. With the backing for Forsaken magic and arms, the Grimtotems would become an even more fearsome enemy. The balance of power in Kalimdor could shift considerably.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11186] = {title = "Signs of Treachery?", objective = "Bring the Sealed Letter to Nazeer Bloodpike in Brackenwall Village.", description = "Recovered from the body of a Forsaken apothecary, this letter hints at an underground correspondence between Undercity and the Grimtotem leadership.\n\n\"As a demonstration of good faith and a symbol of our newfound trust, we have dispatched Apothecary Cylla to aid you in battling our mutual enemy in the land of Kalimdor. None will stand before our combined might and determination.\"\n\nPerhaps Nazeer Bloodpike in Brackenwall Village will know how to handle this information.", progress = "What is that you're carrying, <class>?", completion = "If this is what it appears to be, the Forsaken have some explaining to do!\n\nThe antics of the Grimtotems have long tried the Warchief's patience. We have traditionally treated it as a matter to be settled among the tauren people, but this letter may change it.\n\nIt will take time to investigate these suspicions, but do not speak to anyone of what you have seen this day.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11191] = {title = "This Old Lighthouse", objective = "Speak to Babs Fizzletorque at the lighthouse on the island east of Theramore.", description = "The old lighthouse out to the east hasn't worked for some time, but Babs Fizzletorque has gotten it into her head to get it working again.\n\nI don't know how she plans to do it by herself, but she claims that it'll make the movement of ships and goods into the docks smoother, so I can't really object. Drawing duty on the docks is really nothing to complain about when you could be on the front lines, you know?", progress = nil, completion = "Good. I can use all the help you can offer. My first priority is to get that lamp re-lit.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11192] = {title = "Thresher Oil", objective = "Bring 4 containers of Thresher Oil to Babs Fizzletorque at the lighthouse near Theramore.", description = "The old log in the lighthouse indicates that the lamp was fueled with oil from the threshers that live along the coast here.\n\n<Babs wrinkles her nose at the mention of such outdated technology.>\n\nI suppose it's a practical, if inelegant solution. The log says that the oil taken from the youngest murk threshers works the best, and those live right underneath the docks of Theramore.\n\nIf you're up for it, would you help resupply the lighthouse with fuel?", progress = "Were you able to get any of that thresher oil?", completion = "Well, I have my doubts, but this is the only solution available right now. Once we have it up and running, I'm sure there will be time to look at other ways to fuel the lamp.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11193] = {title = "Dastardly Denizens of the Deep", objective = "Bring Dastardly Denizens of the Deep to \"Dirty\" Michael Crowe on the Theramore docks.", description = "You know, it's amazing what you can find in that old lighthouse. After I lit the lamp, I noticed this book in one of the old trunks up there.\n\n<Babs holds up the book and reads the title dramatically.>\n\n\"Dastardly Denizens of the Deep!\"\n\nWhy, I think I might swoon if I ever saw one of these! I'm sure it's good for a laugh or two, but I simply don't have time for reading right now.\n\nYou know who might enjoy it, though... that fishmonger on the docks, \"Dirty\" Michael Crowe. He collects old books.", progress = "What'll it be today? The snook is quite good.", completion = "Well, now, that was thoughtful o' Babs to send that over. I don't know if you've leafed through it or not, but there's a lot of truth to the tales in that book. Sailors didn't just make it all up, you know.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11194] = {title = "Is it Real?", objective = "Talk to Nat Pagle at Nat's Landing in Tidefury Cove.", description = "Oh, I'm sure you and Babs had a good laugh over the outlandish descriptions and sketches in the book, but have you stopped to consider there might be some truth to the legends?\n\nIf you listen closely enough, I bet you can still hear sailors talk about Tethyr, the sea creature the book says lives right here! Of course, if you wanted to know for sure, you could always ask old Nat Pagle.\n\nHe's got a small fishing camp on a little island in Tidefury Cove, which is southwest across Dustwallow Bay.", progress = nil, completion = "So you want to know about sea monsters? Hmm... well, I'll make you a deal, but it's going to involve a lot of alcohol and some embarrassment on your part.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11195] = {title = "Playin' With Dolls", objective = "Take the Tattered Voodoo Doll to Griftah in Shattrath City.", description = "I'm touched, <name>, an' dat be da truth. I'm not rememberin' the last time a <race> helped Zungam outta trouble.\n\nI snatched this from one of them savages when he was busy chainin' me up. It don't look like much, but if anyone can determine its worth, it be my good friend, Griftah!\n\nIf ya be makin' it outta here alive, it might be worth takin' this to him out in Shattrath City.", progress = "Hey, <name>! I hear ya been workin' yer way into Budd's crew. Ya won't live to regret that move, friend, I can promise ya that.\n\nWhatcha got there, mon?", completion = "Hey now, where ya be gettin' this?\n\nNo, no, don't tell me - this be comin' from the Hex-Lord himself! It all be clear now. Strong mojo! The bearer of this relic, no matter how many disgraces he be sufferin', be always honored by his peers. Incredible!\n\n&lt;As Griftah holds the doll in the air, a small, rusty charm falls from around its neck. The troll begins to discard it, but then turns toward you with a gleam in his eye.&gt;\n\nI gots no coins right now, mon, but ya be welcome to this here...", rewards = "You will receive:\n\nCharmed Amani Jewel"}
MultiLanguageQuestData['en'][11196] = {title = "TEMP X", objective = "Prigmon has tasked you with locating and assisting his cousin Zungam, somewhere within Zul'aman.Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'aman. He still be alive too mon - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Lissen mon, there be sumthin' else needs doin fer ol' Prigmon.\n\nZungam, my good-fer-nuthin' cousin, be stuck inside Zul'aman. He still be alive too mon - I seen his signal flare just last night!\n\nI should be lettin' him rot fer gettin' me tied up in this mess, but he be owin' me big money.\n\nDo what ya can to help him out, then leave the collectin' to me!You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11198] = {title = "Take Down Tethyr!", objective = "Major Mills at the Theramore docks wants you to defeat Tethyr.", description = "Sea monster or no, we're not going to risk the safety of our shipping. I've ordered our best marksmen to prepare for a confrontation with this Tethyr. The artillerymen have augmented the dock's defenses with three mortars.\n\nI'm going to order the lighthouse's lamp illuminated. If Tethyr does attack, it will be your job to operate the mortars and take down the beast before it can kill all of the marksmen. I wouldn't stand in one place too long, though. Using the mortars is likely to draw its attention.", progress = nil, completion = "Well done, &lt;name&gt;! I'll admit, when I caught my first glimpse of that beast, I had doubts about our ability to defend the docks, but you held together the defenders brilliantly!", rewards = "You will be able to choose one of these rewards:\n\nCrimson TunicSwift Wind SpauldersGolden Helm\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11200] = {title = "More than Coincidence", objective = "Krog at Brackenwall Village wants you to bring him 7 Blackhoof Armaments.", description = "We've gleaned as much as we can from the ruins of the inn. I'm concerned about where the investigation will lead us from here, but we must know the truth.\n\nBetween the hoofprints and the shield with Mosarn's mark, I'm lead to believe that the Grimtotems may have been involved. They've recently established a settlement in the swamp, Blackhoof Village to the northeast. Travel to Blackhoof Village and search for more arms of Mosarn's manufacture.", progress = "What did your search of Blackhoof Village reveal?", completion = "&lt;Krog inspects the weapons and armor you've brought from Blackhoof Village.&gt;\n\nThis is unmistakably the work of Mosarn. Questioning him further may draw too much attention, but we have a bit more freedom in dealing with the Grimtotems.", rewards = "You will be able to choose one of these rewards:\n\nBiting AxeBone DirkGlowing Tourmaline Ring\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11201] = {title = "The Grimtotem Plot", objective = "Bring the Grimtotem Battle Plan to Krog at Brackenwall Village.", description = "With the activities of the Grimtotems in Thousand Needles brought to light, many tauren now regard them with suspicion.  We've seen high-ranking Grimtotems engage in murder and kidnapping to advance their interests and I fear we may become their next target.\n\nBlackhoof Village, to the northeast, near Bluefen, is a large new Grimtotem settlement. Their leaders, the elders, will all have orders from Thunder Bluff. See if you can capture the orders and piece them together to learn the Grimtotems' plans.", progress = "Were you able to find any trace of the orders?", completion = "&lt;Krog reads over the battle plan.&gt;\n\nThere's no doubt in my mind that the Grimtotems are moving against the humans. What I don't understand is what their intentions are toward us. The actions of the Grimtotems have caused tension within the Horde in the past, but the Warchief has always diffused it.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11203] = {title = "Seek Out Tabetha", objective = "Speak with Tabetha at her farm in the Quagmire.", description = "The arms you captured in Blackhoof Village have not seen any combat beyond mere training exercises, which means the Grimtotems who destroyed the Shady Rest are still at large.\n\nTo the south, in the heart of the Quagmire, lives the witch Tabetha. Though she is a human, she has dealt honorably with us and trained some of our mages.\n\nAsk her for assistance in tracking down the band of Grimtotem responsible for burning the inn. The Alliance must not be allowed to think we were complicit in the attack.", progress = nil, completion = "&lt;Tabetha smiles slightly.&gt;\n\nKrog wishes me to scry for the Grimtotems, eh? Well, I have no need of magic in this case.\n\nIt seems we have a mutual enemy. The Grimtotems have built an outpost nearby and are a constant thorn in the side of me and my students.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11204] = {title = "Return to Krog", objective = "Speak with Krog at Brackenwall Village.", description = "I hope I've been helpful to you and I'm sorry I can't offer more information. My apprentices and I produce such a large volume of arms and armor that it's almost impossible to recall details about any individual piece.\n\nNot only do we outfit the braves defending tauren lands, but the Grimtotems have a particular fondness for my work. A seasoned warrior knows good work when he sees it.", progress = nil, completion = "He actually said that the Grimtotems are his biggest customers? Mosarn gave us more help than he knows. With this much pointing toward the Grimtotems, I think we just found our first suspects.", rewards = "You will be able to choose one of these rewards:\n\nFleshripperCrimson BarbutMariner's Sword\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11205] = {title = "Raze Direhorn Post!", objective = "Burn the North Tent, East Tent, and the Northeast Tent at Direhorn Post, then return to Tabetha at her farm.", description = "There's no scrying necessary to see the trouble my new \"neighbors\" are creating. And if this is the band that burnt down the Shady Rest Inn, as you claim, there's no reason to tolerate their presence any longer.\n\nTake this torch and raze their camp to the ground! You'll find Direhorn just to the north of my farm. You can't miss it, really, as the Grimtotems have done a splendid job of announcing their presence with those totems they favor.", progress = "Have you put that torch to good use?", completion = "The Grimtotems should have no trouble understanding our latest message.\n\nAs for you, your contact at Brackenwall Village will want to know of your success. I know the destruction of the Shady Rest Inn could be a source of tensions between the Horde and Alliance. If I encounter any investigators from Theramore, I will gladly tell them the Grimtotems acted on their own.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11206] = {title = "Justice Dispensed", objective = "Return to Krog at Brackenwall Village.", description = "I doubt the Grimtotems will give up their campaign to drive humans from the marsh. At least we have dealt with the perpetrators of the crimes at the Shady Rest Inn.\n\nI'm sure the investigator who sent you doesn't need to be told this, but the Horde can no longer afford not to rein in the Grimtotems. There will be a day when their actions will put the Horde in a regrettable position.\n\nNeither Lady Jaina nor Warchief Thrall desire another war, but are they willing to do what's necessary to avoid it?", progress = nil, completion = "&lt;Krog listens to your report.&gt;\n\nI'm impressed, &lt;name&gt;. I would've thought that the Grimtotem criminals would've been more difficult to locate. \n\nTabetha's warnings have not fallen on deaf ears, but it is not my place to chastise the Grimtotems. I will, of course, mention it in my report to the Warchief. Do not speak of it to anyone until Thrall has dealt with the Grimtotems. You have done well in solving the mystery of the Shady Rest and sparing us from the suspicion of Theramore.", rewards = "You will be able to choose one of these rewards:\n\nLeggings of the Long RoadSkirmisher's CoverSteel-banded Hauberk\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11207] = {title = "Secure the Cargo!", objective = "Moxie Steelgrille at Beezil's Wreck wants you to recover 8 pieces of Zeppelin Cargo.", description = "This zeppelin was carrying six months' worth of supplies to us at Mudsprocket! Sure, they've been able to barter for some of what they need, but they won't hold out forever.\n\nI've been sent out here to recover what I can of the cargo, but the wreckage is scattered all over the marsh in this area. I'm sure a lot of the cargo didn't survive the crash, but are you willing to help me recover what we can?", progress = "<Moxie looks frantic with worry.>\n\nDid the cargo survive? Did you find any of it?", completion = "Wow! You certainly found a lot more than I expected would be out there. I'm not sure how much Drazzit thought we were going to find out here, but he's going to have to be happy with this for now.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11208] = {title = "Delivery for Drazzit", objective = "Take the Zeppelin Cargo to Drazzit Dripvalve at Mudsprocket.", description = "Drazzit will expect to hear something from me soon, but I don't think the site is secure enough for me to leave. If you have time, would you be willing to take some of the salvaged cargo down to him at Mudsprocket?\n\nIf you haven't been there yet, it's a small settlement to the southwest of here, beyond the Stonemaul Ruins. You can take the road there from Tabetha's Farm, too. When you get to Mudsprocket, the guy you're looking for is Drazzit Dripvalve.", progress = "Yes?", completion = "&lt;Drazzit accepts the cargo from you.&gt;\n\nI'm so hungry, I could eat a dragon! Thank goodness Moxie finally got some of that cargo down here. We've been reduced to playing dice against the ogre for whatever he's managed to kill on his hunting trips!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11209] = {title = "Nat's Bargain", objective = "Nat Pagle at Nat's Landing wants you to test his new fish bait.", description = "So you found a copy of Dastardly Denizens of the Deep, did you? Well, I can tell you from experience, it's all true. I've even seen a few of 'em with my own eyes.\n\nBut you want to know about Tethyr.  I said I'd make you a deal, so here's what I want you to do. I'm working on a new line of baits, but I haven't tested this one yet.\n\nJust take this paste -- yeah, it smells a little foul -- smear it on yourself, and swim over to that wrecked ship to the southwest. If you survive, let me know how it works!", progress = "Remember, the deal is \"don't come back until something bites you.\"", completion = "Not bad at all, but you know, I think I'd get a bath in as soon as possible, if I was you.\n\nNow, about your sea monster...\n\nHelp yourself to a brew or two in the meantime.", rewards = "You will receive:\n\nDarkmoon Special Reserve"}
MultiLanguageQuestData['en'][11210] = {title = "Oh, It's Real", objective = "Speak with Major Mills at the docks in Theramore.", description = "Yes, Tethyr is certainly real, and he lives in the waters off Theramore.\n\nHas a thing for bright lights. He's the reason they shut down the lighthouse in the first place, you know...\n\nAnd if you light it up again, he'll come right back. But no one in their right mind would do that.\n\nSo that must be your plan! It's been good sharing a drink with you, but don't blame ol' Nat if Tethyr REALLY turns you into fish bait. If you're going to do this, make sure you consult Major Mills at the Theramore docks.", progress = nil, completion = "&lt;You recount your experiences with Nat Pagle, carefully omitting the portion about the 'bait test.'&gt;\n\nWell, it sounds like we've got our work cut out for us. I'll make the preparations.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11211] = {title = "Help for Mudsprocket", objective = "Speak with Drazzit Dripvalve at Mudsprocket.", description = "When that goblin... what's her name... Boxie, Foxy... Moxie, that's it! Anyway, when she came through here on her way to the zeppelin wreck, she said the town of Mudsprocket was having some problems.\n\nThat crashed zeppelin was bringing them fresh supplies. If you follow the road south from here, past the Stonemaul Ruins, you'll eventually come to Mudsprocket.\n\nWhy don't you check in with Drazzit Dripvalve down there and see if there's anything you can do to help?", progress = nil, completion = "It's good of Tabetha to send you down here. I'd prevail upon her for some food until the wreckage from the zeppelin is taken care of, but I know she's got none to spare at the moment. If you're feeling adventurous, I've posted a bounty for the death of a particularly nasty raptor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11212] = {title = "Tabetha's Farm", objective = "Speak with Tabetha at her farm in the Quagmire.", description = "Deep in the heart of the swamp lives an old woman named Tabetha. We've never really known much about her, save that she's a good deal older than she appears. She's helped us from time to time and helped keep the peace here between the Horde and our forces.\n\nShe used to keep in regular contact, but we haven't received one lately.\n\nCould you check in with her when you have time? Just follow the road beyond North Point Tower, where it turns south and into the Quagmire. You can see her farm from the road.", progress = nil, completion = "It's good of Theramore to send someone. Your guard friend's suspicions were correct. We've got some new neighbors, and they aren't the kind you'd bring a casserole.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11213] = {title = "Check Up on Tabetha", objective = "Speak to Tabetha at her farm in the Quagmire.", description = "A human woman named Tabetha lives on a small farm near the middle of the marsh. Ordinarily, I wouldn't associate with a human, but her help has proven useful at times.\n\nUnfortunately, she's been out of touch for quite some time now and I'm looking for someone to travel down to her farm to see if everything's all right.\n\nIf you follow the road south out of the village, then into the swamp's interior, you'll find her farm near the middle of the Quagmire.", progress = nil, completion = "It's fortunate Nazeer thought to send someone. We've got some new neighbors and they've been nothing but pests since they set up camp.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11214] = {title = "Mission to Mudsprocket", objective = "Speak with Drazzit Dripvalve at Mudsprocket.", description = "The Steamwheedle Cartel has recently established a new outpost in the southern part of Dustwallow Marsh. It's called Mudsprocket, if I recall, and it's located on the main road south out of Tabetha's Farm and the Stonemaul Ruins.\n\nThis is an excellent opportunity for us to establish new trade contacts and Lady Jaina wants me to send a representative down there to establish contact. Would you be willing to go?", progress = nil, completion = "So Theramore is interested in doing business? Well, that's not an offer I'd turn down. Supplies are pretty scarce here right now, so we need all the business contacts we can get!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11215] = {title = "Help Mudsprocket", objective = "Speak with Drazzit Dripvalve at Mudsprocket.", description = "The Steamwheedle Cartel's new outpost in the southern part of the marsh isn't faring so well. The zeppelin carrying supplies to Mudsprocket crashed, leaving them without vital tools, food, and medical supplies.\n\nFollow the road down south and into the marsh's interior. You'll pass by Tabetha's Farm and the Stonemaul Ruins before the road brings you to Mudsprocket. Offer any help you can provide to the town's leadership.", progress = nil, completion = "I won't turn down any help! We're in the process of setting up here and trying to make the most of what we've got, until those supplies from the zeppelin arrive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11216] = {title = "Archmage Alturus", objective = "Speak to Archmage Alturus outside of Karazhan in Deadwind Pass.", description = "I was sent here by my mentor to look for assistance, but unfortunately I'm not allowed outside of Lower City and the individuals that frequent this establishment tend to be less than helpful.\n\nYou do seem different, more like the adventurous type.  If you're interested in aiding our cause, speak to Archmagae Alturus outside of Medivh's old dwelling, Karazhan.\n\nIn the meantime, I'm going to see about gaining access to the rest of the city.  One of our old associates is rumored to be here.", progress = nil, completion = "I thank you for taking the time to come to our aid.  We've important work ahead of us.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11217] = {title = "Catch a Dragon by the Tail", objective = "Gizzix Grimegurgle at Mudsprocket wants you to bring him 8 Wyrmtail stalks.", description = "With the zeppelin crash delaying supplies, we've run out of medicines and bandages.\n\nWe're making use of what we can, but between all the insects, the injuries, and the enemies we're encountering here, I can barely keep up! I've found one herb that seems to help heal wounds and dull pain, but it, too, is in short supply.\n\nIt's called wyrmtail, and it's abundant in the Dragonmurk and Wyrmbog areas east of town. The plants themselves are made of coiled stalks, and seem to pulsate when you look at them.", progress = "Did you find any of the wyrmtail?", completion = "Thank you! This will help keep our guys going out in the field until Moxie returns with the rest of the supplies from the zeppelin crash.", rewards = "You will be able to choose one of these rewards:\n\nJourneyman's EpauletsBattlecaster's EdgeOiled Leather Leggings\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11219] = {title = "Stop the Fires!", objective = "The Masked Orphan Matron wants you to help put out all the village fires. When they are out, speak again to the Masked Orphan Matron in town.", description = "The Horde's children need you, <name>.  The Headless Horseman, once a human paladin and now an insane fiend, has set fire to our village!  You must put out those fires!\n\nGrab a bucket and throw it onto the blaze, or toss it to an ally who is closer to the flames.  Extinguish all the fires and thwart the Headless Horseman!", progress = "The Horde's children need you!  Do not abandon them!", completion = "The fires are out!  You and your fire brigade were victorious!  Hah!\n\nThe Headless Horseman's attack has failed, but until he and his head are destroyed together, he will return.\n\nUntil then, however, let's take comfort in the safety you brought our children.  I am honored to have watched your brave work today.", rewards = "You will receive:\n\nHallow's End Pumpkin TreatWeighted Jack-o'-Lantern"}
MultiLanguageQuestData['en'][11220] = {title = "The Headless Horseman", objective = "Find the Headless Horseman's Pumpkin Shrine.", description = "Until the head of the Headless Horseman is destroyed, his rampage will not end.\n\nThe Horseman rests within the Forlorn Cloister of the Scarlet Monastery, in Tirisfal Glade.  Go to his pumpkin shrine and speak these words:\n\n  Horseman, rise\n  Your time is nigh\n  You felt death once\n  Now, know demise!\n\nThis will rouse the fiend.  Destroy the head of the Horseman's and he will plague us no longer.", progress = nil, completion = "The origin of this shrine is unknown, but there is no doubt to whom it pays homage...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11222] = {title = "Warn Bolvar!", objective = "Speak to Highlord Bolvar Fordragon in Stormwind Keep.", description = "Although we don't have all the answers we might like, it's imperative that you bring our findings to Highlord Bolvar Fordragon right away!\n\nHe needs to know that the Defias have a powerful patron in Stormwind and that they're involved in the disappearance of King Varian!\n\nI can use my magic to expedite your trip to Stormwind. Just speak to me when you're prepared to go, <name>.", progress = nil, completion = "&lt;Highlord Bolvar listens while you deliver Jaina's message.&gt;\n\nAre you certain? This is a very serious charge...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11223] = {title = "Return to Jaina", objective = "Speak to Lady Jaina Proudmoore in Theramore.", description = "Do not let Lady Prestor's protestations distract you, <name>. That she is blind to this problem does not surprise me, but that is a separate matter.\n\nAs I was saying, you and Lady Jaina have my thanks for bringing your findings to me in such haste. Let her know that no good citizen of Stormwind will rest until our king walks among us again.\n\nGo to the Mage Quarter at the western end of the city and speak with Archmage Malin at the foot of the tower there. He will speed your return to Theramore.", progress = nil, completion = "That is excellent news, &lt;name&gt;! I was worried the highlord might question the veracity of our information, but I see now my concern was misplaced.\n\nYou are to be well rewarded for your efforts on behalf of Theramore and the Alliance.", rewards = "You will be able to choose one of these rewards:\n\nBejeweled DaggerGleaming Scale BreastplateArcher's Wristguard\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11225] = {title = "The Hermit of Witch Hill", objective = "Speak with \"Swamp Eye\" Jarl at Swamplight Manor.", description = "The marsh seems to have a strange effect on humans. Some grow mad simply by living here.\n\nAnyone who has ever settled at Swamplight Manor has gone mad in a spectacular way. The latest owner, one \"Swamp Eye\" Jarl, is already showing signs.\n\nI don't completely understand what's happening there, you'd have my thanks for looking into it.\n\nThe manor is at the eastern edge of the swamp. Trek east across Bluefen and past North Point Tower. The manor is in a haunted patch of land called Witch Hill.", progress = nil, completion = "Have you come here to spy on me? No?\n\nPerhaps you have an appreciation for fine cuisine, then? Good, you can help!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11242] = {title = "Free at Last!", objective = "Take the Tome of Thomas Thomson to the Costumed Orphan Matron in Goldshire, Kharanos or Azure Watch.", description = "Rage was my prison, <name>, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children may know that I will haunt them no more.", progress = "You have something for me, good <name>?", completion = "What is this?  The tome of Thomas Thomson?  But that is the name of the Horseman before he was cursed!  Does this mean that he is finally free?  Does this mean he will no longer torment the good people of Azeroth?\n\nWhat a joyous day!  &lt;name&gt;, your feat will live long with us.  The children, and their children, will sing your name!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11293] = {title = "Bark for the Barleybrews!", objective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", description = "We need to get the word out about the Barleybrews at Brewfest.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.  I'll make things easy though, I'll lend you some racing ram reins and a racing ram for 4 minutes.  Use the reins to let him go, but try not to tire him out.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the Barleybrews?", completion = "Well done!  That kinda shouting is sure to bring business our way.\n\nAnd we promised you a reward, here it is.  The Barleybrews keep their word.\n\nOh, and come back any other day if you want to help spread the good name of Barleybrew.", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11294] = {title = "Bark for the Thunderbrews!", objective = "Spread the word about Brewfest at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.", description = "It's time to let people know that the Thunderbrew have heard their cries for good brew.  You need to shout at the flags outside the bank, in the Military Ward, in the Hall of Explorers and in the Mystic Ward.\n\nWe'll make it easy though.  We'll lend you a ram AND some reins for 4 minutes.\n\nBe careful with going too fast though since you won't find any apple crates in Ironforge...  We can't take the chance of helping out the Barleybrew messengers.", progress = "Did you let everyone know that the Thunderbrews are here at Brewfest?", completion = "Good job!  That'll show those arrogant Barleybrews.\n\nWell we promised you a reward and here it is.  We Thunderbrew reward you with prizes, the Barleybrew reward you with foul odors and false promises.\n\nYou chose wisely.\n\nIf you want to keep making the right choice, stop by another day and help us spread the word.", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11318] = {title = "Now This is Ram Racing... Almost.", objective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", description = "So you want to check out the racing rams?  Well I hope you're ready for speed.  BUT before I let you loose in the world, you'll need to show me that you can handle these fine creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.  If you need instructions how to handle the ram, talk to my apprentice, Pol Amberstill.", progress = "Were you able to handle the speed?", completion = "Nice work there!  It takes time to get the hang of controlling your ram.  But once you do, you'll wish every ram was a racing ram.\n\nWhat's that? \"Where's my reward?\"  Ha Ha Ha... you got to ride the fastest ram around!  You want more?  Well how about this...\n\nYou've been rewarded with the chance to help other people around Brewfest.  There's plenty of work, and rewards, for an eager, young, ram racer.", rewards = "The following spell will be cast on you:\n\nDismount Ram - Quest"}
MultiLanguageQuestData['en'][11321] = {title = "Did Someone Say \"Souvenir?\"", objective = "Redeem the Brewfest Stein Voucher with Belbi Quikswitch in the Brewfest camp.", description = "Brewfest isn't just about racing rams, it's also about drinking!  When you have a moment, take this voucher to Belbi Quikswitch.  She's near the back of the Brewfest camp.  If you can't see her, don't worry, she'll be sure to see you.\n\nIn any case, take this voucher to her to get your free Brewfest stein.  She'll also be more than happy to handle any and all other Brewfest transactions.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nYellow Brewfest Stein"}
MultiLanguageQuestData['en'][11334] = {title = "He Shoots, He Scores!", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][11335] = {title = "Call to Arms: Arathi Basin", objective = "Win an Arathi Basin battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle of Arathi Basin that demands immediate reinforcements.\n\nReturn to me with news of victory, <name>.  We cannot allow the Horde scum to secure the resources that are rightfully ours!", progress = "Tell me, <name>.  What news do you bring from the front?", completion = "Excellent news, &lt;class&gt;!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", rewards = "You will receive:\n\nArathi Basin Mark of Honor"}
MultiLanguageQuestData['en'][11336] = {title = "Call to Arms: Alterac Valley", objective = "Win an Alterac Valley battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", description = "The reality of fighting on multiple fronts, <lad/lass>, is that we cannot spread our forces too thin or we risk losing it all!\n\nCritical troop deployments are necessary on a day by day basis.  Today it is the battle for Alterac Valley that's in most need of brave combatants.\n\nGo now, <name>, and aid the Stormpike Expedition.  We cannot allow the Frostwolf Clan to get away with the violence they've inflicted on our brethren!", progress = "Tell me, <name>.  What news do you bring from the front?", completion = "Just what I wanted to hear!  A victory in Alterac Valley - even a temporary one - is crucial to our overall strategy against the Horde.", rewards = "You will receive:\n\nAlterac Valley Mark of Honor"}
MultiLanguageQuestData['en'][11337] = {title = "Call to Arms: Eye of the Storm", objective = "Win an Eye of the Storm battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", description = "The fight against the Horde knows no boundaries, <name>.  Even in Outland, territorial disputes and old hatreds are enough to tip the scales in favor of war.\n\nGo into the Eye of the Storm and make sure the Alliance prevails in Outland just like it has in Azeroth.", progress = "Tell me, <name>.  What news do you bring from the front?", completion = "We've come one step closer to achieving total victory over the Horde.  We cannot allow the enemy to obtain a foothold in this world or any other.", rewards = "You will receive:\n\nEye of the Storm Mark of Honor"}
MultiLanguageQuestData['en'][11338] = {title = "Call to Arms: Warsong Gulch", objective = "Win a Warsong Gulch battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", description = "The Silverwing Sentinels fight to protect the forest in Warsong Gulch.  We aid them, not because we're tree-lovers, but because the forest forms a natural protective barrier for Alliance territory.\n\nTheir need is greater today than it's ever been.  We need to deploy reinforcements right away unless we want to see Ashenvale annexed to the Barrens!", progress = "What news do you bring from the front, <name>?", completion = "Excellent work, &lt;name&gt;.  The integrity of our borders must be preserved at all costs!", rewards = "You will receive:\n\nWarsong Gulch Mark of Honor"}
MultiLanguageQuestData['en'][11339] = {title = "Call to Arms: Arathi Basin", objective = "Win an Arathi Basin battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", description = "Arathi Basin is on the verge of being lost to Alliance forces.  We must send reinforcements at this very moment or all our efforts will have been in vain.\n\nDo not delay, <class>, go to Arathi Basin and crush the enemy.  Victory to the Horde!", progress = "You're back already.  Do you bring news of victory?", completion = "You've brought great honor to the Horde, &lt;name&gt;.  Your victory today will ensure a thousand victories tomorrow!", rewards = "You will receive:\n\nArathi Basin Mark of Honor"}
MultiLanguageQuestData['en'][11340] = {title = "Call to Arms: Alterac Valley", objective = "Win an Alterac Valley battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", description = "We've recently come extremely close to driving the Stormpike invaders from Alterac Valley.  As a result we're redirecting all our reinforcements to aid the Frostwolf Clan.\n\nA decisive victory there would free up the resources we need to crush the Alliance scum on all the other battlefronts.\n\nGo, <name>.  Earn great honor by heeding the call of the brave Frostwolf warriors.", progress = "You're back!  Do you bring news of victory?", completion = "There is no greater honor than driving invaders from Horde territories.  We salute your great courage in aiding our forces today!", rewards = "You will receive:\n\nAlterac Valley Mark of Honor"}
MultiLanguageQuestData['en'][11341] = {title = "Call to Arms: Eye of the Storm", objective = "Win an Eye of the Storm battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", description = "We will fight and crush the enemy wherever we find them.  Azeroth, Outland, the place makes no difference.\n\nWe cannot allow the Alliance to establish superiority in the Eye of the Storm.  Take the battle to them today... tomorrow it might be too late!", progress = "You're back!  Do you bring news of victory?", completion = "You bring honor to us all, &lt;name&gt;.  We must show the enemy that we will fight them wherever we find them.", rewards = "You will receive:\n\nEye of the Storm Mark of Honor"}
MultiLanguageQuestData['en'][11342] = {title = "Call to Arms: Warsong Gulch", objective = "Win a Warsong Gulch battleground match and return to a Horde Warbringer at any Horde capital city or Shattrath.", description = "The Alliance is an insidious enemy, <name>.  They claim to defend the Ashenvale forests to justify their acts of aggression against our territories in the Barrens.\n\nToday we have an opportunity to drive the enemy from our lands once and for all.  Go to Warsong Gulch and take back what is rightfully ours!", progress = "You're back!  Do you bring news of victory?", completion = "The Horde is in your debt, &lt;name&gt;.  You've made your people proud with your courage in defending our lands.", rewards = "You will receive:\n\nWarsong Gulch Mark of Honor"}
MultiLanguageQuestData['en'][11345] = {title = "Prizes for Pellets", objective = "[PH] Rinling wants you to shoot a marked target and then return the Target Rifle to him.", description = "[PH] Shoot a marked target.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n[PH] Tiny Creepy Rag Doll"}
MultiLanguageQuestData['en'][11354] = {title = "Wanted: Nazan's Riding Crop", objective = "Wind Trader Zhareem has asked you to obtain Nazan's Riding Crop. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Today I have a buyer who is interested in a piece that's held by the mount of Illidan's herald. I, of course, speak of Vazruden the Herald and his dragon mount, Nazan.\n\nIf you want the finder's fee that I offer in return, find them flying above the Ramparts at Hellfire Citadel and return with the dragon's riding crop.\n\nMy sources tell me that the item in question is personally held by the dragon. It is said that Nazan refuses to allow Vazruden to strike him with it.", progress = "The riding crop please.", completion = "Another soon-to-be satisfied customer. It looks like it's in fine condition. You are to be rewarded.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11356] = {title = "Costumed Orphan Matron", objective = "Speak with a Costumed Orphan Matron in either Goldshire, Kharanos or Azure Watch.", description = "During Hallow's End, human orphanages have organized trips for their orphans to visit Alliance countryside villages.  Those poor children would love to see a real <class> like yourself!\n\nWhy don't you visit them?  You'll find orphans at Goldshire in Elwynn Forest, Kharanos in Dun Morogh and Azure Watch in Azuremyst.  Speak to the children's ward, a costumed orphan matron, and she'll introduce you to the children.", progress = nil, completion = "You're here to visit the children!  Wonderful!  They have known such heartache in their short lives.  It is good that they see real heroes like you.  It really lifts their spirits!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11357] = {title = "Masked Orphan Matron", objective = "Speak with a Masked Orphan Matron in either Razor Hill, Brill or Falconwing Square.", description = "For Hallow's End, orc orphans were taken on a trip to many Horde villages.  The orphan matrons thought it would be good for them to see real heroes adventuring in the field.\n\nWhy don't you visit them?  A brave <class> like yourself could strengthen their spirits with tales of your valor!  Go to either Razor Hill in Durotar, Brill in Tirisfal Glades or Falconwing Square in Eversong Woods.  Speak with the masked orphan matron and she'll introduce you to the children.", progress = nil, completion = "The children love to watch heroes at their work.  It is my hope that, one day, each of these orphans will grow into a strong member of the Horde, and ultimately die in glorious battle!\n\nAh, thoughts of such a fine fate brings mist to my eyes...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11360] = {title = "Fire Brigade Practice", objective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", description = "With the Headless Horseman at large, the heroes of Goldshire are always ready to form a fire brigade.  Do you want to help?\n\nNorth of here, guards set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here, or the one near the fires.\n\nGood bye, <name>.  When you're done with fire brigade practice, please visit us again!", progress = "Hello, <name>.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the north!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11361] = {title = "Fire Training", objective = "Toss Water Buckets on 5 fires, then speak with the Masked Orphan Matron in Razor Hill.", description = "The grunts set up a fire training area outside the village.  These days, Razor Hill's buildings often catch fire -- you should lend a hand and train as a fire fighter!\n\nHead west out of Razor Hill, then turn right as you pass the village's wall.  Find the training area, then grab buckets and toss them on the practice fires.", progress = "Have you dowsed any fires, <name>?  The training area is west of Razor Hill's western exit.", completion = "Well done, &lt;name&gt;!  Children, take a good look at this &lt;class&gt;. Grow strong and brave like him and one day you too will fight for the Horde.", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11362] = {title = "Wanted: Keli'dan's Feathered Stave", objective = "Wind Trader Zhareem has asked you to obtain Keli'dan's Feathered Stave. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "There is no accounting for taste. Take my most recent buyer for instance.\n\nThere is a blood orc within Hellfire Citadel known as Keli'dan the Breaker. He bears a most mundane stave; certainly nothing to take a second glance at. And yet, this is what my customer wishes.\n\nWho am I to say no?\n\nIf you desire my compensation, you will find him and his stave within the Blood Furnace.", progress = "We are speaking again... you must have the stave.", completion = "Perhaps I will have new feathers tied onto it before shipping it on to the buyer. I'm certain with so many arakkoa hereabouts it will not prove difficult. A small matter, and nothing to detract from your reward in any case.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11363] = {title = "Wanted: Bladefist's Seal", objective = "Wind Trader Zhareem has asked you to obtain Bladefist's Seal. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Today I have a very wealthy collector in need of something very unique indeed.\n\nWarchief Kargath Bladefist carries upon his person his seal of command, which he uses to sign all official documents. I want you to retrieve it for me.\n\nYou will find him deep within the Shattered Halls. No doubt you will have to wade through a veritable army to get to him. I have no doubt that you will succeed.", progress = "I have heard it whispered that the warchief has weapons in place of his hands. Is this true?", completion = "Truly a daring acquisition that the bards should put pen to parchment for. Here, you have more than earned this.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11364] = {title = "Wanted: Shattered Hand Centurions", objective = "Nether-Stalker Mah'duun has tasked you with the deaths of 4 Shattered Hand Centurions. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "Do you question your master? Neither does Mah'duun.\n\nThe blood of the centurions of the Shattered Hand clan is what I seek. You will find them within the Shattered Halls of Hellfire Citadel.\n\nIf you want the bounty, you will not return until you have slain them all.", progress = "You have returned. The centurions all lay dead?", completion = "Very well, you have earned your bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11368] = {title = "Wanted: The Heart of Quagmirran", objective = "Wind Trader Zhareem has asked you to obtain The Heart of Quagmirran. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "I have an unusual request. A certain wealthy individual that I am in contact with off-world is interested in a macabre piece.\n\nSpecifically, she wants the heart of Quagmirran.\n\nI hear that the beast has three, but one will suffice for our purposes. As I understand it, you can find Quagmirran resting within a deep pool of water at the Slave Pens.", progress = "I trust that you know of a way to preserve the heart in transit?", completion = "Now that I think of it, it's a pity I didn't ask you to return with the other two hearts as well. Perhaps next time. In any case, you've earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11369] = {title = "Wanted: A Black Stalker Egg", objective = "Wind Trader Zhareem wants you to obtain a Black Stalker Egg. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "There is only ever one great mother of the marsh walkers in Zangarmarsh. She is always known as the Black Stalker, and she hatches from one of the eggs left behind when her mother dies.\n\nI have a buyer who is interested in one of those eggs. He mentioned something about adding her as a zoo attraction.\n\nIf you are interested in the reward I am offering, travel to the Underbog and slay the Black Stalker for her egg.", progress = "We're speaking again because you have the egg? Outstanding, let me see it!", completion = "Is it not amazing to feel the life pulsing within the egg? I must hurry to deliver it to the purchaser. We wouldn't want it hatching here now would we?\n\nYour payment is ready.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11370] = {title = "Wanted: The Warlord's Treatise", objective = "Wind Trader Zhareem has asked you to acquire The Warlord's Treatise. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "While it is known that Warlord Kalithresh of the naga is a great warrior in his own right, there are fewer who know that he has codified all of his knowledge.\n\nOne of my customers is aware of it though, and is keenly interested in obtaining his treatise.\n\nI ask that you travel to the Steamvault in Coilfang Reservoir and obtain this book for me.", progress = "My customer grows restless. I believe he wishes to plumb the depths of the warlord's tactical thinking to help with one of his ongoing conflicts.", completion = "Indeed, I fear my customer will not have time to peruse the entirety of this book. Nevertheless, that is not our concern.  Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11371] = {title = "Wanted: Coilfang Myrmidons", objective = "Nether-Stalker Mah'duun has asked you to slay 14 Coilfang Myrmidons. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "Mah'duun hears and obeys, and I now ask you to be my instrument.\n\nIt has been related to me that the myrmidons of the coilfang tribe must be destroyed. Seek them out within the humid confines of the Steamvault underneath Coilfang Reservoir.\n\nI will accept nothing less than their utter annihilation.", progress = "How fares your fight against the coilfang myrmidons?", completion = "I trust that it was a fight worthy of your time? Certainly this bounty will be.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11372] = {title = "Wanted: The Headfeathers of Ikiss", objective = "Wind Trader Zhareem has asked you to acquire The Headfeathers of Ikiss. Deliver them to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "I've recently been approached by a tauren whose husband is about to be elevated to chieftain. She wishes to make a special addition to his headdress.\n\nSpecifically, she wants to obtain the headfeathers from the dastardly Talon King Ikiss.\n\nIf you are interested in collecting my reward, travel to Auchindoun's Sethekk Halls and find him.", progress = "The time of the chieftain's ceremony grows near.", completion = "I am sure that these feathers will make a fine addition to the chieftain's headdress. You have earned your compensation, &lt;class&gt;.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11373] = {title = "Wanted: Shaffar's Wondrous Pendant", objective = "Wind Trader Zhareem wants you to obtain Shaffar's Wondrous Amulet. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Today I have a personal request of you, yet the reward will certainly match the danger.\n\nMy family has a 'history', shall we say, with Nexus-Prince Shaffar and his followers. If the amulet he wears were to fall into my hands then surely that would mean that he had been dealt with.\n\nIf the bounty I am offering is of interest to you then journey to his lair within Auchindoun's Mana-Tombs.", progress = "Not many know that the source of Shaffar's magic rests solely within his amulet. Without it he is powerless.\n\nThen again, if you have it that must mean that he is dead.", completion = "&lt;You sense a deep level of satisfaction from the wind trader.&gt;\n\nGood, I am glad to hear of his demise. And perhaps I will be able to unlock the secrets of his amulet for myself. If not, then I will sell it for a handsome price.\n\nI trust that this reward is sufficient.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11374] = {title = "Wanted: The Exarch's Soul Gem", objective = "Wind Trader Zhareem has asked you to recover The Exarch's Soul Gem. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Within Auchindoun's Auchenai Crypts many unsavory experiments are undertaken in the pursuit of a greater understanding of the necromantic arts. Many are the spirits that are tortured or destroyed therein.\n\nI have a customer who is interested in the liberation of one of those spirits. I have been informed that this spirit is contained within a soul gem held by none other than Exarch Maladaar himself.\n\nSeek him out within the crypts with all due haste and return to me with the gem.", progress = "Can you imagine being trapped within a gem for all eternity?", completion = "You're quite the hero, &lt;name&gt;. I am certain that my customer will find a way to free the spirit of their loved one from within the gem. For a job well done, your payment awaits.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11375] = {title = "Wanted: Murmur's Whisper", objective = "Wind Trader Zhareem has asked you to obtain Murmur's Whisper. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "When I'm done speaking, you may not want to take this commission.\n\nI have an eccentric client who specializes in the study of dead realities. It is rumored that the being known as Murmur destroyed the last world from which he was summoned. The professor is interested in examining his 'whisper' as he called it to understand how it is that Murmur accomplished such a feat.\n\nWill you journey to the Shadow Labyrinth within Auchindoun and retrieve it for me?", progress = "I'm not even certain what form a whisper is supposed to take in the physical world, but the professor assures me that you'll know it when you see it.\n\nPerhaps it is something akin to the being's voice box?", completion = "I was worried that you might not return. I trust that you didn't go deaf from fighting Murmur?\n\nHere is your reward. The professor will be pleased no doubt, though I worry what he ultimately wishes to do with this thing.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11376] = {title = "Wanted: Malicious Instructors", objective = "Nether-Stalker Mah'duun wants you to kill 3 Malicious Instructors. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "Mah'duun has heard it said that none are as cruel as the six-armed demonesses inside the Shadow Labyrinth.\n\nGo to Auchindoun, seek them out, kill them all.\n\nIf you cannot accomplish so simple a task, we do not have anything further to say to one another.", progress = "The instructors, they are all dead? No?\n\nDid I not say not to return unless you had killed them all?", completion = "I am satisfied. He who speaks through the nether shall be as well. Mah'duun has your bounty prepared.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'deen.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11377] = {title = "Revenge is Tasty", objective = "The Rokk in Lower City has asked you to cook up some Kaliri Stew using his cooking pot. Return to him when it's done.", description = "I'm providing the catering for some unusual party guests tonight.  One of these fellows was flying around in Skettis and got knocked to the ground by a monstrous kaliri--his leg was broken badly.\n\nThey've requested something special for his get well party: Kaliri Stew.\n\nI can loan you my cooking pot so you can whip up a batch of stew for me.  The recipe itself is simple, but you'll need to get a giant kaliri wing and some cooked warp burgers.", progress = "Do I smell something tasty?", completion = "Oh, I do smell something tasty!  I hope you gave that bird quite a good beating.\n\nPlease, help yourself to some of my extra stock.  I'm sure someone of your talent could put it to good use.", rewards = "You will be able to choose one of these rewards:\n\nBarrel of FishCrate of Meat\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11378] = {title = "Wanted: The Epoch Hunter's Head", objective = "Wind Trader Zhareem has asked you to obtain the Epoch Hunter's Head. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "The tastes of my customers range from the mundane to the exotic. And sometimes they want to do very mundane things with the exotic objects they seek.\n\nSuch is the case with my latest request. My client, who shall remain nameless, wishes to obtain the head of the Epoch Hunter to mount on his wall.\n\n<class>, will you find a way to travel back in time to Old Hillsbrad and procure said head for my trophy-hunting patron?", progress = "The head of the Epoch Hunter... how does one come to the decision that they want it mounted on their wall?\n\nAnd even then, to not hunt the beast yourself, what does one say to their friends when asked how the fight went?\n\nHe'll lie, I suppose.", completion = "I see you are returned to the present time intact.\n\n&lt;The wind trader looks around.&gt;\n\nIt doesn't appear that anything has changed. But then again, how would I know?\n\nThat's a nice cut; my customer will be pleased. Here is your reward.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11379] = {title = "Super Hot Stew", objective = "The Rokk in Lower City has asked you to cook up some Demon Broiled Surprise using his cooking pot, two Mok'Nathal Shortribs and a Crunchy Serpent. Return to him when it's done.", description = "I'm trying to invent something with some real zing.  But to be honest, I'm more of an idea goblin these days.  I've lost my sense of adventure.\n\nBut you... remind me of my younger days; ready to take on the world with a sword in one hand and a skillet in the other.\n\nI want you to take my beloved cooking pot and head out to Blade's Edge.  Throw in some shortribs and crunchy serpent--already cooked for extra flavor--and broil it over an abyssal's corpse, the only thing hot enough to do the trick.", progress = "Any luck with my little experiment?", completion = "Now look at that...\n\n&lt;The Rokk takes a sip of the concoction and his face twists into a bizarre mask of pain and delight.&gt;\n\nSweet A'dal that's good!  A cook with your potential shouldn't be without his proper materials.  Take some of my extra stock and make me proud.", rewards = "You will be able to choose one of these rewards:\n\nBarrel of FishCrate of Meat\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11380] = {title = "Manalicious", objective = "The Rokk in Lower City has asked you collect 15 Mana Berries from the Eco-Domes in Netherstorm.", description = "Wouldn't you know it, I think my foodstuffs are up to date and someone comes along and requests the unusual: Mana Berry Delight.\n\nUnfortunately, mana berries are only found in the eco-domes of Netherstorm.  Just don't bother looking around Stormspire--it's picked clean.\n\nI could only trust someone trained in the culinary arts to pick the best berries, so don't let me down!", progress = "Any luck, friend?", completion = "Those are the juiciest mana berries I've ever seen.  I think I'm getting smarter just by looking at them.\n\nSince I no longer need most of my meat and fish stock, why don't you take some?  I'm certain you could make something delicious.", rewards = "You will be able to choose one of these rewards:\n\nBarrel of FishCrate of Meat\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11381] = {title = "Soup for the Soul", objective = "The Rokk in Lower City has asked you to cook up some Spiritual Soup using his cooking pot. Return to him when it's done.", description = "Death is in the air.  I've never had so many orders for my famous soup--it lifts your spirits and soothes the soul.\n\nAnd I know a fellow cook when I see one!  Would you like to help me out and get a cut of the profits?\n\nHere, take my cooking pot, gather some clefthoof meat and I'll let you in on a little secret.  What makes my soup so good for the soul?  It's not chicken--I cook it at the Ancestral Grounds in Nagrand to soak up all that spiritual stuff there.", progress = "What smells so good?", completion = "That is a fine batch of spiritual soup if I ever did smell one.  Just a pinch of pepper and it's done.\n\nAs promised, here's your cut.  And because you did such a fine job, I'm going to throw in some of my extra stock.", rewards = "You will be able to choose one of these rewards:\n\nBarrel of FishCrate of Meat\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11382] = {title = "Wanted: Aeonus's Hourglass", objective = "Wind Trader Zhareem has asked you to acquire Aeonus's Hourglass. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "I swear that some of my customers are crazy. There are possessions that you go after, and there are ones that you dare not even think of!\n\nMy current client is clearly over-the-top insane. He covets the hourglass that Aeonus holds.\n\nYes, you heard right, Aeonus of the Infinite Dragonflight!\n\nWho am I to argue since he's paying a king's ransom? So, ready to go to the Caverns of Time and travel to the Black Morass to retrieve it for me?", progress = "If I were you, I would be very careful with time-travel. You wouldn't want to accidentally do something, like kill one of your ancestors, and then accidentally erase yourself from the present!", completion = "Odd that the sands in that thing are still falling upward. I think I will have it delivered to its new owner with all due haste.\n\nI thank you for a job well done, &lt;class&gt;. You have certainly earned your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11383] = {title = "Wanted: Rift Lords", objective = "Nether-Stalker Mah'duun wants you to kill 4 Rift Lords. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "Mah'duun knows where you must go. Mah'duun knows that you must kill rift lords. But, Mah'duun does not know exactly when.\n\nI know that does not make sense, but the voice on the winds was not more specific.\n\nTravel to the Black Morass through the Caverns of Time and the way shall be made clear.", progress = "We are speaking, but I sense that all of the rift lords are not yet dead.\n\nReturn again when they are, <class>.", completion = "You found your way back in time, and then back again. You must be a great &lt;class&gt;, &lt;race&gt;. The bounty is earned.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11384] = {title = "Wanted: A Warp Splinter Clipping", objective = "Wind Trader Zhareem has asked you to obtain a Warp Splinter Clipping. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Not long ago, I was approached by a kaldorei druidess with a touching request. And plenty of gold, of course!\n\nIt would appear that the forces of Darnassus wish to restore an ancient of the arcane known as Warp Splinter. The giant tree has been confused or corrupted, I'm not certain, but you'll find it inside of the Botanica at Tempest Keep.\n\nShe said that all they would need to regrow him was a small clipping.", progress = "Did you lose your way to the Botanica? You can't miss it... it's at Tempest Keep off of the eastern edge of the Netherstorm.", completion = "Aw, you did get it! It's so tiny. And yet, when the druids are done with it -- a process I am told will take a very long time -- Warp Splinter will be regrown anew.\n\nAnd here is your reward as promised.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11385] = {title = "Wanted: Sunseeker Channelers", objective = "Nether-Stalker Mah'duun wants you to kill 6 Sunseeker Channelers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "It has been whispered to Mah'duun that the channelers of the military unit known as the Sunseekers must be killed today.\n\nThey are to be found within the Botanica at Tempest Keep.\n\nYou want the bounty, you kill the channelers.", progress = "How can it be that we are speaking when the channelers are not all lying dead?", completion = "And now they are dead, channeling no longer. He who whispers upon the nether is satisfied and you have secured the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11386] = {title = "Wanted: Pathaleon's Projector", objective = "Wind Trader Zhareem has asked you to acquire Pathaleon's Projector. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "I always assumed that Pathaleon the Calculator used magic to project his image across Outland. Apparently I was wrong.\n\nMy latest customer tells me that the blood elf uses a mechanical device for his communication with the leaders of Prince Kael'thas's special projects. As I understand it, he acquired it from the Zaxxis rebels in the Netherstorm.\n\nMy client wishes to obtain the projector. Why don't you pay Pathaleon a visit? He can be found within the Mechanar at Tempest Keep.", progress = "It's not that projector technology is something special in and of itself, but the range of this particular model is a true breakthrough!", completion = "I'm tempted to keep it for myself and return my client's money. It could certainly expand the reach of my business.\n\n&lt;The wind trader sighs.&gt;\n\nHowever, I have a reputation to uphold.\n\nSpeaking of my reputation, thank you for helping me to maintain it. Here is your commission.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11387] = {title = "Wanted: Tempest-Forge Destroyers", objective = "Nether-Stalker Mah'duun wants you to destroy 5 Tempest-Forge Destroyers. Return to him in Shattrath's Lower City once they all lie dead in order to collect the bounty.", description = "There are mechanical constructs within the Mechanar which Mah'duun has been told must be dismantled.\n\nGo to Tempest Keep, find the tempest-forge destroyers and destroy them.\n\nThen you may return to collect the bounty.", progress = nil, completion = "Mah'duun enjoys fighting constructs; they are less messy than organic beings.\n\nThe bounty is yours.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11388] = {title = "Wanted: The Scroll of Skyriss", objective = "Wind Trader Zhareem has asked you to obtain The Scroll of Skyriss. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed on Heroic difficulty.", description = "Today's client seeks something truly unique.\n\nIt is said that Harbinger Skyriss is a servant of the Old Gods. It is also said that he carries a large scroll that contains their instructions for his domination of life in the universe on their behalf.\n\nMy current buyer wishes to get <his/her> hands on that scroll, nevermind that <he/she> won't be able to read the language upon it.\n\nTravel to Tempest Keep's Arcatraz and get it for me, will you, <class>?", progress = "It must be a very dangerous thing to do to meddle directly in the affairs of the Old Gods.\n\nBetter you than me!", completion = "I dare not touch the scroll lest I too risk the notice of the Old Gods. I will have one of my assistants handle its delivery.\n\nYou have more than earned your reward, &lt;class&gt;, and I wish you all the luck in the known worlds.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11389] = {title = "Wanted: Arcatraz Sentinels", objective = "Nether-Stalker Mah'duun wants you to dismantle 5 Arcatraz Sentinels. Return to him in Shattrath's Lower City once that has been accomplished in order to collect the bounty.", description = "The sentinels within the Arcatraz have gone haywire. The prisoners run rampant and the guards attack those that would help.\n\nMah'duun hears the speaker on the nether winds. The speaker says to destroy the sentinels\n\nAccomplish this and today's bounty is yours.", progress = nil, completion = "With the sentinels destroyed, perhaps the naaru will ask the Consortium to replace them? Mah'duun does not know and does not care.\n\nYou have earned the bounty.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11392] = {title = "Call the Headless Horseman", objective = "Take a Dreary Candle to the Loosely Turned Soil.", description = "Many dreary candles adorn this pumpkin shrine.", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11400] = {title = "Brewfest Riding Rams", objective = "Bring the \"Honorary Brewer\" Hand Stamp to Pol Amberstill near the entrance to the Brewfest Grounds in Dun Morogh.", description = "If you show this hand stamp to Pol Amberstill, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, &lt;name&gt;... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", rewards = nil}
MultiLanguageQuestData['en'][11401] = {title = "Call the Headless Horseman", objective = "Take a Dreary Candle to the Loosely Turned Soil.", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11403] = {title = "Free at Last!", objective = "Take the Tome of Thomas Thomson to a Masked Orphan Matron in Durotar, Brill or Falconwing Square.", description = "Rage was my prison, <name>, and you have freed me.  Though I thought I did right, my soul now weeps for the terror and the death I have caused the good people of Azeroth.\n\nThank you for leading me back to the Light.  May I never again lose my way.\n\nTake this torn prayer book to an orphan matron, so the children will know that I will haunt them no more.", progress = "<name>, it is good to see you again.  I'm sure the children enjoy tales of your heroism.", completion = "What?  This holy tome once belonged to an infamous paladin of the Alliance.  Was he the Headless Horseman?  Does this mean that the Horseman is defeated?\n\nThis is a glorious day, &lt;name&gt;!  Your legend will shine bright, and may it last for twice the years of the Horseman's reign of fear.", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11404] = {title = "Call the Headless Horseman", objective = "Take a Dreary Candle to the Loosely Turned Soil.", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11405] = {title = "Call the Headless Horseman", objective = "Take a Dreary Candle to the Loosely Turned Soil.", description = "Many dreary candles adorn this pumpkin shrine, which grins, taunting...", progress = "This dirt has been recently disturbed.  Earthworms lie in the topsoil, squirming to escape the dark depths beneath them.", completion = "Will you lay the candle down and call the Headless Horseman from his doomed rest?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11407] = {title = "Bark for Drohn's Distillery!", objective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", description = "So, do you want to help bring strength and honor to Brewfest?  We need you to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nWe'll lend you a racing ram for 4 minutes and also give you these racing reins.\n\nBe careful though, the cheap goblins didn't put any apple crates along the way.", progress = "Have you finished spreading the word about Brewfest?", completion = "You kept your word and let people know about our brewmasters.  Thank you. We promised you these tokens, and gladly give them to you.  I imagine the trolls are a bit more stingy with handing over their tokens...\n\nCome back another day to help us spread the word about Brewfest.", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11408] = {title = "Bark for T'chali's Voodoo Brewery!", objective = "Spread the word about Brewfest at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.", description = "We need to spread the word about the trolls at Brewfest.  Ya need to shout at the flags outside the auction house in the Valley of Strength, in the Valley of Honor, in the Valley of Wisdom and in the Valley of Spirits.\n\nBut I'll make it easy for ya, I'll lend you a racing ram for 4 minutes.  I'll also give you these racing reins.\n\nBe careful though, the goblins didn't put any apple crates along the way.  They are cheap like that.", progress = "Have you finished spreading the word about Brewfest?  But more importantly, did you let people know about the amazing troll brew?", completion = "Ya did it!  We gotta get ready for the flood of customers that are sure to come our way!  Thanks!\n\nOh, that's right, and we promised you a reward.  Can't forget about that...\n\nFeel free to stop by again another day to help us spread the word some more.", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11409] = {title = "Now This is Ram Racing... Almost.", objective = "You have 4 minutes to ride the ram and maintain 3 different levels of speed for 8 seconds.", description = "So you want to check out the racing rams?  The dwarves think they have got a handle on it, but let's be honest, they are drunk most of the time, so how hard can it really be?\n\nNow before I let you strut your stuff, you'll need to show me that you can handle these fine, legally obtained creatures.\n\nSo here's the deal:  I'll lend you some racing reins and the use of a ram. You need to prove to me that you can handle using these rams.\n\nKeep the ram at a trot, canter and gallop for 8 seconds each.", progress = nil, completion = "Hey, that wasn't too bad... are you sure you're not a dwarf?\n\nSo there's plenty more racing to be had and it's not just from me.  All over the Brewfest grounds you'll find people in need of a decent ram racer.  So go and make yourself useful.\n\nOh and don't forget, these rams were legally obtained.  I just want to make sure we're clear.", rewards = "The following spell will be cast on you:\n\nDismount Ram - Quest"}
MultiLanguageQuestData['en'][11412] = {title = "There and Back Again", objective = "Get a keg from the Goblin stranded on the road to Razor Hill and return it to Ram Master Ray's assistant. Do this 3 times before your ram goes away.", description = "Am I glad you're here.  We are in big trouble!  The goblin that was supposed to be bringing us more brew had an accident on his way from Razor Hill.  You gotta get us that brew!\n\nI'll put you on one of my racing rams and you follow the road to Razor Hill.\n\nOnce you get near him he'll toss you a keg, then you run the keg back here and toss the keg to my more capable assistant.  For now, all we want are 3 kegs.  Do a good job and maybe we'll have another job for you.", progress = "Did you see the mess that goblin made?  I hope you didn't do too much reckless off-roading.", completion = "Thanks for your help!  As long as Brewfest is going, the Dark Iron dwarves are attacking and our supplier is stuck in that canyon, I'll need some help shipping kegs.  So if you want to work for more tokens, talk to me every day.\n\nHere are the tokens we promised you.  Have fun!", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][11413] = {title = "Did Someone Say \"Souvenir?\"", objective = "Redeem the Brewfest Stein Voucher with Blix Fixwidget in the back of the Brewfest camp.", description = "Not only are we supplying brew to everyone, we also have steins to give out!  Beautiful, commemorative steins all obtained by the most legal of means!  Here's a voucher for one.\n\nTalk to Blix near the back of the Brewfest camp.  He's pretty strange, even more so now that he's always wearing those goggles.  He'll handle the voucher for you, and any other Brewfest transaction.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nYellow Brewfest Stein"}
MultiLanguageQuestData['en'][11419] = {title = "Brewfest Riding Rams", objective = "Bring the \"Honorary Brewer\" Hand Stamp to Driz Tumblequick near the entrance to the Brewfest Grounds in Durotar.", description = "If you show this hand stamp to Driz Tumblequick, the Ram Racing Apprentice, he'll allow you to purchase Brewfest riding rams.", progress = "Is that an \"Honorary Brewer\" stamp you've got on your hand?", completion = "Good job, &lt;name&gt;... you've won the trust of the festival's brewers, earning the right to purchase a Brewfest riding ram.", rewards = nil}
MultiLanguageQuestData['en'][11425] = {title = "Test Quest - Craig", objective = "Vermin, gotta hate 'em.", description = "Go on a quest!You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11431] = {title = "Catch the Wild Wolpertinger!", objective = "The \"dwarf,\" Glodrak Huntsniper, has asked you to capture 5 Stunned Wolpertingers using the Wolpertinger Net. He mentioned that you must be intoxicated to see them.", description = "Hey there!  I'm a crazy dwarf!  We dwarves believe when you get enough brew together, invisible creatures show up.  In fact they are probably wandering around the Brewfest grounds right now! But you can only see them if you are really drunk.\n\nWe dwarves will come up with any excuse to drink.\n\nI bet you want a reason to drink too...  So here it is, bring me 5 of those wolpertingers with this net I got from a really drunk dwarf.\n\nIf you can't see them, you're probably not drunk enough.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nWolpertinger's Tankard"}
MultiLanguageQuestData['en'][11435] = {title = "Gathered Pumpkins NYI", objective = "Take the bunch of jack-o'-lanterns to the Costumed Orphan Matron.", description = "Hi, <name>!  Thanks for driving away the Horseman!  Now that he's gone, the matron said we can roam the village!\n\nI found some pumpkins that the Horseman dropped.  They look scary... will you take them and show  them to the matron?You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nWeighted Jack-o'-Lantern"}
MultiLanguageQuestData['en'][11439] = {title = "Fire Brigade Practice", objective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", description = "The brave dwarves of Kharanos can form a fire brigade in an instant, now that the Headless Horseman is around. Do you want to help?\n\nSouth of here, the mountaineers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, <name>.  When you're done with fire brigade practice, please visit us again!", progress = "Hello, <name>.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the south!", completion = "You're smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11440] = {title = "Fire Brigade Practice", objective = "Throw Water Buckets onto 5 fires, and then speak with the Costumed Orphan Matron.", description = "With the threat of the Headless Horseman looming, the peacekeepers have been diligent in forming a fire brigade when needed. Do you want to help?\n\nWest of here, toward the Exodar, the peacekeepers set up a small area to practice fighting fires.  Go there and throw buckets onto the blazes.  You can fill a bucket from the water barrel here.\n\nGood bye, <name>.  When you're done with fire brigade practice, please visit us again!", progress = "Hello, <name>.  Have you been perfecting your fire fighting techniques?  Don't forget about the practice area to the west!", completion = "You're wet and smudged with soot!  You must have been extinguishing fires!\n\nWell done!  As an honorary member of the Fire Brigade, I beg you to return here if ever the village needs you!", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11441] = {title = "Brewfest!", objective = "Speak to the Brewfest Organizer.", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Ho ho! Come for your free beer?", rewards = "You will be able to choose one of these rewards:\n\nBarleybrew ClearThunder 45Gordok Grog"}
MultiLanguageQuestData['en'][11442] = {title = "Welcome to Brewfest!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "Ho ho! Come for your free beer?", rewards = "You will be able to choose one of these rewards:\n\nBarleybrew ClearThunder 45Gordok Grog"}
MultiLanguageQuestData['en'][11446] = {title = "Brewfest!", objective = "Speak to the Brewfest Organizer.", description = "Speak to the Brewfest Organizer at the Brewfest Grounds outside of Orgrimmar and receive a free beer.", progress = nil, completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", rewards = "You will be able to choose one of these rewards:\n\nBarleybrew ClearThunder 45Gordok Grog"}
MultiLanguageQuestData['en'][11447] = {title = "Welcome to Brewfest!", objective = "[PH] Speak to the Brewfest Organizer and receive a free beer.", description = "[PH] Speak to the Brewfest Organizer at the Brewfest Grounds outside of Ironforge and receive a free beer.", progress = nil, completion = "What?! A free beer? Yeah, yeah. I guess we said we'd do that this year.", rewards = "You will be able to choose one of these rewards:\n\nBarleybrew ClearThunder 45Gordok Grog"}
MultiLanguageQuestData['en'][11449] = {title = "Fire Training", objective = "Toss buckets on 5 fires, then speak with the Masked Orphan Matron in Brill.", description = "The deathstalkers have set up a fire training area outside the town.  We cannot afford further damage to the buildings of Brill - you should do your duty and train as a fire fighter.\n\nHead west past the graveyard, following the road. You'll find the training area there.", progress = "Have you dowsed any fires, <name>?  The training area is west of Brill.", completion = "Well done, &lt;name&gt;.  Children, take a good look at this &lt;class&gt;.  Let him be a strong example to you.", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11450] = {title = "Fire Training", objective = "Toss buckets on 5 fires, then speak with the Masked Orphan Matron in Falconwing Square.", description = "The guards have set up a fire training area outside the town.  We cannot allow the Horseman to destroy what we have worked so hard to rebuild - you should do your duty and train as a fire fighter.\n\nHead south through the gate to the crossroads. You'll find the training area there.", progress = nil, completion = "Well done, &lt;name&gt;.  Children, take a good look at this &lt;class&gt;.  Let him be a fine example for you to follow.", rewards = "You will receive:\n\nHallow's End Pumpkin Treat"}
MultiLanguageQuestData['en'][11451] = {title = "Alicia's Poem", objective = "You have been asked to deliver Alicia's Poem to Caylee Dak in Shattrath City in Outland.", description = "Hi, I wrote a poem for my friend Caylee.  She likes to hang out with the Aldor in Shattrath City.  You know, in Outland?\n\nCould you take my poem to her?  My mommy says I'm too young to go to Shattrath City!", progress = "Oh, is that a poem?", completion = "What a touching poem, thank you!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11454] = {title = "Seek the Saboteurs", objective = "Find Coren Direbrew in the Grim Guzzler within Blackrock Depths.This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.You will receive:\n\n", description = "This scrap of paper seems to have been left behind accidentally by the Dark Iron invaders.\n\nWhile the plans are complicated and written in some form of coded Dwarvish, the signature at the end - \"Coren Direbrew\" - is clear enough, as is mention of the Grim Guzzler deep within Blackrock Depths. You should seek out the instigator and put an end to these raids.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nDark Iron Ale Mug"}
MultiLanguageQuestData['en'][11481] = {title = "Crisis at the Sunwell", objective = "Adyen the Lightwarden on the Aldor Rise in Shattrath City has requested that you travel to Sunwell Plateau and speak with Larethor.", description = "By the naaru, I thank you, <race>, for your efforts.\n\nOur work is far from finished, however, and I must request that you undertake a critical mission - one as important as any I've issued.\n\nOur forces are spread thinly. To compound the strain, we've had to dispatch a contingent to Azeroth to investigate developments at the Sunwell Plateau.\n\nYou are needed there, <name>. Report to Larethor. Tell him that I wish we could spare more men.", progress = nil, completion = "Another soldier from Shattrath? A welcome sight!\n\nWish there were more of you, but we'll make due with what we have. Whatever's going on out here won't wait for us to make ready.\n\nHave a look around, &lt;class&gt;. There's much that needs doing. Pitch in and do your share.\n\nOh, yeah, and don't go tauntin' the cryers - err, Scryers. Looks like we're in this thing together....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11482] = {title = "Duty Calls", objective = "Dathris Sunstriker on Scryer's Tier in Shattrath City has insisted that you travel to Azeroth at once and report to Larethor at the Sunwell.", description = "Hear me, <race>.\n\nDuty requires that you return to Azeroth. Every able person is to report to the Sunwell Plateau immediately.\n\nI'm afraid I have no more information to share, except this:\n\nYou'll be joining forces with the Aldor for this mission. Speak with a draenei by the name of Larethor when you arrive.\n\nApparently, the situation calls for us to set our differences aside and join forces.\n\nPrepare yourself, friend. This sounds serious.", progress = nil, completion = "Welcome to Sunwell Plateau, cryer - What's that? Oh Scryer, yes of course. Isn't that what I said?\n\nWell, now, let's get a few things straight. There's some serious business going on behind those walls and it's in the interest of both of our people to address it. And since neither of us have the forces to go it alone, we're going to work - TOGETHER. Got that?\n\nNow let's get started, shall we?", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11488] = {title = "Magisters' Terrace", objective = "Exarch Larethor at the Shattered Sun Staging Area wants you to search Magisters' Terrace and find Tyrith, a blood elf spy.", description = "Welcome to the Sunwell, <class>. Get yourself settled in and contribute however you can - there's much to do!\n\nMe? Yes, I have a little something that needs doing, but I'm not sure you're up to the task.\n\nWe've had a contact embedded in Magisters' Terrace gathering intelligence for us. He's recently failed to report and I'm growing concerned.\n\nThe terrace is just up the rise to the east. The information he was collecting is vital to our mission.\n\nThink you can handle it, <race>?", progress = nil, completion = "...Come closer, &lt;race&gt;... Listen carefully to my words....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11490] = {title = "The Scryer's Scryer", objective = "Tyrith wants you to use the orb on the balcony in Magisters' Terrace.", description = "<Tyrith winces in pain as he speaks.>\n\nGo to the terrace... use the orb.\n\n...They're...feeding the sunwell....\n\n <Tyrith gasps for breath.>\n\nHurry... They must be stopped... before they can....\n\n<Tyrith dies.>", progress = "Go and peer into the orb, mortal.", completion = "I consider it to be no coincidence that our paths cross this day.\n\nI sense the tendrils of destiny....", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11492] = {title = "Hard to Kill", objective = "Kalecgos has asked you to defeat Kael'thas in Magisters' Terrace. You are to take Kael's head and report back to Larethor at the Shattered Sun Staging Area.", description = "Welcome to the Sunwell, mortals. Your arrival is indeed timely.\n\nAs you've now witnessed, the Legion forces work tirelessly, manipulating the Sunwell's power to achieve their malevolent ends.\n\nKael'thas has risen from the ashes of defeat and once more leads them in their efforts. Find him, mortals. He must again be stopped.\n\nOther, equally urgent matters require my immediate attention. I shall leave Kael's fate to you. Do not fail.\n\nWith luck, we shall speak again.", progress = "Well, <class>, I must admit, I wasn't sure I'd see you again.\n\nWhat news do you bring?", completion = "&lt;Larethor listens intently as you explain your deeds in Magisters' Terrace.&gt;\n\nTyrith will be missed - good man, that one. Thanks to you though, his death wasn't in vain.\n\nI've underestimated you, &lt;race&gt;. Please, accept this on behalf of the Sunwell Offensive - a gift worthy of a hero such as yourself.", rewards = "You will be able to choose one of these rewards:\n\nBright Crimson SpinelRuned Crimson SpinelTeardrop Crimson Spinel\n\nYou will also learn:\n\nHeroic Countenance\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11496] = {title = "The Sanctum Wards", objective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the Sun's Reach Sanctum to the east.", description = "Our first priority is to capture the Sun's Reach Sanctum.  Once we've secured it, we'll be able to use its energy to open a portal from Shattrath.\n\nThe sanctum is overrun with the Wretched - former blood elves who've devolved into mindless husks of their former selves.  Its defenses would've normally prevented this intrusion, but the Wretched have stolen the power sources from the protective wards.\n\nHunt down the Wretched and get the mana remnants they carry.  Use them to energize the sanctum wards.", progress = "Have you reactivated the crystal wards, <name>?", completion = "Good work, &lt;name&gt;.  The wards are slowly regaining their power.  The sanctum will be ours in no time!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11497] = {title = "Learning to Fly", objective = "Speak with Ilsa Blusterbrew at Wildhammer Stronghold in Shadowmoon Valley.", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Wildhammer Stronghold in the southwest corner of Shadowmoon Valley. When you get there, speak with Ilsa Blusterbrew about some flight instruction. Mind you, her training's not cheap. But, I think that you'll find it worth your while.", progress = nil, completion = "So, me boyo, Nutral, sent ya along did he?  Good man... I'll need ta remember ta send him along a pint fer all o' the business he's sendin' me way.\n\nIf it's the learnin' o' how ta fly right and proper yer after, ye've come ta the right place. No one flies finer than us Wildhammer and those we train. Fer a fee, and not a small one mind ya, I'll teach ya how ta soar through the skies!\n\nAnd when yer done, don't forget ta talk ta Brunn over there about buying one o' these gryphon beauties!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11498] = {title = "Learning to Fly", objective = "Speak with Olrokk at Shadowmoon Village in Shadowmoon Valley.", description = "Though it may end up hurting my business in the long run, you look the sort that dreams of flying <his/her> own mount through the skies, rather than being flown from place to place.\n\nI understand the feeling completely.\n\nYou, my friend, need to head to Shadowmoon Village in the northwest corner of Shadowmoon Valley. When you get there, speak with Olrokk about some flight instruction. Mind you, his training's not cheap. But, I think that you'll find it worth your while.", progress = nil, completion = "Blood and thunder, Nutral sent me another ground grunt! Good man... for a draenei.\n\n&lt;Olrokk spits on the ground near your feet.&gt;\n\nYou've come to the right place if you want to learn how to ride your own mount through the skies. In return for a big sack of gold, I'll teach you what you need to know and not fall dishonorably to your death.\n\nAnd when you're done, don't forget to talk to Dama Wildmane over there about buying one of the windriders from our stable!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11499] = {title = "Wanted: The Signet Ring of Prince Kael'thas", objective = "Wind Trader Zhareem has asked you to obtain The Signet Ring of Prince Kael'thas. Deliver it to him in Shattrath's Lower City to collect the reward.\n\nThis quest may only be completed at the Magisters' Terrace on Heroic difficulty.", description = "<class>, today I ask the impossible. Today, you must obtain the signet ring of Kael'thas Sunstrider, lord of the blood elves!\n\nIt's true, the rumors of his death within Tempest Keep were ill-founded. He has appeared once more, this time at the Magisters' Terrace on the Isle of Quel'Danas. What he is doing there is a tale for someone else to tell you. What I know is that I have innumerable collectors interested in his princely ring, and I mean to acquire it for them.\n\nOr rather, I mean for you to do so.", progress = "The Magisters' Terrace must be a very dangerous place indeed being so close to the Sunwell.\n\nI trust that you're not having second thoughts?", completion = "So, the blood elf prince is truly dead this time? A pity, I always thought he had class. To think that one so lofty could be brought down for such a paltry sum.\n\nBut as they say, business is business. Your reward is earned, adventurer.\n\nCome back tomorrow and I will have another request for you to fulfill.", rewards = "You will receive:\n\nBadge of Justice"}
MultiLanguageQuestData['en'][11500] = {title = "Wanted: Sisters of Torment", objective = "Nether-Stalker Mah'duun wants you to slay 4 Sisters of Torment. Return to him in Shattrath's Lower City once you have done so in order to collect the bounty.", description = "It has been whispered to Mah'duun that the sisters of torment are to be sent back to the hells from which they sprang.\n\nMah'duun knows that these demons can be found at the Magisters' Terrace on the Isle of Quel'Danas.\n\nYou will do this thing to earn the bounty, or you will not.", progress = nil, completion = "Who can say why the demonic sisters needed to be slain? Do you care?\n\nMah'duun thinks you care enough to collect the bounty, though.\n\nReturn again tomorrow and the winds will have whispered once more to Mah'duun.", rewards = "You will receive:\n\nEthereum Prison Key"}
MultiLanguageQuestData['en'][11502] = {title = "In Defense of Halaa", objective = "Defeat 10 enemy players in Halaa and return to Lakoor in Telaar.", description = "We are not a warlike race, <race>.  However when war comes to our lands, we do not run away from it.\n\nThe Alliance and the Horde wage war in the city of Halaa, to the northwest. We do not know what the blood elves are scheming, but any victory for the Horde would be disastrous.  The history between our people and the orcs is one of bloodshed and betrayal.\n\nGo and slay the enemy in Halaa and you will be rewarded in coin, honor and renown.", progress = "Is your task done, <name>?", completion = "I thank you, &lt;name&gt;.  Your efforts will not be ignored.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11503] = {title = "Enemies, Old and New", objective = "Defeat 10 enemy players in Halaa and return to Karrtog in Garadar.", description = "Our ancient enemy, the draenei, have returned with powerful allies.  They wage war in Halaa, southwest of here.\n\nWe cannot allow them a victory there as Garadar would be next without a doubt.\n\nGo and slay those who would aid our ancient enemy.", progress = nil, completion = "You bring great honor to our people.  You have our thanks.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11505] = {title = "Spirits of Auchindoun", objective = "Help the Alliance secure a tower in the Bone Wastes.", description = "Auchindoun's spirits have no stake in the conflict between the Alliance and the Horde, but incurring their favor will give our side an edge in the region.\n\nAncient custom directs the living to pay their respects at spirit towers in the Bone Wastes - though only at specific times of the day.  If you can help secure a tower during these times, you will have helped bring the spirits to our side.\n\nShould we succeed in gaining the spirits' favor, they will grant us a boon that will aid us in our endeavors.", progress = "The spirits are restless, <name>.  Have you accomplished your task?", completion = "The spirits are one step closer to resting in peace.  It is good to incur their favor, especially when waging war so close to their place of rest.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11506] = {title = "Spirits of Auchindoun", objective = "Help the Horde secure a Spirit Tower in the Bone Wastes.", description = "The draenei might be our enemies, but the spirits of their ancestors in Auchindoun are restless and have no allegiance.\n\nThe draenei's custom required them to pay their respects at spirit towers at various times during the day.  If you can help secure a tower during these times, you will help the spirits return to peace in Auchindoun.\n\nThe Alliance will try to capture the towers in order to secure the dead's favor.   We must ensure that our side succeeds instead.", progress = "The spirits of Auchindoun are all around us.  Will they grant us their boon?", completion = "The spirits are closer to finding peace and have bestowed their favor onto us.\n\nA humiliating blow to our enemy that their own ancestors would side against them, even if only temporarily.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11513] = {title = "Intercepting the Mana Cells", objective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", description = "I have devised a plan to acquire a power source strong enough for the creation of our portal.\n\nThe ethereal forces at Bash'ir Landing, atop the northwestern Blade's Edge Mountains, have been smuggling mana cells out of Tempest Keep and transporting them to the Sunwell for Kael'thas.\n\nThey have hidden the cells, but there is a way for you to find them; the ethereal carry phase devices that you can use to see the smuggled goods.\n\nJust beware the mana cells' phase wyrm guardians.", progress = "Did you acquire the mana cells?", completion = "These mana cells are vital to our efforts. We will have the portal to the Sunwell Isle created in no time!\n\nReturn tomorrow and I will send you out to acquire more of them from our Bash'ir 'friends'.", rewards = "You will receive:\n\nShattered Sun Supplies"}
MultiLanguageQuestData['en'][11514] = {title = "Maintaining the Sunwell Portal", objective = "Obtain 10 Smuggled Mana Cells and return them to Exarch Nasuun on the Terrace of Light in Shattrath City.", description = "We must maintain the energy to our portal or it will collapse. The mana cells that the ethereals at Bash'ir Landing have hidden will continue to serve our purposes. The landing sits atop the northwestern corner of the Blade's Edge Mountains, far to the north.\n\nRemember, acquire a phase device from one of the ethereals and then use it to locate the smuggled goods.\n\nJust be cautious of the phase wyrms that they use to guard the mana cells.", progress = "<name>, how fare your efforts to obtain mana cells for us this day?", completion = "These mana cells will continue to power the portal.\n\nReturn tomorrow and I will send you out to obtain more.", rewards = "You will receive:\n\nShattered Sun Supplies"}
MultiLanguageQuestData['en'][11515] = {title = "Blood for Blood", objective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to kill 4 Emaciated Felbloods by using the Fel Siphon on them. You will need Demonic Blood from nearby Wrath Heralds to power the Fel Siphon.", description = "When Kael's forces retreated through that portal, his most loyal lackeys were rewarded with an abominable gift.  They  stayed behind and gorged themselves on the blood of demons for days.\n\nThe blood has changed them, given them new powers.  It will also prove their undoing.\n\nObtain blood samples from other demons.  Use them to power this fel siphon and deprive these arrogant fools of their new powers.  Slay them in their weakened state and return to me.", progress = "These freaks are a disgrace to our race.  You must destroy them, <name>.", completion = "Fools.  They learned to drain fel energy but did not learn how to retain it.\n\nWe were lucky, &lt;name&gt;.  An experienced felblood would've surely been a formidable opponent.", rewards = "You will be able to choose one of these rewards:\n\nMark of SargerasSunfury Signet\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11516] = {title = "Blast the Gateway", objective = "Magistrix Seyla at the Throne of Kil'jaeden wants you to use the Sizzling Embers to summon a Living Flare and slay Incandescent Fel Sparks near it until it becomes an Unstable Living Flare. Return to the Legion Gateway with the Unstable Living Flare to destroy it.", description = "We have to shut down this gateway to stop Legion reinforcements to the Isle of Quel'Danas.\n\nTake these embers, they contain one of my creations: a living flare.  It is designed to act as a powerful destructive force - as long as it has been provided enough energy.\n\nFind the fel sparks that wander the area and slay them near the living flare.  The flare will grow in power each time, until it becomes unstable.\n\nOnce you've achieved this bring the flare to the gateway.  It will know what to do.", progress = "Is it done, <name>?  We must stop further Legion forces from reinforcing Kael'thas.", completion = "Excellent work, &lt;name&gt;.  The demons might repair the gateway in due time.  I suppose we'll just have to blow it up again.", rewards = "You will receive:\n\nShattered Sun Supplies"}
MultiLanguageQuestData['en'][11517] = {title = "Report to Nasuun", objective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", description = "I am most glad that you are here, <class>! Now that we have taken this sanctum, we must hurry to create a magical portal that will lead to here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to do just that. He asked me to send along any promising candidates who have what it takes to help with the portal's creation.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", progress = nil, completion = "Portanuus sent you? Good, we haven't any time to spare!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11520] = {title = "Discovering Your Roots", objective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", description = "Greetings, <race>.\n\nI'm afraid I have little to offer here until my reagents are stocked.\n\nOf the supplies I require, there is a special reagent, razorthorn root, that is particularly difficult to harvest.\n\nFortunately, I know a secret....\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.", progress = "Really, <name>, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "These should do nicely, &lt;class&gt;.\n\nI thank you for your assistance.", rewards = "You will receive:\n\nShattered Sun Supplies"}
MultiLanguageQuestData['en'][11521] = {title = "Rediscovering Your Roots", objective = "Mar'nah at Sun's Reach Harbor wants you to travel to Razorthorn Rise in Outlands, collect 5 Razorthorn Roots, and return to her.", description = "My stocks are presently sufficient, but I'll need plenty of razorthorn roots to keep up with the demand.\n\nCollecting the roots is difficult, but I know a special method of extraction.\n\nUsing the glands of the Razorthorn flayers, one can control a ravager there and use it to expose a root.\n\nTo find the roots, travel to Outlands and fly northeast from Shattrath until you reach Razorthorn Rise.\n\nReturn to me, <name>, once you have collected five of the roots.", progress = "Really, <name>, I'm far too busy for idle chatter.\n\nLet me know when you've gathered those roots.", completion = "Excellent work, &lt;name&gt;.\n\nThank you again for your help!", rewards = "You will receive:\n\nShattered Sun Supplies"}
MultiLanguageQuestData['en'][11523] = {title = "Arm the Wards!", objective = "Captain Theris Dawnhearth at the Shattered Sun Staging Area wants you to obtain 4 Mana Remnants from Wretched Fiends and Wretched Devourers and use them to energize one of the Crystal Wards surrounding the structures in Sun's Reach.", description = "We've succeeded in reactivating the crystal wards around the sanctum, but why stop there?  We'll build defenses around the other structures, but the Wretched are stubborn and continue to steal power from the crystal wards.\n\nHunt them down and get the mana remnants they carry.  Use the remnants to energize the sanctum wards; the safety of our operation depends on it.", progress = "Have you reactivated a crystal ward, <name>?", completion = "Good work, &lt;name&gt;.  The wards are slowly regaining their power.  Sun's Reach will be ours in no time!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11524] = {title = "Erratic Behavior", objective = "Vindicator Xayanna at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", description = "We lack the numbers to capture the Sanctum at Sun's Reach, but I've a plan that will tip the scales in our favor.\n\nThe loose energy from the Sunwell has caused the sentries that patrol this island to malfunction.  The crystal cores that control their behavior are damaged beyond repair.\n\nI've crafted new crystals that will bring them under our control; place them inside of the hulls of defeated sentries.  We will need all the help we can get.", progress = "Have you converted the sentries, <name>?", completion = "Good job, &lt;name&gt;.  The sanctum will be ours in no time!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11525] = {title = "Further Conversions", objective = "Vindicator Xayann at the Shattered Sun Staging Area wants you to place the Attuned Crystal Cores inside 5 defeated Erratic Sentries to turn them into friendly units.", description = "My plan to replace the damaged crystals on the erratic sentries has been a success.  We've managed to take the Sun's Reach Sanctum with their help.\n\nI've crafted new crystals that will bring more of them under our control; place them inside the hulls of defeated sentries.  We'll deploy them to other locations once they're converted.", progress = "Have you converted the sentries, <name>?", completion = "Excellent.  The converted sentries will help to secure our perimeter.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11526] = {title = "The Missing Magistrix", objective = "Use the Captured Legion Scroll near the portal at Dawning Square. Once you've gone through the portal, find Magistrix Seyla.", description = "We sent one of our operatives to investigate the fel portal in the middle of Dawning Square, south of here.  She never returned.\n\nTake this scroll we found on one of the enemy corpses.  We believe it will grant you access through the portal.  Once through, find Magistrix Seyla and aid her in any way you can.", progress = "Keep quiet, <class>.  The Legion's forces watch the south of the gate.", completion = "It's very sweet of Theris to worry about my hide, but we've got bigger problems here.  Much bigger.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11528] = {title = "A Winter Veil Gift", objective = "A small tag on this present reads:\n\nHappy holidays, <name>!You will receive:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nWinter Veil Gift"}
MultiLanguageQuestData['en'][11531] = {title = "Strange Engine Part", objective = "Take the Strange Engine Part to K. Lee Smallfry in Telredor.", description = "This strange engine part doesn't look like it fits in a steam pump, much less anything else you've seen.  Perhaps K. Lee Smallfry might know something about it.", progress = "Oh goodness!  What've you got there, <name>?", completion = "&lt;K. Lee looks at the engine part and then stares off into the distance for a moment.&gt;\n\nThis is somethin' real special.  Difficulty to say where it's from--like it just fell out of the sky.  I'm gonna hold on to this and pay you for your troubles.\n\nBetween you and me though, I think it's best if we didn't mention this to anyone.\n\n&lt;K. Lee puts on her most charming smile.&gt;", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11532] = {title = "Distraction at the Dead Scar", objective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", description = "The Legion will move against us as soon as their forces to the south are freed up.  The Scourge at the Dead Scar are keeping their forces occupied at the moment.  It won't last long, however.\n\nI want you to fly a dragonhawk over to the scar and put a dent in the demons' numbers with these arcane charges.\n\nIf all goes well, they won't even notice us taking the armory from Kael's lackeys.  Talk to Ayren, the dragonhawk master in the west part of the harbor, when you're ready to fly there.", progress = "Have you accomplished your mission, <name>?", completion = "You've got some real talent, kid.  Did you ever think of joining the Skyguard?\n\nI jest, &lt;name&gt;.  We need you here if we want to take the docks any time soon.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11533] = {title = "The Air Strikes Must Continue", objective = "Battlemage Arynna wants you to speak to Ayren Cloudbreaker when you're ready to fly over the Dead Scar. Once there, use the Arcane Charges to kill 2 Pit Overlords, 3 Eredar Sorcerers and 12 Wrath Enforcers.", description = "We've taken the armory from the enemy thanks to our aerial attacks against the Legion's forces in the Dead Scar.\n\nAs a matter of fact, it's gone so well that we're going to continue our air strikes against them.  Take these arcane charges and use them against their forces.\n\nTalk to Ayren Cloudbreaker at the Sun's Reach Harbor when you're ready for flight.", progress = "Have you accomplished your mission, <name>?", completion = "Any demons we kill today are demons that we do not have to fight tomorrow.  Keep it up.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11534] = {title = "Report to Nasuun", objective = "Tradesman Portanuus has asked you to speak with Exarch Nasuun on the Terrace of Light in Shattrath City.", description = "I am most glad that you are here, <class>! When we took this sanctum from the wretched, we hurried to create a magical portal that leads here from Shattrath City in the Outland.\n\nMy liege lord, Exarch Nasuun, is heading up the Offensive's efforts to maintain that portal. He asked me to send along any promising candidates who have what it takes to help with acquiring more energy to fuel it.\n\nPlease, travel to Shattrath City and speak with him inside A'dal's chamber on the Terrace of Light.", progress = nil, completion = "Portanuus sent you? Good, we haven't any time to spare!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11535] = {title = "Making Ready", objective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", description = "Supplies are inbound, or so I'm told.\n\nRegardless, we can ill afford to wait around hoping that help arrives before our offensive stalls. We must make the best of what we have.\n\nAs for me, I need ore to fashion an anvil so I can begin to upgrade our armor and weapons.\n\nThere are a group of naga on the coast to the east of here collecting ore and placing it in chests for shipment to the Legion.\n\nRelieving them of their ore will help our efforts in more ways than one....", progress = "Have you gathered the ore I need?", completion = "Excellent! We're getting closer....\n\nSoon I'll be able to craft an anvil, then the real work can begin.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11536] = {title = "Don't Stop Now....", objective = "Smith Hauthaa in Sun's Reach Armory wants you to kill Darkspine Myrmidon to the east and use their keys to steal three pieces of the ore from their chests.", description = "Now that we have an anvil, I can really get to work.\n\nNo matter how many supplies we receive, I'll always be able to put the Darkspine Iron Ore to good use. We'll need a constant supply of weapons and armor if we're to be successful here.\n\nThere are a group of naga on the coast to the east of here. They're collecting ore and placing it in chests for shipment to the Legion. Relieving them of their ore will help our efforts in more ways than one....", progress = "Have you gathered the ore I asked for?", completion = "Excellent! This will help me keep our soldiers in weapons and armor.\n\nYour help is truly making a difference!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11537] = {title = "The Battle Must Go On", objective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", description = "We must continue to defeat and demoralize the armies of the Legion.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", progress = "Have you succeeded, <name>?", completion = "Your dedication is exemplary, &lt;name&gt;.  We will show the forces of the Burning Legion what we're capable of.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11538] = {title = "The Battle for the Sun's Reach Armory", objective = "Harbinger Inuuro wants you to slay 6 Burning Legion Demons and the Emissary of Hate in Dawning Square or the Sun's Reach Armory. Use the Shattered Sun Banner to impale the Emissary of Hate's corpse.", description = "The Burning Legion holds the Sun's Reach Armory, which is of tactical importance to our operation.  As long as their morale remains high we will not wrest the building from their control.\n\nThe emissaries of hate are Legion shocktroopers deployed to reinforce tactical Legion positions.  The enemy rallies around them for they fear them more than they fear us.\n\nToday we will change that.  Take this banner and slay the demons of the Legion.  When you meet the emissary, slay and impale him.", progress = "Have you done what I asked of you, <name>?", completion = "Your dedication is exemplary, &lt;name&gt;.  We will take the armory from the forces of the Legion in no time!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11539] = {title = "Taking the Harbor", objective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", description = "One of Kael's most elite forces, the Dawnblade army, has been stationed at the Sun's Reach Harbor and Dawnstar Village.\n\nThe harbor is of critical importance to our plans, so any Dawnblade casualties you inflict will be of tremendous help.  Kael'thas will rue the day that he turned his back on his people and sided with the Burning Legion.", progress = "Have you slain the Dawnblade scum, <name>?", completion = "Excellent work, &lt;class&gt;.  Kael's armies will falter and once we take the harbor we shall deliver the killing blow!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11540] = {title = "Crush the Dawnblade", objective = "Magister Ilastar at Sun's Reach Armory wants you to slay 6 Dawnblade Summoners, 6 Dawnblade Blood Knights and 3 Dawnblade Marksmen.", description = "We've driven the Dawnblade army out of the Sun's Reach Harbor.  Sun's Reach is ours in its entirety.  Yet somehow... I'm not entirely satisfied.\n\nI want you to go to Dawnstar Village, west of here, and slay any surviving Dawnblade combatants.  They sealed their fate when they followed Kael to this place.", progress = nil, completion = "What thoughts go through Prince Kael'thas Sunstrider's head when he hears of his armies' defeats?\n\nDoes he feel despair?  Helplessness?  Fear?\n\nI sure hope so.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11541] = {title = "Disrupt the Greengill Coast", objective = "Captain Valindria wants you to free 10 Greengill Slaves. Return to her onboard the Silvermoon's Pride at Sun's Reach Harbor once you have done so.", description = "The naga have taken the Greengill Coast to the southeast. Their females, the Darkspine sirens, are using magic to enslave the indigenous murlocs.\n\nIt's my responsibility to see to it that whatever the naga are up to over there is disrupted. That's where you come in.\n\n<class>, I want you to get the controlling orbs from the female naga and throw them near the Greengill slaves, breaking the orb and setting the murlocs free.\n\nMy guess is that the murlocs will be incensed and turn on their masters.", progress = "My scouts tell me that there hasn't yet been enough disruption of the naga today.", completion = "That's enough for today. Slow and steady is the key here. Too much disruption and they'd turn their attention directly upon us; something that we don't want.\n\nCome back again tomorrow and we'll work on it some more.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11542] = {title = "Intercept the Reinforcements", objective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", description = "We're making a push to solidify our control of Sun's Reach by capturing the harbor next.  Unfortunately a fleet of Dawnblade reservists is on its way to reinforce Kael's forces there.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.    You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", progress = "Have you accomplished your task, <name>?", completion = "Well done, &lt;name&gt;.  It should be a long time before the harbor receives any reinforcements.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11543] = {title = "Keeping the Enemy at Bay", objective = "Vindicator Kaalan at the Sun's Reach Armory wants you to speak to Ayren Cloudbreaker and fly over the Dawnblade reinforcement fleet. Use the Flaming Oil to set the ship sails on fire as you fly and once you land, slay 6 Dawnblade Reservists.", description = "We've managed to capture Sun's Reach in its entirety.  Unfortunately a fleet of Dawnblade reservists is on its way to take back the harbor.\n\nTake this oil and secure a dragonhawk from Ayren Cloudbreaker.  You should be able to fly within reach of the ships' sails; once you're close enough, set them on fire.\n\nLand in one of the ships and attack the reservists.  With their ship sails on fire they won't be able to mount much of a defense.", progress = "Have you accomplished your task, <name>?", completion = "Well done, &lt;name&gt;.  It should be a long time before the harbor receives any reinforcements.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11544] = {title = "Ata'mal Armaments", objective = "Smith Hauthaa needs you to produce 5 Cleansed Ata'mal Metal. Do so by breaking down Ata'mal Armaments on her anvil at the Sun's Reach Armory on the Isle of Quel'Danas.", description = "The Ata'mal Terrace in eastern Shadowmoon Valley is holy to the draenei, but is now overrun by fel orcs. They have dug up the special ore from that place and created corrupted weapons and armor.\n\nI need the armaments to form an alloy with the naga ore. Our anchorites have blessed my anvil with the ability to cleanse them.\n\nRetrieve the armaments from the Shadowmoon chosen, slayers and darkweavers. Return them here, breaking down and purifying them upon my anvil, and then hand me the cleansed results.", progress = "I need all of the cleansed Ata'mal metal that I can get my hands on, <class>.", completion = "Thank you, my friend. Now I will be able to fashion more of the special alloy that is going into the creation of our forces' weapons and armor.\n\nAnd, I have some leftover extract from the process, which you'll likely find handy for use on your weapons. Please, take your pick of whichever will serve your purposes.\n\nReturn to me again on the morrow. No doubt I will need more armaments.", rewards = "You will be able to choose one of these rewards:\n\nBlessed Weapon CoatingRighteous Weapon Coating\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][11545] = {title = "A Charitable Donation", objective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", description = "We've taken Sun's Reach from the enemy and our final victory is at hand.  The cost was high and many brave combatants gave their lives so we could achieve this.\n\nIt is my goal to ensure that those who perished in combat are not forgotten.  I ask that you take a moment to consider making a donation towards a memorial fund.  Any leftover gold will go to the widows and orphans of the fallen.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, &lt;name&gt;.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", rewards = nil}
MultiLanguageQuestData['en'][11546] = {title = "Open for Business", objective = "Mar'nah at the Sun's Reach Harbor wants you to gather 5 Bloodberries from the bushes found on Quel'Danas.", description = "Welcome, <name>.\n\nThere are a number of ways I can assist you in your efforts here.\n\nFor example, I've recently discovered a recipe for a unique elixir.\n\nThe bloodberry grows wild in many regions of Azeroth and has long been considered nothing more than a nuisance. I've learned though, that when exposed to the Sunwell's power this plant takes on special properties that can be distilled and imbibed to magnify one's abilites.\n\nBring me a sample from the nearby bushes and I'll show you what I mean.", progress = "Have you gathered those berries yet?", completion = "Excellent, &lt;name&gt;.\n\nI hope this will aid you in your efforts here.", rewards = "You will receive:\n\nBloodberry Elixir"}
MultiLanguageQuestData['en'][11547] = {title = "Know Your Ley Lines", objective = "Astromancer Darnarian in the Sun's Reach Sanctum wants you to use the Astromancer's Crystal at the Bloodcrystal, the Dawning Square portal, and the naga shrine at Greengill Coast.", description = "Freeloaders!\n\nYou all want instant gratification - never giving thought to the effort required to create even the simplest of portals.\n\nPerhaps a little education will instill a bit of gratitude for my ceaseless efforts.\n\nTake this crystal. Attune it to the Bloodcrystal to the west, at the Dawning Square portal just south of here, and at the naga shrine at Greengill Coast to the southeast.\n\nPerhaps then you'll appreciate your precious translocations....", progress = "Have you attuned the crystal yet, <class>?", completion = "Yes, yes. Let's have a look now, shall we?\n\nThings seem to be in order. Very well. Here is your translocator.\n\nIf any of your readings are faulty, there's no telling where you'll end up, and mind you, you'll only have yourself to blame.", rewards = "You will receive:\n\nDarnarian's Scroll of Teleportation"}
MultiLanguageQuestData['en'][11548] = {title = "Your Continued Support", objective = "Anchorite Ayuri at Sun's Reach in Sunwell Isle wants you to donate 10 gold.", description = "We've built a memorial to honor those slain in battle.  It's but a small consolation to the families that lost their loved ones.\n\nI am taking up a collection to aid the orphans and spouses of our war heroes.  If you can spare a small donation it would go a long way.", progress = "Do you wish to make a donation?", completion = "You are a virtuous soul, &lt;name&gt;.  It is easy to forget the fallen amidst the turmoil of war and the euphoria of victory.  The friends and families of the dead thank you.", rewards = nil}
MultiLanguageQuestData['en'][11549] = {title = "A Magnanimous Benefactor", objective = "Anchorite Kairthos wants you to donate 1000 gold to aid in Anchorite Ayuri's efforts. You will be known as <name> of the Shattered Sun if you complete this quest.", description = "You've done so much for us, <name>.  We greatly appreciate your assistance.\n\nYou might have noticed Anchorite Ayuri's efforts outside.  She has a big heart and is very convincing, but the donations do not quite add up to what she had expected.\n\nIf you were to make a large contribution to her cause, I will make sure that word of your deeds in this war spreads far and wide.  What do you say?", progress = "Are you ready to make the contribution?", completion = "You truly are a generous person and a worthy ally.  From now on you shall be known as &lt;name&gt; of the Shattered Sun and all who fought here will know of your deeds!", rewards = nil}
MultiLanguageQuestData['en'][11550] = {title = "Enter, the Deceiver...", objective = "Report to Archmage Ne'thul on the Isle of Quel'Danas, north of Quel'Thalas.\n\nFlight masters in Ironforge and Silvermoon City will get you to your destination.", description = "Despite our best efforts, Kael'thas's sinister plans have been carried out. The Sunwell has been re-ignited in preparation for the Deceiver's arrival.\n\nThe object that stands before me and below A'dal is a representation of the current status of the Sunwell's defenses. Mighty barriers have been raised, stymieing our attacks against the inner chambers. If ever there were a time that our world needed assistance, it would be now.\n\nReport to Archmage Ne'thul at the Isle of Quel'Danas, north of Quel'Thalas.", progress = nil, completion = "Kil'jaeden bears down upon this world with the full force of the Burning Legion. Should the summoning complete, our world will once more be flung into the throes of chaos. Your assistance on the Isle of Quel'Danas is critical to our success against the Burning Legion.\n\nOur mages are working on bringing down the barriers blocking access to the Sunwell. Do your part in battling the forces of the Legion by helping the Shattered Sun Offensive.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11551] = {title = "Agamath, the First Gate", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nCache of the Shattered Sun"}
MultiLanguageQuestData['en'][11554] = {title = "A Friend in the Frontlines", objective = "Your aid in the offensive has not gone unnoticed, <name>.  The combined forces of the Aldor and Scryers offer you their thanks.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nAldor Supplies PackageScryer Supplies Package"}
MultiLanguageQuestData['en'][11555] = {title = "Honored by Your Allies", objective = "You continue to prove yourself in this most important battle, <name>.  Please accept this as a token of our continued gratitude.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nAldor Supplies PackageScryer Supplies Package"}
MultiLanguageQuestData['en'][11556] = {title = "Revered in the Field of Battle", objective = "We couldn't have gotten where we are without you, <name>.  The combined might of the Aldor and Scryers is not enough to crush the Legion and Kael.  We are thankful to have allies of your caliber among us.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nAldor Supplies PackageScryer Supplies Package"}
MultiLanguageQuestData['en'][11557] = {title = "Exalted Among All Combatants", objective = "You are one of our very best, <name>.  Your name will be known throughout our ranks for a long time to come.\n\nPlease accept this small gift on the behalf of our forces.", description = nil, progress = nil, completion = nil, rewards = "You will be able to choose one of these rewards:\n\nAldor Supplies PackageScryer Supplies Package"}
MultiLanguageQuestData['en'][11558] = {title = "Dangerous Love", objective = "Get a Guardian's Moldy Card and bring it to Fenstad Argyle in the Undercity.", description = "There's something unnatural about this epidemic of love. It's disgusting, and as it lowers our defenses, it could be a threat to the all of us.\n\nIt's bad enough that so many of our people are caught up in this ridiculous behavior. But I think that it has spread even to our guardians, who should be immune to such things.\n\nFind one of our guardians and see if they've been caught up in this foolishness.", progress = "Was I right to worry? Have our idiot guardians been overcome?", completion = "So it is true. This is unbelievable. How could this have happened? Let me think for a moment. There must be a reason behind this.", rewards = nil}
MultiLanguageQuestData['en'][11580] = {title = "Desecrate this Fire!", objective = "Desecrate the Horde's Silverpine bonfire!", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nStamp Out Bonfire\n\nYou will receive:\n\nBurning Blossom"}
MultiLanguageQuestData['en'][11581] = {title = "Desecrate this Fire!", objective = "Desecrate the Alliance's Westfall bonfire!", description = nil, progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\nStamp Out Bonfire\n\nYou will receive:\n\nBurning Blossom"}
MultiLanguageQuestData['en'][11583] = {title = "Honor the Flame", objective = "Honor the Westfall flame.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBurning Blossom"}
MultiLanguageQuestData['en'][11584] = {title = "Honor the Flame", objective = "Honor the Silverpine Forest flame.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nBurning Blossom"}
MultiLanguageQuestData['en'][11657] = {title = "Torch Catching", objective = "Catch 4 torches in a row, then speak with the Master Fire Eater.", description = "Now that you can throw a torch, let's see if you can catch one!\n\nTake this stack of unlit torches.  Go to the bonfire and throw a torch high into the air.  Catch it before it hits the ground... then throw it back up!  Catch four in a row, then come back to me.\n\nCareful! They're dangerous if they hit the ground!  And don't miss any catches!  If you do then you'll have to go back to the bonfire and start over.  Good luck!", progress = "Torch catching is a lot of fun, don't you think?  But have care!  You don't want to get singed!", completion = "Did you get burned?  If you did, then maybe you'll think twice before playing with fire...\n\nJust kidding!  Well done!  It's official.  You're a bona fide fire juggler.  Now get out there and have some fun!", rewards = "You will receive:\n\nJuggling TorchBurning Blossom"}
MultiLanguageQuestData['en'][11665] = {title = "Crocolisks in the City", objective = "Bring a Baby Crocolisk to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", description = "Hello <lad/lass>.  I'm glad you've stopped by to talk to this old man--there's trouble back home.\n\nA traveling merchant recently sold a batch of baby crocolisks to some gullible children.  Crocolisks are wild beasts, and many have escaped and now lurk in city waterways.\n\nGrab your strongest fishing pole and drop a line in Stormwind or Orgrimmar and bring one of the little devils back to me.  I'm anxious to see one.", progress = "Catch any crocs in the sewers yet?", completion = "What a mean little creature!  I'm sure the Rokk will make something tasty with him.\n\nI'm just kidding, of course.\n\n&lt;Old Man Barlo winks slyly.&gt;", rewards = "You will receive:\n\nBag of Fishing Treasures"}
MultiLanguageQuestData['en'][11666] = {title = "Bait Bandits", objective = "Bring a Blackfin Darter to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", description = "You probably know all about the golden darter--they're fairly common in the rivers of Terokkar Forest and a delicacy for priests.  But here's one you haven't heard of: the blackfin darter.\n\nThe fish is notoriously crafty and difficult to catch.  You have to pull your line at the last possible second, because they nibble at the bait before they take it.\n\nDrop your line in the rivers of Terokkar and bring me a blackfin darter.  Avoid the lakes, as the blackfin only thrive in moving water.", progress = "How's the fishing today, lad?", completion = "Well look at that... you caught a big one!  This old man is eating in style tonight.", rewards = "You will receive:\n\nBag of Fishing Treasures"}
MultiLanguageQuestData['en'][11667] = {title = "The One That Got Away", objective = "Catch the World's Largest Mudfish and bring it to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", description = "Figluster's mudfish is a surprisingly quick bottom feeder found in the waters of Nagrand.  They grow their entire lives and are well known as fighters.\n\nYears ago, I caught what I'm certain was the world's biggest mudfish... until it snapped my line and escaped.\n\nA fisherman of your caliber doesn't need to be told what to do--your destiny awaits in the lakes of Nagrand.", progress = "Tell me you caught him.  Please tell me you caught that son of a carp.", completion = "There he is!  I'd know that scar anywhere.\n\nTo be completely honest, I thought he'd be... bigger.  Well, I suppose I'll let him go and try again another day.", rewards = "You will receive:\n\nBag of Fishing Treasures"}
MultiLanguageQuestData['en'][11668] = {title = "Shrimpin' Ain't Easy", objective = "Bring 10 Giant Freshwater Shrimp to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", description = "There's a lot of big fish in the Zangarmarsh lakes.  Ever wonder what they eat?\n\nShrimp.  Giant freshwater shrimp.  The Rokk tells me the dishes you can make with shrimp are nearly endless.\n\nBut shrimp are too small to catch with a fishing line.  So here's the trick: cut open the bloated barbed gill trout and you'll find a shrimp or two if you're lucky.", progress = "What's the catch of the day, lad?", completion = "You are skilled with both the hook and knife.  Hand those sweet tidbits over, and I'll let you have a taste.", rewards = "You will receive:\n\nBag of Fishing Treasures"}
MultiLanguageQuestData['en'][11669] = {title = "Felblood Fillet", objective = "Bring a Monstrous Felblood Snapper to Old Man Barlo. You can find him fishing northeast of Shattrath City by Silmyr Lake.", description = "This old man is going hunting soon.  I'm gonna take down a mammoth shark off the coast of Azshara.\n\nThe thing is, I need a toxin that'll stay on a spear tip while it's underwater.  To make that kind of stuff, I need the glands from a poisonous fish: the felblood snapper.\n\nSuch a vile fish only thrives in the waters of Hellfire Peninsula and Shadowmoon Valley.  Bring me back a whopper and I'll be a happy old man.", progress = "The felblood is a marvel of evolution.  It can survive in any water and even lava, and fishermen are its only natural predator.\n\nAny luck with your prey?", completion = "That is the biggest, ugliest fish I've seen.  I can't even imagine what you used for bait.\n\nJust set the beast on the ground, and I'll deal with it once I'm sure it's dead.", rewards = "You will receive:\n\nBag of Fishing Treasures"}
MultiLanguageQuestData['en'][11691] = {title = "Summon Ahune", objective = "Bring the Earthen Ring Magma Totem to the Ice Stone.", description = "I and my Shamans have gathered our powers for the coming battle with the Lord of Frost.  <name>, you will be the fist of the Earthmother.\n\nTake this magma totem.  Use it against the Ice Stone, to the northeast.  Ahune is channeling his power through this stone; it is our hope that the totem will disrupt him and cut off his link to the elemental planes.\n\nIf fortune is with us, then, perhaps, we can defeat him.\n\nPrepare yourself, <name>.  If Ahune comes to face us, then his fury will be great.", progress = "This shard of ice echoes the deep, cracking rumble of invading glaciers.  Its cold turns your thoughts to a lifeless, endless winter.", completion = "The magma totem bursts into three separate flames as it is brought near the ice stone.  The stone shimmers, then is gone...", rewards = "The following spell will be cast on you:\n\nAhune - Summoning Rhyme Aura\n\nYou will receive:\n\n"}
MultiLanguageQuestData['en'][11696] = {title = "Ahune is Here!", objective = "Find Luma Skymother in the Slave Pens.", description = "<name>, your presence is a blessing.  Ahune lies within these caverns, gathering strength for his assault.  Earthen Ring forces were sent ahead, but they alone cannot defeat him.\n\nExplore, <name>.  Find our Earthen Ring Shamans and speak with their leader, Luma Skymother.  Perhaps, with your added strength, we can beat Ahune before it's too late.", progress = nil, completion = "The cold of Ahune spreads through these caverns, &lt;name&gt;; a seed of the frigid death that awaits us if he gains his full strength.  I thank the Earthmother for sending you.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][11731] = {title = "Torch Tossing", objective = "Win the torch tossing game, then speak with the Master Fire Eater.", description = "So you want to be a fire juggler?  Do you have what it takes?  The dexterity?  The reflexes?  ...the courage?  If you think so, then let's give you a little practice!\n\nTake these torches and run near the bonfire.  You'll see  braziers with markers flashing above them.  Toss a torch at a marked brazier.  Be quick! Do it before the mark fades if you want credit for the toss!\n\nHit enough marked braziers before the time limit, then come back here... for your next lession.", progress = "Quick!  There's no time to waste!", completion = "Well done!  You'll be a fire juggler faster than the fuse on a ground flower!  Now gird yourself!  The next test is when things really heat up...", rewards = "You will receive:\n\nBurning Blossom"}
