MultiLanguageQuestData['en'][12420] = {title = "Brew of the Month Club", objective = "Bring the \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", description = "Membership has its privileges.  Being part of the \"Brew of the Month\" club means knowing where to get the latest and greatest brew.\n\nBring your \"Brew of the Month\" club membership form to Larkin Thunderbrew in the Stonefire Tavern in Ironforge.", progress = "Do you have your membership forms filled out?", completion = "Your paperwork looks to be in order.  Welcome to the club, &lt;name&gt;!\n\nYou can expect to get our mail at the start of every month.  If you like what you got, stop by and we can sell you some more.  This is the club that keeps on giving.", rewards = nil}
MultiLanguageQuestData['en'][12421] = {title = "Brew of the Month Club", objective = "Bring the \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.", description = "There is strength in numbers, <name>.  Being part of the \"Brew of the Month\" club means knowing you and your brethren will always have access to the best brew.\n\nBring your \"Brew of the Month\" club membership form to Ray'ma in the Darkbriar Lodge in Orgrimmar's Valley of Spirits.", progress = "Do ya have your membership forms filled out?", completion = "So you be joinin' our ranks, &lt;name&gt;?  We treat ya nice here.  You only get the best when you part of dis club!\n\nWe be sendin' out brew to you at da start of every month.  If you like what you got, and you be wantin' more, head back over here.  We make sure you get more of da brew you like.", rewards = nil}
MultiLanguageQuestData['en'][12479] = {title = "Wrath of the Lich King: Onwards to Northrend!", objective = "Speak to the Alliance Recruiter inside Valiance Keep in Borean Tundra or the one at Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Alliance recruiter in Valiance Keep in Borean Tundra or you can go to Valgarde in Howling Fjord.", progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][12480] = {title = "Wrath of the Lich King: Onwards to Northrend!", objective = "Speak to the Horde Recruiter inside Warsong Hold in Borean Tundra or Vengeance Landing in Howling Fjord.Welcome to the Wrath of the Lich King Friends and Family Alpha. Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = "Welcome to the Wrath of the Lich King Friends and Family Alpha.  Use the portals next to me to begin your journey into Northrend.\n\nYou can choose to report to the Horde recruiter in Warsong Hold in Borean Tundra or you can go to Vengeance Landing in Howling Fjord.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][12491] = {title = "Direbrew's Dire Brew", objective = "Give Direbrew's Dire Brew to Ipfelkofer Ironkeg at the Brewfest camp near Ironforge.", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", progress = "<name>, your face has a grim set to it.  Do you have dire news?", completion = "This is the Coren Direbrew's drink?  The brew he wanted more than anything to submit at Brewfest?  Well, officially we can't recognize this submission, but out of respect for a fallen brewer, perhaps I'll have a taste...", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][12492] = {title = "Direbrew's Dire Brew", objective = "Give Direbrew's Dire Brew to Tapper Swindlekeg at the Brewfest camp near Orgrimmar.", description = "Coren Direbrew's corpse clutched this small cask tightly to its gut.  This must be his infamous Dire Brew!", progress = "Hey <name>, your face is all smudged!  Have you been to Blackrock Depths?", completion = "Ah, so Direbrew finally submitted his brew.  What a pity he had to die to do it...\n\nOh, well.  Bottoms up, eh?", rewards = "You will receive:\n\nBrewfest Prize Token"}
MultiLanguageQuestData['en'][12513] = {title = "Nice Hat...", objective = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! So... it WAS you. I'd thought so. The old scars ached when you drew near, but... so young! You've not changed at all!\n\nWell... so now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've more than earned it.", rewards = "You will receive:\n\nHaliscan Brimmed Hat"}
MultiLanguageQuestData['en'][12515] = {title = "Nice Hat...", objective = "Don Carlos has inadvertently challenged you to defeat his younger self in Old Hillsbrad. Afterwards, bring Don Carlos' Hat to him in Tanaris as proof.", description = "My hat? Yes, it's an unusual style, I know, from far away... few tailors here know how to make them.\n\nWhen I was young and hot-blooded, I wore it as a standing challenge. Many came seeking to defeat me and win it for themselves... but no one ever did.\n\nAh, but those days are long past. I'm an old man, now: I drink, I fish, but I no longer duel.", progress = "I was unbeatable, in those days... proud, and rightly so. No challenger ever won this fine hat...", completion = "My... my hat! But... how did you...?\n\nWell... no matter. So, now you know my secret. I WAS beaten... once. Here: take this hat, in return for mine. You've earned it.", rewards = "You will receive:\n\nHaliscan Brimmed Hat"}
MultiLanguageQuestData['en'][12616] = {title = "Chamber of Secrets", objective = "The Argent Dawn Emissary wants you to search the chamber of Tenris Mirkblood within the Servant's Quarters of Karazhan.", description = "Excellent, an experienced adventurer. Precisely what we need.\n\nThere has been talk from the Kirin Tor guarding Medivh's tower that something is amiss with Karazhan. There is a new power lurking within, one that answers neither to the Guardian's magic nor the Legion. From what they've scouted, it appears it is an elven prince called Tenris Mirkblood, and there is reason to believe he serves the Scourge.\n\nGo, my friend, investigate Mirkblood's chamber, and return with any information you might find.You will receive:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\nItem #40354"}
MultiLanguageQuestData['en'][12911] = {title = "Kill Credit Test", objective = "/wave at Kill Credit Test", description = "/wave at me and I'll assign 'kill credit to player' to you.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][13408] = {title = "Hellfire Fortifications", objective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, <name>, for you will no doubt clash with Horde forces eager to gain these same fortifications.", progress = "<name>, return to me when you have aided in the capture of each of the forts!", completion = "Well done, &lt;name&gt;.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", rewards = "You will be able to choose one of these rewards:\n\nItem #40476\n\nYou will also receive:\n\nMark of Honor Hold"}
MultiLanguageQuestData['en'][13409] = {title = "Hellfire Fortifications", objective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", progress = nil, completion = "Nice work, &lt;name&gt;.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", rewards = "You will be able to choose one of these rewards:\n\nItem #40477\n\nYou will also receive:\n\nMark of Thrallmar"}
MultiLanguageQuestData['en'][13410] = {title = "Hellfire Fortifications", objective = "Capture the Overlook, the Stadium and Broken Hill, then return to Warrant Officer Tracy Proudwell in Honor Hold in Hellfire Peninsula.", description = "The Hellfire Citadel wages constant battles with our forces.  We are holding our own so far, but we can't yet launch a real offensive against them.  To do that, we need forward staging areas.\n\nOur scouts identified three fortifications near Hellfire Citadel.  We want you to help secure these forts.  Capture each fort, and then report back to me.\n\nMay fortune shine upon you in the conflicts ahead, <name>, for you will no doubt clash with Horde forces eager to gain these same fortifications.", progress = nil, completion = "Well done, &lt;name&gt;.  Your actions in the field are instrumental in our battle for Hellfire Peninsula.", rewards = "You will receive:\n\nMark of Honor Hold"}
MultiLanguageQuestData['en'][13411] = {title = "Hellfire Fortifications", objective = "Capture the Overlook, the Stadium and Broken Hill, then return to Battlecryer Blackeye in Thrallmar.", description = "The fel orcs of Hellfire Citadel must be scoured from our birthland!  To attack them, we must first secure forward staging points near the Citadel.\n\nOur outrunners found three fortifications that will suit this purpose, but the Alliance has the same idea and even now sends forces to take them!\n\nWe want you to stop the Alliance and capture these forts.  Aid in the capture of each fort and then return to me.\n\nFor the Horde!", progress = nil, completion = "Nice work, &lt;name&gt;.  I could almost hear the battles waged at those forts.  I wish I was there to see them!", rewards = "You will receive:\n\nMark of Thrallmar"}
MultiLanguageQuestData['en'][13429] = {title = "A Distraction for Akama", objective = "Ensure that Akama and Maiev enter the Black Temple in Shadowmoon Valley after Xi'ri's forces create a distraction.", description = "<Xi'ri pulses with lights as the Aldor and Scryer forces around him respond to his orders.  Xi'ri's army is ready to push Illidan's forces back and create a distraction for Akama.  The naaru awaits your request to begin the attack.>", progress = "<Xi'ri acknowledges your presence.>", completion = "&lt;Xi'ri pulses with energy as you feel an object materialize in your hands.  It is the medallion you gave to A'dal on Akama's behalf, its power augmented by the naaru's magic.  The Sha'tar have entrusted you with the Medallion of Karabor, and with it access to the Black Temple.&gt;", rewards = "You will receive:\n\nMedallion of Karabor"}
MultiLanguageQuestData['en'][13430] = {title = "Trial of the Naaru: Magtheridon", objective = "A'dal in Shattrath City wants you to slay Magtheridon.", description = "Four trials you must pass before you are deemed worthy by the naaru.\n\nOnly one obstacle remains, mortal. Gather an army and travel to the lair of Magtheridon, deep inside Hellfire Citadel. Battle your way to the heart of the chamber and destroy the foul corrupter!", progress = nil, completion = "You have proven yourself as a being of great power. The naaru approve...", rewards = "You will receive:\n\nPhoenix-fire Band"}
MultiLanguageQuestData['en'][13431] = {title = "The Cudgel of Kar'desh", objective = "Skar'this the Heretic in the heroic Slave Pens of Coilfang Reservoir wants you to bring him the Earthen Signet and the Blazing Signet.", description = "Bring me the elemental signets that the cudgel requires!\n\nThe earthen signet is held by Gruul the Dragonkiller. Gruul can be found inside his lair in the Blade's Edge Mountains.\n\nThe second signet is the blazing heart of a creature known as Nightbane. This mythical beast is said to reside in the hallowed halls of the prophet, Medivh.\n\nMake haste!", progress = "With the cudgel reformed, I shall break free of my bonds and return to Serpentshrine to exact vengeance on Vashj and her minions!", completion = "At last!\n\nWith these bonds broken and the cudgel in my possession I shall send  the sea witch back to the icy depths...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][14352] = {title = "An Unholy Alliance", objective = "Take the Small Scroll to Bragor Bloodfist in the Undercity.", description = "My Lady,\n\nYou know very well what it is we are offering. The opportunity for you to take the Barrens and the lands beyond is a great one. We simply want your aid in return. By aid we mean nothing more than your giving us the freedom to take action in the area.\n\nPlease, allow us to discuss this further. We have great power and are willing to share with those wise enough to join us. I will remain outside Razorfen Downs for the time being.\n\nBest Regards,\nAmbassador Malcin", progress = "What do you want, <name>? This had better be important.", completion = "I've seen the insignia on this scroll before during my time in Northrend. You say this was on that crone who leads the pigs in Razorfen Kraul?\n\nI'll be damned if I'm going to let the Scourge get a foothold here. The one who wrote this - this Malcin - is one of the Lich King's servants, obviously, and that makes him a target. Your target.\n\nThey're not going to take Kalimdor.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][14353] = {title = "An Unholy Alliance", objective = "Bring Ambassador Malcin's Head to Bragor Bloodfist in the Undercity.", description = "Supposedly this Malcin is outside Razorfen Downs. There's no question - he has to die.\n\nMy contacts in Orgrimmar tell me their scouts have found signs of the Plague down there. The quilboar are showing signs of being plagued, too; they're much more powerful. Whatever the Scourge are doing down there needs to end. Now.\n\nFind this Malcin and kill him. Report back here when he's dead.", progress = "Did you find the Ambassador, <name>? Did you kill him?\n\nI will not have the Scourge gain a foothold in Kalimdor. We've fought too hard to allow them easy access to our cities.\n\nAt least their crone still numbers among the living. She might be stupid enough to allow the Scourge in her home, but she must have sense enough to know she'd lose everything if she took the 'power' they offer.", completion = "Good work, &lt;class&gt;!\n\nYou've done the Horde proud by stopping the Scourge from setting down roots on our soil. An act like that deserves a reward, and the Forsaken have enough lying around that I'm sure they can spare a few things.\n\nWe may not know everything they've done in the Downs, but we'll find out. They can't slink around in the dark forever.", rewards = "You will be able to choose one of these rewards:\n\nSkullbreakerNail SpitterZealot's Robe\n\nYou will also receive:\n\n"}
MultiLanguageQuestData['en'][14355] = {title = "Into The Scarlet Monastery", objective = "Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Bragor Bloodfist in the Undercity.", description = "One of my duties while I'm stationed here is to help the Forsaken take care of their borders, and that, <class>, is exactly what you're going to do for me.\n\nI might live and breathe, but the Scarlet Crusade will cut down my people as quickly as they will one of the undead. They're a problem here, a big one, and you're going to do something about it.\n\nGo to the Monastery and slay High Inquisitor Whitemane and her lieutenants.", progress = nil, completion = "I'm sure Sylvanas will be glad to have that problem taken care of, &lt;name&gt;. The task I gave you wasn't easy, but here you stand, victorious. That commands respect, and what you've done won't be forgotten.", rewards = "You will be able to choose one of these rewards:\n\nSword of OmenProphetic CaneDragon's Blood Necklace"}
MultiLanguageQuestData['en'][14356] = {title = "The Power to Destroy...", objective = "Bring the books Spells of Shadow and Incantations from the Nether to Bragor Bloodfist in Undercity.", description = "Listen up, <class>.\n\nYou may not know this, but Orgrimmar's got a problem. Deep in Ragefire Chasm, a sect of the Shadow Council called the Searing Blade performs their sinister work. They're mainly orcs, and I can't trust sensitive information in the hands of the grunts there. That's where you come in.\n\nThey should have two books in their possession. I want them kept out of the hands of the Searing Blade and the Forsaken alike. Bring them to me directly.", progress = "Did you secure the books? They need to be kept out of the wrong hands.", completion = "Good, &lt;class&gt;. You've done well. I'll keep these safe from prying eyes; the last thing we need is a strong Shadow Council rising up again.\n\nCheck back with me in the future; there's always something that needs doing around here, apparently, and I might need another able body.", rewards = "You will be able to choose one of these rewards:\n\nGhastly TrousersDredgemire LeggingsGargoyle Leggings"}
MultiLanguageQuestData['en'][24553] = {title = "The Purification of Quel'Delar", objective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to me and to the rest of my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. The blade will bond to you. When that happens, carry it to Caladis Brightspear at Quel'Delar's Rest.", progress = "What happened during your time in the Sunwell?", completion = "This is unbelievable, &lt;name&gt;. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", rewards = nil}
MultiLanguageQuestData['en'][24564] = {title = "The Purification of Quel'Delar", objective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", description = "The Sunwell and the end of Quel'Delar's exile await, <name>.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell. Immerse the reformed Quel'Delar in the Sunwell to complete the restoration. Afterward, show the blade to Myralion Sunblaze at Quel'Delar's Rest.", progress = "What happened inside the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", rewards = nil}
MultiLanguageQuestData['en'][24580] = {title = "Anub'Rekhan Must Die!", objective = "Kill Anub'Rekhan.\n\nThis quest can be completed with any difficulty or size raid.", description = "Anub'Rekhan, once-mighty Spider Lord of the nerubian empire, has been taken by the Lich King and corrupted into a state of undeath.\n\nNow a crypt lord, he sits in his parlor in the Arachnid Quarter of Naxxramas, spinning strategies for Kel'Thuzad.\n\nThe Council of Six has decreed that Anub'Rekhan must die!", progress = nil, completion = "Word of your success precedes you, &lt;class&gt;. Anub'Rekhan is no more. You did him a great service, &lt;name&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][24581] = {title = "Noth the Plaguebringer Must Die!", objective = "Kill Noth the Plaguebringer.\n\nThis quest can be completed with any difficulty or size raid.", description = "Noth the Plaguebringer, traitor and coward! Second only to the Lich King himself for the number of souls that have been Scourged!\n\nMake haste to Naxxramas. You will find him within the Plague Quarter hiding behind his undead minions.\n\nDestroy him! The Council of Six has decreed that Noth must die!", progress = nil, completion = "That's one less thorn in our side. With Noth destroyed, Scourge research into refining the means of creating the undead will grind to a halt.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][24582] = {title = "Instructor Razuvious Must Die!", objective = "Kill Instructor Razuvious.\n\nThis quest can be completed with any difficulty or size raid.", description = "Instructor Razuvious smugly struts about the Military Quarter of Naxxramas. It is said that only a death knight personally trained by him could possibly even withstand the prowess of his blade.\n\nYou and your group are going to prove everyone wrong.\n\nThe Council of Six has decreed that Razuvious must die!", progress = nil, completion = "Well done, &lt;class&gt;. The Scourge military command out of Naxxramas has been thrown into disarray by Razuvious's demise.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][24583] = {title = "Patchwerk Must Die!", objective = "Kill Patchwerk.\n\nThis quest can be completed with any difficulty or size raid.", description = "The so-called \"avatar of war\", Patchwerk is the ultimate abomination. It is also taking a heavy toll upon on our forces in the Dragonblight.\n\nI want you to assemble your companions and enter the Construct Quarter of Naxxramas. Disassemble the construct.\n\nThe Council of Six has decreed that Patchwerk must die!", progress = nil, completion = "Children everywhere will sleep easier knowing that Patchwerk is no more.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][24595] = {title = "The Purification of Quel'Delar", objective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", description = "I admit, I was skeptical that you had actually re-forged Quel'Delar and I did not expect Thalorien's spirit to reveal itself to you. You cannot understand what it means to my people that Quel'Delar has been recovered.\n\nAs promised, I will admit you to the Sunwell and you will find the leaders of Silvermoon within. Carry the sword to the chamber of the Sunwell and immerse it. Once the blade is restored, return with it to Caladis Brightspear at Quel'Delar's Rest.", progress = "Tell me of what happened in the Sunwell, <name>.", completion = "This is unbelievable, &lt;name&gt;. You've really done it! All of the quel'dorei have heard of Thalorien Dawnseeker and Quel'Delar, but no one ever thought the sword would be restored.", rewards = nil}
MultiLanguageQuestData['en'][24596] = {title = "The Purification of Quel'Delar", objective = "Immerse your Tainted Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", description = "The Sunwell and the end of Quel'Delar's exile await, <name>.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete the its restoration, then speak with Myralion Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What happened during your visit to the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", rewards = nil}
MultiLanguageQuestData['en'][24598] = {title = "The Purification of Quel'Delar", objective = "Immerse your Tempered Quel'Delar in the Sunwell. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", description = "The Sunwell and the end of Quel'Delar's exile await, <name>.\n\nYou will find Lor'themar Theron, the regent of Quel'Thalas, and Grand Magister Rommath standing within. Be wary of them and do not allow them to entrap you in their political scheming.\n\nInstead, remain focused on your task here. Immerse the reformed Quel'Delar in the Sunwell to complete its restoration, then show it to Myralio Sunblaze at Quel'Delar's Rest. Speak to a Warden of the Sunwell when you are ready to enter the Sunwell Plateau.", progress = "What news do you bring from the Sunwell?", completion = "Am I truly laying my eyes upon the weapon of Thalorien Dawnseeker? This is a wondrous day for the Sunreavers and for all sin'dorei!", rewards = nil}
MultiLanguageQuestData['en'][24797] = {title = "REUSE", objective = "Upon completion of this quest you will gain:\n\n", description = nil, progress = nil, completion = nil, rewards = nil}
MultiLanguageQuestData['en'][63448] = {title = "A Deluxe Delivery", objective = "Greetings <name>, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReawakened Phase-HunterDark PortalPath of Illidan"}
MultiLanguageQuestData['en'][63450] = {title = "A Deluxe Delivery", objective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have these rewards in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose any of these items, come back and I'll give you a replacement, no charge.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nReawakened Phase-HunterDark PortalPath of Illidan"}
MultiLanguageQuestData['en'][63767] = {title = "Imp in a Ball", objective = "Greetings <class>, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nImp in a Ball"}
MultiLanguageQuestData['en'][63768] = {title = "Imp in a Ball", objective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nImp in a Ball"}
MultiLanguageQuestData['en'][63770] = {title = "A Special Thanks", objective = "Greetings <name>,\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nNetherwhelp's Collar"}
MultiLanguageQuestData['en'][63865] = {title = "A Special Thanks", objective = "Greetings <name>,\n\nWe have a special gift of appreciation for being a passionate collector! We would like to present you with this small yet feisty friend.  May he lead you to new adventures through the Dark Portal and into Outland!", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nNetherwhelp's CollarLurky's Egg"}
MultiLanguageQuestData['en'][63866] = {title = "Claiming the Light", objective = "Use the Shimmering Vessel on M'uru to fill it and return to Knight-Lord Bloodvalor in Silvermoon City.", description = "Take this vessel, <name>. Invoking its magic will allow you to take this creature's power and claim it for yourself. With it, you will be able to restore your fallen comrade to life.\n\nThere are those who would say what we're doing is wrong, but much of what has befallen us is also wrong. Would they have us throw away such a gift?\n\nThey do not complain when our power is used to prevent the further destruction of Silvermoon. No, they object when they are safe from harm and indulging their magic addictions.", progress = "Have you spoken with Magister Astalor Bloodsworn?", completion = "Well done, &lt;name&gt;. The powers granted by the Light have never come 'naturally' to the Blood Knights, but we are not so weak-willed as to let nature dictate to us.\n\nOur mastery of the arcane has provided a path to help see us through these harsh times. Power no longer flows freely in these halls, but it is there for the tenacious and strong of will. Few have the stomach or the aptitude to master it these days, but I know you will not disappoint the order.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][63978] = {title = "Cloak and Daggers", objective = "Use Stealth to sneak around.", description = "As a Rogue, you specialize in striking from the shadows, dispatching foes with a variety of poisons and bleeding attacks. Use Stealth to sneak around and then speak with me when your ready for more training.You will receive:\n\nUpon completion of this quest you will gain:\n\n", progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64028] = {title = "A New Beginning", objective = "Meet with a <class> trainer in Stormwind.", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to the city of Stormwind, capital of the Alliance! \n\nMeet with a <class> trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", progress = nil, completion = "Ready for your training, &lt;race&gt;?", rewards = "You will receive:\n\nAzeroth Survival Kit"}
MultiLanguageQuestData['en'][64031] = {title = "Tools for Survival", objective = "Open the survival kit and equip a weapon.", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", progress = nil, completion = "You look prepared! Let us move onto your first lesson in combat training.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64034] = {title = "Combat Training", objective = "Train a spell by speaking to a <class> trainer.", description = "As you grow in power, so does your capabilities of being a skillful <class>.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Stormwind, Darnassus, or Ironforge.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, &lt;race&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64035] = {title = "Talented", objective = "Activate the Talents interface and allocate 5 Talent Points.", description = "Every <class> makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a <class> trainer to rework them.", progress = nil, completion = "You're ready for battle, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64037] = {title = "Eastern Plaguelands", objective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", description = "By the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to Lord Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn needs your help to win back the Eastern Plaguelands from the grasp of the scourge.\n\nTo reach the Eastern Plaguelands, speak to the Gryphon Master, Dungar Longdrink, and his gryphons can get you there faster than even the swiftest horse.\n\nFor the glory and honor of the Alliance!", progress = nil, completion = "Perhaps you can help, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64038] = {title = "The Dark Portal", objective = "Find Watch Commander Relthorn Netherwane at the Blasted Lands. He awaits your arrival before the Dark Portal.", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer.\n\nBy the order of Highlord Bolvar Fordragon, all able-bodied citizens of the Alliance are to report to the Blasted Lands. Speak to Dungar Longdrink, the Gryphon Master to arrange a flight.\n\nOnce at the Blasted Lands, report to Watch Commander Relthorn Netherwane. He awaits you before the Dark Portal...", progress = nil, completion = "Welcome to the nightmare!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64046] = {title = "A New Beginning", objective = "Meet with a <class> trainer in Orgrimmar.", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Orgrimmar, capital of the Horde!\n\nMeet with a <class> trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", progress = nil, completion = "Ready for your training, &lt;race&gt;?", rewards = "You will receive:\n\nAzeroth Survival Kit"}
MultiLanguageQuestData['en'][64047] = {title = "A New Beginning", objective = "Meet with a <class> trainer in Thunder Bluff.", description = "A letter magically appears in the lining of your armor. It reads:\n\n\"Welcome to Thunder Bluff, capital to the Tauren!\n\nMeet with a <class> trainer to begin your training. They will help prepare you for your journey across Azeroth and beyond.\"", progress = nil, completion = "Ready for your training?", rewards = "You will receive:\n\nAzeroth Survival Kit"}
MultiLanguageQuestData['en'][64048] = {title = "Tools for Survival", objective = "Open the survival kit and equip a weapon.", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", progress = "I've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", completion = "You look prepared! Let us move onto your first lesson in combat training.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64049] = {title = "Tools for Survival", objective = "Open the survival kit and equip a weapon.", description = "Before we begin, you need to be equipped with weapons and armor suited to your talents. The life of an adventurer is never dull, and you never know what will happen next!\n\nI've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", progress = "I've prepared a survival kit for your adventures. It contains additional weapons, armor, and rations. I trust that you will make use of it well.", completion = "You look prepared! Let us move onto your first lesson in combat training.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64050] = {title = "Combat Training", objective = "Train a spell by speaking to a <class> trainer.", description = "As you grow in power, so does your capabilities of being a skillful <class>.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Orgrimmar, Thunder Bluff, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, &lt;race&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64051] = {title = "Combat Training", objective = "Train a spell by speaking to a <class> trainer.", description = "As you grow in power, so does your capabilities of being a skillful <class>.\n\nYou can find trainers all around Azeroth, and in capital cities such as here in Thunder Bluff, Orgrimmar, or the Undercity.\n\nThere's a price to this knowledge, but I will reimburse you just this once. When you are ready, speak with me again to train your abilities.", progress = "When you are ready, speak with me again to train your abilities.", completion = "You look stronger already, &lt;race&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64052] = {title = "Talented", objective = "Activate the Talents interface and allocate 5 Talent Points.", description = "Every <class> makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a <class> trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're ready for battle, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64053] = {title = "Talented", objective = "Activate the Talents interface and allocate 5 Talent Points.", description = "Every <class> makes use of different abilities, talents and capabilities. We differ from each other in that we have unique interests and inclinations.\n\nWhen you level up in power, you can enhance and specialize your abilities through your talents, without the instruction of a trainer.\n\nIf you change your mind on these talents, you can speak with a <class> trainer to rework them.", progress = "Activate the Talents interface and allocate 5 Talent Points.", completion = "You're almost ready for battle, &lt;name&gt;!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64054] = {title = "Unused", objective = "You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64062] = {title = "Unused", objective = "You will receive:\n\nUpon completion of this quest you will gain:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64063] = {title = "The Dark Portal", objective = "Find Watch Warlord Dar'toon at the Blasted Lands. He awaits your arrival before the Dark Portal.", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer. \n\nAll able bodied members of the Horde are hereby ordered to report to the Blasted Lands. Visit the Zeppelin Master outside of the city gates of Orgrimmar and ride to Grom'gol Base Camp. From there, speak to Thysta to arrange a flight to Stonard.\n\nReport to Warlord Dar'toon at once. He awaits you before the Dark Portal...", progress = nil, completion = "Welcome to the nightmare!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64064] = {title = "Eastern Plaguelands", objective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", description = "All able bodied members of the Horde are hereby ordered to report to Leonid Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nVisit Zeppelin Master Frezza outside the city's main gate and travel to the Undercity. From there, make your way to Light's Hope Chapel in the Eastern Plaguelands.\n\nDestiny calls!", progress = nil, completion = "Perhaps you can help, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64128] = {title = "Eastern Plaguelands", objective = "Travel to the Eastern Plaguelands and find Leonid Barthalomew. He awaits your arrival at Light's Hope Chapel.", description = "All able bodied members of the Horde are hereby ordered to report to Leonid Barthalomew at Light's Hope Chapel.\n\nThe Argent Dawn has reinforced its presence in the Plaguelands and it needs your help to consolidate its victories.\n\nSpeak to Tal, the Wind Rider Master to fly to Orgrimmar. From there, visit Zeppelin Master Frezza outside the city's main gate and travel to the Undercity. It is there where you can make your way to the Eastern Plaguelands.\n\nDestiny calls!", progress = nil, completion = "Perhaps you can help, &lt;class&gt;.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64139] = {title = "A Summons from Lady Liadrin", objective = "Speak with Lady Liadrin in Silvermoon City.", description = "Your dedication to our order and advancement through the ranks has not gone unnoticed. In fact, Lady Liadrin, leader of the Blood Knights, has asked to speak with you.\n\nThis is a rare honor, <name>. Normally, Lady Liadrin leaves the management of the order's rank-and-file to me, but she has taken a personal interest in you. Do not tarry, <name>.", progress = nil, completion = "We will discuss the purpose for your visit soon. First, let me say that I am indeed impressed by your service and your skill in wielding the Light.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64140] = {title = "The Master's Path", objective = "Speak with Lady Liadrin again to accept her offer of sponsorship.", description = "Within the ranks of my order, there exists an inner circle of elite knights. Members of the circle represent the most dedicated, skilled, and trustworthy of all Blood Knights and are handpicked by the leadership. Most simply know the masters by their thalassian charger mounts.\n\nEach candidate for membership must have a sponsor within the circle and must demonstrate their dedication to the order's central tenets.\n\nI have chosen to sponsor you for standing as a Blood Knight master, if this is your wish.", progress = nil, completion = "That you have chosen to accept my offer speaks well of you, &lt;name&gt;. I wish you luck in the tasks I am about to set for you, but I'm certain you'll prove yourself more than capable.\n\nI will present the tasks in order from easiest to most difficult and we may begin when you are prepared.", rewards = nil}
MultiLanguageQuestData['en'][64141] = {title = "A Gesture of Commitment", objective = "Bring 40 Runecloth, 6 Arcanite Bars, 10 Sungrass, 5 Dark Runes, and 150 Gold to Lady Liadrin in Silvermoon City.", description = "A Blood Knight's loyalty does not stop at the end of <his/her> blade, <name>. The order asks more of its members than mere drilling and combat. A true knight contributes to all of the order's activities, even the ones that may not seem glorious on the surface.\n\nThis first task is neither combat intensive, nor glorious, but without such contributions, the order would fall apart. I will give you a list of items Magister Astalor Bloodsworn's men require to keep us supplied with Light energy for our magics.", progress = "Have you returned with the materials Magister Astalor requires?", completion = "Excellent. It appears everything is here.\n\nDon't worry, your next task will include plenty of opportunities to wield your weapon again, I promise.\n\nI'll have an initiate bring it all to Magister Astalor. There's no need to send you on such a trivial errand when there are more important things to be done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64142] = {title = "A Demonstration of Loyalty", objective = "Lady Liadrin in Silvermoon City wants you to destroy 3 Scourge Meat Wagons and kill 15 Scourge Siege Engineers.", description = "We Blood Knights are bound to defend Quel'Thalas, <name>. This is a central part of your training. Our enemies are fierce and unrelenting. Silvermoon and its people remain free by our efforts and the support of our allies.\n\nI have received some disturbing reports of a renewed Scourge presence to the southeast of our border with the Eastern Plaguelands. A company of Scourge siege engineers and their equipment appear to be staging for an attack on the Ghostlands. They must not be permitted to succeed.", progress = "Welcome back, <name>. Have you beaten back the Scourge and their meatwagons?", completion = "You have done well in demonstrating your loyalty to your homeland and dedication to the needs of the order, &lt;name&gt;. I have one last task for you before you may lay claim to the title of master.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64143] = {title = "True Masters of the Light", objective = "Lady Liadrin in Silvermoon City wants you to bring her a vial of Tyr's Hand Holy Water.", description = "A Blood Knight master possesses incredible skill at wielding and weaving the Light in a way that other so-called 'paladins' can never comprehend. It doesn't stop them from despising us for unleashing the Light's true potential.\n\nWe must send them a message and show them that we are not to be trifled with. What I have in mind will be neither brief nor easy, but if you are committed, the first step will be to infiltrate the library wing of the Tyr's Hand Abbey and procure a vial of Tyr's Hand holy water.", progress = "Were you able to get the water?", completion = "Hmm... this is a rather small amount, but if we're careful, it should be sufficient. You see, the Scarlet Crusade believes itself dedicated to the Light. I suppose they still are, in a twisted sort of way, and that's exactly what I'm hoping to capitalize on.\n\nTheir misguided zeal has even tainted the blessing spoken over this water, making it ideal for our purpose.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64144] = {title = "True Masters of the Light", objective = "Lady Liadrin in Silvermoon City wants you to bring her 1 Arcane Catalyst, 1 Crepuscular Powder, 1 Azerothian Diamond, and 1 Pristine Black Diamond.", description = "Now that we have the water, we're going to need a number of reagents in precise quantities. Some of these substances are rare and expensive, <name>, but I have located sources for two.\n\nYou should be able to purchase some arcane catalyst from Zalle, the reagent vendor in one of the shops on the plaza near the Dead Scar. Darlia, the poison merchant near the rogue trainers on Murder Row, stocks crepuscular powder.\n\nTo complete my mixture, I'll also need an azerothian diamond and a pristine black diamond.", progress = "Have you gathered the reagents I'll need?", completion = "Now that we have all the reagents, I can prepare the mixture.\n\n&lt;A slow smile spreads across Lady Liadrin's face.&gt;\n\nIt's all coming together perfectly, &lt;name&gt;. When this is finished, I'll give you the details about what remains to be done.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64217] = {title = "The Dark Portal", objective = "Find Watch Warlord Dar'toon at the Blasted Lands. He awaits your arrival before the Dark Portal.", description = "There exists a hellish gate that has loomed silent for years, but it is silent no longer. \n\nAll able bodied members of the Horde are hereby ordered to report to the Blasted Lands. Visit the Zeppelin Master outside of the city gates of Orgrimmar and ride to Grom'gol Base Camp. From there, speak to Thysta to arrange a flight to Stonard.\n\nReport to Warlord Dar'toon at once. He awaits you before the Dark Portal...", progress = nil, completion = "Welcome to the nightmare!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64319] = {title = "A Study in Power", objective = "Speak with Magister Astalor Bloodsworn in the hidden chamber beneath Blood Knight headquarters.", description = "Do not think me unduly harsh, <name>. Stillblade knew well what he was being sent to do. He understood and accepted his duty and is an example for all aspiring Blood Knights.\n\nMy words are no eulogy, <name>. Stillblade's service to us is far from over and you will be the instrument of his resurrection.\n\nYour education in the use of the Light has focused on mere charms and parlor tricks thus far. The time has come for you to learn of the nature and breadth of our power. Seek out Magister Astalor Bloodsworn.", progress = nil, completion = "Welcome, young &lt;class&gt;.\n\nThe power of the Blood Knights is taken from a being of immense power.\n\n\n\nIsn't it magnificent? 'Twas a gift from our beloved Prince Kael'thas, and it is the foundation of the Blood Knights' mastery of the Light. This creature begrudges us its power, so we have devised a method for claiming it on our own terms.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][64845] = {title = "Alliance War Effort", objective = "Win a battleground match and return to an Alliance Brigadier General at any Alliance capital city or Shattrath.", description = "War is upon us and the Alliance is in need of more combatants to crush the Horde!\n\nOur mission is to disrupt their operations in all of our active battlegrounds.\n\nYe've come to enlist, right?", progress = "Tell me, <name>.  What news do you bring from the front?", completion = "Excellent news, &lt;class&gt;!  If our tactical deployments continue to be this successful, the Horde will be in full retreat before long.", rewards = "You will receive:\n\nEnlistment Bonus"}
MultiLanguageQuestData['en'][65221] = {title = "Purchase 1 Unstable Flask of the Sorcerer for the cost of 10 Apexis Shards", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnstable Flask of the Sorcerer"}
MultiLanguageQuestData['en'][65222] = {title = "Purchase 5 Unstable Flasks of the Sorcerer for the cost of 50 Apexis Shards", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnstable Flask of the Sorcerer"}
MultiLanguageQuestData['en'][65223] = {title = "Purchase 1 Unstable Flask of the Beast for the cost of 10 Apexis Shards", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnstable Flask of the Beast"}
MultiLanguageQuestData['en'][65224] = {title = "Purchase 5 Unstable Flasks of the Beast for the cost of 50 Apexis Shards", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnstable Flask of the Beast"}
MultiLanguageQuestData['en'][65284] = {title = "Goblin Gumbo Kettle", objective = "Greetings <class>, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGoblin Gumbo Kettle"}
MultiLanguageQuestData['en'][65285] = {title = "Goblin Gumbo Kettle", objective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGoblin Gumbo Kettle"}
MultiLanguageQuestData['en'][65561] = {title = "Tabard of Flame", objective = "Greetings <class>, I've been expecting you. An acquaintance of mine asked me to give you something when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose this item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTabard of Flame"}
MultiLanguageQuestData['en'][65562] = {title = "Tabard of Flame", objective = "Ah, yes. I'm glad you finally showed up to take this package off my hands.\n\nOur mutual friends wanted you to have this reward in exchange for a purchase you made. That's none of my business though. I'm just the delivery boy on this deal.\n\nIf you ever lose this item, come back and I'll give you a replacement, no charge.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nTabard of Flame"}
MultiLanguageQuestData['en'][65593] = {title = "Hearts of the Lovers", objective = "Bring the hearts of Avelina Lilly and Isaac Pearson to Carendin Halgar in the Temple of the Damned.", description = "An incubus will be drawn to the hearts of lovers, and the most aching love will create the most irresistible lure.\n\nMy scrying has revealed two that should serve exceptionally.\n\nIn Silverpine Forest, Avelina Lilly provides her tailoring services to the fallen wizards at Ambermill. In the Barrens, Isaac Pearson hopes to make his mark in the seaside town of Ratchet.\n\nThey toil on opposite ends of the world, yet their hearts yearn only for each other. Bring those hearts to Carendin.", progress = "Ah, <name>, you return. Were you able to procure the lovers' hearts?", completion = "As expected. Excellently done, &lt;name&gt;.\n\n\n\nIdiots.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][65597] = {title = "The Binding", objective = "Using the Lovers' Hearts, summon and subdue an incubus, then return the Lovers' Hearts to Carendin Halgar in the Magic Quarter of the Undercity.", description = "The time has come at last. Bring the hearts to the summoning circle below. Place them at its center and call forth the incubus.\n\nThe demon will not be pleased when it realizes that you have tempted it into a trap. Do not fall prey to its beguilement, <name>. You must subdue it fully.\n\nOnly then can I teach you the spell to bind it to your will.", progress = "The incubus possesses martial prowess, but its illusory charms are its most potent weapon. Falter for even a moment, and the demon will seize upon the opportunity to enthrall you.\n\nDo not let it, <name>.", completion = "Impressive. Very impressive. The sayaad specialize in preying upon mortals. Many a &lt;class&gt; has thought themselves strong enough to command one, only to find themselves being commanded instead.\n\nThis trial did not break you, &lt;name&gt;, and your efforts have earned your reward. I will teach you the spell to summon the incubus.", rewards = "You will learn:\n\nSummon Incubus\n\nThe following spell will be cast on you:\n\nTeach Summon Incubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][65601] = {title = "Love Hurts", objective = "Speak with Magar in Orgrimmar.", description = "A sayaad male is known as an incubus. A creature of profound evil and singular mind.\n\nThe demon must be lured into our world with an item of enticement - an object that represents great love and devotion.\n\nIf you trust a blind man to lead you, <name>, then listen. East from the Cleft of Shadow, along the main drag of Orgrimmar, lives Magar. He longs for the return of his mate, Krilge.\n\nSeek him out. He'll ask you to search for something precious. That is the key which you must bring to Gan'rul.", progress = nil, completion = "Who told you about Krilge? Have you come with any news? You better not be toying with me...", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][65602] = {title = "What Is Love?", objective = "Retrieve the Wooden Figurine and bring it to Gakin the Darkbinder in the Mage Quarter of Stormwind.", description = "You will need a powerful reagent to tempt an incubus -- an object that represents great devotion and love.\n\nWith my scrying, I have located a small figurine that should be suitable for your ritual.\n\nThousands of years ago, the figurine belonged to a young couple. The original owners are no more, but their keepsake has survived to the present day.\n\nFollow the road north into Ashenvale, then west and past Maestra's Post. You will see a house nestled amongst the trees. There you will find what you seek.", progress = "You've returned. Successfully, I assume?", completion = "&lt;Gakin turns the wooden figurine over in his hand.&gt;\n\nI sense the emotional energy residing within this artifact, undiminished by the passing of time. The incubus will be drawn to it like a fly to honey.\n\nTakar never disappoints.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][65603] = {title = "The Binding", objective = "Using the Wooden Figurine, summon and subdue an incubus, then return the Wooden Figurine to Gakin the Darkbinder in the Slaughtered Lamb.", description = "The time has come. Take the figurine and descend into the crypts below. A summoning circle has been prepared, and you must place the figurine at its center.\n\nThen the gateway will open, and the incubus will cross into our world.\n\nA sayaad is not to be underestimated. The demon will not hesitate to attack when it realizes your ruse. You must draw upon all you have been taught to defeat it.\n\nIf you succeed, return to me and I shall bind the creature to your will. Fail, and your soul is forfeit.", progress = "The incubus will try to lower your guard through beguilement and deception. The demon is adept at swaying the hearts of mortals.\n\nRemember that anything it may offer you is false. To the demon, you are merely prey.", completion = "Not bad, &lt;name&gt;. Your have bested the fiend, and your will remains unbroken.\n\nMany a &lt;class&gt; has believed themselves strong enough to bind a sayaad, only to become the demon's next meal instead. I am pleased to see you are not so foolish.\n\nWatch closely, and I will teach you the invocation to call upon your newly bound incubus.", rewards = "You will learn:\n\nSummon Incubus\n\nThe following spell will be cast on you:\n\nTeach Summon Incubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][65604] = {title = "The Binding", objective = "Using the Withered Scarf, summon and subdue an incubus, then return the Withered Scarf to Gan'rul Bloodeye in Orgrimmar.", description = "Yes... I see. I feel the residual emotions bound within these threads. Love is woven into its stitches. The incubus will not be able to resist.\n\nTake this to the summoning circle in Neeru's tent, <name>. Summon forth a malevolent incubus, then show it your mastery. Do not expect it to be subdued quietly. Ready your magic and prepare yourself for a fight. Underestimating a demon has been many a warlock's final mistake.\n\nWhen you have defeated it, return the cloth to me. I will let Magar know what you found.", progress = "The sayaad are dominators of minds and torturers of souls. Their visage brings the heart joy, leaving you defenseless when they rend your flesh with whip and claw.\n\nDo not entertain the incubus' charms, <name>. Slay it quickly and let it be done.", completion = "Hah! Victorious, as expected!\n\nThe incubus is subdued, and it will be my pleasure to teach you to summon the demon. Your strength is growing, and I have no doubt that this is a mere stepping stone to even greater powers.\n\nI will return the scarf to Magar. I have known that orc for many years, and never did I think he would care for someone the way he cared for Krilge.\n\nIt is a reminder of what separates us from the demons. We wield their darkness, but they will never wield us.", rewards = "You will learn:\n\nSummon Incubus\n\nThe following spell will be cast on you:\n\nTeach Summon Incubus\n\nYou will also receive:\n\nSmall Soul Pouch"}
MultiLanguageQuestData['en'][65610] = {title = "Wish You Were Here", objective = "Investigate Fallen Sky Lake in Ashenvale and report your findings to Gan'rul Bloodeye in Orgrimmar.", description = "I met Krilge while making Mooncloth in Ashenvale. He was stationed there to protect civilians from danger, until he disappeared...\n\nThey've stopped looking for him and consider him a deserter, but I don't believe it.\n\nWe would often meet at Fallen Sky Lake before it became overrun by those aggressive bog beasts.\n\nI'm not typically one to ask favors, but if you could go to Ashenvale and look for any sign of him, I'd appreciate it.", progress = "Yes, what is it?", completion = "What is it you have there, &lt;name&gt;? A scarf made of... Mooncloth? You best not be seeking to romance me.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][91889] = {title = "Your Reward has Arrived!", objective = "You will receive:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nZergling LeashDiablo StonePanda Collar"}
MultiLanguageQuestData['en'][93823] = {title = "A Grand Delivery", objective = "Greetings <name>, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGrand Gift"}
MultiLanguageQuestData['en'][93824] = {title = "A Grand Delivery", objective = "You will receive:\n\n", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nGrand Gift"}
MultiLanguageQuestData['en'][95158] = {title = "Reset Current Rating - 2v2", objective = "Pay 40 gold to an Arena Organizer to reset Current 2v2 Arena Rating back to 1500.", description = "Hey <name>, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 2v2 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?", progress = nil, completion = "You made the right choice, &lt;name&gt;... But let's just keep this between us for now.", rewards = "The following spell will be cast on you:\n\n[DNT] PvP Rating and MMR Reset - 2v2"}
MultiLanguageQuestData['en'][95251] = {title = "Reset Current Rating - 3v3", objective = "Pay 40 gold to an Arena Organizer to reset Current 3v3 Arena Rating back to 1500.", description = "Hey <name>, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 3v3 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?The following spell will be cast on you:\n\n", progress = nil, completion = nil, rewards = "The following spell will be cast on you:\n\n[DNT] PvP Rating and MMR Reset - 3v3"}
MultiLanguageQuestData['en'][95252] = {title = "Reset Current Rating - 5v5", objective = "Pay 40 gold to an Arena Organizer to reset Current 5v5 Arena Rating back to 1500.", description = "Hey <name>, you're not looking too hot.\n\nRogues got you in a stun-lock? Mages chain polymorphing your arena partner?\n\nLook here, I may have a way to wipe this all off your record!\n\nFor the measly price of 40 gold, I can reset your Current Arena Rating for the 5v5 Bracket. This is a once a week deal that you won't want to miss!\n\nSo whaddya say?", progress = nil, completion = "You made the right choice, &lt;name&gt;... But let's just keep this between us for now.", rewards = "The following spell will be cast on you:\n\n[DNT] PvP Rating and MMR Reset - 5v5"}
MultiLanguageQuestData['en'][95455] = {title = "Concerted Efforts", objective = "Bring 1 Alterac Valley Mark of Honor, 1 Arathi Basin Mark of Honor, 1 Warsong Gulch Mark of Honor and 1 Eye of the Storm Mark of Honor to an Alliance Brigadier General in any Alliance Capital City or Shattrath.", description = "We're not fighting isolated battles against the Horde anymore, <lad/lass>.\n\nVictory in one front means denying the Horde resources they'd use against us in a different battle.  By the same token, abandoning any given battle could give the advantage to our opponent somewhere else around the world.\n\nThe Alliance is in need of more combatants with this sort of worldly understanding... truly seasoned veterans!  <name>, come back to me after you've served against the Horde at all of our active battlegrounds.", progress = "How are yer travels faring laddie?", completion = "You're not one to disappoint, &lt;name&gt;!  What you've learned goes beyond petty medals and commendations.  What you've learned is what can only come with experience and the hardening of one's temper in the field of battle.\n\nYou've done well, &lt;class&gt;.  You're a true hero of the Alliance!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][95456] = {title = "Concerted Efforts", objective = "Ah, <name>.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", description = nil, progress = "Ah, <name>.  I hope you continue to lend your experience to the different battlefronts.  A lot of our lads and lasses in the field look up to seasoned veterans like you.", completion = "You live up to yer reputation, &lt;name&gt;.  Without people like you, the Alliance wouldn't stand a chance against the savage forces of the Horde.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][95457] = {title = "For Great Honor", objective = "Bring 1 Alterac Valley Mark of Honor, 1 Arathi Basin Mark of Honor, 1 Warsong Gulch Mark of Honor and 1 Eye of the Storm Mark of Honor to a Horde Warbringer in any Horde capital city or Shattrath.", description = "Serving the Horde in one of the great battles against the Alliance is a source of great honor!  The few however, that have served the Horde in ALL of our active battlefronts are our truly great fighters.  We shall vanquish our opponents, not by fighting isolated skirmishes, but by waging a well-coordinated war.\n\nGo forth and crush the Alliance in Arathi Basin, Alterac Valley, Eye of the Storm and Warsong Gulch!  For Honor!  For the Horde!", progress = "Arathi is still wet with the blood of great warriors and the clash of steel still rings throughout Alterac.  Do not waste my time unless you bring news from the front!", completion = "Your trials have not been easy, but your courage did not escape you and your strength did not fail.  Part with past tokens of victory, &lt;class&gt;.  None shall need them as a reminder of your worth.  Stand up straight, &lt;name&gt;.  Today you will walk with great pride for you are a hero!", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][95458] = {title = "For Great Honor", objective = "Many brave fighters look up to you, <name>.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", description = nil, progress = "Many brave fighters look up to you, <name>.  You continue to be an example for all in the fight against the Alliance.  What news do you bring from your journeys?", completion = "You continue to honor the Horde, &lt;name&gt;.  I'm glad to see you haven't turned soft.", rewards = "You will receive:\n\n"}
MultiLanguageQuestData['en'][96253] = {title = "An Unexpected Delivery", objective = "Greetings <name>, I've been expecting you. An acquaintance of mine asked me to give you these items when you stopped by. He mentioned something about a reward for a purchase you made from some mutual friends.\n\nMaybe you know what he meant?\n\nAnyway, here's your reward. Oh, one more thing. My acquaintance, Landro Longshot, said that if you ever lose an item, you can find him on the docks in Booty Bay to get a replacement.", description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnexpected Gift"}
MultiLanguageQuestData['en'][96254] = {title = "An Unexpected Delivery", objective = nil, description = nil, progress = nil, completion = nil, rewards = "You will receive:\n\nUnexpected Gift"}
